        public string getPrefConnString(int accountId, string userid, string ReportName)
        {
            string query = "select DefaultServer from tbl_server_reference  where AccountId=? and (login=? or login is NULL) and ReportName=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountId);
            lParameter.Add("login", userid);
            lParameter.Add("ReportName", ReportName);
            DataTable dt = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            if (dt.Rows.Count > 0)
                return dt.Rows[0]["DefaultServer"].ToString();
            else
                return null;
        }

        public DataTable GetIDCCounselingLog(string driverId)
        {
            string query = "select * from idc_violationfeedback v " +
                           " left JOIN idc_ddtfeedback d ON d.DriverId = v.DriverId AND DATE(v.AddedOn) = DATE(d.AddedOn)" +
                           " WHERE v.DriverId =?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("driverId", driverId);
            DataTable ds = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            return ds;
        }

        public Int64 writeTrackerData(XmlNode pdu, String truckId, String altitude)
        {
            return writeTrackerData(pdu, truckId, altitude, false);
        }
        public async Task<Int64> writeTrackerData_async(XmlNode pdu, String truckId, String altitude)
        {
            return writeTrackerData(pdu, truckId, altitude, false);
        }
        public Int64 writeTrackerData(XmlNode pdu, String truckId, String altitude, bool ReplaceData)
        {
            XmlNodeList positions = pdu.SelectNodes("./position");
            XmlNodeList CANnodes = pdu.SelectNodes("./CAN");
            StringBuilder query = new StringBuilder();
            if (!ReplaceData)
                query.Append("insert into trackerdata ");
            else
                query.Append("replace into trackerdata ");
            query.Append("(TruckID, FromTimeStamp, ToTimeStamp, Temperature, IdlingInstances, IdlingDuration, AccelerationInstances, DecelerationInstances, Distance, noGPSDuration, curGSMSigStrength, badSigCount, gprsDataKB, numSMS, numCallIns, numCallOuts, AlarmData, CallerPhone, altitude, ServerTS) values(\"");
            query.Append(truckId);
            query.Append("\",");
            XmlNode fromDate = positions.Item(0).Attributes.GetNamedItem("date");
            DateTime fromTS = DateTime.Parse(fromDate.Value);
            String fromTSStr = fromTS.ToString("u");
            String frmttdFromTSStr = fromTSStr.Substring(0, fromTSStr.Length - 1);
            query.Append("\"" + frmttdFromTSStr + "\"");
            query.Append(",");
            XmlNode toDate = positions.Item(positions.Count - 1).Attributes.GetNamedItem("date");
            DateTime toTS = DateTime.Parse(toDate.Value);
            String toTSStr = toTS.ToString("u");
            String frmttdToTSStr = toTSStr.Substring(0, toTSStr.Length - 1);
            query.Append("\"" + frmttdToTSStr + "\"");
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("temperature").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numIdle").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("timeIdle").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numAccel").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numDecel").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("distance").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("noGPS").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("curGSMSigStrength").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("badSigCount").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("gprsDataKB").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numSMS").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numCallIns").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numCallOuts").Value);
            query.Append(",");
            //Alarm Data
            query.Append(pdu.Attributes.GetNamedItem("alarms").Value);
            query.Append(",");
            //Caller Phone
            XmlNode caller = pdu.Attributes.GetNamedItem("CallerPhone");
            if (caller != null)
            {
                query.Append("'" + caller.Value + "'");
            }
            else
            {
                query.Append("NULL");
            }
            query.Append(",");
            if (pdu.Attributes.GetNamedItem("altitude") != null)
                query.Append(pdu.Attributes.GetNamedItem("altitude").Value);
            else
                query.Append(altitude);
            query.Append(",");
            query.Append("\"" + formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff())) + "\"");
            query.Append(");");
            //Console.WriteLine(query.ToString());
            //Console.ReadKey(true);
            try
            {
                dbx.executeNonQuery(query.ToString());
            }
            catch (System.Data.Odbc.OdbcException e)
            {
                bool duplicate = false;
                for (int j = 0; j < e.Errors.Count; j++)
                {
                    // Check for duplicate entries error and suppress it
                    if (e.Errors[j].NativeError == 1062)
                    {
                        duplicate = true;
                    }
                }
                if (duplicate == false)
                {
                    throw e;
                }
                return -1;
            }
            string q = "SELECT LAST_INSERT_ID()"; //Changed by Gopal 18/12/2017 -- Instead of doing max(id) from trackerdata,replace with LAST_INSERT_ID
            Int64 id = Convert.ToInt64(dbx.executeScalar(q));
            for (int i = 0; i < positions.Count; i++)
            {
                try
                {
                    XmlNode position = positions.Item(i);
                    writePositionData(position, id, truckId, ReplaceData);
                }
                catch (System.Data.Odbc.OdbcException e)
                {
                    bool duplicate = false;
                    for (int j = 0; j < e.Errors.Count; j++)
                    {
                        // Check for duplicate entries error and suppress it						
                        if (e.Errors[j].NativeError == 1062)
                        {
                            duplicate = true;
                        }
                    }
                    if (duplicate == false)
                    {
                        throw e;
                    }
                }
            }

            for (int i = 0; i < CANnodes.Count; i++)
            {
                try
                {
                    XmlNode CAN = CANnodes.Item(i);
                    writeCANData(CAN, id, truckId);
                }
                catch (System.Data.Odbc.OdbcException e)
                {
                    bool duplicate = false;
                    for (int j = 0; j < e.Errors.Count; j++)
                    {
                        // Check for duplicate entries error and suppress it                        
                        if (e.Errors[j].NativeError == 1062)
                        {
                            duplicate = true;
                        }
                    }
                    /* if (duplicate == false)
                     {
                         throw e;
                     }*/
                }
            }
            return (id);
        }

