        private string GetDateTablePartitions(DateTime fromdate, DateTime todate, String[] partion)
        {
            string temp = string.Empty;
            int cnt = 0;
            if (todate > fromdate)
            {
                while (fromdate <= todate && cnt < 13)
                {
                    temp = temp + partion[fromdate.Month - 1] + ",";
                    fromdate = fromdate.AddMonths(1);
                    if (fromdate > todate && fromdate.Month == todate.Month && (fromdate - todate).TotalDays < DateTime.DaysInMonth(todate.Year, todate.Month) - 1)
                    {
                        temp = temp + partion[fromdate.Month - 1] + ",";
                        cnt++;
                    }
                }
                temp = temp.Substring(0, temp.Length - 1);
            }
            else
            {
                temp = partion[0];
            }
            return temp;
        }

        private string GetTransNotifPartitions(DateTime fromdate, DateTime todate, String[] t_partitions)
        {
            string temp = string.Empty;
            int cnt = 0;
            int day_of_the_month = 0;
            if (todate > fromdate)
            {
                while (fromdate <= todate && cnt <= 31)
                {
                    try
                    {
                        day_of_the_month = Convert.ToDateTime(fromdate).Day;
                    }
                    catch { }
                    temp = temp + t_partitions[day_of_the_month - 1] + ",";
                    fromdate = fromdate.AddDays(1);
                    if (fromdate > todate && fromdate.Day == todate.Day && (fromdate - todate).TotalDays < DateTime.DaysInMonth(todate.Year, todate.Month) - 1)
                    {
                        temp = temp + transporterNot_partitions[fromdate.Month - 1] + ",";
                        cnt++;
                    }
                }
                temp = temp.Substring(0, temp.Length - 1);
            }
            else
            {
                temp = transporterNot_partitions[0];
            }
            return temp;
        }

