        public Int64 writeTrackerDataCDAC(XmlNode pdu, String truckId, String altitude)
        {
            XmlNodeList positions = pdu.SelectNodes("./position");
            StringBuilder query = new StringBuilder();
            query.Append("insert into trackerdataCDAC(TruckID, FromTimeStamp, ToTimeStamp, Temperature, IdlingInstances, IdlingDuration, AccelerationInstances, DecelerationInstances, Distance, noGPSDuration, curGSMSigStrength, badSigCount, gprsDataKB, numSMS, numCallIns, numCallOuts, AlarmData, CallerPhone, altitude, ServerTS) values(\"");
            query.Append(truckId);
            query.Append("\",");
            XmlNode fromDate = positions.Item(0).Attributes.GetNamedItem("date");
            DateTime fromTS = DateTime.Parse(fromDate.Value);
            String fromTSStr = fromTS.ToString("u");
            String frmttdFromTSStr = fromTSStr.Substring(0, fromTSStr.Length - 1);
            query.Append("\"" + frmttdFromTSStr + "\"");
            query.Append(",");
            XmlNode toDate = positions.Item(positions.Count - 1).Attributes.GetNamedItem("date");
            DateTime toTS = DateTime.Parse(toDate.Value);
            String toTSStr = toTS.ToString("u");
            String frmttdToTSStr = toTSStr.Substring(0, toTSStr.Length - 1);
            query.Append("\"" + frmttdToTSStr + "\"");
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("temperature").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numIdle").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("timeIdle").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numAccel").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numDecel").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("distance").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("noGPS").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("curGSMSigStrength").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("badSigCount").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("gprsDataKB").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numSMS").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numCallIns").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("numCallOuts").Value);
            query.Append(",");
            //Alarm Data
            query.Append(pdu.Attributes.GetNamedItem("alarms").Value);
            query.Append(",");
            //Caller Phone
            XmlNode caller = pdu.SelectSingleNode("./caller");
            if (caller != null)
            {
                query.Append(caller.Attributes.GetNamedItem("phone").Value);
            }
            else
            {
                query.Append("NULL");
            }
            query.Append(",");
            if (altitude != null)
            {
                query.Append(altitude);
            }
            else
            {
                query.Append("NULL");
            }
            query.Append(",");
            query.Append("\"" + formatDBDate(DateTime.UtcNow.AddSeconds(5 * 60 * 60 + 30 * 60)) + "\"");
            query.Append(");");
            //Console.WriteLine(query.ToString());
            //Console.ReadKey(true);
            try
            {
                dbx.executeNonQuery(query.ToString());
            }
            catch (System.Data.Odbc.OdbcException e)
            {
                bool duplicate = false;
                for (int j = 0; j < e.Errors.Count; j++)
                {
                    // Check for duplicate entries error and suppress it
                    if (e.Errors[j].NativeError == 1062)
                    {
                        duplicate = true;
                    }
                }
                if (duplicate == false)
                {
                    throw e;
                }
                return -1;
            }
            Int64 id = getLastTrackerDataCDACId();
            for (int i = 0; i < positions.Count; i++)
            {
                try
                {
                    XmlNode position = positions.Item(i);
                    writePositionDataCDAC(position, id, truckId);
                }
                catch (System.Data.Odbc.OdbcException e)
                {
                    bool duplicate = false;
                    for (int j = 0; j < e.Errors.Count; j++)
                    {
                        // Check for duplicate entries error and suppress it						
                        if (e.Errors[j].NativeError == 1062)
                        {
                            duplicate = true;
                        }
                    }
                    if (duplicate == false)
                    {
                        throw e;
                    }
                }
            }
            return (id);
        }

        public int InsertFuelLevelInLtrs(string vehicleid, string timestamp, object fuellevel, object fuelInLtrs)
        {
            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            Query = "insert ignore into fuellevel(Truckid,timestamp,fuellevel,fuelInLtrs) values(?,?,?,?)";
            lParameter.Add("Truckid", vehicleid);
            lParameter.Add("timestamp", timestamp);
            lParameter.Add("fuellevel", fuellevel);
            lParameter.Add("fuelInLtrs", fuelInLtrs);
            return dbx.executeNonQuery(Query, lParameter);
        }
        public DataTable GetFuelLevelInLtrs(string vehicleid, string timestamp)
        {
            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            Query = "select Truckid,timestamp,fuellevel,fuelInLtrs from fuellevel where Truckid=? and timestamp>? order by id desc limit 1";
            lParameter.Add("Truckid", vehicleid);
            lParameter.Add("timestamp", timestamp);
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }
        public Int64 getLastTrackerDataCDACId()
        {
            Object idObj = dbx.executeScalar("select max(id) from trackerdataCDAC;");
            Int64 id = Convert.ToInt64(idObj);
            return id;
        }

        public void writePositionData(XmlNode position, Int64 id, String truckId, bool ReplaceData)
        {
            StringBuilder query = new StringBuilder();
            //#if PANIC
            //#else

            if (!ReplaceData)
                query.Append("insert into positiondata ");
            else
                query.Append("replace into positiondata ");

            query.Append("(ID, TruckID, TimeStamp, Start, Stop, Latitude, Longitude, Speed, FuelLevel, LAC, CI) values(");
            //#endif
            query.Append(id);
            query.Append(",\"");
            query.Append(truckId);
            query.Append("\",");
            XmlNode date = position.Attributes.GetNamedItem("date");
            DateTime timestamp = DateTime.Parse(date.Value);
            String timestampStr = timestamp.ToString("u");
            String formattedTsStr = timestampStr.Substring(0, timestampStr.Length - 1);
            query.Append("\"" + formattedTsStr + "\"");
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("start").Value);
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("stop").Value);
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("lat").Value);
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("long").Value);
            query.Append(",");
            String speedStr = position.Attributes.GetNamedItem("speed").Value;
            float speed = Convert.ToSingle(speedStr);
            query.Append(speed);
            query.Append(",");
            String fuelStr = position.Attributes.GetNamedItem("fuel").Value;
            float fuel = Convert.ToSingle(fuelStr);
            query.Append(fuel);
            query.Append(",");
            String LACStr = position.Attributes.GetNamedItem("lac").Value;
            query.Append(LACStr);
            query.Append(",");
            String CIStr = position.Attributes.GetNamedItem("ci").Value;
            query.Append(CIStr);
            query.Append(");");
            //Console.WriteLine(query.ToString());
            //Console.ReadKey(true);
            dbx.executeNonQuery(query.ToString());
        }

