        public void writeCANData(XmlNode CAN, Int64 id, String truckId)
        {
            StringBuilder query = new StringBuilder();
            //#if PANIC
            //#else
            query.Append("insert into CANdata (ID,TruckID,TimeStamp, engineRPM, AxleSpeed, CoolantTemp, EngineLoad, accClutch, Diagnostics,CANM1,CANM2,CANM3) values(");
            //#endif
            query.Append(id);
            query.Append(",\"");
            query.Append(truckId);
            query.Append("\",");
            XmlNode date = CAN.Attributes.GetNamedItem("date");
            DateTime timestamp = DateTime.Parse(date.Value);
            String timestampStr = timestamp.ToString("u");
            String formattedTsStr = timestampStr.Substring(0, timestampStr.Length - 1);
            query.Append("\"" + formattedTsStr + "\"");
            query.Append(",");
            string engineRPMStr = CAN.Attributes.GetNamedItem("engineRPM").Value;
            query.Append(Convert.ToSingle(engineRPMStr));
            query.Append(",");

            string axleSpeedStr = CAN.Attributes.GetNamedItem("axleSpeed").Value;
            query.Append(Convert.ToDecimal(axleSpeedStr));
            query.Append(",");
            string coolantTempStr = CAN.Attributes.GetNamedItem("coolantTemp").Value;
            query.Append(Convert.ToInt16(coolantTempStr));
            query.Append(",");
            string engineLoadStr = CAN.Attributes.GetNamedItem("engineLoad").Value;
            query.Append(Convert.ToDecimal(engineLoadStr));
            query.Append(",");
            string accClutchStr = CAN.Attributes.GetNamedItem("acceleratorClutch").Value;
            query.Append(Convert.ToInt32(accClutchStr));
            // String fuelStr = CAN.Attributes.GetNamedItem("CANfuellevel").Value;
            // float fuel = Convert.ToSingle(fuelStr);
            // query.Append(fuel);
            query.Append(",");
            string CANErrorStr = CAN.Attributes.GetNamedItem("CANError").Value;
            long CANError = Convert.ToInt64(CANErrorStr);
            query.Append(CANError);
            query.Append(",");
            try
            {  // May be there 
                string CANM1Str = CAN.Attributes.GetNamedItem("CANM1").Value;
                query.Append(CANM1Str);
                query.Append(",");
            }
            catch { query.Append("0"); query.Append(","); }  // append zero if absent
            try
            {
                string CANM2Str = CAN.Attributes.GetNamedItem("CANM2").Value;
                //query.Append("\"");
                query.Append(CANM2Str);
                query.Append(",");
            }
            catch { query.Append("0"); query.Append(","); }  // append zero if absent
            try
            {
                string CANM3Str = CAN.Attributes.GetNamedItem("CANM3").Value;
                //query.Append("\"");
                query.Append(CANM3Str);
                query.Append(");");
            }
            catch { query.Append("0"); query.Append(");"); }  // append zero if absent
            //query.Append("");
            //Console.WriteLine(query.ToString());
            //Console.ReadKey(true);
            dbx.executeNonQuery(query.ToString());
        }

