		public object[] getnotifications(string SessionId, string Export = "")
		{
			string ActionTime = formatDBDate(DateTime.UtcNow);
			string query0 = "update transporternotification t join sessions s set t.Notifiedtime='" + ActionTime + "' where t.Loginid=s.login "
						   + "and s.SessionID=? and t.IsNotified=1 and t.Notifiedtime='0000-00-00 00:00:00'";
			var lParameter = new Dictionary<string, object>();
			lParameter.Add("SessionId", SessionId);
			dbx.executeNonQuery(query0.ToString(), lParameter);

			StringBuilder query = new StringBuilder();
			string current_partition = string.Empty;
			// get 7 days data
			current_partition = GetTransNotifPartitions(DateTime.Now.AddDays(-7), DateTime.Now, transporterNot_partitions); // get all partition names for 7 days
																															//string prev_day = formatDBDate(DateTime.UtcNow.AddDays(-1));
																															//string prev_day_partition = getdaypartition(prev_day);
			if (Export == "Export")
			{
				query.Append("SELECT t.Subject, t.Info, t.Datetime, t.IsNotified, t.Notifiedtime FROM sessions s JOIN transporternotification PARTITION(" + current_partition + ") t ON s.login = t.Loginid" +
							" WHERE s.SessionID = '" + SessionId + "' AND t.Info NOT LIKE '%s3.amazonaws.com%' AND t.Datetime >= DATE_SUB(CURDATE(), INTERVAL 3 DAY) ORDER BY t.Datetime DESC");
			}
			else
			{
				query.Append("select t.Subject,t.Info,t.Datetime,t.IsNotified,t.Notifiedtime from sessions s join transporternotification partition(" + current_partition +
					") t");
				//query.Append(" where s.SessionID=" + "'" + SessionId + "'" + " and s.login=t.Loginid order by t.Datetime desc limit 100");
				query.Append(" where s.SessionID=" + "'" + SessionId + "'" + " and t.Info NOT LIKE '%s3.amazonaws.com%' and s.login=t.Loginid order by t.Datetime desc limit 100");
			}
			DataSet ds = dbx.executeQuery(query.ToString());
			string query1 = "update transporternotification t join sessions s set t.IsNotified=1,t.Notifiedtime='" + ActionTime + "' where t.Loginid=s.login and s.SessionID=? and t.IsNotified=0";
			lParameter = new Dictionary<string, object>();
			lParameter.Add("SessionId", SessionId);
			dbx.executeNonQuery(query1.ToString(), lParameter);

			DataTable table = ds.Tables[0];
			ArrayList notificationList = new ArrayList();
			foreach (DataRow row in table.Rows)
			{
				notificationList.Add(row.ItemArray);
			}
			return notificationList.ToArray();
		}

		public String getTrackerData(int id)
        {
            String[] xmlHeaders ={
                "truckId",
                "distance",
                "temperature",
                "numIdle",
                "timeIdle",
                "numAccel",
                "numDecel",
                "alarms",
                "noGPS",
                "curGSMSigStrength",
                "badSigCount",
                "gprsDataKB",
                "numSMS",
                "numCallIns",
                "numCallOuts"
            };

            String[] dbHeaders = {
                "TruckID",
                "Distance",
                "Temperature",
                "IdlingInstances",
                "IdlingDuration",
                "AccelerationInstances",
                "DecelerationInstances",
                "AlarmData",
                "noGPSDuration",
                "curGSMSigStrength",
                "badSigCount",
                "gprsDataKB",
                "numSMS",
                "numCallIns",
                "numCallOuts"
            };

            String query = "select * from trackerdata where id=\"" + id + "\";";
            DataSet ds = dbx.executeQuery(query);
            StringBuilder response = new StringBuilder();
            DataTable table = ds.Tables[0];
            int ordinal;
            foreach (DataRow row in table.Rows)
            {
                response.Append("<pdu");
                for (int column = 0; column < xmlHeaders.Length; column++)
                {
                    ordinal = table.Columns.IndexOf(dbHeaders[column]);
                    String value = readValue(row[ordinal], table.Columns[ordinal].DataType.ToString());
                    response.Append(" " + xmlHeaders[column] + "=\"" + value + "\"");
                }
                response.Append(">\n");
                ordinal = table.Columns.IndexOf("CallerPhone");
                if (!row.IsNull(ordinal))
                {
                    response.Append("<caller phone=\"" + row[ordinal] + "\"/>\n");
                }
                response.Append(getPositionData(id));
                response.Append("</pdu>");
            }
            return response.ToString();
        }

