        public int insertFuelData(string vehicleId, DateTime timestamp, double filledFuel, double prefuel, int distance, double mileage, string fuelSensorType)
        {
            object[] latlng = getLatLongByVehicle(vehicleId, timestamp.ToString());
            double lat = 0;
            double lng = 0;
            if (latlng.Length > 0)
            {
                lat = Convert.ToDouble((((Object[])(latlng[0]))[0]).ToString());
                lng = Convert.ToDouble((((Object[])(latlng[0]))[1]).ToString());
            }

            string query = "INSERT IGNORE INTO `non_sensel_fueldata` (`TruckID`, `TimeStamp`,Latitude,Longitude, `PostFuel`,PreFuel,Distance,Mileage, `Source`) VALUES "
                + "(?, ?, ?, ?, ?, ?, ?, ?, ?);";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TruckID", vehicleId);
            lParameter.Add("TimeStamp", formatDBDate(timestamp));
            lParameter.Add("Latitude", lat);
            lParameter.Add("Longitude", lng);
            lParameter.Add("PostFuel", filledFuel + prefuel);
            lParameter.Add("PreFuel", prefuel);
            lParameter.Add("Distance", distance);
            lParameter.Add("Mileage", mileage);
            lParameter.Add("FuelSensorType", fuelSensorType);
            return dbx.executeNonQuery(query, lParameter);
        }

        public long ConvertDateTimeToUnixTimestampSecs(DateTime dateTime)
        {
            long unixTimestamp = (Int64)(dateTime.Subtract(new DateTime(1970, 1, 1))).TotalSeconds;
            return unixTimestamp;
        }

        public DateTime ConvertUnixTimestampSecsToDateTime(long unixTimeStamp)
        {
            DateTime dtDateTime = new DateTime(1970, 1, 1, 0, 0, 0, 0, System.DateTimeKind.Utc);
            return dtDateTime.AddSeconds(unixTimeStamp).ToLocalTime();
        }

