        public Object[] getFuelPoints(String vehicleId, String fromDateStr, String toDateStr)
        {
            StringBuilder query = new StringBuilder();
            query.Append("create temporary table fuelData1 (rownum int not null auto_increment,ID int not null, TimeStamp DATETIME NOT NULL, FuelLevel decimal(5,2), PRIMARY KEY(rownum))");
            dbx.executeNonQuery(query.ToString());

            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            query = new StringBuilder();
            query.Append("insert into fuelData1 (ID, TimeStamp, FuelLevel) select id, TimeStamp, FuelLevel from positiondata PARTITION(" + part + ") ");
            query.Append("where truckId =\"" + vehicleId + "\" ");
            query.Append("and TimeStamp >= \"" + fromDateStr + "\" ");
            query.Append("and TimeStamp <= \"" + toDateStr + "\" ");
            query.Append("and FuelLevel > 0.0 order by TimeStamp");
            dbx.executeNonQuery(query.ToString());

            query = new StringBuilder();
            query.Append("create temporary table fuelData2 select * from fuelData1");
            dbx.executeNonQuery(query.ToString());

            query = new StringBuilder();
            query.Append("Select FillVoltageDirection from fuelenable ");
            query.Append("where truckId =\"" + vehicleId + "\"");
            int fillVoltageDirection = Convert.ToInt32(dbx.executeScalar(query.ToString()));
            int voltageDiff = fillVoltageDirection * 2;

            query = new StringBuilder();
            query.Append("select T1.ID, T1.TimeStamp, T1.FuelLevel, T2.FuelLevel from fuelData1 T1, fuelData2 T2 where (T1.FuelLevel - T2.FuelLevel > ");
            query.Append(voltageDiff.ToString());
            query.Append(") and ((T2.rownum - T1.rownum = 1))");
            //Console.WriteLine(query);
            ArrayList fuelPointsList = new ArrayList();
            DataSet fuelPoints = dbx.executeQuery(query.ToString());
            DataTable table = fuelPoints.Tables[0];
            foreach (DataRow row in table.Rows)
            {
                fuelPointsList.Add(row.ItemArray);
            }
            return fuelPointsList.ToArray();
        }

