        public Object[] getRouteLatLong(String vehicleId, String fromDateStr, String toDateStr)
        {

            DateTime fromdate = Convert.ToDateTime(fromDateStr);
            DateTime todate = Convert.ToDateTime(toDateStr);
            string temp = string.Empty;
            if (todate > fromdate)
            {
                while (fromdate <= todate)
                {
                    temp = temp + partions[fromdate.Month - 1] + ",";
                    fromdate = fromdate.AddMonths(1);

                    if (fromdate > todate && fromdate.Month == todate.Month && (fromdate - todate).TotalDays < DateTime.DaysInMonth(todate.Year, todate.Month) - 1)
                        temp = temp + partions[fromdate.Month - 1] + ",";

                }
                temp = temp.Substring(0, temp.Length - 1);
            }
            else
            {
                temp = "pjan";
            }
            StringBuilder query = new StringBuilder();
            query.Append("Select id, DATE_FORMAT(positiondata.timestamp, '%d %b %y, %r'), Start, Stop, Latitude, Longitude, Speed, UNIX_TIMESTAMP(positiondata.timestamp),FuelLevel,LAC,CI");
            query.Append(" from positiondata PARTITION(" + temp + ")");
            query.Append(" where positiondata.truckId =? ");
            if (fromDateStr != null)
            {
                query.Append(" and TimeStamp >= ? ");
            }
            if (toDateStr != null)
            {
                query.Append(" and TimeStamp <= ? ");
            }
            query.Append(" order by TimeStamp");

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("fromDateStr", fromDateStr);
            lParameter.Add("toDateStr", toDateStr);
            DataSet routeLatLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = routeLatLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();

        }
        public Object[] getRouteLatLongForRailwayGateway(String vehicleId, double startLatitude, double endLatitude, double startLongitude, double endLongitude, string direction, DateTime timestamp)
        {
            string dt = formatDBDate(timestamp);
            string query = "SELECT id, DATE_FORMAT(DATE_ADD('" + dt + "',INTERVAL (@rownum := @rownum + 30) SECOND), '%d %b %y, %r'), Start, 0 as Stop , Latitude, Longitude, 5 as Speed, UNIX_TIMESTAMP(positiondata.timestamp), FuelLevel, LAC, CI " +
               "FROM (SELECT @rownum:= 0) r, positiondata PARTITION(pmar) " +
               "WHERE positiondata.truckId = ? AND Latitude BETWEEN ? AND ? AND Longitude BETWEEN ? AND ? " +
               "ORDER BY Latitude " + (direction.ToLower() == "asc" ? "ASC" : "DESC");

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("startLatitude", startLatitude);
            lParameter.Add("endLatitude", endLatitude);
            lParameter.Add("startLongitude", startLongitude);
            lParameter.Add("endLongitude", endLongitude);

            DataSet routeLatLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = routeLatLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();
        }
        public Object[] getRFID_data(String vehicleId, String fromDateStr, String toDateStr, string rawdata = "0")
        {
            string inparam = string.Empty;
            String[] vehicles = vehicleId.Replace("'", "").Replace("\"", "").Split(',');
            for (int i = 0; i < vehicles.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
            }
            //string query = "select distinct r.Name,e.serverts,e.Latitude,e.Longitude,e.TruckID,r.RfidCardNo,r.Rfidlogs" +
            string query = "select distinct r.Name,e.timestamp,e.Latitude,e.Longitude,e.TruckID,r.RfidCardNo,r.Rfidlogs" +
                         "   from rfidinfo r  join ets_rfiddata e on r.Rfidlogs=e.bid " +
                         "   where e.TruckID in (" + inparam + ") and e.timestamp >= ? and e.timestamp <= ?" +
                         "   union " +
                         "   select r.Name,e.timestamp,e.Latitude,e.Longitude,e.TruckID,r.RfidCardNo,r.Rfidlogs from rfidinfo r " +
                         "   join ets_rfiddata e on  r.Rfidlogs=LEFT(e.bid ,LENGTH(e.bid)-2)" +
                         "   where e.TruckID in (" + inparam + ") and e.timestamp >= ? and e.timestamp <= ? " +
                         "   union " +
                         "   select distinct e.bid as Name,e.timestamp,e.Latitude,e.Longitude,e.TruckID, e.bid as RfidCardNo, e.bid as Rfidlogs" +
                         "   from  ets_rfiddata e" +
                         "   where e.TruckID in (" + inparam + ") and e.timestamp >= ? and e.timestamp <= ?" +
                         "   and e.bid not in (select  r.Rfidlogs from rfidinfo r)" +
                         "   and LEFT(e.bid ,LENGTH(e.bid)-2) not in (select  r.Rfidlogs from rfidinfo r)" +
                         "   order by timestamp";
            var lParameter = new Dictionary<string, object>();
            for (int i = 0; i < vehicles.Length; i++)
            {
                lParameter.Add("vehicle1_" + i, vehicles[i]);
            }
            lParameter.Add("fromDateStr", fromDateStr);
            lParameter.Add("toDateStr", toDateStr);
            for (int i = 0; i < vehicles.Length; i++)
            {
                lParameter.Add("vehicle2_" + i, vehicles[i]);
            }
            lParameter.Add("fromDateStr1", fromDateStr);
            lParameter.Add("toDateStr1", toDateStr);
            for (int i = 0; i < vehicles.Length; i++)
            {
                lParameter.Add("vehicle3_" + i, vehicles[i]);
            }
            lParameter.Add("fromDateStr2", fromDateStr);
            lParameter.Add("toDateStr2", toDateStr);
            if (rawdata == "1")
            {
                query = "select distinct e.TruckID,e.timestamp,e.Latitude,e.Longitude,e.bid" +
                         " from ets_rfiddata e where e.TruckID in (" + inparam + ") and e.timestamp >= ? and e.timestamp <= ?" +
                         " order by e.timestamp";
                lParameter = new Dictionary<string, object>();
                for (int i = 0; i < vehicles.Length; i++)
                {
                    lParameter.Add("vehicle_" + i, vehicles[i]);
                }
                lParameter.Add("fromDateStr", fromDateStr);
                lParameter.Add("toDateStr", toDateStr);
            }
            DataSet routeLatLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = routeLatLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();
        }
        public DataTable GetRFIDData(String vehicleId, String fromDateStr, String toDateStr)
        {
            var lParameter = new Dictionary<string, object>();
            string inparam = string.Empty;
            String[] vehicles = vehicleId.Replace("'", "").Split(',');
            for (int i = 0; i < vehicles.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
            }
            string query = "select distinct e.TruckID,e.timestamp,e.Latitude,e.Longitude,e.bid" +
                        " from ets_rfiddata e where e.TruckID in (" + inparam + ") and e.timestamp >= ? and e.timestamp <= ?" +
                        " order by e.TruckID,e.timestamp";
            for (int i = 0; i < vehicles.Length; i++)
            {
                lParameter.Add("vehicle_" + i, vehicles[i]);
            }
            lParameter.Add("fromDateStr", fromDateStr);
            lParameter.Add("toDateStr", toDateStr);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public Object[] getOnOffLatLong(String vehicleId, String fromDateStr, String toDateStr, String type)
        {
            StringBuilder query = new StringBuilder();
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            string track_part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), track_partions);
            if (type == "AC" || type == "")
            {
                query.Append("select t.id, idlingInstances, DATE_FORMAT(p.timestamp, '%d %b %Y, %r'), Start, Stop, Latitude, Longitude, UNIX_TIMESTAMP(p.timestamp) ,distance ,p.TruckID ");
                query.Append("from trackerdata PARTITION(" + track_part + ") AS t join positiondata PARTITION(" + part + ") AS p on (t.id = p.id and t.TruckID = p.TruckID) ");
                query.Append("where p.truckId =? ");
            }
            else if (type == "DOOR")
            {
                query.Append("select t.id, distance, DATE_FORMAT(p.timestamp, '%d %b %Y, %r'), Start, Stop,Latitude, Longitude, UNIX_TIMESTAMP(p.timestamp),Speed,p.TruckID  ");
                query.Append("from trackerdata PARTITION(" + track_part + ") AS t join positiondata PARTITION(" + part + ") AS p on (t.id = p.id and t.TruckID = p.TruckID) ");
                query.Append("where p.truckId =? ");
            }
            else if (type == "MACHINE")//It will take from STOP bit.
            {
                query.Append("select id,Stop as idlingInstances, DATE_FORMAT(p.timestamp, '%d %b %Y, %r'), Start, Stop, Latitude, Longitude, UNIX_TIMESTAMP(p.timestamp),Speed,p.TruckID  ");
                query.Append("from positiondata PARTITION(" + part + ") AS p ");
                query.Append("where p.truckId =? ");
            }
            else if(type == "IGNITION")
            {
                query.Append("select t.id, CASE WHEN idlingInstances = 1 AND Stop = 0 THEN 1 ELSE idlingInstances END AS idlingInstances, DATE_FORMAT(p.timestamp, '%d %b %Y, %r'), Start, Stop, Latitude, Longitude, UNIX_TIMESTAMP(p.timestamp),distance,p.TruckID ");
                query.Append("from trackerdata PARTITION(" + track_part + ") AS t join positiondata PARTITION(" + part + ") AS p on (t.id = p.id and t.TruckID = p.TruckID) ");
                query.Append("where p.truckId =? ");
            }
            else
            {

                query.Append("select t.id, idlingInstances, DATE_FORMAT(p.timestamp, '%d %b %Y, %r'), Start, Stop, Latitude, Longitude, UNIX_TIMESTAMP(p.timestamp),distance,p.TruckID ");
                query.Append("from trackerdata PARTITION(" + track_part + ") AS t join positiondata PARTITION(" + part + ") AS p on (t.id = p.id and t.TruckID = p.TruckID) ");
                query.Append("where p.truckId =? ");
            }
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            if (fromDateStr != null)
            {
                query.Append("and TimeStamp >= ? ");
                lParameter.Add("fromDateStr", formatDBDate(Convert.ToDateTime(fromDateStr)));
            }
            if (toDateStr != null)
            {
                query.Append("and TimeStamp <= ? ");
                lParameter.Add("toDateStr", formatDBDate(Convert.ToDateTime(toDateStr)));
            }
            query.Append(" order by TimeStamp");
            DataSet routeLatLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = routeLatLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();
        }
