        public Object[] getLastPositions(String sessionId, String date, string vehicles, string ShowTripStateinLand = "0", string vehicleType = "0")
        {

            String dbEndDate = date;
            bool isServiceUser;
            if (date == null)
            {
                DateTime endDate = DateTime.UtcNow;
                endDate = endDate.AddSeconds(GetTimeZoneDiff(sessionId));
                dbEndDate = formatDBDate(endDate);
            }

            string GetPosDataFrom = System.Web.Configuration.WebConfigurationManager.AppSettings["GetPosDataFrom"];
            if (GetPosDataFrom == "lastupdtdata")
            {
                return getLastPositionsFromLastUpdateTable(sessionId, vehicles, ShowTripStateinLand, vehicleType);
            }

            StringBuilder query = new StringBuilder();
            query.Append("create temporary table LastPositionsTS SELECT truckId, MAX(timestamp) as timestamp from lastupdtdata  where timestamp < ? group by truckId;");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("timestamp", dbEndDate);
            dbx.executeNonQuery(query.ToString(), lParameter);

            // Check for a service user
            // Find all groups that belong to the service
            query = new StringBuilder();
            query.Append("select s.GroupId from rp_users rp, sessions se, servicesgroupsmap s ");
            query.Append("where se.login = rp.login and rp.serviceid = s.serviceid and se.SessionID = ?");
            lParameter.Clear();
            lParameter.Add("SessionID", sessionId);

            DataSet serviceGroups = dbx.executeQuery(query.ToString(), lParameter);

            DataTable groups;
            groups = serviceGroups.Tables[0];
            if (serviceGroups.Tables[0].Rows.Count > 0)
            {
                groups = serviceGroups.Tables[0];
            }
            else                            // if the session is not from a service group , select from usersgroupsmap for groupid
            {
                // Try to find account users groups			
                query = new StringBuilder();
                query.Append("select um.GroupId from users u, sessions s, usersgroupsmap um ");
                query.Append("where s.login = u.login and u.login = um.Login and s.SessionID = ?;");

                lParameter.Clear();
                lParameter.Add("SessionID", sessionId);
                DataSet accountGroups = dbx.executeQuery(query.ToString(), lParameter);
                groups = accountGroups.Tables[0];
            }
            if (groups.Rows.Count > 0)
            {
                query = new StringBuilder();
                lParameter.Clear();
                //ADDED STOP bit on 21-01-14
                query.Append("create temporary table lastvehposdata Select distinct p.truckId, CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,");
                query.Append(" p.latitude, p.longitude, p.speed, UNIX_TIMESTAMP(p.timestamp) as unix, v.VehicleInfo,p.Stop,l.direction,v.IconType,v.OnOffType,v.TempSense,l.hvinp,l.gvinp1,l.BV,l.haltfrom,l.fuellevel,l.panic ");
                query.Append(" from positiondata p, LastPositionsTS lt, vehicles v, vehiclesgroupsmap vm,lastupdtdata l where v.VehicleId = vm.VehicleId and (");
                int groupCount = 0;
                foreach (DataRow row in groups.Rows)
                {
                    query.Append("vm.GroupId = ? OR ");
                    lParameter.Add("GroupId" + groupCount, row.ItemArray[0]);
                    groupCount++;
                }
                query.Append(" 0) and v.vehicleId = lt.truckId and p.timestamp = lt.timestamp ");
                query.Append("and p.TruckId = lt.truckId and l.truckid = lt.truckId ;");
            }
            else
            {
                query = new StringBuilder();
                lParameter.Clear();

                query.Append("select rp.serviceId from rp_users rp, sessions s ");
                query.Append("where s.login = rp.login and s.SessionID = ? ;");
                lParameter.Add("SessionID", sessionId);

                int serviceid = Convert.ToInt16(dbx.executeScalar(query.ToString(), lParameter));
                if (serviceid != 0)
                {
                    isServiceUser = true;
                    query.Clear();
                    query = new StringBuilder();
                    lParameter.Clear();

                    query.Append("create temporary table lastvehposdata Select distinct p.truckId, CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times ,");
                    query.Append(" p.latitude,p.longitude, p.speed, UNIX_TIMESTAMP(p.timestamp) as unix, v.VehicleInfo,p.Stop,l.direction,v.IconType, ");
                    query.Append("v.OnOffType,v.TempSense,l.hvinp,l.gvinp1,l.BV,l.haltfrom,l.fuellevel,l.panic from positiondata p,LastPositionsTS lt, vehicles v, servicesVehiclesmap sm, lastupdtdata l ");
                    query.Append("where v.VehicleId = sm.VehicleId and sm.serviceId = ?");
                    query.Append(" and sm.VehicleId = lt.truckId and p.timestamp = lt.timestamp");
                    query.Append(" and p.TruckId = lt.truckId and l.TruckId = lt.truckId ;");
                    lParameter.Add("serviceId", serviceid);

                }
                else
                {
                    // If user has no groups, he belongs to the whole account.
                    // Use all vehicles in the account                
                    query = new StringBuilder();


                    //////////////ADDED THE STOPBIT ON 09-01-2014

                    query.Append("create temporary table lastvehposdata Select distinct p.truckId, CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times, ");
                    query.Append("p.latitude,p.longitude,p.speed, UNIX_TIMESTAMP(p.timestamp) as unix, v.VehicleInfo,p.Stop,l.direction,v.IconType,v.OnOffType,v.TempSense,l.hvinp,l.gvinp1,l.BV,l.haltfrom,l.fuellevel,l.panic ");
                    query.Append(" from positiondata p, LastPositionsTS lt, vehicles v, accounts a, users u, sessions s, lastupdtdata l");
                    query.Append(" where v.AccountID = a.ID and a.ID = u.AccountID  and u.login = s.login");
                    query.Append(" and v.vehicleId = lt.truckId and p.timestamp = lt.timestamp");
                    query.Append(" and p.TruckId = lt.truckId and l.TruckId = lt.truckId and SessionID = ?");
                    lParameter.Clear();
                    lParameter.Add("SessionID", sessionId);

                }
            }

            DataSet lastPos = dbx.executeQuery(query.ToString(), lParameter);
            query = new StringBuilder();
            query.Append("select l.truckId, l.times, l.latitude,l.longitude,l.speed,l.unix, l.VehicleInfo,l.Stop,l.direction,l.IconType,l.OnOffType,l.TempSense,v.direction,l.hvinp,l.gvinp1,l.BV,l.haltfrom,l.fuellevel,l.panic from lastvehposdata l left join vehicleroutesummary v on l.truckid=v.vehicleid");

            DataSet lastPositions = dbx.executeQuery(query.ToString());
            DataTable table = lastPositions.Tables[0];
            ArrayList argsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                argsList.Add(row.ItemArray);
            }
            query = new StringBuilder();
            query.Append(" drop table IF EXISTS LastPositionsTS;");
            dbx.executeNonQuery(query.ToString());
            query = new StringBuilder();
            query.Append(" drop table IF EXISTS lastvehposdata;");
            dbx.executeNonQuery(query.ToString());
            return argsList.ToArray();
        }

        private bool checklastupdtdataAvailable(string date)
        {
            try
            {
                DateTime dt = Convert.ToDateTime(dbx.executeScalar("select Max(timestamp) from lastupdtdata;"));
                if ((Convert.ToDateTime(date) - dt).TotalMinutes <= 120 && (Convert.ToDateTime(date) - dt).TotalMinutes >= -60)
                    return true;
                else
                    return false;
            }
            catch { return false; }
        }

