        public DataTable GetMetroDailyDistance(string sessionId, DateTime reportDate)
        {
            int accountId = GetAccountId(sessionId);
            string sMonth = reportDate.Month.ToString();
            string sYear = reportDate.Year.ToString();
            string query = "select distinct m.StoreNo,m.vehicleId,DATE_FORMAT(m.Date, '%d/%m/%Y') as Date,m.Trips,m.runTime as `Est. Distance`,m.Distance as `Act. Distance`,m.TotalTrips, ROUND(sum(m2.Distance),2) as `TotalKmsInMonth` from metrodailydistance m " +
                "inner join metrodailydistance m2 on m.vehicleId = m2.vehicleId and month(m2.Date)= ? and year(m2.Date)= ? where date(m.Date) = ? group by m2.vehicleId order by m.StoreNo,m.vehicleId";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("month", sMonth);
            lParameter.Add("year", sYear);
            lParameter.Add("reportDate", formatDBDate(reportDate.Date));
            //lParameter.Add("AccountId", accountId);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public void UpdateMetroCustomerAddress(string customerId, string latitude, string longitude)
        {
            try
            {
                string address = getPositionTxt(latitude, longitude, 0);
                string query = "SELECT * FROM metro_customer_address WHERE CustomerId = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("CustomerId", customerId);
                DataTable dtCustomerAddreses = dbx.executeQuery(query, lParameter).Tables[0];
                DeleteCustomerDistanceMatrix(customerId);
                if (dtCustomerAddreses != null && dtCustomerAddreses.Rows.Count > 0)
                {
                    query = "UPDATE metro_customer_address SET Address = ?,Latitude = ?,Longitude = ? WHERE CustomerId = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Address", address);
                    lParameter.Add("Latitude", latitude);
                    lParameter.Add("Longitude", longitude);
                    lParameter.Add("CustomerId", customerId);

                    dbx.executeNonQuery(query, lParameter);
                }
                else
                {
                    query = "INSERT IGNORE INTO `metro_customer_address` (`CustomerId`,`Address`,`Latitude`,`Longitude`)";
                    query += " VALUES (?,?,?,?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("CustomerId", customerId);
                    lParameter.Add("Address", address);
                    lParameter.Add("Latitude", latitude);
                    lParameter.Add("Longitude", longitude);

                    dbx.executeNonQuery(query, lParameter);
                }
            }
            catch (Exception e)
            {
            }
        }

