                    DataTable dtProductVolume = dbx.executeQuery(query, lParameter).Tables[0];
                    if (dtProductVolume != null)
                    {
                        if (dtProductVolume.Rows.Count > 0)
                        {
                            if (!String.IsNullOrEmpty(dtProductVolume.Rows[0]["Length"].ToString()) && dtProductVolume.Rows[0]["Length"].ToString() != "null")
                            {
                                length = Convert.ToDecimal(dtProductVolume.Rows[0]["Length"]);

                                if (!String.IsNullOrEmpty(dtProductVolume.Rows[0]["Width"].ToString()) && dtProductVolume.Rows[0]["Width"].ToString() != "null")
                                    width = Convert.ToDecimal(dtProductVolume.Rows[0]["Width"]);

                                if (!String.IsNullOrEmpty(dtProductVolume.Rows[0]["Height"].ToString()) && dtProductVolume.Rows[0]["Height"].ToString() != "null")
                                    height = Convert.ToDecimal(dtProductVolume.Rows[0]["Height"]);

                                //Convert MM to CM
                                decimal mm2cm = Convert.ToDecimal(0.1);
                                if (length == 0)
                                    length = 1;
                                else
                                    length = length * mm2cm;
                                if (width == 0)
                                    width = 1;
                                else
                                    width = width * mm2cm;
                                if (height == 0)
                                    height = 1;
                                else
                                    height = height * mm2cm;

                                decimal productVolume = 0, totalproductVolume = 0;
                                productVolume = length * width * height;
                                totalproductVolume = productVolume * Convert.ToInt32(lp[i].totalQuantity);
                                totalvolume = totalvolume + totalproductVolume;
