                            {
                                TripId = dtTripId.Rows[0][0].ToString();
                            }
                        }

                        query = "UPDATE metro_invoice_details SET TripId = ?, TripSheetNo = ? WHERE TaxInvoiceNum = ?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("TripId", TripId);
                        lParameter.Add("TripSheetNo", objMetroInvoice.tripno);
                        lParameter.Add("TaxInvoiceNum", objMetroInvoice.taxinvoicenum);
                        dbx.executeNonQuery(query, lParameter);
                    }
                    catch (Exception e)
                    {
                    }

                }
            }

        }

