        public void MetroAddAdhocVehicles(string username, int accountid, int storeNo, string newVehicleId, string existingVehicleId, string vehicleName, string vehicleCapacity, string DriverName, string Mobile, string DLNo, string DLExpiryDate, string Transporter, long vehicleVolume)
        {
            string query = "";
            int acc = 2737;
            var lParameter = new Dictionary<string, object>();
            try
            {
                query = "UPDATE metro_market_vehicles SET Active = 0 WHERE VehicleId = ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", newVehicleId.Replace(" ", ""));
                dbx.executeNonQuery(query, lParameter);
            }
            catch (Exception e)
            {

            }

            query = "SELECT * from vehiclesgroupsmap v " +
                "inner join usersgroupsmap u on v.GroupId = u.GroupId " +
                "WHERE u.Login = ? AND REPLACE(v.VehicleId, ' ', '') = ?";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("Login", username);
            lParameter.Add("VehicleId", newVehicleId.Replace(" ", ""));
            string vehicleType = "Adhoc";
            DataTable dsVehicleType = dbx.executeQuery(query, lParameter).Tables[0];
            if (dsVehicleType != null)
            {
                if (dsVehicleType.Rows.Count > 0)
                {
                    vehicleType = "Dedicated";
                }
            }

            query = "SELECT TransporterId FROM transporterinfo WHERE ShortName = ?";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("ShortName", Transporter);
            string TransporterId = "";
            DataTable dsTransporterId = dbx.executeQuery(query, lParameter).Tables[0];
            if (dsTransporterId != null)
            {
                if (dsTransporterId.Rows.Count > 0)
                {
                    TransporterId = dsTransporterId.Rows[0][0].ToString();
                }
            }

            string dt = string.Empty;
            if (!String.IsNullOrEmpty(DLExpiryDate))
            {
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(DLExpiryDate, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt = formatDBDate(Convert.ToDateTime(DLExpiryDate));
                }
            }


            query = "INSERT INTO `metro_market_vehicles` (`StoreNo`,`VehicleId`,`VehicleName`,`Capacity`,`VehicleType`,`DriverName`,`Mobile`,`LicenseNo`,`LicenseValidity`,`MetroVehicleId`,`Transporter`,`TransporterId`,`AccountId`,`VolumeCap`)";
            query += " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("StoreNo", storeNo);
            lParameter.Add("VehicleId", newVehicleId.Replace(" ", ""));
            lParameter.Add("VehicleName", vehicleName);
            lParameter.Add("Capacity", vehicleCapacity);
            lParameter.Add("VehicleType", vehicleType);
            lParameter.Add("DriverName", DriverName);
            lParameter.Add("Mobile", Mobile);
            lParameter.Add("LicenseNo", DLNo);
            lParameter.Add("LicenseValidity", dt);
            lParameter.Add("MetroVehicleId", existingVehicleId.Replace(" ", ""));
            lParameter.Add("Transporter", Transporter);
            lParameter.Add("TransporterId", TransporterId);
            lParameter.Add("AccountId", acc);
            lParameter.Add("VolumeCap", vehicleVolume);
            dbx.executeNonQuery(query, lParameter);
        }

        public void Update_Metro_Vehicles(Metro_MarketVehicleInfo objMetroVehicle, string accountid)
        {
            decimal capacity = Convert.ToDecimal(objMetroVehicle.Capacity);
            if (capacity > 100)
            {
                capacity = capacity / 1000;
            }
            string query = "UPDATE metro_market_vehicles SET Active = 0 WHERE VehicleId = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleId", objMetroVehicle.VehicleId.Replace(" ", ""));
            dbx.executeNonQuery(query, lParameter);

            query = "SELECT TransporterId FROM transporterinfo WHERE ShortName = ?";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("ShortName", objMetroVehicle.Transporter);
            string TransporterId = "";
            DataTable dsTransporterId = dbx.executeQuery(query, lParameter).Tables[0];
            if (dsTransporterId != null)
            {
                if (dsTransporterId.Rows.Count > 0)
                {
                    TransporterId = dsTransporterId.Rows[0][0].ToString();
                }
            }

            query = "INSERT INTO `metro_market_vehicles` (`StoreNo`,`VehicleId`,`VehicleName`,`Capacity`,`VehicleType`,`DriverName`,`Mobile`,`Transporter`,`TransporterId`,`AccountId`)";
            query += " VALUES (?,?,?,?,?,?,?,?,?,?)";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("StoreNo", objMetroVehicle.StoreNo);
            lParameter.Add("VehicleId", objMetroVehicle.VehicleId.Replace(" ", ""));
            lParameter.Add("VehicleName", objMetroVehicle.VehicleType);
            lParameter.Add("Capacity", capacity);
            lParameter.Add("VehicleType", objMetroVehicle.Type);
            lParameter.Add("DriverName", objMetroVehicle.DriverName);
            lParameter.Add("Mobile", objMetroVehicle.MobileNo);
            lParameter.Add("Transporter", objMetroVehicle.Transporter);
            lParameter.Add("TransporterId", TransporterId);
            lParameter.Add("AccountId", accountid);
            dbx.executeNonQuery(query, lParameter);
        }

        public Object[] getLastPositionsFromLastUpdateTable(String sessionId, string Vehicles = "", string ShowTripStateinLand = "0", string vehicleType = "0")
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            if (!string.IsNullOrEmpty(Vehicles))
            {
                string[] vehls = Vehicles.Replace("'", "").Replace("\"", "").Split(',');
                string inparam = string.Empty;
                for (int i = 0; i < vehls.Length; i++)
                {
                    if (i == 0)
                        inparam += ("?");
                    else
                        inparam += (", ?");
                }
                query = new StringBuilder();
                if (ShowTripStateinLand == "0")
                {
                    query.Append("Select distinct p.truckId,CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,latitude,longitude,speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,'' as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel,p.panic ");
                    query.Append(" from lastupdtdata p,vehicles v");
                    query.Append(" where v.VehicleId = p.truckId");
                    query.Append(" and p.TruckId in (" + inparam + ");");
                }
                else
                {
                    query.Append("Select distinct p.truckId,CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,r.direction as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel ");
                    query.Append(" from lastupdtdata p");
                    query.Append(" join vehicles v on v.VehicleId = p.truckId");
                    query.Append(" left join vehicleroutesummary r on p.truckid=r.vehicleid");
                    query.Append(" where p.TruckId in (" + inparam + ");");
                }
                lParameter = new Dictionary<string, object>();
                for (int i = 0; i < vehls.Length; i++)
                {
                    lParameter.Add("vehicle1_" + i, vehls[i]);
                }
                DataTable lastPostable = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                ArrayList arglst = new ArrayList();
                foreach (DataRow row in lastPostable.Rows)
                {
                    arglst.Add(row.ItemArray);
                }
                return arglst.ToArray();
            }
            // Check for a service user
            // Find all groups that belong to the service
            query = new StringBuilder();
            query.Append("select s.GroupId from rp_users u, sessions se, servicesgroupsmap s ");
            query.Append("where se.login = u.login and u.serviceid = s.serviceid and se.SessionID =?");
            lParameter = new Dictionary<string, object>();
            lParameter.Add("SessionID", sessionId);
            DataSet serviceGroups = dbx.executeQuery(query.ToString(), lParameter);


            DataTable groups;
            groups = serviceGroups.Tables[0];
            if (serviceGroups.Tables[0].Rows.Count > 0)
            {
                groups = serviceGroups.Tables[0];
            }
            else                            // if the session is not from a service group , select from usersgroupsmap for groupid
            {
                // Try to find account users groups			
                query = new StringBuilder();
                query.Append("select um.GroupId from users u, sessions s, usersgroupsmap um ");
                query.Append("where s.login = u.login and u.login = um.Login and s.SessionID = ?");
                lParameter.Clear();
                lParameter.Add("SessionID", sessionId);
                DataSet accountGroups = dbx.executeQuery(query.ToString(), lParameter);
                groups = accountGroups.Tables[0];
            }
            if (groups.Rows.Count > 0)
            {
                query = new StringBuilder();
                if (ShowTripStateinLand == "0")
                {
                    query.Append("Select distinct p.truckId,  CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,'' as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel,p.panic ");
                    query.Append(" from lastupdtdata p");
                    query.Append(" join vehicles v on v.vehicleId = p.truckId");
                    query.Append(" join vehiclesgroupsmap g on v.VehicleId = g.VehicleId ");
                    if (vehicleType == "1")
                        query.Append(" join configdata cd on cd.TruckID = g.VehicleId and cd.OwnerContact=1  and cd.ReturnDate IS NULL");
                    else if (vehicleType == "2")
                        query.Append(" join configdata cd on cd.TruckID = g.VehicleId and cd.OwnerContact!=-1 and cd.ReturnDate IS NULL");
                    else if (vehicleType == "3")
                    {
                        query.Append(" AND p.truckid NOt IN (SELECT vp.vehicleid  FROM vehicleinplant vp JOIN ");
                        query.Append(" vehiclesgroupsmap g on vp.VehicleId = g.VehicleId WHERE g.GroupId=" + groups.Rows[0]["GroupId"].ToString() + " AND vp.planttype IN(1,2) AND vp.outtimestamp IS NULL ");
                        query.Append(" AND vp.intimestamp > '" + Convert.ToDateTime(DateTime.Today).ToString("yyyy-MM-dd") + "') ");
                    }
                }
                else
                {
                    query.Append("Select distinct p.truckId,  CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,r.direction as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel ");
                    query.Append(" from lastupdtdata p");
                    query.Append(" join vehicles v on v.vehicleId = p.truckId");
                    query.Append(" join vehiclesgroupsmap g on v.VehicleId = g.VehicleId ");
                    query.Append(" left join vehicleroutesummary r on p.truckid=r.vehicleid");
                }
                query.Append(" where (");
                lParameter.Clear();
                int j = 0;
                foreach (DataRow row in groups.Rows)
                {
                    j++;
                    query.Append("g.GroupId = ? OR ");
                    lParameter.Add("GroupId" + j, row.ItemArray[0]);
                }
                query.Append(" 0)");
            }
            else
            {
                query = new StringBuilder();
                query.Append("select rp.serviceId from rp_users rp, sessions s ");
                query.Append("where s.login = rp.login and s.SessionID = ?");
                lParameter.Clear();
                lParameter.Add("SessionID", sessionId);
                int serviceid = Convert.ToInt16(dbx.executeScalar(query.ToString(), lParameter));
                if (serviceid != 0)
                {
                    query = new StringBuilder();
                    if (ShowTripStateinLand == "0")
                    {
                        query.Append("Select distinct p.truckId, CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,'' as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel ");
                        query.Append(" from lastupdtdata p,vehicles v,servicesVehiclesmap g");
                        query.Append(" where v.VehicleId = g.VehicleId and g.serviceId = ? and g.VehicleId = p.truckId;");
                        lParameter.Clear();
                        lParameter.Add("serviceId", serviceid);
                    }
                    else
                    {
                        query.Append("Select distinct p.truckId,  CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,r.direction as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel ");
                        query.Append(" from lastupdtdata p");
                        query.Append(" join vehicles v on v.VehicleId = p.truckId");
                        query.Append(" join servicesVehiclesmap g on v.VehicleId = g.VehicleId");
                        query.Append(" left join vehicleroutesummary r on p.truckid=r.vehicleid");
                        query.Append(" where g.serviceId = ?");
                        lParameter.Clear();
                        lParameter.Add("serviceId", serviceid);
                    }
                }
                else
                {
                    // If user has no groups, he belongs to the whole account.
                    // Use all vehicles in the account                
                    query = new StringBuilder();
                    if (ShowTripStateinLand == "0")
                    {
                        query.Append("Select distinct p.truckId,  CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,'' as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel ");
                        query.Append(" from lastupdtdata p");
                        query.Append(" join vehicles v on v.vehicleId = p.truckid");
                        query.Append(" join accounts a on v.AccountID = a.ID");
                        query.Append(" join users u on a.ID = u.AccountID");
                        query.Append(" join sessions s on u.login = s.login");
                        query.Append(" where s.SessionID =? ;");
                        lParameter.Clear();
                        lParameter.Add("SessionID", sessionId);
                    }
                    else
                    {
                        query.Append("Select distinct p.truckId, CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,r.direction as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel ");
                        query.Append(" from lastupdtdata p");
                        query.Append(" join vehicles v on v.vehicleId = p.truckid");
                        query.Append(" join accounts a on v.AccountID = a.ID");
                        query.Append(" join users u on a.ID = u.AccountID");
                        query.Append(" join sessions s on u.login = s.login");
                        query.Append(" left join vehicleroutesummary r on p.truckid=r.vehicleid");
                        query.Append(" where s.SessionID =? ;");
                        lParameter.Clear();
                        lParameter.Add("SessionID", sessionId);
                    }
                }
            }
            DataSet lastPositions = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = lastPositions.Tables[0];
            ArrayList argsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                argsList.Add(row.ItemArray);
            }
            query = new StringBuilder();
            return argsList.ToArray();
        }

