        public string MobileTrackingApp_OTPRequest(string mobileno)
        {
            try
            {
                string query = "SELECT * FROM mobileapptracking_config_for_vehicle m WHERE m.MobileNo = ? AND m.Active = 1";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("MobileNo", mobileno);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                if (dt.Rows.Count > 0)
                {

                    query = "SELECT * FROM mobileapptracking_config_for_vehicle m WHERE m.MobileNo = ? AND m.Active = 1 AND m.NoOfHoursToTrack != 0";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("MobileNo", mobileno);
                    DataTable dtTrips = dbx.executeQuery(query, lParameter).Tables[0];

                    if (dtTrips.Rows.Count > 0)
                    {
                        query = "UPDATE mobileapp_otp_sessions o SET o.IsExpired = 1 WHERE o.MobileNo = ?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("MobileNo", mobileno);
                        dbx.executeNonQuery(query, lParameter);

                        Random rand = new Random();
                        string otp = rand.Next(1000, 9999).ToString();
                        string str = "One Time Password for Driver APP is " + otp;
                        query = "Insert into mobileapp_otp_sessions(`Type`,TrackID,MobileNo,OTP,OTP_GeneratedOn,sessionid,AccountId,GlobalAccID)" +
                                " values(?,?,?,?,?,?,?,?)";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("Type", "Vehicle");
                        lParameter.Add("TrackID", dt.Rows[0]["TrackID"].ToString());
                        lParameter.Add("MobileNo", mobileno);
                        lParameter.Add("OTP", otp);
                        lParameter.Add("OTP_GeneratedOn", formatDBDate(DateTime.Now));
                        lParameter.Add("sessionid", Guid.NewGuid().ToString());
                        lParameter.Add("AccountId", dt.Rows[0]["AccountID"].ToString());
                        lParameter.Add("GlobalAccID", dt.Rows[0]["GlobalAccID"].ToString());
                        dbx.executeNonQuery(query, lParameter);
                        SendSMSByAdminService(dt.Rows[0]["GlobalAccID"].ToString(), "", mobileno, str, "Driver App OTP", "");
                        return "OTP Send Successfully";
                    }
                    else
                    {
                        return "Currently No Trips Allocated";
                    }
                }
                else
                {
                    return "Mobile Number is Not Registered.";
                }
            }
            catch (Exception ex) { return ex.Message; }
        }
