        public string GetTripInvoicesByCustomerAndStatus(string customerid, string tripsheetno, string status)
        {
            try
            {
                //string query = "select o.*,d.Name from otp_sessions o " +
                //               " join driverinfo d on d.DriverId=o.userid where o.MobileNo=? and o.OTP=?";
                string query = "SELECT SUM(s.TotalQuantity) FROM metro_invoice_products s WHERE s.InvoiceId IN (SELECT s.TaxInvoiceNum FROM metro_invoice_details s WHERE s.TripSheetNo = ? AND s.CustomerId = ? AND s.Delivery_Status = ?)";
                if (status == "Returned")
                {
                    query = "SELECT SUM(s.ReturnedQty) FROM metro_invoice_products s WHERE s.InvoiceId IN (SELECT s.TaxInvoiceNum FROM metro_invoice_details s WHERE s.TripSheetNo = ? AND s.CustomerId = ? AND s.Delivery_Status = ?)";
                }
                else if (status == "Rejected")
                {
                    query = "SELECT SUM(s.TotalQuantity) FROM metro_invoice_products s WHERE s.InvoiceId IN (SELECT s.TaxInvoiceNum FROM metro_invoice_details s WHERE s.TripSheetNo = ? AND s.CustomerId = ? AND s.Delivery_Status = ?)";
                }

                var lParameter = new Dictionary<string, object>();
                lParameter.Add("TripSheetNo", tripsheetno);
                lParameter.Add("CustomerId", customerid);
                lParameter.Add("Delivery_Status", status);
                return Convert.ToString(dbx.executeScalar(query, lParameter));
            }
            catch (Exception ex) { return null; }
        }
