        public DataTable MetroGetInvoiceDetailsByTripNo(string tripsheetno)
        {
            try
            {
                //string query = "SELECT m.TaxInvoiceNum,IFNULL(m.InvoiceType,'Delivery') as InvoiceType from metro_invoice_details m where m.TripSheetNo = ?";
                string query = "SELECT m.StoreNo,m.TaxInvoiceNum,IFNULL(m.InvoiceType,'Delivery') as InvoiceType,m.ConsignmentId,m.Delivery_Status,m.Delivery_Status_Updated_On AS `Delivery_Status_Updated_On`,m.Reason,CONCAT(v.DriverName,'_',v.Mobile) AS `DriverInfo`,t.Trip_Status_Updated_On AS `Trip_Status_Updated_On`,m.OrderType,m.PaymentType,m.ReturnId from metro_invoice_details m " +
                    "JOIN metro_trip_details t ON m.TripId = t.Id " +
                    "JOIN metro_market_vehicles v ON v.VehicleId = t.VehicleId AND t.DriverId = v.ID AND v.Active = 1 " +
                    "where m.TripSheetNo = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("TripSheetNo", tripsheetno);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            catch (Exception ex) { return null; }
        }
