        public string MetroGetTripSheetNoByInvoice(string invoiceNum)
        {
            string tripSheetNum = "";
            string query = "SELECT TripId FROM metro_invoice_details WHERE InvoiceNum= ? ORDER BY TripId DESC LIMIT 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("InvoiceNum", invoiceNum);
            DataTable dstripSheetNum = dbx.executeQuery(query, lParameter).Tables[0];
            if (dstripSheetNum != null)
            {
                if (dstripSheetNum.Rows.Count > 0)
                {
                    tripSheetNum = dstripSheetNum.Rows[0][0].ToString();
                }
            }
            return tripSheetNum;
        }
        public string Metro_DriverApp_UpdateCustomerAddress(string invoiceNum, string latlng)
        {
            string AddressId = "";
            string loc = "";
            string query = "SELECT AddressId FROM metro_invoice_details WHERE TaxInvoiceNum= ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TaxInvoiceNum", invoiceNum);
            DataTable dsAddressId = dbx.executeQuery(query, lParameter).Tables[0];
            if (dsAddressId != null)
            {
                if (dsAddressId.Rows.Count > 0)
                {
                    AddressId = dsAddressId.Rows[0][0].ToString();
                }
            }
            string[] latitudelongitude = latlng.ToString().Split(',');
            if (latitudelongitude.Length > 1 && !String.IsNullOrEmpty(latitudelongitude[0]) && !String.IsNullOrEmpty(latitudelongitude[1]))
                loc = getPositionTxt(latitudelongitude[0], latitudelongitude[1], 0);


            query = "SELECT CustomerId FROM metro_invoice_details WHERE TaxInvoiceNum= ?";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("TaxInvoiceNum", invoiceNum);
            DataTable dsCustomerId = dbx.executeQuery(query, lParameter).Tables[0];
            string customerId = "";
            if (dsCustomerId != null)
            {
                if (dsCustomerId.Rows.Count > 0)
                {
                    customerId = dsCustomerId.Rows[0][0].ToString();
                }
            }

            DeleteCustomerDistanceMatrix(customerId);

            query = "UPDATE metro_customer_address SET Address = ?,Latitude = ?,Longitude = ? WHERE AddressId = ?";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("Address", loc);
            lParameter.Add("Latitude", latitudelongitude[0].ToString());
            lParameter.Add("Longitude", latitudelongitude[1].ToString());
            lParameter.Add("AddressId", AddressId);
            dbx.executeNonQuery(query, lParameter);
            return "";
        }
