        public string InsertFeedSmartFoodProviderEntry(string sessionid, string morningPacks, string eveningPacks, string locationid)
        {
            try
            {
                DataTable dt = GetFeedSmartFoodRqdLocData();
                int adminMrngPacks = 0;
                int adminEvngPacks = 0;
                int userMrngPacks = Convert.ToInt32(morningPacks);
                int userEvngPacks = Convert.ToInt32(eveningPacks);
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    if (locationid == dt.Rows[i]["LocationId"].ToString())
                    {
                        adminMrngPacks = Convert.ToInt32(dt.Rows[i]["Morning"].ToString());
                        adminEvngPacks = Convert.ToInt32(dt.Rows[i]["Evening"].ToString());
                        break;
                    }
                }
                string userid = GetFeedSmartFoodUserIDbySessionid(sessionid);

                string query = "select * from feed_smart_food_provider f where f.Date=? and f.UserID=? and f.LocationID=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("Date", convertDateTime(DateTime.Today.ToString("")));
                lParameter.Add("UserID", userid);
                lParameter.Add("LocationID", locationid);
                DataTable userDt = dbx.executeQuery(query, lParameter).Tables[0];

                if (userDt != null && userDt.Rows.Count > 0)
                {
                    adminMrngPacks = adminMrngPacks + Convert.ToInt32(userDt.Rows[0]["Morning"].ToString());
                    adminEvngPacks = adminMrngPacks + Convert.ToInt32(userDt.Rows[0]["Morning"].ToString());
                }
                if (userMrngPacks > adminMrngPacks)
                    return "Failed - " + (userMrngPacks - adminMrngPacks) + " Morning Packs are more. Please try again.";
                else if (userEvngPacks > adminEvngPacks)
                    return "Failed - " + (userEvngPacks - adminEvngPacks) + " Evening Packs are more. Please try again.";
                else
                {
                    query = "update feed_smart_food_provider f set f.Morning=?, f.Evening=? where f.Date=? and f.UserID=? and f.LocationID=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Morning", morningPacks);
                    lParameter.Add("Evening", eveningPacks);
                    lParameter.Add("Date", convertDateTime(DateTime.Today.ToString("")));
                    lParameter.Add("UserID", userid);
                    lParameter.Add("LocationID", locationid);
                    int res = dbx.executeNonQuery(query, lParameter);

                    if (res == 0)
                    {
                        query = "INSERT INTO `feed_smart_food_provider` (`Date`, `UserID`, `Morning`, `Evening`,LocationID) VALUES (?, ?, ?, ?, ?);";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("Date", convertDateTime(DateTime.Today.ToString("")));
                        lParameter.Add("UserID", userid);
                        lParameter.Add("Morning", morningPacks);
                        lParameter.Add("Evening", eveningPacks);
                        lParameter.Add("LocationID", locationid);
                        res = dbx.executeNonQuery(query, lParameter);

                        if (Convert.ToInt32(morningPacks) > 0)
                        {
                            query = "INSERT INTO `feed_smart_trips` (`Date`, `UserID`, `Packets`, `Type`, `SourceLocID`, `DestinationLocID`) "
                                + "(SELECT f.Date,f.UserID,f.Morning,'Morning',p.LocationId,f.LocationID from feed_smart_food_provider f JOIN feed_smart_profiles p ON "
                                + "p.ID=f.UserID where f.Date=? and f.UserID=? AND f.LocationID=?)";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("Date", convertDateTime(DateTime.Today.ToString("")));
                            lParameter.Add("UserID", userid);
                            lParameter.Add("LocationID", locationid);
                            res = dbx.executeNonQuery(query, lParameter);
                        }
                        if (Convert.ToInt32(eveningPacks) > 0)
                        {
                            query = "INSERT INTO `feed_smart_trips` (`Date`, `UserID`, `Packets`, `Type`, `SourceLocID`, `DestinationLocID`) "
                                + "(SELECT f.Date,f.UserID,f.Evening,'Evening',p.LocationId,f.LocationID from feed_smart_food_provider f JOIN feed_smart_profiles p ON "
                                + "p.ID=f.UserID where f.Date=? and f.UserID=? AND f.LocationID=?)";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("Date", convertDateTime(DateTime.Today.ToString("")));
                            lParameter.Add("UserID", userid);
                            lParameter.Add("LocationID", locationid);
                            res = dbx.executeNonQuery(query, lParameter);
                        }
                    }
                    else
                    {
                        query = "UPDATE feed_smart_trips t SET t.Packets=? WHERE t.Date=? AND t.UserID=? AND t.`Type`='Morning' AND t.DestinationLocID=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("Packets", userMrngPacks);
                        lParameter.Add("Date", convertDateTime(DateTime.Today.ToString("")));
                        lParameter.Add("UserID", userid);
                        lParameter.Add("LocationID", locationid);
                        res = dbx.executeNonQuery(query, lParameter);

                        query = "UPDATE feed_smart_trips t SET t.Packets=? WHERE t.Date=? AND t.UserID=? AND t.`Type`='Evening' AND t.DestinationLocID=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("Packets", userEvngPacks);
                        lParameter.Add("Date", convertDateTime(DateTime.Today.ToString("")));
                        lParameter.Add("UserID", userid);
                        lParameter.Add("LocationID", locationid);
                        res = dbx.executeNonQuery(query, lParameter);
                    }
                    return "Updated Successfully";
                }
            }
            catch (Exception ex) { return "Error"; }
        }

