        public string InsertFeedSmartProfileInfo(string name, string mobileno, string location, string latlng, string address)
        {
            try
            {
                string query = "select * from feed_smart_profiles f where f.MobileNo=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("mobileno", mobileno);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];

                if (dt.Rows.Count == 0)
                {
                    query = "INSERT INTO `feed_smart_locations` (`LocationName`, `Latitude`, `Longitude`,Address) VALUES (?, ?, ?, ?);";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("LocationName", location);
                    lParameter.Add("Latitude", latlng.Split(',')[0]);
                    lParameter.Add("Longitude", latlng.Split(',')[1]);
                    lParameter.Add("Address", address);
                    int res = dbx.executeNonQuery(query, lParameter);
                    if (res > 0)
                    {
                        query = "select max(f.ID) from feed_smart_locations f where f.LocationName=? and f.Latitude=? and f.Longitude=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("LocationName", location);
                        lParameter.Add("Latitude", latlng.Split(',')[0]);
                        lParameter.Add("Longitude", latlng.Split(',')[1]);
                        string id = Convert.ToString(dbx.executeScalar(query, lParameter));

                        query = "INSERT INTO `feed_smart_profiles` (`Name`, `Role`, `MobileNo`, `LocationId`) VALUES (?, ?, ?, ?);";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("Name", name);
                        lParameter.Add("Role", "NonAdmin");
                        lParameter.Add("MobileNo", mobileno);
                        lParameter.Add("LocationId", id);
                        res = dbx.executeNonQuery(query, lParameter);
                        if (res == 0)
                            return "Failed to register mobile number";
                        else
                            return "Registered Successfully";
                    }
                    else
                        return "Failed to update Location";
                }
                else
                    return "Already phone number is registered. Please login with OTP.";
            }
            catch (Exception ex) { return ex.ToString(); }
        }

