        public DataTable GetFeedSmartFoodRqdLocData()
        {
            try
            {
                string query = "select * from (select p.LocationId,(m.Morning-ifnull(sum(f.Morning),0)) 'Morning',(m.Evening-ifnull(sum(f.Evening),0)) 'Evening',"
                    + "l.Latitude,l.Longitude,l.LocationName from feed_smart_profiles p join feed_smart_food_master m on p.ID=m.UserID join feed_smart_locations l on "
                    + "l.ID=p.LocationId left join feed_smart_food_provider f on f.LocationID=p.LocationId and f.Date=m.Date where p.Role='Admin' and date(m.Date)=? "
                    + "group by (p.LocationId)) tbl where tbl.Morning>0 or tbl.Evening>0";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("Date", convertDateTime(DateTime.Today.ToString("")));
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            catch (Exception ex) { return null; }
        }

