        public DataTable Metro_DriverApp_GetTrips(string driver_sessionid)
        {
            try
            {
                string query = "select t.TripNum,d.OrderDateTime,d.TaxInvoiceNum,d.TotalPrice,d.InvoiceAmountCollected,d.DeliveryCharge,d.DeliveryChargeCollected,d.IsVerified,c.CustomerId,c.CustomerName,"
                    + "a.MobileNo,a.CustomerAddressId,a.Address,IFNULL(d.Delivery_Status,'Pending') as Delivery_Status,d.InvoiceType,d.OrderType,d.PaymentType,d.PaymentMethod,d.PaymentStatus,d.ConsignmentId,d.ReturnId,d.AlternativeMobileNo,t.Trip_Status,a.Latitude,a.Longitude from metro_trip_details t" +
                               " join metro_invoice_details d on d.TripId = t.Id" +
                               " join metro_customers_info c on c.CustomerId = d.CustomerId AND c.StoreNo = t.StoreNo" +
                               " join metro_customer_address a on a.AddressId = d.AddressId" +
                               //" join driverinfo di on (di.AssignedVehicleId = t.VehicleId or REPLACE(di.AssignedVehicleId, ' ', '') = t.VehicleId)" +
                               " join metro_market_vehicles di on di.VehicleId = t.VehicleId" +
                               " join otp_sessions o on o.MobileNo = di.Mobile" +
                               " where o.sessionid =? and t.TripDate>? and t.Trip_Status != 'Closed' AND di.Active = 1" +
                               " group by d.TaxInvoiceNum order by d.DeliveryOrder";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("driver_sessionid", driver_sessionid);
                lParameter.Add("date", DateTime.Today.AddDays(-1).ToString("yyyy-MM-dd 00:00"));
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            catch (Exception ex) { return null; }
        }
        public DataTable Metro_DriverApp_GetInvoiceProducts(string invoiceno)
