        public Object[] getEmployeesRostered(String DateStr, String routingShift)
        {
            StringBuilder query = new StringBuilder();
            if (routingShift == "All")
            {
                query.Append("select ets_employee.employeenumber, ets_employee.sex, ets_employeeshift.fromtime, ets_employeeshift.totime,ets_employee.zone, ets_employee.stoplatitude, ets_employee.stoplongitude ");
                query.Append("from (ets_employee join ets_employeeshift on ets_employee.id=ets_employeeshift.emp_id) ");
                query.Append("where ets_employeeshift.date=\"" + DateStr + "\"");
            }
            else
            {
                char[] separator = { ' ' };
                String[] tStr = routingShift.Split(separator);
                if (tStr[1] == "login")
                {
                    query.Append("select ets_employee.employeenumber, ets_employee.sex, ets_employeeshift.fromtime, ets_employeeshift.totime,ets_employee.zone, ets_employee.stoplatitude, ets_employee.stoplongitude ");
                    query.Append("from (ets_employee join ets_employeeshift on ets_employee.id=ets_employeeshift.emp_id) ");
                    query.Append("where ets_employeeshift.date=\"" + DateStr + "\"");
                    query.Append(" and ets_employeeshift.fromtime = \"" + tStr[0] + "\"");
                }
                else if (tStr[1] == "logout")
                {
                    query.Append("select ets_employee.employeenumber, ets_employee.sex, ets_employeeshift.fromtime, ets_employeeshift.totime,ets_employee.zone, ets_employee.stoplatitude, ets_employee.stoplongitude ");
                    query.Append("from (ets_employee join ets_employeeshift on ets_employee.id=ets_employeeshift.emp_id) ");
                    query.Append("where ets_employeeshift.date=\"" + DateStr + "\"");
                    query.Append(" and ets_employeeshift.totime = \"" + tStr[0] + "\"");
                }
            }

            DataSet qresult = dbx.executeQuery(query.ToString());
            DataTable table = qresult.Tables[0];
            ArrayList vList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                vList.Add(row.ItemArray);
            }
            return vList.ToArray();
        }


        public Object[] getPlannedHalfTrips(String DateStr, String routingShift)
        {
            StringBuilder query = new StringBuilder();
            if (routingShift == "All")
            {
                query.Append("select ets_trips.tripid, ets_trips.shift, ets_trips.type, ets_employee.employeenumber, ets_employee.name, ets_employee.sex, ets_employee.project, ets_employee.address, ets_employee.pickuppoint, ets_employee.phone1, ets_trips.tripoccupancy from ");
                query.Append("(( ets_trips join ets_tripstops on ets_trips.tripid = ets_tripstops.tripid) join ets_employee on ets_employee.employeenumber = ets_tripstops.employeenumber) ");
                query.Append("where ets_trips.tripdate=\"" + DateStr + "\" order by ets_trips.type, ets_trips.shift, ets_trips.tripid, ets_tripstops.stop ");
            }
            else
            {
                char[] separator = { ' ' };
                String[] tStr = routingShift.Split(separator);
                if (tStr[1] == "login")
                {
                    query.Append("select ets_trips.tripid, ets_trips.shift, ets_trips.type, ets_employee.employeenumber, ets_employee.name, ets_employee.sex, ets_employee.project, ets_employee.address, ets_employee.pickuppoint, ets_employee.phone1, ets_trips.tripoccupancy  from ");
                    query.Append("(( ets_trips join ets_tripstops on ets_trips.tripid = ets_tripstops.tripid) join ets_employee on ets_employee.employeenumber = ets_tripstops.employeenumber) ");
                    query.Append("where ets_trips.tripdate=\"" + DateStr + "\" and ets_trips.type='0' and ets_trips.shift='" + tStr[0] + "' order by ets_trips.type, ets_trips.shift, ets_trips.tripid, ets_tripstops.stop ");
                }
                else if (tStr[1] == "logout")
                {
                    query.Append("select ets_trips.tripid, ets_trips.shift, ets_trips.type, ets_employee.employeenumber, ets_employee.name, ets_employee.sex, ets_employee.project, ets_employee.address, ets_employee.pickuppoint, ets_employee.phone1, ets_trips.tripoccupancy  from ");
                    query.Append("(( ets_trips join ets_tripstops on ets_trips.tripid = ets_tripstops.tripid) join ets_employee on ets_employee.employeenumber = ets_tripstops.employeenumber) ");
                    query.Append("where ets_trips.tripdate=\"" + DateStr + "\" and ets_trips.type='1' and ets_trips.shift='" + tStr[0] + "' order by ets_trips.type, ets_trips.shift, ets_trips.tripid, ets_tripstops.stop ");
                }
            }

            DataSet qresult = dbx.executeQuery(query.ToString());
            DataTable table = qresult.Tables[0];
            ArrayList vList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                vList.Add(row.ItemArray);
            }
            return vList.ToArray();
        }

