        //RSrini Changed on 06/02/2015
        public Object[] getLastDirection(String vehicleId, String toDateStr)
        {
            DateTime todate = Convert.ToDateTime(toDateStr);
            DateTime fromdate = todate.AddDays(-1);
            string temp = string.Empty;
            if (todate > fromdate)
            {
                while (fromdate <= todate)
                {
                    temp = temp + partions[fromdate.Month - 1] + ",";
                    fromdate = fromdate.AddMonths(1);

                    if (fromdate > todate && fromdate.Month == todate.Month && (fromdate - todate).TotalDays < DateTime.DaysInMonth(todate.Year, todate.Month) - 1)
                        temp = temp + partions[fromdate.Month - 1] + ",";

                }
                temp = temp.Substring(0, temp.Length - 1);
            }
            else
            {
                temp = "pjan";
            }
            StringBuilder query = new StringBuilder();
            query.Append("select Latitude, Longitude, UNIX_TIMESTAMP(positiondata.timestamp) ");
            query.Append("from positiondata PARTITION(" + temp + ") ");
            query.Append("where positiondata.truckId =? ");
            if (toDateStr != null)
            {
                query.Append("and TimeStamp <= ? ");
            }
            query.Append("order by TimeStamp DESC limit 5");

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("toDateStr", toDateStr);
            DataSet routeLatLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = routeLatLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();
        }

