        public DateTime[] getLastTripTimes(String vehicleId, String toDateStr, double distdiff)
        {
            DateTime[] dates = new DateTime[2];
            //dates[0] = DateTime.UtcNow.AddSeconds(5*60*60 + 30*60 - 24*60*60);
            // Changed 08 April 2009 to handle case where box is just installed.
            // At start of data it is outside home and has no prior home date.
            // Take minvalue as the home date.
            dates[0] = DateTime.MinValue;
            dates[1] = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
            StringBuilder query = new StringBuilder();
            query.Append("select HomeLat, HomeLong from vehicles");
            query.Append(" where vehicleID=?;");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            DataSet vehicleHome = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = vehicleHome.Tables[0];
            float homeLat = Convert.ToSingle(table.Rows[0][0]);
            float homeLong = Convert.ToSingle(table.Rows[0][1].ToString());

            String outsideHomeDBDateTimeStr = null;
            query = new StringBuilder();
            string part = GetDateTablePartitions(Convert.ToDateTime(toDateStr).AddDays(-30), Convert.ToDateTime(toDateStr), partions);
            query.Append("SELECT timestamp from positiondata PARTITION(" + part + ") ");
            query.Append(" where truckId=?");
            if (toDateStr != null)
            {
                query.Append(" and timestamp < ?");
            }
            query.Append(" and latitude not between ? and ?");
            query.Append(" and longitude not between ? and ?");
            query.Append(" order by timestamp desc limit 1;");
            lParameter.Clear();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("toDateStr", toDateStr);
            lParameter.Add("latitude1", (homeLat - distdiff));
            lParameter.Add("latitude2", (homeLat + distdiff));
            lParameter.Add("longitude1", (homeLong - distdiff));
            lParameter.Add("longitude2", (homeLong + distdiff));

            Object outsideHomeDate = dbx.executeScalar(query.ToString(), lParameter);
            if (outsideHomeDate == null)
            {
                return dates;
            }
            dates[1] = (DateTime)outsideHomeDate;
            outsideHomeDBDateTimeStr = formatDBDate((DateTime)outsideHomeDate);

            query = new StringBuilder();
            query.Append("SELECT timestamp from positiondata PARTITION(" + part + ") ");
            query.Append(" where truckId=?");
            query.Append(" and latitude between ? and ?");
            query.Append(" and longitude between ? and ?");
            query.Append(" and timestamp < ?");
            query.Append(" order by timestamp desc limit 1;");

            lParameter.Clear();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("latitude1", (homeLat - distdiff));
            lParameter.Add("latitude2", (homeLat + distdiff));
            lParameter.Add("longitude1", (homeLong - distdiff));
            lParameter.Add("longitude2", (homeLong + distdiff));
            lParameter.Add("outsideHomeDBDateTimeStr", outsideHomeDBDateTimeStr);

            Object homeDate = dbx.executeScalar(query.ToString(), lParameter);
            if (homeDate != null)
            {
                dates[0] = (DateTime)homeDate;
            }
            return dates;
        }
        public DateTime[] getLastTripTimes(String vehicleId, String toDateStr)
        {
            double distdiff = 0.002;
            DateTime[] dates = new DateTime[2];
            //dates[0] = DateTime.UtcNow.AddSeconds(5*60*60 + 30*60 - 24*60*60);
            // Changed 08 April 2009 to handle case where box is just installed.
            // At start of data it is outside home and has no prior home date.
            // Take minvalue as the home date.
