            query.Append(" and longitude not between ? and ?");
            query.Append(" order by timestamp desc limit 1;");
            lParameter.Add("latitude1", (homeLat - distdiff));
            lParameter.Add("latitude2", (homeLat + distdiff));
            lParameter.Add("longitude1", (homeLong - distdiff));
            lParameter.Add("longitude2", (homeLong + distdiff));
            Object outsideHomeDate = dbx.executeScalar(query.ToString(), lParameter);
            if (outsideHomeDate == null)
            {
                return dates;
            }
            dates[1] = (DateTime)outsideHomeDate;
            outsideHomeDBDateTimeStr = formatDBDate((DateTime)outsideHomeDate);

            query = new StringBuilder();
            query.Append("SELECT timestamp from positiondata PARTITION(" + part + ")");
