        public void UpdateVehicleComplianceStatus(string sessionId, string vehicleId, string complianceType, string expireDate, string uploadDate, string status)
        {

            string username = getUserId(sessionId);
            string query = "UPDATE vehicle_driver_compliance_details SET ApprovedDate = ?,ApprovedBy = ?,Remarks = ?,Status = ? " +
                "WHERE VehicleId = ? AND ComplianceType = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("ApprovedDate", formatDBDate(DateTime.Now));
            lParameter.Add("ApprovedBy", username);
            lParameter.Add("Remarks", status);
            lParameter.Add("Status", status);
            lParameter.Add("VehicleId", vehicleId);
            lParameter.Add("ComplianceType", complianceType);
            dbx.executeNonQuery(query, lParameter);

            if (status == "Approved")
            {
                //Update Vehicle Validity Table
                string dt = string.Empty;
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(expireDate, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt = formatDBDate(Convert.ToDateTime(expireDate));
                }
                query = "UPDATE vehicle_validity_data SET " + complianceType + " = ? WHERE VehicleId = ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("ComplianceType", dt);
                lParameter.Add("VehicleId", vehicleId);
                int res = dbx.executeNonQuery(query, lParameter);
                if (res == 0)
                {
                    if (Convert.ToInt16(AddNewVehicleData(vehicleId)) > 0)
                        dbx.executeNonQuery(query, lParameter);
                }
            }
        }
