            lParameter.Add("ApprovedDate", formatDBDate(DateTime.Now));
            lParameter.Add("ApprovedBy", username);
            lParameter.Add("Remarks", status);
            lParameter.Add("Status", status);
            lParameter.Add("DriverId", driverId);
            lParameter.Add("ComplianceType", complianceType);
            dbx.executeNonQuery(query, lParameter);

            if (status == "Approved")
            {
                //Update Driver Validity Table
                string dt = string.Empty;
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(expireDate, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch
                {
                    dt = formatDBDate(Convert.ToDateTime(expireDate));
                }
                if (complianceType == "DDC_Validity")
                {
                    query = "UPDATE driver_validity_data SET " + complianceType + " = ?, DDC_Grade = ? WHERE UserDefinedDriverId = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("ComplianceType", dt);
                    lParameter.Add("DDC_Grade", grade);
                    lParameter.Add("UserDefinedDriverId", driverId);
                }
                else
                {
                    query = "UPDATE driver_validity_data SET " + complianceType + " = ? WHERE UserDefinedDriverId = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("ComplianceType", dt);
                    lParameter.Add("UserDefinedDriverId", driverId);
                }

                int res = dbx.executeNonQuery(query, lParameter);
                if (res == 0)
                {
                    if (Convert.ToInt16(AddNewDriverData(sessionId, driverId)) > 0)
                        dbx.executeNonQuery(query, lParameter);
                }
            }
        }
