        public bool isVehicleHome(String vehicleId, String dateStr)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select HomeLat, HomeLong from vehicles");
            query.Append(" where vehicleID=?;");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            DataSet vehicleHome = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = vehicleHome.Tables[0];
            float homeLat = Convert.ToSingle(table.Rows[0][0]);
            float homeLong = Convert.ToSingle(table.Rows[0][1].ToString());
            string part = GetDateTablePartitions(Convert.ToDateTime(dateStr).AddDays(-10), Convert.ToDateTime(dateStr), partions);

            query = new StringBuilder();
            lParameter.Clear();
            query.Append("select Latitude, Longitude ");
            query.Append("from positiondata PARTITION(" + part + ") ");
            query.Append("where truckId =? ");
            lParameter.Add("vehicleId", vehicleId);
            if (dateStr != null)
            {
                query.Append("and TimeStamp <= ? ");
                lParameter.Add("dateStr", dateStr);
            }
            query.Append("order by TimeStamp DESC limit 1");

            DataSet lastPosition = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table2 = lastPosition.Tables[0];
            if (table2.Rows.Count == 0)
            {
                return false;
            }
            float lastLat = Convert.ToSingle(table2.Rows[0][0]);
            float lastLong = Convert.ToSingle(table2.Rows[0][1]);
            float deltaLat = Math.Abs(lastLat - homeLat);
            float deltaLong = Math.Abs(lastLong - homeLong);
            if (deltaLat < 0.002 && deltaLong < 0.002)
            {
                return true;
            }
            return false;
        }

