        public Object[] getLatLong(String vehicleId, String fromDateStr, String toDateStr)
        {
            DateTime fromdate = Convert.ToDateTime(fromDateStr);
            DateTime todate = Convert.ToDateTime(toDateStr);
            string temp = string.Empty;
            if (todate > fromdate)
            {
                while (fromdate <= todate)
                {
                    temp = temp + partions[fromdate.Month - 1] + ",";
                    fromdate = fromdate.AddMonths(1);

                    if (fromdate > todate && fromdate.Month == todate.Month && (fromdate - todate).TotalDays < DateTime.DaysInMonth(todate.Year, todate.Month) - 1)
                        temp = temp + partions[fromdate.Month - 1] + ",";

                }
                temp = temp.Substring(0, temp.Length - 1);
            }
            else
            {
                temp = "pjan";
            }
            StringBuilder query = new StringBuilder();
            // Add STOP bit also as to calculate distance the lat/longs can be skipped
            query.Append("select Latitude, Longitude, Timestamp, stop,start,speed,FuelLevel,LAC,CI ");
            query.Append("from positiondata PARTITION(" + temp + ") ");
            query.Append("where positiondata.truckId =? ");
            query.Append("and TimeStamp >= ? ");
            query.Append("and TimeStamp <= ? ");
            query.Append("order by TimeStamp");

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("TimeStamp1", fromDateStr);
            lParameter.Add("TimeStamp2", toDateStr);

            DataSet latLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = latLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();
        }

        public Object[] getMapLatLong(String vehicleId, String fromDateStr, String toDateStr)
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            StringBuilder query = new StringBuilder();
            query.Append("select distinct positiondata.Latitude, positiondata.Longitude, Timestamp, Place, District, State ");
            query.Append("from positiondata PARTITION(" + part + ") left join gsmlocations ");
            query.Append("on positiondata.lac = gsmlocations.lac and positiondata.ci = gsmlocations.ci ");
            query.Append("left join anchorlocations on gsmlocations.gsmarea like CONCAT(anchorlocations.place, '\\_\\_%') ");
            query.Append("where positiondata.truckId =? ");
            query.Append("and TimeStamp >= ? ");
            query.Append("and TimeStamp <= ? ");
            query.Append("order by TimeStamp");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("fromDateStr", fromDateStr);
            lParameter.Add("toDateStr", toDateStr);
            DataSet latLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = latLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();
        }
