        public bool getUserDetails(String login, String password, String loginTable)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select Name, password,login from ");
            query.Append(loginTable);
            query.Append(" where login=?");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("login", login);
            DataSet loginInfo = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = loginInfo.Tables[0];
            if (table.Rows.Count == 0)
            {
                //throw new Exception("User name or password is Incorrect");
                return false;
            }
            String name = table.Rows[0][0].ToString();
            String storedPassword = table.Rows[0][1].ToString();
            String str_login = table.Rows[0]["login"].ToString();
            if (str_login.ToLower() != login.ToLower())
            {
                //throw new Exception("User name or password is Incorrect");
                return false;
            }
            query = new StringBuilder();
            query.Append("select SHA1(?)");
            lParameter = new Dictionary<string, object>();
            lParameter.Add("password", password);
            Object encryptedPassword = dbx.executeScalar(query.ToString(), lParameter);
            String encryptedPasswordStr;
            if (encryptedPassword.GetType().ToString() == "System.Byte[]")
            {
                encryptedPasswordStr = System.Text.Encoding.ASCII.GetString((System.Byte[])encryptedPassword);
            }
            else
            {
                encryptedPasswordStr = encryptedPassword.ToString();
            }
            if (storedPassword != encryptedPasswordStr)
            {
                // wrong password
                //throw new Exception("User name or password is Incorrect");
                return false;
            }

            return true;
        }
        public String getSessionId(String login, String password, String loginTable, string IP = "")
        {

            DateTime now = DateTime.Now;
            DataTable Login = CheckLoginDetails(login);
            string q = "";
            if (Login.Rows.Count > 0)
            {
                if (Login.Rows[0]["Name"].ToString().ToLower().Contains("total"))
                {
                    if (Login.Rows[0]["login"].ToString().ToLower().StartsWith("l") || Login.Rows[0]["login"].ToString().ToLower().StartsWith("j"))
                    {
                        q = "select IFNULL(login_attempt_count,0) from login_log where IP='" + IP + "' and Username= '" + login + "' ";
                    }
                    else
                    {
                        q = "select IFNULL(login_attempt_count,0) from login_log where IP='" + IP + "' and login_attempt_time>'" + now.AddMinutes(-5).ToString("yyyy-MM-dd HH:mm:ss") + "'";
                    }
                }
                else
                {
                    q = "select IFNULL(login_attempt_count,0) from login_log where IP='" + IP + "' and login_attempt_time>'" + now.AddMinutes(-5).ToString("yyyy-MM-dd HH:mm:ss") + "'";
                }
            }
            else
            {
                q = "select IFNULL(login_attempt_count,0) from login_log where IP='" + IP + "' and login_attempt_time>'" + now.AddMinutes(-5).ToString("yyyy-MM-dd HH:mm:ss") + "'";
            }
            object res = dbx.executeScalar(q);
            int login_attempt_count = 0;
            if (res != null)
            {
                login_attempt_count = Convert.ToInt32(res);
                if (login_attempt_count > 10)
                {
                    if (Login.Rows.Count > 0)
                    {
                        string globalaccid = GetGlobalAccountId(Login.Rows[0]["AccountID"].ToString());
                        int GlobalAccid = Convert.ToInt32(globalaccid);
                        DataTable blockingdetails = GetBlockingDatails(login, globalaccid);
                        if (Login.Rows[0]["login"].ToString().ToLower().StartsWith("l") || Login.Rows[0]["login"].ToString().ToLower().StartsWith("j"))
                        {
                            if (Login.Rows[0]["Name"].ToString().ToLower().Contains("total"))
                            {
                                if (blockingdetails == null)
                                {
                                    bool str = InsertBlockedUserDetails(GlobalAccid, login, now, "Password Expired", 0);
                                    throw new Exception("Your System is blocked Please contact Administrator");
                                }
                                else throw new Exception("Your System is blocked Please contact Administrator");
                            }
                        }
                        else throw new Exception("Your System is blocked temporarily due to many failed attempts,Please try again after 5min");
                    }
                    else throw new Exception("Your System is blocked temporarily due to many failed attempts,Please try again after 5min");

                }

            }
            q = "Replace into login_log(IP,login_attempt_time,Username,login_attempt_count) values('" + IP + "','" + now.ToString("yyyy-MM-dd HH:mm:ss") + "','" + login + "', ";
            StringBuilder query = new StringBuilder();
            query.Append("select Name, password,login from ");
            query.Append(loginTable);
            query.Append(" where login=?");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("login", login);
            DataSet loginInfo = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = loginInfo.Tables[0];
            if (table.Rows.Count == 0)
            {
                login_attempt_count++;
                dbx.executeNonQuery(q + login_attempt_count + ")");
                throw new Exception("User name or password is Incorrect");
            }
            String name = table.Rows[0][0].ToString();
            String storedPassword = table.Rows[0][1].ToString();
            String str_login = table.Rows[0]["login"].ToString();
            if (str_login.ToLower() != login.ToLower())
            {
                login_attempt_count++;
                dbx.executeNonQuery(q + login_attempt_count + ")");
                throw new Exception("User name or password is Incorrect");
            }
            query = new StringBuilder();
            query.Append("select SHA1(?)");
            lParameter = new Dictionary<string, object>();
            lParameter.Add("password", password);
            Object encryptedPassword = dbx.executeScalar(query.ToString(), lParameter);
            String encryptedPasswordStr;
            if (encryptedPassword.GetType().ToString() == "System.Byte[]")
            {
                encryptedPasswordStr = System.Text.Encoding.ASCII.GetString((System.Byte[])encryptedPassword);
            }
            else
            {
                encryptedPasswordStr = encryptedPassword.ToString();
            }
            if (storedPassword != encryptedPasswordStr)
            {
                // wrong password
                login_attempt_count++;
                dbx.executeNonQuery(q + login_attempt_count + ")");
                throw new Exception("User name or password is Incorrect");
            }
            // Check if there's already a session running for the user.
            // I fyes, just return the session id
            query = new StringBuilder();
            query.Append("select SessionID from sessions");
            query.Append(" where login=?");
            lParameter = new Dictionary<string, object>();
            lParameter.Add("login", login);
            Object sessionId = dbx.executeScalar(query.ToString(), lParameter);
            if (sessionId != null)
            {
                string globalid = GetGlobalAccountIdBySession(sessionId.ToString());
                if (globalid != null)
                {
                    DataTable dtBlock = new DataTable();
                    try
                    {
                        dtBlock = GetBlockingDatails(login, globalid);
                    }
                    catch { }

                    if (dtBlock != null)
                    {
                        if (dtBlock.Rows.Count > 0)
                        {
                            Login = CheckLoginDetails(dtBlock.Rows[0]["loginId"].ToString());
                            if (Login.Rows.Count > 0)
                            {
                                if (Login.Rows[0]["login"].ToString().ToLower().StartsWith("l") || Login.Rows[0]["login"].ToString().ToLower().StartsWith("j"))
                                {
                                    if (Login.Rows[0]["Name"].ToString().ToLower().Contains("total"))
                                    {
                                        DataTable GetPasswordChangedata = GetdataForPasswordChange(dtBlock.Rows[0]["loginId"].ToString());
                                        if (GetPasswordChangedata.Rows.Count > 0)
                                        {
                                            DateTime AddedOn = Convert.ToDateTime(GetPasswordChangedata.Rows[0]["AddedOn"]);
                                            DateTime BlockingDate = Convert.ToDateTime(dtBlock.Rows[0]["Blockeddate"]);
                                            if ((AddedOn > BlockingDate) && (dtBlock.Rows[0]["Reason"].ToString() == "Password Expired"))
                                            {
                                                bool str = UnblockUser(Convert.ToInt32(globalid), login, BlockingDate);
                                            }
                                            else { throw new Exception("Change password"); }
                                        }
                                        else { throw new Exception("Change password"); }
                                    }
                                }
                                throw new Exception(dtBlock.Rows[0]["Reason"].ToString());
                            }
                            else
                                throw new Exception(dtBlock.Rows[0]["Reason"].ToString());
                        }
                    }
                }

                return sessionId.ToString();
            }
            // Create a new session id
            query = new StringBuilder();
            query.Append("select SHA1(?)");
            //
            // There are some versions of database which will return a BINARY type which gets translated to System.Byte[]
            // In order to correct it use GetString()
            //
            lParameter = new Dictionary<string, object>();
            lParameter.Add("sessionid", password + DateTime.Now.Ticks.ToString());
            object newSessionId = dbx.executeScalar(query.ToString(), lParameter);
            String newSessionID;
            if (newSessionId.GetType().ToString() == "System.Byte[]")
            {
                newSessionID = System.Text.Encoding.ASCII.GetString((System.Byte[])newSessionId);
            }
            else
            {
                newSessionID = newSessionId.ToString();
            }
            //
            // String newSessionId = dbx.executeScalar(query.ToString()).ToString(); 
            //
            // Store the session id in the sessions table
            query = new StringBuilder();
            query.Append("insert into sessions (login, SessionID, StartTime, State) Values(");
            query.Append("'" + login + "', ");
            query.Append("'" + newSessionID + "', ");
            query.Append("'" + formatDBDate(DateTime.Now) + "', ");
            query.Append("'0');");
            dbx.executeNonQuery(query.ToString());
            return newSessionID;
        }

