        public Object[] getLocationsInArea(string minLat, string minLong, string maxLat, string maxLong)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select gsmcells.ID, gsmcells.LAC, gsmcells.CI");
            query.Append(", cellpoints.ID, cellpoints.Latitude, cellpoints.Longitude");
            query.Append(", addresses.ID, addresses.Place, addresses.Road, addresses.City, addresses.District, addresses.State ");
            query.Append("from gsmcells, gsmcellpointsmap, cellpoints, cellpointsaddressmap, addresses ");
            query.Append("where gsmcells.id = gsmcellpointsmap.GsmCellId ");
            query.Append("and gsmcellpointsmap.CellPointid = cellpoints.id ");
            query.Append("and cellpoints.id = cellpointsaddressmap.CellPointid ");
            query.Append("and cellpointsaddressmap.Addressid = addresses.id ");
            if (minLat != null && minLat != "")
            {
                query.Append("and " + minLat + " < cellpoints.Latitude ");
            }
            if (maxLat != null && maxLat != "")
            {
                query.Append("and " + maxLat + " > cellpoints.Latitude ");
            }
            if (minLong != null && minLong != "")
            {
                query.Append("and " + minLong + " < cellpoints.Longitude ");
            }
            if (maxLong != null && maxLong != "")
            {
                query.Append("and " + maxLong + " > cellpoints.Longitude ");
            }
            query.Append(";");
            DataSet latLong = dbx.executeQuery(query.ToString());
            DataTable table = latLong.Tables[0];
            ArrayList locations = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                locations.Add(row.ItemArray);
            }
            return locations.ToArray();
        }

