        public void writeCellPointsAddress(string lac, string ci, int radius
                                           , Object[] values, int confidence
                                           , string place, string road, string city, string district, string state)
        {
            string queryId = "SELECT LAST_INSERT_ID()";

            int gsmCellId;
            DateTime date = DateTime.Now;
            String dateStr = formatDBDate(date);
            StringBuilder query = new StringBuilder();
            query.Append("update gsmcells set LastUpdate=\"");
            query.Append(dateStr);
            query.Append("\" ");
            query.Append("where LAC = \"");
            query.Append(lac);
            query.Append("\" and CI = \"");
            query.Append(ci);
            query.Append("\";");
            int ret = dbx.executeNonQuery(query.ToString());

            if (ret <= 0)
            {
                try
                {
                    query = new StringBuilder();
                    query.Append("insert into gsmcells (NetworkId, LastUpdate, LAC, CI, PointsRadius) values(1, \"");
                    query.Append(dateStr);
                    query.Append("\", \"");
                    query.Append(lac);
                    query.Append("\", \"");
                    query.Append(ci);
                    query.Append("\", ");
                    query.Append(radius);
                    query.Append(")");
                    dbx.executeNonQuery(query.ToString());
                }
                catch (Exception)
                {
                }
            }

            query = new StringBuilder();
            query.Append("select ID from gsmcells ");
            query.Append("where LAC = \"");
            query.Append(lac);
            query.Append("\" and CI = \"");
            query.Append(ci);
            query.Append("\";");
            gsmCellId = Convert.ToInt32(dbx.executeScalar(query.ToString()));

            int addressId;

            query = new StringBuilder();
            query.Append("select ID from addresses ");
            query.Append("where Place = \"");
            query.Append(place);
            query.Append("\" and Road = \"");
            query.Append(road);
            query.Append("\" and City = \"");
            query.Append(city);
            query.Append("\" and District = \"");
            query.Append(district);
            query.Append("\" and State = \"");
            query.Append(state);
            query.Append("\";");
            Object addressIdObj = dbx.executeScalar(query.ToString());
            if (addressIdObj != null)
            {
                addressId = Convert.ToInt32(addressIdObj);
            }
            else
            {
                query = new StringBuilder();
                query.Append("insert into addresses (Place, Road, City, District, State) values(");
                query.Append("\"");
                query.Append(place);
                query.Append("\", \"");
                query.Append(road);
                query.Append("\", \"");
                query.Append(city);
                query.Append("\", \"");
                query.Append(district);
                query.Append("\", \"");
                query.Append(state);
                query.Append("\");");
                dbx.executeNonQuery(query.ToString());
                addressIdObj = dbx.executeScalar(queryId);
                addressId = Convert.ToInt32(addressIdObj);
            }



            for (int i = 0; i < values.Length; i++)
            {
                int count = Convert.ToInt32(((Object[])(values[i]))[2]);
                if (count < confidence)
                {
                    continue;
                }
                int valid = 1;
                try
                {
                    query = new StringBuilder();
                    query.Append("insert into cellpoints (Latitude, Longitude, Valid, Count) values(");
                    query.Append(((Object[])values[i])[0] + ", ");
                    query.Append(((Object[])values[i])[1] + ", ");
                    query.Append(valid + ", ");
                    query.Append(((Object[])(values[i]))[2] + ");");
                    dbx.executeNonQuery(query.ToString());
                    int cellPointId = Convert.ToInt32(dbx.executeScalar(queryId));

                    query = new StringBuilder();
                    query.Append("insert into cellpointsaddressmap (CellPointId, AddressId) values(");
                    query.Append(cellPointId);
                    query.Append(", ");
                    query.Append(addressId);
                    query.Append(")");
                    dbx.executeNonQuery(query.ToString());

                    query = new StringBuilder();
                    query.Append("insert into gsmcellpointsmap (GsmCellId, CellPointId) values(");
                    query.Append(gsmCellId);
                    query.Append(", ");
                    query.Append(cellPointId);
                    query.Append(")");
                    dbx.executeNonQuery(query.ToString());
                }
                catch (Exception)
                {
                }
            }
        }
