        public Object[] getLocation(string latitude, string longitude, double deltaLat, double deltaLong, string accountid = "")
        {
            double lat = Convert.ToDouble(latitude);
            double minLatitude = lat - deltaLat;
            double maxLatitude = lat + deltaLat;
            double lon = Convert.ToDouble(longitude);
            double minLongitude = lon - deltaLong;
            double maxLongitude = lon + deltaLong;
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            string RailwayFlag = "";
            if (!String.IsNullOrEmpty(accountid))
            {
                try
                {
                    RailwayFlag = GetlowBatteryRatio(Convert.ToInt32(accountid));
                }
                catch { }
            }
            if (RailwayFlag.ToLower() == "railway")
            {
                query.Append("select addressesRailway.Road, addressesRailway.Place, addressesRailway.City, addressesRailway.District, addressesRailway.State, ");
                query.Append(" addressesRailway.Latitude, addressesRailway.Longitude,addressesRailway.Accountid");
                query.Append(" from addressesRailway ");
                query.Append(" where addressesRailway.Latitude between ? and ?");
                query.Append(" and addressesRailway.Longitude between ? and ?");
            }
            else if (string.IsNullOrEmpty(accountid))//Modified by suvarna on 28/7/2021 to fetch accurate db positiontxt for both geofenced and non-geofenced customers by accountid base
            {
                query.Append("select addressesNew.Road, addressesNew.Place, addressesNew.City, addressesNew.District, addressesNew.State, ");
                query.Append(" addressesNew.Latitude, addressesNew.Longitude,addressesNew.Accountid");
                query.Append(" from addressesNew ");
                query.Append(" where addressesNew.Latitude between ? and ?");
                query.Append(" and addressesNew.Longitude between ? and ?");
            }
            else
            {
                query.Append("select addressesNew.Road, addressesNew.Place, addressesNew.City, addressesNew.District, addressesNew.State, ");
                query.Append(" addressesNew.Latitude, addressesNew.Longitude,addressesNew.Accountid");
                query.Append(" from addressesNew ");
                query.Append(" where Accountid=? and addressesNew.Latitude between ? and ?");
                query.Append(" and addressesNew.Longitude between ? and ?");
                lParameter.Add("AccountId", accountid);
            }

            lParameter.Add("minLatitude", minLatitude);
            lParameter.Add("maxLatitude", maxLatitude);
            lParameter.Add("minLongitude", minLongitude);
            lParameter.Add("maxLongitude", maxLongitude);

            DataSet latLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = latLong.Tables[0];
            ArrayList locations = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                locations.Add(row.ItemArray);
            }
            return locations.ToArray();

        }
