        public Object[] getAnchorLocations(string vehicleID, String fromDateStr, String toDateStr)
        {
            StringBuilder query = new StringBuilder();
            // diff of total 0.2 in lat long is 30 Km distance
            // need that much to account for bypasses and distance from city center etc.
            query.Append("select positiondata.Timestamp, positiondata.Latitude, positiondata.Longitude, ");
            query.Append("anchorlocations.Place, anchorlocations.District, anchorlocations.State, anchorlocations.Latitude, anchorlocations.Longitude ");
            query.Append("from positiondata left join anchorlocations ");
            query.Append("on positiondata.latitude between (anchorlocations.latitude - 0.1) and (anchorlocations.latitude + 0.1) ");
            query.Append("and positiondata.longitude between (anchorlocations.longitude - 0.1) and (anchorlocations.longitude + 0.1) ");
            query.Append("where district is not null ");
            query.Append("and positiondata.truckId =? ");
            query.Append("and TimeStamp >=? ");
            query.Append("and TimeStamp <=? ");
            query.Append("order by TimeStamp");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleID);
            lParameter.Add("fromDateStr", fromDateStr);
            lParameter.Add("toDateStr", toDateStr);
            DataSet latLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = latLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();
        }

