        public String updateSessionId(String sessionId, String password, String login)
        {
            StringBuilder query = new StringBuilder();
            String newSessionID = string.Empty;
            if (String.IsNullOrEmpty(sessionId))
            {

                query.Append("select SHA1('");
                query.Append(password + DateTime.Now.Ticks.ToString());
                query.Append("');");
                //
                // There are some versions of database which will return a BINARY type which gets translated to System.Byte[]
                // In order to correct it use GetString()
                //
                object newSessionId = dbx.executeScalar(query.ToString());

                if (newSessionId.GetType().ToString() == "System.Byte[]")
                {
                    newSessionID = System.Text.Encoding.ASCII.GetString((System.Byte[])newSessionId);
                }
                else
                {
                    newSessionID = newSessionId.ToString();
                }
                //
                // String newSessionId = dbx.executeScalar(query.ToString()).ToString(); 
                //
                // Store the session id in the sessions table
                query.Length = 0;
                query.Append("update sessions set sessionId =");
                query.Append("'" + newSessionID + "'" + " where login = ");
                query.Append("'" + login + "';");
                dbx.executeNonQuery(query.ToString());
                query.Length = 0;
                query.Append("select a.name from accountgroups a, users b where a.accountid = b.accountid and b.login = ");
                query.Append("'" + login + "'" + " order by a.name limit 1;");
                String acctgrpname = string.Empty;
                Object acctgrpnameObj = dbx.executeScalar(query.ToString());
                if (acctgrpnameObj != System.DBNull.Value)
                {
                    acctgrpname = Convert.ToString(acctgrpnameObj);
                    query.Length = 0;
                    query.Append("update adminsessionids set sessionId =");
                    query.Append("'" + newSessionID + "'" + " where name = ");
                    query.Append("'" + acctgrpname + "';");
                    dbx.executeNonQuery(query.ToString());
                }
                return newSessionID;
            }
            else
            {
                query.Length = 0;
                query.Append("update sessions set sessionId =");
                query.Append("'" + sessionId + "'" + " where login = ");
                query.Append("'" + login + "';");

                dbx.executeNonQuery(query.ToString());
                return sessionId;
            }
        }

