        public Object[] getDisconnectedVehicles(String sessionId, int time)
        {
            DataTable table = new DataTable();
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            string lastTS = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() + 60 - time));
            int groupid = getGroupId(sessionId);
            if (!string.IsNullOrEmpty(sessionId))
            {
                query.Append("select v.VehicleId as VehicleId,'' as VehicleInfo,l.timestamp AS serverts from vehiclesgroupsmap v join lastupdtdata l on v.VehicleId=l.truckid");
                query.Append(" where v.GroupId=? and (l.TIMESTAMP<? or l.timestamp is null)");
                //query.Append("select truckid as VehicleId,'' as VehicleInfo,timestamp AS serverts from lastupdtdata ");
                //query.Append("where timestamp < ? and truckid in (select vehicleid from vehiclesgroupsmap where GroupId=?)");
                lParameter.Add("GroupId", groupid);
                lParameter.Add("ServerTS", lastTS);
                table = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            if (table.Rows.Count == 0)
            {
                if (!string.IsNullOrEmpty(sessionId))
                {
                    query.Clear();
                    lParameter.Clear();
                    query.Append("select rp.login from rp_users rp,sessions s ");
                    query.Append("where s.login = rp.login and s.SessionID =? limit 1");
                    lParameter.Add("SessionID", sessionId);

                    if (dbx.executeQuery(query.ToString(), lParameter).Tables[0].Rows.Count > 0)
                    {
                        //Get All Vehicles for Service User
                        query.Clear();
                        lParameter.Clear();
                        //query.Append("select v.VehicleId as VehicleId,'' as VehicleInfo,l.TIMESTAMP AS serverts from vehiclesgroupsmap v ");
                        //query.Append("left join lastupdtdata l on v.VehicleId=l.truckid WHERE (l.TIMESTAMP<? or l.timestamp is NULL) AND VehicleId not like 'INST%';"); 
                        query.Append("select truckid as VehicleId,'' as VehicleInfo,timestamp AS serverts from lastupdtdata ");
                        query.Append("where timestamp < ? and truckid not like 'INST%'");
                        lParameter.Add("ServerTS", lastTS);
                        table = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                    }
                }
            }

            ArrayList vehiclesList = new ArrayList();


            //LP Device have Not Reachable more 25 Hours, 90000 sec;
            query.Clear(); lParameter.Clear();
            //DateTime cmpDate = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() + 60 - 90000);
            DateTime cmpDate = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() + 60 - time);
            query.Append("SELECT VehicleID FROM vehicles WHERE VehicleID IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?) AND TempSense='AT';");
            lParameter.Add("GroupId", groupid);
            DataTable lpDevice = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            if (lpDevice.Rows.Count > 0)
            {
                foreach (DataRow row in table.Rows)
                {
                    string vehicleId = row["VehicleId"].ToString();
                    DataRow[] present = lpDevice.Select("VehicleID='" + vehicleId + "'");
                    if (present.Length == 0)
                        vehiclesList.Add(row.ItemArray);
                    else
                    {
                        string lastupdt = row["serverts"].ToString();
                        if (!string.IsNullOrEmpty(lastupdt))
                        {
                            if (cmpDate > Convert.ToDateTime(lastupdt))
                                vehiclesList.Add(row.ItemArray);
                        }

                    }
                }
            }
            else
            {
                foreach (DataRow row in table.Rows)
                {
                    vehiclesList.Add(row.ItemArray);
                }

            }
            return vehiclesList.ToArray();
        }
