        public Object[] getAccountInfo(String sessionId)
        {
            DataSet account;

            // Try to find account group name
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query.Append("select accountgroups.name, accountgroups.email, accountgroups.accountid,accountgroups.barfeatures,auxinput,accountgroups.maprequest,accountgroups.mapview,accountgroups.refreshrate ");
            query.Append("from sessions, usersgroupsmap, accountgroups ");
            query.Append("where sessions.login = usersgroupsmap.login ");
            query.Append("and usersgroupsmap.groupId = accountgroups.groupId ");
            query.Append("and sessions.SessionID = ?");
            lParameter.Add("SessionID", sessionId);
            account = dbx.executeQuery(query.ToString(), lParameter);
            if (account.Tables[0].Rows.Count > 0)
            {
                return account.Tables[0].Rows[0].ItemArray;
            }
            // If user has no groups, he belongs to the whole account.
            // Find the account name
            query = new StringBuilder();
            query.Append("select accounts.name, accounts.email, accounts.id,accounts.barfeatures,'','GOOGLE','','' ");
            query.Append("from sessions, users, accounts ");
            query.Append("where sessions.login = users.login ");
            query.Append("and users.accountId = accounts.id ");
            query.Append("and sessions.SessionID = ?");
            lParameter.Clear();
            lParameter.Add("SessionID", sessionId);
            account = dbx.executeQuery(query.ToString(), lParameter);
            if (account.Tables[0].Rows.Count > 0)
            {
                return account.Tables[0].Rows[0].ItemArray;
            }
            return null;
        }
