        //Code Added By Zoya to fix the login issue while binding with an S3 image
        public DataSet getNotificationCount(string username)
        {
            string ActionTime = string.Empty;
            ActionTime = formatDBDate(DateTime.UtcNow);
            //string current_partition = GetTransNotifPartitions(DateTime.Now.AddDays(-7), DateTime.Now, transporterNot_partitions);
            string query = "select (select count(*) from transporternotification  t where" +
               "  t.Loginid=" + "'" + username + "'" + " and t.IsNotified=0) as count,n.Subject,n.Info from transporternotification n where " +
               " n.Loginid=" + "'" + username + "' and n.Info NOT LIKE '%s3.amazonaws.com%' order by n.Datetime desc limit 3";

