        public Object[] getDesignatedHalts(String vehicleId, String fromDateStr, String toDateStr)
        {
            StringBuilder query = new StringBuilder();
            query.Append("create temporary table HaltPositions ");
            query.Append("(ID INT UNSIGNED NOT NULL AUTO_INCREMENT,  TruckId VARCHAR(20), TimeStamp DATETIME NOT NULL, Latitude DECIMAL(9,6), Longitude DECIMAL(9,6), Speed DECIMAL(5,2), PRIMARY KEY(ID));");
            dbx.executeNonQuery(query.ToString());
            query = new StringBuilder();
            query.Append("INSERT into HaltPositions(TruckId, TimeStamp, Latitude, Longitude, Speed) SELECT TruckId, TimeStamp, Latitude, Longitude, Speed from positiondata ");
            query.Append("where truckid = \"" + vehicleId + "\" ");
            query.Append("and timestamp >= \"" + fromDateStr + "\" ");
            query.Append("and timestamp <= \"" + toDateStr + "\" ");
            query.Append("order by TimeStamp");
            dbx.executeNonQuery(query.ToString());
            query = new StringBuilder();
            query.Append("select distinct HaltPositions.ID, DATE_FORMAT(HaltPositions.timestamp, '%d %b %y, %r'), 0, 0, HaltPositions.Latitude, HaltPositions.Longitude, HaltPositions.Speed, 0x0, UNIX_TIMESTAMP(HaltPositions.timestamp), 0, 0, 0, 0 from HaltPositions, accounthaltlocations, vehicles ");
            query.Append("where HaltPositions.TruckId = vehicles.VehicleId ");
            query.Append("and vehicles.AccountId = accounthaltlocations.AccountId ");
            query.Append("and HaltPositions.Latitude between accounthaltlocations.Latitude - 0.005 and accounthaltlocations.Latitude + 0.005 ");
            query.Append("and HaltPositions.Longitude between accounthaltlocations.Longitude - 0.005 and accounthaltlocations.Longitude + 0.005 ");
            query.Append("order by HaltPositions.TimeStamp");
            dbx.executeQuery(query.ToString());
            DataSet designatedHalts = dbx.executeQuery(query.ToString());
            DataTable table = designatedHalts.Tables[0];
            ArrayList designatedHaltsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                designatedHaltsList.Add(row.ItemArray);
            }
            query = new StringBuilder();
            query.Append("drop table HaltPositions");
            dbx.executeNonQuery(query.ToString());
            return designatedHaltsList.ToArray();
        }

        /// <summary>
        /// Check if session belongs to a user who is in a group,
        ///	and that group is part of a service.
        ///	if yes, find all vehicles that belong to all 
        ///	groups in that service.
        /// </summary>
        /// <param name="sessionId"></param>
        /// <returns></returns>

        public bool createServiceVehiclesView(String sessionId)
        {

            StringBuilder query;
            query = new StringBuilder();
            query.Append("select sg2.groupid ");
            query.Append("from sessions, users, usersgroupsmap, ");
            query.Append("servicesgroupsmap as sg1, servicesgroupsmap as sg2 ");
            query.Append("where sessionid ='" + sessionId + "' ");
            query.Append("and sessions.login = users.login ");
            query.Append("and users.login = usersgroupsmap.login ");
            query.Append("and usersgroupsmap.groupid = sg1.groupid ");
            query.Append("and sg1.serviceid = sg2.serviceid;");
            DataSet serviceGroups = dbx.executeQuery(query.ToString());

            DataTable groups;
            groups = serviceGroups.Tables[0];
            if (groups.Rows.Count > 0)
            {
                query = new StringBuilder();
                query.Append("create temporary table vehiclesview select vehicles.* ");
                query.Append("from vehicles, vehiclesgroupsmap ");
                query.Append("where vehicles.VehicleId = vehiclesgroupsmap.VehicleId and (");
                foreach (DataRow row in groups.Rows)
                {
                    query.Append("vehiclesgroupsmap.GroupId = " + row.ItemArray[0] + " OR ");
                }
                query.Append(" 0);");
                dbx.executeNonQuery(query.ToString());
                return true;
            }
            else
            {
                // User is not part of any service group.
                // Use vehicles belonging to his group or account.
                createVehiclesView(sessionId);
                return false;
            }
        }

        public bool createVehiclesView(String sessionId)
        {
            bool isServiceUser = false;
            bool customServiceGrp = false;
            StringBuilder query;
            query = new StringBuilder();
            query.Append("drop temporary table if exists vehiclesview;");
            dbx.executeNonQuery(query.ToString());
            // Check for a service user
            // Find all groups that belong to the service
            query = new StringBuilder();
            query.Append("select servicesgroupsmap.GroupId ");
            query.Append("from rp_users, sessions, servicesgroupsmap ");
            query.Append("where sessions.login = rp_users.login ");
            query.Append("and rp_users.serviceid = servicesgroupsmap.serviceid ");
            query.Append("and sessions.SessionID = ?");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("sessionId", sessionId);
            DataSet serviceGroups = dbx.executeQuery(query.ToString(), lParameter);

            DataTable groups;
            groups = serviceGroups.Tables[0];
            if (serviceGroups.Tables[0].Rows.Count > 0)
            {
                isServiceUser = true;
                groups = serviceGroups.Tables[0];
            }
            else if (serviceGroups.Tables[0].Rows.Count == 0)  // check to see if it is a custom service groups where a few vehicles from multiple groups are pulled
            {
                query = new StringBuilder();
                query.Append("select rp_users.serviceId ");
                query.Append("from rp_users, sessions, servicesVehiclesmap ");
                query.Append("where sessions.login = rp_users.login ");
                query.Append("and sessions.SessionID = ?;");
                lParameter = new Dictionary<string, object>();
                lParameter.Add("sessionId", sessionId);
                int serviceid = Convert.ToInt16(dbx.executeScalar(query.ToString(), lParameter));

                if (serviceid != 0)
                {
                    isServiceUser = true;

                    query = new StringBuilder();
                    query.Append("create temporary table vehiclesview select vehicles.* ");
                    query.Append("from vehicles, servicesVehiclesmap ");
                    query.Append("where vehicles.VehicleId = servicesVehiclesmap.VehicleId and (");
                    query.Append("servicesVehiclesmap.serviceId = ?);");
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("serviceid", serviceid);
                    dbx.executeNonQuery(query.ToString(), lParameter);
                    customServiceGrp = true;
                }
                else
                {
                    // Try to find account users groups
                    query = new StringBuilder();
                    query.Append("select usersgroupsmap.GroupId ");
                    query.Append("from users, sessions, usersgroupsmap ");
                    query.Append("where sessions.login = users.login ");
                    query.Append("and users.login = usersgroupsmap.Login ");
                    query.Append("and sessions.SessionID = ?;");
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("sessionId", sessionId);
                    DataSet accountGroups = dbx.executeQuery(query.ToString(), lParameter);
                    groups = accountGroups.Tables[0];
                }
            }

            if (groups.Rows.Count > 0 && !customServiceGrp)
            {
                query = new StringBuilder();
                query.Append("create temporary table vehiclesview select vehicles.* ");
                query.Append("from vehicles, vehiclesgroupsmap ");
                query.Append("where vehicles.VehicleId = vehiclesgroupsmap.VehicleId and (");
                lParameter = new Dictionary<string, object>();
                int count = 0;
                foreach (DataRow row in groups.Rows)
                {
                    query.Append("vehiclesgroupsmap.GroupId = ? OR ");
                    lParameter.Add("GroupId" + count, row.ItemArray[0]);
                    count++;
                }
                query.Append(" 0);");
                dbx.executeNonQuery(query.ToString(), lParameter);
            }
            else if (!customServiceGrp)
            {
                // If user has no groups, he belongs to the whole account.
                // Find all vehicles in the account
                query = new StringBuilder();
                query.Append("create temporary table vehiclesview select vehicles.* ");
                query.Append("from vehicles, accounts, users, sessions ");
                query.Append("where vehicles.AccountID = accounts.ID ");
                query.Append("and accounts.ID = users.AccountID ");
                query.Append("and users.login = sessions.login ");
                query.Append("and sessions.SessionID = ?;");
                lParameter = new Dictionary<string, object>();
                lParameter.Add("sessionId", sessionId);
                dbx.executeNonQuery(query.ToString(), lParameter);
            }
            return isServiceUser;
        }

