        private ArrayList mergeTripTables(DataTable loginTable, DataTable logoutTable, int loginTimeIndex, int logoutTimeIndex)
        {
            ArrayList tripsList = new ArrayList();
            int loginIndex = 0;
            int logoutIndex = 0;
            // Merge the two tables
            while (loginIndex < loginTable.Rows.Count && logoutIndex < logoutTable.Rows.Count)
            {
                Object[] loginItemArray = loginTable.Rows[loginIndex].ItemArray;
                Object[] logoutItemArray = logoutTable.Rows[logoutIndex].ItemArray;
                DateTime loginTime = Convert.ToDateTime(loginItemArray[loginTimeIndex]);
                DateTime logoutTime = Convert.ToDateTime(logoutItemArray[logoutTimeIndex]);
                if (loginTime.CompareTo(logoutTime) <= 0)
                {
                    tripsList.Add(loginItemArray);
                    loginIndex++;
                }
                else
                {
                    tripsList.Add(logoutItemArray);
                    logoutIndex++;
                }
            }
            // Add remaining items when one of the table finishes.
            while (loginIndex < loginTable.Rows.Count)
            {
                Object[] loginItemArray = loginTable.Rows[loginIndex].ItemArray;
                tripsList.Add(loginItemArray);
                loginIndex++;
            }
            while (logoutIndex < logoutTable.Rows.Count)
            {
                Object[] logoutItemArray = logoutTable.Rows[logoutIndex].ItemArray;
                tripsList.Add(logoutItemArray);
                logoutIndex++;
            }
            return tripsList;
        }

        public Object[] getTrips2(String loginFromDateStr, String loginToDateStr, String logoutFromDateStr, String logoutToDateStr)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select rp_trips.tripid, vehiclesview.vehicleid, rp_cabs.type, rp_trips.type, ");
            query.Append("rp_trips.logintime, rp_trips.logouttime, rp_cabs.drivername, rp_cabs.contactnumber, rp_trips.oldstickerno, rp_trips.stickerno, rp_trips.checked ");
            query.Append("from rp_trips, rp_cabs, rp_cabstickermap, vehiclesview ");
            query.Append("where rp_cabs.vehicleid = vehiclesview.vehicleid ");
            query.Append("and rp_trips.stickerno = rp_cabstickermap.stickerno ");
            query.Append("and rp_cabstickermap.vehicleid = rp_cabs.vehicleid ");
            query.Append("and rp_trips.type = 'login' ");
            query.Append("and rp_trips.logintime >= '" + loginFromDateStr + "' ");
            query.Append("and rp_trips.logintime <= '" + loginToDateStr + "' ");
            query.Append("order by logintime, tripid");
            DataSet loginTrips = dbx.executeQuery(query.ToString());
            DataTable loginTable = loginTrips.Tables[0];

            query = new StringBuilder();
            query.Append("select rp_trips.tripid, vehiclesview.vehicleid, rp_cabs.type, rp_trips.type, ");
            query.Append("rp_trips.logintime, rp_trips.logouttime, rp_cabs.drivername, rp_cabs.contactnumber, rp_trips.oldstickerno, rp_trips.stickerno, rp_trips.checked ");
            query.Append("from rp_trips, rp_cabs, rp_cabstickermap, vehiclesview ");
            query.Append("where rp_cabs.vehicleid = vehiclesview.vehicleid ");
            query.Append("and rp_trips.stickerno = rp_cabstickermap.stickerno ");
            query.Append("and rp_cabstickermap.vehicleid = rp_cabs.vehicleid ");
            query.Append("and rp_trips.type = 'logout' ");
            query.Append("and rp_trips.logouttime >= '" + logoutFromDateStr + "' ");
            query.Append("and rp_trips.logouttime <= '" + logoutToDateStr + "' ");
            query.Append("order by logouttime, tripid");
            DataSet logoutTrips = dbx.executeQuery(query.ToString());
            DataTable logoutTable = logoutTrips.Tables[0];

            ArrayList tripsList = mergeTripTables(loginTable, logoutTable, 4, 5);
            return tripsList.ToArray();
        }

