        private bool tmpTripPositionsCreated = false;
        public Object[] getTripHalts2(int tripId, string vehicleId, string fromDateStr, string toDateStr)
        {
            StringBuilder query;
            if (tmpTripPositionsCreated == false)
            {
                query = new StringBuilder();
                query.Append("create temporary table if not exists trippositions ");
                query.Append("(ID INT UNSIGNED NOT NULL AUTO_INCREMENT,  TruckId VARCHAR(20), TimeStamp DATETIME NOT NULL, Latitude DECIMAL(9,6), Longitude DECIMAL(9,6), Speed DECIMAL(5,2), PRIMARY KEY(ID));");
                dbx.executeNonQuery(query.ToString());
                tmpTripPositionsCreated = true;
            }
            query = new StringBuilder();
            query.Append("INSERT into trippositions(TruckId, TimeStamp, Latitude, Longitude, Speed) SELECT TruckId, TimeStamp, Latitude, Longitude, Speed from positiondata ");
            query.Append("where truckid = \"" + vehicleId + "\" ");
            query.Append("and timestamp >= \"" + fromDateStr + "\" ");
            query.Append("and timestamp <= \"" + toDateStr + "\" ");
            query.Append("order by TimeStamp");
            //Console.WriteLine(query.ToString());
            dbx.executeNonQuery(query.ToString());
            query = new StringBuilder();
            query.Append("select distinct trippositions.id, DATE_FORMAT(trippositions.timestamp, '%d %b %y, %r'), 0, rp_tripstops.stopnumber, trippositions.Latitude, trippositions.Longitude, trippositions.Speed, 0x0, UNIX_TIMESTAMP(trippositions.timestamp), 0, 0, 0, 0 from trippositions, rp_tripstops, rp_employeedata ");
            query.Append("where rp_employeedata.number = rp_tripstops.employeenumber ");
            query.Append("and rp_tripstops.TripId = '" + tripId + "' ");
            query.Append("and trippositions.Latitude between rp_employeedata.stopspotlatitude - 0.005 and rp_employeedata.stopspotlatitude + 0.005 ");
            query.Append("and trippositions.Longitude between rp_employeedata.stopspotlongitude - 0.005 and rp_employeedata.stopspotlongitude + 0.005 ");
            query.Append("order by rp_tripstops.stopnumber, trippositions.TimeStamp");
            //Console.WriteLine(query.ToString());
            DataSet tripHalts = dbx.executeQuery(query.ToString());
            DataTable table = tripHalts.Tables[0];
            ArrayList tripHaltsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                tripHaltsList.Add(row.ItemArray);
            }
            query = new StringBuilder();
            query.Append("delete from trippositions");
            dbx.executeNonQuery(query.ToString());
            return tripHaltsList.ToArray();
        }

