            query.Append("and newstickermap.vehicleid = newvehicles.vehicleid ");
            query.Append("and newstickermap.stickerno = rp_trips.stickerno ");
            query.Append("and rp_trips.type = 'login' ");
            query.Append("and rp_trips.logintime >= '" + loginFromDateStr + "' ");
            query.Append("and rp_trips.logintime <= '" + loginToDateStr + "' ");
            query.Append("order by LoginTime, oldstickerno");
            DataSet loginAssignment = dbx.executeQuery(query.ToString());
            DataTable loginTable = loginAssignment.Tables[0];

            query = new StringBuilder();
            query.Append("select rp_trips.tripid, rp_trips.oldstickerno, rp_trips.stickerno, rp_trips.logouttime, rp_trips.type, oldstickermap.vehicleid, newstickermap.vehicleid, rp_trips.lastmodified, rp_trips.autoverified, rp_trips.checked, oldvehicles.vehicleinfo, newvehicles.vehicleinfo ");
            query.Append("from rp_trips, vehicles oldvehicles, vehicles newvehicles, rp_cabstickermap oldstickermap, rp_cabstickermap newstickermap ");
            query.Append("where oldstickermap.stickerno = rp_trips.oldstickerno ");
            query.Append("and oldstickermap.vehicleid = oldvehicles.vehicleid ");
            query.Append("and newstickermap.vehicleid = newvehicles.vehicleid ");
            query.Append("and newstickermap.stickerno = rp_trips.stickerno ");
            query.Append("and rp_trips.type = 'logout' ");
            query.Append("and rp_trips.logouttime >= '" + logoutFromDateStr + "' ");
            query.Append("and rp_trips.logouttime <= '" + logoutToDateStr + "' ");
            query.Append("order by LogoutTime, oldstickerno");
            DataSet logoutAssignment = dbx.executeQuery(query.ToString());
            DataTable logoutTable = logoutAssignment.Tables[0];

            ArrayList assignmentList = mergeTripTables(loginTable, logoutTable, 3, 3);
            return assignmentList.ToArray();
        }

