        public void updateAutoVerifiedTrips(ArrayList autoVerified, ArrayList autoUnverified)
        {
            StringBuilder query = new StringBuilder();
            if (autoVerified.Count > 0)
            {
                query.Append("update rp_trips set autoverified = 1 ");
                query.Append("where ");
                for (int i = 0; i < autoVerified.Count; i++)
                {
                    if (i == 0)
                    {
                        query.Append("tripid = " + autoVerified[i] + " ");
                    }
                    else
                    {
                        query.Append("OR tripid = " + autoVerified[i] + " ");
                    }
                }
                dbx.executeNonQuery(query.ToString());
            }
            if (autoUnverified.Count > 0)
            {
                query = new StringBuilder();
                query.Append("update rp_trips set autoverified = 0 ");
                query.Append("where ");
                for (int i = 0; i < autoUnverified.Count; i++)
                {
                    if (i == 0)
                    {
                        query.Append("tripid = " + autoUnverified[i] + " ");
                    }
                    else
                    {
                        query.Append("OR tripid = " + autoUnverified[i] + " ");
                    }
                }
                dbx.executeNonQuery(query.ToString());
            }
        }

        public string getServerRequest(string truckId)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select RequestNo, RequestMsg from serverrequests where VehicleID=\"");
            query.Append(truckId);
            query.Append("\" order by ID LIMIT 1;");
            DataSet serverRequests = dbx.executeQuery(query.ToString());
            DataTable request = serverRequests.Tables[0];
            if (request.Rows.Count == 0)
            {
                return null;
            }
            int requestNo = (int)(request.Rows[0].ItemArray[0]);
            string requestMsg = (string)(request.Rows[0].ItemArray[1]);
            query = new StringBuilder();
            query.Append("delete from serverrequests where VehicleID=\"");
            query.Append(truckId);
            query.Append("\" order by ID LIMIT 1;");
            if (truckId.Contains("32998"))
                dbx.executeNonQuery(query.ToString());
            return requestNo.ToString() + " " + requestMsg;
        }

