        public void prepareBackupTables(string toDateStr)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select value from backupinfo where name = 'LastBackupDate';");
            string lastBackupDate = Convert.ToString(dbx.executeScalar(query.ToString()));

            query = new StringBuilder();
            query.Append("create table if not exists trackerdata_bak(");
            query.Append("`ID` int(10) unsigned NOT NULL auto_increment, ");
            query.Append("`TruckID` varchar(20) NOT NULL, ");
            query.Append("`FromTimeStamp` datetime NOT NULL, ");
            query.Append("`ToTimeStamp` datetime NOT NULL, ");
            query.Append("`Temperature` decimal(5,2) default NULL, ");
            query.Append("`IdlingInstances` int(11) default NULL, ");
            query.Append("`IdlingDuration` int(11) default NULL, ");
            query.Append("`AccelerationInstances` int(11) default NULL, ");
            query.Append("`DecelerationInstances` int(11) default NULL, ");
            query.Append("`Distance` int(11) default NULL, ");
            query.Append("`noGPSDuration` int(11) default NULL, ");
            query.Append("`curGSMSigStrength` int(11) default NULL, ");
            query.Append("`badSigCount` int(11) default NULL, ");
            query.Append("`gprsDataKB` int(11) default NULL, ");
            query.Append("`numSMS` int(11) default NULL, ");
            query.Append("`numCallIns` int(11) default NULL, ");
            query.Append("`numCallOuts` int(11) default NULL, ");
            query.Append("`AlarmData` bit(16) default NULL, ");
            query.Append("`CallerPhone` varchar(16) default NULL, ");
            query.Append("`altitude` int(11) default NULL, ");
            query.Append("`ServerTS` datetime default NULL, ");
            query.Append("PRIMARY KEY  (`ID`), ");
            query.Append("UNIQUE KEY `TruckID` (`TruckID`,`FromTimeStamp`,`ToTimeStamp`)");
            query.Append(")");
            dbx.executeNonQuery(query.ToString());

            query = new StringBuilder();
            query.Append("create table if not exists `positiondata_bak` (");
            query.Append("`id` int(10) unsigned NOT NULL, ");
            query.Append("`TruckID` varchar(20) NOT NULL, ");
            query.Append("`TimeStamp` datetime NOT NULL, ");
            query.Append("`Start` bit(1) NOT NULL, ");
            query.Append("`Stop` bit(1) NOT NULL, ");
            query.Append("`Latitude` decimal(9,6) default NULL, ");
            query.Append("`Longitude` decimal(9,6) default NULL, ");
            query.Append("`Speed` decimal(5,2) default NULL, ");
            query.Append("`FuelLevel` decimal(5,2) default NULL, ");
            query.Append("`LAC` int(10) unsigned NOT NULL, ");
            query.Append("`CI` int(10) unsigned NOT NULL, ");
            query.Append("UNIQUE KEY `TruckID` (`TruckID`,`TimeStamp`)");
            query.Append(")");
            dbx.executeNonQuery(query.ToString());

            query = new StringBuilder();
            query.Append("delete from trackerdata_bak;");
            dbx.executeNonQuery(query.ToString());

            query = new StringBuilder();
            query.Append("delete from positiondata_bak;");
            dbx.executeNonQuery(query.ToString());

            //string currentBackupDate = formatDBDate(DateTime.UtcNow.AddSeconds(5*60*60 + 30*60));
            string currentBackupDate = toDateStr;
            query = new StringBuilder();
            query.Append("insert into trackerdata_bak select * FROM `trackerdata` WHERE fromtimestamp  > '");
            query.Append(lastBackupDate);
            query.Append("' ");
            query.Append(" and fromtimestamp < '");
            query.Append(currentBackupDate);
            query.Append("'");
            dbx.executeNonQuery(query.ToString());

            query = new StringBuilder();
            query.Append("insert into positiondata_bak select * FROM `positiondata` WHERE timestamp  > '");
            query.Append(lastBackupDate);
            query.Append("' ");
            query.Append(" and timestamp < '");
            query.Append(currentBackupDate);
            query.Append("'");
            dbx.executeNonQuery(query.ToString());

            query = new StringBuilder();
            query.Append("update backupinfo set value=\"");
            query.Append(currentBackupDate);
            query.Append("\" ");
            query.Append("where name = \"LastBackupDate\";");
            dbx.executeNonQuery(query.ToString());
        }

