        public String getReplicationTrackerData(int id)
        {
            String[] dbHeadersTD = {
                "TruckID",
                "FromTimeStamp",
                "ToTimeStamp",
                "Temperature",
                "IdlingInstances",
                "IdlingDuration",
                "AccelerationInstances",
                "DecelerationInstances",
                "Distance",
                "noGPSDuration",
                "curGSMSigStrength",
                "badSigCount",
                "gprsDataKB",
                "numSMS",
                "numCallIns",
                "numCallOuts",
                "AlarmData",
                "CallerPhone",
                "altitude",
                "ServerTS"
            };

            StringBuilder query = new StringBuilder();
            query.Append("select ");
            for (int i = 0; i < dbHeadersTD.Length; i++)
            {
                query.Append(dbHeadersTD[i]);
                if (i != (dbHeadersTD.Length - 1))
                {
                    query.Append(", ");
                }
            }
            query.Append(" from trackerdata where id=\"");
            query.Append(id.ToString());
            query.Append("\";");
            //Console.WriteLine(query.ToString());
            DataSet ds = dbx.executeQuery(query.ToString());
            DataTable table = ds.Tables[0];
            StringBuilder response = new StringBuilder();
            response.Append("insert ignore into trackerdata (");
            for (int i = 0; i < dbHeadersTD.Length; i++)
            {
                response.Append(dbHeadersTD[i]);
                if (i != (dbHeadersTD.Length - 1))
                {
                    response.Append(", ");
                }
            }
            response.Append(") values (");
            for (int i = 0; i < dbHeadersTD.Length; i++)
            {
                response.Append("'" + readValue(table.Rows[0].ItemArray[i], table.Columns[i].DataType.ToString()) + "'");
                if (i != (dbHeadersTD.Length - 1))
                {
                    response.Append(", ");
                }
            }
            response.Append(");");
            return response.ToString();
        }

        public String getReplicationPositionData(int id, int newId)
        {
            String[] dbHeadersPD = {
                "TruckID",
                "TimeStamp",
                "Start",
                "Stop",
                "Latitude",
                "Longitude",
                "Speed",
                "FuelLevel",
                "LAC",
                "CI"
            };
            StringBuilder query = new StringBuilder();
            query.Append("select ");
            for (int i = 0; i < dbHeadersPD.Length; i++)
            {
                query.Append(dbHeadersPD[i]);
                if (i != (dbHeadersPD.Length - 1))
                {
                    query.Append(", ");
                }
            }
            query.Append(" from positiondata where id=\"");
            query.Append(id.ToString());
            query.Append("\";");
            //Console.WriteLine(query.ToString());
            DataSet ds = dbx.executeQuery(query.ToString());
            DataTable table = ds.Tables[0];
            if (table.Rows.Count == 0)
            {
                return ("");
            }
            StringBuilder response = new StringBuilder();
            response.Append("insert ignore into positiondata (id, ");
            for (int i = 0; i < dbHeadersPD.Length; i++)
            {
                response.Append(dbHeadersPD[i]);
                if (i != (dbHeadersPD.Length - 1))
                {
                    response.Append(", ");
                }
            }
            response.Append(") values ");
            for (int numPos = 0; numPos < table.Rows.Count; numPos++)
            {
                response.Append("(");
                if (newId >= 0)
                {
                    response.Append("'" + newId + "', ");
                }
                else
                {
                    response.Append("@uid, ");
                }
                for (int i = 0; i < dbHeadersPD.Length; i++)
                {
                    response.Append("'" + readValue(table.Rows[numPos].ItemArray[i], table.Columns[i].DataType.ToString()) + "'");
                    if (i != (dbHeadersPD.Length - 1))
                    {
                        response.Append(", ");
                    }
                }
                response.Append(")");
                if (numPos != table.Rows.Count - 1)
                {
                    response.Append(",");
                }
            }
            response.Append(";");
            return response.ToString();
        }

