        public String formatDBDate(DateTime date)
        {
            String dateStr = date.ToString("u");
            //Returns string of format 2000-08-17 23:32:32Z
            //Strip off the trailing Z
            dateStr = dateStr.Substring(0, dateStr.LastIndexOf('Z'));
            return dateStr;
        }

        private String readValue(Object value, String type)
        {
            if (type == "System.Byte[]")
            {
                byte[] valArray = (byte[])value;
                StringBuilder retStr = new StringBuilder("0x");
                for (int i = 0; i < valArray.Length; i++)
                {
                    retStr.Append(valArray[i].ToString());

                }
                return retStr.ToString();
            }
            if (type == "System.Boolean")
            {
                bool flag = Convert.ToBoolean(value);
                string ret;
                if (flag)
                {
                    ret = "1";
                }
                else
                {
                    ret = "0";
                }
                return ret;
            }
            if (type == "System.DateTime")
            {
                return formatDBDate(Convert.ToDateTime(value));
            }
            return value.ToString();
        }
        public DataSet getVehicleReportDetails(string vehicleId, string fromdate, string todate, string type)
        {
            if (type != "Cumulative Distance")
            {
                string part = GetDateTablePartitions(Convert.ToDateTime(fromdate), Convert.ToDateTime(todate), partions);
                string query = "select count(*) as count from storevehicleviolations PARTITION(" + part + ") AS s where s.vehicleId='" + vehicleId + "' and "
                            + "s.timestamp>='" + fromdate + "' and s.timestamp<='" + todate + "' and s.`type`='" + type + "'";
                DataSet noOfRows = dbx.executeQuery(query);
                return noOfRows;
            }
            else
            {
                string query = "select d.Distance from dailydistance d where d.vehicleId='" + vehicleId + "' and d.Date='" + fromdate + "'";
                DataSet distance = dbx.executeQuery(query);
                return distance;
            }
        }
