            string currenttime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string lastupdatetime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() - 30 * 60));
            string query = "select truckid,ServerTS from lastaccess where ServerTS <"
                    + "'" + lastupdatetime + "';";
            //Console.WriteLine(query.ToString());
            DataSet vehicles = dbx.executeQuery(query.ToString());
            DataTable table = vehicles.Tables[0];
            //Console.WriteLine(table.Rows.Count.ToString());
            if (table.Rows.Count == 0)
            {
                //Console.WriteLine("lastaccess returned NULL \n");
                return null;
            }
            //Console.WriteLine(" there are trucks not updating \n");
            ArrayList noupdatelist = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                string noupdatetruck = row.ItemArray[0].ToString();
                string lastaccesstime = row.ItemArray[1].ToString();
                query = "select lastMesgtime from noupdates where truckid="
                        + "'" + noupdatetruck + "';";
                //Console.WriteLine(query.ToString());
                object msgtime = dbx.executeScalar(query.ToString());
                //Console.WriteLine(msgtime.GetType());
                if (msgtime != null)
                {
                    if (msgtime == System.DBNull.Value)
                    {
                        //Console.WriteLine("In msgtime = NULL \n");
                        query = "update noupdates set lastMesgtime ="
                                + "'" + currenttime + "'"
                                + "where truckid ="
                                + "'" + noupdatetruck + "';";
                        //Console.WriteLine(query.ToString());
                        dbx.executeNonQuery(query);
                        noupdatelist.Add(row.ItemArray[0]);
                    }
                    else
                    {
                        //Console.WriteLine(" there are entries in the noupdates table \n");
                        if (DateTime.Compare(DateTime.Parse(msgtime.ToString()), DateTime.Parse(lastaccesstime)) < 0)
                        {
                            //Console.WriteLine("In truck again not updating \n");
                            query = "update noupdates set lastMesgtime="
                                        + "'" + currenttime + "'where truckid="
                                        + "'" + noupdatetruck + "';";
                            //Console.WriteLine(query.ToString());
                            dbx.executeNonQuery(query.ToString());
                            noupdatelist.Add(row.ItemArray[0]);
                        }
                        else
                        {
                            System.TimeSpan lastSMSgap = DateTime.Parse(currenttime) - DateTime.Parse(msgtime.ToString());
                            if ((lastSMSgap.Hours) >= 8)
                            {
                                //	Console.WriteLine(" More than 8 hrs since last update \n");
                                query = "update noupdates set lastMesgtime="
                                    + "'" + currenttime + "'where truckid="
                                    + "'" + noupdatetruck + "';";
                                //	Console.WriteLine(query.ToString());
                                dbx.executeNonQuery(query.ToString());
                                noupdatelist.Add(row.ItemArray[0]);
                            }
                        }
                    }
                }
            }
            return noupdatelist.ToArray();
        }


        public Object[] getLastUpdates_byaccounts(string accountname, int defaultDelay)
        {
            //Console.WriteLine("in GetLastAccess \n");
            string currenttime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string lastupdatetime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() - defaultDelay * 60));
            string query = "select c.vehicleid,d.serverTS "
                         + "from accounts a,accountgroups b,vehiclesgroupsmap c,lastaccess d where "
                         + "a.id=b.accountid and "
                         + "b.groupid=c.groupid and "
                         + "d.truckid=c.vehicleid and "
                         + "d.ServerTS<" + "'" + lastupdatetime + "'"
                         + " and d.truckid=c.vehicleid and a.name=" + "'" + accountname + "'"
                         + " group by vehicleid";
            /*string query = "select truckid,ServerTS,EmailId from lastaccess a,accountgroups b,vehiclesgroupsmap c where ServerTS <"
                    + "'" + lastupdatetime + "'" + "and a.truckid=c.vehicleid and c.groupid=b.groupid and b.name=" +
                     "'" + groupname + "'";*/
            //Console.WriteLine(query.ToString());
            DataSet vehicles = dbx.executeQuery(query.ToString());
            DataTable table = vehicles.Tables[0];
            //Console.WriteLine(table.Rows.Count.ToString());
            if (table.Rows.Count == 0)
            {
                return null;
            }
            //Console.WriteLine(" there are trucks not updating \n");
            ArrayList noupdatelist = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                string noupdatetruck = row.ItemArray[0].ToString();
                string lastaccesstime = row.ItemArray[1].ToString();
                query = "select lastmesgtime from noupdates where truckid="
                        + "'" + noupdatetruck + "';";
                //Console.WriteLine(query.ToString());
                object msgtime = dbx.executeScalar(query.ToString());
                //Console.WriteLine(msgtime.GetType());
                if (msgtime != null)
                {
                    if (msgtime == System.DBNull.Value)
                    {
                        //Console.WriteLine("In msgtime = NULL \n");
                        query = "update noupdates set lastmesgtime ="
                                + "'" + currenttime + "'"
                                + "where truckid ="
                                + "'" + noupdatetruck + "';";
                        //Console.WriteLine(query.ToString());
                        dbx.executeNonQuery(query);
                        noupdatelist.Add(row.ItemArray);
                    }
                    else
                    {
                        //Console.WriteLine(" there are entries in the LastMsgTime table \n");
                        if (DateTime.Compare(DateTime.Parse(msgtime.ToString()), DateTime.Parse(lastaccesstime)) < 0)
                        {
                            //
                            // If it comes here then it means that since the lastUpdate time the vehicle had come alive and then 
                            // gone out of sight
                            //
                            //Console.WriteLine("In truck again not updating \n");
                            query = "update noupdates set lastmesgtime="
                                        + "'" + currenttime + "'where truckid="
                                            + "'" + noupdatetruck + "';";
                            //Console.WriteLine(query.ToString());
                            dbx.executeNonQuery(query.ToString());
                            noupdatelist.Add(row.ItemArray);
                        }
                        else
                        {
                            System.TimeSpan lastSMSgap = DateTime.Parse(currenttime) - DateTime.Parse(msgtime.ToString());
                            if ((lastSMSgap.Hours) >= 12)
                            {
                                //Console.WriteLine(" More than 8 hrs since last update \n");
                                query = "update noupdates set lastmesgtime="
                                    + "'" + currenttime + "'" + "where truckid="
                                    + "'" + noupdatetruck + "';";
                                //Console.WriteLine(query.ToString());
                                dbx.executeNonQuery(query.ToString());
                                noupdatelist.Add(row.ItemArray);
                            }
                        }
                    }
                }

            }
            return noupdatelist.ToArray();
        }

        public Object[] getLastAccess_ByGroup(string groupname, string updateinterval = "")
        {
            //Console.WriteLine("in GetLastAccess \n");
            string currenttime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string lastupdatetime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() - 30 * 60));
            string query = "select groupid from accountgroups where name= '" + groupname + "'";
            object grpIdObj = dbx.executeScalar(query);
            if (grpIdObj == null && string.IsNullOrEmpty(updateinterval))
                return (null);
            int grpId = Convert.ToInt32(grpIdObj);
            query = "select noupdateinterval from vehicletripparams where groupid = " + grpId;
            object noUpdateIntervalObj = dbx.executeScalar(query);
            int noUpdateInterval = 0;
            if (noUpdateIntervalObj != null)
            {

                try
                {
                    noUpdateInterval = Convert.ToInt32(noUpdateIntervalObj);   // in secs
                }
                catch
                {

                }
                lastupdatetime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() - noUpdateInterval));
            }
            if (!string.IsNullOrEmpty(updateinterval))
            {
                noUpdateInterval = Convert.ToInt32(updateinterval);
                lastupdatetime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() - noUpdateInterval));
                query = "select c.vehicleid,d.serverTS,b.Name as Account "
                         + "from accounts a,accountgroups b,vehiclesgroupsmap c,lastaccess d where "
                         + "a.id=b.accountid and "
                         + "b.groupid=c.groupid and "
                         + "d.truckid=c.vehicleid and "
                         + "d.ServerTS<" + "'" + lastupdatetime + "' and d.ServerTS>date_sub(" + "'" + lastupdatetime + "', interval 3 hour) "
                         + " and d.truckid=c.vehicleid and b.groupid=" + grpId + " group by vehicleid order by d.ServerTS desc,b.Name  ";
            }
            else
            {
                lastupdatetime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() - noUpdateInterval));
                query = "select c.vehicleid,d.serverTS,b.Name as Account "//bug fixed asNo update cron failing
                             + "from accounts a,accountgroups b,vehiclesgroupsmap c,lastaccess d where "
                             + "a.id=b.accountid and "
                             + "b.groupid=c.groupid and "
                             + "d.truckid=c.vehicleid and "
                         + "d.ServerTS<" + "'" + lastupdatetime + "'"
                             + " and d.truckid=c.vehicleid and b.groupid=" + grpId
                             + " group by vehicleid";
            }
            DataSet vehicles = dbx.executeQuery(query.ToString());
            DataTable table = vehicles.Tables[0];
            //Console.WriteLine(table.Rows.Count.ToString());
            if (table.Rows.Count == 0)
            {
                return null;
            }
            //Console.WriteLine(" there are trucks not updating \n");
            ArrayList noupdatelist = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                noupdatelist.Add(row.ItemArray);
            }
            return noupdatelist.ToArray();
        }

