        public int getUid(string tid, string IMEI = "", string tbl = "")
        {
            string query = String.Empty;
            string tblName = String.Empty;
            var lParameter = new Dictionary<string, object>();
            if (String.IsNullOrEmpty(tbl))
                tblName = "tid2uid";
            else
                tblName = tbl;

            query = "select uid from " + tblName + " where tid= ?";
            lParameter.Add("tid", tid);
            if (!string.IsNullOrWhiteSpace(IMEI))
            {
                query += " and (IMEI=? or IMEI is NULL)";
                lParameter.Add("IMEI", IMEI);
            }

            object uidObj = dbx.executeScalar(query, lParameter);
            if (uidObj == null)
                return (0);
            int uid = Convert.ToInt32(uidObj);
            return (uid);
        }

        public void writeTid(string tid, string IMEI = "", string tbl = "")
        {
            string timestamp = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string tblName = String.Empty;
            if (String.IsNullOrEmpty(tbl))
                tblName = "tid2uid";
            else
                tblName = tbl;
            string query = "insert into " + tblName + "(timestamp,tid) values(" + "'" + timestamp + "'" + ",'" + tid + "')";
            if (!string.IsNullOrWhiteSpace(IMEI))
                query = "insert into " + tblName + "(timestamp,tid,IMEI) values(" + "'" + timestamp + "'" + ",'" + tid + "','" + IMEI + "')";
            dbx.executeNonQuery(query);
        }

