            }
            return fdArray.ToArray();
        }

        public void updateFuelCalibration(string truckId, double mileage, double[] fuelVal, double[] voltVal, int calibsteps)
        {
            string query = "select count(*) from fuelcalibration where truckid = '" + truckId + "'";
            string fuelVoltStr = System.String.Empty;
            string fieldStr = "(truckid,mileage,volt1,fuel1,volt2,fuel2,volt3,fuel3,volt4,fuel4,volt5,fuel5,volt6,fuel6,volt7,fuel7,volt8,fuel8,volt9,fuel9,volt10,fuel10,volt11,fuel11)";
            if (Convert.ToInt32(dbx.executeScalar(query)) != 0)
            {
                // need one extra as there will be calibsteps + 1 pair of values
                for (int i = 1; i < (calibsteps + 2); i++)
                {
                    fuelVoltStr += ",fuel" + i + "=" + fuelVal[i - 1] + ",volt" + i + "=" + voltVal[i - 1];
                }
                query = "update fuelcalibration set mileage = " + mileage + fuelVoltStr +
                        " where truckid = '" + truckId + "'";
                dbx.executeNonQuery(query);
            }
            else
            {
                query = "insert into fuelcalibration" + fieldStr + " values('" + truckId + "'," + mileage;
                for (int i = 1; i < (calibsteps + 2); i++)
                {
                    fuelVoltStr += "," + fuelVal[i - 1] + "," + voltVal[i - 1];
                }
                query = query + fuelVoltStr + ");";
                dbx.executeNonQuery(query);
            }
        }

