        public String updateFuelData(String vehicleId, String PositionId, String DateStr, String Latitude, String Longitude, String PreFuel, String PostFuel, String Distance, String Mileage)
        {
            string query = "select count(*) from fueldata where PositionId = \"" + PositionId + "\"  and Valid != \"0\" ";
            string fieldStr = "(PositionId,Valid,TruckID,TimeStamp,Latitude,Longitude,PreFuel,PostFuel,Distance,Mileage)";


            if (Convert.ToInt32(dbx.executeScalar(query)) != 0)
            {
                query = "update fueldata set Distance ='" + Distance + "',Mileage = '" + Mileage + "' where PositionId = '" + PositionId + "'";
                dbx.executeNonQuery(query);
                return query;
            }
            else
            {
                query = "insert into fueldata " + fieldStr + " values('" + PositionId + "','1','" + vehicleId + "','" + DateStr + "','" + Latitude + "','" + Longitude + "','" + PreFuel + "','" + PostFuel + "','" + Distance + "','" + Mileage + "');";
                dbx.executeNonQuery(query);
                return query;
            }
        }

