        public void updateLastAccessNonIndia(string truckId, int seconds)
        {
            DateTime date = DateTime.UtcNow.AddSeconds(seconds); // based on which TimeZone
            string serverTS = formatDBDate(date);
            StringBuilder query = new StringBuilder();
            query.Append("update lastaccess set ServerTS=\"");
            query.Append(serverTS);
            query.Append("\" where TruckId = \"");
            query.Append(truckId);
            query.Append("\";");
            int ret = dbx.executeNonQuery(query.ToString());
            if (ret > 0)
            {
                return;
            }
            query = new StringBuilder();
            query.Append("insert into lastaccess values(\"");
            query.Append(truckId);
            query.Append("\", \"");
            query.Append(serverTS);
            query.Append("\");");
            dbx.executeNonQuery(query.ToString());
        }

