        public Object[] insertMoveAlertTable(string vehicleId)
        {
            // Get groupid from the vehiclesgroupsmap table 
            // Get another vehicle with the same group no
            // Get the SMsPhone and Email and update it along with current time.
            // So the first vehicle for the group has to be mannually entered.
            DateTime date = DateTime.Now;
            String dateStr = date.ToString("yyyy-MM-dd HH:mm:ss");
            string query = "select groupid from vehiclesgroupsmap where vehicleid = '" + vehicleId + "';";
            Object grpId = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(grpId);
            query = "select SmsPhone,Email from moveAlerts where groupid = " + groupId + " Limit 1";
            DataSet contactInfo = dbx.executeQuery(query);
            DataTable table = contactInfo.Tables[0];
            query = "insert into moveAlerts(vehicleid,SmsPhone,Email,lastSmsMsgTime,groupid) values('" + vehicleId + "','"
                    + table.Rows[0].ItemArray[0] + "','" + table.Rows[0].ItemArray[1] + "','" + dateStr + "',"
                    + groupId + ")";
            dbx.executeNonQuery(query);
            ArrayList contactinfolist = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                contactinfolist.Add(row.ItemArray);
            }
            return contactinfolist.ToArray();
        }

