        public String getOnOffIdlingInstances(String vehicleId, string inclTimings)
        {
            try
            {
                StringBuilder query = new StringBuilder();
                query.Append("select OnOffType from vehicles");
                query.Append(" where vehicleid = ?");
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleId", vehicleId);
                String onofftype = Convert.ToString(dbx.executeScalar(query.ToString(), lParameter));
                string colmn = "hvinp";
                if (onofftype == "DUTY" || onofftype == "DOOR")
                {
                    if (inclTimings == "1")
                        colmn = "CONCAT(gvinp1, '#', timestamp)";
                    else
                        colmn = "gvinp1";
                    query = new StringBuilder();
                    query.Append("select " + colmn + " from lastupdtdata where truckid = ?");
                    Object idlinginstance = dbx.executeScalar(query.ToString(), lParameter);
                    return idlinginstance.ToString();
                }
                else
                    if (!String.IsNullOrEmpty(onofftype))
                {
                    if (inclTimings == "1")
                        colmn = "CONCAT(hvinp, '#', timestamp)";
                    else
                        colmn = "hvinp";
                    query = new StringBuilder();
                    query.Append("select " + colmn + " from lastupdtdata where truckid = ?");
                    return dbx.executeScalar(query.ToString(), lParameter).ToString();

                }
                else
                    return "NC";
            }
            catch { return "NC"; }
        }

        public Object getAuxillaryInputInfo(String sessionId)
        {
            Object auxinputinfo;

            // Try to find account group name

            // If user has no groups, he belongs to the whole account.
            // Find the account name
            StringBuilder query = new StringBuilder();
            query.Append("select ag.auxinput from sessions s, users u, accountgroups ag ");
            query.Append("where s.login = u.login and u.accountId = ag.accountid and s.SessionID = ? LIMIT 1;");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("SessionID", sessionId);
            auxinputinfo = dbx.executeScalar(query.ToString(), lParameter);
            if (auxinputinfo != null)
            {
                if (!auxinputinfo.Equals(System.DBNull.Value))
                {
                    return auxinputinfo;
                }
            }
            return null;
        }
        public Object[] getVehicleTripParams(string sessionId)
        {
            return getVehicleTripParams(sessionId, "");
        }
        public Object[] getVehicleTripParams(string sessionId, string vehicleId)
        {
            String query = "";
            var lParameter = new Dictionary<string, object>();
            int groupId = getGroupId(sessionId);
            DataSet tripSpecs = new DataSet();
            if (string.IsNullOrEmpty(vehicleId))
            {
                query = "select shortRunDuration,shortRestDuration,longRunDuration,curfewStart,curfewEnd,maxSpeed,suddenAccl,harshBreaking, allowedMaxSpeedDur, smsflags, shortRunDuration2, shortRestDuration2,changeDate,ifnull(routedeviation,1000) as routedeviation,DailyRestTime,WeeklyRestTime,WeeklyRunTime,RFIDKey,ExcessiveIdle,ExcessiveRPM,ExcessiveRPMTime,FreewheelingSpeed,FreewheelingRPM_Min,FreewheelingRPM_Max,FreewheelingTime,SeatBeltViolationTime,CrashEvent,CrashEvent_Time,NightDrivingTime,DailyDutyHours,HA_RECORD,HA_ALERT,HA_ALARM,HB_RECORD,HB_ALERT,HB_ALARM,HC_RECORD ,allowedMaxSpeedDur2,ShortRunCount,LongRunCount,NDCount,callFlags,ndDuration,ShiftStart,ShiftEnd " +
                        " from vehicletripparams where groupid = ? ORDER BY changeDate LIMIT 1";
                lParameter.Add("groupid", groupId);
                try
                {
                    tripSpecs = dbx.executeQuery(query.ToString(), lParameter);
                }
                catch
                {
                    query = "select shortRunDuration,shortRestDuration,longRunDuration,curfewStart,curfewEnd,maxSpeed,suddenAccl,harshBreaking, allowedMaxSpeedDur, smsflags, shortRunDuration2, shortRestDuration2,changeDate,ifnull(routedeviation,1000) as routedeviation,DailyRestTime,WeeklyRestTime,WeeklyRunTime,RFIDKey,ExcessiveIdle,ExcessiveRPM,ExcessiveRPMTime,FreewheelingSpeed,FreewheelingRPM_Min,FreewheelingRPM_Max,FreewheelingTime,SeatBeltViolationTime,CrashEvent,CrashEvent_Time,NightDrivingTime,DailyDutyHours,HA_RECORD,HA_ALERT,HA_ALARM,HB_RECORD,HB_ALERT,HB_ALARM,HC_RECORD ,allowedMaxSpeedDur2,ShortRunCount,LongRunCount,NDCount,callFlags,ndDuration,ShiftStart,ShiftEnd " +
                           " from vehicletripparams where groupid = ? ORDER BY changeDate LIMIT 1";
                    tripSpecs = dbx.executeQuery(query.ToString(), lParameter);
                }
                if (tripSpecs.Tables[0].Rows.Count == 0)
                {
                    int accountid = GetAccountIdByGroupId(groupId);
                    query = "select shortRunDuration,shortRestDuration,longRunDuration,curfewStart,curfewEnd,maxSpeed,suddenAccl,harshBreaking, allowedMaxSpeedDur, smsflags, shortRunDuration2, shortRestDuration2,changeDate,ifnull(routedeviation,1000) as routedeviation,DailyRestTime,WeeklyRestTime,WeeklyRunTime,RFIDKey,ExcessiveIdle,ExcessiveRPM,ExcessiveRPMTime,FreewheelingSpeed,FreewheelingRPM_Min,FreewheelingRPM_Max,FreewheelingTime,SeatBeltViolationTime,CrashEvent,CrashEvent_Time,NightDrivingTime,DailyDutyHours,HA_RECORD,HA_ALERT,HA_ALARM,HB_RECORD,HB_ALERT,HB_ALARM,HC_RECORD ,allowedMaxSpeedDur2,ShortRunCount,LongRunCount,NDCount,callFlags,ndDuration,ShiftStart,ShiftEnd " +
                           " from vehicletripparams where groupid in (select groupid from accountgroups where accountid=?) ORDER BY changeDate LIMIT 1";
                    lParameter.Clear();
                    lParameter.Add("accountid", accountid);
                    tripSpecs = dbx.executeQuery(query.ToString(), lParameter);
                }
            }
            else
            {
                try
                {
                    query = "select shortRunDuration,shortRestDuration,longRunDuration,curfewStart,curfewEnd,maxSpeed,suddenAccl,harshBreaking, allowedMaxSpeedDur, smsflags, shortRunDuration2, shortRestDuration2,changeDate,ifnull(routedeviation,1000) as routedeviation,DailyRestTime,WeeklyRestTime,WeeklyRunTime,RFIDKey,ExcessiveIdle,ExcessiveRPM,ExcessiveRPMTime,FreewheelingSpeed,FreewheelingRPM_Min,FreewheelingRPM_Max,FreewheelingTime,SeatBeltViolationTime,CrashEvent,CrashEvent_Time,NightDrivingTime,DailyDutyHours,HA_RECORD,HA_ALERT,HA_ALARM,HB_RECORD,HB_ALERT,HB_ALARM,HC_RECORD " +
                            " from vehicletripparams_vehwise where VehicleId = ? and (ExpiryDate>='" + formatDBDate(DateTime.Today) + "' or ExpiryDate is NULL) ORDER BY changeDate LIMIT 1";
                    lParameter.Clear();
                    lParameter.Add("VehicleId", vehicleId);
                    lParameter.Add("ExpiryDate", formatDBDate(DateTime.Today));

                    tripSpecs = dbx.executeQuery(query.ToString(), lParameter);
                    if (tripSpecs.Tables[0].Rows.Count == 0 && !string.IsNullOrEmpty(sessionId))
                    {
                        //Removing Vehicle Id and calling back.
                        return getVehicleTripParams(sessionId);
                    }
                    else if (tripSpecs.Tables[0].Rows.Count == 0 && string.IsNullOrEmpty(sessionId))
                    {
                        query = "select shortRunDuration,shortRestDuration,longRunDuration,curfewStart,curfewEnd,maxSpeed,suddenAccl,harshBreaking, allowedMaxSpeedDur, smsflags, shortRunDuration2, shortRestDuration2,changeDate,ifnull(routedeviation,1000) as routedeviation,DailyRestTime,WeeklyRestTime,WeeklyRunTime,RFIDKey,ExcessiveIdle,ExcessiveRPM,ExcessiveRPMTime,FreewheelingSpeed,FreewheelingRPM_Min,FreewheelingRPM_Max,FreewheelingTime,SeatBeltViolationTime,CrashEvent,CrashEvent_Time,NightDrivingTime,DailyDutyHours,HA_RECORD,HA_ALERT,HA_ALARM,HB_RECORD,HB_ALERT,HB_ALARM,HC_RECORD ,allowedMaxSpeedDur2,ShortRunCount,LongRunCount,NDCount,callFlags,ndDuration,ShiftStart,ShiftEnd " +
                            " from vehicletripparams where groupid in (select groupid from vehiclesgroupsmap where VehicleId = ?) ORDER BY changeDate LIMIT 1";
                        lParameter.Clear();
                        lParameter.Add("VehicleId", vehicleId);
                        tripSpecs = dbx.executeQuery(query.ToString(), lParameter);
                    }
                }
                catch
                {
                    //Removing Vehicle Id and calling back.
                    return getVehicleTripParams(sessionId);
                }
            }
            DataTable table = tripSpecs.Tables[0];
            ArrayList tripSpecList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                tripSpecList.Add(row.ItemArray);
            }
            return tripSpecList.ToArray();
        }    
        
        public Object[] getVehicleSnapShot(string vehicleId, string DriverId)
        {
            string query = "select shortRunTime,shortStopTime,cummRuntime,longStopTime,longRestFlag,shortStopFlag,lastUpdateTime,nightRunDuration,DutyTime,shortST from" +
                           " vehiclessnapshot where vehicleid =?";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);

            if (!string.IsNullOrEmpty(DriverId))
            {
                query += " and DriverId=?";
                lParameter.Add("DriverId", DriverId);
            }
            DataSet snapshot = dbx.executeQuery(query, lParameter);
            DataTable table = snapshot.Tables[0];
            if (table.Rows.Count == 0)
            {
                query = "insert ignore into vehiclessnapshot(vehicleId,DriverId) values(?,?)";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleId", vehicleId);
                lParameter.Add("DriverId", DriverId);
                dbx.executeNonQuery(query, lParameter);
            }
            ArrayList snapShotList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                snapShotList.Add(row.ItemArray);
            }
            return snapShotList.ToArray();
        }

        public void updateVehicleSnapShot(string vehicleId, int shortRunTime, int shortStoptime, int cummRunTime, int nightRunDuration, int longStopTime, Boolean longStopFlag, Boolean shortStopFlag, DateTime lastUpdate, int dutyTime, int shortST, string DriverId = "")
        {// lastUpdate always contains the lastTime the vehicle sent data to the server

            string lastUpdateStr = String.Empty;
            string query = String.Empty;
            if (lastUpdate != DateTime.MinValue)
            {
                lastUpdateStr = formatDBDate(lastUpdate);
                query = "update vehiclessnapshot set shortRunTime=" + shortRunTime + ",shortStopTime=" + shortStoptime + ",cummRunTime=" + cummRunTime +
                    ",nightRunDuration=" + nightRunDuration + ",longStopTime=" + longStopTime + ",longRestFlag=" + longStopFlag +
                    ",lastUpdateTime='" + lastUpdateStr + "'" + ",Dutytime=" + dutyTime + ",shortST=" + shortST + " where vehicleid = '" + vehicleId + "'";
            }
            else
                query = "update vehiclessnapshot set shortRunTime=" + shortRunTime + ",shortStopTime=" + shortStoptime + ",cummRunTime=" + cummRunTime +
                   ",nightRunDuration=" + nightRunDuration + ",longStopTime=" + longStopTime + ",longRestFlag=" + longStopFlag + ",Dutytime=" + dutyTime + ",shortST=" + shortST +
                   " where vehicleid = '" + vehicleId + "'";
            if (!string.IsNullOrEmpty(DriverId))
            {
                query += " and DriverId='" + DriverId + "'";
            }
            dbx.executeNonQuery(query);
        }

