        public void storeVehicleViolations(String vehicleId, String actDriver, String type, String when, double duration, String remarks, String location, string latitude = "NULL", string longitude = "NULL", int numSample = 0, float maxSampleVal = 0.0F)
        {
            int overlapCount = 0;
            if (type == "JRM OVERSPEEDING" && location.ToLower().Contains("jrm_rhm"))
            {
                overlapCount = CheckOverlapJRMOverspeeding(vehicleId, when, duration);
            }
            if (overlapCount == 0)
            {
                //string query = "insert ignore into storevehicleviolations(vehicleid,type,timestamp,duration,remarks,location,drivername,latitude,longitude,samples,maxsamplesval) values(?,?,?,?,?,?,?,?,?,?,?)";
                //string query = "INSERT INTO storevehicleviolations(`vehicleId`, `type`, `timestamp`, `duration`, `remarks`, `Location`, `driverName`, `latitude`, `longitude`,samples,maxsamplesval) " +
                //" SELECT * FROM(select " + vehicleId + "," + type + "," + when + "," + duration + "," + remarks + "," + location + "," + actDriver + "," + latitude + "," + longitude + "," + numSample + "," + maxSampleVal + ") AS tmp " +
                //" WHERE NOT EXISTS ( SELECT vehicleId FROM storevehicleviolations WHERE vehicleId =" + vehicleId + " )";
                string query = "INSERT INTO `storevehicleviolations`(`vehicleId`, `type`, `timestamp`, `duration`, `remarks`, `Location`, `driverName`, `latitude`, `longitude`,samples,maxsamplesval) " +
                              " (SELECT '" + vehicleId + "','" + type + "','" + when + "','" + duration + "','" + remarks + "','" + location + "','" + actDriver + "','" + latitude + "','" + longitude + "','" + numSample + "','" + maxSampleVal + "' FROM `storevehicleviolations`" +
                              " where vehicleId='" + vehicleId + "' and timestamp='" + when + "' and type='" + type + "' and remarks='" + remarks + "' and duration='"
                              + duration + "' HAVING COUNT(vehicleId)= 0)";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", vehicleId);
                lParameter.Add("type", type);
                lParameter.Add("timestamp1", when);
                lParameter.Add("duration", duration);
                lParameter.Add("remarks", remarks);
                lParameter.Add("location", location);
                if (string.IsNullOrEmpty(actDriver))
                {
                    actDriver = getdrivername(vehicleId, when).Split(',')[0];
                }
                lParameter.Add("drivername", actDriver);
                lParameter.Add("latitude", latitude);
                lParameter.Add("longitude", longitude);
                lParameter.Add("samples", numSample);
                lParameter.Add("maxsamplesval", maxSampleVal);
                dbx.executeNonQuery(query, lParameter);
            }
        } 
