        public int CheckOverlapJRMOverspeeding(string vehicleID, string starttime, double duration)
        {
            try
            {
                string query = "select count(*) from (select s.timestamp starttime,date_add(s.timestamp,interval (s.duration-1) second) endtime from storevehicleviolations s"
                    + " where s.vehicleId=? and s.`type`='JRM OVERSPEEDING' and s.timestamp>?) res where res.starttime<=? and res.endtime>=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", vehicleID);
                lParameter.Add("timestamp", formatDBDate(Convert.ToDateTime(starttime).AddHours(-1)));
                lParameter.Add("starttime", formatDBDate(Convert.ToDateTime(starttime)));
                lParameter.Add("endtime", formatDBDate(Convert.ToDateTime(starttime).AddSeconds(duration - 1)));
                return Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString());
            }
            catch (Exception ex)
            {
                STL_RecordErrorMessage("Xmldb_CheckOverlapJRMOverspeeding_" + DateTime.Now + "_" + ex.ToString());
                return 0;
            }
        }

        public void RecordViolationEvent1SecData(String vehicleId, String when, String type, String speedstr, bool valid_violation)
        {
            try
            {
                string query = "insert into tbl_event_secs_data(vehicleid,timestamp,type,speedstr,valid_violation) values(?,?,?,?,?)";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", vehicleId);
