        public Object[] getVehicleViolationsForDashBoard(String vehicleId, String fromDate, String toDate, String sessionId, string viotype = "")
        {
            string query = String.Empty;
            string temp = GetDateTablePartitions(Convert.ToDateTime(fromDate), Convert.ToDateTime(toDate), partions);
            var lParameter = new Dictionary<string, object>();
            if (String.Compare(vehicleId, "ALL") == 0)
            {
                string groupid = getGroupId(sessionId).ToString();
                DataTable dtgrpveh = GetVehiclesByGroupId(groupid).Tables[0];
                string vehls = string.Empty;
                if (dtgrpveh.Rows.Count == 0)
                {
                    DataTable dt = GetVehiclesBySessionId(sessionId).Tables[0];
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        vehls += "'" + dt.Rows[i]["VehicleId"].ToString() + "',";
                    }
                    vehls += "''";
                }
                query = "select distinct s1.vehicleid as 'vehicleid',s1.type,s1.timestamp,s1.duration,s1.location,remarks,s1.drivername from storevehicleviolations PARTITION(" + temp + ") AS s1 " +
                    " where s1.timestamp between '" + fromDate + "' and '" + toDate + "' ";
                if (string.IsNullOrEmpty(vehls))
                    query += "and s1.vehicleid in (select VehicleId from vehiclesgroupsmap where GroupId='" + groupid + "')  ";
                else
                    query += "and s1.vehicleid in (" + vehls + ")  ";

                if (string.IsNullOrEmpty(viotype))
                    query += "and s1.type<>'NORMAL' and s1.type<>'HARSH BRAKING'";
                else
                    query += "and s1.type in (" + viotype + ")";

            }
            else
            {
                query = "select  distinct vehicleid,type,timestamp,duration,location,remarks,drivername from storevehicleviolations PARTITION(" + temp + ") where timestamp between '"
                    + fromDate + "' and '" + toDate + "' and vehicleid =? and s1.type<>'NORMAL' and s1.type<>'HARSH BRAKING'";
                lParameter.Add("vehicleid", vehicleId);
            }
            DataSet violations = dbx.executeQuery(query, lParameter);

            violations.Tables[0].DefaultView.Sort = "vehicleid asc";
            DataTable table = violations.Tables[0].DefaultView.ToTable();
            ArrayList violationsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                violationsList.Add(row.ItemArray);
            }
            return violationsList.ToArray();
        }

