        public Object[] checkPlantGeoLocations(double latitude, double longitude, string accountid = "0")
        {
            StringBuilder query = new StringBuilder();
            // should be within 500 mts diameter to say it is inside the plant

            query.Append("select locstr,type,customerid FROM plantgeolocations ");
            query.Append("where (minlatitude <= " + latitude + " ");
            query.Append("AND minLongitude <= " + longitude + " ");
            query.Append("AND maxLatitude >= " + latitude + " ");
            query.Append("AND maxLongitude >= " + longitude + ")");
            if (accountid != "0")
                query.Append(" AND accountid='" + accountid + "'");
            DataSet plantDetails = dbx.executeQuery(query.ToString());
            DataTable table = plantDetails.Tables[0];
            ArrayList plantDetailsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                plantDetailsList.Add(row.ItemArray);
            }
            return plantDetailsList.ToArray();
        }
