        public int updateVehicleInPlant(String vehicleId, String locationStr, int plantType, DateTime vehTs, string configtimeZoneStr = "")
        {	// Here we insert an entry in vehicleInPlant if the previous entry is more than one day old
            // The reason is that the vehicle will be there for hours 
            // Also old data keeps coming to the  server which has to be discarded when already an entry for that vehicle and locationStr
            // is already present in the vehicleinplant table
            //DateTime minVehTs = vehTs.AddMinutes(-24*60);  // changed from 24 to 72
            String maxTs = formatDBDate(vehTs);
            int timeZone = GetTimeZoneDiff();
            string timeZoneStr = configtimeZoneStr;
            if (timeZoneStr != "")
            {
                timeZone = Convert.ToInt32(timeZoneStr);
            }
            DateTime indianTime = DateTime.UtcNow;
            indianTime = indianTime.AddSeconds(timeZone);
            string oneminprevioustime = "";
            oneminprevioustime = formatDBDate(indianTime.AddMinutes(-10));
            string query = "";
            //GA05 P 9125 of impact technology was updating olderdata like 7am,10am,10.15am,8am,10.20am,9am...
            ///so srini decide to take inputdatetime>=system date-2min
            //string query = "select count(*) from dual where '" + maxTs + "'  <='" + oneminprevioustime + "'";
            //string query = "select count(*) from vehicleinplant where vehicleid = '" + vehicleId + "' and locationstr = '" + locationStr +
            //                "' and intimestamp > '" + maxTs + "'";
            //Object countObj = dbx.executeScalar(query);
            int numEnt = 0;// Convert.ToInt32(countObj);
            if (vehTs <= indianTime.AddMinutes(-10))
            {// Return for late arrival
                query = "insert into VehicleinplantRejectedData values('" + vehicleId + "','" + maxTs + "','" + oneminprevioustime + "','" + formatDBDate(indianTime) + "','" + "Late arrival" + "','" + locationStr + "');";
                dbx.executeNonQuery(query);
                return 1;

            }
            //enter new record only if previous point outtime is done.
            query = "select count(*) from vehicleinplant where vehicleId = '" + vehicleId + "'" +
                    " and  outtimestamp is NULL and locationstr = '" + locationStr + "'";
            Object countObj = dbx.executeScalar(query);
            numEnt = Convert.ToInt32(countObj);
            if (numEnt == 0)
            {
                query = "insert into vehicleinplant(vehicleid,locationstr,reportstatus,planttype,intimestamp) values('" + vehicleId +
                    "','" + locationStr + "',0," + plantType + ",'" + maxTs + "')";
                dbx.executeNonQuery(query);
                //1)assume multiple trip with same sorce,destination can never be captured for a perticular vehicle before compleating previous trip.
                //at time of destination capturing it is needed to check for in .
                //because destination of one trip can be source of other trip.
                //so both the query needed to execute for each point came.
                //2)source geofence can be destination for other grno
                //so source needed to check if null ot not 
                //and destination is needed to check if sorurceintime is not null and destination time is null.
                query = "update grnoassign set geosourcein='" + maxTs + "' where " + "truckid='" + vehicleId +
                    "' and geofencesource='" + locationStr + "' and geosourcein is NULL";
                dbx.executeNonQuery(query);

                query = "update grnoassign set geodestinationin ='" + maxTs + "' where " + "truckid='" + vehicleId +
                    "' and geofencedestination='" + locationStr + "' and geodestinationin is NULL and geosourcein is NOT NULL";
                dbx.executeNonQuery(query);

            }
            return numEnt;
        }
