        public void updateVehicleInPlantOuttime(String vehicleId, int plantType, DateTime vehTs)
        {	//only update thoes records of that vehicle for which outtimedone is null
            //and if multiple records fond then skip updation for next batch process
            string timestamp = "";
            try
            {
                string query = "select max(intimestamp)  from vehicleinplant where vehicleid='" + vehicleId + "'";

                object time = dbx.executeScalar(query).ToString();

                if (time != null)
                {
                    timestamp = formatDBDate(Convert.ToDateTime(time.ToString()));
                    //query=  "select veh.locationstr from  vehicleinplant veh where 1=(select count(1) from vehicleinplant where " +
                    //              "vehicleid = '" + vehicleId + "' and outtimestamp is null and intimestamp<'" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "') and veh.vehicleid='" + vehicleId + "' and " +
                    //              "outtimestamp is null ";

                    query = "select veh.locationstr from  vehicleinplant veh where intimestamp='" + timestamp + "' and vehicleid = '" + vehicleId + "' and outtimestamp is null ";
                    DataSet geofenceinout = dbx.executeQuery(query);
                    DataTable table = geofenceinout.Tables[0];
                    DataRow[] values = new DataRow[table.Rows.Count];
                    table.Rows.CopyTo(values, 0);
                    string geofencename = string.Empty;
                    if (values.Length > 0)
                    {
                        geofencename = values[0].ItemArray[0].ToString();
                        query = "update vehicleinplant set outtimestamp='" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "',outtimedone=1 " + "where vehicleid = '" + vehicleId + "' and " +
                                       "  outtimestamp is NULL and locationstr='" + geofencename + "'" + " and intimestamp<'" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "'";
                        dbx.executeNonQuery(query);
                        query = "update grnoassign set geosourceout='" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "' where " + "truckid='" + vehicleId +
                            "' and geofencesource='" + geofencename + "' and geosourceout is NULL and geosourcein is not null";
                        dbx.executeNonQuery(query);
                        query = "update grnoassign set geodestinationeout='" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "' where " + "truckid='" + vehicleId +
                           "' and geofencedestination='" + geofencename + "' and geodestinationout is NULL and geodestinationin is not null";
                        dbx.executeNonQuery(query);
                    }
                }
            }
            catch (Exception e)
            {

            }
        }
