        public void writeUnloadedQnty(String vehicleid, DateTime when, String locationStr, float netQty, String emailStr, String photo = "", string CustomerCode = "", string Plant = "")
        {
            String whenStr = formatDBDate(when);
            String[] dateOnly = whenStr.Split(' ');
            // String query = "insert into unloadqtydetails(vehicleid,timestamp,locStr,netqty,emailid,photo,ReturningTo) values('" + vehicleid + "','" + whenStr + "','" + locationStr + "'," + netQty + ",'" + emailStr + "','" + photo + "','" + Plant + "')";
            String query = "insert into unloadqtydetails(vehicleid,timestamp,locStr,netqty,emailid,photo,ReturningTo) values(?,?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleid", vehicleid);
            lParameter.Add("timestamp", whenStr);
            lParameter.Add("locStr", locationStr);
            lParameter.Add("netqty", netQty);
            lParameter.Add("emailid", emailStr);
            lParameter.Add("photo", photo);
            lParameter.Add("ReturningTo", Plant);

            var a = dbx.executeNonQuery(query, lParameter);
            if (netQty != -1)
            {	// it is possible that the same vehicle goes to 3 different customers on the same trip and unload so we need to extract customer name from plantgeolocations
                // and use it as a qualifier to update the dcinvoicedetails talbe
                query = "select customername from plantgeolocations where locstr = ?";

                //query = "select customername from plantgeolocations where locstr = '" + locationStr + "'";
                lParameter.Clear();
                lParameter.Add("locstr", locationStr);
                Object custNameObj = dbx.executeScalar(query, lParameter);
                string custName = (string)custNameObj;
                query = "update dcinvoicedetails set unloadqty = ? where vehicleid = ? and customerName = ? and date < ? and unloadqty = 0.0 and invoiceno is NULL";
                lParameter.Clear();
                lParameter.Add("unloadqty", netQty);
                lParameter.Add("vehicleid", vehicleid);
                lParameter.Add("customerName", custName);
                lParameter.Add("date", dateOnly[0]);
                // query = "update dcinvoicedetails set unloadqty = " + netQty + " where vehicleid = '" + vehicleid + "' and customerName = '" + custName + "' and date < '" + dateOnly[0] + "' and unloadqty = 0.0 and invoiceno is NULL";
                int rowsAffected = dbx.executeNonQuery(query, lParameter);
                if (rowsAffected == 0)
                {   // i.e there is no entry DC entry for the unload then insert the unload quantity with default DC values
                    // query = "insert into dcinvoicedetails(vehicleid,customername,unloadqty) values('" + vehicleid + "','" + custName + "'," + netQty + ")";
                    query = "insert into dcinvoicedetails(vehicleid,customername,unloadqty) values(?,?,?)";
                    lParameter.Clear();
                    lParameter.Add("vehicleid", vehicleid);
                    lParameter.Add("customerName", custName);
                    lParameter.Add("unloadqty", netQty);
                    dbx.executeNonQuery(query, lParameter);
                }
            }
        }

