        public DataTable GetUnloadQtyDetails(String VehicleId, String fromDateStr, String toDateStr)
        {
            String query = "select vehicleid,timestamp,locStr,netqty,emailid,photo from unloadqtydetails where timestamp > ? and timestamp <= ?";
            var lParameter = new Dictionary<string, object>();
            if (VehicleId.Contains("'"))
            {
                query += " and vehicleid in (";
                String[] vehicles = VehicleId.Replace("'", "").Split(',');
                for (int i = 0; i < vehicles.Length; i++)
                {   // Bit naive 
                    if (i == 0)
                        query += ("?");
                    else
                        query += (", ?");
                }
                query += (")");
                lParameter.Add("fromdate", fromDateStr);
                lParameter.Add("todate", toDateStr);
                for (int i = 0; i < vehicles.Length; i++)
                {   // Bit naive 
                    lParameter.Add("vehicle" + i, vehicles[i]);
                }
            }
            else
            {
                query += " and vehicleid=?";
                lParameter.Add("fromdate", fromDateStr);
                lParameter.Add("todate", toDateStr);
                lParameter.Add("vehicle", VehicleId);
            }

            //  

            DataSet unloadDS = dbx.executeQuery(query.ToString(), lParameter);
            return unloadDS.Tables[0];
        }

