        public Object[] getAclDclLatLongInStoreVehicleViolation(String vehicleId, String fromDateStr, String toDateStr)
        {
            StringBuilder query = new StringBuilder();
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            query.Append("select s.type,s.timestamp,s.duration,s.remarks,s.Location ");
            query.Append("from storevehicleviolations PARTITION(" + part + ") AS s ");
            query.Append("where s.vehicleId =? and (s.type='HARSH BRAKING' or s.type='HIGH ACCELERATION') ");
            query.Append("and s.timestamp >=? ");
            query.Append("and s.timestamp <=? ");
            query.Append("order by s.timestamp");

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("fromDateStr", fromDateStr);
            lParameter.Add("toDateStr", toDateStr);
            DataSet aclDclLatLong = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = aclDclLatLong.Tables[0];
            ArrayList aclDclList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                aclDclList.Add(row.ItemArray);
            }
            return aclDclList.ToArray();
        }
        //
        // Checks whether the vehicle is "allowed" or "not allowed" in the regions described in the table
        //
        public Object[] allowedInGeoRegion(String vehicleid, int id, float latitude, float longitude, bool unauthorised_stop = false)
        {
            StringBuilder query = new StringBuilder();
            //string time = string.Format("HH:mm:ss", DateTime.Now);
            //Modified by suvarna on 08/2/2021  as there was delay in cron job (issue like KA51 AF 3378 on 28th Jan)
            string time = DateTime.Now.AddMinutes(-5).ToString("HH:mm:ss");//Modified by suvarna on 18/1/2021  as it was not comparing accurate from time and totime(Issue of 
            query.Append("select groupid from vehiclesgroupsmap where vehicleid = ? order by groupid");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleid", vehicleid);
            Object grpObj = dbx.executeScalar(query.ToString(), lParameter);
            if (grpObj != DBNull.Value)
                id = Convert.ToInt32(grpObj);
            query.Length = 0;
            query.Append("select allowed, regionName,speedUp,speedDown FROM georegions ");
            query.Append(" where (minlatitude <= ? ");
            query.Append("AND minLongitude <= ? ");
            query.Append("AND maxLatitude >= ? ");
            query.Append("AND maxLongitude >= ?)");
            lParameter.Clear();
            lParameter.Add("minlatitude", latitude);
            lParameter.Add("minLongitude", longitude);
            lParameter.Add("maxLatitude", latitude);
            lParameter.Add("maxLongitude", longitude);

            if (id != 0)
            {
                query.Append(" and acntOrGrpId = ?");
                lParameter.Add("acntOrGrpId", id);
            }
            if (unauthorised_stop)
                query.Append(" and fromTime is NULL and toDateTime is NULL");//for unscheduled stops
            else
            {
                query.Append(" and (CAST(? as time) > fromTime or CAST(? as time) < toDateTime)");//other than unscheduled stops
                lParameter.Add("time1", time);
                lParameter.Add("time2", time);

            }
            DataSet allowed = dbx.executeQuery(query.ToString(), lParameter);
            if (allowed.Tables[0].Rows.Count == 0 && unauthorised_stop)
            {
                lParameter.Clear();
                string q = "select Id,geofencename,0 as speedUp,0 as speedDown from geofencenew" +
                         " where (minlatitude <= ? AND minLongitude <= ? AND maxLatitude >= ?" +
                         " AND maxLongitude >= ?) and Accountid=(select AccountID from vehicles where VehicleID=?)";
                lParameter.Add("minlatitude", latitude);
                lParameter.Add("minLongitude", longitude);
                lParameter.Add("maxLatitude", latitude);
                lParameter.Add("maxLongitude", longitude);
                lParameter.Add("VehicleID", vehicleid);
                allowed = dbx.executeQuery(q, lParameter);
            }
            if (allowed.Tables[0].Rows.Count == 0 && unauthorised_stop)
            {
                lParameter.Clear();
                string q = "select Id,locstr,0 as speedUp,0 as speedDown from plantgeolocations" +
                         " where (minlatitude <= ? AND minLongitude <= ? AND maxLatitude >= ?" +
                         " AND maxLongitude >= ? ) and accountid=(select AccountID from vehicles where VehicleID=?) and (`type`<>20 or locstr not like '%JRM%' or locstr like '%parking%'  or locstr like '%REST Area%')";
                lParameter.Add("minlatitude", latitude);
                lParameter.Add("minLongitude", longitude);
                lParameter.Add("maxLatitude", latitude);
                lParameter.Add("maxLongitude", longitude);
                lParameter.Add("VehicleID", vehicleid);
                allowed = dbx.executeQuery(q, lParameter);
            }
            DataTable table = allowed.Tables[0];
            ArrayList regionList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                regionList.Add(row.ItemArray);
            }
            return (regionList.ToArray());
        }
        //Getting all authorised locations to check route points for fuctuations of gps at same places
        public DataTable GetAllAllowedRegions(String vehicleid, int id, bool unauthorised_stop)
        {
            StringBuilder query = new StringBuilder();
            string time = string.Format("HH:mm:ss", DateTime.Now);
            query.Append("select groupid from vehiclesgroupsmap where vehicleid = ? order by groupid");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleid", vehicleid);
            Object grpObj = dbx.executeScalar(query.ToString(), lParameter);
            if (grpObj != DBNull.Value)
                id = Convert.ToInt32(grpObj);
            query.Length = 0;
            query.Append("select allowed, regionName,speedUp,speedDown,minLatitude,minLongitude,maxLatitude,maxLongitude FROM georegions where 1=1 ");
            lParameter = new Dictionary<string, object>();
            if (id != 0)
            {
                query.Append(" and acntOrGrpId = ?");
                lParameter.Add("acntOrGrpId", id);
            }
            if (unauthorised_stop)
                query.Append(" and fromTime is NULL and toDateTime is NULL");//for unscheduled stops
            else
            {
                query.Append(" and (CAST(? as time) > fromTime or CAST(? as time) < toDateTime)");//other than unscheduled stops
                lParameter.Add("time1", time);
                lParameter.Add("time2", time);

            }

            if (unauthorised_stop)
            {
                query.Append(" union select Id,geofencename,0 as speedUp,0 as speedDown,minLatitude,minLongitude,maxLatitude,maxLongitude from geofencenew" +
                         " where Accountid=(select AccountID from vehicles where VehicleID=?)");
                lParameter.Add("VehicleID", vehicleid);
            }
            if (unauthorised_stop)
            {
                query.Append(" union select Id,locstr,0 as speedUp,0 as speedDown,minLatitude,minLongitude,maxLatitude,maxLongitude from plantgeolocations" +
                         " where accountid=(select AccountID from vehicles where VehicleID=?) and "
                         + "(`type`<>20 or locstr not like '%JRM%' or locstr like '%parking%'  or locstr like '%REST Area%')");
                lParameter.Add("VehicleID1", vehicleid);
            }
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }

