        //
        // Need the set of vehicles that are still in plant (not left the plant) in order to check if they have left the plant
        // Input is planttype. Returns a set of vehicles still in plant along with the intimestamp. The model followed for truck reporting
        // is FIFO. Also there may be cases when  a truck may have reported more than once (theoretically n times) so it has to be processed 
        // in order of reporting times.
        // ONLY SELECT VEHICLES THAT BELONG TO THE GROUP
        public Object[] getVehiclesInPlant(String plantLocStr, String sessionId)
        {
            String query = String.Empty;
            query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
                "sessionid ='" + sessionId + "'";
            Object groupIdObj = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(groupIdObj);
            if (String.Compare(plantLocStr, "ALL") == 0)
                query = "select v.vehicleid, intimestamp from vehicleinplant v join vehiclesgroupsmap v1" +
                " on v.vehicleid = v1.vehicleid where outtimedone = 0 and v1.groupid = " + groupId;
            else
                query = "select v.vehicleid, intimestamp from vehicleinplant v join vehiclesgroupsmap v1 on v.vehicleid = v1.vehicleid " +
                    " where locationstr like '" + plantLocStr + "%' and outtimedone = 0 and v1.groupid =" + groupId;
            DataSet listVehIn = dbx.executeQuery(query);
            DataTable table = listVehIn.Tables[0];
            ArrayList vehInPlantList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                vehInPlantList.Add(row.ItemArray);
            }
            return (vehInPlantList.ToArray());
        }

        //
        // Update outtimestamp of a vehicle. The entry to be updated will also be qualified by intimestamp as a vehicle can report IN 
        // multiple times and will be updated in that order and also as per planttype
        //
        public void updateVehicleOutTime(String vehicleId, String inTs, String outTs, String locStr, int plantType)
        {
            String query = String.Empty;
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("outtimestamp", outTs);
            lParameter.Add("vehicleid", vehicleId);
            lParameter.Add("intimestamp", inTs);
            lParameter.Add("locationStr", locStr);
            if (plantType == -1)
                query = "update LOW_PRIORITY vehicleinplant set outtimestamp = ?, outtimedone = 1 where vehicleid = ? and intimestamp = ? and locationStr = ?";
            else
                query = "update LOW_PRIORITY vehicleinplant set outtimestamp = ?, outtimedone = 1 where vehicleid = ? and intimestamp = ? and planttype = ?";
            dbx.executeNonQuery(query, lParameter);
        }

        //
        // The LocStr is Wild carded  so that search will include potentially all plants (main and sattellite) so it is important to
        // prefix the company name to all plants. TO include all plants and customer locations pass ALL in plantLocStr
        //

        /// <summary>
        /// Modified by suvarna on 26/11/2020 to make report as level/planttype
        /// </summary>
        /// <param name="fromDateStr"></param>
        /// <param name="toDateStr"></param>
        /// <param name="planttype"></param>
        /// <param name="sessionId"></param>
        /// <returns></returns>
        public Object[] getVehiclesInPlantList(String fromDateStr, String toDateStr, string planttype, String sessionId)
        {
            string accountName = GetAccountName(sessionId);
            String query = String.Empty;
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("intimestamp1", fromDateStr);
            lParameter.Add("intimestamp2", toDateStr);
            if (!accountName.ToLower().Contains("total"))
            {
                //String query = String.Empty;
                /*query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
                    "sessionid ='" + sessionId + "'";
                Object groupIdObj = dbx.executeScalar(query);
                int groupId = Convert.ToInt32(groupIdObj);
                // extract only those vehicles which belong to sessionId i.e group
                if (plantType == -1)
                    query = "select v.vehicleid, locationstr,intimestamp,outtimestamp,outtimedone from vehicleinplant v join vehiclegroupsmap v1" +
                        " on v.vehicleid = v1.vehicleid where intimestamp between '" +    fromDateStr + "' and '" + toDateStr + "' and v1.groupid = " +
                        groupId;
                else*/
                // There are super users and also custom service groups i.e random vehicles from a set of group added to a service id. Hence
                // we need to create a view and use a sub query to check for vehicles as a groupid may not always be present for a
                // session id
                createVehiclesView(sessionId);
                //var lParameter = new Dictionary<string, object>();
                //lParameter.Add("intimestamp1", fromDateStr);
                //lParameter.Add("intimestamp2", toDateStr);


                //if (String.Compare(planttype, "ALL") == 0)
                if (planttype == "0")//All
                {
                    query = "select  v.vehicleid, locationstr,intimestamp as intimestamp,outtimestamp,outtimedone,s.VehicleInfo from vehicleinplant v join vehicles s on v.vehicleid=s.VehicleID " +
                    " where v.planttype not in (100,20) and intimestamp between ? and ?" +
                    " and v.vehicleid in (select vehicleid from vehiclesview) group by concat(v.vehicleid, v.intimestamp)  order by v.vehicleid,intimestamp asc;";                                                  // Before logic is :  order by locationstr,intimestamp desc;
                }                                                                                                                                                       // Changed because of not showing all the Geofence left details   and  joined  vehicles table to get the route details of Mother dairy vehicles
                else if (planttype == "1")//Loading
                {
                    query = "select  v.vehicleid, locationstr,intimestamp as intimestamp,outtimestamp,outtimedone,s.VehicleInfo from vehicleinplant v join vehicles s on v.vehicleid=s.VehicleID " +
                   " where  intimestamp between ? and ? and v.planttype=0 " +
                   " and v.vehicleid in (select vehicleid from vehiclesview) group by concat(v.vehicleid, v.intimestamp)  order by v.vehicleid,intimestamp asc;";
                }
                else if (planttype == "2")//Unloading
                {
