        //
        // There will be many use cases one of which is for HPCL where the RFID reader is at the security gate and the driver comes there
        // and swipes. In this case the truckid has to be inferred.
        //
        public void recordRfidTime(string vehId, string rfidStr, int timeZone, double latitude, double longitude)
        {  // Whenever rfid is swipped then record the name of the swipped person and the organization
            // he/she belongs
            DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
            String nowStr = formatDBDate(now);
            string query = "select name,organization from rfidtable where cardno = '" + rfidStr + "' order by issued LIMIT 1";
            DataSet rfidDet = dbx.executeQuery(query);
            DataTable table = rfidDet.Tables[0];
            if (table.Rows.Count == 0)
                return;

            String nameStr = (table.Rows[0][0]).ToString();
            String organization = (table.Rows[0][1]).ToString();

            query = "insert into capturerfidreportingtime(vehicleid,timestamp,name,organization,latitude,longitude) " +
                "values('" + vehId + "','" + nowStr + "','" + nameStr + "','" + organization + "'," + latitude + "," + longitude + ")";
            dbx.executeNonQuery(query);
        }
