        //
        // Returns one or more DateTime based on number of times swipped.If only one entry returned and 
        // is DateTime.MinValue then no swipe found.
        //
        public DateTime[] getDriverReportingTime(string vehicleId, DateTime lastTS)
        {
            String lastTSStr = formatDBDate(lastTS);
            String query = "select timestamp from driverreportingtime where vehicleid = '" + vehicleId + "' and timestamp >= '" + lastTSStr + "'";
            DataSet dtDS = dbx.executeQuery(query.ToString());
            DataTable table = dtDS.Tables[0];
            ArrayList dtArray = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                dtArray.Add(row.ItemArray);
            }
            Object[] dtObj = dtArray.ToArray();
            int numEntries = 1;

            if (dtArray.Count > 0)
            {
                numEntries = dtObj.Length;
            }
            // The driver would not have swipped or would have swipped one or more times
            DateTime[] drvLoginDates = new DateTime[numEntries];
            for (int i = 0; i < numEntries; i++)
                drvLoginDates[i] = DateTime.MinValue;	//initialize
            if (dtArray.Count > 0)
            {
                for (int i = 0; i < numEntries; i++)
                    drvLoginDates[i] = DateTime.Parse((((Object[])dtObj[i])[0]).ToString());
            }
            return (drvLoginDates);
        }
        // +++++++++++++++++++++++++++++++++ SPECIAL FUNCTION ++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
        // This function is called to execute a stored procedure in MySQL. After doing a brief study it seems that the only way
        // to execute a stored procedure is to create a new connection at the ODBC level and execute. The reasons are 
        // 	- Need OdbcCommand to be instantiated. OdbcCommand command is a private variable defined in DataAccess so cannot access it here
        //	- Making it public is probably an issue as as per my understanding of documentation only public static variables are THREAD SAFE
        // So Open a new ODBC connection. Instantiate the command variable, call a stored procedure and CLOSE it
        // ++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
        public void checkRefRouteProcedure(String truckId, String fromdate, String todate, String groupid, string accountid, String connectionStr)
        {
            if (connectionStr == null)
                connectionStr = System.Web.Configuration.WebConfigurationManager.AppSettings["dbConnectionString"];
            OdbcConnection OdbcDBX = new OdbcConnection(connectionStr);
            Mutex mutex = new Mutex();
            OdbcCommand cmd = new OdbcCommand("{ CALL checkreferenceroute_v1(?,?,?,?,?) }", OdbcDBX);
            cmd.CommandType = CommandType.StoredProcedure;

            cmd.Connection = OdbcDBX;

            cmd.Parameters.Add("@truckId", OdbcType.VarChar, 32).Value = truckId;
            cmd.Parameters.Add("@fromdate", OdbcType.VarChar, 32).Value = fromdate;
            cmd.Parameters.Add("@todate", OdbcType.VarChar, 32).Value = todate;
            cmd.Parameters.Add("@groupid", OdbcType.VarChar, 128).Value = groupid;
            cmd.Parameters.Add("@accountid", OdbcType.VarChar, 128).Value = accountid;
            mutex.WaitOne();
            try
            {
                OdbcDBX.Open();
                cmd.ExecuteNonQuery();
            }
            finally
            {
                mutex.ReleaseMutex();
            }
            //int retvalue = Convert.ToInt32(cmd.Parameters["@crossedcount"].Value);
            OdbcDBX.Close();
        }

