        public void chkUsrinFreq(String uid, String pageurl, string sUI = "OLD")
        {
            try
            {
                StringBuilder query = new StringBuilder();
                DateTime date = DateTime.Today;
                String currtime = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()).ToString("T");
                String dte = date.ToString("yyyy-MM-dd");
                query.Append("select count(0) from usr_visit_freq where uid = ?");
                query.Append(" AND logDate = ?");
                query.Append(" AND pageUrl = ? ;");
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("uid", uid);
                lParameter.Add("logDate", dte);
                lParameter.Add("pageUrl", pageurl);
                Object cntNum = dbx.executeScalar(query.ToString(), lParameter);
                int usrNum = Convert.ToInt32(cntNum);

                query.Length = 0;
                query.Capacity = 0;

                if (usrNum == 0)
                {
                    query.Append("insert into usr_visit_freq (uid, logDate, pageUrl, num,last_login,UI) Values(?,?,?,?,?,?)");
                    lParameter.Clear();
                    lParameter.Add("uid", uid);
                    lParameter.Add("logDate", dte);
                    lParameter.Add("pageUrl", pageurl);
                    lParameter.Add("num", 1);
                    lParameter.Add("last_login", currtime);
                    lParameter.Add("UI", sUI);
                    dbx.executeNonQuery(query.ToString(), lParameter);
                }
                else
                {
                    query.Append("update usr_visit_freq set num = num + 1,last_login =? where uid =? AND logDate =? AND pageUrl =? AND UI=? ;");
                    lParameter.Clear();
                    lParameter.Add("last_login", currtime);
                    lParameter.Add("uid", uid);
                    lParameter.Add("logDate", dte);
                    lParameter.Add("pageUrl", pageurl);
                    lParameter.Add("UI", sUI);
                    dbx.executeNonQuery(query.ToString(), lParameter);
                }
            }
            catch { }
        }

