        public Object[] getCummDriveTimes(String sessionId, int longRunDuration)
        {
            String query = String.Empty;
            query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
                "sessionid ='" + sessionId + "'";
            Object groupIdObj = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(groupIdObj);
            query = "select v.vehicleid,v1.vehicleinfo from vehiclessnapshot v join vehicles v1 on v.vehicleid = v1.vehicleid " +
                "where v.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid = " + groupId + ") and v.cummAlert=0" +
                " and cummRunTime > " + (longRunDuration - 7200);
            DataSet vehDS = dbx.executeQuery(query);
            DataTable table = vehDS.Tables[0];
            ArrayList vehList = new ArrayList();
            foreach (DataRow Row in table.Rows)
            {
                vehList.Add(Row.ItemArray);
            }
            Object[] veh = vehList.ToArray();
            if (veh.Length > 0)
            {
                String vehicle = String.Empty;
                for (int i = 0; i < veh.Length; i++)
                {
                    vehicle = (((Object[])veh[i])[0]).ToString();
                    query = "update vehiclessnapshot set cummAlert=1 where vehicleid = '" + vehicle + "'";
                    dbx.executeNonQuery(query);
                }
            }
            return veh;
        }

