        public Object[] getallexpirydates(string type, string datatype)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select ");
            if (type.Equals("Transporter"))
            {
                query.Append("transpotername,contractenddate,nextauditdate,nextmeetdate from transporterdata");
                if (!(datatype.Equals("all")))
                {
                    query.Append(" where transpotername=\"" + datatype + "\"");
                }
            }
            else if (type.Equals("Driver"))
            {
                query.Append("drivername,dlvdate,hdlldate from driverdetails");
                if (!(datatype.Equals("all")))
                {
                    query.Append(" where transportername=\"" + datatype + "\"");
                }
            }
            else if (type.Equals("truck"))
            {
                query.Append("truckid,insvaldate,rtofdate,pesovaldate,cenddate,nexthtDate,prvdate,nextidate from truckdetails");
                if (!(datatype.Equals("all")))
                {
                    query.Append(" where transportername=\"" + datatype + "\"");
                }
            }
            DataSet comInfo = dbx.executeQuery(query.ToString());

            DataTable table = comInfo.Tables[0];

            ArrayList comInfoList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                comInfoList.Add(row.ItemArray);
            }

            //Added for concatnation of the drivername and DOB
            if (type.Equals("Driver"))
            {
                ////////////////////changes are done to support the CONCATNATION of DOB and DRIVERNAME
                object[] ret = comInfoList.ToArray();
                int i = 0;
                String drivername = String.Empty;
                for (i = 0; i < ret.Length; i++)
                {
                    drivername = (((Object[])ret[i])[2]).ToString();
                    if (!string.IsNullOrEmpty(drivername))
                    {
                        String[] drivertmp = drivername.Split('|');
                        drivername = drivertmp[0];
                        (((Object[])ret[i])[2]) = drivername;
                    }
                }
                return ret;
            }
            else
                return comInfoList.ToArray();
        }



