        public void writeTempVehViolationSummary(string vehId, string restTime, string spVio, string cdVio, string nDrv, string maxDrvVio, string harshVio, string highAcclVio, string date, string sessionId, string name, string driverid, string distance, int earnedpoints, int negativepoints, int totalpoints, int rank_points, string maxhalt, string totalruntime, string dailyRest, string weeklyRest, string weeklyRun, string dutyTime)
        {
            //String nowStr= DateTime.Now.ToString("yyyy-MM-dd");
            String query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
            "sessionid ='" + sessionId + "'";
            Object groupIdObj = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(groupIdObj);

            query = "select count(*) from daywisetmpvehviosummary where vehicleid = '" + vehId + "' and groupid = " + groupId + " and date = '" + date + "'";
            Object numObj = dbx.executeScalar(query);

            int num = Convert.ToInt32(numObj);
            if (num == 0)
            {
                query = "insert into daywisetmpvehviosummary(groupid,vehicleid,date,cd,maxsp,nd,md,harshBraking,resttime,maxhalttime,drivername,driverid,Kms_driven,positivepoints,negativepoints,points_earned,ranking_points,totalruntime,IdleTime,WeeklyRest,HarshAcceleration) values(" + groupId + ",'" + vehId + "','" + date +
                    "','" + cdVio + "','" + spVio + "','" + nDrv + "','" + maxDrvVio + "','" + harshVio + "','" + restTime + "','" + maxhalt + "','" + name + "','" + driverid + "','" + distance + "','" + earnedpoints + "','" + negativepoints + "','" + totalpoints + "','" + rank_points + "','" + totalruntime + "','" + dailyRest + "','" + weeklyRest + "','" + highAcclVio + "')";
                dbx.executeNonQuery(query);
            }
            else
            {
                query = "update daywisetmpvehviosummary set cd = '" + cdVio + "',maxsp='" + spVio + "',nd = '" + nDrv + "',md='" + maxDrvVio +
                    "',harshBraking = '" + harshVio + "',resttime = '" + restTime + "',maxhalttime = '" + maxhalt + "',Kms_driven='" + distance + "',positivepoints='" + earnedpoints + "',negativepoints='" + negativepoints + "',points_earned='" + totalpoints + "',ranking_points='" + rank_points + "',totalruntime='" + totalruntime + "',IdleTime='" + dailyRest + "',WeeklyRest='" + weeklyRest + "',HarshAcceleration='" + highAcclVio + "'  where vehicleid = '" + vehId + "' and date = '" + date + "'";
                dbx.executeNonQuery(query);
            }
            // RECORD ALERT AND ALARM FOR NIGHT DRIVING AND MAXIMUM DRIVING
            // RULES ND & MD - 15 mins RECORD, 30 mins ALERT 1hr ALARM
            // Split nd and md which are hh:mm
            String[] nDrvHHMM = null;
            String[] maxDrvVioHHMM = null;
            int hours = 0;
            int mins = 0;
            if (!String.IsNullOrEmpty(nDrv))
            {
                nDrvHHMM = nDrv.Split(':');
                try
                {
                    hours = Convert.ToInt32(nDrvHHMM[0]);
                    mins = Convert.ToInt32(nDrvHHMM[1]);
                    // Apply rule
                    if (hours > 11) //Alarm
                        storeVehicleViolations(vehId, "", "NIGHT DRIVING", "", (double)((hours - 11) * 60 + mins), "ALARM", "");
                    else if (mins > 30)
                        storeVehicleViolations(vehId, "", "NIGHT DRIVING", "", (double)(mins - 30), "ALERT", "");
                    else if (mins > 15)
                        storeVehicleViolations(vehId, "", "NIGHT DRIVING", "", (double)(mins - 15), "RECORD", "");
                }
                catch { }
                ;
            }
            if (!String.IsNullOrEmpty(maxDrvVio))
            {
                maxDrvVioHHMM = nDrv.Split(':');
                try
                {
                    hours = Convert.ToInt32(maxDrvVioHHMM[0]);
                    mins = Convert.ToInt32(maxDrvVioHHMM[1]);
                    // Apply rule
                    if (hours > 11) //Alarm
                        storeVehicleViolations(vehId, "", "TOTAL RUNTIME", "", (double)((hours - 11) * 60 + mins), "ALARM", "");
                    else if (mins > 30)
                        storeVehicleViolations(vehId, "", "TOTAL RUNTIME", "", (double)(mins - 30), "ALERT", "");
                    else if (mins > 15)
                        storeVehicleViolations(vehId, "", "TOTAL RUNTIME", "", (double)(mins - 15), "RECORD", "");
                }
                catch { }
                ;
            }
        }

