                string[] nd_startlatlng = ndstartlatlng.Split(',');
                string[] nd_endlatlng = ndendlatlng.Split(',');

                if (startlatlng.Length > 1)
                    tripstartloc = getPositionTxt(startlatlng[0], startlatlng[1], 0);
                if (endlatlng.Length > 1)
