                    ndendloc = getPositionTxt(nd_endlatlng[0], nd_endlatlng[1], 0);
            }
            catch (Exception e) { }
            ;

            string query = "INSERT INTO `daywisevehviosummary` (`groupid`, `vehicleid`, `date`, `cd`, `maxsp`, `nd`, `md`, `harshBraking`, `resttime`, `maxhalttime`, `drivername`, `driverid`, `Kms_driven`, `positivepoints`, `negativepoints`, `points_earned`, `ranking_points`, `nd_distance`,`IsNightDrivingViol`,`nd_startlatlng`, `nd_endlatlng`, `maxsp_count`, `maxsp_loc`,maxsp_time, `rd_count`, `rd_kms`, `harshbraking_count`, `harshaccln_Count`, `harshaccln_value`, `totalruntime`, `trip_starttime`, `trip_endtime`, `startlatlng`, `endlatlng`, `totalstops`, `harshbraking_loc`, `harshaccln_loc`,actual_starttime,actual_endtime,TripId,IsTrip,IdleTime,VehMaxSpeed,MaxSpDuration,startlocation,endlocation,ndstartlocation,ndendlocation) VALUES (" + groupId + ",'" + vehId + "','" + date +
                    "','" + cdVio + "','" + spVio + "','" + nDrv + "','" + maxDrvVio + "','" + harshVio + "','" + restTime + "','" + maxhalt + "','" + name + "','" + driverid + "','" + distance + "','" + earnedpoints + "','" + negativepoints + "','" + totalpoints + "','" + rank_points + "','" + nd_distance + "','" + IsNightDrivingViol + "','" + ndstartlatlng + "','" + ndendlatlng + "','" + maxspcount + "','" + maxsploc + "','" + OverSpeedTime + "','" + rdcount + "','" + rdkms + "','" + HBcount + "','" + HAcount + "','" + HAvalue + "','" + runtime + "','" + tripstart + "','" + tripend + "','" + tripstartlatlng + "','" + tripendlatlng + "','" + totalstops + "','" + HBLoc + "','" + HALoc + "','" + formatDBDate(ActualStartTime) + "','" + formatDBDate(ActualEndTime) + "','" + TripId + "','" + IsTrip + "','" + idletime + "','" + VehMaxSp + "','" + MaxSpDur + "','" + tripstartloc + "','" + tripendloc + "','" + ndstartloc + "','" + ndendloc + "')";
            dbx.executeNonQuery(query);
        }
        public void writeTempViolationSummaryData(int totalNumVeh, int VehWithNilViolations, int VehShortContDrive, int VehOverspeed, int VehNightDriveViolation, int VehLongContDrive, int HarshBrakingViolation, int HighAccelerationViolation, String date, string sessionId)
        {
            String nowStr = DateTime.Now.ToString("yyyy-MM-dd");
            String query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
                "sessionid =?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("sessionid", sessionId);
            Object groupIdObj = dbx.executeScalar(query, lParameter);
            int groupId = Convert.ToInt32(groupIdObj);
            query = "select count(*) from storetmpviolationsummarydata where date = ? and groupid = ?";
            lParameter.Clear();
            lParameter.Add("date", date);
            lParameter.Add("groupid", groupId);

            Object numObj = dbx.executeScalar(query, lParameter);
            int num = Convert.ToInt32(numObj);
            if (num == 0)
            {
                query = "insert into storetmpviolationsummarydata(groupid,date,numVeh,nilviolations,cdviolations,speedviolations,nightdrvvioaltions,runtimeviolation,harshbrakingviolation,harshAccelerationviolation) " +
                    " values(?,?,?,?,?,?,?,?,?);";
                lParameter.Clear();
                lParameter.Add("groupid", groupId);
                lParameter.Add("date", date);
                lParameter.Add("numVeh", totalNumVeh);
                lParameter.Add("nilviolations", VehWithNilViolations);
                lParameter.Add("cdviolations", VehShortContDrive);
                lParameter.Add("speedviolations", VehOverspeed);
                lParameter.Add("nightdrvvioaltions", VehNightDriveViolation);
                lParameter.Add("runtimeviolation", VehLongContDrive);
                lParameter.Add("harshbrakingviolation", HarshBrakingViolation);
                lParameter.Add("harshAccelerationviolation", HighAccelerationViolation);
                dbx.executeNonQuery(query, lParameter);
            }
            else
            {
                query = "update storetmpviolationsummarydata set numVeh=?,nilviolations=?,cdviolations= ?" +
                    ",speedviolations=?,nightdrvvioaltions=?,runtimeviolation=?" +
                    ",harshbrakingviolation=?,harshAccelerationviolation=? where date = ? and groupid = ?;";
                lParameter.Clear();
                lParameter.Add("numVeh", totalNumVeh);
                lParameter.Add("nilviolations", VehWithNilViolations);
                lParameter.Add("cdviolations", VehShortContDrive);
                lParameter.Add("speedviolations", VehOverspeed);
                lParameter.Add("nightdrvvioaltions", VehNightDriveViolation);
                lParameter.Add("runtimeviolation", VehLongContDrive);
                lParameter.Add("harshbrakingviolation", HarshBrakingViolation);
                lParameter.Add("harshAccelerationviolation", HighAccelerationViolation);
                lParameter.Add("date", date);
                lParameter.Add("groupid", groupId);
                dbx.executeNonQuery(query, lParameter);
            }
        }

