        {
            if (n == 1)
            {
                string query = "select * from comttddata where drivername ='" + driver + "' and drvdate = '" + date + "'";

                DataSet dInfo = dbx.executeQuery(query.ToString());
                DataTable table = dInfo.Tables[0];
                ArrayList dInfoList = new ArrayList();
                foreach (DataRow row in table.Rows)
                {
                    dInfoList.Add(row.ItemArray);
                }
                return dInfoList.ToArray();
            }
            else
