        public Boolean checkWhichPlant(int planttype, String vehicleId, String locStr)
        {
            // Get the vehicle's HomeLat and HomeLong and get the plantType which will decide what is to be done
            Object[] vehDetails = getVehicleDetails(vehicleId);
            float homeLat = 0.0F;
            float homeLong = 0.0F;
            String homeLocStr = String.Empty;
            Boolean home = false;
            if (vehDetails.Length > 0)
            {
                try
                {
                    homeLat = Convert.ToSingle((((Object[])vehDetails[0])[0]).ToString());
                    homeLong = Convert.ToSingle((((Object[])vehDetails[0])[1]).ToString());
                }
                catch { }
                //Console.WriteLine("Home Lat - " + homeLat + " Home Long: " + homeLong);
                //Console.ReadKey(true);
                Object[] vehHomLoc = checkPlantGeoLocations((double)homeLat, (double)homeLong);
                if (vehHomLoc.Length > 0)
                {
                    homeLocStr = (((Object[])vehHomLoc[0])[0]).ToString();
                    //Console.WriteLine("HOME LOC RETURNED - " + homeLocStr);
                    //Console.WriteLine("LOC PASSWD - " + locStr);
                    //Console.ReadKey(true);

                }
                if (homeLocStr.Equals(locStr))
                {	// means the vehicle is in HOME plant
                    home = true;
                }
                else
                {
                    home = false;
                }
            }
            return (home);
        }

        public void updateRouteSummaryTable(String vehicleId, String wayPointsTbl, Boolean home, int timeZone)
        {
            try
            {
                String query = String.Empty;
                if (!String.IsNullOrEmpty(wayPointsTbl))
                {
                    query = "DROP TABLE IF EXISTS " + wayPointsTbl;
                    dbx.executeNonQuery(query);
                }
                DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
                String nowStr = formatDBDate(now);

                String direction = String.Empty;
                String route = "";
                String wpTbl = "";
                if (home)
                {
                    direction = "UP";
                    //Console.WriteLine(direction);
                    //Console.ReadKey(true);
                    query = "update vehicleroutesummary set direction = '" + direction + "',activeroute='" + route + "',tripstart='" + nowStr +
                    "',waypoints='" + wpTbl + "' where vehicleid = '" + vehicleId + "'";
                }
                else
                {
                    direction = "DOWN";
                    //Console.WriteLine(direction);
                    //Console.ReadKey(true);
                    query = "update vehicleroutesummary set direction = '" + direction + "',activeroute='" + route + "',waypoints='" + wpTbl +
                        "' where vehicleid = '" + vehicleId + "'";
                }
                dbx.executeNonQuery(query);
            }
            catch { }
        }

