        public String checkAndPlayWayPointAlerts(String vehicleId, float latitude, float longitude, String sessionId, int timeZone, String alertLang)
        {
            // Check if the vehicle is still on the allocated route by checking it against the reference route. 
            // Update the waypoints which may involve de-allocating the old waypoint and assigning a new one
            // The reference route table will return the route the vehicle is currently in and then use that to check if 
            // a new wayPointTbl has to be allocated.
            // Now the referenceroute for BOTH UP AND DOWN will be the same but the WAYPOINTS tbl WILL BE DIFFERENT so even
            // if the route matches the WAYPOINT tbl should be allocated based on the DIRECTION OF THE VEHICLE.
            // Then check and return all the wayPoint data that has to be played on the vehicle
            Object[] accountInfo = getAccountInfo(sessionId);
            int accountId = 0;
            String accountName = String.Empty;
            if (accountInfo != null)
                if (accountInfo.Length > 0)
                {
                    accountId = Convert.ToInt32(accountInfo[2]);
                    accountName = accountInfo[0].ToString();
                }
            Boolean restJRMPlayed = false;
            String query = "select distinct routename from referenceroutedetail where accountid = " + accountId + " and (" + latitude
                + " between (minlat-0.005) and (maxlat+0.005)) and (" + longitude + " between (minlong-0.005) and (maxlong+0.005)) limit 1";
            //String query = "select distinct routename from referenceroutedetail where (minlat-0.005) < " + latitude + " and (maxlat+0.005) > " +
            //    latitude + " and (minlong-0.005) < " + longitude + " and (maxlong+0.005) > " + longitude + " and accountid = " + accountId + " and isvehicleassigned !=-1 limit 1";
            Object refRouteNameObj = dbx.executeScalar(query);
            if (refRouteNameObj == null)
                return ("NO: NO MATCHING REF ROUTE");
            //if (Convert.IsDBNull(refRouteNameObj))
            //{
            //	return("NO : NO MATCHING REF ROUTE");
            //}

            String routeName = refRouteNameObj.ToString();
            if (String.IsNullOrEmpty(routeName))
                return ("NO: NO MATCHING REF ROUTE");  // current vehicle location does not match any reference route stored
            query = "select direction,activeroute,waypoints from vehicleroutesummary where vehicleid = '" + vehicleId + "'";
            DataSet vehWayPointSummarySet = dbx.executeQuery(query);
            DataTable table = vehWayPointSummarySet.Tables[0];
            if (table.Rows.Count == 0)
                return ("NO: NO ENTRY IN VEHICLE ROUTE SUMMARY TABLE!!");
            String dir = table.Rows[0].ItemArray[0].ToString();	// It is assumed that the direction is set once the vehicle reaches PLANT or cust loc
            String actRoute = table.Rows[0].ItemArray[1].ToString();
            String currentWayPointsTblName = table.Rows[0].ItemArray[2].ToString();
            String wayPointTbl = String.Empty;
            String vehId = String.Empty;
            // A FEW scenarios
            // Route not allocated means the vehicle is most likely inplant or just coming out of Non JRM region. Allocate route and also the wayPoints
            // Route may now be different in which case de-allocated the WAYPoint tbl and change route and also allocate a new WAYPOINT tbl based on DIR
            // Route may be same but check the DIRECTION and ensure that the RIGHT WAYPOINT tbl is being used if not de-allocate and allocate a fresh one
            //
            vehId = vehicleId.Replace(' ', '_');
            routeName = routeName.Replace(' ', '_');
            String wayPointTblRoute = routeName + "_" + dir;
            wayPointTbl = "tmp_" + wayPointTblRoute + "_" + vehId;
            Object[] tripParams = getVehicleTripParams(sessionId, vehicleId);
            if (tripParams.Length == 0)
            {
                return ("NO: TRIP PARAMS MISSING FOR THE VEHICLE!!");
            }
            int defaultSpeed = (int)(Convert.ToSingle(((Object[])tripParams[0])[5]) / 1.852F);
            //routeName = routeName + "_" + dir;
            if (String.IsNullOrEmpty(actRoute))
            {	// Assign route and also allocate a WAYPOINT tbl
                // actRoute = actRoute + "_" + dir;
                //Console.WriteLine("EMPTY ROUTE TABLE -" + wayPointTbl + " route - " + wayPointTblRoute);
                //Console.ReadKey(true);
                query = "create table if not exists " + wayPointTbl + "(`routename` VARCHAR(255) NOT NULL DEFAULT '', " +
                    "`locstr` VARCHAR(255) NOT NULL DEFAULT '', " +
                    "`description` VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'Comma separated', " +
                    "`commands` VARCHAR(255) NOT NULL DEFAULT '', " +
                    "`crossed` TINYINT NOT NULL DEFAULT '0'," +
                    "`played` TINYINT NOT NULL DEFAULT '1'," +
                    "`minlat` FLOAT NOT NULL DEFAULT '0.0', " +
                    "`maxlat` FLOAT NOT NULL DEFAULT '0.0', " +
                    "`minlong` FLOAT NOT NULL DEFAULT '0.0', " +
                    "`maxlong` FLOAT NOT NULL DEFAULT '0.0' ," +
                    "UNIQUE KEY `unique_jrm` (`minlat`,`minlong`))";
                dbx.executeNonQuery(query);
                query = "insert ignore into " + wayPointTbl + "(locstr,description,commands,minlat,maxlat,minlong,maxlong) (select " +
                    " locstr,description,commands,minlat,maxlat,minlong,maxlong from waypointsref where accountid = " + accountId + " and routename = '" + wayPointTblRoute + "')";
                dbx.executeNonQuery(query);
                // Update the route assigned and also the wayPointTableName
                query = "update vehicleroutesummary set activeroute = '" + routeName + "',waypoints = '" + wayPointTbl + "' where vehicleid = '" + vehicleId + "'";
                dbx.executeNonQuery(query);
                //Console.WriteLine("vehicleroutesummary - Check");
                //Console.ReadKey(true);
                checkAndResetSpeedLimit(vehicleId, defaultSpeed, timeZone);
            }
            else if ((String.Compare(actRoute, routeName) == 0 && String.Compare(wayPointTbl, currentWayPointsTblName) != 0) ||
                     (String.Compare(actRoute, routeName) != 0))
            {	// Routes are the same now BUT DIRECTION IS different OR ROUTE is DIFFERENt
                //Console.WriteLine("actRoute - " + actRoute + " routeName - " + routeName + " wayPointTbl - " + wayPointTbl + 
                // " currentWayPoints - " + currentWayPointsTblName);
                //Console.ReadKey(true);
                if (!String.IsNullOrEmpty(currentWayPointsTblName))
                {
                    query = "DROP TABLE IF EXISTS " + currentWayPointsTblName;
                    dbx.executeNonQuery(query);
                }
                // Assign route and also allocate a WAYPOINT tbl
                // actRoute = actRoute + "_" + dir;
                //wayPointTbl = "tmp_" + wayPointTblRoute + "_" + vehicleId;
                query = "create table if not exists " + wayPointTbl + "(`routename` VARCHAR(255) NOT NULL DEFAULT '', " +
                    "`locstr` VARCHAR(255) NOT NULL DEFAULT '', " +
                    "`description` VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'Comma separated', " +
                    "`commands` VARCHAR(255) NOT NULL DEFAULT '', " +
                    "`crossed` TINYINT NOT NULL DEFAULT '0'," +
                    "`played` TINYINT NOT NULL DEFAULT '1'," +
                    "`minlat` FLOAT NOT NULL DEFAULT '0.0', " +
                    "`maxlat` FLOAT NOT NULL DEFAULT '0.0', " +
                    "`minlong` FLOAT NOT NULL DEFAULT '0.0', " +
                    "`maxlong` FLOAT NOT NULL DEFAULT '0.0' ," +
                    "UNIQUE KEY `unique_jrm` (`minlat`,`minlong`))";
                dbx.executeNonQuery(query);
                query = "insert ignore into " + wayPointTbl + "(locstr,description,commands,minlat,maxlat,minlong,maxlong) (select " +
                    " locstr,description,commands,minlat,maxlat,minlong,maxlong from waypointsref where accountid = " + accountId + " and routename = '" + wayPointTblRoute + "')";
                dbx.executeNonQuery(query);
                // Update the route assigned and also the wayPointTableName
                //Console.WriteLine("Check the waytbl");
                //Console.ReadKey(true);
                query = "update vehicleroutesummary set activeroute = '" + routeName + "',waypoints = '" + wayPointTbl + "' where vehicleid = '" + vehicleId + "'";
                dbx.executeNonQuery(query);
                checkAndResetSpeedLimit(vehicleId, defaultSpeed, timeZone);
            }
            // It is essential that all waypoints that are crossed to be marked otherwise for eg. when a vehicle is resting "rest area" message will keep 
            // playing
            query = "update " + wayPointTbl + " set crossed = 1,played=0 where minlat < " + latitude + " and maxlat > " + latitude +
                " and minlong < " + longitude + " and maxlong > " + longitude + " and crossed = 0";
            dbx.executeNonQuery(query);

            // Now the route is IDENTIFIED and the WAYPOINTTABLE has been CORERCTLY ALLOCATED so check if any ACTION HAS to be taken


            query = "select distinct locstr, commands, description from " + wayPointTbl + "  where played = 0";
            try
            {
                DataSet jrmSet = dbx.executeQuery(query);
                table = jrmSet.Tables[0];
            }
            catch { return ("NO: WAYPOINT"); }

            if (table.Rows.Count == 0)
            { // If it comes here it means there are no JRM waypoint currently. So check if a RESET OF JRM is needed by checking when was the 
                // last JRM PLAYED.
                checkAndResetSpeedLimit(vehicleId, defaultSpeed, timeZone);
                return ("NO: WAYPOINT");
            }

            query = "update " + wayPointTbl + " set played=1 where played = 0";
            dbx.executeNonQuery(query);
            // If there are waypoints then identify them. There can be two types of waypoints for now.
            // i) SLOW DOWN
            // ii) REST AREA
            // In case of REST AREA we have to check Continuous Drive(CD) value and Maximum Drive(MD) parameter and then play.
            // There may be more than WAYPOINT match and each ROW will contain ONLY ONE WAYPOINT.
            // For now everything other than REST AREA would entail setting the SPEED. 

            DateTime jrmTS = DateTime.UtcNow.AddSeconds(timeZone);
            String jrmTSStr = formatDBDate(jrmTS);
            int shortRunDuration = Convert.ToInt32(((Object[])tripParams[0])[0]);
            int longRunDuration = Convert.ToInt32((((Object[])tripParams[0])[2]).ToString().Split(',')[0]);
            for (int i = 0; i < table.Rows.Count; i++)
            {
                String locStr = table.Rows[i].ItemArray[0].ToString();
                String command = table.Rows[i].ItemArray[1].ToString();
                String description = table.Rows[i].ItemArray[2].ToString();
                int msgNo = 0;
                //String isRestArea = table.Rows[i].ItemArray[3].ToString();
                if (accountName.Contains("HPCL"))
                {
                    query = "select msgno from alertlanguagemapping where language = '" + alertLang + "' and description = '" + description + "'";
                    Object msgObj = dbx.executeScalar(query);
                    if (msgObj != null)
                        msgNo = Convert.ToInt32(msgObj.ToString());
                    if (msgNo == 0)
                    {
                        command = command + "6 )"; //default
                        addServerRequest(vehicleId, 5, command);
                    }
                    else
                    {
                        command = command + msgNo + " )";
                        addServerRequest(vehicleId, 5, command);
                    }
                    updateJRMTs(vehicleId, jrmTSStr, 1);
                    logJRMData(vehicleId, locStr, description);
                    checkAndResetSpeedLimit(vehicleId, defaultSpeed, timeZone);
                }
                else
                {
                    if (String.Compare(description, "REST AREA") != 0 && !description.ToLower().Contains("parking"))
                    { // Way point other than REST AREA is also present
                        addServerRequest(vehicleId, 5, command);		// contains the exact command to be played in the box with () included
                        // Since SPEED LIMIT is dynamic it has to be reset to the default value once the vehicle is out of the wyapoint zone
                        // Capture the TimeStamp of the JRM so that action can be taken later to RESET the SPEED parameter.
                        updateJRMTs(vehicleId, jrmTSStr, 1);
                        logJRMData(vehicleId, locStr, description);
                    }
                    else
                    {
                        // Has a REST AREA CHECK CD AND MD AND THEN DECIDE TO PLAY
                        string drivername = getdrivername(vehicleId, jrmTS.ToString("yyyy-MM-dd HH:mm:ss"));
                        Object[] vehSnapShot = getVehicleSnapShot(vehicleId, drivername.Split(',')[1]);
                        if (vehSnapShot.Length > 0)
                        {
                            int shortRunTime = Convert.ToInt32((((Object[])vehSnapShot[0])[0]).ToString());
                            int cummRuntime = Convert.ToInt32((((Object[])vehSnapShot[0])[2]).ToString());
                            if (shortRunTime >= (shortRunDuration - 15 * 60) || cummRuntime >= (longRunDuration - 15 * 60)) //15 minutes before
                            {
                                addServerRequest(vehicleId, 5, command);
                                restJRMPlayed = true;
                                logJRMData(vehicleId, locStr, description);
                            }
                        }
                        checkAndResetSpeedLimit(vehicleId, defaultSpeed, timeZone);
                    }
                }
            }
            if (table.Rows.Count == 0)
                return ("NO: WAYPOINT");
            else
                return ("YES: - " + vehicleId);
        }

        public void updateJRMTs(String vehicleId, String jrmTSStr, int jrmReset)
        {
            String query = "update vehicleroutesummary set lastjrmts = '" + jrmTSStr + "',resetjrm=" + jrmReset + " where vehicleid = '" + vehicleId + "'";
            dbx.executeNonQuery(query);
        }

        public void checkAndResetSpeedLimit(String vehicleId, int defaultSpeed, int timeZone)
        {
            DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
            String query = "select lastjrmts,resetjrm from vehicleroutesummary where vehicleid = '" + vehicleId + "'";
            DataSet resetDS = dbx.executeQuery(query);
            DataTable table = resetDS.Tables[0];
            int resetJrm = 0;
            if (table.Rows.Count == 0)
                return;
            DateTime lastJRMTs = DateTime.MinValue;
            try
            {
                lastJRMTs = DateTime.Parse(table.Rows[0].ItemArray[0].ToString());
            }
            catch { }
            try
            {
                resetJrm = int.Parse(table.Rows[0].ItemArray[1].ToString());
            }
            catch { }

            if (resetJrm == 1)
            {
                // There will be regions of WAYpoints that are KMs long (for eg. clubbed WAYPOINTS), logic sets the zone has been crossed once
                // the vehicle enters and the vehicle will take time to cross the waypoint region so there should be a time lapse before
                // the speed is reset
                TimeSpan timeSinceLastJRM = now - lastJRMTs;
                if (timeSinceLastJRM.TotalSeconds >= 5 * 60)   // assumes that in 5 mins max a JRM zone is cross which translates to 7.5kms zone max
                {
                    String vmuCmd = "(SET SPEEDLIMIT " + defaultSpeed + ")";
                    //Send command to SLD to reset

                    //Console.WriteLine(vmuCmd);
                    //Console.ReadKey(true);
                    addServerRequest(vehicleId, 5, vmuCmd);
                    vmuCmd = "(ACT SERCMD1 #SET,0" + (int)(defaultSpeed * 1.9) + "*)";
                    addServerRequest(vehicleId, 5, vmuCmd);
                    query = "update vehicleroutesummary set resetjrm = " + 0 + " where vehicleid = '" + vehicleId + "'";
                    dbx.executeNonQuery(query);
                }
            }
        }

        public DateTime getInTimestampForVehicle(String vehicleId, DateTime now)
        {
            String nowStr = formatDBDate(now);
            DateTime past = now.AddMinutes(-3 * 60);
            String pastStr = formatDBDate(past);
            String query = "select intimestamp from vehicleinplant where vehicleid = '" + vehicleId + "' and intimestamp > '" + pastStr +
                "' and intimestamp <= '" + nowStr + "' and planttype<>20 LIMIT 1";
            Object inTSObj = dbx.executeScalar(query);
            String inTSStr = String.Empty;
            DateTime inTS = DateTime.MinValue;
            if (inTSObj == null)
                return (inTS);
            if (inTSObj != DBNull.Value)
                inTSStr = inTSObj.ToString();
            if (!String.IsNullOrEmpty(inTSStr))
                inTS = DateTime.Parse(inTSStr);
            return (inTS);
        }

