        public void recordDriverPunch(String truckId, String drvName, int punched, int timeZone)
        {
            // After much thought it has been decided that only login has to be done to keep things simple for the driver. A login means the 
            // prev session has been closed.
            // This is as opposed to LOGIN and LOGOUT which can confuse the drivers and lead to wrong entries and consequent issues. This will also
            // result in many wrong scenarios which the sw has to handle. 
            // LOGIN
            // Take the last entry for the day starting 5:00 am (vehicletripparams). Ideally it should have the other driver login details. 
            // If ZERO entries are found INSERT an entry with current dateTime
            // Take the last entry and close the logout for that entry and INSERT A new entry.
            // Take care of repeated logins i.e if a login happens < 2 hrs ignore it. 
            // THERE will be issues like 
            // 	LATE LOGIN
            //	MISSED LOGIN
            //  This will effect the driver who logs in correctly while the other driver does not login but it is each driver's resposibility to 
            //  see that the other logs in
            // get the from and the to datetime and decide to discard or record
            // Since this function is called from HostedServer there is no sessionId so use the truckid to get the groupid. The assumption is 
            // that the first groupid is the master groupid.

            String query = "select groupid from vehiclesgroupsmap where vehicleid = '" + truckId + "' order by groupid LIMIT 1";
            Object groupIdObj = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(groupIdObj);

            query = "select curfewEnd from vehicletripparams where groupid = " + groupId;
            Object curfewEndObj = dbx.executeScalar(query);
            if (curfewEndObj == null)
                return;
            DateTime curfewEnd = DateTime.MinValue;
            try
            {
                curfewEnd = DateTime.Parse(curfewEndObj.ToString());
            }
            catch { }
            DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
            if (now < curfewEnd) curfewEnd.AddDays(-1);
            String curfewEndStr = formatDBDate(curfewEnd);
            if (punched == 0)  // means login. Sequence is driver code followed by 0 and 0.
            {	// If there is an open login for this driver in the last 2 hours ignore it
                // else accept it
                String nowStr = formatDBDate(now);
                // Get the lastentry in twodriverdata for which the logout has not be closed for this truck. There will be many possiblities including 
                // the one where the truck has reached the destination and no logout is recorded. If a the truck is on a single driver then the single driver 
                // has to login to close the old logout of the two driver trip
                query = "select fromtime from twodriverdata where vehicleid = '" + truckId + "' and logout = 0 order by fromtime desc LIMIT 1";
                Object fromTimeObj = dbx.executeScalar(query);
                DateTime lastLogin = DateTime.MinValue;
                TimeSpan timeSinceLastLogin = new TimeSpan(0);

                if (fromTimeObj != null)
                {
                    try
                    {
                        lastLogin = DateTime.Parse(fromTimeObj.ToString());
                        timeSinceLastLogin = now - lastLogin;
                    }
                    catch { }
                }
                if (timeSinceLastLogin.TotalSeconds > 2 * 3600)
                {	// close the previous logout and insert a new login
                    //	no entries from curfewEndTime (vehicletripparams). Then insert an entry
                    //  Else close the prev entry and insert a new entry.
                    query = "select vehicleid,drivername,fromtime from twodriverdata where vehicleid = '" + truckId + "' and fromtime > '" + curfewEndStr + "' order by fromtime DESC LIMIT 1";
                    DataSet loginDS = dbx.executeQuery(query);
                    DataTable loginTab = loginDS.Tables[0];
                    if (loginTab.Rows.Count > 0)
                    {
                        String drivername = loginTab.Rows[0][1].ToString();
                        DateTime fromTime = DateTime.Parse(loginTab.Rows[0][2].ToString());
                        String fromTimeStr = formatDBDate(fromTime);
                        query = "update twodriverdata set toTime = '" + nowStr + "',logout=1 where vehicleid = '" + truckId + "' and drivername = '" +
                            drivername + "' and fromTime = '" + fromTimeStr + "';";
                        dbx.executeNonQuery(query);
                    }
                }
                if (fromTimeObj == null || timeSinceLastLogin.TotalSeconds > 2 * 3600)
                {
                    Console.WriteLine(truckId, drvName, nowStr);
                    query = "insert into twodriverdata(vehicleid,drivername,fromtime,login) values('" + truckId + "','" + drvName + "','" + nowStr + "',login=1)";
                    dbx.executeNonQuery(query);
                }
            }
        }

        public String getCurrentDriver(String vehicleId, String sessionId, int timeZone)
        {
            // To get the current active driver get the entry for the current day. The assumption is that in case of single driver the 
            // details in comttddata will be current. 
            String query = String.Empty;
            String driverName = String.Empty;
            query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
                "sessionid ='" + sessionId + "'";
            Object groupIdObj = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(groupIdObj);
            DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
            query = "select curfewEnd from vehicletripparams where groupid = " + groupId;
            Object curfewEndObj = dbx.executeScalar(query);
            if (curfewEndObj == null)
                return ("");
            DateTime curfewEnd = DateTime.MinValue;
            try
            {
                curfewEnd = DateTime.Parse(curfewEndObj.ToString());
            }
            catch { }
            if (now < curfewEnd) curfewEnd.AddDays(-1);
            String curfewEndStr = formatDBDate(curfewEnd);
            String nowStr = formatDBDate(now);
            query = "select drivername,fromtime from twodriverdata where vehicleid = '" + vehicleId + "' and fromTime >= '" + curfewEndStr +
                "' and logout= 0 order by fromtime DESC LIMIT 1";
            DataSet driverDS = dbx.executeQuery(query);
            DataTable table = driverDS.Tables[0];
            if (table.Rows.Count > 0)
            {
                driverName = table.Rows[0][0].ToString();
                return (driverName);
            }
            else
                return ("");
        }

        public Object[] getDriverNames(String vehicleId, String fromDateStr, String toDateStr)
        {
            // Drivers can login and logout at anytime and not strictly by curfewEndTime so make sure you include all entries that 
            // fall between fromDateStr and toDateStr i.e take the first entry that starts before fromDateStr but logout happens to be
            // within the timeperiod requested and also the last entry logout that falls outside the toDateStr
            String query = "select fromtime from twodriverdata where vehicleid = ? and toTime > ? order by fromtime LIMIT 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleid", vehicleId);
            lParameter.Add("toTime", fromDateStr);
            Object fromTimeObj = dbx.executeScalar(query, lParameter);
            DateTime fromTime = DateTime.MinValue;
            try
            {
                fromTime = DateTime.Parse(fromTimeObj.ToString());
            }
            catch { }
            if (fromTime != DateTime.MinValue)
                fromDateStr = formatDBDate(fromTime);
            // Now check the last entry
            query = "select toTime from twodriverdata where vehicleid = ? and fromTime < ? order by toTime DESC LIMIT 1";
            lParameter.Clear();
            lParameter.Add("vehicleid", vehicleId);
            lParameter.Add("fromTime", toDateStr);
            Object toTimeObj = dbx.executeScalar(query, lParameter);
            DateTime toTime = DateTime.MinValue;
            try
            {
                toTime = DateTime.Parse(toTimeObj.ToString());
            }
            catch { }
            if (toTime != DateTime.MinValue)
                toDateStr = formatDBDate(toTime);

            query = "select distinct drivername from twodriverdata where vehicleid = ? and fromTime >= ? and toTime <= ? ;";
            lParameter.Clear();
            lParameter.Add("vehicleid", vehicleId);
            lParameter.Add("fromTime", fromDateStr);
            lParameter.Add("toTime", toDateStr);
            DataSet drvDS = dbx.executeQuery(query, lParameter);
            DataTable table = drvDS.Tables[0];
            ArrayList drvNameList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                drvNameList.Add(row.ItemArray);
            }
            return (drvNameList.ToArray());
        }

