        public Object[] checkPanic(DateTime timeStamp)
        {
            return checkPanic(timeStamp, 0);
        }
        public Object[] checkPanic(DateTime timeStamp, int groupId = 0, string grpType = "")
        {
            string temp = GetDateTablePartitions(timeStamp, DateTime.Now, partions);
            String tsStr = formatDBDate(timeStamp);
            var lParameter = new Dictionary<string, object>();
            StringBuilder query = new StringBuilder();
            int AccId = 0;
            // If the accountgroup type is ASSET-SMART then we need to get the last entry for each of the ASSET in PANIC table
            // The issue is to get the LAST ENTRY for EACH of the ASSET so we are using the correlated SUB QUERY  here to get it.  Some ASSET may have updated more than
            // months ago
            DataSet panicInfo;

            if (grpType == "AT")
            {
                /*query.Append("select a.vehicleid, a.alertTimestamp,ackTimestamp,TYPE from panic as a where a.alerttimestamp = " +
                    "(" +
                    "select max(alerttimestamp) from panic as b where a.vehicleid = b.vehicleid and type in ('STOLEN','FASTTOSLOW') " +
                    ")" +
                    " and vehicleid in (select vehicleid from vehiclesgroupsmap where groupid = ?) and type not in ('MAIN CONNECTED', 'MAIN DISCONNECTED')" +
                    " order by a.alerttimestamp;");
                lParameter.Add("groupid", groupId);*/
                // need to get the max(alerttimestamp) of EACH ASSET-SMART device and its STATE "THEFT" avoiding MAIN DISCONNECT / CONNECT state
                query.Append("SELECT * FROM panic a WHERE vehicleid in (select vehicleid from vehiclesgroupsmap where groupid = ?) and type in ('STOLEN', 'FASTTOSLOW')" +
                             " and a.alertTimestamp = (SELECT MAX(alerttimestamp) FROM panic b WHERE b.vehicleid = a.vehicleid AND type in ('STOLEN','FASTTOSLOW')) " +
                             " ORDER BY a.vehicleId;");
                lParameter.Add("groupid", groupId);
                panicInfo = dbx.executeQuery(query.ToString(), lParameter);
            }
            else
            {
                query.Append("select * from (select distinct vehicleId,alertTimestamp,ackTimestamp,TYPE ");
                // query.Append("select distinct vehicleId,alertTimestamp,ackTimestamp,type ");
                query.Append("from panic PARTITION(" + temp + ") where (alertTimestamp > ? and acktimestamp='0000-00-00 00:00:00') ");
                lParameter.Add("alertTimestamp", tsStr);

                if (groupId != 0)
                {
                    AccId = GetAccountIdByGroupId(groupId);
                    query.Append("and vehicleId in (select vehicleId from vehiclesgroupsmap where GroupId=?) ");
                    lParameter.Add("GroupId", groupId);
                }
                query.Append("order by alertTimestamp");
                query.Append(") temp where temp.TYPE!='panic' or (temp.TYPE='panic' and temp.vehicleId not in (select vehicleid from panicerror ");
                if (AccId > 0)
                {
                    query.Append(" where accountid=? ");
                    lParameter.Add("Accountid", AccId);
                }
                query.Append("));");

                panicInfo = dbx.executeQuery(query.ToString(), lParameter);
            }
            DataTable table = panicInfo.Tables[0];
            ArrayList panicInfoList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                panicInfoList.Add(row.ItemArray);
            }
            return panicInfoList.ToArray();
        }
