        public int getbatterystatus(int BatVal)
        {
            int Batpercentage = 0;

            if (BatVal >= 407) Batpercentage = 100;
            else if (BatVal >= 397) Batpercentage = 90;
            else if (BatVal >= 392) Batpercentage = 80;
            else if (BatVal >= 385) Batpercentage = 70;
            else if (BatVal >= 377) Batpercentage = 60;
            else if (BatVal >= 369) Batpercentage = 50;
            else if (BatVal >= 363) Batpercentage = 40;
            else if (BatVal >= 358) Batpercentage = 30;
            else if (BatVal >= 353) Batpercentage = 20;
            else if (BatVal >= 346) Batpercentage = 10;
            else Batpercentage = 5;

            return Batpercentage;
        }

        public Object[] getRfidDetail(String vehicleId, String fromDateStr, String toDateStr)
