            query.Append("order by TimeStamp");
            DataSet RfidDetail = dbx.executeQuery(query.ToString());
            DataTable table = RfidDetail.Tables[0];
            ArrayList RfidList = new ArrayList();
            foreach (DataRow row in table.Rows)
