        public object[] getDriverByTransporter(String transporterName)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select * from driverdetails where transportername='" + transporterName + "'");
            DataSet derInfo = dbx.executeQuery(query.ToString());
            DataTable table = derInfo.Tables[0];


            ArrayList derInfoList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                derInfoList.Add(row.ItemArray);
            }
            //Code added to Split the drivername by |
            object[] ret = derInfoList.ToArray();
            int i = 0;
            String drivername = String.Empty;
            for (i = 0; i < ret.Length; i++)
            {
                drivername = (((Object[])ret[i])[2]).ToString();
                if (!string.IsNullOrEmpty(drivername))
                {
                    String[] drivertmp = drivername.Split('|');
                    drivername = drivertmp[0];
                    (((Object[])ret[i])[2]) = drivername;
                }
            }
            return ret;

        }

