        public void writeRuntimeResttime(string vehId, int runTime, int restTime, string date, string sessionId)
        {
            //String nowStr= DateTime.Now.ToString("yyyy-MM-dd");
            String query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
            "sessionid ='" + sessionId + "'";
            Object groupIdObj = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(groupIdObj);

            query = "select count(*) from daywisevehruntimeresttime where vehicleid = '" + vehId + "' and groupid = " + groupId + " and date = '" + date + "'";
            Object numObj = dbx.executeScalar(query);

            int num = Convert.ToInt32(numObj);
            if (num == 0)
            {
                query = "insert into daywisevehruntimeresttime(groupid,vehicleid,date,runtime,resttime) values(" + groupId + ",'" + vehId + "','" + date +
                    "'," + runTime + "," + restTime + ")";
                dbx.executeNonQuery(query);
            }
            else
            {
                query = "update daywisevehruntimeresttime set runtime = " + runTime + ",resttime=" + restTime + " where vehicleid = '" + vehId + "' and date = '" + date + "'";
                dbx.executeNonQuery(query);
            }
        }

