        public void disableTheftAlert(String Login, String Vehno, String timeStamp, String ackTime,string Remarks)
        {
            try
            {
                String query = "update lastupdtdata set TheftackTimeStamp=? where truckid=?";
                var lParameter = new Dictionary<string, object>();
                var lParameter1 = new Dictionary<string, object>();
                lParameter.Add("ackTime", ackTime);
                lParameter.Add("truckid", Vehno);
                dbx.executeNonQuery(query, lParameter);                

                query = "insert into tbl_TheftAcknowledgementLog(Asset,login,AcknowledgedTime,Remarks,GroupId) values(?,?,?,?,?)";
                lParameter1.Add("Asset", Vehno);
                lParameter1.Add("login", Login);
                lParameter1.Add("AcknowledgedTime", ackTime);
                lParameter1.Add("Remarks", Remarks);
                lParameter1.Add("GroupId", getGroupIdByLogin(Login));
                dbx.executeNonQuery(query, lParameter1);

                AddTransporterNotifications(Login, "Theft Acknowledged " + Vehno, Remarks);
            }
            catch { }
        }

        ///Created by vamsi krishna for scores of technical invariant on 2020-09-10
        /// <summary>
        /// Technical invariant scores
        /// </summary>
        /// <param name="VetID"></param>
        public DataTable GetTechnicalInvariantScores(String vetID)
        {
            String query = "select res.Category,res.Criteria,res.totalcount,res.yescount,round((res.yescount/res.totalcount)*100)  from (select v.Category,v.Criteria,"
                + "(count(*)-sum(if(c.`Status`='NA',1,0))) totalcount,sum(if(c.`Status`='Y',1,0)) yescount from veh_inv_checklist v join veh_inv_checklist_value c on "
                + "v.ID=c.chkID where c.vetID=? group by concat(v.Category,'-',v.Criteria)) res order by res.Category,res.Criteria";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vetID", vetID);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetTechnicalInvariantCategoryScores(string vetIDs, string category, string category_shortname)
        {
            string query = "select d.ID,sum(if(i.Criteria='R',if(c.`Status`='Y',1,0),0)) " + category_shortname + "_red_criteria_compliance,sum(if(i.Criteria='R',1,0)) " + category_shortname + "_total_red_criteria,"
                + "sum(if(i.Criteria='O',if(c.`Status`='Y',1,0),0)) " + category_shortname + "_orange_criteria_compliance,sum(if(i.Criteria='O',1,0)) " + category_shortname + "_total_orange_criteria from veh_inv_details d join "
                + "veh_inv_checklist_value c on c.vetID=d.ID join veh_inv_checklist i on i.ID=c.chkID and i.`Type` in ('',d.trtType,d.sttcType,d.wptType,d.hbtType,d.gteType) where d.ID in (" + vetIDs
                + ") and i.Category=? group by d.ID";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Category", category);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

