        ///Created by rajesh Sharma
        /// <summary>
        /// Get and Set the Server request
        /// </summary>
        /// <param name="truckId"></param>
        /// <returns></returns>
        public string GetSetServerRequest(string truckId)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select RequestNo, RequestMsg from serverrequests where VehicleID=\"");
            query.Append(truckId);
            query.Append("\" order by ID desc LIMIT 1;");
            DataSet serverRequests = dbx.executeQuery(query.ToString());
            DataTable request = serverRequests.Tables[0];
            if (request.Rows.Count == 0)
            {
                return null;
            }
            int requestNo = (int)(request.Rows[0].ItemArray[0]);
            string requestMsg = (string)(request.Rows[0].ItemArray[1]);
            query = new StringBuilder();
            query.Append("delete from serverrequests where VehicleID=\"");
            query.Append(truckId);
            query.Append("\" order by ID desc LIMIT 1;");
            if (!truckId.Contains("32998"))
                dbx.executeNonQuery(query.ToString());
            return requestMsg;
        }

