        public DataTable GetComplianceDetails(string type, string haulier, string vehicleId, string driverId, string compliance, int accountId)
        {
            string query = "";
            if (type == "Driver")
                query = "select v.*,d.Name DriverName,t.ShortName HaulierName from vehicle_driver_compliance_details v left join driverinfo d on "
                    + "v.DriverId=d.UserDefinedDriverId inner join transporterinfo t on t.TransporterId=d.Transporter where v.Type = ? and v.Status = ? and v.AccountId = ?";
            else if (type == "Vehicle")
                query = "select v.*,'' DriverName,t.ShortName HaulierName from vehicle_driver_compliance_details v left join vehicleinfo i on "
                    + "replace(i.VehicleId,' ','')=v.VehicleId left join transporterinfo t on t.TransporterId=i.Transporter where v.Type = ? and v.Status = ? and v.AccountId = ?";
            else if (type == "RHM")
                query = "select v.*,t.ShortName HaulierName from vehicle_driver_compliance_details v left join transporterinfo t on t.TransporterId=v.Transporter where v.Type = ? and v.Status = ? and v.AccountId = ?";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Type", type);
            lParameter.Add("Status", "Pending");
            lParameter.Add("AccountId", accountId);

            if (haulier != "")
            {
                query += " and t.ShortName=?";
                lParameter.Add("Haulier", haulier);
            }
            if (vehicleId != "")
            {
                query += " and v.VehicleId=?";
                lParameter.Add("VehicleId", vehicleId);
            }
            if (driverId != "")
            {
                query += " and v.DriverId=?";
                lParameter.Add("DriverId", driverId);
            }
            if (compliance != "")
            {
                query += " and v.ComplianceType=?";
                lParameter.Add("ComplianceType", compliance);
            }
            DataSet ds = dbx.executeQuery(query.ToString(), lParameter);
            return ds.Tables[0];
        }

