        public DataTable GetVehicleValidityDetails(string sessionId, string haulier, string vehicleId, string shellId, string TransporterId)
        {
            string username = getUserId(sessionId);
            string query = "select v.Transporter,v.UserDefId,v.VehicleId," +
                "DATE_FORMAT(v.ROTA_A,'%d-%b-%Y') AS `ROTA_A`,DATE_FORMAT(v.ROTA_B,'%d-%b-%Y') AS `ROTA_B` ," +
                "DATE_FORMAT(v.PUC,'%d-%b-%Y') AS `PUC` ,DATE_FORMAT(v.Fire_Extinguisher,'%d-%b-%Y') AS `Fire_Extinguisher` ,DATE_FORMAT(v.Goods_Permit,'%d-%b-%Y') AS `Goods_Permit` ,DATE_FORMAT(v.Explosive_License,'%d-%b-%Y') AS `Explosive_License`,DATE_FORMAT(v.Road_Tax,'%d-%b-%Y') AS `Road_Tax`,DATE_FORMAT(v.Insurance,'%d-%b-%Y') AS `Insurance`,DATE_FORMAT(v.FC,'%d-%b-%Y') AS `FC`,DATE_FORMAT(v.Calibration_certificate,'%d-%b-%Y') AS `Calibration_certificate`,DATE_FORMAT(v.Hose_Test,'%d-%b-%Y') AS `Hose_Test`,DATE_FORMAT(v.Green_Hose,'%d-%b-%Y') AS `Green_Hose`,DATE_FORMAT(v.Lifeline_Rope_Test,'%d-%b-%Y') AS `Lifeline_Rope_Test`,"
                //+ "if(count(distinct d1.FileName)>0,1,0) as 'ROTA-A_File',if(count(distinct d2.FileName)>0,1,0) as 'ROTA-B_File',"
                //+ "if(count(distinct d3.FileName)>0,1,0) as PUC_File,if(count(distinct d4.FileName)>0,1,0) as 'Fire Extinguisher_File',"
                //+ "if(count(distinct d5.FileName)>0,1,0) as 'Goods Permit_File',if(count(distinct d6.FileName)>0,1,0) as 'Explosive License_File',"
                //+ "if(count(distinct d7.FileName)>0,1,0) as 'Road Tax_File',if(count(distinct d8.FileName)>0,1,0) as Insurance_File,"
                //+ "if(count(distinct d9.FileName)>0,1,0) as FC_File,if(count(distinct d10.FileName)>0,1,0) as 'Calibration Certificate_File',"
                //+ "if(count(distinct d11.FileName)>0,1,0) as 'Hose Test_File',if(count(distinct d12.FileName)>0,1,0) as 'Lifeline Rope Test_File',"
                + "t.ShortName HaulierName,di1.Name DriverName1,di2.Name DriverName2 from vehicle_validity_data v"
                + " join vehiclesgroupsmap ve on replace(ve.VehicleID,' ','')=v.VehicleId"
                + " Left join vehicleinfo vi on replace(vi.VehicleId,' ','')=v.VehicleId"
                + " Left join transporterinfo t on t.TransporterId=vi.Transporter"
                + " Left join driverinfo di1 on replace(di1.AssignedVehicleId,' ','')=v.VehicleId and di1.DriverNo=1"
                + " Left join driverinfo di2 on replace(di2.AssignedVehicleId,' ','')= v.VehicleId and di2.DriverNo = 2"
                //+ " LEFT join vehicle_driver_compliance_details d1 on v.VehicleId = d1.VehicleId and d1.ComplianceType = 'ROTA_A' and d1.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d2 on v.VehicleId = d2.VehicleId and d2.ComplianceType = 'ROTA_B' and d2.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d3 on v.VehicleId = d3.VehicleId and d3.ComplianceType = 'PUC' and d3.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d4 on v.VehicleId = d4.VehicleId and d4.ComplianceType = 'Fire_Extinguisher' and d4.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d5 on v.VehicleId = d5.VehicleId and d5.ComplianceType = 'Goods_Permit' and d5.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d6 on v.VehicleId = d6.VehicleId and d6.ComplianceType = 'Explosive_License' and d6.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d7 on v.VehicleId = d7.VehicleId and d7.ComplianceType = 'Road_Tax' and d7.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d8 on v.VehicleId = d8.VehicleId and d8.ComplianceType = 'Insurance' and d8.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d9 on v.VehicleId = d9.VehicleId and d9.ComplianceType = 'FC' and d9.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d10 on v.VehicleId = d10.VehicleId and d10.ComplianceType = 'Calibration_Certificate' and d10.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d11 on v.VehicleId = d11.VehicleId and d11.ComplianceType = 'Hose_Test' and d11.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d12 on v.VehicleId = d12.VehicleId and d12.ComplianceType = 'Lifeline_Rope_Test' and d12.`Status`= 'Approved'"
                + " where ve.GroupId=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", getGroupId(sessionId));
            if (haulier != "" && TransporterId == "0")
            {
                query += " and v.Transporter= ?";
                lParameter.Add("Transporter", haulier);
            }
            //else if (TransporterId != "0")
            //{
            //    query += " and v.transporter=(select ShortName from transporterinfo where TransporterId=?)";
            //    lParameter.Add("Transporter", TransporterId);
            //}

            if (vehicleId != "")
            {
                query += " and v.VehicleId= ?";
                lParameter.Add("VehicleId", vehicleId);
            }
            if (shellId != "")
            {
                query += " and v.UserDefId= ?";
                lParameter.Add("UserDefId", shellId);
            }

            query += " group by v.VehicleId order by t.ShortName,v.VehicleId";
            DataSet ds = dbx.executeQuery(query.ToString(), lParameter);
            return ds.Tables[0];
        }

        public string getFileNameForCompliance(string id, string complianceType, string type)
        {
            string query = "select v.FileName from vehicle_driver_compliance_details v where ";
            if (type == "Vehicle")
                query += "v.VehicleId=? ";
            else
                query += "v.DriverId=? ";
            query += "and v.ComplianceType=? order by v.UploadedDate desc limit 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("id", id);
            lParameter.Add("ComplianceType", complianceType);
            return dbx.executeScalar(query, lParameter).ToString();
        }

