        public DataTable GetDriverValidityDetails(string sessionId, string haulier, string driverId, string TransporterId, string status)
        {
            string query = "select d.Transporter,d.UserDefinedDriverId,DATE_FORMAT(d.DL_Expiry,'%d-%b-%Y') AS `DL_Expiry`,DATE_FORMAT(d.Hazardous,'%d-%b-%Y') AS `Hazardous` ,DATE_FORMAT(d.Medical,'%d-%b-%Y') AS `Medical` ,DATE_FORMAT(d.Fire_Fighting,'%d-%b-%Y') AS `Fire_Fighting` ,DATE_FORMAT(d.First_Aid,'%d-%b-%Y') AS `First_Aid` ,DATE_FORMAT(d.DDC_Validity,'%d-%b-%Y') AS `DDC_Validity`,d.DDC_Grade"
                //+ ",count(d1.FileName) 'DL_Expiry_File',count(d2.FileName) 'Hazardous_File',count(d3.FileName) 'Medical_File',count(d4.FileName)'Fire_Fighting_File',count(d5.FileName) 'First_Aid_File',count(d6.FileName) 'DDC_Validity_File'"
                + ",di.Name 'DriverName',di.RFIDTag ,di.AssignedVehicleId 'VehicleId',t.ShortName 'HaulierName' from driver_validity_data d"
                + " join driverinfo di on di.UserDefinedDriverId=d.UserDefinedDriverId"
                + " join transporterinfo t on di.Transporter=t.TransporterId"
                //+ " LEFT join vehicle_driver_compliance_details d1 on d.UserDefinedDriverId = d1.DriverId and d1.ComplianceType = 'DL_Expiry' and d1.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d2 on d.UserDefinedDriverId = d2.DriverId and d2.ComplianceType = 'Hazardous' and d2.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d3 on d.UserDefinedDriverId = d3.DriverId and d3.ComplianceType = 'Medical' and d3.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d4 on d.UserDefinedDriverId = d4.DriverId and d4.ComplianceType = 'Fire_Fighting' and d4.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d5 on d.UserDefinedDriverId = d5.DriverId and d5.ComplianceType = 'First_Aid' and d5.`Status`= 'Approved'"
                //+ " LEFT join vehicle_driver_compliance_details d6 on d.UserDefinedDriverId = d6.DriverId and d6.ComplianceType = 'DDC_Validity' and d6.`Status`= 'Approved'"
                + " where t.AccountId=? and di.Active = 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountID", GetAccountId(sessionId));
            if (status == "Vehicle Assigned")
            {
                query += " and di.AssignedVehicleId IS NOT NULL and di.AssignedVehicleId <> ''";
            }
            else
            {
                query += " and (di.AssignedVehicleId = '' OR di.AssignedVehicleId IS NULL)";
            }

            if (haulier != "" && TransporterId == "0")
            {
                query += " and t.ShortName= ?";
                lParameter.Add("Transporter", haulier);
            }
            else if (TransporterId != "0")
            {
                query += " and t.ShortName=(select ShortName from transporterinfo where TransporterId=?)";
                lParameter.Add("Transporter", TransporterId);
            }

            if (driverId != "")
            {
                query += " and d.UserDefinedDriverId= ?";
                lParameter.Add("UserDefinedDriverId", driverId);
            }
            query += " group by d.UserDefinedDriverId order by t.ShortName,d.UserDefinedDriverId";
            DataSet ds = dbx.executeQuery(query.ToString(), lParameter);
            return ds.Tables[0];
        }
