        public bool FindIsOnTripOrNot(string vehicleid, string timestamp, string accname)
        {
            //Modified by suvarna on 4/1/2021 to record violations for NON-Nokia vendors without considering Static data
            if (accname.ToLower().Contains("nokia"))
            {
                try
                {
                    string query = "call sp_findTripOrNot(?,?)";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("vehicleid", vehicleid);
                    lParameter.Add("timestamp", timestamp);
                    string res = dbx.executeScalar(query.ToString(), lParameter).ToString();
                    if (res == "0")
                        return false;
                    else
                        return true;
                }
                catch
                {
                    return true;
                }
            }
            else
            {
                return true;
            }
        }
        public string GetUIDByVehicleIdWithoutSpace(string VehicleId)
        {
            StringBuilder query = new StringBuilder();
            string UID = String.Empty;
            query.Append("select UID from configdata where replace(TruckID,' ','') = '" + VehicleId + "'"); //INST value
            Object UIDObj = dbx.executeScalar(query.ToString());
            if (UIDObj != null)
            {
                if (!(UIDObj.Equals(System.DBNull.Value)))
                {
                    UID = UIDObj.ToString();
                    return UID;
                }
                else
                    return string.Empty;
            }
            else
            {
                return string.Empty;
            }
        }
