        public bool CheckLastReminderDate(string username, string accountid)
        {
            string query = "Select LastRememberedDate from kyc_reminder where LoginId='" + username + "'and AccountId='" + accountid + "'";
            Object obj = dbx.executeScalar(query.ToString());
            int timeZone = GetTimeZoneDiff();
            DateTime lastdate = Convert.ToDateTime("2000-10-10 00:00:00");
            DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
            if ((!Object.Equals(obj, null)) || (!Object.Equals(obj, System.DBNull.Value)))
            {
                lastdate = Convert.ToDateTime(obj.ToString());
            }
            if (DateTime.Compare(now.Date, lastdate.Date) > 0)
            {
                return false;
            }
            return true;

        }
        public int UpdateRemainder(string username, string accountid)
        {
            string query = "Select * from kyc_reminder where LoginId='" + username + "'and AccountId='" + accountid + "'";
            DataSet ds = dbx.executeQuery(query.ToString());
            int timeZone = GetTimeZoneDiff();
            DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
            if (ds.Tables[0].Rows.Count == 0)
            {
                query = "insert into  kyc_reminder(LoginId,AccountId,LastRememberedDate) values('" + username + "','" + accountid + "','" + formatDBDate(now) + "')";

            }
            else
            {
                query = "update kyc_reminder set LastRememberedDate='" + formatDBDate(now) + "' where LoginId='" + username + "' and AccountId='" + accountid + "'";
            }
            return dbx.executeNonQuery(query);

        }


        public DataSet GetNoDataVehiclesBySessionId(string sessionId, string VehicleId = "")
        {
            int timeZone = GetTimeZoneDiff(sessionId);
            DateTime now = DateTime.UtcNow.AddSeconds(timeZone).AddHours(-8);
            int groupid = getGroupId(sessionId);
            string query = "select vi.VehicleId from vehiclesgroupsmap vi where vi.GroupId=? and vi.VehicleId not in (select l.truckid from lastaccess l where l.ServerTs>?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("ServerTs", formatDBDate(now));
            DataSet ds = dbx.executeQuery(query.ToString(), lParameter);
            return ds;
        }

        protected string getAlertStr(object[] dataObj)
        {
            String retVal = String.Empty;
            for (int i = 0; i < dataObj.Length; i++)
            {
                retVal = retVal + (((Object[])dataObj[i])[0]).ToString() + "@" + Convert.ToDateTime((((Object[])dataObj[i])[1]).ToString()).ToString("dd'/'MM'/'yyyy hh:mm:ss tt") + ",";
            }
            retVal = retVal.Replace("-", "/");///-----because "-" means different
            return retVal;

        }

        public string dashBoardString(string sessionidstr, string SpeedLimit, String maxGprsDelayStr, string DashboardAccess = "")
        {
            try
            {
                StringBuilder response = new StringBuilder();
                String vehicleId = String.Empty;
                double maxSpeed = 70;
                int gid = getGroupId(sessionidstr);
                if (String.IsNullOrEmpty(SpeedLimit))
                {
                    SpeedLimit = getMaxSpeed(gid);
                    if (!String.IsNullOrEmpty(SpeedLimit))
                        maxSpeed = Convert.ToDouble(SpeedLimit);
                }
                else
                    maxSpeed = Convert.ToDouble(SpeedLimit);

                string login = getUserId(sessionidstr);
                if (login.Contains("%2inst%")) //If INST Login.
                    return string.Empty;

                int timeZone = GetTimeZoneDiff(sessionidstr);
                String maxAlertDelayStr = "3600";
                String disVehicles = String.Empty;
                String overSpeedVehicles = String.Empty;
                String panicString = String.Empty;
                String ACString = String.Empty;
                String TipperString = String.Empty;
                String speedAlertStr = String.Empty;
                String mainOffAlertStr = String.Empty;
                String batteryLowAlertStr = String.Empty;
                Object auxinputinfoObj = getAuxillaryInputInfo(sessionidstr);
                String AuxInputVehicles = String.Empty;
                String theftString = String.Empty;
                String lowbatteryforAsset = String.Empty;
                //if (ret)
                {
                    object[] vehicles = getVehicles(sessionidstr);
                    object[] disConnected = getDisconnectedVehicles(sessionidstr, Convert.ToInt32(maxGprsDelayStr));

                    int t = 0;
                    int d = 0;
                    int p = 0;
                    int o = 0;
                    int a = 0;
                    int tr = 0;
                    int m = 0;
                    int bl = 0;
                    int u = 0;
                    int r = 0;
                    int aux = 0;
                    //Added By Madhuri for theft alert for asset-30-12-2021
                    int th = 0;
                    int lowbat = 0;
                    string unScheduledStpAlrtStr = string.Empty;
                    string routeDeviationAlrtStr = string.Empty;
                    String vehUpDownslctedSTr = String.Empty;


                    #region code for ading panic alarms and AC alarms last hour
                    Object[] account = getAccountInfo(sessionidstr);
                    String acntGrpAtt = "";
                    if (account != null)
                        if (account.Length > 0)
                        {
                            acntGrpAtt = account[3].ToString();//Convert.ToString(((Object[])account[0])[3]);
                        }
                    // checkPanic will behave differently if the accountgroup belongs to ASSET-SMART
                    object[] panicInfo = null;
                    if (acntGrpAtt != "AT")
                    {
                        panicInfo = checkPanic(DateTime.UtcNow.AddSeconds(timeZone).AddSeconds(-Convert.ToInt32(maxAlertDelayStr)), gid, acntGrpAtt);
                    }
                    #endregion
                    ///////////////////////This code is written for finding all vehicles having speed violations
                    ///developed by sidharth 23-05-14
                    DateTime endDate = DateTime.UtcNow;
                    Object[] vehSpeedViolationInfo = null;
                    endDate = endDate.AddSeconds(timeZone);//for converting in to IST
                    try
