        public string GetTheftAlertList(String sessionIdstr)
        {
            String vehicleId = String.Empty;
            String theftString = String.Empty;
            StringBuilder response = new StringBuilder();
            object[] vehicles = getVehicles(sessionIdstr);
            int t = 0;
            string activeVehls = "";
            DateTime endDate = DateTime.UtcNow;
            int timeZone = GetTimeZoneDiff(sessionIdstr);
            endDate = endDate.AddSeconds(timeZone);//for converting in to IST
            for (t = 0; t < vehicles.Length; t++)
            {
                vehicleId = (String)((Object[])vehicles[t])[0];
                if (!string.IsNullOrEmpty(activeVehls))
                {
                    if (!activeVehls.Contains(vehicleId))
                        continue;
                }
                object[] theftInfo = gettheftalertdataforAsset(vehicleId);
                for (int j = 0; j < theftInfo.Length; j++)
                {
                    if ((((((Object[])theftInfo[j])[0]).ToString()).Trim()).Equals(vehicleId.Trim()))
                    {
                        if (((((Object[])theftInfo[j])[1]).ToString()).Equals("1"))
                        {
                            if ((endDate - Convert.ToDateTime(((((Object[])theftInfo[j])[2]).ToString()))).TotalSeconds < 90000)
                            {
                                theftString = theftString + vehicleId + "@" + Convert.ToDateTime((((Object[])theftInfo[j])[2]).ToString()).ToString("dd'/'MM'/'yyyy hh:mm:ss tt") + ",";
                                theftString = theftString.Replace("-", "/");///-----because "-" means different
                            }
                        }
                    }
                }
            }
            //response.Append("THEFT-");
            response.Append(theftString + "#");//list of Assets having theft alerts
            return response.ToString();
        }
        public DataSet GetCustomerStockRequestForDashBoard(string accountId, DateTime dateTime)
        {
            DateTime nowDt = DateTime.Now;
            string query = "select * from customerstockrequestlog c where c.AccountId=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountId);
            DataSet ds = dbx.executeQuery(query, lParameter);
            bool syncData = false;

            if (ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0)
                syncData = Convert.ToDateTime(ds.Tables[0].Rows[0]["LastSyncTime"].ToString()).AddHours(1) < nowDt;
            else
                syncData = true;
            if (syncData)
            {
                ds = GetCustomerStockRequest(accountId, "All", nowDt.AddMonths(-1).ToString("yyyy-MM-dd HH:mm:ss"), nowDt.ToString("yyyy-MM-dd HH:mm:ss"));
                if (ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0)
                {
                    query = "delete from customerstockrequestlog where AccountId=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("AccountId", accountId);
                    int res = dbx.executeNonQuery(query, lParameter);

                    query = "INSERT INTO `customerstockrequestlog` (`Name`, `CustomerCode`, `SafeLevel`, `Storage`, `CustomerType`, `Quantity`, `DateTime`, `customerId`,"
                                 + " `OnTransit`, `StockRequest`, `RequiredDate`, `RequestedOn`, `RequestedBy`, `DispatchBefore`, `segment`,AccountId,LastSyncTime) VALUES ";
                    lParameter = new Dictionary<string, object>();
                    for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
                    {
                        if (i != 0)
                            query += ",";
                        query += "(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
                        lParameter.Add("Name_" + i, ds.Tables[0].Rows[i]["Name"].ToString());
                        lParameter.Add("CustomerCode_" + i, ds.Tables[0].Rows[i]["CustomerCode"].ToString());
                        lParameter.Add("SafeLevel_" + i, ds.Tables[0].Rows[i]["SafeLevel"].ToString());
                        lParameter.Add("Storage_" + i, ds.Tables[0].Rows[i]["Storage"].ToString());
                        lParameter.Add("CustomerType_" + i, ds.Tables[0].Rows[i]["CustomerType"].ToString());
                        lParameter.Add("Quantity_" + i, ds.Tables[0].Rows[i]["Quantity"].ToString());
                        lParameter.Add("DateTime_" + i, string.IsNullOrEmpty(ds.Tables[0].Rows[i]["DateTime"].ToString()) ? "" : formatDBDate(Convert.ToDateTime(ds.Tables[0].Rows[i]["DateTime"].ToString())));
                        lParameter.Add("customerId_" + i, ds.Tables[0].Rows[i]["customerId"].ToString());
                        lParameter.Add("OnTransit_" + i, ds.Tables[0].Rows[i]["OnTransit"].ToString());
                        lParameter.Add("StockRequest_" + i, ds.Tables[0].Rows[i]["StockRequest"].ToString());
                        lParameter.Add("RequiredDate_" + i, string.IsNullOrEmpty(ds.Tables[0].Rows[i]["RequiredDate"].ToString()) ? "" : formatDBDate(Convert.ToDateTime(ds.Tables[0].Rows[i]["RequiredDate"].ToString())));
                        lParameter.Add("RequestedOn_" + i, string.IsNullOrEmpty(ds.Tables[0].Rows[i]["RequestedOn"].ToString()) ? "" : formatDBDate(Convert.ToDateTime(ds.Tables[0].Rows[i]["RequestedOn"].ToString())));
                        lParameter.Add("RequestedBy_" + i, ds.Tables[0].Rows[i]["RequestedBy"].ToString());
                        lParameter.Add("DispatchBefore_" + i, string.IsNullOrEmpty(ds.Tables[0].Rows[i]["DispatchBefore"].ToString()) ? "" : formatDBDate(Convert.ToDateTime(ds.Tables[0].Rows[i]["DispatchBefore"].ToString())));
                        lParameter.Add("segment_" + i, ds.Tables[0].Rows[i]["segment"].ToString());
                        lParameter.Add("AccountId" + i, accountId);
                        lParameter.Add("LastSyncTime" + i, formatDBDate(nowDt));
                    }
                    res = dbx.executeNonQuery(query, lParameter);
                }
            }
            return ds;
        }

        public bool IsRouteDeviationAllowedRegion(string accountid, string latitude, string longitude)
        {
            try
            {
                StringBuilder query = new StringBuilder();
                query.Append("select allowed, regionName,speedUp,speedDown FROM route_georegions ");
                query.Append(" where (minlatitude <= " + latitude + " ");
                query.Append("AND minLongitude <= " + longitude + " ");
                query.Append("AND maxLatitude >= " + latitude + " ");
                query.Append("AND maxLongitude >= " + longitude + ")");
                query.Append(" and acntOrGrpId = " + accountid);
                DataSet allowed = dbx.executeQuery(query.ToString());
                DataTable table = allowed.Tables[0];
                if (allowed.Tables[0].Rows.Count > 0)
                    return true;
                else
                    return false;
            }
            catch { return false; }
        }

