        public string ValidateToken(string UserName, string Token, int minLimit = 5)
        {
            string result = "true";
            DataTable dtwebtoken = dbx.executeQuery("select Id,ServerTs,NoOfReqMin,NoOfReqHour,NoOfReqDay,RejectedInMin,RejectedInHour,RejectedInDay from webservicetoken  WHERE upper(UserName) =upper('" + UserName + "') and  Token= '" + Token + "'").Tables[0];
            if (dtwebtoken.Rows.Count > 0)
            {
                DateTime LastRequest = Convert.ToDateTime(dtwebtoken.Rows[0]["ServerTs"].ToString());
                int NoOfReqMin = Convert.ToInt32(dtwebtoken.Rows[0]["NoOfReqMin"].ToString());
                int NoOfReqHour = Convert.ToInt32(dtwebtoken.Rows[0]["NoOfReqHour"].ToString());
                int NoOfReqDay = Convert.ToInt32(dtwebtoken.Rows[0]["NoOfReqDay"].ToString());

                int RejectedInMin = Convert.ToInt32(dtwebtoken.Rows[0]["RejectedInMin"].ToString());
                int RejectedInHour = Convert.ToInt32(dtwebtoken.Rows[0]["RejectedInHour"].ToString());
                int RejectedInDay = Convert.ToInt32(dtwebtoken.Rows[0]["RejectedInDay"].ToString());
                DateTime now = DateTime.Now;
                string updatereq = "NoOfReqMin=1,NoOfReqHour=1,NoOfReqDay=1";
                if (LastRequest.Day == now.Day && LastRequest.Hour == now.Hour && LastRequest.Minute == now.Minute)
                {
                    NoOfReqMin++; NoOfReqHour++; NoOfReqDay++;
                    updatereq = "NoOfReqMin=" + NoOfReqMin + ",NoOfReqHour=" + NoOfReqHour + ",NoOfReqDay=" + NoOfReqDay;
                    if (NoOfReqMin > minLimit && (NoOfReqHour / now.Minute) > minLimit && now.Minute >= 7)
                    {
                        result = "FAIL:OVER_QUERY_LIMIT";
                        RejectedInMin++;
                        if (LastRequest.Day == now.Day && LastRequest.Hour == now.Hour)
                            RejectedInHour++;
                        if (LastRequest.Day == now.Day)
                            RejectedInDay++;
                    }
                }
                else if (LastRequest.Day == now.Day && LastRequest.Hour == now.Hour)
                {
                    RejectedInMin = 0;
                    NoOfReqHour++; NoOfReqDay++;
                    updatereq = "NoOfReqMin=1,NoOfReqHour=" + NoOfReqHour + ",NoOfReqDay=" + NoOfReqDay;
                }
                else if (LastRequest.Day == now.Day)
                {
                    NoOfReqDay++;
                    RejectedInMin = 0;
                    RejectedInHour = 0;
                    updatereq = "NoOfReqMin=1,NoOfReqHour=1,NoOfReqDay=" + NoOfReqDay;
                }
                else
                {
                    RejectedInMin = 0;
                    RejectedInHour = 0;
                    RejectedInDay = 0;
                }
                updatereq = updatereq + ",RejectedInMin=" + RejectedInMin + ",RejectedInHour=" + RejectedInHour + ",RejectedInDay=" + RejectedInDay;
                dbx.executeNonQuery("Update webservicetoken set " + updatereq + ",ServerTs='" + now.ToString("yyyy-MM-dd HH:mm:ss") + "' WHERE Id=" + dtwebtoken.Rows[0]["Id"].ToString());
            }
            else
            {
                result = "Authentication failure";
            }
            return result;

        }
