            Object len = dbx.executeScalar(query_fst.ToString());
            int ln = Convert.ToInt32(len.ToString());
            if (ln != 0)
                query = "update vehicletripparams set maxSpeed=" + speedLim + " , allowedMaxSpeedDur=0, changeDate=\"" + DateTime.Now.ToString("yyyy-MM-dd") + "\"" + " where groupId=" + gid;
