                query = "insert into vehicletripparams (shortRunDuration,shortRestDuration,longRunDuration,curfewStart,curfewEnd,shortRunDuration2,shortRestDuration2,maxSpeed,groupId,changeDate) values (0,0,0,'','',0,0," + speedLim + "," + gid + ",\"" + DateTime.Now.ToString("yyyy-MM-dd") + "\")";
