        public Object[] Geofence(String vehicleId, String tblName)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("truckId", vehicleId);
            if (tblName == "geofence")
            {
                query.Append("select id,geofencename,truckid,minlatitude,minlongitude,maxlatitude,maxlongitude,lastviolation,smsphone,smsmessage,email_id,inorout,noofpoints,lat1,lng1,lat2,lng2,lat3,lng3,lat4,lng4,lat5,lng5,lat6,lng6,lat7,lng7,lat8,lng8,lat9,lng9 from geofence ");
                query.Append("where truckId = ? and noofpoints= 4");
            }
            else if (tblName == "plantgeolocations")
            {
                query.Append("select accountid from vehicles where vehicleid = ?");
                Object accIdObj = dbx.executeScalar(query.ToString(), lParameter);
                if (accIdObj == null)
                    return null;
                int accId = Convert.ToInt32(accIdObj);
                query.Clear();
                lParameter.Clear();
                query.Append("select accountid,locstr,emailid,minlatitude,minlongitude,maxlatitude,maxlongitude,`type` from plantgeolocations where accountid = ? and minlatitude <>0.0");
                lParameter.Add("accountid", accId);

                //query.Append("where truckId = '" + vehicleId);
                //query.Append("'");
            }
            DataSet geofence = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = geofence.Tables[0];
            ArrayList geofencelist = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                geofencelist.Add(row.ItemArray);
            }
            return geofencelist.ToArray();
        }

