        public String getLastPanicInfo(String vehicleId, string timestamp)
        {
            DateTime fromdate = DateTime.Now.AddDays(-10);
            DateTime todate = DateTime.Now;
            string temp = GetDateTablePartitions(fromdate, todate, partions);
            StringBuilder query = new StringBuilder();
            query.Append("select `type` from panic PARTITION(" + temp + ") where vehicleId ='" + vehicleId + "' and ");
            query.Append("alertTimeStamp=(select max(alertTimeStamp) from panic PARTITION(" + temp + ") where vehicleId ='" + vehicleId + "'");
            if (!string.IsNullOrEmpty(timestamp))
                query.Append(" and alertTimeStamp<'" + timestamp + "' and type like 'MAIN%')");
            else
                query.Append(" and type like 'MAIN%')");
            Object panicInfo = dbx.executeScalar(query.ToString());
            return Convert.ToString(panicInfo);
        }


