        /// <summary>
        /// Insert Solar Data from Solar TCP Parser
        /// </summary>
        /// <param name="uid"></param>
        /// <param name="ID"></param>
        /// <param name="V1"></param>
        /// <param name="V2"></param>
        /// <param name="I1"></param>
        /// <param name="I2"></param>
        /// <param name="D"></param>
        /// <param name="SEQ"></param>
        /// <param name="timeStamp"></param>
        public void writesolarData(int uid, int ID, float V1, float V2, float I1, float I2, float D, int SEQ, DateTime timeStamp)
        {
            StringBuilder query = new StringBuilder();
            string truckId = String.Empty;
            query.Append("select TruckId from configdata where uid = " + uid); //INST value
            Object truckIdObj = dbx.executeScalar(query.ToString());
            if (!(truckIdObj.Equals(System.DBNull.Value)))
                truckId = truckIdObj.ToString();
            else
                return;
            string timeStampStr = formatDBDate(timeStamp);
            query.Length = 0;
            query.Append("insert into solardata (UID,ID,V1,V2,I1,I2,D,SEQ,TimeStamp) values(");
            query.Append("'" + truckId + "'" + "," + ID + "," + V1 + "," + V2 + "," + I1 + "," + I2 + "," + D + "," + SEQ + "," + "'" + timeStampStr + "'" + ");");

            //Console.WriteLine(query.ToString());
            try
            {
                dbx.executeNonQuery(query.ToString());
            }
            catch (System.Data.Odbc.OdbcException e)
            {
                throw e;
                return;
            }

        }

        /// <summary>
        ///Code Added by : Gopal.S
        ///Date & Time : 02/08/2014 02:57 PM
        ///Reason for Adding : Send the Alert Email vehicle Moves at Specific Confg. Time Period (Untime Vehicle Movement)
        /// </summary>
        public System.Collections.Generic.List<object> getAlertMailforVehicleMovement(int CheckingTimePeriod, DateTime StartDate, DateTime ToDate)
        {
            string query = string.Empty;
            string truckId = String.Empty;
            //Getting users who are having Vehicle Movement Alert.Here If AlertType=1 :Vehicle Movement
            query = "select v.curfewStart,v.curfewEnd,v.groupId from vehicletripparams v" +
                  " where (v.curfewStart!=Null and v.curfewEnd!=Null) or (v.curfewStart!='' and v.curfewEnd!='') and AlertFlag=1"; //Who are having This Alert for Untime Vechicle Movement  
            DataSet ds = dbx.executeQuery(query.ToString());
            //Creating Generic List (AlertList)
            System.Collections.Generic.List<object> Alertlist = new System.Collections.Generic.List<object>();

            for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
            {
                //Getting Curfewstart and Curfewend for TimePeriod
                DateTime tsStart;
                DateTime tsEnd;
                if (DateTime.TryParse(ds.Tables[0].Rows[i]["curfewStart"].ToString(), out tsStart))
                {
                    tsStart = Convert.ToDateTime(StartDate.ToString("yyyy-MM-dd") + " " + ds.Tables[0].Rows[i]["curfewStart"].ToString());

                }
                if (DateTime.TryParse(ds.Tables[0].Rows[i]["curfewEnd"].ToString(), out tsEnd))
                {
                    tsEnd = Convert.ToDateTime(StartDate.ToString("yyyy-MM-dd") + " " + ds.Tables[0].Rows[i]["curfewEnd"].ToString());

                }
                if (tsStart > tsEnd)
                {
                    if (DateTime.Now > tsEnd)
                        tsEnd = tsEnd.AddDays(1);
                    else
                        tsStart = tsStart.AddDays(-1);

                }
                //Getting Vehicles from vehiclesgroupsmap by GroupId
                string subquery = string.Empty;
                subquery = "select GroupId,VehicleId from vehiclesgroupsmap where GroupId=" + ds.Tables[0].Rows[i]["groupId"].ToString();
                DataSet dsVeichles = dbx.executeQuery(subquery);

                DataSet dsVoilation = new DataSet();
                for (int j = 0; j < dsVeichles.Tables[0].Rows.Count; j++)
                {
                    DateTime StartPeriod = StartDate.AddMinutes(-CheckingTimePeriod);
                    if (StartPeriod < tsStart)
                        StartPeriod = tsStart;
                    //Getting all Route Data by Vehicle Id,Start and End Time.
                    DataTable dt = getRoutebyDate(dsVeichles.Tables[0].Rows[j]["vehicleId"].ToString(), tsStart.ToString("yyyy-MM-dd HH:mm:ss"), tsEnd.ToString("yyyy-MM-dd HH:mm:ss"));
                    //Variable Declaration
                    bool Movflag = false;//If Vehicle Moved It will get true;
                    TimeSpan duration = new TimeSpan(0, 0, 0);//Vehicle Moving Time Continuously
                    DateTime lastVioTime = new DateTime();//Last Violation Time In this Period of Time
                    int RowId = 0;
                    for (int k = 0; k < dt.Rows.Count; k++)
                    {
                        if (Convert.ToDecimal(dt.Rows[k]["Speed"].ToString()) > 3 && dt.Rows[k]["Stop"].ToString() == "0")//If Vehicle Speed more than 3 kmh ;We are considering Vehicle is Moving. 
                        {
                            if (Movflag == false)
                            {
                                Movflag = true;
                                duration = new TimeSpan(0, 0, 0);
                                lastVioTime = Convert.ToDateTime(dt.Rows[k]["Timestamp"].ToString());
                                RowId = k;
                            }
                            else
                            {

                                Movflag = true;
                                RowId = k;
                                duration += lastVioTime - Convert.ToDateTime(dt.Rows[k]["Timestamp"].ToString());
                                lastVioTime = Convert.ToDateTime(dt.Rows[k]["Timestamp"].ToString());
                                if (duration.Minutes >= 5)//If Vehicle is moving Continuously 5 min .we breaking this loop.and decide in this Period contains vehicle movement.
                                    break;

                            }
                        }
                        else
                        {

                            Movflag = false;
                            duration = new TimeSpan(0, 0, 0);
                        }

                    }

                    if (dsVoilation.Tables.Count == 0)
                        dsVoilation.Tables.Add(dt.Clone()); //Getting the Structure of Violation Table for retrun a result;as a this format.
                    if (Movflag == true && duration.Minutes >= 5)//If Vehicle moved 5 mins and Move Flag is true,than Vehicle is moved in this Period.
                    {
                        //Checking the alert table for last violation of this Vehicle.
                        query = "select TruckId from alerts where  LastViolation='" + Convert.ToDateTime(dt.Rows[RowId]["TimeStamp"].ToString()).ToString("yyyy-MM-dd HH:mm:ss") + "'  and TruckId='" + dsVeichles.Tables[0].Rows[j]["vehicleId"].ToString() + "' and AlertType=1";
                        DataTable dsAlert = dbx.executeQuery(query).Tables[0];
                        if (dsAlert.Rows.Count == 0)//If no Record.Adding the data inti violation table.
                        {
                            dsVoilation.Tables[0].Rows.Add(dsVoilation.Tables[0].NewRow());
                            dsVoilation.Tables[0].Rows[dsVoilation.Tables[0].Rows.Count - 1]["id"] = dt.Rows[RowId]["id"].ToString();
                            dsVoilation.Tables[0].Rows[dsVoilation.Tables[0].Rows.Count - 1]["TruckId"] = dt.Rows[RowId]["TruckId"].ToString();
                            dsVoilation.Tables[0].Rows[dsVoilation.Tables[0].Rows.Count - 1]["TimeStamp"] = dt.Rows[RowId]["TimeStamp"].ToString();
                            dsVoilation.Tables[0].Rows[dsVoilation.Tables[0].Rows.Count - 1]["Start"] = dt.Rows[RowId]["Start"].ToString();
                            dsVoilation.Tables[0].Rows[dsVoilation.Tables[0].Rows.Count - 1]["Stop"] = dt.Rows[RowId]["Stop"].ToString();
                            dsVoilation.Tables[0].Rows[dsVoilation.Tables[0].Rows.Count - 1]["Latitude"] = dt.Rows[RowId]["Latitude"].ToString();
                            dsVoilation.Tables[0].Rows[dsVoilation.Tables[0].Rows.Count - 1]["Longitude"] = dt.Rows[RowId]["Longitude"].ToString();
                            dsVoilation.Tables[0].Rows[dsVoilation.Tables[0].Rows.Count - 1]["Speed"] = dt.Rows[RowId]["Speed"].ToString();

                        }

                    }



                }

                if (dsVoilation.Tables.Count != 0)
                {
                    if (dsVoilation.Tables[0].Rows.Count != 0)
                    {
                        //If any violation avilable in this Case ,adding Vehicletripparam and Violation data into Generic List.
                        Alertlist.Add(ds.Tables[0].Rows[0]);
                        Alertlist.Add(dsVoilation);
                    }
                }



            }
            //retrun the violation list
            return Alertlist;

        }
        //Inserting the alert data.
        public void insertAlert(string VehicleID, string Latitude, string Longitude, string email, string UpdatedTime, string Speed)
        {
            //Checking the Vehicle is available in alert table
            StringBuilder chkquery = new StringBuilder();
            chkquery.Append("select id from alerts where TruckID='" + VehicleID + "' and email_id='" + email + "' and AlertType=1");
            object id = dbx.executeScalar(chkquery.ToString());
            StringBuilder query = new StringBuilder();
            //If no data for that Vehicle ,Insert as new record
            if (id == null)
            {
                query.Append("insert into alerts (TruckID,MinLatitude, MinLongitude,LastViolation,alertTs,email_id,speedingThrshKmph,AlertType) values(");
                query.Append("'" + VehicleID + "','" + Latitude + "','" + Longitude + "','" + UpdatedTime + "','" + DateTime.Now.AddHours(5.5).ToString("yyyy-MM-dd HH:mm:ss") + "','" + email + "','" + Speed + "',1)");
            }
            //If data is avilable for that Vehicle ,Updating as the record by ID
            else
            {
                query.Append("Update alerts Set MinLatitude='" + Latitude + "', MinLongitude='" + Longitude + "',LastViolation='" + UpdatedTime + "',alertTs='" + DateTime.Now.AddHours(5.5).ToString("yyyy-MM-dd HH:mm:ss") + "',speedingThrshKmph='" + Speed + "' ");
                query.Append("where ID=" + id.ToString());
            }
            dbx.executeNonQuery(query.ToString());
        }
        public DataTable getRoutebyDate(String vehicleId, String fromDateStr, String toDateStr)
        {
            //Getting Rout Data by Date and vehicle Id.
            string pos_part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            string track_part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), track_partions);
            StringBuilder query = new StringBuilder();
            query.Append("select t.id, DATE_FORMAT(p.timestamp, '%d %b %y, %r'),Start, Stop, Latitude, Longitude, Speed, HEX(AlarmData), p.timestamp, FuelLevel, Altitude, IdlingDuration, Distance,p.truckId ");
            query.Append("from trackerdata PARTITION(" + track_part + ") AS t join positiondata PARTITION(" + pos_part + ") AS p on t.id = p.id and t.TruckID = p.TruckID ");
            query.Append("where p.truckId ='" + vehicleId + "' ");
            if (fromDateStr != null)
            {
                query.Append("and TimeStamp >= \"" + fromDateStr + "\" ");
            }
            if (toDateStr != null)
            {
                query.Append("and TimeStamp <= \"" + toDateStr + "\" ");
            }
            query.Append("order by TimeStamp Desc");
            DataSet routeLatLong = dbx.executeQuery(query.ToString());
            return routeLatLong.Tables[0];

        }
