        public DataTable CheckIfvehNumberExists(string vehicle)
        {
            int startIndex = vehicle.Length - 4;
            int length = 4;
            string lastFourLetters = vehicle.Substring(startIndex, length);

            string query = "SELECT * FROM metro_market_vehicles m WHERE m.Active = 1 AND m.VehicleId like '%" + lastFourLetters + "%'";
