        // Check if the metro transporter vehicle is blocked- Added By Sahana on 28/03/2024 
        public bool IsMetroTransporterVehicleBlocked(string vehicleNo)
        {
            try
            {
                string query = "SELECT V.Blocked from metro_market_vehicles V where REPLACE(V.VehicleId, ' ', '')= ? ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleNo", vehicleNo.Replace(" ", ""));
                string res = dbx.executeScalar(query.ToString(), lParameter).ToString();
                if (res == "TRUE")
                    return true;
                else
                    return false;
            }
            catch (Exception e)
            {
                return false;
            }
        }
