        //Get all invoice by account id  created By Tusar 
        public DataSet MetroGetInvoicesDetails(String sessionId, string Transpoterid)
        {
            string username = getUserId(sessionId);
            int storeNo = Convert.ToInt32(getMetroStoreNo(username));
            int accountId = GetAccountId(sessionId);
            string query = "SELECT DISTINCT r.RouteId,c.CustomerId,c.CustomerName,i.TaxInvoiceNum as InvoiceNum,i.OrderDateTime,i.Priority,i.InvoiceType,a.Address,c.custType,t.TransporterId,t.Name,i.StoreNo FROM metro_invoice_details as i " +
                            " INNER JOIN metro_customers_info as c ON i.CustomerId = c.CustomerId  AND i.StoreNo = c.StoreNo" +
                            " LEFT JOIN metro_customer_address as a on i.AddressId = a.AddressId " +
                            " LEFT JOIN metro_route_table as r ON i.RouteId = r.RouteId " +
                            " LEFT JOIN transporterinfo as t ON i.TransporterId = t.TransporterId " +
                            " WHERE i.IsDeleted = 0 AND i.AccountId =?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountId);
            if (storeNo != 0)
            {
                query += " and i.StoreNo=?";
                lParameter.Add("StoreNo", storeNo);
            }
            if (Transpoterid != "0")
            {
                query += " and i.TransporterId=? and a.Address<>'null'";
                lParameter.Add("Transpoterid", Transpoterid);
            }
            query += " AND i.TripSheetNo = '' AND i.OrderDateTime between DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -7 DAY) and DATE_ADD(CURRENT_TIMESTAMP, INTERVAL 1 DAY) ORDER BY i.OrderDateTime DESC";
            DataSet dsInvoices = dbx.executeQuery(query, lParameter);
            return dsInvoices;
        }
        public DataSet MetroGetInvoiceProductDetails(string invoiceNumber)
        {
            string query = "SELECT p.ProductId,m.productName,p.Amount,p.TotalQuantity,p.TaxPercentage,p.TotalTaxAmount," +
                "ROUND((p.TotalTaxAmount * p.TaxPercentage / 100), 2) AS 'TaxAmount', (ROUND((p.TotalTaxAmount * p.TaxPercentage / 100), 2) + p.TotalTaxAmount) AS 'TotalAmount' FROM metro_invoice_products p " +
                "INNER JOIN metro_products m ON m.productId = p.ProductId " +
                "WHERE p.InvoiceId = ?";
            var lParameter = new Dictionary<string, object>();
