        public DataSet MetroGetTripSheet(String sessionId, String Transpoterid)
        {
            int accountId = GetAccountId(sessionId);
            string username = getUserId(sessionId);
            int storeNo = Convert.ToInt32(getMetroStoreNo(username));
            //string query = "SELECT mtd.Id as Trip_No,mtd.TripNum as TripSheetNum,mtd.TripDate as DateTime,COUNT(mi.CustomerId) as No_Of_Customer,mrt.RouteName,mtd.VehicleID " +
            //                "FROM metro_trip_details mtd LEFT JOIN metro_invoice_details mi ON mi.TripId = mtd.Id " +
            //                "LEFT JOIN metro_route_table mrt ON mrt.RouteId = mtd.RouteId " +
            //                "LEFT JOIN vehicles v ON v.VehicleID = mtd.VehicleId " +
            //                "WHERE mtd.IsDeleted = 0 AND mi.AccountId =?";
            string query = "SELECT mtd.Id as Trip_No,mtd.TripNum as TripSheetNum,mtd.TripDate as DateTime,mtd.Trip_Status as Status,COUNT(DISTINCT mi.TaxInvoiceNum) as No_Of_Customer,mrt.RouteName,mtd.VehicleID,concat(v.DriverName,'-',v.Mobile) as Driver " +
                           "FROM metro_trip_details mtd LEFT JOIN metro_invoice_details mi ON mi.TripId = mtd.Id " +
                           "LEFT JOIN metro_route_table mrt ON mrt.RouteId = mtd.RouteId " +
                           "LEFT JOIN metro_market_vehicles v ON v.VehicleId = mtd.VehicleId " +
                           "WHERE mtd.IsDeleted = 0 AND mtd.TripDate between DATE_ADD(CURRENT_TIMESTAMP, INTERVAL -1 DAY) AND DATE_ADD(CURRENT_TIMESTAMP, INTERVAL 1 DAY) AND mi.AccountId =?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountId);
            if (Transpoterid != "0")
            {
                query += " and mtd.TransporterId=?";
                lParameter.Add("Transpoterid", Transpoterid);
            }
            if (storeNo != 0)
            {
                query += " and mi.StoreNo=?";
                lParameter.Add("StoreNo", storeNo);
            }

            query += " group by mi.TripId order by mtd.TripDate desc";

            DataSet dstrips = dbx.executeQuery(query, lParameter);
            return dstrips;
        }

