        public DataTable MetroGetCustomersAddressByLocations(string addessid, string latitude, string longitude, string pincode)
        {
            string lat = latitude.Substring(0, latitude.Length - 3);
            string lon = longitude.Substring(0, longitude.Length - 3);

            string query = "select a.AddressId from metro_customer_address a where a.AddressId != '" + addessid + "' and a.Latitude like '%" + lat + "%' and a.Longitude like '%" + lon + "%' and a.Pincode = '" + pincode + "' ORDER BY a.AddressId DESC LIMIT 5";

            var lParameter = new Dictionary<string, object>();
            DataTable dtTable = dbx.executeQuery(query).Tables[0];
            if (dtTable != null && dtTable.Rows.Count > 0)
            {
                return dtTable;
            }
            else
            {
                query = "select a.AddressId from metro_customer_address a where a.AddressId != '" + addessid + "' and a.Pincode = '" + pincode + "' ORDER BY a.AddressId DESC LIMIT 5";
                dtTable = dbx.executeQuery(query).Tables[0];
                return dtTable;
            }

        }
        public DataSet MetroGetTripReportDetails(string StoreNo, DateTime tripsStartAt, DateTime tripsEndAt)
        {
            //string query = "SELECT mtd.Id as TripId,mtd.TripNum,mtd.TripDate,mtd.Trip_Status,mtd.VehicleId,mtd.Distance,mtd.NoOfCustomers,mtd.NoOfInvoices,mtd.NoOfShipperBoxes,m.VehicleType,m.DriverName,m.Mobile FROM metro_trip_details mtd " +
            //    "LEFT JOIN transporterinfo t ON t.TransporterId = mtd.TransporterId " +
            //    "LEFT JOIN metro_market_vehicles m ON m.VehicleId = mtd.VehicleId " +
            //    "WHERE mtd.TripDate BETWEEN ? AND ? AND m.Active = 1 AND mtd.StoreNo = ? AND mtd.IsByMetro = 2 AND mtd.IsDeleted = 0 " +
            //    "GROUP BY mtd.Id ORDER BY mtd.TripDate DESC";
            string query = "SELECT mtd.StoreNo, mtd.TripNum,date_format(mtd.TripDate,'%d-%m-%Y %H:%i:%S') as TripDate,mtd.PaymentType ,mtd.Trip_Status,mtd.VehicleId,m.VehicleType,m.Transporter,m.Capacity,mtd.Distance,mtd.NoOfCustomers,mtd.NoOfInvoices,m.DriverName,m.Mobile,if(mtd.DriverId != 0, 'Yes', 'No') AS 'AppUsage',sum(m2.TotalPrice) as 'TripCost',sum(m2.TotalWeight) as 'TripWeight',Concat(FORMAT(Round(sum(m2.TotalWeight)/(m.Capacity * 1000)*100),2),'%') as'VehicleUtilizationPercentage' FROM metro_trip_details mtd " +
                "LEFT JOIN transporterinfo t ON t.TransporterId = mtd.TransporterId " +
                "LEFT JOIN metro_market_vehicles m ON m.VehicleId = mtd.VehicleId " +
                "LEFT JOIN metro_invoice_details  m2 ON m2.TripId =mtd.Id " +
                "WHERE mtd.TripDate BETWEEN ? AND ? AND m.Active = 1 AND mtd.StoreNo = ? AND mtd.IsByMetro = 2 AND mtd.IsDeleted = 0 GROUP BY mtd.Id ORDER BY mtd.TripDate DESC";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("tripsStartAt", formatDBDate(tripsStartAt));
            lParameter.Add("tripsEndAt", formatDBDate(tripsEndAt));
            lParameter.Add("StoreNo", StoreNo);
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;
        }
