        public DataSet MetroGetTripSheetDetails(string StoreNo, string TripDate)
        {
            DateTime dt;
            try
            {
                dt = DateTime.ParseExact(TripDate, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);

            }
            catch
            {
                dt = Convert.ToDateTime(TripDate);
            }
            DateTime tripsStartAt = dt.Date.AddHours(00).AddMinutes(00).AddSeconds(01);
            DateTime tripsEndAt = dt.Date.AddHours(23).AddMinutes(59).AddSeconds(59);
            //string query = "SELECT mtd.Id as TripId,mtd.TripNum,mtd.TripDate,mtd.Trip_Status,mtd.VehicleId,t.ShortName AS `Transporter`,mtd.DispatchMode," +
            //    "mtd.RouteId,mtd.Distance,mtd.NoOfCustomers,mtd.NoOfInvoices,mtd.NoOfShipperBoxes," +
            //    "mtd.TotalAmount,mtd.TotalDeliveryCharge,mtd.StoreNo,mtd.Trip_Status_Updated_On,mtd.Trip_Closed_On,mtd.IsByMetro FROM metro_trip_details mtd " +
            //    "LEFT JOIN transporterinfo t ON t.TransporterId = mtd.TransporterId " +
            //    "WHERE mtd.TripDate between ? and ? and mtd.StoreNo = ? order by mtd.TripNum";
            string query = "SELECT distinct mtd.Id as TripId,mtd.TripNum,date_format(mtd.TripDate,'%d-%m-%Y %H:%i:%S') as `TripDate`,mtd.Trip_Status,mtd.VehicleId,mmv.VehicleType,mmv.DriverName,mmv.Mobile,t.ShortName AS `Transporter`,mtd.DispatchMode,mtd.RouteId,mtd.Distance,mtd.NoOfCustomers,mtd.NoOfInvoices,mtd.NoOfShipperBoxes,mtd.TotalAmount,mtd.TotalDeliveryCharge,mtd.StoreNo,date_format(mtd.Trip_Status_Updated_On,'%d-%m-%Y %H:%i:%S') as `Trip_Status_Updated_On`,date_format(mtd.Trip_Closed_On,'%d-%m-%Y %H:%i:%S') as `Trip_Closed_On`,mtd.Trip_Closed_By,mtd.IsByMetro FROM metro_trip_details mtd " +
                "LEFT JOIN transporterinfo t ON t.TransporterId = mtd.TransporterId " +
                "LEFT JOIN metro_market_vehicles mmv ON mmv.VehicleId = mtd.VehicleId AND mmv.StoreNo = mtd.StoreNo ";
            //"WHERE mtd.TripDate BETWEEN ? and ? and mtd.StoreNo = ? AND mmv.Active = 1 order by mtd.TripNum";

            if (StoreNo == "60")
                query += "WHERE mtd.TripDate BETWEEN ? and ? and mtd.StoreNo in (59,60) AND mmv.Active = 1 order by mtd.TripNum";
            else
                query += "WHERE mtd.TripDate BETWEEN ? and ? and mtd.StoreNo = ? AND mmv.Active = 1 order by mtd.TripNum";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("tripsStartAt", formatDBDate(tripsStartAt));
            lParameter.Add("tripsEndAt", formatDBDate(tripsEndAt));
            lParameter.Add("StoreNo", StoreNo);
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;
        }
