        //To asign  invoice to a transporter -created By Tusar 
        public void MetroAsignInvoiceToTransporter(string sessionid, string[] InvoiceNum, string TranspoterID)
        {
            string userId = getUserId(sessionid);
            string update_query = "Update metro_invoice_details mid set mid.TransporterId=? where mid.TaxInvoiceNum in (";
            string insert_query = "Insert into metro_invoice_transpoter_mapping(`TransporterId`, `InvoiceNum`, `InvoiceStatus`, `ModifiedDate`,AddedBy) values";
            var lParameter = new Dictionary<string, object>();
            var lParameter_insert = new Dictionary<string, object>();
            string now = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            lParameter.Add("TranspoterID", TranspoterID);
            for (int i = 0; i < InvoiceNum.Length; i++)
            {
                update_query += "?";
                lParameter.Add("TaxInvoiceNum" + i, InvoiceNum[i]);
                insert_query += "(?,?,?,?,?)";
                lParameter_insert.Add("TranspoterID" + i, TranspoterID);
                lParameter_insert.Add("TaxInvoiceNum" + i, InvoiceNum[i]);
                lParameter_insert.Add("InvoiceStatus" + i, "Asigned");
                lParameter_insert.Add("ModifiedDate" + i, now);
                lParameter_insert.Add("AddedBy" + i, userId);
                if (i == InvoiceNum.Length - 1)
                {
                    update_query += ")";
                    insert_query += ";";
                }
                else
                {
                    update_query += ",";
                    insert_query += ",";
                }
            }
            dbx.executeNonQuery(update_query, lParameter);
            dbx.executeNonQuery(insert_query, lParameter_insert);
        }
        public void MetroAsignInvoiceToCustomerAddress(string sessionid, string InvoiceNum, string AddressId)
        {
            string userId = getUserId(sessionid);
            string update_query = "Update metro_invoice_details mid set mid.AddressId= ? where mid.TaxInvoiceNum = ?";
            var lParameter = new Dictionary<string, object>();
            string now = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            lParameter.Add("AddressId", AddressId);
            lParameter.Add("TaxInvoiceNum", InvoiceNum);
            dbx.executeNonQuery(update_query, lParameter);
        }
        //To Delete Metro Invoice -created By Tusar 
        public void MetroDeleteInvoice(string username, string InvoiceNum, string reason)
        {
            string query = "UPDATE metro_invoice_details mid SET mid.IsDeleted = 1, mid.DeletedBy = ?, mid.ReasonForDelete = ? ";
            query += "WHERE mid.TaxInvoiceNum= ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("username", username);
            lParameter.Add("reason", reason);
            lParameter.Add("TaxInvoiceNum", InvoiceNum);
            dbx.executeNonQuery(query, lParameter);
        }
        //To Delete Metro Trip Sheet -created By Tusar 
        public void MetroDeleteTripSheet(string username, string TripNo, string reason)
        {
            string query = "UPDATE metro_trip_details mtd SET mtd.IsDeleted = 1, mtd.DeletedBy = ?, mtd.ReasonForDelete = ? ";
            query += "WHERE mtd.Id= ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("DeletedBy", username);
            lParameter.Add("ReasonForDelete", reason);
            lParameter.Add("TripNum", TripNo);
            dbx.executeNonQuery(query, lParameter);

            string updatequery = "UPDATE metro_invoice_details mid SET mid.TripId = 0,mid.TripSheetNo = ''  ";
            updatequery += "WHERE mid.TripId= ?";
            var uParameter = new Dictionary<string, object>();
            uParameter.Add("TripId", TripNo);
            dbx.executeNonQuery(updatequery, uParameter);
        }
