        //To Update Metro Customer Info & Addresses
        public void Update_Metro_CustomerInfo(string sessionid, Metro_CustomerInfo objMetroCustomer)
        {
            string username = getUserId(sessionid);
            int storeNo = Convert.ToInt32(getMetroStoreNo(username));
            int accountId = GetAccountId(sessionid);

            string query = "UPDATE metro_customers_info SET CustomerName = ?, custType = ?, MobileNo = ?, EmailId = ?";
            query += " WHERE CustomerId = ? AND StoreNo = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("CustomerName", objMetroCustomer.CustomerName);
            lParameter.Add("custType", objMetroCustomer.custType);
            lParameter.Add("MobileNo", objMetroCustomer.MobileNo);
            lParameter.Add("EmailId", objMetroCustomer.Email);
            lParameter.Add("CustomerId", objMetroCustomer.CustomerId);
            lParameter.Add("storeNo", storeNo);
            dbx.executeNonQuery(query, lParameter);



            List<Metro_CustomerAddress> mca = objMetroCustomer.Addresses;

            for (int i = 0; i < mca.Count; i++)
            {
                try
                {
                    DeleteCustomerDistanceMatrix(mca[i].AddressId);
                    string latitude = mca[i].Latitude;
                    string longitude = mca[i].Longitude;
                    string res = getMMIGeoCodeLatLng(mca[i].Address.Trim());
                    if (!string.IsNullOrEmpty(res) && res != "No Data" && res.Contains(","))
                    {
                        latitude = res.Split(',')[0];
                        longitude = res.Split(',')[1];
                    }
                    query = "UPDATE metro_customer_address SET Address = ?, Latitude = ?, Longitude = ?, ModifiedBy =?";
                    query += " WHERE AddressId = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Address", mca[i].Address);
                    lParameter.Add("Latitude", latitude);
                    lParameter.Add("Longitude", longitude);
                    lParameter.Add("ModifiedBy", username);
                    lParameter.Add("AddressId", mca[i].AddressId);
                    dbx.executeNonQuery(query, lParameter);
                }
                catch { }
            }
        }

        public void Insert_Metro_CustomerAddress(string sessionid, Metro_CustomerAddress objMetroCustomerAddress)
        {
            DeleteCustomerDistanceMatrix(objMetroCustomerAddress.AddressId);
            string username = getUserId(sessionid);
            int storeNo = Convert.ToInt32(getMetroStoreNo(username));
