            if (!String.IsNullOrEmpty(objMetroCustomerAddress.Address))
            {
                string res = getMMIGeoCodeLatLng(objMetroCustomerAddress.Address.Trim());
                if (!string.IsNullOrEmpty(res) && res != "No Data" && res.Contains(","))
                {
                    string query = "INSERT INTO metro_customer_address (CustomerId,MobileNo,StoreNo,Address,Pincode,Latitude,Longitude,DetentionTime,DeliveryTime,ModifiedBy)";
                    query += " VALUES (?,?,?,?,?,?,?,?,?,?)";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("CustomerId", objMetroCustomerAddress.CustomerId);
                    lParameter.Add("MobileNo", objMetroCustomerAddress.Mobile);
                    lParameter.Add("StoreNo", storeNo);
                    lParameter.Add("Address", objMetroCustomerAddress.Address);
                    lParameter.Add("Pincode", objMetroCustomerAddress.Pincode);
                    lParameter.Add("Latitude", res.Split(',')[0]);
                    lParameter.Add("Longitude", res.Split(',')[1]);
                    lParameter.Add("DetentionTime", 30);
                    lParameter.Add("DeliveryTime", "16:40:00");
                    lParameter.Add("ModifiedBy", username);
                    dbx.executeNonQuery(query, lParameter);
                }
                else
                {
                    string lat = "0.000000";
                    string lon = "0.000000";
                    string query = "SELECT a.Latitude,a.Longitude from metro_customer_address a where a.StoreNo=? and a.Pincode=? ORDER BY a.ModifiedTime DESC LIMIT 1";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("StoreNo", storeNo);
                    lParameter.Add("Pincode", objMetroCustomerAddress.Pincode);
                    DataTable dtLocationDetails = dbx.executeQuery(query, lParameter).Tables[0];
                    if (dtLocationDetails != null && dtLocationDetails.Rows.Count > 0)
                    {
                        lat = dtLocationDetails.Rows[0]["Latitude"].ToString();
                        lon = dtLocationDetails.Rows[0]["Longitude"].ToString();
                    }

                    query = "INSERT INTO metro_customer_address (CustomerId,MobileNo,StoreNo,Address,Pincode,Latitude,Longitude,DetentionTime,DeliveryTime,ModifiedBy)";
