        public string MetroUpdateTripInvoiceStatus(string taxinvoiceno, string status, string reason)
        {
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
            String query = "";
            int tripId = 0;
            var lParameter = new Dictionary<string, object>();
            if (status != "Cancel")
            {
                try
                {
                    query = "update metro_invoice_details set Delivery_Status=?,Delivery_Status_Updated_On=?,Reason=? where TaxInvoiceNum=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Delivery_Status", status);
                    lParameter.Add("Delivery_Status_Updated_On", formatDBDate(now));
                    lParameter.Add("Reason", reason);
                    lParameter.Add("invoiceno", taxinvoiceno);
                    return dbx.executeNonQuery(query, lParameter).ToString();
                }
                catch { return "-1"; }
            }
            else
            {
                try
                {
                    query = "update metro_invoice_details set TripId=?,TripSheetNo=?,Reason=? where TaxInvoiceNum=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("TripId", tripId);
                    lParameter.Add("TripSheetNo", "");
                    lParameter.Add("Reason", reason);
                    lParameter.Add("invoiceno", taxinvoiceno);
                    return dbx.executeNonQuery(query, lParameter).ToString();
                }
                catch { return "-1"; }
            }
        }


        public void MetroCloseAllTrips(string sessionid, DateTime tripDate)
        {
            DateTime tripsStartTime = tripDate.Date.AddDays(-1).AddHours(00).AddMinutes(00).AddSeconds(01);
            DateTime tripsEndTime = tripDate.Date.AddHours(23).AddMinutes(45).AddSeconds(00);
            string query = "UPDATE metro_trip_details SET Trip_Status = ?, Trip_Closed_On = ?, Trip_Closed_By = ?";
            query += " WHERE TripDate between ? and ? and Trip_Status != ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TripStatus", "Closed");
            lParameter.Add("TripClosedOn", formatDBDate(tripsEndTime));
            lParameter.Add("TripClosedBy", "System");
            lParameter.Add("tripsStartTime", formatDBDate(tripsStartTime));
            lParameter.Add("tripsEndTime", formatDBDate(tripsEndTime));
            lParameter.Add("Status", "Closed");
            dbx.executeNonQuery(query, lParameter);
        }

