        public DataTable GetVehiclesInTrip(string login, string sessionId, DateTime tripDate)
        {
            DateTime tripsStartTime = tripDate.Date.AddHours(00).AddMinutes(00).AddSeconds(01);
            DateTime tripsEndTime = tripDate.Date.AddHours(23).AddMinutes(45).AddSeconds(00);
            string query = "select distinct m.VehicleId from vehiclesgroupsmap v " +
                "inner join usersgroupsmap u on v.GroupId = u.GroupId " +
                "inner join accountgroups a on a.GroupId = v.GroupId " +
                "inner join metro_market_vehicles m on m.VehicleId = REPLACE(v.vehicleid, ' ', '') " +
                "inner join metro_trip_details t on t.VehicleId = m.VehicleId " +
                "where v.VehicleId IN(select distinct p.vehicleid from vehicleinplant p where p.intimestamp > DATE_ADD(t.Trip_Status_Updated_On, INTERVAL 0 HOUR)) " +
                "AND a.AccountID = 2737 and u.Login = ?  and t.Trip_Status_Updated_On between ? and ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("login", login);
            lParameter.Add("tripsStartTime", tripsStartTime);
            lParameter.Add("tripsEndTime", tripsEndTime);
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails.Tables[0];
        }

