        public DataTable GetMetroVehiclesInGeofence(string vehicleid, string tripDate)
        {
            string query = "SELECT REPLACE (vp.vehicleid,' ','') AS `VehicleId` FROM vehicleinplant vp " +
                "INNER JOIN geofencenew gn ON gn.geofencename = vp.locationstr " +
                "INNER JOIN metro_store_geofence sg ON gn.ID = sg.GeofenceId " +
                "WHERE REPLACE (vp.vehicleid,' ','') = ? AND vp.intimestamp > DATE_ADD(?, INTERVAL 1 HOUR) " +
                "ORDER BY vp.intimestamp DESC LIMIT 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleid", vehicleid);
            lParameter.Add("intimestamp", formatDBDate(Convert.ToDateTime(tripDate)));
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails.Tables[0];
        }
        public DataTable GetMetroVehiclesInTrip()
        {
            string query = "SELECT distinct mtd.VehicleId,mtd.TripDate,mtd.TripNum,mtd.StoreNo,mtd.Trip_Status " +
                 "FROM metro_trip_details mtd " +
                 //"INNER JOIN vehiclesgroupsmap m ON REPLACE(m.VehicleId,' ','') = mtd.VehicleId " +
                 "WHERE mtd.TripDate >= DATE_ADD(CURDATE(), INTERVAL 0 DAY) AND mtd.Trip_Status != 'Closed' " +
                 "order by mtd.TripNum,mtd.StoreNo";

