        public DataSet MetroGetStorewiseDriverAppUsageSummaryReport(string fromTripDate, string toTripDate)
        {
            string query = "select DATE_FORMAT(mtd.TripDate, '%d/%m/%Y') as `Date`,mid.StoreNo as `Store No`,count(distinct mid.CustomerId) as `No Of Customers`,count(distinct mid.TripSheetNo) as `No Of Trips`," +
                "count(distinct mid.latlng) as `No Of LatLong Captured` ,concat(round(( count(distinct mid.latlng)/count(distinct mid.CustomerId) * 100 ),2),'%') AS `Percentage No Of LatLong Captured` " +
                "from metro_invoice_details mid " +
                "inner join metro_trip_details mtd on mtd.TripNum = mid.TripSheetNo " +
                "where mtd.TripDate between ? and ? group by mid.StoreNo";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromTripDate", fromTripDate);
            lParameter.Add("toTripDate", toTripDate);
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;
        }

        public DataSet MetroGetStorewiseDriverAppUsageDetailsReport(string fromTripDate, string toTripDate)
        {
            string query = "SELECT mtd.StoreNo,mtd.TripNum as 'Trip Number',mtd.TripDate as 'Trip Date',mtd.VehicleId as 'Vehicle',mkv.DriverName as 'Driver Name',mkv.Mobile as 'Driver Mobile',mtd.Trip_Status as 'Trip Status'," +
                "mtd.Trip_Closed_By  as `Trip Closed By`,mtd.Trip_Closed_On as `Trip Closed On`,mid.CustomerId as 'Customer ID',mci.CustomerName,mca.CustomerAddressId as 'Customer Address ID',mca.Address as 'Address'," +
                "mca.Latitude,mca.Longitude,mid.TaxInvoiceNum,mid.OrderDateTime,mid.Delivery_Status as 'Delivery Status',mid.Delivery_Status_Updated_On as `Delivered On` from metro_trip_details mtd " +
                "inner join metro_invoice_details mid on mtd.Id = mid.TripId " +
                "inner join metro_customer_address mca on mid.AddressId = mca.AddressId " +
                "inner join metro_customers_info mci on mid.CustomerId = mci.CustomerId " +
                "inner join metro_market_vehicles mkv on mkv.VehicleId = mtd.VehicleId " +
                "where mtd.TripDate between ? and ? and mtd.Trip_Status = 'Closed' and mkv.Active = 1 order by mtd.TripNum";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromTripDate", fromTripDate);
            lParameter.Add("toTripDate", toTripDate);
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;
        }

        //To Generate Metro Trip Sheet
        public string GenerateTripSheet(string sessionid, Metro_TripInfo objMetroTrip, long estimatedTripDistance, string TripSheetNo, string StoreNo, string isByMetro, string routingBy, string routingFor, string tripsFor, string paymentType)
        {
            string now = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string query = "INSERT INTO metro_trip_details (TransporterId,VehicleId,RouteId,Distance,TripDate,TripNum,NoOfShipperBoxes,StoreNo,IsByMetro,RoutingBy,RoutingFor,TripsFor,PaymentType)";
            query += " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TransporterId", objMetroTrip.TransporterId);
            lParameter.Add("VehicleId", objMetroTrip.VehicleId);
            lParameter.Add("RouteId", objMetroTrip.RouteId);
            lParameter.Add("Distance", estimatedTripDistance);
            lParameter.Add("TripDate", formatDBDate(DateTime.Now));
            lParameter.Add("TripNum", TripSheetNo);
            lParameter.Add("NoOfShipperBoxes", objMetroTrip.ShipperBox);
            lParameter.Add("StoreNo", StoreNo);
            lParameter.Add("IsByMetro", isByMetro);
            lParameter.Add("RoutingBy", routingBy);
            lParameter.Add("RoutingFor", routingFor);
            lParameter.Add("TripsFor", tripsFor);
            lParameter.Add("PaymentType", paymentType);
            dbx.executeNonQuery(query, lParameter);

            query = "SELECT MAX(Id) as Id FROM metro_trip_details";
            DataSet dsTripId = dbx.executeQuery(query);
            string TripId = dsTripId.Tables[0].Rows[0][0].ToString();
            List<Metro_TripInvoices> mti = objMetroTrip.Invoices;
            for (int i = 0; i < mti.Count; i++)
            {
                try
                {
                    query = "UPDATE metro_invoice_details SET TripId = ?,TripSheetNo=?,DeliveryOrder=?";
                    query += " WHERE TaxInvoiceNum = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("TripId", TripId);
                    lParameter.Add("TripSheetNo", TripSheetNo);
                    lParameter.Add("DeliveryOrder", i);
                    lParameter.Add("TaxInvoiceNum", mti[i].InvoiceNum);
                    dbx.executeNonQuery(query, lParameter);
                }
                catch { }
            }
            return TripId;
        }

        //To Generate Metro Invoice Transfer Trip Sheet
        public string GenerateInvoiceTransferTripSheet(string sessionid, string TransporterId, string VehicleId, string estimatedTripDistance, string TripSheetNo, string StoreNo, string isByMetro)
        {
            string now = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string query = "INSERT INTO metro_trip_transfer_details (TransporterId,VehicleId,Distance,TripDate,TripNum,StoreNo,IsByMetro)";
            query += " VALUES (?,?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TransporterId", TransporterId);
            lParameter.Add("VehicleId", VehicleId);
            lParameter.Add("Distance", estimatedTripDistance);
            lParameter.Add("TripDate", formatDBDate(DateTime.Now));
            lParameter.Add("TripNum", TripSheetNo);
            lParameter.Add("StoreNo", StoreNo);
            lParameter.Add("IsByMetro", isByMetro);
            dbx.executeNonQuery(query, lParameter);

            query = "SELECT MAX(Id) as Id FROM metro_trip_transfer_details";
            DataSet dsTripId = dbx.executeQuery(query);
            string TripId = dsTripId.Tables[0].Rows[0][0].ToString();

            try
            {
                query = "UPDATE metro_invoice_transfer_details SET TripId = ?,TripSheetNo=?";
                query += " WHERE StoreNo = ? and TripId = 0";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("TripId", TripId);
                lParameter.Add("TripSheetNo", TripSheetNo);
                lParameter.Add("StoreNo", StoreNo);
                dbx.executeNonQuery(query, lParameter);
            }
            catch (Exception ex) { }

            return TripId;
        }
        public DataTable MetroInvoiceTransferTripSheetHeaderData(String TripId)
        {
            string query = "SELECT mtd.VehicleId,m.VehicleName AS VehicleInfo,m.Capacity,mtd.Id as TripNo,DATE_FORMAT(mtd.TripDate,'%d-%m-%Y %H:%i:%s') as TripDate,m.DriverName,m.Mobile as MobileNo,mrt.Places,mtd.Distance FROM metro_trip_transfer_details mtd " +
