        public DataTable MetroPendingInvoices(String storeNo)
        {
            string query = "SELECT m.*,mci.CustomerName,mca.DeliveryTime,datediff(current_date,m.OrderDateTime) as Age " +
                "FROM metro_invoice_details m " +
                "INNER JOIN metro_customers_info mci ON m.CustomerId = mci.CustomerId " +
                "INNER JOIN metro_customer_address mca ON m.AddressId = mca.AddressId " +
                "WHERE m.OrderDateTime <= subdate(current_date, 1) and m.Delivery_Status IS NULL and m.StoreNo = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StoreNo", storeNo);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable MetroSelfDeliveredInvoices(String storeNo, String orderDate)
        {
            DateTime dt;
            try
            {
                dt = DateTime.ParseExact(orderDate, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);

            }
            catch
            {
                dt = Convert.ToDateTime(orderDate);
            }
            DateTime orderStartAt = dt.Date.AddHours(00).AddMinutes(00).AddSeconds(01);
            DateTime orderEndAt = dt.Date.AddHours(23).AddMinutes(59).AddSeconds(59);
            string query = "SELECT DISTINCT s.StoreNo FROM metro_invoice_details s WHERE s.OrderDateTime BETWEEN ? and ? AND s.TripId =1";
            if (!String.IsNullOrEmpty(storeNo))
            {
                query = "SELECT s.StoreNo,s.TaxInvoiceNum,s.OrderDateTime,s.Delivery_Status_Updated_On,s.Delivery_Status,s.Reason FROM metro_invoice_details s WHERE s.OrderDateTime BETWEEN ? and ? AND s.TripId =1";
            }

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("orderStartAt", formatDBDate(orderStartAt));
            lParameter.Add("orderEndAt", formatDBDate(orderEndAt));
            if (!String.IsNullOrEmpty(storeNo))
            {
                query += " AND s.StoreNo = ?";
                lParameter.Add("StoreNo", storeNo);
            }
            query += " ORDER BY s.StoreNo,s.OrderDateTime";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
