        public DataTable MetroGetTripInvoiceDetailsByTripSheetNo(string tripsheetno)
        {
            string query = "SELECT m.TripNum AS `TripSheetNo`,DATE_FORMAT(m.TripDate, '%d/%m/%Y %H:%i:%s') AS `TripDate`,i.TaxInvoiceNum AS `InvoiceNo`,IFNULL(i.Delivery_Status,'Pending') AS `DeliveryStatus`," +
                "i.CustomerId AS `CustomerId`,p.ProductId AS `ArticleNo`,a.Description AS `ArticleDetails`,p.TotalQuantity AS `TotalQty`,(p.TotalQuantity - IFNULL(p.ReturnedQty, 0)) AS `DeliveredQty`,IFNULL(p.ReturnedQty, 0) AS `ReturnedQty` FROM metro_invoice_details i " +
                "INNER JOIN metro_invoice_products p ON p.InvoiceId = i.TaxInvoiceNum " +
