            lParameter.Add("TripSheetNo", tripsheetno);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public double GetGPSorCANSpeed(double GPSSpeed, double VehicleSpeed, double CANSpeed_Calibration_Val)
        {
            try
            {
                bool CANEnabled = false;
                if (CANSpeed_Calibration_Val > 0)
                {
                    if (VehicleSpeed > 1 && GPSSpeed > 0 && VehicleSpeed < 900)
                    {
                        CANEnabled = true;
                        VehicleSpeed = VehicleSpeed / CANSpeed_Calibration_Val;
                        if (VehicleSpeed > 70)
                            CANEnabled = false;
                    }
                }
                if (CANEnabled == true)
                {
                    if (Math.Abs(GPSSpeed - VehicleSpeed) > 5)
                    {
                        if (VehicleSpeed > GPSSpeed && GPSSpeed > 1 && GPSSpeed <= 60)
                            CANEnabled = false;
                        else if (VehicleSpeed < GPSSpeed && VehicleSpeed <= 60)
                            CANEnabled = true;
                        else if (GPSSpeed < 1 && VehicleSpeed > GPSSpeed && VehicleSpeed < 60)
                            CANEnabled = true;
                        else if (VehicleSpeed > GPSSpeed)
                            CANEnabled = false;
                        else
                            CANEnabled = true;
                    }
                }
                if (CANEnabled)
                    return VehicleSpeed;
                else
                    return GPSSpeed;
            }
            catch
            {
                return GPSSpeed;
            }
        }
