        public DataTable MetroGetLatLong(Metro_TripInfo data)
        {
            string[] invoices = new string[data.Invoices.Count];
            List<Metro_TripInvoices> mti = data.Invoices;
            for (int i = 0; i < mti.Count; i++)
            {
                invoices[i] = mti[i].InvoiceNum;
            }

            string query = "SELECT mid.StoreNo,mid.AddressId,msi.Latitude as SrcLatitude,msi.Longitude as SrcLongitude,if(mca.Latitude='0.0000000',msi.Latitude,"
                + "mca.Latitude) as DestLatitude,if(mca.Longitude='0.0000000',msi.Longitude,mca.Longitude) as DestLongitude " +
                "FROM metro_invoice_details mid " +
                "INNER JOIN metro_stores_info msi ON mid.StoreNo = msi.StoreNo " +
                "INNER JOIN metro_customer_address mca ON mid.AddressId = mca.AddressId " +
                "WHERE mid.TaxInvoiceNum IN(";
            var lParameter = new Dictionary<string, object>();
            for (int i = 0; i < invoices.Length; i++)
            {
                lParameter.Add("TaxInvoiceNum" + i, invoices[i]);
                query += "?";
                if (i == invoices.Length - 1)
                {
                    query += ")";
                }
                else
                {
                    query += ",";
                }
            }
            return dbx.executeQuery(query, lParameter).Tables[0];

        }
