        public int UpdateDriversForVehicle(string sessionid, string vehicleId, int existingDriverId1, string existingDriverName1, string existingRfid1, string newdriverId1, string newdriverName1, string rfid1, string rfid1_new, int existingDriverId2, string existingDriverName2, string existingRfid2, string newdriverId2, string newdriverName2, string rfid2, string rfid2_new, string type)
        {
            DateTime now = DateTime.UtcNow;
            now = now.AddSeconds(GetTimeZoneDiff());
            string username = getUserId(sessionid);
            string Transpoterid = getTransporterIdByLogin(username);
            string AccountId = GetAccountId(sessionid).ToString();
            string query = "update driverinfo d set d.AssignedVehicleId='' where d.DriverId= ? and d.AccountId= ?";
            insertauditdata("Edit", "driverinfo", "AssignedVehicleId", vehicleId);
            var lParameter = new Dictionary<string, object>();
            if (newdriverId1 != existingDriverId1.ToString())
            {
                lParameter.Add("DriverId", existingDriverId1);
                lParameter.Add("AccountId", AccountId);
                dbx.executeNonQuery(query, lParameter);
            }
            if (newdriverId2 != existingDriverId2.ToString())
            {
                lParameter = new Dictionary<string, object>();
                lParameter.Add("DriverId", existingDriverId2);
                lParameter.Add("AccountId", AccountId);
                dbx.executeNonQuery(query, lParameter);
            }
            try
            {
                string updatequery = "update drivervehiclelog set Todate=? where Todate is NULL and Vehicleid=? and Driverid !=? and Driverid != ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Todate", formatDBDate(now));
                lParameter.Add("Vehicleid", vehicleId);
                lParameter.Add("driverId1", newdriverId1);
                lParameter.Add("driverId2", newdriverId2);
                Convert.ToInt16(dbx.executeNonQuery(updatequery, lParameter));
            }
            catch { }
            string ApproveBy = "";
            if (true)
            {
                ApproveBy = "System";
                string active_rifd = "";
                //Driver1 Update
                try
                {
                    if (newdriverId1 != "0")
                    {
                        lParameter = new Dictionary<string, object>();
                        string updatequery = "update driverinfo set AssignedVehicleId=?,DriverNo=1,Approve=1";
                        lParameter.Add("AssignedVehicleId", vehicleId);
                        if (!string.IsNullOrEmpty(rfid1_new))
                        {
                            updatequery += ",RFIDTag=?";
                            lParameter.Add("rfid1_new", rfid1_new);
                            //Replace RFID1 in Device
                            active_rifd = rfid1_new;
                        }
                        else
                        {
                            active_rifd = rfid1;
                        }
                        updatequery += " where Driverid = ?";
                        lParameter.Add("driverId1", newdriverId1);
                        Convert.ToInt16(dbx.executeNonQuery(updatequery, lParameter));
                    }
                }
                catch { }

                //Driver2 Update
                try
                {
                    if (newdriverId2 != "0")
                    {
                        lParameter = new Dictionary<string, object>();
                        string updatequery = "update driverinfo set AssignedVehicleId=?,DriverNo=2,Approve=1";
                        lParameter.Add("AssignedVehicleId", vehicleId);
                        if (!string.IsNullOrEmpty(rfid2_new))
                        {
                            updatequery += ",RFIDTag=?";
                            lParameter.Add("rfid2_new", rfid2_new);
                            active_rifd = active_rifd + "," + rfid2_new;
                        }
                        else
                        {
                            active_rifd = active_rifd + "," + rfid2;
                        }
                        updatequery += " where Driverid = ?";
                        lParameter.Add("driverId2", newdriverId2);
                        Convert.ToInt16(dbx.executeNonQuery(updatequery, lParameter));
                    }
                }
                catch { }
                if (!string.IsNullOrEmpty(active_rifd))

                    addServerRequest(vehicleId, 5, "(ACT RFIDLIST )");
                addServerRequest(vehicleId, 5, "(ACT RFIDLIST )");
                //Order Changed as per the Server Request Execute in LIFO method by Tusar on 29/04/2021
                addServerRequest(vehicleId, 5, "(ACT RFIDREPLACE " + active_rifd + ")");

                //RFID Update
                try
                {
                    string updatequery = "update driverinfo set RFIDTag='' where Driverid != ? and RFIDTag=?";
                    if (!string.IsNullOrEmpty(rfid1_new))
                    {
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("driverId1", newdriverId1);
                        lParameter.Add("rfid1_new", rfid1_new);
                        Convert.ToInt16(dbx.executeNonQuery(updatequery, lParameter));
                    }
                    if (!string.IsNullOrEmpty(rfid2_new))
                    {
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("driverId2", newdriverId2);
                        lParameter.Add("rfid2_new", rfid2_new);
                        Convert.ToInt16(dbx.executeNonQuery(updatequery, lParameter));
                    }
                }
                catch { }
            }

            if (newdriverId1 != "0")
                AssignVehicletoDriver(Convert.ToInt32(newdriverId1), vehicleId);
            if (newdriverId2 != "0")
                AssignVehicletoDriver(Convert.ToInt32(newdriverId2), vehicleId);

            query = "update driverchangelog set `Status`=? where VehicleId=? and `Status`='Under Process'";
            var Parameter = new Dictionary<string, object>();
            Parameter.Add("Status", "Done");
            Parameter.Add("VehicleId", vehicleId);
            dbx.executeNonQuery(query, Parameter);


            string insertquery = "INSERT INTO driverchangelog (VehicleId,ExistingDriverID1,ExistingDriverName1,ExistingDriverRfid1,NewDriverId1,NewDriverName1,NewDriverRfId1,NewDriverRfid1_change, " +
                                 "ExistingDriverID2, ExistingDriverName2,ExistingDriverRfid2, NewDriverId2, NewDriverName2, NewDriverRfid2,NewDriverRfid2_change, " +
                                 "RequestType, RequestDate, Status, TransporterId, AccountId,ApproveBy,RequestedBy)";
            insertquery += " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";

            var insertParameter = new Dictionary<string, object>();
            insertParameter.Add("VehicleId", vehicleId);
            insertParameter.Add("ExistingDriverID1", existingDriverId1);
            insertParameter.Add("ExistingDriverName1", existingDriverName1);
            insertParameter.Add("ExistingDriverRfid1", existingRfid1);
            insertParameter.Add("NewDriverId1", newdriverId1);
            insertParameter.Add("NewDriverName1", newdriverName1);
            insertParameter.Add("NewDriverRfId1", rfid1);
            insertParameter.Add("NewDriverRfId1_new", rfid1_new);
            insertParameter.Add("ExistingDriverID2", existingDriverId2);
            insertParameter.Add("ExistingDriverName2", existingDriverName2);
            insertParameter.Add("ExistingDriverRfid2", existingRfid2);
            insertParameter.Add("NewDriverId2", newdriverId2);
            insertParameter.Add("NewDriverName2", newdriverName2);
            insertParameter.Add("NewDriverRfid2", rfid2);
            insertParameter.Add("NewDriverRfid2_new", rfid2_new);
            insertParameter.Add("RequestType", type);
            insertParameter.Add("RequestDate", now);
            if (string.IsNullOrEmpty(ApproveBy))
                insertParameter.Add("Status", "Pending");
            else
                insertParameter.Add("Status", "Under Process");
            insertParameter.Add("TransporterId", Transpoterid);
            insertParameter.Add("AccountId", AccountId);
            insertParameter.Add("ApproveBy", ApproveBy);
            insertParameter.Add("RequestedBy", username);
            int res = dbx.executeNonQuery(insertquery, insertParameter);
            return res;
        }
