        public DataTable GetDriverChangeHistory(int groupid, string username)
        {
            string date = formatDBDate(System.DateTime.Now.AddDays(-2));
            string query = "SELECT dc.ID,dc.VehicleId,t.Name as Transporter,dc.ExistingDriverID1,dc.ExistingDriverName1,dc.ExistingDriverRfid1,dc.NewDriverId1,dc.NewDriverName1,IF(NewDriverRfid1_change='',dc.NewDriverRfId1,dc.NewDriverRfid1_change) as NewDriverRfId1," +
                            "dc.ExistingDriverID2,dc.ExistingDriverName2,dc.ExistingDriverRfid2,dc.NewDriverId2,dc.NewDriverName2,IF(NewDriverRfid2_change='',dc.NewDriverRfid2,dc.NewDriverRfid2_change) as NewDriverRfid2,dc.RequestType," +
                            "DATE_FORMAT(dc.RequestDate, '%d/%m/%Y %H:%i:%s') AS RequestDate, ApproveBy, DATE_FORMAT(dc.ApproveDate, '%d/%m/%Y %H:%i:%s') AS ApproveDate," +
                            " dc.Status,dc.TransporterId,dc.AccountId,dc.RequestedBy FROM driverchangelog dc " +
                            "LEFT JOIN transporterinfo t ON dc.TransporterId = t.TransporterId";
            query += " WHERE (dc.RequestedBy = ? or dc.VehicleId in (select VehicleId from vehiclesgroupsmap where GroupId=?))";
            query += " and (dc.RequestDate>? or dc.Status!='Done')";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("RequestedBy", username);
            lParameter.Add("groupid", groupid);
            lParameter.Add("date", date);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

