        public int updateviolation(string[] v, string[] s, string[] n, string[] c, string[] m, string[] h, string date)
        {
            StringBuilder Query = new StringBuilder();
            DataTable ds = getincentivepoints().Tables[0];
            int negative_points = 0;
            for (int i = 0; i < v.Length - 1; i++)
            {
                v[i] = v[i].Trim();
                negative_points = 0;
                if (c[i] != "")
                    negative_points = negative_points + Convert.ToInt32(ds.Rows[10][4]);
                if (s[i] != "")
                    negative_points = negative_points + Convert.ToInt32(ds.Rows[7][4]);
                if (n[i] != "")
                    negative_points = negative_points + Convert.ToInt32(ds.Rows[8][4]);
                if (m[i] != "")
                    negative_points = negative_points + Convert.ToInt32(ds.Rows[9][4]);
                if (h[i] != "")
                    negative_points = negative_points + Convert.ToInt32(ds.Rows[11][4]);

                var lParameter = new Dictionary<string, object>();
                Query.Append("update daywisetmpvehviosummary set cd=?,  maxsp=?," +
                    "  nd=?,  md=?, harshBraking=?, negativepoints=?, points_earned=(positivepoints - ?) where vehicleid=? and date=?;");
                lParameter.Add("cd", c[i]);
                lParameter.Add("maxsp", s[i]);
                lParameter.Add("nd", n[i]);
                lParameter.Add("md", m[i]);
                lParameter.Add("harshBraking", h[i]);
                lParameter.Add("negativepoints", negative_points);
                lParameter.Add("positivepoints", negative_points);
                lParameter.Add("vehicleid", v[i]);
                lParameter.Add("date", date);
                dbx.executeNonQuery(Query.ToString(), lParameter);
                Query.Clear();
                Query.Append("update daywisevehviosummary set cd=?,  maxsp=?," +
                    "  nd=?,  md=?, harshBraking=?, negativepoints=?, points_earned=(positivepoints - ?) where vehicleid=? and date=?;");
                //lParameter.Add("cd", c[i]);
                //lParameter.Add("maxsp", s[i]);
                //lParameter.Add("nd", n[i]);
                //lParameter.Add("md", m[i]);
                //lParameter.Add("harshBraking", h[i]);
                //lParameter.Add("negativepoints", negative_points);
                //lParameter.Add("positivepoints", negative_points);
                //lParameter.Add("vehicleid", v[i]);
                //lParameter.Add("date", date);
                dbx.executeNonQuery(Query.ToString(), lParameter);
            }
            return 1;
        }
        //for driver app
        public DataRow[] PlacesData(string curlat, string curlong, string type, string radius = "0.10")
        {
            double curlat1 = Convert.ToDouble(curlat);
            double curlong1 = Convert.ToDouble(curlong);
            DataRow[] places;
            StringBuilder Query = new StringBuilder();
            if (type == "6")
            {

                Query.Append("select accountid as Id,'Parking' as Name,'6' as Type,w.locstr as Address,'0' as Phone,(w.minlat+w.maxlat)/2 as Latitude,(w.minlong+w.maxlong)/2 as Longitude from waypointsref w "
                              + " where commands='(ACT PLAYAU 3 )' AND abs((w.minlat+w.maxlat)/2 -'" + curlat1 + "')<='" + radius + "' AND abs((w.minlong+w.maxlong)/2 -'" + curlong1 + "')<='" + radius + "' ");

            }
            else
            {
                Query.Append("select *  from places where abs(Latitude-'" + curlat1 + "')<='" + radius + "' AND abs(Longitude-'" + curlong1 + "')<='" + radius + "' AND Type='" + type + "'");

            }
            DataSet data = dbx.executeQuery(Query.ToString());
            if (data.Tables[0].Rows.Count < 1 && Convert.ToDouble(radius) <= 0.50)
            {
                double r = Convert.ToDouble(radius) + 0.20;
                places = PlacesData(curlat, curlong, type, r.ToString());
            }
            else
            {
                places = new DataRow[data.Tables[0].Rows.Count];
                data.Tables[0].Rows.CopyTo(places, 0);
            }
            return places;
        }
