        //for driver app
        public string SourceDestination(string IMEI)
        {
            string source = "";
            string destination = "";
            //find source


            StringBuilder Query = new StringBuilder();
            Query.Append("select sd.Source,sd.Destination from driverinfo di " +
                         "inner join vehicledctrip vt on vt.VehicleID=di.AssignedVehicleId " +
                         "inner join customerdcassign ad on ad.DCTripId=vt.id " +
                         "inner join customerinfo ci on ci.customerid=ad.customerid " +
                         "inner join customerroute cr on cr.customerid=ci.CustomerCode " +
                         "inner join sourcedestinationmap sd on sd.Id=cr.routeid " +
                         "where vt.IsTripEnds=false AND vt.IsCancel=false AND di.IMEI='" + IMEI + "'" +
                         "order by cr.distance desc ");

            DataSet data = dbx.executeQuery(Query.ToString());
            if (data.Tables[0].Rows.Count > 0)
            {
                source = data.Tables[0].Rows[0][0].ToString();
                destination = data.Tables[0].Rows[0][1].ToString();
            }


            return source + "," + destination;

        }
