        //for driver app
        public DataRow[] GetjrmSpots(string IMEI, string val)
        {
            DataSet data = null;
            if (val == "dashboard")
            {
                string vehicle = GetVehilceByIMEI(IMEI);
                string query = "select distinct w.minlat,w.maxlat,w.minlong,w.maxlong,(CASE w.description WHEN 'ACCIDENT SPOT' THEN 'Accident' "
                             + "WHEN 'PARKING, REST AREA' THEN 'Parking' WHEN 'BLIND SPOT' THEN 'Blind' ELSE 'Other' END) as spots from "
                             + "waypointsref w where (w.description='BLIND SPOT' or w.description='PARKING, REST AREA' or w.description="
                             + "'ACCIDENT SPOT') and w.accountid in (select min(AccountID) from vehicles where VehicleID='" + vehicle + "')";

                data = dbx.executeQuery(query);
                query = "select distinct g.minLatitude,g.maxLatitude,g.minLongitude,g.maxLongitude,'nightspots' as spots from georegions g where "
                      + "g.acntOrGrpId in (select min(v.GroupId) from vehiclesgroupsmap v where v.VehicleID='" + vehicle + "' order by v.GroupId) and"
                      + " g.allowed=1";
                DataSet data1 = dbx.executeQuery(query);
                foreach (DataRow d in data1.Tables[0].Rows)
                {
                    data.Tables[0].Rows.Add(d.ItemArray);
                }
            }
            else if (val == "map")
            {
                string vehicle = GetVehilceByIMEI(IMEI);
                string query = "select distinct (w.minlat+w.maxlat)/2 as Latitude,(w.minlong+w.maxlong)/2 as Longitude,(CASE w.description "
                             + "WHEN 'ACCIDENT SPOT' THEN 'Accident zone' WHEN 'PARKING, REST AREA' THEN 'Parking' WHEN 'BLIND SPOT' THEN "
                             + "'Blind spot' ELSE 'Other' END) as Name,w.locstr as Address,'0' as Phone from waypointsref w where "
                             + "(w.description='BLIND SPOT' or w.description='PARKING, REST AREA' or w.description='ACCIDENT SPOT') and "
                             + "w.accountid in (select min(AccountID) from vehicles where VehicleID='" + vehicle + "')";

                data = dbx.executeQuery(query);
            }
            DataRow[] places = new DataRow[data.Tables[0].Rows.Count];
            data.Tables[0].Rows.CopyTo(places, 0);
            return places;
        }
