        public int insertMobileGpsData(string IMEI, string data)
        {
            string[] dat = data.Split('|');
            StringBuilder Query = new StringBuilder();
            Query.Append("INSERT INTO `mobilepositiondata` (`IMEI`, `Datetime`, `Latitude`, `Longitude`, `Speed`) VALUES ");
            for (int i = 0; i < dat.Length - 1; i++)
            {
                string[] res = dat[i].Split('#');
                Query.Append("('" + IMEI + "', '" + res[3] + "', " + res[0] + ", " + res[1] + ", " + res[2] + ")");
                if (i == dat.Length - 2)
                    Query.Append(";");
                else
                    Query.Append(",");
            }
            int result = dbx.executeNonQuery(Query.ToString());
            return result;
        }
