        public int insertlogAudioData(string vehicleId, string data)
        {
            string[] dat = data.Split(new string[] { "&@" }, StringSplitOptions.None);
            StringBuilder Query = new StringBuilder();
            Query.Append("INSERT INTO `logjrmdata` (vehicleid,ts,locstr,description) VALUES ");
            for (int i = 0; i < dat.Length - 1; i++)
            {
                string[] res = dat[i].Split(new string[] { "@&" }, StringSplitOptions.None);
                string locstr = getPositionTxt(res[1], res[2], 0);
                Query.Append("('" + vehicleId + "', '" + res[0] + "','" + locstr + "', '" + res[3] + "')");
                if (i == dat.Length - 2)
                    Query.Append(";");
                else
                    Query.Append(",");
            }
            int result = dbx.executeNonQuery(Query.ToString());
            return result;
        }
