            Query.Append("select p.TruckID,p.Latitude,p.Longitude,max(p.TimeStamp) from emergencyvehicles e " +
                         "inner join lastupdtdata p on e.VehicleId=p.TruckID " +
                         "where e.AccountId=?" +
