        public DataSet GetTransporterNotifications(string login)
        {
            DateTime date = System.DateTime.Now;
            string ActionTime = formatDBDate(DateTime.UtcNow);
            string current_partition = GetTransNotifPartitions(DateTime.Now.AddDays(-7), DateTime.Now, transporterNot_partitions);

            StringBuilder Query = new StringBuilder();
            Query.Append("select tn.LoginId,tn.Subject,tn.Info,tn.Datetime,0 as count,tn.IsNotified,tn.Priority from transporternotification partition(" +
                 current_partition + ") tn " + " where tn.Isnotified<>1 and tn.LoginId='" + login + "' order by tn.Datetime desc limit 100");
            DataSet result = dbx.executeQuery(Query.ToString());
            int newrows = result.Tables[0].Rows.Count;
            if (newrows < 10)
            {
                Query.Clear();
                Query.Append("select tn.LoginId,tn.Subject,tn.Info,tn.Datetime,0 as count,tn.IsNotified,tn.Priority from transporternotification   partition(" +
                   current_partition + ") tn " + " where tn.LoginId='" + login + "' order by tn.Datetime desc limit 10");
                result = dbx.executeQuery(Query.ToString());
            }
            if (result.Tables[0].Rows.Count > 0)
            {
                result.Tables[0].Rows[0][4] = newrows;
            }
            return result;
        }

