        /// <param name="accountID"></param>
        /// <param name="dateTime"></param>
        /// <returns>Get all vettings done in month</returns>
        public DataTable GetInvariantScoresByType(string accountID, DateTime dateTime)
        {
            string query = "select d.ID,d.truckRegNo VehicleNo,d.carrier Transporter,cap.Capacity,d.vehType Type from veh_inv_details d left join ((select v.VehicleID,vi.Capacity from vehicles v"
                + " join vehicleinfo vi on v.VehicleID=vi.VehicleId where v.AccountID=? group by replace(v.VehicleID,' ',''))) cap on "
                + "replace(cap.VehicleID,' ','')=replace(d.truckRegNo,' ','') where month(d.DateTime)>=? and year(d.DateTime)=? and d.AccountID=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountID", accountID);
            lParameter.Add("month", dateTime.Month);
            lParameter.Add("year", dateTime.Year);
            lParameter.Add("AccountID1", accountID);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }

