        public DataSet GetMobilePositiondata()
        {
            string fromdate = formatDBDate(System.DateTime.Now.AddMinutes(-2));
            string todate = formatDBDate(System.DateTime.Now);
            string date = System.DateTime.Now.ToShortDateString();
            StringBuilder Query = new StringBuilder();
            Query.Append("select di.DriverId, m.IMEI,m.Datetime,min(m.Latitude),min(m.Longitude),max(m.Latitude),max(m.Longitude) from mobilepositiondata m " +
                         "inner join driverinfo di on di.IMEI=m.IMEI " +
                         "where m.Datetime between '" + fromdate + "' and '" + todate + "' " +
                         "and (di.LastVerifiedDate <> '" + todate + "' OR di.LastVerifiedDate is null) " +
                         "group by di.DriverId");
            return dbx.executeQuery(Query.ToString());
        }
