        public void createpositioncopy(string timestamp)
        {
            string fromdate = formatDBDate(Convert.ToDateTime(timestamp).AddSeconds(-20));
            string todate = formatDBDate(Convert.ToDateTime(timestamp).AddSeconds(20));

            StringBuilder Query = new StringBuilder();
            Query.Append("TRUNCATE TABLE positiondatacopy;");//truncate previous data
            dbx.executeNonQuery(Query.ToString());
            Query.Clear();
            //Insert positiondata
            Query.Append("INSERT INTO positiondatacopy(Truckid,Timestamp,Latitude,Longitude,IMEI) " +
                         "select p.TruckID,p.TimeStamp,p.Latitude,p.Longitude,'0' as IMEI from positiondata p " +
                         "where p.TimeStamp between '" + fromdate + "' and '" + todate + "' " +
                         "and p.`Stop`= 0");
            dbx.executeNonQuery(Query.ToString());
        }


