        //Assign vehicle to driver
        public void AssignVehicletoDriver(int driverid, string vehicleid, string IMEI = "", string tdate = "")
        {
            StringBuilder Query = new StringBuilder();
            string date = formatDBDate(System.DateTime.Now);
            string cdate = Convert.ToDateTime(date).ToString("yyyy-MM-dd");
            Query.Append("select di.AssignedVehicleId from driverinfo di " +
                         "where di.DriverId='" + driverid + "'");
            string currentvehicle = dbx.executeQuery(Query.ToString()).Tables[0].Rows[0][0].ToString();
            Query.Clear();
            try
            {
                tdate = Convert.ToDateTime(tdate).ToString("yyyy-MM-dd");
            }
            catch { }
            if (tdate == cdate)
            {
                //Update Assigned vehicle 
                insertauditdata("Edit", "driverinfo", "DriverId", driverid.ToString());
                Query.Append("update driverinfo di set di.AssignedVehicleId='" + vehicleid + "', di.LastVerifiedDate='" + date + "' where di.DriverId=" + driverid + "");
                dbx.executeNonQuery(Query.ToString());
                //Keep log of vehicle change
                if (currentvehicle != vehicleid)
                {
                    Query.Clear();
                    Query.Append("update `drivervehiclelog` lg set lg.Todate='" + date + "' where lg.Driverid='" + driverid + "' and lg.Todate is NULL;");
                    dbx.executeNonQuery(Query.ToString());
                    Query.Clear();
                    Query.Append("INSERT INTO `drivervehiclelog`(Driverid,Vehicleid,Fromdate,Todate) " +
                                 "VALUES ('" + driverid + "', '" + vehicleid + "', '" + date + "', NULL); ");
                    int res = dbx.executeNonQuery(Query.ToString());
                    if (res == 1)
                        PushChangeDataToAPI(driverid.ToString(), "UpdateDriverVehicle", getAccountIdByVehicleId(vehicleid).ToString());
                }
            }
            if (IMEI.Length > 2)
            {
                Query.Clear();
                string d = Convert.ToDateTime(date).ToString("yyyy-MM-dd");
                //Update  vehicle in nfc data
                Query.Append("update nfcdata nd  set nd.Vehicleid='" + vehicleid + "' where nd.Data='" + IMEI + "' and date(nd.Datetime)='" + tdate + "';");
                dbx.executeNonQuery(Query.ToString());
            }

        }
        public void UpdateVehicletoDriverlog(string vehicleid = "")
        {
            try
            {
                StringBuilder Query = new StringBuilder();
                string date = formatDBDate(System.DateTime.Now);
				DataTable dt = new DataTable();

				Query.Append("select di.AssignedVehicleId,di.DriverId from driverinfo di");
                var lParameter = new Dictionary<string, object>();
                if (!string.IsNullOrEmpty(vehicleid))
                {
                    Query.Append(" where di.AssignedVehicleId=?");
                    lParameter.Add("AssignedVehicleId", vehicleid);
					//code modified by sahana(13-08-2025) - datatable calling moved inside condition .
					//if vehicle not passed from reference method do not proceed with the insert/update actions of vehicletodriverlog 
					dt = dbx.executeQuery(Query.ToString(), lParameter).Tables[0];
				}                
                Query.Clear();
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    Query.Clear();
                    Query.Append("select * from drivervehiclelog d where d.DriverId=?  and d.Todate is NULL  order by Fromdate desc limit 1");
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("DriverId", dt.Rows[i]["DriverId"].ToString());
                    DataTable dtveh = dbx.executeQuery(Query.ToString(), lParameter).Tables[0];
                    string currentveh = dt.Rows[i]["AssignedVehicleId"].ToString();
                    string driverid = dt.Rows[i]["DriverId"].ToString();
                    if (dtveh.Rows.Count > 0)
                    {
                        string oldveh = dtveh.Rows[0]["Vehicleid"].ToString();
                        if (oldveh != currentveh)
                        {
                            insertauditdata("Edit", "drivervehiclelog", "Driverid", driverid);
                            Query.Clear();
                            Query.Append("update `drivervehiclelog` lg set lg.Todate=? where lg.Driverid=? and lg.Todate is NULL;");
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("Todate", date);
                            lParameter.Add("DriverId", driverid);
                            dbx.executeNonQuery(Query.ToString(), lParameter);
                            Query.Clear();
                            Query.Append("INSERT INTO `drivervehiclelog`(Driverid,Vehicleid,Fromdate,Todate) " +
                                         "VALUES (?, ?, ?, NULL); ");
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("driverid", driverid);
                            lParameter.Add("currentveh", currentveh);
                            lParameter.Add("date", date);
                            int res = dbx.executeNonQuery(Query.ToString(), lParameter);
                            if (res == 1)
                            {
                                PushChangeDataToAPI(driverid.ToString(), "UpdateDriverInfo", getAccountIdByVehicleId(currentveh).ToString());
                                PushChangeDataToAPI(driverid.ToString(), "UpdateDriverVehicle", getAccountIdByVehicleId(currentveh).ToString());
                            }
                        }
                    }
                    else
                    {
                        Query.Clear();
                        Query.Append("INSERT INTO `drivervehiclelog`(Driverid,Vehicleid,Fromdate,Todate) " +
                                     "VALUES ('" + driverid + "', '" + currentveh + "', '" + date + "', NULL); ");
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("driverid", driverid);
                        lParameter.Add("currentveh", currentveh);
                        lParameter.Add("date", date);
                        int res = dbx.executeNonQuery(Query.ToString(), lParameter);
                        if (res == 1)
                            PushChangeDataToAPI(driverid.ToString(), "UpdateDriverInfo", getAccountIdByVehicleId(currentveh).ToString());
                        PushChangeDataToAPI(driverid.ToString(), "UpdateDriverVehicle", getAccountIdByVehicleId(currentveh).ToString());
                    }
                    //added by Madhuri to sync todate and fromdate-vehiclewise-08-11-2022
                    Query.Clear();
                    Query.Append("select * from drivervehiclelog d where d.Vehicleid=? order by Fromdate desc limit 2");
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Vehicleid", currentveh);
                    DataTable dtvehcurrentdetais = dbx.executeQuery(Query.ToString(), lParameter).Tables[0];
                    if (dtvehcurrentdetais.Rows.Count > 1)
                    {
                        string fromdate = "";
                        string todate = "";
                        fromdate = dtvehcurrentdetais.Rows[0]["Fromdate"].ToString();
                        todate = dtvehcurrentdetais.Rows[1]["Todate"].ToString();
                        string lasstrow = dtvehcurrentdetais.Rows[0]["Id"].ToString();
                        string secondlasstrow = dtvehcurrentdetais.Rows[1]["Id"].ToString();
                        if (!string.IsNullOrEmpty(fromdate.ToString()) && !string.IsNullOrEmpty(todate.ToString()))
                        {
                            if ((Convert.ToDateTime(fromdate)) > (Convert.ToDateTime(todate)))
                            {
                                Query.Clear();
                                Query.Append("update `drivervehiclelog` lg set lg.Fromdate=? where Id=? ;");
                                lParameter = new Dictionary<string, object>();
                                lParameter.Add("Fromdate", formatDBDate(Convert.ToDateTime(todate)));
                                lParameter.Add("Id", lasstrow);
                                dbx.executeNonQuery(Query.ToString(), lParameter);
                                Query.Clear();
                            }
                        }
                        if (string.IsNullOrEmpty(todate.ToString()))
                        {
                            Query.Clear();
                            Query.Append("update `drivervehiclelog` lg set lg.Todate=? where Id=? ;");
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("Todate", formatDBDate(Convert.ToDateTime(fromdate)));
                            lParameter.Add("Id", secondlasstrow);
                            dbx.executeNonQuery(Query.ToString(), lParameter);
                            Query.Clear();
                        }
                    }
                    //Ended by Madhuri-08-11-2022
                }
            }
            catch (Exception ex)
            {
            }

        }
        public void UpdateIMEItoDriverlog()
        {
            try
            {
                StringBuilder Query = new StringBuilder();
                string date = formatDBDate(System.DateTime.Now);
                string cdate = Convert.ToDateTime(date).ToString("yyyy-MM-dd");
                Query.Append("select di.IMEI,di.DriverId from driverinfo di");
                DataTable dt = dbx.executeQuery(Query.ToString()).Tables[0];
                Query.Clear();
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    Query.Append("select * from driverimeilog d where d.DriverId='" + dt.Rows[i]["DriverId"].ToString() + "' and d.Todate is NULL order by Fromdate desc limit 1");
                    DataTable dtveh = dbx.executeQuery(Query.ToString()).Tables[0];
                    string currentIMEI = dt.Rows[i]["IMEI"].ToString();
                    string driverid = dt.Rows[i]["DriverId"].ToString();
                    if (dtveh.Rows.Count > 0)
                    {
                        string oldIMEI = dtveh.Rows[0]["IMEI"].ToString();
                        if (oldIMEI != currentIMEI)
                        {
                            Query.Clear();
                            Query.Append("update `driverimeilog` lg set lg.Todate='" + date + "' where lg.Driverid='" + driverid + "' and lg.Todate is NULL;");
                            dbx.executeNonQuery(Query.ToString());
                            Query.Clear();
                            Query.Append("INSERT INTO `driverimeilog`(Driverid,Vehicleid,Fromdate,Todate) " +
                                         "VALUES ('" + driverid + "', '" + currentIMEI + "', '" + date + "', NULL); ");
                            dbx.executeNonQuery(Query.ToString());
                        }
                    }
                    else
                    {
                        Query.Append("INSERT INTO `driverimeilog`(Driverid,Vehicleid,Fromdate,Todate) " +
                                     "VALUES ('" + driverid + "', '" + currentIMEI + "', '" + date + "', NULL); ");
                        dbx.executeNonQuery(Query.ToString());
                    }
                }
            }
            catch { }

        }
