        public string DriverPoints(string IMEI)
        {
            string driverid = "0";
            string name = "NA";
            string vehicle = "NA";
            string month = "0";
            string negative = "0";
            string year = "0";
            string lastday = "0";
            string lastencashed = "0";
            string last_earned_date = DateTime.Now.AddDays(-1).ToString("dd'/'MM'/'yyyy");
            StringBuilder Query = new StringBuilder();
            //Get Driver Name and Id
            Query.Append("select Name,Driverid,di.AssignedVehicleId from driverinfo di where di.IMEI='" + IMEI + "'");
            DataTable dt = dbx.executeQuery(Query.ToString()).Tables[0];
            if (dt.Rows.Count > 0)
            {
                name = dt.Rows[0][0].ToString();
                driverid = dt.Rows[0][1].ToString();
                vehicle = dt.Rows[0][2].ToString();
            }
            Query.Clear();
            //Get this month positive and neagtive points
            Query.Append("select IFNULL(SUM(d.`points_earned`),0)as positive,IFNULL(SUM(d.`negativepoints`),0)as negative from daywisevehviosummary d " +
                         "where month(date) ='" + DateTime.Now.AddDays(-1).Month + "' AND year(date) ='" + DateTime.Now.AddDays(-1).Year + "' and d.DriverId ='" + driverid + "'");
            dt = dbx.executeQuery(Query.ToString()).Tables[0];
            if (dt.Rows.Count > 0)
            {
                month = dt.Rows[0][0].ToString();
                negative = dt.Rows[0][1].ToString();
            }
            Query.Clear();
            Query.Append("select IFNULL(SUM(d.`points_earned`),0) as thisyear from daywisevehviosummary d where year(date) ='" + DateTime.Now.AddDays(-1).Year + "' and d.driverid='" + driverid + "' ");
            object obj = dbx.executeScalar(Query.ToString());
            if (obj != null && obj.ToString() != "")
            {
                year = obj.ToString();
            }
            Query.Clear();
            Query.Append("select d.points_earned,d.date from daywisevehviosummary d " +
                           "where d.driverid='" + driverid + "' and d.points_earned<>0 order by d.date desc limit 1 ");
            dt = dbx.executeQuery(Query.ToString()).Tables[0];
            if (dt.Rows.Count > 0)
            {
                lastday = dt.Rows[0][0].ToString();
                last_earned_date = Convert.ToDateTime(dt.Rows[0][1]).ToString("dd'/'MM'/'yyyy");
            }
            Query.Clear();
            DateTime date = System.DateTime.Now;
            int m = date.AddMonths(-1).Month;
            int y = date.AddMonths(-1).Year;
            Query.Append("select SUM(d.`points_earned`) from daywisevehviosummary d where month(date) ='" + m + "' AND year(date) ='" + y + "' and d.driverid='" + driverid + "'");
            obj = dbx.executeScalar(Query.ToString());
            if (obj != null && obj.ToString() != "")
            {
                lastencashed = obj.ToString();
            }
            return name + "," + month + "," + year + "," + lastday + "," + negative + "," + lastencashed + "," + last_earned_date + "," + vehicle;
        }
        //for driver app
        public DataTable TransportorPoints(string IMEI)
        {
            StringBuilder Query = new StringBuilder();
            //get today points
            Query.Append("select t.Transporter from vehicleinfo t inner join driverinfo di on t.VehicleId=di.AssignedVehicleId " +
                           "where di.IMEI='" + IMEI + "'");
            DataSet result = dbx.executeQuery(Query.ToString());
            if (result.Tables[0].Rows.Count > 0)
            {
                string transportor = result.Tables[0].Rows[0][0].ToString();
                Query.Clear();
                Query.Append("select drivername,Sum(points_earned) as this_month_points from daywisevehviosummary dw " +
                             "inner join vehicleinfo v on v.VehicleId=dw.vehicleid " +
                             "where month(date)='" + DateTime.Now.AddDays(-1).Month + "' and year(date)='" + DateTime.Now.AddDays(-1).Year + "' and v.Transporter='" + transportor + "' and dw.driverid<>0 " +
                             "group by driverid order by this_month_points desc");
                result = dbx.executeQuery(Query.ToString());
                return result.Tables[0];
            }
            else
            {
                Query.Clear();
                Query.Append("select '' as drivername,0 as points from vehicleinfo where 1!=1");
                result = dbx.executeQuery(Query.ToString());
                return result.Tables[0];
            }
        }

