        //for driver app
        public DataTable BestDriver(string accountId = "")
        {
            if (string.IsNullOrEmpty(accountId))
                accountId = "9";
            else if (accountId == "0")
                accountId = "9";
            StringBuilder Query = new StringBuilder();
            DateTime date = DateTime.Now.AddDays(-1);
            DateTime now = DateTime.Now;
            DateTime addedOn = DateTime.Now.AddYears(-1);
            string query = "select drivername,points,vehicleid,AddedOn from best_driver where AccountId='" + accountId + "' and `Month`=" + date.Month + " and `Year`=" + date.Year + " order by AddedOn desc limit 1";
            DataSet result = dbx.executeQuery(query);
            if (result.Tables[0].Rows.Count > 0)
            {
                addedOn = Convert.ToDateTime(result.Tables[0].Rows[0]["AddedOn"].ToString());
            }
            if (result.Tables[0].Rows.Count == 0 || now.AddHours(-12) > addedOn)
            {
                Query.Append("select drivername,sum(d.points_earned) as points,vehicleid " +
                            " from daywisevehviosummary d " +
                            " where month(d.date)=" + date.Month + " and year(d.date)=" + date.Year + " and driverid<>0 and groupid in (select groupid from accountgroups where accountid=" + accountId + ")" +
                            " group by driverid order by points desc limit 1");
                result = dbx.executeQuery(Query.ToString());
                if (result.Tables[0].Rows.Count > 0)
                {
                    query = "insert ignore into best_driver(drivername,points,vehicleid,AccountId,Month,Year,AddedOn) values(?,?,?,?,?,?,?)";
                    var lParameter = new Dictionary<string, Object>();
                    lParameter.Add("drivername", result.Tables[0].Rows[0]["drivername"].ToString());
                    lParameter.Add("points", result.Tables[0].Rows[0]["points"].ToString());
                    lParameter.Add("vehicleid", result.Tables[0].Rows[0]["vehicleid"].ToString());
                    lParameter.Add("AccountId", accountId);
                    lParameter.Add("Month", date.Month);
                    lParameter.Add("Year", date.Year);
                    lParameter.Add("AddedOn", formatDBDate(now));
                    dbx.executeNonQuery(query, lParameter);
                }
            }
            if (result.Tables[0].Rows.Count > 0)
            {
                string vehicleid = result.Tables[0].Rows[0]["vehicleid"].ToString();
                Query.Clear();
                Query.Append("select t.Name from vehicleinfo vi inner join transporterinfo t on t.TransporterId=vi.Transporter where vi.VehicleId='" + vehicleid + "'");
                DataSet t_name = dbx.executeQuery(Query.ToString());
                if (t_name.Tables[0].Rows.Count > 0)
                {
                    result.Tables[0].Rows[0]["vehicleid"] = t_name.Tables[0].Rows[0][0];//Replacing vehicleid by transportername 
                }
                else
                {
                    result.Tables[0].Rows[0]["vehicleid"] = "";//Replacing vehicleid by transportername
                }
            }
            return result.Tables[0];
        }
