        //for transportor app
        public DataTable Getviolation(string vehicle)
        {
            int timeZone = 5 * 60 * 60 + 30 * 60;
            string date = DateTime.UtcNow.AddSeconds(timeZone).ToString("yyyy-MM-dd 05:00:00");
            string part = GetDateTablePartitions(Convert.ToDateTime(date), DateTime.Now, partions);
            string inparam = string.Empty;
            var lParameter = new Dictionary<string, object>();
            String[] vehicles = vehicle.Replace("'", "").Replace("\"", "").Split(',');
            for (int i = 0; i < vehicles.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
                lParameter.Add("truckId" + i, vehicles[i]);
            }
            string query = " SELECT distinct v.vehicleId," +
                           " max( IF (sv.`type`='NIGHT DRIVING','yes','Nil')) AS nightdriving, " +
                           " min( IF (sv.`type`='OVERSPEEDING',sv.remarks,'Nil')) AS overspeed, " +
                           " max( IF (sv.`type`='HARSH BRAKING','yes','Nil')) AS harshbrake ," +
                           " TIME_FORMAT(SEC_TO_TIME(v.cummRunTime),'%Hh %imin') AS Runtime" +
                           " from vehiclessnapshot v " +
                           " inner join storevehicleviolations PARTITION(" + part + ") AS sv on v.vehicleId=sv.vehicleId" +
                           " where sv.timestamp>='" + date + "' and v.vehicleid in (" + inparam + ") " +
                           " and v.DriverId in (select d.DriverId from driverinfo d where d.AssignedVehicleId=v.vehicleId)" +
                           " group by v.vehicleid,v.DriverId";
            try
            {
                DataSet ds = dbx.executeQuery(query, lParameter);
                return ds.Tables[0];
            }
            catch
            {

                return null;
            }
        }
        public DataTable GetviolationSumByVehicleAndTime(string vehicle, string Fromtimestamp, string Totimestamp)
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(Fromtimestamp), Convert.ToDateTime(Totimestamp), partions);
            var lParameter = new Dictionary<string, object>();
            String[] vehicles = vehicle.Replace("'", "").Replace("\"", "").Split(',');
            string inparam = string.Empty;
            for (int i = 0; i < vehicles.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
            }
            string query = "SELECT distinct sv.vehicleId,max( IF (sv.`type`='NIGHT DRIVING','yes','Nil')) AS nightdriving, " +
                           "max( IF (sv.`type`='OVERSPEEDING',sv.remarks,'Nil')) AS overspeed, " +
                           "max( IF (sv.`type`='HARSH BRAKING','yes','Nil')) AS harshbrake, " +
                           "max((select CONCAT(CAST(floor((cummRunTime/3600)) as UNSIGNED),'h  ',CAST(MOD((cummRunTime/60),60)as UNSIGNED),'min') " +
                           " from vehiclessnapshot s where s.vehicleid=sv.vehicleid)) as MaxRuntime " +
                           "from storevehicleviolations PARTITION(" + part + ") AS sv " +
                           "where sv.vehicleid in (" + inparam + ") and sv.timestamp>=? and sv.timestamp<=?" +
                           "group by vehicleid";
            for (int i = 0; i < vehicles.Length; i++)
            {
                lParameter.Add("truckId" + i, vehicles[i]);
            }
            lParameter.Add("timestamp1", Fromtimestamp);
            lParameter.Add("timestamp2", Totimestamp);
            try
            {
                DataSet ds = dbx.executeQuery(query, lParameter);
                return ds.Tables[0];
            }
            catch
            {

                return null;
            }
        }
        public DataTable GetDriverActivityLog(string DriverId, string fromDate, string toDate, string Activity)
        {
            string query = "select * from driveractivitylog where DriverId=? and Date between ? and ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("DriverId", DriverId);
            lParameter.Add("Date1", fromDate);
            lParameter.Add("Date2", toDate);

            if (Activity != "ALL")
            {
                if (Activity.Contains(','))
                {
                    string inparam = string.Empty;
                    String[] vals = Activity.Replace("'", "").Replace("\"", "").Split(',');
                    for (int i = 0; i < vals.Length; i++)
                    {
                        if (i == 0)
                            inparam += ("?");
                        else
                            inparam += (",?");
                        lParameter.Add("vals_" + i, vals[i]);
                    }
                    query = query + " and Activity in (" + inparam + ")";

                }
                else
                {
                    query = query + " and Activity=?";
                    lParameter.Add("vals", Activity);
                }
            }
            return dbx.executeQuery(query, lParameter).Tables[0];

        }
