        public DataSet GetFirstOutTimeFromPlant(string truckid, string fromdata, string todate, double minlat, double minlng, double maxlat, double maxlng)
        {
            StringBuilder query = new StringBuilder();
            string pos_part = GetDateTablePartitions(Convert.ToDateTime(fromdata), Convert.ToDateTime(todate), partions);
            query.Append("select pos.TruckID,pos.Latitude,pos.Longitude,pos.TimeStamp,pos.Stop from positiondata PARTITION(" + pos_part + ") AS pos ");
            query.Append(" where pos.TimeStamp between '" + fromdata + "' and '" + todate + "' and TruckID='" + truckid + "' ");
            query.Append(" and pos.`Stop`=0 and pos.Latitude not between " + minlat + " and " + maxlat + " and pos.Longitude not between " + minlng + " and " + maxlng);
