        public DataSet GetVehicleUtilization(string sessionid, string type, string value, string barcharttype, string start, string end)
        {
            string Groupid = getGroupId(sessionid).ToString();
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            if (type == "All")
            {
                query.Append("select count(*) as utilizationcount from daywisevehviosummary ds join vehicleinfo vi join vehiclesgroupsmap vgm");
                query.Append(" where ds.vehicleid=vi.vehicleid and vi.vehicleid=vgm.VehicleId and vgm.GroupId=? and");
                query.Append(" ds.date>=? and ds.date<=? and ds.Kms_driven>2");
                lParameter.Add("GroupId", Groupid);
                lParameter.Add("FromDate", formatDBDate(Convert.ToDateTime(start)));
                lParameter.Add("ToDate", formatDBDate(Convert.ToDateTime(end)));

                if (barcharttype != "All")
                {
                    query.Append(" and vi." + barcharttype + "=?");
                    lParameter.Add("barcharttype", value);
                }
            }
            else
            {
                query.Append("select count(*) as utilizationcount from daywisevehviosummary ds join vehicleinfo vi join vehiclesgroupsmap vgm");
                query.Append(" where ds.vehicleid=vi.vehicleid and vi.vehicleid=vgm.VehicleId and vgm.GroupId=? and");
                query.Append(" vi.TypeOfVehicle=? and");
                query.Append(" ds.date>=? and ds.date<=? and ds.Kms_driven>2");
                lParameter.Clear();
                lParameter.Add("GroupId", Groupid);
                lParameter.Add("TypeOfVehicle", type);
                lParameter.Add("FromDate", formatDBDate(Convert.ToDateTime(start)));
                lParameter.Add("ToDate", formatDBDate(Convert.ToDateTime(end)));
                if (barcharttype != "All")
                {
                    query.Append(" and vi." + barcharttype + "=?");
                    lParameter.Add("barcharttype", value);
                }
            }
            DataSet vehicles = dbx.executeQuery(query.ToString(), lParameter);
            return vehicles;
        }
