        /// <summary>
        /// STOLEN panic alerts for SIA DC-09 packet building (theft/SOS).
        /// </summary>
        public DataTable GetStolenPanicAlertsForSia(int groupId, DateTime alertTimestampFrom, DateTime alertTimestampTo)
        {
            string query = "SELECT * FROM panic p WHERE p.`type` = ? AND p.alertTimestamp > ? AND p.alertTimestamp <= ? " +
                           "AND p.vehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap v WHERE v.GroupId = ?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("type", "STOLEN");
            lParameter.Add("alertTimestampFrom", formatDBDate(alertTimestampFrom));
            lParameter.Add("alertTimestampTo", formatDBDate(alertTimestampTo));
            lParameter.Add("GroupId", groupId);
            DataSet ds = dbx.executeQuery(query, lParameter);
            if (ds != null && ds.Tables.Count > 0)
                return ds.Tables[0];
            return new DataTable();
        }

        /// <summary>
        /// STOLEN panic rows in the lookback window that still need SIA DC-09 dispatch (no SUCCESS log yet).
        /// PriorDispatchAttempts = how many log rows already exist for this alert (for retry audit).
        /// </summary>
        public DataTable GetStolenPanicAlertsForSiaDc09Dispatch(int groupId, DateTime alertTimestampFrom, DateTime alertTimestampTo)
        {
            string query = "SELECT p.vehicleId, p.alertTimestamp, p.`type`, p.ackTimeStamp, " +
                           "IFNULL(prior.PriorDispatchAttempts, 0) AS PriorDispatchAttempts " +
                           "FROM panic p " +
                           "LEFT JOIN (SELECT AssetId, EventTimestamp, COUNT(*) AS PriorDispatchAttempts " +
                           "FROM tbl_sia_dc09_log GROUP BY AssetId, EventTimestamp) prior " +
                           "ON prior.AssetId = p.vehicleId AND prior.EventTimestamp = p.alertTimestamp " +
                           "WHERE p.`type` = ? AND p.alertTimestamp > ? AND p.alertTimestamp <= ? " +
                           "AND p.vehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap v WHERE v.GroupId = ?) " +
                           "AND NOT EXISTS (SELECT 1 FROM tbl_sia_dc09_log l WHERE l.AssetId = p.vehicleId " +
                           "AND l.EventTimestamp = p.alertTimestamp AND UPPER(l.Status) = 'SUCCESS')";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("type", "STOLEN");
            lParameter.Add("alertTimestampFrom", formatDBDate(alertTimestampFrom));
            lParameter.Add("alertTimestampTo", formatDBDate(alertTimestampTo));
            lParameter.Add("GroupId", groupId);
            DataSet ds = dbx.executeQuery(query, lParameter);
            if (ds != null && ds.Tables.Count > 0)
                return ds.Tables[0];
            return new DataTable();
        }

