        public string getLastPanicEntry(string vehicleid, string type)
        {
            try
            {
                string query = "select Max(p.alertTimestamp) from panic p where p.vehicleId='" + vehicleid + "' and p.`type`='" + type + "' and p.alertTimestamp<='" + DateTime.Now.AddDays(2).ToString("yyyy-MM-dd HH:mm") + "'";
                object res = dbx.executeScalar(query);
                if (res != null)
                {
                    return res.ToString();
                }
                else
                {
                    return null;
                }
            }
            catch { return null; }
        }
