            query.Append("`City`,`State`,`ContactNo`,`MobileNo`,`LicenceNo`,`IssuedBy`,`LicenceValid`,`LicenceRemainder`,");
            query.Append("`LRStartBefore`,`LRRepeat`,`LRSMS`,`LRSMS_MobileNo`,`LREmail`,`LREmail_MailId`,`InsuranceCompany`");
            query.Append(",`PolicyNo`,`PolicyDate`,`InsuranceRemainder`,`IRStartBefore`,`IRRepeat`,`IRSMS`,`IRSMS_MobileNo`,");
            query.Append("`IREmail`,`IREmail_MailId`,`AssignedVehicleId`,`CleanerName`,`CleanerMobile`,`DriverLanguagePreference`,");
            query.Append("`DriverPhoto`,driverinfo.AccountId,`Active`,`UserDefinedDriverId`,HelperId,IMEI,RFIDTag,HazardousLicNo,HazardousLicExpDate,");
            query.Append("DDTDate,DDTExpiryDate,MedicalTestDate,MediExpDate,DrivingExp,DOJ,DriverAccidentHistory,DDTGrade,Approve,driverinfo.DriverType,d.DriverType as 'DriverTypeName' FROM `driverinfo` left join drivertype d on d.Id=driverinfo.DriverType ");
