        public string insertDriverCounseling(string vehDriPlant, string plant, string type, string details, string counsellor, string file, string date, string userid,
            int incent_points, int accountid)
        {
            string str = string.Empty;
            string[] vehicleDriverPlant = vehDriPlant.Split(',');
            var lParameter = new Dictionary<string, object>();
            for (int i = 0; i < (vehicleDriverPlant.Length / 3); i++)
            {
                str = str + "(?,?,?,?,";
                str = str + "?,?,?,?,?,?)";
                if (i == (vehicleDriverPlant.Length / 3) - 1)
                    str = str + ";";
                else
                    str = str + ",";
                lParameter.Add("VehicleId_" + i, vehicleDriverPlant[(i * 3)]);
                lParameter.Add("DriverName_" + i, vehicleDriverPlant[(i * 3) + 1]);
                lParameter.Add("DriverId_" + i, vehicleDriverPlant[(i * 3) + 2]);
                lParameter.Add("Plant_" + i, plant);
                lParameter.Add("TypeOfCounseling_" + i, type);
                lParameter.Add("CounseledDetails_" + i, details.Replace("'", "''"));
                lParameter.Add("CounselingBy_" + i, counsellor.Replace("'", "''"));
                lParameter.Add("Attachment_" + i, file);
                lParameter.Add("Datetime_" + i, date);
                lParameter.Add("Addedby_" + i, userid);
                if (type == "Toolbox Meeting")
                {
                    RecordIncentiveLog("TOOLBOX MEETING", vehicleDriverPlant[(i * 3)], vehicleDriverPlant[(i * 3) + 2], vehicleDriverPlant[(i * 3) + 1], date,
                        incent_points, accountid, userid, true, formatDBDate(DateTime.Now.AddDays(-4)));
                }
            }
            string query = "insert into drivercounseling (VehicleId,DriverName,DriverId,Plant,TypeOfCounseling,CounseledDetails,CounselingBy,Attachment,Datetime,Addedby) values " + str;
            return dbx.executeNonQuery(query.ToString(), lParameter).ToString();
        }
        public string insertDriverCounselingSmartFleet(string vehicleid, string topic, string details, string counseledby, string attachment, string license_number, string userid)
        {
            var lParameter = new Dictionary<string, object>();
            string result = "Failed to add";
            if (!string.IsNullOrEmpty(attachment))
                attachment = "placeinfo/" + attachment;
            //get driver details by vehicleid
            if (vehicleid.Length > 1 && vehicleid.CompareTo("No Vehicle") != 0)
            {
                DataTable table = GetDriverInfoByVehicle(vehicleid);
                if (table.Rows.Count > 0)
                {
                    string date = formatDBDate(DateTime.Now);
                    string plant = GetPlantNameByVehicle(vehicleid);
                    string query = "INSERT INTO `drivercounseling` (`VehicleId`, `DriverName`, `Datetime`, `TypeOfCounseling`, `CounseledDetails`, `CounselingBy`, `Plant`, `Attachment`, `DriverId`,`Addedby`) " +
                        "VALUES (?,?,?,?,?,?,?,?,?,?)";
                    lParameter.Add("VehicleId", vehicleid);
                    lParameter.Add("DriverName", table.Rows[0]["Driver"]);
                    lParameter.Add("Datetime", date);
                    lParameter.Add("TypeOfCounseling", topic);
                    lParameter.Add("CounseledDetails", details);
                    lParameter.Add("CounselingBy", counseledby);
                    lParameter.Add("Plant", plant);
                    lParameter.Add("Attachment", attachment);
                    lParameter.Add("DriverId", table.Rows[0]["DriverId"]);
                    lParameter.Add("Addedby", userid);
                    if (dbx.executeNonQuery(query.ToString(), lParameter) > 0)
                        result = "Successfully Added";
                }
                else
                    result = "This Driver/vehicle info not exists";
            }
            else if (license_number.Length > 1)
            {
                string query = "select Name,Driverid,AssignedVehicleid,di.LicenceNo " +
                                "from driverinfo di where di.LicenceNo= ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("LicenceNo", license_number);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                string date = formatDBDate(DateTime.Now);
                if (dt.Rows.Count > 0)
                {
                    query = "INSERT INTO `drivercounseling` (`VehicleId`, `DriverName`, `Datetime`, `TypeOfCounseling`, `CounseledDetails`, `CounselingBy`, `Plant`, `Attachment`, `DriverId`,`Addedby`) " +
                        "VALUES (?,?,?,?,?,?,?,?,?,?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("VehicleId", vehicleid);
                    lParameter.Add("DriverName", dt.Rows[0]["Name"]);
                    lParameter.Add("Datetime", date);
                    lParameter.Add("TypeOfCounseling", topic);
                    lParameter.Add("CounseledDetails", details);
                    lParameter.Add("CounselingBy", counseledby);
                    lParameter.Add("Plant", "");
                    lParameter.Add("Attachment", attachment);
                    lParameter.Add("DriverId", dt.Rows[0]["DriverId"]);
                    lParameter.Add("Addedby", userid);
                    if (dbx.executeNonQuery(query.ToString(), lParameter) > 0)
                        result = "Successfully Added";
                }
                else
                    result = "Wrong Licence number";
            }
            return result;
        }


