        public DataTable GetFieldsList(string sessionid, string type)
        {
            int accountid = GetAccountId(sessionid);

            string Query = "SELECT f.Id,f.FieldName,t.`Type` AS `FieldType`,v.Validation,f.Mandatory,m.Value as FieldValues,s.DateTime,s.Id AS VettingId FROM vet_fields f INNER JOIN vet_field_type t ON f.FieldType = t.Id INNER JOIN vet_field_validations v ON v.Id = f.Validation " +
                "INNER JOIN vet_field_values m ON m.FieldId = t.Id " +
                "INNER JOIN vet_static_details s ON s.Id = m.VetId " +
                "WHERE s.Id IN(SELECT max(s.Id) FROM vet_static_details s WHERE s.AppId = 2)" +
                "ORDER BY f.Id";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountid);
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }
