        public DataTable getVetHeaderDetails(int accountid, string licenseNo, string InspectedBy)
        {
            string Query = "SELECT v.VettingId,c.HeaderId,h.HeaderName,SUM(v.Score * c.Coefficient) AS `HE Score`,CONCAT(DATE_FORMAT(s.DateTime, '%b'),'-',YEAR(s.DateTime)) AS `IDate`,CONCAT(DATE_FORMAT(DATE_ADD(s.DateTime, INTERVAL 1 MONTH), '%b'),'-',YEAR(DATE_ADD(s.DateTime, INTERVAL 1 MONTH))) AS `NM1`,CONCAT(DATE_FORMAT(DATE_ADD(s.DateTime, INTERVAL 2 MONTH), '%b'),'-',YEAR(DATE_ADD(s.DateTime, INTERVAL 2 MONTH))) AS `NM2`,CONCAT(DATE_FORMAT(DATE_ADD(s.DateTime, INTERVAL 3 MONTH), '%b'),'-',YEAR(DATE_ADD(s.DateTime, INTERVAL 3 MONTH))) AS `NM3`,CONCAT(DATE_FORMAT(DATE_ADD(s.DateTime, INTERVAL 4 MONTH), '%b'),'-',YEAR(DATE_ADD(s.DateTime, INTERVAL 4 MONTH))) AS `NM4`,CONCAT(DATE_FORMAT(DATE_ADD(s.DateTime, INTERVAL 5 MONTH), '%b'),'-',YEAR(DATE_ADD(s.DateTime, INTERVAL 5 MONTH))) AS `NM5`,CONCAT(DATE_FORMAT(DATE_ADD(s.DateTime, INTERVAL 6 MONTH), '%b'),'-',YEAR(DATE_ADD(s.DateTime, INTERVAL 6 MONTH))) AS `NM6` FROM vet_checklist_values v " +
                "INNER JOIN vet_checklist c ON c.Id = v.RuleId " +
                "INNER JOIN vet_header h ON h.Id = c.HeaderId " +
                "INNER JOIN vet_static_details s ON s.Id = v.VettingId " +
                "WHERE v.VettingId IN(SELECT MAX(fv.VetId) " +
                "FROM vet_field_values fv INNER JOIN vet_static_details vs ON vs.Id = fv.VetId join vet_app_config a on a.Id=vs.AppId WHERE fv.FieldId = a.UniqueFieldId AND fv.Value = ?";
            if (InspectedBy == "HE")
            {
                Query += " AND vs.AddedBy in ('hubertebner','hubertebnerlubes','lsctotallpg','lsctotallubes'))";
            }
            else
            {
                Query += " AND vs.AddedBy not in ('hubertebner','hubertebnerlubes','lsctotallpg','lsctotallubes'))";
            }
            Query += " AND h.AccountId = ? GROUP BY c.HeaderId ORDER BY c.HeaderId";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Value", licenseNo);
            lParameter.Add("AccountId", accountid);
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }

