        public DataTable getVettingScoresForDriverImpPlan(string licenseNo, string type, string monthname, string year)
        {
            string query = "select v2.HeaderName,floor((sum(v.Score*v1.Coefficient)/sum(v1.Coefficient*2))*100) Score from vet_checklist_values v join vet_checklist v1 on"
                         + " v.RuleId=v1.Id join vet_header v2 on v2.Id=v1.HeaderId where v.VettingId in (select max(v.Id) from vet_static_details v join vet_field_values "
                         + "v1 on v.Id=v1.VetId join vet_app_config a on a.Id=v.AppId  where v1.FieldId= a.UniqueFieldId and v1.Value=? and ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Value", licenseNo);
            if (type == "HE")
                query += "v.AddedBy in ('hubertebner','hubertebnerlubes','lsctotallpg','lsctotallubes')";
            else if (type == "Driver")
            {
                query += "v.AddedBy='totalgas' and monthname(v.DateTime)=? and year(v.DateTime)=?";
                lParameter.Add("monthname", monthname);
                lParameter.Add("year", year);
            }
            else
            {
                query += "v.AddedBy not in ('hubertebner','hubertebnerlubes','lsctotallpg','lsctotallubes') and v.AddedBy!='totalgas' and monthname(v.DateTime)=? and year(v.DateTime)=?";
                lParameter.Add("monthname", monthname);
                lParameter.Add("year", year);
            }
            query += ") group by v2.HeaderName order by v2.Id";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

