        public int insertDriverImprovementDetails(string userName, string sessionid, Dictionary<string, string> fieldsWithValues, Dictionary<string, string> checkListWithValues)
        {
            int maxId = 0, res = 0;
            string query = "";
            var lParameter = new Dictionary<string, object>();
            int accountId = GetAccountId(sessionid);
            if (fieldsWithValues.Count > 0)
            {
                query = "INSERT INTO `vet_static_details` (`AddedBy`, `AppId`, `DateTime`, `AccountId`,`ServerTs`) VALUES (?, ?, ?, ?, ?)";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("AddedBy", userName);
                lParameter.Add("AppId", 2);
                lParameter.Add("DateTime", formatDBDate(DateTime.Now));
                lParameter.Add("AccountId", accountId);
                lParameter.Add("ServerTs", formatDBDate(DateTime.Now));
                res = dbx.executeNonQuery(query, lParameter);

                if (res == 0)
                {
                    return res;
                }
                else
                {
                    query = "select Max(v.Id) from vet_static_details v where v.AddedBy=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("AddedBy", userName);
                    maxId = Convert.ToInt16(dbx.executeScalar(query, lParameter));

                    query = "INSERT INTO `vet_field_values` (`VetId`, `FieldId`, `Value`) VALUES ";
                    lParameter = new Dictionary<string, object>();
                    foreach (String key in fieldsWithValues.Keys)
                    {
                        query += "(?,?,?),";
                        lParameter.Add("VetId" + key, maxId);
                        lParameter.Add("FieldId" + key, key);
                        lParameter.Add("Value" + key, fieldsWithValues[key]);
                    }
                    query = query.Substring(0, query.Length - 1);
                    res = dbx.executeNonQuery(query, lParameter);
                }
            }


            if (checkListWithValues.Count > 0)
            {
                query = "INSERT INTO `vet_checklist_values` (`VettingId`, `RuleId`, `Score`) VALUES ";
                lParameter = new Dictionary<string, object>();
                foreach (String key in checkListWithValues.Keys)
                {
                    query += "(?,?,?),";
                    lParameter.Add("VettingId" + key, maxId);
                    lParameter.Add("RuleId" + key, key);
                    lParameter.Add("Score" + key, checkListWithValues[key]);
                }
                query = query.Substring(0, query.Length - 1);
                res = dbx.executeNonQuery(query, lParameter);
                return maxId;
            }

            return res;
        }

