        public int UpdateDriverForVehicle(string vehicleId, string sessionid, string driverId1, string driverId2, string rfid1, string rfid2)
        {
            DateTime now = DateTime.UtcNow;
            now = now.AddSeconds(GetTimeZoneDiff());


            string AccountId = GetAccountId(sessionid).ToString();
            string query = "update driverinfo d set d.AssignedVehicleId='',d.RFIDTag='' where d.AssignedVehicleId=? and d.AccountId=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AssignedVehicleId", vehicleId);
            lParameter.Add("AccountId", AccountId);
            int res = Convert.ToInt16(dbx.executeNonQuery(query, lParameter));

            try
            {
                query = "update drivervehiclelog set d.Todate=? where Todate is NULL and Vehicleid=? and Driverid !=? and Driverid != ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Todate", formatDBDate(now));
                lParameter.Add("Vehicleid", vehicleId);
                lParameter.Add("driverId1", driverId1);
                lParameter.Add("driverId2", driverId2);
                res = Convert.ToInt16(dbx.executeNonQuery(query, lParameter));
            }
            catch { }

            if (driverId1 != "0")
            {
                query = "update driverinfo d set d.AssignedVehicleId=?,d.DriverNo=?,d.RFIDTag=? where d.DriverId=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("AssignedVehicleId", vehicleId);
                lParameter.Add("DriverNo", 1);
                lParameter.Add("RFIDTag", rfid1);
                lParameter.Add("DriverId", driverId1);
                res = Convert.ToInt16(dbx.executeNonQuery(query, lParameter));
                insertauditdata("Edit", "driverinfo", "DriverId", driverId1);
            }
            if (driverId2 != "0")
            {
                query = "update driverinfo d set d.AssignedVehicleId=?,d.DriverNo=?,d.RFIDTag=? where d.DriverId=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("AssignedVehicleId", vehicleId);
                lParameter.Add("DriverNo", 2);
                lParameter.Add("RFIDTag", rfid2);
                lParameter.Add("DriverId", driverId2);
                res = Convert.ToInt16(dbx.executeNonQuery(query, lParameter));
                insertauditdata("Edit", "driverinfo", "DriverId", driverId2);
            }
            UpdateVehicletoDriverlog(vehicleId);
            return res;
        }
