        public object[] GetRemainder(string Type, string Vehicle, string Period, string sessionId)
        {
            var lParameter = new Dictionary<string, object>();
            string query = "SELECT r.`id`,r.`VehicleId`,r.`RemainderItemId`,r.`DocType`,r.`DocNo`, " +
            "r.`DueDate`,r.`Amount`,r.`IsRepeat`,r.`RepeatForEveryDistance`,r.`CurrentDistance`, " +
            "r.`RepeatForEvery`,r.`RepeatationPeriodIn`,r.`RemaindBefore`,r.`NextDueDate`,r.`LastDueDate`," +
            "r.`SMS`,r.`SMS_MobileNo`,r.`Email`,r.`Email_MailId`,r.`Note`,r.`RemainderType`,m.`Item`,r.`DocumentFile`,r.RemindKMBefore FROM `remainder` r" +
            " join `remainderitemmaster` m on r.`RemainderItemId`=m.`id` where ";
            if (Vehicle == "AllVehicles")
            {
                string Groupid = getGroupId(sessionId).ToString();
                query += "  r.`VehicleId` in (select `VehicleId` from vehiclesgroupsmap where `GroupId`=?)";
                lParameter.Add("Groupid", Groupid);
            }
            else
            {
                query += " r.`VehicleId`=? ";
                lParameter.Add("Vehicle", Vehicle);
            }
            if (Period == "UpComing")
            {
                query += " and r.`DueDate`>=? and r.`DueDate`<=?";
                lParameter.Add("date", DateTime.Today.ToString("yyyy-MM-dd"));
                lParameter.Add("date1", DateTime.Today.AddMonths(6).ToString("yyyy-MM-dd"));
            }
            if (Type != "0")
            {
                query += " and r.`RemainderType`=?";
                lParameter.Add("Type", Type);
            }
            query += " ORDER BY r.RemainderItemId DESC ";
            DataSet vehicles = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = vehicles.Tables[0];
            ArrayList remainderList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                remainderList.Add(row.ItemArray);
            }
            return remainderList.ToArray();
        }
        public DataTable CheckVehicleRemainder(string checkdate)
        {
            string query = "SELECT r.`id`,r.`VehicleId`,r.`RemainderItemId`,r.`DocType`,r.`DocNo`,r.`DueDate`,r.`Amount`," +
            "r.`IsRepeat`,r.`RepeatForEveryDistance`,r.`CurrentDistance`,r.`LastUpdatedDistanceOn`,r.`RepeatForEvery`," +
            "r.`RepeatationPeriodIn`,r.`RemaindBefore`,r.`NextDueDate`,r.`LastDueDate`,r.`SMS`,r.`SMS_MobileNo`,r.`Email`," +
            "r.`Email_MailId`,r.`Note`,r.`RemainderType`,rm.`Item`,	v.`owner`,v.AddressLine1,v.AddressLine2,v.AddressLine3," +
            "v.Email as OwnerEmail,v.ContactNo,v.MobileNo,v.YearOfManufacturer,v.TypeOfBody,rm.AccountId FROM `remainder` r inner join `remainderitemmaster` rm " +
            " on rm.`id`=r.`RemainderItemId` inner join configdata c on c.Truckid=r.VehicleId and c.UID<100000 left join `vehicleinfo` v on v.VehicleId=r.VehicleId where " +
            " (DATE_SUB(r.`DueDate` , INTERVAL r.`RemaindBefore` DAY)<=? or " +
            " (r.`RemainderType`='Service' and r.`CurrentDistance`>=r.`RepeatForEveryDistance` and r.`IsRepeat`=b'1'))" +
            " and (r.SMS=b'1' or r.Email=b'1') ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Date", checkdate);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];

        }
        public DataTable CheckDriverRemainder(string checkdate)
        {
            string query = "SELECT `DriverId`,`Name`,`Father`,Date_Format(`DOB`,'%d/%m/%Y') as DOB,`AddressLine1`,`AddressLine2`,`AddressLine3`,`City`,`State`,`ContactNo`,`MobileNo`," +
            "`LicenceNo`,`IssuedBy`,`LicenceValid`,`LicenceRemainder`,`LRStartBefore`,`LRRepeat`,`LRSMS`,`LRSMS_MobileNo`,`LREmail`,`LREmail_MailId`," +
            "`InsuranceCompany`,`PolicyNo`,`PolicyDate`,`InsuranceRemainder`,`IRStartBefore`,`IRRepeat`,`IRSMS`,`IRSMS_MobileNo`,`IREmail`,`IREmail_MailId`," +
            "`AssignedVehicleId`,`CleanerName`,`CleanerMobile`,`DriverLanguagePreference`,`DriverPhoto`,`AccountId`,`Active`," +
            " (DATE_SUB(`LicenceValid` , INTERVAL `LRStartBefore` DAY)<=?)  as lcr,  " +
            " (DATE_SUB(`PolicyDate` , INTERVAL `IRStartBefore` DAY)<=?) as icr " +
            " FROM `driverinfo`  where " +
            " ( (DATE_SUB(`LicenceValid` , INTERVAL `LRStartBefore` DAY)<=?) or " +
            " (DATE_SUB(`PolicyDate` , INTERVAL `IRStartBefore` DAY)<=?) ) and `Active`=b'1' ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Date", checkdate);
            lParameter.Add("Date1", checkdate);
            lParameter.Add("Date2", checkdate);
            lParameter.Add("Date3", checkdate);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }
