                try
                {
                    dt = formatDBDate(DateTime.ParseExact(newdata[1], "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch
                {
                    dt = formatDBDate(Convert.ToDateTime(newdata[1]));
