            string DocType = newdata[2].ToString();
            string DocNo = newdata[3].ToString();
            string DueDate = newdata[4].ToString();
            string Amount = newdata[5].ToString();
            string IsRepeat = newdata[6].ToString();
            string RepeatForEveryDistance = newdata[7].ToString();
            string RepeatForEvery = newdata[8].ToString();
            string RepeatationPeriodIn = newdata[9].ToString();
            string RemaindBefore = newdata[10].ToString();
            string NextDueDate = newdata[11].ToString();
            string SMS = newdata[12].ToString();
            string SMS_MobileNo = newdata[13].ToString();
            string Email = newdata[14].ToString();
            string Email_MailId = newdata[15].ToString();
            string Note = newdata[16].ToString();
            string RemainderType = newdata[17].ToString();
            string Document = newdata[18].ToString();
            string query = "select id from remainder where REPLACE(VehicleId,' ','')='" + VehicleId.Trim().Replace(" ", "") + "' and RemainderItemId='" + RemainderItemId + "'";
            DataTable dt = dbx.executeQuery(query).Tables[0];
            if (dt.Rows.Count == 0)
            {
                query = "INSERT INTO `remainder` (`VehicleId`, `RemainderItemId`, " +
                "`DocType`, `DocNo`, `DueDate`, `Amount`, `IsRepeat`, `RepeatForEveryDistance`," +
                "`RepeatForEvery`, `RepeatationPeriodIn`, `RemaindBefore`,  " +
                "`NextDueDate`,`LastDueDate`,`SMS`, `SMS_MobileNo`, `Email`, `Email_MailId`, " +
                "`Note`, `RemainderType`,`DocumentFile`) VALUES ('" + VehicleId + "', '" + RemainderItemId + "', '" + DocType + "', " +
                "'" + DocNo + "', '" + DueDate + "', '" + Amount + "', b'" + IsRepeat + "', '" + RepeatForEveryDistance + "'," +
                "'" + RepeatForEvery + "', '" + RepeatationPeriodIn + "', '" + RemaindBefore + "'," +
                "" + NextDueDate + ",'" + DueDate + "', b'" + SMS + "', '" + SMS_MobileNo + "', b'" + Email + "', '" + Email_MailId + "'," +
                "'" + Note + "', '" + RemainderType + "','" + Document + "');";
            }
            else
            {
                string id = dt.Rows[0]["id"].ToString();
                insertauditdata("Edit", "remainder", "id", id);
                query = "Update `remainder` set `VehicleId`='" + VehicleId + "', `RemainderItemId`='" + RemainderItemId + "', " +
                "`DocType`='" + DocType + "', `DocNo`='" + DocNo + "', `DueDate`='" + DueDate + "', " +
                "`Amount`='" + Amount + "', `IsRepeat`=b'" + IsRepeat + "', `RepeatForEveryDistance`= '" + RepeatForEveryDistance + "'," +
                "`RepeatForEvery`='" + RepeatForEvery + "', `RepeatationPeriodIn`='" + RepeatationPeriodIn + "', `RemaindBefore`='" + RemaindBefore + "',  " +
                "`NextDueDate`=" + NextDueDate + ",`LastDueDate`='" + DueDate + "',`SMS`=b'" + SMS + "'," +
                "`SMS_MobileNo`='" + SMS_MobileNo + "', `Email`= b'" + Email + "', `Email_MailId`='" + Email_MailId + "', " +
                "`Note`='" + Note + "', `RemainderType`='" + RemainderType + "'";
                if (!string.IsNullOrEmpty(Document))
                    query = query + ",DocumentFile='" + Document + "' where id=" + id;
                else
                    query = query + " where id=" + id;
                if (dt.Rows.Count >= 2)//Keep one recorde and delete others
                {
                    string deleteids = "0";
                    for (int i = 1; i < dt.Rows.Count; i++)
                    {
                        deleteids += "," + dt.Rows[i]["id"].ToString();
                    }
                    DeleteRemainderData(deleteids);
                }
            }
            return dbx.executeNonQuery(query.ToString()).ToString();
        }
