        string convertDate(string date)
        {
            try
            {
                return formatDBDate(DateTime.ParseExact(date, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));

            }
            catch
            {
                try
                {
                    return Convert.ToDateTime(date).ToString("yyyy-MM-dd");
                }
                catch { return "NULL"; }

            }
        }
        string convertDateTime(string dateTime)
        {
            try
            {
                return formatDBDate(DateTime.ParseExact(dateTime, "dd-MM-yyyy HH:mm", System.Globalization.CultureInfo.InvariantCulture));

            }
            catch
            {
                try
                {
                    return formatDBDate(DateTime.ParseExact(dateTime, "dd/MM/yyyy HH:mm", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch
                {
                    try
                    {
                        return formatDBDate(DateTime.ParseExact(dateTime, "dd/MM/yyyy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));
                    }
                    catch
                    {
                        try
                        {
                            return formatDBDate(Convert.ToDateTime(dateTime));
                        }
                        catch { return "NULL"; }
                    }
                }

            }
        }
