        public DataTable VehicleRenewalExpiry(string VehicleId, string AccountId)
        {

            string query = "select r.Id,r.VehicleId,rm.Item,r.DocType,r.DocNo,Date_Format(r.DueDate,'%d/%m/%Y') as DueDate,If( DATEDIFF(r.DueDate,CURDATE())<0,'Expired', DATEDIFF(r.DueDate,CURDATE())) as DaysLeft " +
                            " from  remainder r " +
                            " left join remainderitemmaster rm on rm.Id=r.RemainderItemId " +
                            " where DATEDIFF(r.DueDate,CURDATE())<=10 and r.VehicleId='" + VehicleId + "'  order by r.DueDate";
            return dbx.executeQuery(query.ToString()).Tables[0];

        }
        public DataTable DriverDataExpiry(string DriverId, string AccountId)
        {

            string query = "select d.DriverId,concat(d.Name,' ',d.UserDefinedDriverId) as Driver,'Licence' as Item,d.LicenceNo as Doc,Date_Format(d.LicenceValid,'%d/%m/%Y') as DueDate," +
                           " If( DATEDIFF(d.LicenceValid,CURDATE())<0,'Expired', DATEDIFF(d.LicenceValid,CURDATE())) as DaysLeft from driverinfo d " +
                           " where  DATEDIFF(d.LicenceValid,CURDATE())<=10  and d.DriverId='" + DriverId + "';";
            return dbx.executeQuery(query.ToString()).Tables[0];

        }
        public object[] VehicleDriverDataExpired(string VehicleId, string DriverId, string SecondDriverId, string AccountId)
        {

            string query = "select * from (select r.Id,'Vehicle' as ForType,r.VehicleId as Name,concat(rm.Item,' ',r.DocType,' ',r.DocNo) as Item, " +
                           " Date_Format(r.DueDate,'%d/%m/%Y') as DueDate,If( DATEDIFF(r.DueDate,CURDATE())<0,'Expired', DATEDIFF(r.DueDate,CURDATE())) as DaysLeft  " +
                           " from  remainder r  " +
                           " left join remainderitemmaster rm on rm.Id=r.RemainderItemId  " +
                           " where DATEDIFF(r.DueDate,CURDATE())<0 and r.VehicleId='" + VehicleId + "'  " +
                           " union  " +
                           " select d.DriverId as Id,'Driver' as ForType,concat(d.Name,' ',d.UserDefinedDriverId) as Name,concat('Licence',' ',d.LicenceNo) as Item, " +
                           " Date_Format(d.LicenceValid,'%d/%m/%Y') as DueDate, " +
                           " If( DATEDIFF(d.LicenceValid,CURDATE())<0,'Expired', DATEDIFF(d.LicenceValid,CURDATE())) as DaysLeft from driverinfo d " +
                           " where  DATEDIFF(d.LicenceValid,CURDATE())<0 and d.DriverId='" + DriverId + "' or d.DriverId='" + SecondDriverId + "') a order by a.DueDate;";
            DataSet vehicles = dbx.executeQuery(query.ToString());
            DataTable table = vehicles.Tables[0];
            ArrayList ExpList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                ExpList.Add(row.ItemArray);
            }
            return ExpList.ToArray();
        }
