            string query = "Select Id From `detailsofplants` where `LoadingPoint`='" + LoadingPoint + "' and `UnloadingPoint`='" + UnloadingPoint + "' and `AccountId`='" + AccId + "'";
            DataTable dt = dbx.executeQuery(query.ToString()).Tables[0];
            if (dt.Rows.Count <= 0)
            {
                query = "insert into detailsofplants(LoadingPoint,UnloadingPoint,AccountId)" +
                      " values('" + LoadingPoint + "','" + UnloadingPoint + "','" + AccId + "')";
                dbx.executeNonQuery(query);
                query = "Select Id From `detailsofplants` where `LoadingPoint`='" + LoadingPoint + "' and `UnloadingPoint`='" + UnloadingPoint + "' and `AccountId`='" + AccId + "'";
                return dbx.executeScalar(query.ToString()).ToString();

            }
            else
            {
                return dt.Rows[0][0].ToString();
            }
        }
        public DataTable CheckGatePassData(string Id, string ColumnName, string AccId)
        {

            string query = " SELECT g.`id`,g.`VehicleId`,g.`DriverId`,g.`PlantId`,g.`Quantity`,g.`AddedOn`,g.`AddedBy`,g.`AccountId`," +
                           " d.Name as DriverName,d.MobileNo as DriverPhone,d.LicenceNo,d.DriverLanguagePreference," +
                           " concat(p.LoadingPoint,'-',p.UnLoadingPoint) as Destination, " +
                           " IF(g.gatepassno<99999, LPAD(g.gatepassno,5,'0'),g.gatepassno)  as gatepassno,g.HelperPId,h.HelperId,h.Name as HelperName,d.UserDefinedDriverId " +
                           " FROM `gatepass` g" +
                           " left join driverinfo d on d.DriverId=g.DriverId" +
                           " left join helperinfo h on h.Id=g.HelperPId" +
                           " left join detailsofplants p on p.Id=g.PlantId where g." + ColumnName + "='" + Id + "' and g.`AccountId`='" + AccId + "'  ORDER BY `AddedOn` DESC LIMIT 1";
            return dbx.executeQuery(query.ToString()).Tables[0];

        }
