        public string AddUserActivity(string PageUrl, string Action, string UI, string login, string UserIP, string Browser, string OperatingSystem, string Table = "", string SqlQuery = "", string Duration = "")
        {
            string ActionTime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string query = "Insert Into `useractivity`(`PageUrl`,`Action`,`ActionTime`,`UI`,`login`,`UserIP`,`Browser`,`OperatingSystem`,`tablename`,`sqlcommand`,`Duration`) values(?,?,?,?,?,?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("PageUrl", PageUrl);
            lParameter.Add("Action", Action);
            lParameter.Add("ActionTime", ActionTime);
            lParameter.Add("UI", UI);
            lParameter.Add("login", login);
            lParameter.Add("UserIP", UserIP);
            lParameter.Add("Browser", Browser);
            lParameter.Add("OperatingSystem", OperatingSystem);
            lParameter.Add("tablename", Table);
            lParameter.Add("sqlcommand", SqlQuery);
            lParameter.Add("Duration", Duration);
            return dbx.executeNonQuery(query.ToString(), lParameter).ToString();

        }
