        public string InsertPlantDetailsData(object myObject)
        {
            Type myType = myObject.GetType();
            System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());

            string Id = props[1].GetValue(myObject, null).ToString();
            string LoadingPoint = props[2].GetValue(myObject, null).ToString();
            string UnLoadingPoint = props[3].GetValue(myObject, null).ToString();
            string LoadingAddress = props[4].GetValue(myObject, null).ToString();
            string UnLoadingAddress = props[5].GetValue(myObject, null).ToString();
            string ContactPerson = props[6].GetValue(myObject, null).ToString();
            string ContactNumber = props[7].GetValue(myObject, null).ToString();
            string EmailId = props[8].GetValue(myObject, null).ToString();
            string Distance = props[9].GetValue(myObject, null).ToString();
            string AccountId = props[10].GetValue(myObject, null).ToString();


            string query = "select id from detailsofplants where LoadingPoint='" + LoadingPoint + "' and UnLoadingPoint='" + UnLoadingPoint + "' and AccountId=" + AccountId;
            if (dbx.executeQuery(query).Tables[0].Rows.Count <= 0)
            {
                query = "INSERT INTO `detailsofplants` (`LoadingPoint`, `UnLoadingPoint`, `LoadingAddress`, `UnLoadingAddress`, `ContactPerson`, `ContactNumber`," +
               "`Distance`, `AccountId`,`EmailId`)" +
               " VALUES ('" + LoadingPoint + "','" + UnLoadingPoint + "','" + LoadingAddress + "','" + UnLoadingAddress + "','" + ContactPerson + "','" + ContactNumber + "'," +
               "'" + Distance + "','" + AccountId + "','" + EmailId + "')";
                string res = dbx.executeNonQuery(query.ToString()).ToString();
                return res + "#" + "0";
            }
            else
            {
                query = "Update `detailsofplants` Set  `LoadingAddress`='" + LoadingAddress + "', `UnLoadingAddress`='" + UnLoadingAddress + "', `ContactPerson`='" + ContactPerson + "', `ContactNumber`='" + ContactNumber + "'," +
               "`Distance`='" + Distance + "',`EmailId`='" + EmailId + "' where LoadingPoint='" + LoadingPoint + "' and UnLoadingPoint='" + UnLoadingPoint + "' and AccountId=" + AccountId;
                string res = dbx.executeNonQuery(query.ToString()).ToString();
                return res + "#" + "1";

            }
        }

