        /// <summary>
        /// Any action insert ,update ,delete will porformed by sql command 
        /// so if we will capture that we will able fetch all information from that sql command only.
        /// and for DML operation on database action name will be DML Operation.
        /// </summary>
        /// <param name="table"></param>
        /// <param name="sqlcommand"></param>
        public void CaptureUserEvent(string table, string sqlcommand)
        {
            string ActionTime = formatDBDate(DateTime.UtcNow);
            //sURL, "Download Template", "NEW", System.Web.HttpContext.Current.Session["UserName"].ToString(), System.Web.HttpContext.Current.Session["UserIPAddress"].ToString(), System.Web.HttpContext.Current.Session["UserBrowser"].ToString(), System.Web.HttpContext.Current.Session["UserOperatingSystem"].ToString()
            string sURL = System.Web.HttpContext.Current.Request.UrlReferrer.Segments[1];
            string query = "Insert Into `useractivity`(`PageUrl`,`Action`,`ActionTime`,`UI`,`login`,`UserIP`,`Browser`,`OperatingSystem`,'tablename','sqlcommand')" +
                " values('" + sURL + "','" + "DML Operation" + "','" + ActionTime + "','" + "NEW" + "','" + System.Web.HttpContext.Current.Session["UserName"].ToString() + "','" + System.Web.HttpContext.Current.Session["UserIPAddress"].ToString() + "','" + System.Web.HttpContext.Current.Session["UserBrowser"].ToString() + "','" + System.Web.HttpContext.Current.Session["UserOperatingSystem"].ToString() + "'" + ",'" + table + "','" + sqlcommand + "')";
        }
