        public object[] GetTodayGatePassData(string sessionid)
        {
            //string userid = getUserId(sessionid).ToString();
            string Today = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff(sessionid)).AddDays(-1));
            string query = "SELECT g.`id`,g.`VehicleId`,g.`DriverId`,g.`PlantId`,g.`Quantity`,g.`AddedOn`,g.`AddedBy`,g.`AccountId`," +
                           " d.Name as DriverName,d.MobileNo as DriverPhone,d.LicenceNo,d.DriverLanguagePreference," +
                           " concat(p.LoadingPoint,'-',p.UnLoadingPoint) as Destination, " +
                           " IF(g.gatepassno<99999, LPAD(g.gatepassno,5,'0'),g.gatepassno)  as gatepassno,g.HelperPId,h.HelperId,h.Name as HelperName,p.LoadingPoint,p.UnLoadingPoint,d.UserDefinedDriverId, " +
                           " g.IsSecondDriver,d2.`DriverId`as DriverId2,d2.Name as DriverName2,d2.MobileNo as DriverPhone2,d2.LicenceNo as LicenceNo2,d2.UserDefinedDriverId as UserDefinedDriverId2,d2.DriverLanguagePreference as DriverLanguagePreference2, " +
                           " g.SendingToApproverFor,g.ApprovedStatus,g.ApprovedBy,g.ApprovedOn,g.ApprovedNote " +
                           " FROM `gatepass` g" +
                           " left join driverinfo d on d.DriverId=g.DriverId" +
                           " left join helperinfo h on h.Id=g.HelperPId" +
                           " left join detailsofplants p on p.Id=g.PlantId" +
                           " left join driverinfo d2 on d2.DriverId=g.DriverId2" +
                           " where g.AddedOn>='" + Convert.ToDateTime(Today).ToString("yyyy-MM-dd") + " 00:00:00' Order by g.AddedOn Desc";
            DataTable GatePass = dbx.executeQuery(query.ToString()).Tables[0];
            ArrayList GatePassList = new ArrayList();
            foreach (DataRow row in GatePass.Rows)
            { GatePassList.Add(row.ItemArray); }
            return GatePassList.ToArray();
        }
