        public string InsertGatePassData(object myObject)
        {
            Type myType = myObject.GetType();
            System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());

            string GatePassId = props[2].GetValue(myObject, null).ToString();
            string VehicleId = props[3].GetValue(myObject, null).ToString();
            string DriverId = props[4].GetValue(myObject, null).ToString().Split('#')[0].ToString();
            string PlantId = props[8].GetValue(myObject, null).ToString();
            string Quantity = props[10].GetValue(myObject, null).ToString();
            string AddedBy = props[12].GetValue(myObject, null).ToString();
            string DriverLang = props[13].GetValue(myObject, null).ToString();
            string AccountId = props[14].GetValue(myObject, null).ToString();
            string addedon = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string HelperId = props[16].GetValue(myObject, null).ToString();
            string IsSecondDriver = props[22].GetValue(myObject, null).ToString();
            string DriverId2 = props[23].GetValue(myObject, null).ToString();
            string SendingToApproverFor = props[29].GetValue(myObject, null).ToString();
            string ApprovedStatus = props[30].GetValue(myObject, null).ToString();

            string query = "Update driverinfo set AssignedVehicleId='" + VehicleId + "' where DriverId=" + DriverId;
            dbx.executeNonQuery(query);
            if (IsSecondDriver == "0")
            {
                query = "Update driverinfo set HelperId='" + HelperId + "' where DriverId=" + DriverId;
                dbx.executeNonQuery(query);
            }
            else
            {
                query = "Update driverinfo set AssignedVehicleId='" + VehicleId + "' where DriverId=" + DriverId2;
                dbx.executeNonQuery(query);
            }
            query = "select Max(gatepassno) from gatepass";
            string maxgatepassno = dbx.executeScalar(query).ToString();
            if (!string.IsNullOrEmpty(maxgatepassno))
                maxgatepassno = (1 + Convert.ToInt32(maxgatepassno)).ToString();
            else
                maxgatepassno = "1";
            query = "select * from gatepass where VehicleId='" + VehicleId + "' and DriverId='" + DriverId + "' and PlantId='" + PlantId + "' and Quantity='" + Quantity + "' and AddedBy='" + AddedBy + "' and AddedOn>='" + Convert.ToDateTime(addedon).AddMinutes(-2).ToString("yyyy-MM-dd HH:mm:ss") + "' and AddedOn<='" + Convert.ToDateTime(addedon).AddMinutes(1).ToString("yyyy-MM-dd HH:mm:ss") + "'";
            if (dbx.executeQuery(query).Tables[0].Rows.Count <= 0)
            {
                query = "Insert into gatepass(`VehicleId`,`DriverId`,`PlantId`,`Quantity`,`AddedOn`,`AddedBy`,`AccountId`,`gatepassno`,HelperPId,IsSecondDriver,DriverId2,SendingToApproverFor,ApprovedStatus)" +
                    " values('" + VehicleId + "','" + DriverId + "','" + PlantId + "','" + Quantity + "','" + addedon + "','" + AddedBy + "','" + AccountId + "','" + maxgatepassno + "','" + HelperId + "','" + IsSecondDriver + "','" + DriverId2 + "','" + SendingToApproverFor + "','" + ApprovedStatus + "')";
                return dbx.executeNonQuery(query).ToString();
            }
            else
            {
                return "1";
            }
        }
