        public string DeleteTransporterInfoData(string ids)
        {
            string[] rems = ids.Split(',');
            string Finalresult = "0";
            for (int i = 0; i < rems.Length; i++)
            {
                insertauditdata("Delete", "transporterinfo", "TransporterId", rems[i].ToString());
                string query = "Delete From `transporterinfo` where TransporterId= ? ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("TransporterId", rems[i].ToString());
                Finalresult = dbx.executeNonQuery(query, lParameter).ToString();
            }
            return Finalresult;
        }
        public object[] GetTransporterDetails(string sessionid)
        {
            string AccountId = GetAccountId(sessionid).ToString();
            string query = "SELECT t.`TransporterId`,t.`Name`,t.`AddressLine1`,t.`AddressLine2`,t.`AddressLine3`," +
                           " `City`,t.`State`,t.`ContactNo`,t.`MobileNo`,t.`EmailId`,t.`AccountId`,t.`Active`,t.`TransNumber`," +
                           " t.ContractType,t.ContractValid,t.AuditedDate,m.Date as LastMeeting,m.NextMeetingDate FROM `transporterinfo` t " +
                           " left join transportermeeting m on m.Id= (select max(e.Id) from  transportermeeting e where e.TransporterId=t.TransporterId) " +
                           " where `AccountId`=? and t.Active=1 Order by Name";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", AccountId);
            DataSet vehicles = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = vehicles.Tables[0];
            ArrayList driverList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                driverList.Add(row.ItemArray);
            }
            return driverList.ToArray();
        }
