        public object[] GetVehicleInfoForHPCL(string sessionId)
        {
            string query = string.Empty;
            query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
                "sessionid ='" + sessionId + "'";
            Object groupIdObj = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(groupIdObj);

            query = "select v.VehicleID,v.VehicleInfo,ti.Name as TransporterName,ti.MobileNo as TransporterMobile,ti.TransNumber," +
                       " d.Name as DriverName,d.MobileNo as DriverMobile,Concat(p.LoadingPoint,'-',p.UnLoadingPoint) as Destination," +
                       " g.Quantity,DATE_FORMAT(g.AddedOn,'%d/%m/%Y %l:%i:%s %p') as AddedOn " +
                       " from vehicles v " +
                       " left join vehicleinfo vi on vi.VehicleId=v.VehicleID " +
                       " left join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                       " left join gatepass g on g.VehicleId=v.VehicleID " +
                       " left join driverinfo d on d.DriverId=g.DriverId " +
                       " left join detailsofplants p on p.Id=g.PlantId  where v.VehicleID in " +
                       " (select vg.VehicleId from vehiclesgroupsmap vg where vg.GroupId='" + groupId + "')" +
                       " order by g.AddedOn desc";
            DataTable dt = dbx.executeQuery(query.ToString()).Tables[0];
            ArrayList vehinfo = new ArrayList();
            foreach (DataRow row in dt.Rows)
            {
                vehinfo.Add(row.ItemArray);
            }
            return vehinfo.ToArray();
        }
