                    strQry.Append("(select GROUP_CONCAT(usersgroupsmap.GroupId) as GroupId from users, sessions, usersgroupsmap where sessions.login = users.login ");
                    strQry.Append("and users.login = usersgroupsmap.Login and sessions.SessionID ='" + sSession + "' ) ");
                    strQry.Append("and vehicles.vehicleId = Temp_ShowPositions.truckId ");
                    strQry.Append("and positiondata.timestamp = Temp_ShowPositions.timestamp ");
                    strQry.Append("and positiondata.TruckId = Temp_ShowPositions.truckId; ");
                    //strQry.Append("DROP TEMPORARY TABLE IF EXISTS Temp_ShowPositions; ");
                    return dbx.executeQuery(strQry.ToString());
                }

                strQry.Clear();
                //strQry.Append("DROP TEMPORARY TABLE IF EXISTS Temp_ShowPositions; ");
                // strQry.Append("CREATE TEMPORARY TABLE Temp_ShowPositions ");
                //strQry.Append("SELECT truckId, MAX(timestamp) as timestamp from positiondata where timestamp < '" + sCurrentDateTime + "' group by truckId; ");
                strQry.Append("Select distinct positiondata.truckId as VehicleId ,vehiclesgroupsmap.GroupId, ");
                strQry.Append("Select distinct positiondata.truckId as VehicleId, ");
                strQry.Append("CAST(DATE_FORMAT(positiondata.timestamp, '%d %b %y, %r') as CHAR) as LastGprsTimeStamp, ");
                strQry.Append("TIMESTAMPDIFF(SECOND,positiondata.timestamp,'" + sCurrentDateTime + "') as GprsActiveTime, ");
                strQry.Append("'" + sMaxGprsDelay + "' as GprsDelay,'" + sMaxGpsDelay + "' as GpsDelay, '" + sMaxSpeedDisplayTime + "' as MaxSpeedDisplayTime, ");
                strQry.Append(" latitude, longitude,  ");
                strQry.Append(" CASE WHEN (TIMESTAMPDIFF(SECOND,positiondata.timestamp,'" + sCurrentDateTime + "') > '" + sMaxSpeedDisplayTime + "' Or ABS(TIMESTAMPDIFF(SECOND,positiondata.timestamp,'" + sCurrentDateTime + "')) > '" + sMaxGprsDelay + "') THEN ");
                strQry.Append("'0' ");
                strQry.Append("ELSE	 ");
                strQry.Append("speed ");
                strQry.Append("END as Speed, UNIX_TIMESTAMP(positiondata.timestamp), vehicles.VehicleInfo,positiondata.Stop, ");
                strQry.Append("IFNULL(vehicles.OnOffType,'NC') as OnOffType ,IFNULL(vehicles.TempSense,'NC') as TempSense,	'70' as MaxSpeed ");

                strQry.Append("FROM positiondata, (SELECT truckId, MAX(timestamp) as timestamp from positiondata where timestamp < '" + sCurrentDateTime + "' group by truckId)Temp_ShowPositions, vehicles, accounts, users, sessions ");

                strQry.Append("where vehicles.AccountID = accounts.ID ");
                strQry.Append("and accounts.ID = users.AccountID ");
                strQry.Append("and users.login = sessions.login ");
                strQry.Append("and vehicles.vehicleId = Temp_ShowPositions.truckId ");
                strQry.Append("and positiondata.timestamp = Temp_ShowPositions.timestamp ");
                strQry.Append("and positiondata.TruckId = Temp_ShowPositions.truckId ");
                strQry.Append("and SessionID = ='" + sSession + "' ; ");
                //strQry.Append("DROP TEMPORARY TABLE IF EXISTS Temp_ShowPositions;");
                return dbx.executeQuery(strQry.ToString());
            }
            catch
            {
                return null;
            }
        }


        public DataSet GetPanicDetail(string sSession, string sCurrentDateTime, string sMaxAlertDelay)
        {
            try
            {
                StringBuilder strQry = new StringBuilder();
                strQry.Append("SELECT VehicleId,ackTimestamp, GROUP_CONCAT(DISTINCT alertTimestamp) as alertTimestamp,  ");
                strQry.Append("GROUP_CONCAT(DISTINCT type) as PanicType, GROUP_CONCAT(DISTINCT   ");
                strQry.Append("CASE WHEN  upper(type) =  'NO GPS SIGNAL' then  'No GPS Signal'  ");
                strQry.Append("WHEN upper(type) = 'BATTERY OK' then  ''  ");
                strQry.Append("WHEN upper(type) = 'BATTERY LOW' then 'Battery Low'  ");
                strQry.Append("WHEN upper(type) = 'PANIC' then 'Panic Button Presses'  ");
                strQry.Append("WHEN upper(type)= 'AC' then 'AC On'  ");
                strQry.Append("WHEN upper(type) = 'TIPPER' then 'Tipper ON'  ");
                strQry.Append("else '' End  ");
                strQry.Append(" ) as Alert, ");
                strQry.Append(" GROUP_CONCAT( cast( concat( type, '@', alertTimestamp ) AS char ))  as  PanicTypeAndAlertTimeStamp ");
                strQry.Append(" FROM panic ");
                strQry.Append("where alertTimestamp > DATE_SUB('" + sCurrentDateTime + "',INTERVAL '" + sMaxAlertDelay + "' second)  ");
                strQry.Append("and  acktimestamp ='0000-00-00 00:00:00'  GROUP BY VehicleId; ");
                return dbx.executeQuery(strQry.ToString());
            }
            catch
            {
                return null;
            }
        }
