        public int insertDayDistance(string vehicleid, DateTime date, string distance, TimeSpan runtime)
        {
            int num = 0;
            try
            {
                string query = "select count(*) from dailydistance d where d.vehicleId=? and d.Date=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleId", vehicleid);
                lParameter.Add("fromDate", formatDBDate(date));
                int dataExists = Convert.ToInt32(dbx.executeScalar(query, lParameter));
                if (dataExists > 0)
                {
                    lParameter.Clear();
                    query = "update dailydistance d set d.Distance=?,runtime=?  where d.vehicleId=? and d.Date=?";
                    lParameter.Add("Distance", distance);
                    lParameter.Add("runtime", runtime.TotalSeconds);
                    lParameter.Add("vehicleid", vehicleid);
                    lParameter.Add("date", formatDBDate(date));
                    num = dbx.executeNonQuery(query, lParameter);
                }
                else
                {
                    query = "insert into dailydistance (date,vehicleid,distance,totaldistance,runtime) values (?,?,?,0,?)";
                    lParameter.Clear();
                    lParameter.Add("date", formatDBDate(date));
                    lParameter.Add("vehicleid", vehicleid);
                    lParameter.Add("Distance", distance);
                    lParameter.Add("runtime", runtime.TotalSeconds);
                    num = dbx.executeNonQuery(query, lParameter);
                }
            }
            catch { num = 0; }
            return num;
        }
        public void InsertDistanceTables(DateTime date, double distance, string vehicleId, TimeSpan runtime)
        {
            //DateTime datePreviousDay = date.AddDays(-1);
            int month = date.Month;
            int year = date.Year;
            double totalDistance = 0.0;
            double lasttotalDistance = 0.0;
            double totalRunTime = 0.0;
            string query;
            try
            {
                query = "select count(*) from dailydistance where vehicleId = " + "'" + vehicleId + "'" +
                                " and month(date) = " + month + " and  year(date) = " + year;
                int dataExists = Convert.ToInt16(dbx.executeScalar(query));
                if (dataExists > 0)
                {
                    query = "select count(*) from dailydistance where vehicleId = " + "'" + vehicleId + "'" +
                                        " and date = " + "'" + formatDBDate(date) + "'";
                    if (Convert.ToInt16(dbx.executeScalar(query)) == 1)
                    {
                        return;
                    }

                    query = "select max(totalDistance) from dailydistance  where month(date) = "
                    + month + " and year(date)= " + year + " and vehicleId = " +
                    "'" + vehicleId + "'";
                    Object lasttotalDistanceObj = dbx.executeScalar(query);
                    lasttotalDistance = Convert.ToDouble(lasttotalDistanceObj);
                    totalDistance = lasttotalDistance + distance;
                    query = "insert into dailydistance(date,vehicleId,distance,runTime) values("
                             + "'" + formatDBDate(date) + "'" + ","
                             + "'" + vehicleId + "'" + ","
                             + distance + "," +
                             +runtime.TotalSeconds + ")";
                    dbx.executeNonQuery(query);
                    query = "select count(*) from MonthlyDistance" + " where vehicleId = " + "'" + vehicleId + "'" +
                                " and month = " + month + " and year = " + year;

                    int entryExists = Convert.ToInt16(dbx.executeScalar(query));
                    if (entryExists == 1)
                    {
                        query = "select sum(runTime) from dailydistance where month(date)="
                               + month + " and year(date) = " + year + " and vehicleid= " + "'" + vehicleId + "'";
                        totalRunTime = Convert.ToDouble(dbx.executeScalar(query));
                        query = "update MonthlyDistance set distance = " + totalDistance + "," + " runtime = " + totalRunTime +
                                    " where vehicleid = " + "'" + vehicleId + "'" +
                                        " and month = " + month + " and year = " + year;
                        dbx.executeNonQuery(query);

                    }


                }
                else
                {
                    query = "insert into dailydistance(date,vehicleId,distance,runtime) values("
                            + "'" + formatDBDate(date) + "'" + ","
                            + "'" + vehicleId + "'" + ","
                            + distance + "," +
                            +runtime.TotalSeconds + ")";
                    dbx.executeNonQuery(query);
                    query = "insert into MonthlyDistance(vehicleid,Month,Year,Distance,runtime) values("
                            + "'" + vehicleId + "'" + ","
                            + month + ","
                            + year + ","
                            + distance + "," +
                            +runtime.TotalSeconds + " )";
                    dbx.executeNonQuery(query);
                }
                /*   if (date.Day.Equals(DateTime.DaysInMonth(year, month)))
                   {
                       query = "select sum(runTime) from dailyDistance where month(date)="
                                   + month + " and year(date) = " + year + " and vehicleid= " + "'" + vehicleId + "'";
                       totalRunTime = Convert.ToInt16(dbx.executeScalar(query));
                       query = "update MonthlyDistance set runtime = " + totalRunTime +
                                   " where vehicleid = " + "'" + vehicleId + "'" +
                                           " and month = " + month + " and year = " + year;
                   } */
            }
            catch (Exception e)
            {
                throw e;
            }
        }

        public void InsertDistanceTables(DateTime fromDate, DateTime toDate, double distance, string vehicleId, TimeSpan runtime)
        {
            //DateTime datePreviousDay = date.AddDays(-1);
            int month = fromDate.Month;
            int year = fromDate.Year;
            DateTime date;
            int numberofdays = toDate.Day - fromDate.Day + 1;
            int daysOffset = 0;
            double totalDistance = 0.0;
            double lasttotalDistance = 0.0;
            double totalRunTime = 0.0;
            string query;
            if (fromDate.Month != toDate.Month && fromDate.Year != toDate.Year)
                throw new Exception("from date and to date should be of same month and same year");
            try
            {
                while (daysOffset < numberofdays)
                {
                    date = fromDate.AddDays(daysOffset);


                    try
                    {
                        query = "select count(*) from dailydistance where vehicleId = " + "'" + vehicleId + "'" +
                                        " and month(date) = " + month + " and  year(date) = " + year;
                        int dataExists = Convert.ToInt16(dbx.executeScalar(query));
                        if (dataExists > 0)
                        {
                            query = "select count(*) from dailydistance where vehicleId = " + "'" + vehicleId + "'" +
                                        " and date = " + "'" + formatDBDate(date) + "'";
                            if (Convert.ToInt16(dbx.executeScalar(query)) == 1)
                                continue;

                            query = "select max(totalDistance) from dailydistance  where month(date) = "
                            + month + " and year(date)= " + year + " and vehicleId = " +
                            "'" + vehicleId + "'";
                            Object lasttotalDistanceObj = dbx.executeScalar(query);
                            lasttotalDistance = Convert.ToDouble(lasttotalDistanceObj);
                            totalDistance = lasttotalDistance + distance;
                            query = "insert into dailydistance(date,vehicleId,distance,TotalDistance,runTime) values("
                                     + "'" + formatDBDate(date) + "'" + ","
                                     + "'" + vehicleId + "'" + ","
                                     + distance + "," +
                                     +totalDistance + ","
                                     + runtime.TotalSeconds + ")";
                            dbx.executeNonQuery(query);
                            query = "select count(*) from MonthlyDistance" + " where vehicleId = " + "'" + vehicleId + "'" +
                                        " and month = " + month + " and year = " + year;

                            int entryExists = Convert.ToInt16(dbx.executeScalar(query));
                            if (entryExists == 1)
                            {
                                query = "select sum(runTime) from dailydistance where month(date)="
                                       + month + " and year(date) = " + year + " and vehicleid= " + "'" + vehicleId + "'";
                                totalRunTime = Convert.ToDouble(dbx.executeScalar(query));
                                query = "update MonthlyDistance set distance = " + totalDistance + "," + " runtime = " + totalRunTime +
                                            " where vehicleid = " + "'" + vehicleId + "'" +
                                                " and month = " + month + " and year = " + year;
                                dbx.executeNonQuery(query);

                            }


                        }
                        else
                        {
                            query = "insert into dailydistance(date,vehicleId,distance,TotalDistance,runtime) values("
                                    + "'" + formatDBDate(date) + "'" + ","
                                    + "'" + vehicleId + "'" + ","
                                    + distance + "," +
                                    +distance + "," +
                                    +runtime.TotalSeconds + ")";
                            dbx.executeNonQuery(query);
                            query = "insert into MonthlyDistance(vehicleid,Month,Year,Distance,runtime) values("
                                    + "'" + vehicleId + "'" + ","
                                    + month + ","
                                    + year + ","
                                    + distance + "," +
                                    +runtime.TotalSeconds + " )";
                            dbx.executeNonQuery(query);
                        }


                    }

                    catch (Exception e)
                    {
                        throw e;
                    }

                    daysOffset += 1;
                }
            }
            catch (Exception e)
            {
                throw e;
            }


        }

