        public string getEstimatedDistancebyVehicles(string vehicleid, DateTime date)
        {
            //double distance;
            string query = "SELECT sum(t.Distance) AS 'Estimated Distance' FROM metro_trip_details t WHERE t.VehicleId = ? AND DATE(t.TripDate) = ? AND t.IsDeleted = 0";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleid.Replace(" ", ""));
            lParameter.Add("fromDate", formatDBDate(date));
            Object distanceObj = dbx.executeScalar(query, lParameter);
            if (distanceObj == null)
                return "null";
            else
                return Convert.ToString(distanceObj);
        }



