            query.Append(" where (minlat <= " + latitude + " ");
            query.Append(" AND minLong <= " + longitude + " ");
            query.Append(" AND maxLat >= " + latitude + " ");
            query.Append(" AND maxLong >= " + longitude + ") ");
            query.Append(" AND Groupid= '" + Groupid + "'");
