            data.Tables[0].Rows.CopyTo(geofence, 0);
            return geofence;
        }
        public DataRow[] GetnearestGeofenc(string groupId, string latitude, string longitude)
        {

            StringBuilder query = new StringBuilder();
            query.Append("select  sqrt((POWER((" + latitude + "-centerlat),2))+(POWER((" + longitude + "-centerlong),2))),Groupid,geofencename,minlat,maxlat,minlong,maxlong,noofhaltinsidegeofence ");
            query.Append(" from maphalttogeofence where sqrt((POWER((" + latitude + "-centerlat),2))+(POWER((" + longitude + "-centerlong),2)))=");
            query.Append("(select min(sqrt((POWER((" + latitude + "-centerlat),2))+(POWER((" + longitude + "-centerlong),2)))) from maphalttogeofence  where Groupid=" + groupId + ")");
            DataSet data = dbx.executeQuery(query.ToString());
            DataRow[] geofence = new DataRow[data.Tables[0].Rows.Count];
            data.Tables[0].Rows.CopyTo(geofence, 0);
            return geofence;

        }
        public int Createmaphalttogeofence(string groupid, string latitude, string longitude, string adjust = "")
        {
            double lat = Convert.ToDouble(latitude), lng = Convert.ToDouble(longitude);
            double minlat = lat - 0.002, minlng = lng - 0.002, maxlat = lat + 0.002, maxlng = lng + 0.002;
            string geofencename = groupid + "_" + lat + "_" + lng;
            string query = "insert into maphalttogeofence values('" + groupid + "'," + lat + "," + lng + "," + minlat + "," + minlng + "," + maxlat + "," + maxlng + ",0,'" + geofencename + "','no')";
            return dbx.executeNonQuery(query);
        }
        public int Updatemaphalttogeofence(string groupId, string geofencename, string centerlat, string centerlong, string minlat, string minlong, string maxlat, string maxlong, string nooftimehalted, string insidegeofenceupdate = "")
        {
            string query = "";
            if (insidegeofenceupdate == "")
                query = " update maphalttogeofence k set k.minlat=" + minlat + ",k.minlong=" + minlong + ",k.maxlat=" + maxlat + ",k.maxlong=" + maxlong + " , noofhaltinsidegeofence = noofhaltinsidegeofence+1  where geofencename='" + geofencename + "' and Groupid='" + groupId + "'";
            //query = " update maphalttogeofence k set k.centerlat=" + centerlat + ",k.centerlong=" + centerlong + ",k.minlat=" + minlat + ",k.minlong=" + minlong + ",k.maxlat=" + maxlat + ",k.maxlong=" + maxlong + " , noofhaltinsidegeofence = noofhaltinsidegeofence+1  where geofencename='" + geofencename + "' and Groupid='" + groupId + "'";
            else
                query = " update maphalttogeofence k set   noofhaltinsidegeofence=noofhaltinsidegeofence+1 where geofencename='" + geofencename + "' and Groupid='" + groupId + "'";
            return dbx.executeNonQuery(query);

