        public DataRow[] GetGapedpointsfromreffroute(string reffroutename)
        {
            StringBuilder query = new StringBuilder();
            query.Append(" select r.routename 'routename',r.sequence 'seq1',r1.sequence 'seq2',(r.minlat+r.maxlat)/2 'centerlat1',(r.minlong+r.maxlong)/2 'centerlong1',");
            query.Append(" (r1.minlat+r1.maxlat)/2 'centerlat2',(r1.minlong+r1.maxlong)/2 'centerlong2',sqrt(((r1.minlat-r.minlat)*(r1.minlat-r.minlat))+((r1.minlong-r.minlong)*(r1.minlong-r.minlong))) 'distance' ");
            query.Append(" ,r.minlat 'minlat1',r.maxlat 'maxlat1',r.minlong 'minlong1',r.maxlong 'maxlong1',r1.minlat 'minlat2',r1.maxlat 'maxlat2',r1.minlong 'minlong2',r1.maxlong 'maxlong2',r.accountid,r.groupid ");
            query.Append(" from (select * from referenceroutedetail where routename='" + reffroutename + "') r ");
            query.Append(" left join ");
            query.Append("(select * from referenceroutedetail where routename='" + reffroutename + "') r1");
            query.Append(" on r.sequence=r1.sequence-1  and r1.sequence is not null ");
            query.Append(" where sqrt(((((r1.minlat+r1.maxlat)/2)-((r.minlat+r.maxlat)/2))*(((r1.minlat+r1.maxlat)/2)-((r.minlat+r.maxlat)/2)))+ ((((r1.minlong+r1.maxlong)/2)-((r.minlong+r.maxlong)/2))*(((r1.minlong+r1.maxlong)/2)-((r.minlong+r.maxlong)/2))))>0.002 ");
            DataSet data = dbx.executeQuery(query.ToString());
            DataRow[] gappoints = new DataRow[data.Tables[0].Rows.Count];
            data.Tables[0].Rows.CopyTo(gappoints, 0);
            return gappoints;
        }

