        public bool CheckUserNamePassword(String login, String password, String loginTable)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select Name, password from ");
            query.Append(loginTable);
            query.Append(" where login=\"" + login + "\";");
            DataSet loginInfo = dbx.executeQuery(query.ToString());
            DataTable table = loginInfo.Tables[0];
            if (table.Rows.Count == 0)
            {
                return false;
            }
            String name = table.Rows[0][0].ToString();
            String storedPassword = table.Rows[0][1].ToString();
            query = new StringBuilder();
            query.Append("select SHA1('");
            query.Append(password);
            query.Append("');");
            Object encryptedPassword = dbx.executeScalar(query.ToString());
            String encryptedPasswordStr;
            if (encryptedPassword.GetType().ToString() == "System.Byte[]")
            {
                encryptedPasswordStr = System.Text.Encoding.ASCII.GetString((System.Byte[])encryptedPassword);
            }
            else
            {
                encryptedPasswordStr = encryptedPassword.ToString();
            }
            if (storedPassword != encryptedPasswordStr)
            {
                return false;
            }
            return true;
        }
        public string ChangeNewPassword(String login, String password)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select SHA1('" + password + "');");
            Object encryptedPassword = dbx.executeScalar(query.ToString());
            query = new StringBuilder();
            query.Append("update users set password=? where login=?");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("password", password);
            lParameter.Add("login", login);
            int numRowsAffected = dbx.executeNonQuery(query.ToString(), lParameter);
            if (numRowsAffected <= 0)
            {
                query = new StringBuilder();
                query.Append("update rp_users set password=? where login=?");
                numRowsAffected = dbx.executeNonQuery(query.ToString(), lParameter);
            }
            return numRowsAffected.ToString();
        }
