                           "from driverinfo di inner join nfcdata nd on di.IMEI=nd.Data and nd.Data<>''" +
                           "inner join plantgatemobile pm on pm.IMEI=nd.IMEI where di.AccountId='" + accid + "' and login='" + accountname + "' and nd.Datetime between '" + fromdate + "' and '" + todate + "' order by nd.Datetime desc";
