        public string EditNoUpdatesAlertSMSNo(string VehicleId, string SMSTo, string sessionid)
        {

            string addedon = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff(sessionid)));
            string query = "";
            if (!VehicleId.Contains(",") && VehicleId != "ALL")
            {
                query = "select truckid from noupdates where truckid=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("truckid", VehicleId);
                if (dbx.executeQuery(query, lParameter).Tables[0].Rows.Count == 0)
                {
                    query = "Replace Into noupdates(truckid,SmsPhone) values(?,?)";
                    lParameter.Clear();
                    lParameter.Add("truckid", VehicleId);
                    lParameter.Add("SmsPhone", SMSTo);
                    dbx.executeNonQuery(query, lParameter);
                }
                else
                {
                    query = "update noupdates set SmsPhone=? where truckid=?;";
                    lParameter.Clear();
                    lParameter.Add("SmsPhone", SMSTo);
                    lParameter.Add("truckid", VehicleId);
                    dbx.executeNonQuery(query, lParameter);
                }
            }
            else if (VehicleId.Contains(",") && VehicleId != "ALL")
            {
                string[] veh = VehicleId.Split(',');
                for (int i = 0; i < veh.Length; i++)
                {
                    query = "select truckid from noupdates where truckid=?";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("truckid", veh[i]);
                    if (dbx.executeQuery(query, lParameter).Tables[0].Rows.Count == 0)
                    {
                        query = "Replace Into noupdates(truckid,SmsPhone) values(?,?)";
                        lParameter.Clear();
                        lParameter.Add("truckid", veh[i]);
                        lParameter.Add("SmsPhone", SMSTo);
                        dbx.executeNonQuery(query, lParameter);
                    }
                    else
                    {
                        query = "update noupdates set SmsPhone=? where truckid=?;";
                        lParameter.Clear();
                        lParameter.Add("SmsPhone", SMSTo);
                        lParameter.Add("truckid", veh[i]);
                        dbx.executeNonQuery(query, lParameter);
                    }
                }

            }
            else if (VehicleId == "ALL")
            {
                var lParameter = new Dictionary<string, object>();
                query = "select v.VehicleId  from noupdates n " +
                " right join vehiclesgroupsmap  v on v.VehicleId=n.truckid  " +
                " inner join usersgroupsmap m on m.GroupId=v.GroupId " +
                " inner join sessions s on s.login=m.login " +
                " where s.SessionID=?";
                lParameter.Add("SessionID", sessionid);
                DataSet ds = dbx.executeQuery(query, lParameter);
                for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
                {
                    query = "select truckid from noupdates where truckid=?";
                    lParameter.Clear();
                    lParameter.Add("truckid", ds.Tables[0].Rows[i]["VehicleId"].ToString());
                    if (dbx.executeQuery(query, lParameter).Tables[0].Rows.Count == 0)
                    {
                        query = "Replace Into noupdates(truckid,SmsPhone) values(?,?)";
                        lParameter.Clear();
                        lParameter.Add("truckid", ds.Tables[0].Rows[i]["VehicleId"].ToString());
                        lParameter.Add("SmsPhone", SMSTo);
                        dbx.executeNonQuery(query, lParameter);
                    }
                    else
                    {
                        query = "update noupdates set SmsPhone=? where truckid=?;";
                        lParameter.Clear();
                        lParameter.Add("SmsPhone", SMSTo);
                        lParameter.Add("truckid", ds.Tables[0].Rows[i]["VehicleId"].ToString());
                        dbx.executeNonQuery(query, lParameter);
                    }
                }
            }
            return "1";
        }
