            string query = "";
            string part = GetDateTablePartitions(Convert.ToDateTime(fromdate), Convert.ToDateTime(todate), partions);
            if (accountidorgroupidflg == "groupid")
                query = "INSERT into `" + positiontable + "`(truckId,Time_Stamp,latitude,longitude,startbit,stopbit,speed) select truckId,TimeStamp,Latitude,Longitude,start,stop,speed from positiondata PARTITION(" + part + ") AS p where timestamp between '" + fromdate + "' and '" + todate + "' and truckId in (select distinct(vehicleid) FROM vehiclesgroupsmap where groupid=" + accountidorgroupid + ")";
            else if (accountidorgroupidflg == "accountid")
                query = "INSERT into `" + positiontable + "`(truckId,Time_Stamp,latitude,longitude,startbit,stopbit,speed) select truckId,TimeStamp,Latitude,Longitude,start,stop,speed from positiondata PARTITION(" + part + ") AS p where timestamp between '" + fromdate + "' and '" + todate + "' and truckId in (select distinct(vehicleid) FROM vehiclesgroupsmap where groupid in (select groupid from accountgroups where accountid=" + accountidorgroupid + "))";
            if (first == "ok")
            {
                dbx.executeNonQuery(query);

            }
            // query = "INSERT into `"+reffeoute+"` select routename,minlat,minlong,maxlat,maxlong,locstr,crossed,timestamp from referenceroutedetail where (case when groupid is null then accountid when groupid is not null then groupid ELSE '0'  END) in (" +groupid+ "," + accountid +")";
            //dbx.executeNonQuery(query);
            query = "update `" + positiontable + "` p, `" + reffeoute + "` r  set p.crossed = 1 where p.latitude between r.minlat and r.maxlat and p.longitude between r.minlong and r.maxlong ";
            dbx.executeNonQuery(query);

        }
