        public DataRow[] fngetallplantgeolocationname(string accountid, string fromdate = "", string todate = "")
        {
            string query = "select  min(sequence) minsq,max(sequence) maxsq from referenceroutedetail where accountid=" + accountid + " group by routename order by routename";
            DataSet data1 = dbx.executeQuery(query);
            DataRow[] value1 = new DataRow[data1.Tables[0].Rows.Count];
            data1.Tables[0].Rows.CopyTo(value1, 0);
            string sequenceno = value1[0].ItemArray[0].ToString() + "," + value1[0].ItemArray[1].ToString();
            for (int i = 1; i < value1.Length; i++)
            {
                if (sequenceno.Contains(value1[i].ItemArray[0].ToString()) == false)
                    sequenceno = sequenceno + "," + value1[i].ItemArray[0].ToString();
                if (sequenceno.Contains(value1[i].ItemArray[1].ToString()) == false)
                    sequenceno = sequenceno + "," + value1[i].ItemArray[1].ToString();
            }
            if ((fromdate == "" || fromdate == null) && (todate == "" || todate == null))
            {
                query = "select locstr,minlat,minlong,maxlat,maxlong,min(distance) distance,routename from (select sqrt(((p.minlatitude-r.minlat)*(p.minlatitude-r.minlat))+((p.minlongitude-r.minlong)*(p.minlongitude-r.minlong))) distance," +
                    " p.locstr,r.routename,r.minlat,r.minlong,r.maxlat,r.maxlong from " +
                    " (select * from plantgeolocations where accountid=" + accountid + ") p,(select * from referenceroutedetail where accountid=" + accountid + " and sequence in(" + sequenceno + ")  ) r " +
                     " where sqrt(((p.minlatitude-r.minlat)*(p.minlatitude-r.minlat))+((p.minlongitude-r.minlong)*(p.minlongitude-r.minlong))) " +
                     " between 0.006 and  0.02 order by p.locstr) a  group by locstr ";


            }
            else
            {

                query = "select locstr,minlat,minlong,maxlat,maxlong,min(distance) distance,routename from (select sqrt(((p.minlatitude-r.minlat)*(p.minlatitude-r.minlat))+((p.minlongitude-r.minlong)*(p.minlongitude-r.minlong))) distance," +
                   " p.locstr,r.routename,r.minlat,r.minlong,r.maxlat,r.maxlong from " +
                   " (select * from plantgeolocations where accountid=" + accountid + ") p,(select * from referenceroutedetail where accountid=" + accountid + " and sequence in(" + sequenceno + ")  ) r " +
                    " where sqrt(((p.minlatitude-r.minlat)*(p.minlatitude-r.minlat))+((p.minlongitude-r.minlong)*(p.minlongitude-r.minlong))) " +
                    " between 0.006 and  0.02 order by p.locstr) a where locstr in (select distinct(locationstr) from vehicleinplant where outtimestamp between '" + fromdate + "' and '" + todate + "') group by locstr ";

            }
            DataSet data = dbx.executeQuery(query);
            DataRow[] value = new DataRow[data.Tables[0].Rows.Count];
            data.Tables[0].Rows.CopyTo(value, 0);
            return value;
        }
        public DataRow[] GetvehicleidouttimedoneinTimeframe(string geofecnename, string fromate, string todate)
        {
            string Fromdate, Todate;
            if (fromate == "" && todate == "")
            {
                int timeZone = GetTimeZoneDiff();
                string timeZoneStr = System.Web.Configuration.WebConfigurationManager.AppSettings["timeZoneOffset"]; ;
                if (timeZoneStr != "")
                {
                    timeZone = Convert.ToInt32(timeZoneStr);
                }
                DateTime indianTime = DateTime.UtcNow;
                indianTime = indianTime.AddSeconds(timeZone);
                string oneminprevioustime = "";
                Fromdate = formatDBDate(indianTime.AddHours(-24));
                Todate = formatDBDate(indianTime);
            }
            else
            {
                Fromdate = fromate;
                Todate = todate;

            }
            string query = "select vehicleid,outtimestamp from vehicleinplant  v where locationstr='" + geofecnename + "' and  v.outtimestamp between '" + Fromdate + "' and '" + Todate + "' " +
                           " and outtimestamp is not null and (outtimestamp-intimestamp)/2400>5 ";

            DataSet data = dbx.executeQuery(query);
            DataRow[] value = new DataRow[data.Tables[0].Rows.Count];
            data.Tables[0].Rows.CopyTo(value, 0);
            return value;


        }
