        public void Insertdattopositiondata_backupandtrackerdata_backup(string vehicleid, string fromtime, string totime)
        {
            string query = "truncate table positiondata_k";
            dbx.executeNonQuery(query);
            query = "truncate table trackerdata_k";
            dbx.executeNonQuery(query);
            query = "INSERT IGNORE INTO positiondata_k(id, TruckID, `TimeStamp`, `Start`, `Stop`, Latitude, Longitude,Speed, FuelLevel, LAC, CI) select  id, TruckID, `TimeStamp`, `Start`, `Stop`, Latitude, Longitude,Speed, FuelLevel, LAC, CI from positiondata " +
                           "where truckid='" + vehicleid + "' and timestamp between '" + fromtime + "' and '" + totime + "'";
            dbx.executeNonQuery(query);
            query = "INSERT IGNORE INTO trackerdata_k(ID,TruckID,FromTimeStamp,ToTimeStamp,Temperature,IdlingInstances,IdlingDuration, AccelerationInstances,DecelerationInstances,Distance,noGPSDuration,AlarmData,CallerPhone,curGSMSigStrength, badSigCount,gprsDataKB,numSMS,numCallIns,numCallOuts,altitude,ServerTS) " +
                    "select ID,TruckID,FromTimeStamp,ToTimeStamp,Temperature,IdlingInstances,IdlingDuration, AccelerationInstances,DecelerationInstances,Distance,noGPSDuration,AlarmData,CallerPhone,curGSMSigStrength, badSigCount,gprsDataKB,numSMS,numCallIns,numCallOuts,altitude,ServerTS " +
                    "from trackerdata t where truckid='" + vehicleid + "' and fromtimestamp between '" + fromtime + "' and '" + totime + "' ";
            dbx.executeNonQuery(query);
        }
        public DataRow[] Latearrivaltrackerdata(string truckid, string fromdate, string todate, string whichtable = "")
        {
            //here we are not using from time to time because we are processing 24 hr data only .and this _back tables have 24 hr data only

            string query = "";
            if (whichtable == "_backup")
                query = "select tr.seqno,tr.truckid,tr.fromtimestamp,tr.serverts,tr.difftime,p.Latitude,p.Longitude from (SELECT @row := @row + 1 as seqno,t.id, t.TruckID,t.FromTimeStamp,t.ServerTS,TIMESTAMPDIFF(MINUTE, t.FromTimeStamp,t.ServerTS) difftime  " +
                              " FROM trackerdata_backup t, (SELECT @row := 0) r  where truckid='" + truckid + "' and TIMESTAMPDIFF(MINUTE, t.FromTimeStamp,t.ServerTS) >40 and curgsmsigstrength<9 order by fromtimestamp asc) tr ,positiondata_backup p " +
                              " where p.id=tr.id and p.TruckID='" + truckid + "' and p.stop!=1 and p.Speed>4.0 and p.TimeStamp = tr.fromtimestamp  order by seqno ";
            else
                query = "select 1,tr.truckid,tr.fromtimestamp,tr.serverts,tr.difftime,p.Latitude,p.Longitude from (SELECT t.id, t.TruckID,t.FromTimeStamp,t.ServerTS,TIMESTAMPDIFF(MINUTE, t.FromTimeStamp,t.ServerTS) difftime  " +
                        " FROM trackerdata_k t  where truckid='" + truckid + "' and TIMESTAMPDIFF(MINUTE, t.FromTimeStamp,t.ServerTS)>40 and curgsmsigstrength<9 and fromtimestamp between '" + fromdate + "' and '" + todate + "' order by fromtimestamp asc) tr ,positiondata_k p " +
                       " where p.id=tr.id and p.TruckID='" + truckid + "' and p.stop!=1 and p.Speed>4.0 and p.TimeStamp = tr.fromtimestamp  order by timestamp ";

            DataSet data = dbx.executeQuery(query);
            DataRow[] latedata = new DataRow[data.Tables[0].Rows.Count];
            data.Tables[0].Rows.CopyTo(latedata, 0);
            return latedata;


        }
