        public int updateoutdirectionvehicleinplant(string vehicleid, string geofeceneme, string intime, string outtime = null)
        {
            string query =
                   "select max(intimestamp) from vehicleinplant g where g.locationstr='" + geofeceneme + "' and vehicleid='" + vehicleid + "' and outtimestamp is null ";
            string tempdate = dbx.executeScalar(query).ToString();
            string date = "";
            if (tempdate != "")
                date = Convert.ToDateTime(tempdate).ToString("yyyy-MM-dd HH:mm:ss");

            string formattedOutTime = null;
            //if (!string.IsNullOrEmpty(outtime))
            //{
            //    formattedOutTime = Convert.ToDateTime(outtime).ToString("yyyy-MM-dd HH:mm:ss");
            //}

            if (!String.IsNullOrEmpty(outtime))
            {
                try
                {
                    formattedOutTime = formatDBDate(DateTime.ParseExact(outtime, "yyyy-MM-dd HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    formattedOutTime = formatDBDate(Convert.ToDateTime(outtime));
                }
            }

            query = "update vehicleinplant set outtimestamp='" + formattedOutTime + "'   where intimestamp='" + date + "' and locationstr='" + geofeceneme + "' and vehicleid='" + vehicleid + "' and outtimestamp is null";
            return dbx.executeNonQuery(query);


        }
