                lParameter.Add("date2", formatDBDate(ToDate));
                return dbx.executeScalar(query, lParameter).ToString();
            }
            catch
            {
                return "0";
            }
            finally
            {
                //dbx.disconnect();
            }
        }
        public DataRow[] GetRejectedData(string groupid, string fromdate, string todate)
        {
            StringBuilder query = new StringBuilder();
            query.Append("  select a.seq,a.vehicleid,a.geofencename,a.vehicletime  from ");
            query.Append(" (select @x:=@x+1 as seq,vehicleid,vehicletime,geofencename from VehicleinplantRejectedData  where ServerTime between'" + fromdate + "' and '" + todate + "' and geofencename is not null order by vehicleid,vehicletime asc)a");
            query.Append(" LEFT JOIN (select @y:=@y+1 as seq,vehicleid,vehicletime,geofencename from VehicleinplantRejectedData  where ServerTime between '" + fromdate + "' and '" + todate + "' and geofencename is not null order by vehicleid,vehicletime asc)b");
            query.Append(" on a.seq=b.seq where");
            query.Append("  a.geofencename!=b.geofencename");
            query.Append(" and a.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid=" + groupid + ") order by a.vehicleid,a.vehicletime ");
            dbx.executeNonQuery("set @x:=0,@y:=1");
            DataSet value = dbx.executeQuery(query.ToString());
            DataRow[] rejectedvalues = new DataRow[value.Tables[0].Rows.Count];
            value.Tables[0].Rows.CopyTo(rejectedvalues, 0);
            return rejectedvalues;

        }
        public DataRow[] GetRejectedData(string groupid, string fromdate, string todate, string dummy = "")
        {
            StringBuilder query = new StringBuilder();
            query.Append(" select vehicleid,geofencename,vehicletime from VehicleinplantRejectedData where ServerTime between '" + fromdate + "' and '" + todate + "' order by vehicleid,servertime desc ");

            DataSet value = dbx.executeQuery(query.ToString());
            DataRow[] rejectedvalues = new DataRow[value.Tables[0].Rows.Count];
            value.Tables[0].Rows.CopyTo(rejectedvalues, 0);
            return rejectedvalues;

        }
