        // 21 Feb 2021 - A new parameter which indicates how the lat/long has been obtained - geoL is added to the function
        // if geoL is false then both the main table and mirror table have identical entries always otherwise on vehiclepositontxt only will be updated
        // and vehiclepositiontxtGL will have the GPS data (last known). This way the latest data is always shown in Landing Page.
        //
        public string writePositionTextFromParser(double latitude, double longitude, DateTime dateTime, string truckId, Boolean geoL = false)
        {
            DateTime now = DateTime.UtcNow;
            now = now.AddSeconds(GetTimeZoneDiff() + 120);
            if (now > dateTime)
            {
                string query = "select timestamp,Latitude,Longitude from vehiclepositiontxt where truckId='" + truckId + "'";
                DataTable dt = dbx.executeQuery(query).Tables[0];
                if (dt.Rows.Count > 0)
                {
                    string ts = dt.Rows[0]["timestamp"].ToString();
                    DateTime test = DateTime.Now;
                    if ((DateTime.TryParse(ts, out test) == true))
                    {
                        if (Convert.ToDateTime(ts) < dateTime)
                        {
                            string lat = dt.Rows[0]["Latitude"].ToString();
                            string longi = dt.Rows[0]["Longitude"].ToString();
                            if (!string.IsNullOrEmpty(lat) && !string.IsNullOrEmpty(longi))
                            {
                                String AddressUpdateRateDistance = System.Web.Configuration.WebConfigurationManager.AppSettings["AddressUpdateRateDistance"];
                                if (string.IsNullOrEmpty(AddressUpdateRateDistance))
                                    AddressUpdateRateDistance = "0.25";
                                double dist = computeDistance(latitude, longitude, Convert.ToDouble(lat), Convert.ToDouble(longi));
                                if (dist >= Convert.ToDouble(AddressUpdateRateDistance))
                                {
                                    //string postxt = getPositionTxt(latitude.ToString(), longitude.ToString(), 3);
                                    string postxt = getPositionTxt(latitude.ToString(), longitude.ToString(), 3, getAccountIdByVehicleId(truckId).ToString());
