        public object[] getLatestPositiontxt(string sessionId)
        {
            try
            {
                var Query = new StringBuilder();
                Query.Append("select vp.truckId,vp.positiontxt,vp.timestamp,vp.Latitude,vp.Longitude ");
                Query.Append("from vehiclesgroupsmap v,sessions s,usersgroupsmap u,vehicles vi,vehiclepositiontxt vp ");
                Query.Append("where s.SessionID= ? and s.login=u.Login and v.GroupId=u.GroupId and vi.VehicleID=v.VehicleId and vi.VehicleID=vp.truckId");
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("SessionID", sessionId);
                DataTable dt = dbx.executeQuery(Query.ToString(), lParameter).Tables[0];
                ArrayList list = new ArrayList();
                foreach (DataRow row in dt.Rows)
                {
                    list.Add(row.ItemArray);
                }
                return list.ToArray();
            }
            catch { return null; }
        }
