        //Get Position Text
        #region Get Position Text
        public string getPositionTxt(string latitude, string longitude, int direction, string accountid = "")
        {
            double lat = Convert.ToDouble(latitude);
            double lon = Convert.ToDouble(longitude);
            String positionTxt = String.Empty;
            string RailwayFlag = "";
            if (!String.IsNullOrEmpty(accountid))
            {
                try
                {
                    RailwayFlag = GetlowBatteryRatio(Convert.ToInt32(accountid));
                }
                catch { }
            }
            positionTxt = getAccurateDBPositionTxt(latitude, longitude, direction, accountid);

            if (String.IsNullOrEmpty(positionTxt) && RailwayFlag.ToLower() != "railway")
            {
                try
                {
                    if (System.Web.HttpContext.Current.Session != null)
                    {
                        if (System.Web.HttpContext.Current.Session["LocationRequest"] != null)
                        {
                            if (System.Web.HttpContext.Current.Session["LocationRequest"].ToString() == "GOOGLE")
                            {
                                //positionTxt = getMMIGeoCodeData(latitude, longitude);
                                positionTxt = getGoogleGeoCodeData(latitude, longitude);
                                if (!String.IsNullOrEmpty(positionTxt))
                                    return positionTxt.Replace("\r", "").Replace("\n", " ").Replace(Environment.NewLine, " ").Replace("#", "");

                            }
                            else
                                if (System.Web.HttpContext.Current.Session["LocationRequest"].ToString().Contains("ACCOUNT"))
                            {
                                int accId = Convert.ToInt32(System.Web.HttpContext.Current.Session["LocationRequest"].ToString().Split('-')[1]);
                                positionTxt = getGeoCodePositionTxt(latitude, longitude, direction, accId);
                                if (!String.IsNullOrEmpty(positionTxt))
                                    return positionTxt.Replace("\r", "").Replace("\n", " ").Replace(Environment.NewLine, " ").Replace("#", "");
                            }
                        }
                    }
                }
                catch { }
            }
            if (String.IsNullOrEmpty(positionTxt))
            {
                positionTxt = getApproxDBPositionTxt(latitude, longitude, accountid);
            }
            if (String.IsNullOrEmpty(positionTxt) && RailwayFlag.ToLower() != "railway")
            {
                positionTxt = getMMIGeoCodeData(latitude, longitude);
            }
            if (!String.IsNullOrEmpty(positionTxt))
            {
                positionTxt = positionTxt.Replace("\r", "").Replace("\n", " ").Replace(Environment.NewLine, " ");
            }
            if (positionTxt != null)
                return positionTxt.Replace("#", "");
            else
                return positionTxt;
        }
        public string getAccurateDBPositionTxt(string latitude, string longitude, int direction, string accountid = "")
        {
            try
            {
                double lat = Convert.ToDouble(latitude);
                double lon = Convert.ToDouble(longitude);
                double distance = 10000.0;
                Object[] values = getLocation(latitude, longitude, 0.005, 0.005, accountid);
                if (values.Length <= 0)
                {
                    values = getLocation(latitude, longitude, 0.01, 0.01, accountid);
                    if (values.Length <= 0)
                        return "";
                }
                int index = 0;
                Object[] row;
                bool fndaccntaddress = false;
                int AccountAddressIndex = 0;
                double min_AccountAddress_distance = 10000.0;
                for (int i = 0; i < values.Length; i++)
                {
                    row = (Object[])(values[i]);
                    double currentLat = Convert.ToDouble(row[5]);
                    double currentLong = Convert.ToDouble(row[6]);
                    double currentDistance = computeDistance(lat, lon, currentLat, currentLong);
                    if (currentDistance < distance)
                    {
                        distance = currentDistance;
                        index = i;
                    }
                    if ((currentDistance <= 0.25 && currentDistance < min_AccountAddress_distance) && !string.IsNullOrEmpty(row[7].ToString()))
                    {
                        AccountAddressIndex = i;
                        min_AccountAddress_distance = currentDistance;
                        fndaccntaddress = true;
                    }
                }
                String positionTxt = "";
                String comma = "";
                System.Text.RegularExpressions.Regex placeRegEx = new System.Text.RegularExpressions.Regex(".*&.*@.*@.*");
                if (fndaccntaddress)
                    row = (Object[])(values[AccountAddressIndex]);
                else
                    row = (Object[])(values[index]);
                int closestAnchorDistance = int.MaxValue;
                int closestAnchorDirection = -1;
                string closestAnchor = null;
                int milestoneAnchorDistance = int.MaxValue;
                int milestoneAnchorDirection = -1;
                string milestoneAnchor = null;
                for (int j = 0; j < 5; j++)
                {
                    try
                    {
                        if (row[j] != null && Convert.ToString(row[j]) != "")
                        {
                            if (j == 1 && placeRegEx.IsMatch((string)row[j]))
                            {
                                string place = (string)row[j];
                                char[] separator1 = { '&' };
                                string[] fragments = place.Split(separator1);
                                if (fragments != null && fragments[0] != "")
                                {
                                    positionTxt += comma + fragments[0];
                                    comma = ", ";
                                }
                                for (int i = 1; i < fragments.Length; i++)
                                {
                                    char[] separator2 = { '@' };
                                    int DIRECTION_INDEX = 0;
                                    int DISTANCE_INDEX = 1;
                                    int ANCHOR_INDEX = 2;
                                    string[] components = fragments[i].Split(separator2);
                                    if (components.Length != 3)
                                    {
                                        continue;
                                    }
                                    int curDistance = Convert.ToInt32(components[DISTANCE_INDEX]);
                                    int curDirection = Convert.ToInt32(components[DIRECTION_INDEX]);
                                    if (curDistance < closestAnchorDistance)
                                    {
                                        closestAnchorDistance = curDistance;
                                        closestAnchorDirection = curDirection;
                                        closestAnchor = components[ANCHOR_INDEX];
                                    }
                                    if (direction >= 0 && Math.Abs(direction - curDirection) <= 1 && curDistance < milestoneAnchorDistance)
                                    {
                                        milestoneAnchorDistance = curDistance;
                                        milestoneAnchorDirection = curDirection;
                                        milestoneAnchor = components[ANCHOR_INDEX];
                                    }
                                }
                                if (closestAnchor != null && closestAnchorDistance <= 5)
                                {
                                    positionTxt += comma + "At " + closestAnchor;
                                    comma = ", ";
                                }
                                else if (milestoneAnchor != null)
                                {
                                    positionTxt += comma + milestoneAnchorDistance + " Km from " + milestoneAnchor;
                                    comma = ", ";
                                }
                                else if (closestAnchor != null)
                                {
                                    positionTxt += comma + closestAnchorDistance + " Km " + compassDirections[(closestAnchorDirection + 4) % 8] + " of " + closestAnchor;
                                    comma = ", ";
                                }
                            }
                            else if (j == 2 && (string)row[2] == (string)row[3])
                            {
                                // If district and city is same,skip city
                                continue;
                            }
                            else if (j == 3 && (closestAnchor != null || milestoneAnchor != null))
                            {
                                // skip district if anchor is used to indicate place.
                                continue;
                            }
                            else
                            {
                                positionTxt += comma + (string)row[j];
                                comma = ", ";
                            }
                        }
                    }
                    catch (Exception)
                    {
                    }
                }
                return positionTxt;
            }
            catch
            {
                throw;
            }
        }
        protected string getApproxDBPositionTxt(string latitude, string longitude, string accountid = "")
        {
            try
            {
                double lat = Convert.ToDouble(latitude);
                double lon = Convert.ToDouble(longitude);
                //Leave out Bangalore 12.97, 77.56. Well NO. There are places in Bangalore which are not mapped
                // within 1 Km so let approx DB work to get the location strings
                //Leave out approx 26 Km each side i.e. 0.17 delta
                //if (lat > 12.80 && lat < 13.14 && lon > 77.39 && lon < 77.73)
                //{
                //	return null;
                //}
                double distance = 10000.0;
                Object[] values;
                string RailwayFlag = "";
                if (!String.IsNullOrEmpty(accountid))
                {
                    try
                    {
                        RailwayFlag = GetlowBatteryRatio(Convert.ToInt32(accountid));
                    }
                    catch { }
                }
                if (RailwayFlag.ToLower() == "railway")
                {
                    values = getLocation(latitude, longitude, 1.59, 1.59, accountid);
                }
                else
                {
                    values = getLocation(latitude, longitude, 0.07, 0.07, "");//Changed 0.17 to 0.07 => (0.07)2 -> 0.14 (approx. 22 KM)
                }
                if (values.Length <= 0)
                {
                    return "";
                }
                int index = 0;
                Object[] row;
                for (int i = 0; i < values.Length; i++)
                {
                    row = (Object[])(values[i]);
                    double currentLat = Convert.ToDouble(row[5]);
                    double currentLong = Convert.ToDouble(row[6]);
                    double currentDistance = computeDistance(lat, lon, currentLat, currentLong);
                    if (currentDistance < distance)
                    {
                        distance = currentDistance;
                        index = i;
                    }
                }
                String positionTxt = "";
                String comma = "";
                System.Text.RegularExpressions.Regex placeRegEx = new System.Text.RegularExpressions.Regex(".*&.*@.*@.*");
                row = (Object[])(values[index]);

                positionTxt = "near ";
                for (int j = 0; j < 5; j++)
                {
                    try
                    {
                        if (j == 2 && (string)row[2] == (string)row[3])
                        {
                            // If district and city is same,skip city
                            continue;
                        }
                        else
                            if (row[j] != null && Convert.ToString(row[j]) != "")
                        {
                            positionTxt += comma + (string)row[j];
                            comma = ", ";
                        }
                    }
                    catch (Exception)
                    {
                    }
                }
                return positionTxt;
            }
            catch
            {
                throw;
            }
        }
        protected string getMMIPositionTxt(string latitude, string longitude)
        {
            try
            {
                //return "<resultset type='reverseGeocode'><result num='1'><road name='2nd Cross Road' routeNo='null' alternateName='null'/><fow name='null'/><state name='Karnataka'/><city name='Bangalore'/><locality name='AECS Layout'/><district name='Bangalore'/></result></resultset>";
                //OLD OLD REVERSE GEO CODING API
                //String requestUrl = "http://locator.mapmyindia.com/reverseGeocode/x=" + longitude + "&y=" + latitude + "&type=WGS84";
                // OLD REVERSE GEOCODING API
                //String requestUrl = "http://senseltelematics.com/Handlers/ReverseMappingRedirect.ashx?mmiAPI/reverseGeocode/x=" + longitude + "&y=" + latitude + "&key=455b3696b64aa2096ec3d831649e4e1a";
                //Latest GeoCoding API - Oct 2011
                String requestUrl = "http://senseltelematics.com/Handlers/ReverseMappingRedirect.ashx?v2.0/reversegeocode/x=" + longitude + "&y=" + latitude + "&type=WGS84&key=fc0d0e8165990568bf28641dd1e0fff7";
                //String requestUrl = "http://apis.mapmyindia.com/v2.0/reversegeocode/x=" + longitude + "&y=" + latitude + "&type=WGS84&key=fc0d0e8165990568bf28641dd1e0fff7";
                String reverseMappingUrl = System.Web.Configuration.WebConfigurationManager.AppSettings["reverseMappingUrl"];
                if (reverseMappingUrl != null)
                {
                    //requestUrl = reverseMappingUrl + "?mmiAPI/reverseGeocodeBeta/x=" + longitude + "&y=" + latitude + "&type=WGS84" + "&key=455b3696b64aa2096ec3d831649e4e1a";
                    requestUrl = reverseMappingUrl + "?v2.0/reversegeocode/x=" + longitude + "&y=" + latitude + "&type=WGS84&key=fc0d0e8165990568bf28641dd1e0fff7";
                }
                System.Net.WebRequest request = System.Net.WebRequest.Create(requestUrl);
                request.Method = "GET";
                System.Net.HttpWebResponse response;
                try
                {
                    response = (System.Net.HttpWebResponse)request.GetResponse();
                }
                catch (Exception)
                {
                    return null;
                }
                Encoding encode = System.Text.Encoding.GetEncoding("utf-8");
                // Pipe the stream to a higher level stream reader with the required encoding format. 
                System.IO.StreamReader readStream = new System.IO.StreamReader(response.GetResponseStream(), encode);
                Char[] read = new Char[256];
                int count;
                String outBuffer = String.Empty;
                String positionTxt = "";
                //StringBuilder outBuffer = new StringBuilder();
                // Read 256 charcters at a time.    
                while ((count = readStream.Read(read, 0, 256)) > 0)
                {
                    // Dump the 256 characters on a string and display the string onto the console.
                    String str = new String(read, 0, count);
                    outBuffer += str;
                }

                // 
                // If there is some error in reverse MMI result then return empty position text
                //
                if (response.StatusCode != System.Net.HttpStatusCode.OK || String.IsNullOrEmpty(outBuffer))
                    return positionTxt;
                //
                // Another possibility is that there is some ERROR in the reverseMapping Handler so try and work around that issue
                //

                int index = outBuffer.IndexOf("<?x");
                if (index < 0) // return empty positionTxt
                    return positionTxt;
                else
                    if (index > 0)  // remove all chars till the XML string
                    outBuffer = outBuffer.Remove(0, index);
                //Response.Write("var OutBuffer=" + outBuffer +  ";\n");
                String comma = "";
                XmlDocument positionXml = new XmlDocument();
                positionXml.LoadXml(outBuffer.ToString());
                String road = String.Empty;
                String route = String.Empty;
                String locality = String.Empty;

                XmlNode roadNode = positionXml.SelectSingleNode("./resultset/result/road/@name");
                if (roadNode != null)
                {
                    road = positionXml.SelectSingleNode("./resultset/result/road/@name").Value;
                    //Response.Write("var PositionTxt=" + road +  ";\n");
                    //if (road != "null" && road != "")
                    if (!String.IsNullOrEmpty(road))
                    {
                        positionTxt += comma + road;
                        comma = ", ";
                    }
                }
                XmlNode routeNode = positionXml.SelectSingleNode("/resultset/result/road/@routeNo");
                if (routeNode != null)
                {
                    route = positionXml.SelectSingleNode("/resultset/result/road/@routeNo").Value;
                    //Response.Write("var PositionTxt=" + route +  ";\n");
                    if (!String.IsNullOrEmpty(route))
                    {
                        positionTxt += comma + route;
                        comma = ", ";
                    }
                }
                XmlNode localityNode = positionXml.SelectSingleNode("/resultset/result/locality/@name");
                if (localityNode != null)
                {
                    locality = positionXml.SelectSingleNode("/resultset/result/locality/@name").Value;
                    // Response.Write("var PositionTxt=" + locality +  ";\n");
                    if (!String.IsNullOrEmpty(locality))
                    {
                        positionTxt += comma + locality;
                        comma = ", ";
                    }
                }

                XmlNode cityNode = positionXml.SelectSingleNode("/resultset/result/city_town_village/@name");
                String city = String.Empty;
                if (cityNode != null)
                {
                    city = positionXml.SelectSingleNode("/resultset/result/city_town_village/@name").Value;

                    if (!String.IsNullOrEmpty(city))
                    {
                        positionTxt += comma + city;
                        comma = ", ";
                    }
                }
                // Don't add district and State for Bangalore!, to make output small
                // Can add other major cities to skip if required
                string district = String.Empty;
                string state = String.Empty;
                if (city != "Bangalore")
                {
                    XmlNode districtNode = positionXml.SelectSingleNode("./resultset/result/district/@name");
                    if (districtNode != null)
                    {
                        district = positionXml.SelectSingleNode("./resultset/result/district/@name").Value;
                        positionTxt += comma + district;
                    }
                    comma = ", ";
                    XmlNode stateNode = positionXml.SelectSingleNode("./resultset/result/state/@name");
                    if (stateNode != null)
                    {
                        state = positionXml.SelectSingleNode("./resultset/result/state/@name").Value;
                        positionTxt += comma + state;
                    }
                }
                insertAddress(road, locality, city, district, state, latitude, longitude); // cache it
                //Response.Write("var PositionTxt=" + positionTxt +  ";\n");
                return positionTxt;
            }
            catch
            {
                throw;
            }
        }
        protected string getGooglePositionTxt(string latitude, string longitude)
        {
            // Google map API 
            String requestUrl = "http://maps.googleapis.com/maps/api/geocode/xml?latlng=" + latitude + "," + longitude + "&sensor=false";

            System.Net.WebRequest request = System.Net.WebRequest.Create(requestUrl);
            request.Method = "GET";
            System.Net.HttpWebResponse response;
            try
            {
                response = (System.Net.HttpWebResponse)request.GetResponse();
            }
            catch (Exception)
            {
                return null;
            }
            Encoding encode = System.Text.Encoding.GetEncoding("utf-8");
            // Pipe the stream to a higher level stream reader with the required encoding format. 
            System.IO.StreamReader readStream = new System.IO.StreamReader(response.GetResponseStream(), encode);
            Char[] read = new Char[256];
            int count;
            String outBuffer = String.Empty;
            // Read 256 charcters at a time.    
            string positionTxt = "";
            while ((count = readStream.Read(read, 0, 256)) > 0)
            {
                // Dump the 256 characters on a string and display the string onto the console.
                String str = new String(read, 0, count);
                outBuffer += str;
            }
            if (response.StatusCode != System.Net.HttpStatusCode.OK)
                return positionTxt;

            string comma = "";
            XmlDocument positionXml = new XmlDocument();
            positionXml.LoadXml(outBuffer);
            string status = positionXml.SelectSingleNode("/GeocodeResponse/status/text()").Value;
            if (status != "OK")
            {
                return positionTxt;
            }
            string address = positionXml.SelectSingleNode("/GeocodeResponse/result/formatted_address/text()").Value;
            if (address != "null" && address != "")
            {
                positionTxt += comma + address;
                comma = ", ";
            }
            return positionTxt;
        }
