        public string getGeoCodePositionTxt(string latitude, string longitude, int direction, int AccountId)
        {
            try
            {
                double lat = Convert.ToDouble(latitude);
                double lon = Convert.ToDouble(longitude);
                double distance = 10000.0;
                String positionTxt = "";
                Object[] values = getLocation(latitude, longitude, 0.05, 0.05, AccountId);
                if (values.Length <= 0)
                {
                    values = getLocation(latitude, longitude, 0.07, 0.07, AccountId); //Changed 0.17 to 0.07 => (0.07)2 -> 0.14 (approx. 22 KM)
                    if (values.Length <= 0)
                        return null;
                    else
                        positionTxt = "near ";
                }
                int index = 0;
                Object[] row;
                bool fndaccntaddress = false;
                int AccountAddressIndex = 0;
                for (int i = 0; i < values.Length; i++)
                {
                    row = (Object[])(values[i]);
                    double currentLat = Convert.ToDouble(row[5]);
                    double currentLong = Convert.ToDouble(row[6]);
                    double currentDistance = computeDistance(lat, lon, currentLat, currentLong);
                    if (currentDistance < distance)
                    {
                        distance = currentDistance;
                        index = i;
                    }
                    if (currentDistance <= 0.25 && !string.IsNullOrEmpty(row[7].ToString()))
                    {
                        AccountAddressIndex = i;
                        fndaccntaddress = true;
                    }
                }

                String comma = "";
                System.Text.RegularExpressions.Regex placeRegEx = new System.Text.RegularExpressions.Regex(".*&.*@.*@.*");
                if (fndaccntaddress)
                    row = (Object[])(values[AccountAddressIndex]);
                else
                    row = (Object[])(values[index]);
                int closestAnchorDistance = int.MaxValue;
                int closestAnchorDirection = -1;
                string closestAnchor = null;
                int milestoneAnchorDistance = int.MaxValue;
                int milestoneAnchorDirection = -1;
                string milestoneAnchor = null;
                for (int j = 0; j < 5; j++)
                {
                    try
                    {
                        if (row[j] != null && Convert.ToString(row[j]) != "")
                        {
                            if (j == 1 && placeRegEx.IsMatch((string)row[j]))
                            {
                                string place = (string)row[j];
                                char[] separator1 = { '&' };
                                string[] fragments = place.Split(separator1);
                                if (fragments != null && fragments[0] != "")
                                {
                                    positionTxt += comma + fragments[0];
                                    comma = ", ";
                                }
                                for (int i = 1; i < fragments.Length; i++)
                                {
                                    char[] separator2 = { '@' };
                                    int DIRECTION_INDEX = 0;
                                    int DISTANCE_INDEX = 1;
                                    int ANCHOR_INDEX = 2;
                                    string[] components = fragments[i].Split(separator2);
                                    if (components.Length != 3)
                                    {
                                        continue;
                                    }
                                    int curDistance = Convert.ToInt32(components[DISTANCE_INDEX]);
                                    int curDirection = Convert.ToInt32(components[DIRECTION_INDEX]);
                                    if (curDistance < closestAnchorDistance)
                                    {
                                        closestAnchorDistance = curDistance;
                                        closestAnchorDirection = curDirection;
                                        closestAnchor = components[ANCHOR_INDEX];
                                    }
                                    if (direction >= 0 && Math.Abs(direction - curDirection) <= 1 && curDistance < milestoneAnchorDistance)
                                    {
                                        milestoneAnchorDistance = curDistance;
                                        milestoneAnchorDirection = curDirection;
                                        milestoneAnchor = components[ANCHOR_INDEX];
                                    }
                                }
                                if (closestAnchor != null && closestAnchorDistance <= 5)
                                {
                                    positionTxt += comma + "At " + closestAnchor;
                                    comma = ", ";
                                }
                                else if (milestoneAnchor != null)
                                {
                                    positionTxt += comma + milestoneAnchorDistance + " Km from " + milestoneAnchor;
                                    comma = ", ";
                                }
                                else if (closestAnchor != null)
                                {
                                    positionTxt += comma + closestAnchorDistance + " Km " + compassDirections[(closestAnchorDirection + 4) % 8] + " of " + closestAnchor;
                                    comma = ", ";
                                }
                            }
                            else if (j == 2 && (string)row[j] == "Bangalore")
                            {
                                // skip district and state if city is Bangalore
                                break;
                            }
                            else if (j == 3 && (closestAnchor != null || milestoneAnchor != null))
                            {
                                // skip district if anchor is used to indicate place.
                                continue;
                            }
                            else
                            {
                                positionTxt += comma + (string)row[j];
                                comma = ", ";
                            }
                        }
                    }
                    catch (Exception)
                    {
                    }
                }
                return positionTxt;
            }
            catch
            {
                throw;
            }
        }

        private string TryGetsPlaceElementValue(System.Xml.Linq.XElement parentEl, string sData, string elementName, string defaultValue = "")
        {
            string Rvalue = String.Empty;
            var foundEl = parentEl.Element(elementName);
            if (foundEl != null)
            {
                Rvalue = foundEl.Value;
            }
            else
            {
                Rvalue = defaultValue;
            }

            if ((!string.IsNullOrEmpty(sData)) && (!string.IsNullOrEmpty(Rvalue)))
                Rvalue = sData + "," + Rvalue;

            if (Rvalue == "")
                Rvalue = sData;

            return Rvalue;
        }
        public double computeDistance(double lat1, double lon1, double lat2, double lon2)
        {
            /*
                 The Haversine formula according to Dr. Math.
                 http://mathforum.org/library/drmath/view/51879.html
        
                 dlon = lon2 - lon1
                 dlat = lat2 - lat1
                 a = (sin(dlat/2))^2 + cos(lat1) * cos(lat2) * (sin(dlon/2))^2
                 c = 2 * atan2(sqrt(a), sqrt(1-a)) 
                 d = R * c
        
                 Where
                     * dlon is the change in longitude
                     * dlat is the change in latitude
                     * c is the great circle distance in Radians.
                     * R is the radius of a spherical Earth.
                     * The locations of the two points in 
                         spherical coordinates (longitude and 
                         latitude) are lon1,lat1 and lon2, lat2.
             */
            double dDistance = Double.MinValue;
            double dLat1InRad = lat1 * (Math.PI / 180.0);
            double dLon1InRad = lon1 * (Math.PI / 180.0);
            double dLat2InRad = lat2 * (Math.PI / 180.0);
            double dLon2InRad = lon2 * (Math.PI / 180.0);

            double dLongitude = dLon2InRad - dLon1InRad;
            double dLatitude = dLat2InRad - dLat1InRad;

            // Intermediate result a.
            double a = Math.Pow(Math.Sin(dLatitude / 2.0), 2.0) +
                       Math.Cos(dLat1InRad) * Math.Cos(dLat2InRad) *
                       Math.Pow(Math.Sin(dLongitude / 2.0), 2.0);

            // Intermediate result c (great circle distance in Radians).
            double c = 2.0 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1.0 - a));

            // Distance.
            // const Double kEarthRadiusMiles = 3956.0;
            const Double kEarthRadiusKms = 6376.5;
            dDistance = kEarthRadiusKms * c;

            return dDistance;
        }
        protected string getGoogleGeoCodeData(string lat, string lon)
        {
            try
            {
                float latitude = float.Parse(lat);
                float longitude = float.Parse(lon);

                var requestUri = "https://maps.googleapis.com/maps/api/geocode/xml?latlng=" + latitude + "," + longitude + "&client=gme-senseltelematics";
                requestUri = Sign(requestUri);
                var request = System.Net.WebRequest.Create(requestUri);
                var response = request.GetResponse();
                var xdoc = System.Xml.Linq.XDocument.Load(response.GetResponseStream());

                if (xdoc.Root.Value == "REQUEST_DENIEDThis API project is not authorized to use this API.")
                    return "";
                if (xdoc.Root.Value == "OVER_QUERY_LIMITYou have exceeded your daily request quota for this API.")
                    return "";
                if (xdoc.Root.Value == "OVER_QUERY_LIMITYou have exceeded your rate-limit for this API.")
                    return "";
                if (xdoc.Root.Value == "ZERO_RESULTS")
                    return "";

                var result = xdoc.Element("GeocodeResponse").Element("result");

                if (result == null)
                    return "";

                string sStreetNumber = string.Empty;
                string sRoute = string.Empty;
                string sNeighborhood = string.Empty;
                string sSublocality = string.Empty;



                string sCity = string.Empty;
                string sDistrict = string.Empty;
                string sState = string.Empty;
                string sCountry = string.Empty;
                string sPincode = string.Empty;

                foreach (var s in xdoc.Element("GeocodeResponse").Descendants("result"))
                {
                    foreach (System.Xml.Linq.XElement element in s.Descendants("address_component"))
                    {
                        string strElement = element.ToString();

                        if (strElement.IndexOf("<type>street_number</type>") != -1)
                        {
                            sStreetNumber = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if (strElement.IndexOf("<type>route</type>") != -1)
                        {
                            sRoute = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>neighborhood</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1))
                        {
                            sNeighborhood = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>sublocality</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1))
                        {
                            if (!string.IsNullOrEmpty(sSublocality))
                                sSublocality = sSublocality + ", " + element.Element("long_name").Value.Replace("Unnamed Road", "");
                            else
                                sSublocality = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>locality</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //City
                        {
                            sCity = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>administrative_area_level_3</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //District
                        {
                            sDistrict = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>administrative_area_level_2</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //District
                        {
                            sDistrict = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>administrative_area_level_1</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //State
                        {
                            sState = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if ((strElement.IndexOf("<type>country</type>") != -1) && (strElement.IndexOf("<type>political</type>") != -1)) //Country
                        {
                            sCountry = element.Element("long_name").Value.Replace("Unnamed Road", "");
                        }
                        else if (strElement.IndexOf("<type>postal_code</type>") != -1)   //PinCode
                        {
                            sPincode = element.Element("long_name").Value.Replace("Unnamed Road", "");
                            if (!string.IsNullOrEmpty(sPincode))
                                sPincode = " - " + sPincode;
                        }
                    }
                }

                string sPlace = string.Empty;
                string sRoad = string.Empty;

                if ((!string.IsNullOrEmpty(sStreetNumber)) && (!string.IsNullOrEmpty(sRoute)))
                    sRoad = sStreetNumber + ", " + sRoute;
                if ((!string.IsNullOrEmpty(sStreetNumber)) && (string.IsNullOrEmpty(sRoute)))
                    sRoad = sStreetNumber;
                if ((string.IsNullOrEmpty(sStreetNumber)) && (!string.IsNullOrEmpty(sRoute)))
                    sRoad = sRoute;
                if ((string.IsNullOrEmpty(sStreetNumber)) && (string.IsNullOrEmpty(sRoute)))
                    sRoad = "";

                if ((!string.IsNullOrEmpty(sNeighborhood)) && (!string.IsNullOrEmpty(sSublocality)))
                    sPlace = sNeighborhood + ", " + sSublocality;
                if ((!string.IsNullOrEmpty(sNeighborhood)) && (string.IsNullOrEmpty(sSublocality)))
                    sPlace = sStreetNumber;
                if ((string.IsNullOrEmpty(sNeighborhood)) && (!string.IsNullOrEmpty(sSublocality)))
                    sPlace = sSublocality;
                if ((string.IsNullOrEmpty(sNeighborhood)) && (string.IsNullOrEmpty(sSublocality)))
                    sPlace = "";

                if (!string.IsNullOrEmpty(sCity))
                    sCity = sCity + sPincode;

                string RoadPlace = string.Empty;
                RoadPlace = sRoad;
                if (string.IsNullOrEmpty(RoadPlace))
                    RoadPlace = sPlace;

                if (string.IsNullOrEmpty(RoadPlace))
                {
                    string rs = result.Element("formatted_address").Value;
                    string[] words = rs.Split(',');
                    RoadPlace = words[0].Replace("Unnamed Road", "");
                    sPlace = RoadPlace;
                }
                insertMapApiLog("Google", "Reverse Geocoding");
                if ((!string.IsNullOrEmpty(RoadPlace)) && (!string.IsNullOrEmpty(sState)) && (!string.IsNullOrEmpty(sDistrict)))
                {
                    AddUpdateGeoCode(sRoad.Replace("'", ""), sPlace.Replace("'", ""), sCity, sDistrict, sState, latitude, longitude);
                    return sRoad.Replace("'", "") + ", " + sPlace.Replace("'", "") + ", " + sCity + ", " + sDistrict + ", " + sState;
                }
                else if ((!string.IsNullOrEmpty(sCity)) && (!string.IsNullOrEmpty(sState)) && (!string.IsNullOrEmpty(sDistrict)))
                {
                    AddUpdateGeoCode(sRoad.Replace("'", ""), sPlace.Replace("'", ""), sCity, sDistrict, sState, latitude, longitude);
                    return (sRoad.Replace("'", "") + ", " + sPlace.Replace("'", "") + ", " + sCity + ", " + sDistrict + ", " + sState).Replace(",,", ",");
                }
                else if ((!string.IsNullOrEmpty(RoadPlace)) || (!string.IsNullOrEmpty(sCity)) || (!string.IsNullOrEmpty(sState)) || (!string.IsNullOrEmpty(sDistrict)))
                {
                    return (sRoad.Replace("'", "") + ", " + sPlace.Replace("'", "") + ", " + sCity + ", " + sDistrict + ", " + sState).Replace(",,", ",");
                }

                return "";
            }
            catch
            {
                return "";
            }
        }

        public void InsertGoogleStatistics(string key)
        {
            try
            {
                string url = HttpContext.Current.Request.Url.AbsoluteUri;
                string query = "INSERT INTO `google_statistics` (`MethodName`, `URL`, `DateTime`) VALUES (?, ?, ?);";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("MethodName", key);
                lParameter.Add("URL", url);
                lParameter.Add("DateTime", formatDBDate(DateTime.Now));
                dbx.executeNonQuery(query, lParameter);
            }
            catch { }
        }

        public string getMMIGeoCodeLatLng(string locstr, string pincode = "")
        {
            try
            {
                string EndPoint = "https://outpost.mapmyindia.com/api/security/oauth/token";
                string HTTPMethod = "POST";
                string ContentType = "application/x-www-form-urlencoded";
                string PostData = "grant_type=client_credentials&client_id=hXSUdcWsRUMTp846ham5KMMerU8Oow6onfm701EhgfVjSafp47ndnA%3D%3D&client_secret=3q5ykeMZ1h5tpVVLPJgK5-pQYfeIfQJ0vhjT8TIMbZN98CEghDbcw4m1b6LS1EML";
                string res = MakeHttpRequest(EndPoint, HTTPMethod, ContentType, PostData);
                System.IO.File.AppendAllText(HostingEnvironment.ApplicationPhysicalPath + "/mmilog.txt", "DateTime: " + DateTime.Now.ToString() + " | POSTMMIData: " + res.ToString() + " | LocationStr: " + locstr.ToString() + " | Pincode: " + pincode.ToString() + Environment.NewLine);
                var data = JsonConvert.DeserializeObject<dynamic>(res);
                string access_token = data["access_token"].ToString();
                string token_type = data["token_type"].ToString();
                locstr = locstr.Replace("#", " ");
                locstr = locstr.Replace("&", " ");
                locstr = HttpContext.Current.Server.UrlEncode(locstr);
                EndPoint = "http://atlas.mapmyindia.com/api/places/geocode?address=" + locstr;
                if (!string.IsNullOrEmpty(pincode))
                    EndPoint += "&bound=" + pincode;
                HTTPMethod = "GET";
                ContentType = "";
                string Headers = "authorization," + token_type + " " + access_token;
                res = MakeHttpRequest(EndPoint, HTTPMethod, ContentType, "", Headers);
                System.IO.File.AppendAllText(HostingEnvironment.ApplicationPhysicalPath + "/mmilog.txt", "DateTime: " + DateTime.Now.ToString() + " | GETMMIData: " + res.ToString() + " | LocationStr: " + locstr.ToString() + " | Pincode: " + pincode.ToString() + Environment.NewLine);
                data = JsonConvert.DeserializeObject<dynamic>(res);
                insertMapApiLog("MMI", "Geocoding");
                return data["copResults"]["latitude"].ToString() + "," + data["copResults"]["longitude"].ToString();
            }
            catch (Exception ex)
            {
                System.IO.File.AppendAllText(HostingEnvironment.ApplicationPhysicalPath + "/mmilog.txt", "DateTime: " + DateTime.Now.ToString() + " | Type: " + ex.GetType().Name.ToString() + " | Exception: " + ex.Message.ToString() + " | LocationStr: " + locstr.ToString() + " | Pincode: " + pincode.ToString() + Environment.NewLine);
                return "No Data";
            }
        }

        public string getGeolocationByLacCi(string lac, int ci, string mcc, string mnc)
        {
            try
            {
                //string query = "select concat(p.Latitude,',',p.Longitude) latlng from positiondata p where p.LAC=? and p.CI=? limit 1";
                //var lParameter = new Dictionary<string, object>();
                //lParameter.Add("LAC", lac);
                //lParameter.Add("CI", ci);
                string location = null;
                DataTable dt = GetLatLngByLACI(lac, ci, mcc, mnc);
                if (dt.Rows.Count == 0)
                {
                    string _EndPoint = @"https://www.googleapis.com/geolocation/v1/geolocate?key=AIzaSyCACZOOfvdmPNZ77Fh-CkIAh52BztqwjGg";
                    string _ContentType = "application/json";
                    // As on 09 Feb 2022 Google geolocation API defaults to considerIP as true which then returns the lat/long corresponding to the server location in case the 
                    // cell Tower information is not found. If the servers are hosted in the US then it returns the US datacentre lat/long!!!!
                    // So explicitly turn considerIP to false in which case it will return a NOT FOUND ERROR
                    string _PostData = "{\r\n \"homeMobileCountryCode\":" + mcc + ",\r\n \"homeMobileNetworkCode\":" + mnc + ",\r\n \"considerIp\":\"false\",\r\n  \"cellTowers\": [\r\n  {\r\n   \"cellId\": " + ci + ",\r\n   \"locationAreaCode\": " + lac + ",\r\n   \"mobileCountryCode\":" + mcc + ",\r\n   \"mobileNetworkCode\":" + mnc + "\r\n  }\r\n ]\r\n}";
                    string json = MakeHttpRequest(_EndPoint, "POST", _ContentType, _PostData);
                    if (!json.Contains("error"))
                    {
                        var data = JsonConvert.DeserializeObject<dynamic>(json);
                        location = data["location"]["lat"].ToString() + "," + data["location"]["lng"].ToString();
                        InsertLACCI_LatLng(lac, ci, mcc, mnc, data["location"]["lat"].ToString(), data["location"]["lng"].ToString());
                        insertMapApiLog("Google - success", "Geolocation");
                    }
                    else
                        insertMapApiLog("Google - ERR-Not Found", "Geolocation");
                }
                else
                {
                    location = dt.Rows[0]["Latitude"].ToString() + "," + dt.Rows[0]["Longitude"].ToString();
                }
                return location;
            }
            catch (Exception ex)
            {
                return null;
            }
        }
        public string getGeolocationByLacCiWithAsset(string assetid, string lac, int ci, string mcc_, string mnc_)
        {
            try
            {
                //string query = "select concat(p.Latitude,',',p.Longitude) latlng from positiondata p where p.LAC=? and p.CI=? limit 1";
                var lParameter = new Dictionary<string, object>();
                //lParameter.Add("LAC", lac);
                //lParameter.Add("CI", ci);
                string location = null;
                string query = "select state from assetstatemap where asset=" + "'" + assetid + "';";

                string assetstate = Convert.ToString(dbx.executeScalar(query));
                if (!string.IsNullOrEmpty(assetstate))
                {
                    query = "select mcc,mnc from mccmncdata where state like " + "'%" + assetstate + "%';";
                    DataSet mobilecodesDS = dbx.executeQuery(query);
                    if (mobilecodesDS.Tables.Count > 0)
                    {
                        if (mobilecodesDS.Tables[0].Rows.Count > 0)
                        {
                            for (int i = 0; i < mobilecodesDS.Tables[0].Rows.Count; i++)
                            {
                                int mcc = Convert.ToInt16(mobilecodesDS.Tables[0].Rows[i]["mcc"]);
                                int mnc = Convert.ToInt16(mobilecodesDS.Tables[0].Rows[i]["mnc"]);
                                DataTable dt = GetLatLngByLACI(lac, ci, mcc.ToString(), mnc.ToString()); // retunrs lat/long if present with lac/ci only
                                if (dt.Rows.Count == 0)
                                {
                                    if (mcc != 0 & mnc != 0)
                                    {
                                        string _EndPoint = @"https://www.googleapis.com/geolocation/v1/geolocate?key=AIzaSyCACZOOfvdmPNZ77Fh-CkIAh52BztqwjGg";
                                        string _ContentType = "application/json";
                                        // As on 09 Feb 2022 Google geolocation API defaults to considerIP as true which then returns the lat/long corresponding to the server location in case the
                                        // cell Tower information is not found. If the servers are hosted in the US then it returns the US datacentre lat/long!!!!
                                        // So explicitly turn considerIP to false in which case it will return a NOT FOUND ERROR
                                        string _PostData = "{\r\n \"homeMobileCountryCode\":" + mcc + ",\r\n \"homeMobileNetworkCode\":" + mnc + ",\r\n \"considerIp\":\"false\",\r\n  \"cellTowers\": [\r\n  {\r\n   \"cellId\": " + ci + ",\r\n   \"locationAreaCode\": " + lac + ",\r\n   \"mobileCountryCode\":" + mcc + ",\r\n   \"mobileNetworkCode\":" + mnc + "\r\n  }\r\n ]\r\n}";
                                        string json = MakeHttpRequest(_EndPoint, "POST", _ContentType, _PostData);
                                        if (!json.Contains("error"))
                                        {

                                            var data = JsonConvert.DeserializeObject<dynamic>(json);
                                            location = data["location"]["lat"].ToString() + "," + data["location"]["lng"].ToString();
                                            InsertLACCI_LatLng(lac, ci, mcc.ToString(), mnc.ToString(), data["location"]["lat"].ToString(), data["location"]["lng"].ToString());
                                            insertMapApiLog("Google - success", "Geolocation");
                                            return location;
                                        }
                                    }
                                }
                                else
                                {
                                    location = dt.Rows[0]["Latitude"].ToString() + "," + dt.Rows[0]["Longitude"].ToString();
                                    return location;
                                }
                            }
                        }
                        else
                        {
                            DataTable dt = GetLatLngByLACI(lac, ci, mcc_, mnc_); // retunrs lat/long if present with lac/ci only
                            if (dt.Rows.Count > 0)
                            {
                                location = dt.Rows[0]["Latitude"].ToString() + "," + dt.Rows[0]["Longitude"].ToString();
                                return location;
                            }
                            else
                            {
                                insertMapApiLog("Google-mccmnc nodata " + assetid, "Geolocation");
                                return null;
                            }
                        }
                    }
                    else
                    {
                        DataTable dt = GetLatLngByLACI(lac, ci, mcc_, mnc_); // retunrs lat/long if present with lac/ci only
                        if (dt.Rows.Count > 0)
                        {
                            location = dt.Rows[0]["Latitude"].ToString() + "," + dt.Rows[0]["Longitude"].ToString();
                            return location;
                        }
                        else
                        {
                            insertMapApiLog("Google-mccmnc nodata " + assetid, "Geolocation");
                            return null;
                        }
                    }
                }
                else
                {  // possible that the device is actully sending correct mcc/mnc combo
                    DataTable dt = GetLatLngByLACI(lac, ci, mcc_, mnc_); // retunrs lat/long if present with lac/ci only
                    if (dt.Rows.Count > 0)
                    {
                        location = dt.Rows[0]["Latitude"].ToString() + "," + dt.Rows[0]["Longitude"].ToString();
                        return location;
                    }
                    else
                    {
                        string _EndPoint = @"https://www.googleapis.com/geolocation/v1/geolocate?key=AIzaSyCACZOOfvdmPNZ77Fh-CkIAh52BztqwjGg";
                        string _ContentType = "application/json";
                        // As on 09 Feb 2022 Google geolocation API defaults to considerIP as true which then returns the lat/long corresponding to the server location in case the
                        // cell Tower information is not found. If the servers are hosted in the US then it returns the US datacentre lat/long!!!!
                        // So explicitly turn considerIP to false in which case it will return a NOT FOUND ERROR
                        string _PostData = "{\r\n \"homeMobileCountryCode\":" + mcc_ + ",\r\n \"homeMobileNetworkCode\":" + mnc_ + ",\r\n \"considerIp\":\"false\",\r\n  \"cellTowers\": [\r\n  {\r\n   \"cellId\": " + ci + ",\r\n   \"locationAreaCode\": " + lac + ",\r\n   \"mobileCountryCode\":" + mcc_ + ",\r\n   \"mobileNetworkCode\":" + mnc_ + "\r\n  }\r\n ]\r\n}";
                        string json = MakeHttpRequest(_EndPoint, "POST", _ContentType, _PostData);
                        if (!json.Contains("error"))
                        {

                            var data = JsonConvert.DeserializeObject<dynamic>(json);
                            location = data["location"]["lat"].ToString() + "," + data["location"]["lng"].ToString();
                            InsertLACCI_LatLng(lac, ci, mcc_, mnc_, data["location"]["lat"].ToString(), data["location"]["lng"].ToString());
                            insertMapApiLog("Google - success", "Geolocation");
                            return location;
                        }
                        else
                        {
                            insertMapApiLog("ERROR - " + assetid, " Geolocation - " + _PostData);
                            return null;
                        }
                    }
                }
                insertMapApiLog("Google- ERROR" + assetid, "Geolocation");
                return null;
            }
            catch (Exception ex)
            {
                insertMapApiLog("Google- Exception " + assetid, "Geolocation");
                return null;
            }
        }
