        public string getMMIGeoCodeData(string lat, string lon)
        {
            try
            {
                string EndPoint = "http://apis.mapmyindia.com/advancedmaps/v1/rvu8ga55okjz3u9qf76rsvgomzdmdd2h/rev_geocode?lat=" + lat + "&lng=" + lon;
                string HTTPMethod = "GET";
                string ContentType = "application/json";
                string res = MakeHttpRequest(EndPoint, HTTPMethod, ContentType);
                var data = JsonConvert.DeserializeObject<dynamic>(res);
                if (data["responseCode"].ToString() == "200")
                {
                    string sRoad = string.Empty;
                    string sPlace = string.Empty;
                    string sCity = string.Empty;
                    string sDistrict = string.Empty;
                    string sState = string.Empty;

                    sRoad = formatMMIGeocodeLocation(data["results"][0]["houseNumber"].ToString(), sRoad);
                    sRoad = formatMMIGeocodeLocation(data["results"][0]["houseName"].ToString(), sRoad);
                    sRoad = formatMMIGeocodeLocation(data["results"][0]["poi"].ToString(), sRoad);
                    sRoad = formatMMIGeocodeLocation(data["results"][0]["street"].ToString(), sRoad);

                    sPlace = formatMMIGeocodeLocation(data["results"][0]["subSubLocality"].ToString(), sPlace);
                    sPlace = formatMMIGeocodeLocation(data["results"][0]["subLocality"].ToString(), sPlace);
                    sPlace = formatMMIGeocodeLocation(data["results"][0]["locality"].ToString(), sPlace);
                    sPlace = formatMMIGeocodeLocation(data["results"][0]["village"].ToString(), sPlace);

                    sCity = formatMMIGeocodeLocation(data["results"][0]["city"].ToString(), sCity);
                    sCity = formatMMIGeocodeLocation(data["results"][0]["subDistrict"].ToString(), sCity);

                    sDistrict = formatMMIGeocodeLocation(data["results"][0]["district"].ToString(), sDistrict);

                    sState = formatMMIGeocodeLocation(data["results"][0]["state"].ToString(), sState);
                    insertMapApiLog("MMI", "Reverse Geocoding");
                    insertAddress(sRoad, sPlace, sCity, sDistrict, sState, lat, lon);
                    return (sRoad + ", " + sPlace + ", " + sCity + ", " + sDistrict + ", " + sState);
                }
                return "";
            }
            catch (Exception ex)
            {
                return "";
            }
        }

        //Code Added By Tushar on 14092023 to divert MMI distance api call via Metro azure server for TLS 1.2 issue
        //GetMMIDistanceMatrixUsingMetroAzureServer
        public string getDistanceByMMIDistanceMatrix(string orglat, string orglong, string destlat, string destlong)
        {
            var jsonObject = new
            {
                latlng = new[]
                    {
                        $"{orglong},{orglat}",
                        $"{destlong},{destlat}"
                }
            };

            string postData = JsonConvert.SerializeObject(jsonObject);

            try
            {
                string EndPoint = "http://metro.vehicle-tracking.co.in/SenselRestService.svc/rest/v3/GetMMIDistanceMatrixUsingSenselRestService";
                string HTTPMethod = "POST";
                string ContentType = "application/json";
                string res = MakeHttpRequest(EndPoint, HTTPMethod, ContentType, postData);
                var jsondata = JsonConvert.DeserializeObject<dynamic>(res);
                //var data = JsonConvert.DeserializeObject<dynamic>(jsondata);
                if (jsondata["responseCode"].ToString() == "200")
                {
                    if (jsondata["results"]["code"].ToString() == "Ok")
                    {
                        return jsondata["results"]["distances"][0][1].ToString();
                    }
                }
                return "NoData";
            }
            catch (Exception ex)
            {
                return "NoData";
            }

        }
        //GetMMIDistanceMatrixUsingMetroAzureServer
        public long[] GetMMIDistanceMatrix(string[] latlong)
        {
            string res = "";
            try
            {
                if (latlong.Length > 0)
                {
                    string EndPoint = "http://metro.vehicle-tracking.co.in/SenselRestService.svc/rest/v3/GetMMIDistanceMatrixUsingSenselRestService";

                    var jsonObject = new
                    {
                        latlng = latlong
                    };

                    string PostData = JsonConvert.SerializeObject(jsonObject);
                    string HTTPMethod = "POST";
                    string ContentType = "application/json";
                    res = MakeHttpRequest(EndPoint, HTTPMethod, ContentType, PostData);
                    var jsondata = JsonConvert.DeserializeObject<dynamic>(res);
                    //var data = JsonConvert.DeserializeObject<dynamic>(jsondata);
                    if (jsondata["responseCode"].ToString() == "200")
                    {
                        if (jsondata["results"]["code"].ToString() == "Ok")
                        {
                            string[] distMat = jsondata["results"]["distances"][0].ToString().Replace("\r\n", "").Replace("[", "").Replace("]", "").Replace(" ", "")
                                .Replace("null", "0").Split(',');
                            //insertMapApiLog("MMI", "Distance Matrix", distMat.Length.ToString());
                            long[] result = new long[distMat.Length];
                            for (int i = 0; i < distMat.Length; i++)
                            {
                                result[i] = Convert.ToInt64(Convert.ToDecimal(distMat[i]) / 1000);
                            }
                            return result;
                        }
                    }
                    //STL_RecordErrorMessage("MMI_Distance_Matrix_" + data.ToString());
                }
                return null;
            }
            catch (Exception ex)
            {
                STL_RecordErrorMessage("MMI_Distance_Matrix_" + ex.ToString() + "-->" + res);
                return null;
            }
        }


