        public string InsertCustomerInfoData(object myObject)
        {
            Type myType = myObject.GetType();
            string query = string.Empty;
            var lParameter = new Dictionary<string, object>();

            System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
            string CustomerId = HttpUtility.HtmlEncode(props[1].GetValue(myObject, null).ToString());
            string Name = HttpUtility.HtmlEncode(props[2].GetValue(myObject, null).ToString());
            string AddressLine1 = HttpUtility.HtmlEncode(props[3].GetValue(myObject, null).ToString());
            string AddressLine2 = HttpUtility.HtmlEncode(props[4].GetValue(myObject, null).ToString());
            string AddressLine3 = HttpUtility.HtmlEncode(props[5].GetValue(myObject, null).ToString());
            string City = HttpUtility.HtmlEncode(props[6].GetValue(myObject, null).ToString());
            string State = HttpUtility.HtmlEncode(props[7].GetValue(myObject, null).ToString());
            string ContactPerson = HttpUtility.HtmlEncode(props[8].GetValue(myObject, null).ToString());
            string MobileNo = HttpUtility.HtmlEncode(props[9].GetValue(myObject, null).ToString());
            string EmailId = HttpUtility.HtmlEncode(props[10].GetValue(myObject, null).ToString());
            string AccountId = HttpUtility.HtmlEncode(props[11].GetValue(myObject, null).ToString());
            string Active = props[12].GetValue(myObject, null).ToString() == "True" ? "1" : "0";
            string CustomerCode = "";
            if (!string.IsNullOrEmpty(Convert.ToString(props[13].GetValue(myObject, null))))
                CustomerCode = HttpUtility.HtmlEncode(props[13].GetValue(myObject, null).ToString());
            else
            {
                query = "select max(customerId) from customerinfo where Name=?";
                lParameter.Add("Name", Name);
                CustomerCode = Name + Convert.ToString(dbx.executeScalar(query, lParameter)); // Taking some value, if it is empty
            }
            string segment = HttpUtility.HtmlEncode(props[14].GetValue(myObject, null).ToString());
            string ExecutiveMobileNo = HttpUtility.HtmlEncode(props[15].GetValue(myObject, null).ToString());
            string CustomerType = HttpUtility.HtmlEncode(props[16].GetValue(myObject, null).ToString());
            string Storage = HttpUtility.HtmlEncode(props[17].GetValue(myObject, null).ToString());
            string DefaultPlant = HttpUtility.HtmlEncode(props[18].GetValue(myObject, null).ToString());
            string RTKM = HttpUtility.HtmlEncode(props[19].GetValue(myObject, null).ToString());
            string SafeLevel = HttpUtility.HtmlEncode(props[20].GetValue(myObject, null).ToString());

            string TransitTime = props[22].GetValue(myObject, null).ToString();
            string Geofence = props[21].GetValue(myObject, null).ToString();
            string ExecutiveName = props[23].GetValue(myObject, null).ToString();
            string ExecutiveNo = props[24].GetValue(myObject, null).ToString();
            string ExecutiveEmail = "";
            if (!string.IsNullOrEmpty(Convert.ToString(props[25].GetValue(myObject, null))))
                ExecutiveEmail = props[25].GetValue(myObject, null).ToString();
            string OfficerName = props[26].GetValue(myObject, null).ToString();
            string OfficerNo = props[27].GetValue(myObject, null).ToString();
            string OfficerEmail = "";
            if (!string.IsNullOrEmpty(Convert.ToString(props[28].GetValue(myObject, null))))
                OfficerEmail = props[28].GetValue(myObject, null).ToString();
            string District = props[29].GetValue(myObject, null).ToString();

            StringBuilder Query = new StringBuilder();

            query = "INSERT INTO `customerinfo` (`Name`,`AddressLine1`, `AddressLine2`, `AddressLine3`," +
                    "`City`, `State`, `ContactPerson`, `MobileNo`,`EmailId`, `AccountId`, `Active`,`CustomerCode`,`segment`,ExecutiveMobileNo,CustomerType,`Storage`,DefaultPlant,SafeLevel,ExpectedTransitTime,GeofenceName,District)" +
                    " VALUES (?,?,?,?,?,?,?,?,?,?,b'" + Active + "',?,?,?,?,?,?,?,?,?,?)";
            lParameter.Clear();
            lParameter.Add("Name", Name);
            lParameter.Add("AddressLine1", AddressLine1);
            lParameter.Add("AddressLine2", AddressLine2);
            lParameter.Add("AddressLine3", AddressLine3);
            lParameter.Add("City", City);
            lParameter.Add("State", State);
            lParameter.Add("ContactPerson", ContactPerson);
            lParameter.Add("MobileNo", MobileNo);
            lParameter.Add("EmailId", EmailId);
            lParameter.Add("AccountId", AccountId);
            lParameter.Add("CustomerCode", CustomerCode);
            lParameter.Add("segment", segment);
            lParameter.Add("ExecutiveMobileNo", ExecutiveMobileNo);
            lParameter.Add("CustomerType", CustomerType);
            lParameter.Add("Storage", Storage);
            lParameter.Add("DefaultPlant", DefaultPlant);
            lParameter.Add("SafeLevel", SafeLevel);
            lParameter.Add("ExpectedTransitTime", TransitTime);
            lParameter.Add("GeofenceName", Geofence);
            lParameter.Add("District", District);

            //query = query.Replace(",'NULL'", ",NULL");//bug Fixed

            string res = dbx.executeNonQuery(query.ToString(), lParameter).ToString();
            if (!String.IsNullOrEmpty(RTKM))
            {
                Query.Clear();
                lParameter.Clear();
                Query.Append("REPLACE INTO `roundtriptime` (`Plant`,`CustomerCode`, `RTKm`) Values (?,?,?)");
                lParameter.Add("Plant", DefaultPlant);
                lParameter.Add("CustomerCode", CustomerCode);
                lParameter.Add("RTKm", RTKM);
                dbx.executeNonQuery(Query.ToString(), lParameter).ToString();
            }
            if (res == "1")
            {
                //Add executive and distict officer details
                query = "select max(customerId) from customerinfo where Name=?";
                lParameter.Clear();
                lParameter.Add("Name", Name);
                string CustId = Convert.ToString(dbx.executeScalar(query, lParameter));
                if (!string.IsNullOrEmpty(ExecutiveName))
                {
                    query = "insert into customer_executive (CustomerId,Name,MobileNo,EmailId) values (?,?,?,?)";
                    lParameter.Clear();
                    lParameter.Add("CustomerId", CustId);
                    lParameter.Add("Name", ExecutiveName);
                    lParameter.Add("MobileNo", ExecutiveNo);
                    lParameter.Add("EmailId", ExecutiveEmail);
                    dbx.executeNonQuery(query, lParameter);
                }
                if (!string.IsNullOrEmpty(OfficerName))
                {
                    query = "insert into district_officer (CustomerId,Name,MobileNo,EmailId) values (?,?,?,?)";
                    lParameter.Clear();
                    lParameter.Add("CustomerId", CustId);
                    lParameter.Add("Name", OfficerName);
                    lParameter.Add("MobileNo", OfficerNo);
                    lParameter.Add("EmailId", OfficerEmail);
                    dbx.executeNonQuery(query, lParameter);
                }
                string GAccId = GetGlobalAccountId(AccountId);
                if (GAccId != "2477")
                {
                    try
                    {
                        query = "insert into dc_source_destination_mapping (UserLogin,CustomerId,Type) values (?,?,?)";
                        lParameter = new Dictionary<string, object>();
                        string userName = System.Web.HttpContext.Current.Session["UserName"].ToString();
                        lParameter.Add("UserLogin", userName);
                        lParameter.Add("CustomerId", CustId);
                        string type = "1";
                        if (CustomerType == "Loading")
                        {
                            type = "0";
                        }
                        lParameter.Add("Type", type);
                        dbx.executeNonQuery(query, lParameter);
                    }
                    catch { }
                }
                PushChangeDataToAPI(CustId, "UpdateCustomerInfo", AccountId);
            }

            return res;
        }
