        public object[] GetCustomerDetails(string sessionid)
        {
            string AccountId = GetAccountId(sessionid).ToString();
            string query = "SELECT i.`CustomerId`,i.`Name`,i.`AddressLine1`,i.`AddressLine2`,i.`AddressLine3`," +
                           " i.`City`,i.`State`,i.`ContactPerson`,i.`MobileNo`,i.`EmailId`,i.`AccountId`,i.`Active`," +
                           " i.`CustomerCode`,i.`segment`,i.ExecutiveMobileNo,i.CustomerType,i.`Storage`,i.DefaultPlant,r.RTKm,i.SafeLevel,i.GeofenceName,i.ExpectedTransitTime,i.District" +
                           " FROM `customerinfo` i" +
                           " left join roundtriptime r on r.Plant=i.DefaultPlant and r.CustomerCode= i.CustomerCode" +
                           " where i.`AccountId`=? Order by Name";
            var lPararmeter = new Dictionary<string, object>();
            lPararmeter.Add("AccountId", AccountId);
            DataSet vehicles = dbx.executeQuery(query.ToString(), lPararmeter);
            DataTable table = vehicles.Tables[0];
            ArrayList driverList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                driverList.Add(row.ItemArray);
            }
            return driverList.ToArray();
        }
        public DataSet GetCustomerData(string sessionid, string CustomerCode = "")
        {
            var lParameter = new Dictionary<string, object>();
            string query = "SELECT i.`CustomerId`,i.`Name`,i.`AddressLine1`,i.`AddressLine2`,i.`AddressLine3`," +
                           " i.`City`,i.`State`,i.`ContactPerson`,i.`MobileNo`,i.`EmailId`,i.`AccountId`,i.`Active`," +
                           " i.`CustomerCode`,i.`segment`,i.ExecutiveMobileNo,i.CustomerType,i.`Storage`,i.DefaultPlant,r.RTKm,i.SafeLevel" +
                           " FROM `customerinfo` i" +
                           " left join roundtriptime r on r.Plant=i.DefaultPlant and r.CustomerCode= i.CustomerCode";
            if (string.IsNullOrEmpty(CustomerCode))
            {
                string AccountId = GetAccountId(sessionid).ToString();
                query += " where i.`AccountId`=? Order by Name";
                lParameter.Add("AccountId", AccountId);
            }
            else
            {
                lParameter.Clear();
                lParameter.Add("CustomerCode", CustomerCode);
                query += " where i.`CustomerCode`=?";
                //query += " where i.`CustomerCode`='" + CustomerCode + "'";
            }
            return dbx.executeQuery(query.ToString(), lParameter);
        }
