        public object[] GetTotalViolationDailyReport(string fromDateStr, string toDateStr, string sessionId)
        {
            int groupid = getGroupId(sessionId);
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            string query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration,s.timestamp," +
                            " s.Location,s.driverName,vg.GroupId,ti.Name,case s.remarks when 'RECORD' Then 0 when 'ALERT' Then 1 when 'ALARM' Then 2 END as MaxRem	" +
                            " from storevehicleviolations PARTITION(" + part + ") AS s " +
                            " join vehiclesgroupsmap vg on vg.VehicleId=s.vehicleId and vg.GroupId=? " +
                            " left join vehicleinfo ag on ag.VehicleId=vg.VehicleId" +
                            " left join transporterinfo ti on ti.TransporterId=ag.Transporter" +
                            " where s.timestamp>=? and s.timestamp<=? and s.`type`!='NORMAL'" +
                            " and (s.remarks like '%record%' or s.remarks like '%alert%' or s.remarks like '%alarm%' or s.remarks like '%LATE NIGHT DRIVING%' )" +
                            " order by s.vehicleId,s.type,s.timestamp,MaxRem DESC";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("timestamp1", fromDateStr);
            lParameter.Add("timestamp2", toDateStr);
            DataTable table = dbx.executeQuery(query.ToString(), lParameter).Tables[0];

            ArrayList lst = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                lst.Add(row.ItemArray);
            }
            return lst.ToArray();
        }
