        public object[] GetTotalNoofViolation(string viovehls, DateTime frmdate, DateTime todate)
        {
            string part = GetDateTablePartitions(frmdate, todate, partions);
            string inparam = string.Empty;
            var lParameter = new Dictionary<string, object>();
            String[] vals = viovehls.Replace("'", "").Replace("\"", "").Split(',');
            for (int i = 0; i < vals.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
            }
            string query = "select s.vehicleId,s.`type`,count(s.duration) as cnt,sum(s.duration) as sm," +
                           " sum((Case s.remarks when 'RECORD' then 60 when 'ALERT' then 40 when  'ALARM' then 10 else 0 End)) as sumbyrem from storevehicleviolations PARTITION(" + part + ") AS s " +
                           " where s.timestamp>=? and s.timestamp<=? and s.`type`!='NORMAL'" +
                           " and (s.remarks like '%record%' or s.remarks like '%alert%' or s.remarks like '%alarm%' or s.remarks like '%LATE NIGHT DRIVING%'  )" +
                           " and s.vehicleId in (" + inparam + ")" +
                           " group by s.vehicleId,s.type " +
                           " order by s.vehicleId,s.type";
            lParameter.Add("timestamp1", formatDBDate(frmdate));
            lParameter.Add("timestamp2", formatDBDate(todate));
            for (int i = 0; i < vals.Length; i++)
            {
                lParameter.Add("vals_" + i, vals[i]);
            }
            DataTable table = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            ArrayList lst = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                lst.Add(row.ItemArray);
            }
            return lst.ToArray();
        }

        public string AddDCAssignData(string VehicleId, List<object> DCData, string sessionId, string DriverMobileNo)
        {
            try
            {
                string AccountId = GetAccountId(sessionId).ToString();
                string userId = getUserId(sessionId).ToString();
                int timeZone = GetTimeZoneDiff(sessionId);
                DateTime now = DateTime.UtcNow.AddSeconds(timeZone);
                string ld_code = "";
                string ld_place = "";

                string query = "select * from vehicledctrip v where v.VehicleID=? and v.IsTripEnds=0";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", VehicleId);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                if (dt != null && dt.Rows.Count > 0)
                {
                    query = "Update vehicledctrip set IsTripEnds=b'1',TripEndsOn=? where `VehicleID`=? and IsTripEnds=0 ";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("TripEndsOn", formatDBDate(now));
                    lParameter.Add("VehicleId", VehicleId);
                    dbx.executeNonQuery(query, lParameter);

                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        PushChangeDataToAPI(dt.Rows[i]["id"].ToString(), "UpdateTripDetails", AccountId);
                    }
                }
                try
                {
                    query = "select concat(customerid,',',plant) from plantlogin where login=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("login", userId);
                    object plant = dbx.executeScalar(query, lParameter);
                    if (plant != null)
                    {
                        if (plant.ToString().Contains(","))
                        {
                            ld_code = plant.ToString().Split(',')[0];
                            ld_place = plant.ToString().Split(',')[1];
                        }
                    }
                }
                catch { }

                query = "Insert Into vehicledctrip(`VehicleID`,`DateTime`,`NoofDcs`,`AddedBy`,`AccountID`,DriverMobileNo,LoadingPlaceName,LoadingCustomerCode)" +
                    " values(?,?,?,?,?,?,?,?)";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", VehicleId);
                lParameter.Add("DateTime", formatDBDate(now));
                lParameter.Add("NoofDcs", DCData.Count);
                lParameter.Add("AddedBy", userId);
                lParameter.Add("AccountID", AccountId);
                lParameter.Add("DriverMobileNo", DriverMobileNo);
                lParameter.Add("LoadingPlaceName", ld_place);
                lParameter.Add("LoadingCustomerCode", ld_code);

                int res = dbx.executeNonQuery(query, lParameter);
                if (res > 0)
                {
                    query = "Select Max(id) from vehicledctrip where VehicleID=? and AddedBy=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("VehicleId", VehicleId);
                    lParameter.Add("userId", userId);
                    string DCTripId = dbx.executeScalar(query, lParameter).ToString();
                    for (int i = 0; i < DCData.Count; i++)
                    {
                        Type myType = DCData[i].GetType();
                        System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
                        string DCNo = props[2].GetValue(DCData[i], null).ToString();
                        string Cust = props[3].GetValue(DCData[i], null).ToString();
                        string Qty = props[10].GetValue(DCData[i], null).ToString();
                        string Remarks = props[16].GetValue(DCData[i], null).ToString();
                        string AcknowledBy = props[17].GetValue(DCData[i], null).ToString();
                        string Filename = props[18].GetValue(DCData[i], null).ToString();
                        query = "Insert Into customerdcassign(`DCNo`,`CustomerId`,`DCTripId`,`Quantity`,`Remarks`,`AcknowledBy`,`FileName`)" +
                        " values(?,?,?,?,?,?,?)";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("DCNo", DCNo);
                        lParameter.Add("Cust", Cust);
                        lParameter.Add("DCTripId", DCTripId);
                        lParameter.Add("Qty", Qty);
                        lParameter.Add("Remarks", Remarks);
                        lParameter.Add("AcknowledBy", AcknowledBy);
                        lParameter.Add("FileName", Filename);
                        dbx.executeNonQuery(query, lParameter);

                    }
                    PushChangeDataToAPI(DCTripId, "UpdateTripInfo", AccountId);
                    return DCTripId;
                }
                else
                    return "0";
            }
            catch
            {
                return "0";
            }

        }

        public string EditDCAssignData(string Id, string VehicleId, List<object> DCData, string sessionId, string DriverMobileNo)
        {
            try
            {
                string AccountId = GetAccountId(sessionId).ToString();
                string userId = getUserId(sessionId).ToString();
                int timeZone = GetTimeZoneDiff(sessionId);
