        public string getCustomerId(string CustomerCode, string EmailID)
        {
            try
            {
                string query = "select customerid,EmailId from customerinfo where CustomerCode='" + CustomerCode + "'";
                DataTable dt = dbx.executeQuery(query).Tables[0];
                if (dt.Rows.Count > 0)
                {
                    string regmail = dt.Rows[0]["EmailId"].ToString();
                    regmail = regmail.ToLower();
                    EmailID = EmailID.ToLower();
                    if (regmail.Contains(","))
                    {
                        string[] arr = regmail.Split(',');
                        for (int i = 0; i < arr.Length; i++)
                        {
                            if (arr[i] == EmailID)
                                return dt.Rows[0]["customerid"].ToString();
                        }
                        return string.Empty;

                    }
                    else
                    {
                        if (regmail == EmailID)
                            return dt.Rows[0]["customerid"].ToString();

                    }

                }
                else if (CustomerCode.Length >= 10)
                {
                    query = "select customerid,EmailId from customerinfo where ExecutiveMobileNo like '%" + CustomerCode + "%'";
                    dt = dbx.executeQuery(query).Tables[0];
                    if (dt.Rows.Count > 0)
                        return CustomerCode;
                }
            }
            catch
            {
                return string.Empty;
            }
            return string.Empty;
        }

        public Object[] GetCustomerDCVehicles(string CustomerCode, string InclNotUnloaded = "0")
        {
            String query = "select distinct v.VehicleID,ca.DCNo,ca.Quantity,v.DateTime,v.AddedBy,v.NoofDcs,case when ci.Segment in ('BOOM / BOOT','ALDS','COMMODITY',null,'') then ci.Name else ci.segment end as Name,ci.CustomerCode,ca.distcovered,ca.distanceupdatedOn,ca.Id,ca.DCTripId,ca.disthavetocover,v.LoadingPlaceName from vehicledctrip v" +
                           " join customerdcassign ca on ca.DCTripId=v.id" +
                           " join customerinfo ci on ci.customerId=ca.CustomerId" +
                           " where ci.CustomerCode='" + CustomerCode + "' and v.IsTripEnds=0 and v.IsCancel=0 and ca.IsCancel=0";
            if (InclNotUnloaded == "0")
                query += " and ca.IsDelivered=0";
            else
                query += " and ca.DeliveredQty is NULL";
            DataSet ds = dbx.executeQuery(query);
            DataTable table = ds.Tables[0];
            if (table.Rows.Count <= 0)
            {
                query = "select  v.VehicleID,ca.DCNo,ca.Quantity,v.DateTime,v.AddedBy,v.NoofDcs,GROUP_CONCAT(case when ci.Segment in ('BOOM / BOOT','ALDS','COMMODITY',null,'') then ci.Name else ci.segment end) as Name,GROUP_CONCAT(ci.CustomerCode) as CustomerCode,ca.distcovered,ca.distanceupdatedOn,ca.Id,ca.DCTripId,ca.disthavetocover,v.LoadingPlaceName from vehicledctrip v" +
                           " join customerdcassign ca on ca.DCTripId=v.id" +
                           " join customerinfo ci on ci.customerId=ca.CustomerId" +
                           " where ci.ExecutiveMobileNo like '%" + CustomerCode + "%' and v.IsTripEnds=0 and v.IsCancel=0 and ca.IsCancel=0";
                if (InclNotUnloaded == "0")
                    query += " and ca.IsDelivered=0 group by v.VehicleID";
                else
                    query += " and ca.DeliveredQty is NULL group by v.VehicleID";
                ds = dbx.executeQuery(query);
                table = ds.Tables[0];
            }
            ArrayList al = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                al.Add(row.ItemArray);
            }
            return al.ToArray();
        }

