        public string getSessionIdByVehicle(string vehicleId)
        {
            try
            {

                string query = "select s.SessionID from vehiclesgroupsmap v" +
                               " join usersgroupsmap u on u.GroupId=v.GroupId" +
                               " join sessions s on s.login=u.Login" +
                               "  where v.VehicleId='" + vehicleId + "' and s.SessionID='c52d1b490c9ac9432532c4ffe7364155b171387c' limit 1";
                DataTable dt = dbx.executeQuery(query).Tables[0];
                if (dt.Rows.Count > 0)
                    return "c52d1b490c9ac9432532c4ffe7364155b171387c";
                else
                    query = "select s.SessionID from vehiclesgroupsmap v" +
                               " join usersgroupsmap u on u.GroupId=v.GroupId" +
                               " join sessions s on s.login=u.Login" +
                               "  where v.VehicleId='" + vehicleId + "' order by v.groupid limit 1";
                return dbx.executeScalar(query).ToString();
            }
            catch
            {
                return string.Empty;
            }
        }
        public object[] GetViolationReport(string fromDateStr, string toDateStr, string viotype, string vehicles, string sessionId, string conditions = "", string page = "")
        {
            string query = string.Empty;
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            string inparam = string.Empty;
            String[] vals = vehicles.Replace("'", "").Replace("\"", "").Split(',');
            for (int i = 0; i < vals.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
            }
            var lParameter = new Dictionary<string, object>();
            if (viotype != "ALL" && !viotype.Contains("','"))
            {
                // Modified Query by on 25/08/2020 : Harish
                // Added the one more Extra Column name samples in Query 
                // Reason : Route Diviation duration details recording in samples column
                query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration,s.timestamp,s.Location,s.latitude,s.longitude,s.maxsamplesval,s.samples " +
                        " from storevehicleviolations PARTITION(" + part + ") AS s " +
                        " where s.timestamp>=? and s.timestamp<=? and s.`type` in (?)  and  s.vehicleId in (" + inparam + ") " + conditions +
                        " order by s.vehicleId,s.type,s.timestamp";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("fromDateStr", fromDateStr);
                lParameter.Add("toDateStr", toDateStr);
                lParameter.Add("viotype", viotype);
                for (int i = 0; i < vals.Length; i++)
                {
                    lParameter.Add("vehl" + i, vals[i]);
                }
            }
            else if (viotype.Contains("','"))
            {
                string inparam2 = string.Empty;
                String[] vals2 = viotype.Replace("'", "").Replace("\"", "").Split(',');
                for (int i = 0; i < vals2.Length; i++)
                {
                    if (i == 0)
                        inparam2 += ("?");
                    else
                        inparam2 += (",?");
                }
                query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration,s.timestamp,s.Location,s.latitude,s.longitude,s.maxsamplesval,s.samples " +
                       " from storevehicleviolations PARTITION(" + part + ") AS s " +
                       " where s.timestamp>=? and s.timestamp<=? and s.`type` in (" + inparam2 + ")  and  s.vehicleId in (" + inparam + ") " + conditions +
                       " order by s.vehicleId,s.type,s.timestamp";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("fromDateStr", fromDateStr);
                lParameter.Add("toDateStr", toDateStr);
                for (int i = 0; i < vals2.Length; i++)
                {
                    lParameter.Add("vehl2_" + i, vals2[i]);
                }
                for (int i = 0; i < vals.Length; i++)
                {
                    lParameter.Add("vehl" + i, vals[i]);
                }
            }
            else
            {
                string allviolations = "";
                string GblAccId = "";
                if (!string.IsNullOrEmpty(sessionId))
                {
                    GblAccId = GetGlobalAccountIdBySession(sessionId);
                    query = "select Group_Concat(CONCAT(\"'\",ViolationKey,\"'\")) as viol from violation_menu_config a where a.Accountid=? and a.IsActive=1";
                    lParameter.Add("Accountid", GetAccountId(sessionId).ToString());
                    DataTable dt = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                    if (dt.Rows.Count > 0)
                    {
                        allviolations = dt.Rows[0]["viol"].ToString();
                    }
                    query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration,s.timestamp,s.Location,s.latitude,s.longitude,s.maxsamplesval,s.samples " +
                            " from storevehicleviolations PARTITION(" + part + ") AS s " +
                            " where s.timestamp>=? and s.timestamp<=? and s.vehicleId in (" + inparam + ") ";
                    if (string.IsNullOrEmpty(allviolations))
                    {
                        // Manually Binding the All Violations of the Customers
                        if (GblAccId == "53" || GblAccId == "178" || GblAccId == "1092" || GblAccId == "3831" || GblAccId == "4164" || GblAccId == "3345")      // Total Accounts
                        {
                            if (page.ToLower() == "baseviolation")
                                allviolations = "'OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','SHORT RUNTIME','TOTAL RUNTIME','NIGHT DRIVING','MAIN DISCONNECTED DRIVING','ROUTE DEVIATION','DAILY RESTTIME','WEEKLY RESTTIME','WEEKLY RUNTIME','DUTY TIME'";//Modified by suvarna on 4/8/2021 to add duty time in base violation report
                            else if (page.ToLower() == "zoneviolation")
                                allviolations = "'JRM OVERSPEEDING','ROUTE DEVIATION','UNSCHEDULED STOP'";
                            else if (page.ToLower() == "jrmviolation")
                                allviolations = "'SHORT RUNTIME','TOTAL RUNTIME','OVERSPEEDING','JRM OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','NIGHT DRIVING'";
                            else
                                allviolations = "'OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','SHORT RUNTIME','TOTAL RUNTIME','NIGHT DRIVING','MAIN DISCONNECTED DRIVING','ROUTE DEVIATION','DAILY RESTTIME','WEEKLY RESTTIME','WEEKLY RUNTIME','JRM OVERSPEEDING','UNSCHEDULED STOP','DUTY TIME'";//Modified by suvarna on 4/8/2021 to add duty time in base violation report
                        }
                        else if (GblAccId == "3717" || GblAccId == "3891")
                        {
                            if (page.ToLower() == "baseviolation")
                                //allviolations = "'OVERSPEEDING','JRM OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','EXCESSIVE RPM','NIGHT DRIVING','ROUTE DEVIATION','SHORT RUNTIME','UNSCHEDULED STOP','FREEWHEELING','EXCESSIVE IDLE','TOTAL RUNTIME'";
                                allviolations = "'OVERSPEEDING','JRM OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','NIGHT DRIVING','ROUTE DEVIATION','SHORT RUNTIME','UNSCHEDULED STOP','TOTAL RUNTIME'";
                        }
                        else if (GblAccId == "4755")
                        {
                            if (page.ToLower() == "baseviolation")
                                allviolations = "'OVERSPEEDING','JRM OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','NIGHT DRIVING','ROUTE DEVIATION','SHORT RUNTIME','UNSCHEDULED STOP','TOTAL RUNTIME','FREEWHEELING','EXCESSIVE IDLE'";

                        }
                        else
                        {
                            allviolations = "'OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','SHORT RUNTIME','TOTAL RUNTIME','NIGHT DRIVING','MAIN DISCONNECTED DRIVING','DUTY TIME'";//Modified by suvarna on 4/8/2021 to add duty time in base violation report
                        }
                    }

                    if (allviolations.Contains("'ALL',"))
                        allviolations.Replace("'ALL',", string.Empty);

                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("fromDateStr", fromDateStr);
                    lParameter.Add("toDateStr", toDateStr);
                    for (int i = 0; i < vals.Length; i++)
                    {
                        lParameter.Add("vehl" + i, vals[i]);
                    }
                    if (!string.IsNullOrEmpty(allviolations))
                    {
                        query += " and s.`type` in (" + allviolations + ")";
                    }
                    else if (GblAccId == "3717" || GblAccId == "3891")
                    {
                        query += " and s.`type` not in ('SCHEDULED STOP','SHORT REST','LONG REST','NORMAL')";
                    }
                    else
                    {
                        query += " and s.`type`!='NORMAL'";
                    }
                    query += " order by s.vehicleId,s.type,s.timestamp";
                }


            }
            DataTable table = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            ArrayList lst = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                lst.Add(row.ItemArray);
            }
            return lst.ToArray();

        }

        public object[] GetZoneViolationReport(string fromDateStr, string toDateStr, string viotype, string vehicles, string sessionId, string conditions = "")
        {
            string query = string.Empty;
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            string inparam = string.Empty;
            String[] vals = vehicles.Replace("'", "").Replace("\"", "").Split(',');
            for (int i = 0; i < vals.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
            }
            var lParameter = new Dictionary<string, object>();
            if (viotype != "ALL" && !viotype.Contains("','"))
            {
                query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration,s.timestamp,s.Location,s.latitude,s.longitude,s.maxsamplesval " +
                        " from storevehicleviolations PARTITION(" + part + ") AS s " +
                        " where s.timestamp>=? and s.timestamp<=? and s.`type`=?  and  s.vehicleId in (" + inparam + ") " + conditions +
                        " order by s.vehicleId,s.type,s.timestamp";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("fromDateStr", fromDateStr);
                lParameter.Add("toDateStr", toDateStr);
                lParameter.Add("viotype", viotype);
                for (int i = 0; i < vals.Length; i++)
                {
                    lParameter.Add("vehl" + i, vals[i]);
                }
            }
            else if (viotype.Contains("','"))
            {
                string inparam2 = string.Empty;
                String[] vals2 = viotype.Replace("'", "").Replace("\"", "").Split(',');
                for (int i = 0; i < vals2.Length; i++)
                {
                    if (i == 0)
                        inparam2 += ("?");
                    else
                        inparam2 += (",?");
                }
                query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration,s.timestamp,s.Location,s.latitude,s.longitude " +
                       " from storevehicleviolations PARTITION(" + part + ") AS s " +
                       " where s.timestamp>=? and s.timestamp<=? and s.`type` in (" + inparam2 + ")  and  s.vehicleId in (" + inparam + ") " + conditions +
                       " order by s.vehicleId,s.type,s.timestamp";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("fromDateStr", fromDateStr);
                lParameter.Add("toDateStr", toDateStr);
                for (int i = 0; i < vals2.Length; i++)
                {
                    lParameter.Add("vehl2_" + i, vals2[i]);
                }
                for (int i = 0; i < vals.Length; i++)
                {
                    lParameter.Add("vehl" + i, vals[i]);
                }
            }
            else
            {
                string allviolations = "";
                if (!string.IsNullOrEmpty(sessionId))
                {
                    query = "select Group_Concat(CONCAT(\"'\",ViolationKey,\"'\")) as viol from violation_menu_config a where a.Accountid=? and a.IsActive=1";
                    lParameter.Add("Accountid", GetAccountId(sessionId).ToString());
                    DataTable dt = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                    if (dt.Rows.Count > 0)
                    {
                        allviolations = dt.Rows[0]["viol"].ToString();
                    }
                }
                query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration,s.timestamp,s.Location,s.latitude,s.longitude " +
                       " from storevehicleviolations PARTITION(" + part + ") AS s " +
                       " where s.timestamp>=? and s.timestamp<=? and  s.vehicleId in (" + inparam + ")  and s.`type` in('JRM OVERSPEEDING','ROUTE DEVIATION','UNSCHEDULED STOP')" + conditions;
                lParameter = new Dictionary<string, object>();
                lParameter.Add("fromDateStr", fromDateStr);
                lParameter.Add("toDateStr", toDateStr);
                for (int i = 0; i < vals.Length; i++)
                {
                    lParameter.Add("vehl" + i, vals[i]);
                }
                if (!string.IsNullOrEmpty(allviolations))
                {
                    query += " and s.`type` in (" + allviolations + ")";
                }
                query += " order by s.vehicleId,s.type,s.timestamp";
            }
            DataTable table = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            ArrayList lst = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                lst.Add(row.ItemArray);
            }
            return lst.ToArray();

        }

