        public DataTable GetDetailedViolationReport(string fromDateStr, string toDateStr, string viotype, string vehicles, string sessionId, string conditions)
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            int gid = getGroupId(sessionId);
            string inparam = string.Empty;
            String[] vals = vehicles.Replace("'", "").Replace("\"", "").Split(',');
            for (int i = 0; i < vals.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
            }
            var lParameter = new Dictionary<string, object>();
            StringBuilder Query = new StringBuilder();
            Query.Append("select s.vehicleId,t.NAME AS 'Haliour',s.`type`,");
            Query.Append("if(s.`type`='OVERSPEEDING',ifnull(p.maxSpeed,pv.maxSpeed), if(s.`type`='JRM OVERSPEEDING',SUBSTRING_INDEX(s.Location,'-',-1),");
            Query.Append("if(s.`type`='HARSH BRAKING',u.ACLHBTH3, if(s.`type`='HIGH ACCELERATION',u.ACLHATH3,if(s.`type`='HARSH CORNERING','',");
            Query.Append("if(s.`type`='FREEWHEELING', ifnull(p.FreewheelingTime,pv.FreewheelingTime),if(s.`type`='EXCESSIVE RPM',");
            Query.Append("ifnull(p.ExcessiveRPM,pv.ExcessiveRPM), if(s.`type`='EXCESSIVE IDLE',ifnull(p.ExcessiveIdle,pv.ExcessiveIdle),");
            Query.Append("if(s.TYPE='NIGHT DRIVING',IFNULL(pv.NightDrivingTime,p.NightDrivingTime),if(s.`type`= 'ROUTE DEVIATION',IFNULL(p.routedeviation,pv.routedeviation),");
            Query.Append("if(s.`type`= 'SHORT RUNTIME',round(IFNULL(p.shortRunDuration,pv.shortRunDuration)/60,0),if(s.`type`= 'TOTAL RUNTIME',round(IFNULL(p.longRunDuration,pv.longRunDuration)/60,0),'')))))))))))) Limits,");
            Query.Append("if(s.`type`='JRM OVERSPEEDING',round(pd.CI * RPMRatio(s.vehicleId)),if(s.TYPE='NIGHT DRIVING' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`= 'ROUTE DEVIATION' or s.`type`='UNSCHEDULED STOP',' ',if(s.`type`='EXCESSIVE RPM',s.samples,round(pd.CI,0)))) AS 'RPM',");
            Query.Append("if(s.`type`='JRM OVERSPEEDING',SUBSTRING_INDEX(s.remarks,'-',-1),if(s.TYPE='NIGHT DRIVING' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`= 'ROUTE DEVIATION' or s.`type`='UNSCHEDULED STOP', ' ',Concat(pd.Speed,'-',pd.FuelLevel))) AS 'Speed',");
            Query.Append(" if(s.TYPE='ROUTE DEVIATION',s.duration,if(s.`type`='HARSH BRAKING' OR s.`type`='HIGH ACCELERATION' OR s.`type`='HARSH CORNERING',IF(s.duration=0,round((s.maxsamplesval*127094.18)/3600,2),s.duration),'')) as event_value,");
            Query.Append(" if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM',(s.timestamp-interval s.duration MINUTE),if(s.`type`='HARSH BRAKING' or s.`type`='HIGH ACCELERATION' or s.`type`='HARSH CORNERING',if(s.duration=0,s.timestamp-INTERVAL 1 SECOND,(s.timestamp-interval s.duration SECOND)),s.timestamp)) starttime,");
            Query.Append("if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM','',s.Location) Location,");
            Query.Append("if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM','',s.latitude) latitude,");
            Query.Append("if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM','',s.longitude) longitude,");
            Query.Append("if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM' or s.`type`='HARSH BRAKING' or s.`type`='HIGH ACCELERATION' or s.`type`='HARSH CORNERING' ,s.timestamp,if(s.`type`='ROUTE DEVIATION',(s.timestamp+interval s.samples MINUTE),(s.timestamp+interval if(s.duration=0,1,s.duration-1)second))) endtime,");
            Query.Append("if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM',s.Location,'') endlocation,");
            Query.Append("if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM',s.latitude,'') endlatitude,");
            Query.Append("if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM',s.longitude,'') endlongitude,");
            Query.Append("if(s.`type`='UNSCHEDULED STOP' or s.`type`= 'SHORT RUNTIME' or s.`type`= 'TOTAL RUNTIME' or s.`type`='EXCESSIVE IDLE' or s.`type`='FREEWHEELING' or s.`type`='NIGHT DRIVING' or s.`type`='EXCESSIVE RPM', sec_to_time(s.duration*60),if(s.`type`='ROUTE DEVIATION',sec_to_time(s.samples*60),sec_to_time(if(s.duration=0,1,s.duration)))) duration,s.timestamp as event_time ");
            Query.Append(" from storevehicleviolations PARTITION(" + part + ") s left join vehicleinfo v on s.vehicleId=v.VehicleId ");
            Query.Append("left join transporterinfo t on t.TransporterId=v.Transporter ");
            Query.Append("left join vehicletripparams_vehwise p on p.VehicleId=v.VehicleId ");
            Query.Append("left join vehicletripparams pv on pv.groupId=? ");
            Query.Append("left join positiondata pd on pd.TruckID=s.VehicleId and pd.TimeStamp=s.TIMESTAMP ");
            Query.Append("left join unitconfigparams u on u.VehicleId=s.vehicleId ");
            Query.Append("where s.TIMESTAMP>=? and s.TIMESTAMP<=? and s.vehicleId IN (" + inparam + ")");

            lParameter = new Dictionary<string, object>();
            lParameter.Add("groupId", gid);
            lParameter.Add("fromDateStr", fromDateStr);
            lParameter.Add("toDateStr", toDateStr);
            for (int i = 0; i < vals.Length; i++)
            {
                lParameter.Add("vehl" + i, vals[i]);
            }
            if (viotype != "ALL" && conditions == "")
            {
                Query.Append(" and s.`type` = ? ");
                lParameter.Add("viotype", viotype);
            }
            else
                Query.Append(" and s.`type` in (" + conditions + ") ");
            Query.Append(" AND ((s.TYPE='NIGHT DRIVING' AND s.duration>0) OR s.TYPE!='NIGHT DRIVING')");
            Query.Append(" order by s.vehicleId,s.type,s.timestamp");
            return dbx.executeQuery(Query.ToString(), lParameter).Tables[0];
        }

