        public Object[] getLastPositionsByVehicles(String Vehicles, string date = null)
        {
            String dbEndDate = date;
            if (date == null)
            {
                DateTime endDate = DateTime.UtcNow;
                endDate = endDate.AddSeconds(GetTimeZoneDiff());
                dbEndDate = formatDBDate(endDate);
            }

            string GetPosDataFrom = System.Web.Configuration.WebConfigurationManager.AppSettings["GetPosDataFrom"];
            if (GetPosDataFrom == "lastupdtdata")
            {
                //if (checklastupdtdataAvailable(dbEndDate))
                return getLastPositionsFromLastUpdateTable("", Vehicles);
            }
            StringBuilder query = new StringBuilder();
            query.Append("create temporary table LastPositionsTS SELECT truckId, MAX(timestamp) as timestamp from lastupdtdata  where timestamp < ? group by truckId;");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("timestamp", dbEndDate);
            //query.Append("create temporary table LastPositionsTS SELECT truckId, MAX(timestamp) as timestamp from lastupdtdata  where timestamp < \"");
            //query.Append(dbEndDate);
            //query.Append("\" group by truckId;");
            dbx.executeNonQuery(query.ToString(), lParameter);

            query = new StringBuilder();
            query.Append(" create temporary table lastvehposdata Select distinct positiondata.truckId,  CAST(DATE_FORMAT(positiondata.timestamp, '%d %b %y, %r') as CHAR) as times, latitude, longitude, speed, UNIX_TIMESTAMP(positiondata.timestamp) as unix, vehicles.VehicleInfo,positiondata.Stop,0 as direction,vehicles.IconType");
            query.Append(" from positiondata, LastPositionsTS, vehicles");
            query.Append(" where vehicles.VehicleId in (" + Vehicles + ")");
            query.Append(" and vehicles.vehicleId = LastPositionsTS.truckId");
            query.Append(" and positiondata.timestamp = LastPositionsTS.timestamp");
            query.Append(" and positiondata.TruckId = LastPositionsTS.truckId");
            query.Append(" ;");

            DataSet lastPos = dbx.executeQuery(query.ToString());
            query = new StringBuilder();
            query.Append("select l.truckId, l.times, l.latitude,l.longitude,l.speed,l.unix, l.VehicleInfo,l.Stop,l.direction,l.IconType,v.direction from lastvehposdata l left join vehicleroutesummary v on l.truckid=v.vehicleid");
            DataSet lastPositions = dbx.executeQuery(query.ToString());
            DataTable table = lastPositions.Tables[0];
            ArrayList argsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                argsList.Add(row.ItemArray);
            }
            query = new StringBuilder();
            query.Append(" drop table IF EXISTS LastPositionsTS;");
            dbx.executeNonQuery(query.ToString());
            query = new StringBuilder();
            query.Append(" drop table IF EXISTS lastvehposdata;");
            dbx.executeNonQuery(query.ToString());
            return argsList.ToArray();
        }

        public string insertauditdata(string Operation, string Tablename, string PrimaryCol, string PrimaryValue)
        {
            string userName = string.Empty;
            string userIP = string.Empty;
            try
            {
                userName = System.Web.HttpContext.Current.Session["UserName"].ToString();
                userIP = GetUser_IP();
            }
            catch { }
            try
            {
                DateTime now = DateTime.UtcNow;
                now = now.AddSeconds(GetTimeZoneDiff());
                formatDBDate(now);
                string query = "SELECT group_Concat(`column_name`) FROM   `information_schema`.`columns` WHERE  `table_name`=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("table_name", Tablename);
                string cols = dbx.executeScalar(query, lParameter).ToString();
                query = "select  CAST(group_concat(concat_ws(','," + cols + ")) as CHAR) as val from " + Tablename + " where " + PrimaryCol + "='" + PrimaryValue + "'";
                string value = dbx.executeScalar(query).ToString().Replace("\0", " ");
                query = "insert into auditdata(Operation,timestamp,value,tablename,username,userIP) values (?,?,?,?,?,?)";
                lParameter.Clear();
                lParameter.Add("Operation", Operation);
                lParameter.Add("timestamp", formatDBDate(now));
                lParameter.Add("value", value);
                lParameter.Add("tablename", Tablename);
                lParameter.Add("username", userName);
                lParameter.Add("userIP", userIP);

                //query = "insert into auditdata(Operation,timestamp,value,tablename,username,userIP) " +
                //           " values('" + Operation + "','" + formatDBDate(now) + "','" + value + "','" + Tablename + "','" + userName + "','" + userIP + "')";

                return dbx.executeNonQuery(query, lParameter).ToString();
            }
            catch { return "0"; }
        }
        public string GetUser_IP()
        {
            string VisitorsIPAddr = string.Empty;
            try
            {
                if (System.Web.HttpContext.Current.Request.ServerVariables["HTTP_X_FORWARDED_FOR"] != null)
                {
                    VisitorsIPAddr = System.Web.HttpContext.Current.Request.ServerVariables["HTTP_X_FORWARDED_FOR"].ToString();
                }
                else if (System.Web.HttpContext.Current.Request.UserHostAddress.Length != 0)
                {
                    VisitorsIPAddr = System.Web.HttpContext.Current.Request.UserHostAddress;
                }
            }
            catch { }
            return VisitorsIPAddr;
        }

