        public DataRow[] getTrackerDataRmc(string vehicleId, string fromdata, string todate)
        {
            string track_part = GetDateTablePartitions(Convert.ToDateTime(fromdata), Convert.ToDateTime(todate), track_partions);
            string query = "select t.badSigCount,t.distance,t.IdlingInstances,fromtimestamp  from trackerdata PARTITION(" + track_part + ") AS t where truckid=? and fromtimestamp between ? and ? order by fromtimestamp desc";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("fromdata", fromdata);
            lParameter.Add("todate", todate);
            DataSet data = dbx.executeQuery(query.ToString(), lParameter);
            DataRow[] rmc = new DataRow[data.Tables[0].Rows.Count];
            data.Tables[0].Rows.CopyTo(rmc, 0);
            return rmc;

        }
        public DataTable GetAllUnDeliveredCustomerDC(string withoutqty = "0")
        {
            try
            {
                string query = "select vd.VehicleID,vd.DateTime,ci.CustomerCode,ci.customerId,cd.id,cd.DCTripId,cd.DCNo,cd.Quantity,ci.Name,ci.segment,ci.EmailId,ci.MobileNo,ci.ExecutiveMobileNo,ci.AccountId,vd.AddedBy,vd.LoadingPlaceName,vd.LoadingCustomerCode from customerdcassign cd" +
                                   " join vehicledctrip vd on vd.id=cd.DCTripId" +
                                   " join customerinfo ci on ci.customerId=cd.CustomerId" +
                                   " where vd.IsCancel=0 and vd.IsTripEnds=0 and vd.AccountID not in (20,21,22)" +
                                   " and cd.IsCancel=0 and cd.UnloadingInTime is NULL and vd.DateTime>'" + DateTime.Now.AddDays(-30).ToString("yyyy-MM-dd HH:mm") + "' and vd.DateTime<'" + DateTime.Now.AddHours(-3).ToString("yyyy-MM-dd HH:mm") + "'";
                if (withoutqty == "1")
                {
                    //Find DC which is not yet delivered.
                    query = "select vd.VehicleID,vd.DateTime,ci.CustomerCode,ci.customerId,cd.id,cd.DCTripId,cd.DCNo,cd.Quantity,ci.Name,ci.segment,ci.EmailId,ci.MobileNo,ci.ExecutiveMobileNo,ci.AccountId,vd.AddedBy from customerdcassign cd" +
                                   " join vehicledctrip vd on vd.id=cd.DCTripId" +
                                   " join customerinfo ci on ci.customerId=cd.CustomerId" +
                                   " where vd.IsCancel=0 and vd.IsTripEnds=0 and vd.AccountID not in (20,21,22)" +
                                   " and cd.IsCancel=0 and ( cd.IsDelivered=0 or cd.DeliveredQty='') and vd.DateTime>'" + DateTime.Now.AddDays(-30).ToString("yyyy-MM-dd HH:mm") + "'";
                }
                if (withoutqty == "2")
                {
                    //Find Trip which is not yet started from the plant
                    query = "select distinct c.id, v.VehicleID,ci.Name as loading,ci.CustomerCode as loadingcode," +
                           " i.Name as unloading,i.CustomerCode as unloadingcode,c.DCNo," +
                           " v.DateTime as loadedon," +
                           " c.DeliveredOn,c.DeliveredQty,v.AddedBy,c.DCTripId  from customerdcassign c" +
                           " join vehicledctrip v on v.id=c.DCTripId" +
                           " join customerinfo i on i.customerId=c.CustomerId" +
                           " join plantlogin l on l.login=v.AddedBy" +
                           " join customerinfo ci on ci.CustomerCode=l.customerid" +
                           " where v.LoadingOutTime is NULL and v.DateTime>'" + formatDBDate(DateTime.Now.AddDays(-5)) + "' order by v.DateTime";

                }
                if (withoutqty == "3")
                {
                    //Find Trip which is completed but not summarized in dc_vehicletrip_summary
                    //Optimized this query by Madhuri - 28/11/2025
                    query = "SELECT DISTINCT c.id,v.VehicleID,v.DateTime,ci.Name AS loading,ci.CustomerCode AS loadingcode,i.Name AS unloading, " +
                           " i.CustomerCode AS unloadingcode,c.DCNo,v.DateTime AS loadedon,v.TripEndsOn,c.DeliveredOn,c.DeliveredQty, " +
                           " v.AddedBy,c.DCTripId,pl.locstr AS ld_loc,pu.locstr AS ul_loc FROM customerdcassign c INNER JOIN vehicledctrip v " +
                           " ON v.id = c.DCTripId INNER JOIN customerinfo i ON i.customerId = c.CustomerId INNER JOIN plantlogin l  " +
                           " ON l.login = v.AddedBy INNER JOIN customerinfo ci ON ci.CustomerCode = l.customerid LEFT JOIN plantgeolocations pl  " +
                           " ON pl.password = ci.CustomerCode LEFT JOIN plantgeolocations pu ON pu.password = i.CustomerCode " +
                           " LEFT JOIN dc_vehicletrip_summary d ON d.CustDCId = c.id " +
                           " WHERE v.IsTripEnds = 1 AND d.CustDCId IS NULL AND v.DateTime > '" + formatDBDate(DateTime.Now.AddMonths(-3)) + "' LIMIT 50 ";
                }
                else if (withoutqty == "4")
                {
                    //Find DC which is not yet reached to customer geofence
                    query = "select vd.VehicleID,vd.DateTime,ci.CustomerCode,ci.customerId,cd.id,cd.DCTripId,cd.DCNo,cd.Quantity,ci.Name,ci.segment,ci.EmailId,ci.MobileNo,ci.ExecutiveMobileNo,ci.AccountId,vd.AddedBy,vd.LoadingPlaceName,vd.LoadingCustomerCode,p.locstr as ul_loc from customerdcassign cd" +
                                   " join vehicledctrip vd on vd.id=cd.DCTripId" +
                                   " join customerinfo ci on ci.customerId=cd.CustomerId" +
                                   " join plantgeolocations p on p.password=ci.CustomerCode" +
                                   " where vd.IsCancel=0 and vd.IsTripEnds=0 and vd.AccountID not in (20,21,22)" +
                                   " and cd.IsCancel=0 and cd.UnloadingInTime is NULL and cd.ReportedTime is NULL and vd.DateTime>'" + DateTime.Now.AddDays(-15).ToString("yyyy-MM-dd HH:mm") + "' and vd.DateTime<'" + DateTime.Now.AddMinutes(-30).ToString("yyyy-MM-dd HH:mm") + "'";

                }
                else if (withoutqty == "5")
                {
                    //Find DC which is not yet reached to customer geofence for SHV only
                    query = "select vd.VehicleID,vd.DateTime,ci.CustomerCode,ci.customerId,cd.id,cd.DCTripId,cd.DCNo,cd.Quantity,ci.Name,ci.segment,ci.EmailId,ci.MobileNo,ci.ExecutiveMobileNo,ci.AccountId,vd.AddedBy,vd.LoadingPlaceName,vd.LoadingCustomerCode,p.locstr as ul_loc,vd.TripEndsOn from customerdcassign cd" +
                                   " join vehicledctrip vd on vd.id=cd.DCTripId" +
                                   " join customerinfo ci on ci.customerId=cd.CustomerId" +
                                   " join plantgeolocations p on p.password=ci.CustomerCode" +
                                   " where vd.IsCancel=0 and vd.IsTripEnds=0 and vd.AccountID in (27)" +
                                   " and cd.IsCancel=0 and cd.UnloadingInTime is NULL and cd.ReportedTime is NULL and vd.DateTime>'" + DateTime.Now.AddDays(-6).ToString("yyyy-MM-dd HH:mm") + "' and vd.DateTime<'" + DateTime.Now.AddMinutes(-30).ToString("yyyy-MM-dd HH:mm") + "'";

                }
                else if (withoutqty == "6")
                {
                    //Find DC which is not yet reached to customer geofence for SHV only
                    query = "select vd.VehicleID,vd.DateTime,ci.CustomerCode,ci.customerId,cd.id,cd.DCTripId,cd.DCNo,cd.Quantity,ci.Name,ci.segment,ci.EmailId,ci.MobileNo,ci.ExecutiveMobileNo,ci.AccountId,vd.AddedBy,vd.LoadingPlaceName,vd.LoadingCustomerCode,p.locstr as ul_loc,vd.TripEndsOn from customerdcassign cd" +
                                   " join vehicledctrip vd on vd.id=cd.DCTripId" +
                                   " join customerinfo ci on ci.customerId=cd.CustomerId" +
                                   " join plantgeolocations p on p.password=ci.CustomerCode" +
                                   " where vd.IsCancel=0 and vd.IsTripEnds=0 and cd.ReportedTime IS NOT NULL and vd.AccountID in (27)" +
                                   " and cd.IsCancel=0 and cd.UnloadingInTime is NULL and cd.ReportedTime is NULL and vd.DateTime>'" + DateTime.Now.AddDays(-6).ToString("yyyy-MM-dd HH:mm") + "' and vd.DateTime<'" + DateTime.Now.AddMinutes(-30).ToString("yyyy-MM-dd HH:mm") + "'";

                }
                return dbx.executeQuery(query).Tables[0];
            }
            catch { return null; }
        }

