        public DataTable GetInTimePlant(string VehicleId, DateTime DateTime, string PlantLocStr, string ToDate = "", string outtime = "0")
        {
            try
            {
                if (!PlantLocStr.Contains("'"))
                    PlantLocStr = "'" + PlantLocStr + "'";
                string inparam = string.Empty;
                String[] vals = PlantLocStr.Replace("'", "").Replace("\"", "").Split(',');
                var lParameter = new Dictionary<string, object>();
                for (int i = 0; i < vals.Length; i++)
                {
                    if (i == 0)
                        inparam += ("?");
                    else
                        inparam += (",?");
                    lParameter.Add("vals_" + i, vals[i]);
                }
                string query = "select a.intimestamp,a.outtimestamp from vehicleinplant a where a.locationstr in (" + inparam + ") and a.vehicleid=? and a.intimestamp>='" + formatDBDate(DateTime) + "'";

                if (!string.IsNullOrEmpty(ToDate))
                    query += " and a.intimestamp<='" + formatDBDate(Convert.ToDateTime(ToDate)) + "'";
                if (outtime == "1")
                    query += " order by a.intimestamp desc limit 1";
                else
                    query += " order by a.intimestamp desc limit 1";
                lParameter.Add("vehicleid", VehicleId);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            catch { return null; }
        }

        public DataTable GetUnloadedCustomerDC(string VehicleId, string CustomerCode, string timestamp, string SelectBy = "")
        {
            try
            {
                DateTime ts = Convert.ToDateTime(timestamp);
                string query = "select u.timestamp,u.netqty from plantgeolocations p" +
                               " join unloadqtydetails u on u.locStr=p.locstr where " +
                               " u.vehicleid='" + VehicleId + "' and p.password='" + CustomerCode + "' and u.timestamp>='" + formatDBDate(ts) + "'";
                if (!string.IsNullOrEmpty(SelectBy))
                {
                    query = "select u.timestamp,(u.grossweight-u.tareweight) as netqty from unloadbyapp u" +
                               " where u.vehicleid='" + VehicleId + "' and u.CustomerCode='" + CustomerCode + "' and u.timestamp>='" + formatDBDate(ts) + "'";
                    if (SelectBy == "Driver")
                        query += " and CHAR_LENGTH(u.Token)<=18";
                    else
                        query += " and CHAR_LENGTH(u.Token) > 18";
                    query += " order by u.timestamp asc";
                }
                return dbx.executeQuery(query).Tables[0];
            }
            catch { return null; }
        }

        public string UpdateCustomerDCDelivery(string Id, string DeliveredOn, string DeliveredQty, string ReportedTime = "")
        {
            try
            {
                string query = "";
                var lParameter = new Dictionary<string, object>();
                if (!string.IsNullOrEmpty(ReportedTime))
                {
                    query = "update customerdcassign set ReportedTime=? where id=? ;";
                    //query = "update customerdcassign set ReportedTime='" + ReportedTime + "' where id='" + Id + "'";
                    lParameter.Clear();
                    lParameter.Add("ReportedTime", ReportedTime);
                    lParameter.Add("id", Id);
                    return dbx.executeNonQuery(query, lParameter).ToString();
                }
                else
                {
                    DateTime ts = Convert.ToDateTime(DeliveredOn);
                    //   query = "update customerdcassign set IsDelivered=b'1',DeliveredOn='" + formatDBDate(ts) + "',DeliveredQty='" + DeliveredQty + "' where id='" + Id + "'";
                    query = "update customerdcassign set IsDelivered=b'1',DeliveredOn=?,DeliveredQty=? where id=?";
                    lParameter.Clear();
                    lParameter.Add("DeliveredOn", formatDBDate(ts));
                    lParameter.Add("DeliveredQty", DeliveredQty);
                    lParameter.Add("id", Id);

                    if (string.IsNullOrEmpty(DeliveredQty))
                    {
                        query = "update customerdcassign set IsDelivered=b'1',DeliveredOn=?,UnloadingInTime=? where id=?";
                        // query = "update customerdcassign set IsDelivered=b'1',DeliveredOn='" + formatDBDate(ts) + "',UnloadingInTime='" + formatDBDate(ts) + "' where id='" + Id + "'";
                        lParameter.Clear();
                        lParameter.Add("DeliveredOn", formatDBDate(ts));
                        lParameter.Add("UnloadingInTime", formatDBDate(ts));
                        lParameter.Add("id", Id);
                    }
                    string res = dbx.executeNonQuery(query, lParameter).ToString();
                    try
                    {
                        query = "select ci.AccountId from customerdcassign c join customerinfo ci on c.CustomerId=ci.customerId where c.id=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("id", Id);
                        string accountid = Convert.ToString(dbx.executeScalar(query, lParameter));
                        PushChangeDataToAPI(Id, "UpdateDeliveryDetails", accountid);
                    }
                    catch { }
                    return res;
                }
            }
            catch { return "0"; }
        }
        public string UpdateUnloadTime(string FO_Number, string DeliveredOn, string DeliveredQty, string ReportedTime = "")
        {
            try
            {
                string query = "";
                var lParameter = new Dictionary<string, object>();
                DateTime ts = Convert.ToDateTime(DeliveredOn);
                //   query = "update customerdcassign set IsDelivered=b'1',DeliveredOn='" + formatDBDate(ts) + "',DeliveredQty='" + DeliveredQty + "' where id='" + Id + "'";
                query = "update customerdcassign set IsDelivered=b'1',DeliveredOn=?,DeliveredQty=? where DCNo=?";
                lParameter.Clear();
                lParameter.Add("DeliveredOn", formatDBDate(ts));
                lParameter.Add("DeliveredQty", DeliveredQty);
                lParameter.Add("FO_Number", FO_Number);
                string res = dbx.executeNonQuery(query, lParameter).ToString();
                try
                {
                    query = "SELECT * FROM customerdcassign c WHERE c.DCNo = ? ";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("FO_Number", FO_Number);
                    var result = dbx.executeQuery(query.ToString(), lParameter);

                    string id = result.Tables[0].Rows[0]["id"].ToString();

                    query = "select ci.AccountId from customerdcassign c join customerinfo ci on c.CustomerId=ci.customerId where c.id=?";
                    lParameter = new Dictionary<string, object>();
