        }
        public int GetTimeZoneDiff(string sessionId = "")
        {
            int TimeDiff = 19800;
            try
            {
                //Checking Timezone in Web.Session
                if (System.Web.HttpContext.Current.Session != null)
                {
                    if (System.Web.HttpContext.Current.Session["UserTimeZone"] != null)
                    {
                        //Getting Timezone in  Web.Session
                        TimeDiff = Convert.ToInt32(System.Web.HttpContext.Current.Session["UserTimeZone"].ToString());
                        //If Diffrent sessionId passed.have to Check once in accountgroups
                        if (sessionId != "")
                        {
                            if (System.Web.HttpContext.Current.Session["UserTimeZoneSessionId"] != null)
                            {
                                if (sessionId != System.Web.HttpContext.Current.Session["UserTimeZoneSessionId"].ToString())
                                {
                                    TimeDiff = checktimezoneinsessionconfig(sessionId);
                                    System.Web.HttpContext.Current.Session["UserTimeZone"] = TimeDiff;
                                    System.Web.HttpContext.Current.Session["UserTimeZoneSessionId"] = sessionId;
                                }
                            }
                        }
                    }
                    else
                    {
                        TimeDiff = checktimezoneinsessionconfig(sessionId);
                        if (sessionId != "")
                        {
                            System.Web.HttpContext.Current.Session["UserTimeZone"] = TimeDiff;
                            System.Web.HttpContext.Current.Session["UserTimeZoneSessionId"] = sessionId;
                        }
                    }
                }
                else
                {
                    TimeDiff = checktimezoneinsessionconfig(sessionId);
                    if (sessionId != "")
                    {
                        try
                        {
                            //Storing timezone in Web.Session
                            System.Web.HttpContext.Current.Session["UserTimeZone"] = TimeDiff;
                            System.Web.HttpContext.Current.Session["UserTimeZoneSessionId"] = sessionId;
                        }
                        catch { }
                    }
                }
            }
            catch
            {
                if (sessionId != "")
                {
                    try
                    {
                        TimeDiff = checktimezoneinsessionconfig(sessionId);
                    }
                    catch { }
                }
                else
                {
                    String timeZoneStr = System.Web.Configuration.WebConfigurationManager.AppSettings["timeZoneOffset"];
                    if (!String.IsNullOrEmpty(timeZoneStr))
                    {
                        TimeDiff = Convert.ToInt32(timeZoneStr);
                    }
                }
                if (string.IsNullOrEmpty(TimeDiff.ToString()))
                {
                    TimeDiff = 19800;
                }
            }
            return TimeDiff;
        }

        private int checktimezoneinsessionconfig(string sessionid)
        {
            int TimeDiff = 19800;
            try
            {
                //Getting timezone by sessionId in accountgroups
                string tdiff = GetTimeZoneDiffInAccGrp(sessionid);
                if (int.TryParse(tdiff, out TimeDiff))
                {
                    TimeDiff = Convert.ToInt32(tdiff);
                }
                else
                {
                    //Getting timezone in web Config
                    String timeZoneStr = System.Web.Configuration.WebConfigurationManager.AppSettings["timeZoneOffset"];
                    if (timeZoneStr != null)
                    {
                        TimeDiff = Convert.ToInt32(timeZoneStr);
                    }
                    else
                    {
                        TimeDiff = 19800;//Default IST Time Diff
                    }
                }
                return TimeDiff;
            }
            catch
            {
                return 19800;
            }
        }

