        public DataTable checkweatherzoneavail(string latitude, string longitude, double delta)
        {
            try
            {
                double lat = Convert.ToDouble(latitude);
                double minLatitude = lat - delta;
                double maxLatitude = lat + delta;
                double lon = Convert.ToDouble(longitude);
                double minLongitude = lon - delta;
                double maxLongitude = lon + delta;
                string query = "select Id,latitude,longitude,Current_Temp,Max_Temp,Min_Temp,Humidity,Pressure,Wind_Speed_Value,Wind_Speed_Name,Wind_Direction_Value,Wind_Direction_Code," +
                               "  Clouds_Value,Couds_Name,Visibility,Weather_Number,Weather_Value,Last_Updated_On,Cityid,Cityname from weatherzone w where " +
                               "  latitude between " + minLatitude + " and " + maxLatitude +
                               "  and longitude between " + minLongitude + " and " + maxLongitude + " order by Last_Updated_On Desc";
                return dbx.executeQuery(query).Tables[0];
            }
            catch { return null; }
        }

        public string AddUpdateWeatherData(string latitude, string longitude, string Mode, string Id, string Cityid, string Cityname,
        string Current_Temp, string Min_Temp, string Max_Temp, string Humidity, string Pressure, string Wind_Speed_Value,
        string Wind_Speed_Name, string Wind_Direction_Value, string Wind_Direction_Code, string Clouds_Value, string Couds_Name,
        string Visibility, string Weather_Number, string Weather_Value, string Last_Updated_On)
        {
            try
            {
                Last_Updated_On = formatDBDate(DateTime.UtcNow);
                string query = "INSERT INTO weatherzone(latitude,longitude,Current_Temp,Max_Temp,Min_Temp,Humidity,Pressure," +
                                "Wind_Speed_Value,Wind_Speed_Name,Wind_Direction_Value,Wind_Direction_Code,Clouds_Value,Couds_Name," +
                                "Visibility,Weather_Number,Weather_Value,Last_Updated_On,Cityid,Cityname)" +
                                " values ('" + latitude + "','" + longitude + "','" + Current_Temp + "','" + Max_Temp + "','" + Min_Temp + "','" + Humidity + "','" + Pressure + "','" +
                                 Wind_Speed_Value + "','" + Wind_Speed_Name + "','" + Wind_Direction_Value + "','" + Wind_Direction_Code + "','" + Clouds_Value + "','" + Couds_Name + "','" +
                                 Visibility + "','" + Weather_Number + "','" + Weather_Value + "','" + Last_Updated_On + "','" + Cityid + "','" + Cityname + "')";
                if (Mode == "Edit")
                {
                    query = "Update weatherzone set latitude='" + latitude + "',longitude='" + longitude + "',Current_Temp='" + Current_Temp + "',Max_Temp='" + Max_Temp + "',Min_Temp='" + Min_Temp + "',Humidity='" + Humidity + "',Pressure='" + Pressure + "'," +
                                 "Wind_Speed_Value='" + Wind_Speed_Value + "',Wind_Speed_Name='" + Wind_Speed_Name + "',Wind_Direction_Value='" + Wind_Direction_Value + "',Wind_Direction_Code='" + Wind_Direction_Code + "',Clouds_Value='" + Clouds_Value + "',Couds_Name='" + Couds_Name + "'," +
                                 "Visibility='" + Visibility + "',Weather_Number='" + Weather_Number + "',Weather_Value='" + Weather_Value + "',Last_Updated_On='" + Last_Updated_On + "',Cityid='" + Cityid + "',Cityname='" + Cityname + "' where Id='" + Id + "'";

                }
                return dbx.executeNonQuery(query).ToString();
            }
            catch { return "0"; }
        }

