        public string checkRFIDInfoFromParser(string truckid, string rfidlogs, string CheckInDriverInfo = "", string type = "RFID")
        {
            try
            {
                //StringBuilder query = new StringBuilder();
                //query.Append("select concat(r.Name,'@#',r.PrimaryContact,'@#',u.login,'@#',ac.globalaccountid,'@#',SMSFormat,'@#',r.Rfidlogs) as rfiddetails from rfidinfo r ");
                //query.Append("   join vehiclesgroupsmap v on v.GroupId=r.GroupId");
                //query.Append("   join usersgroupsmap u on u.GroupId=r.GroupId");
                //query.Append("   join accountgroups a on a.GroupId=r.GroupId");
                //query.Append("   join accounts ac on ac.ID=a.AccountID");
                //query.Append("   where v.VehicleId='" + truckid + "' and r.Rfidlogs='" + rfidlogs + "'");
                string query = "select concat(r.Name,'@#',r.PrimaryContact,'@#',u.login,'@#',r.AssignedVehicleId,'@#',r.Rfidlogs,'@#',r.Rfidlogs) as rfiddetails from rfidinfo r " +
                              "   join vehiclesgroupsmap v on v.GroupId=r.GroupId" +
                              "   join usersgroupsmap u on u.GroupId=r.GroupId" +
                              "   join accountgroups a on a.GroupId=r.GroupId" +
                              "   join accounts ac on ac.ID=a.AccountID" +
                              "   where v.VehicleId='" + truckid + "' and r.Rfidlogs like '%" + rfidlogs + "'";
                if (CheckInDriverInfo == "1")
                {
                    query = "select concat(DriverId,'@#',Name,'@#',RFIDTag,'@#',AssignedVehicleId,'@#1@#1') from driverinfo where " +
                            " RFIDTag like '%" + rfidlogs + "%' order by ApprovedDateTime desc limit 1";
                    if (type == "FGPD")
                    {
                        query = "select CONCAT(d.DriverId,'@#',d.NAME,'@#',f.FingerPrintID,'@#',d.AssignedVehicleId,'@#1@#1@#',d.DrivingExp) FROM " +
                                " driverinfo d JOIN driverfingerprintmapping f ON f.DriverId = d.DriverId" +
                                " WHERE f.FingerPrintID like '%" + rfidlogs + "%' order by d.ApprovedDateTime desc limit 1";
                    }
                }
                return dbx.executeScalar(query).ToString();
            }
            catch (Exception ex)
            {
                return string.Empty;
            }
        }
        public Object[] getMaxLatLongOnTime(string vehicleId, string fromDateStr)
        {
            DateTime fromDate = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() - 24 * 60 * 60);
            try
            {
                fromDate = DateTime.Parse(fromDateStr);
            }
            catch (Exception)
            {
            }
            fromDateStr = formatDBDate(fromDate);
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr).AddDays(-10), Convert.ToDateTime(fromDateStr), partions);
            StringBuilder query = new StringBuilder();
            query.Append("Select id, DATE_FORMAT(p.timestamp, '%d %b %y, %r'), Start, Stop, Latitude, Longitude, Speed, UNIX_TIMESTAMP(p.timestamp), FuelLevel");
            query.Append(" from positiondata PARTITION(" + part + ") AS p");
            query.Append(" where p.truckId =\"" + vehicleId + "\" ");
            if (fromDateStr != null)
            {
                query.Append(" and TimeStamp <= \"" + fromDateStr + "\" ");
            }
            query.Append(" order by TimeStamp desc limit 1");
            DataSet routeLatLong = dbx.executeQuery(query.ToString());
            DataTable table = routeLatLong.Tables[0];
            ArrayList latLongList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                latLongList.Add(row.ItemArray);
            }
            return latLongList.ToArray();
        }
