        //Get source and destination
        public DataTable[] GetSourceDestination(string login, string accountid = "")
        {
            int account = 0;
            if (!string.IsNullOrEmpty(accountid))
            {
                if (accountid != "0")
                    account = Convert.ToInt32(accountid);
            }

            if (!string.IsNullOrEmpty(login))
                account = GetAccountId(getSessionIdFromLogin(login));

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", account);
            string query = "Select distinct Source from sourcedestinationmap where AccountId=?";

            DataSet source = dbx.executeQuery(query, lParameter);
            query = "Select distinct Destination from sourcedestinationmap where AccountId=?;";
            DataSet destination = dbx.executeQuery(query, lParameter);

            DataTable[] dtc = new DataTable[2];
            dtc[0] = source.Tables[0];
            dtc[1] = destination.Tables[0];

            //DataSet data = new DataSet();
            //data.Tables.AddRange(dtc);
            return dtc;
        }
        public DataTable GetViolationsByVehicleIDs(string vehicleids, string fromDateStr, string toDateStr, string types, string groupid = "0")
        {
            var lParameter = new Dictionary<string, object>();
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            string query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration, concat(s.timestamp) as datetime,s.Location,s.latitude,s.longitude,s.remarks,s.timestamp,s.maxsamplesval " +
                      " from storevehicleviolations PARTITION(" + part + ") AS s " +
                      " where s.timestamp>=? and s.timestamp<=? ";
            lParameter.Add("fromdate", fromDateStr);
            lParameter.Add("todate", toDateStr);
            if (groupid != "0" && vehicleids == "")
                query += " and s.vehicleId in (select vehicleid from vehiclesgroupsmap where GroupId='" + groupid + "')";
            else
            {
                String[] vehicles = vehicleids.Replace("'", "").Replace("\"", "").Split(',');
                string inparam = string.Empty;
                for (int i = 0; i < vehicles.Length; i++)
                {
                    if (i == 0)
                        inparam += ("?");
                    else
                        inparam += (",?");
                    lParameter.Add("truckId" + i, vehicles[i]);
                }
                query += " and s.vehicleId in (" + inparam + ")";
            }
            string inparam2 = string.Empty;
            String[] type = types.Replace("'", "").Replace("\"", "").Split(',');
            for (int i = 0; i < type.Length; i++)
            {
                if (i == 0)
                    inparam2 += ("?");
                else
                    inparam2 += (",?");
                lParameter.Add("type" + i, type[i]);
            }
            query += "  and s.`type` in (" + inparam2 + ") order by s.vehicleId,s.type,s.timestamp";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
