        public DataTable GetVehicleDCTrip(string vehicleids, string fromdate, string todate)
        {
            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            String[] vehicles = vehicleids.Replace("'", "").Replace("\"", "").Split(',');
            string inparam = string.Empty;
            for (int i = 0; i < vehicles.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
                lParameter.Add("truckId" + i, vehicles[i]);
            }
            Query = "select v.VehicleID,v.DateTime,v.LoadingPlaceName as Source,i.Name as Destination,c.DeliveredOn,v.TripEndsOn from customerdcassign c" +
                    " join vehicledctrip v on v.id = c.DCTripId" +
                    " join customerinfo i on i.customerId = c.CustomerId" +
                    " where v.VehicleID in (" + inparam + ")" +
                    " and v.DateTime between ? and ?";
            lParameter.Add("fromdate", fromdate);
            lParameter.Add("todate", todate);
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }
