        public DataRow[] GetRouteSegments(string source, string destination, string sessionid)
        {
            int accid = GetAccountId(sessionid);
            StringBuilder query = new StringBuilder();
            query.Append("select Segments from sourcedestinationmap where Source=? and Destination=? and AccountId=?;");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Source", source);
            lParameter.Add("Destination", destination);
