        public object[] GetCustomerLoadReportData(string fromDateStr, string toDateStr, string sessionid)
        {
            string GroupId = getGroupId(sessionid).ToString();
            string query = "select distinct c.id, v.VehicleID,ci.Name as loading,ci.CustomerCode as loadingcode," +
                           " i.Name as unloading,i.CustomerCode as unloadingcode,c.DCNo," +
                           " v.DateTime as loadedon," +
                           " c.DeliveredOn,c.DeliveredQty,v.AddedBy  from customerdcassign c" +
                           " join vehicledctrip v on v.id=c.DCTripId" +
                           " join customerinfo i on i.customerId=c.CustomerId" +
                           " join plantlogin l on l.login=v.AddedBy" +
                           " join customerinfo ci on ci.CustomerCode=l.customerid" +
                           " join vehiclesgroupsmap vi on vi.VehicleId=v.VehicleID" +
                           " where v.DateTime>='" + fromDateStr + "' and v.DateTime<='" + toDateStr + "' and vi.GroupId='" + GroupId + "'  order by v.DateTime";
            DataSet data = dbx.executeQuery(query.ToString());
            DataTable table = data.Tables[0];
            ArrayList lst = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                lst.Add(row.ItemArray);
            }
            return lst.ToArray();
        }
