        public string GetOutTimeDoneByCustomerId(string loadingcode, string loadedTime, string vehicleId)
        {
            try
            {
                DateTime load = Convert.ToDateTime(loadedTime);
                string locstr = getlocstring(loadingcode);

                if (!string.IsNullOrEmpty(locstr))
                {
                    string query = "select v.outtimestamp from vehicleinplant v " +
                                  " where v.locationstr='" + locstr + "' and v.vehicleid='" + vehicleId + "' and v.outtimestamp>'" + formatDBDate(load.AddHours(-10)) + "'" +
                                  " order by v.outtimestamp asc limit 1";
                    object tt = dbx.executeScalar(query.ToString());
                    if (tt == null)
                    {
                        return string.Empty;
                    }
                    return tt.ToString();
                }
                else
                    return string.Empty; ;
            }
            catch
            {
                return loadedTime;
            }
        }
