        public string GetListOfUsersByVehicleID(string vehicleId)//developed by zoya on 16/02/2026 to concat the user list in code as group_concat is not working in mysql
        {
            try
            {
                string query = "SELECT u.Login FROM vehiclesgroupsmap v JOIN usersgroupsmap u ON u.GroupId = v.GroupId WHERE v.VehicleID = ?";

                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleId", vehicleId);

                DataSet ds = dbx.executeQuery(query, lParameter);

                if (ds == null || ds.Tables.Count == 0)
                    return string.Empty;

                var list = new List<string>();

                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    list.Add($"'{row["Login"]}'");
                }

                return string.Join(",", list);
            }
            catch
            {
                return string.Empty;
            }
        }

