        public object[] getViolationCount(string vehicleId, string fromDateStr, string toDateStr, bool IsRec = false)
        {
            try
            {
                string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
                String maxspeed = System.Web.Configuration.WebConfigurationManager.AppSettings["SummaryMaxSpeed"];
                if (string.IsNullOrEmpty(maxspeed))
                    maxspeed = "0";
                string query = "select `type`,sum(cnt) as cnt from (select s.`type`,count(s.timestamp) as cnt,remarks from storevehicleviolations PARTITION(" + part + ") AS s" +
                               " where s.vehicleId='" + vehicleId + "' " +
                               " and s.timestamp>='" + fromDateStr + "' " +
                               " and s.timestamp<='" + toDateStr + "' and s.`type`<>'NORMAL'" +
                               " group by s.`type`,remarks) a where" +
                               " ((`type`='OVERSPEEDING' and SUBSTR(remarks,13)>" + maxspeed + ") or `type`<>'OVERSPEEDING') " +
                               " group by `type`";
                DataSet vehicles = dbx.executeQuery(query.ToString());
                DataTable table = vehicles.Tables[0];
                ArrayList driverList = new ArrayList();
                foreach (DataRow row in table.Rows)
                {
                    driverList.Add(row.ItemArray);
                }
                return driverList.ToArray();
            }
            catch (Exception ex)
            {
                if (ex.ToString().Contains("Lost connection") && IsRec == false)
                {
                    return getViolationCount(vehicleId, fromDateStr, toDateStr, true);

                }
            }
            return null;
        }

