        public object[] getViolationSummaryReport(string fromDateStr, string toDateStr, string vehicleId, string IsOverAllSum = "No", string DriverId = "0")
        {
            String[] vals = vehicleId.Replace("'", "").Replace("\"", "").Split(',');
            string inparam = string.Empty;
            for (int i = 0; i < vals.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
            }
            string query = "select  m.VehicleId," +
                          " d.cd,sum(IF(m.cd='',0,1)) as m_cd," +
                          " d.maxsp,sum(IF(m.maxsp='',0,1)) as m_maxsp," +
                          " d.nd,sum(IF(m.nd='',0,1)) as m_nd," +
                          " d.md,sum(IF(m.md='',0,1)) as m_md," +
                          " d.harshBraking,sum(IF(m.harshBraking='',0,1)) as m_harshBraking  " +
                         "  from daywisevehviosummary d   " +
                          " join daywisevehviosummary m on m.vehicleid=d.VehicleId " +
                          " and m.date>=? and m.date<=? " +
                         "  and d.date=? " +
                         "  where d.vehicleid in (" + inparam + ")" +
                         "  group by m.vehicleid";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("date1", fromDateStr);
            lParameter.Add("date2", toDateStr);
            lParameter.Add("date", toDateStr);
            for (int i = 0; i < vals.Length; i++)
            {
                lParameter.Add("truckId" + i, vals[i]);
            }
            if (IsOverAllSum == "Yes")
            {
                lParameter.Clear();
                query = "select sum(IF(d.cd='',0,1)) as cd," +
                        " sum(IF(d.maxsp='',0,1)) as maxsp," +
                        " sum(IF(d.nd='',0,1)) as nd," +
                        " sum(IF(d.md='',0,1)) as md," +
                        " sum(IF(d.harshBraking='',0,1)) as harshBraking " +
                        " from daywisevehviosummary d  " +
                        " where d.date>=? and d.date<=?";
                lParameter.Add("date2", fromDateStr);
                lParameter.Add("date", toDateStr);
                if (DriverId != "0")
                {
                    query += " and d.driverid=?";
                    lParameter.Add("driverid", DriverId);
                }
                else
                {
                    query += " and d.vehicleid in (" + vehicleId + ")";
                    for (int i = 0; i < vals.Length; i++)
                    {
                        lParameter.Add("truckId" + i, vals[i]);
                    }
                }
            }
            DataSet vehicles = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = vehicles.Tables[0];
            ArrayList driverList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                driverList.Add(row.ItemArray);
            }
            return driverList.ToArray();
        }


