            string fromDateLoadUnLoadStr = string.Empty;
            DateTime fromDateLoadUnload = Convert.ToDateTime(fromDateStr).AddHours(-24);
            fromDateLoadUnLoadStr = formatDBDate(fromDateLoadUnload);
            query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
               "sessionid ='" + sessionId + "'";
            Object groupIdObj = dbx.executeScalar(query);
            int groupId = Convert.ToInt32(groupIdObj);

            query = "select  'Waiting for unloading'  Status , locationstr, count(v.vehicleid) count  from vehicleinplant v join vehiclesgroupsmap v1   on v.vehicleid = v1.vehicleid where intimestamp between " + "'" + fromDateStr + "'" + " and '" + toDateStr + "'" +
                 " and locationstr like '%parking%' " +
                 " and outtimestamp is null " +
                 " and planttype = 1" +
                 " and v1.groupid = " + groupId + "   group by locationstr"
                 + " union all"
                 + " select  'Unloaded Vehicles' Status,locationstr,count(v.vehicleid) count from vehicleinplant v join vehiclesgroupsmap v1 "
                 + " on v.vehicleid = v1.vehicleid where intimestamp between " + "'" + fromDateLoadUnLoadStr + "'"
                 + " and " + "'" + toDateStr + "'"
                 + " and locationstr like '%unloading%' "
                 + " and outtimestamp is not null "
                 + " and planttype = 1"
                 + " and v1.groupid =  " + groupId + "  group by locationstr"
                 + " union all"
                 + " select  'Loaded Vehicles' Status,locationstr,count(v.vehicleid) count from vehicleinplant v join vehiclesgroupsmap v1 "
                 + " on v.vehicleid = v1.vehicleid where intimestamp between " + "'" + fromDateLoadUnLoadStr + "'"
                 + " and " + "'" + toDateStr + "'"
                 + " and locationstr like '%loading%' "
                 + " and outtimestamp is not null "
                 + " and planttype = 0"
                 + " and v1.groupid =  " + groupId + "  group by locationstr;";
            DataSet listSummayVehIn = dbx.executeQuery(query);
            DataTable table = listSummayVehIn.Tables[0];
            ArrayList SummaryvehInPlantList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                SummaryvehInPlantList.Add(row.ItemArray);
            }
            return (SummaryvehInPlantList.ToArray());

        }

