                if (!string.IsNullOrEmpty(PktRecvdAt))
                    sDate = formatDBDate(Convert.ToDateTime(PktRecvdAt));
                String query = String.Empty;
                query = "insert into TcpParserMonitor(ThreadId,UID,ServerTS, ThreadDateTime, sRemoteEndPoint, sLocalEndPoint, content,Remark,TotalThread) values(" +
                                "'" + ThreadId + "'" + "," +
