                                     "'" + sDate + "'" + "," +
                                        "'" + ThreadDateTime + "'" + "," +
                                        "'" + sRemoteEndPoint + "'" + "," +
                                        "'" + sLocalEndPoint + "'" + "," +
                                        "'" + content + "'" + "," +
                                        "'" + Remark + "'" + "," +
                                            "'" + TotalThread + "'" + ")";
                dbx.executeNonQuery(query);


                Object idObj = dbx.executeScalar("select id from TcpParserMonitor where UID =" + UID + " and ThreadId ='" + ThreadId + "' and ServerTS ='" + sDate + "' and content ='" + content + "' ;");
