        //Check birthday IsBirthday
        public bool IsBirthday(string driverid, DateTime date)
        {
            string fdate = formatDBDate(date);
            int month = date.Month;
            int day = date.Day;
            string query = "select count(di.DriverId) from driverinfo di where di.DriverId=? and month(DOB)=? and day(DOB)=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("DriverID", driverid);
            lParameter.Add("month", month);
            lParameter.Add("day", day);
            object obj = dbx.executeScalar(query, lParameter);
            if (obj != null && Convert.ToInt16(obj.ToString()) > 0)
                return true;
            else
                return false;
        }
        //for driver incentives
        public int AddDriverPoints(string DriverId, string Points, string Reason)
        {
            string date = formatDBDate(System.DateTime.Now);
            string query = "";
            int rows = 0;

            if (!DriverId.Contains(",") && DriverId != "ALL")
            {
                query = "INSERT INTO `driverpoints` (`DriverId`, `Date`, `Points`, `Reason`) VALUES (?,?,?,?);";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("DriverId", DriverId);
                lParameter.Add("Date", date);
                lParameter.Add("Points", Points);
                lParameter.Add("Reason", Reason);
                rows = dbx.executeNonQuery(query, lParameter);
            }
            else if (DriverId.Contains(",") && DriverId != "ALL")
            {
                string[] drivers = DriverId.Split(',');
                for (int i = 0; i < drivers.Length; i++)
                {
                    query = "INSERT INTO `driverpoints` (`DriverId`, `Date`, `Points`, `Reason`) VALUES (?,?,?,?);";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("DriverId", drivers[i].ToString());
                    lParameter.Add("Date", date);
                    lParameter.Add("Points", Points);
                    lParameter.Add("Reason", Reason);
                    rows += dbx.executeNonQuery(query, lParameter);
                }
            }
            else if (DriverId == "ALL")
            {
                query = "select d.DriverId from driverinfo d" +
                " where d.AccountId=9";
                DataSet ds = dbx.executeQuery(query);
                for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
                {
                    query = "INSERT INTO `driverpoints` (`DriverId`, `Date`, `Points`, `Reason`) VALUES (?,?,?,?);";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("DriverId", ds.Tables[0].Rows[i][0].ToString());
                    lParameter.Add("Date", date);
                    lParameter.Add("Points", Points);
                    lParameter.Add("Reason", Reason);
                    rows += dbx.executeNonQuery(query, lParameter);
                }
            }
            return rows;
        }

