        //for driver name
        public string getdrivername(string truckid, string datetime = "", string driverId = "0")
        {
            string name = "";
            string id = "0";
            string start_time = "";
            int groupid = getGroupIdByVehicleid(truckid);
            try
            {
                if (string.IsNullOrEmpty(datetime))
                    datetime = formatDBDate(DateTime.Now);
                else
                    datetime = formatDBDate(Convert.ToDateTime(datetime));
                String query = String.Empty;
                var lParameter = new Dictionary<string, object>();

                //////////////////By Driver Id///////////////////////////////////
                if (driverId != "0" && !string.IsNullOrEmpty(driverId))
                {
                    query = "select i.Name,i.DriverId from driverinfo i where i.DriverId=?";
                    lParameter.Add("driverId", driverId);
                    DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                    if (dt.Rows.Count > 0)
                    {
                        name = dt.Rows[0][0].ToString();
                        id = dt.Rows[0][1].ToString();
                        start_time = DateTime.Now.AddMonths(-1).ToString("yyyy-MM-dd HH:mm:ss");
                        return name + "," + id + "," + start_time;
                    }
                }


                //////////////////Get the Driver Details by Tag in/out//////////////////////////
                try
                {
                    query = "select d.Name,t.DriverId,t.TagInOrOut,t.TimeStamp from taging t" +
                            " join driverinfo d on d.DriverId=t.DriverId" +
                            //" where VehicleId=? and TimeStamp<?  and TimeStamp>? order by TimeStamp desc limit 1";
                            " where VehicleId=? AND t.TimeStamp = (SELECT MAX(TimeStamp) FROM taging WHERE VehicleId = ? AND TimeStamp < ? AND TimeStamp > ? ) ";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("truckid", truckid);
                    lParameter.Add("truckid1", truckid);
                    lParameter.Add("datetime", formatDBDate(Convert.ToDateTime(datetime).AddSeconds(360)));   //  was 40 seconds before
                    lParameter.Add("datetime1", formatDBDate(Convert.ToDateTime(datetime).AddHours(-24)));
                    DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                    if (dt.Rows.Count > 0)
                    {
                        if (dt.Rows[0]["TagInOrOut"].ToString() == "1")
                        {
                            name = dt.Rows[0]["Name"].ToString();
                            id = dt.Rows[0]["DriverId"].ToString();
                            start_time = Convert.ToDateTime(dt.Rows[0]["TimeStamp"].ToString()).ToString("yyyy-MM-dd HH:mm:ss");
                        }
                    }
                }
                catch { }
                ///////////////////////////////////////////////////////////////////////////////

                //////////////////Get the Driver Change Log (Shell) --Maintenance or Not-- //////////////////////////
                try
                {
                    query = "select * from driverchangelog v where v.VehicleId=?" +
                            " and v.RequestDate < ?" +
                            " order by v.RequestDate desc limit 1";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("truckid", truckid);
                    lParameter.Add("datetime", formatDBDate(Convert.ToDateTime(datetime).AddSeconds(40)));
                    DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                    if (dt.Rows.Count > 0)
                    {
                        if (dt.Rows[0]["RequestType"].ToString() == "Maintenance" || dt.Rows[0]["RequestType"].ToString() == "Non Operational")
                        {
                            DateTime reqDate = Convert.ToDateTime(dt.Rows[0]["RequestDate"].ToString());
                            if (!string.IsNullOrEmpty(start_time))
                            {
                                if (Convert.ToDateTime(start_time) < reqDate)
                                {
                                    name = "";
                                    id = "0";
                                    start_time = Convert.ToDateTime(dt.Rows[0]["RequestDate"].ToString()).ToString("yyyy-MM-dd HH:mm:ss");
                                    return name + "," + id + "," + start_time;
                                }
                                else
                                {
                                    name = "";
                                    id = "0";
                                    start_time = Convert.ToDateTime(dt.Rows[0]["RequestDate"].ToString()).ToString("yyyy-MM-dd HH:mm:ss");
                                    return name + "," + id + "," + start_time;
                                }
                            }
                            else
                            {
                                name = "";
                                id = "0";
                                start_time = Convert.ToDateTime(dt.Rows[0]["RequestDate"].ToString()).ToString("yyyy-MM-dd HH:mm:ss");
                                return name + "," + id + "," + start_time;
                            }
                        }
                    }
                }
                catch { }
                ///////////////////////////////////////////////////////////////////////////////



                /////////Get the Driver Details by vehicle and Driver Change log///////////////
                query = "select i.Name,i.DriverId,d.Fromdate from drivervehiclelog d " +
                        " join driverinfo i on i.DriverId=d.Driverid and i.AssignedVehicleId=d.Vehicleid" +
                        " where d.Vehicleid=? and d.Fromdate<=?" +
                        " and (d.Todate is NULL or d.Todate>=?) order by d.Fromdate desc,i.LastVerifiedDate desc,i.ApprovedDateTime desc";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("truckid", truckid);
                lParameter.Add("datetime", datetime);
                lParameter.Add("datetime1", datetime);
                DataSet ds = dbx.executeQuery(query, lParameter);
                if (ds.Tables[0].Rows.Count > 0)
                {
                    if (!string.IsNullOrEmpty(start_time))
                    {
                        DateTime drvchangeDate = Convert.ToDateTime(ds.Tables[0].Rows[0]["Fromdate"].ToString());
                        if (Convert.ToDateTime(start_time) < drvchangeDate)
                        {
                            name = ds.Tables[0].Rows[0][0].ToString();
                            id = ds.Tables[0].Rows[0][1].ToString();
                            start_time = drvchangeDate.ToString("yyyy-MM-dd HH:mm:ss");
                        }
                    }
                    else
                    {
                        name = ds.Tables[0].Rows[0][0].ToString();
                        id = ds.Tables[0].Rows[0][1].ToString();
                        start_time = Convert.ToDateTime(ds.Tables[0].Rows[0]["Fromdate"].ToString()).ToString("yyyy-MM-dd HH:mm:ss");
                    }
                }
                ////////////////////////////////////////////////////////////////////////////
                if (id == "0")
                {
                    try
                    {
                        query = "select d.Driverid,i.Name,d.Fromdate from drivervehiclelog d " +
                                 " join driverinfo i on i.DriverId=d.Driverid" +
                                 " where d.Vehicleid=? " +
                                 " and (? between d.Fromdate and d.Todate) order by id desc limit 1";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("truckid", truckid);
                        lParameter.Add("datetime", datetime);
                        ds = dbx.executeQuery(query, lParameter);
                        if (ds.Tables[0].Rows.Count > 0)
                        {
                            return ds.Tables[0].Rows[0]["Name"].ToString() + "," + ds.Tables[0].Rows[0]["Driverid"].ToString() + "," + Convert.ToDateTime(ds.Tables[0].Rows[0]["Fromdate"].ToString()).ToString("yyyy-MM-dd HH:mm:ss");
                        }
                    }
                    catch { }
                }
                ////////////Get Driver Details by Driver Info.////////////////////
                if (id == "0" && groupid == 147)//Modified by suvarna on 18/6/2021 for shell, If there is no driverassignment during mentioned datettime, then name should be blank
                {

                    name = "";
                    id = "";
                    start_time = datetime;
                }
                if (id == "0")
                {
                    query = "select i.Name,i.DriverId from driverinfo i " +
                            " where i.AssignedVehicleId=? order by i.ApprovedDateTime desc,i.LastVerifiedDate desc";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("truckid", truckid);
                    ds = dbx.executeQuery(query, lParameter);
                    if (ds.Tables[0].Rows.Count > 0)
                    {
                        name = ds.Tables[0].Rows[0][0].ToString();
                        id = ds.Tables[0].Rows[0][1].ToString();
                        start_time = DateTime.Now.AddMonths(-1).ToString("yyyy-MM-dd HH:mm:ss");
                    }
                }
                //////////////////////////////////////////////////////////////////
            }
            catch { }
            return name + "," + id + "," + start_time;
        }

        public string getLastVehicleLatLng(string truckid)
        {
            string latlng = "";
            string drivername = "";
            string driverid = "";
            try
            {
                String query = String.Empty;
                query = "select d.Name,d.DriverId,concat(p.Latitude,',',p.Longitude) from lastupdtdata p left join driverinfo d on "
                      + "p.TruckID=d.AssignedVehicleId where p.TruckID='" + truckid + "' order by i.ApprovedDateTime desc,i.LastVerifiedDate desc";
                DataSet ds = dbx.executeQuery(query);
                latlng = ds.Tables[0].Rows[0][0].ToString();
