        public DataSet getvehiclesinplant(string fromDateStr, string toDateStr, string sessionid)
        {
            string query = string.Empty;
            int groupid;

            query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
                           "sessionid =" + "'" + sessionid + "'";
            groupid = Convert.ToInt16(dbx.executeScalar(query));
            query = "select distinct v.vehicleid " + //v.vehicleid, locationstr,intimestamp,outtimestamp,outtimedone,planttype,concat(concat(substring_index(locationstr,' ',2),' ',substring_index(locationstr,' ',-1)) ),substring_index(locationstr,' ',-1)" +
                "  from vehicleinplant v join vehiclesgroupsmap v1" +
                            " on v.vehicleid = v1.vehicleid where " +
                             "  intimestamp between '" + fromDateStr + "' and '" + toDateStr + "'" +
                                    " and v1.groupid = " + groupid + " order by v.vehicleid , intimestamp desc;";
            DataSet dsVehicleinPlant = dbx.executeQuery(query);
            DataTable table = dsVehicleinPlant.Tables[0];
            string vehicleid = string.Empty;
            string location = string.Empty;
            string inTime = string.Empty;
            string outTime = string.Empty;
            int outtimedone;
            string locationPlant = string.Empty;
            string location_substr = string.Empty;
            int type;

            string vehicleidPrev = string.Empty;
            string locationPrev = string.Empty;
            string intimePrev = string.Empty;
            string outimePrev = string.Empty;
            int prev_outtimedone;
            int prev_type;
            string locationPlant_prev = string.Empty;
            string locationPrev_substr = string.Empty;
            DataSet dsVehicleMovements = new DataSet();
            DataTable dt = new DataTable();
            dt.Columns.Add("vehicleid", typeof(string));
            dt.Columns.Add("location", typeof(string));
            dt.Columns.Add("inTime", typeof(string));
            dt.Columns.Add("outTime", typeof(string));
            dt.Columns.Add("outtimedone", typeof(int));
            dt.Columns.Add("plantType", typeof(int));
            dt.Columns.Add("locationPlant", typeof(string));
            dt.Columns.Add("locationsubstr", typeof(string));
            dsVehicleMovements.Tables.Add(dt);
            foreach (DataRow row in table.Rows)
            {
                vehicleid = Convert.ToString(row[0]);
                query = "select vehicleid, locationstr,intimestamp,ifNull(outtimestamp,''),outtimedone,planttype,concat(concat(substring_index(locationstr,' ',2),' ',substring_index(locationstr,' ',-1)) ),substring_index(locationstr,' ',-1)" +
                           "  from vehicleinplant where vehicleid = " + "'" + vehicleid + "'" +
                            "  and intimestamp between '" + fromDateStr + "' and '" + toDateStr + "'" +
                                            " order by intimestamp desc limit 2;";
                DataSet dseachvehicle = new DataSet();
                dseachvehicle = dbx.executeQuery(query);
                DataTable tableVehicle = dseachvehicle.Tables[0];
                foreach (DataRow rowVehicle in tableVehicle.Rows)
                {
                    location = Convert.ToString(rowVehicle[1]);
                    inTime = Convert.ToString(rowVehicle[2]);
                    outTime = Convert.ToString(rowVehicle[3]);
                    outtimedone = Convert.ToInt32(rowVehicle[4]);
                    type = Convert.ToInt16(rowVehicle[5]);
                    locationPlant = Convert.ToString(rowVehicle[6]);
                    location_substr = Convert.ToString(rowVehicle[7]);
                    DataRow rowAllVehicles = dt.NewRow();
                    dt.Rows.Add(rowAllVehicles);
                    // dsVehicleMovements.Tables[dt].NewRow();
                    rowAllVehicles[0] = vehicleid;
                    rowAllVehicles[1] = location;
                    rowAllVehicles[2] = inTime;
                    rowAllVehicles[3] = outTime;
                    rowAllVehicles[4] = outtimedone;
                    rowAllVehicles[5] = type;
                    rowAllVehicles[6] = locationPlant;
                    rowAllVehicles[7] = location_substr;

                }

            }
            return dsVehicleMovements;
        }

        public Object[] writeVehiclesWaitingtoUnload(DataSet dsvehicles)
        {
            string location_substr = string.Empty;
            string vehicleidPrev = string.Empty;
            string locationPrev = string.Empty;
            string intimePrev = string.Empty;
            string outimePrev = string.Empty;
            int outtimedone = 0;
            int outtimedonePrev = 0;
            int typePrev = 0;
            string locationPrev_substr = string.Empty;
            ArrayList unloadingList = new ArrayList();
            //String[] unloadingVehicle = new string[3];                

            DataTable table = dsvehicles.Tables[0];


            if (table.Rows.Count == 0)
                return null;
            DataTable dt = new DataTable();
            dt.Columns.Add("locationsubstr", typeof(string));
            dt.Columns.Add("vehicleid", typeof(string));
            dt.Columns.Add("location", typeof(string));
            dt.Columns.Add("inTime", typeof(string));


            string vehicleid = string.Empty;
            string location = string.Empty;
            string inTime = string.Empty;
            string outTime = string.Empty;
            int type;
            bool entered = false;
            foreach (DataRow row in table.Rows)
            {

                vehicleid = Convert.ToString(row[0]);
                location = Convert.ToString(row[1]);
                inTime = Convert.ToString(row[2]);
                outTime = Convert.ToString(row[3]);
                outtimedone = Convert.ToInt16(row[4]);
                type = Convert.ToInt16(row[5]);
                location_substr = Convert.ToString(row[7]);
                entered = false;
                if (vehicleid != vehicleidPrev)
                {

                    entered = false;
                    if ((type == 1) && location.Contains("Unloading") && outtimedone == 0)
                    {
                        dt.Rows.Add(new Object[] { location_substr, vehicleid, location, inTime });
                        entered = true;

                    }
                }
                if ((vehicleid == vehicleidPrev) && entered == false)
                {
                    if (typePrev == 1 && locationPrev.Contains("Parking") && outtimedonePrev == 0 && !(location.Contains("Unloading") && (location_substr == locationPrev_substr)))
                    {
                        dt.Rows.Add(new Object[] { locationPrev_substr, vehicleid, locationPrev, intimePrev });
                        entered = true;
                    }
                }
                if ((vehicleid == vehicleidPrev) && entered == false)
                {
                    if (typePrev == 1 && type == 0 && outtimedonePrev == 0)
                    {
                        dt.Rows.Add(new Object[] { locationPrev_substr, vehicleid, locationPrev, intimePrev });
                        entered = true;
                    }
                }
                vehicleidPrev = vehicleid;
                locationPrev = location;
                intimePrev = inTime;
                outimePrev = outTime;
                typePrev = type;
                locationPrev_substr = location_substr;
                outtimedonePrev = outtimedone;

            }


            DataRow[] drow = dt.Select("", "locationsubstr,inTime");


            foreach (DataRow row in drow)
            {
                String[] unloadingVehicle = new string[3];
                unloadingVehicle[0] = Convert.ToString(row[1]);
                unloadingVehicle[1] = Convert.ToString(row[2]);
                unloadingVehicle[2] = Convert.ToString(row[3]);
                unloadingList.Add(unloadingVehicle);
            }

            return unloadingList.ToArray();
        }

