        public Object[] writeVehiclesWaitingtoLoad(DataSet dsvehicles)
        {
            string vehicleid = string.Empty;
            string location = string.Empty;
            string inTime = string.Empty;
            DateTime inTimeDate = new DateTime();
            string outTime = string.Empty;
            DateTime outTimeDate = new DateTime();
            int type;
            string location_substr = string.Empty;
            string vehicleidPrev = string.Empty;
            string locationPrev = string.Empty;
            string intimePrev = string.Empty;
            DateTime intimePrevDate = new DateTime();
            string outtimePrev = string.Empty;
            DateTime outtimePrevDate = new DateTime();
            int outtimedone = 0;
            int outtimedonePrev = 0;
            int typePrev = 0;
            string locationPrev_substr = string.Empty;
            ArrayList loadingList = new ArrayList();
            bool entered = false;
            // String[] loadingVehicle = new string[3];                

            DataTable table = dsvehicles.Tables[0];


            if (table.Rows.Count == 0)
                return null;
            DataTable dt = new DataTable();
            dt.Columns.Add("locationsubstr", typeof(string));
            dt.Columns.Add("vehicleid", typeof(string));
            dt.Columns.Add("location", typeof(string));
            dt.Columns.Add("inTime", typeof(String));
            dt.Columns.Add("inTimeDateformat", typeof(DateTime));


            foreach (DataRow row in table.Rows)
            {
                vehicleid = Convert.ToString(row[0]);
                location = Convert.ToString(row[1]);
                inTime = Convert.ToString(row[2]);
                inTimeDate = Convert.ToDateTime(inTime);

                outTime = Convert.ToString(row[3]);
                if (!String.IsNullOrEmpty(outTime))
                    outTimeDate = Convert.ToDateTime(outTime);
                outtimedone = Convert.ToInt16(row[4]);
                type = Convert.ToInt16(row[5]);
                location_substr = Convert.ToString(row[7]);
                if (vehicleid != vehicleidPrev)
                {
                    entered = false;
                    if (type == 0 && (location.Contains("Loading") && !location.Contains("Unloading")) && outtimedone == 0)
                    {

                        dt.Rows.Add(new Object[] { location_substr, vehicleid, location, inTime, inTimeDate });
                        entered = true;

                    }
                }
                if ((vehicleid == vehicleidPrev) && entered == false)
                {
                    if (typePrev == 0 && locationPrev.Contains("Parking") && outtimedonePrev == 0 && !(location.Contains(" Loading"))) // &&  location.Contains("Unloading")))
                    {
                        dt.Rows.Add(new Object[] { locationPrev_substr, vehicleid, locationPrev, intimePrev, intimePrevDate });
                    }
                }
                vehicleidPrev = vehicleid;
                locationPrev = location;
                locationPrev_substr = location_substr;
                intimePrev = inTime;
                outtimePrev = outTime;
                outtimedonePrev = outtimedone;
                typePrev = type;
            }
            DataRow[] drow = dt.Select("", "locationsubstr, inTimeDateformat");
            //DataRow[] drow = dt.Select("", "locationsubstr,inTime");
            //DataRow[] drowbylocation = dt.Select("", "locationsubstr,inTime");
            //DataTable dtbylocation = drowbylocation.CopyToDataTable();
            //DataRow[] drow = dtbylocation.Select("", "inTime");

            foreach (DataRow row in drow)
            {
                String[] loadingVehicle = new string[3];
                loadingVehicle[0] = Convert.ToString(row[1]);
                loadingVehicle[1] = Convert.ToString(row[2]);
                loadingVehicle[2] = Convert.ToString(row[3]);
                loadingList.Add(loadingVehicle);
            }
            return loadingList.ToArray();
        }

