        public Object[] summaryofLoadingUnloading(DataSet dsVehicles)
        {
            string query = string.Empty;
            Object[] waitingtoUnloadList = null;
            Object[] waitingtoLoadList = null;
            Object[] VehiclesUnloadedList = null;
            Object[] VehiclesLoadedList = null;
            try
            {
                query = "create  temporary table if not exists LoadUnloadSummary(ID INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,status varchar(200),vehicleid varchar(100),location varchar(200),ReportedTime varchar(30),unique index idxsummary(vehicleid) );";
                dbx.executeNonQuery(query);
                if ((waitingtoUnloadList = writeVehiclesWaitingtoUnload(dsVehicles)) != null)
                {
                    int count = waitingtoUnloadList.Length;
                    for (int i = 0; i < count; i++)
                    {
                        string vehicleid = ((Object[])waitingtoUnloadList[i])[0].ToString();
                        string location = ((Object[])waitingtoUnloadList[i])[1].ToString();
                        string reportedTime = ((Object[])waitingtoUnloadList[i])[2].ToString();
                        string status = "Waiting to Unload";
                        query = "insert into LoadUnloadSummary(status,vehicleid,location,ReportedTime) values(" + "'" + status + "'" + "," +
                             "'" + vehicleid + "'" + "," +
                            "'" + location + "'" + "," + "'" + reportedTime + "');";
                        dbx.executeNonQuery(query);
                    }
                }
                if ((waitingtoLoadList = writeVehiclesWaitingtoLoad(dsVehicles)) != null)
                {
                    int count = waitingtoLoadList.Length;
                    for (int i = 0; i < count; i++)
                    {
                        string vehicleid = ((Object[])waitingtoLoadList[i])[0].ToString();
                        string location = ((Object[])waitingtoLoadList[i])[1].ToString();
                        string reportedTime = ((Object[])waitingtoLoadList[i])[2].ToString();
                        string status = "Waiting to Load";
                        query = "insert into LoadUnloadSummary(status,vehicleid,location,ReportedTime) values(" + "'" + status + "'" + "," +
                             "'" + vehicleid + "'" + "," +
                            "'" + location + "'" + "," + "'" + reportedTime + "');";
                        dbx.executeNonQuery(query);
                    }
                }
                if ((VehiclesLoadedList = writeVehiclesLoadedTransit(dsVehicles)) != null)
                {
                    int count = VehiclesLoadedList.Length;
                    for (int i = 0; i < count; i++)
                    {
                        string vehicleid = ((Object[])VehiclesLoadedList[i])[0].ToString();
                        string location = ((Object[])VehiclesLoadedList[i])[1].ToString();
                        string reportedTime = ((Object[])VehiclesLoadedList[i])[2].ToString();
                        string status = "Loaded and Transit";
                        query = "insert into LoadUnloadSummary(status,vehicleid,location,ReportedTime) values(" + "'" + status + "'" + "," +
                             "'" + vehicleid + "'" + "," +
                            "'" + location + "'" + "," + "'" + reportedTime + "');";
                        dbx.executeNonQuery(query);
                    }
                }
                if ((VehiclesUnloadedList = writeVehiclesUnloadedTransit(dsVehicles)) != null)
                {
                    int count = VehiclesUnloadedList.Length;
                    for (int i = 0; i < count; i++)
                    {
                        string vehicleid = ((Object[])VehiclesUnloadedList[i])[0].ToString();
                        string location = ((Object[])VehiclesUnloadedList[i])[1].ToString();
                        string reportedTime = ((Object[])VehiclesUnloadedList[i])[2].ToString();
                        string status = "Unloaded and Transit";
                        query = "insert into LoadUnloadSummary(status,vehicleid,location,ReportedTime) values(" + "'" + status + "'" + "," +
                             "'" + vehicleid + "'" + "," +
                            "'" + location + "'" + "," + "'" + reportedTime + "');";
                        dbx.executeNonQuery(query);
                    }
                }
                query = "select status,location,count(distinct vehicleid) from LoadUnloadSummary  group by status,location";
                DataSet dsSummary = dbx.executeQuery(query);
                DataTable table = dsSummary.Tables[0];
                ArrayList SummaryList = new ArrayList();

                foreach (DataRow row in table.Rows)
                {
                    SummaryList.Add(row.ItemArray);
                }
                query = "drop temporary table if exists LoadUnloadSummary";
                dbx.executeNonQuery(query);
                return (SummaryList.ToArray());


            }
            catch
            {
                ArrayList arr = new ArrayList();
                return arr.ToArray();
            }
        }


