        public DataTable STL_Checklogin(string username, string password)
        {
            try
            {
                string query = "select * from stl_users where username='" + username + "'";
                DataTable dt = dbx.executeQuery(query).Tables[0];
                if (dt.Rows.Count > 0)
                {
                    if (dt.Rows[0]["password"].ToString() == password)
                    {
                        return dt;
                    }
                    else
                    {
                        return null;
                    }
                }
                else
                {
                    return null;
                }
            }
            catch { return null; }
        }

        public string STL_GetWorkflowTypeforAdd(string username, string vehicleid)
        {
            try
            {
                string workflowtype = "0";
                string query = "select * from stl_users where username='" + username + "'";
                DataTable dt = dbx.executeQuery(query).Tables[0];
                string usertype = dt.Rows[0]["usertype"].ToString();
                if (usertype == "1" || usertype == "2" || usertype == "3")
                {
                    return usertype;
                }
                else
                {
                    query = "select d.DateTime,d.LoadingPlaceName,p.locstr,i.CustomerType from vehicledctrip d" +
                            " join customerdcassign a on a.DCTripId=d.id" +
                            " join customerinfo i on i.customerId=a.CustomerId" +
                            " join plantgeolocations p on p.password=i.CustomerCode" +
                            " where d.VehicleID='" + vehicleid + "' order by d.DateTime desc limit 1";
                    DataTable dtdc = dbx.executeQuery(query).Tables[0];
                    if (dtdc.Rows.Count > 0)
                    {
                        if (dtdc.Rows[0]["locstr"].ToString().ToLower() == dt.Rows[0]["plant"].ToString().ToLower())
                        {
                            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
                            double difftranist = (now - Convert.ToDateTime(dtdc.Rows[0]["DateTime"].ToString())).TotalHours;
                            if (difftranist < 180)
                            {
                                query = "select username from stl_workflow a where a.vehicleId='" + vehicleid + "' order by workflowid desc limit 1";
                                DataTable laststl = dbx.executeQuery(query).Tables[0];
                                if (laststl.Rows.Count > 0)
                                {
                                    if (laststl.Rows[0]["username"].ToString().ToLower() != username.ToLower())
                                        return "3";
                                }
                            }
                        }
                    }
                }
                return workflowtype;
            }
            catch { return "0"; }
        }

