        public string STL_CreateWorkflow(string vehicleId, string group, string username, string latitude, string longitude, string vehicletype, string transporter, string wftype, string IMEI)
        {
            try
            {
                string accid = GetSTLAccountID(username);
                string query = "select IFNULL(Max(InspectionId),0) from stl_workflow where AccountId='" + accid + "' and workflowtype='" + wftype + "'";
                Int64 InspectionId = Convert.ToInt64(dbx.executeScalar(query).ToString()) + 1;
                string query1 = "SELECT l.latitude,l.longitude FROM lastupdtdata l WHERE Replace (truckid,' ','')=REPLACE('" + vehicleId + "',' ','');";
                DataTable dt = dbx.executeQuery(query1).Tables[0];
                if (dt.Rows.Count > 0)
                {
                    query = "Insert into stl_workflow(vehicleId,`group`,datetime,username,latitude,longitude,AccountId,InspectionId,vehicletype,transporter,workflowtype,vehicleLat,vehicleLong,IMEI) values('" + vehicleId + "','" + group + "','" + formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff())) + "','" + username + "','" + latitude + "','" + longitude + "','" + accid + "','" + InspectionId + "','" + vehicletype + "','" + transporter + "','" + wftype + "','" + dt.Rows[0]["latitude"].ToString() + "','" + dt.Rows[0]["longitude"].ToString() + "','" + IMEI + "')";
                }
                else
                {
                    query = "Insert into stl_workflow(vehicleId,`group`,datetime,username,latitude,longitude,AccountId,InspectionId,vehicletype,transporter,workflowtype,vehicleLat,vehicleLong,IMEI) values('" + vehicleId + "','" + group + "','" + formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff())) + "','" + username + "','" + latitude + "','" + longitude + "','" + accid + "','" + InspectionId + "','" + vehicletype + "','" + transporter + "','" + wftype + "','','','" + IMEI + "')";
                }
                int res = dbx.executeNonQuery(query);
                if (res > 0)
                {
                    query = "select Max(workflowId) from stl_workflow where username='" + username + "' and vehicleId='" + vehicleId + "'";
                    return dbx.executeScalar(query).ToString();
                }
                return "-1";
            }
            catch (Exception ex) { return "-1"; }
        }

