        public string STL_AddCheckedRules(string workflowid, string ruleId, string status, string comment, string image_link)
        {
            try
            {
                string[] imgarr = image_link.Split(';');
                int res = 0;
                for (int i = 0; i < imgarr.Length; i++)
                {
                    if (i == 0)
                    {
                        string query = "Insert into stl_workflowchecks(RuleId,Status,Comment,image_link,workflowId) values('" + ruleId + "','" + status + "','" + comment + "','" + imgarr[i] + "','" + workflowid + "');";
                        res = dbx.executeNonQuery(query);
                    }
                    else
                    {
                        STL_AddMoreworkflowImages(workflowid, ruleId, imgarr[i], "0");
                    }
                }
                return res.ToString();
            }
            catch { return "-1"; }
        }
        public string STL_UpdateIncentivePoints(string vehicleId, string workflowid, string Action, string username)
        {
            try
            {
                string query = "select * from incentivelog where Purpose='STL REJECTION' and VehicleId='" + vehicleId + "' and AddedDate>'" + formatDBDate(DateTime.Now.AddHours(-24)) + "' limit 1";
                DataTable dt = dbx.executeQuery(query).Tables[0];
                if (dt.Rows.Count > 0)
                {
                    if (Action.ToLower() == "allow")
                    {
                        query = "Update incentivelog set Wavied=1,EditedBy='" + username + "',EditedDate='" + formatDBDate(DateTime.Now) + "' where Id=" + dt.Rows[0]["Id"].ToString();
                        return dbx.executeNonQuery(query).ToString();
                    }
                    else
                        return "0";
                }
                else if (Action.ToLower() == "block")
                {
                    string driver = getdrivername(vehicleId);
                    string driverid = driver.Split(',')[1];
                    string drivername = driver.Split(',')[0];
                    int points = GetIncentiveCreteriaPoints("STL REJECTION", "ALERT", 0);
                    return RecordIncentiveLog("STL REJECTION", vehicleId, driverid, drivername, DateTime.Now.ToString("yyyy-MM-dd"), points, 9, username).ToString();
                }
                else
                    return "0";
            }
            catch { return "-1"; }
        }
