        public DataTable STL_CheckWorkFlowMC(string workflowid, string EditId)
        {
            try
            {
                if (EditId == "0")
                {
                    string query = "select c.RuleId,c.`Status`,r.RuleType from stl_workflowchecks c" +
                                   " join stl_checklist r on r.RuleId=c.RuleId" +
                                   " join stl_workflow w on w.workflowId=c.workflowId" +
                                   " where w.workflowId=" + workflowid + " and c.`Status`='No' and r.RuleType='MC' ";
                    return dbx.executeQuery(query).Tables[0];
                }
                else
                {
                    string query = "select c.RuleId,c.`Status`,r.RuleType from stl_editedworkflowchecks c" +
                                " join stl_checklist r on r.RuleId=c.RuleId" +
                                " join stl_workflow w on w.workflowId=c.workflowId" +
                                " where w.workflowId=" + workflowid + " and EditId='" + EditId + "' and c.`Status`='No' and r.RuleType='MC' ";
                    return dbx.executeQuery(query).Tables[0];
                }

            }
            catch { return null; }
        }

        public DataTable STL_CheckActionTaken(string vehicleId)
        {
            try
            {
                string query = "select a.workflowId,a.RuleId,c.Rule,a.`Action`,a.ExtendedDate,a.ExtendedDate,a.DateTime,a.addedBy " +
                               " from  stl_action a" +
                               " join stl_workflowchecks s on s.workflowId=a.workflowId and s.RuleId=a.RuleId and s.`Status`='No'" +
                               " join stl_checklist c on c.RuleId=a.RuleId where" +
                               " a.workflowId in (select  Max(a.workflowId) from  stl_action a where a.vehicleId='" + vehicleId + "' )";
                return dbx.executeQuery(query).Tables[0];

            }
            catch { return null; }
        }
        public string STL_GetCustDCWorkflowID(string CustDCAssigId, string wftype)
        {
            try
            {
                string query = "select max(w.workflowId) from customerdcassign c" +
                               " join vehicledctrip v on v.id=c.DCTripId" +
                               " join stl_workflow w on w.vehicleid=v.VehicleID";
                if (wftype == "0") //STL
                    query += " and w.DateTime<v.DateTime and w.workflowtype=0";
                else if (wftype == "1") //STD
                {
                    query += " and w.DateTime<DATE_ADD(v.DateTime,INTERVAL 3 HOUR) and w.workflowtype=1";
                }
                else if (wftype == "2") //SPOT
                {
                    query += " and w.DateTime>v.DateTime and w.workflowtype=2" +
                             " and (w.DateTime < v.TripEndsOn or v.TripEndsOn IS NULL)";
                }
                else if (wftype == "3") //STUL - UNLOAD
                {
                    query += " and w.DateTime>v.DateTime and w.workflowtype=3" +
                             " and (w.DateTime < v.TripEndsOn or v.TripEndsOn IS NULL)";
                }
                query += " where c.id= ?"; //+ CustDCAssigId;
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("id", CustDCAssigId);
                object res = dbx.executeScalar(query, lParameter);
                if (res == System.DBNull.Value)
                    return "0";
                else
                    return res.ToString();

            }
            catch { return "0"; }
        }

        public string STL_GetCustWorkflowID(string workflowid, string tripstarttime, string tripendtime, string lasttriptime, string Vehicleid, string seltype, string type)
        {
            try
            {
                int seltyp = int.Parse(seltype); int wftype = int.Parse(type);
                string Query = string.Empty;
                int wkflowid = int.Parse(workflowid);
                StringBuilder query = new StringBuilder();
                var lParameter = new Dictionary<string, Object>();
                string getNextWfid = "SELECT min(s.workflowId) FROM stl_workflow s WHERE s.vehicleId=? AND s.workflowtype=? And s.workflowId>?";
                string getBefrWfid = "SELECT max(s.workflowId) FROM stl_workflow s WHERE s.vehicleId=? AND s.workflowtype=? And s.workflowId<?";
                if (wftype == 3 || seltyp == 1)
                    query.Append(getNextWfid);
                else if (wftype == 1 || seltyp == 3)
                    query.Append(getBefrWfid);
                else if (seltyp < wftype)
                    query.Append(getNextWfid);
                else if (seltyp > wftype)
                    query.Append(getBefrWfid);
                if (wftype == 2 || wftype == 3)
                {
                    query.Append(" And s.datetime>?");
                    if (!string.IsNullOrEmpty(tripendtime))
                        query.Append(" and s.datetime<?");
                }
                else if (wftype == 0 || wftype == 1)
                {
                    query.Append(" And s.datetime<?");
                    if (!string.IsNullOrEmpty(lasttriptime))
                        query.Append(" and s.datetime>?");
                }

                lParameter.Add("vehicleId", Vehicleid);
                lParameter.Add("workflowtype", type);
                lParameter.Add("workflowId", workflowid);
                lParameter.Add("datetime", tripstarttime);
                if (wftype == 2 || wftype == 3)
                {
                    if (!string.IsNullOrEmpty(tripendtime))
                        lParameter.Add("datetime1", tripendtime);
                }
                else if (wftype == 1 || wftype == 0)
                {
                    if (!string.IsNullOrEmpty(lasttriptime))
                        lParameter.Add("datetime1", lasttriptime);
                }

                object res = dbx.executeScalar(query.ToString(), lParameter);

                if (res == System.DBNull.Value)
                    return "0";
                else
                    return res.ToString();

            }
            catch { return "0"; }

        }

        public DataTable STL_GetCheckList(string username, string group, string vehicletype)
        {
            try
            {
                string query = "select c.RuleId,c.Rule,IFNULL(g.IsBlockingPoint,c.RuleType) as RuleType,c.Input,r.IsMandatory,c.ListOrder from stl_checklist c" +
                               "  join stl_checklistgroup g on g.Ruleid=c.RuleId" +
                               "  join stl_checklistroles r on r.Checklistid=g.Ruleid" +
                               "  join stl_userroles u on u.roleid=r.roleId and u.username=?" +
                               "   where g.`group`=? and (g.vehicletype=? or g.vehicletype='0' or g.vehicletype='') order by c.ListOrder asc";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("username", username);
                lParameter.Add("group", group);
                lParameter.Add("vehicletype", vehicletype);
                if (string.IsNullOrEmpty(username) && string.IsNullOrEmpty(group) && string.IsNullOrEmpty(vehicletype))
                {
                    //All checklist
                    query = "select distinct c.RuleId,c.Rule,c.RuleType,c.Input,0 as IsMandatory,c.ListOrder from stl_checklist c" +
                               "  join stl_checklistgroup g on g.Ruleid=c.RuleId" +
                               "  join stl_checklistroles r on r.Checklistid=g.Ruleid" +
                               "  join stl_userroles u on u.roleid=r.roleId" +
                               "  order by c.ListOrder asc";
                    lParameter.Clear();
                }
                return dbx.executeQuery(query, lParameter).Tables[0];

            }
            catch { return null; }
        }

