        public DataTable STL_GetWorkflow(string wrkflowid)
        {
            try
            {
                if (!string.IsNullOrEmpty(wrkflowid))
                {
                    string query = " select  a.*,GROUP_CONCAT(m.image_link) as more_img,(select vehicleid from stl_workflow where workflowId='" + wrkflowid + "') as VehicleId from " +
                                   " (select distinct c.RuleId,r.Rule,c.`Comment`,c.`Status`,c.image_link,r.RuleType,  " +
                                   " e.timestamp as datetime,e.username,u.`level`,u.plant,e.Action,e.Comment as wrk_comment,e.EditId,r.Category,r.Input,r.ListOrder,'" + wrkflowid + "' as workflowId from stl_editedworkflowchecks c  " +
                                   " join stl_checklist r on r.RuleId=c.RuleId  " +
                                   " join stl_editedworkflow e on e.EditId=c.EditId  " +
                                   " join stl_users u on u.username=e.username  " +
                                   " where c.workflowId ='" + wrkflowid + "'  " +
                                   " union all  " +
                                   " select distinct c.RuleId,r.Rule,c.`Comment`,c.`Status`,c.image_link,r.RuleType,  " +
                                   " w.datetime,w.username,u.`level`,u.plant,w.Action,w.Comment as wrk_comment,0 as EditId,r.Category,r.Input,r.ListOrder,'" + wrkflowid + "' as workflowId from stl_workflowchecks c  " +
                                   " join stl_checklist r on r.RuleId=c.RuleId  " +
                                   " join stl_workflow w on w.workflowId=c.workflowId  " +
                                   " join stl_users u on u.username=w.username  " +
                                   " where c.workflowId ='" + wrkflowid + "') a  " +
                                   " left join stl_moreworkflowimages m on a.RuleId=m.RuleId and a.EditId=m.EditId and m.workflowid='" + wrkflowid + "' " +
                                   " group by a.EditId,a.RuleId " +
                                   " order by a.RuleId,a.datetime";
                    return dbx.executeQuery(query).Tables[0];
                }
                else
                {
                    return null;
                }

            }
            catch { return null; }
        }
