        //
        // 21 Feb 21 - A new flag indicating if the lat/long has been obtained via geolocation APIS. If no then lastupdtdata and its mirror lastupdtdataGL have
        // identical copies otherwise only lastupdtdata is updated.  i.e to say that lastupdtdataGL has only the last known GPS updates 
        // This is because in SHOW POSITIONS need to show both the  geolocation coordinates as well as last known GPS coordinates in map
        //
        public void updateLastPositionData(string vehicleId, DateTime timestamp, int start, int stop, double latitude, double longitude, double speed, double fuel,
            int hvinp, int gvinp1, DateTime ServerTs, int bv1, string PORT, string tmtr = null, int panic = 0, string temp = "0.0", Boolean geoL = false)
        {
            try
            {
                StringBuilder query = new StringBuilder();
                query.Append("select timestamp,stop,latitude,longitude,direction,start,speed,ServerTS,haltlat,haltlong,haltfrom from lastupdtdata where truckid='" + vehicleId + "'");
                DataTable dt = dbx.executeQuery(query.ToString()).Tables[0];
                query.Clear();
                DateTime lsttimestamp = timestamp;
                string formatedtimestamp = formatDBDate(timestamp);
                double dir = 0;
                if (dt.Rows.Count > 0)
                {
                    lsttimestamp = Convert.ToDateTime(dt.Rows[0]["timestamp"].ToString());
                    if (lsttimestamp <= timestamp)
                    {
                        double lastlat = Convert.ToDouble(dt.Rows[0]["latitude"].ToString());
                        double lastlng = Convert.ToDouble(dt.Rows[0]["longitude"].ToString());

                        double haltlat = Convert.ToDouble(dt.Rows[0]["haltlat"].ToString());
                        double haltlong = Convert.ToDouble(dt.Rows[0]["haltlong"].ToString());
                        double haltdist = computeDistance(haltlat, haltlong, latitude, longitude);

                        if ((timestamp - lsttimestamp).TotalHours >= 1)
                        {
                            string last_stop = dt.Rows[0]["stop"].ToString();
                            string last_start = dt.Rows[0]["start"].ToString();
                            string last_speed = dt.Rows[0]["speed"].ToString();
                            string last_ServerTS = dt.Rows[0]["ServerTS"].ToString();
                            string haltfrom = dt.Rows[0]["haltfrom"].ToString();

                            if (computeDistance(lastlat, lastlng, latitude, longitude) > 2)
                                UpdateMissingPositionData(vehicleId, lsttimestamp, lastlat, lastlng, last_stop, last_start, last_speed, last_ServerTS, timestamp, latitude, longitude, stop.ToString(), start.ToString(), speed.ToString(), ServerTs);
                            UpdatePositionDataGap(vehicleId, lsttimestamp, lastlat, lastlng, last_stop, last_start, last_speed, last_ServerTS, timestamp, latitude, longitude, stop.ToString(), start.ToString(), speed.ToString(), ServerTs, haltlat, haltlong, haltfrom);
                        }
                        dir = Convert.ToDouble(dt.Rows[0]["direction"].ToString());
                        if (stop == 0)
                        {
                            if (speed >= 3)//If Vehicle Speed > 3 -> Update Direction For Avoid Idling Direction Changes 
                                dir = angleFromlatlng(latitude, longitude, lastlat, lastlng);
                        }
                        if (!geoL)
                        {
                            query.Append("update lastupdtdata set timestamp = '" + formatedtimestamp + "',start = " + start + ",stop = " + stop + ",latitude = " + latitude
                                        + ",longitude = " + longitude + ",speed = " + speed + ",fuellevel = " + fuel + ",hvinp = " + hvinp + ",gvinp1 = " + gvinp1 + ",direction=" + dir + ",ServerTS='" + formatDBDate(ServerTs) + "',BV='" + bv1 + "',PORT='" + PORT + "',panic=" + panic + ",temp=" + temp);
                            if (haltdist > 0.25)
                            {
                                query.Append(",haltlat='" + latitude + "',haltlong='" + longitude + "',haltfrom='" + formatedtimestamp + "'");
                            }
                            query.Append(" where truckid = '" + vehicleId + "'");
                            int rowsUpdated = dbx.executeNonQuery(query.ToString());
                            query.Clear();
                            // Now we need to store the data in lastupdtdataGL as well. Here it is possible that there is no entry corresponding to this asset/vehicle
                            query.Append("select timestamp,stop,latitude,longitude,direction,start,speed,ServerTS,haltlat,haltlong,haltfrom from lastupdtdataGL where truckid='" + vehicleId + "'");
                            dt = dbx.executeQuery(query.ToString()).Tables[0];
                            query.Clear();
                            if (dt.Rows.Count > 0)
                            {
                                query.Append("update lastupdtdataGL set timestamp = '" + formatedtimestamp + "',start = " + start + ",stop = " + stop + ",latitude = " + latitude
                                            + ",longitude = " + longitude + ",speed = " + speed + ",fuellevel = " + fuel + ",hvinp = " + hvinp + ",gvinp1 = " + gvinp1 + ",direction=" + dir + ",ServerTS='" + formatDBDate(ServerTs) + "',BV='" + bv1 + "',PORT='" + PORT + "',panic=" + panic + ",temp=" + temp);
                                if (haltdist > 0.25)
                                {
                                    query.Append(",haltlat='" + latitude + "',haltlong='" + longitude + "',haltfrom='" + formatedtimestamp + "'");
                                }
                                query.Append(" where truckid = '" + vehicleId + "'");
                                rowsUpdated = dbx.executeNonQuery(query.ToString());
                                query.Clear();
                            }
                            else
                            {
                                query.Append("insert into lastupdtdataGL(truckid,timestamp,start,stop,latitude,longitude,speed,fuellevel,hvinp,gvinp1,direction,BV,PORT,ServerTS,temp,panic) values('" + vehicleId + "','"
                                + formatDBDate(timestamp) + "'," + start + "," + stop + "," + latitude + "," + longitude + "," + speed + "," + fuel + "," + hvinp +
                                "," + gvinp1 + ",0,'" + bv1 + "','" + PORT + "','" + formatDBDate(ServerTs) + "'," + temp + "," + panic + ")");
                                dbx.executeNonQuery(query.ToString());
                            }
                        }
                        else
                        {
                            query.Append("update lastupdtdata set timestamp = '" + formatedtimestamp + "',start = " + start + ",stop = " + stop + ",latitude = " + latitude
                                        + ",longitude = " + longitude + ",speed = " + speed + ",fuellevel = " + fuel + ",hvinp = " + hvinp + ",gvinp1 = " + gvinp1 + ",direction=" + dir + ",ServerTS='" + formatDBDate(ServerTs) + "',BV='" + bv1 + "',PORT='" + PORT + "',panic=" + panic + ",temp=" + temp);
                            if (haltdist > 0.25)
                            {
                                query.Append(",haltlat='" + latitude + "',haltlong='" + longitude + "',haltfrom='" + formatedtimestamp + "'");
                            }
                            query.Append(" where truckid = '" + vehicleId + "'");
                            int rowsUpdated = dbx.executeNonQuery(query.ToString());
                            // It is likely that lastupdtdataGL is empty
                            /* query.Append("select timestamp,stop,latitude,longitude,direction,start,speed,ServerTS,haltlat,haltlong,haltfrom from lastupdtdataGL where truckid='" + vehicleId + "'");
                             dt = dbx.executeQuery(query.ToString()).Tables[0];
                             query.Clear();
                             if (dt.Rows.Count > 0)
                             {
                                 query.Append("update lastupdtdataGL set timestamp = '" + formatedtimestamp + "',start = " + start + ",stop = " + stop + ",latitude = " + latitude
                                             + ",longitude = " + longitude + ",speed = " + speed + ",fuellevel = " + fuel + ",hvinp = " + hvinp + ",gvinp1 = " + gvinp1 + ",direction=" + dir + ",ServerTS='" + formatDBDate(ServerTs) + "',BV='" + bv1 + "',PORT='" + PORT + "',panic=" + panic + ",temp=" + temp);
                                 if (haltdist > 0.25)
                                 {
                                     query.Append(",haltlat='" + latitude + "',haltlong='" + longitude + "',haltfrom='" + formatedtimestamp + "'");
                                 }
                                 query.Append(" where truckid = '" + vehicleId + "'");
                                 int rowsUpdated = dbx.executeNonQuery(query.ToString());
                                 query.Clear();
                             }
                             else
                             {
                                 query.Append("insert into lastupdtdataGL(truckid,timestamp,start,stop,latitude,longitude,speed,fuellevel,hvinp,gvinp1,direction,BV,PORT,ServerTS,temp,panic) values('" + vehicleId + "','"
                                 + formatDBDate(timestamp) + "'," + start + "," + stop + "," + latitude + "," + longitude + "," + speed + "," + fuel + "," + hvinp +
                                 "," + gvinp1 + ",0,'" + bv1 + "','" + PORT + "','" + formatDBDate(ServerTs) + "'," + temp + "," + panic + ")");
                                 dbx.executeNonQuery(query.ToString());
                             }*/
                        }
                        if (start == 1 && tmtr != "tamper")
                        {
                            addServerRequest(vehicleId, 5, "(ACT ATCMD AT+CCID )");
                        }
                    }
                    else
                    {
                        //Counting No.of delayed packetes
                        //UpdateDealyedPointsinDataGap(vehicleId, formatedtimestamp);
                    }
                }
                else
                {   // if the lat/long is obtained by geolocation then update only the lastupdtdatGL table.
                    if (!geoL)
                    {   // 
                        query.Append("insert into lastupdtdata(truckid,timestamp,start,stop,latitude,longitude,speed,fuellevel,hvinp,gvinp1,direction,BV,PORT,ServerTS,temp,panic) values('" + vehicleId + "','"
                            + formatDBDate(timestamp) + "'," + start + "," + stop + "," + latitude + "," + longitude + "," + speed + "," + fuel + "," + hvinp +
                            "," + gvinp1 + ",0,'" + bv1 + "','" + PORT + "','" + formatDBDate(ServerTs) + "'," + temp + "," + panic + ")");
                        dbx.executeNonQuery(query.ToString());
                        query.Clear();

                        query.Append("insert into lastupdtdataGL(truckid,timestamp,start,stop,latitude,longitude,speed,fuellevel,hvinp,gvinp1,direction,BV,PORT,ServerTS,temp,panic) values('" + vehicleId + "','"
                        + formatDBDate(timestamp) + "'," + start + "," + stop + "," + latitude + "," + longitude + "," + speed + "," + fuel + "," + hvinp +
                        "," + gvinp1 + ",0,'" + bv1 + "','" + PORT + "','" + formatDBDate(ServerTs) + "'," + temp + "," + panic + ")");
                        dbx.executeNonQuery(query.ToString());
                        query.Clear();
                    }
                    else
                    {
                        query.Append("insert into lastupdtdata(truckid,timestamp,start,stop,latitude,longitude,speed,fuellevel,hvinp,gvinp1,direction,BV,PORT,ServerTS,temp,panic) values('" + vehicleId + "','"
                            + formatDBDate(timestamp) + "'," + start + "," + stop + "," + latitude + "," + longitude + "," + speed + "," + fuel + "," + hvinp +
                            "," + gvinp1 + ",0,'" + bv1 + "','" + PORT + "','" + formatDBDate(ServerTs) + "'," + temp + "," + panic + ")");
                        dbx.executeNonQuery(query.ToString());
                        query.Clear();
                        // it is possible that lastupdtdataGL has entry for this vehicle so check and either insert or update
