        public void PushDataToOthers(DataTable dtpush, string vehicleId, DateTime timestamp, int start, int stop, double latitude, double longitude, double speed,
            double fuel, int hvinp, int gvinp1, DateTime ServerTs, int bv1, string PORT, double dir, string tmtr, int panic)
        {
            for (int i = 0; i < dtpush.Rows.Count; i++)
            {
                try
                {
                    if (dtpush.Rows[i]["Active"].ToString() == "True")
                    {
                        string EndPoint = dtpush.Rows[i]["URL"].ToString();
                        string log = dtpush.Rows[i]["log"].ToString();
                        string PostData = dtpush.Rows[i]["Template"].ToString();
                        string ContentType = dtpush.Rows[i]["ContentType"].ToString();
                        string HTTPMethod = dtpush.Rows[i]["HTTPMethod"].ToString();
                        string Headers = dtpush.Rows[i]["Headers"].ToString();
                        string IsTMTR = dtpush.Rows[i]["IsTMTR"].ToString();
                        if (IsTMTR == "1" && string.IsNullOrEmpty(tmtr))
                            continue;
                        PostData = PostData.Replace("<VEHICLE>", vehicleId.Replace(" ", ""));
                        if (PostData.Contains("<UID>"))
                        {
                            PostData = PostData.Replace("<UID>", GetUIDByVehicleId(vehicleId));
                        }
                        if (PostData.Contains("<LOCATION>"))
                        {
                            PostData = PostData.Replace("<LOCATION>", getPositionTxt(latitude.ToString(), longitude.ToString(), 0));
                        }
                        PostData = PostData.Replace("<LAT>", latitude.ToString());
                        PostData = PostData.Replace("<LNG>", longitude.ToString());
                        PostData = PostData.Replace("<DATE>", timestamp.ToString("yyyy-MM-dd"));
                        PostData = PostData.Replace("<TIME>", timestamp.ToString("HH:mm:ss"));
                        PostData = PostData.Replace("<DATETIME>", timestamp.ToString("yyyy-MM-dd HH:mm:ss"));
                        PostData = PostData.Replace("<GMT_DATETIME>", timestamp.AddSeconds(-19800).ToString("yyyy/MM/dd HH:mm:ss"));
                        PostData = PostData.Replace("<GMTDATE>", timestamp.AddSeconds(-19800).ToString("yyyy-MM-dd"));
                        PostData = PostData.Replace("<GMTTIME>", timestamp.AddSeconds(-19800).ToString("HH:mm:ss"));
                        PostData = PostData.Replace("<GMTDATETIME>", timestamp.AddSeconds(-19800).ToString("yyyy-MM-dd HH:mm:ss"));
                        PostData = PostData.Replace("<UNIXTIME>", ((Int64)(timestamp.Subtract(new DateTime(1970, 1, 1))).TotalSeconds).ToString());
                        PostData = PostData.Replace("<UNIXTIME_UTC>", ((Int64)(timestamp.AddSeconds(-19800).Subtract(new DateTime(1970, 1, 1))).TotalSeconds).ToString());
                        PostData = PostData.Replace("<SPEED>", speed.ToString());
                        PostData = PostData.Replace("<DIR>", dir.ToString());
                        PostData = PostData.Replace("<IGN>", (stop == 0 ? 1 : 0).ToString());
                        PostData = PostData.Replace("<IGN_B>", (stop == 0 ? "true" : "false").ToString());
                        PostData = PostData.Replace("<SER_DATE>", DateTime.Now.ToString("yyyy-MM-dd"));
                        PostData = PostData.Replace("<SER_TIME>", DateTime.Now.ToString("HH:mm:ss"));
                        PostData = PostData.Replace("<SER_DATETIME>", DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                        PostData = PostData.Replace("<PANIC>", panic.ToString());
                        bool tmtrFlag = true;
                        if (!string.IsNullOrEmpty(tmtr))
                        {
                            string IsTMTRloop = dtpush.Rows[i]["IsTMTRloop"].ToString();
                            string SplitChar = dtpush.Rows[i]["SplitChar"].ToString();
                            if (IsTMTRloop == "1" && !string.IsNullOrEmpty(SplitChar) && PostData.Contains("<TMTRLOOP>") && PostData.Contains("</TMTRLOOP>"))
                            {
                                tmtrFlag = false;
                                string[] tmtrStr = tmtr.Split(new string[] { SplitChar }, StringSplitOptions.None);
                                string fullPostData = "";
                                string[] splitStr = PostData.Split(new string[] { "<TMTRLOOP>" }, StringSplitOptions.None);
                                string beforeLoopStr = splitStr[0];
                                splitStr = splitStr[1].Split(new string[] { "</TMTRLOOP>" }, StringSplitOptions.None);
                                PostData = splitStr[0];
                                string afterLoopStr = splitStr[1];
                                for (int a = 0; a < tmtrStr.Length; a++)
                                {
                                    string dupPostData = PostData;
                                    dupPostData = dupPostData.Replace("<TMTR>", tmtrStr[a]);
                                    if (fullPostData != "")
                                        fullPostData += ",";
                                    fullPostData += dupPostData;
                                }
                                PostData = beforeLoopStr + fullPostData + afterLoopStr;
                            }
                        }
                        if (tmtrFlag)
                            PostData = PostData.Replace("<TMTR>", tmtr);
                        string res = MakeHttpRequest(EndPoint, HTTPMethod, ContentType, PostData, Headers);
                        if (log == "1")
                        {
                            string id = dtpush.Rows[i]["id"].ToString();
                            string query = "insert into tbl_push_data_log(PushId,truckid,timestamp,response,ServerTS,data) values(" + id + ",'" + vehicleId + "','"
                                + formatDBDate(timestamp) + "',?,'" + formatDBDate(ServerTs) + "',?)";
                            var lParameter = new Dictionary<string, object>();
                            lParameter.Add("response", res);
                            lParameter.Add("data", PostData);
                            dbx.executeNonQuery(query.ToString(), lParameter);
                        }
                    }
                }
                catch (Exception ex)
                {
                    string query = "insert into tbl_push_data_log(PushId,truckid,timestamp,response,ServerTS,data) values(1,'" + vehicleId + "','"
                        + formatDBDate(timestamp) + "',?,'" + formatDBDate(ServerTs) + "',?)";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("response", ex.ToString());
                    lParameter.Add("data", "");
                    dbx.executeNonQuery(query.ToString(), lParameter);
                }
            }
        }
