        public string PushDataToOthers(string endPoint, string header, string data)
        {
            DateTime ServerTs = DateTime.Now;
            string vehicleId = "";
            string id = "0";
            string response = "";
            try
            {
                string query = "select * from tbl_push_data t where t.URL=? and t.Headers=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("URL", endPoint);
                lParameter.Add("Headers", header);
                DataTable dtpush = dbx.executeQuery(query, lParameter).Tables[0];
                string PostData = @"[<DATA_LOOP>{""gpsId"": ""<UID>"",""timestamp"": ""<UNIXTIME_UTC>"",""lat"": ""<LAT>"",""lng"": ""<LNG>"",""speed"": <SPEED>,""ignitionStatus"": <IGN>,""address"": ""<LOCATION>"",""acStatus"": <HV_INP>,""orientation"": <DIR>,""vehicleNo"": ""<VEHICLE>""}</DATA_LOOP>]";
                string log = "0";
                if (dtpush.Rows.Count > 0)
                {
                    if (dtpush.Rows[0]["Active"].ToString() == "True")
                    {
                        PostData = dtpush.Rows[0]["Template"].ToString();
                        log = dtpush.Rows[0]["log"].ToString();
                        id = dtpush.Rows[0]["id"].ToString();
                    }
                }
                string[] dataStr = data.Split('|');
                string uid = dataStr[0];
                vehicleId = dataStr[dataStr.Length - 1];
                int indexToremove = 0;
                dataStr = dataStr.Take(indexToremove).Concat(dataStr.Skip(indexToremove + 1)).ToArray();
                indexToremove = dataStr.Length - 1;
                dataStr = dataStr.Take(indexToremove).Concat(dataStr.Skip(indexToremove + 1)).ToArray();
                string fullPostData = "";
                string[] splitStr = PostData.Split(new string[] { "<DATA_LOOP>" }, StringSplitOptions.None);
                string beforeLoopStr = splitStr[0];
                splitStr = splitStr[1].Split(new string[] { "</DATA_LOOP>" }, StringSplitOptions.None);
                PostData = splitStr[0];
                string afterLoopStr = splitStr[1];
                for (int a = 0; a < dataStr.Length; a++)
                {
                    string dupPostData = PostData;
                    string[] paramsStr = dataStr[a].Split(',');
                    dupPostData = dupPostData.Replace("<UID>", uid);
                    dupPostData = dupPostData.Replace("<LAT>", paramsStr[0]);
                    dupPostData = dupPostData.Replace("<LNG>", paramsStr[1]);
                    dupPostData = dupPostData.Replace("<UNIXTIME_UTC>", paramsStr[2]);
                    dupPostData = dupPostData.Replace("<SPEED>", paramsStr[3]);
                    dupPostData = dupPostData.Replace("<IGN>", paramsStr[4] == "1" ? "0" : "1");
                    dupPostData = dupPostData.Replace("<HV_INP>", paramsStr[5]);
                    dupPostData = dupPostData.Replace("<DIR>", paramsStr[6]);
                    if (dupPostData.Contains("<LOCATION>"))
                        dupPostData = dupPostData.Replace("<LOCATION>", getPositionTxt(paramsStr[0], paramsStr[1], 0));
                    dupPostData = dupPostData.Replace("<VEHICLE>", vehicleId);
                    if (fullPostData != "")
                        fullPostData += ",";
                    fullPostData += dupPostData;
                }
                PostData = beforeLoopStr + fullPostData + afterLoopStr;
                response = MakeHttpRequest(endPoint, "POST", "application/json", PostData, header);
                if (log == "1")
                {
                    query = "insert into tbl_push_data_log(PushId,truckid,timestamp,response,ServerTS,data) values(?,?,?,?,?,?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("PushId", id);
                    lParameter.Add("truckid", vehicleId);
                    lParameter.Add("timestamp", formatDBDate(ServerTs));
                    lParameter.Add("response", response);
                    lParameter.Add("ServerTS", formatDBDate(ServerTs));
                    lParameter.Add("data", PostData);
                    dbx.executeNonQuery(query.ToString(), lParameter);
                }
            }
            catch (Exception ex)
            {
                response = ex.ToString();
                try
                {
                    string query = "insert into tbl_push_data_log(PushId,truckid,timestamp,response,ServerTS,data) values(?,?,?,?,?,?)";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("PushId", id);
                    lParameter.Add("truckid", vehicleId);
                    lParameter.Add("timestamp", formatDBDate(ServerTs));
                    lParameter.Add("response", ex.ToString());
                    lParameter.Add("ServerTS", formatDBDate(ServerTs));
                    lParameter.Add("data", data);
                    dbx.executeNonQuery(query.ToString(), lParameter);
                }
                catch { }
            }
            return response;
        }

