        //Added by Tushar for Adani SOUL
        public string MakeHttpRequestForAdaniSOUL(string EndPoint, string HttpMethod, string ContentType, string PostData = "", string Headers = "")
        {
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls | SecurityProtocolType.Tls11 | SecurityProtocolType.Tls12 | SecurityProtocolType.Ssl3;
            ///Added by Vamsi Krishna on 2020-09-22
            ///Certification validations are ignored
            ServicePointManager.ServerCertificateValidationCallback += (sender, cert, chain, sslPolicyErrors) => { return true; };
            var responseValue = string.Empty;
            try
            {
                var request = (System.Net.HttpWebRequest)System.Net.WebRequest.Create(EndPoint);

                request.Method = HttpMethod;
                request.ContentLength = 0;
                request.ContentType = ContentType;
                request.Accept = "application/json";
                System.Net.ServicePointManager.DefaultConnectionLimit = 100000;
                if (!string.IsNullOrEmpty(Headers))
                {
                    string[] heads = Headers.Split(new string[] { "||" }, StringSplitOptions.None);
                    foreach (string h in heads)
                    {
                        request.Headers.Add(h.Split(',')[0], h.Split(',')[1]);
                    }
                }
                if (!string.IsNullOrEmpty(PostData) && HttpMethod == "POST")
                {
                    var encoding = new UTF8Encoding();
                    var bytes = Encoding.GetEncoding("iso-8859-1").GetBytes(PostData);
                    request.ContentLength = bytes.Length;

                    using (var writeStream = request.GetRequestStream())
                    {
                        writeStream.Write(bytes, 0, bytes.Length);
                    }
                }
                else if (!string.IsNullOrEmpty(PostData) && HttpMethod == "PUT")
                {
                    var encoding = new UTF8Encoding();
                    var bytes = Encoding.GetEncoding("iso-8859-1").GetBytes(PostData);
                    request.ContentLength = bytes.Length;

                    using (var writeStream = request.GetRequestStream())
                    {
                        writeStream.Write(bytes, 0, bytes.Length);
                    }
                }
                //request.Timeout = 2500;
                using (var response = (System.Net.HttpWebResponse)request.GetResponse())
                {
                    //if (response.StatusCode != System.Net.HttpStatusCode.OK)
                    //{
                    //    var message = String.Format("Request failed. Received HTTP {0}", response.StatusCode);
                    //    return "";
                    //}
                    // grab the response
                    using (var responseStream = response.GetResponseStream())
                    {
                        if (responseStream != null)
                        {
                            using (var reader = new StreamReader(responseStream))
                            {
                                responseValue = reader.ReadToEnd();
                            }
                        }
                    }

                    return responseValue;
                }
            }
            catch (Exception ex)
            {
                return "Error:" + responseValue + ex.ToString();
            }
        }

        // This class is an object store that gets returned on EndGetResponse is called which can then be used to log data.
        public class pushAsyncWebRequestState
        {
            public string truckid;//= String.Empty;
            public DateTime pktTime;// = DateTime.MinValue;
            public string pdu;// = String.Empty;
            public HttpWebRequest request;
            public HttpWebResponse response;
            public Stream streamResponse;
            public pushAsyncWebRequestState()
            { }
        }
        // 
        // Start the Async call to the remote end point 
        // Need to add a timeout mechanism in case the remote host takes a long time 
        private void CallRemoteAsync(HttpWebRequest request, string pdu, string truckid, DateTime pktTime, DBConnection dbx)
        {
            pushAsyncWebRequestState myState = new pushAsyncWebRequestState();
            try
            {
                myState.truckid = truckid;
                myState.pdu = pdu;
                myState.pktTime = pktTime;
                myState.request = request;
                // Start the asynchronous request.
                IAsyncResult result =
                  (IAsyncResult)request.BeginGetResponse(new AsyncCallback(RecordResponse1), myState);
            }
            catch (WebException ex)
            {
                myState.response = ex.Response as HttpWebResponse;
                //LogPushDataErrorFromParserAsync(myState.truckid, (DateTime)myState.pktTime, DateTime.Now, myState.response.ToString(), myState.pdu);
                LogPushDataErrorFromParser(myState.truckid, (DateTime)myState.pktTime, DateTime.Now, myState.response.ToString(), myState.pdu);
            }
            catch (Exception e)
            {
                //LogPushDataErrorFromParserAsync(myState.truckid, (DateTime)myState.pktTime, DateTime.Now, e.ToString(), myState.pdu);
                LogPushDataErrorFromParser(myState.truckid, (DateTime)myState.pktTime, DateTime.Now, e.ToString(), myState.pdu);
            }
        }

        private void RecordResponse1(IAsyncResult ar)
        {
            pushAsyncWebRequestState myState = (pushAsyncWebRequestState)ar.AsyncState;
            try
            {
                HttpWebRequest myHttpWebRequest = myState.request;
                HttpWebResponse response = (HttpWebResponse)myHttpWebRequest.EndGetResponse(ar);
                String body = new StreamReader(response.GetResponseStream()).ReadToEnd();
                //LogPushDataErrorFromParserAsync(myState.truckid, (DateTime)myState.pktTime, DateTime.Now, body, myState.pdu);
                LogPushDataErrorFromParser(myState.truckid, (DateTime)myState.pktTime, DateTime.Now, body, myState.pdu);
            }
            catch (WebException ex)
            {
                // It needs to be done like this in order to read responses with error status:
                //myState.response = ex.Response as HttpWebResponse;
                //LogPushDataErrorFromParserAsync(myState.truckid, (DateTime)myState.pktTime, DateTime.Now, "In RecordResp" + ex.ToString(), myState.pdu);
                LogPushDataErrorFromParser(myState.truckid, (DateTime)myState.pktTime, DateTime.Now, "In RecordResp" + ex.ToString(), myState.pdu);
            }
        }
