        public string MakeHttpRequestMMI(string EndPoint, string HttpMethod, string ContentType, string PostData = "", string Headers = "")
        {
            string exepurl = "";
            try
            {
                int tls10 = (int)SecurityProtocolType.Tls;
                int tls11 = (int)SecurityProtocolType.Tls11;
                int tls12 = (int)SecurityProtocolType.Tls12;
                int ssl3 = (int)SecurityProtocolType.Ssl3;
                exepurl = "tls10-" + tls10 + "tls11-" + tls11 + "tls12-" + tls12 + "ssl3-" + ssl3;

            }
            catch (Exception ex)
            {

            }
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
            ///Added by Vamsi Krishna on 2020-09-22
            ///Certification validations are ignored
            ServicePointManager.ServerCertificateValidationCallback += (sender, cert, chain, sslPolicyErrors) => { return true; };
            var responseValue = string.Empty;
            try
            {
                var request = (System.Net.HttpWebRequest)System.Net.WebRequest.Create(EndPoint);

                request.Method = HttpMethod;
                request.ContentLength = 0;
                request.ContentType = ContentType;
                System.Net.ServicePointManager.DefaultConnectionLimit = 100000;
                if (!string.IsNullOrEmpty(Headers))
                {
                    string[] heads = Headers.Split(new string[] { "||" }, StringSplitOptions.None);
                    foreach (string h in heads)
                    {
                        request.Headers.Add(h.Split(',')[0], h.Split(',')[1]);
                    }
                }
                if (!string.IsNullOrEmpty(PostData) && HttpMethod == "POST")
                {
                    var encoding = new UTF8Encoding();
                    var bytes = Encoding.GetEncoding("iso-8859-1").GetBytes(PostData);
                    request.ContentLength = bytes.Length;

                    using (var writeStream = request.GetRequestStream())
                    {
                        writeStream.Write(bytes, 0, bytes.Length);
                    }
                }
                using (var response = (System.Net.HttpWebResponse)request.GetResponse())
                {
                    //if (response.StatusCode != System.Net.HttpStatusCode.OK)
                    //{
                    //    var message = String.Format("Request failed. Received HTTP {0}", response.StatusCode);
                    //    return "";
                    //}
                    // grab the response
                    using (var responseStream = response.GetResponseStream())
                    {
                        if (responseStream != null)
                        {
                            using (var reader = new StreamReader(responseStream))
                            {
                                responseValue = reader.ReadToEnd();
                            }
                        }
                    }

                    return responseValue;
                }
            }
            catch (Exception ex)
            {
                ExceptionLogging("MakeHttpRequestMMI", "ui.vehicle-tracking", EndPoint, HttpMethod, ContentType, PostData, Headers, ex.Message.ToString(), ex.GetType().Name.ToString(), exepurl, ex.StackTrace.ToString());
                return "Error:" + responseValue + ex.ToString();
            }
        }

