        public double angleFromlatlng(double lat1, double long1, double lat2, double long2)
        {
            double angle = Math.Atan2(lat1 - lat2, long1 - long2);
            angle = angle * (180 / Math.PI);
            angle = (angle + 360) % 360;
            angle = 360 - angle + 90;
            return angle;
        }

        public void AddandUpdateDriverDocs(string DriverId, string[] doc, string[] files)
        {
            try
            {
                String query = "Select Id from driverdocument where DriverId = '" + DriverId + "'";
                DataTable dt = dbx.executeQuery(query).Tables[0];
                if (dt.Rows.Count > doc.Length)
                {
                    query = "Delete from driverdocument where DriverId = '" + DriverId + "'";
                    int rowsUpdated = dbx.executeNonQuery(query);
                }
                for (int i = 0; i < doc.Length; i++)
                {
                    if (!string.IsNullOrEmpty(files[i]))
                    {
                        query = "Select Id from driverdocument where DriverId = '" + DriverId + "' and FileNo='" + i + "';";
                        dt = dbx.executeQuery(query).Tables[0];
                        if (dt.Rows.Count >= 1)
                        {
                            query = "update driverdocument set DocumentName='" + doc[i] + "',FilePath='" + files[i] + "' where Id = '" + dt.Rows[0]["Id"].ToString() + "'";
                            dbx.executeNonQuery(query);
                        }
                        else
                        {
                            query = "Insert into driverdocument(DocumentName,FilePath,DriverId,FileNo) values('" + doc[i] + "','" + files[i] + "'," + DriverId + "," + i + ")";
                            dbx.executeNonQuery(query);
                        }
                    }
                }
            }
            catch { }
        }
        public void AddandUpdatevehicleDocs(string VehicleId, string[] doc, string[] files)
        {
            try
            {
                String query = "Select Id from vehicledocument where REPLACE(VehicleId,' ','') = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", VehicleId.Trim().Replace(" ", ""));
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                if (dt.Rows.Count > doc.Length)
                {
                    query = "Delete from vehicledocument where REPLACE(VehicleId,' ','') = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("VehicleId", VehicleId.Trim().Replace(" ", ""));
                    int rowsUpdated = dbx.executeNonQuery(query, lParameter);
                }
                for (int i = 0; i < doc.Length; i++)
                {
                    if (!string.IsNullOrEmpty(files[i]))
                    {
                        query = "Select Id from vehicledocument where REPLACE(VehicleId,' ','') = ? and FileNo=?;";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("VehicleId", VehicleId.Trim().Replace(" ", ""));
                        lParameter.Add("FileNo", i);
                        dt = dbx.executeQuery(query, lParameter).Tables[0];
                        if (dt.Rows.Count >= 1)
                        {
                            query = "update vehicledocument set DocumentName=?,FilePath=? where Id = ?";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("DocumentName", doc[i]);
                            lParameter.Add("FilePath", files[i]);
                            lParameter.Add("Id", dt.Rows[0]["Id"].ToString());
                            dbx.executeNonQuery(query, lParameter);
                        }
                        else
                        {
                            query = "Insert into vehicledocument(DocumentName,FilePath,VehicleId,FileNo) values(?,?,?,?)";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("DocumentName", doc[i]);
                            lParameter.Add("FilePath", files[i]);
                            lParameter.Add("VehicleId", VehicleId);
                            lParameter.Add("FileNo", i);
                            dbx.executeNonQuery(query, lParameter);
                        }
                    }
                }
            }
            catch { }
        }
