						 '{row["DriverMedicalFitness"]}', '{row["ActiveDriver"]}', '{row["ActiveDriverNo"]}', '{row["EngrName"]}', 
						 '{row["EngrId"]}', '{row["EngrMobileNo"]}', '{row["concat(p.TagInTime)"]}', '{row["concat(p.TagOutTime)"]}', '{row["concat(TIMEDIFF(p.TagOutTime,p.TagInTime))"]}',
						 '{row["PTW_Number"]}', '{row["WFM_ID"]}', '{row["WFM_Task"]}', '{row["TagInOMR"]}', '{row["TagOutOMR"]}',
						 '{row["OMRDist"]}', '{row["startlatlng"]}', '{row["TripStartDate"]}', '{row["TripStartTime"]}', 
						 '{row["TravelShift"]}', '{row["endlatlng"]}', '{row["TripEndDate"]}', '{row["TripEndTime"]}', 
						 '{row["Kms_driven"]}', '{row["CONCAT(TIME_FORMAT(SEC_TO_TIME(ds.totalruntime*60),'%H:%i'))"]}', '{row["maxsp_count"]}', '{row["maxsp"]}', 
						 '{row["AvgSpeed"]}', '{row["maxsp_loc"]}', '{row["maxsp_time"]}', '{row["cd"]}', '{row["resttime"]}', 
						 '{row["totalstops"]}', '{row["NightViol"]}', '{row["NightRunTime"]}', '{row["NightDistance"]}', 
						 '{row["nd_startlatlng"]}', '{row["nd_endlatlng"]}','{row["md"]}', '{row["harshbraking_count"]}', '{row["harshBraking"]}', 
						 '{row["harshbraking_loc"]}', '{row["harshaccln_Count"]}', '{row["harshaccln_value"]}', '{row["harshaccln_loc"]}', 
						 '{row["TripId"]}', '{row["VehicleUsedFor"]}', '{row["Fix Slab"]}'
						);";
					   res = dbx.executeNonQuery(query);					 
				}
				return res;
			}
			catch (Exception ex)
			{
				// log ex.Message if required
				res = 0;
			}
				return res;			  
		}
		public DataTable GetVehicleReminderByTransporter()
        {
            //Modified by suvarna on 1/1/2021 to fetch data only for active transporters.
            string query = "select distinct r.VehicleId,r.RemainderItemId,m.Item,r.DueDate,t.Name,t.EmailId,a.email from remainder r " +
                           " join vehicleinfo i on i.VehicleId=r.VehicleId " +
                           " join remainderitemmaster m on m.Id=r.RemainderItemId " +
                           " left join transporterinfo t on t.TransporterId=i.Transporter " +
                           " join vehiclesgroupsmap v on v.VehicleId=r.VehicleId " +
                           " join accountgroups a on a.GroupId=v.GroupId " +
                           " join accounts s on s.ID=a.AccountId " +
                           " where ((s.globalaccountid=53 and v.GroupId=9) or s.globalaccountid!=53) and s.globalaccountid not in (3717,3891,4755) and ((m.Id=123 and DATE_SUB(DATE_ADD(r.`DueDate` , INTERVAL 1 YEAR),"
                           + "INTERVAL 30 DAY)<=?) or (m.Id !=123 and DATE_SUB(r.`DueDate` , INTERVAL r.`RemaindBefore` DAY)<=?)) and t.Active=1  " +
                           " group by r.VehicleId,r.id " +
                           " order by t.Name,m.Item";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Date", formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff())));
            lParameter.Add("Date1", formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff())));
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }
        public DataTable GetDriverLicenceRemindByTransporter()
