        }

        public DataTable GetVehicleNotAvailFotTotalGaz()
        {
            string query = "select g.VehicleId,v.*,t.Name as TransName,t.TransNumber,d.Name as Driver,a.Serverts,d.*," +
                           " MAX(CASE WHEN rv.RemainderItemId=123 THEN rv.DueDate ELSE NULL END) as VettingDate," +
                           " MAX(CASE WHEN rv.RemainderItemId=123 THEN rv.Amount ELSE NULL END) as VettingRatings," +
                           " MAX(CASE WHEN rv.RemainderItemId=120 THEN rv.DueDate ELSE NULL END) as PESOLicenseValid," +
                           " MAX(CASE WHEN rv.RemainderItemId=120 THEN rv.DocNo ELSE NULL END) as PESOLicense," +
                           " MAX(CASE WHEN rv.RemainderItemId=26 THEN rv.DueDate ELSE NULL END) as RTOFitnessDate," +
                           " MAX(CASE WHEN rv.RemainderItemId=121 THEN rv.DueDate ELSE NULL END) as TankHydroValid," +
                           " MAX(CASE WHEN rv.RemainderItemId=122 THEN rv.DueDate ELSE NULL END) as SaftyValve," +
                           " MAX(CASE WHEN rv.RemainderItemId=98 THEN rv.DueDate ELSE NULL END) as HalfYearlyDue," +
                           " MAX(CASE WHEN rv.RemainderItemId=2 THEN rv.DueDate ELSE NULL END) as InsuranceValid," +
                           " MAX(CASE WHEN rv.RemainderItemId=124 THEN rv.DueDate ELSE NULL END) as PermitValidity," +
                           " MAX(CASE WHEN rv.RemainderItemId=102 THEN rv.DueDate ELSE NULL END) as PLIValidity," +
                           " MAX(CASE WHEN rv.RemainderItemId=101 THEN rv.DueDate ELSE NULL END) as CLLValidity," +
                           " MAX(CASE WHEN rv.RemainderItemId=125 THEN rv.DueDate ELSE NULL END) as FireGunValidity," +
                           " MAX(CASE WHEN rv.RemainderItemId=103 THEN rv.DueDate ELSE NULL END) as PUCValidity," +
                           " MAX(CASE WHEN rv.RemainderItemId=173 THEN rv.DueDate ELSE NULL END) as RearViewMirror," +
                           " MAX(CASE WHEN rv.RemainderItemId=170 THEN rv.DueDate ELSE NULL END) as BrakeValue " +
                           " from vehiclesgroupsmap g" +
                           " join vehicles l on l.VehicleID=g.VehicleId and l.AccountID=9 " +
                           " join lastaccess a on a.Truckid=g.VehicleId and l.AccountID=9 " +
                           " left join vehicleinfo v on g.VehicleId=v.VehicleId and g.GroupId=9" +
                           " left join remainder rv on rv.VehicleId=v.VehicleId " +
                           " left join transporterinfo t on t.TransporterId=v.Transporter " +
                           " left join driverinfo d on d.AssignedVehicleId=v.VehicleId " +
                           " where g.GroupId=9" +
                           " group by v.VehicleId" +
                           " having " +
                           " (" +
                           " (v.MarkersName='' or v.MarkersName is NULL) OR" +
                           " (v.TypeOfBody='' or v.TypeOfBody is NULL) OR" +
                           " (v.YearOfManufacturer='' or v.YearOfManufacturer is NULL) OR" +
                           " (v.Transporter='' or v.Transporter is NULL) OR" +
                           " (v.Capacity='' or v.Capacity is NULL) OR" +
                           " (v.IsContract='' or v.IsContract is NULL) OR" +
                           " ((v.ContractFrom='' or v.ContractFrom is NULL) and v.IsContract='YES') OR" +
                           " ((v.TankManfDate='' or v.TankManfDate is NULL) and v.TypeOfVehicle='Bulk') OR" +
                           " (v.VehRegDate='' or v.VehRegDate is NULL) OR" +
                           " (v.TypeOfVehicle='' or v.TypeOfVehicle is NULL) OR" +
                           " (d.DOB is NULL) OR" +
                           " (d.LicenceNo='' or d.LicenceNo is NULL) OR" +
                           " (d.HazardousLicExpDate is NULL) OR" +
                           " (d.DDTExpiryDate is NULL) OR" +
                           " (d.DDTGrade='' or d.DDTGrade is NULL) OR" +
                           " (d.MediExpDate is NULL) OR" +
                           " (d.DrivingExp='' or d.DrivingExp is NULL) OR" +
                           " (d.DriverLanguagePreference='' or d.DriverLanguagePreference is NULL) OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=123 THEN rv.DueDate ELSE NULL END) is NULL) OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=120 THEN rv.DueDate ELSE NULL END) is NULL and v.TypeOfVehicle='Bulk') OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=26 THEN rv.DueDate ELSE NULL END) is NULL) OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=121 THEN rv.DueDate ELSE NULL END) is NULL and v.TypeOfVehicle='Bulk') OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=122 THEN rv.DueDate ELSE NULL END) is NULL and v.TypeOfVehicle='Bulk') OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=2 THEN rv.DueDate ELSE NULL END) is NULL) OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=124 THEN rv.DueDate ELSE NULL END) is NULL) OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=124 THEN rv.DueDate ELSE NULL END) is NULL) OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=102 THEN rv.DueDate ELSE NULL END) is NULL and v.TypeOfVehicle='Bulk') OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=101 THEN rv.DueDate ELSE NULL END) is NULL and v.TypeOfVehicle='Bulk') OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=125 THEN rv.DueDate ELSE NULL END) is NULL) OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=103 THEN rv.DueDate ELSE NULL END) is NULL) OR" +
                           " (MAX(CASE WHEN rv.RemainderItemId=170 THEN rv.DueDate ELSE NULL END) is NULL and v.TypeOfVehicle='Bulk')" +
                           " )";
            return dbx.executeQuery(query.ToString()).Tables[0];
        }


        public DataTable STL_GetCheckListHistory(string vehicleId, string ruleId)
        {
            string query = "select w.RuleId,w.`Status`,w.`Comment`,w.image_link,s.datetime,s.username,u.`level`,u.plant from stl_workflow s " +
                           " join stl_workflowchecks w on w.workflowId=s.workflowId  " +
                           " join stl_users u on u.username=s.username " +
                           " and s.vehicleId='" + vehicleId + "' and w.RuleId='" + ruleId + "' order by s.datetime desc limit 3";
            return dbx.executeQuery(query.ToString()).Tables[0];
        }
        public DataTable STL_GetAllCommentsImages(string ruleId, string workflowid)
        {
            string query = "Select a.`Status`,a.`Comment`,a.image_link,GROUP_CONCAT(m.image_link) as moreimg,a.EditId,a.username,a.datetime,u.`level`,u.plant from " +
                           " (select c.`Status`,c.`Comment`,c.image_link,0 as EditId,w.username,w.datetime from stl_workflowchecks c" +
                           " join stl_workflow w on w.workflowId=c.workflowId and w.workflowId='" + workflowid + "'" +
                           " where c.workflowId='" + workflowid + "' and c.RuleId='" + ruleId + "'" +
                           " group by c.RuleId" +
                           " union all" +
                           " select c.`Status`,c.`Comment`,c.image_link,c.EditId,w.username,w.timestamp from stl_editedworkflowchecks c" +
                           " join stl_editedworkflow w on w.EditId=c.EditId and w.workflowId='" + workflowid + "'" +
                           " where c.workflowId='" + workflowid + "' and c.RuleId='" + ruleId + "') a" +
                           " left join stl_moreworkflowimages m on m.EditId=a.EditId and m.RuleId='" + ruleId + "' and m.workflowid='" + workflowid + "'" +
                           " join stl_users u on u.username=a.username " +
                           " group by a.EditId order by a.datetime desc";
            return dbx.executeQuery(query.ToString()).Tables[0];
        }

        public string InsertDriverNotifications(string DriverId, string Subject, string Info, int Priority = 0)
        {
            try
            {
                string currenttime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
                string query = "Insert into drivernotification(Driverid,Subject,Info,Date,Priority) values(?,?,?,?,?)";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("DriverId", DriverId);
                lParameter.Add("Subject", Subject);
                lParameter.Add("Info", Info);
                lParameter.Add("currenttime", currenttime);
                lParameter.Add("Priority", Priority);
                int res = dbx.executeNonQuery(query, lParameter);
                return res.ToString();
            }
            catch { return "-1"; }
        }

        public bool GetPanicPressed(string vehicleId, string fromDate, string toDate)
        {
            string temp = GetDateTablePartitions(Convert.ToDateTime(fromDate), Convert.ToDateTime(toDate), partions);
            StringBuilder query = new StringBuilder();
            query.Append("select count(vehicleId) ");
            query.Append("from panic PARTITION(" + temp + ") where type='panic' and vehicleId='" + vehicleId + "' ");
            query.Append("and alertTimeStamp >='" + fromDate + "' and   alertTimeStamp < '" + toDate + "'");
            Object obj = dbx.executeScalar(query.ToString());
            if (Convert.ToInt32(obj) > 0)
                return true;

            return false;

        }

