        public void getgeoRegionViolations(int grpid, DateTime toDate, string duration = "")
        {
            string vehicleId = string.Empty;
            if (string.IsNullOrEmpty(duration))
                duration = "1440";//24 Hours
            DateTime fromDate = toDate.AddMinutes(-Convert.ToInt32(duration));
            string fromDateStr = formatDBDate(fromDate);
            string toDateStr = formatDBDate(toDate);
            int fhour = fromDate.Hour;
            int thour = toDate.Hour;
            if ((fhour == 5) && (thour == 7))//For delay packets, we are running this for last 24 hrs @ this period
            {
                fromDateStr = formatDBDate(toDate.AddHours(-24)).ToString();
            }

            string query = string.Empty;
            double RSZSpeed = 0.0;
            DateTime RSZSpeedTS = new DateTime();
            ArrayList overSpeedList = new ArrayList();
            query = "select vehicleid from vehiclesgroupsmap where groupid = " + grpid;
            DataSet dsVehicles = dbx.executeQuery(query);
            DataTable table = dsVehicles.Tables[0];
            double speedLimit = 1000;
            if (table.Rows.Count == 0)
                return;
            for (int i = 0; i < table.Rows.Count; i++)
            {
                vehicleId = Convert.ToString(table.Rows[i][0]);
                query = "select vehicleid, intimestamp, locationstr,outtimestamp, substring_index(locationstr,'-',-1), outtimedone from vehicleinplant where locationStr like '%JRM%'"
                            + " and vehicleid = " + "'" + vehicleId + "'"
                            + " and intimestamp >= " + "'" + fromDateStr + "'" + " and intimestamp <= " + "'" + toDateStr + "'";
                DataSet dsVehicleinPlant = dbx.executeQuery(query);
                DataTable table1 = dsVehicleinPlant.Tables[0];
                if (table1.Rows.Count == 0)
                    continue;
                for (int j = 0; j < table1.Rows.Count; j++)
                {
                    try
                    {
                        string truckId = Convert.ToString(table1.Rows[j][0]);
                        DateTime t1 = Convert.ToDateTime(table1.Rows[j][1]);
                        string locationStr = Convert.ToString(table1.Rows[j][2]);
                        string speedLimitStr = Convert.ToString(table1.Rows[j][4]);
                        speedLimit = Double.Parse(speedLimitStr);
                        int outtimedone = Convert.ToInt16(table1.Rows[j][5]);
                        DateTime t2 = t1.AddMinutes(2); // vehicle crosses the geofence in approximately 2 min
                        if (outtimedone == 1)
                            t2 = Convert.ToDateTime(table1.Rows[j][3]);//if outtime is recorded in vehicleinplant read the outime


                        DataSet dsSpeedviolations = GetPositionData(truckId, formatDBDate(t1), formatDBDate(t2));
                        // Get the data before entering the jRM zone to get an avg speed b4 entering the jRM zone  and 1 minute aftr entering the zone 
                        // to capture the reaction time. it is assumed that it takes 1 min for the jRM spee msg to play
                        DataSet dsSpeedviolationsB4 = GetPositionData(truckId, formatDBDate(t1.AddMinutes(-2)), formatDBDate(t1));
                        DataSet dsSpeedviolationsAfter = GetPositionData(truckId, formatDBDate(t1.AddMinutes(1)), formatDBDate(t1.AddMinutes(3))); // assuming that after 1 minute the audio JRM is played in cabin
                        DataTable tableB4 = dsSpeedviolationsB4.Tables[0];
                        DataTable tableAfter = dsSpeedviolationsAfter.Tables[0];
                        DataTable table2 = dsSpeedviolations.Tables[0];
                        if (table2.Rows.Count == 0)
                            continue;
                        int violationCnt = 0;
                        double maxSpeed = 0.0;
                        string maxSpeedStr = string.Empty;
                        DateTime maxSpeedTS = new DateTime();
                        string latitude = "0.0";
                        string longitude = "0.0";
                        double avgJRMSpeed = 0.0;
                        double avgSpeedB4JRM = 0.0;
                        double initSpeedInJRM = 0.0;
                        int reactTime = 0;
                        for (int k = 0; k < table2.Rows.Count; k++)
                        {
                            string violatedtruckId = Convert.ToString(table2.Rows[k][1]);
                            RSZSpeedTS = Convert.ToDateTime(table2.Rows[k][2]);
                            RSZSpeed = Convert.ToDouble(table2.Rows[k][7]);
                            avgJRMSpeed += RSZSpeed;
                            if (RSZSpeed > speedLimit)
                            {
                                violationCnt += 1;
                                if (RSZSpeed > maxSpeed)
                                {
                                    maxSpeed = RSZSpeed;
                                    maxSpeedTS = RSZSpeedTS;
                                    latitude = table2.Rows[k][5].ToString();
                                    longitude = table2.Rows[k][6].ToString();
                                }

                            }
                        }
                        if (violationCnt > 0)
                        {
                            maxSpeedStr = "Max Speed - " + Convert.ToString(maxSpeed);
                            try
                            {
                                storeVehicleViolations(truckId, "", "JRM OVERSPEEDING", formatDBDate(maxSpeedTS), violationCnt, maxSpeedStr, locationStr, latitude, longitude);
                            }
                            catch
                            { }
                        }
                        try
                        {
                            // Get the ID of the JRM spot and also the driver id to store
                            query = "select id from plantgeolocations where locstr = '" + locationStr + "' and " + latitude + " between minlatitude and maxlatitude and " + longitude +
                                " between minlongitude and maxlongitude";
                            Object idObj = dbx.executeScalar(query);
                            int jrmId = 0;
                            if (idObj != null)
                            {
                                if (!(idObj.Equals(System.DBNull.Value)))
                                {
                                    jrmId = Int16.Parse(idObj.ToString());  // id of the JRM spot
                                }
                            }
                            string driverData = getdrivername(truckId);  // returns name,id,starttime
                            string[] drvDataSplit = driverData.Split(',');
                            string driverId = String.Empty;
                            if (drvDataSplit.Length > 0)
                                driverId = drvDataSplit[1];

                            avgJRMSpeed = avgJRMSpeed / table2.Rows.Count;  // take the average speed inside the zone
                                                                            // Now to check the reaction time. Take the avg speed before entering the zone 2 mins b4. And 2 mintues after 1 min of entering the zone
                                                                            // Record both b4 and after speed and then also record if it has decreased.
                            for (int k = 0; k < tableB4.Rows.Count; k++)
                            {
                                RSZSpeed = Convert.ToDouble(table2.Rows[k][7]);
                                avgSpeedB4JRM += RSZSpeed;
                            }
                            avgSpeedB4JRM = avgSpeedB4JRM / tableB4.Rows.Count;   // avg speed b4 entering the zone
                            for (int k = 0; k < tableAfter.Rows.Count; k++)
                            {
                                RSZSpeed = Convert.ToDouble(table2.Rows[k][7]);
                                initSpeedInJRM += RSZSpeed;
                            }
                            initSpeedInJRM = initSpeedInJRM / tableAfter.Rows.Count;

                            // Store the vehicles performance in the table
                            string reduced = String.Empty;
                            reduced = (avgSpeedB4JRM - initSpeedInJRM) > 5 ? "yes" : "no";
                            if (avgJRMSpeed < speedLimit)  // if already below limit
                                reduced = "yes";
                            query = "insert into jrmstats(vehicleid,timestamp,location,avgspdin,spdb4enter,spdafter,reduced,jrmid,driverid) values('" + truckId + "','" + formatDBDate(t1) + "','" + locationStr +
                                "'," + avgJRMSpeed + "," + avgSpeedB4JRM + "," + initSpeedInJRM + ",'" + reduced + "'," + jrmId + ",'" + driverId + "')";
                            dbx.executeNonQuery(query);
                        }
                        catch { }
                    }
                    catch { }
                }
            }
            return;
        }

