        public DataTable STL_GetTodaysReport(string username, string date)
        {
            DataTable dt = STL_GetUserDetails(username);
            string levelno = string.Empty;
            string plant = string.Empty;
            string AccountId = "9";
            if (dt.Rows.Count > 0)
            {
                levelno = dt.Rows[0]["levelno"].ToString();
                plant = dt.Rows[0]["plant"].ToString();
                AccountId = dt.Rows[0]["AccountId"].ToString();
            }
            string query = "select username,`level`,plant,levelno,Sum(Allowed)+Sum(Blocked) Total,Sum(Allowed) as Allowed,Sum(Blocked) as Blocked from" +
                          " (select u.username,u.`level`,u.plant,u.levelno,0 as Allowed,count(1) as Blocked from stl_workflow w" +
                          " left join vehicleinfo v on v.VehicleId=w.vehicleId" +
                          " left join transporterinfo t on t.TransporterId=v.Transporter" +
                          " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                          " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId)" +
                          " join stl_users u on IFNULL(a.username,IFNULL(e.username,w.username))=u.username" +
                          " where w.AccountId='" + AccountId + "' and" +
                          " ((w.`Action`='Block' and e.`Action` is NULL and a.`Action` is NULL)" +
                          " or" +
                          " (e.`Action`='Block' and a.`Action` is NULL)" +
                          " or" +
                          " (a.`Action`='Block')) and w.datetime>='" + date + " 00:00' and w.datetime<='" + date + " 23:59'" +
                          " group by u.username" +
                          " union " +
                          " select u.username,u.`level`,u.plant,u.levelno,count(1) as Allowed,0 as Blocked from stl_workflow w" +
                          " left join vehicleinfo v on v.VehicleId=w.vehicleId" +
                          " left join transporterinfo t on t.TransporterId=v.Transporter" +
                          " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                          " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId)" +
                          " join stl_users u on IFNULL(a.username,IFNULL(e.username,w.username))=u.username" +
                          " where w.AccountId='" + AccountId + "' and" +
                          " ((w.`Action`='Allow' and e.`Action` is NULL and a.`Action` is NULL)" +
                          " or" +
                          " (e.`Action`='Allow' and a.`Action` is NULL)" +
                          " or" +
                          " (a.`Action`='Allow')) and w.datetime>='" + date + " 00:00' and w.datetime<='" + date + " 23:59'" +
                          " group by u.username) temp where levelno<='" + levelno + "' and plant='" + plant + "'" +
                          " group by username" +
                          " order by levelno,username";
            return dbx.executeQuery(query.ToString()).Tables[0];
        }


