        //for driver custom notification
        public int AddDriverNotifications(string DriverId, string Subject, string Detail, string sessionid = "", string Priority = "Low")
        {
            string date = formatDBDate(System.DateTime.Now);
            string query = "";
            int rows = 0;
            int priority = 0;
            if (Priority == "High")
                priority = 1;
            var lParameter = new Dictionary<string, object>();
            if (!DriverId.Contains(",") && DriverId != "ALL")
            {
                query = "INSERT INTO `drivernotification` (`Driverid`, `Subject`, `Info`, `Date`, `Isnotified`, `NotifiedTime`,`Priority`) VALUES "
                    + "(?, ?, ?, ?, 0, '0000-00-00 00:00:00',?);";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Driverid", DriverId);
                lParameter.Add("Subject", Subject);
                lParameter.Add("Info", Detail);
                lParameter.Add("Date", date);
                lParameter.Add("Priority", priority);
                rows = dbx.executeNonQuery(query, lParameter);
            }
            else if (DriverId.Contains(",") && DriverId != "ALL")
            {
                string[] drivers = DriverId.Split(',');
                for (int i = 0; i < drivers.Length; i++)
                {
                    query = "INSERT INTO `drivernotification` (`Driverid`, `Subject`, `Info`, `Date`, `Isnotified`, `NotifiedTime`,`Priority`) VALUES "
                        + "(?, ?, ?, ?, 0, '0000-00-00 00:00:00',?);";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Driverid", drivers[i]);
                    lParameter.Add("Subject", Subject);
                    lParameter.Add("Info", Detail);
                    lParameter.Add("Date", date);
                    lParameter.Add("Priority", priority);
                    rows += dbx.executeNonQuery(query, lParameter);
                }
            }
            else if (DriverId == "ALL" && !string.IsNullOrEmpty(sessionid))
            {
                DataSet ds = GetDriversBySessionId(sessionid);
                for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
                {
                    query = "INSERT INTO `drivernotification` (`Driverid`, `Subject`, `Info`, `Date`, `Isnotified`, `NotifiedTime`,`Priority`) VALUES "
                        + "(?, ?, ?, ?, 0, '0000-00-00 00:00:00',?);";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Driverid", ds.Tables[0].Rows[i]["DriverId"].ToString());
                    lParameter.Add("Subject", Subject);
                    lParameter.Add("Info", Detail);
                    lParameter.Add("Date", date);
                    lParameter.Add("Priority", priority);
                    rows += dbx.executeNonQuery(query, lParameter);
                }
            }
            return rows;
        }

        private DataSet GetDriversBySessionId(string sessionid)
        {
            DataTable dt = GetVehiclesBySessionId(sessionid).Tables[0];
            string vehls = string.Empty;
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                vehls += "'" + dt.Rows[i]["VehicleId"].ToString() + "',";
            }
            vehls += "'-'";
            string query = "select * from driverinfo where AssignedVehicleId in (" + vehls + ")";
            return dbx.executeQuery(query);
        }

