                return dbx.executeQuery(query, lParameter).Tables[0];
            }
        }

        //for driver custom notification
        public int AddTransporterNotifications(string loginId, string Subject, string Detail, Int16 priority = 0)
        {
            string date = formatDBDate(System.DateTime.Now);
            string query = "";
            int rows = 0;
            loginId = loginId.Replace("'", "");
            var lParameter = new Dictionary<string, object>();
            if (!loginId.Contains(",") && loginId != "ALL")
            {
                query = "INSERT INTO `transporternotification` (`LoginId`, `Subject`, `Info`, `Datetime`, `Isnotified`, `NotifiedTime`, `Priority`) VALUES "
                      + "(?, ?, ?,?, 0, '0000-00-00 00:00:00',?);";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("loginId", loginId);
                lParameter.Add("Subject", Subject);
                lParameter.Add("Detail", Detail);
                lParameter.Add("date", date);
                lParameter.Add("priority", priority);
                rows = dbx.executeNonQuery(query, lParameter);
            }
            else if (loginId.Contains(",") && loginId != "ALL")
            {
                string[] logins = loginId.Split(',');
                for (int i = 0; i < logins.Length; i++)
                {
                    query = "INSERT INTO `transporternotification` (`LoginId`, `Subject`, `Info`, `Datetime`, `Isnotified`, `NotifiedTime`, `Priority`) VALUES "
                          + "(?, ?, ?,?, 0, '0000-00-00 00:00:00',?);";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("loginId", logins[i]);
                    lParameter.Add("Subject", Subject);
                    lParameter.Add("Detail", Detail);
                    lParameter.Add("date", date);
                    lParameter.Add("priority", priority);
                    rows += dbx.executeNonQuery(query, lParameter);
                }
            }
            else if (loginId == "ALL")
            {
                query = "select d.login from users d" +
                " where d.AccountId=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("AccountId", 9);
                DataSet ds = dbx.executeQuery(query, lParameter);
                for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
                {
                    query = "INSERT INTO `transporternotification` (`LoginId`, `Subject`, `Info`, `Datetime`, `Isnotified`, `NotifiedTime`, `Priority`) VALUES "
                          + "(?, ?, ?,?, 0, '0000-00-00 00:00:00',?);";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("loginId", ds.Tables[0].Rows[i][0]);
                    lParameter.Add("Subject", Subject);
                    lParameter.Add("Detail", Detail);
                    lParameter.Add("date", date);
                    lParameter.Add("priority", priority);
                    rows += dbx.executeNonQuery(query, lParameter);
                }
            }
            return rows;
        }
