        public DataTable STL_GetSummaryData(string IsPlantBase, string Plant, string StartDate, string ToDate, int accountid, string workflowtype, string Vehicles, string sessionid)
        {
            int groupid = getGroupId(sessionid);
            String query = "select Name,Sum(w.Allowed) as Allowed,Sum(w.Blocked) as Blocked from (" +
                           " select u.plant as Name,count(w.`Action`) as Allowed,0 as Blocked,w.workflowtype" +
                           " from stl_workflow w  " +
                           " join stl_users u on u.username=w.username and w.AccountId=? and w.datetime>=? and w.datetime<=?" +
                           " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                           " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId)" +
                           " where w.workflowtype=? and ((w.`Action`='Allow' and e.`Action` is NULL and a.`Action` is NULL) or (e.`Action`='Allow' and a.`Action` is NULL) or (a.`Action`='Allow')) ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("accountid", accountid);
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("workflowtype", workflowtype);
            if (Vehicles != "All")
            {
                if (Vehicles == "Contract")
                {
                    query += " and w.vehicleId in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid1", accountid);
                }
                else if (Vehicles == "Ex-Plant")
                {
                    query += " and w.vehicleId not in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid1", accountid);
                }
            }
            query += " group by u.plant " +
                       " union " +
                       " select u.plant as Name,0 as Allowed,count(1) as Blocked,w.workflowtype" +
                       " from stl_workflow w  " +
                       " join stl_users u on u.username=w.username and w.AccountId=? and w.datetime>=? and w.datetime<=?" +
                       " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                       " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId)" +
                       " where w.workflowtype=? and ((w.`Action`='Block' and e.`Action` is NULL and a.`Action` is NULL) or (e.`Action`='Block' and a.`Action` is NULL) or (a.`Action`='Block'))";
            lParameter.Add("accountid2", accountid);
            lParameter.Add("StartDate1", StartDate);
            lParameter.Add("ToDate1", ToDate);
            lParameter.Add("workflowtype1", workflowtype);
            if (Vehicles != "All")
            {
                if (Vehicles == "Contract")
                {
                    query += " and w.vehicleId in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid3", accountid);
                }
                else if (Vehicles == "Ex-Plant")
                {
                    query += " and w.vehicleId not in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid3", accountid);
                }
            }
            query += " group by u.plant ) w group by w.Name";
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            if (IsPlantBase == "true")
            {
                DataView dv = new DataView(dt);
                dv.RowFilter = "Name='" + Plant + "'";
                return dv.ToTable();
            }
            return dt;
        }
        public DataTable STL_GetCategoryWiseSummary(string StartDate, string ToDate, string Status, int accountid, string Plant, string Category, string Transporter, string vehicles, string workflowtype = "0")
        {

            String query = "select r.Category,count(1) as cnt from stl_workflow w" +
                           " join stl_users u on u.username=w.username and w.AccountId=? and w.datetime>=? and w.datetime<=?" +
                           " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                           " left join stl_users es on es.username=e.username " +
                           " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId) " +
                           " left join vehicleinfo v on v.VehicleId=w.vehicleId " +
                           " left join stl_workflowchecks c on c.workflowId=w.workflowId and c.`Status`='NO'" +
                           " left join stl_editedworkflowchecks ec on ec.workflowId=e.workflowId and ec.`Status`='NO'" +
                           " left join stl_checklist r on r.RuleId=c.RuleId or r.RuleId=ec.RuleId" +
                           " where w.AccountId=? and w.workflowtype=?" +
                           " and (((e.`Action` is Null and w.`Action`='Block') or (e.`Action`='Block' and a.`Action` is NULL) ) and (a.`Action`='Block' or a.`Action` is NULL))";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("accountid", accountid);
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("accountid1", accountid);
            lParameter.Add("workflowtype", workflowtype);
            if (Plant != "All")
            {
                query += " and u.plant=?";
                lParameter.Add("Plant", Plant);
            }
            if (Category != "All")
            {
                query += " and r.Category=?";
                lParameter.Add("Category", Category);
            }
            if (Transporter != "All")
            {
                query += " and v.Transporter=?";
                lParameter.Add("Transporter", Transporter);
            }
            if (vehicles != "All")
            {
                if (vehicles == "Contract")
                {
                    query += " and w.vehicleId in (select VehicleID from vehicles where AccountID=? )";
                    lParameter.Add("accountid2", accountid);
                }
                else if (vehicles == "Ex-Plant")
                {
                    query += " and w.vehicleId not in (select VehicleID from vehicles where AccountID=? )";
                    lParameter.Add("accountid2", accountid);
                }
            }
            query += " group by r.Category";

            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable STL_GetTransporterWiseSummary(string StartDate, string ToDate, string Status, int accountid, string Plant, string Category, string Transporter, string vehicles, string workflowtype = "0")
        {
            String query = "select IFNULL(t.Name,'Others') as Name,t.ShortName,count(1) as cnt from stl_workflow w" +
                           " join stl_users u on u.username=w.username" +
                           " left join vehicleinfo v on v.VehicleId=w.vehicleId" +
                           " left join transporterinfo t on t.TransporterId=v.Transporter" +
                           " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                           " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId)" +
                           " where w.AccountId=? and w.workflowtype=? and" +
                           " ((w.`Action`='Block' and e.`Action` is NULL and a.`Action` is NULL)" +
                           " or" +
                           " (e.`Action`='Block' and a.`Action` is NULL)" +
                           " or" +
                           " (a.`Action`='Block')) and w.datetime>=? and w.datetime<=? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("accountid", accountid);
            lParameter.Add("workflowtype", workflowtype);
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            if (Plant != "All")
            {
                query += " and u.plant=?";
                lParameter.Add("Plant", Plant);
            }
            if (Category != "All")
            {
                query += " and (w.workflowId in (select cd.workflowid from stl_workflowchecks cd join stl_checklist cl on cl.RuleId=cd.RuleId where cl.Category=? and cd.`Status`='NO')" +
                      " or w.workflowId in (select ed.workflowid from stl_editedworkflowchecks ed join stl_checklist el on el.RuleId=ed.RuleId where el.Category=? and ed.`Status`='NO'))";
                lParameter.Add("Category", Category);
                lParameter.Add("Category1", Category);
            }
            if (Transporter != "All")
            {
                query += " and v.Transporter=?";
                lParameter.Add("Transporter", Transporter);
            }
            if (vehicles != "All")
            {
                if (vehicles == "Contract")
                {
                    query += " and w.vehicleId in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid1", accountid);
                }
                else if (vehicles == "Ex-Plant")
                {
                    query += " and w.vehicleId not in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid1", accountid);
                }
            }
            query += " group by t.TransporterId";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
