            //               " select distinct w.workflowId,a.vehicleId,u.plant,u.`level`,a.datetime,w.username,w.`Action`,w.`Comment`,a.transporter,a.AccountId from stl_workflowaction w" +
            //               " join stl_users u on u.username=w.username" +
            //               " join stl_workflow a on a.workflowid=w.workflowId" +
            //               " where a.AccountId=? and a.workflowtype=? and a.datetime>=? and a.datetime<=? " +
            //               " ) a" +
            //               " left join vehicleinfo v on v.VehicleId=a.vehicleId where  a.AccountId=? ";
            String query = "select distinct CONCAT(a.username,'(',a.`level`,')') as Name,count(1) as cnt from (" +
                            " select w.workflowId,w.vehicleId,u.plant,u.`level`,w.datetime,w.username,w.`Action`,w.`Comment`,w.transporter, w.AccountId from stl_workflow w" +
                            " join stl_users u on u.username=w.username" +
                           " where w.AccountId=? and w.workflowtype=? and w.datetime>=? and w.datetime<=? " +
                           " ) a" +
                           " left join vehicleinfo v on v.VehicleId=a.vehicleId where  a.AccountId=? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("accountid", accountid);
            lParameter.Add("workflowtype", workflowtype);
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            //lParameter.Add("accountid1", accountid);
            //lParameter.Add("workflowtype1", workflowtype);
            //lParameter.Add("StartDate1", StartDate);
            //lParameter.Add("ToDate1", ToDate);
            //lParameter.Add("accountid2", accountid);
            //lParameter.Add("workflowtype2", workflowtype);
            //lParameter.Add("StartDate2", StartDate);
            //lParameter.Add("ToDate2", ToDate);
            lParameter.Add("accountid3", accountid);
            if (Plant != "All")
            {
                query += " and a.plant=?";
                lParameter.Add("Plant", Plant);
            }
            if (Transporter != "All")
            {
                query += " and v.Transporter=?";
                lParameter.Add("Transporter", Transporter);
            }
            if (vehicles != "All")
            {
                if (vehicles == "Contract")
                {
                    query += " and a.vehicleId in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid4", accountid);
                }
                else if (vehicles == "Ex-Plant")
                {
                    query += " and a.vehicleId not in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid4", accountid);
                }
            }
            query += " group by a.`username`";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public int STL_GetTotalNoOfInspections(string StartDate, string ToDate, string Status, int accountid, string Plant, string Category, string Transporter, string vehicles)
        {
            try
            {
                String query = "select count(1) as cnt from stl_workflow w" +
                               " join stl_users u on u.username=w.username" +
                               " left join vehicleinfo v on v.VehicleId=w.vehicleId" +
                               " left join transporterinfo t on t.TransporterId=v.Transporter" +
                               " where w.AccountId=? and " +
                               " w.datetime>=? and w.datetime<=? ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("accountid", accountid);
                lParameter.Add("StartDate", StartDate);
                lParameter.Add("ToDate", ToDate);
                if (Plant != "All")
                {
                    query += " and u.plant=?";
                    lParameter.Add("Plant", Plant);
                }
                if (Transporter != "All")
                {
                    query += " and v.Transporter=?";
                    lParameter.Add("Transporter", Transporter);

                }
                if (vehicles != "All")
                {
                    if (vehicles == "Contract")
                    {
                        query += " and w.vehicleId in (select VehicleID from vehicles where AccountID=?)";
                        lParameter.Add("AccountID", accountid);
                    }
                    else if (vehicles == "Ex-Plant")
                    {
                        query += " and w.vehicleId not in (select VehicleID from vehicles where AccountID=?)";
                        lParameter.Add("AccountID_Ex", accountid);
                    }
                }
                return Convert.ToInt32(dbx.executeScalar(query, lParameter).ToString());
            }
            catch
            {
                return 0;
            }
        }


        public DataTable STL_GetInspectionData(string IsPlantBase, string Plant, string StartDate, string ToDate, int groupid, string workflowid, string workflowtype, string Vehicles, string SessionId = "")
        {
            //Modified by suvarna on 02/3/2021 to filter the report based on login vehicles
            string login = getUserId(SessionId);//Modified by suvarna on 10/12/2021 to filter the report based on login vehicles including market vehicles
            string transid = getTransporterIdByLogin(login);
            int accountid = GetAccountIdByGroupId(groupid);
            String query = "select distinct w.workflowId,w.vehicleId,w.`group`,w.datetime," +
                           " IFNULL(e.`Action`,w.`Action`) `Action`,IFNULL(e.`Comment`,w.`Comment`) as `Comment`,u.plant,w.username,u.`level`,a.`Action` as T3Action1," +
                           " a.username as T3Action2,a.`Comment` as T3ActionCom2,a.TakenOn," +
                           " e.timestamp as EditedOn,e.username as Editedby,w.InspectionId,d.Name as Driver,t.Name as Transporter,es.`level` as Editedbylevel from stl_workflow w  " +
                           " left join vehicleinfo v on v.VehicleId=w.vehicleId" +
                           " left join transporterinfo t on t.TransporterId=v.Transporter" +
                           " left join driverinfo d on d.AssignedVehicleId=w.vehicleId" +
                           " join stl_users u on u.username=w.username  and w.AccountId=? and w.datetime>=? and w.datetime<=?   " +
                           " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                           " left join stl_users es on es.username=e.username " +
                           " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId) " +
                           " where w.workflowtype=? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("accountid", accountid);
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("workflowtype", workflowtype);
            if (IsPlantBase == "true")
            {
                query += "and u.plant=?";
                lParameter.Add("Plant", Plant);
            }
            if (Vehicles != "All")
            {
                if (Vehicles == "Contract")
                {
                    query += " and w.vehicleId in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid1", accountid);
                }
                else if (Vehicles == "Ex-Plant")
                {
                    query += " and w.vehicleId not in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid1", accountid);
                }
            }
            if (transid != "0")
            {
                query += " and w.vehicleId in (Select vehicleid from vehiclesgroupsmap where groupid=?)";
                lParameter.Add("groupid", groupid);
            }

            query += " group by w.workflowId" +
                 " order by w.datetime desc";
            if (workflowid != "0")
            {
                query = "select w.workflowId,w.vehicleId,w.`group`,w.datetime," +
                           " IFNULL(e.`Action`,w.`Action`) `Action`,IFNULL(e.`Comment`,w.`Comment`) as `Comment`,u.plant,w.username,u.`level`,a.`Action` as T3Action1," +
                           " a.username as T3Action2,a.`Comment` as T3ActionCom2,a.TakenOn," +
                           " e.timestamp as EditedOn,e.username as Editedby,w.InspectionId,d.Name as Driver,t.Name as Transporter from stl_workflow w  " +
                           " join stl_users u on u.username=w.username" +
                           " left join vehicleinfo v on v.VehicleId=w.vehicleId" +
                           " left join transporterinfo t on t.TransporterId=v.Transporter" +
                           " left join driverinfo d on d.AssignedVehicleId=w.vehicleId" +
                           " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                           " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId) " +
                           " where w.workflowId=?;";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("workflowid", workflowid);

            }
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable STL_GetInspectionReportData(string StartDate, string ToDate, int accountid, string Plant, string Transporter, string Action, string Truck, string Vehicles, int groupid, string workflowtype)
        {
            //Modified by suvarna on 15/2/2021 to add location in UI stl report
            String query = "select distinct w.workflowId,w.vehicleId,w.`group`,w.datetime," +
                           " IFNULL(e.`Action`,w.`Action`) `Action`,IFNULL(e.`Comment`,w.`Comment`) as `Comment`,u.plant,w.username,u.`level`,a.`Action` as T3Action1," +
                           " a.username as T3Action2,a.`Comment` as T3ActionCom2,a.TakenOn," +
                           " e.timestamp as EditedOn,e.username as Editedby,w.InspectionId,es.`level` as Editedbylevel,ti.Name as TransName,ti.ShortName as TransShortName, w.latitude,w.longitude,w.vehicleLat,w.vehicleLong,w.IMEI from stl_workflow w  " +
                           " join stl_users u on u.username=w.username  and w.AccountId=? and w.datetime>=? and w.datetime<=?   " +
                           " left join stl_editedworkflow e on e.EditId=(select Max(a.EditId) from stl_editedworkflow a where  a.workflowid=w.workflowId)" +
                           " left join stl_users es on es.username=e.username " +
                           " left join stl_workflowaction a on a.Id=(select Max(b.Id) from stl_workflowaction b where b.workflowid=w.workflowId) " +
                           " left join vehicleinfo v on v.VehicleId=w.vehicleId " +
                           " left join transporterinfo ti on ti.TransporterId=v.Transporter " +
                           " where w.AccountId=? and w.workflowtype=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("accountid", accountid);
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("accountid1", accountid);
            lParameter.Add("workflowtype", workflowtype);
            if (Plant != "All")
            {
                query += " and u.plant=?";
                lParameter.Add("Plant", Plant);
            }
            if (Transporter != "All")
            {
                query += " and v.Transporter=?";
                lParameter.Add("Transporter", Transporter);
            }
            if (Action != "All")
            {
                query += " and (((e.`Action` is Null and w.`Action`=?) or (e.`Action`=? and a.`Action` is NULL) ) and (a.`Action`=? or a.`Action` is NULL))";
                lParameter.Add("Action", Action);
                lParameter.Add("Action1", Action);
                lParameter.Add("Action2", Action);
            }
            //if (Vehicles != "All")
            //{
            //if (Vehicles == "Contract" || Vehicles == "All")//Modified by suvarna on 24/6/2021 to show loginwise vehicles data
            if (Vehicles == "Contract")
            {
                string transid = "0";
                try
                {
                    string username = System.Web.HttpContext.Current.Session["UserName"].ToString();
                    transid = getTransporterIdByLogin(username);
                }
                catch { }
                if (transid == "0")
                {
                    query += " and w.vehicleId in (select VehicleID from vehicles where AccountID=?)";
                    lParameter.Add("accountid2", accountid);
                }
                else
                {
                    query += " and w.vehicleId in (select VehicleID from vehiclesgroupsmap where GroupId=?)";
                    lParameter.Add("groupid", groupid);
                }

            }
            else if (Vehicles == "Ex-Plant")
            {
                query += " and w.vehicleId not in (select VehicleID from vehicles where AccountID=?)";
                lParameter.Add("accountid3", accountid);
            }
            // }
            if (!string.IsNullOrEmpty(Truck))
            {
                if (Truck.ToLower() != "all")
                {
                    query += " and w.vehicleId=?";
                    lParameter.Add("Truck", Truck);
                }
            }
            query += " group by w.workflowId" +
                     " order by w.datetime desc";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetVehicleDCDataReport(string StartDate, string ToDate, int accountid, string Plant, string Customerid, string Truck)
        {
            if (ToDate == StartDate)
                ToDate = ToDate.Replace("00:00:00", "23:59:59");//Modified by suvarna on 3/12/2020 As thr was a issue in exporting 1 day data
            String query = "select c.id,c.CustomerId,i.CustomerCode,c.DCTripId,v.VehicleID,v.AddedBy,v.DateTime,v.NoofDcs," +
                           " p.Plant,i.Name,c.DCNo,c.Quantity,c.DeliveredOn,c.DeliveredQty," +
                           " d.LoadInTime,d.LoadOutTime,c.ETA,c.ReverseETA,d.UnloadInTime,d.UnloadOutTime,d.TripEndTime," +
                           " IF(c.ETA != '0000-00-00 00:00:00' AND d.LoadOutTime != '0000-00-00 00:00:00',TIMEDIFF(c.ETA,d.LoadOutTime),NULL) as ETA_Duration," +
                           " IF(d.UnloadInTime != '0000-00-00 00:00:00' AND d.LoadOutTime != '0000-00-00 00:00:00',TIMEDIFF(d.UnloadInTime,d.LoadOutTime),NULL) as Up_Duration,SEC_TO_TIME(d.up_runtime*60) as Up_RunTime,ROUND(d.up_distance,2) AS Up_Distance," +
                           " IF(d.TripEndTime != '0000-00-00 00:00:00' AND d.UnloadOutTime != '0000-00-00 00:00:00',TIMEDIFF(d.TripEndTime,d.UnloadOutTime),NULL) as Down_Duration,SEC_TO_TIME(d.down_runtime*60) as Down_RunTime,ROUND(d.down_distance,2) AS Down_Distance," +
                           " IF(c.ReverseETA != '0000-00-00 00:00:00' AND d.UnloadOutTime != '0000-00-00 00:00:00',TIMEDIFF(c.ReverseETA,d.UnloadOutTime),NULL) as RETA_Duration," +
                           " w.datetime as Load_STL_Time" +
                           " from customerdcassign c" +
                           " join vehicledctrip v on v.id=c.DCTripId" +
                           " join customerinfo i on i.CustomerId=c.CustomerId" +
                           " join plantlogin p on p.login=v.AddedBy" +
                           " left join dc_vehicletrip_summary d on d.CustDCId=c.id" +
                           " left join stl_workflow w on w.workflowid = (select max(s.workflowid) from stl_workflow s where s.vehicleid=v.VehicleID and (s.datetime>=d.LoadInTime or s.datetime>DATE_ADD(v.DateTime,INTERVAL -1 DAY)) and s.datetime<=v.DateTime)" +
                           " where v.DateTime>? and v.DateTime<? and v.AccountId=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("accountid", accountid);
            if (Plant != "All")
            {
                lParameter.Add("Plant", Plant);
                query += " and p.Plant=?";
            }
            if (Customerid != "All")
            {
                lParameter.Add("Customerid", Customerid);
                query += " and c.CustomerId=?";
            }
            if (!string.IsNullOrEmpty(Truck))
            {
                if (Truck.ToLower() != "all")
                {
                    lParameter.Add("Truck", Truck);
                    query += " and v.VehicleID=?";
                }
            }
            query += " order by v.DateTime,v.VehicleID,d.UnloadInTime asc";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        //Added By Zoya For SHV
        public DataTable GetVehicleETADataReport(string StartDate, string ToDate, int accountid, string sessionId, string Plant, string Customerid, string Truck)
        {
            string groupid = getGroupId(sessionId).ToString();
            if (ToDate == StartDate)
                ToDate = ToDate.Replace("00:00:00", "23:59:59");//Modified by Zoya on 19/10/2023 for SHV
            string query = "SELECT distinct c.DCNo AS FO_Number, v.DateTime AS FO_Date, v.VehicleID AS Vehicle_Number, p.Plant AS Supplying_Plant, i.CustomerCode AS Customer_Number, " +
                            "g.DestPlannedArrival AS Planned_Delivery_Time,c.ETA AS Revised_Delivery_Time, IFNULL(c.ReportedTime, 'NA') AS Unload_In_Time, CASE WHEN c.ReportedTime >= g.DestPlannedArrival " +
                            "THEN TIMEDIFF(c.ReportedTime, g.DestPlannedArrival) ELSE CONCAT('-', TIMEDIFF(g.DestPlannedArrival, c.ReportedTime)) END AS Difference_in_hours " +
                            "FROM customerdcassign c " +
                            "JOIN vehicledctrip v ON v.id = c.DCTripId " +
                            "JOIN customerinfo i ON i.CustomerId = c.CustomerId " +
                            "LEFT JOIN shv_trip_details s ON s.DCTripId = v.id " +
                            "LEFT JOIN shv_trip_stages g ON g.FO_ID = s.FO_ID AND g.DestLocId = i.CustomerCode " +
                            "JOIN plantlogin p ON p.login = v.AddedBy " +
                            "WHERE v.DATETIME > ? AND v.DATETIME < ? AND v.AccountId = ? AND s.IsActive= 1 AND v.IsCancel = b'0' AND v.VehicleID IN (SELECT VehicleId FROM vehiclesgroupsmap WHERE GroupId=?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("accountid", accountid);
            lParameter.Add("GroupId", groupid);
            if (Plant != "All")
            {
                lParameter.Add("Plant", Plant);
                query += " and p.Plant=?";
            }
            if (Customerid != "All")
            {
                lParameter.Add("Customerid", Customerid);
                query += " and c.CustomerId=?";
            }
            if (!string.IsNullOrEmpty(Truck))
            {
                if (Truck.ToLower() != "all")
                {
                    lParameter.Add("Truck", Truck);
                    query += " and v.VehicleID=?";
                }
            }
            query += " order by v.DateTime desc";
            DataTable details = dbx.executeQuery(query, lParameter).Tables[0];
            return details;
        }
        public DataTable GetSHVETADataReport(string StartDate, string ToDate, int accountid, string sessionId, string Plant, string Customerid, string Truck)
        {
            string groupid = getGroupId(sessionId).ToString();
            if (ToDate == StartDate)
                ToDate = ToDate.Replace("00:00:00", "23:59:59");//Modified by Zoya on 19/10/2023 for SHV
            string query = "SELECT s.DC_No AS FO_Number, DATE_FORMAT(s.FO_Date, '%d/%m/%Y %h:%i:%s %p') AS FO_Date, s.Vehicle_ID AS Vehicle_Number, v.Category AS Transporter, s.Plant AS Supplying_Plant, " +
                "s.Customer_Code AS Customer_Number, DATE_FORMAT(s.Planned_Delivery, '%d/%m/%Y %h:%i:%s %p') AS Planned_Delivery_Time, DATE_FORMAT(c.ETA, '%d/%m/%Y %h:%i:%s %p') AS Revised_Delivery_Time, " +
                "IFNULL(COALESCE(DATE_FORMAT(c.ReportedTime, '%d/%m/%Y %h:%i:%s %p'), DATE_FORMAT(c.DeliveredOn, '%d/%m/%Y %h:%i:%s %p'), DATE_FORMAT(c.UnloadingInTime, '%d/%m/%Y %h:%i:%s %p'), c.DeviceStatus), 'NA') AS Unload_In_Time," +
                "CASE WHEN c.ReportedTime >= s.Planned_Delivery THEN TIMEDIFF(c.ReportedTime, s.Planned_Delivery) ELSE CONCAT('-', TIMEDIFF(s.Planned_Delivery, c.ReportedTime)) END AS Difference_in_hours FROM shv_eta_report s LEFT JOIN " +
                "vehiclecategory v ON v.VehicleId = s.Vehicle_ID LEFT JOIN (SELECT DCNo, MAX(ETA) AS ETA, MAX(ReportedTime) AS ReportedTime, MAX(DeliveredOn) AS DeliveredOn, MAX(UnloadingInTime) AS UnloadingInTime, MAX(DeviceStatus) AS DeviceStatus, CustomerId FROM customerdcassign GROUP BY DCNo, CustomerId) c ON c.DCNo = s.DC_No " +
                "WHERE s.FO_Date BETWEEN ? AND ? AND s.Vehicle_ID IN (SELECT VehicleId FROM vehiclesgroupsmap WHERE GroupId = ?) ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            //lParameter.Add("accountid", accountid);
            lParameter.Add("GroupId", groupid);
            if (Plant != "All")
            {
                lParameter.Add("Plant", Plant);
                query += " and s.Plant=?";
            }
            if (Customerid != "All")
            {
                lParameter.Add("Customerid", Customerid);
                query += " and c.CustomerId=?";
            }
            if (!string.IsNullOrEmpty(Truck))
            {
                if (Truck.ToLower() != "all")
                {
                    lParameter.Add("Truck", Truck);
                    query += " and s.Vehicle_ID=?";
                }
            }
            query += " order by s.FO_Date desc";
            DataTable details = dbx.executeQuery(query, lParameter).Tables[0];
            return details;
        }

        public DataTable GetDetailsFODateGreaterthanETA(string StartDate, string ToDate, int accountid, string sessionId)
        {
            string groupid = getGroupId(sessionId).ToString();
            if (ToDate == StartDate)
                ToDate = ToDate.Replace("00:00:00", "23:59:59");//Modified by Zoya on 19/10/2023 for SHV
            string query = "SELECT g.FO_ID,g.StageId,DATE_FORMAT(ADDTIME(s.ServerTS, '05:30:00'), '%d/%m/%Y %h:%i:%s %p') AS 'FO Date',s.VehicleNo,RIGHT(g.DestLocId, LENGTH(g.DestLocId) - 4) AS 'Customer Number',DATE_FORMAT(g.DestPlannedArrival, '%d/%m/%Y %h:%i:%s %p') as DestPlannedArrival FROM shv_trip_details s " +
                "JOIN shv_trip_stages g ON g.FO_ID = s.FO_ID WHERE s.ServerTS BETWEEN ? AND ? AND ADDTIME(s.ServerTS,'05:30:00')> g.DestPlannedArrival AND " +
                "s.VehicleNo IN(SELECT v.VehicleId FROM vehiclesgroupsmap v WHERE v.GroupId= ?) AND g.StageId != 'RTN'; ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("GroupId", groupid);
            DataTable details = dbx.executeQuery(query, lParameter).Tables[0];
            return details;
        }

