        public string Getouttimefordelaydata(string unloadingcode, string plannedarrival, string TripEndsOn, string vehicleId)
        {
            try
            {
                DateTime load = Convert.ToDateTime(plannedarrival);

                DateTime? load1 = null;
                if (!string.IsNullOrEmpty(TripEndsOn))
                {
                    load1 = Convert.ToDateTime(TripEndsOn);
                }

                string locstr = getlocstring(unloadingcode);
                if (!string.IsNullOrEmpty(locstr))
                {
                    string query;
                    if (load1.HasValue)
                    {
                        query = "select v.outtimestamp from vehicleinplant v where v.locationstr='" + locstr + "' and v.vehicleid='" + vehicleId + "' and " +
                                "v.intimestamp > '" + formatDBDate(load) + "' AND v.outtimestamp < '" + formatDBDate(load1.Value) + "' order BY v.outtimestamp asc limit 1;";
                    }
                    else
                    {
                        query = "select v.outtimestamp from vehicleinplant v where v.locationstr='" + locstr + "' and v.vehicleid='" + vehicleId + "' and " +
                                "v.intimestamp > '" + formatDBDate(load) + "' order BY v.outtimestamp asc limit 1;";
                    }

                    object tt = dbx.executeScalar(query);
                    if (tt == null)
                    {
                        return string.Empty;
                    }
                    return tt.ToString();
                }
                else
                {
                    return string.Empty;
                }
            }
            catch
            {
                return string.Empty;
            }
        }

        public int InsertSHVETAReport(string DCNo, string TripStartsOn, string VehicleID, string Plant, string CustomerCode, string DestPlannedArrival, string ETA, string ReportedTime, string Difference_in_hours)
        {
            try
            {
                string query = "";

                string Query = "INSERT IGNORE INTO `shv_eta_report` (`DC_No`, `FO_Date`, `Vehicle_ID`, `Plant`, `Customer_Code`, `Planned_Delivery`) VALUES (?, ?, ?, ?, ?, ?)";

                var lParameter = new Dictionary<string, object>();
                lParameter.Add("DC_No", DCNo);
                //lParameter.Add("Stage_ID", StageID);
                lParameter.Add("FO_Date", formatDBDate(DateTime.Parse(TripStartsOn)));
                lParameter.Add("Vehicle_ID", VehicleID);
                lParameter.Add("Plant", Plant);
                lParameter.Add("Customer_Code", CustomerCode);
                lParameter.Add("Planned_Delivery", formatDBDate(DateTime.Parse(DestPlannedArrival)));
                lParameter.Add("Revised_Delivery", formatDBDate(DateTime.Parse(ETA)));
                lParameter.Add("Unload_In_Time", ReportedTime.Equals("NA", StringComparison.OrdinalIgnoreCase) ? (object)DBNull.Value : formatDBDate(DateTime.Parse(ReportedTime)));
                lParameter.Add("Difference_Hours", Difference_in_hours);

                int result = dbx.executeNonQuery(Query, lParameter);
                return result;
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error inserting data: " + ex.Message);
                return 0;
            }
        }
