        public DataTable GetCompletedtripsNA(string StartDate, string ToDate, int accountid, string sessionid)
        {
            string groupid = getGroupId(sessionid).ToString();
            if (ToDate == StartDate)
                ToDate = ToDate.Replace("00:00:00", "23:59:59");//Modified by Zoya on 13/01/2025 for SHV
            string query = "SELECT s.DC_No AS FO_Number, s.FO_Date, vd.TripEndsOn, s.Vehicle_ID AS Vehicle_Number, s.Customer_Code AS Customer_Number, s.Planned_Delivery FROM shv_eta_report s " +
                "LEFT JOIN vehicledctrip vd ON vd.DateTime=s.FO_Date LEFT JOIN vehiclecategory v ON v.VehicleId = s.Vehicle_ID LEFT JOIN (SELECT DCNo, MAX(ETA) AS ETA, MAX(ReportedTime) AS ReportedTime, " +
                "MAX(DeliveredOn) AS DeliveredOn, MAX(UnloadingInTime) AS UnloadingInTime, MAX(DeviceStatus) AS DeviceStatus, CustomerId FROM customerdcassign GROUP BY DCNo, CustomerId) c ON c.DCNo = s.DC_No " +
                "WHERE s.FO_Date BETWEEN ? AND ? AND s.FO_Date <= s.Planned_Delivery AND s.Vehicle_ID IN (SELECT VehicleId FROM vehiclesgroupsmap WHERE GroupId = ?) AND c.DeviceStatus='NA' AND vd.IsTripEnds=1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("GroupId", groupid);
            //lParameter.Add("accountid", accountid);
            DataTable details = dbx.executeQuery(query, lParameter).Tables[0];
            return details;
        }



        public DataTable GetVehicleDetentionDataReport(string StartDate, string ToDate, int accountid, string Plant, string Customerid, string Truck)
        {
            if (ToDate == StartDate)
                ToDate = ToDate.Replace("00:00:00", "23:59:59");//Modified by Zoya on 19/10/2023 for SHV
            String query = "SELECT distinct c.DCNo AS FO_Number, v.DATETIME AS FO_Date,v.VehicleID AS Vehicle_Number, p.Plant AS Supplying_Plant,i.CustomerCode AS Customer_Number, " +
                            "(SELECT vp.intimestamp FROM vehicleinplant vp WHERE vp.locationstr = pl.customername AND vp.vehicleid = s.VehicleNo AND YEAR(vp.intimestamp) BETWEEN YEAR(v.DATETIME) " +
                            "AND YEAR(v.DATETIME) +2 AND vp.intimestamp > v.DateTime LIMIT 1) AS 'intimestamp', " +
                            "(SELECT vp.outtimestamp FROM vehicleinplant vp WHERE vp.locationstr = pl.customername AND vp.vehicleid = s.VehicleNo AND YEAR(vp.intimestamp) BETWEEN YEAR(v.DATETIME) " +
                            "AND YEAR(v.DATETIME) +2 AND vp.intimestamp > v.DATETIME " +
                            "LIMIT 1) AS 'outtimestamp',  " +
                            "TIME_FORMAT(TIMEDIFF((SELECT vp.outtimestamp FROM vehicleinplant vp WHERE vp.locationstr = pl.customername AND vp.vehicleid = s.VehicleNo AND YEAR(vp.intimestamp) BETWEEN YEAR(v.DATETIME) AND YEAR(v.DATETIME) + 2 AND vp.intimestamp > v.DATETIME LIMIT 1)," +
                            "(SELECT vp.intimestamp FROM vehicleinplant vp WHERE vp.locationstr = pl.customername AND vp.vehicleid = s.VehicleNo AND YEAR(vp.intimestamp) BETWEEN YEAR(v.DATETIME) AND YEAR(v.DATETIME) + 2 AND vp.intimestamp > v.DateTime LIMIT 1)), '%H:%i:%s') AS 'Difference_in_hours'" +
                            " FROM customerdcassign c " +
                            "JOIN vehicledctrip v ON v.id = c.DCTripId " +
                            "JOIN customerinfo i ON i.CustomerId = c.CustomerId " +
                            "LEFT JOIN shv_trip_details s ON s.DCTripId = v.id " +
                            "JOIN plantlogin p ON p.login = v.AddedBy " +
                            "JOIN plantgeolocations pl ON pl.PASSWORD = i.CustomerCode " +
                            "WHERE v.DATETIME > ? AND v.DATETIME < ? AND v.AccountId = ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            lParameter.Add("accountid", accountid);
            if (Plant != "All")
            {
                lParameter.Add("Plant", Plant);
                query += " and p.Plant=?";
            }
            if (Customerid != "All")
            {
                lParameter.Add("Customerid", Customerid);
                query += " and c.CustomerId=?";
            }
            if (!string.IsNullOrEmpty(Truck))
            {
                if (Truck.ToLower() != "all")
                {
                    lParameter.Add("Truck", Truck);
                    query += " and v.VehicleID=?";
                }
            }
            query += " ORDER BY v.DateTime DESC";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        //Modified by Zoya as one month data was not being fetched on 28/08/2024
        public DataTable GetVehicleDetentionData(string StartDate, string ToDate, string sessionId, int accountid, string Plant, string Customerid, string Truck)
        {
            string groupid = getGroupId(sessionId).ToString();
            if (ToDate == StartDate)
                ToDate = ToDate.Replace("00:00:00", "23:59:59");//Modified by Zoya on 19/10/2023 for SHV
            String query = "SELECT DISTINCT s.FO_Number,DATE_FORMAT(s.FO_Date, '%d/%m/%Y %h:%i:%s %p') AS FO_Date,s.Vehicle_Number,s.Supplying_Plant,s.Customer_Number,DATE_FORMAT((SELECT vp.intimestamp FROM vehicleinplant vp " +
                "WHERE vp.locationstr = pl.customername AND vp.vehicleid = s.Vehicle_Number AND YEAR(vp.intimestamp) BETWEEN YEAR(s.FO_Date) AND YEAR(s.FO_Date) + 2 AND vp.intimestamp > s.FO_Date LIMIT 1),'%d/%m/%Y %h:%i:%s %p') AS " +
                "intimestamp,DATE_FORMAT((SELECT vp.outtimestamp FROM vehicleinplant vp WHERE vp.locationstr = pl.customername AND vp.vehicleid = s.Vehicle_Number AND YEAR(vp.intimestamp) BETWEEN YEAR(s.FO_Date) AND YEAR(s.FO_Date) + 2 AND vp.intimestamp > s.FO_Date LIMIT 1),'%d/%m/%Y %h:%i:%s %p') AS outtimestamp," +
                "TIME_FORMAT(TIMEDIFF((SELECT vp.outtimestamp FROM vehicleinplant vp WHERE vp.locationstr = pl.customername AND vp.vehicleid = s.Vehicle_Number AND YEAR(vp.intimestamp) BETWEEN YEAR(s.FO_Date) AND " +
                "YEAR(s.FO_Date) + 2 AND vp.intimestamp > s.FO_Date LIMIT 1),(SELECT vp.intimestamp FROM vehicleinplant vp WHERE vp.locationstr = pl.customername AND vp.vehicleid = s.Vehicle_Number AND YEAR(vp.intimestamp) BETWEEN YEAR(s.FO_Date) AND YEAR(s.FO_Date) + 2 AND vp.intimestamp > s.FO_Date LIMIT 1)),'%H:%i:%s') AS Difference_in_hours " +
                "FROM shv_detention_report s JOIN plantgeolocations pl ON pl.PASSWORD = s.Customer_Number WHERE s.FO_Date BETWEEN ? AND ? AND s.Vehicle_Number IN (SELECT VehicleId FROM vehiclesgroupsmap WHERE GroupId = ?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StartDate", StartDate);
            lParameter.Add("ToDate", ToDate);
            //lParameter.Add("accountid", accountid);
            lParameter.Add("GroupId", groupid);
            if (Plant != "All")
            {
                lParameter.Add("Plant", Plant);
                query += " and s.Supplying_Plant=?";
            }
            if (Customerid != "All")
            {
                lParameter.Add("Customerid", Customerid);
                query += " and s.CustomerId=?";
            }
            if (!string.IsNullOrEmpty(Truck))
            {
                if (Truck.ToLower() != "all")
                {
                    lParameter.Add("Truck", Truck);
                    query += " and s.Vehicle_Number=?";
                }
            }
            query += " ORDER BY s.FO_Date DESC";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataSet GetUltraTechTripReport(int accountid, string username, string VehicleId, string fromdate, string todate)
        {
            string frdate = string.Empty;
            string tdate = string.Empty;
            if (!String.IsNullOrEmpty(fromdate))
            {
                try
                {
                    frdate = formatDBDate(DateTime.ParseExact(fromdate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    frdate = formatDBDate(Convert.ToDateTime(fromdate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    tdate = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    tdate = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            string GroupId = getGroupIdByLogin(username).ToString();
            string query = "SELECT u.Trip_ID,u.Tipper_No,u.Loader_No,u.Loading_Geo_Fence_Name,DATE_FORMAT(u.Tipper_InTime, '%d/%m/%Y %h:%i:%s %p') as Tipper_InTime,DATE_FORMAT(u.Tipper_OutTime, '%d/%m/%Y %h:%i:%s %p') as Tipper_OutTime,DATE_FORMAT(u.Loader_InTime, '%d/%m/%Y %h:%i:%s %p') as Loader_InTime,DATE_FORMAT(u.Loader_OutTime, '%d/%m/%Y %h:%i:%s %p') as Loader_OutTime,u.Unloading_Validation,DATE_FORMAT(u.Tipper_Unloading_InTime, '%d/%m/%Y %h:%i:%s %p') as Tipper_Unloading_InTime,DATE_FORMAT(u.Tipper_Unloading_OutTime, '%d/%m/%Y %h:%i:%s %p') as Tipper_Unloading_OutTime,u.Unloading_Geo_Fence_Name FROM ultratech_trip_details u where u.Tipper_InTime between ? and ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromdate", frdate);
            lParameter.Add("todate", tdate);
            if (VehicleId != "--Select Tipper--")
            {
                query += " and Tipper_No=? ";
                lParameter.Add("DeviceId", VehicleId);
            }
            else
            {
                query += " and Tipper_No IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?)";
                lParameter.Add("GroupId", GroupId);
            }
            query += " ORDER BY u.Tipper_InTime DESC";
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;
        }
