        public Object[] getJRMViolations(String vehicleId, String fromDate, String toDate, String sessionId)
        {
            string query = String.Empty;
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDate), Convert.ToDateTime(toDate), partions);
            if (String.Compare(vehicleId, "ALL") == 0)
            {
                DataTable dt = GetVehiclesBySessionId(sessionId).Tables[0];
                string vehls = string.Empty;
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    vehls += "'" + dt.Rows[i]["VehicleId"].ToString() + "',";
                }
                vehls += "''";
                query = "select distinct s1.vehicleid as vehicleid,s1.type,s1.timestamp,s1.duration,s1.location,remarks,s1.drivername from storevehicleviolations PARTITION(" + part + ") AS s1 " +
                    " where s1.timestamp between '" + fromDate + "' and '" + toDate + "' and s1.vehicleid in (" + vehls + ")  and type like " + "'JRM%'  order by vehicleid";
            }
            else
                query = "select vehicleid,type,timestamp,duration,location,remarks,drivername from storevehicleviolations PARTITION(" + part + ") AS s1 where timestamp between '"
                    + fromDate + "' and '" + toDate + "' and vehicleid = '" + vehicleId + "'" + " and type like " + "'JRM%'";

            DataSet violations = dbx.executeQuery(query);
            DataTable table = violations.Tables[0];
            ArrayList violationsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                violationsList.Add(row.ItemArray);
            }
            return violationsList.ToArray();
        }

