        public int SaveMultiGeofence(string geofenceName, string AlertOn, string AlertBy, string Email, string SmsPhone, string MinLat, string MinLog, string MaxLat, string MaxLong, string SingleOrAll, string LoginUser, string smsMessage, string NoOfPoints, List<string> vehicles,
                               string Place, string Road, string City, string Dist, string State, double Lat, double Long, int AccountId, string GeofenceType, string plantType, ArrayList Points, string AlertNotification)
        {
            int result = 0;
            int pointCount = Convert.ToInt32(NoOfPoints);
            try
            {
                //string[] Points = PolygonLinePoints.ToArray();
                String query = String.Empty;
                if (NoOfPoints == "4")
                {
                    query = "insert into geofencenew(geofencename,MinLatitude,MinLongitude,MaxLatitude,MaxLongitude,LoginUser," +
                    "SmsPhone,SmsMessage,email_id,inorout,noofpoints,AllOrSingleVehicle,Road,Place,City,District,State,Latitude," +
                    "Longitude,Accountid,geofencetype,planttype,AlertNotification) values('" + geofenceName + "','" + MinLat + "','" + MinLog + "'," +
                    "'" + MaxLat + "','" + MaxLong + "','" + LoginUser + "','" + SmsPhone + "','" + smsMessage + "','" + Email + "'," +
                    "'" + AlertOn + "','" + NoOfPoints + "','" + SingleOrAll + "','" + Road + "','" + Place + "','" + City + "','" + Dist + "','" + State + "','" + Lat + "','" + Long + "'," +
                    "'" + AccountId + "','" + GeofenceType + "','" + plantType + "','" + AlertNotification + "')";
                }
                else if (pointCount > 4 && pointCount <= 25)
                {
                    string columns = "geofencename,LoginUser,SmsPhone,SmsMessage,email_id,inorout,noofpoints,AllOrSingleVehicle,";
                    string values = "'" + geofenceName + "','" + LoginUser + "','" + SmsPhone + "','" + smsMessage + "','" + Email + "','" +
                                    AlertOn + "','" + pointCount + "','" + SingleOrAll + "',";

                    int totalPoints = Points.Count / 2; // ✅ actual available points

                    for (int i = 0; i < totalPoints && i < 25; i++)
                    {
                        columns += "lat" + (i + 1) + ",lng" + (i + 1) + ",";
                        values += "'" + Points[i * 2] + "','" + Points[(i * 2) + 1] + "',";
                    }

                    columns += "Road,Place,City,District,State,Latitude,Longitude,Accountid,geofencetype,planttype,MinLatitude,MinLongitude,MaxLatitude,MaxLongitude,AlertNotification";

                    values += "'" + Road + "','" + Place + "','" + City + "','" + Dist + "','" + State + "','" +
                              Lat + "','" + Long + "','" + AccountId + "','" + GeofenceType + "','" + plantType + "','" +
                              Convert.ToDouble(MinLat) + "','" + Convert.ToDouble(MinLog) + "','" +
                              Convert.ToDouble(MaxLat) + "','" + Convert.ToDouble(MaxLong) + "','" +
                              AlertNotification + "'";

                    query = "INSERT INTO geofencenew (" + columns + ") VALUES (" + values + ")";
                }
                result = dbx.executeNonQuery(query);
                if (result == 1)
                {
                    query = "insert into addressesNew(road,place,city,district,state,latitude,longitude,Accountid) values('" + Road + "','" + Place + "','" + City + "','" + Dist + "','" + State + "'," + Lat + "," + Long + "," + AccountId + ")";
                    result = dbx.executeNonQuery(query);

                    query = "SELECT LAST_INSERT_ID()";
                    DataTable table = dbx.executeQuery(query.ToString()).Tables[0];
                    if (table.Rows.Count > 0)
                    {
                        int GeofenceId = Convert.ToInt32(table.Rows[0][0]);

                        if (GeofenceId != null)
                        {
                            if (vehicles.Count > 0)
                            {
                                foreach (string TruckID in vehicles)
                                {
                                    query = "select * from geofencevehicle where TruckID ='" + TruckID + "' and GeofenceId = '" + GeofenceId + "'";
                                    result = dbx.executeNonQuery(query);
                                    if (result == 0)
                                    {
                                        query = "insert into geofencevehicle (TruckID,GeofenceId) values('" + TruckID + "', '" + GeofenceId + "')";
                                        result = dbx.executeNonQuery(query);
                                    }
                                }
                                result = 1;
                            }
                        }
                    }
                }
            }
            catch (Exception e) { }
            return result;
        }

