                    query = "SELECT LAST_INSERT_ID()";
                    DataTable table = dbx.executeQuery(query.ToString()).Tables[0];
                    if (table.Rows.Count > 0)
                    {
                        int GeofenceId = Convert.ToInt32(table.Rows[0][0]);

                        if (GeofenceId != null)
                        {
                            if (vehicles.Count > 0)
                            {
                                foreach (string TruckID in vehicles)
                                {
                                    query = "select * from geofencevehicle where TruckID ='" + TruckID + "' and GeofenceId = '" + GeofenceId + "'";
                                    result = dbx.executeNonQuery(query);
                                    if (result == 0)
                                    {
                                        query = "insert into geofencevehicle (TruckID,GeofenceId) values('" + TruckID + "', '" + GeofenceId + "')";
                                        result = dbx.executeNonQuery(query);
                                    }
                                }
                                result = 1;
                            }
                        }
                    }
                }
            }
            catch { }
            return result;
        }
