        public int UpdateGeofence(string Id, string geofenceName, string AlertOn, string AlertBy, string Email, string SmsPhone, string MinLat, string MinLog, string MaxLat,
                                  string MaxLong, string SingleOrAll, string LoginUser, string smsMessage, string NoOfPoints, List<string> vehicles, string Place,
                                  string Road, string City, string Dist, string State, double Lat, double Long, int AccountId, double PreviousLattitude, double PreviousLongitude, string GeofenceType, string PlantType, ArrayList Points, string AlertNotification)
        {
            int result = 0;
            try
            {
                insertauditdata("Edit", "geofencenew", "ID", Id);
                String query = "update geofencenew set geofencename = '" + geofenceName + "',MinLatitude = '" + MinLat + "',MinLongitude = '" + MinLog + "'," +
                               "MaxLatitude = '" + MaxLat + "',MaxLongitude = '" + MaxLong + "',LoginUser = '" + LoginUser + "',SmsPhone = '" + SmsPhone + "'," +
                               "SmsMessage = '" + smsMessage + "',email_id = '" + Email + "',inorout = '" + AlertOn + "',noofpoints = '" + NoOfPoints + "'," +
                              "AllOrSingleVehicle ='" + SingleOrAll + "',AlertNotification='" + AlertNotification + "',";
                if (Points.Count > 0)
                {
                    query = query + "lat1='" + Points[0] + "', lng1='" + Points[1] + "', lat2='" + Points[2] + "', lng2='" + Points[3] + "'," +
                               "lat3='" + Points[4] + "', lng3='" + Points[5] + "', lat4='" + Points[6] + "', lng4='" + Points[7] + "', lat5='" + Points[8] + "', " +
                               "lng5='" + Points[9] + "', lat6='" + Points[10] + "', lng6='" + Points[11] + "', lat7='" + Points[12] + "', lng7='" + Points[13] + "', lat8='" + Points[14] + "'," +
                               "lng8='" + Points[15] + "', lat9='" + Points[16] + "', lng9='" + Points[17] + "',";
                }
                query = query + "Road ='" + Road + "', Place ='" + Place + "',City ='" + City + "',District ='" + Dist + "'," +
                               "State ='" + State + "', Latitude ='" + Lat + "', Longitude ='" + Long + "',Accountid ='" + AccountId + "',geofencetype='" + GeofenceType + "'," +
                               "planttype='" + PlantType + "' where ID = '" + Id + "'";

                result = dbx.executeNonQuery(query);
                if (result == 1)
                {
                    result = SaveAddressesNew(Place, Road, City, Dist, State, Lat, Long, AccountId, PreviousLattitude, PreviousLongitude);

                    if (SingleOrAll == "1")
                    {
                        query = "delete from geofencevehicle where GeofenceId = '" + Id + "'";
                        result = dbx.executeNonQuery(query);
                        foreach (string TruckID in vehicles)
                        {
                            query = "insert into geofencevehicle (TruckID,GeofenceId) values('" + TruckID + "', '" + Id + "')";
                            result = dbx.executeNonQuery(query);
                        }
                    }
                    else
                    {
                        query = "delete from geofencevehicle where GeofenceId = '" + Id + "'";
                        result = dbx.executeNonQuery(query);
                        result = 1;
                    }
                }
            }
            catch { }
            return result;
        }

        public int DeleteGeofence(string GeofenceId)
        {
            //deleting releated geofenceId form geofencevehicle table
            int result = 0;
            string query = string.Empty;
            query = "select * from geofencevehicle where GeofenceId = '" + GeofenceId + "'";
            result = dbx.executeNonQuery(query);
            if (result > 0)
            {
                query = "delete from geofencevehicle where GeofenceId = '" + GeofenceId + "'";
                result = dbx.executeNonQuery(query);
            }
            query = "select * from geofencenew where ID = " + GeofenceId + "";
            DataSet ds = dbx.executeQuery(query);
            DataTable geofence = ds.Tables[0];
            if (geofence.Rows.Count > 0)
            {
                query = "delete from addressesNew where Latitude = " + geofence.Rows[0][37] + " and Longitude=" + geofence.Rows[0][38] + "";
                result = dbx.executeNonQuery(query);
            }
            //Once records deleted from geofenceid from geofencevehicle, now we need to delete geofence from geofencenew table
            insertauditdata("Delete", "geofencenew", "ID", GeofenceId);
            query = "delete from geofencenew where ID = " + GeofenceId + "";
            result = dbx.executeNonQuery(query);
            return result;
        }

        public Object[] GetVehicleLocationByVehicleId(string VehicleId, string date, string SessionId)
        {
            ArrayList vehDetailsArray = new ArrayList();
            DateTime maxTs;
            DateTime now;
            String nowStr;
            if (date == "")
            {
                int timeZone = GetTimeZoneDiff(SessionId);
                maxTs = DateTime.MinValue;
                now = DateTime.UtcNow.AddSeconds(timeZone);
                nowStr = formatDBDate(now); ;
            }
            else
            {
                nowStr = date;
            }
            string part = GetDateTablePartitions(Convert.ToDateTime(nowStr).AddDays(-15), Convert.ToDateTime(nowStr), partions);
            String query = "select max(timestamp) from positiondata PARTITION(" + part + ") AS p where truckid = '" + VehicleId + "' and timestamp < '" + nowStr + "'";
            Object vehTs = dbx.executeScalar(query);
            try
            {
                maxTs = DateTime.Parse(vehTs.ToString());
            }
            catch
            {
                return (vehDetailsArray.ToArray());
            }
            String maxTsStr = formatDBDate(maxTs);
            query = "select timestamp,latitude,longitude from positiondata PARTITION(" + part + ") AS p where truckid = '" + VehicleId + "' and timestamp ='" + maxTsStr + "'";
            DataSet vehDet = dbx.executeQuery(query);
            DataTable table = vehDet.Tables[0];
            foreach (DataRow row in table.Rows)
            {
                string UserName = getUserId(SessionId);
                if (vehDetailsArray.Count == 0)
                    vehDetailsArray.Add(row.ItemArray);
                StringBuilder Query = new StringBuilder();
                Query.Append("select minlatitude,minLongitude,maxLatitude,maxLongitude,geofencename from geofencenew ");
                Query.Append("where LoginUser='" + UserName + "' and (minlatitude <= " + table.Rows[0][1].ToString() + " ");
                Query.Append("AND minLongitude <= " + table.Rows[0][2].ToString() + " ");
                Query.Append("AND maxLatitude >= " + table.Rows[0][1].ToString() + " ");
                Query.Append("AND maxLongitude >= " + table.Rows[0][2].ToString() + ") ");
                DataTable GeofenceLatLng = dbx.executeQuery(Query.ToString()).Tables[0];
                if (GeofenceLatLng.Rows.Count > 0)
                {
                    vehDetailsArray.Add(GeofenceLatLng.Rows[0].ItemArray);
                }
            }
            return vehDetailsArray.ToArray();
        }

