        //for Smart_Driver app
        public DataRow GetRunningTime(string vehicle, string IMEI)
        {
            int timeZone = 5 * 60 * 60 + 30 * 60;
            string date = DateTime.UtcNow.AddSeconds(timeZone).ToString("yyyy-MM-dd 05:00:00");
            string DriverId = GetDriverIdByIMEI(IMEI);
            string query = "select CONCAT(CAST(floor((cummRunTime/3600)) as UNSIGNED),'h  ',CAST(MOD((cummRunTime/60),60)as UNSIGNED),'min') " +
                           "as maxtime,s.lastUpdateTime " +
                           "from vehiclessnapshot s where s.vehicleid=? and (s.DriverId=? or s.DriverId=0) order by s.DriverId desc limit 1";
            try
            {
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", vehicle);
                lParameter.Add("DriverId", DriverId);
                DataSet ds = dbx.executeQuery(query, lParameter);
                return ds.Tables[0].Rows[0];
            }
            catch
            {

                return null;
            }
        }

        //for Smart_Driver app
        public DataRow GetRunAndContinuousTime(string vehicle, string IMEI)
        {
            string DriverId = GetDriverIdByIMEI(IMEI);
            string query = "select CONCAT(CAST(floor((cummRunTime/3600)) as UNSIGNED),'h  ',CAST(MOD((cummRunTime/60),60)as UNSIGNED),'min') as "
                         + "maxtime,s.lastUpdateTime,CONCAT(CAST(floor((shortRunTime/3600)) as UNSIGNED),'h  ',CAST(MOD((shortRunTime/60),60)as "
                         + "UNSIGNED),'min') as contime,CAST(floor((shortStopTime/60)) as UNSIGNED) as resttime from vehiclessnapshot s "
                         + "where s.vehicleid=? and (s.DriverId=? or s.DriverId=0) order by s.DriverId desc limit 1";
            try
            {
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", vehicle);
                lParameter.Add("DriverId", DriverId);
                DataSet ds = dbx.executeQuery(query, lParameter);
                if (ds.Tables[0].Rows.Count > 0)
                    return ds.Tables[0].Rows[0];
                else
                    return null;
            }
            catch
            {

                return null;
            }
        }

        //for Smart_Driver app
        public DataTable GetJrmLimitations(string vehicleid, string imei)
        {
            string query = "select CONCAT(CAST(floor((longRunDuration/3600)) as UNSIGNED),'h  ',CAST(MOD((longRunDuration/60),60)as UNSIGNED),'min'"
                         + ") as daylimit,s.curfewStart,s.curfewEnd,CONCAT(CAST(floor((shortRunDuration/3600)) as UNSIGNED),'h  ',CAST(MOD(("
                         + "shortRunDuration/60),60)as UNSIGNED),'min') as shortrun,CONCAT(CAST(floor((shortRestDuration/3600)) as UNSIGNED),'h  '"
                         + ",CAST(MOD((shortRestDuration/60),60)as UNSIGNED),'min') as shortrest,CONCAT(CAST(floor((shortRunDuration2/3600)) as "
                         + "UNSIGNED),'h  ',CAST(MOD((shortRunDuration2/60),60)as UNSIGNED),'min') as shortrun2,CONCAT(CAST(floor(("
                         + "shortRestDuration2/3600)) as UNSIGNED),'h  ',CAST(MOD((shortRestDuration2/60),60)as UNSIGNED),'min') as shortrest2,"
                         + "maxSpeed,'2592000' as jrmspotsupdaterate,'600' as runtimeupdaterate,'259200000' as audioupdaterate,'30' as gpsupdaterate,"
                         + "'10' as gpsdistanceinterval,'0' as gpstimeinterval,'Sensel12345' as applockpassword from vehicletripparams s where "
                         + "s.groupId= (select min(v.GroupId) from vehiclesgroupsmap v where v.VehicleID='" + vehicleid + "' order by v.GroupId)";
            DataTable ds = dbx.executeQuery(query).Tables[0];
            if (ds.Rows.Count == 0)
            {
                query = "select '10h  0min' as daylimit,'08:00:00 PM' as curfewStart,'05:00:00 AM' as curfewEnd,'2h  0min' as shortrun,'0h  20min'"
                      + " as shortrest,'4h  30min' as shortrun2,'0h  45min' as shortrest2,'60' as maxSpeed,'2592000' as jrmspotsupdaterate,'600' "
                      + "as runtimeupdaterate,'259200000' as audioupdaterate,'30' as gpsupdaterate,'10' as gpsdistanceinterval,'0' as gpstimeinterval"
                      + ",'Sensel12345' as applockpassword";
                if (imei == "353285067384198")
                    query = "select '0h  0min' as daylimit,'08:00:00 PM' as curfewStart,'05:00:00 AM' as curfewEnd,'2h  0min' as shortrun,'0h  20min'"
                      + " as shortrest,'4h  30min' as shortrun2,'0h  45min' as shortrest2,'160' as maxSpeed,'2592000' as jrmspotsupdaterate,'600' "
                      + "as runtimeupdaterate,'259200000' as audioupdaterate,'30' as gpsupdaterate,'10' as gpsdistanceinterval,'0' as gpstimeinterval"
                      + ",'Sensel12345' as applockpassword";
                ds = dbx.executeQuery(query).Tables[0];
            }
            query = "select c.jrmspotsupdaterate,c.runtimeupdaterate,c.audioupdaterate,c.gpsupdaterate,c.gpsdistanceinterval,"
                      + "c.gpstimeinterval,c.applockpassword from driverappconfig c where c.IMEI='" + imei + "'";
            DataTable config = dbx.executeQuery(query).Tables[0];
            if (config.Rows.Count > 0)
            {
                ds.Rows[0]["jrmspotsupdaterate"] = config.Rows[0]["jrmspotsupdaterate"];
                ds.Rows[0]["runtimeupdaterate"] = config.Rows[0]["runtimeupdaterate"];
                ds.Rows[0]["audioupdaterate"] = config.Rows[0]["audioupdaterate"];
                ds.Rows[0]["gpsupdaterate"] = config.Rows[0]["gpsupdaterate"];
                ds.Rows[0]["gpsdistanceinterval"] = config.Rows[0]["gpsdistanceinterval"];
                ds.Rows[0]["gpstimeinterval"] = config.Rows[0]["gpstimeinterval"];
                ds.Rows[0]["applockpassword"] = config.Rows[0]["applockpassword"];
            }
            return ds;
        }

