        public DataTable GetChecklistVehicles(string accountid, string groupid)
        {
            //Modified by suvarna on 12/5/2021 to get list of active dc data
            //Modified by suvarna on 23/6/2021 to enable this report for lubes
            DateTime date = DateTime.Now;
            String dateStr = date.ToString("yyyy-MM-dd");
            String datetoStr = date.AddDays(-1).ToString("yyyy-MM-dd");
            string query = "select distinct di.Name,di.AssignedVehicleId,di.DriverId,di.ContactNo,ti.Name as Transporter,vi.Dedicated,vi.Plant from driverinfo di " +
                            "inner join vehicledctrip vt on vt.VehicleID=di.AssignedVehicleId " +
                            "inner join vehicleinfo vi on vi.VehicleId=vt.VehicleID " +
                            "inner join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                            "where di.AccountId='" + accountid + "' and di.AssignedVehicleId<>' ' and di.AssignedVehicleId<>'' and di.IMEI<>' ' and di.IMEI<>'' " +
                            //"and vt.DateTime between '" + datetoStr + "' and '" + dateStr + "' and vt.IsCancel=0 " +
                            "and vt.IsTripEnds = 0 and vt.VehicleID in (select vehicleid from vehiclesgroupsmap where groupid ='" + groupid + "' ) and vt.IsCancel = 0 " +
                            //"and di.IMEI is not null and di.DriverId not in (select ch.Driverid from driverchecklists ch where date(ch.DateTime)='" + datetoStr + "' OR date(ch.DateTime)='" + dateStr + "')";
                            "and di.IMEI is not null and di.DriverId not in (select ch.Driverid from DailyChecklistHeader ch where date(ch.SubmissionDateTime)='" + datetoStr + "' OR date(ch.SubmissionDateTime)='" + dateStr + "')";  

            return dbx.executeQuery(query.ToString()).Tables[0];
        }

