        //For fleet_smart app
        public DataTable GetConsolidatedReport(string sessionId, string vehicles)
        {
            if (vehicles != null)
            {
                DateTime date = DateTime.Now;
                string yesterday = date.AddDays(-1).ToString("yyyy-MM-dd"); //for yesterday date
                DateTime firstDayOfMonth = new DateTime(date.Year, date.Month, 1);
                DateTime firstDayOfYear = new DateTime(date.Year, 1, 1);
                string monthfirst = firstDayOfMonth.ToString("yyyy-MM-dd");
                string yearfirst = firstDayOfYear.ToString("yyyy-MM-dd");
                string query = "select dv.vehicleid,kms_driven as yesterday,c.thismonth,d.thisyear " +
                               "from daywisevehviosummary dv " +
                               "inner join " +
                               "(select vehicleid, sum(kms_driven) as thismonth " +
                               "from daywisevehviosummary where date>='" + monthfirst + "' group by vehicleid)c " +
                               "on dv.vehicleid=c.vehicleid " +
                               "inner join " +
                               "(select vehicleid, sum(kms_driven) as thisyear " +
                               "from daywisevehviosummary where date>='" + yearfirst + "' group by vehicleid)d " +
                               "on c.vehicleid=d.vehicleid " +
                               "where dv.date='" + yesterday + "' AND dv.vehicleid in(" + vehicles + ")";
                return dbx.executeQuery(query.ToString()).Tables[0];
            }
            return null;
        }

