        public DataSet GetCustomerAllVehicleLastTrips(string groupid)
        {
            StringBuilder Query = new StringBuilder();
            string query = "select v.VehicleID,v.DateTime as starttrip,IFNULL(v.TripEndsOn,c.DeliveredOn) as endtrip from vehicledctrip v " +
                            " join customerdcassign c on c.id=(select max(id) from customerdcassign where DCTripId=v.id) " +
                            " where v.id in  " +
                            " (select max(a.id) as endtrip  " +
                            " from vehicledctrip a " +
                            " join customerdcassign c on c.id=(select max(id) from customerdcassign where DCTripId=a.id) " +
                            " where (c.IsDelivered=1 or a.IsTripEnds=1) and a.VehicleID in (select vehicleid from vehiclesgroupsmap m where m.Groupid=?) " +
                            " group by a.VehicleID)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Groupid", groupid);
            return dbx.executeQuery(query.ToString(), lParameter);
        }
