        public DataTable GetVehicleInfo(string vehicleId, string DriverNo)
        {
            string query = "SELECT  i.`VehicleId`,t.Name as TransName,t.TransNumber,i.Transporter as TransporterId,i.ABS,i.ChasisNo,i.EngineNo,i.MarkersName,i.Capacity," +
                           " i.Articulated,i.TypeOfBody,i.YearOfManufacturer,i.OEMCabin,i.TankManfDate,i.TankMakeModel,i.Logo,i.GPS,i.SeatBelt," +
                           " d.Name as Driver,d.DOB,d.MobileNo,d.LicenceNo,d.LicenceValid,d.HazardousLicExpDate,d.DDTDate,d.DDTGrade,d.DDTExpiryDate," +
                           " d.MedicalTestDate,d.MediExpDate,d.DriverId,i.Accident,i.UnladenWeight,i.rate,i.ContactNo,i.BrakeValue,d.ContactNo as DriverContactNo,d.DriverLanguagePreference,d.DriverPhoto,d.HazardousLicNo,t.EmailId as TransEmailId,d.IMEI,i.CrashGuard, " +
                           " d.DriverAccidentHistory,d.DrivingExp,d.DOJ,i.Plant,i.Dedicated,i.IsContract,i.ContractFrom,i.NoofAxle,i.VehRegDate,t.ContractType,t.ContractValid,t.AuditedDate,i.UnladenWeight,i.TypeOfVehicle,i.TruckType,d.RFIDTag,d.UserDefinedDriverId,d.NiyoAccNo " +
                           " FROM `vehicleinfo` i" +
                           " left join vehicles v on v.VehicleID=i.VehicleId" +
                           " left join driverinfo d on d.AssignedVehicleId=v.VehicleID and d.DriverNo=?" +
                           " left join transporterinfo t on t.TransporterId=i.Transporter" +
                           " where i.VehicleID=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("DriverNo", DriverNo);
            lParameter.Add("VehicleID", vehicleId);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }

