        public string UpdateVehicleInfo(string vehicleId, string Transporter, string ABS, string ChasisNo, string EngineNo, string MarkerName, string Capacity, string Articulated, string TypeOfBody, string YearofManf, string OEMCabin, string TankManfDate, string TankMakeModel, string Logo, string GPS, string SeatBelt, string AccidentHistory, string UnladenWeight, string Rate, string BrakeValue, string CrashGuard, string Plant, string Dedicated, string Contract, string ContractFrom, string NoofAxle, string VehRegDate, string VehicleType, string TruckType, string RFIDNo = "1", string RFIDTagVal = "")
        {
            insertauditdata("REPLACE", "vehicleinfo", "VehicleId", vehicleId);
            DataTable dt = GetVehicleInfoData(vehicleId);
            if (dt.Rows.Count == 0)
            {
                string query = "REPLACE INTO `vehicleinfo` (`VehicleId`,`ChasisNo`, `EngineNo`, `MarkersName`, `TypeOfBody`, `YearOfManufacturer`, `UnladenWeight`,`Transporter`, `Accident`, `ABS`, `Capacity`, `Articulated`, `OEMCabin`, `TankManfDate`, `TankMakeModel`, `Logo`, `GPS`, `SeatBelt`,`BrakeValue`, `rate`,`CrashGuard`,`Plant`, `Dedicated`, `IsContract`, `ContractFrom`, `NoofAxle`,`VehRegDate`,`TypeOfVehicle`,TruckType,RFID" + RFIDNo + ") VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?);";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", vehicleId);
                lParameter.Add("ChasisNo", ChasisNo);
                lParameter.Add("EngineNo", EngineNo);
                lParameter.Add("MarkersName", MarkerName);
                lParameter.Add("TypeOfBody", TypeOfBody);
                lParameter.Add("YearOfManufacturer", YearofManf);
                lParameter.Add("UnladenWeight", UnladenWeight);
                lParameter.Add("Transporter", Transporter);
                lParameter.Add("Accident", AccidentHistory);
                lParameter.Add("ABS", ABS);
                lParameter.Add("Capacity", Capacity);
                lParameter.Add("Articulated", Articulated);
                lParameter.Add("OEMCabin", OEMCabin);
                lParameter.Add("TankManfDate", TankManfDate);
                lParameter.Add("TankMakeModel", TankMakeModel);
                lParameter.Add("Logo", Logo);
                lParameter.Add("GPS", GPS);
                lParameter.Add("SeatBelt", SeatBelt);
                lParameter.Add("BrakeValue", BrakeValue);
                lParameter.Add("rate", Rate);
                lParameter.Add("CrashGuard", CrashGuard);
                lParameter.Add("Plant", Plant);
                lParameter.Add("Dedicated", Dedicated);
                lParameter.Add("IsContract", Contract);
                lParameter.Add("ContractFrom", ContractFrom);
                lParameter.Add("NoofAxle", NoofAxle);
                lParameter.Add("VehRegDate", VehRegDate);
                lParameter.Add("TypeOfVehicle", VehicleType);
                lParameter.Add("TruckType", TruckType);
                lParameter.Add("RFIDNo", RFIDTagVal);
                string res = dbx.executeNonQuery(query.ToString(), lParameter).ToString();
                if (res != "0")
                    PushChangeDataToAPI(vehicleId, "UpdateVehicleInfo", getAccountIdByVehicleId(vehicleId).ToString());
                return res;
            }
            else
            {
                string query = "update `vehicleinfo` set `ChasisNo`=?,`EngineNo`=?,`MarkersName`=?,`TypeOfBody`=?,`YearOfManufacturer`=?,`UnladenWeight`=?,`Transporter`=?,`Accident`=?,`ABS`=?," +
                               "`Capacity`=?,`Articulated`=?,`OEMCabin`=?,`TankManfDate`=?,`TankMakeModel`=?,`Logo`=?,`GPS`=?,`SeatBelt`=?,`BrakeValue`=?,`rate`=?,`CrashGuard`=?,`Plant`=?," +
                               "`Dedicated`=?,`IsContract`=?,`ContractFrom`=?,`NoofAxle`=?,`VehRegDate`=?,`TypeOfVehicle`=?,`TruckType`=?";
                if (!string.IsNullOrEmpty(RFIDTagVal))
                {
                    query += ",RFID" + RFIDNo + "=?";
                }
                query += " where `VehicleId`=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("ChasisNo", ChasisNo);
                lParameter.Add("EngineNo", EngineNo);
                lParameter.Add("MarkersName", MarkerName);
                lParameter.Add("TypeOfBody", TypeOfBody);
                lParameter.Add("YearOfManufacturer", YearofManf);
                lParameter.Add("UnladenWeight", UnladenWeight);
                lParameter.Add("Transporter", Transporter);
                lParameter.Add("Accident", AccidentHistory);
                lParameter.Add("ABS", ABS);
                lParameter.Add("Capacity", Capacity);
                lParameter.Add("Articulated", Articulated);
                lParameter.Add("OEMCabin", OEMCabin);
                lParameter.Add("TankManfDate", TankManfDate);
                lParameter.Add("TankMakeModel", TankMakeModel);
                lParameter.Add("Logo", Logo);
                lParameter.Add("GPS", GPS);
                lParameter.Add("SeatBelt", SeatBelt);
                lParameter.Add("BrakeValue", BrakeValue);
                lParameter.Add("rate", Rate);
                lParameter.Add("CrashGuard", CrashGuard);
                lParameter.Add("Plant", Plant);
                lParameter.Add("Dedicated", Dedicated);
                lParameter.Add("IsContract", Contract);
                lParameter.Add("ContractFrom", ContractFrom);
                lParameter.Add("NoofAxle", NoofAxle);
                lParameter.Add("VehRegDate", VehRegDate);
                lParameter.Add("TypeOfVehicle", VehicleType);
                lParameter.Add("TruckType", TruckType);
                if (!string.IsNullOrEmpty(RFIDTagVal))
                {
                    lParameter.Add("RFID" + RFIDNo, RFIDTagVal);
                }
                lParameter.Add("VehicleId", vehicleId);
                string res = dbx.executeNonQuery(query.ToString(), lParameter).ToString();
                if (res != "0")
                    PushChangeDataToAPI(vehicleId, "UpdateVehicleInfo", getAccountIdByVehicleId(vehicleId).ToString());
                return res;
            }
        }

