            {
                string Query = "select d.Date,v.VehicleId,v.`Group`,d.Distance,d.runTime,IFNULL((select vf.OdometerInitialVal from vehicleinfo vf where vf.VehicleId=v.VehicleId),0) as IntialOdoMeter from vehiclegrouping v, daywisedistance d where v.VehicleId = d.vehicleId and d.Date <= '" + formatDBDate(Convert.ToDateTime(Date)) + "' order by d.Date";
