                return result;
            }
        }

        public DataTable GetMissingPositionDataVehicles(string groupid, DateTime FromDate, DateTime ToDate, string vehicleids)
        {
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("groupid", groupid);
            lParameter.Add("FromDate", formatDBDate(FromDate));
            lParameter.Add("ToDate", formatDBDate(ToDate));
            string Query = "select m.* from missingpositiondata m " +
                           " join vehiclesgroupsmap v on v.VehicleID=m.TruckId and v.GroupId=? " +
                           " where " +
                           " m.CurrentUpdateTime between ? and ? ";
            if (!string.IsNullOrEmpty(vehicleids))
            {
                String[] vals = vehicleids.Replace("'", "").Replace("\"", "").Split(',');
                string inparam = "";
                for (int i = 0; i < vals.Length; i++)
                {
                    if (i == 0)
                        inparam += ("?");
                    else
                        inparam += (",?");
                    lParameter.Add("truckId" + i, vals[i]);
                }
                Query += " and m.TruckId in (" + inparam + ")";
            }
            Query += " group by m.TruckId,m.LastUpdateTime;";
            return dbx.executeQuery(Query.ToString(), lParameter).Tables[0];
        }
        public DataTable GetDataGapVehicles(string groupid, DateTime FromDate, DateTime ToDate, int hours)
        {
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("groupid", groupid);
            lParameter.Add("FromDate", formatDBDate(FromDate));
            lParameter.Add("ToDate", formatDBDate(ToDate));
            lParameter.Add("hours", hours + ":00:00");
            string Query = "select m.* from datagap m " +
                           " join vehiclesgroupsmap v on v.VehicleID=m.TruckId and v.GroupId=? " +
                           " where " +
                           " m.FromTimeStamp between ? and ? and TIMEDIFF(m.ToTimeStamp,m.FromTimeStamp)>? group by m.TruckId,m.FromTimeStamp;";
            return dbx.executeQuery(Query.ToString(), lParameter).Tables[0];
        }
