        public string EditVehicleIcon(string VehicleId, string Icon, string sessionid)
        {

            string addedon = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff(sessionid)));
            string query = "";
            var lParameter = new Dictionary<string, object>();
            if (!VehicleId.Contains(",") && VehicleId != "ALL")
            {
                query = "update vehicles set IconType=? where VehicleID=?;";
                lParameter.Clear();
                lParameter.Add("IconType", Icon);
                lParameter.Add("VehicleID", VehicleId);
                dbx.executeNonQuery(query, lParameter);
            }
            else if (VehicleId.Contains(",") && VehicleId != "ALL")
            {
                string[] veh = VehicleId.Split(',');
                for (int i = 0; i < veh.Length; i++)
                {
                    query = "update vehicles set IconType=? where VehicleID=?;";
                    lParameter.Clear();
                    lParameter.Add("IconType", Icon);
                    lParameter.Add("VehicleID", veh[i]);
                    dbx.executeNonQuery(query, lParameter);
                }

            }
            else if (VehicleId == "ALL")
            {
                query = "select v.VehicleId  from noupdates n " +
                " right join vehiclesgroupsmap  v on v.VehicleId=n.truckid  " +
                " inner join usersgroupsmap m on m.GroupId=v.GroupId " +
                " inner join sessions s on s.login=m.login " +
                " where s.SessionID=?";
                lParameter.Clear();
                lParameter.Add("SessionID", sessionid);
                DataSet ds = dbx.executeQuery(query, lParameter);
                for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
                {
                    query = "update vehicles set IconType=? where VehicleID=?;";
                    lParameter.Clear();
                    lParameter.Add("IconType", Icon);
                    lParameter.Add("VehicleID", ds.Tables[0].Rows[i]["VehicleId"].ToString());
                    dbx.executeNonQuery(query, lParameter);
                }
            }
            return "1";
        }

