        public string AddVehicleInPlantDetails(string TurckId, double Latitude, double Longitude, int StartBit, int StopBit, double Speed, DateTime TimeStamp, string configtimeZoneStr = "")
        {
            string time = string.Empty;
            string Result = string.Empty;
            try
            {
                string locationStr = String.Empty;
                string query = "select ID,LoginUser,geofencename,AllorSingleVehicle,planttype,minlatitude,minLongitude,maxLatitude,maxLongitude,noofpoints,lat1, lng1, lat2, lng2, lat3, lng3, " +
                         "lat4, lng4, lat5, lng5, lat6, lng6, lat7, lng7, lat8, lng8, lat9, lng9 from geofencenew " +
                         "where Accountid = (select v.AccountID from vehicles v where v.VehicleID='" + TurckId + "')";

                DataTable GetAllGeofence = dbx.executeQuery(query.ToString()).Tables[0];

                //To select regular geofence 
                string FilterRegularGeofence = "minlatitude <=" + Latitude + " and minLongitude <= " + Longitude + " and maxLatitude >= " + Latitude + " and maxLongitude >= " + Longitude + "";

                //To select irregualr geofence if it not found in regular geofnece 
                DataRow[] GeofenceList = GetAllGeofence.Select(FilterRegularGeofence);

                DataTable lGeofenceDetails = new DataTable();
                DataTable lIrregularTable = new DataTable();

                string NoOfPoints = "9";
                string InLocStrgs = string.Empty;
                string VehicleSinglOrMutiple = string.Empty;

                string FilterIrregularGeofence = "noofpoints=" + NoOfPoints;
                DataRow[] IrregularList = GetAllGeofence.Select(FilterIrregularGeofence);
                if (IrregularList.Length > 0)
                {
                    lIrregularTable = IrregularList.CopyToDataTable();
                    lIrregularTable = GetAllGeofencePolygonByLatLng(lIrregularTable, Latitude, Longitude);
                    lGeofenceDetails = lIrregularTable.Copy();
                }
                if (GeofenceList.Length > 0)
                {
                    lGeofenceDetails.Merge(GeofenceList.CopyToDataTable());
                }

                for (int i = 0; i < lGeofenceDetails.Rows.Count; i++)
                {
                    locationStr = (string)lGeofenceDetails.Rows[i][2];

                    int IsSingelOrAllVehicle = Convert.ToInt32(lGeofenceDetails.Rows[i][3].ToString());

                    VehicleSinglOrMutiple = Convert.ToString(IsSingelOrAllVehicle);
                    string GeofenceId = Convert.ToString(lGeofenceDetails.Rows[i][0]);
                    int PlantType = Convert.ToInt32(lGeofenceDetails.Rows[i][4].ToString());

                    //Checking geofence applicable for all vehilcles or multiple vehicle
                    if (IsSingelOrAllVehicle != 0)
                    {
                        string Query = "select count(gn.TruckID) from geofencevehicle gn where gn.GeofenceId=" + GeofenceId + " and gn.TruckID='" + TurckId + "'";
                        int count = dbx.executeNonQuery(Query.ToString());
                        // Checking wether vehicle is belogns to geofence or not
                        if (count > 0)
                        {
                            time = InsertVehicleInPlantDetails(TurckId, locationStr, PlantType, TimeStamp, configtimeZoneStr);
                        }
                    }
                    else
                    {
                        time = InsertVehicleInPlantDetails(TurckId, locationStr, PlantType, TimeStamp, configtimeZoneStr);
                    }
                    if (i == lGeofenceDetails.Rows.Count - 1)
                        InLocStrgs += "'" + locationStr + "'";
                    else
                        InLocStrgs += "'" + locationStr + "',";
                }

                Result = UpdateVehicleOutTimeFromGeofence(TurckId, 0, TimeStamp, InLocStrgs);
            }
            catch { }
            return time + Result;
        }
