        public DataTable GetAuxInputByVehicle(string vehicleid, string timestamp)
        {
            string query = "select v.OnOffType,v.TempSense,t.gvinp1 as distance,t.hvinp as idlingInstances,t.bv as CallerPhone,'' as Temperature from lastupdtdata t" +
                           "  join vehicles v on v.VehicleID=t.TruckID" +
                           "  where t.TruckID='" + vehicleid + "'";
            DataTable dt = dbx.executeQuery(query.ToString()).Tables[0];
            if (dt.Rows.Count > 0)
            {
                if (dt.Rows[0]["TempSense"].ToString() == "TEMP")
                {
                    string track_part = GetDateTablePartitions(Convert.ToDateTime(timestamp), Convert.ToDateTime(timestamp).AddMinutes(1), track_partions);
                    query = "select * from trackerdata PARTITION(" + track_part + ") AS t" +
                                   "  join vehicles v on v.VehicleID=t.TruckID and t.FromTimeStamp<='" + formatDBDate(Convert.ToDateTime(timestamp)) + "'" +
                                   "  where t.TruckID='" + vehicleid + "'" +
                                   "  order by t.FromTimeStamp desc limit 1";
                    return dbx.executeQuery(query.ToString()).Tables[0];
                }
            }
            return dt;
        }


