        public DataTable GetDriver_NotCheckingRoute(string accountid)
        {
            try
            {
                DateTime date = DateTime.Now;
                String frmdate = date.ToString("yyyy-MM-dd");
                String todate = date.AddDays(-1).ToString("yyyy-MM-dd");
                //string frmdate = formatDBDate(DateTime.Now.AddHours(-25));//Last 
                //string todate = formatDBDate(DateTime.Now.AddHours(-1));// Don't check for last one hour

                StringBuilder query = new StringBuilder();
                query.Append("select distinct di.Name,v.VehicleID,di.DriverId,di.ContactNo,ti.Name as Transporter,vi.Dedicated,vi.Plant from customerdcassign c ");
                query.Append("inner join vehicledctrip v on v.id=c.DCTripId  ");
                query.Append("inner join driverinfo di on di.AssignedVehicleId=v.VehicleID   ");
                query.Append("inner join vehicleinfo vi on vi.VehicleId=v.vehicleid  ");
                query.Append("inner join transporterinfo ti on ti.TransporterId=vi.Transporter  ");
                query.Append("where di.AccountId='" + accountid + "' and v.DateTime between '" + frmdate + "' and '" + todate + "' and c.IsDelivered=0 and v.IsTripEnds=0 and c.IsCancel=0  ");
                query.Append("and di.IMEI<>' ' and di.IMEI<>'' and di.IMEI is not null and IMEI not in (select IMEI from driveractivitylog dl  ");
                query.Append("where dl.activity='route' and dl.Date between '" + frmdate + "' and '" + todate + "')");

                return dbx.executeQuery(query.ToString()).Tables[0];
            }
            catch
            {
                return null;
            }
        }

