        public void InsertDayWiseDistanceTable(DateTime date, double distance, string vehicleId, TimeSpan runtime)
        {
            int month = date.Month;
            int year = date.Year;
            double totalDistance = 0.0;
            double lasttotalDistance = 0.0;
            string query;
            try
            {
                StringBuilder Query1 = new StringBuilder();
                Query1.Append("select OdometerValue from daywisedistance d where d.vehicleId='" + vehicleId + "' order by d.Date desc limit 1");
                Double LastDayOdoVal = Convert.ToDouble(dbx.executeScalar(Query1.ToString()));
                Double TodayOdoVal = LastDayOdoVal + distance;

                query = "select count(*) from daywisedistance where vehicleId = " + "'" + vehicleId + "'" +
                                " and month(date) = " + month + " and  year(date) = " + year;
                int dataExists = Convert.ToInt16(dbx.executeScalar(query));
                if (dataExists > 0)
                {
                    query = "select count(*) from daywisedistance where vehicleId = " + "'" + vehicleId + "'" +
                                        " and date = " + "'" + formatDBDate(date) + "'";
                    if (Convert.ToInt16(dbx.executeScalar(query)) == 1)
                    {
                        query = "update daywisedistance set distance=" + distance + " where vehicleId ='" + vehicleId + "' and date = " + "'" + formatDBDate(date) + "'";
                        dbx.executeNonQuery(query);
                        return;
                    }

                    query = "select max(totalDistance) from daywisedistance  where month(date) = "
                    + month + " and year(date)= " + year + " and vehicleId = " +
                    "'" + vehicleId + "'";
                    Object lasttotalDistanceObj = dbx.executeScalar(query);
                    lasttotalDistance = Convert.ToDouble(lasttotalDistanceObj);
                    totalDistance = lasttotalDistance + distance;

                    StringBuilder Query = new StringBuilder();
                    Query.Append("INSERT INTO `daywisedistance` (`Date`, `vehicleId`, `Distance`, `runTime`,`OdometerValue`) VALUES ('" + formatDBDate(date) + "', '" + vehicleId + "', " + distance + ", " + runtime.TotalSeconds + ", " + TodayOdoVal + ");");
                    //query = "insert into daywisedistance(date,vehicleId,distance,runTime,OdometerValue) values("
                    //         + "'" + formatDBDate(date) + "'" + ","
                    //         + "'" + vehicleId + "'" + ","
                    //         + distance + "," +
                    //         +runtime.TotalSeconds + ")";
                    dbx.executeNonQuery(Query.ToString());
                }
                else
                {
                    StringBuilder query1 = new StringBuilder();
                    query1.Append("INSERT INTO `daywisedistance` (`Date`, `vehicleId`, `Distance`, `runTime`,`OdometerValue`) VALUES ('" + formatDBDate(date) + "', '" + vehicleId + "', " + distance + ", " + runtime.TotalSeconds + ", " + TodayOdoVal + ");");

                    //query = "insert into daywisedistance(date,vehicleId,distance,runtime) values("
                    //        + "'" + formatDBDate(date) + "'" + ","
                    //        + "'" + vehicleId + "'" + ","
                    //        + distance + "," +
                    //        +runtime.TotalSeconds + ")";
                    dbx.executeNonQuery(query1.ToString());
                }
            }
            catch (Exception e)
            {
                throw e;
            }
        }

