        public DataTable GetCustomerDCbyVehicle(string VehicleId, string Cust, DateTime FromDate, DateTime ToDate, string driverid = "0")
        {
            try
            {
                string query = "select v.* from vehicledctrip v " +
                               " join customerdcassign c on c.DCTripId=v.id" +
                               " where v.VehicleID=? and c.CustomerId=?" +
                               " and v.DateTime>=? and v.DateTime<=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleID", VehicleId);
                lParameter.Add("CustomerId", Cust);
                lParameter.Add("DateTime1", formatDBDate(FromDate));
                lParameter.Add("DateTime2", formatDBDate(ToDate));

                if (driverid != "0")
                {
                    query = "select v.* from vehicledctrip v " +
                               " join customerdcassign c on c.DCTripId=v.id" +
                               " join drivervehiclelog d on d.Vehicleid=v.VehicleID and v.DateTime between d.Fromdate and IFNULL(d.Todate,NOW())" +
                               " where d.Driverid=? and c.CustomerId=?" +
                               " and v.DateTime>=? and v.DateTime<=?";
                    lParameter.Clear();
                    lParameter.Add("Driverid", driverid);
                    lParameter.Add("CustomerId", Cust);
                    lParameter.Add("DateTime1", formatDBDate(FromDate));
                    lParameter.Add("DateTime2", formatDBDate(ToDate));
                }
                return dbx.executeQuery(query, lParameter).Tables[0];

            }
            catch { return null; }
        }
