        public int ReffRouteUpdate(string RouteName, string Vehicles, string IsVehicleAssigned)
        {
            string Query = string.Empty;
            Query = "update referenceroutedetail set isvehicleassigned = ? where routename=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("isvehicleassigned", IsVehicleAssigned);
            lParameter.Add("routename", RouteName);

            int Result = dbx.executeNonQuery(Query.ToString(), lParameter);
            if (Result >= 0)
            {
                string query = string.Empty;
                query = "delete from assignedvehicleroute where RouteName=?";
                lParameter.Clear();
                lParameter.Add("RouteName", RouteName);
                dbx.executeQuery(query, lParameter);

                var lVehicles = Vehicles.Split(',');
                for (int i = 0; i < lVehicles.Length; i++)
                {
                    if (lVehicles[i].ToString() != "")
                    {
                        query = "insert into assignedvehicleroute(RouteName,VehicleId) values(?,?)";
                        lParameter.Clear();
                        lParameter.Add("RouteName", RouteName);
                        lParameter.Add("VehicleId", lVehicles[i].ToString());
                        Result = dbx.executeNonQuery(query, lParameter);
                    }
                }
            }
            return Result;
        }


