        public DataTable GetRoutePointsByLatitudeLongitude(double minLatitude, double minLongitude, double maxLatitude, double maxLongitude, string vehicleid, string accountid)
        {
            string query = string.Empty;
            query = "select minlat-0.006 as minlat,minlong-0.006 as minlong,minlat+0.006 as maxlat,minlong+0.006 as maxlong from referenceroutedetail r " +
                    " join assignedvehicleroute a on r.routename = a.RouteName and a.VehicleId='" + vehicleid + "' or (r.isvehicleassigned is NULL or r.isvehicleassigned=0)" +
                    " where r.minlat>='" + minLatitude + "' and r.minlong>='" + minLongitude + "' and r.minlat<='" + maxLatitude + "' and r.minlong<='" + maxLongitude + "' and r.accountid='" + accountid + "' and r.isvehicleassigned !=-1";
            return dbx.executeQuery(query).Tables[0];
        }

        /// <summary>
        /// Get KM driven by driver in current month
        /// </summary>
        /// <param name="driverid"></param>
        /// <returns>int</returns>
        public int getKmsDrivenForthisMonth(int driverid, string vehicle, string IsTrip = null)
        {

            string query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            int month = DateTime.Now.Month;
            int year = DateTime.Now.Year;
            query = "select IFNULL(sum(Kms_driven),0) as 'KMS' from daywisevehviosummary d where month(d.date)=? and year(d.date)= ? ";
            lParameter.Add("month", month);
            lParameter.Add("year", year);
            if (driverid == 0)
            {
                query += "and vehicleid=?";
                lParameter.Add("vehicleid", vehicle);
            }
            else
            {
                query += "and driverid=?";
                lParameter.Add("driverid", driverid);
            }
            if (!string.IsNullOrEmpty(IsTrip))
            {
                query += " and IsTrip=?";
                lParameter.Add("IsTrip", IsTrip);
            }
            object obj = dbx.executeScalar(query, lParameter);
            if (obj != null)
            {
                return Convert.ToInt32(obj);
            }
            else
                return 0;
        }
