        public DataTable GetAllHUBDSByCityName(int AccountId, string Origin, string Table)
        {
            string query = string.Empty;
            query = "select distinct c.Origin from citywiseemailids c where c.AccountId=" + AccountId + " and c.CityName='" + Origin + "'";
            DataTable ListOfHUBDS = dbx.executeQuery(query).Tables[0];
            if (ListOfHUBDS.Rows.Count > 0)
            {
                List<string> Orgins = new List<string>();
                foreach (DataRow dr in ListOfHUBDS.Rows)
                {
                    string str_origin = Convert.ToString(dr["Origin"]);
                    if (!string.IsNullOrEmpty(str_origin))
                    {
                        Orgins.AddRange(str_origin.Split(',').ToList());
                    }
                }
                string qryInStr = string.Join(",", Orgins.Distinct().ToArray());
                if (Table.ToLower() == "vehiclescheduleshift")
                {
                    query = "select distinct HubName from vehiclescheduleshift v where v.AccountId=" + AccountId + " and v.OriginDc in (" + qryInStr + ")  ORDER BY HubName asc";
                }
                else
                {
                    query = "SELECT DISTINCT NAME as HubName FROM customerinfo i join (SELECT d.CustomerId FROM customerinfo c JOIN dc_source_destination_mapping d ON c.LoginUser =d.UserLogin WHERE c.AccountId=" + AccountId + " and c.GeofenceName IN (" + qryInStr + ") AND d.`Type`=1) s ON s.CustomerId=i.customerId ORDER BY NAME asc;";
                }
                ListOfHUBDS = dbx.executeQuery(query).Tables[0];
            }
            return ListOfHUBDS;
        }

