        public string UpdateVehicleOutTimeFromGeofence(String vehicleId, int plantType, DateTime vehTs)
        {	//only update thoes records of that vehicle for which outtimedone is null
            //and if multiple records fond then skip updation for next batch process
            string timestamp = "";
            string GeofenceName = "";
            int? result = null;
            string sqlQurery = "";
            int UpdateFlag = 0;
            try
            {
                string query = "select max(intimestamp) from vehicleinplant where vehicleid='" + vehicleId + "' and outtimestamp is null";
                object time = dbx.executeScalar(query);
                if (!time.Equals(System.DBNull.Value))
                {
                    timestamp = time.ToString();
                    query = "select veh.locationstr from  vehicleinplant veh where intimestamp='" + formatDBDate(Convert.ToDateTime(timestamp)) + "' and " +
                             "vehicleid = '" + vehicleId + "' and outtimestamp is null ";
                    sqlQurery = query;
                    DataTable geofenceinout = dbx.executeQuery(query).Tables[0];
                    string geofencename = string.Empty;
                    if (geofenceinout.Rows.Count > 0)
                    {
                        geofencename = geofenceinout.Rows[0]["locationstr"].ToString();
                        GeofenceName = geofencename;
                        query = "update vehicleinplant set outtimestamp='" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "',outtimedone=1 " + "where vehicleid = '" + vehicleId + "' and " +
                                       "  outtimestamp is NULL and locationstr='" + geofencename + "'" + " and intimestamp<'" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "'";
                        result = dbx.executeNonQuery(query);
                        UpdateFlag = 1;
                    }
                }
                if (UpdateFlag == 0)
                {
                    int TimeZone = GetTimeZoneDiff();

                    DateTime IndianTime = DateTime.UtcNow;

                    IndianTime = IndianTime.AddSeconds(TimeZone);
                    // Here igonering the late arrival data if it is less than 5 minutes with comparing the present timestamp
                    int TotalMinutes = Convert.ToInt32(IndianTime.Subtract(vehTs).TotalMinutes);
                    string Result = string.Empty;
                    if (TotalMinutes >= 5)
                    {
                        Result = "Inside 5 Minute block";
                        //Getting last out time when late arrival data more than 5 minutes
                        string Query = string.Empty;
                        DataTable lPreviousData = new DataTable();
                        Query = "select v.intimestamp,v.outtimestamp,v.locationstr from vehicleinplant v where v.vehicleid='" + vehicleId + "' " +
                                 "and v.outtimestamp is not null and v.outtimestamp>'" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "' order " +
                                 "by v.outtimestamp desc limit 1";
                        lPreviousData = dbx.executeQuery(Query).Tables[0];
                        if (lPreviousData.Rows.Count > 0)
                        {
                            DateTime lInTime = Convert.ToDateTime(lPreviousData.Rows[0][0].ToString());
                            DateTime lOutTime = Convert.ToDateTime(lPreviousData.Rows[0][1].ToString());
                            string Location = Convert.ToString(lPreviousData.Rows[0][2]);
                            int Intime = vehTs.CompareTo(lInTime);
                            int OutTime = vehTs.CompareTo(lOutTime);

                            if (Intime > 0 && OutTime < 0)
                            {
                                //Updating actual out time
                                Query = "update vehicleinplant set outtimestamp='" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "' where vehicleid='" + vehicleId + "' " +
                                         "and locationstr ='" + Location + "' and outtimestamp='" + formatDBDate(lOutTime) + "'";
                                dbx.executeNonQuery(Query);
                                //return "Updated Actual out time";
                                return "";
                            }
                            //return "Not Updated Actual out time "; 
                            return "";
                        }
                        //return "Inside 5 Minute block to update actual out time";
                        return "";
                    }
                }
            }
            catch (Exception e)
            {

            }
            return "";
        }
        public string UpdateVehicleOutTimeFromGeofence(String vehicleId, int plantType, DateTime vehTs, string InLocStrgs)
        {	//only update thoes records of that vehicle for which outtimedone is null
            //and if multiple records fond then skip updation for next batch process
            int? FinallyResult = null;
            if (string.IsNullOrEmpty(InLocStrgs))
            {
                return UpdateVehicleOutTimeFromGeofence(vehicleId, plantType, vehTs);
            }
            else
            {
                string timestamp = "";
                try
                {
                    string query = "select max(intimestamp) from vehicleinplant where vehicleid='" + vehicleId + "' and locationstr not in (" + InLocStrgs + ") and outtimestamp is null";
                    object time = dbx.executeScalar(query);
                    if (time != null)
                    {
                        timestamp = time.ToString();

                        query = "select veh.locationstr from  vehicleinplant veh where intimestamp='" + formatDBDate(Convert.ToDateTime(timestamp)) + "' and " +
                                 "vehicleid = '" + vehicleId + "' and outtimestamp is null ";
                        DataTable geofenceinout = dbx.executeQuery(query).Tables[0];
                        string geofencename = string.Empty;
                        if (geofenceinout.Rows.Count > 0)
                        {
                            geofencename = geofenceinout.Rows[0]["locationstr"].ToString();
                            query = "update vehicleinplant set outtimestamp='" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "',outtimedone=1 " + "where vehicleid = '" + vehicleId + "' and " +
                                           "  outtimestamp is NULL and locationstr='" + geofencename + "'" + " and intimestamp<'" + vehTs.ToString("yyyy-MM-dd HH:mm:ss") + "'";
                            FinallyResult = dbx.executeNonQuery(query);
                        }
                    }
                }
                catch (Exception e)
                {

                }
            }
            return "";
        }

