        public object[] getprevplantlocdata(string vehicleid, string currentlocTS, string currentloc)
        {
            string query = "select locationstr , planttype, intimestamp from vehicleinplant where vehicleid = '" + vehicleid + "'" +
                                " and intimestamp > '" + formatDBDate(Convert.ToDateTime(currentlocTS).AddDays(-7)) + "' and intimestamp < '" + currentlocTS + "'" +
                                " and locationstr != '" + currentloc + "'" +
                                " and planttype in (0,1,2) " +
                                " order by intimestamp desc limit 1";
            DataSet dsplantLoc = dbx.executeQuery(query);
            string prevlocTS = string.Empty;
            int interval;
            object[] prevplantlocdata;
            try
            {
                prevplantlocdata = dsplantLoc.Tables[0].Rows[0].ItemArray;
                prevlocTS = formatDBDate(Convert.ToDateTime(dsplantLoc.Tables[0].Rows[0].ItemArray[2]));
                query = "select Timestampdiff(day," + "'" + prevlocTS + "'," + "'" + currentlocTS + "'" + ")";
                interval = Convert.ToInt16(dbx.executeScalar(query));
                if (interval >= 10)
                    return null;
                else
                    return prevplantlocdata;
            }

            catch { return null; }
        }
