        public bool checkforLatePackets(string truckid, string fromTime, string toTime)
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(fromTime), Convert.ToDateTime(toTime), partions);
            string query = "select count(*) from positiondata PARTITION(" + part + ") AS p where truckid =" + "'" + truckid + "'" + " and timestamp between " +
                               "'" + fromTime + "'" + " and " + "'" + toTime + "';";
            int packetscnt = Convert.ToInt32(dbx.executeScalar(query));
            query = "select timestampdiff(minute, " + "'" + fromTime + "'" + "," + "'" + toTime + "'" + ")";
            int interval = Convert.ToInt32(dbx.executeScalar(query));
            if (packetscnt >= Math.Round(Convert.ToDecimal(interval / 2)))
                return true;
            else
                return false;
        }



