        public Object[] GetGeoFenceViolationsByLatLng(string truckId, double latitude, double longitude)
        {
            string lastViolation = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff() - 24 * 60 * 60));
            int inOrOut = 1;
            string ListOfUsers = GetListOfUsersByVehicleID(truckId);
            StringBuilder query = new StringBuilder();
            try
            {
                query.Append("select inorout from geofencenew where LoginUser in (" + ListOfUsers + ")");
                inOrOut = Convert.ToInt32(dbx.executeScalar(query.ToString()));
            }
            catch { }
            query.Length = 0;
            if (inOrOut != 0)
            {//outside
                query.Append("select ID, SmsPhone, SmsMessage,email_id FROM geofence ");
                query.Append("where LoginUser in (" + ListOfUsers + ")");
                query.Append("AND LastViolation < \"" + lastViolation + "\" ");
                query.Append("AND (MinLatitude > " + latitude + " ");
                query.Append("OR MinLongitude > " + longitude + " ");
                query.Append("OR MaxLatitude < " + latitude + " ");
                query.Append("OR MaxLongitude < " + longitude + ") ");
                query.Append("LIMIT 1;");
            }
            else
            {  // inside
                query.Append("select ID, SmsPhone, SmsMessage,email_id FROM geofence ");
                query.Append("where LoginUser in (" + ListOfUsers + ")");
                query.Append("AND LastViolation < \"" + lastViolation + "\" ");
                query.Append("AND (MinLatitude <= " + latitude + " ");
                query.Append("AND MinLongitude <= " + longitude + " ");
                query.Append("AND MaxLatitude > " + latitude + " ");
                query.Append("AND MaxLongitude > " + longitude + ") ");
                query.Append("LIMIT 1;");
            }
            DataSet vehicles = dbx.executeQuery(query.ToString());
            DataTable table = vehicles.Tables[0];
            ArrayList violationList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                violationList.Add(row.ItemArray);
            }
            return violationList.ToArray();
        }

        // Added for New Geofence
        public DataRow[] GetAllNullOutTime(string fromtime = "", string totime = "")
        {
            StringBuilder query = new StringBuilder();
            if (fromtime == "" && totime == "")
            {
                query.Append("select distinct vehin.vehicleid,vehin.locationstr,intimestamp,geo.MinLatitude,geo.MinLongitude,geo.MaxLatitude,geo.MaxLongitude from vehicleinplant vehin,geofencenew geo ");
                query.Append(" where vehin.outtimestamp is null and vehin.locationstr=geo.geofencename");
                query.Append(" union");
                query.Append(" select distinct vehin.vehicleid,vehin.locationstr,intimestamp,geo.MinLatitude,geo.MinLongitude,geo.MaxLatitude,geo.MaxLongitude from vehicleinplant vehin,plantgeolocations geo ");
                query.Append(" where vehin.outtimestamp is null and vehin.locationstr=geo.locstr AND vehin.intimestamp > '" + DateTime.Now.AddDays(-2).ToString("yyyy-MM-dd HH:mm") + "' ");
            }
            else
            {
                query.Append("select distinct vehin.vehicleid,vehin.locationstr,intimestamp,geo.MinLatitude,geo.MinLongitude,geo.MaxLatitude,geo.MaxLongitude from vehicleinplant vehin,geofencenew geo ");
                query.Append("where vehin.outtimestamp is null and vehin.locationstr=geo.geofencename and vehin.intimestamp>'" + fromtime + "'");

            }
            DataSet Values = dbx.executeQuery(query.ToString());
            DataRow[] Vehicles = new DataRow[(Values.Tables[0].Rows.Count)];

            Values.Tables[0].Rows.CopyTo(Vehicles, 0);
            return Vehicles;
        }

        public DataTable GetRoutebyPlantname(string source, string destination, string vehicle = null)
        {
            StringBuilder query = new StringBuilder();
            query.Append("SELECT  Segments FROM    sourcedestinationmap s " +
                         "WHERE   (? LIKE CONCAT('%', UCASE(s.Source), '%') and ? like  CONCAT('%', UCASE(s.Destination), '%')) ");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("source", source.ToUpperInvariant());
            lParameter.Add("destination", destination.ToUpperInvariant());
            object segments = dbx.executeScalar(query.ToString(), lParameter);
            if (segments == null)
                return null;

            string[] route_segments = segments.ToString().Split(',');
            string format_segments = "'";
            for (int i = 0; i < route_segments.Length - 1; i++)
                format_segments = format_segments + route_segments[i] + "','";
            format_segments = format_segments + route_segments[route_segments.Length - 1] + "'";

            //insert record for reference
            InsertRouteDeviationlog(vehicle, source, destination, format_segments);

            query.Clear();
            query.Append("select minlat-0.006 as minlat,minlong-0.006 as minlong,minlat+0.006 as maxlat,minlong+0.006 as maxlong from referenceroutedetail r where r.routename in (" + format_segments + ") and (r.isvehicleassigned !=-1 or r.isvehicleassigned is null)");
            DataSet ds = dbx.executeQuery(query.ToString());
            if (ds != null)
                return ds.Tables[0];
            else
                return null;

        }
        /// <summary>
        /// Get plant type  =1 between two time stamps
        /// </summary>
        /// <param name="fromDateStr"></param>
        /// <param name="toDateStr"></param>
        /// <param name="plantType"></param>
        /// <param name="sessionId"></param>
        /// <param name="vehicleid"></param>
        /// <returns></returns>
        public Object[] getEndTripTs(String fromDateStr, String toDateStr, int plantType, string sessionId, string vehicleid)
        {
            String query = String.Empty;
            query = "select usersgroupsmap.GroupId from usersgroupsmap,sessions where sessions.login = usersgroupsmap.login and " +
                "sessionid =?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("sessionid", sessionId);
            Object groupIdObj = dbx.executeScalar(query, lParameter);
            int groupId = Convert.ToInt32(groupIdObj);
            // Get the accountid to filter out plants that do not belong to the account
            lParameter.Clear();
            query = "select accountid from accountgroups where groupid =?";
            lParameter.Add("groupid", groupId);
            Object accountIdObj = dbx.executeScalar(query);
            int accountId = Convert.ToInt32(accountIdObj);
            // Need a three way filter that returns only those vehicles that belong to the group which have reached plants belonging to that 
            // account
            lParameter.Clear();
            query = "select v.vehicleid,locationStr,planttype,intimestamp from vehicleinplant v join plantgeolocations p on v.locationstr = p.locstr " +
                " where intimestamp between ?" +
                 " and ? and p.type=?  " +  ///*and p.accountId = ?*/
                " and reportstatus = 0 and v.vehicleid=? order by intimestamp asc";
            lParameter.Add("intimestamp1", fromDateStr);
            lParameter.Add("intimestamp2", toDateStr);
            lParameter.Add("type", plantType);
            //lParameter.Add("accountId", accountId);
            lParameter.Add("vehicleid", vehicleid);
            DataSet vehInPlant = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = vehInPlant.Tables[0];
            ArrayList vehInPlantList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                vehInPlantList.Add(row.ItemArray);
            }
            //
            // There are many instances where the vehicle will stay put for days @ plant so if there was an entry for the same vehicle within the past 36 hrs then skip it.
            //
            Object[] stillInPlant = vehInPlantList.ToArray();
            ArrayList finalList = new ArrayList();
            for (int i = 0; i < stillInPlant.Length; i++)
            {
                String vehicleId = (((Object[])stillInPlant[i])[0]).ToString();
                DateTime ts = DateTime.Parse((((Object[])stillInPlant[i])[3]).ToString());
                ts = ts.AddMinutes(-1);
                DateTime tsMin = ts.AddHours(-12);  // changed from 36 to 12
                String tsStr = formatDBDate(ts);
                String tsMinStr = formatDBDate(tsMin);
                lParameter.Clear();
                query = "select count(*) from vehicleinplant where vehicleid = ?" +
                        " and intimestamp between ? and ? and planttype= ? ";
                lParameter.Add("vehicleid", vehicleId);
                lParameter.Add("intimestamp1", tsMinStr);
                lParameter.Add("intimestamp2", tsStr);
                lParameter.Add("planttypes", plantType);
                Object countObj = dbx.executeScalar(query, lParameter);
                int numEnt = Convert.ToInt32(countObj);

                if (numEnt == 0)
                {
                    finalList.Add((Object[])stillInPlant[i]);
                }
            }
            return finalList.ToArray();
        }

