        public int insertVehicleEvents(string vehicleId, string eventName, string eventType, string timestamp, string duration, string source)
        {
            int res = 0;
            try
            {
                string query = "select v.VehicleID from vehicles v where replace(v.VehicleID,' ','')=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", vehicleId);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                if (dt != null && dt.Rows.Count > 0)
                {
                    vehicleId = dt.Rows[0]["VehicleID"].ToString();
                    dt = GetDriTransIdsbyVehicleID(vehicleId);
                    DateTime nowDt = DateTime.Now;
                    if (dt != null && dt.Rows.Count > 0)
                    {
                        string location = "";
                        string lat = "";
                        string lng = "";
                        DataTable posDt = GetLastPosdata(vehicleId, Convert.ToDateTime(timestamp));
                        if (posDt != null && posDt.Rows.Count > 0)
                        {
                            lat = posDt.Rows[0]["Latitude"].ToString();
                            lng = posDt.Rows[0]["Longitude"].ToString();
                            location = getPositionTxt(lat, lng, 1);
                        }
                        int accountid = getAccountIdByVehicleId(vehicleId);
                        query = "INSERT INTO `vehicle_events` (`VehicleId`, `DriverId`, `TransporterId`, `EventName`, `EventType`, `Timestamp`, `Duration`, `Source`,"
                        + "Location,Latitude,Longitude,AccountId,RecordedTime) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("vehicleid", vehicleId);
                        lParameter.Add("DriverId", Convert.ToString(dt.Rows[0]["DriverId"]));
                        lParameter.Add("TransporterId", Convert.ToString(dt.Rows[0]["Transporter"]));
                        lParameter.Add("EventName", eventName);
                        lParameter.Add("EventType", eventType);
                        lParameter.Add("Timestamp", formatDBDate(Convert.ToDateTime(timestamp)));
                        lParameter.Add("Duration", duration);
                        lParameter.Add("Source", source);
                        lParameter.Add("Location", location);
                        lParameter.Add("Latitude", lat);
                        lParameter.Add("Longitude", lng);
                        lParameter.Add("AccountId", accountid);
                        lParameter.Add("RecordedTime", nowDt);
                        res = dbx.executeNonQuery(query, lParameter);
                    }
                }
            }
            catch (Exception ex)
            {
            }
            return res;
        }

