        public DataTable GetPreviousTripsForSameCustomerByDC(string VehicleId)
        {
            string query = "select i.CustomerCode from vehicledctrip v " +
                         " join customerdcassign c on c.DCTripId=v.Id " +
                         " join customerinfo i on i.customerId=c.CustomerId" +
                         " where v.VehicleID='" + VehicleId + "' and v.IsTripEnds=0 limit 1";
            string customercode = "";
            object result = dbx.executeScalar(query);
            if (result != null)
            {
                customercode = result.ToString();

            }
            query = "select distinct vd.*,cd.DeliveredOn,i.Name from vehicledctrip vd" +
                           " join customerdcassign  cd on  vd.id=cd.DCTripId" +
                           " join customerinfo i on i.customerId=cd.CustomerId" +
                           " and (i.CustomerCode in (select customerid from customerroute where routeid=(select distinct c.routeid from customerroute c where c.customerid='" + customercode + "' limit 1)) or i.CustomerCode ='" + customercode + "')" +
                           " where vd.VehicleID='" + VehicleId + "' and vd.IsTripEnds=1" +
                           " order by vd.TripEndsOn desc limit 10";
            DataTable dt = dbx.executeQuery(query).Tables[0];
            return dt;
        }


