        public DataTable VehiclesForDCTrip(string AccountId, string user, string type)
        {

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("user", user);
            string query = "select p.minlatitude,p.minlongitude from plantlogin l join plantgeolocations p on p.password=l.customerid";
            if (type == "plant")
                query += " where l.Plant=?";
            else
                query += " where l.login=?";
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            lParameter.Clear();
            //if no plant is assigned taking default plant
            if (dt == null || dt.Rows.Count == 0)
            {
                query = "select p.minlatitude,p.minlongitude from plantlogin l join plantgeolocations p on p.password=l.customerid where l.login='default'";
                dt = dbx.executeQuery(query).Tables[0];
            }
            if (dt.Rows.Count > 0)
            {
                DateTime ts = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()).AddHours(-5);
                query = "select distinct a.truckid,ti.Name as `Transporter`,a.timestamp,a.latitude,a.longitude,v.positiontxt,d.DateTime," +
                        " d.IsTripEnds,r.direction,i.Name,i.CustomerCode,cd.IsDelivered,t.RTKm,vi.TypeOfVehicle,vi.Plant from lastupdtdata a " +
                        " join vehiclepositiontxt v on a.truckid=v.truckid" +
                        " join vehicles g on g.VehicleId=a.truckid and g.AccountId=? " +
                        " join vehiclesgroupsmap vg on vg.VehicleId=a.truckid and vg.GroupId='9'" +
                        " left join vehicleroutesummary r on r.vehicleid=a.truckid " +
                        " left join vehicledctrip d on d.id=(select max(id) from vehicledctrip where vehicleid=a.truckid)" +
                        " left join customerdcassign cd on cd.id=(select max(id) from customerdcassign where DCTripId=d.id)" +
                        " left join customerinfo i on i.customerId=cd.CustomerId" +
                        " left join vehicleinfo vi on vi.VehicleId=g.VehicleId" +
                        " left join transporterinfo ti on vi.Transporter = ti.TransporterId" +
                        " left join plantlogin pl on pl.login=d.AddedBy" +
                        " left join roundtriptime t on t.Plant=pl.Plant and t.CustomerCode=i.CustomerCode" +
                        " where (d.DateTime<=? or d.IsTripEnds=1) and abs(a.latitude-?)<0.1 and abs(a.longitude-?)<0.1" +
                        " and a.timestamp>? order by t.RTKm";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("AccountId", AccountId);
                lParameter.Add("DateTime", formatDBDate(ts));
                lParameter.Add("latitude", dt.Rows[0]["minlatitude"].ToString());
                lParameter.Add("longitude", dt.Rows[0]["minlongitude"].ToString());
                lParameter.Add("timestamp", formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()).AddDays(-15)));

                DataTable ds = dbx.executeQuery(query, lParameter).Tables[0];
                return ds;
            }
            return null;
        }
        public DataTable GetCurrentMonthTripRTKM(string vehicleid)
        {
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()).AddDays(-1);
            DateTime startDate = new DateTime(now.Year, now.Month, 1);
            DateTime endDate = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()).AddDays(1);

            string query = "select d.VehicleID,d.DateTime,d.AddedBy,i.Name,cd.Quantity,i.CustomerCode,t.RTKm from vehicledctrip d" +
                           " left join customerdcassign cd on cd.id=(select max(id) from customerdcassign where DCTripId=d.id)" +
                           " left join customerinfo i on i.customerId=cd.CustomerId" +
                           " left join plantlogin pl on pl.login=d.AddedBy" +
                           " left join roundtriptime t on t.Plant=pl.Plant and t.CustomerCode=i.CustomerCode" +
                           " where d.VehicleID=? and d.DateTime>=? and d.DateTime<=? order by d.DateTime desc";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleid", vehicleid);
            lParameter.Add("startDate", formatDBDate(startDate));
            lParameter.Add("endDate", formatDBDate(endDate));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public string InsertVehicleInPlantDetails(String vehicleId, String locationStr, int plantType, DateTime vehTs, string configtimeZoneStr = "")
        {
            string query = string.Empty;
            String maxTs = formatDBDate(vehTs);
            string result = string.Empty;
            int TimeZone = GetTimeZoneDiff();

            DateTime IndianTime = DateTime.UtcNow;

            IndianTime = IndianTime.AddSeconds(TimeZone);
            // Deciding late arrival data or not, if it is more 5 mins late data condsidering late data by comparing utc time with vehTs
            // Taking 5 mins threshold to avoid running every time block of code.
            // For sequence of data, it will run narmolly.
            int TotalMinutes = Convert.ToInt32(IndianTime.Subtract(vehTs).TotalMinutes);

            if (TotalMinutes >= 2) //To reduce immedidate in/out because of late data. 
            {                      //Before leaving the geofence area device will stop updating and after some time it will start updating
                //Alredy vehicle in details inserted, to reduce immedidate in/out checking 2 mins late data
                if (TotalMinutes > 5)
                {
                    result = "Inside 5 Minute block";
                    string CheckVehicleInsidePlantOrNot = string.Empty;
                    CheckVehicleInsidePlantOrNot = "select max(v.intimestamp) from vehicleinplant v where v.vehicleid='" + vehicleId + "' and " +
                                                   "v.locationstr='" + locationStr + "' and v.outtimestamp is null";
                    object InTime = dbx.executeScalar(CheckVehicleInsidePlantOrNot);

                    if (!InTime.Equals(System.DBNull.Value))
                    {
                        DateTime VehicleInTime = Convert.ToDateTime(InTime);
                        int IsLesserInTime = vehTs.CompareTo(VehicleInTime);
                        if (IsLesserInTime < 0)
                        {
                            //Already vehicle in entry is there.Here just going to update intime of vehicle.
                            string UpdateInTime = "update vehicleinplant v set v.intimestamp='" + maxTs + "' where v.vehicleid='" + vehicleId + "' and v.locationstr='" + locationStr + "' and v.intimestamp='" + formatDBDate(VehicleInTime) + "'";
                            int IsSuceess = dbx.executeNonQuery(UpdateInTime);
                            //return "Because of late arrival data updating Actual Intime ";
                            return "";
                        }
                    }
                    else
                    {
                        string AddVehicleInPlantData = string.Empty;
                        AddVehicleInPlantData = "select v.intimestamp,v.outtimestamp from vehicleinplant v where v.vehicleid='" + vehicleId + "'" +
                                                "and v.locationstr='" + locationStr + "' order by v.intimestamp desc limit 1";
                        DataTable FetchingPreviousData = dbx.executeQuery(AddVehicleInPlantData).Tables[0];
                        if (FetchingPreviousData.Rows.Count > 0)
                        {
                            DateTime PreDataIntime = Convert.ToDateTime(FetchingPreviousData.Rows[0][0].ToString());
                            DateTime PreDataOuttime = Convert.ToDateTime(FetchingPreviousData.Rows[0][1].ToString());
                            int InTimeStamp = vehTs.CompareTo(PreDataIntime);
                            int OutTimeStamp = vehTs.CompareTo(PreDataOuttime);
                            //Here comparing previous record intime and outtime with time to insert data or not
                            if (InTimeStamp > 0 && OutTimeStamp < 0)
                            {
                                //Dont insert record because already record is present in vehicleinplant table between the time
                                //return "Dont insert";
                                return "";
                            }
                            else
                            {
                                //There is no record between the time,here new data going to insert vehicleinplant table
                                query = "insert into vehicleinplant(vehicleid,locationstr,reportstatus,planttype,intimestamp) values('" + vehicleId +
                                         "','" + locationStr + "',0," + plantType + ",'" + maxTs + "')";
                                dbx.executeNonQuery(query);
                                //return "Because of late arrival data inserting new record ";
                                return "";
                            }
                        }
                        else
                        {
                            query = "insert into vehicleinplant(vehicleid,locationstr,reportstatus,planttype,intimestamp) values('" + vehicleId +
                                         "','" + locationStr + "',0," + plantType + ",'" + maxTs + "')";
                            dbx.executeNonQuery(query);
                            //return "Inserting new record";
                            return "";

                        }
                    }
                    //return "Inside 5 Minute block";
                    return "";
                }
                return "";
            }
            //enter new record only if previous point outtime is done.
            query = "select count(1) from vehicleinplant where vehicleId = '" + vehicleId + "'" +
                    " and  outtimestamp is NULL and locationstr = '" + locationStr + "'";
            Object countObj = dbx.executeScalar(query);
            int numEnt = Convert.ToInt32(countObj);
            if (numEnt == 0)
            {
                DateTime insInTime = Convert.ToDateTime(maxTs);
                query = string.Empty;
                query = "select * from vehicleinplant where vehicleid=? and locationstr=? and plantType=? and outtimedone=1 order by outtimestamp desc limit 1;";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", vehicleId);
                lParameter.Add("locationstr", locationStr);
                lParameter.Add("plantType", plantType);
                DataTable lastupdate = dbx.executeQuery(query, lParameter).Tables[0];
                DateTime LastOutTime = insInTime;
                if (lastupdate.Rows.Count > 0)
                {
                    LastOutTime = Convert.ToDateTime(lastupdate.Rows[0]["outtimestamp"]);
                }
                if (insInTime >= LastOutTime)
                {
                    query = string.Empty;
                    query = "insert into vehicleinplant(vehicleid,locationstr,reportstatus,planttype,intimestamp) values('" + vehicleId +
                        "','" + locationStr + "',0," + plantType + ",'" + maxTs + "')";
                    dbx.executeNonQuery(query);
                }
            }
            return "";
        }

