        public DataTable GetDriverChecklistReport(string fromDate, string toDate, int groupid)
        {
            string query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromDate", fromDate);
            lParameter.Add("toDate", toDate);
            lParameter.Add("fromstartTime", fromDate);
            lParameter.Add("tostartTime", toDate);
            lParameter.Add("groupid", groupid);
            query = "select di.Name,di.AssignedVehicleId,t.Name as 'Transporter',max(dc.DateTime) as Datetime,dc.EngineOil,dc.CoolantLevel,dc.WaterSeperator,dc.EDCWarningLight," +
                    "dc.VaccumIndicator,dc.TyrePressure,dc.WheelNuts,dc.TyreWear,dc.Gauges,dc.Wiper,dc.CabinLights,dc.WaterLevel,dc.Battery,dc.Photos,w.startTime, w.endTime, (CASE WHEN w.startTime IS NULL AND w.endTime IS NULL THEN '' WHEN w.endTime IS NULL THEN 'Driver Not Ended endTime' WHEN TIMEDIFF(w.endTime, w.startTime) > '12:00:00' THEN 'Exceeded more than 12 hours' ELSE CONCAT(HOUR(TIMEDIFF(w.endTime, w.startTime)), ' hours ', MINUTE(TIMEDIFF(w.endTime, w.startTime)), ' minutes ', SECOND(TIMEDIFF(w.endTime, w.startTime)), ' seconds') END) AS 'TotalWorkTime' " +
                    "from driverinfo di " +
                    "join vehiclesgroupsmap vi on vi.VehicleId=di.AssignedVehicleId " +
                    "left join transporterinfo t ON t.TransporterId=di.Transporter " +
                    "inner join driverchecklists dc on dc.Driverid=di.DriverId " +
                    "LEFT JOIN workdonedata w ON w.DriverId = di.DriverId AND DATE(w.startTime) = DATE(dc.DateTime) AND w.startTime BETWEEN ? AND ? " +
                    "where dc.Datetime between ? and ? and vi.GroupId=? " +
                    "group by di.DriverId,date(dc.DateTime)";//Modified by Zoya on 27/7/2023 As there was a issue that workstarttime was not avaliable for some drivers
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            if (dt.Rows.Count > 0)
                return dt;
            else
                return null;
        }

