        /// <summary>
        /// Showig the customer current stock level
        /// Modified Details : Added the custState parameter to the method default active and In Query where condition inside added customer state
        /// Modifed by Harish on 31/08/2020
        /// </summary>
        /// <param name=""></param>
        /// <returns></returns>
        public DataSet GetCustomerCurrentStockLevel(string CustomerId, string accountid, string CustomerType, string addedBy, string CustomerState)
        {
            string Query = string.Empty;
            CustomerState = CustomerState.Replace(" ", string.Empty).ToLower();
            var lParameter = new Dictionary<string, object>();
            if (CustomerId == "All")
            {
                Query = "select i.Name,i.CustomerCode,t.StockLevel,t.Next3DaysExpected,t.timestamp,i.SafeLevel,i.`Storage`,i.CustomerType," +
                        " DATE_ADD(t.timestamp,INTERVAL (t.StockLevel/(Next3DaysExpected/3)) DAY) as Next,a.Quantity,v.DateTime, i.customerId,'0' as OnTransit,t.AddedBy,i.ExecutiveName as SalesPerson " +
                        " from customerinfo i" +
                        " left join customerstock t  on t.CustomerId=i.customerId and t.timestamp=(select Max(timestamp) from customerstock where CustomerId=i.customerId";
                if (addedBy == "System")
                    Query += " and AddedBy='System'";
                else
                    Query += " and AddedBy!='System'";
                Query += ") left join customerdcassign a  on a.CustomerId=i.customerId  and a.id=(select Max(Id) from customerdcassign where CustomerId=i.CustomerId)" +
                  " left join vehicledctrip v  on v.id=a.DCTripId  where i.AccountId=?";
                lParameter.Add("AccountId", accountid);
                if (CustomerType == "All")
                    Query += " and i.CustomerType in ('STK','BOOM / BOOT','ALDS','PACKED','COMMODITY','Other')";
                else
                {
                    // Query += " and i.CustomerType='" + CustomerType + "'";
                    Query += " and i.CustomerType=?";
                    lParameter.Add("CustomerType", CustomerType);
                }
                // added conditions for filter customer based on customer state
                if (CustomerState == "active")
                {
                    Query += " and i.Active=1";
                }
                else if (CustomerState == "inactive")
                {
                    Query += " and i.Active=0";
                }
                Query += " group by i.customerId order by t.timestamp desc";
            }
            else
            {
                lParameter.Clear();
                Query = "select i.Name,i.CustomerCode,t.StockLevel,t.Next3DaysExpected,t.timestamp,i.SafeLevel,i.`Storage`,i.CustomerType,i.ExecutiveName as SalesPerson," +
                        " DATE_ADD(t.timestamp,INTERVAL (t.StockLevel/(Next3DaysExpected/3)) DAY) as Next,a.Quantity,v.DateTime, i.customerId,0 as OnTransit" +
                        " from customerinfo i" +
                        " left join customerstock t  on t.CustomerId=i.customerId and t.timestamp=(select Max(timestamp) from customerstock where CustomerId=i.customerId";
                if (addedBy == "System")
                    Query += " and AddedBy='System'";
                else
                    Query += " and AddedBy!='System'";
                Query += ") left join customerdcassign a  on a.CustomerId=i.customerId  and a.id=(select Max(Id) from customerdcassign where CustomerId=i.CustomerId)" +
                        " left join vehicledctrip v  on v.id=a.DCTripId" +
                        " where i.customerId=?" +
                        " group by i.customerId";
                lParameter.Add("customerId", CustomerId);
            }
            return dbx.executeQuery(Query.ToString(), lParameter);
        }
