        public int UpdateCustomerCurrentStocklevel(string customercode, string quantity, string date, string next3daysexpected, string addedby)
        {
            string Query = string.Empty;
            Query = "select ci.customerid from customerinfo ci where ci.customercode=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("customercode", customercode);
            object obj = dbx.executeScalar(Query, lParameter);
            bool notExists = true;
            if (obj != null)
            {
                string customerid = obj.ToString();
                if (addedby == "System")
                {
                    //in api next 3 days consumption won't be there. So system picking last Next3DaysExpected value
                    Query = "select c.Next3DaysExpected from customerstock c where c.CustomerId=? order by c.Id desc limit 1";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("customerid", customerid);
                    obj = dbx.executeScalar(Query, lParameter);
                    if (obj != null)
                        next3daysexpected = obj.ToString();
                    //api giving same data that data is ignoring by datatime
                    Query = "select c.timestamp from customerstock c where c.CustomerId=? and c.AddedBy=? order by c.Id desc limit 1";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("customerid", customerid);
                    lParameter.Add("AddedBy", addedby);
                    obj = dbx.executeScalar(Query, lParameter);
                    if (obj != null && Convert.ToDateTime(obj) == Convert.ToDateTime(date))
                        notExists = false;
                }
                if (notExists)
                {
                    Query = "INSERT INTO `customerstock` (`CustomerId`, `StockLevel`, `timestamp`, `Next3DaysExpected`, `AddedBy`) VALUES (?, ?, ?, ?, ?);";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("CustomerId", customerid);
                    lParameter.Add("StockLevel", quantity);
                    lParameter.Add("timestamp", formatDBDate(Convert.ToDateTime(date)));
                    lParameter.Add("Next3DaysExpected", next3daysexpected);
                    lParameter.Add("AddedBy", addedby);
                    return dbx.executeNonQuery(Query, lParameter);
                }
                return 0;
            }
            else
                return 0;
        }

        public string UpdateCustomerCurrentStocklevelNew(string customercode, string quantity, string date, string next3daysexpected, string addedby)
        {
            try
            {
                string Query = string.Empty;
                Query = "select ci.customerid,ci.`Storage` from customerinfo ci where ci.customercode='" + customercode + "'";
                DataTable obj = dbx.executeQuery(Query).Tables[0];
                string customerid = obj.Rows[0]["customerid"].ToString();
                string storage = obj.Rows[0]["Storage"].ToString();
                if ((!string.IsNullOrEmpty(storage) && Convert.ToDouble(storage) >= Convert.ToDouble(quantity)) || string.IsNullOrEmpty(storage))
                {
                    string now = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
                    Query = "INSERT INTO `customerstock` (`CustomerId`, `StockLevel`, `timestamp`, `Next3DaysExpected`, `AddedBy`) VALUES (" + customerid + ", " + quantity + ", '" + date + "', " + next3daysexpected + ", '" + addedby + "');";
                    int res = dbx.executeNonQuery(Query);
                    if (res > 0)
                        return "Successfully Updated";
                    else
                        return "Failed to update";
                }
                else
                {
                    return "Current stock level entry is more than storage capacity(" + storage + "MT)";
                }
            }
            catch (Exception ex)
            {
                STL_RecordErrorMessage("UpdateCustomerCurrentStocklevelNew_" + customercode + "_" + ex.ToString());
                return "Server Error";
            }
        }

