        //Checking vheicle inside the irregular geofecne or not
        public DataTable GetAllGeofencePolygonByLatLng(DataTable dt, double Latitude, double Longitude)
        {
            DataTable PolygonGeofence = new DataTable();
            //To copy data from one table to another table
            PolygonGeofence = dt.Clone();

            foreach (DataRow row in dt.Rows)
            {
                ArrayList polyX = new ArrayList();
                ArrayList polyY = new ArrayList();
                bool IsVehicleInside = false;

                for (int k = 10; k < row.ItemArray.Length;)
                {
                    if (!string.IsNullOrEmpty(row.ItemArray[k].ToString()))
                    {
                        polyX.Add(row.ItemArray[k]);
                        polyY.Add(row.ItemArray[k + 1]);
                    }
                    k = k + 2;
                }

                double x = Latitude;
                double y = Longitude;

                int i, j = polyX.Count - 1;

                for (i = 0; i < polyX.Count; i++)
                {
                    if (Convert.ToDouble(polyY[i]) < y && Convert.ToDouble(polyY[j]) >= y
                    || Convert.ToDouble(polyY[j]) < y && Convert.ToDouble(polyY[i]) >= y)
                    {
                        if (Convert.ToDouble(polyX[i]) + (y - Convert.ToDouble(polyY[i])) /
                            (Convert.ToDouble(polyY[j]) - Convert.ToDouble(polyY[i])) *
                            (Convert.ToDouble(polyX[j]) - Convert.ToDouble(polyX[i])) < x)
                        {
                            IsVehicleInside = !IsVehicleInside;
                        }
                    }
                    j = i;
                }
                if (IsVehicleInside == true)
                {
                    PolygonGeofence.ImportRow(row);
                }
            }
            return PolygonGeofence;
        }

        public bool pointIsInPoly(double lat, double lng, double[] latArr, double[] lngArr)
        {
            bool isInside = false;
            double minX = latArr[0];
            double maxX = latArr[0];
            double minY = lngArr[0];
            double maxY = lngArr[0];
            for (var n = 1; n < lngArr.Length; n++)
            {
                minX = Math.Min(latArr[n], minX);
                maxX = Math.Max(latArr[n], maxX);
                minY = Math.Min(lngArr[n], minY);
                maxY = Math.Max(lngArr[n], maxY);
            }

            if (lat < minX || lat > maxX || lng < minY || lng > maxY)
            {
                return false;
            }

            int i = 0;
            int j = latArr.Length - 1;
            for (; i < latArr.Length; j = i++)
            {
                if ((lngArr[i] > lng) != (lngArr[j] > lng) &&
                        lat < (latArr[j] - latArr[i]) * (lng - lngArr[i]) / (lngArr[j] - lngArr[i]) + latArr[i])
                {
                    isInside = !isInside;
                }
            }

            return isInside;
        }

