        //for driver custom notification
        public int AddCCMNotifications(string loginId, string Subject, string Detail, Int16 priority = 0)
        {
            string date = formatDBDate(System.DateTime.Now);
            string query = "";
            int rows = 0;
            loginId = loginId.Replace("'", "");
            var lParameter = new Dictionary<string, object>();

            if (!loginId.Contains(",") && loginId != "ALL")
            {
                query = "INSERT INTO `ccmnotification` (`LoginId`, `Subject`, `Info`, `Datetime`, `Isnotified`, `Priority`) VALUES (?,?,?,?,?,?);";
                lParameter.Add("LoginId", loginId);
                lParameter.Add("Subject", Subject);
                lParameter.Add("Detail", Detail);
                lParameter.Add("date", date);
                lParameter.Add("Isnotified", 0);
                lParameter.Add("priority", priority);
                rows = dbx.executeNonQuery(query, lParameter);
            }
            else if (loginId.Contains(",") && loginId != "ALL")
            {
                string[] logins = loginId.Split(',');
                for (int i = 0; i < logins.Length; i++)
                {
                    lParameter.Clear();
                    lParameter.Add("Loginids", logins[i]);
                    lParameter.Add("Subject", Subject);
                    lParameter.Add("Detail", Detail);
                    lParameter.Add("date", date);
                    lParameter.Add("Isnotified", 0);
                    lParameter.Add("priority", priority);
                    query = "INSERT INTO `ccmnotification` (`LoginId`, `Subject`, `Info`, `Datetime`, `Isnotified`, `Priority`) VALUES (?,?,?,?,?,?);";
                    rows += dbx.executeNonQuery(query, lParameter);
                }
            }
            else if (loginId == "ALL")
            {
                query = "select d.CustomerCode from customerinfo d" +
                " where d.AccountId=9";
                DataSet ds = dbx.executeQuery(query);
                for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
                {
                    lParameter.Clear();
                    lParameter.Add("Login", ds.Tables[0].Rows[i][0]);
                    lParameter.Add("Subject", Subject);
                    lParameter.Add("Detail", Detail);
                    lParameter.Add("date", date);
                    lParameter.Add("Isnotified", 0);
                    lParameter.Add("priority", priority);
                    query = "INSERT INTO `ccmnotification` (`LoginId`, `Subject`, `Info`, `Datetime`, `Isnotified`, `Priority`) VALUES (?,?,?,?,?,?);";
                    rows += dbx.executeNonQuery(query, lParameter);
                }
            }
            return rows;
        }

        //Passenger App custom Notifications
        public int AddPsngrNotifications(string PsngrId, string Subject, string Detail, string SessionId, string MobileNos = "", string vehicleid = "")
        {
            string date = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
            string query = "";
            int rows = 0;
            PsngrId = PsngrId.Replace("'", "");
            DataTable tokens = new DataTable();
            if (!string.IsNullOrEmpty(MobileNos))
            {
                query = "INSERT INTO `psngr_notifications` (`PsngrId`, `Subject`, `Info`, `DateTime`) " +
                        "select PsngrId,'" + Subject + "','" + Detail + "','" + date + "' from psngr_info a where a.Active=1 and a.MobileNo in (" + MobileNos + ")";
                rows = dbx.executeNonQuery(query);
                query = "select distinct f.Token from psngr_info p join otp_sessions o on p.PsngrId=o.userid join firebase_tokens f on f.Login=o.sessionid where "
                    + "p.Active=1 and p.MobileNo in (" + MobileNos + ")";
                tokens = dbx.executeQuery(query).Tables[0];
            }
            else if (!string.IsNullOrEmpty(vehicleid) && PsngrId != "SpecificVehicle")
            {
                query = "INSERT INTO `psngr_notifications` (`PsngrId`, `Subject`, `Info`, `DateTime`) " +
                       "select PsngrId,'" + Subject + "','" + Detail + "','" + date + "' from psngr_info a where a.Active=1 and a.AssignedVehicleId='" + vehicleid + "'";
                rows = dbx.executeNonQuery(query);
                query = "select distinct f.Token from psngr_info p join otp_sessions o on p.PsngrId=o.userid join firebase_tokens f on f.Login=o.sessionid where "
                    + "p.Active=1 and p.AssignedVehicleId='" + vehicleid + "'";
                tokens = dbx.executeQuery(query).Tables[0];
            }
            else if (PsngrId == "AddAll")
            {
                string user = System.Web.HttpContext.Current.Session["UserName"].ToString();
                DataTable dt = GetPassengerInfo(SessionId, "SchVehTrck", user);
                string psngrids = "";
                query = "INSERT INTO `psngr_notifications` (`PsngrId`, `Subject`, `Info`, `DateTime`) VALUES ";
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    query += "(" + dt.Rows[i]["PsngrId"] + ", '" + Subject + "', '" + Detail + "', '" + date + "')";
                    psngrids += dt.Rows[i]["PsngrId"];
                    if (i != dt.Rows.Count - 1)
                    {
                        query += ",";
                        psngrids += ",";
                    }
                }
                rows = dbx.executeNonQuery(query);
                query = "select distinct f.Token from psngr_info p join otp_sessions o on p.PsngrId=o.userid join firebase_tokens f on f.Login=o.sessionid where "
                    + "p.Active=1 and p.PsngrId in (" + psngrids + ")";
                tokens = dbx.executeQuery(query).Tables[0];
            }
            else if (PsngrId == "SpecificVehicle")
            {
                if (!string.IsNullOrEmpty(vehicleid))
                {
                    string user = System.Web.HttpContext.Current.Session["UserName"].ToString();
                    string psngrids = "";
                    query = "INSERT INTO `psngr_notifications` (`PsngrId`, `Subject`, `Info`, `DateTime`) VALUES ";
                    DataTable Psnger = GetSpecificVehiclePassInfo(vehicleid, SessionId);
                    for (int i = 0; i < Psnger.Rows.Count; i++)
                    {
                        query += "(" + Psnger.Rows[i]["PsngrId"] + ", '" + Subject + "', '" + Detail + "', '" + date + "')";
                        psngrids += Psnger.Rows[i]["PsngrId"];
                        if (i != Psnger.Rows.Count - 1)
                        {
                            query += ",";
                            psngrids += ",";
                        }
                    }
                    rows = dbx.executeNonQuery(query);
                    query = "select distinct f.Token from psngr_info p join otp_sessions o on p.PsngrId=o.userid join firebase_tokens f on f.Login=o.sessionid where "
                        + "p.Active=1 and p.PsngrId in (" + psngrids + ")";
                    tokens = dbx.executeQuery(query).Tables[0];
                }
            }
            else if (!PsngrId.Contains(","))
            {
                query = "INSERT INTO `psngr_notifications` (`PsngrId`, `Subject`, `Info`, `DateTime`) VALUES (" + PsngrId + ", '"
                      + Subject + "', '" + Detail + "', '" + date + "');";
                rows = dbx.executeNonQuery(query);
                query = "select distinct f.Token from psngr_info p join otp_sessions o on p.PsngrId=o.userid join firebase_tokens f on f.Login=o.sessionid where "
                    + "p.Active=1 and p.PsngrId in (" + PsngrId + ")";
                tokens = dbx.executeQuery(query).Tables[0];
            }
            else
            {
                string[] psngrs = PsngrId.Split(',');
                query = "INSERT INTO `psngr_notifications` (`PsngrId`, `Subject`, `Info`, `DateTime`) VALUES ";
                string psngrids = "";
                for (int i = 0; i < psngrs.Length; i++)
                {
                    query += "(" + psngrs[i] + ", '" + Subject + "', '" + Detail + "', '" + date + "')";
                    psngrids += psngrs[i];
                    if (i != psngrs.Length - 1)
                    {
                        psngrids += ",";
                        query += ",";
                    }
                }
                rows = dbx.executeNonQuery(query);
                query = "select distinct f.Token from psngr_info p join otp_sessions o on p.PsngrId=o.userid join firebase_tokens f on f.Login=o.sessionid where "
                    + "p.Active=1 and p.PsngrId in (" + psngrids + ")";
                tokens = dbx.executeQuery(query).Tables[0];
            }
            SendNotificationFromFirebaseCloud(tokens, Detail, Subject);
            return rows;
        }
        public DataTable GetGatePassVehicles(string login)
        {
            DataTable vehicles = new DataTable();
            StringBuilder query = new StringBuilder();
            query.Append("SELECT * FROM (select Distinct v.VehicleId,vi.Capacity from vehiclesgroupsmap v left JOIN ");
            query.Append(" vehicleinfo vi on v.VehicleId=vi.VehicleId join vehicles vs on vs.VehicleID=v.VehicleId ");
            query.Append(" WHERE v.GroupId IN (SELECT u.GroupId FROM usersgroupsmap u WHERE u.Login IN (SELECT c.LoginUser FROM customerinfo c WHERE c.customerId IN ");
            query.Append(" (SELECT c.CustomerId FROM dc_source_destination_mapping c WHERE c.UserLogin=?))) ORDER BY v.VehicleId) d ");
            query.Append(" UNION select VehicleID,'' As Capacity from useraddedvehicle u WHERE u.AddedBy=?;");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("login1", login);
            lParameter.Add("login2", login);
            vehicles = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            return vehicles;
        }

        public void SendNotificationFromFirebaseCloud(DataTable tokens, string body, string title)
        {
            for (int i = 0; i < tokens.Rows.Count; i++)
            {
                try
                {
                    if (string.IsNullOrEmpty(tokens.Rows[i]["Token"].ToString()))
                    {
                        WebRequest tRequest = WebRequest.Create("https://fcm.googleapis.com/fcm/send");
                        tRequest.Method = "post";
                        //serverKey - Key from Firebase cloud messaging server  
                        tRequest.Headers.Add(string.Format("Authorization: key={0}", "AAAA4nn2yNs:APA91bGL9LeGa2imguFvxXR0a271WzKyDqihsiYv3z8DImgAsbaHwTQD37HQwXwYjDkAoTBfqMFZhYENVU0t_O_kpLF17OXKOazn7jEoRt5j88G4qALQJEX8aE7G8IsuCahi873apqADt1_neIvaqKS1Z7BA3ahl2g"));
                        //Sender Id - From firebase project setting  
                        tRequest.Headers.Add(string.Format("Sender: id={0}", "972708825307"));
                        tRequest.ContentType = "application/json";
                        var payload = new
                        {
                            to = tokens.Rows[i]["Token"].ToString(),
                            priority = "high",
                            content_available = true,
                            notification = new
                            {
                                body = body,
                                title = title,
                                badge = 1
                            },
                        };

                        string postbody = JsonConvert.SerializeObject(payload).ToString();
                        Byte[] byteArray = Encoding.UTF8.GetBytes(postbody);
                        tRequest.ContentLength = byteArray.Length;
                        using (Stream dataStream = tRequest.GetRequestStream())
                        {
                            dataStream.Write(byteArray, 0, byteArray.Length);
                            using (WebResponse tResponse = tRequest.GetResponse())
                            {
                                using (Stream dataStreamResponse = tResponse.GetResponseStream())
                                {
                                    if (dataStreamResponse != null) using (StreamReader tReader = new StreamReader(dataStreamResponse))
                                        {
                                            String sResponseFromServer = tReader.ReadToEnd();
                                            //result.Response = sResponseFromServer;
                                        }
                                }
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    ex.ToString();
                }
            }
        }

