        public int InsertJrmResponse(string IMEI, string cur_latlng, string response, string jrmType, string Latlng, string isNightZone)
        {
            int result = 0;
            string Query = string.Empty;
            string datetime = formatDBDate(DateTime.Now);
            Query = "select DriverId,AssignedVehicleid from driverinfo di where di.IMEI=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("IMEI", IMEI);
            DataTable dt = dbx.executeQuery(Query, lParameter).Tables[0];
            if (dt.Rows.Count > 0)
            {
                string _driverid = dt.Rows[0][0].ToString();
                string _vehicle = dt.Rows[0][1].ToString();
                string _today = DateTime.Now.ToString("yyyy-MM-dd");
                Query = "select Id from jrmDriverResponse j " +
                     "where j.DriverId=? and date(j.Timestamp)=? and Latlng=POINT(" + Latlng + ") ";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("DriverId", _driverid);
                lParameter.Add("Timestamp", _today);
                object id = dbx.executeScalar(Query, lParameter);
                if (id != null)
                {
                    Query = "UPDATE jrmDriverResponse j set CuLatlng=POINT(" + cur_latlng + "),Response=?,Timestamp=? where id=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Response", response);
                    lParameter.Add("Timestamp", datetime);
                    lParameter.Add("id", datetime);
                }
                else
                {
                    Query = "INSERT INTO `jrmDriverResponse` (`DriverId`, `VehicleId`,`Timestamp`, `CuLatlng`, `Response`, `JrmType`, `Latlng`, `NightZone`) VALUES "
                        + "(?, ?,?, POINT(" + cur_latlng + "), ?, ?, POINT(" + Latlng + "), ?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("DriverId", _driverid);
                    lParameter.Add("VehicleId", _vehicle);
                    lParameter.Add("Timestamp", datetime);
                    lParameter.Add("Response", response);
                    lParameter.Add("JrmType", jrmType);
                    lParameter.Add("NightZone", isNightZone);
                }
                result = dbx.executeNonQuery(Query, lParameter);
            }
            return result;
        }

        public DataTable GetAllViolationByVehicle(string fromDateStr, string toDateStr, string IMEI)
        {
            string query = "select Assignedvehicleid from driverinfo di where di.IMEI='" + IMEI + "'";
            object vehicle = dbx.executeScalar(query);
            if (vehicle != null)
            {
                string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
                query = "select distinct s.vehicleId,s.`type` ,s.remarks,s.duration, concat(s.timestamp) as datetime,s.Location,s.latitude,s.longitude,s.remarks " +
                          " from storevehicleviolations PARTITION(" + part + ") AS s " +
                          " where s.timestamp>='" + fromDateStr + "' and s.timestamp<='" + toDateStr + "' and  s.vehicleId='" + vehicle + "' and s.`type`!='SCHEDULED STOP' and s.`type`!='UNSCHEDULED STOP' and  s.`type`!='LONG REST'  and  s.`type`!='NORMAL' " +
                          " order by s.vehicleId,s.type,s.timestamp";
                return dbx.executeQuery(query).Tables[0];
            }
            return null;
        }

