        /// <summary>
        /// Added by Mallikarjun
        /// </summary>
        /// <param name="sessionId"></param>
        /// <param name="date"></param>
        /// <returns></returns>
        public DataTable getLastPositionsnew(String sessionId, String date)
        {

            String dbEndDate = date;
            string query;
            if (date == null)
            {
                DateTime endDate = DateTime.UtcNow;
                endDate = endDate.AddSeconds(GetTimeZoneDiff(sessionId));
                dbEndDate = formatDBDate(endDate);
            }

            //Check account user
            int groupid = 0;
            groupid = GetAccountUserGroupid(sessionId);
            if (groupid > 0)
            {
                query = "select vehicles.VehicleID, CAST(DATE_FORMAT(lastupdtdata.timestamp, '%d %b %y, %r') as CHAR) as times,lastupdtdata.latitude,lastupdtdata.longitude,lastupdtdata.speed, UNIX_TIMESTAMP(lastupdtdata.timestamp) as unix,vehicles.VehicleInfo, lastupdtdata.id,lastupdtdata.direction,lastupdtdata.BV,vehicles.IconType,lastupdtdata.hvinp,lastupdtdata.gvinp1,vehicles.TempSense,vehicles.OnOffType,lastupdtdata.haltfrom,lastupdtdata.stop ,lastupdtdata.start,lastaccess.ServerTS  " +
                              "from lastupdtdata  inner join vehicles  on lastupdtdata.truckid=vehicles.VehicleID " +
                              "inner join lastaccess on lastaccess.TruckID=lastupdtdata.truckid " +
                              "inner join vehiclesgroupsmap on vehiclesgroupsmap.vehicleid=vehicles.VehicleID " +
                              "where vehiclesgroupsmap.Groupid='" + groupid + "';";
                return dbx.executeQuery(query).Tables[0];
            }

            // Check for a service user groups
            // Find all groups that belong to the service example IOCL
            query = "select servicesgroupsmap.GroupId " +
                  "from rp_users, sessions, servicesgroupsmap " +
                  "where sessions.login = rp_users.login " +
                  "and rp_users.serviceid = servicesgroupsmap.serviceid " +
                  "and sessions.SessionID ='" + sessionId + "';";
            DataTable serviceGroups = dbx.executeQuery(query.ToString()).Tables[0];
            string groupids = "";
            foreach (DataRow row in serviceGroups.Rows)
            {
                groupids = groupids + "vehiclesgroupsmap.GroupId = " + row.ItemArray[0] + " OR ";
            }
            groupids = groupids + " 0";
            if (serviceGroups.Rows.Count > 0)
            {
                query = "select vehicles.VehicleID, CAST(DATE_FORMAT(lastupdtdata.timestamp, '%d %b %y, %r') as CHAR) as times,lastupdtdata.latitude,lastupdtdata.longitude,lastupdtdata.speed, UNIX_TIMESTAMP(lastupdtdata.timestamp) as unix,vehicles.VehicleInfo, lastupdtdata.id,lastupdtdata.direction,lastupdtdata.BV,vehicles.IconType,lastupdtdata.hvinp,lastupdtdata.gvinp1,vehicles.TempSense,vehicles.OnOffType,lastupdtdata.haltfrom,lastupdtdata.stop ,lastupdtdata.start,lastaccess.ServerTS  " +
                        "from lastupdtdata  inner join vehicles  on lastupdtdata.truckid=vehicles.VehicleID " +
                        "inner join lastaccess on lastaccess.TruckID=lastupdtdata.truckid " +
                        "inner join vehiclesgroupsmap on vehiclesgroupsmap.VehicleId=lastupdtdata.truckid " +
                        "where " + groupids + "";
                return dbx.executeQuery(query).Tables[0];
            }
            //check for serviceid users
            int serviceid = 0;
            serviceid = GetServiceId(sessionId);
            if (serviceid > 0)
            {
                query = "select vehicles.VehicleID, CAST(DATE_FORMAT(lastupdtdata.timestamp, '%d %b %y, %r') as CHAR) as times,lastupdtdata.latitude,lastupdtdata.longitude,lastupdtdata.speed, UNIX_TIMESTAMP(lastupdtdata.timestamp) as unix,vehicles.VehicleInfo, lastupdtdata.id,lastupdtdata.direction,lastupdtdata.BV,vehicles.IconType,lastupdtdata.hvinp,lastupdtdata.gvinp1,vehicles.TempSense,vehicles.OnOffType,lastupdtdata.haltfrom,lastupdtdata.stop ,lastupdtdata.start,lastaccess.ServerTS " +
                        "from lastupdtdata  inner join vehicles  on lastupdtdata.truckid=vehicles.VehicleID " +
                        "inner join lastaccess on lastaccess.TruckID=lastupdtdata.truckid " +
                        "inner join servicesVehiclesmap on servicesVehiclesmap.vehicleid=vehicles.VehicleID " +
                        "where servicesVehiclesmap.serviceId='" + serviceid + "'";
                return dbx.executeQuery(query).Tables[0];
            }
            else
            {
                //Get from accountid
                query = "select vehicles.VehicleID, CAST(DATE_FORMAT(lastupdtdata.timestamp, '%d %b %y, %r') as CHAR) as times,lastupdtdata.latitude,lastupdtdata.longitude,lastupdtdata.speed, UNIX_TIMESTAMP(lastupdtdata.timestamp) as unix,vehicles.VehicleInfo, lastupdtdata.id,lastupdtdata.direction,lastupdtdata.BV,vehicles.IconType,lastupdtdata.hvinp,lastupdtdata.gvinp1,vehicles.TempSense,vehicles.OnOffType,lastupdtdata.haltfrom,lastupdtdata.stop ,lastupdtdata.start,lastaccess.ServerTS  " +
                        "from lastupdtdata  inner join vehicles  on lastupdtdata.truckid=vehicles.VehicleID " +
                        "inner join lastaccess on lastaccess.TruckID=lastupdtdata.truckid " +
                        "inner join accounts on accounts.ID=vehicles.AccountID " +
                        "inner join users on users.AccountID=accounts.ID " +
                        "inner join sessions on sessions.login=users.login " +
                        "where sessions.SessionID='" + sessionId + "'";
                return dbx.executeQuery(query).Tables[0];
            }
        }

        public int GetAccountUserGroupid(string sessionId)
        {
            StringBuilder query = new StringBuilder();
            //check account users
            query.Append("select usersgroupsmap.GroupId ");
            query.Append("from users, sessions, usersgroupsmap ");
            query.Append("where sessions.login = users.login ");
            query.Append("and users.login = usersgroupsmap.Login ");
            query.Append("and sessions.SessionID = \"");
            query.Append(sessionId);
            query.Append("\";");
            object obj = dbx.executeScalar(query.ToString());
            if (obj == null)
                return 0;
            else
            {
                try
                {
                    return Convert.ToInt32(obj);
                }
                catch (FormatException ex)
                {
                    return 0;
                }
            }
        }

        public int GetServiceId(string sessionId)
        {
            //service users 
            StringBuilder query = new StringBuilder();
            query.Append("select rp_users.serviceId ");
            query.Append("from rp_users, sessions ");
            query.Append("where sessions.login = rp_users.login ");
            query.Append("and sessions.SessionID = \"");
            query.Append(sessionId);
            query.Append("\" ;");
            return Convert.ToInt16(dbx.executeScalar(query.ToString()));
        }
