        public DataTable GetGatePassDetails(string DCTripId)
        {
            try
            {
                DataTable lVehicleList = new DataTable();
                string query = "select v.DateTime as Date,v.VehicleID as VehicleNumber,c.LoadingPoint,v.DriverName," +
                             " v.InChargeName,v.SecurityName,v.InChargePhoneNo as InchargeNo,c.id as CustomerDCAssignId," +
                             " i.Name as Destination,i.EmailId as CustomerEmailId," +
                             " CONCAT_WS('|',f.AddressLine1,f.AddressLine2,f.AddressLine3,f.City,f.State) as FromAddress," +
                             " CONCAT_WS('|',i.AddressLine1,i.AddressLine2,i.AddressLine3,i.City,i.State) as ToAddress," +
                             " f.TinNo as FromTinNo,i.TinNo as ToTinNo,v.OGPNo,f.EmailId as FromMailId," +
                             " c.IsReverse,v.DriverMobileNo as DriverNo,v.Remarks,v.AddedBy,v.AccountID,v.OTL,i.customerId as DestinationCustomerId,v.EWayBillNo,v.VehicleType " +
                             " from customerdcassign c" +
                             " join vehicledctrip v on v.id=c.DCTripId " +
                             " join customerinfo f on f.customerId=c.SourceId" +
                             " join customerinfo i on i.customerId=c.CustomerId" +
                             " where v.id='" + DCTripId + "'";
                lVehicleList = dbx.executeQuery(query).Tables[0];
                return lVehicleList;
            }
            catch
            {
                return null;
            }

        }

