                        //            vehTbl = dbx.executeQuery(Query).Tables[0];
                        //            if (vehTbl.Rows.Count > 0)
                        //            {
                        //                string loginName = Convert.ToString(GroupId.Split(',')[0]);
                        //                if (!string.IsNullOrEmpty(loginName))
                        //                {
                        //                    if (IsUserAddedVehIsNotExits(VehicleNo, loginName))
                        //                    {
                        //                        Query = "INSERT INTO useraddedvehicle (`VehicleID`, `AccountID`,`AddedBy`) VALUES ('" + VehicleNo + "'," + AccountId + ",'" + loginName + "');";
                        //                        dbx.executeNonQuery(Query);
                        //                    }
                        //                }
                        //            }
                        //        }
                        //    }
                        //    AddTransporterNotifications(GroupId.Split(',')[0], "Vehicle Dispatched From " + LoadingPoint, "Vehicle No: " + VehicleNo + "</br> Total Quantity: " + Qty + "</br> Time: " + now.ToString("dd/MM/yy hh:mm tt"));
                        //}
                        //Gathaering OutPassDetails
                        DataRow lRow = lVehicleList.NewRow();
                        lRow["Date"] = now;
                        lRow["VehicleNumber"] = VehicleNo;
                        lRow["LoadingPoint"] = LoadingPoint;
                        lRow["DriverName"] = DriverName;
                        lRow["InchargeName"] = InchargeName;
                        lRow["SecurityName"] = SecurityName;
                        lRow["InchargeNo"] = InchargeNo;
                        lRow["CustomerDCAssignId"] = CustomerDCAssignId;
                        lRow["Destination"] = Destination;
                        lRow["CustomerEmailId"] = EmailId;
                        lRow["FromAddress"] = FromAdd;
                        lRow["ToAddress"] = ToAdd;
                        lRow["FromTinNo"] = FromTinNo;
                        lRow["ToTinNo"] = ToTinNo;
                        lRow["OGPNo"] = OGPNO;
                        lRow["FromMailId"] = FromMailId;
                        lRow["IsReverse"] = IsReverse;
                        lRow["DriverNo"] = DriverNo;
                        lRow["Remarks"] = Remarks;
                        lRow["OTL"] = OTL;
                        lRow["DestinationCustomerId"] = Cust;
                        lRow["EWayBillNo"] = EWayBillNo;
                        lRow["VehicleType"] = VehicleType;

                        if (SelectedIteams.Split('-').Length > 1)
                        {
                            var qtytList = SelectedIteams.Split(',');
                            if (qtytList.Length > 0)
                            {
                                for (int j = 0; j < qtytList.Length; j++)
