                                            //Adding details to dc_quntityinfo table
                                            var c = qtytList[j].Split('-');
                                            string Id = c[0].Trim().ToString();
                                            //string Name = c[0].Trim().ToString();
                                            string NoOfQty = c[1].Trim().ToString();
                                            Query = "select d.ProductName from dc_productinfo d where d.Id ='" + Id + "';";
                                            string Name = dbx.executeScalar(Query).ToString();
                                            Query = " insert into dc_quntityinfo (Quntity,ProductId,CustomerDCAssignId) values('" + NoOfQty + "','" + Id + "','" + CustomerDCAssignId + "')";
                                            int Result = Convert.ToInt32(dbx.executeNonQuery(Query));
                                            if (Result == 1)
                                            {
                                                if (IsAssetTransation == "1" && (!string.IsNullOrEmpty(CustomerDCAssignId)))
                                                {
                                                    if (Name.ToUpperInvariant().Trim() != "NC")
