                                                DataRow Row = lVehicleList.NewRow();
                                                Row["CustomerDCAssignId"] = "0";
                                                lVehicleList.Rows.Add(Row);
                                                return lVehicleList;
                                            }
                                        }
                                        catch
                                        {
                                            DeleteEntredGatePass(DCTripId, Ids);
                                            lVehicleList.Rows.Clear();
                                            DataRow Row = lVehicleList.NewRow();
                                            Row["CustomerDCAssignId"] = "0";
                                            lVehicleList.Rows.Add(Row);
                                            return lVehicleList;
                                        }
                                    }
                                }
                                lVehicleList.Rows.Add(lRow);
                            }
                            else
                            {
                                //Deleting entred data if anything fails while entring a quanity, this because remove paratically entred data.
                                DeleteEntredGatePass(DCTripId, Ids);
                                //Returning a row with 0 Value, indicates that user entred wrong quantity  
                                lVehicleList.Rows.Clear();
                                DataRow Row = lVehicleList.NewRow();
                                Row["CustomerDCAssignId"] = "0";
                                lVehicleList.Rows.Add(Row);
                                return lVehicleList;
                            }
                        }
                        else
                        {
                            //Deleting entred data if anything fails while entring a quanity, this because remove paratically entred data.
                            DeleteEntredGatePass(DCTripId, Ids);
                            //Returning a row with 0 Value, indicates that user entred wrong quantity  
                            lVehicleList.Rows.Clear();
                            DataRow Row = lVehicleList.NewRow();
                            Row["CustomerDCAssignId"] = "0";
                            lVehicleList.Rows.Add(Row);
                            return lVehicleList;
                        }
                    }
                    return lVehicleList;
                }
                else
                    return null;
            }
            catch (Exception ex)
            {
                //Deleting entred data if anything fails
                DeleteEntredGatePass(DCTripId, Ids);
                lVehicleList.Rows.Clear();
                DataRow Row = lVehicleList.NewRow();
                Row["CustomerDCAssignId"] = "0";
                lVehicleList.Rows.Add(Row);
                STL_RecordErrorMessage(ex.ToString());
                return lVehicleList;
            }

        }
        /// <summary>
        /// Get violation count of particular violation for specified month
        /// </summary>
        /// <param name="vehicleid"></param>
        /// <param name="month"></param>
        /// <param name="vioType"></param>
        /// <returns></returns>
        public string GetViolationCountByVehicle(string driverId, string vioType, string vehicleid, string date)
        {

            StringBuilder query = new StringBuilder();
            query.Append("select count(1) from daywisevehviosummary d ");
            query.Append("where  d." + vioType + "<>'' and month(d.date)=" + DateTime.Now.Month + " and d.driverid='" + driverId + "'");
            int vehicle_cumulative = Convert.ToInt16(dbx.executeScalar(query.ToString()));

            query.Clear();
            //Get cumulative violation of transporter
            query.Append("select count(d.vehicleid) from daywisevehviosummary d ");
            query.Append("where   d." + vioType + "<>'' and d.date>'" + date + "' and  ");
            query.Append("d.vehicleid in(select vehicleid from vehicleinfo ");
            query.Append("where Transporter=(select ti.TransporterId from vehicleinfo vi ");
            query.Append("inner join transporterinfo ti on ti.TransporterId=vi.Transporter where vi.VehicleId='" + vehicleid + "'))");

            int transporter_cumulative = Convert.ToInt32(dbx.executeScalar(query.ToString()));
            return vehicle_cumulative + "," + transporter_cumulative;
        }

        public DataTable GetQuantityByCustomerDCID(string Id)
        {
            string Query = string.Empty;
            Query = "select p.ProductName,q.Quntity,q.ReceivedQuantity,p.Id  from dc_quntityinfo q join dc_productinfo " +
                    "p on q.ProductId=p.Id where q.CustomerDCAssignId=" + Id + "";
            return dbx.executeQuery(Query).Tables[0];
        }

        public string GetHtmlTemplateByUser(string LoginUser, string Type, string templateType = "")
        {
            string SessionId = getSessionIdFromLogin(LoginUser);
            int AccountId = GetAccountId(SessionId);
            string Query = string.Empty;
            Query = "select h.Template from htmltemplate h where h.Type='" + Type + "' and ((h.AccountId='" + AccountId + "' and h.LoginUser is NULL) or h.LoginUser='" + LoginUser + "') ";
            if (!string.IsNullOrEmpty(templateType))
                Query += "and TemplateType='" + templateType + "' ";
            Query += "order by h.LoginUser desc limit 1";
            return dbx.executeScalar(Query).ToString();
        }

