        public DataTable GetSourceDestinationByDCTripId(string DCTripId, string CustomerDCAssignId)
        {
            string Query = string.Empty;
            if (!string.IsNullOrEmpty(CustomerDCAssignId))
                Query = "select cd.id,cd.LoadingPoint,ci.Name,cd.CustomerId,cd.SourceId,(select sum(q.Quntity) from dc_quntityinfo q where " +
                       "q.CustomerDCAssignId=cd.id) as Quantity,cd.IsReverse,cd.DCNo,cd.InvioceVal from customerdcassign cd " +
                       "join customerinfo ci on cd.CustomerId=ci.customerId  where cd.DCTripId='" + DCTripId + "' and cd.id='" + CustomerDCAssignId + "'";
