        }

        public string EditGatePassDetails(string DCTripID, string LoginUser, string VehicleNo, string DriverNo, string DriverName, string InchargeName, string InchargeNo, string SecurityName, List<Object> GatePassDetails, string Remarks, string OTL, string IsAssetTransation, string EWayBillNo, string VehicleType)
        {
            ArrayList Ids = new ArrayList();
            try
            {
                string SessionId = getSessionIdFromLogin(LoginUser);
                int AccountId = GetAccountId(SessionId);
                int timeZone = GetTimeZoneDiff(SessionId);
                DateTime now = DateTime.UtcNow.AddSeconds(timeZone);

                string Query = string.Empty;

                insertauditdata("Edit", "vehicledctrip", "id", DCTripID);
                insertauditdata("Edit", "customerdcassign", "DCTripId", DCTripID);

                Query = "update vehicledctrip dc set dc.VehicleID='" + VehicleNo + "',dc.DateTime='" + formatDBDate(now) + "',dc.AddedBy='" + LoginUser + "'," +
                        "dc.DriverMobileNo='" + DriverNo + "',dc.DriverName='" + DriverName + "',dc.InChargeName='" + InchargeName + "',dc.InChargePhoneNo='" + InchargeNo + "'," +
                        "dc.SecurityName='" + SecurityName + "',Remarks='" + Remarks + "',OTL='" + OTL + "',VehicleType='" + VehicleType + "',EWayBillNo='" + EWayBillNo + "' where dc.id='" + DCTripID + "'";
                string result = dbx.executeNonQuery(Query).ToString();

                string custDCAssignIds = "";
                for (int i = 0; i < GatePassDetails.Count; i++)
                {
                    Type myType = GatePassDetails[i].GetType();
                    System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());

                    try
                    {
                        string cid = props[7].GetValue(GatePassDetails[i], null).ToString();
                        if (!string.IsNullOrEmpty(cid))
                        {
                            custDCAssignIds += props[7].GetValue(GatePassDetails[i], null).ToString() + ",";
                            Ids.Add(cid);
                        }
                    }
                    catch { }
                }
                custDCAssignIds += "0";

                Query = "select id,SourceId from customerdcassign where DCTripId='" + DCTripID + "'";
                DataTable dt = dbx.executeQuery(Query).Tables[0];

                Query = "delete from customerdcassign where DCTripId='" + DCTripID + "' and id not in (" + custDCAssignIds + ")";
                string deltedcutDCs = dbx.executeNonQuery(Query).ToString();
                if (Convert.ToInt32(deltedcutDCs) > 0)
                {
                    // Here deleting asset transaction details, if user deleted details list while editing. 
                    IsCustomerDeleted(DCTripID, custDCAssignIds, dt);
                }

                for (int i = 0; i < GatePassDetails.Count; i++)
                {
                    Type myType = GatePassDetails[i].GetType();
                    System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
                    string LoadingPoint = props[0].GetValue(GatePassDetails[i], null).ToString();
                    string Destination = props[1].GetValue(GatePassDetails[i], null).ToString();
                    string SourceId = props[2].GetValue(GatePassDetails[i], null).ToString();
                    string Cust = props[3].GetValue(GatePassDetails[i], null).ToString();
                    string Qty = props[4].GetValue(GatePassDetails[i], null).ToString();
                    string IsReverse = props[8].GetValue(GatePassDetails[i], null).ToString();
                    string InvoiceVal = "0";
                    string SelectedIteams = props[09].GetValue(GatePassDetails[i], null).ToString();
                    if (SelectedIteams.Split('-').Length > 1)
                    {
                        InvoiceVal = Convert.ToString(props[10].GetValue(GatePassDetails[i], null));
                    }
                    else
                    {
                        SelectedIteams = props[10].GetValue(GatePassDetails[i], null).ToString();
                        InvoiceVal = Convert.ToString(props[09].GetValue(GatePassDetails[i], null));
                    }
                    InvoiceVal = string.IsNullOrEmpty(InvoiceVal) ? "0" : InvoiceVal;

                    string DCNo = "";
                    bool IsAdded = false;
                    try
                    {
                        DCNo = props[5].GetValue(GatePassDetails[i], null).ToString();
                    }
                    catch { }

                    string QuantityInfo = props[6].GetValue(GatePassDetails[i], null).ToString();
                    string CustmoerDcAssignId = "";
                    try
                    {
                        CustmoerDcAssignId = props[7].GetValue(GatePassDetails[i], null).ToString();
                    }
                    catch { }

                    //Possiablity is here both can happen Add and Edit the details, deciding add or edit depend on customerdcassignid
                    if (!string.IsNullOrEmpty(CustmoerDcAssignId))
                    {
                        // Here deleting asset transaction because if source is changed there is no asset transaction for previous source
                        if (IsAssetTransation == "1")
                        {
                            Query = "select cd.SourceId from customerdcassign cd where cd.id='" + CustmoerDcAssignId + "'";
                            string CustSourceId = Convert.ToString(dbx.executeScalar(Query));
                            if (CustSourceId != SourceId)
                            {
                                DeleteTransactionAssetByDcAssignId(CustmoerDcAssignId, CustSourceId);
                            }
                        }

                        Query = "update customerdcassign cd set cd.DCNo='" + DCNo + "',cd.Quantity='" + Qty + "',SourceId='" + SourceId + "',cd.CustomerId='" + Cust + "'," +
                        "cd.LoadingPoint='" + LoadingPoint + "',IsReverse=" + IsReverse + ",cd.InvioceVal='" + InvoiceVal + "' where cd.DCTripId='" + DCTripID + "' and cd.id='" + CustmoerDcAssignId + "'";
                        dbx.executeNonQuery(Query).ToString();
                        result = "1";
                    }
                    else
                    {
                        Query = "Insert Into customerdcassign(`DCNo`,`CustomerId`,`DCTripId`,Quantity,LoadingPoint,SourceId,IsReverse,InvioceVal)" +
                        " values('" + DCNo + "','" + Cust + "','" + DCTripID + "','" + Qty + "','" + LoadingPoint + "','" + SourceId + "'," + IsReverse + ",'" + InvoiceVal + "')";
                        result = dbx.executeNonQuery(Query).ToString();
                        //Fetching id from customerdcassign table
                        Query = "Select Max(id) from customerdcassign where DCTripId='" + DCTripID + "'";
                        CustmoerDcAssignId = dbx.executeScalar(Query).ToString();
                        Ids.Add(CustmoerDcAssignId);
                    }
                    insertauditdata("Edit", "dc_quntityinfo", "CustomerDCAssignId", CustmoerDcAssignId);

                    Query = "select CONCAT_WS(',',u.Login,CONVERT(u.GroupId,char(50))) from customerinfo c join usersgroupsmap u on u.Login=LoginUser where c.customerId='" + Cust + "'";
                    string GroupId = Convert.ToString(dbx.executeScalar(Query));
                    if (!string.IsNullOrEmpty(GroupId))
                    {
                        if (IsVehicleExists(VehicleNo, GroupId.Split(',')[1]))
                        {
                            Query = "SELECT VehicleID FROM vehicles v WHERE v.AccountID=" + AccountId + " AND v.VehicleID='" + VehicleNo + "';";
                            DataTable vehTbl = dbx.executeQuery(Query).Tables[0];
                            if (vehTbl.Rows.Count > 0)
                            {
                                Query = "insert into vehiclesgroupsmap (VehicleId,GroupId) values('" + VehicleNo + "','" + GroupId.Split(',')[1] + "')";
                                dbx.executeNonQuery(Query);
                            }
                            else
                            {
                                Query = "SELECT u.VehicleID FROM useraddedvehicle u WHERE u.AccountID=" + AccountId + " AND REPLACE(u.VehicleID,' ','')='" + VehicleNo + "';";
                                vehTbl = dbx.executeQuery(Query).Tables[0];
                                if (vehTbl.Rows.Count > 0)
                                {
                                    string loginName = Convert.ToString(GroupId.Split(',')[0]);
                                    if (IsUserAddedVehIsNotExits(VehicleNo, loginName))
                                    {
                                        Query = "INSERT INTO useraddedvehicle (`VehicleID`, `AccountID`,`AddedBy`) VALUES ('" + VehicleNo + "'," + AccountId + ",'" + loginName + "');";
                                        dbx.executeNonQuery(Query);
                                    }
                                }
                            }
                        }
                        AddTransporterNotifications(GroupId.Split(',')[0], "Vehicle Dispatched From " + LoadingPoint, "Vehicle No: " + VehicleNo + "</br> Total Quantity: " + Qty + "</br> Time: " + now.ToString("dd/MM/yy hh:mm tt"));
                    }

                    Query = "delete from dc_quntityinfo where CustomerDCAssignId='" + CustmoerDcAssignId + "'";
                    dbx.executeScalar(Query);
                    if (IsAssetTransation == "1")
                    {
                        Query = "delete from asset_transaction where CustomerDCAssignId='" + CustmoerDcAssignId + "'";
                        dbx.executeScalar(Query);
                    }

                    var qtytList = SelectedIteams.Split(',');
                    for (int j = 0; j < qtytList.Length; j++)
                    {
                        if (!string.IsNullOrEmpty(qtytList[j].ToString()))
                        {
                            var c = qtytList[j].Split('-');
                            string Id = c[0].Trim().ToString();
                            string NoOfQty = c[1].Trim().ToString();
                            Query = "select d.ProductName  from dc_productinfo d where d.Id='" + Id + "'";
                            string Name = dbx.executeScalar(Query).ToString();
                            Query = "insert into dc_quntityinfo (Quntity,ProductId,CustomerDCAssignId) values('" + NoOfQty + "','" + Id + "','" + CustmoerDcAssignId + "')";
                            int Result = dbx.executeNonQuery(Query);
                            if (Result == 1)
                            {
                                if (IsAssetTransation == "1" && (!string.IsNullOrEmpty(CustmoerDcAssignId)))
                                {
                                    if (Name.ToUpperInvariant().Trim() != "NC")
                                        SaveAssetTransation(SourceId, CustmoerDcAssignId, Convert.ToInt32(NoOfQty), "0", LoginUser, "Edit", Id, IsAdded);
                                }
                            }
                            else
                            {
                                //Deleting entred data if anything fails while entring a quanity, this because remove paratically entred data.
                                //DeleteEntredGatePass(DCTripID, Ids);
                                return "0";
                            }
                        }
                    }

                }
                return result;
            }
            catch
            {
                //Deleting entred data if anything fails
                //DeleteEntredGatePass(DCTripID, Ids);
                return "0";
            }

        }

        public string UpdateDistanceLastUpdate(string VehicleNo, string Date, double Distance, double TotalDistance, TimeSpan RunTime, DateTime CurrentTime)
        {
            string Query = string.Empty;
            Query = "replace into dailydistancelastupdate (Date,vehicleId,Distance,TotalDistance,runTime,lastupdated) " +
                    "values ('" + Date + "','" + VehicleNo + "','" + Distance + "','" + TotalDistance + "','" + RunTime + "','" + formatDBDate(CurrentTime) + "')";
            return dbx.executeNonQuery(Query).ToString();
        }

        public DataTable GetVehicleDistanceCapacityByVehicleId(string VehicleId, DateTime Date)
        {
            string Query = string.Empty;
            Query = "select v.VehicleID,vi.Capacity,dl.Distance,vip.locationstr,vip.intimestamp,dl.lastupdated " +
                     "from vehicles v left join dailydistancelastupdate dl on (dl.vehicleId=v.VehicleID and dl.Date='" + Date.ToString("yyyy-MM-dd") + "') " +
                     "left join vehicleinplant vip on (vip.vehicleid=dl.vehicleId and vip.outtimestamp is null and vip.intimestamp>'" + Date.ToString("yyyy-MM-dd") + "') " +
                     "left join vehicleinfo vi on vi.VehicleId=v.VehicleID where v.VehicleID='" + VehicleId + "'";

            return dbx.executeQuery(Query).Tables[0];
        }

