            Query = "select d.lastupdated from dailydistancelastupdate d where d.vehicleId='" + VehicleId + "'" +
                    " order by lastupdated desc limit 1";
            return dbx.executeScalar(Query);

        }

        public string DeleteCustomerDCAssign(string Id, string DCTripId)
        {
            string Query = "select count(dc.DCTripId) from customerdcassign dc where dc.DCTripId='" + DCTripId + "'";
            int Count = dbx.executeNonQuery(Query);
            insertauditdata("Delete", "customerdcassign", "Id", Id);
            int Result = 0;
            try
            {
                if (Count == 1)
                {
                    string query = "Delete From customerdcassign where id='" + Id + "'";
                    dbx.executeNonQuery(query);
                    Query = "Delete From vehicledctrip where Id='" + DCTripId + "'";
                    Result = dbx.executeNonQuery(Query);
                    insertauditdata("Delete", "vehicledctrip", "Id", DCTripId);
                }
                else
                {
                    string query = "Delete From customerdcassign where id='" + Id + "'";
                    Result = dbx.executeNonQuery(query);
                }

                return Result.ToString();
            }
            catch
            {
                return "0";
            }
        }

