        public Object[] GetAllVehicleOutGatePassedDetails(string LoginUser)
        {
            string Query = string.Empty;
            Query = "select vd.VehicleID,cd.LoadingPoint,vd.DateTime,cd.CustomerId,vd.id,cd.id from  customerdcassign cd left join customerinfo c on cd.CustomerId=c.customerId " +
                  "join vehicledctrip vd on cd.DCTripId=vd.id where c.LoginUser='" + LoginUser + "' and cd.IsAcknowledged=0";
            DataTable dt = dbx.executeQuery(Query).Tables[0];
            ArrayList lList = new ArrayList();
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                string VehilceId = dt.Rows[i][0].ToString();
                Query = "select count(v.VehicleId) from vehiclesgroupsmap v join usersgroupsmap u on " +
                        "v.GroupId=u.GroupId where u.Login='" + LoginUser + "' and v.VehicleId='" + VehilceId + "'";
                int count = dbx.executeNonQuery(Query);
                if (count > 0)
                {
                    lList.Add(dt.Rows[i].ItemArray);
                }
            }
            return lList.ToArray();
        }

        public string AddReceivedQuanityDeatials(string CustomerDCAssignId, List<Object> ReceivedQty, string LoginUser, string vehicleId, string Remarks, string AcknowledBy, string PhoneNo, string DcTripId, string IsAssetTransation, string CustDestinationId)
        {
            string Result = string.Empty;
            string Query = string.Empty;
            int DeliverdQty = 0;
            string SessionId = getSessionIdFromLogin(LoginUser);
            int AccountId = GetAccountId(SessionId);
            int timeZone = GetTimeZoneDiff(SessionId);
            DateTime now = DateTime.UtcNow.AddSeconds(timeZone);

            Query = "delete from dc_quntityinfo where CustomerDCAssignId='" + CustomerDCAssignId + "'";
            dbx.executeScalar(Query);

            for (int i = 0; i < ReceivedQty.Count; i++)
            {
                Type myType = ReceivedQty[i].GetType();
                System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
                string ProductName = "";
                string NoOfQuantity = "";
                string AckQuantity = "";
                string ProductId = "";

                try
                {
                    ProductName = props[0].GetValue(ReceivedQty[i], null).ToString();
                }
                catch { }
                try
                {
                    NoOfQuantity = props[1].GetValue(ReceivedQty[i], null).ToString();
                }
                catch { }
                try
                {
                    AckQuantity = props[2].GetValue(ReceivedQty[i], null).ToString();
                }
                catch { }
                try
                {
                    ProductId = props[3].GetValue(ReceivedQty[i], null).ToString();
                }
                catch { }

                DeliverdQty = DeliverdQty + Convert.ToInt32(AckQuantity);

                //Query = "select d.Id from dc_productinfo d where d.ProductName='" + ProductName + "'";
                //string Id = dbx.executeScalar(Query).ToString();
                Query = "insert into dc_quntityinfo (Quntity,ProductId,CustomerDCAssignId,ReceivedQuantity,AcknowledgementTime) values('" + NoOfQuantity + "','" + ProductId + "','" + CustomerDCAssignId + "','" + AckQuantity + "','" + formatDBDate(now) + "')";
                Result = dbx.executeNonQuery(Query).ToString();
                if (IsAssetTransation == "1")
                    if (ProductName.ToUpperInvariant().Trim() != "NC")
                    {
                        SaveAssetTransation(CustDestinationId, CustomerDCAssignId, Convert.ToInt32(AckQuantity), "1", LoginUser, "Ack", ProductId, false);
                    }
            }
            if (Result == "1")
            {
                //Checking wether is it loading or unloading. This is because to delete from vehiclesgroupsmap or not
                Query = "select c.IsLoading from customerinfo c join customerdcassign cd " +
                        "on c.customerId=cd.CustomerId where cd.id='" + CustomerDCAssignId + "'";
                int IsLoading = Convert.ToInt32(dbx.executeScalar(Query));
                if (IsLoading != 1)
                {
                    Query = "delete from vehiclesgroupsmap where " +
                            "GroupId=(select GroupId from usersgroupsmap where Login='" + LoginUser + "') and VehicleId='" + vehicleId + "' limit 1";
                    Result = dbx.executeNonQuery(Query).ToString();
                }
                Query = "update customerdcassign dc set dc.IsAcknowledged=1, dc.IsDelivered=1, dc.DeliveredOn='" + formatDBDate(now) + "', dc.DeliveredQty='" + DeliverdQty.ToString() + "'," +
                        "dc.Remarks='" + Remarks + "',dc.AcknowledBy='" + AcknowledBy + "',dc.Phone='" + PhoneNo + "' where dc.id='" + CustomerDCAssignId + "'";
                Result = dbx.executeNonQuery(Query).ToString();

                Query = "update vehicledctrip vd set vd.IsTripEnds=1,vd.TripEndsOn='" + formatDBDate(now) + "' where vd.id='" + DcTripId + "'";
                Result = dbx.executeNonQuery(Query).ToString();

            }
            return Result;
        }


