        }
        public int insertwaypointsrefData(double minlat, double maxlat, double minlng, double maxlng, string route, string location, int speed, int accountid)
        {
            string loctype = "ACCIDENT SPOT";
            if (location.ToLower().Contains("parking") || location.ToLower().Contains("rest area"))
            {
                loctype = "PARKING";
                string query = "INSERT INTO `waypointsref` (`accountid`, `routename`, `locstr`, `description`, `commands`, `minlat`, `maxlat`, `minlong`, `maxlong`) VALUES (" + accountid + ", '" + route + "', '" + location + "','" + loctype + "', '(ACT PLAYAU 3 )', " + minlat + ", " + maxlat + ", " + minlng + "," + maxlng + ");";
                return dbx.executeNonQuery(query);
            }
            else if (speed == 35)
            {
                loctype = "BLIND SPOT";
                string query = "INSERT INTO `waypointsref` (`accountid`, `routename`, `locstr`, `description`, `commands`, `minlat`, `maxlat`, `minlong`, `maxlong`) VALUES (" + accountid + ", '" + route + "', '" + location + "','" + loctype + "', '(SET SPEEDLIMIT 18 )', " + minlat + ", " + maxlat + ", " + minlng + "," + maxlng + ");";
                return dbx.executeNonQuery(query);
            }
            else
            {
