        public string EditVehicleidByQRCode(string vehicleid, string qrcode, string mobile, string IMEI)
        {
            if (!string.IsNullOrWhiteSpace(vehicleid))
                vehicleid = vehicleid.ToUpperInvariant();
            string query = "select vehicleid from vehicles  where  replace(vehicleid,' ','') = replace('" + vehicleid + "',' ','')";
            object vehicle = dbx.executeScalar(query);
            if (vehicle == null)
                return "Invalid Vehicle";
            if (!string.IsNullOrWhiteSpace(vehicle.ToString()))
            {
                query = "update vehicleqrmapping vm set vehicleid='" + vehicle.ToString() + "' where QRCode='" + qrcode + "'";
                dbx.executeNonQuery(query);
                query = "update driverinfo set AssignedVehicleId='" + vehicle.ToString() + "',IMEI='" + IMEI + "' where MobileNo='" + mobile + "'";
                dbx.executeNonQuery(query);
                return vehicle.ToString();
            }
            else
                return "Invalid Vehicle";
        }
