        public int EditDriverData(string Name, string IMEI, string LicenseNo, string DOB, string mobileNo, string vehicleid, string photo)
        {
            string query = "select DriverId from driverinfo di where ((di.MobileNo='" + mobileNo + "' and lower(REPLACE(di.LicenceNo,' ',''))='" + LicenseNo.Replace(" ", "").ToLower() + "') OR (lower(REPLACE(di.LicenceNo,' ',''))='" + LicenseNo.Replace(" ", "").ToLower() + "'  and lower(REPLACE(di.Name,' ',''))='" + Name.Replace(" ", "").ToLower() + "') OR (lower(REPLACE(di.LicenceNo,' ',''))='" + LicenseNo.Replace(" ", "").ToLower() + "' and di.DOB='" + DOB + "') OR (lower(REPLACE(di.Name,' ',''))='" + Name.Replace(" ", "").ToLower() + "' and di.DOB='" + DOB + "'))";
            object id = dbx.executeScalar(query);
            if (id != null)
            {
                //change previous IMEI to empty
                query = "update driverinfo set IMEI='' where IMEI='" + IMEI + "' ";
                dbx.executeNonQuery(query);
                //change vehicle ids
                query = "update driverinfo set AssignedVehicleId='' where AssignedVehicleId='" + vehicleid + "' ";
                dbx.executeNonQuery(query);

                query = "update driverinfo set IMEI='" + IMEI + "',Name='" + Name + "' , LicenceNo='" + LicenseNo + "', DOB='" + DOB + "', MobileNo='" + mobileNo + "', DriverPhoto='" + photo + "', AssignedVehicleId='" + vehicleid + "'  where DriverId='" + id.ToString() + "' ";
            }
            else
            {
                int accountid = GetVehAccontId(vehicleid);
                int groupid = getGroupId(getSessionIdByVehicle(vehicleid));
                query = "INSERT INTO `driverinfo` (`Name`, `Father`, `DOB`, `AddressLine1`, `AddressLine2`, `AddressLine3`, `City`, `State`, `ContactNo`, `MobileNo`, `LicenceNo`, `IssuedBy`, `LicenceValid`, `LicenceRemainder`, `LRStartBefore`, `LRRepeat`, `LRSMS`, `LRSMS_MobileNo`, `LREmail`, `LREmail_MailId`, `InsuranceCompany`, `PolicyNo`, `PolicyDate`, `InsuranceRemainder`, `IRStartBefore`, `IRRepeat`, `IRSMS`, `IRSMS_MobileNo`, `IREmail`, `IREmail_MailId`, `AssignedVehicleId`, `CleanerName`, `CleanerMobile`, `DriverLanguagePreference`, `DriverPhoto`, `AccountId`,`GroupId`, `Active`, `UserDefinedDriverId`, `HelperId`, `IMEI`, `RFIDTag`, `HazardousLicNo`, `HazardousLicExpDate`, `DDTDate`, `DDTExpiryDate`, `MedicalTestDate`, `MediExpDate`, `DrivingExp`, `DOJ`, `DriverAccidentHistory`, `DDTGrade`, `LastVerifiedDate`) VALUES ('" + Name + "', ' ', '" + DOB + "', ' ', '', '', ' ', ' ', ' ', '" + mobileNo + "', '" + LicenseNo + "', ' ', ' ', b'0', 0, NULL, b'0', '', b'0', '', '', '', NULL, b'0', 0, NULL, b'0', '', b'0', '', '" + vehicleid + "', '', '', '0', '" + photo + "', " + accountid + ", " + groupid + ", b'1', '', '-1', '" + IMEI + "', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);";
            }
            return dbx.executeNonQuery(query);
        }


