        public Object[] GetVehilcesByLogin(string LoginUser, DateTime reportDate)
        {
            int Month = reportDate.Month;
            int Year = reportDate.Year;
            string now = formatDBDate(reportDate.Date);
            string Query = string.Empty;
            //Query = "select distinct v.vehicleid,i.Capacity from vehiclesgroupsmap v " +
            //    "inner join usersgroupsmap u on v.GroupId = u.GroupId " +
            //    "inner join accountgroups a on a.GroupId = v.GroupId " +
            //    "inner join vehiclecategory g on g.VehicleId = v.VehicleId " +
            //    "left join vehicleinfo i on v.VehicleId = i.VehicleId " +
            //    "where u.Login = '" + LoginUser + "' order by g.Category,v.VehicleId";

            Query = "select g.Category as `Store Number`,v.VehicleId,i.Capacity,count(distinct m.Id) daycount,count(distinct m1.Id) monthcount from usersgroupsmap u join vehiclesgroupsmap v on v.GroupId=u.GroupId " +
                    "inner join vehiclecategory g on g.VehicleId = v.VehicleId " +
                    "left join vehicleinfo i on v.VehicleId = i.VehicleId " +
                    "left join metro_trip_details m on m.VehicleId = replace(v.VehicleId, ' ', '') and date(m.TripDate)= '" + now + "' " +
                    "left join metro_trip_details m1 on m1.VehicleId = replace(v.VehicleId, ' ', '') and month(m1.TripDate)= " + Month + " and year(m1.TripDate)= " + Year +
                    " where u.Login = '" + LoginUser + "' group by v.VehicleId order by g.Category,v.VehicleId";
            DataTable dt = dbx.executeQuery(Query).Tables[0];
            ArrayList lList = new ArrayList();
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                lList.Add(dt.Rows[i].ItemArray);
            }
            return lList.ToArray();

        }
