        public DataRow[] IsVehilceInGeofenceLocation(double latitude, double longitude, string AccountId)
        {
            StringBuilder query = new StringBuilder();

            query.Append("select geofencename FROM geofencenew ");
            query.Append("where (minlatitude <= " + latitude + " ");
            query.Append("AND minLongitude <= " + longitude + " ");
            query.Append("AND maxLatitude >= " + latitude + " ");
            query.Append("AND maxLongitude >= " + longitude + ") and Accountid= " + AccountId + "");
            DataSet geofenceinout = dbx.executeQuery(query.ToString());
            DataTable table = geofenceinout.Tables[0];
            DataRow[] values = new DataRow[table.Rows.Count];
            return values;
        }

        public DataTable GetVehiclesWithoutDC(string groupid)
        {
            string Query = string.Empty;
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
            Query = "select v.vehicleid,l.ServerTS,i.Plant,l.latitude,l.longitude from vehicleroutesummary v" +
                    " join lastupdtdata l on l.TruckID=v.vehicleid" +
                    " left join vehicledctrip d on d.id=(select max(id) from vehicledctrip c where c.VehicleID=v.vehicleid)" +
                    " left join vehicleinfo i on i.VehicleID=v.vehicleid" +
                    " where v.direction='UP'" +
                    " and v.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid=" + groupid + ")" +
                    " and l.ServerTS>'" + formatDBDate(now.AddHours(-24)) + "' and TIMEDIFF(l.ServerTS,d.DateTime)>'7.0:00:00' and d.IsTripEnds=1";
            return dbx.executeQuery(Query).Tables[0];
        }
        public DataTable GetVehiclesWithouteSTL(string accountid)
        {
            string Query = string.Empty;
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
            Query = "select d.VehicleID,d.DateTime,d.AddedBy,d.NoofDcs,group_concat(i.Name) Name,group_concat(c.DCNo) DCNo,d.LoadingPlaceName from vehicledctrip d" +
                    " join customerdcassign c on c.DCTripId=d.id" +
                    " join customerinfo i on i.customerId=c.CustomerId" +
                    " where d.AccountID='" + accountid + "'" +
                    " and d.DateTime>'" + formatDBDate(now.AddHours(-30)) + "' and d.DateTime<'" + formatDBDate(now.AddHours(1)) + "' and REPLACE(d.VehicleID,' ','') not in (select REPLACE(w.VehicleID,' ','') from stl_workflow w where" +
                    " w.datetime> DATE_ADD(d.DateTime,INTERVAL -20 HOUR) and w.datetime< DATE_ADD(d.DateTime,INTERVAL 5 HOUR)) group by d.id";
            return dbx.executeQuery(Query).Tables[0];
        }
        public DataTable GetNearestVehiclesByAccount(double latitude, double longitude, int accountid, double radius)
        {
            string Query = string.Empty;
            double minlat = latitude - radius;
            double maxlat = latitude + radius;
            double minlng = longitude - radius;
            double maxlng = longitude + radius;
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
            Query = "select truckid,latitude,longitude,concat(timestamp) as time from lastupdtdata l " +
                    "where (latitude between " + minlat + " and " + maxlat + ") and " +
                    "(longitude between " + minlng + " and " + maxlng + ") and " +
                    "truckid in(select v.VehicleID from vehicles v where v.AccountId=" + accountid + ");";
            return dbx.executeQuery(Query).Tables[0];
        }

