        public DataTable GetDriverTagInOutReport(string sessionId, DateTime fromDate, DateTime Todate, string vehicleid = "")
        {
            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            if (string.IsNullOrEmpty(vehicleid))
            {
                int groupid = getGroupId(sessionId);
                Query = "select t.* from taging t" +
                        " join vehiclesgroupsmap v on v.VehicleId=t.VehicleId" +
                        " where v.GroupId=? and t.TimeStamp>=? and t.TimeStamp<=? group by t.DriverId,t.VehicleId,t.TagInOrOut,t.TimeStamp";
                lParameter.Add("GroupId", groupid);
            }
            else
            {
                Query = "select t.* from taging t" +
                       " where t.vehicleid=? and t.TimeStamp>=? and t.TimeStamp<=? group by t.DriverId,t.VehicleId,t.TagInOrOut,t.TimeStamp";
                lParameter.Add("vehicleid", vehicleid);
            }
            lParameter.Add("TimeStamp", formatDBDate(fromDate));
            lParameter.Add("todate", formatDBDate(Todate));
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }
