        public DataTable GetMobileNoConfig(int AccountId, string Purpose, string login = "", string vehicleid = "")
        {
            try
            {
                string Query = string.Empty;
                var lParameter = new Dictionary<string, object>();
                Query = "select group_concat(distinct MobileNos) as MobileNos,d.SMS_Login,a.globalaccountid from mobilenoconfig d " +
                        " join accounts a on a.ID = d.AccountId where d.AccountId=? and d.Purpose=? and d.Active=1";
                lParameter.Add("AccountId", AccountId);
                if (!string.IsNullOrEmpty(login))
                {
                    Query = "select group_concat(distinct MobileNos) as MobileNos,d.SMS_Login,a.globalaccountid from mobilenoconfig d " +
                            " join accounts a on a.ID = d.AccountId where d.login=? and d.Purpose=? and d.Active=1";
                    lParameter.Clear();
                    lParameter.Add("login", login);
                }
                if (!string.IsNullOrEmpty(vehicleid))
                {
                    Query = "select group_concat(distinct MobileNos) as MobileNos,d.SMS_Login,a.globalaccountid from mobilenoconfig d  " +
                            " join accounts a on a.ID = d.AccountId where d.login in (select u.Login from vehiclesgroupsmap v " +
                            " join usersgroupsmap u on u.GroupId=v.GroupId " +
                            " where v.VehicleID=?) and d.Purpose=? and d.Active=1";
                    lParameter.Clear();
                    lParameter.Add("vehicleid", vehicleid);
                }
                lParameter.Add("Purpose", Purpose);
                return dbx.executeQuery(Query, lParameter).Tables[0];
            }
            catch (Exception ex)
            { return null; }
        }

        public void updateLogJRMTbl(String truckId, DateTime ts, String value1, String value2, String column)
        {
            ts = ts.AddMinutes(-60);   // go back a bit. Now depending on whether the vehicle entered no network zone or not this may not fetch any row

            String tsStr = formatDBDate(ts);
            String query = "select ts from logjrmdata l where l.ts > '" + tsStr + "' and l.description not like '%WEATHER%' and l.vehicleid = '" + truckId
                + "' order by ts desc LIMIT 1";
            DateTime updtTime = DateTime.Parse(((Object)dbx.executeScalar(query)).ToString());
            if (updtTime != null)
            {
                query = "update logjrmdata set " + column + " = '" + value1 + value2 + "' where ts = '" + formatDBDate(updtTime) + "'";
                dbx.executeNonQuery(query);
            }
        }

