        public DataTable getCustomerDetailsByPlant(string plant, string type, string accountid)
        {
            if (type == "All")
            {
                string query = "select (p.minlatitude + p.maxlatitude)/2,(p.minlongitude + p.maxlongitude)/2,i.Name,i.CustomerCode,t.StockLevel,t.Next3DaysExpected/3,"
                             + "t.timestamp,i.SafeLevel,i.`Storage`,i.CustomerType,r.RTKm/2,a.Quantity,v.DateTime, i.customerId,0 as OnTransit,0 as dipatchQt from "
                             + "customerinfo i left join customerstock t  on t.CustomerId=i.customerId  and t.Id=(select Max(Id) from customerstock where CustomerId="
                             + "i.customerId) left join customerdcassign a  on a.CustomerId=i.customerId  and a.id=(select Max(Id) from customerdcassign where "
                             + "CustomerId=i.CustomerId) left join vehicledctrip v  on v.id=a.DCTripId left join plantgeolocations p on p.customerid=i.CustomerCode left "
                             + "join roundtriptime r on r.Plant=i.DefaultPlant and r.CustomerCode=i.CustomerCode where i.AccountId=? and i.CustomerType in "
                             + "('STK','BOOM / BOOT','ALDS','PACKED','COMMODITY','Other') and i.DefaultPlant=? group by i.customerId order by t.timestamp desc";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AccountId", accountid);
                lParameter.Add("DefaultPlant", plant);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            else
            {
                string query = "select (p.minlatitude + p.maxlatitude)/2,(p.minlongitude + p.maxlongitude)/2,i.Name,i.CustomerCode,t.StockLevel,t.Next3DaysExpected/3,"
                             + "t.timestamp,i.SafeLevel,i.`Storage`,i.CustomerType,r.RTKm/2,a.Quantity,v.DateTime, i.customerId,0 as OnTransit,0 as dipatchQt from "
                             + "customerinfo i left join customerstock t  on t.CustomerId=i.customerId  and t.Id=(select Max(Id) from customerstock where CustomerId="
                             + "i.customerId) left join customerdcassign a  on a.CustomerId=i.customerId  and a.id=(select Max(Id) from customerdcassign where "
                             + "CustomerId=i.CustomerId) left join vehicledctrip v  on v.id=a.DCTripId left join plantgeolocations p on p.customerid=i.CustomerCode left "
                             + "join roundtriptime r on r.Plant=i.DefaultPlant and r.CustomerCode=i.CustomerCode where i.AccountId=? and i.CustomerType=? and "
                             + "i.DefaultPlant=? group by i.customerId order by t.timestamp desc";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AccountId", accountid);
                lParameter.Add("CustomerType", type);
                lParameter.Add("DefaultPlant", plant);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
        }
        public DataTable getCustomerLoadontransitBulk(string customerids)
        {
            string[] custs = customerids.Split(',');
            string inQuery = "";
            var lParameter = new Dictionary<string, object>();
            for (int i = 0; i < custs.Length; i++)
            {
                inQuery += "?";
                if (i != custs.Length - 1)
                    inQuery += ",";
                lParameter.Add("cust" + i, custs[i]);
            }
            string query = "select sum(c.Quantity),c.customerId from customerdcassign c join vehicledctrip v on v.id=c.DCTripId where "
                         + "c.IsDelivered=0 and c.IsCancel=0 and v.IsTripEnds=0 and c.CustomerId in (" + inQuery + ") group by c.CustomerId";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable getActiveMarketVehicles(string Accountid, string type, int groupid = 0, string joinConfig_VehiclesGp = "0")
        {
            var lParameter = new Dictionary<string, object>();
            string query = "select a.TruckID from configdata a";
            if (joinConfig_VehiclesGp == "1" & groupid > 0)
            {
                string configQuery = "SELECT v.VehicleId FROM  vehiclesgroupsmap v JOIN configdata c ON REPLACE(v.VehicleId,' ','')=Replace(c.TruckID,' ','')"
                                    + " WHERE v.GroupId=" + groupid + " AND c.UID IS NOT NULL AND c.UID !='' AND v.VehicleId NOT LIKE '%INST%'";
                return dbx.executeQuery(configQuery).Tables[0];
            }
            else
            {
                if (groupid > 0)
                {
                    query += " where a.TruckID in (select vehicleid from vehiclesgroupsmap where GroupId = ?)";
                    lParameter.Add("GroupId", groupid);
                }
                else
                {
                    query += " where a.TruckID in (select vehicleid from vehicles where accountid = ?)";
                    lParameter.Add("AccountId", Accountid);
                }
                if (type == "1")
                    query += " and a.OwnerContact = 1";
                else if (type == "0")
                    query += " and a.OwnerContact != 1";
                query += " and a.ReturnDate IS NULL";
                return dbx.executeQuery(query, lParameter).Tables[0];
            }

        }

