        public DataTable GetVehicleInPlant(string vehicleIds, string FromDate, string ToDate, string PlantType)
        {
            var lParameter = new Dictionary<string, object>();
            String[] vals = vehicleIds.Replace("'", "").Replace("\"", "").Split(',');
            string inparam = "";
            for (int i = 0; i < vals.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
                lParameter.Add("truckId" + i, vals[i]);
            }
            //string query = "select vehicleid,locationstr,planttype,intimestamp,outtimestamp from vehicleinplant where vehicleid in (" + inparam + ") and planttype in (" + PlantType + ") and intimestamp>=? and intimestamp<=? order by vehicleid,intimestamp asc";
            //Modified by Suvarna on 29/3/2021  as previuos query was skipping partial inward trips (ex.2021-03-25 17:41:25(in)-2021-03-26 03:44:59(out)) but stil it will cause partial outward trip)
            string query = "select vehicleid,locationstr,planttype,intimestamp,outtimestamp from vehicleinplant where vehicleid in (" + inparam + ") and planttype in (" + PlantType + ") and outtimestamp>=? and intimestamp<=? group by concat(vehicleid, intimestamp) order by vehicleid,intimestamp asc";
            lParameter.Add("FromDate", FromDate);
            lParameter.Add("ToDate", ToDate);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
