        /// <summary>
        /// Returns highest numeric SequenceNo used for the V-Protect account (0000 if none).
        /// </summary>
        public int GetMaxSiaDc09SequenceForAccount(string accountId)
        {
            int maxSeq = 0;
            try
            {
                string query = "SELECT MAX(CAST(SequenceNo AS UNSIGNED)) FROM tbl_sia_dc09_log WHERE AccountId = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AccountId", accountId ?? string.Empty);
                object result = dbx.executeScalar(query, lParameter);
                if (result != null && result != DBNull.Value)
                    maxSeq = Convert.ToInt32(result);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error reading max SIA DC-09 sequence: " + ex.Message);
            }
            return maxSeq;
        }

        /// <summary>
        /// Returns SiteId/AccountId mapping for a given Asset (vehicle).
        /// SiteId is used as V-Protect account/UID in SIA DC-09 packets.
        /// </summary>
        public DataTable GetAssetSiteIdMapping(int asset)
        {
            try
            {
                string query = "SELECT SiteId, AccountId FROM assetSiteIdMapping WHERE Asset = ? LIMIT 1";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("Asset", asset);
                DataSet ds = dbx.executeQuery(query, lParameter);
                if (ds != null && ds.Tables.Count > 0)
                    return ds.Tables[0];
                return new DataTable();
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error reading assetSiteIdMapping: " + ex.Message);
                return new DataTable();
            }
        }

        /// <summary>
        /// Next DispatchAttempt for Asset + EventTimestamp (1 = first send, 2+ = retry insert).
        /// </summary>
        public int GetNextSiaDc09DispatchAttempt(string assetId, DateTime eventTimestamp)
        {
            int nextAttempt = 1;
            try
            {
                string query = "SELECT IFNULL(MAX(DispatchAttempt), 0) FROM tbl_sia_dc09_log WHERE AssetId = ? AND EventTimestamp = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AssetId", assetId ?? string.Empty);
                lParameter.Add("EventTimestamp", formatDBDate(eventTimestamp));
                object result = dbx.executeScalar(query, lParameter);
                if (result != null && result != DBNull.Value)
                    nextAttempt = Convert.ToInt32(result) + 1;
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error reading next SIA DC-09 dispatch attempt: " + ex.Message);
            }
            return nextAttempt;
        }

        /// <summary>
        /// Returns true if this Asset + panic EventTimestamp was already logged/sent.
        /// </summary>
        public bool SiaDc09LogExistsForAssetAndEventTime(string assetId, DateTime eventTimestamp)
        {
            try
            {
                string query = "SELECT COUNT(1) FROM tbl_sia_dc09_log WHERE AssetId = ? AND EventTimestamp = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AssetId", assetId ?? string.Empty);
                lParameter.Add("EventTimestamp", formatDBDate(eventTimestamp));
                object result = dbx.executeScalar(query, lParameter);
                if (result != null && result != DBNull.Value)
                    return Convert.ToInt32(result) > 0;
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error checking SIA DC-09 duplicate log: " + ex.Message);
            }
            return false;
        }

        /// <summary>
        /// Logs SIA DC-09 outbound packet and receiver acknowledgement for panic/SOS events.
        /// </summary>
        public long InsertSiaDc09Log(string alertId, string globalAccId, string loginName, string assetId, string accountId,
            string sequenceNo, string eventCode, DateTime eventTimestamp, int dispatchAttempt, double latitude, double longitude,
            string receiverHost, int receiverPort, string sentPacket, string sentPayload, string ackPacket,
            string ackType, int attemptCount, string status, string errorMessage)
        {
            long result = 0;
            try
            {
                string query = "INSERT INTO tbl_sia_dc09_log (AlertId, GlobalAccId, LoginName, AssetId, AccountId, SequenceNo, EventCode, EventTimestamp, DispatchAttempt, " +
                    "Latitude, Longitude, ReceiverHost, ReceiverPort, SentPacket, SentPayload, AckPacket, AckType, AttemptCount, Status, ErrorMessage, CreatedOn) " +
                    "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";

                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AlertId", alertId ?? string.Empty);
                lParameter.Add("GlobalAccId", globalAccId ?? string.Empty);
                lParameter.Add("LoginName", loginName ?? string.Empty);
                lParameter.Add("AssetId", assetId ?? string.Empty);
                lParameter.Add("AccountId", accountId ?? string.Empty);
                lParameter.Add("SequenceNo", sequenceNo ?? string.Empty);
                lParameter.Add("EventCode", eventCode ?? string.Empty);
                lParameter.Add("EventTimestamp", formatDBDate(eventTimestamp));
                lParameter.Add("DispatchAttempt", dispatchAttempt > 0 ? dispatchAttempt : 1);
                lParameter.Add("Latitude", latitude);
                lParameter.Add("Longitude", longitude);
                lParameter.Add("ReceiverHost", receiverHost ?? string.Empty);
                lParameter.Add("ReceiverPort", receiverPort);
                lParameter.Add("SentPacket", sentPacket ?? string.Empty);
                lParameter.Add("SentPayload", sentPayload ?? string.Empty);
                lParameter.Add("AckPacket", ackPacket ?? string.Empty);
                lParameter.Add("AckType", ackType ?? string.Empty);
                lParameter.Add("AttemptCount", attemptCount);
                lParameter.Add("Status", status ?? string.Empty);
                lParameter.Add("ErrorMessage", errorMessage ?? string.Empty);
                lParameter.Add("CreatedOn", formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff())));

                dbx.executeNonQuery(query, lParameter);
                object id = dbx.executeScalar("SELECT LAST_INSERT_ID()");
                if (id != null && id != DBNull.Value)
                    result = Convert.ToInt64(id);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error inserting SIA DC-09 log: " + ex.Message);
            }
            return result;
        }

        public int UpdateSiaDc09LogResponse(long logId, string ackPacket, string ackType, int attemptCount, string status, string errorMessage, DateTime responseTime)
        {
            int result = 0;
            try
            {
                string query = "UPDATE tbl_sia_dc09_log SET AckPacket = ?, AckType = ?, AttemptCount = ?, Status = ?, ErrorMessage = ?, ResponseTime = ? WHERE Id = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AckPacket", ackPacket ?? string.Empty);
                lParameter.Add("AckType", ackType ?? string.Empty);
                lParameter.Add("AttemptCount", attemptCount);
                lParameter.Add("Status", status ?? string.Empty);
                lParameter.Add("ErrorMessage", errorMessage ?? string.Empty);
                lParameter.Add("ResponseTime", formatDBDate(responseTime));
                lParameter.Add("Id", logId);
                result = dbx.executeNonQuery(query, lParameter);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error updating SIA DC-09 log: " + ex.Message);
            }
            return result;
        }

