        public void UpdateUIDSimConfig(int UID, string SimNo, string IMEI)
        {
            try
            {
                var lParameter = new Dictionary<string, object>();
                string query = "";
                if (string.IsNullOrEmpty(SimNo))
                    return;
                if (SimNo == "919845197008")
                {
                    query = "select * from uidsimconfig where uid=? and SIMNO<>?";
                    lParameter.Add("UID", UID);
                    lParameter.Add("SIMNO", SimNo);
                    if (dbx.executeQuery(query, lParameter).Tables[0].Rows.Count > 0)
                        return;
                }
                query = "update `uidsimconfig` set LastVerifiedOn=? where UID=? and SIMNO=? and IMEI=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("LastVerifiedOn", formatDBDate(DateTime.UtcNow));
                lParameter.Add("UID", UID);
                lParameter.Add("SIMNO", SimNo);
                lParameter.Add("IMEI", IMEI);
                int res = dbx.executeNonQuery(query, lParameter);
                if (res == 0)
                {
                    query = "Replace into `uidsimconfig`(UID,SIMNO,IMEI) values(?,?,?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("UID", UID);
                    lParameter.Add("SIMNO", SimNo);
                    lParameter.Add("IMEI", IMEI);
                    dbx.executeNonQuery(query, lParameter);
                }
            }
            catch
            {
            }
        }

