        public void UpdateGatePassVehicleInOut(string Intime, string OutTime, string CustomerDCAssignId, string LoginUser)
        {
            string Query = string.Empty;
            if (!string.IsNullOrEmpty(Intime))
            {
                //Updating out time of source 
                Query = "update vehicledctrip v set v.LoadingOutTime ='" + formatDBDate(Convert.ToDateTime(Intime)) + "' where v.id=(select c.DCTripId from customerdcassign c where c.id='" + CustomerDCAssignId + "')";
                dbx.executeNonQuery(Query);
            }
            else if (!string.IsNullOrEmpty(OutTime))
            {
                //Update in time of destination
                Query = "update customerdcassign cd set cd.UnloadingInTime ='" + formatDBDate(Convert.ToDateTime(OutTime)) + "' where cd.id='" + CustomerDCAssignId + "'";
                int Result = dbx.executeNonQuery(Query);
                if (LoginUser == "Aopl")
                {
                    if (Result == 1)
                    {
                        Query = Query = "update customerdcassign cd set cd.DeliveredOn ='" + formatDBDate(Convert.ToDateTime(OutTime)) + "' where cd.id='" + CustomerDCAssignId + "'";
                        dbx.executeNonQuery(Query);
                    }
                }
            }
        }
