        public DataTable getVehiclesByPlantWithDetails(string plant, int groupid)
        {
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()).AddHours(-10);
            string formatDate = formatDBDate(now);
            string query = "select vr.VehicleId,ci.Name,(case when sw.`Action` is null then (case when se.`Action` is null then s.`Action` else se.`Action` end) else "
                         + "sw.`Action` end) as action,vp.Latitude,vp.Longitude,vp.timestamp,v.Capacity,(case when sw.`Action` is null then (case when se.`Action` is "
                         + "null then s.datetime else se.timestamp end) else sw.TakenOn end) as actiontime,vd.DateTime,vp.positiontxt from vehiclesgroupsmap vr join "
                         + "vehicleinfo v on v.VehicleId=vr.VehicleId left join vehicledctrip vd on vd.id=(select max(id) from vehicledctrip where vehicleid=vr.vehicleid"
                         + ") left join customerdcassign c on c.id=(select max(id) from customerdcassign where DCTripId=vd.id) left join customerinfo ci on ci.customerId"
                         + "=c.CustomerId left join stl_workflow s on s.workflowId=(select max(workflowId) from stl_workflow where vehicleId=v.VehicleId) left join "
                         + "stl_editedworkflow se on se.EditId=(select max(EditId) from stl_editedworkflow where workflowId=s.workflowId) left join stl_workflowaction "
                         + "sw on sw.Id=(select max(Id) from stl_workflowaction where workflowId=s.workflowId) left join vehiclepositiontxt vp on vp.truckid=vr.VehicleId"
                         + " where v.Plant=? and v.TypeOfVehicle='Bulk' and vr.GroupId=? and (vd.DateTime<? or (vd.DateTime>? and vd.IsTripEnds=1))";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Plant", plant);
            lParameter.Add("GroupId", groupid);
            lParameter.Add("DateTime", formatDate);
            lParameter.Add("DateTime1", formatDate);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }

