        public DataTable GetAllAsset(string LoginUser, string AccountId, string LocationId)
        {
            string query = "select a.Id,c.Region,a.Quantity,a.DateTime,p.Id as ProductId,p.ProductName,a.WriteOff from asset_master a " +
                       "join customerinfo c on a.CustomerId=c.customerId " +
                       "join dc_productinfo p on a.ProductId=p.Id join users s on s.login=c.LoginUser " +
                       "where a.Id in (select max(a1.Id) from asset_master a1 left join customerinfo ci on " +
                       "ci.customerId=a1.CustomerId join users s on s.login=ci.LoginUser " +
                       "where s.login=c.LoginUser group by a1.ProductId,s.login) and c.customerId=? and p.AccountId=? order by a.DateTime desc";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("LocationId", LocationId);
            lParameter.Add("AccountId", AccountId);
            DataTable lList = dbx.executeQuery(query, lParameter).Tables[0];
            return lList;
        }

        public DataTable GetAllAsset(string LoginUser, string AccountId)
        {
            var lParameter = new Dictionary<string, object>();
            string query = "select c.IsLoading,c.Region from customerinfo c where c.LoginUser=?";
            lParameter.Add("LoginUser", LoginUser);
            DataTable lValues = dbx.executeQuery(query, lParameter).Tables[0];
            int IsAdmin = 0;
            string Region = string.Empty;
            if (lValues.Rows.Count > 0)
            {
                IsAdmin = Convert.ToInt32(lValues.Rows[0][0]);
                Region = Convert.ToString(lValues.Rows[0][1]);
            }
            string Value = string.Empty;
            lParameter.Clear();
            if (IsAdmin == 3)
            {
                //Admin users
                Value = "s1.AccountID";
                lParameter.Add("AccountId", AccountId);
            }
            else if (IsAdmin == 1)
            {
                //DC users
                Value = "ci.Region";
                lParameter.Add("Region", Region);
            }
            else
            {
                //Normall users
                Value = "s1.login";
                lParameter.Add("LoginUser", LoginUser);
            }
            query = "select a.Id,c.Region,a.Quantity,a.DateTime,p.Id as ProductId,p.ProductName from asset_master a " +
                      "join customerinfo c on a.CustomerId=c.customerId " +
                      "join dc_productinfo p on a.ProductId=p.Id join users s on s.login=c.LoginUser " +
                      "where a.Id in (select max(a1.Id) from asset_master a1 left join customerinfo ci on " +
                      "ci.customerId=a1.CustomerId join users s1 on s1.login=ci.LoginUser " +
                      "where " + Value + "=? group by a1.ProductId,s1.login) order by a.DateTime desc";

            DataTable lList = dbx.executeQuery(query, lParameter).Tables[0];
            return lList;
        }

        public DataTable GetCurrentAssetDetails(string CustomerId)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query.Append("select c.customerId,c.Name,a2.CurrentAssets as Quantity,c.Region,p.ProductName,a2.ProductId,TransactionTime from ");
            query.Append(" asset_transaction a2 join customerinfo c on c.customerId=a2.CustomerId JOIN dc_productinfo p ON p.Id=a2.ProductId ");
            query.Append(" where a2.Id IN (select max(a1.Id) from asset_transaction a1 join customerinfo c on a1.CustomerId=c.customerId ");
            query.Append(" WHERE c.customerId =? group by c.customerId,a1.ProductId) group by a2.ProductId UNION ");
            query.Append(" select c.customerId,c.Name,a2.CurrentAssets as Quantity,c.Region,p.ProductName,a2.ProductId,TransactionTime from ");
            query.Append(" asset_transaction a2 join customerinfo c on c.customerId=a2.CustomerId JOIN (SELECT * FROM dc_productinfo d WHERE ");
            query.Append(" d.LoginUser IN (SELECT c.LoginUser AS 'Userlogin' FROM dc_source_destination_mapping m JOIN customerinfo c ON ");
            query.Append(" c.customerId=m.CustomerId WHERE m.UserLogin in (SELECT c3.LoginUser FROM customerinfo c3 WHERE c3.customerId=?))) p ON p.Id=a2.ProductId where a2.Id IN (select max(a1.Id) from ");
            query.Append(" asset_transaction a1 join customerinfo c on a1.CustomerId=c.customerId ");
            query.Append(" WHERE c.customerId=? group by c.customerId,a1.ProductId) group by a2.ProductId;");
            lParameter.Add("Login1", CustomerId);
            lParameter.Add("Login2", CustomerId);
            lParameter.Add("Login3", CustomerId);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }
