        public DataTable GetLocationsByRegion(string Region, string LoginUser)
        {
            var lParameter = new Dictionary<string, object>();
            string query = "select c.IsLoading from customerinfo c where c.LoginUser=?";
            lParameter.Add("LoginUser", LoginUser);
            DataTable lList = new DataTable();
            int IsAdmin = Convert.ToInt32(dbx.executeScalar(query, lParameter));
            //Checking IsAdmin or IsDcUsers
            if (IsAdmin == 3 || IsAdmin == 1)
            {
                query = "select c.Name,c.customerId from customerinfo c where c.Region=?";
                lParameter.Clear();
                lParameter.Add("Region", Region);
                return lList = dbx.executeQuery(query, lParameter).Tables[0];
