        public string SaveAsset(DataTable AssetList)
        {
            string Result = string.Empty;
            DateTime CurrentTime = DateTime.Now;
            for (int i = 0; i < AssetList.Rows.Count; i++)
            {
                //Type myType = AssetList[i].GetType();
                //System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
                bool isAssAvl = true;
                string ProductId = AssetList.Rows[i]["ProductId"].ToString();
                string CustomerId = AssetList.Rows[i]["CustomerId"].ToString();
                string Quantity = AssetList.Rows[i]["Quantity"].ToString();
                string Query = "select Quantity from asset_master where Id =(select max(a.Id) from asset_master a where a.ProductId='" + ProductId + "' and a.CustomerId='" + CustomerId + "')";
                string Value = Convert.ToString(dbx.executeScalar(Query));

                if (string.IsNullOrEmpty(Value))
                {
                    Value = "0";
                    isAssAvl = false;
                }
                if (Value == "0" && Quantity == "0")
                    Value = "1";
                if (Convert.ToInt32(Value) != Convert.ToInt32(Quantity) && (isAssAvl == false || Convert.ToInt32(Quantity) > 0))
                {
                    Query = "insert into asset_master (ProductId,CustomerId,Quantity,DateTime) " +
                                   "values (" + ProductId + "," + CustomerId + "," + Quantity + ",'" + formatDBDate(CurrentTime) + "')";
                    Result = Convert.ToString(dbx.executeNonQuery(Query));

                    if (Result == "1" && Convert.ToInt32(Quantity) > 0)
                    {
                        StringBuilder query = new StringBuilder();
                        query.Append("select a.Quantity,a.DateTime,a.customerId from asset_master a join customerinfo c on a.CustomerId=c.customerId join dc_productinfo p on a.ProductId=p.Id where a.Id in ");
                        query.Append("(select max(a1.Id) from asset_master a1 left join customerinfo ci on ");
                        query.Append("ci.customerId=a1.CustomerId join users s on s.login=ci.LoginUser where ci.customerId='" + CustomerId + "' and a1.DateTime<'" + formatDBDate(CurrentTime));
                        query.Append("' group by a1.ProductId,s.login) and a.ProductId=" + ProductId + "  order by a.DateTime desc;");
                        DataTable lAsset = dbx.executeQuery(query.ToString()).Tables[0];

                        int EstimatedCurrentAssets = GetEstimatedCurrentAsset(lAsset, CustomerId, ProductId, Convert.ToInt32(Quantity), 1);

                        query.Clear();
                        query.Append("insert into asset_transaction (CustomerId,CustomerDCAssignId,ProductId,CurrentAssets,UpdatedAssets,TransactionTime,TransactionType) ");
                        query.Append("values (?,?,?,?,?,?,?);");
                        var lParameter = new Dictionary<string, object>();
                        lParameter.Add("CustomerId", CustomerId);
                        lParameter.Add("CustomerDCAssignId", "1");
                        lParameter.Add("ProductId", ProductId);
                        lParameter.Add("CurrentAssets", EstimatedCurrentAssets);
                        lParameter.Add("UpdatedAssets", Quantity);
                        lParameter.Add("TransactionTime", formatDBDate(System.DateTime.Now));
                        lParameter.Add("TransactionType", 1);
                        dbx.executeNonQuery(query.ToString(), lParameter);
                    }
                }
            }
            return Result;
        }


        public Object[] getViolationsLatLong(string sessionid, string fromDateStr, string toDateStr, string violationtype)
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            string query = string.Empty;
            StringBuilder Query = new StringBuilder();
            Query.Append("select ag.groupId from accountgroups ag, users u, sessions s, usersgroupsmap ug where");
            Query.Append(" s.sessionid =? and u.login = s.login and u.login = ug.login and ag.groupid = ug.groupid;");

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("sessionid", sessionid);
            int groupid = Convert.ToInt16(dbx.executeScalar(Query.ToString(), lParameter));

            Query.Clear();
            lParameter.Clear();
            Query.Append("select s.vehicleid,type, DATE_FORMAT(timestamp, '%d-%m-%Y %H:%i:%s'),latitude,longitude,Location,v.IconType,remarks,duration from storevehicleviolations PARTITION(" + part + ") AS s, vehiclesgroupsmap vg, vehicles v where ");
            Query.Append("s.vehicleid = vg.vehicleid and vg.vehicleid = v.vehicleid and vg.groupid =? and timestamp between ? and ? and type=? and latitude is not null and longitude is not null;");
            lParameter.Add("groupid", groupid);
            lParameter.Add("timestamp1", fromDateStr);
            lParameter.Add("timestamp2", toDateStr);
            lParameter.Add("type", violationtype);
            DataSet dsViolations = dbx.executeQuery(Query.ToString(), lParameter);
            DataTable dtViolations = dsViolations.Tables[0];
            ArrayList ViolationsList = new ArrayList();
            foreach (DataRow row in dtViolations.Rows)
            {
                ViolationsList.Add(row.ItemArray);
            }
            return ViolationsList.ToArray();

        }

        public DataTable GetMainConnAndDisConnection(string AccountId, DateTime fromDate, DateTime toDate, string selectedVehicles = "", string GroupId = "")
        {
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromDate", formatDBDate(fromDate));
            lParameter.Add("toDate", formatDBDate(toDate));

            string temp = GetDateTablePartitions(fromDate, toDate, partions);
            string query = "select distinct * from panic PARTITION(" + temp + ") AS p where p.alertTimestamp>? " +
                           " and p.alertTimestamp<? and (type='MAIN CONNECTED' or type='MAIN DISCONNECTED') ";
            if (GroupId != "" && GroupId != "0")
            {
                lParameter.Add("GroupId", GroupId);
                query += " and p.vehicleId in (select vehicleid from vehiclesgroupsmap where GroupId=?) ";
            }
            else
            {
                lParameter.Add("AccountId", AccountId);
                query += " and p.vehicleId in (select vehicleid from vehicles where accountid=?) ";
            }
            if (!string.IsNullOrEmpty(selectedVehicles))
            {
                String[] vals = selectedVehicles.Replace("'", "").Replace("\"", "").Split(',');
                string inparam = "";
                for (int i = 0; i < vals.Length; i++)
                {
                    if (i == 0)
                        inparam += ("?");
                    else
                        inparam += (",?");
                    lParameter.Add("truckId" + i, vals[i]);
                }
                query += " and p.vehicleId in (" + inparam + ") ";
            }
            query += " order by p.vehicleId,p.alertTimestamp";
            DataSet vehicles = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = vehicles.Tables[0];
            return table;
        }
