        public void SaveAssetTransation(string CustomerId, string CustomerDCAssignId, int TotalQuantity, string TransationType, string LoginUser, string ActionType, string ProductId, bool IsChanged)
        {
            try
            {
                string Query = string.Empty;
                Query = "select a.Quantity,a.DateTime,a.customerId from asset_master a join customerinfo " +
                        "c on a.CustomerId=c.customerId join dc_productinfo p on a.ProductId=p.Id where a.Id in " +
                        "(select max(a1.Id) from asset_master a1 left join customerinfo ci on " +
                        "ci.customerId=a1.CustomerId join users s on s.login=ci.LoginUser where ci.customerId='" + CustomerId + "' " +
                        "group by a1.ProductId,s.login) and a.ProductId=" + ProductId + "  order by a.DateTime desc";
                DataTable lAsset = dbx.executeQuery(Query).Tables[0];
                if (lAsset.Rows.Count > 0)
                {

                    int EstimatedCurrentAssets = GetEstimatedCurrentAsset(lAsset, CustomerId, ProductId, TotalQuantity, Convert.ToInt32(TransationType));

                    Query = "insert into asset_transaction (CustomerId,CustomerDCAssignId,ProductId,CurrentAssets,UpdatedAssets,TransactionTime,TransactionType) " +
                            "values (" + CustomerId + "," + CustomerDCAssignId + "," + ProductId + "," + EstimatedCurrentAssets + "," + TotalQuantity + ",'" + formatDBDate(System.DateTime.Now) + "'," + TransationType + ")";
                    dbx.executeNonQuery(Query);
                }

            }
            catch { }
        }

        public string deleteJRM(string name, string type, string minlat, string maxlat, string minlng, string maxlng)
        {
            try
            {
                StringBuilder query = new StringBuilder();
                query.Append("delete from waypointsref where minlat=? and maxlat=? and minlong=? and maxlong=?");
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("minlat", minlat);
                lParameter.Add("maxlat", maxlat);
                lParameter.Add("minlong", minlng);
                lParameter.Add("maxlong", maxlng);

                dbx.executeNonQuery(query.ToString(), lParameter);
                query.Clear();
                lParameter.Clear();
                query.Append("delete from plantgeolocations where minlatitude=? and maxlatitude=? and minlongitude=? and maxlongitude=? and locstr=? and type=?;");
                lParameter.Add("minlatitude", minlat);
                lParameter.Add("maxlatitude", maxlat);
                lParameter.Add("minlongitude", minlng);
                lParameter.Add("maxlongitude", maxlng);
                lParameter.Add("locstr", name);
                lParameter.Add("type", type);

                return dbx.executeNonQuery(query.ToString(), lParameter).ToString();
            }
            catch
            {
                return "0";
            }
        }

