                           " join driverinfo d on d.AssignedVehicleId=v.VehicleID and d.IMEI is not null and d.IMEI<>'' " +
                           " where a.IsDelivered=1 and a.DeliveredQty='' and a.UnloadingInTime>'" + formatDBDate(DateTime.Now.AddHours(-10)) + "' and a.UnloadingInTime<'" + formatDBDate(DateTime.Now.AddHours(-1)) + "' " +
