                           "v.DateTime,v.LoadingOutTime,c.UnloadingInTime,c.DeliveredOn,c.CustomerId,c.SourceId from vehicledctrip v join customerdcassign c " +
                           "on c.DCTripId=v.id join customerinfo ci on c.CustomerId= ci.customerId " +
                           "where ci.AccountId=? and v.DateTime between ? and ?";
            lParameter.Add("AccountId", AccountId);
            lParameter.Add("FromDate", FromDate);
            lParameter.Add("ToDate", ToDate);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

