        public DataTable GetUnauthorizedHaltsByAccountId(string AccountId, string FromDate, string ToDate)
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(FromDate), Convert.ToDateTime(ToDate), partions);
            var lParameter = new Dictionary<string, object>();
            string query = "select s.vehicleId,s.Location,s.timestamp,s.duration from storevehicleviolations PARTITION(" + part + ") AS s join vehicles v on " +
                           "s.vehicleId=v.VehicleID where s.`type`='UNSCHEDULED STOP' and v.AccountID=? and " +
                            "s.timestamp between ? and ?";
            lParameter.Add("AccountId", AccountId);
            lParameter.Add("FromDate", FromDate);
            lParameter.Add("ToDate", ToDate);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetUnauthorizedHaltsByRegion(string GroupId, string FromDate, string ToDate)
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(FromDate), Convert.ToDateTime(ToDate), partions);
            var lParameter = new Dictionary<string, object>();
            string query = "select s.vehicleId,s.Location,s.timestamp,s.duration from storevehicleviolations PARTITION(" + part + ") AS s join vehiclesgroupsmap v on " +
                           "s.vehicleId=v.VehicleId where s.`type`='UNSCHEDULED STOP' and v.GroupId=? and " +
                            "s.timestamp between ? and ?";
            lParameter.Add("GroupId", GroupId);
            lParameter.Add("FromDate", FromDate);
            lParameter.Add("ToDate", ToDate);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

