        public DataTable getViosummaryData(int groupid, string date, string client, string PassengerTrip = "0")
        {
            string query = "";
            if (groupid == 8102 || groupid == 7359 || groupid == 8189 || groupid == 8230 || groupid == 8601 || groupid == 8722 || groupid == 8752 || groupid == 8814)// saplg/vodafoneidea/sri ram/viplg/RHG/vipl wb/tnsvoda/vil mh to get onroadvehicles
            {
                query = "select count(DISTINCT v.VehicleId) as totalvehicles,(COUNT(distinct d.vehicleid)) as onroad_vehicles," +
                            " (COUNT(distinct IF(cd > 0, d.vehicleid, 0)) - 1) as cd_count , (COUNT(distinct IF(maxsp > 0, d.vehicleid, 0)) - 1) as maxspeed_count," +
                            " (COUNT(distinct IF(IsNightDrivingViol > 0, d.vehicleid, 0)) - 1) as nd_count,(COUNT(distinct IF(md > 0, d.vehicleid, 0)) - 1) as md_count," +
							" (COUNT(distinct IF(d.harshbraking_count > 0, d.vehicleid, 0)) - 1) as HB_Count,(COUNT(distinct IF(d.harshaccln_count > 0, d.vehicleid, 0)) - 1) as HA_Count from daywisevehviosummary d " +
                            " join vehiclesgroupsmap v  on d.groupid = v.GroupId " +
                            " and d.IsTrip = 1 and(d.groupid = '" + groupid + "' or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid ='" + groupid + "') ) and  d.date='" + Convert.ToDateTime(date).ToString("yyyy-MM-dd") + "' and d.trip_starttime<>'0000-00-00 00:00:00' and  d.Kms_driven>1";
            }
            else
            {
                query = "select count(DISTINCT vehicleid) as totalvehicles,(COUNT(distinct IF(Kms_driven > 10,vehicleid,0))-1) as onroad_vehicles ,(COUNT(distinct IF(cd>0,vehicleid,0))-1) as cd_count , " +
                              "(COUNT(distinct IF(maxsp>0,vehicleid,0))-1) as maxspeed_count,(COUNT(distinct IF(IsNightDrivingViol>0,vehicleid,0))-1) as nd_count,(COUNT(distinct IF(md>0,vehicleid,0))-1) as md_count, " +
                              "(COUNT(distinct IF(d.harshbraking_count>0,vehicleid,0))-1) as HB_Count,(COUNT(distinct IF(d.harshaccln_Count>0,vehicleid,0))-1) as HA_Count,(COUNT(distinct d.TripId)) as TripCount " +
                              "from daywisevehviosummary d " +
                              "where d.IsTrip=1 and (d.groupid='" + groupid + "' or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid='" + groupid + "') ) and  d.date='" + Convert.ToDateTime(date).ToString("yyyy-MM-dd") + "' and d.trip_starttime<>'0000-00-00 00:00:00' ";
            }
            if (!string.IsNullOrEmpty(client))
                query += " and REPLACE(d.vehicleid,' ','') in (Select vehicle from vehdriver_staticdata where CT like '%" + client + "%')";
            if (PassengerTrip == "1")
                query += " and d.TripId>0";
            DataSet data = dbx.executeQuery(query.ToString());
            DataTable table = data.Tables[0];
            if (table.Rows.Count > 0)
            {
                if (table.Rows[0]["onroad_vehicles"].ToString() == "-1")
                    table.Rows[0]["onroad_vehicles"] = "0";
                if (table.Rows[0]["cd_count"].ToString() == "-1")
                    table.Rows[0]["cd_count"] = "0";
                if (table.Rows[0]["maxspeed_count"].ToString() == "-1")
                    table.Rows[0]["maxspeed_count"] = "0";
                if (table.Rows[0]["nd_count"].ToString() == "-1")
                    table.Rows[0]["nd_count"] = "0";
                if (table.Rows[0]["md_count"].ToString() == "-1")
                    table.Rows[0]["md_count"] = "0";
                if (table.Rows[0]["HB_Count"].ToString() == "-1")
                    table.Rows[0]["HB_Count"] = "0";
                if (table.Rows[0]["HA_Count"].ToString() == "-1")
                    table.Rows[0]["HA_Count"] = "0";
            }
            if (groupid == 8102 || groupid == 7359 || groupid == 8189 || groupid == 8230 || groupid == 8601 || groupid == 8722 || groupid == 8752 || groupid == 8814)// saplg/vodafoneidea/sri ram/viplg/RHG/vipl wb/tnsvoda/vil mh to get onroadvehicles Modified  on 23/8/2021 as mismatch in login vehicles(VIL MH)
            {
                DataTable dtcount = dbx.executeQuery(query).Tables[0];
                DataTable dt1 = GetVehiclesByGroupId(Convert.ToString(groupid)).Tables[0];//number of trucks in login
                int total_vehicles = dt1.Rows.Count;
                table.Rows[0]["totalvehicles"] = total_vehicles.ToString();
                //int total_vehicles = Convert.ToInt32(dtcount.Rows[0]["totalvehicles"]);
                //table.Rows[0]["totalvehicles"] = total_vehicles.ToString();
                int onroad_vehicles = Convert.ToInt32(dtcount.Rows[0]["onroad_vehicles"]);
                table.Rows[0]["onroad_vehicles"] = onroad_vehicles.ToString();


                query = "select COUNT(distinct d.vehicleid) from daywisevehviosummary d" +
                 " where (d.groupid='" + groupid + "' or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid='" + groupid + "') ) and  d.date='" + Convert.ToDateTime(date).ToString("yyyy-MM-dd") + "' and d.trip_starttime<>'0000-00-00 00:00:00' " +
                 " and (d.startlatlng!='' or d.endlatlng!='' or d.nd_startlatlng!='' or d.nd_endlatlng!='' or d.totalruntime>0 or d.Kms_driven >0 )";
                if (!string.IsNullOrEmpty(client))
                    query += " and REPLACE(d.vehicleid,' ','') in (Select vehicle from vehdriver_staticdata where CT like '%" + client + "%')";
                int Reachbles = Convert.ToInt32(dbx.executeScalar(query.ToString()));

                table.Columns.Add("NotReachables");
                table.Rows[0]["NotReachables"] = (total_vehicles - Reachbles).ToString();

                query = "select COUNT(distinct d.vehicleid) from daywisevehviosummary d" +
                        "  left JOIN lastupdtdata l ON l.truckid = d.vehicleid " +
                        " where(d.groupid = '" + groupid + "' or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid = '" + groupid + "') ) and d.date = '" + Convert.ToDateTime(date).ToString("yyyy-MM-dd") + "'" +
                        " and(l.timestamp < '" + Convert.ToDateTime(date).AddDays(-6).ToString("yyyy-MM-dd 00:00") + "' or l.timestamp IS NULL)";
                if (!string.IsNullOrEmpty(client))
                    query += " and REPLACE(d.vehicleid,' ','') in (Select vehicle from vehdriver_staticdata where CT like '%" + client + "%')";
                int NotReachables7Days = Convert.ToInt32(dbx.executeScalar(query.ToString()));
                table.Columns.Add("NotReachables7Days");
                table.Rows[0]["NotReachables7Days"] = NotReachables7Days.ToString();
            }
            else
            {
                query = "select COUNT(distinct d.vehicleid) from daywisevehviosummary d" +
                   " where (d.groupid='" + groupid + "' or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid='" + groupid + "') ) and  d.date='" + Convert.ToDateTime(date).ToString("yyyy-MM-dd") + "' and d.trip_starttime<>'0000-00-00 00:00:00' " +
                   " and (d.startlatlng!='' or d.endlatlng!='' or d.nd_startlatlng!='' or d.nd_endlatlng!='' or d.totalruntime>0 or d.Kms_driven >0 )";
                if (!string.IsNullOrEmpty(client))
                    query += " and REPLACE(d.vehicleid,' ','') in (Select vehicle from vehdriver_staticdata where CT like '%" + client + "%')";
                int Reachbles = Convert.ToInt32(dbx.executeScalar(query.ToString()));


                query = "select COUNT(distinct d.vehicleid) from daywisevehviosummary d" +
                      " where (d.groupid='" + groupid + "' or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid='" + groupid + "') ) and  d.date='" + Convert.ToDateTime(date).ToString("yyyy-MM-dd") + "' and d.trip_starttime<>'0000-00-00 00:00:00' ";
                if (!string.IsNullOrEmpty(client))
                    query += " and REPLACE(d.vehicleid,' ','') in (Select vehicle from vehdriver_staticdata where CT like '%" + client + "%')";
                int total_vehicles = Convert.ToInt32(dbx.executeScalar(query.ToString()));
                table.Rows[0]["totalvehicles"] = total_vehicles.ToString();

                query = "select COUNT(distinct d.vehicleid) from daywisevehviosummary d" +
                  " where (d.groupid='" + groupid + "' or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid='" + groupid + "') ) and  d.date='" + Convert.ToDateTime(date).ToString("yyyy-MM-dd") + "' and d.trip_starttime<>'0000-00-00 00:00:00' " +
                  " and d.Kms_driven > 10";
                if (!string.IsNullOrEmpty(client))
                    query += " and REPLACE(d.vehicleid,' ','') in (Select vehicle from vehdriver_staticdata where CT like '%" + client + "%')";
                int onroad_vehicles = Convert.ToInt32(dbx.executeScalar(query.ToString()));
                table.Rows[0]["onroad_vehicles"] = onroad_vehicles.ToString();

                table.Columns.Add("NotReachables");
                table.Rows[0]["NotReachables"] = (Convert.ToInt32(table.Rows[0]["totalvehicles"]) - Reachbles).ToString();

                query = "select COUNT(distinct d.vehicleid) from daywisevehviosummary d" +
                        "  left JOIN lastupdtdata l ON l.truckid = d.vehicleid " +
                        " where(d.groupid = '" + groupid + "' or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid = '" + groupid + "') ) and d.date = '" + Convert.ToDateTime(date).ToString("yyyy-MM-dd") + "'" +
                        " and(l.timestamp < '" + Convert.ToDateTime(date).AddDays(-6).ToString("yyyy-MM-dd 00:00") + "' or l.timestamp IS NULL)";
                if (!string.IsNullOrEmpty(client))
                    query += " and REPLACE(d.vehicleid,' ','') in (Select vehicle from vehdriver_staticdata where CT like '%" + client + "%')";
                int NotReachables7Days = Convert.ToInt32(dbx.executeScalar(query.ToString()));
                table.Columns.Add("NotReachables7Days");
                table.Rows[0]["NotReachables7Days"] = NotReachables7Days.ToString();
            }
            return table;
        }

