        public DataTable GetPsngrInfoWithValidationWithImei(string imei, string flag, string appName)
        {
            string query = "select d.*,c.AppKeyWord,'' PsngrId from driverinfo d left join psngr_config c on d.AccountId=c.AccountId where d.IMEI=? and d.Active=1 "
                          + "and c.AppName=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("IMEI", imei);
            lParameter.Add("AppName", appName);
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            if (flag == "Validate")
                return dt;
            else if (flag == "Tag")
            {
                if (dt.Rows.Count > 0)
                {
                    string sessionid = "";
                    if (!String.IsNullOrEmpty(dt.Rows[0]["AssignedVehicleId"].ToString()))
                        sessionid = getSessionIdByVehicle(dt.Rows[0]["AssignedVehicleId"].ToString());
                    query = "select t.VehicleId,t.TimeStamp TagInTime,(case when t.TagInOrOut=0 then 'TagIn' else 'TagOut' end) as Status,? as sessionid,0 "
                                      + "TagInOMR from taging t join driverinfo d on d.DriverId=t.DriverId and d.AssignedVehicleId=t.VehicleId and "
                                      + "t.Source='Driver Passenger App' where d.IMEI=? order by t.TagId desc limit 1";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("sessionid", sessionid);
                    lParameter.Add("IMEI", imei);
                    dt = dbx.executeQuery(query, lParameter).Tables[0];
                    if (dt.Rows.Count == 0)
                    {
                        query = "select d.AssignedVehicleId VehicleId,'' as TagInTime,'TagIn' as Status,? as sessionid,0 TagInOMR from driverinfo d where "
                              + "d.IMEI=? limit 1";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("sessionid", sessionid);
                        lParameter.Add("IMEI", imei);
                        dt = dbx.executeQuery(query, lParameter).Tables[0];
                    }
                    return dt;
                }
                else
                    return null;
            }
            else
            {
                return null;
            }
        }

        public DataTable GetPsngrInfoWithValidation(string mobileno, string flag, string appName)
        {
            try
            {
                if (appName == "")
                    appName = "com.sensel.passengerapp";
                string query = "select p.*,c.AppKeyWord from psngr_info p left join psngr_config c on p.AccountId=c.AccountId where "
                        //string query = "select p.PsngrId,p.PsngrName,p.MobileNo,p.AccountId,p.RegionId,p.Gender,p.EmpId,p.IsLogged,p.LogggedOn,p.Active,CONCAT(p.AssignedVehicleId, '  -9743400098') as 'AssignedVehicleId',p.Addedby,p.AddedOn,p.Designation,p.HomeLatitude,p.HomeLongitude,p.HomeLocationStr,c.AppKeyWord from psngr_info p left join psngr_config c on p.AccountId=c.AccountId where "
                        + "p.MobileNo=? and p.Active=1 and c.AppName=?";
                if (flag == "Tag")
                {
                    query += " and IsLogged=1";
                }
                query += " order by p.PsngrId desc limit 1";
                if (appName == "com.sensel.passengerapp.drivertrack")
                {
                    query = "select d.*,c.AppKeyWord,'' PsngrId from driverinfo d left join psngr_config c on d.AccountId=c.AccountId where d.MobileNo=? and d.Active=1 "
                          + "and c.AppName=?";
                }
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("mobileno", mobileno);
                lParameter.Add("AppName", appName);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];

                if (dt.Rows.Count > 0)
                {
                    string AccountId = dt.Rows[0]["AccountId"].ToString();
                    if (flag == "Validate")
                    {
                        return dt;
                    }
                    else if (flag.Contains("OTP"))
                    {
                        if (appName != "com.sensel.passengerapp.drivertrack")
                        {
                            query = "update psngr_info set IsLogged=1 where MobileNo=? and Active=1";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("mobileno", mobileno);
                            dbx.executeNonQuery(query, lParameter);
                        }
                        query = "select a.globalaccountid,u.login from accounts a left join users u on u.Name=a.Name where a.ID=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("AccountId", dt.Rows[0]["AccountId"]);
                        return dbx.executeQuery(query, lParameter).Tables[0];
                    }
                    else if (flag == "Vehicles")
                    {
                        //query = "select replace(v.VehicleId,' ','') VehicleId,Concat(d.Name,':-',d.LicenceNo) as Driver from "
                        //      + "vehicleinfo v inner join vehiclesgroupsmap vg on v.VehicleId=vg.VehicleId left join driverinfo d "
                        //      + "on d.AssignedVehicleId=vg.VehicleId and d.ApprovedDateTime in (select max(di.ApprovedDateTime) from driverinfo di"
                        //      + " where di.AssignedVehicleId=d.AssignedVehicleId) where v.RegionId=? and vg.GroupId=(select "
                        //      + "min(u.GroupId) from accountgroups u where u.AccountID=?) group by v.VehicleId order by v.VehicleId";
                        
                        //Added code by Madhuri for passenger app - optimized below query for fetching the vehicle list 28072025

                        query = "SELECT REPLACE(v.VehicleId, ' ', '') AS VehicleId, CONCAT(d.Name, ':-', d.LicenceNo) AS Driver FROM vehicleinfo v "
                              + "INNER JOIN vehiclesgroupsmap vg ON v.VehicleId = vg.VehicleId LEFT JOIN(SELECT di1.AssignedVehicleId, di1.Name, "
                              + "di1.LicenceNo FROM driverinfo di1 INNER JOIN (SELECT AssignedVehicleId, MAX(ApprovedDateTime) AS MaxApprovedDateTime "
                              + " FROM driverinfo GROUP BY AssignedVehicleId) latest ON di1.AssignedVehicleId = latest.AssignedVehicleId  "
                              + "AND di1.ApprovedDateTime = latest.MaxApprovedDateTime) d ON d.AssignedVehicleId = vg.VehicleId "
                              + " WHERE v.RegionId = ? AND vg.GroupId = (SELECT MIN(u.GroupId) FROM accountgroups u WHERE u.AccountID = ?)  "
                              + " GROUP BY v.VehicleId, d.Name, d.LicenceNo ORDER BY v.VehicleId ";

                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("RegionId", dt.Rows[0]["RegionId"]);
                        lParameter.Add("AccountId", dt.Rows[0]["AccountId"]);
                        return dbx.executeQuery(query, lParameter).Tables[0];
                    }
                    else if (flag == "Drivers")
                    {
                        query = "select d.DriverId,Concat(d.Name,':-',d.LicenceNo) as Driver from driverinfo d where d.AccountId=? group by Driver";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("AccountId", dt.Rows[0]["AccountId"]);
                        return dbx.executeQuery(query, lParameter).Tables[0];
                    }
                    else if (flag == "Zones")
                    {
                        query = "select distinct concat(t.ZoneName,'-',t.City) zone,'' from psngr_tower_locations t  where t.RegionID=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("RegionId", dt.Rows[0]["RegionId"]);
                        return dbx.executeQuery(query, lParameter).Tables[0];
                    }
                    else if (flag == "Towers")
                    {
                        query = "select distinct l.TowerName from psngr_info i join psngr_tag t on t.PsngrId=i.PsngrId join psngr_tower_locations l on "
                            + "l.TowerName=t.TowerName and l.RegionID=i.RegionId where i.MobileNo=? order by t.Id desc limit 500";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("MobileNo", mobileno);
                        DataTable freqTower = dbx.executeQuery(query, lParameter).Tables[0];
                        if (freqTower == null || freqTower.Rows.Count == 0)
                        {
                            query = "select distinct t.TowerName from psngr_info i join psngr_tower_locations t on t.RegionID=i.RegionId where i.MobileNo=? order by "
                                + "t.TowerName limit 500";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("MobileNo", mobileno);
                            return dbx.executeQuery(query, lParameter).Tables[0];
                        }
                        else
                            return freqTower;
                    }
                    else if (flag == "CheckList")
                    {
                        query = "select p.PsngrChkId,pc.ChkName,pc.`Type` from psngr_chklist_map p left join psngr_chklist pc on pc.ChkId="
                              + "p.PsngrChkId where p.CustAccountId=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("AccountId", dt.Rows[0]["AccountId"]);
                        DataTable chkdt = dbx.executeQuery(query, lParameter).Tables[0];
                        if (chkdt.Rows.Count > 0)
                            return chkdt;
                        else
                        {
                            query = "select p.PsngrChkId,pc.ChkName,pc.`Type` from psngr_chklist_map p left join psngr_chklist pc on pc.ChkId=p.PsngrChkId where p.CustAccountId=0";
                            return dbx.executeQuery(query).Tables[0];
                        }
                    }
                    else if (flag == "Tag")
                    {
                        string sessionid = "";
                        if (!String.IsNullOrEmpty(dt.Rows[0]["AssignedVehicleId"].ToString()))
                            sessionid = getSessionIdByVehicle(dt.Rows[0]["AssignedVehicleId"].ToString());
                        if (appName == "com.sensel.passengerapp.drivertrack")
                        {
                            query = "select t.VehicleId,t.TimeStamp TagInTime,(case when t.TagInOrOut=0 then 'TagIn' else 'TagOut' end) as Status,? as sessionid,0 "
                                  + "TagInOMR from taging t join driverinfo d on d.DriverId=t.DriverId and d.AssignedVehicleId=t.VehicleId and "
                                  + "t.Source='Driver Passenger App' where d.MobileNo=? order by t.TagId desc limit 1";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("sessionid", sessionid);
                            lParameter.Add("MobileNo", mobileno);
                            dt = dbx.executeQuery(query, lParameter).Tables[0];
                            if (dt.Rows.Count == 0)
                            {
                                query = "select d.AssignedVehicleId VehicleId,'' as TagInTime,'TagIn' as Status,? as sessionid,0 TagInOMR from driverinfo d where "
                                      + "d.MobileNo=? limit 1";
                                lParameter = new Dictionary<string, object>();
                                lParameter.Add("sessionid", sessionid);
                                lParameter.Add("MobileNo", mobileno);
                                dt = dbx.executeQuery(query, lParameter).Tables[0];
                            }
                        }
                        else
                        {
                            if (dt.Rows[0]["AccountId"].ToString() != "4453")
                            {
                                query = "select p.VehicleId,p.TagInTime,'TagOut' as Status,? as sessionid,p.TagInOMR "
                                  + "from psngr_tag p where p.Id=(select Max(p.Id) as Id from psngr_tag p where p.PsngrId=(select "
                                  + "Max(pi.PsngrId) from psngr_info pi where pi.MobileNo=? and Active=1) and (p.TagOutTime "
                                  + "is null or trim(p.TagOutTime)=''))";
                                lParameter = new Dictionary<string, object>();
                                lParameter.Add("sessionid", sessionid);
                                lParameter.Add("MobileNo", mobileno);
                                dt = dbx.executeQuery(query, lParameter).Tables[0];
                            }
                            else if (dt.Rows[0]["AccountId"].ToString() == "4453")
                            {
                                query = "select p.VehicleId,p.TagInTime,'TagOut' as Status,? as sessionid,p.TagInOMR "
                                  + "from psngr_tag p where p.Id=(select Max(p.Id) as Id from psngr_tag p where p.PsngrId=(select "
                                  + "Max(pi.PsngrId) from psngr_info pi where pi.MobileNo=? and Active=1) and (p.TagOutTime "
                                  + "is null or trim(p.TagOutTime)=''))";
                                lParameter = new Dictionary<string, object>();
                                lParameter.Add("sessionid", sessionid);
                                lParameter.Add("MobileNo", mobileno);
                                dt = dbx.executeQuery(query, lParameter).Tables[0];

                                if (dt.Rows.Count > 0)
                                {
                                    query = "select CONCAT(p.VehicleId, ' - 9743400098') as 'VehicleId',p.TagInTime,'TagOut' as Status,? as sessionid,p.TagInOMR "
                                                                      + "from psngr_tag p where p.Id=(select Max(p.Id) as Id from psngr_tag p where p.PsngrId=(select "
                                                                      + "Max(pi.PsngrId) from psngr_info pi where pi.MobileNo=? and Active=1) and (p.TagOutTime "
                                                                      + "is null or trim(p.TagOutTime)=''))";
                                    lParameter = new Dictionary<string, object>();
                                    lParameter.Add("sessionid", sessionid);
                                    lParameter.Add("MobileNo", mobileno);
                                    dt = dbx.executeQuery(query, lParameter).Tables[0];
                                }
                            }

                            if (dt.Rows.Count == 0)
                            {
                                query = "select p.AssignedVehicleId as VehicleId,'' as TagInTime,'TagIn' as Status,? as sessionid,0 as "
                                          + "TagInOMR from psngr_info p where p.MobileNo=? order by p.PsngrId desc limit 1";
                                lParameter = new Dictionary<string, object>();
                                lParameter.Add("sessionid", sessionid);
                                lParameter.Add("MobileNo", mobileno);
                                dt = dbx.executeQuery(query, lParameter).Tables[0];
                            }
                        }
                        return dt;
                    }
                    else
                        return null;
                }
                else
                {
                    if (appName != "com.sensel.passengerapp.drivertrack")
                    {
                        query = "update psngr_info set IsLogged=1 where MobileNo=? and Active=1";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("mobileno", mobileno);
                        dbx.executeNonQuery(query, lParameter);
                    }
                    DataRow dr = dt.NewRow();
                    dr[1] = "No Data Logout";
                    dt.Rows.Add(dr);
                    return dt;
                }
            }
            catch (Exception e)
            {
                return null;
            }
        }

        public DataTable GetPsngrTowerLocations(string mobileno, string zone, string enteredkey)
        {
            string query = "select t.TowerName from psngr_tower_locations t join psngr_info i on i.RegionId=t.RegionID  where concat(t.ZoneName,'-',t.City)=? and t.TowerName like '%" + enteredkey
                + "%' and i.MobileNo=? order by t.TowerName";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("ZoneName", zone);
            lParameter.Add("MobileNo", mobileno);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public string CheckPsngrTowerLocation(string mobileno, string towername)
        {
            string query = "select count(*) from psngr_info p join psngr_tower_locations t on t.RegionID=p.RegionId where p.MobileNo=? and t.TowerName=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("MobileNo", mobileno);
            lParameter.Add("TowerName", towername);
            return Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString()) > 0 ? "true" : "false";
        }

        public string getSessionByPsngrID(string psngrId)
