                         + " join psngr_info p on p.AccountId=g.AccountID where p.PsngrId=?) union select '' limit 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("PsngrId", psngrId);
            return dbx.executeScalar(query, lParameter).ToString();
        }

