        public string InsertPsngrChecklist(string psngrId, string vehicleId, string type, string rules, string wfmid, string ptw,
            string driverId, string IMEI, string Lat, string Lng, string Manual, string DriverDetails, string OMR, string gpscheckid, string gpsReason, string driverImage, string towername, string vehiclephoto, string Tagin_OdometerPhoto, string Tagout_OdometerPhoto)
        {
            try
            {
                DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
                string formatDate = formatDBDate(now); 
				int AccountId = getAccountIdByVehicleId(vehicleId);
				int groupid = getGroupIdByVehicleid(vehicleId);
				if (psngrId.Equals("DriverId"))
                {
                    string query = "select * from taging t where t.DriverId=? and t.Source='Driver Passenger App' order by t.TagId desc limit 1";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("DriverId", driverId);
                    DataTable tag = dbx.executeQuery(query, lParameter).Tables[0];
                    if (type == "TagIn")
                    {
                        if (tag.Rows.Count == 0 || (tag.Rows.Count > 0 && tag.Rows[0]["TagInOrOut"].ToString() == "0"))
                        {
                            query = "INSERT INTO `taging` (`DriverId`, `DriverName`, `IMEI`, `MobileLatLng`, `VehicleId`, `TagInOrOut`, `TimeStamp`,`Source`) VALUES "
                                  + "(?, ?, ?, ?, ?, ?, ?, 'Driver Passenger App')";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("DriverId", driverId);
                            lParameter.Add("DriverName", DriverDetails);
                            lParameter.Add("IMEI", IMEI);
                            lParameter.Add("MobileLatLng", Lat + "," + Lng);
                            lParameter.Add("VehicleId", vehicleId);
                            lParameter.Add("TagInOrOut", 1);
                            lParameter.Add("TimeStamp", formatDate);
                            return dbx.executeNonQuery(query, lParameter).ToString();
                        }
                        else
                            return "0";
                    }
                    else if (type == "TagOut")
                    {
                        if (tag.Rows.Count > 0 && tag.Rows[0]["TagInOrOut"].ToString() == "1")
                        {
                            query = "INSERT INTO `taging` (`DriverId`, `DriverName`, `IMEI`, `MobileLatLng`, `VehicleId`, `TagInOrOut`, `TimeStamp`,`Source`) VALUES "
                                  + "(?, ?, ?, ?, ?, ?, ?, 'Driver Passenger App')";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("DriverId", driverId);
                            lParameter.Add("DriverName", DriverDetails);
                            lParameter.Add("IMEI", IMEI);
                            lParameter.Add("MobileLatLng", Lat + "," + Lng);
                            lParameter.Add("VehicleId", vehicleId);
                            lParameter.Add("TagInOrOut", 0);
                            lParameter.Add("TimeStamp", formatDate);
                            return dbx.executeNonQuery(query, lParameter).ToString();
                        }
                        else
                            return "0";
                    }
                    else
                        return "0";
                }
                else
                {
                    string query = "select p.VehicleId,p.TagInTime,'TagOut' as Status from psngr_tag p where p.Id=(select Max(p.Id) as Id from "
                                 + "psngr_tag p where p.PsngrId=? and (p.TagOutTime is null or trim(p.TagOutTime)=''))";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("PsngrId", psngrId);
                    DataTable tag = dbx.executeQuery(query, lParameter).Tables[0];

                    if (tag.Rows.Count == 0 && type == "TagIn")
                    {
                        query = "select p.AccountId from psngr_info p where p.PsngrId=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("psngrId", psngrId);
                        string accountid = dbx.executeScalar(query, lParameter).ToString();
                        //this is only for nokia. 
                        if (accountid == "2100")
                        {
                            //if one psngr already tagin to vehicle another psngr should not tagin for the same.
                            query = "select p.PsngrId,i.PsngrName,i.MobileNo from psngr_tag p join psngr_info i on p.PsngrId=i.PsngrId where "
                                  + "replace(p.VehicleID,' ','')=? and p.TagOutTime is null and i.Active=1";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("vehicleId", vehicleId);
                            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                            if (dt.Rows.Count > 0)
                            {
                                return "PsngrMessage-" + dt.Rows[0]["PsngrName"].ToString() + "(" + dt.Rows[0]["MobileNo"].ToString()
                                    + ") already done TagIn for this vehicle. You are not allowed to TagIn until he closes the trip.";
                            }

                            //if one psngr already tagin to driver another psngr should not tagin for the same.
                            query = "select p.PsngrId,i.PsngrName,i.MobileNo from psngr_tag p join psngr_info i on p.PsngrId=i.PsngrId where p.DriverId!=0 and "
                                  + "p.DriverId=? and p.TagOutTime is null and i.Active=1";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("DriverId", driverId);
                            dt = dbx.executeQuery(query, lParameter).Tables[0];
                            if (dt.Rows.Count > 0)
                            {
                                return "PsngrMessage-" + dt.Rows[0]["PsngrName"].ToString() + "(" + dt.Rows[0]["MobileNo"].ToString()
                                    + ") already done TagIn for this driver. You are not allowed to TagIn until he closes the trip.";
                            }
                        }
                        query = "select v.VehicleID from vehicles v left join configdata c on c.TruckID=v.VehicleID where replace(v.VehicleID,' ','')=? and c.UID<300000";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("VehicleId", vehicleId);
                        DataTable veh = dbx.executeQuery(query, lParameter).Tables[0];
                        if (veh.Rows.Count > 0)
                        {
                            vehicleId = veh.Rows[0]["VehicleID"].ToString();
                            if (Manual == "1")
                                Manual = "2";
                        }
                        string wfmTask = null;
                        if (wfmid.Contains("@&"))
                        {
                            string[] str = wfmid.Split(new string[] { "@&" }, StringSplitOptions.None);
                            wfmid = str[0];
                            wfmTask = str[1];
                        }
						query = "INSERT INTO `psngr_tag` (`PsngrId`, `VehicleId`,`DriverId`, `TagInTime`, `TagInIMEI`, `TagInLat`, `TagInLng`, `WFM_ID`,WFM_Task, "
							 + "`PTW_Number`,`Manual`,DriverDetails,TagInOMR,GPS_CheckId,GPS_Reason,DriverImage,TowerName,TagIn_VehiclePhoto,TagIn_OdometerPhoto,TagOut_OdometerPhoto,GroupId,AccountId) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
						lParameter = new Dictionary<string, object>();
                        lParameter.Add("PsngrId", psngrId);
                        lParameter.Add("VehicleId", vehicleId);
                        lParameter.Add("DriverId", driverId);
                        lParameter.Add("TagInTime", formatDate);
                        lParameter.Add("TagInIMEI", IMEI);
                        lParameter.Add("TagInLat", Lat);
                        lParameter.Add("TagInLng", Lng);
                        lParameter.Add("WFM_ID", wfmid);
                        lParameter.Add("WFM_Task", wfmTask);
                        lParameter.Add("PTW_Number", ptw);
                        lParameter.Add("Manual", Manual);
                        lParameter.Add("DriverDetails", DriverDetails);
                        lParameter.Add("TagInOMR", OMR);
                        lParameter.Add("GPS_CheckId", gpscheckid);
                        lParameter.Add("GPS_Reason", gpsReason);
                        lParameter.Add("DriverImage", driverImage);
                        lParameter.Add("TowerName", towername);
                        lParameter.Add("TagIn_VehiclePhoto", vehiclephoto);
                        lParameter.Add("TagIn_OdometerPhoto", Tagin_OdometerPhoto); 
						lParameter.Add("TagOut_OdometerPhoto", Tagout_OdometerPhoto);
						lParameter.Add("GroupId", groupid);
						lParameter.Add("AccountId", AccountId);
						int res = dbx.executeNonQuery(query, lParameter);
						if (res > 0 && rules == "")
                        {
                            return res.ToString();
                        }
                        else if (res > 0)
                        {
                            string resStatus = "YES";
                            query = "select Max(p.Id) from psngr_tag p where p.PsngrId=?";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("psngrId", psngrId);
                            string id = dbx.executeScalar(query, lParameter).ToString();
                            query = "insert into psngr_chklist_status (TagId,ChkId,Status) values ";
                            string[] rule = rules.Split(new string[] { "@#" }, StringSplitOptions.None);
                            lParameter = new Dictionary<string, object>();
                            for (int i = 0; i < rule.Length; i++)
                            {
                                string[] checklist = rule[i].Split('|');
                                query += "(?,?,?)";
                                if (i == rule.Length - 1)
                                    query += ";";
                                else
                                    query += ",";
                                if (checklist[1].ToLower().Equals("no"))
                                    resStatus = "NO";
                                lParameter.Add("id" + i, id);
                                lParameter.Add("checklist0" + i, checklist[0]);
                                lParameter.Add("checklist1" + i, checklist[1]);
                            }
                            res = dbx.executeNonQuery(query, lParameter);
                            if (res > 0)
                            {
                                try
                                {
                                    DataTable Rules = GetPassengerTagingRules(id);
                                    string msg = string.Empty;
                                    query = "select * from psngr_info where PsngrId=?";
                                    lParameter = new Dictionary<string, object>();
                                    lParameter.Add("psngrId", psngrId);
                                    DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                                    string drivername = getdrivername(vehicleId);
                                    if (resStatus == "NO")
                                    {
                                        msg = vehicleId + "(" + drivername.Split(',')[0] + ") is Failed in Passenger Checklist,WFM ID:" + wfmid + "PTW:" + ptw + "<br/>";
                                        for (int k = 0; k < Rules.Rows.Count; k++)
                                        {
                                            if (Rules.Rows[k]["Status"].ToString().ToLower().Contains("no"))
                                                msg += Rules.Rows[k]["ChkName"] + ":<b>" + Rules.Rows[k]["Status"] + "</b><br/>";
                                        }
                                        msg += "Passenger Name:" + dt.Rows[0]["PsngrName"].ToString() + "(" + dt.Rows[0]["EmpId"].ToString() + ") - " + dt.Rows[0]["MobileNo"].ToString();
                                        AddTransporterNotifications(GetListOfUsersByVehicleID(vehicleId), vehicleId + "(" + drivername.Split(',')[0] + ") is Failed in Passenger Checklist", msg);
                                    }
                                    else
                                    {
                                        msg = vehicleId + "(" + drivername.Split(',')[0] + ") is Success in Passenger Checklist,WFM ID:" + wfmid + "PTW:" + ptw + "<br/>";
                                        msg += "Passenger Name:" + dt.Rows[0]["PsngrName"].ToString() + "(" + dt.Rows[0]["EmpId"].ToString() + ") - " + dt.Rows[0]["MobileNo"].ToString();
                                        AddTransporterNotifications(GetListOfUsersByVehicleID(vehicleId), vehicleId + "(" + drivername.Split(',')[0] + ") is Success in Passenger Checklist", msg);
                                    }
                                }
                                catch { }
                            }
                            if (res > 0 && driverId == "0")
                            {
                                try
                                {
                                    AddTransporterNotifications(GetListOfUsersByVehicleID(vehicleId), vehicleId + "-Non compliance Driver", vehicleId + " is assigned to non compliance driver. Driver Details -" + DriverDetails);
                                }
                                catch { }
                            }
                            return res.ToString();
                        }
                        else
                            return "0";
                    }
                    else if (tag.Rows.Count > 0 && type == "TagOut")
                    {
                        query = "select p.AccountId from psngr_info p where p.PsngrId=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("psngrId", psngrId);
                        string accountid = dbx.executeScalar(query, lParameter).ToString();
                        //this is only for Amazon. 
                        if (accountid == "5632")
                        {
                            query = "update psngr_info set AssignedVehicleId=ReallocatedVehicle where PsngrId=?";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("psngrId1", psngrId);
                            dbx.executeNonQuery(query, lParameter).ToString();
                        }
                        query = "select Max(p.Id) from psngr_tag p where p.PsngrId=? and (p.TagOutTime is null or trim(p.TagOutTime)='')";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("psngrId", psngrId);
                        string id = dbx.executeScalar(query, lParameter).ToString();
                        if (!String.IsNullOrEmpty(id))
                        {
                            query = "update psngr_tag set TagOutTime=?,TagOutIMEI=?,TagOutLat=?,TagOutLng=?,TagOutOMR=?,Tagout_OdometerPhoto=? where Id=?";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("formatDate", formatDate);
                            lParameter.Add("IMEI", IMEI);
                            lParameter.Add("Lat", Lat);
                            lParameter.Add("Lng", Lng);
                            lParameter.Add("OMR", OMR);
                            lParameter.Add("Tagout_OdometerPhoto", Tagout_OdometerPhoto);
                            lParameter.Add("id", id);
                            return dbx.executeNonQuery(query, lParameter).ToString();
                        }
                        else
                            return "0";
                    }
                    else
                        return "0";
                }
            }
            catch
            {
                return "0";
            }
        }
        //******************************************Dash Board **************************
        public DataTable Get_DashBoardviolation(string fromdate, string todate, int groupid, string group, string viotype, string time)
        {
            string where = " ";
            if (time == "Day")
            {
                where = "and hour(d.trip_starttime) < 20 and hour(d.trip_starttime)>= 8 ";
            }
            else if (time == "Night")
            {
                where = "and (hour(d.trip_starttime) >= 20 or hour(d.trip_starttime)< 8) ";
            }
            if (viotype == "crashes")
            {
                where = " ";
                if (time == "Day")
                {
                    where = "and (hour(c.timestamp) < 20 and hour(c.timestamp)>= 8)";
                }
                else if (time == "Night")
                {
                    where = "and (hour(c.timestamp) >= 20 or hour(c.timestamp)< 8)";
                }
                string query = "select c.VehicleId,di.Name as DriverName,concat(c.timestamp) as 'DateTime',c.DCLValue,c.Latitude,c.Longitude,c.remarks  from crash_events c left join driverinfo di on di.Driverid=c.DriverId where c.vehicleid in (select vehicleid from vehiclesgroupsmap where GroupId=?) and c.timestamp between ? and ? " + where;
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("GroupId", groupid);
                lParameter.Add("timestamp_start", fromdate);
                lParameter.Add("timestamp_end", todate);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            else if (viotype == "totalruntime")
            {
                string query = "select concat(" + group + ") as date,count(Nullif(totalruntime>480,''))as vcount,(count(Nullif(totalruntime>480,''))*100)/(count(distinct d.driverid)) as percentage from daywisevehviosummary d " +
               "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and (trip_starttime between ? and ?) " + where +
               "group by " + group + " ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("GroupId", groupid);
                lParameter.Add("trip_starttime", fromdate);
                lParameter.Add("trip_endtime", todate);

                //string query = "select concat(" + group + ") as date,count(Nullif(totalruntime>480,''))as vcount,(count(Nullif(totalruntime>480,''))*100)/(count(distinct d.driverid)) as percentage from daywisevehviosummary d " +
                //               "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=" + groupid + ") and (trip_starttime between '" + fromdate + "' and '" + todate + "') " + where +
                //               "group by " + group + " ";
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            else if (viotype == "IVMS")
            {
                string query = "select concat(" + group + ") as date,count(distinct IMEI) as vcount,(count(distinct IMEI)*100)/(select count(distinct Driverid) from driverinfo) as percentage from taging  t " +
                                "inner join vehicleinfo v on v.VehicleId=t.VehicleId " +
                                "inner join regioninfo r on r.RegionId=v.RegionId " +
                                "inner join transporterinfo ti on ti.TransporterId=v.Transporter " +
                                "where t.VehicleId in (select vehicleid from vehiclesgroupsmap m where m.GroupId=" + groupid + ") and TimeStamp>='" + fromdate + "' and TimeStamp<='" + todate + "' " + where +
                                "group by " + group + " ";
                return dbx.executeQuery(query).Tables[0];
            }
            else if (viotype == "DriverApp")
            {
                string query = "select di.Name,di.AssignedVehicleId as vehicle, ri.RegionName,max(concat(t.TimeStamp)) as LastTaging from driverinfo di" +
                               " inner join taging t on t.DriverId = di.DriverId" +
                               " inner join vehicleinfo vi on vi.VehicleId = t.VehicleId" +
                               " left join regioninfo ri on ri.RegionId = vi.RegionId" +
                               " where t.VehicleId in (select vehicleid from vehiclesgroupsmap vm where vm.GroupId = ?)" +
                               " and t.TimeStamp between ? and ?" +
                               " group by di.DriverId";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("GroupId", groupid);
                lParameter.Add("TimeStamp_start", fromdate);
                lParameter.Add("TimeStamp_end", todate);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            else if (viotype == "PassengerApp")
            {
                int accountid = GetAccountIdByGroupId(groupid);
                string query = "select p.PsngrName as Name,p.MobileNo,ri.RegionName,p.EmpId,max(concat(pt.TagInTime)) as LastLogin from psngr_info p " +
                                "inner join psngr_tag pt on pt.PsngrId=p.PsngrId " +
                                "left join regioninfo ri on ri.RegionId=p.RegionId " +
                                "where p.Active=1 and p.AccountId=? and pt.TagInTime between ? and ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AccountId", accountid);
                lParameter.Add("TagInTime_start", fromdate);
                lParameter.Add("TagInTime_end", todate);
                if (groupid != 2801)
                {
                    query += " and pt.VehicleId in (select vehicleid from vehiclesgroupsmap vm where vm.GroupId=?)";
                    lParameter.Add("GroupId", groupid);
                }
                query += " group by p.PsngrId";
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            else
            {
                string query = "select concat(" + group + ") as date,count(Nullif(" + viotype + ">0,''))as vcount,(count(Nullif(" + viotype + ">0,''))*100)/(count(distinct d.driverid)) as percentage from daywisevehviosummary d " +
                                "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and (trip_starttime between ? and ?) and d.IsTrip=1 " + where +
                                "group by " + group + " ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("GroupId", groupid);
                lParameter.Add("TagInTime_start", fromdate);
                lParameter.Add("TagInTime_end", todate);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
        }

        public DataTable Get_Transportewisedata(string fromdate, string todate, string viotype, int groupid, string time)
        {
            string where = " ";
            if (time == "Day")
            {
                where = "and hour(d.trip_starttime) < 20  and hour(d.trip_starttime)>= 8";
            }
            else if (time == "Night")
            {
                where = "and (hour(d.trip_starttime) >= 20 or hour(d.trip_starttime)< 8)";
            }

            if (viotype == "IVMS")
            {
                string query = "select ti.ShortName as Name ,count(distinct IMEI)as vcount from taging d " +
                    " inner join vehicleinfo vi on vi.vehicleid=d.vehicleid " +
                    " inner join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                    " where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and TimeStamp>=? and TimeStamp<=? " +
                    " group by ti.Name ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("GroupId", groupid);
                lParameter.Add("TimeStamp_start", fromdate);
                lParameter.Add("TimeStamp_end", todate);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            else if (viotype == "totalruntime")//driver drove more than 8 hours
            {
                string query = "select ti.ShortName as Name ,count(Nullif(totalruntime>480,''))as vcount from daywisevehviosummary d " +
                         " inner join vehicleinfo vi on vi.vehicleid=d.vehicleid " +
                         " inner join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                         " where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and (trip_starttime between ? and ?) and d.IsTrip=1 " + where +
                         " group by ti.Name ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("GroupId", groupid);
                lParameter.Add("Trip_start", fromdate);
                lParameter.Add("Trip_end", todate);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
            else
            {
                string query = "select ti.ShortName as Name ,count(Nullif(" + viotype + ">0,''))as vcount from daywisevehviosummary d " +
                        " inner join vehicleinfo vi on vi.vehicleid=d.vehicleid " +
                        " inner join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                        " where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and (trip_starttime between ? and ?) and d.IsTrip=1 " + where +
                        " group by ti.Name ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("GroupId", groupid);
                lParameter.Add("Trip_start", fromdate);
                lParameter.Add("Trip_end", todate);
                return dbx.executeQuery(query, lParameter).Tables[0];
            }
        }
