        public DataTable Get_ICT2SummaryDetails(string loginid, string fromdate, string todate, int groupid, string ptype)
        {
            string query = "select * from tbl_trans_dashboard_keys where Category=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("ptype", ptype);
            DataSet data = dbx.executeQuery(query.ToString(), lParameter);
            for (int i = 0; i < data.Tables[0].Rows.Count; i++)
            {
                int accountid = GetAccountIdByGroupId(groupid);
                string transporterid = getTransporterIdByLogin(loginid);
                query = "CALL `sp_GetICT2Details`(?,?,?,?,?,?,?)";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("loginid", loginid);
                lParameter.Add("fromdate", fromdate);
                lParameter.Add("todate", todate);
                lParameter.Add("accountid", accountid);
                lParameter.Add("transporterid", transporterid);
                lParameter.Add("ptype", ptype);
                lParameter.Add("key", data.Tables[0].Rows[i]["key"].ToString());
                DataTable dt = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                if (dt.Rows.Count > 0)
                    data.Tables[0].Rows[i]["value"] = dt.Rows[0][0].ToString();
            }
            return data.Tables[0];
        }
