        public DataTable Get_TransportewisedataSafetyDashboard(string fromdate, string todate, int groupid)
        {
            string query = "select ti.ShortName as Name ,count(Nullif(maxsp>0,''))as overspeed_count,count(Nullif(cd>0 ,''))as cd_count, " +
                    "count(Nullif(md>0 ,''))as md_count, " +
                    "count(Nullif(nd>0 and d.IsNightDrivingViol=1 ,''))as nd_count,count(Nullif(harshbraking_count>0 ,''))as hb_count,count(if(d.harshaccln_count > 0, d.vehicleid, NULL)) AS ha_count from daywisevehviosummary d " +
                    " inner join vehicleinfo vi on vi.vehicleid=d.vehicleid " +
                    " inner join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                    "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and (trip_starttime between ? and ?) and d.IsTrip=1 " +
                    "group by ti.Name ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("trip_starttime", fromdate);
            lParameter.Add("trip_endtime", todate);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
