        public DataTable Get_AllviolationdataSafetyDashboard(string fromdate, string todate, string groupby, int groupid)
        {
            int accountid = GetAccountIdByGroupId(groupid);
            string query = "select (" + groupby + ") as date ,count(Nullif(maxsp>0,''))as overspeed_count,count(Nullif(cd>0 ,''))as cd_count, " +
                    "count(Nullif(md>0 ,''))as md_count, " +
                    "count(Nullif(nd>0 and d.IsNightDrivingViol=1 ,''))as nd_count,count(Nullif(harshbraking_count>0 ,''))as hb_count,count(Nullif(d.harshaccln_count>0 ,''))as ha_count, count(Nullif(totalruntime>=480 ,''))as tr_count from daywisevehviosummary d " +
                    "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=" + groupid + ") and (trip_starttime between '" + fromdate + "' and '" + todate + "') and d.IsTrip=1 " +
                    "group by " + groupby + " ORDER BY date";
            DataTable dt = dbx.executeQuery(query).Tables[0];
            if (groupby == "case when hour(d.trip_starttime) <  20 and hour(d.trip_starttime)>= 8 then 'DAY' else 'NIGHT' end")
            {
                if (dt.Rows.Count == 1)
                {
                    DataRow dr = dt.NewRow();
                    dr[0] = "Night";
                    dr[1] = "0";
                    dt.Rows.Add(dr);
                }
                dt.Columns.Add("crash_count", typeof(Int32));
                query = "select count(vehicleid) as crashes  from crash_events c where " +
                        " vehicleid in (select vehicleid from vehiclesgroupsmap where GroupId='" + groupid + "') and" +
                        " c.timestamp between '" + fromdate + "' and '" + todate + "' and hour(c.timestamp)<20";
                DataTable temp = dbx.executeQuery(query).Tables[0];
                dt.Rows[0]["crash_count"] = temp.Rows[0]["crashes"];

                query = "select count(vehicleid) as crashes  from crash_events c where " +
                        " vehicleid in (select vehicleid from vehiclesgroupsmap where GroupId='" + groupid + "') and" +
                        " c.timestamp between '" + fromdate + "' and '" + todate + "' and hour(c.timestamp)>=20";
                temp = dbx.executeQuery(query).Tables[0];
                dt.Rows[1]["crash_count"] = temp.Rows[0]["crashes"];

                dt.Columns.Add("vehicles_count", typeof(Int32));
                query = "select count(distinct v.VehicleId) as vcount from vehiclesgroupsmap vm inner join vehicles v on v.VehicleId=vm.VehicleId where groupid=" + groupid + "";
                temp = dbx.executeQuery(query).Tables[0];
                dt.Rows[0]["vehicles_count"] = temp.Rows[0]["vcount"];

                query = "select count(distinct d.DriverId) as mcount from taging t inner join vehicleinfo v on v.VehicleId=t.VehicleId " +
                        " left join regioninfo r on r.RegionId = v.RegionId" +
                        " join driverinfo d on d.DriverId = t.DriverId" +
                        " where t.TimeStamp between '" + fromdate + "' and '" + todate + "'" +
                        " and v.VehicleId in (select vehicleid from vehiclesgroupsmap vm where vm.GroupId = '" + groupid + "')";
                temp = dbx.executeQuery(query).Tables[0];
                dt.Rows[1]["vehicles_count"] = temp.Rows[0]["mcount"];

                dt.Columns.Add("install_count", typeof(Int32));
                query = "select count(distinct IMEI) as total_mcount from taging t inner join vehicleinfo v on v.VehicleId=t.VehicleId " +
                        " inner join regioninfo r on r.RegionId=v.RegionId " +
                        " where v.VehicleId in (select vehicleid from vehiclesgroupsmap vm where vm.GroupId = '" + groupid + "')";
                temp = dbx.executeQuery(query).Tables[0];
                dt.Rows[0]["install_count"] = temp.Rows[0]["total_mcount"];
                dt.Rows[1]["install_count"] = dt.Rows[1]["vehicles_count"];

                dt.Columns.Add("psngr_install_count", typeof(Int32));
                query = "select count(distinct p.PsngrId) as total_psngr from psngr_info p " +
                        " inner join psngr_tag pt on pt.PsngrId = p.PsngrId " +
                        " left join regioninfo ri on ri.RegionId = p.RegionId " +
                        " where p.Active = 1 and p.AccountId=" + accountid;
                if (groupid != 2801)
                    query += " and pt.VehicleId in (select vehicleid from vehiclesgroupsmap vm where vm.GroupId = '" + groupid + "')";
                temp = dbx.executeQuery(query).Tables[0];
                dt.Rows[0]["psngr_install_count"] = temp.Rows[0]["total_psngr"];

                query = "select count(distinct p.PsngrId) as using_psngr from psngr_info p " +
                        " inner join psngr_tag pt on pt.PsngrId = p.PsngrId" +
                        " left join regioninfo ri on ri.RegionId = p.RegionId" +
                        " where p.Active = 1 and p.AccountId ='" + accountid + "' and pt.TagInTime between '" + fromdate + "' and '" + todate + "'";
                if (groupid != 2801)
                    query += " and pt.VehicleId in (select vehicleid from vehiclesgroupsmap vm where vm.GroupId = '" + groupid + "')";
                temp = dbx.executeQuery(query).Tables[0];
                dt.Rows[1]["psngr_install_count"] = temp.Rows[0]["using_psngr"];

            }
            return dt;
        }

