        public DataTable Get_Allviolationdata_Total(string fromdate, string todate, string groupby, int groupid)
        {
            string query = "select concat(" + groupby + ") as date,SUM(IF(d.maxsp='',0,1)) as overspeed_count,SUM(IF(d.cd='',0,1)) as cd_count, " +
                    "SUM(IF(d.md='',0,1)) as md_count, " +
                    "SUM(IF(d.nd='',0,1)) as nd_count,SUM(IF(d.harshBraking='',0,1)) as hb_count,SUM(IF(TIME_TO_SEC(STR_TO_DATE(d.maxhalttime,'%H:%i:%s')) between 14400 and 31500,1,0)) as ha_count, count(Nullif(totalruntime>=480 ,'')) as tr_count from daywisevehviosummary d " +
                    "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and (`date` between ? and ?) " +
                    "group by " + groupby + " ";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("date_start", fromdate);
            lParameter.Add("date_end", todate);
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            return dt;
        }
        public DataTable GetCurrentPassngerTrip(string vehicleid, string swipedts)
