        }
        public DataTable GetPreviousPassngerTrip(string vehicleid, string swipedts)
        {
            string query = "select * from psngr_tag p join psngr_info i on i.PsngrId=p.PsngrId where p.VehicleId=? and p.TagInTime<? order by TagInTime desc limit 1";
