        public DataTable Get_Circlewise_Selecteddata(string fromdate, string todate, string cirlcle, string violationtype, int groupid, string time)
        {
            string where = "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=" + groupid + ") and (trip_starttime between '" + fromdate + "' and '" + todate + "') and vehicleid in (select vehicleid from vehicleinfo vi inner join regioninfo r on r.RegionId=vi.RegionId where r.RegionName='" + cirlcle + "') and d.IsTrip=1 ";
            string query = "select d.vehicleid as VehicleId,d.drivername as 'Driver Name',concat(d.date) as Date,";
            if (time == "Day")
            {
                where += " and hour(d.trip_starttime) < 20 and hour(d.trip_starttime)>=8 ";
            }
            else if (time == "Night")
            {
                where += " and (hour(d.trip_starttime) >= 20 or hour(d.trip_starttime)<8) ";
            }
            if (violationtype == "OverSpeed")
            {
                query += "d.maxsp as MaxSpeed,d.maxsp_loc as 'MaxSpeed Location',d.maxsp_count as 'MaxSpeed Count'";
                where += "and d.maxsp>0";
            }
            else if (violationtype == "Continuous Driving")
            {
                query += "d.cd as 'Continue Drive'";
                where += "and d.cd>0";
            }
            else if (violationtype == "Maximum Driving")
            {
                query += "d.md as 'Total Duration'";
                where += "and d.md>0";
            }
            else if (violationtype == "Night Driving")
            {
                query += "d.nd as 'Night Duration',d.nd_distance as Distance,d.nd_startlatlng as 'Start Lat/Long',d.nd_endlatlng as 'End Lat/Long'";
                where += "and d.nd>0 and d.IsNightDrivingViol=1";
            }
            else if (violationtype == "HarshBrake")
            {
                query += "d.harshbraking_loc 'HarshBrake Location',d.harshBraking as 'HarshBrake Value',harshbraking_count as 'HarshBrake Count'";
                where += "and d.harshbraking_count>0";
            }
            else if (violationtype == "Harsh Acceleration")
            {
                query += "d.harshaccln_loc 'Harsh Acceleration Location',d.harshaccln_value as 'Harsh Acceleration Value',harshaccln_Count as 'Harsh Acceleration Count'";
                where += "and d.harshaccln_count>0";
            }
            else if (violationtype == "Max Driver Availability")
            {
                query += "concat(SEC_TO_TIME(d.totalruntime*60)) as RunTime,d.Kms_driven as KMS";
                where += "and d.totalruntime>480";
            }
            query += " from daywisevehviosummary d " + where;

            return dbx.executeQuery(query).Tables[0];
        }
        public DataTable Get_Circlewise_SelecteddataSD(string fromdate, string todate, string cirlcle, string violationtype, int groupid, string time)
        {
            string where = " WHERE d.vehicleid IN " +
                           " (SELECT vehicleid FROM vehiclesgroupsmap m WHERE m.GroupId=" + groupid + ") " +

                           " AND d.timestamp >= '" + fromdate + "' " +
                           " AND d.timestamp <= '" + todate + "' " +

                           " AND d.vehicleid IN " +
                           " (SELECT vehicleid FROM vehicleinfo vi " +
                           " INNER JOIN regioninfo r ON r.RegionId=vi.RegionId " +
                           " WHERE r.RegionName='" + cirlcle + "') ";

            // DAY / NIGHT FILTER
            if (time == "Day")
            {
                where += " AND HOUR(d.timestamp) >= 8 " +
                         " AND HOUR(d.timestamp) < 20 ";
            }
            else if (time == "Night")
            {
                where += " AND (HOUR(d.timestamp) >= 20 " +
                         " OR HOUR(d.timestamp) < 8) ";
            }

            // BASE QUERY
            string query = " SELECT " +
                           " d.vehicleid AS VehicleId, " +
                           " d.drivername AS 'Driver Name', " +
                           " d.type AS 'Violation Type', " +
                           " DATE_FORMAT(d.timestamp,'%Y-%m-%d %H:%i:%s') AS Date, " +
                           " d.duration AS Duration, " +
                           " d.Location, " +
                           " d.latitude, " +
                           " d.Longitude ";

            // VIOLATION FILTERS
            if (violationtype == "OverSpeed")
            {
                where += " AND d.type='OVERSPEEDING' ";
            }
            else if (violationtype == "Continuous Driving" || violationtype == "Continue Driving")
            {
                where += " AND d.type='SHORT RUNTIME' ";
            }
            else if (violationtype == "Maximum Driving")
            {
                where += " AND d.type='TOTAL RUNTIME' ";
            }
            else if (violationtype == "Night Driving")
            {
                where += " AND d.type='NIGHT DRIVING' ";
            }
            else if (violationtype == "HarshBrake")
            {
                where += " AND d.type='HARSH BRAKING' ";
            }
            else if (violationtype == "Harsh Acceleration")
            {
                where += " AND d.type='HIGH ACCELERATION' ";
            }
            else if (violationtype == "Max Driver Availability")
            {
                where += " AND d.type='TOTAL RUNTIME' " +
                         " AND d.duration > 480 ";
            }

            query += " FROM storevehicleviolations d " +
                     where +
                     " ORDER BY d.timestamp DESC ";

            return dbx.executeQuery(query).Tables[0];
        }


