        public DataTable Get_Allviolation_Selecteddata(string date, string violationtype, int groupid, string group, string fromdate, string todate, string time)
        {
            string where = "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=" + groupid + ") and trip_starttime<>'0000-00-00 00:00:00' and date>='" + fromdate + "' and date<='" + todate + "' and d.IsTrip=1 ";
            if (group == "week")
            {
                where += " and WEEKOFYEAR(date)=WEEKOFYEAR('" + date + "')";
            }
            else if (group == "month")
            {
                try
                {
                    string temp = date.Substring(0, date.IndexOf(' '));
                    where += " and monthname(date)='" + temp + "'";

                }
                catch (Exception e)
                {
                    string temp = Convert.ToDateTime(date).ToString("MMMM");
                    where += " and monthname(date)='" + temp + "'";
                }
            }
            else if (group == "year")
            {
                where += " and YEAR(date)='" + date + "'";
            }
            else
            {
                where += " and date='" + date + "'";
            }

            string query = "select d.vehicleid as VehicleId,d.drivername as 'Driver Name',concat(d.date) as Date,";
            if (violationtype == "OverSpeed")
            {
                query += "d.maxsp as MaxSpeed,d.maxsp_loc as 'MaxSpeed Location',d.maxsp_count as 'MaxSpeed Count'";
                where += "and d.maxsp>0";
            }
            else if (violationtype == "Continuous Driving")
            {
                query += "d.cd as 'Continue Drive'";
                where += "and d.cd>0";
            }
            else if (violationtype == "Maximum Driving")
            {
                query += "d.md as 'Total Duration'";
                where += "and d.md>0";
            }
            else if (violationtype == "Night Driving")
            {
                query += "d.nd as 'Night Duration',d.nd_distance as Distance,d.nd_startlatlng as 'Start Lat/Long',d.nd_endlatlng as 'End Lat/Long'";
                where += "and d.nd>0 and d.IsNightDrivingViol=1";
