        //Get all Circle
        public DataTable Get_Circles(string sessionId)
        {
            string accountName = GetAccountName(sessionId);
            int accountid = GetAccountId(sessionId);
            string GlAcid = GetGlobalAccountIdBySession(sessionId);
            string query = "select RegionId,RegionName,groupid from regioninfo s where s.AccountId='" + accountid + "'";
            if (accountName.ToLower().Contains("nokia"))
                query = "select RegionId,RegionName,groupid from regioninfo s where s.RegionName like '%" + accountName + "%'";
            else if (GlAcid == "4467")
            {
                int Gid = getGroupId(sessionId);
                if (Gid != 8199)
                    query = "select RegionId,RegionName,groupid from regioninfo s where s.groupid='" + Gid + "'";
            }
            return dbx.executeQuery(query).Tables[0];
        }

