        //******************************Violation Summary Tab2***********************************
        public DataTable Get_CirclewiseSummary(string fromdate, string todate, string circle, string groupby, int groupid)
        {
            string query = "select concat(" + groupby + ") as date,count(Nullif(maxsp>0,''))as overspeed_count,count(Nullif(cd>0 ,''))as cd_count, " +
                            "count(Nullif(md>0 ,''))as md_count, " +
                            "count(Nullif(nd>0 and d.IsNightDrivingViol=1 ,''))as nd_count,count(Nullif(harshbraking_count>0 ,''))as hb_count,count(Nullif(d.harshaccln_count>0 ,''))as ha_count from daywisevehviosummary d " +
                            " inner join vehicleinfo vi on vi.vehicleid=d.vehicleid " +
                            " inner join regioninfo ri on ri.RegionId=vi.RegionId  " +
                            "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=" + groupid + ") and d.IsTrip=1 ";
            if (circle != "ALL Circles")
                query += " and ri.RegionName='" + circle + "'";
            query += " and (trip_starttime between '" + fromdate + "' and '" + todate + "') " +
                             "group by " + groupby;
            return dbx.executeQuery(query).Tables[0];
        }
        public DataTable Get_CirclewiseSummarySD(string fromdate, string todate, string circle, string displayDate, int groupid)
        {
            string query = /*"SELECT DATE_FORMAT(" + groupby + ", '%d/%m/%Y') AS date, " +*/"SELECT " + displayDate + " AS date, " +

                           " SUM(CASE WHEN d.type='OVERSPEEDING' THEN 1 ELSE 0 END) AS overspeed_count, " +

                           " SUM(CASE WHEN d.type='SHORT RUNTIME' THEN 1 ELSE 0 END) AS cd_count, " +

                           " SUM(CASE WHEN d.type='TOTAL RUNTIME' THEN 1 ELSE 0 END) AS md_count, " +

                           " SUM(CASE WHEN d.type='NIGHT DRIVING' THEN 1 ELSE 0 END) AS nd_count, " +

                           " SUM(CASE WHEN d.type='HARSH BRAKING' THEN 1 ELSE 0 END) AS hb_count, " +

                           " SUM(CASE WHEN d.type='HIGH ACCELERATION' THEN 1 ELSE 0 END) AS ha_count " +

                           " FROM storevehicleviolations d " +

                           " INNER JOIN vehicleinfo vi ON vi.vehicleid=d.vehicleid " +

                           " INNER JOIN regioninfo ri ON ri.RegionId=vi.RegionId " +

                           " WHERE d.vehicleid IN " +
                           " (SELECT vehicleid FROM vehiclesgroupsmap m WHERE m.GroupId=" + groupid + ") " +

                           " AND d.timestamp >= '" + fromdate + "' " +
                           " AND d.timestamp <= '" + todate + "' ";

            // CIRCLE FILTER
            if (circle != "ALL Circles")
            {
                query += " AND ri.RegionName='" + circle + "' ";
            }

            query += " GROUP BY " + displayDate +

                     " ORDER BY d.timestamp";

            return dbx.executeQuery(query).Tables[0];
        }

