            }
            string where = " WHERE d.vehicleId IN " +
                           " (SELECT vehicleid FROM vehiclesgroupsmap m WHERE m.GroupId=" + groupid + ") " +
                           " AND d.timestamp >= '" + fromdate + "' " +
                           " AND d.timestamp <= '" + todate + "' ";

