            //    where += " AND YEAR(d.timestamp)='" + date + "'";
            //}
            //else
            //{
            //    where += " AND DATE(d.timestamp)='" + date + "'";
            //}
            if (group == "week")
            {
                where += " AND DATE_FORMAT(STR_TO_DATE(CONCAT(YEARWEEK(d.timestamp,1), ' Monday'), '%X%V %W'), '%Y-%m-%d') = '" + date + "'";
            }
            else if (group == "month")
            {
                where += " AND DATE_FORMAT(d.timestamp, '%M %Y') = '" + date + "'";
            }
            else if (group == "year")
            {
