            else if (violationtype == "Night Driving")
                where += " AND d.type='NIGHT DRIVING'";
            else if (violationtype == "HarshBrake")
                where += " AND d.type='HARSH BRAKING'";
            else if (violationtype == "Harsh Acceleration")
                where += " AND d.type='HIGH ACCELERATION'";

