        public DataTable Get_TransporterwiseSummary(string fromdate, string todate, string transporter, string groupby, int groupid)
        {
            string query = "select concat(" + groupby + ") as date,count(Nullif(maxsp>0,''))as overspeed_count,count(Nullif(cd>0 ,''))as cd_count, " +
                            "count(Nullif(md>0 ,''))as md_count, " +
