                            " inner join vehicleinfo vi on vi.vehicleid=d.vehicleid " +
                            " inner join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                            "where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) ";
