        //*************************************Tab 4************************************
        public DataTable GetDriversRankWiseData(string fromdate, string todate, string circle, string transporter, string order, int groupid)
        {
            string where = " where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and trip_starttime<>'0000-00-00 00:00:00' and (trip_starttime between ? and ?) and d.IsTrip=1 ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("trip_starttime", fromdate);
            lParameter.Add("trip_endtime", todate);

            if (transporter != "ALL Transporters")
            {
                where += " and ti.Name=?";
                lParameter.Add("Name", transporter);
            }
            if (circle != "ALL Circles")
            {
                where += " and ri.RegionName=?";
                lParameter.Add("RegionName", circle);
            }

            string query = "SELECT @rownum := @rownum + 1 AS 'Rank',Driver,VehicleId,Circle,Transporter,Overspeed,`Continuous Driving`,`Max Driving`,`Night Driving`,`HarshBraking`,`HarshAcceleration`,`Total Violations`,`Distance Traveled`,`Points`" +
                           " FROM ( " +
                       " select  d.drivername as Driver,d.vehicleid as VehicleId, ri.RegionName as Circle,ti.Name as Transporter,count(Nullif(maxsp>0,''))as Overspeed,count(Nullif(cd>0 ,''))as 'Continuous Driving' " +
                       " ,count(Nullif(md>0 ,''))as 'Max Driving',count(Nullif(nd>0 and d.IsNightDrivingViol=1 ,'')) as 'Night Driving',count(Nullif(harshbraking_count>0 ,''))as HarshBraking,count(Nullif(d.harshaccln_value>0 ,''))as HarshAcceleration, " +
                       " count(Nullif(maxsp>0,''))+count(Nullif(cd>0 ,''))+count(Nullif(md>0 ,''))+count(Nullif(nd>0 and IsNightDrivingViol=1 ,''))+count(Nullif(harshbraking_count>0 ,''))+count(Nullif(d.harshaccln_value>0 ,'')) as 'Total Violations' " +
                       " ,Sum(d.Kms_driven) as 'Distance Traveled',sum(d.points_earned) as Points,@rownum := 0 " +
                       " from daywisevehviosummary d " +
                       " inner join vehicleinfo vi on vi.VehicleId=d.vehicleid " +
                       " inner join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                       " Left join regioninfo ri on ri.RegionId=vi.RegionId " + where +
                       " group by d.driverid,d.vehicleid having Sum(d.Kms_driven)>0 order by Points " + order + ") t";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        //Vodafone tab
        public DataTable Get_ClientwiseData(int groupid, string client, string fromdate, string todate)
        {
            string Query = string.Empty;
            Query = "select count(distinct v.Vehicle) from vehdriver_staticdata v ";
            string where = " ";
            if (client != "ALL Clients")
            {
                if (client == "VODAFONE")
                {
                    where = " and (v.CT='" + client + "' or v.CT='VIL')";
                    Query += " where (v.CT='" + client + "' or v.CT='VIL')";
                }
                else
                {
                    Query += " where v.CT='" + client + "' ";
                    where = " and v.CT='" + client + "'";
                }

            }
            object vehicles = dbx.executeScalar(Query);
            var lParameter = new Dictionary<string, object>();
            lParameter = new Dictionary<string, object>();
            lParameter.Add("groupid", groupid);
            lParameter.Add("FromDate", fromdate);
            lParameter.Add("ToDate", todate);
            Query = "select  a.Shift,a.Month,ifnull(`Total Kms`,0) as `Total Kms` , ifnull(`Vehicles`,0) as `Vehicles`  , ifnull(OverSpeed,0) as OverSpeed, ifnull(Vehicles_num,0) as Vehicles_num   from " +
                    " (select distinct (case when ( hour(d.trip_starttime) <  20 and hour(d.trip_starttime)>= 8) then 'DAY' else 'NIGHT' end) as Shift, concat(monthname(d.date) , '-', year(d.date)) as `Month` " +
                    " from daywisevehviosummary d where (d.date >= '" + fromdate + "' and d.date<='" + todate + "') and d.trip_starttime<>'0000-00-00 00:00:00')a " +
                    " left join " +
                    " (" +
                    " select (case when ( hour(d.trip_starttime) <  20 and hour(d.trip_starttime)>= 8) then 'DAY' else 'NIGHT' end) as Shift, " +
                    " concat(monthname(d.date) , '-', year(d.date)) as `Month`,sum(d.Kms_driven) as `Total Kms`,count(distinct if(d.maxsp>0,vehicleid,''))-1 as `Vehicles` , " +
                    " sum(d.maxsp_count) as `OverSpeed`, " + vehicles + " as Vehicles_num " +
                    " from daywisevehviosummary d " +
                    " inner join vehdriver_staticdata v on v.Vehicle=replace(d.vehicleid,' ','') " + where +
                    " where d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) and d.trip_starttime<>'0000-00-00 00:00:00' and (d.date between ? and ?) and d.IsTrip=1 " + where +
                    " group by month(d.date),(case when ( hour(d.trip_starttime) <  20 and hour(d.trip_starttime)>= 8) then 'DAY' else 'NIGHT' end) " +
                    " )b on a.Shift=b.Shift and a.Month=b.Month order by a.Shift";
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }
        //Vodafone detail
        public DataTable Get_ClientwiseDetail(int groupid, string client, string fromdate, string todate, string month, string time)
        {
            string Query = string.Empty;
            string monthname = month.Substring(0, month.IndexOf('-'));
            string year = month.Substring(month.IndexOf('-') + 1, 4);
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("FromDate", fromdate);
            lParameter.Add("ToDate", todate);
            string where = " and monthname(d.date)='" + monthname + "' and year(d.date)=?";
            lParameter.Add("year", year);
            if (client != "ALL Clients")
            {
                where += " and v.CT=? ";
                lParameter.Add("client", client);
            }
            if (time == "DAY")
            {
                where += " and hour(d.trip_starttime) < 20 and hour(d.trip_starttime)>= 8 ";
            }
            else if (time == "NIGHT")
            {
                where += " and (hour(d.trip_starttime) >= 20 or hour(d.trip_starttime)< 8) ";
            }
            Query = "select concat(d.date) as 'Date',ri.RegionName as 'Circle', " +
                    "d.maxsp as 'Peak Speed',d.vehicleid as Vehicle,d.maxsp_loc as 'Peak Speed Location', d.maxsp_count as 'No of  Over speed instances' from daywisevehviosummary d " +
                    "inner join vehdriver_staticdata v on v.Vehicle=replace(d.vehicleid,' ','') " +
                    "inner join vehicleinfo vi on vi.VehicleId=d.vehicleid " +
                    "inner join regioninfo ri on ri.RegionId=vi.RegionId " +
                    "where d.trip_starttime<>'0000-00-00 00:00:00' and (trip_starttime between ? and ?)  and d.IsTrip=1 and d.maxsp>0 " + where;
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }
        public DataTable GetAllVehicleGatePassByGroupId(string GroupId, DateTime From, DateTime To)
        {
            string Query = string.Empty;
            Query = "select c.Region,v.DateTime,cd.LoadingPoint as Source,c.Name as Destination,v.OGPNo as GPNo,v.VehicleID,p.ProductName as AssetName,v.DateTime as GPConfirmedTime," +
                    "q.AcknowledgementTime as GPAckTime,q.Quntity as DispatchQty,q.ReceivedQuantity as AckQty,(q.Quntity - q.ReceivedQuantity) as " +
                    "diff,v.Remarks as SourceRemarks,cd.AcknowledBy,cd.Remarks as DestinationRemarks,v.OTL,v.EWayBillNo from vehicledctrip v join customerdcassign cd on v.id=cd.DCTripId join dc_quntityinfo " +
                    "q on cd.id=q.CustomerDCAssignId join dc_productinfo p on q.ProductId=p.Id " +
                    "join customerinfo c on c.customerId=cd.CustomerId " +
                    "where v.DateTime between '" + formatDBDate(From) + "' and '" + formatDBDate(To) + "' and c.GroupId='" + GroupId + "'";
            return dbx.executeQuery(Query).Tables[0];
        }

        public void DeleteEntredGatePass(string DCTripId, ArrayList Ids, int nooftries = 0)
        {
            try
            {
                string CustomerDcAssignId = "";
                for (int k = 0; k < Ids.Count; k++)
                {
                    if (Ids.Count - 1 != k)
                        CustomerDcAssignId = CustomerDcAssignId + Ids[k] + ",";
                    else
                        CustomerDcAssignId = CustomerDcAssignId + Ids[k];

                }
                string Qurey = string.Empty;
                Qurey = "delete from asset_transaction where CustomerDCAssignId in (" + CustomerDcAssignId + ")";
                dbx.executeNonQuery(Qurey);
                Qurey = "delete from dc_quntityinfo where CustomerDCAssignId in (" + CustomerDcAssignId + ")";
                dbx.executeNonQuery(Qurey);
                Qurey = "delete from customerdcassign where DCTripId='" + DCTripId + "' and id in (" + CustomerDcAssignId + ")";
                dbx.executeNonQuery(Qurey);
                Qurey = "delete from vehicledctrip where id='" + DCTripId + "'";
                dbx.executeNonQuery(Qurey);
            }
            catch (Exception ex)
            {
                nooftries++;
                STL_RecordErrorMessage(ex.ToString());
                if (nooftries < 3)
                {
                    DeleteEntredGatePass(DCTripId, Ids, nooftries);
                }
            }
        }

        public int IsDuplicateEntry(string VehicleId, string CustomerId, string AddedBy)
        {
            DateTime CurrentTime = DateTime.Now;
            CurrentTime = CurrentTime.AddMinutes(-5);
            DateTime DefaultTime = DateTime.Now;
            var lParameter = new Dictionary<string, object>();
            string query = "select v.DateTime from vehicledctrip v join customerdcassign c on v.id=c.DCTripId " +
                           "where c.CustomerId=? and v.AddedBy=? and v.VehicleID=? and v.DateTime >=? order by v.DateTime desc limit 1";
            lParameter.Add("CustomerId", CustomerId);
            lParameter.Add("AddedBy", AddedBy);
            lParameter.Add("VehicleId", VehicleId);
            lParameter.Add("CurrentTime", CurrentTime);
            string LastAddedGatePass = Convert.ToString(dbx.executeScalar(query, lParameter));
            if (!string.IsNullOrEmpty(LastAddedGatePass))
            {
                if (DefaultTime.Subtract(Convert.ToDateTime(LastAddedGatePass)).TotalMinutes <= 10)
                    return 0;
                else
                    return 1;
            }
            else
                return 1;
        }
