        public void DeleteTransactionAssetByDcAssignId(string Id, string CustomerId)
        {
            string Qurey = string.Empty;
            Qurey = "delete from asset_transaction where CustomerDCAssignId='" + Id + "'";
            dbx.executeNonQuery(Qurey);

            Qurey = "select * from asset_transaction a where a.Id in (select max(a.Id) from asset_transaction a where a.CustomerId=" + CustomerId + " group by a.ProductId)";
            DataTable TransAsset = dbx.executeQuery(Qurey).Tables[0];
            for (int i = 0; i < TransAsset.Rows.Count; i++)
            {
                string ProductId = Convert.ToString(TransAsset.Rows[i]["ProductId"]);
                string AssetId = Convert.ToString(TransAsset.Rows[i]["Id"]);
                Qurey = "select Quantity,DateTime from asset_master a where a.Id in (select max(a.Id) from asset_master a where a.CustomerId=" + CustomerId + " and a.ProductId =" + ProductId + ")";
                DataTable dt = dbx.executeQuery(Qurey).Tables[0];
                int EstimatedCurrentStock = GetEstimatedCurrentAsset(dt, CustomerId, ProductId, 0, 0);
                Qurey = "update asset_transaction set CurrentAssets=" + EstimatedCurrentStock.ToString() + " where CustomerId=" + CustomerId + " and " +
                        "ProductId =" + ProductId + " and Id=" + AssetId + "";
                dbx.executeNonQuery(Qurey);

            }

        }

        public int GetEstimatedCurrentAsset(DataTable lAsset, string CustomerId, string ProductId, int TotalQuantity, int TransactionType)
        {
            int EstimatedCurrentAssets = 0;
            int TotalStock = 0;
            DateTime LatestAsset = new DateTime(2016, 01, 01);
            if (lAsset.Rows.Count > 0)
            {
                TotalStock = Convert.ToInt32(lAsset.Rows[0]["Quantity"]);
                LatestAsset = Convert.ToDateTime(lAsset.Rows[0]["DateTime"]);
            }
            string Query = string.Empty;
            Query = "select sum(a.UpdatedAssets) as CurrentAsset from asset_transaction a where a.CustomerId=" + CustomerId + " and a.ProductId=" + ProductId + " " +
                    "and a.TransactionType=0 and TransactionTime>='" + formatDBDate(LatestAsset) + "'";
            string AssetOut = Convert.ToString(dbx.executeScalar(Query));

            Query = "select sum(a.UpdatedAssets) as CurrentAsset from asset_transaction a where a.CustomerId=" + CustomerId + " and a.ProductId=" + ProductId + " " +
                    "and a.TransactionType=1 and TransactionTime>='" + formatDBDate(LatestAsset) + "'";
            string AssetIn = Convert.ToString(dbx.executeScalar(Query));

            int TotalAssetIn = 0;
            int TotalAssetOut = 0;
            if (!string.IsNullOrEmpty(AssetIn))
                TotalAssetIn = Convert.ToInt32(AssetIn);
            if (!string.IsNullOrEmpty(AssetOut))
                TotalAssetOut = Convert.ToInt32(AssetOut);

            int Total = 0;
            int Flag = 0;

            if (TotalAssetIn > TotalAssetOut)
            {
                Total = TotalAssetIn - TotalAssetOut;
                EstimatedCurrentAssets = TotalStock + Total;
                Flag = 1;
            }
            else if (TotalAssetIn < TotalAssetOut)
            {
                Total = TotalAssetOut - TotalAssetIn;
                EstimatedCurrentAssets = TotalStock - Total;
                Flag = 1;
            }

            if (TransactionType == 0 && Flag == 1)
                EstimatedCurrentAssets = EstimatedCurrentAssets - TotalQuantity;
            else if (TransactionType == 1 && Flag == 1)
                EstimatedCurrentAssets = EstimatedCurrentAssets + TotalQuantity;

            if (TransactionType == 0 && Flag == 0)
                EstimatedCurrentAssets = TotalStock - Convert.ToInt32(TotalQuantity);
            else if (TransactionType == 1 && Flag == 0)
                EstimatedCurrentAssets = TotalStock + Convert.ToInt32(TotalQuantity);

            return EstimatedCurrentAssets;
        }

        public DataTable GetCustomerByRegion(string Region, string AccountId)
        {
            string Query = string.Empty;
            if (!string.IsNullOrEmpty(AccountId))
            {
                Query = "select distinct a.CustomerId,c.Region,c.Name from asset_master a join customerinfo c on " +
                               "c.customerId=a.CustomerId where c.AccountId='" + AccountId + "' group by c.customerId";
            }
            else if (!string.IsNullOrEmpty(Region))
            {
                Query = "select distinct a.CustomerId,c.Name,c.Region from asset_master a join customerinfo c on " +
                         "c.customerId=a.CustomerId where c.Region='" + Region + "' group by c.customerId";
            }
            return dbx.executeQuery(Query).Tables[0];
        }
