				Query = "SELECT v.CT AS `MU Name`,p.VehicleId,c.UID,COALESCE(NULLIF(p.DriverDetails, ''), NULLIF(d.NAME, ''), ' ') AS `Driver Name`, DATE_FORMAT(p.TagInTime, '%Y-%m-%d %h:%i:%s %p') AS TagInTime," +
                     " p.TagInOMR, DATE_FORMAT(p.TagOutTime, '%Y-%m-%d %h:%i:%s %p') AS TagOutTime,p.TagOutOMR,(p.TagOutOMR - p.TagInOMR) AS DistanceByOMR, p.TripKm,i.EmpId,i.PsngrName,i.MobileNo," +
                     "r.RegionName, d.MobileNo as `Driver MobileNumber`,v.VehicleUsedFor,p.RunTime,ROUND(p.MaxSpeed, 0) AS MaxSpeed FROM psngr_tag p LEFT JOIN psngr_info i ON i.PsngrId = p.PsngrId LEFT JOIN " +
					 "regioninfo r ON r.RegionId = i.RegionId  LEFT JOIN driverinfo d ON d.DriverId = p.DriverId LEFT JOIN vehdriver_staticdata v on v.Vehicle=replace(p.VehicleId,' ','') LEFT JOIN vehicleinfo " +
