        public DataTable GetDriverTagingInfo(string tagInTime, string tagOutTime, string vehString, string sessionid, string pagename)
        {
            string Query = "";
            String GblAcId = GetGlobalAccountIdBySession(sessionid);
            if (!string.IsNullOrEmpty(sessionid))
            {
                Object[] accountInfo = getAccountInfo(sessionid);
                try
                {
                    tagInTime = formatDBDate(DateTime.ParseExact(tagInTime, "yyyy/MM/dd HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));
                    if (!string.IsNullOrEmpty(tagOutTime))
                        tagOutTime = formatDBDate(DateTime.ParseExact(tagOutTime, "yyyy/MM/dd HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    tagInTime = formatDBDate(Convert.ToDateTime(tagInTime));
                    if (!string.IsNullOrEmpty(tagOutTime))
                        tagOutTime = formatDBDate(Convert.ToDateTime(tagOutTime));
                }
                if (pagename.ToLower() == "driverlog")
                {
                    Query = "SELECT t.VehicleId,t.DriverId,t.DriverName,t.IMEI,t.MobileLatLng,t.TimeStamp,t.TagInOrOut  FROM taging t WHERE t.TimeStamp >= ? and ";
                    if (!string.IsNullOrEmpty(tagOutTime))
                        Query += " t.TimeStamp <= ? and ";
                    Query += " (TagInOrOut='1' OR TagInOrOut='2') and t.VehicleId in ( " + vehString + " ) order by t.VehicleId,t.DriverId,t.TimeStamp";
                }
                else
                {
                    Query = "SELECT t.VehicleId,t.DriverId,t.DriverName,t.IMEI,t.MobileLatLng,t.TimeStamp  FROM taging t WHERE t.TimeStamp >= ? and ";
                    if (!string.IsNullOrEmpty(tagOutTime))
                        Query += " t.TimeStamp <= ? and ";
                    Query += " t.VehicleId in (" + vehString + ") order by t.TimeStamp ";
                }
            }
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromdt", tagInTime);
            if (!string.IsNullOrEmpty(tagOutTime))
                lParameter.Add("todt", tagOutTime);
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }

