        public string updateTripDeparture(string tripId, string vehicleNo, string source, DateTime enteredDate)
        {
            DateTime CurrentDateTime = DateTime.Now;
            var lParameter = new Dictionary<string, object>();
            TimeSpan timediff = CurrentDateTime.Subtract(enteredDate);
            string outTime = string.Empty;

            string query = "SELECT outtimestamp from vehicleinplant WHERE vehicleid=? AND locationstr=? AND intimestamp>=? order by intimestamp asc limit 1";           // Trip Entered onwords check Left time calulating.
            lParameter.Add("VehicleId", vehicleNo);
            lParameter.Add("SOURCE", source);
            lParameter.Add("tripAddedTime", formatDBDate(enteredDate));
            outTime = Convert.ToString(dbx.executeScalar(query, lParameter));

            if (string.IsNullOrEmpty(outTime) && timediff.Hours > 2)                                                // Trip entered 2 hours onwords also not left then check previous left time
            {
                lParameter.Clear();
                query = "SELECT outtimestamp from vehicleinplant WHERE vehicleid=? AND locationstr=? AND intimestamp>=? AND intimestamp<=? order by intimestamp desc limit 1";
                lParameter.Add("VehicleId", vehicleNo);
                lParameter.Add("SOURCE", source);
                lParameter.Add("geofenceInTime", formatDBDate(enteredDate.AddHours(-12)));
                lParameter.Add("tripAddedTime", formatDBDate(enteredDate));
                outTime = Convert.ToString(dbx.executeScalar(query, lParameter));
            }

            if (!string.IsNullOrEmpty(outTime))                                             // Update the table Departure left information & avoid exicte one more time 
            {
                try
                {
                    outTime = formatDBDate(Convert.ToDateTime(outTime));                    // inserting value in db format;
                }
                catch
                {
                    outTime = outTime.Trim(' ');
                }

                lParameter.Clear();
                query = "UPDATE trip SET Depature=?, DeptUpdated=1 WHERE Id=? AND VehicleId=? AND SOURCE=?";
                lParameter.Add("DepatureTime", outTime);
                lParameter.Add("TripId", tripId);
                lParameter.Add("VehicleId", vehicleNo);
                lParameter.Add("SOURCE", source);
