        public string CheckandUpdtArrival(string tripId, string vehicleNo, string source, string destination, DateTime Depttime, string ExpectedTime, string SessionId)
        {
            DateTime CurrentTime = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff(SessionId));
            TimeSpan TraTime = CurrentTime.Subtract(Depttime);
            TimeSpan ExTraTime = ConvertStringToTimeSpan(ExpectedTime);
            var lParameter = new Dictionary<string, object>();
            string query = "SELECT intimestamp from vehicleinplant WHERE vehicleid=? AND locationstr=? AND intimestamp>? order by intimestamp asc limit 1";
            lParameter.Add("VehicleId", vehicleNo);
            lParameter.Add("Destination", destination);
            lParameter.Add("outtimestamp", formatDBDate(Depttime));
            string inTime = Convert.ToString(dbx.executeScalar(query, lParameter));

            if (!string.IsNullOrEmpty(inTime))
            {
                try
                {
                    inTime = formatDBDate(Convert.ToDateTime(inTime));
                }
                catch
                {
                    inTime = inTime.Trim(' ');
                }
                lParameter.Clear();
                query = "UPDATE `trip` SET `Arrival`=?,`ClosedType`='Automatically' WHERE `Id`=? AND VehicleId=? AND SOURCE=?";
                lParameter.Add("InTime", inTime);
                lParameter.Add("TripId", tripId);
                lParameter.Add("VehicleId", vehicleNo);
                lParameter.Add("SOURCE", source);
                return Convert.ToString(dbx.executeNonQuery(query, lParameter));
            }
            else if (TraTime > ExTraTime)                                           // Destination geofence is not alvailable then close by trip using source Geofence
            {
				//query = "SELECT intimestamp from vehicleinplant WHERE vehicleid=? AND locationstr=? AND outtimestamp>? order by outtimestamp asc limit 1"; query modified for negative value captured in non closed trip by destination data 
				query = "SELECT intimestamp from vehicleinplant WHERE vehicleid=? AND locationstr=? AND intimestamp>? order by outtimestamp asc limit 1";
                lParameter.Clear();
                lParameter.Add("VehicleId", vehicleNo);
                lParameter.Add("source", source);
                lParameter.Add("outtimestamp", formatDBDate(Depttime.AddMinutes(30)));
                inTime = Convert.ToString(dbx.executeScalar(query, lParameter));
                if (!string.IsNullOrEmpty(inTime))
                {
                    try
                    {
                        inTime = formatDBDate(Convert.ToDateTime(inTime));
                    }
                    catch
                    {
                        inTime = inTime.Trim(' ');
                    }
                    lParameter.Clear();
                    query = "UPDATE `trip` SET `Arrival`=?,`ClosedType`='Automatically RoundTrip' WHERE `Id`=? AND VehicleId=? AND SOURCE=?";
                    lParameter.Add("InTime", inTime);
                    lParameter.Add("TripId", tripId);
                    lParameter.Add("VehicleId", vehicleNo);
                    lParameter.Add("SOURCE", source);
                    return Convert.ToString(dbx.executeNonQuery(query, lParameter));
                }
                else
                {
                    return "0";

                }
            }
            else
            {
                return "0";
            }


        }

