        public DataTable GetNokiaPassengerTagingRules(string tagIds)
        {
            string Query = "select p.TagId, MAX(CASE WHEN c.ChkId = 1 THEN p.Status END) AS `DDT Compliance`," +
            "MAX(CASE WHEN c.ChkId = 2 THEN p.Status END) AS `Driver Commercial License`," +
            "MAX(CASE WHEN c.ChkId = 3 THEN p.Status END) AS `Commercial Registration`," +
            "MAX(CASE WHEN c.ChkId = 4 THEN p.Status END) AS `< 4 years ageing`," +
            "MAX(CASE WHEN c.ChkId = 5 THEN p.Status END) AS `IVMS Functional`," +
            "MAX(CASE WHEN c.ChkId = 6 THEN p.Status END) AS `First Aid Kit`," +
            "MAX(CASE WHEN c.ChkId = 7 THEN p.Status END) AS `3 Point RSBFP`," +
            "MAX(CASE WHEN c.ChkId = 8 THEN p.Status END) AS `Driver Shoes`," +
            "MAX(CASE WHEN c.ChkId = 9 THEN p.Status END) AS `Safety Reflective Triangle`," +
            "MAX(CASE WHEN c.ChkId = 10 THEN p.Status END) AS `Driver Medical Fit`," +
            "MAX(CASE WHEN c.ChkId = 11 THEN p.Status END) AS `Fire Extinguisher`," +
            "MAX(CASE WHEN c.ChkId = 12 THEN p.Status END) AS `Reflective Jackets`," +
            "MAX(CASE WHEN c.ChkId = 13 THEN p.Status END) AS `Aknowlegdment`," +
            "MAX(CASE WHEN c.ChkId = 14 THEN p.Status END) AS `Traveller Additional Info`," +
            "MAX(CASE WHEN c.ChkId = 15 THEN p.Status END) AS `Misc Info`from psngr_chklist_status p left join psngr_chklist c on p.ChkId=c.ChkId where c.ChkId<16 AND p.TagId in (" + tagIds + ")GROUP BY p.TagId";
            return dbx.executeQuery(Query).Tables[0];
        }
