        public DataTable GetCustLocations(string custCodes)
        {
            var lParameter = new Dictionary<string, object>();
            String[] vals = custCodes.Replace("'", "").Replace("\"", "").Split(',');
            string inparam = "";
            for (int i = 0; i < vals.Length; i++)
            {
                if (i == 0)
                    inparam += ("?");
                else
                    inparam += (",?");
                lParameter.Add("val" + i, vals[i]);
            }
            string Query = "select p.customerid,c.Name,(p.minlatitude+ p.maxlatitude)/2 lat,(p.minlongitude+ "
                         + "p.maxlongitude)/2 lng from plantgeolocations p left join customerinfo c on c.CustomerCode="
                         + "p.customerid where p.customerid in (" + inparam + ") group by p.customerid";
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }
