        public DataTable getDistanceMatForCustomers(string custCodes)
        {
            string[] custs = custCodes.Split(',');
            string inQuery = "";
            var lParameter = new Dictionary<string, object>();
            for (int i = 0; i < custs.Length; i++)
            {
                inQuery += "?";
                if (i != custs.Length - 1)
                    inQuery += ",";
                lParameter.Add("cust" + i, custs[i]);
            }
            for (int i = 0; i < custs.Length; i++)
            {
                lParameter.Add("custs" + i, custs[i]);
            }
            string Query = "select c.FromCustId,c.ToCustId,c.Distance,r.RTKm/2 RTKm from customerdistancematrix c left join "
                         + "plantgeolocations p on p.customerid=c.FromCustId left join roundtriptime r on r.Plant=p.locstr and "
                         + "r.CustomerCode=c.ToCustId where c.FromCustId in (" + inQuery + ") and c.ToCustId in (" + inQuery + ")";
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }
