        }

        public DataTable GetAssetStatus(DateTime FromDate, DateTime ToDate, string AccountId, string Region)
        {
            string Query = string.Empty;
            string Condition = string.Empty;
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("FromDate", formatDBDate(FromDate));
            lParameter.Add("ToDate", formatDBDate(ToDate));
            if (!string.IsNullOrEmpty(Region))
            {
                Condition = "ci.Region=?";
                lParameter.Add("Region", Region);
            }
            else
            {
                Condition = "ci.AccountId=?";
                lParameter.Add("AccountId", AccountId);
            }
            Query = "select a.CustomerId,a.ProductId,(select (case when TransactionType = 0 then " +
                    "CurrentAssets+UpdatedAssets else CurrentAssets-UpdatedAssets end) from asset_transaction where Id=Min(a.Id)) " +
                    "as Opening,(select CurrentAssets from asset_transaction where Id=MAx(a.Id)) as Closing, " +
                    "sum(CASE WHEN a.TransactionType = 0 THEN a.UpdatedAssets ELSE 0 END) Dispatched, " +
                    "sum(CASE WHEN a.TransactionType = 1 THEN a.UpdatedAssets ELSE 0 END) Recieved, " +
                    "CAST(a.TransactionTime AS DATE) as Date,ci.Region,ci.Name,d.ProductName from asset_transaction a join customerinfo ci " +
                    "on ci.customerId=a.CustomerId join dc_productinfo d on d.Id=a.ProductId where a.TransactionTime>=? and a.TransactionTime<=? " +
                    "and " + Condition + " group by CAST(a.TransactionTime AS DATE),a.CustomerId,a.ProductId";
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }

        public DataTable GetDiscrepancyReceiving(DateTime FromDate, DateTime ToDate, string AccountId, string Region)
        {
            string Query = string.Empty;
            string Condition = string.Empty;
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("FromDate", formatDBDate(FromDate));
            lParameter.Add("ToDate", formatDBDate(ToDate));
            if (!string.IsNullOrEmpty(Region))
            {
                Condition = "c.Region=?";
                lParameter.Add("Region", Region);
            }
            else
            {
                Condition = "c.AccountId=?";
                lParameter.Add("AccountId", AccountId);
            }
            Query = "select cd.CustomerId,d.ProductId,(sum(d.Quntity)-sum(d.ReceivedQuantity)) as Diff,cast(v.DateTime as Date) " +
                    "as Date from customerdcassign cd join dc_quntityinfo d on cd.id=d.CustomerDCAssignId join " +
                    "vehicledctrip v on v.id=cd.DCTripId join customerinfo c on c.customerId=cd.CustomerId " +
                    "where v.DateTime>=? and v.DateTime<=? and " + Condition + " group by cd.CustomerId,d.ProductId,cast(v.DateTime as Date)";
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }

