        ///************************Get Passengers info********Added by Mallikarjun
        public DataTable GetPassengerInfo(string sessionId, string KeyWord, string user, string psngr_id = "0")
        {
            string query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            int accountId = 0;
            if (!string.IsNullOrEmpty(sessionId))
                accountId = GetAccountId(sessionId);
            if (KeyWord == "SelVehChkLst")
            {
                string accountName = GetAccountName(sessionId);
                query = "select p.PsngrId,p.PsngrName,p.MobileNo,ri.RegionName,p.Gender,p.EmpId,p.AssignedVehicleId,p.Designation from psngr_info p " +
                        "inner join regioninfo ri on ri.RegionId=p.RegionId where p.Active=1 and p.AccountId=?";
                lParameter.Add("AccountId", accountId);
                if (accountId == 2100)
                    query += " and RegionName like '%" + accountName + "%'";
                else if (accountId == 4315)
                {
                    int GId = getGroupId(sessionId);
                    if (GId != 8199)
                    {
                        query += " and ri.groupid=?";
                        lParameter.Add("Groupid", GId);
                    }
                }
            }
            else if (KeyWord == "SchVehTrck")
            {
                query = "select p.PsngrId,p.PsngrName,p.MobileNo,'' RegionName,p.Gender,p.EmpId,p.AssignedVehicleId,p.Designation from psngr_info "
                      + "p where p.Active=1 and p.AccountId=? and p.Addedby='" + user + "'";
                lParameter.Add("AccountId", accountId);
            }
            else if (KeyWord == "AsgndVehTrck")
            {
                query = "select p.PsngrId,p.PsngrName,p.MobileNo,'' RegionName,p.Gender,p.EmpId,p.AssignedVehicleId,p.Designation from psngr_info "
                 + "p where p.Active=1 and p.AccountId=?";
                lParameter.Add("AccountId", accountId);
            }
            else if (psngr_id != "" && psngr_id != "0")
            {
                query = "select p.*,ri.RegionName from psngr_info p left join regioninfo ri on ri.RegionId = p.RegionId where p.PsngrId = ?";
                lParameter.Add("PsngrId", psngr_id);
            }
            else
                return null;
            return dbx.executeQuery(query, lParameter).Tables[0];

        }

