        public string InsertPassengerInfo(object myObject, string sessionId)
        {
            Type myType = myObject.GetType();
            System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
            string Name = props[1].GetValue(myObject, null).ToString();
            string MobileNo = props[2].GetValue(myObject, null).ToString();
            string Region = props[3].GetValue(myObject, null).ToString();
            string Gender = props[4].GetValue(myObject, null).ToString();
            string EmpId = props[5].GetValue(myObject, null).ToString();
            string AssignedVeh = props[7].GetValue(myObject, null).ToString();
            string Addedby = props[8].GetValue(myObject, null).ToString();
            string Designation = Convert.ToString(props[9].GetValue(myObject, null));
            int accountId = GetAccountId(sessionId);

            var lParameter = new Dictionary<string, object>();

            string query = "select PsngrId from `psngr_info`  where MobileNo=? and Active=1 and accountId=?";
            lParameter.Add("MobileNo", MobileNo);
            lParameter.Add("accountId", accountId);
            object obj = dbx.executeScalar(query.ToString(), lParameter);
            if (obj != null)
            {
                int psngrId = Convert.ToInt16(obj);
                string res = "0";
                if (psngrId > 0)
                {
                    query = "select count(1) from psngr_tag pt where pt.PsngrId=" + psngrId;
                    obj = dbx.executeScalar(query.ToString(), lParameter).ToString();
                    if (Convert.ToInt16(obj) == 0)
                    {
                        query = "Update `psngr_info`  set`PsngrName`=?,`MobileNo`=?, `RegionId`=?, `Gender`=?," +
                                 "`EmpId`=?, AssignedVehicleId=?, Designation=?" +
                                 " where PsngrId=?";
                        query = query.Replace(",'NULL'", ",NULL");//bug Fixed
                        var lParameter1 = new Dictionary<string, object>();
                        lParameter1.Add("PsngrName", Name);
                        lParameter1.Add("MobileNo", MobileNo);
                        lParameter1.Add("RegionId", Region);
                        lParameter1.Add("Gender", Gender);
                        lParameter1.Add("EmpId", EmpId);
                        lParameter1.Add("AssignedVehicleId", AssignedVeh);
                        lParameter1.Add("Designation", Designation);
                        lParameter1.Add("PsngrId", psngrId);
                        res = dbx.executeNonQuery(query.ToString(), lParameter1).ToString();
                        return res;
                    }
                }
                return res;

            }
