        public int InsertPsngrChecklistForPsngr(string psngrId, string vehicleId, string type, string rules, string wfmid, string ptw, string driverId, string IMEI, string Lat, string Lng, string Manual, string DriverDetails)
        {
            try
            {
                string query = "select p.VehicleId,p.TagInTime,'TagOut' as Status from psngr_tag p where p.Id=(select Max(p.Id) as Id from "
                             + "psngr_tag p where p.PsngrId=? and (p.TagOutTime is null or trim(p.TagOutTime)=''))";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("PsngrId", psngrId);
                DataTable tag = dbx.executeQuery(query, lParameter).Tables[0];

                if (tag.Rows.Count == 0 && type == "TagIn")
                {
                    query = "select v.VehicleID from vehicles v left join configdata c on c.TruckID=v.VehicleID where replace(v.VehicleID,' ','')=? and c.UID<100000";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("VehicleId", vehicleId);
                    DataTable veh = dbx.executeQuery(query, lParameter).Tables[0];
                    if (veh.Rows.Count > 0)
                    {
                        vehicleId = veh.Rows[0]["VehicleID"].ToString();
                        if (Manual == "1")
                            Manual = "2";
                    }
                    DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
                    string formatDate = formatDBDate(now);
                    query = "INSERT INTO `psngr_tag` (`PsngrId`, `VehicleId`,`DriverId`, `TagInTime`, `TagInIMEI`, `TagInLat`, "
                           + "`TagInLng`, `WFM_ID`, `PTW_Number`,`Manual`,DriverDetails) VALUES (?,?,?,?,?,?,?,?,?,?,?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("PsngrId", psngrId);
                    lParameter.Add("VehicleId", vehicleId);
                    lParameter.Add("DriverId", driverId);
                    lParameter.Add("TagInTime", formatDate);
                    lParameter.Add("TagInIMEI", IMEI);
                    lParameter.Add("TagInLat", Lat);
                    lParameter.Add("TagInLng", Lng);
                    lParameter.Add("WFM_ID", wfmid);
                    lParameter.Add("PTW_Number", ptw);
                    lParameter.Add("Manual", Manual);
                    lParameter.Add("DriverDetails", DriverDetails);
                    int res = dbx.executeNonQuery(query, lParameter);
                    if (res > 0 && rules == "")
                    {
                        return res;
                    }
                    else if (res > 0)
                    {
                        string resStatus = "YES";
                        query = "select Max(p.Id) from psngr_tag p where p.PsngrId=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("psngrId", psngrId);
                        string id = dbx.executeScalar(query, lParameter).ToString();
                        query = "insert into psngr_chklist_status (TagId,ChkId,Status) values ";
                        string[] rule = rules.Split(new string[] { "@#" }, StringSplitOptions.None);
                        lParameter = new Dictionary<string, object>();
                        for (int i = 0; i < rule.Length; i++)
                        {
                            string[] checklist = rule[i].Split('|');
                            query += "(?,?,?)";
                            if (i == rule.Length - 1)
                                query += ";";
                            else
                                query += ",";
                            if (checklist[1].ToLower().Contains("no"))
                                resStatus = "NO";
                            else if (checklist[1].ToLower() == "null")
                                checklist[1] = "";
                            lParameter.Add("id" + i, id);
                            lParameter.Add("checklist0" + i, checklist[0]);
                            lParameter.Add("checklist1" + i, checklist[1]);
                        }
                        res = dbx.executeNonQuery(query, lParameter);
                        if (res > 0 && resStatus == "NO")
                        {
                            try
                            {
                                DataTable Rules = GetPassengerTagingRules(id);
                                string msg = string.Empty;
                                query = "select * from psngr_info where PsngrId=?";
                                lParameter = new Dictionary<string, object>();
                                lParameter.Add("psngrId", psngrId);
                                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                                string drivername = getdrivername(vehicleId);
                                msg = vehicleId + "(" + drivername.Split(',')[0] + ") is Failed in Passenger Checklist,WFM ID:" + wfmid + "PTW:" + ptw + "<br/>";
                                for (int k = 0; k < Rules.Rows.Count; k++)
                                {
                                    if (Rules.Rows[k]["Status"].ToString().ToLower().Contains("no"))
                                        msg += Rules.Rows[k]["ChkName"] + ":<b>" + Rules.Rows[k]["Status"] + "</b><br/>";
                                }
                                msg += "Passenger Name:" + dt.Rows[0]["PsngrName"].ToString() + "(" + dt.Rows[0]["EmpId"].ToString() + ") - " + dt.Rows[0]["MobileNo"].ToString();
                                AddTransporterNotifications(GetListOfUsersByVehicleID(vehicleId), vehicleId + "(" + drivername.Split(',')[0] + ") is Failed in Passenger Checklist", msg);
                            }
                            catch { }
                        }
                        if (res > 0 && driverId == "0")
                        {
                            try
                            {
                                AddTransporterNotifications(GetListOfUsersByVehicleID(vehicleId), vehicleId + "-Non compliance Driver", vehicleId + " is assigned to non compliance driver. Driver Details -" + DriverDetails);
                            }
                            catch { }
                        }
                        return res;
                    }
                    else
                        return 0;
                }
                else if (tag.Rows.Count > 0 && type == "TagOut")
                {
                    query = "select Max(p.Id) from psngr_tag p where p.PsngrId=? and (p.TagOutTime is null or trim(p.TagOutTime)='')";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("psngrId", psngrId);
                    string id = dbx.executeScalar(query, lParameter).ToString();
                    if (!String.IsNullOrEmpty(id))
                    {
                        DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
                        string formatDate = formatDBDate(now);
                        query = "update psngr_tag set TagOutTime=?,TagOutIMEI=?,TagOutLat=?,TagOutLng=? where Id=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("formatDate", formatDate);
                        lParameter.Add("IMEI", IMEI);
                        lParameter.Add("Lat", Lat);
                        lParameter.Add("Lng", Lng);
                        lParameter.Add("id", id);
                        return dbx.executeNonQuery(query, lParameter);
                    }
                    else
                        return 0;
                }
                else
                    return 0;
            }
            catch
            {
                return 0;
            }
        }

