		// Vehicle Rag Report
		public DataTable GetVehicleViolationCounts(string fromDate, string toDate, int groupId, string circle, string transporter)
		{ 
			string fromDateStr = formatDBDate(Convert.ToDateTime(fromDate));
			string toDateStr =  formatDBDate(Convert.ToDateTime(toDate));			 

			string violationQuery = @"SELECT s.vehicleId, s.drivername, SUM(CASE WHEN s.type='HIGH ACCELERATION' THEN 1 ELSE 0 END) AS HighAcceleration,
            SUM(CASE WHEN s.type='HARSH BRAKING' THEN 1 ELSE 0 END) AS HarshBraking,   SUM(CASE WHEN s.type='OVERSPEEDING' THEN 1 ELSE 0 END) AS Overspeeding
            FROM storevehicleviolations s WHERE s.timestamp BETWEEN ? AND ? 
            AND s.vehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE groupid=?)  GROUP BY s.vehicleId";
			var lParameter = new Dictionary<string, object>();
			lParameter.Add("fromDate", fromDateStr);
			lParameter.Add("toDate", toDateStr);
			lParameter.Add("groupId", groupId); 
			return dbx.executeQuery(violationQuery, lParameter).Tables[0];
		}
		public DataTable GetVehicleDisatnceData(string fromDate, string toDate, int groupId)
		{			 
			string fromDateStr = formatDBDate(Convert.ToDateTime(fromDate));
			string toDateStr = formatDBDate(Convert.ToDateTime(toDate));

			string distanceQuery = @"SELECT vehicleid,SUM(Distance) AS Distance FROM dailydistance   WHERE date BETWEEN ? AND ?
                                  AND vehicleid IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE groupid=?) GROUP BY vehicleid";
			var lParameter = new Dictionary<string, object>();
			lParameter.Add("fromDate", fromDateStr);
			lParameter.Add("toDate", toDateStr);
			lParameter.Add("groupId", groupId);
			return dbx.executeQuery(distanceQuery, lParameter).Tables[0];
		}
		//RAG Report 
		public DataTable GetRAGReport(string fromDate, string toDate, int groupId, string circle, string transporter)
        {
            string where = " ";
            var IParameter = new Dictionary<string, object>();
            IParameter.Add("fromDate", fromDate);
            IParameter.Add("toDate", toDate);
            IParameter.Add("groupId", groupId);
            if (transporter != "ALL Transporters")
            {
                where += " and ti.Name=? ";
                IParameter.Add("transporter", transporter);
            }
            if (circle != "ALL Circles")
            {
                where += " and ri.RegionName=? ";
                IParameter.Add("circle", circle);
            }
            string query = "Select di.Name as `Driver`,ri.RegionName as `Circle`,ti.Name as `Transporter`, sum(d.Kms_driven) as `Distance(KM)`, " +
                        "sum(d.harshaccln_Count)as `Harsh Accel Occurances`,ifnull((sum(d.harshaccln_Count)*100)/sum(d.Kms_driven),0) as `Acceleration per 100 KM`, " +
                        "sum(d.harshbraking_count) as `Harsh Brake Occurances`,ifnull((sum(d.harshbraking_count)*100)/sum(d.Kms_driven),0) `Deceleration per 100 KM`, " +
                        "sum(d.maxsp_count) as `Overspeed Occurances` ,ifnull((sum(d.maxsp_count)*100)/sum(d.Kms_driven),0) as `Overspeed per 100 KM`, " +
                        "ifnull((sum(d.harshbraking_count)*100)/sum(d.Kms_driven) + (sum(d.harshaccln_Count)*100)/sum(d.Kms_driven) +(sum(d.maxsp_count)*100)/sum(d.Kms_driven),0) as RAG " +
                        "from driverinfo di " +
                        "inner join daywisevehviosummary d on d.driverid=di.DriverId " +
                        "left join vehicleinfo vi on vi.VehicleId=d.vehicleid " +
                        "left join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                        "left join regioninfo ri on ri.RegionId=vi.RegionId " +
                        "where  d.driverid>0 and (d.date between ?  and ?)  and d.IsTrip=1 and d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) " + where +
                        "group by di.Name ";


            DataTable dt = dbx.executeQuery(query, IParameter).Tables[0];
            return dt;
        }


