        public DataTable GetVehicleViolationSumamryByMonth(int month, int year, int groupid)
        {
            string query = "select count(distinct(vehicleid)) as total,count(distinct if(d.Kms_driven>0,d.vehicleid,''))-1 as onroad, " +
                        "count(if(d.md>0,d.vehicleid,NULL)) as md, " +
                        "count(if(d.maxsp>0,d.vehicleid,NULL)) as os, " +
                        "count(if(d.cd>0,d.vehicleid,NULL)) as cd, " +
                        "count(if(d.nd != '0:0' && d.IsNightDrivingViol=1,d.vehicleid,NULL)) as nd, " +
                        "count(if(d.harshbraking_count >0,d.vehicleid,NULL)) as HB, " +
                        "count(if(d.harshaccln_value>0,d.vehicleid,NULL)) as HA, " +
                        "(select count(distinct t.IMEI) from taging t where month(t.TimeStamp)=? and year(t.TimeStamp)=?) as driverapp, " +
                        "(select count(c.VehicleId) from crash_events c where c.vehicleid in (select vehicleid from vehiclesgroupsmap where GroupId='" + groupid + "') and month(c.timestamp)=? and year(c.timeStamp)=?) as crashEvents " +
                        "from daywisevehviosummary d " +
                        "where month(date)=? and year(date)=?  and d.IsTrip=1 and d.VehicleId in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Month", month);
            lParameter.Add("Year", year);
            lParameter.Add("Month1", month);
            lParameter.Add("Year1", year);
            lParameter.Add("Month2", month);
            lParameter.Add("Year2", year);
            lParameter.Add("Groupid", groupid);
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];

            int accountid = GetAccountIdByGroupId(groupid);
            dt.Columns.Add("psngr_install_count", typeof(Int32));
            query = "select count(1) as total_psngr from psngr_info n where accountid = " + accountid + " and n.LogggedOn is not NULL and n.Active = 1";
            DataTable temp = dbx.executeQuery(query).Tables[0];
            dt.Rows[0]["psngr_install_count"] = temp.Rows[0]["total_psngr"];

            dt.Columns.Add("psngr_using_count", typeof(Int32));
            query = "select count(distinct psngr.PsngrId) as using_psngr from psngr_tag psngr where month(TagInTime)=" + month + " and year(TagInTime)=" + year + " and psngr.PsngrId in (select PsngrId from psngr_info where AccountId=" + accountid + ")";
            temp = dbx.executeQuery(query).Tables[0];
            dt.Rows[0]["psngr_using_count"] = temp.Rows[0]["using_psngr"];

            dt.Columns.Add("no_of_shifts", typeof(Int32));
            query = "select count(1) as no_of_shifts from daywisevehviosummary d  where month(date)=? and year(date)=? " +
                    " and d.IsTrip = 1 and d.VehicleId in (select vehicleid from vehiclesgroupsmap m where m.GroupId =?)" +
                    " and d.Kms_driven > 0";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("Month", month);
            lParameter.Add("year", year);
            lParameter.Add("groupid", groupid);
            temp = dbx.executeQuery(query, lParameter).Tables[0];
            dt.Rows[0]["no_of_shifts"] = temp.Rows[0]["no_of_shifts"];

            dt.Columns.Add("TagInPsngrs", typeof(Int32));
            query = "select COUNT(DISTINCT CONCAT(DATE_FORMAT(d.TagInTime,'%d-%m-%Y'),'-',d.PsngrId)) as TagInPsngrs from psngr_tag d  " +
                     " where month(TagInTime)=? and year(TagInTime) = ?" +
                     " and d.VehicleId in (select vehicleid from vehiclesgroupsmap m where m.GroupId = ?)";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("Month", month);
            lParameter.Add("year", year);
            lParameter.Add("groupid", groupid);
            temp = dbx.executeQuery(query, lParameter).Tables[0];
            dt.Rows[0]["TagInPsngrs"] = temp.Rows[0]["TagInPsngrs"];


            return dt;
        }
        public DataTable Get_ClientwiseVehiclesData(int groupid, string client, string fromdate, string todate)
        {
            string query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            query = "select count(distinct v.Vehicle) as TotalVeh from vehdriver_staticdata v ";
            if (client != "ALL Clients")
            {
                query += " where v.CT=? ";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("client", client);
            }
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];

            dt.Columns.Add("TotalGPSVeh", typeof(Int32));
            query = "select count(distinct c.TruckID) as TotalGPSVeh from vehdriver_staticdata v join configdata c on REPLACE(c.TruckID, ' ', '') = REPLACE(v.Vehicle, ' ', '')";
            if (client != "ALL Clients")
            {
                query += " where v.CT=? ";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("client", client);
            }
            DataTable temp = dbx.executeQuery(query, lParameter).Tables[0];
            dt.Rows[0]["TotalGPSVeh"] = temp.Rows[0]["TotalGPSVeh"];

            dt.Columns.Add("TotalUsedVeh", typeof(Int32));
            query = "select count(distinct c.TruckID) as TotalUsedVeh from vehdriver_staticdata v " +
                    " join configdata c on REPLACE(c.TruckID, ' ', '') = REPLACE(v.Vehicle, ' ', '')" +
                    " where c.TruckID in (select distinct vehicleid from daywisevehviosummary d where d.date between '" + fromdate + "' and '" + todate + "' and d.Kms_driven > 5)";
            if (client != "ALL Clients")
            {
                query += " and v.CT=? ";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("client", client);
            }
            temp = dbx.executeQuery(query, lParameter).Tables[0];
            dt.Rows[0]["TotalUsedVeh"] = temp.Rows[0]["TotalUsedVeh"];

            dt.Columns.Add("PsngrAppUsage", typeof(Int32));
            query = "select count(distinct c.TruckID) as PsngrAppUsage from vehdriver_staticdata v" +
                    " join configdata c on REPLACE(c.TruckID, ' ', '') = REPLACE(v.Vehicle, ' ', '') where" +
                    " c.TruckID in (select distinct vehicleid from psngr_tag d where d.TagInTime  between '" + fromdate + "' and  '" + todate + "')";
            if (client != "ALL Clients")
            {
                query += " and v.CT=? ";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("client", client);
            }
            temp = dbx.executeQuery(query, lParameter).Tables[0];
            dt.Rows[0]["PsngrAppUsage"] = temp.Rows[0]["PsngrAppUsage"];

            return dt;
        }

