        public string AuthenticateAPIKey(string API_Key, string MethodId, string UserIP, string Client)
        {
            string result = "FAIL:INVALID_API_KEY";
            var lParameter = new Dictionary<string, object>();
            //string Query = "select  k.AccountId,k.groupId,k.username,s.SessionID,k.Allowed_IP,k.Client,k.LocationFlag,a.* from tbl_api_key k " +
            //               " left join tbl_api_access a on a.API_Id=k.Id  join sessions s on s.login=k.username where k.APIKey=? and k.IsActive=1";
            //lParameter.Add("Method_Id", MethodId);modified by suvarna on 15/2/2021 to bypass methodid
            //lParameter.Add("APIKey", API_Key);

            string Query = "select  k.AccountId,k.groupId,k.username,s.SessionID,k.Allowed_IP,k.Client,k.LocationFlag,a.* from tbl_api_key k " +
                "left join tbl_api_access a on a.API_Id = k.Id and a.Method_Id =? join sessions s on s.login = k.username where k.APIKey =? and k.IsActive = 1";
            lParameter.Add("Method_Id", MethodId);
            lParameter.Add("APIKey", API_Key);
            DataTable dtwebtoken = dbx.executeQuery(Query, lParameter).Tables[0];
            if (dtwebtoken.Rows.Count > 0)
            {
                string allowed_IPs = dtwebtoken.Rows[0]["Allowed_IP"].ToString();
                string Method_Id = dtwebtoken.Rows[0]["Method_Id"].ToString();
                string ClientId = dtwebtoken.Rows[0]["Client"].ToString();
                if (allowed_IPs != "" && !allowed_IPs.Contains(UserIP))
                {
                    result = "FAIL:INVALID_IP";
                }
                else if (string.IsNullOrEmpty(Method_Id))
                {
                    result = "FAIL:ACCESS_DENIED_FOR_METHOD";
                }
                else if (!string.IsNullOrEmpty(ClientId) && ClientId.ToLower() != Client)
                {
                    result = "FAIL:INVALID_CLIENT_ID";
                    if (Client == "")
                        result = "FAIL:CLIENT_ID_PARAM_MISSING";
                }
                else
                {
                    result = dtwebtoken.Rows[0]["username"].ToString() + "," + dtwebtoken.Rows[0]["SessionID"].ToString() + ","
                        + dtwebtoken.Rows[0]["groupId"].ToString() + "," + dtwebtoken.Rows[0]["AccountId"].ToString() + ","
                        + dtwebtoken.Rows[0]["LocationFlag"].ToString();
                    DateTime LastRequest = Convert.ToDateTime(dtwebtoken.Rows[0]["LastAccess"].ToString());
                    int NoOfReqMin = Convert.ToInt32(dtwebtoken.Rows[0]["RequestedPerMin"].ToString());
                    int NoOfReqHour = Convert.ToInt32(dtwebtoken.Rows[0]["RequestedPerHour"].ToString());
                    int NoOfReqDay = Convert.ToInt32(dtwebtoken.Rows[0]["RequestedPerDay"].ToString());

                    int RejectedInMin = Convert.ToInt32(dtwebtoken.Rows[0]["RejectedInMin"].ToString());
                    int RejectedInHour = Convert.ToInt32(dtwebtoken.Rows[0]["RejectedInHour"].ToString());
                    int RejectedInDay = Convert.ToInt32(dtwebtoken.Rows[0]["RejectedInDay"].ToString());

                    int AccessPerMin_Limit = Convert.ToInt32(dtwebtoken.Rows[0]["AccessPerMin_Limit"].ToString());
                    int AccessPerHour_Limit = Convert.ToInt32(dtwebtoken.Rows[0]["AccessPerHour_Limit"].ToString());
                    int AccessPerDay_Limit = Convert.ToInt32(dtwebtoken.Rows[0]["AccessPerDay_Limit"].ToString());

                    DateTime now = DateTime.Now;
                    string updatereq = "";
                    if (LastRequest.Day == now.Day && LastRequest.Hour == now.Hour && LastRequest.Minute == now.Minute)
                    {
                        NoOfReqMin++; NoOfReqHour++; NoOfReqDay++;
                        if (NoOfReqMin > AccessPerMin_Limit)
                        {
                            result = "FAIL:OVER_QUERY_LIMIT";
                            RejectedInMin++;
                            if (LastRequest.Day == now.Day && LastRequest.Hour == now.Hour)
                                RejectedInHour++;
                            if (LastRequest.Day == now.Day)
                                RejectedInDay++;
                        }
                        else
                        {
                            updatereq = "RequestedPerMin=" + NoOfReqMin + ",RequestedPerHour=" + NoOfReqHour + ",RequestedPerDay=" + NoOfReqDay + ",LastAccess='" + now.ToString("yyyy-MM-dd HH:mm:ss") + "',";
                        }
                    }
                    else if (LastRequest.Day == now.Day && LastRequest.Hour == now.Hour)
                    {
                        RejectedInMin = 0;
                        NoOfReqHour++; NoOfReqDay++;
                        if (NoOfReqHour > AccessPerHour_Limit)
                        {
                            result = "FAIL:OVER_QUERY_LIMIT";
                            RejectedInMin++;
                            if (LastRequest.Day == now.Day && LastRequest.Hour == now.Hour)
                                RejectedInHour++;
                            if (LastRequest.Day == now.Day)
                                RejectedInDay++;
                        }
                        else
                        {
                            updatereq = "RequestedPerMin=1,RequestedPerHour=" + NoOfReqHour + ",RequestedPerDay=" + NoOfReqDay + ",LastAccess='" + now.ToString("yyyy-MM-dd HH:mm:ss") + "',";
                        }
                    }
                    else if (LastRequest.Day == now.Day)
                    {
                        NoOfReqDay++;
                        RejectedInMin = 0;
                        RejectedInHour = 0;
                        if (NoOfReqDay > AccessPerDay_Limit)
                        {
                            result = "FAIL:OVER_QUERY_LIMIT";
                            RejectedInMin++;
                            RejectedInHour++;
                            if (LastRequest.Day == now.Day)
                                RejectedInDay++;
                        }
                        else
                        {
                            updatereq = "RequestedPerMin=1,RequestedPerHour=1,RequestedPerDay=" + NoOfReqDay + ",LastAccess='" + now.ToString("yyyy-MM-dd HH:mm:ss") + "',";
                        }
                    }
                    else
                    {
                        RejectedInMin = 0;
                        RejectedInHour = 0;
                        RejectedInDay = 0;
                        updatereq = "RequestedPerMin=1,RequestedPerHour=1,RequestedPerDay=1,LastAccess='" + now.ToString("yyyy-MM-dd HH:mm:ss") + "',";
                    }
                    updatereq = updatereq + "RejectedInMin=" + RejectedInMin + ",RejectedInHour=" + RejectedInHour + ",RejectedInDay=" + RejectedInDay;
                    dbx.executeNonQuery("Update tbl_api_access set " + updatereq + " WHERE Access_Id=" + dtwebtoken.Rows[0]["Access_Id"].ToString());
                }
            }
            return result;
        }

