        //record log for incentive
        public int RecordIncentiveLog(string purpose, string vehicle, string driverid, string drivername, string date, int points, int groupid, string addedby, bool IgnoreOnDate = false, string IgnoringTime = "")
        {
            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            if (IgnoreOnDate)
            {
                Query = "Select sum(Points) as Total from `incentivelog` where Purpose=? and Date>=? and DriverId=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Purpose", purpose);
                lParameter.Add("Date", date);
                lParameter.Add("DriverId", driverid);
                object objg = dbx.executeScalar(Query, lParameter);
                if (objg != null)
                    if (objg.ToString() != String.Empty)
                        if (Convert.ToInt32(objg) > 0)
                        {
                            return 1;
                        }
            }
            date = Convert.ToDateTime(date).ToString("yyyy-MM-dd");
            Query = "Select sum(Points) as Total from `incentivelog` where Purpose=? and Date=? and VehicleId=?;";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("Purpose", purpose);
            lParameter.Add("Date", date);
            lParameter.Add("VehicleId", vehicle);
            if (purpose.Contains("OVERSPEEDING"))
            {
                Query = "Select sum(Points) as Total from `incentivelog` where Purpose like '%OVERSPEEDING%' and Date=? and VehicleId=?;";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Date", date);
                lParameter.Add("VehicleId", vehicle);
            }

            object obj = dbx.executeScalar(Query, lParameter);
            int total = 0;
            if (obj != null)
                if (obj.ToString() != String.Empty)
                    total = Convert.ToInt32(obj);
            if (purpose == "NIGHT DRIVING" || purpose == "TOTAL RUNTIME" || purpose == "SHORT RUNTIME" || purpose == "UNSCHEDULED STOP")
            {
                Query = "Select Id from `incentivelog` where Purpose=? and Date=? and VehicleId=?;";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Purpose", purpose);
                lParameter.Add("Date", date);
                lParameter.Add("VehicleId", vehicle);
                obj = dbx.executeScalar(Query, lParameter);
                if (obj != null)
                {
                    if (points < -500)
                        points = -500;
                    Query = "Update `incentivelog` set Points=? where Purpose=? and Date=?and VehicleId=?;";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Purpose", purpose);
                    lParameter.Add("Date", date);
                    lParameter.Add("VehicleId", vehicle);
                    dbx.executeNonQuery(Query, lParameter);
                    return updateviolationsummarypoints(date, Convert.ToInt16(driverid));
                }
            }

            int maxNegPoints = -500;
            if (purpose.Contains("JRM"))
            {
                maxNegPoints = -200;
            }
            if ((total + points) < maxNegPoints)
                points = maxNegPoints - total;

            if (points != 0)
            {
                Query = "INSERT INTO `incentivelog` (`Purpose`, `VehicleId`, `DriverId`, `DriverName`, `Date`, `Points`, `GroupId`, `AddedDate`, `AddedBy`) VALUES " +
                        "(?,?,?,?,?,?,?,?,?);";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Purpose", purpose);
                lParameter.Add("VehicleId", vehicle);
                lParameter.Add("DriverId", driverid);
                lParameter.Add("DriverName", drivername);
                lParameter.Add("Date", date);
                lParameter.Add("Points", points);
                lParameter.Add("GroupId", groupid);
                lParameter.Add("AddedDate", DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
                lParameter.Add("AddedBy", addedby);
                dbx.executeNonQuery(Query, lParameter);
                return updateviolationsummarypoints(date, Convert.ToInt16(driverid));
            }
            return 0;
        }
