        public DataTable getVehiclesEntryInPlant(string customercode, Dictionary<string, string> vehWithDc, DateTime plnRunTime)
        {
            string conditions = string.Empty;
            bool first = true;
            var lParameter = new Dictionary<string, object>();
            foreach (var item in vehWithDc)
            {
                if (first)
                {
                    conditions += "(v.vehicleid=? and v.intimestamp>?)";
                    first = false;
                }
                else
                    conditions += " or (v.vehicleid=? and v.intimestamp>?)";
                lParameter.Add(item.Key + "_1", item.Key);
                lParameter.Add(item.Key + "_2", formatDBDate(Convert.ToDateTime(item.Value).AddHours(10)));
            }
            string query = "select v.vehicleid,Min(v.intimestamp) intimestamp from vehicleinplant v where (" + conditions + ") and "
                         + "v.locationstr in (select pg.locstr from plantgeolocations pg where pg.customername=(select p.locstr from"
                         + " plantgeolocations p where p.password=? order by p.Id limit 1)) and v.planttype in (0,1) and "
                         + "v.intimestamp<? group by v.vehicleid";

            lParameter.Add("password", customercode);
            lParameter.Add("intimestamp", formatDBDate(plnRunTime));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
