        public DataTable getVehiclesByPlant(string customercode, string type, string sessionid, DateTime plnRunTime)
        {
            string formatDt = formatDBDate(plnRunTime);
            int accountid = GetAccountId(sessionid);
            string query = "select v.VehicleId,v.Capacity,'0' Latitude,'0' Longitude,'2000-01-01' timestamp,'' positiontxt,vd.DateTime,vd.IsTripEnds,(select count(*) "
                         + "from customerdcassign cr where cr.DCTripId=(select max(id) from vehicledctrip where VehicleID=v.VehicleId and DateTime<'" + formatDt
                         + "') and cr.IsDelivered=0) sup2cust,(case when vd.IsTripEnds=0 then (select max(cr.ReverseETA) from vehicledctrip pr join customerdcassign cr "
                         + "on cr.DCTripId=pr.id where pr.id=(select max(id) from vehicledctrip where VehicleID=v.VehicleId and DateTime<'" + formatDt + "')) else "
                         + "vd.TripEndsOn end) TripEndsOn,(select sum(dd.Distance) from dailydistance dd where dd.vehicleId=v.VehicleId and day(dd.Date)<"
                         + plnRunTime.Day + " and month(dd.Date)=? and year(dd.Date)=?) kmsdriven,(case when (select count(*) from vehicletripparams_vehwise vv where "
                         + "vv.VehicleId=v.VehicleId)>0 then (select (case when vv.curfewStart=vv.curfewEnd then 'night' else 'day' end) night from "
                         + "vehicletripparams_vehwise vv where vv.VehicleId=v.VehicleId) else (select (case when vv.curfewStart=vv.curfewEnd then 'night' else 'day' "
                         + "end) night from vehicletripparams vv where vv.groupId=(select min(vgm.GroupId) from vehiclesgroupsmap vgm where vgm.VehicleId=v.VehicleId)) "
                         + "end) nightStatus,ifnull(v.CustType,'') CustType from customerinfo c join plantgeolocations p on p.customerid=c.CustomerCode join vehicleinfo "
                         + "v on v.Plant=p.locstr join vehicles ve on v.VehicleId=ve.VehicleID join vehicledctrip vd on vd.VehicleID=v.VehicleId and vd.id=(select "
                         + "max(id) from vehicledctrip t where t.VehicleID=v.VehicleId and t.DateTime<'" + formatDt + "') where c.CustomerCode=? and v.TypeOfVehicle = "
                         + "'Bulk' and ve.AccountID=?";
            if (type == "ALDS")
                query += " and v.Capacity<=12000";
            else if (type == "PROPANE")
                query += " and v.CustType='Propane'";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("month", plnRunTime.Month);
            lParameter.Add("year", plnRunTime.Year);
            lParameter.Add("customercode", customercode);
            lParameter.Add("GroupId", accountid);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable getCustomersByPlant(string customercode, string type, string propaneCustCodes, string sessionid)
        {
            int accountid = GetAccountId(sessionid);
            string typeCondition = "'STK','ALDS','COMMODITY','BOOM / BOOT'";
            if (type == "ALDS")
                typeCondition = "'ALDS'";
            else if (type == "BOOM-COMMODITY")
                typeCondition = "'COMMODITY','BOOM / BOOT'";
            else if (type == "STK")
                typeCondition = "'STK'";
            else if (type == "ALDS-BOOM-COMMODITY")
                typeCondition = "'COMMODITY','ALDS','BOOM / BOOT'";
            else if (type == "STK-BOOM-COMMODITY")
                typeCondition = "'COMMODITY','BOOM / BOOT','STK'";
            string query = "select c.CustomerCode,c.customerId,c.Name,c.CustomerType,c.MaxVehCapacity,case when c.`Storage` is null "
                         + "or trim(c.`Storage`)='' then 'NA' else c.`Storage` end Storage,case when (p.minlatitude+ "
                         + "p.maxlatitude)/2 is null then 'NA' else (p.minlatitude+ p.maxlatitude)/2 end lat,case when "
                         + "(p.minlongitude+ p.maxlongitude)/ 2 is null then 'NA' else (p.minlongitude+ p.maxlongitude)/2 end lng,"
                         + "case when s.StockLevel is null then 'NA' else s.StockLevel end StockLevel,(case when "
                         + "s.Next3DaysExpected/3 is null or s.Next3DaysExpected/3=0 then 'NA' else round(s.Next3DaysExpected/3,3) "
                         + "end) consumption,case when s.timestamp is null then 'NA' else s.timestamp end StockUpdtOn,case when "
                         + "m.Distance is null then 'NA' else m.Distance end Distance,csr.StockRequest,csr.RequiredDate,c.TimeWindow"
                         + ",pi.Demand,concat(pi.DayLimit,',',pi.StartTW,'-',pi.EndTW) tw from customerinfo c left join plantgeolocations p on p.Id="
                         + "(select min(Id) from plantgeolocations where password=c.CustomerCode) left join customerstock s on s.Id "
                         + "= (select Max(Id) from customerstock where CustomerId=c.customerId) left join customerdistancematrix m "
                         + "on m.FromCustId = c.CustomerCode and m.ToCustId =? left join customerstockrequest csr on csr.Id=(select "
                         + "max(Id) from customerstockrequest where CustomerId=c.customerId and RequiredDate>=curdate()) left join "
                         + "planinput pi on pi.Custcode=c.CustomerCode where c.AccountId=? and c.CustomerCode=? or ";
            if (type == "PROPANE")
            {
                query += "c.CustomerCode in (" + propaneCustCodes + ")";
            }
            else
                query += " c.CustomerType in (" + typeCondition + ")";
            query += "and c.Active=1 and c.DefaultPlant in (select p.locstr from plantgeolocations p where p.password=?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("customercode", customercode);
            lParameter.Add("AccountId", accountid);
            lParameter.Add("customercode1", customercode);
            lParameter.Add("customercode2", customercode);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public int saveSolution(int source, DateTime time, int delayhrs, string custType, DataTable vehTable, DataTable custTable, DataTable solTable)
        {
            string query = "INSERT INTO `planinfo` (`CustType`, `Source`, `PlanTime`, `DelayHrs`) VALUES (?, ?, ?, ?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("CustType", custType);
            lParameter.Add("Source", source);
            lParameter.Add("PlanTime", formatDBDate(time));
            lParameter.Add("DelayHrs", delayhrs);
            int i = dbx.executeNonQuery(query, lParameter);
            if (i == 1 && vehTable.Rows.Count > 0 && custTable.Rows.Count > 1)
            {
                query = "select max(PlanID) from planinfo";
                int id = Convert.ToInt16(dbx.executeScalar(query));
                query = "INSERT INTO `planvehinfo` (`PlanId`, `VehicleId`, `Capacity`, `Distance`, `Address`, `Timestamp`, `Runtime`,"
                      + " `Status`, `ETA`, `kmsdriven`) VALUES ";
                for (int j = 0; j < vehTable.Rows.Count; j++)
                {
                    query += "(" + id + ", '" + vehTable.Rows[j]["vehicle"] + "', " + vehTable.Rows[j]["capacity"] + ", "
                           + vehTable.Rows[j]["distance"] + ", '" + vehTable.Rows[j]["address"] + "', '"
                           + formatDBDate(Convert.ToDateTime(vehTable.Rows[j]["timestamp"])) + "', " + vehTable.Rows[j]["runtime"]
                           + ", '" + vehTable.Rows[j]["status"] + "', '" + formatDBDate(Convert.ToDateTime(vehTable.Rows[j]["ETA"]))
                           + "', " + vehTable.Rows[j]["kmsdriven"] + ")";
                    if (vehTable.Rows.Count - 1 != j)
                        query += ",";
                }
                dbx.executeNonQuery(query);
                query = "INSERT INTO `plancustinfo` (`PlanId`, `CustomerCode`, `Demand`, `CustomerName`, `Lat`, `Lng`, `Start`, "
                      + "`End`, `MaxVeh`, `DayLimit`, `Type`, `Storage`, `Address`, `StockLevel`, `Consumption`, `OnTransit`, "
                      + "`EstimatedDemand`, `EstimatedTransit`, `DemandBy`) VALUES ";
                for (int k = 0; k < custTable.Rows.Count; k++)
                {
                    query += "(" + id + ", " + custTable.Rows[k]["code"] + ", " + custTable.Rows[k]["demand"] + ", '"
                           + custTable.Rows[k]["name"] + "', " + custTable.Rows[k]["lat"] + ", " + custTable.Rows[k]["lng"] + ", '"
                           + custTable.Rows[k]["start"] + "', '" + custTable.Rows[k]["end"] + "', " + custTable.Rows[k]["maxveh"]
                           + ", " + custTable.Rows[k]["daylimit"] + ", '" + custTable.Rows[k]["type"] + "', "
                           + custTable.Rows[k]["storage"] + ", '" + custTable.Rows[k]["address"] + "', "
                           + custTable.Rows[k]["stocklevel"] + ", " + custTable.Rows[k]["consumption"] + ", "
                           + custTable.Rows[k]["ontransit"] + ", " + custTable.Rows[k]["estimateddemand"] + ", '"
                           + formatDBDate(Convert.ToDateTime(custTable.Rows[k]["estimatedtransit"])) + "', '"
                           + custTable.Rows[k]["demandby"] + "')";
                    if (custTable.Rows.Count - 1 != k)
                        query += ",";
                }
                dbx.executeNonQuery(query);
                query = "INSERT INTO `planrouteinfo` (`PlanID`, `Vehicle`, `Capacity`, `Route`, `Load`, `Distance`, `Manual`, "
                      + "`TripStart`, `TripStop`, `VehDetails`,Timings) VALUES ";
                for (int l = 0; l < solTable.Rows.Count; l++)
                {
                    query += "(" + id + ", '" + solTable.Rows[l]["vehicle"] + "', " + solTable.Rows[l]["capacity"] + ", '"
                           + solTable.Rows[l]["route"] + "', " + solTable.Rows[l]["load"] + ", " + solTable.Rows[l]["distance"]
                           + ", " + solTable.Rows[l]["manual"] + ", " + solTable.Rows[l]["tripstart"] + ", "
                           + solTable.Rows[l]["tripstop"] + ", '" + solTable.Rows[l]["vehdetails"] + "','" + solTable.Rows[l]["timings"] + "')";
                    if (solTable.Rows.Count - 1 != l)
                        query += ",";
                }
                dbx.executeNonQuery(query);
                return 1;
            }
            return 0;
        }
