        public DataTable getDistanceAndName(string homeCode, string destCode)
        {
            string query = "select c.CustomerCode,c.Name,(p.minlatitude+ p.maxlatitude)/2 lat,(p.minlongitude + p.maxlongitude) / 2 "
                         + "lng,d.Distance,round(r.RTKm/2,0) RTKm from customerinfo c left join plantgeolocations p on p.Id="
                         + "(select min(pg.Id) from plantgeolocations pg where pg.customerid=c.CustomerCode) left join "
                         + "customerdistancematrix d on d.FromCustId=c.CustomerCode and d.ToCustId in (?,?) left join roundtriptime r on r.Plant=p.locstr "
                         + "and r.CustomerCode in (?,?) where c.CustomerCode in (?,?) order by r.RTKm desc";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("customercode0", homeCode);
            lParameter.Add("customercode1", destCode);
            lParameter.Add("customercode2", homeCode);
            lParameter.Add("customercode3", destCode);
            lParameter.Add("customercode4", homeCode);
            lParameter.Add("customercode5", destCode);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
