        //Delete points 
        public int DeletePoints(string ids, string user, string date, int driverid)
        {
            string[] rems = ids.Split(',');
            int Finalresult = 0;
            for (int i = 0; i < rems.Length; i++)
            {
                string Query = string.Empty;
                string Date = formatDBDate(DateTime.Now);
                Query = "update incentivelog i set i.Wavied=1,i.EditedDate=?, i.EditedBy=? where i.Id=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("EditedDate", Date);
                lParameter.Add("EditedBy", user);
                lParameter.Add("Id", rems[i].ToString());
                Finalresult = Finalresult + dbx.executeNonQuery(Query, lParameter);
            }
            updateviolationsummarypoints(date, driverid);
            return Finalresult;

        }

        public int updateviolationsummarypoints(string Date, int DriverId)
        {
            string Query = string.Empty;
            Query = "SELECT driverid,SUM(CASE WHEN Points<0 THEN Points ELSE 0 END) as Negative, " +
                  " SUM(CASE WHEN Points>=0 THEN Points ELSE 0 END) as Postive,sum(Points) as Total " +
                   "from incentivelog where driverid=? and Date=? and Wavied=0";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("DriverId", DriverId);
            lParameter.Add("Date", Date);

            DataTable dt = dbx.executeQuery(Query, lParameter).Tables[0];
            if (dt.Rows.Count > 0 && DriverId > 0)
            {
                Query = "update daywisevehviosummary d " +
                       "set d.negativepoints=?,d.positivepoints=?, d.points_earned=? " +
                       "where d.date=? and d.driverid=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Negative", dt.Rows[0]["Negative"].ToString());
                lParameter.Add("Postive", dt.Rows[0]["Postive"].ToString());
                lParameter.Add("Total", dt.Rows[0]["Total"].ToString());
                lParameter.Add("Date", Date);
                lParameter.Add("DriverId", DriverId);

                return dbx.executeNonQuery(Query, lParameter);
            }
            else
                return 0;
        }

