        public void AddRouteDeviatedSmsAlertFlag(string VehicleId, int IsDeviated, DateTime DeviatedTime)
        {
            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            string DeviatedFlag = IsRouteDeviatedSmsAlertFlag(VehicleId);
            if (!string.IsNullOrEmpty(DeviatedFlag))
            {
                Query = "update referencerouteconfig set IsDeviated=?,DeviatedTime=? where VehicleId =?";
                lParameter.Add("IsDeviated", IsDeviated);
                lParameter.Add("DeviatedTime", formatDBDate(DeviatedTime));
                lParameter.Add("VehicleId", VehicleId);
                dbx.executeNonQuery(Query, lParameter);
            }
            else
            {
                Query = "insert into referencerouteconfig (VehicleId,IsDeviated,DeviatedTime) values(?,?,?)";
                lParameter.Add("VehicleId", VehicleId);
                lParameter.Add("IsDeviated", IsDeviated);
                lParameter.Add("DeviatedTime", formatDBDate(DeviatedTime));
                dbx.executeNonQuery(Query, lParameter);
            }
        }

