        public bool IsRouteDeviationRecorded(string vehicle, string date)
        {
            string Query = string.Empty;
            Query = "select count(1) from vehicledctrip v inner join incentivelog  i on i.VehicleId=v.VehicleID " +
                    "where  i.Purpose='ROUTE DEVIATION' and date(v.DateTime)<='" + date + "' and (v.TripEndsOn>='" + date + "' or  v.TripEndsOn is null) and v.VehicleID='" + vehicle + "' " +
                    "and i.Date>=date(v.DateTime)";
            object obj = dbx.executeScalar(Query);
            if (obj.ToString() == "0")
            {
                return true;
            }
            else
                return false;
        }

