        public string AddVehicle(string VehicleId, string AccountId, string HomeLat, string HomeLong, string vehicleInfo = "", string OnOffType = "", string TempSense = "", string IconType = "Default")
        {
            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            Query = "select count(*) from vehicles v where VehicleId=? and AccountID=?";
            lParameter.Add("VehicleID", VehicleId);
            lParameter.Add("AccountId", AccountId);
            int count = Convert.ToInt32(dbx.executeScalar(Query, lParameter).ToString());
            if (count > 0)
            {
                Query = "update vehicles set VehicleInfo=? where VehicleId=? and AccountID=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleInfo", vehicleInfo);
                lParameter.Add("VehicleID", VehicleId);
                lParameter.Add("AccountId", AccountId);
                return dbx.executeNonQuery(Query, lParameter).ToString();
            }
            else
            {
                Query = "insert ignore into vehicles (VehicleId,AccountID,HomeLat,HomeLong,VehicleInfo,OnOffType,TempSense,IconType) values(?,?,?,?,?,?,?,?)";
                lParameter = new Dictionary<string, object>();
