        public DataSet GetCustomerStockRequest(string accountid, string CustomerType, string fromDate, string toDate, string type = "Report")
        {
            var lParameter = new Dictionary<string, object>();
            string Query = "select i.Name,i.CustomerCode,i.SafeLevel,i.`Storage`,i.CustomerType,i.segment,i.customerId,'0' as OnTransit,r.StockRequest,r.RequiredDate,"
                         + "r.RequestedOn,r.RequestedBy,r.DispatchBefore,a.Quantity,v.DateTime from customerinfo i join customerstockrequest r on r.Id=(select max(r1.Id)"
                         + " from customerstockrequest r1 where r1.CustomerId=i.customerId and r1.IsRejected=0) left join customerdcassign a on a.id=(select max(a1.id)"
                         + " from customerdcassign a1 join vehicledctrip v1 on a1.DCTripId=v1.id where a1.CustomerId=i.customerId and v1.IsCancel=0 and v1.IsTripEnds=1)"
                         + " left join vehicledctrip v on v.id=a.DCTripId where i.AccountId=? and i.Active=1";
            lParameter.Add("AccountId", accountid);
            if (CustomerType == "All")
                Query += " and i.CustomerType in ('STK','BOOM / BOOT','ALDS','PACKED','COMMODITY','Other')";
            else
            {
                Query += " and i.CustomerType=?";
                lParameter.Add("CustomerType", CustomerType);
            }
            if (type == "NotDispatched")
            {
                Query += " and r.DispatchBefore between ? and ?";
            }
            else
            {
                Query += " and r.RequestedOn between ? and ?";
            }
            Query += " group by r.CustomerId,r.RequiredDate,r.StockRequest";
            if (type == "NotDispatched")
            {
                Query += " order by i.customerId,r.DispatchBefore asc";
            }
            else
            {
                Query += " order by r.DispatchBefore desc";
            }
            lParameter.Add("fromDate", fromDate);
            lParameter.Add("toDate", toDate);
            return dbx.executeQuery(Query, lParameter);
        }


