        public DataTable GetDefaltShiftTime(int AccountId, string Origin, int DestType, string Destination)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            DataTable Result = new DataTable();
            string Str_Select = "SELECT v.OriginDc,v.HubName,v.CutOffTime,v.ScheduleArrival,v.GraceTime,v.DestinationType,v.IsSameDay,v.Days,"
                + "v.DepatureMinsBefore,v.DepatureMinsAfter,v.ArrivalMinsBefore,v.ArrivalMinsAfter FROM vehiclescheduleshift v ";
            lParameter.Add("AccountId", AccountId);
            lParameter.Add("OriginDc", Origin.Replace(" ", ""));
            lParameter.Add("DestinationType", DestType);
            if (!string.IsNullOrEmpty(Destination))
            {
                query.Append(Str_Select);
                query.Append("WHERE v.AccountId=? AND (REPLACE(v.OriginDc,' ','')=? OR v.OriginDc IS NULL OR v.OriginDc='') AND v.DestinationType=? AND (REPLACE(v.HubName,' ','')=?) order by v.CutOffTime asc;");
                lParameter.Add("HubName", Destination.Replace(" ", ""));
                Result = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            lParameter.Remove("HubName");
            if (Result.Rows.Count == 0)
            {
                query.Clear();
                query.Append(Str_Select);
                query.Append("WHERE v.AccountId=? AND (REPLACE(v.OriginDc,' ','')=?) AND v.DestinationType=? AND (v.HubName IS NULL OR v.HubName='') order by v.CutOffTime asc;");
                Result = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            if (Result.Rows.Count == 0)
            {
                query.Clear();
                query.Append(Str_Select);
                query.Append("WHERE v.AccountId=? AND (REPLACE(v.OriginDc,' ','')=? OR v.OriginDc IS NULL OR v.OriginDc='') AND v.DestinationType=? AND (v.HubName IS NULL OR v.HubName='') order by v.CutOffTime asc;");
                Result = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            return Result;
        }

