		public DataTable GetLastPositionByBetweenTime(string groupid, string FromDate, string ToDate, string inclNotUpdated, string AccountName)
        {
            string Query = string.Empty;
            if (AccountName.ToLower().Contains("nokia"))
            {
                Query = "select v.VehicleId,c.UID,DATE_FORMAT(l.timestamp,'%Y-%m-%d %T') as timestamp,p.positiontxt,l.latitude,l.longitude," +
                    "d.CT,d.Circle,d.Cluster,d.VehicleUsedFor,d.Vehicle,d.VehicleSupplier,d.VehicleNo,d.Engineer,d.EngineerMobileNo,d.EngineerEmpId,d.Remarks," +
                    "d.VehicleLocationTown,d.EngineerLocationTown,d.PresentVehicleType,d.ProposedVehicleType,d.VehicleMake,d.VehicleRegistrationYear,d.TravelonHighway," +
                    "d.HighwayNumber,d.DDTCertificateNo,d.DDTCertificateDate,d.DriverCommercialLicenseNo,d.DriverCommercialLicenseValidaty,d.DDTCompliance," +
                    "d.DriverCommercialLicense,d.CommercialRegistration,d.SixyearsAgeing as 6yearsAgeing,d.DriverMedicalFitness,d.IVMSFunctional,d.FirstAidKitFireExtinguisher," +
                    "d.ThreePointRetractableSeatBelt as 3PointRetractableSeatBelt,d.DriverShoes,d.ReflectiveJackets,d.DeviceID,d.DriverName,d.DriverContactNo,d.CircleInchargeName,d.CircleInchargeContactNO," +
                    "d.ClusterInchargeName,d.ClusterInchargeContactNo,d.ClusterInchargeEmpID,d.WeeklyOFF" +
                    " from vehicles i  join vehiclesgroupsmap v on v.VehicleId=i.VehicleID  join configdata c on c.TruckID=v.VehicleId and c.ReturnDate is null";
                if (inclNotUpdated == "1")
                    Query += " left join lastupdtdata l on l.truckid=v.VehicleId";
                else
                    Query += " join lastupdtdata l on l.truckid=v.VehicleId";
                Query += " left join vehiclepositiontxt p on p.truckid=l.truckid" +
                         " left join vehdriver_staticdata d on d.Vehicle=REPLACE(v.VehicleId,' ','')" +
                         " where v.GroupId=? and (l.timestamp between ? and ?";
                if (inclNotUpdated == "1")
                    Query += " or l.truckid is NULL";
                Query += ") order by d.CT asc,l.timestamp desc";
            }
            else
            {
                Query = "select v.VehicleId,c.UID,DATE_FORMAT(l.timestamp,'%Y-%m-%d %T') as timestamp,p.positiontxt,l.latitude,l.longitude from vehicles i  " +
                        " join vehiclesgroupsmap v on v.VehicleId = i.VehicleID" +
                        " join configdata c on c.TruckID = v.VehicleId and c.ReturnDate is null";
                if (inclNotUpdated == "1")
                    Query += " left join lastupdtdata l on l.truckid=v.VehicleId";
                else
                    Query += " join lastupdtdata l on l.truckid=v.VehicleId";
                Query += " left join vehiclepositiontxt p on p.truckid = l.truckid" +
                         " where v.GroupId=? and (l.timestamp between ? and ?";
                if (inclNotUpdated == "1")
                    Query += " or l.truckid is NULL";
                Query += ") order by l.timestamp desc";
            }
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("FromDate", formatDBDate(Convert.ToDateTime(FromDate)));
            lParameter.Add("ToDate", formatDBDate(Convert.ToDateTime(ToDate)));
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }

