        public DataTable GetAllTripByCriteria(string TripType, string VehicleId, DateTime FromDate, DateTime ToDate, string Source, string Destination, string LoginUser)
        {
            StringBuilder lQuery = new StringBuilder();
            var lParameter = new Dictionary<string, object>();

            int accId = GetAccountId(getSessionIdFromLogin(LoginUser));
            bool isMainGp = checkMainGroup(LoginUser);

            if (TripType == "0")
                lQuery.Append("select * from trip s where s.DateTime between ? and ?");
            else if (TripType == "1")                                   //Completed Trips
                lQuery.Append("select * from trip s where (s.Arrival is not null and s.Arrival !='') and s.DateTime between ? and ?");
            else if (TripType == "2")                                   //Not completed trips
                lQuery.Append("select * from trip s where (s.Arrival is null or s.Arrival='') and s.DateTime between ? and ?");

            lParameter.Add("FromDate", formatDBDate(FromDate).ToString());
            lParameter.Add("ToDate", formatDBDate(ToDate).ToString());
            if (!string.IsNullOrEmpty(VehicleId)) // Vehicle Condition
            {
                lQuery.Append(" and s.VehicleID=?");
                lParameter.Add("VehicleID", VehicleId);
            }
            if (!string.IsNullOrEmpty(Source))//Checking source,destination and assigning values
            {
                lQuery.Append(" and s.Source=?");
                lParameter.Add("Source", Source);
                if (!string.IsNullOrEmpty(Destination))
                {
                    lQuery.Append(" and s.Destination=?");
                    lParameter.Add("Destination", Destination);
                }
            }
            if (isMainGp == true)
            {
                lQuery.Append(" AND s.AccountId=?;");
                lParameter.Add("AccountId", accId);
            }
            else if (isMainGp == false)
            {
                lQuery.Append(" AND s.AccountId=? and s.AddedBy=?");
                lParameter.Add("AccountId", accId);
                lParameter.Add("AddedBy", LoginUser);
            }
            return dbx.executeQuery(lQuery.ToString(), lParameter).Tables[0];

        }

