        /// <param name="fromDate"></param>
        /// <param name="toDate"></param>
        /// <returns></returns>
        public DataTable getCANReport(string fromDate, string toDate, string truckid)
        {
            var IParameter = new Dictionary<string, Object>();
            IParameter.Add("truckid", truckid);
            IParameter.Add("fromdate", fromDate);
            IParameter.Add("todate", toDate);
            string Query = "select p.TruckID,c.TimeStamp,p.Latitude,p.Longitude,CONCAT('0x',HEX(CAST(c.CANM1 AS CHAR(10000) CHARACTER SET utf8mb4))) as CANM1,CONCAT('0x',HEX(CAST(c.CANM2 AS CHAR(10000) CHARACTER SET utf8mb4))) as CANM2,CONCAT('0x',HEX(CAST(c.CANM3 AS CHAR(10000) CHARACTER SET utf8mb4))) as CANM3 from CANdata c " +
                            "join positiondata p on p.id = c.ID and p.TruckID = c.TruckID and p.TimeStamp = c.TimeStamp " +
                            "where c.TruckID = ? " +
                            "and c.TimeStamp between ? and ?";
            return dbx.executeQuery(Query, IParameter).Tables[0];

        }

