        public string SaveVehicle(string VehicleId, string AccountId, string CurrentTime, string User)
        {
            var lParameter = new Dictionary<string, Object>();
            string Query = "SELECT COUNT(*) FROM vehicles v WHERE REPLACE(v.VehicleID,' ','')=? AND v.AccountID=?";
            lParameter.Add("VehicleId", VehicleId);
            lParameter.Add("AccountId", AccountId);
            int Count = Convert.ToInt32(dbx.executeScalar(Query, lParameter));
            string Result = string.Empty;
            if (Count == 0)
            {
                Query = "select s.VehicleID from useraddedvehicle s where s.VehicleID=? and s.AccountID=? and s.AddedBy=?";
                lParameter.Add("User", User);
                Result = Convert.ToString(dbx.executeScalar(Query, lParameter));
                if (string.IsNullOrEmpty(Result))
                {
                    lParameter.Clear();
                    Query = "insert into useraddedvehicle (VehicleID,AccountID,AddedOn,AddedBy) values(?,?,?,?)";
                    lParameter.Add("VehicleId", VehicleId);
                    lParameter.Add("AccountId", AccountId);
                    lParameter.Add("CurrentTime", formatDBDate(Convert.ToDateTime(CurrentTime)));
                    lParameter.Add("User", User);
                    Result = dbx.executeNonQuery(Query, lParameter).ToString();
                }
                else
                    Result = "2";
            }
            else
            {
                Result = "3";
            }
            return Result;
        }

