        public DataTable GetDriverVehicleFollowUps(string TransporterId, string loginId, string Id, string AccountId, string status, string FormName)
        {
            string query = "";
            var lParameter = new Dictionary<string, object>();
            if (Id != "0")
            {
                query = "select p.*,i.Name as TransName from tbl_trans_vehdriver_followups p " +
                        " left join transporterinfo i on i.TransporterId = p.TransporterId where p.Id=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Id", Id);
            }
            else
            {
                query = "select p.*,i.Name as TransName from tbl_trans_vehdriver_followups p " +
                         " left join transporterinfo i on i.TransporterId = p.TransporterId where (p.TransporterId=? or (p.TransporterId=0 and AddedBy=?))";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("TransporterId", TransporterId);
                lParameter.Add("AddedBy", loginId);
                if (AccountId != "0")
                {
                    query = "select p.*,i.Name as TransName from tbl_trans_vehdriver_followups p " +
                             " left join transporterinfo i on i.TransporterId = p.TransporterId where p.AccountId=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("AccountId", AccountId);
                    if (TransporterId != "0" && TransporterId != "")
                    {
                        query += " and p.TransporterId=?";
                        lParameter.Add("TransporterId", TransporterId);
                    }
                }
                if (status != "All" && status != "")
                {
                    if (status.ToLower().Contains("wait"))
                    {
                        query += " and Review_Action is Null";
                    }
                    else
                    {
                        query += " and Review_Action=?";
                        lParameter.Add("status", status);
                    }
                }
                query += " and FormName=?";
                lParameter.Add("FormName", FormName);

                query += " order by Id desc";
            }
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
