        public DataTable GetRAGReport_Total(string fromDateStr, string toDateStr, int groupId)
        {
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromDate", fromDateStr);
            lParameter.Add("toDate", toDateStr);
            lParameter.Add("groupId", groupId);

            string Query = "Select di.Name as `Driver`,ti.Name as `Transporter`, sum(d.Kms_driven) as `Distance`, " +
                        "sum(d.harshaccln_Count)as `HarshAccelCount`,ifnull((sum(d.harshaccln_Count)*100)/sum(d.Kms_driven),0) as `Accelerationper100KM`, " +
                        "sum(if(d.harshbraking_count>0,d.harshbraking_count,if(d.harshbraking='hb',1,0))) as `HarshBrakeCount`,ifnull((sum(if(d.harshbraking_count>0,d.harshbraking_count,if(d.harshbraking='hb',1,0)))*100)/sum(d.Kms_driven),0) `Decelerationper100KM`, " +
                        "sum(if(d.maxsp_count>0,d.maxsp_count,if(d.maxsp>0,1,0))) as `OverspeedCount` ,ifnull((sum(if(d.maxsp_count>0,d.maxsp_count,if(d.maxsp>0,1,0)))*100)/sum(d.Kms_driven),0) as `Overspeedper100KM`, " +
                        "ifnull((sum(if(d.harshbraking_count>0,d.harshbraking_count,if(d.harshbraking='hb',1,0)))*100)/sum(d.Kms_driven) + (sum(d.harshaccln_Count)*100)/sum(d.Kms_driven) +(sum(if(d.maxsp_count>0,d.maxsp_count,if(d.maxsp>0,1,0)))*100)/sum(d.Kms_driven),0) as RAG " +
                        "from driverinfo di " +
                        "inner join daywisevehviosummary d on d.driverid=di.DriverId " +
                        "left join vehicleinfo vi on vi.VehicleId=d.vehicleid " +
                        "left join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                        "where  d.driverid>0 and (d.date between ?  and ?)and d.vehicleid in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?) " +
                        "group by di.Name ";
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }

