        public DataTable GetFieldsByKey(string keyWord, string sessionid, string type, string id)
        {
            int accountid = GetAccountId(sessionid);
            if (type == null || type == "Save" || type == "View")
                type = "'Static','Planned','Actual'";
            else
                type = "'" + type + "'";

            string Query = "select *,'' as ValueEntered from tbl_trans_form_fields t where t.KeyWord=? and t.Type in (" + type + ") and (t.AccountId=? or t.AccountId is null or trim(t.AccountId)='')";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("KeyWord", keyWord);
            lParameter.Add("AccountId", accountid);
            if (!string.IsNullOrEmpty(id))
            {
                Query += " and t.Id=? ";
                lParameter.Add("Id", id);
            }
            Query += " order by t.Order";
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }


        public DataTable GetFieldValuesByKey(string keyWord, string actionId, string value, string login)
        {
