        public int insertMultipleFormInfo(string actionId, string actionBy, string accountId, Dictionary<string, string> fieldsWithValues, string keyword, string monthYear)
        {
            //For email Purpose added By Tushar on 29/08/2021
            string VehicleNo = "";
            string DriverName = "";
            string DrivingLicenseNumber = "";
            int iFieldId = 0;
            if (actionId == "")
            {
                if (fieldsWithValues.Count > 0)
                {
                    string query = "INSERT INTO `tbl_trans_form_action` (`EditId`, `ActionBy`, `ActionTime`, `AccountId`,KeyWord) VALUES (?, ?, ?, ?, ?)";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("EditId", 1);
                    lParameter.Add("ActionBy", actionBy);
                    lParameter.Add("ActionTime", formatDBDate(DateTime.Now));
                    lParameter.Add("AccountId", accountId);
                    lParameter.Add("KeyWord", keyword);
                    int res = dbx.executeNonQuery(query, lParameter);
                    if (res == 0)
                    {
                        return res;
                    }
                    else
                    {
                        query = "select Max(t.Id) from tbl_trans_form_action t where t.ActionBy=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("ActionBy", actionBy);
                        int id = Convert.ToInt16(dbx.executeScalar(query, lParameter));
                        lParameter = new Dictionary<string, object>();
                        query = "insert into tbl_trans_form_action_info (`ActionId`, `EditId`, `FieldId`, `Value`) values ";
                        foreach (String key in fieldsWithValues.Keys)
                        {
                            query += "(?,?,?,?),";
                            if (key.Contains("Sub"))
                            {
                                lParameter.Add("ActionId" + key, id);
                                lParameter.Add("EditId" + key, key.Split('_')[0]);
                                lParameter.Add("FieldId" + key, key.Split('_')[1]);
                                lParameter.Add("Value" + key, Convert2CamelCase(fieldsWithValues[key]));

                                //For Email Purpose
                                iFieldId = Convert.ToInt32(key.Split('_')[1]);
                                if (iFieldId == 1)
                                {
                                    DriverName = Convert2CamelCase(fieldsWithValues[key]).ToString();
                                }
                                else if (iFieldId == 6)
                                {
                                    DrivingLicenseNumber = Convert2CamelCase(fieldsWithValues[key]).ToString();
                                }
                                else if (iFieldId == 25)
                                {
                                    VehicleNo = Convert2CamelCase(fieldsWithValues[key]).ToString();
                                }
                            }
                            else
                            {
                                lParameter.Add("ActionId" + key, id);
                                lParameter.Add("EditId" + key, 1);
                                lParameter.Add("FieldId" + key, key);
                                lParameter.Add("Value" + key, Convert2CamelCase(fieldsWithValues[key]));

                                //For Email Purpose
                                iFieldId = Convert.ToInt32(key);
                                if (iFieldId == 1)
                                {
                                    DriverName = Convert2CamelCase(fieldsWithValues[key]).ToString();
                                }
                                else if (iFieldId == 6)
                                {
                                    DrivingLicenseNumber = Convert2CamelCase(fieldsWithValues[key]).ToString();
                                }
                                else if (iFieldId == 25)
                                {
                                    VehicleNo = Convert2CamelCase(fieldsWithValues[key]).ToString();
                                }
                            }
                        }
                        query = query.Substring(0, query.Length - 1);
                        res = dbx.executeNonQuery(query, lParameter);

                        DateTime Dtime = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
                        //Insert Into Request Table One row for Action Id
                        query = "INSERT INTO `tbl_trans_form_request` (ActionId ,RequestFor, `RequestType`, `RequestedBy`, `RequestedOn`, AccountId) VALUES (?,?, ?, ?, ?, ?)";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("ActionId", id);
                        lParameter.Add("RequestFor", keyword);
                        lParameter.Add("RequestType", "New Entry");
                        lParameter.Add("RequestedBy", actionBy);
                        lParameter.Add("RequestedOn", formatDBDate(Dtime));
                        lParameter.Add("AccountId", accountId);
                        dbx.executeNonQuery(query, lParameter).ToString();

                        //Insert Into Max Reviewed Lavel Table One row for Action Id
                        query = "INSERT INTO tbl_trans_form_max_level_review (`ActionId`, `MaxLevelReviewed`, `TimeStamp`) VALUES (?, ?, ?)";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("ActionId", id);
                        lParameter.Add("MaxLevelReviewed", 0);
                        lParameter.Add("TimeStamp", formatDBDate(Dtime));
                        dbx.executeNonQuery(query, lParameter).ToString();

                        //Send mail for New Induction of Driver and Vehicle
                        //Added By Tushar on 29/08/2021
                        try
                        {
                            //SendMailAddNewChangeRequestICT(RequestType, TypeOfChange, "", ExistingTransporterName, NewTransName, username, accountid, RequestedDate, Status, "", SessionId, RequestedType, RequestedEntryType, DriverTransporterChangeRemarks);
                            //SendMailAddNewChangeRequestICT(keyword, "", VehicleNo, DriverName, DrivingLicenseNumber, actionBy, Convert.ToInt32(accountId), formatDBDate(Dtime), "Pending For Review Level 1", "", "", keyword, "New Entry", "");
                            SendMailForICTNewInduction(keyword, "New Entry", VehicleNo, DriverName, DrivingLicenseNumber, actionBy, Convert.ToInt32(accountId), formatDBDate(Dtime), "Pending For Review Level 1", "");
                        }
                        catch (Exception ex)
                        {

                        }



                        return id;
                    }
                }
                else
                    return 0;
            }
            else
            {
                if (monthYear == "")
                {
                    //string query = "update tbl_trans_form_action t set t.EditId=t.EditId+1,t.ActionTime=? where t.Id=?";
                    string query = "update tbl_trans_form_action t set t.EditId=t.EditId+1 where t.Id=?";
                    var lParameter = new Dictionary<string, object>();
                    //lParameter.Add("ActionTime", formatDBDate(DateTime.Now));
                    lParameter.Add("Id", actionId);
                    int res = Convert.ToInt16(dbx.executeNonQuery(query, lParameter).ToString());
                    if (res == 0)
                        return res;
                    else
                    {
                        query = "select t.EditId from tbl_trans_form_action t where t.Id=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("Id", actionId);
                        int editId = Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString());
                        query = "delete from tbl_trans_form_action_info where ActionId=? and EditId like 'Sub%'";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("ActionId", actionId);
                        dbx.executeNonQuery(query, lParameter).ToString();
                        lParameter = new Dictionary<string, object>();
                        query = "insert into tbl_trans_form_action_info (`ActionId`, `EditId`, `FieldId`, `Value`) values ";
                        foreach (String key in fieldsWithValues.Keys)
                        {
                            if (key.Contains("Sub"))
                            {
                                query += "(?,?,?,?),";
                                lParameter.Add("ActionId" + key, actionId);
                                lParameter.Add("EditId" + key, key.Split('_')[0]);
                                lParameter.Add("FieldId" + key, key.Split('_')[1]);
                                lParameter.Add("Value" + key, Convert2CamelCase(fieldsWithValues[key]));
                            }
                            else
                            {
                                query += "(?,?,?,?),";
                                lParameter.Add("ActionId" + key, actionId);
                                lParameter.Add("EditId" + key, editId);
                                lParameter.Add("FieldId" + key, key);
                                lParameter.Add("Value" + key, Convert2CamelCase(fieldsWithValues[key]));
                            }
                        }
                        query = query.Substring(0, query.Length - 1);
                        dbx.executeNonQuery(query, lParameter);

                        //Update Max Reviewed Lavel Table One row for Action Id
                        query = "UPDATE tbl_trans_form_max_level_review t SET t.MaxLevelReviewed = 0 WHERE t.ActionId = ?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("ActionId", actionId);
                        return dbx.executeNonQuery(query, lParameter);
                    }
                }
                else
                {
                    string query = "delete from tbl_trans_form_action_info where ActionId=? and EditId like concat(?,'-%')";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("ActionId", actionId);
                    lParameter.Add("EditId", monthYear);
                    dbx.executeNonQuery(query, lParameter).ToString();
                    lParameter = new Dictionary<string, object>();
                    query = "insert into tbl_trans_form_action_info (`ActionId`, `EditId`, `FieldId`, `Value`) values ";
                    foreach (String key in fieldsWithValues.Keys)
                    {
                        query += "(?,?,?,?),";
                        lParameter.Add("ActionId" + key, actionId);
                        lParameter.Add("EditId" + key, key.Split('_')[0]);
                        lParameter.Add("FieldId" + key, key.Split('_')[1]);
                        lParameter.Add("Value" + key, Convert2CamelCase(fieldsWithValues[key]));
                    }
                    query = query.Substring(0, query.Length - 1);
                    return dbx.executeNonQuery(query, lParameter);
                }
            }
        }

        public int MultiFormInfoReview(string keyword, int actionId)
        {
            string query = "select * from tbl_trans_form_key_config t where t.KeyWord=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("KeyWord", keyword);
            DataTable approvalDt = dbx.executeQuery(query, lParameter).Tables[0];
            int result = 0;
            if (approvalDt != null && approvalDt.Rows.Count > 0 && !string.IsNullOrEmpty(approvalDt.Rows[0]["ReviewLevels"].ToString()) &&
                Convert.ToInt16(approvalDt.Rows[0]["ReviewLevels"].ToString()) > 0)
            {
                query = "INSERT INTO `tbl_trans_form_review` (`ActionId`) VALUES (?)";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("ActionId", actionId);
                result = dbx.executeNonQuery(query, lParameter);
            }
            return result;
        }

        public DataTable getAgePermitDetails(string key, string login)
        {
            string dt = formatDBDate(DateTime.Now);
            int id = (key == "TotalDriverInfo") ? 3 : 30;
            string query = "select floor(datediff(?,STR_TO_DATE(t2.Value, '%e/%c/%Y %r'))/365) Age from tbl_trans_form_fields t join tbl_trans_form_action t1 on "
                         + "t.KeyWord=t1.KeyWord join tbl_trans_form_action_info t2 on t2.ActionId=t1.Id and t2.EditId=t1.EditId and t2.FieldId=t.Id where t.Id=? and "
                         + "t1.ActionBy=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("dt", dt);
            lParameter.Add("Id", id);
            lParameter.Add("ActionBy", login);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

