        public DataTable GetServiceReminder(string login)
        {
            DataTable Transporter = IsTransporter(login);
            /*string query = "select t.VehicleId,t.VehicleModel,t.Login,t.ServiceId,t1.Name,t.ServiceNo,t.TimeStamp PlannedService,t.Kms,t.Months,t.Days,t3.DateTime "
                         + "ActualService,if(DateDiff(t3.DateTime,t.TimeStamp)<0 or DateDiff(t3.DateTime,t.TimeStamp) is null, 'Not Done','Done') Status,'Log' Action "
                         + "from tbl_trans_form_service_alerts t join tbl_trans_forms_type_config t1 on t.ServiceId=t1.Id left join tbl_trans_vehdriver_followups t3 on "
                         + "t3.TypeId=t.ServiceId and replace(t3.VehicleId,' ','')=t.VehicleId and t3.DateTime=(select max(t4.DateTime) from "
                         + "tbl_trans_vehdriver_followups t4 where replace(t4.VehicleId,' ','')=t.VehicleId and t4.TypeId=t.ServiceId) where "
                         + "t.TimeStamp=(select max(t2.TimeStamp) from tbl_trans_form_service_alerts t2 where t2.VehicleId=t.VehicleId and t2.Login=t.Login and "
                         + "t2.ServiceId=t.ServiceId)"*/
            string query = " SELECT t.VehicleId,t.VehicleModel,t.Login,t.ServiceId,t1.Name,t.ServiceNo,t.TimeStamp AS PlannedService,t.Kms,t.Months,t.Days,t3.DateTime AS ActualService, "
                         + " IF(t3.DateTime IS NULL OR DATEDIFF(t3.DateTime, t.TimeStamp) < 0,'Not Done','Done') AS Status,'Log' AS Action FROM tbl_trans_form_service_alerts t "
                         + " JOIN tbl_trans_forms_type_config t1 ON t.ServiceId = t1.Id LEFT JOIN ( SELECT REPLACE(TRIM(VehicleId),' ','') AS CleanVehicleId, TypeId, "
                         + " MAX(DateTime) AS MaxDate FROM tbl_trans_vehdriver_followups  GROUP BY CleanVehicleId, TypeId ) x ON x.CleanVehicleId = REPLACE(TRIM(t.VehicleId),' ','') AND x.TypeId = t.ServiceId "
                         + " LEFT JOIN tbl_trans_vehdriver_followups t3 ON REPLACE(TRIM(t3.VehicleId),' ','') = x.CleanVehicleId AND t3.TypeId = x.TypeId AND t3.DateTime = x.MaxDate "
                         + " JOIN ( SELECT VehicleId,Login,ServiceId,MAX(TimeStamp) AS MaxTS FROM tbl_trans_form_service_alerts GROUP BY VehicleId, Login, ServiceId "
                         + " ) y ON y.VehicleId = t.VehicleId AND y.Login = t.Login AND y.ServiceId = t.ServiceId AND y.MaxTS = t.TimeStamp WHERE" ;
                         //+ " GROUP BY CONCAT(t.VehicleId, t.Login, t.ServiceId)";
            if (Transporter.Rows.Count > 0)
                query += "  t.Login=?";
            else
                query += "  t.AccountId=(select a.accountid from sessions s,usersgroupsmap u,accountgroups a where s.login=u.Login and a.groupid=u.groupid and s.login=?)";
            query += " group by concat(t.VehicleId,t.Login,t.ServiceId)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Login", login);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

