        public string GetBefNxtWfid(string datetimeval, string Vehicleid, string Type, string selval)
        {
            string query = string.Empty;
            StringBuilder Qry = new StringBuilder();
            var lParameter = new Dictionary<string, object>();

            if (selval == "Next")
            {
                Qry.Append("SELECT MIN(a.DATETIME) FROM vehicledctrip a WHERE a.VehicleID=? and a.DATETIME>");
                if (Type == "0" || Type == "1")
                {
                    Qry.Append("(SELECT MIN(v.DateTime) FROM vehicledctrip v WHERE v.VehicleID=? AND v.DATETIME>=?)");
                }
                else
                {
                    Qry.Append("(SELECT max(v.DateTime) FROM vehicledctrip v WHERE v.VehicleID=? AND v.DATETIME<?)");
                }
            }
            else if (selval == "Before")
            {
                Qry.Append("SELECT MAX(a.TripEndsOn) FROM vehicledctrip a WHERE a.VehicleID=? AND a.DateTime<");
                if (Type == "0" || Type == "1")
                {
                    Qry.Append("(SELECT MIN(v.DateTime) FROM vehicledctrip v WHERE v.VehicleID=? AND v.DATETIME>=?)");
                }
                else
                {
                    Qry.Append("(SELECT max(v.DateTime) FROM vehicledctrip v WHERE v.VehicleID=? AND v.DATETIME<?)");
                }
            }
            lParameter.Add("VehicleID", Vehicleid);
            lParameter.Add("VehicleID2", Vehicleid);
            lParameter.Add("DATETIME", datetimeval);
            return dbx.executeScalar(Qry.ToString(), lParameter).ToString();
        }

        public DataTable GetTripstart_end(string datetimeval, string Vehicleid, string Type)
        {
            if (!string.IsNullOrEmpty(datetimeval))
                datetimeval = formatDBDate(Convert.ToDateTime(datetimeval));

            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            if (Type == "1" || Type == "0")
                Query = "SELECT v.DateTime as 'starttime',v.TripEndsOn as 'endtime' from vehicledctrip v WHERE v.id=(SELECT min(id) FROM vehicledctrip a WHERE a.VehicleID=? AND a.DateTime>?)";
            else
                Query = "SELECT v.DATETIME as 'starttime',v.TripEndsOn as 'endtime' from vehicledctrip v WHERE v.id=(SELECT max(id) FROM vehicledctrip a WHERE a.VehicleID=? AND a.DATETIME<?)";
            //Query = "SELECT max(v.DATETIME) as 'starttime',max(v.TripEndsOn) as 'endtime' from vehicledctrip v WHERE v.VehicleID=? AND v.DATETIME<?";
            lParameter.Add("VehicleID", Vehicleid);
            lParameter.Add("DATETIME", datetimeval);
            return dbx.executeQuery(Query, lParameter).Tables[0];
        }

