        public int insertMobVehGps(string source, string sourceId, string dateTime, string mobileLat, string mobileLng, string vehicleId, string vehicleLat, string vehicleLng,
            string vehLastUpdt, string status, string remarks)
        {
            string query = "INSERT INTO `mobile_vehicle_gps` (`Source`, `SourceId`, `DateTime`, `MobileLat`, `MobileLng`,VehicleId, `VehicleLat`, `VehicleLng`, "
                             + "`VehLastUpdt`, `Status`, `Remarks`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Source", source);
            lParameter.Add("SourceId", sourceId);
            lParameter.Add("DateTime", formatDBDate(Convert.ToDateTime(dateTime)));
            lParameter.Add("MobileLat", mobileLat);
            lParameter.Add("MobileLng", mobileLng);
            lParameter.Add("VehicleId", vehicleId);
            lParameter.Add("VehicleLat", vehicleLat);
            lParameter.Add("VehicleLng", vehicleLng);
            lParameter.Add("VehLastUpdt", formatDBDate(Convert.ToDateTime(vehLastUpdt)));
            lParameter.Add("Status", status);
            lParameter.Add("Remarks", remarks);
            int res = dbx.executeNonQuery(query, lParameter);
            if (res > 0)
            {
                query = "select m.Id from mobile_vehicle_gps m where m.Source=? and m.SourceId=? and m.DateTime=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Source", source);
                lParameter.Add("SourceId", sourceId);
                lParameter.Add("DateTime", formatDBDate(Convert.ToDateTime(dateTime)));
                return Convert.ToInt32(dbx.executeScalar(query, lParameter).ToString());
            }
            else
                return res;
        }
