        public DataTable GetVehicleGroups(string login, string type)
        {
            string query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            int groupid = getGroupIdByLogin(login);
            int accountid = GetAccountIdByGroupId(groupid);
            if (type == "custom")
            {
                query = "select c.GroupName,group_concat(cv.VehicleId) as vehList from cvg_custvehgroups c join cvg_vehiclemapping cv on cv.CustGroupId=c.Id where "
                      + "c.Login=? group by c.GroupName";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Login", login);
                return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            else if (type == "transporter")
            {
                string accountName = GetAccountNamebyID(accountid.ToString());
                if (accountName.Contains("Shell India"))
                {
                    query = "select IFNULL(t.ShortName,t.Name) GroupName,group_concat(v.VehicleId) vehList from transporterinfo t join vehicleinfo v on v.Transporter = "
                          + "t.TransporterId where t.AccountId = ? and v.VehicleId in (select vehicleid from vehiclesgroupsmap where groupid = ?) group by t.TransporterId";
                }
                else
                {
                    query = "select IFNULL(t.ShortName,t.Name) GroupName,group_concat(v.VehicleId) vehList from transporterinfo t join usersgroupsmap u on u.Login "
                          + "= t.login join vehiclesgroupsmap v on v.GroupId = u.GroupId where t.AccountId = ? and v.VehicleId in (select vehicleid from "
                          + "vehiclesgroupsmap where groupid = ?) group by t.TransporterId";
                }
                lParameter = new Dictionary<string, object>();
                lParameter.Add("AccountId", accountid);
                lParameter.Add("groupid", groupid);
                return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            else if (type == "category")
            {
                query = "select v.Category GroupName,group_concat(v.VehicleId) vehList from vehiclecategory v where v.VehicleId in (select vehicleid from "
                      + "vehiclesgroupsmap where groupid = ?) group by v.Category";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("groupid", groupid);
                return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            else
                return null;
        }

        public DataTable GetVehicleGroupsByType(string login, string vehList, string type)
        {
            string query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            if (type == "add")
            {
                String[] vals = vehList.Replace("'", "").Replace("\"", "").Split(',');
                string inparam = "";
                for (int i = 0; i < vals.Length; i++)
                {
                    if (i == 0)
                        inparam += ("?");
                    else
                        inparam += (",?");
                }
                query = "select c.Id CustGroupId,c.GroupName from cvg_custvehgroups c where c.Login=? and c.Id not in (select c.CustGroupId from cvg_vehiclemapping c "
                      + "join cvg_custvehgroups c1 on c.CustGroupId=c1.Id where c.VehicleId in (" + inparam + ") and c1.Login=? group by c.CustGroupId having count(*)=?)";
                lParameter.Add("Login", login);
                for (int i = 0; i < vals.Length; i++)
                {
                    lParameter.Add("val" + i, vals[i]);
                }
                lParameter.Add("Login1", login);
                lParameter.Add("count", vehList.Split(',').Length);
            }
            else if (type == "remove")
            {
                String[] vals = vehList.Replace("'", "").Replace("\"", "").Split(',');
                string inparam = "";
                for (int i = 0; i < vals.Length; i++)
                {
                    if (i == 0)
                        inparam += ("?");
                    else
                        inparam += (",?");
                    lParameter.Add("val" + i, vals[i]);
                }
                query = "select c.CustGroupId,c1.GroupName from cvg_vehiclemapping c join cvg_custvehgroups c1 on c.CustGroupId=c1.Id where c.VehicleId in ("
                             + inparam + ") and c1.Login=? group by c.CustGroupId having count(*)=?";
                lParameter.Add("Login", login);
                lParameter.Add("count", vehList.Split(',').Length);
            }
            else
            {
                query = "select c.Id CustGroupId,c.GroupName from cvg_custvehgroups c where c.Login=?";
                lParameter.Add("Login", login);
            }
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }

        public string AssigningVeh2Groups(string vehlist, string groups, string type, string login)
        {
            string[] strGroups = groups.Split(',');
            string[] strVehList = vehlist.Split(',');
            string query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            string res = "0";
            if (type == "create")
            {
                query = "select count(*) from cvg_custvehgroups c where c.GroupName=? and c.Login=?";
                lParameter.Add("GroupName", groups);
                lParameter.Add("login", login);
                res = dbx.executeScalar(query, lParameter).ToString();
                if (Convert.ToInt32(res) > 0)
                {
                    return "Group Name already exists";
                }
                else
                {
                    query = "INSERT INTO `cvg_custvehgroups` (`GroupName`, `Login`) VALUES (?, ?);";
                    res = dbx.executeNonQuery(query, lParameter).ToString();
                    if (res == "1")
                    {
                        query = "select c.Id from cvg_custvehgroups c where c.GroupName=? and c.Login=?";
                        res = dbx.executeScalar(query, lParameter).ToString();
                        return AssigningVeh2Groups(vehlist, res, "add", login);
                    }
                    else
                        return "Unable to create new group name";
                }
            }
            else if (type == "delete")
            {
                query = "delete from cvg_vehiclemapping where CustGroupId in (" + groups + ")";
                res = dbx.executeNonQuery(query).ToString();
                query = "delete from cvg_custvehgroups where Id in (" + groups + ")";
                res = dbx.executeNonQuery(query).ToString();
            }
            else if (type == "add" || type == "remove")
            {
                query = "delete from cvg_vehiclemapping where CustGroupId in (" + groups + ") and VehicleId in (" + vehlist + ")";
                res = dbx.executeNonQuery(query).ToString();
                if (type == "add")
                {
                    query = "INSERT INTO `cvg_vehiclemapping` (`CustGroupId`, `VehicleId`) VALUES ";
                    for (int i = 0; i < strGroups.Length; i++)
                    {
                        for (int j = 0; j < strVehList.Length; j++)
                        {
                            query += "(?,?)";
                            lParameter.Add("groupId_" + i + "_" + j, strGroups[i]);
                            lParameter.Add("vehId_" + i + "_" + j, strVehList[j].Substring(1, strVehList[j].Length - 2));
                            if (!(i == strGroups.Length - 1 && j == strVehList.Length - 1))
                                query += ",";
                        }
                    }
                    res = dbx.executeNonQuery(query, lParameter).ToString();
                }
            }
            if (Convert.ToInt32(res) > 0)
                return "Updated Successfully";
            else
                return "Unable to update. Please try again";
        }

