        public string CheckRebootByTime(string vehicle, string datetime)
        {
            string temp = partions[Convert.ToDateTime(datetime).Month - 1];
            string query = "select p.TimeStamp from positiondata PARTITION(" + temp + ") p where p.TruckID=? and p.TimeStamp>=? and p.TimeStamp<=? and p.`Start`=1 limit 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TruckID", vehicle);
            lParameter.Add("TimeStamp", formatDBDate(Convert.ToDateTime(datetime).AddMinutes(-5)));
            lParameter.Add("TimeStamp1", formatDBDate(Convert.ToDateTime(datetime).AddMinutes(5)));
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            if (dt == null || dt.Rows.Count == 0)
                return "";
            else
                return formatDBDate(Convert.ToDateTime(dt.Rows[0]["TimeStamp"].ToString()));
        }

