        public DataTable GetLastGapForVehicleByTime(string vehicle, string datetime)
        {
            string temp = partions[Convert.ToDateTime(datetime).Month - 1];
            string query = "select timestamp,prevDate,timediff(timestamp,prevDate) from (select *, @prevDate prevDate, @prevDate := timestamp from positiondata "
                         + "partition(" + temp + ") p where TruckID=? and timestamp<=? order by timestamp desc limit 50) t1 where t1.timestamp!=? and "
                         + "(hour(timediff(t1.timestamp,t1.prevDate))>0 or (hour(timediff(t1.timestamp,t1.prevDate))=0 and minute(timediff(t1.timestamp,t1.prevDate))>=5))";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TruckID", vehicle);
            lParameter.Add("timestamp", formatDBDate(Convert.ToDateTime(datetime)));
            lParameter.Add("timestamp1", formatDBDate(Convert.ToDateTime(datetime)));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

