        public DataTable getEightEventReport(string vehicleId, string fromDateStr, string toDateStr, int groupId)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select s.vehicleId,s.driverName,t.Name,s.`type`,if(s.`type`='OVERSPEEDING',ifnull(p.maxSpeed,pv.maxSpeed), ");
            query.Append("if(s.`type`='JRM OVERSPEEDING',SUBSTRING_INDEX(s.Location,'-',-1),if(s.`type`='HARSH BRAKING',u.ACLHBTH3, ");
            query.Append("if(s.`type`='HIGH ACCELERATION',u.ACLHATH3,if(s.`type`='HARSH CORNERING','',if(s.`type`='FREEWHEELING', ");
            query.Append("ifnull(p.FreewheelingTime,pv.FreewheelingTime),if(s.`type`='EXCESSIVE RPM',ifnull(p.ExcessiveRPM,pv.ExcessiveRPM), ");
            query.Append("if(s.`type`='EXCESSIVE IDLE',ifnull(p.ExcessiveIdle,pv.ExcessiveIdle),'')))))))) Limits,pd.CI,pd.Speed, ");
            query.Append("if(s.`type`='HARSH BRAKING' OR s.`type`='HIGH ACCELERATION' OR s.`type`='HARSH CORNERING',IF(s.duration=0,round((s.maxsamplesval*127094.18)/3600,2),s.duration),'') as event_value, ");
            query.Append("s.timestamp starttime,if(s.`type`='EXCESSIVE IDLE', (s.timestamp+interval s.duration minute),(s.timestamp+interval if(s.duration=0,1,s.duration) second)) endtime, ");
            query.Append(" if(s.`type`='EXCESSIVE IDLE', sec_to_time(s.duration*60),sec_to_time(if(s.duration=0,1,s.duration))) duration,s.Location,s.latitude,s.longitude from storevehicleviolations s ");
            query.Append("left join vehicleinfo v on s.vehicleId=v.VehicleId ");
            query.Append("left join transporterinfo t on t.TransporterId=v.Transporter ");
            query.Append("left join vehicletripparams_vehwise p on p.VehicleId=v.VehicleId ");
            query.Append("left join vehicletripparams pv on pv.groupId=? ");
            query.Append("left join positiondata pd on pd.TruckID=v.VehicleId and pd.TimeStamp=s.timestamp ");
            query.Append("left join driverinfo d on d.Name=s.driverName ");
            query.Append("left join unitconfigparams u on u.VehicleId=s.vehicleId ");
            query.Append("where s.`type` in ('OVERSPEEDING','JRM OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','HARSH CORNERING','FREEWHEELING','EXCESSIVE RPM','EXCESSIVE IDLE') and");
            query.Append(" s.vehicleId=? and s.timestamp>? and s.timestamp<?;");

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("groupId", groupId);
            lParameter.Add("VehicleId", vehicleId);
            lParameter.Add("StartTime", fromDateStr);
            lParameter.Add("EndTime", toDateStr);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }

