        /// <summary>
        /// Created by vamsi krishna on 2020-09-12
        /// </summary>
        /// <param name="invoices">selected invoices for auto routing</param>
        /// <param name="username">selected store username</param>
        /// <returns>All customer address under the selected store</returns>
        public DataTable GetCustomerAddresses(DataTable invoices, string username)
        {
            var lParameter = new Dictionary<string, object>();
            string inQuery = "";
            for (int i = 0; i < invoices.Rows.Count; i++)
            {
                if (inQuery != "")
                    inQuery += ",";
                inQuery += "?";
                lParameter.Add("customer_" + i, invoices.Rows[i]["CustomerId"].ToString());
            }
            string query = "select a.CustomerId,a.AddressId,a.Address from metro_customer_address a join metro_stores_info s on s.StoreNo=a.StoreNo where a.CustomerId "
                + "in (" + inQuery + ") and a.Latitude!=0 and a.Longitude!=0 and a.Address!='null' and a.Address!='' and a.Address is not null and s.Login=?";
            lParameter.Add("Login", username);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetMetroInvoicesList(string username, int noOfDays, string transporterId, string custType, string payType, string zone, string routingFor)
        {
            string query = "select i.CustomerId,i.AddressId,i.TaxInvoiceNum,if(i.TotalWeight<1 or i.TotalWeight is null,1,i.TotalWeight) TotalWeight,"
                + "if(i.TotalVolume<1 or i.TotalVolume is null,1,i.TotalVolume) TotalVolume,i.OrderDateTime,"
                + "c.CustomerName,c.custType,group_concat(distinct concat(a.AddressId,'@&@',a.Address,'&@&')) AddressIds,i.TransporterId,if(a.Pincode is null,'Non Zone',"
                + "ifnull(z.ZoneName,'Non Zone')) ZoneName,i.InvoiceType from metro_invoice_details i join metro_stores_info s on s.StoreNo = i.StoreNo join metro_customers_info c "
                + "on c.CustomerId = i.CustomerId and c.StoreNo= i.StoreNo join metro_customer_address a on a.CustomerId=i.CustomerId and a.StoreNo=s.StoreNo and "
                + "a.Latitude!=0 and a.Longitude!=0 and a.Address!='null' and a.Address!='' and a.Address is not null";
            if (zone != "All")
            {
                query += " and a.AddressId=i.AddressId";
            }
            query += " left join metro_zones z on z.StoreNo=i.StoreNo and z.Pincode=a.Pincode where "
                + "s.Login = ? and i.IsDeleted = 0 and i.OrderDateTime >= ? and i.TripId=0 ";
            if (transporterId != "All")
                query += "and i.TransporterId='" + transporterId + "' ";
            if (custType == "HoReCa")
                query += "and c.custType='HoReCa' ";
            else if (custType == "Non HoReCa")
                query += "and c.custType!='HoReCa' ";
            if (payType == "COD")
                query += "and i.PaymentType='POD' ";
            else if (payType == "Prepaid")
                query += "and (i.PaymentType!='POD' or i.PaymentType is null) ";
            if (routingFor == "Return")
                query += "and i.InvoiceType='Return' ";
            else if (routingFor == "Delivery")
                query += "and (i.InvoiceType!='Return' or i.InvoiceType is null) ";
            query += "group by i.TaxInvoiceNum";
            query += " union ";
            query += "select 0,m.Login,'Source',0,0,'0000-00-00',m.StoreName,'',concat(m.Login,'@&@',m.StoreAddress,'&@&'),0,'','Source' from metro_stores_info m where m.Login=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Login", username);
            lParameter.Add("OrderDateTime", formatDBDate(Convert.ToDateTime(DateTime.Now.ToShortDateString()).AddDays(-(noOfDays))));
            lParameter.Add("Login1", username);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

