        public DataTable GetMetroTripDistanceAndCapacity(string username, DateTime startTime, DateTime endTime, string type)
        {
            string query = "SELECT s.StoreNo,SUM(s.Distance) as `TotalDistance`,SUM(m.Capacity) as `TotalCapacity` FROM metro_trip_details s " +
                "INNER JOIN metro_market_vehicles m ON m.VehicleId = s.VehicleId AND m.StoreNo = s.StoreNo " +
                "WHERE s.TripDate between ? and ? ";

            if (type == "Auto")
            {
                query += "AND s.IsByMetro = 2";
            }
            query += " AND m.Active = 1 GROUP BY s.StoreNo ORDER BY s.StoreNo";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("startTime", formatDBDate(startTime));
            lParameter.Add("endTime", formatDBDate(endTime));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetMetroVehicleType(string username, DateTime TripDate, string VehicleType, string type)
        {
            string query = "SELECT mtd.StoreNo,COUNT(mtd.TripNum),COUNT(distinct mtd.VehicleId) as 'VehicleType', SUM(mtd.Distance) AS'EstimatedDistance' FROM metro_trip_details mtd WHERE date(mtd.TripDate) = ? ";
            if (type == "Auto")
            {
                query += "AND mtd.IsByMetro = 2";
            }
            query += " AND mtd.IsDeleted = 0 AND mtd.VehicleId IN " +
                "(SELECT distinct mmv.VehicleId FROM metro_market_vehicles mmv WHERE mmv.Active = 1 AND mmv.VehicleType = ?) GROUP BY mtd.StoreNo";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TripDate", formatDBDate(TripDate));
            lParameter.Add("VehicleType", VehicleType);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetMetroVehiclesByStore(string username)
        {
            string query = "SELECT m.StoreNo,COUNT(distinct m.VehicleId) as 'NoOfDedicatedVehicles' FROM metro_market_vehicles m WHERE m.VehicleType ='Dedicated' AND m.Active = 1 GROUP BY m.StoreNo ORDER BY m.StoreNo";
            return dbx.executeQuery(query).Tables[0];
        }

        public DataTable GetMetroVehicleActualDistanceByStoreNo(string username, DateTime TripDate)
