        //Added by Madhuri-27-06-2020 for metro trip reports by storeno
        public DataTable GetMetroTripSummaryReportByStoreNo(string username, DateTime startTime, DateTime endTime)
        {
            int storeNo = Convert.ToInt32(getMetroStoreNo(username));
            string query = "SELECT s.StoreNo,s.StoreName,DATE_FORMAT(s.Date, '%d/%m/%Y') as `Date`,s.NoOfTrips as `No Of Trips`,s.NoOfVehicles as `No Of Vehicles`,s.NoOfDedicatedVehicles as `No Of Dedicated Vehicles`,ROUND((s.NoOfTrips/s.NoOfVehicles),2) AS `Vehicle Productivity`,s.DriverAppUsage as 'App Usage',concat(ROUND((s.DriverAppUsage/s.NoOfTrips * 100 ),2),'%') AS `App Usage Percentage`,s.NoOfInvoices as `No Of Invoices`,s.NoOfCustomers as `No Of Customers`,s.InvoicesDelivered as `No Of LatLong Captured`,concat(ROUND((s.InvoicesDelivered/s.NoOfInvoices * 100 ),2),'%') AS `LatLong Captured Percentage` FROM metro_auto_trip_summary s WHERE s.Date between ? and ? and s.StoreNo=? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("startTime", formatDBDate(startTime.Date));
            lParameter.Add("endTime", formatDBDate(endTime.Date));
            lParameter.Add("StoreNo", storeNo);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable GetMetroTripDetailsReportByStoreNo(string username, DateTime startTime, DateTime endTime)
        {
            int storeNo = Convert.ToInt32(getMetroStoreNo(username));
            string query = "SELECT mtd.StoreNo,mtd.TripNum as 'Trip Number',mtd.TripDate as 'Trip Date',mtd.VehicleId as 'Vehicle',mtd.Trip_Status as 'Trip Status',mtd.Trip_Closed_By  as `Trip Closed By`," +
                "mtd.Trip_Closed_On as `Trip Closed On`,mid.CustomerId as 'Customer ID',mci.CustomerName,mca.Address as 'Address',mca.Latitude,mca.Longitude,mid.TaxInvoiceNum,mid.OrderDateTime,IFNULL(mid.Delivery_Status,'Pending') as 'Delivery Status'" +
                ",IF(mid.IsVerified = 1, 'Done', 'Not Done') AS 'Customer Acknowledgement',IFNULL(mid.Delivery_Status_Updated_On, '') as `Delivered On` from metro_trip_details mtd " +
                "inner join metro_invoice_details mid on mtd.Id = mid.TripId inner join metro_customer_address mca on mid.AddressId = mca.AddressId " +
                "inner join metro_customers_info mci on mid.CustomerId = mci.CustomerId and mid.StoreNo = mci.StoreNo where mtd.TripDate BETWEEN ? and ? AND mtd.IsByMetro = 2 AND mtd.IsDeleted = 0 AND mtd.StoreNo=? ORDER BY mtd.StoreNo,mtd.TripNum";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("startTime", formatDBDate(startTime));
            lParameter.Add("endTime", formatDBDate(endTime));
            lParameter.Add("StoreNo", storeNo);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
