        public DataTable GetMetroTripSummary(string username, DateTime startTime, DateTime endTime)
        {
            string query = "SELECT mtd.StoreNo,msi.StoreName,DATE_FORMAT(mtd.TripDate, '%d/%m/%Y') as `Date`,count(distinct mtd.Id) as `No Of Trips`, count(distinct mtd.VehicleId) as `No Of Vehicles`," +
                "count(distinct mtd.Trip_Status_Updated_On) as 'App Usage',concat(round(( count(distinct mtd.Trip_Status_Updated_On)/count(distinct mtd.TripNum) * 100 ),2),'%') AS `App Usage Percentage`," +
                "count(DISTINCT mid.TaxInvoiceNum) as `No Of Invoices`,count(distinct concat(mid.CustomerId,'-',mid.TripId)) as `No Of Customers`,count(mid.DriverId) as `No Of LatLong Captured` ," +
                "concat(round((count(mid.DriverId)/count(distinct mid.TaxInvoiceNum) * 100 ),2),'%') AS `LatLong Captured Percentage`,SUM(mid.TotalWeight) AS `TotalWeight`" +
                " FROM metro_trip_details mtd " +
                "INNER JOIN metro_stores_info msi on msi.StoreNo = mtd.StoreNo " +
                "INNER JOIN metro_invoice_details mid on mid.TripId = mtd.Id " +
                "WHERE mtd.TripDate between ? and ? AND mtd.IsDeleted = 0 " +
                "AND mtd.IsByMetro = 2 GROUP BY mtd.StoreNo ORDER BY mtd.StoreNo";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("startTime", formatDBDate(startTime));
            lParameter.Add("endTime", formatDBDate(endTime));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

