        public DataTable GetMetroTripDetailsReport(string username, DateTime startTime, DateTime endTime)
        {
            string query = "SELECT mtd.StoreNo,mtd.TripNum as 'Trip Number',DATE_FORMAT(mtd.TripDate,'%d-%m-%Y %H:%i:%s') as 'Trip Date',mtd.PaymentType AS 'Payment Type',mtd.VehicleId as 'Vehicle',mtd.Trip_Status as 'Trip Status',mtd.Trip_Closed_By  as `Trip Closed By`," +
                "DATE_FORMAT(mtd.Trip_Closed_On,'%d-%m-%Y %H:%i:%s') as `Trip Closed On`,mid.CustomerId as 'Customer ID',mci.CustomerName,mca.Address as 'Address',mca.Latitude,mca.Longitude,mid.TaxInvoiceNum,DATE_FORMAT(mid.OrderDateTime,'%d-%m-%Y %H:%i:%s') AS 'OrderDateTime',mid.TotalPrice,IFNULL(mid.Delivery_Status,'Pending') as 'Delivery Status'" +
                ",IF(mid.IsVerified = 1, 'Done', 'Not Done') AS 'Customer Acknowledgement',IFNULL(DATE_FORMAT(mid.Delivery_Status_Updated_On,'%d-%m-%Y %H:%i:%s'), '') as `Delivered On` from metro_trip_details mtd " +
                "inner join metro_invoice_details mid on mtd.Id = mid.TripId inner join metro_customer_address mca on mid.AddressId = mca.AddressId " +
                "inner join metro_customers_info mci on mid.CustomerId = mci.CustomerId and mid.StoreNo = mci.StoreNo where mtd.TripDate BETWEEN ? and ? AND mtd.IsByMetro = 2 AND mtd.IsDeleted = 0 ORDER BY mtd.StoreNo,mtd.TripNum";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("startTime", formatDBDate(startTime));
            lParameter.Add("endTime", formatDBDate(endTime));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

