                "count(DISTINCT mid.TaxInvoiceNum) as `No Of Invoices`,count(distinct mid.CustomerId) as `No Of Customers`,count(mid.DriverId) as `No Of LatLong Captured` ," +
                "concat(round((count(mid.DriverId)/count(distinct mid.TaxInvoiceNum) * 100 ),2),'%') AS `LatLong Captured Percentage`,SUM(mid.TotalWeight) AS `TotalWeight`" +
                " FROM metro_trip_details mtd " +
                "INNER JOIN metro_stores_info msi on msi.StoreNo = mtd.StoreNo " +
                "INNER JOIN metro_invoice_details mid on mid.TripId = mtd.Id " +
                "WHERE mtd.TripDate between ? and ? AND mtd.IsDeleted = 0 " +
                "GROUP BY mtd.StoreNo ORDER BY mtd.StoreNo";
