        {
            string query = "SELECT mtd.StoreNo,mtd.TripNum as 'Trip Number',mtd.TripDate as 'Trip Date',mtd.VehicleId as 'Vehicle',mtd.Trip_Status as 'Trip Status',mtd.Trip_Closed_By  as `Trip Closed By`," +
                "mtd.Trip_Closed_On as `Trip Closed On`,mid.CustomerId as 'Customer ID',mci.CustomerName,mca.Address as 'Address',mca.Latitude,mca.Longitude,mid.TaxInvoiceNum,mid.OrderDateTime,IFNULL(mid.Delivery_Status,'Pending') as 'Delivery Status'" +
                ",IF(mid.IsVerified = 1, 'Done', 'Not Done') AS 'Customer Acknowledgement',IFNULL(mid.Delivery_Status_Updated_On, '') as `Delivered On` from metro_trip_details mtd " +
                "inner join metro_invoice_details mid on mtd.Id = mid.TripId inner join metro_customer_address mca on mid.AddressId = mca.AddressId " +
                "inner join metro_customers_info mci on mid.CustomerId = mci.CustomerId and mid.StoreNo = mci.StoreNo where mtd.TripDate BETWEEN ? and ? AND mtd.IsDeleted = 0 ORDER BY mtd.StoreNo,mtd.TripNum";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("startTime", formatDBDate(startTime));
            lParameter.Add("endTime", formatDBDate(endTime));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public int InsertMetroTripSummary(string StoreNo, string StoreName, DateTime date, string NoOfTrips, string NoOfVehicles, string DriverAppUsage, string NoOfInvoices, string NoOfCustomers, string CustomerOTPVerified, string InvoicesDelivered, decimal TotalWeight, decimal TotalDistance, decimal dedicatedVehicleDistance, decimal TotalCapacity, string NoOfDedicatedVehicles, string type)
        {
            int num = 0;
            string tableName = "metro_trip_summary";
            if (type == "Auto")
            {
                tableName = "metro_auto_trip_summary";
            }

            string query = "INSERT INTO `" + tableName + "` (`StoreNo`, `StoreName`, `Date`, `NoOfTrips`, `NoOfVehicles`, `NoOfDedicatedVehicles`, `DriverAppUsage`, `NoOfInvoices`, `NoOfCustomers`, `CustomerOTPVerified`, `InvoicesDelivered`, `TotalWeight`, `EstimatedDistance`, `DedicatedVehDistance`, `TotalVehicleCapacity`) " +
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("StoreNo", StoreNo);
            lParameter.Add("StoreName", StoreName);
            lParameter.Add("Date", formatDBDate(date));
            lParameter.Add("NoOfTrips", NoOfTrips);
            lParameter.Add("NoOfVehicles", NoOfVehicles);
            lParameter.Add("NoOfDedicatedVehicles", NoOfDedicatedVehicles);
            lParameter.Add("DriverAppUsage", DriverAppUsage);
            lParameter.Add("NoOfInvoices", NoOfInvoices);
            lParameter.Add("NoOfCustomers", NoOfCustomers);
            lParameter.Add("CustomerOTPVerified", CustomerOTPVerified);
            lParameter.Add("InvoicesDelivered", InvoicesDelivered);
            lParameter.Add("TotalWeight", TotalWeight);
            lParameter.Add("EstimatedDistance", TotalDistance);
            lParameter.Add("DedicatedVehDistance", dedicatedVehicleDistance);
            lParameter.Add("TotalVehicleCapacity", TotalCapacity);
            num = dbx.executeNonQuery(query, lParameter);
            return num;
