            lParameter.Add("StoreNo", StoreNo);
            lParameter.Add("TripSheetNo", TripSheetNo);
            lParameter.Add("TaxInvoiceNo", TaxInvoiceNo);
            lParameter.Add("OrderDateTime", formatDBDate(OrderDateTime));
            lParameter.Add("Status", Status);
            lParameter.Add("Reason", Reason);
            lParameter.Add("Delivery_Status_Updated_On", formatDBDate(Delivery_Status_Updated_On));
            lParameter.Add("LatLong", Latlng);
            lParameter.Add("DriverId", DriverId);
            num = dbx.executeNonQuery(query, lParameter);

            if (Status == "Cancelled")
            {
                if (num != 0)
                {
                    query = "update metro_invoice_details set TripId=?,TripSheetNo=?,Delivery_Status=?,Delivery_Status_Updated_On=?,Reason=?,latlng=? where TaxInvoiceNum=?";
