                    lParameter.Add("TripSheetNo", "");
                    lParameter.Add("Delivery_Status", "Pending");
                    lParameter.Add("Delivery_Status_Updated_On", "");
                    lParameter.Add("Reason", "");
                    lParameter.Add("latlng", "");
                    lParameter.Add("TaxInvoiceNo", TaxInvoiceNo);
                    dbx.executeNonQuery(query, lParameter).ToString();
                }
            }
            return num;
        }

