        public DataTable GetMetroTripUtilization(string username, DateTime startTime, DateTime endTime)
        {
            string query = "SELECT t.StoreNo,t.StoreName,DATE_FORMAT(t.Date, '%d/%m/%Y') AS `Report Date`,t.NoOfTrips AS `No Of Auto Trips`,t.NoOfVehicles AS `No Of Vehicles`,t.NoOfDedicatedVehicles AS `No Of Dedicated Vehicles`,t.TotalWeight,(t.TotalVehicleCapacity*1000) AS `Vehicle Capacity in Kg`," +
                "round((t.TotalWeight / t.NoOfTrips), 2) AS `Avg.Trip Utlization`, concat(ROUND((t.TotalWeight / (t.TotalVehicleCapacity * 1000) * 100), 2), '%') AS `Vehicle Utlization Percentage`,t.DedicatedVehDistance AS `EstimatedDistance`,t.ActualDistance " +
                "FROM metro_auto_trip_summary t WHERE t.Date BETWEEN ? AND ? ORDER BY t.StoreNo";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Date1", formatDBDate(startTime.Date));
            lParameter.Add("Date2", formatDBDate(endTime.Date));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

