        public DataTable GetMetroInvoiceDetailsByTaxInvoice(string sessionId, string taxInvoiceNumber)
        {
            string username = getUserId(sessionId);
            int accountId = GetAccountId(sessionId);
            int storeNo = Convert.ToInt32(getMetroStoreNo(username));
            string query = "SELECT CONCAT(m.CustomerId,'-',i.CustomerName) AS CustomerName, CONCAT(a.Address, ' (', a.Latitude, ' , ', a.Longitude, ')') AS CustomerAddress,DATE_FORMAT(m.OrderDateTime,'%d/%m/%Y  %h:%m:%s %p') AS OrderDateTime,IFNULL(m.PaymentType, 'NON-POD') as PaymentType, CAST(m.TotalWeight as decimal(10,2)) as 'TotalWeight', m.IsVerified,m.InvoiceType,m.OrderType,m.PaymentMethod,m.PaymentStatus,DATE_FORMAT(m.PaymentOn,'%d/%m/%Y  %h:%m:%s %p') AS PaymentOn,m.ConsignmentId,DATE_FORMAT(AddTime(m.ServerTs, '05:30:00'), '%d/%m/%Y %h:%m:%s %p') AS 'ServerTs',m.TripSheetNo,m.TripId, IFNULL(m.Delivery_Status, 'Pending') as Delivery_Status,CAST(m.TotalPrice as decimal(10,2)) AS Totalprice,m.DeliveryCharge,coalesce(COUNT(p.ProductId),0) as TotalProducts " +
                "FROM metro_invoice_details m " +
                "INNER JOIN metro_customers_info i ON i.CustomerId = m.CustomerId AND i.StoreNo = m.StoreNo " +
                "INNER JOIN metro_customer_address a ON a.AddressId = m.AddressId " +
                "LEFT JOIN metro_invoice_products p ON p.InvoiceId = m.TaxInvoiceNum " +
                "WHERE m.TaxInvoiceNum = ? AND m.StoreNo = ? GROUP BY m.TaxInvoiceNum";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TaxInvoiceNum", taxInvoiceNumber);
            lParameter.Add("StoreNo", storeNo);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

