        public int InsertInvoiceDeselectReason(Dictionary<string, string> InvoiceDeselectReasons, string login)
        {
            DateTime nowDt = DateTime.Now;
            string query = "INSERT INTO `metro_invoice_deselect_reason` (`TaxInvoiceNum`, `Reason`, `DateTime`, `Login`) VALUES ";
            var lParameter = new Dictionary<string, object>();
            bool valuesExists = false;
            foreach (var item in InvoiceDeselectReasons)
            {
                valuesExists = true;
                query += "(?, ?, ?, ?),";
                lParameter.Add("TaxInvoiceNum_" + item.Key, item.Key);
                lParameter.Add("Reason_" + item.Key, item.Value);
                lParameter.Add("DateTime_" + item.Key, formatDBDate(nowDt));
                lParameter.Add("Login_" + item.Key, login);
            }
            if (valuesExists)
                return dbx.executeNonQuery(query.Substring(0, query.Length - 1), lParameter);
            else
                return 0;
        }

