        public int insertDistanceMatrixForCustomers(List<string> ids, long[,] distMat, string source)
        {
            int result = 0;
            if (ids.Count > 0)
            {
                string inQuery = "";
                var lParameter = new Dictionary<string, object>();
                for (int i = 0; i < ids.Count; i++)
                {
                    if (i != 0)
                        inQuery += ",";
                    inQuery += "?";
                    lParameter.Add("FromCustId_" + i, ids[i]);
                }
                for (int i = 0; i < ids.Count; i++)
                {
                    lParameter.Add("ToCustId_" + i, ids[i]);
                }
                string query = "delete from customerdistancematrix where FromCustId in (" + inQuery + ") and ToCustId in (" + inQuery + ") and Source=?";
                lParameter.Add("Source", source);
                result = dbx.executeNonQuery(query, lParameter);
                query = "INSERT INTO `customerdistancematrix` (`FromCustId`, `ToCustId`, `Distance`, `Source`) VALUES ";
                lParameter = new Dictionary<string, object>();
                for (int i = 0; i < distMat.GetLength(0); i++)
                {
                    for (int j = 0; j < distMat.GetLength(1); j++)
                    {
                        if (i != 0 || j != 0)
                            query += ",";
                        query += "(?, ?, ?, ?)";
                        lParameter.Add("FromCustId" + "_" + i + "_" + j, ids[i]);
                        lParameter.Add("ToCustId" + "_" + i + "_" + j, ids[j]);
                        lParameter.Add("Distance" + "_" + i + "_" + j, distMat[i, j]);
                        lParameter.Add("Source" + "_" + i + "_" + j, source);
                    }
                }
                result = dbx.executeNonQuery(query, lParameter);
            }
            return result;
        }

