        public int insertDistanceMatrixForCustomers(List<string> ids, long[] distMat, string source)
        {
            int result = 0;
            if (ids.Count > 0)
            {
                string inQuery = "";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("FromCustId", ids[0]);
                for (int i = 0; i < ids.Count; i++)
                {
                    if (i != 0)
                        inQuery += ",";
                    inQuery += "?";
                    lParameter.Add("ToCustId_" + i, ids[i]);
                }
                string query = "select ID from customerdistancematrix where FromCustId = ? and ToCustId in (" + inQuery + ") and Source=?";
                lParameter.Add("Source", source);
                DataTable idDt = dbx.executeQuery(query, lParameter).Tables[0];
                if (idDt != null && idDt.Rows.Count > 0)
                {
                    inQuery = "";
                    lParameter = new Dictionary<string, object>();
                    for (int i = 0; i < idDt.Rows.Count; i++)
                    {
                        if (i != 0)
                            inQuery += ",";
                        inQuery += "?";
                        lParameter.Add("ID_" + i, idDt.Rows[i]["ID"].ToString());
                    }
                    query = "Delete from customerdistancematrix where ID in (" + inQuery + ")";
                    result = dbx.executeNonQuery(query, lParameter);
                }
                query = "INSERT INTO `customerdistancematrix` (`FromCustId`, `ToCustId`, `Distance`, `Source`) VALUES ";
                lParameter = new Dictionary<string, object>();
                for (int i = 0; i < distMat.GetLength(0); i++)
                {
                    if (i != 0)
                        query += ",";
                    query += "(?, ?, ?, ?)";
                    lParameter.Add("FromCustId" + "_" + i, ids[0]);
                    lParameter.Add("ToCustId" + "_" + i, ids[i]);
                    lParameter.Add("Distance" + "_" + i, distMat[i]);
                    lParameter.Add("Source" + "_" + i, source);
                }
                result = dbx.executeNonQuery(query, lParameter);
            }
            return result;
        }

