        public bool CheckAuthorizationForMethod(string allowedPages)
        {
            try
            {
                var segments = HttpContext.Current.Request.UrlReferrer.Segments;
                return allowedPages.Contains(segments[segments.Length - 1]);
            }
            catch
            {
                return true;
            }
        }
