                "inner join driverinfo di on di.UserDefinedDriverId = dv.UserDefinedDriverId " +
                "where di.Transporter = ? and di.AssignedVehicleId is not null and di.AssignedVehicleId != '' and di.Active = 1 " +
                "and " + complianceType + " between ? and ?";
