            lParameter.Add("Transporter", Transpoterid);
            lParameter.Add("startDate", formatDBDate(now));
            lParameter.Add("lastDate", formatDBDate(toDate));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
