        public DataTable GetDriverEventSummary(string driverId, string fromDate, string toDate, string AccountName, string nexydaydt)
        {
            string query = "";
            var lParameter = new Dictionary<string, object>();
            if (AccountName.ToLower().Contains("nokia"))
            {
                query = "select DISTINCT di.Name as 'Driver Name',di.UserDefinedDriverId as 'Driver Id',ti.Name as Haulier,REPLACE(d.VehicleId,' ','') as Vehicle,DATE_FORMAT(d.date,'%d-%b-%y') as Date," +
                "d.Kms_driven as 'Distance (In KM)',d.overspeed_count as 'Overspeeding',d.JRMOverspeed_count as 'RHM Overspeeding',d.hb_count as 'Harsh Braking',d.ha_count as 'Harsh Accelearation'," +
                "d.ContDrvg_count as 'Continuous Driving Count',((d.totalruntime * 60)/86400) as 'Driving Hours',(Time_to_sec(TIMEDIFF(w.endTime, w.startTime))/86400) AS 'Duty Hours' " +
                "from daywisesummary d " +
                "join vehicles v on v.VehicleId=d.VehicleId " +
                "join driverinfo di on di.DriverId=d.DriverId " +
                "join taging t ON t.VehicleId=d.VehicleId AND t.TimeStamp BETWEEN '" + fromDate + "' AND '" + nexydaydt + "' " +
                "left JOIN workdonedata w ON d.DriverId=w.driverId AND d.VehicleId=w.vehicleId  " +
                "AND w.date=d.date  " +
                "left join vehicleinfo vi on vi.VehicleId=v.VehicleID " +
                "left join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                "where d.date between ? and ? and d.Kms_driven > 0 and d.DriverId!=0 and di.UserDefinedDriverId=? ";
                lParameter.Add("fromDate", fromDate);
                lParameter.Add("toDate", toDate);
                lParameter.Add("UserDefinedDriverId", driverId);
            }
            else
            {
                if (AccountName.ToLower().Contains("shell energy"))
                {
                    query = "WITH DriverTotalRuntime AS (SELECT d.DriverId,d.date,SUM(d.totalruntime * 60) / 86400 AS TotalRunTime FROM daywisesummary d " +
                    "WHERE d.date BETWEEN ? AND ? GROUP BY d.DriverId, d.date),TagingPerDay AS ( " +
                    "SELECT DriverId,DATE(TimeStamp) AS date,MIN(TimeStamp) AS minTimeStamp,MAX(TimeStamp) AS maxTimeStamp FROM taging " +
                    "WHERE TimeStamp BETWEEN ? AND ? GROUP BY DriverId, DATE(TimeStamp)) " +
                    "SELECT di.Name as 'Driver Name', di.UserDefinedDriverId as 'Driver Id',ti.Name as 'Haulier',REPLACE(d.VehicleId, ' ', '') AS Vehicle,d.date as 'Date', " +
                    "IF(d.totalVehDistance = 0, 0, ROUND((d.Kms_driven / d.totalVehDistance) * 100)) AS 'Driver Key utilization %', " +
                    "d.Kms_driven AS 'Distance (In KM)',d.overspeed_count as 'Overspeeding',d.JRMOverspeed_count as 'RHM Overspeeding',d.hb_count as 'Harsh Braking',d.ha_count as 'Harsh Acceleration',0 AS 'Harsh Cornering',d.Freewheeling_count as 'Freewheeling',d.ExcessiveRPM_count as 'Excessive RPM', " +
                    "d.ExcessiveIdling_count as 'Excessive Idling',d.ContDrvg_count as 'Continuous Driving Count',((d.totalruntime * 60) / 86400) AS 'Driving hours', " +
                    "IFNULL(TIMESTAMPDIFF(SECOND, t.minTimeStamp, t.maxTimeStamp) / 86400, 0) AS 'Duty Hours',IFNULL(TIMESTAMPDIFF(SECOND, t.minTimeStamp, t.maxTimeStamp) / 86400, 0) - ((d.totalruntime * 60) / 86400) AS 'Rest Hours', " +
                    "(d.NightRest * 60) / 86400 AS 'Night Rest Hours(10PM-06AM)',(d.ContRestAfterDuty * 60) / 86400 AS 'Cont.Rest Hours',IF(d.nd_RunTime > 0, (d.nd_runtime * 60) / 86400, 0) AS 'Night driving', " +
                    "d.UnScheduled_stops as 'Unauthorised stop',d.RouteDeviation_count as 'Route diversion',d.SeatBeltViol_count as 'SeatBeltViolation' FROM daywisesummary d JOIN vehicles v ON v.VehicleId = d.VehicleId JOIN driverinfo di ON di.DriverId = d.DriverId  " +
                    "JOIN tripwisesummary ta ON ta.VehicleId = v.VehicleID AND ta.DriverId = d.DriverId LEFT JOIN vehicleinfo vi ON vi.VehicleId = v.VehicleID LEFT JOIN transporterinfo ti ON ti.TransporterId = vi.Transporter " +
                    "LEFT JOIN DriverTotalRuntime dt ON dt.DriverId = d.DriverId AND dt.date = d.date " +
                    "LEFT JOIN TagingPerDay t ON t.DriverId = d.DriverId AND t.date = d.date " +
                    "WHERE d.date BETWEEN ? AND ? AND d.DriverId != 0 AND di.UserDefinedDriverId = ? " +
                    "GROUP BY d.DriverId, d.VehicleId, d.date ORDER BY d.date, d.DriverId, d.VehicleId ";
                    lParameter.Add("fromDate", fromDate);
                    lParameter.Add("toDate", nexydaydt);
                    lParameter.Add("fromDate1", fromDate);
                    lParameter.Add("toDate1 ", nexydaydt);
                    lParameter.Add("fromDate2", fromDate);
                    lParameter.Add("toDate2", nexydaydt);
                    lParameter.Add("UserDefinedDriverId", driverId);
                }
                else
                {
                    query = "select di.Name as 'Driver Name',di.UserDefinedDriverId as 'Driver Id',ti.Name as Haulier,REPLACE(d.VehicleId,' ','') as Vehicle,DATE_FORMAT(d.date,'%d-%b-%y') as Date,IF(d.totalVehDistance=0,0,ROUND((d.Kms_driven/d.totalVehDistance)*100)) AS 'Driver Key Utilization %'," +
                    "d.Kms_driven as 'Distance (In KM)',d.overspeed_count as 'Overspeeding',d.JRMOverspeed_count as 'RHM Overspeeding',d.hb_count as 'Harsh Braking',d.ha_count as 'Harsh Accelearation',d.hc_count as 'Harsh Cornering'," +
                    "d.Freewheeling_count as Freewheeling,d.ExcessiveRPM_count as 'Excessive RPM',d.ExcessiveIdling_count as 'Excessive Idling'," +
                    "d.ContDrvg_count as 'Continuous Driving Count',((d.totalruntime * 60)/86400) as 'Driving Hours',(Time_to_sec(TIMEDIFF(d.duty_endtime, d.duty_starttime))/86400) AS DutyHours," +
                    "((d.NightRest * 60)/86400) as 'Night Rest Hours(10PM-06AM)'," +
                    "((d.ContRestAfterDuty*60)/86400) as 'Cont.Rest Hours'," +
                    "IF(nd_RunTime > 0, ((d.nd_runtime * 60)/86400), 0) as 'Night Driving',d.UnScheduled_stops as 'Unauthorsied Stop'," +
                    "d.RouteDeviation_count as 'Route diversion',d.SeatBeltViol_count as 'SeatBeltViolation' " +
                    "from daywisesummary d " +
                    "join vehicles v on v.VehicleId = d.VehicleId " +
                    "join driverinfo di on di.DriverId = d.DriverId " +
                    "left join vehicleinfo vi on vi.VehicleId = v.VehicleID " +
                    "left join transporterinfo ti on ti.TransporterId = vi.Transporter " +
                    "where d.date between ? and ? " +
                    "and di.UserDefinedDriverId = ?";
                    lParameter.Add("fromDate", fromDate);
                    lParameter.Add("toDate", toDate);
                    lParameter.Add("UserDefinedDriverId", driverId);
                }
            }

            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable GetAllDriverEventSummary(string groupid, string fromDate, string toDate, string AccountName, string nexydaydt)
        {
            string query = "";
            var lParameter = new Dictionary<string, object>();
            if (AccountName.ToLower().Contains("nokia"))
            {
                query = "select DISTINCT di.Name as 'Driver Name',di.UserDefinedDriverId as 'Driver Id',ti.Name as Haulier,REPLACE(d.VehicleId,' ','') as Vehicle,DATE_FORMAT(d.date,'%d-%b-%y') as Date, " +
            "d.Kms_driven as 'Distance (In KM)',d.overspeed_count as 'Overspeeding',d.hb_count as 'Harsh Braking',d.ha_count as 'Harsh Accelearation'," +
            "d.ContDrvg_count as 'Continuous Driving Count',((d.totalruntime * 60)/86400) as 'Driving Hours',(Time_to_sec(TIMEDIFF(w.endTime, w.startTime))/86400) AS 'Duty Hours' " +
            "from daywisesummary d " +
            "join vehicles v on v.VehicleId=d.VehicleId " +
            "join driverinfo di on di.DriverId=d.DriverId " +
