                    lParameter.Add("toDate1", nexydaydt);
                    lParameter.Add("groupid", groupid);
                    lParameter.Add("fromDate2", fromDate);
                    lParameter.Add("toDate2", nexydaydt);
                }
                else
                {
                    query = "select di.Name as 'Driver Name',di.UserDefinedDriverId as 'Driver Id',ti.Name as Haulier,REPLACE(d.VehicleId,' ','') as Vehicle,DATE_FORMAT(d.date,'%d-%b-%y') as Date,IF(d.totalVehDistance=0,0,ROUND((d.Kms_driven/d.totalVehDistance)*100)) AS 'Driver Key Utilization %'," +
                "d.Kms_driven as 'Distance (In KM)',d.overspeed_count as 'Overspeeding',d.JRMOverspeed_count as 'RHM Overspeeding',d.hb_count as 'Harsh Braking',d.ha_count as 'Harsh Accelearation',d.hc_count as 'Harsh Cornering'," +
                "d.Freewheeling_count as Freewheeling,d.ExcessiveRPM_count as 'Excessive RPM',d.ExcessiveIdling_count as 'Excessive Idling'," +
                "d.ContDrvg_count as 'Continuous Driving Count',((d.totalruntime * 60)/86400) as 'Driving Hours',(Time_to_sec(TIMEDIFF(d.duty_endtime, d.duty_starttime))/86400) AS 'Duty Hours'," +
                "((d.RestBeforeDuty + d.RestAfterDuty) * 60/86400) as 'Rest Hours'," +
                "((d.NightRest * 60)/86400) as 'Night Rest Hours(10PM-06AM)'," +
                "((d.ContRestAfterDuty*60)/86400) as 'Cont.Rest Hours'," +
                "IF(nd_RunTime > 0, ((d.nd_runtime * 60)/86400), 0) as 'Night Driving',d.UnScheduled_stops as 'Unauthorsied Stop'," +
                "d.RouteDeviation_count as 'Route diversion' " + //removed by zoya ,d.SeatBeltViol_count as 'SeatBeltViolation' " + on 11/03/2024 as shell driver event summary report they do not need seat Belt
                "from daywisesummary d " +
                "join vehicles v on v.VehicleId=d.VehicleId " +
                "join driverinfo di on di.DriverId=d.DriverId and d.date between ? and ? " +
                "left join vehicleinfo vi on vi.VehicleId=v.VehicleID " +
                "left join transporterinfo ti on ti.TransporterId=vi.Transporter " +
                "where d.VehicleId in (select vehicleid from vehiclesgroupsmap where groupid=?) " +
                "and d.date between ? and ? and d.DriverId!=0 and di.UserDefinedDriverId!='00000' ";
                    lParameter.Add("fromDate", fromDate);
                    lParameter.Add("toDate", toDate);
                    lParameter.Add("groupid", groupid);
                    lParameter.Add("fromDate1", fromDate);
                    lParameter.Add("toDate2", toDate);
                }
            }
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable GetVehicleEventSummary(string vehicleId, string fromDate, string toDate, string AccountName, string nexydaydt)
        {
            string query = "";
            if (AccountName.ToLower().Contains("nokia"))
            {
                //query = "select REPLACE(d.VehicleId,' ','') as VehicleId,ti.Name,DATE_FORMAT(d.date,'%d-%b-%y') as Date," +
                //"((SUM(d.totalruntime) * 60)/86400) as 'Total RunTime(Driving hours)',SUM(d.Kms_driven) as 'Distance (In KM)',ROUND((SUM(d.Kms_driven) / SUM(d.totalruntime)) * 60) as 'Average Speed', " +
                //"SUM(d.overspeed_count) as 'Overspeeding',SUM(d.hb_count) as 'Harsh Braking',SUM(d.ha_count) as 'Harsh Accelearation' " +
                query = "select REPLACE(d.VehicleId,' ','') as VehicleId,ti.Name,DATE_FORMAT(d.date,'%d-%b-%y') as Date," +
                "((SUM(d.totalruntime) * 60)/86400) as 'Total RunTime(Driving hours)',(d.Kms_driven) as 'Distance (In KM)',ROUND((SUM(d.Kms_driven) / SUM(d.totalruntime)) * 60) as 'Average Speed', " +
                "(d.overspeed_count) as 'Overspeeding',(d.hb_count) as 'Harsh Braking',(d.ha_count) as 'Harsh Accelearation' " +
                "from daywisesummary d " +
                "join vehicles v on v.VehicleId = d.VehicleId " +
                "join driverinfo di on di.DriverId = d.DriverId " +
                "join taging t ON t.VehicleId=d.VehicleId AND t.TimeStamp BETWEEN '" + fromDate + "' AND '" + nexydaydt + "' " +
                "left join vehicleinfo vi on vi.VehicleId = v.VehicleID " +
                "left join transporterinfo ti on ti.TransporterId = vi.Transporter " +
                "where d.Kms_driven > 0 and d.date between ? and ? " +
                "and d.VehicleId = ? group by d.VehicleId,d.date order by d.VehicleId";
            }
            else
            {
                query = "select REPLACE(d.VehicleId,' ','') as VehicleId,ti.Name,DATE_FORMAT(d.date,'%d-%b-%y') as Date," +
                "((SUM(d.totalruntime) * 60)/86400) as 'Total RunTime(Driving hours)',SUM(d.Kms_driven) as 'Distance (In KM)',ROUND((SUM(d.Kms_driven) / SUM(d.totalruntime)) * 60) as 'Average Speed',ROUND(MAX(d.AvgRPM)) as 'Average RPM'," +
                "SUM(d.overspeed_count) as 'Overspeeding',SUM(d.JRMOverspeed_count) as 'RHM Overspeeding',SUM(d.hb_count) as 'Harsh Braking',SUM(d.ha_count) as 'Harsh Accelearation',SUM(d.hc_count) as 'Harsh Cornering',SUM(d.Freewheeling_duration) as 'Freewheeling Duration',SUM(d.ExcessiveRPM_count) as 'Excessive RPM',SUM(d.ExcessiveIdling_duration) as 'Excessive Idling Duration'," +
                "((ROUND(AVG(d.DailyRest_maxvalue)) * 60)/86400) as 'Average Daily Rest Hours'," +
                "IF(nd_RunTime > 0, ((SUM(d.nd_runtime) * 60)/86400), 0) as 'Night driving',SUM(d.UnScheduled_stops) as 'Unauthorsied stop',SUM(d.RouteDeviation_count) as 'Route diversion',SUM(d.SeatBeltViol_count) as 'SeatBeltViolation' " +
                "from daywisesummary d " +
                "join vehicles v on v.VehicleId = d.VehicleId " +
                "join driverinfo di on di.DriverId = d.DriverId " +
                "left join vehicleinfo vi on vi.VehicleId = v.VehicleID " +
                "left join transporterinfo ti on ti.TransporterId = vi.Transporter " +
                "where d.date between ? and ? " +
                "and d.VehicleId = ? group by d.VehicleId,d.date order by d.VehicleId";
            }
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromDate", fromDate);
            lParameter.Add("toDate", toDate);
            lParameter.Add("VehicleId", vehicleId);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
