        public DataTable GetVehicleTripSummary(string vehicleId, string fromDate, string toDate, string AccountName, string nexydaydt)
        {
            string query = "";
            if (AccountName.ToLower().Contains("nokia"))
            {
                query = "select REPLACE(d.VehicleId,' ','') as Vehicle," +
                "d.actual_starttime as 'Trip Start Time'," +
                "d.actual_endtime as 'Trip End Time'," +
                "d.startlatlng as 'Start Location',d.endlatlng as 'End Location',i.Name as 'Driver',d.Kms_driven as 'Distance (Km)'," +
                "((d.totalruntime * 60)/86400) as 'RunTime',d.MaxSpeed as 'Max Speed(Km/h)',ROUND((d.Kms_driven / d.totalruntime) * 60) as 'Avg Speed(Km/h)'," +
                "d.ContDrvg_count as 'Continuous Driving Hrs',d.overspeed_count as 'Overspeeding',d.hb_count as 'Harsh Braking',d.ha_count as 'Harsh Accelearation' " +
                "from tripwisesummary d " +
                "join driverinfo i on i.DriverId = d.DriverId " +
                "join taging t ON t.VehicleId=d.VehicleId AND t.TimeStamp BETWEEN '" + fromDate + "' AND '" + nexydaydt + "' " +
                "where d.VehicleId = ? and d.date between ? and ? " +
                "and d.actual_starttime is not null and d.actual_endtime is not null and d.Kms_driven > 0 " +
                "group by d.VehicleId,d.actual_starttime,d.actual_endtime " +
                "order by d.VehicleId,STR_TO_DATE(d.actual_starttime, '%Y-%m-%d %H:%i:%s')";
            }
            else
            {
                query = "select REPLACE(d.VehicleId,' ','') as Vehicle," +
                "d.actual_starttime as 'Trip Start Time'," +
                "d.actual_endtime as 'Trip End Time'," +
                "d.startlatlng as 'Start Location',d.endlatlng as 'End Location',i.Name as 'Driver',d.Kms_driven as 'Distance (Km)'," +
                "((d.totalruntime * 60)/86400) as 'RunTime',d.MaxSpeed as 'Max Speed(Km/h)',ROUND((d.Kms_driven / d.totalruntime) * 60) as 'Avg Speed(Km/h)'," +
                "d.MaxRPM as 'Max RPM',d.ContDrvg_count as 'Continuous Driving Hrs',d.overspeed_count as 'Overspeeding',d.JRMOverspeed_count as 'RHM overspeeding',d.hb_count as 'Harsh Braking',d.ha_count as 'Harsh Accelearation',d.hc_count as 'Harsh Cornering',d.Freewheeling_count as 'Freewheeling'," +
                //"d.ExcessiveRPM_count as 'Excessive RPM',d.ExcessiveIdling_count as 'Excessive Idling',d.UnScheduled_stops as 'Unauthorsied stop',d.RouteDeviation_count as 'Route diversion','' as TimeFromPrevTrip " +
                "d.ExcessiveRPM_count as 'Excessive RPM',d.ExcessiveIdling_count as 'Excessive Idling',d.UnScheduled_stops as 'Unauthorsied stop',d.RouteDeviation_count as 'Route diversion','' AS TimeFromPrevTrip " +
                "from tripwisesummary d " +
                "join driverinfo i on i.DriverId = d.DriverId " +
                "where d.VehicleId = ? and d.date between ? and ? " +
                "and d.actual_starttime is not null and d.actual_endtime is not null and d.Kms_driven > 0 " +
                "group by d.VehicleId,d.actual_starttime,d.actual_endtime " +
                "order by d.VehicleId,STR_TO_DATE(d.actual_starttime, '%Y-%m-%d %H:%i:%s')";
            }
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleId", vehicleId);
            lParameter.Add("fromDate", fromDate);
            lParameter.Add("toDate", toDate);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
