        public DataTable GetDriverTaggingStatusPassengerTagIn(string sessionId, DateTime tagInTime, string shift)
        {
            int accountId = GetAccountId(sessionId);
            int groupId = getGroupId(sessionId);
            string pTagInTime = formatDBDate(tagInTime);
            string query = "select distinct p.DriverId,p.VehicleId,p.TagInTime,d.Name,d.MobileNo,i.PsngrId,i.PsngrName,i.MobileNo as `PMobile` from psngr_tag p " +
                "inner join driverinfo d on d.DriverId = p.DriverId " +
                "inner join psngr_info i on i.PsngrId = p.PsngrId " +
                "where p.DriverId not in (select p.DriverId from psngr_tag p inner join driverinfo d on d.AssignedVehicleId = p.VehicleId " +
                "inner join taging t on p.VehicleId = t.VehicleId where t.TimeStamp between p.TagInTime and DATE_ADD(p.TagInTime, INTERVAL 10 MINUTE) " +
                "and p.TagInTime between DATE_ADD(?, INTERVAL -15 MINUTE) and DATE_ADD(?, INTERVAL -10 MINUTE) and d.AccountId = ? and d.GroupId = ?) " +
                "and p.TagInTime between DATE_ADD(?, INTERVAL -15 MINUTE) and DATE_ADD(?, INTERVAL -10 MINUTE) and d.AccountId = ? and d.GroupId = ?";// and d.DrivingExp = ?
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromTagInTime1", pTagInTime);
            lParameter.Add("fromTagOutTime1", pTagInTime);
            lParameter.Add("AccountId", accountId);
            lParameter.Add("GroupId", groupId);
            lParameter.Add("fromTagInTime2", pTagInTime);
            lParameter.Add("fromTagOutTime2", pTagInTime);
            lParameter.Add("AccId", accountId);
            lParameter.Add("GrpId", groupId);
            //lParameter.Add("shift", shift);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetDriverTaggingStatusInterval(string sessionId, string minTime, string maxTime, string shift)
        {
            int accountId = GetAccountId(sessionId);
            int groupId = getGroupId(sessionId);
            //string now = formatDBDate(DateTime.Now.AddSeconds(GetTimeZoneDiff()));
            string now = formatDBDate(DateTime.Now);
            string query = "select * from driverinfo d where d.DriverId NOT IN " +
                            "(select t.DriverId from taging t inner join driverinfo d on t.DriverId = d.DriverId " +
                            "where t.TimeStamp between ? and ? and " +
                            "t.TimeStamp between DATE_ADD(?, INTERVAL - 3 HOUR) and ? and d.AccountId = ? and d.GroupId = ? and d.DrivingExp = ?)" +
                            " and d.AccountId = ? and d.GroupId = ? and d.DrivingExp = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromTagInTime1", formatDBDate(Convert.ToDateTime(minTime)));
            lParameter.Add("fromTagOutTime1", formatDBDate(Convert.ToDateTime(maxTime)));
            lParameter.Add("fromTagInTime2", now);
            lParameter.Add("fromTagOutTime2", now);
            lParameter.Add("AccountId", accountId);
            lParameter.Add("GroupId", groupId);
            lParameter.Add("shift", shift);
            lParameter.Add("AccId", accountId);
            lParameter.Add("GrpId", groupId);
            lParameter.Add("sft", shift);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

