        public DataTable GetDriverTaginoutSummary(string sessionId, DateTime fromDate, DateTime toDate)
        {
            int accountId = GetAccountId(sessionId);
            string query = "select distinct DATE_FORMAT(n.TimeStamp, '%d-%m-%Y') as 'Date',DATE_FORMAT(n.TimeStamp, '%h:%i:%s') as 'Time',n.Summary as `Violation Summary`,n.Description as `Description`," +
                "n.VehicleNo as `Vehicle No`,v.ProposedVehicleType,v.PresentVehicleType,v.CT,v.Circle," +
                "d.Name as `Driver Name`,d.LicenceNo as `License Number`,d.MobileNo as `Driver MobileNo`," +
                "if(n.DriverTagin='00-00-00 00:00:00','',n.DriverTagin) as `Driver Tagin Time`,d.DrivingExp as `Driver Shift`," +
                "d.AssignedVehicleId as `Assigned Vehicle`,p.PsngrName as `Passenger Name`,p.MobileNo as `Passenager MobileNo`," +
                "if(n.PassengerTagin='00-00-00 00:00:00','',n.PassengerTagin) as `Passenger Tagin Time`," +
                "if(n.PassengerTagout='00-00-00 00:00:00','',n.PassengerTagout) as `Passenger Tagout Time` from nokiaalertslog n " +
                "left join driverinfo d on d.DriverId = n.DriverId " +
                "left join psngr_info p on p.PsngrId = n.PassengerId " +
                "left join vehdriver_staticdata v on v.Vehicle = replace(n.VehicleNo, ' ', '') " +
                "where n.TimeStamp between ? and ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromDate", formatDBDate(fromDate));
            lParameter.Add("toDate", formatDBDate(toDate));
            lParameter.Add("AccountId", accountId);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

