            string[] type = new string[] { "RIGID TRUCK/TRUCK/PRIME MOVER", "Trailer/Semi-Trailer", "Tank", "Accessories", "PPE- Driver", "Vehicle Documents" };
            string inQuery = "";
            var lParameter = new Dictionary<string, object>();
            for (int i = 0; i < type.Length; i++)
            {
                if (truckType == "Packed" && (i == 1 || i == 2))
                {
                    // for packed 2nd and 3rd checklists not there
                }
                else if (truckType == "Rigid" && i == 1)
                {
                    //for rigid 2nd checklist is not there
                }
                else
                {
                    inQuery += "?,";
                    lParameter.Add("chklst" + i, type[i]);
                }
            }
            inQuery = inQuery.Substring(0, inQuery.Length - 1);
            string query = "select c.Id,c.Name,c.RuleName,c.Coefficient,group_Concat(concat('&@&',o.`Option`,'@&@',o.Score)) Options from vet_checklist c join "
                         + "vet_checklist_options o on c.Id=o.ChecklistId where c.Name in (" + inQuery + ") and c.AccountId=? group by c.Id";
            lParameter.Add("AccountId", AccountId);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetVettingReport(string sessionId, string vehicleType, string fromDt, string toDt)
        {
            string username = getUserId(sessionId);
            string query = "select v.Id,v.VehicleId,v.VehicleType,v.VettingDate,l.Name,sum(c.Score * l.Coefficient) obtainedScore,sum(l.Coefficient)*3 totalScore,v.FileName from "
                + "vet_static_details v join vet_checklist_values c on v.Id = c.VettingId join vet_checklist l on l.Id = c.RuleId where v.AddedBy = ? and "
                + "v.VettingDate >= ? and v.VettingDate <= ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AddedBy", username);
            lParameter.Add("VettingDate1", formatDBDate(Convert.ToDateTime(fromDt)));
            lParameter.Add("VettingDate2", formatDBDate(Convert.ToDateTime(toDt)));
            if (vehicleType != "All")
            {
                query += " and v.VehicleType=?";
                lParameter.Add("VehicleType", vehicleType);
            }
            query += " group by v.Id,l.Name";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable GetVetReport(string sessionId, string appId, string fromDt, string toDt)
        {
            string username = getUserId(sessionId);
            string query = "select s.Id,f.FieldName,v.Value,s.DateTime,s.FileName from vet_static_details s join vet_header h on s.AppId=h.AppId join vet_fields f on "
                         + "f.HeaderId=h.Id left join vet_field_values v on v.VetId=s.Id and v.FieldId=f.Id where s.DateTime>=? and s.DateTime<=? and s.AppId=? and "
                         + "s.AddedBy=? and f.ShowMain=1";
