            lParameter.Add("AddedBy", username);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public string GetVetScore(string vetId)
        {
            try
            {
                string query = "select floor(avg(floor((ObtainedScore/TotalScore)*100))) Score from (select h.HeaderName,sum(c.Coefficient* v.Score) ObtainedScore,"
                             + "sum((select max(vco.Score) from vet_checklist_options vco where vco.ChecklistId=c.Id)* c.Coefficient) TotalScore from vet_static_details s "
                             + "join vet_header h on s.AppId=h.AppId and s.AccountId=h.AccountId join vet_checklist c on c.HeaderId=h.Id join vet_checklist_values v on "
                             + "c.Id=v.RuleId and v.VettingId=s.Id join vet_checklist_options o on o.ChecklistId=c.Id and o.Score=v.Score where s.Id=? group by c.HeaderId) result";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("Id", vetId);
                string res = dbx.executeScalar(query, lParameter).ToString();
                if (string.IsNullOrEmpty(res))
                    res = "0";
                return res;
            }
            catch (Exception ex)
            {
                return "0";
            }
        }

