        public string insertVehicleVettingDetails(string sessionid, Vehicle_Vetting_Fields vehicle_Vetting_Fields, List<Vehicle_Vetting_Checklist> vehicle_Vetting_Checklist)
        {
            int AccountId = GetAccountId(sessionid);
            string username = getUserId(sessionid);
            string query = "INSERT INTO `veh_vet_details` (`AccountID`, `AddedBy`, `DateTime`, `prevInspectDate`, `inspectDate`, `inspectStartTime`, `inspectEndTime`,"
                + " `inspectName`, `transporter`, `driverName`, `tractorRegNo`, `trailerRegNo`, `truckChassisNo`, `trailerChassisNo`, `vehCategory`, `vehType`, `tankCap`,"
                + " `productLoad`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", AccountId);
            lParameter.Add("AddedBy", username);
            lParameter.Add("DateTime", formatDBDate(DateTime.Now));
            lParameter.Add("prevInspectDate", vehicle_Vetting_Fields.prevInspectDate);
            lParameter.Add("inspectDate", vehicle_Vetting_Fields.inspectDate);
            lParameter.Add("inspectStartTime", vehicle_Vetting_Fields.inspectStartTime);
            lParameter.Add("inspectEndTime", vehicle_Vetting_Fields.inspectEndTime);
