        public DataTable getVehVetSummary(string ids)
        {
            var lParameter = new Dictionary<string, object>();
            string inQuery = "";
            string[] idStr = ids.Split(',');
            for (int i = 0; i < idStr.Length; i++)
            {
                lParameter.Add("id_" + i, idStr[i]);
                if (inQuery != "")
                    inQuery += ",";
                inQuery += idStr[i];
            }
            string query = "select v.SectionID,count(*) count,group_concat(v.ChecklistID) ids,v.Criteria from veh_vet_checklist v where v.ID in (" + inQuery
                + ") group by v.Criteria,v.SectionID";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

