        public object[] getScoreByCategoryWise(string id, string login, DateTime datetime)
        {
            object[] result = new object[2];
            result[0] = 0;
            result[1] = "";
            int groupid = getGroupIdByLogin(login);
            int violCount = 0;
            try
            {
                string query = "";
                var lParameter = new Dictionary<string, object>();
                switch (id)
                {
                    case "293"://Maximum Driving Hours
                        result = getViolationCountByType(groupid, datetime, "TOTAL RUNTIME");
                        break;
                    case "294"://Number of Night driving/no of days worked
                        result = getViolationCountByType(groupid, datetime, "NIGHT DRIVING");
                        break;
                    case "295"://Number of over speed violations/1000kms driven
                        result = getViolationCountByType(groupid, datetime, "OVERSPEEDING");
                        break;
                    case "296"://Continuous driving
                        result = getViolationCountByType(groupid, datetime, "SHORT RUNTIME");
                        break;
                    case "302"://Number of instances of daily 9hrs  rest not taken
                        result = getViolationCountByType(groupid, datetime, "LONG REST");
                        break;
                    case "309"://Spot Check
                        result = getStdRejectPercent(groupid, datetime, "2");
                        break;
                    case "310"://Safe to Dispatch
                        result = getStdRejectPercent(groupid, datetime, "1");
                        break;
                    case "311"://Safe To Load
                        result = getStdRejectPercent(groupid, datetime, "0");
                        break;
                    case "305"://Defensive Driving-% of A grade drivers
                        result = getAGradeDDTCount(login);
                        break;
                    case "306"://High Risk Drivers
                        result = getHighRiskDrivers(groupid, datetime);
                        break;
                    case "308"://Vetting of Trucks
                        result = getAvgVettingScore(groupid);
                        break;
                    case "297"://Mobile Phone usage
                        result = getSigSenzViolationCount(groupid, datetime, "MobileUsage");
                        break;
                    case "298"://Seat Belt Violation
                        result = getSigSenzViolationCount(groupid, datetime, "SeatBeltViolation");
                        break;
                    case "301"://Driver Fatigue
                        result = getSigSenzViolationCount(groupid, datetime, "DriverFatigue");
                        break;
                    case "300"://Unauthorized person in cabin
                        result = getSigSenzViolationCount(groupid, datetime, "PeopleCount");
                        break;
                        //case "312"://Maintenance of Vehicles
                        // result = getSigSenzViolationCount(groupid, datetime, "PeopleCount");
                        // break;
                }
            }
            catch (Exception ex)
            {

            }
            return result;
        }
        public object[] getViolationCountByType(int groupid, DateTime dt, string vioType)
        {
            string query = "select count(*) from vehiclesgroupsmap v join storevehicleviolations s on v.VehicleId=s.vehicleId where v.GroupId=? and "
                              + "month(s.timestamp)=? and year(s.timestamp)=? and s.`type`=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("month", dt.Month);
            lParameter.Add("year", dt.Year);
            lParameter.Add("type", vioType);
            int violCount = Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString());
            object[] result = new object[2];
            result[1] = "Violation Count : " + violCount;
            result[0] = violCount > 0 ? 0 : 2;
            return result;
        }
        public object[] getStlRejectPercent(int groupid, DateTime dt, string vioType)
        {
            string query = "select ifnull((sum(case when s.`Action`='Allow' then 0 else 1 end)/count(*))*100,0) from stl_workflow s join vehiclesgroupsmap v on "
                + "s.vehicleId=v.VehicleId where v.GroupId=? and s.workflowtype=? and month(s.datetime)=? and year(s.datetime)=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("type", vioType);
            lParameter.Add("month", dt.Month);
            lParameter.Add("year", dt.Year);
            int percent = Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString());
            object[] result = new object[2];
            result[1] = "Deviation(%) : " + percent;
            if (vioType == "0")
                result[0] = percent > 1 ? 0 : 2;
            else
                result[0] = percent == 0 ? 2 : 0;
            return result;
        }
