        public DataTable GetVehicleEventReport(string fromDateStr, string toDateStr, string vehicle)
        {
            //Modified by suvarna on 28/6/2021 to include GPSSpeed
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            int accid = getAccountIdByVehicleId(vehicle);
            StringBuilder query = new StringBuilder();
            query.Append("SELECT * FROM (");
            query.Append("SELECT p.TruckID,p.TIMESTAMP,if(e.bid IS NOT NULL,if(p.`Stop`=0 AND (RPMRatio(p.TruckID)*p.CI)>99.999 AND Can_Speed(p.TruckID,p.TIMESTAMP)>0,'RFID SWIPED,ENGINE ON & MOVING',");
            query.Append("if(p.`Stop`=0 AND (RPMRatio(p.TruckID)*p.CI)>99.999,'RFID SWIPED & ENGINE ON','RFID SWIPED')),");
            query.Append("if(s.`type` IS NOT NULL AND s.type IN ('NIGHT DRIVING','ROUTE DEVIATION','SHORT RUNTIME','UNSCHEDULED STOP','FREEWHEELING','EXCESSIVE IDLE','TOTAL RUNTIME','OVERSPEEDING','JRM OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','EXCESSIVE RPM'),s.`type`,");
            query.Append("if(`Stop`=0,if((RPMRatio(p.TruckID)*p.CI)>99.999,if(Can_Speed(p.TruckID,p.TIMESTAMP)>0.00,'MOVING','IDLING'),if(Can_Speed(p.TruckID,p.TIMESTAMP)>3.00,'','IDLING')),");
            query.Append("if((RPMRatio(p.TruckID)*p.CI)>99.999,if(Can_Speed(p.TruckID,p.TIMESTAMP)>5.00,'MOVING(SB)','IDLING(SB)'),if(Can_Speed(p.TruckID,p.TIMESTAMP)>5,'','HALTED'))))) AS EVENT,");
            query.Append("e.bid,p.`Start`,p.`Stop`,if(Can_Speed(p.TruckID,p.TIMESTAMP)>0,Can_Speed(p.TruckID,p.TIMESTAMP),0) AS 'Speed',if(RPMRatio(p.TruckID)*p.CI >99.999,ROUND((RPMRatio(p.TruckID)*p.CI),0),0) AS RPM,p.Latitude,p.Longitude,s.Location as vioLocation,p.Speed as GPSSpeed");
            query.Append(" FROM positiondata PARTITION(" + part + ") p left JOIN storevehicleviolations s ON s.vehicleId=p.TruckID AND s.TIMESTAMP=p.TIMESTAMP ");
            query.Append("LEFT JOIN ets_rfiddata e on e.TruckID=p.TruckID AND e.TIMESTAMP=p.TimeStamp  WHERE p.TruckID=? AND p.TIMESTAMP BETWEEN ? AND ? ");
            query.Append(" AND ((p.LAC>0.00 OR e.TIMESTAMP=p.TIMESTAMP) OR (p.LAC>0.00 OR s.TIMESTAMP=p.TIMESTAMP))");
            query.Append(" UNION ");
            if (accid == 32)
            {
                query.Append("SELECT r.TruckID,r.TIMESTAMP,'QR Code Scanned' AS EVENT,r.bid,'0' AS `Start`,'0' AS `Stop`,'0' AS `Speed`,'0' AS RPM,r.Latitude,r.Longitude,'' as vioLocation,'0' AS `GPSSpeed` ");
                query.Append("FROM ets_rfiddata r WHERE r.TruckID=? AND r.TIMESTAMP BETWEEN ? AND ?) a ORDER BY a.TIMESTAMP asc;");
            }
            else
            {
                query.Append("SELECT r.TruckID,r.TIMESTAMP,'RFID SWIPED' AS EVENT,r.bid,'0' AS `Start`,'0' AS `Stop`,'0' AS `Speed`,'0' AS RPM,r.Latitude,r.Longitude,'' as vioLocation,'0' AS `GPSSpeed` ");
                query.Append("FROM ets_rfiddata r WHERE r.TruckID=? AND r.TIMESTAMP BETWEEN ? AND ?) a ORDER BY a.TIMESTAMP asc;");
            }
            //query.Append("SELECT p.TruckID,p.TIMESTAMP,if(e.bid IS NOT NULL,'RFID SWIPED',");
            //query.Append("if(s.`type` IS NOT NULL AND s.type IN ('NIGHT DRIVING','ROUTE DEVIATION','SHORT RUNTIME','UNSCHEDULED STOP','FREEWHEELING','EXCESSIVE IDLE','TOTAL RUNTIME','OVERSPEEDING','JRM OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION','HARSH CORNERING','EXCESSIVE RPM'),s.`type`,");
            //query.Append("if(p.`Stop`=0 AND p.Speed>0.00 AND p.CI>99.999,'MOVING',if(p.`Stop`=0 and p.Speed=0.00,'ENGINE ON',if(p.`Stop`=1,'HALTED',''))))) AS EVENT,");
            //query.Append("e.bid,p.`Start`,p.`Stop`,if(p.`Stop`=0,p.Speed,'0.00') AS 'Speed',if(p.`Stop`=0,p.FuelLevel,'0.00') AS FuelLevel, if(p.`Stop`=0,if(p.CI>99.999,round(p.CI,0),'0'),'0') AS RPM,p.Latitude,p.Longitude FROM positiondata PARTITION(" + part + ") p left JOIN storevehicleviolations s ON s.vehicleId=p.TruckID AND s.TIMESTAMP=p.TIMESTAMP ");
            //query.Append("LEFT JOIN ets_rfiddata e on e.TruckID=p.TruckID AND e.TIMESTAMP=p.TimeStamp  WHERE p.TruckID=? AND p.TIMESTAMP BETWEEN ? AND ? AND ((p.LAC>0.00 OR e.TIMESTAMP= p.TIMESTAMP) OR (p.LAC>0.00 OR s.TIMESTAMP=p.TIMESTAMP)) ORDER BY p.TIMESTAMP ASC;");

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TruckID", vehicle);
            lParameter.Add("fromDate", fromDateStr);
            lParameter.Add("toDate", toDateStr);
            lParameter.Add("TruckID2", vehicle);
            lParameter.Add("fromDate2", fromDateStr);
            lParameter.Add("toDate2", toDateStr);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }

        public string SaveVehicleRoutingSolution(GoogleOrToolSolution googleOrToolSolutions, string source, string sessionId, string planStatus, DateTime planDt)
        {
            string username = getUserId(sessionId);
            int accountid = GetAccountId(sessionId);
            string query = "INSERT INTO `otp_plan_info` (`Source`, `DateTime`, `RunBy`, `TotalLoad`, `TotalDistance`, `NumOfCusts`, `NumOfVehs`, `NumOfDrops`, "
                + "`VehiclesUsed`, `Utilization`, `AccountId`,Algorithm,Alg_Direction,Status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Source", source);
            lParameter.Add("DateTime", formatDBDate(planDt));
            lParameter.Add("RunBy", username);
            lParameter.Add("TotalLoad", googleOrToolSolutions.total_load);
            lParameter.Add("TotalDistance", googleOrToolSolutions.total_distance);
            lParameter.Add("NumOfCusts", googleOrToolSolutions.no_of_custs);
            lParameter.Add("NumOfVehs", googleOrToolSolutions.no_of_vehs);
            lParameter.Add("NumOfDrops", googleOrToolSolutions.droppedcustomers.Count);
            lParameter.Add("VehiclesUsed", googleOrToolSolutions.veh_used);
            lParameter.Add("Utilization", googleOrToolSolutions.utilization);
            lParameter.Add("AccountId", accountid);
            lParameter.Add("Algorithm", googleOrToolSolutions.algorithm);
            lParameter.Add("Alg_Direction", googleOrToolSolutions.alg_direction);
            lParameter.Add("Status", planStatus);
            int res = dbx.executeNonQuery(query, lParameter);
            if (res > 0)
            {
                query = "select Max(o.Id) from otp_plan_info o where o.RunBy=? and o.Source=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("RunBy", username);
                lParameter.Add("Source", source);
                string planId = dbx.executeScalar(query, lParameter).ToString();
                for (int i = 0; i < googleOrToolSolutions.trips.Count; i++)
                {
                    query = "INSERT INTO `otp_trip_info` (`PlanId`, `VehicleId`, `Capacity`, `Load`, `Distance`, `Utilization`, `IsInTrip`) VALUES (?, ?, ?, ?, ?, ?, ?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("PlanId", planId);
                    lParameter.Add("VehicleId", googleOrToolSolutions.trips[i].vehicle);
                    lParameter.Add("Capacity", googleOrToolSolutions.trips[i].capacity);
                    lParameter.Add("Load", googleOrToolSolutions.trips[i].load);
                    lParameter.Add("Distance", googleOrToolSolutions.trips[i].distance);
                    lParameter.Add("Utilization", googleOrToolSolutions.trips[i].utilization);
                    lParameter.Add("IsInTrip", googleOrToolSolutions.trips[i].trip_Customers.Count > 0);
                    res = dbx.executeNonQuery(query, lParameter);
                    if (res > 0 && googleOrToolSolutions.trips[i].trip_Customers.Count > 0)
                    {
                        query = "select Max(o.Id) from otp_trip_info o where o.PlanId=?";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("PlanId", planId);
                        string tripId = dbx.executeScalar(query, lParameter).ToString();
                        for (int j = 0; j < googleOrToolSolutions.trips[i].trip_Customers.Count; j++)
                        {
                            query = "INSERT INTO `otp_trip_customers` (`TripId`, `Order`,CustomerName, `CustomerId`, `Load`, `Distance`, `Arrival`, `Departure`) VALUES "
                                + "(?, ?, ?, ?, ?, ?, ?, ?)";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("TripId", tripId);
                            lParameter.Add("Order", j);
                            lParameter.Add("CustomerName", googleOrToolSolutions.trips[i].trip_Customers[j].customername);
                            lParameter.Add("CustomerId", googleOrToolSolutions.trips[i].trip_Customers[j].customerid);
                            lParameter.Add("Load", googleOrToolSolutions.trips[i].trip_Customers[j].load);
                            lParameter.Add("Distance", googleOrToolSolutions.trips[i].trip_Customers[j].distance);
                            lParameter.Add("Arrival", formatDBDate(Convert.ToDateTime(googleOrToolSolutions.trips[i].trip_Customers[j].arrival)));
                            lParameter.Add("Departure", googleOrToolSolutions.trips[i].trip_Customers[j].departure != "" ? formatDBDate(Convert.ToDateTime(googleOrToolSolutions.trips[i].trip_Customers[j].departure)) : null);
                            res = dbx.executeNonQuery(query, lParameter);
                        }
                    }
                }
                for (int i = 0; i < googleOrToolSolutions.droppedcustomers.Count; i++)
                {
                    query = "INSERT INTO `otp_customer_drops` (`PlanId`, `CustomerName`, `CustomerId`, `Load`) VALUES (?, ?, ?, ?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("PlanId", planId);
                    lParameter.Add("CustomerName", googleOrToolSolutions.droppedcustomers[i].customername);
                    lParameter.Add("CustomerId", googleOrToolSolutions.droppedcustomers[i].customerid);
                    lParameter.Add("Load", googleOrToolSolutions.droppedcustomers[i].load);
                    res = dbx.executeNonQuery(query, lParameter);
                }
                return "Updated Successfully..!";
            }
            else
                return "Failed to insert plan..!";
        }

