        public string FindTrueSpeed(string VehicleNo, string strartime, string endtime, string speed, string type)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TruckID", VehicleNo);
            lParameter.Add("strartime", strartime);
            if (type == "EXCESSIVE IDLE")
            {
                query.Append("SELECT Abs(Avg(LAC)),TimeStamp,Speed,FuelLevel,Stop,round(AVG(CI),0) as 'RPM' FROM positiondata p WHERE TruckID=? AND TIMESTAMP BETWEEN ? AND ? AND p.LAC !=0.000");
                lParameter.Add("endtime", endtime);
            }
            else
            {
                query.Append("SELECT Abs(LAC),TimeStamp,Speed,FuelLevel,Stop,if(CI>99,round(CI,0),'0') as 'RPM' FROM positiondata WHERE TruckID=? AND TIMESTAMP = ?;");
            }
            DataTable TblRLac = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            string Speed = speed;
            if (TblRLac.Rows.Count > 0)
            {
                DataRow RLac = TblRLac.Rows[0];
                double lac = 00.00;
                if (!string.IsNullOrEmpty(RLac[0].ToString()))
                    lac = Convert.ToDouble(RLac[0]);
                string sp = "0"; string canSp = "0"; string rpm = "0";
                if (!string.IsNullOrEmpty(RLac[2].ToString()))
                    sp = RLac[2].ToString();
                if (!string.IsNullOrEmpty(RLac[3].ToString()))
                    canSp = RLac[3].ToString();
                if (!string.IsNullOrEmpty(RLac[5].ToString()))
                    rpm = RLac[5].ToString();

                Speed = sp + "-" + canSp + "$" + rpm;
                if (lac < 10.00)
                {
                    query.Clear();
                    query.Append("SELECT LAC,TIMESTAMP,Speed,FuelLevel,STOP,if(CI>99,round(CI,0),'0') as 'RPM' FROM positiondata WHERE TruckID=? AND LAC!=0.000 AND TIMESTAMP > ? ORDER BY TIMESTAMP ASC LIMIT 1;");
                    lParameter.Clear();
                    lParameter.Add("TruckID", VehicleNo);
                    lParameter.Add("time", strartime);
                    RLac = dbx.executeQuery(query.ToString(), lParameter).Tables[0].Rows[0];
                    if (!string.IsNullOrEmpty(RLac[2].ToString()))
                        sp = RLac[2].ToString();
                    if (!string.IsNullOrEmpty(RLac[3].ToString()))
                        canSp = RLac[3].ToString();
                    if (!string.IsNullOrEmpty(RLac[5].ToString()))
                        rpm = RLac[5].ToString();
                    Speed = sp + "-" + canSp + "$" + rpm;
                }
            }

            return Speed;
        }

