        public string ValidatingUnscheduledStops(string vehicleId, string fromdatestr, string todatestr)
        {
            string result = "";
            string isunscheduled = "Yes"; //Modified by suvarna on 15/10/2020
            string part = GetDateTablePartitions(Convert.ToDateTime(fromdatestr), Convert.ToDateTime(todatestr), partions);
            string query = "select * from `positiondata` PARTITION(" + part + ") AS p" +
                           " where TruckID=? and TimeStamp>=? and TimeStamp<=? and Stop=0 and CI!=0";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TruckID", vehicleId);
            lParameter.Add("fromdatestr", formatDBDate(Convert.ToDateTime(fromdatestr)));
            lParameter.Add("todatestr", formatDBDate(Convert.ToDateTime(todatestr)));
            DataTable positiondata = dbx.executeQuery(query, lParameter).Tables[0];
            if (positiondata.Rows.Count == 0)
            {
                part = GetDateTablePartitions(Convert.ToDateTime(fromdatestr).AddMonths(-1), Convert.ToDateTime(fromdatestr), partions);
                query = "select * from positiondata PARTITION(" + part + ") AS p where p.TruckID=? and p.TimeStamp>(select p1.TimeStamp from positiondata PARTITION("
                    + part + ") AS p1 where p1.TruckID=? and p1.TimeStamp<? and p1.Stop=0 order by p1.TimeStamp desc limit 1) and p.`Stop`=1 order by p.TimeStamp limit 1";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("TruckID", vehicleId);
                lParameter.Add("TruckID1", vehicleId);
                lParameter.Add("TimeStamp", formatDBDate(Convert.ToDateTime(fromdatestr)));
                positiondata = dbx.executeQuery(query, lParameter).Tables[0];
                if (positiondata.Rows.Count > 0)
                {
                    DataTable allowedRegions = GetAllAllowedRegions(vehicleId, 0, true);
                    DataRow[] dr = allowedRegions.Select("minLatitude<=" + positiondata.Rows[0]["Latitude"].ToString() + " and minLongitude<="
                        + positiondata.Rows[0]["Longitude"].ToString() + " and maxLatitude>=" + positiondata.Rows[0]["Latitude"].ToString() + " and maxLongitude>="
                        + positiondata.Rows[0]["Longitude"].ToString());
                    if (dr.Length > 0)
                    {
                        int res = updateStorevehviolationType(vehicleId, todatestr, "UNSCHEDULED STOP", "SCHEDULED STOP");
                        isunscheduled = "No";//Modified by suvarna on 15/10/2020
                        if (res > 0)
                        {
                            result = "Unscheduled Stop is updated to scheduled stop for vehicle " + vehicleId + " at " + todatestr + " inside " + dr[0]["regionName"];
                        }
                        else
                            result = "Not updated to scheduled stop for vehicle " + vehicleId + " at " + todatestr + " inside " + dr[0]["regionName"];
                    }
                    else
                        result = "Invalid location for vehicle " + vehicleId + " at " + todatestr;
                }
            }
            return isunscheduled;
        }
