        public int deleteVehicleInPlantData(string vehiclesStr, string geofencesStr, string date)
        {
            string vehicles = "";
            string geofences = "";
            var lParameter = new Dictionary<string, object>();
            string[] str = vehiclesStr.Split(new string[] { "@&@" }, StringSplitOptions.None);
            for (int i = 0; i < str.Length; i++)
            {
                lParameter.Add("vehicle_" + i, str[i]);
                if (vehicles == "")
                    vehicles = "?";
                else
                    vehicles += ",?";
            }
            str = geofencesStr.Split(new string[] { "@&@" }, StringSplitOptions.None);
            for (int i = 0; i < str.Length; i++)
            {
                lParameter.Add("geofence_" + i, str[i]);
                if (geofences == "")
                    geofences = "?";
                else
                    geofences += ",?";
            }
            string query = "delete from vehicleinplant where vehicleid in (" + vehicles + ") and locationstr in (" + geofences + ") and date(intimestamp)=?";
            lParameter.Add("intimestamp", Convert.ToDateTime(date).ToString("yyyy-MM-dd"));
            return dbx.executeNonQuery(query, lParameter);
        }

