            lParameter.Add("ActionId", actionId);
            lParameter.Add("Level", level);
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            if (dt != null && dt.Rows.Count > 0)
            {
                if (string.IsNullOrEmpty(dt.Rows[0]["Status"].ToString()))
                {
                    query = "update tbl_trans_form_review t set t.ReviewBy=?,t.`Status`=?,t.`Comment`=?,t.DateTime=? where t.ActionId=? and t.`Level`=?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("ReviewBy", reviewBy);
                    lParameter.Add("Status", status);
                    lParameter.Add("Comment", comments);
                    lParameter.Add("DateTime", formatDBDate(DateTime.Now));
                    lParameter.Add("ActionId", actionId);
                    lParameter.Add("Level", level);
                    int res = dbx.executeNonQuery(query, lParameter);
                    if (res > 0)
                    {
                        if (status == "Approve")
                        {
                            query = "select * from tbl_trans_form_key_config t where t.KeyWord=?";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("KeyWord", key);
                            dt = dbx.executeQuery(query, lParameter).Tables[0];
                            if (dt != null && dt.Rows.Count > 0 && Convert.ToInt16(dt.Rows[0]["ReviewLevels"].ToString()) > Convert.ToInt16(level))
                            {
                                query = "INSERT INTO `tbl_trans_form_review` (`ActionId`,`Level`) VALUES (?,?)";
                                lParameter = new Dictionary<string, object>();
                                lParameter.Add("ActionId", actionId);
                                lParameter.Add("Level", Convert.ToInt16(level) + 1);
                                res = dbx.executeNonQuery(query, lParameter);
                                if (res > 0)
                                {
                                    return "Send Mail@&@Review submitted successfully..!";
                                }
                            }
                            return "Review submitted successfully..!";
                        }
                        else
                            return "Rejected at Level " + level + " review..!";
                    }
                    else
                        return "Failed to submit review..!";
                }
                else
                    return "Level " + level + " review is already done by " + dt.Rows[0]["ReviewBy"].ToString();
            }
            else
                return "No approval requests found..!";
        }

