        public string GetReviewStatusByActionId(string actionId)
        {
            string query = "select * from tbl_trans_form_review t where t.ActionId=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("ActionId", actionId);
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            if (dt != null && dt.Rows.Count > 0)
            {
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    if (string.IsNullOrEmpty(dt.Rows[i]["Status"].ToString()))
                        return "Waiting for Level " + (i + 1) + " review";
                    else if (dt.Rows[i]["Status"].ToString() == "Reject")
                        return "Rejected at Level " + (i + 1) + " review";
                    if (i == dt.Rows.Count - 1)
                        return "Approved";
                }
            }
            return "";
        }

