		public string AddTrip(string Vehicle, string Source, string Destination, string Customer, string ExpectedTime, string DriverNumber, string VehicleNumber,string LeadTime, string Km, string Speed, string ChallanNo, string Depature, string LoginUser, string AccountId, string[] DropPoints, string[] ExpTimes)
		{
			DateTime Date = DateTime.Now;
            if (!string.IsNullOrEmpty(Depature))
            {
                DateTime DeptTime = ConvertStringToDateTime(Depature, "day");
                Depature = DeptTime.ToString("yyyy-MM-dd HH:mm:ss");
            }
            else
                Depature = Date.ToString("yyyy-MM-dd HH:mm:ss");

            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();

			try
			{ 
			    string accountName = GetAccountNamebyID(AccountId.ToString());
				bool isBios = accountName.IndexOf("Bios", StringComparison.OrdinalIgnoreCase) >= 0;

				if (isBios)
				{

					query.Append("insert into trip (`VehicleId`, `Source`, `Destination`, `Customer`, `TransitExpectedTime`, `KM` , `Speed`, `DriverNumber`, `AssignedVehicle`, `LeadTime`, `Depature`,AddedBy,DateTime,AccountId) VALUES ");
					query.Append("(?,?,?,?,?,?,?,?,?,?,?,?,?,?)");
					lParameter.Add("VehicleId", Vehicle);
					lParameter.Add("Source", Source);
					lParameter.Add("Destination", Destination);
					lParameter.Add("Customer", Customer);
					lParameter.Add("TransitExpectedTime", ExpectedTime);
					lParameter.Add("KM", Km);
					lParameter.Add("Speed", Speed);  
					lParameter.Add("DriverNumber", DriverNumber);
					lParameter.Add("AssignedVehicle", VehicleNumber);
					lParameter.Add("LeadTime", LeadTime);
					lParameter.Add("Depature", Depature);
					lParameter.Add("AddedBy", LoginUser);
					lParameter.Add("DateTime", formatDBDate(Date));
					lParameter.Add("AccountId", AccountId);


				}
				else
				{
					query.Append("insert into trip (`VehicleId`, `Source`, `Destination`, `Customer`, `TransitExpectedTime`, `KM`, `Speed`, `ChallanNo`, `Depature`,AddedBy,DateTime,AccountId) VALUES ");
					query.Append("(?,?,?,?,?,?,?,?,?,?,?,?)");
					lParameter.Add("VehicleId", Vehicle);
					lParameter.Add("Source", Source);
					lParameter.Add("Destination", Destination);
					lParameter.Add("Customer", Customer);
					lParameter.Add("TransitExpectedTime", ExpectedTime);
					lParameter.Add("KM", Km);
					lParameter.Add("Speed", Speed);
					lParameter.Add("ChallanNo", ChallanNo);
					lParameter.Add("Depature", Depature);
					lParameter.Add("AddedBy", LoginUser);
					lParameter.Add("DateTime", formatDBDate(Date));
					lParameter.Add("AccountId", AccountId);

				}

				string inserted = Convert.ToString(dbx.executeNonQuery(query.ToString(), lParameter));

				if (inserted == "1")
                {
                    query.Clear();
                    lParameter.Clear();
                    query.Append("SELECT Id FROM trip where VehicleId =? ORDER BY Id DESC LIMIT 1");
                    lParameter.Add("VehicleId", Vehicle);
                    string tripId = Convert.ToString(dbx.executeScalar(query.ToString(), lParameter));
                    if (!string.IsNullOrEmpty(tripId))
                    {
                        query.Clear();
                        query.Append("INSERT INTO `droppointsdetails` (`TripId`, `DropPoint`, `ExpArrival`) VALUES ");
                        lParameter.Clear();
                        for (int i = 0; i < DropPoints.Length; i++)
                        {
                            string location = DropPoints[i].ToString();
                            if (!string.IsNullOrEmpty(location))
                            {
                                if (i == 0)
                                    query.Append("(?, ?, ?)");
                                else
                                    query.Append(",(?, ?, ?)");

                                string expAriival = ExpTimes[i].ToString();
                                if (!string.IsNullOrEmpty(expAriival))
                                {
                                    DateTime arivalDateTime = ConvertStringToDateTime(expAriival, "day");
                                    expAriival = formatDBDate(arivalDateTime);
                                }
                                lParameter.Add("TripId" + i, tripId);
                                lParameter.Add("DropPoint" + i, location);
                                lParameter.Add("ExpArrival" + i, expAriival);
                            }
                        }
                        inserted = Convert.ToString(dbx.executeNonQuery(query.ToString(), lParameter));
                    }
                }
                return inserted;
            }
            catch
            {
                return "0";
            }
        }


