		public string EditTrip(string Id, string Vehicle, string Source, string Destination, string Customer, string ExpectedTime, string DriverNumber, string VehicleNumber, string LeadTime, string Km, string Speed, string ChallanNo, string Depature, string LoginUser, string Arrival, string Remarks, string[] DropPoints, string[] ExpTimes)
		{
			if (!string.IsNullOrEmpty(Depature))
            {
                DateTime DeptTime = ConvertStringToDateTime(Depature, "day");
                Depature = formatDBDate(DeptTime);
            }
			int AccID = GetAccountId(getSessionIdFromLogin(LoginUser));
			string AccountName = GetAccountNamebyID(AccID.ToString());
            if (!string.IsNullOrEmpty(Arrival))
            {
                DateTime ArrivalTime = ConvertStringToDateTime(Arrival, "day");
                Arrival = formatDBDate(ArrivalTime);
            }

            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            try
            {
                query.Append("select * from droppointsdetails WHERE TripId=?");
                lParameter.Add("TripId", Id);
                DataTable dropPoints = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                if (dropPoints.Rows.Count > 0)
                {
                    string Query = "DELETE from droppointsdetails WHERE TripId=? AND DeparturedTime IS NULL AND ArrivedTime IS NULL;";
                    string deleted = Convert.ToString(dbx.executeNonQuery(Query, lParameter));

                    Query = "SELECT Destination FROM trip WHERE Id=?";
                    string oldDest = Convert.ToString(dbx.executeScalar(Query, lParameter));
                    if (oldDest != Destination)
                    {
                        Query = "DELETE from droppointsdetails WHERE TripId=? and DropPoint=?";
                        lParameter.Add("DropPoint", oldDest);
                        Convert.ToString(dbx.executeNonQuery(Query, lParameter));
                    }
                }
                lParameter.Clear();
                lParameter.Add("TripId", Id);
                dropPoints = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                int dropUpdt = 0;
                for (int i = 0; i < DropPoints.Length; i++)
                {
                    string location = DropPoints[i].ToString();
                    string expArrival = formatDBDate(ConvertStringToDateTime(ExpTimes[i].ToString(), "day"));
                    string find = "DropPoint='" + location + "'";
                    DataRow[] present = dropPoints.Select(find);
                    if (present.Length > 0)
                    {
                        query.Clear(); lParameter.Clear();
                        query.Append("Update droppointsdetails SET ExpArrival=?  WHERE TripId=? AND DropPoint=? ");
                        lParameter.Add("ExpArrival", expArrival);
                        lParameter.Add("TripId", Id);
                        lParameter.Add("DropPoint", location);
                        dropUpdt += dbx.executeNonQuery(query.ToString(), lParameter);
                    }
                    else
                    {
                        query.Clear(); lParameter.Clear();
                        query.Append("INSERT INTO `droppointsdetails` (`TripId`, `DropPoint`, `ExpArrival`) VALUES (?,?,?)");
                        lParameter.Add("TripId", Id);
                        lParameter.Add("DropPoint", location);
                        lParameter.Add("ExpArrival", expArrival);
                        dropUpdt += dbx.executeNonQuery(query.ToString(), lParameter);
                    }
                }

                query.Clear();
                lParameter.Clear();
				bool isBios = AccountName.IndexOf("Bios", StringComparison.OrdinalIgnoreCase) >= 0;

				if (isBios)
				{
					query.Append("UPDATE trip SET VehicleId =?, Source =?, Destination =?, Customer =?, TransitExpectedTime =?, Speed =?, DriverNumber =?, AssignedVehicle =?, LeadTime =?");
					if (!string.IsNullOrEmpty(Depature))
						query.Append(",Depature=?");
					query.Append(",AddedBy=?,Remarks=? where Id=?");
					
					// Parameter binding
					lParameter.Add("VehicleId", Vehicle);
					lParameter.Add("Source", Source);
					lParameter.Add("Destination", Destination);
					lParameter.Add("Customer", Customer);
					lParameter.Add("TransitExpectedTime", ExpectedTime);
					lParameter.Add("Speed", Speed);
					lParameter.Add("DriverNumber", DriverNumber);
					lParameter.Add("AssignedVehicle", VehicleNumber);
					lParameter.Add("LeadTime", LeadTime);

					if (!string.IsNullOrEmpty(Depature))
						lParameter.Add("Depature", Depature);

					lParameter.Add("AddedBy", LoginUser);
					lParameter.Add("Remarks", Remarks);
					lParameter.Add("Id", Id);
				}
				else
				{
					query.Append("update trip set VehicleId=?,Source=?,Destination=?,Customer=?,TransitExpectedTime=?,KM=?,Speed=?,ChallanNo=?");
					if (!string.IsNullOrEmpty(Depature))
						query.Append(",Depature=?");

					query.Append(",AddedBy=?,Remarks=? where Id=?");
					lParameter.Add("VehicleId", Vehicle);
					lParameter.Add("Source", Source);
					lParameter.Add("Destination", Destination);
					lParameter.Add("Customer", Customer);
					lParameter.Add("TransitExpectedTime", ExpectedTime);
					lParameter.Add("KM", Km);
					lParameter.Add("Speed", Speed);
					lParameter.Add("ChallanNo", ChallanNo);

					if (!string.IsNullOrEmpty(Depature))
						lParameter.Add("Depature", Depature);

					lParameter.Add("AddedBy", LoginUser);
					lParameter.Add("Remarks", Remarks);
					lParameter.Add("Id", Id);
				}
                int tripupdt = dbx.executeNonQuery(query.ToString(), lParameter);
                return Convert.ToString(dropUpdt + tripupdt);
            }
            catch { return "0"; }
        }

