        public DataTable GetDropPointsDetaisById(string TripId)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            DataTable resTbl = new DataTable();

            try
            {
                int Id = Convert.ToInt32(TripId);
                query.Append("select * from droppointsdetails where TripId=?");
                lParameter.Add("TripId", Id);
                resTbl = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            catch (Exception ex)
            {
                try
                {
                    int Id = Convert.ToInt32(TripId);
                    query.Clear(); lParameter.Clear();

                    query.Append("SELECT * FROM (SELECT * FROM droppointsdetails WHERE TripId=? AND (ArrivedTime IS NOT NULL OR DeparturedTime IS NOT NULL) ");
                    query.Append("ORDER BY (case when ArrivedTime IS NULL then DeparturedTime ELSE ArrivedTime END) ) a UNION ");
                    query.Append("SELECT * FROM (SELECT * FROM droppointsdetails WHERE TripId=? AND (ArrivedTime IS NULL and DeparturedTime IS NULL) ) b ");

                    lParameter.Add("TripId1", Id);
                    lParameter.Add("TripId2", Id);
                    resTbl = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                }
                catch (Exception e)
                {
                    return resTbl;
                }
            }
            return resTbl;
        }

