        public string checkAndUpdateDropPtDept(string tripId, string dropPoint, string arrTime, string vehicleNo)
        {
            string depeTime = string.Empty;
            if (!string.IsNullOrEmpty(arrTime))
            {
                arrTime = ConvertStringToDateTime(arrTime, "day").ToString("yyyy-MM-dd HH:mm:ss");

                string query = "SELECT outtimestamp FROM vehicleinplant WHERE vehicleid=? AND locationstr=? AND intimestamp=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", vehicleNo);
                lParameter.Add("locationstr", dropPoint);
                lParameter.Add("intimestamp", arrTime);
                depeTime = Convert.ToString(dbx.executeScalar(query, lParameter));

                if (string.IsNullOrEmpty(depeTime))
                {
                    query = " SELECT outtimestamp FROM vehicleinplant WHERE vehicleid=? AND locationstr=? AND outtimestamp> ?";
                    depeTime = Convert.ToString(dbx.executeScalar(query, lParameter));
                }

                if (!string.IsNullOrEmpty(depeTime))
                {
                    try
                    {
                        depeTime = formatDBDate(Convert.ToDateTime(depeTime));
                    }
                    catch
                    {
                        depeTime = depeTime.Trim(' ');
                    }

                    lParameter.Clear();
                    query = "UPDATE droppointsdetails SET DeparturedTime=? WHERE DropPoint = ? and TripId=?;";
