                    lParameter.Add("locationstr", dropPoint);
                    lParameter.Add("TripId", tripId);
                    string res = Convert.ToString(dbx.executeNonQuery(query, lParameter));
                    return res;
                }
                else
                    return "0";
            }
            else
                return "0";
        }

