        public DataTable GetArrangedVehicleinPlant(DataTable DcInOutList, int timeGap)
        {
            if (DcInOutList.Rows.Count > 1)
            {
                for (int j = 0; j < DcInOutList.Rows.Count - 1; j++)
                {
                    try
                    {
                        if (DcInOutList.Rows[j]["vehicleid"].ToString() == DcInOutList.Rows[j + 1]["vehicleid"].ToString())
                        {
                            if (DcInOutList.Rows[j]["locationstr"].ToString() == DcInOutList.Rows[j + 1]["locationstr"].ToString())
                            {
                                DateTime fstLeft = Convert.ToDateTime(DcInOutList.Rows[j]["outtimestamp"]);
                                DateTime SecIn = Convert.ToDateTime(DcInOutList.Rows[j + 1]["intimestamp"]);
                                if (SecIn.Subtract(fstLeft).TotalSeconds < timeGap)
                                {
                                    DcInOutList.Rows[j]["outtimestamp"] = DcInOutList.Rows[j + 1]["outtimestamp"];
                                    DcInOutList.Rows[j + 1].Delete();
                                    DcInOutList.AcceptChanges();
                                    j = j - 1;
                                }
                            }
                        }
                    }
                    catch { }
                }
            }
            return DcInOutList;
        }

        public DateTime ConvertStringToDateTime(string strDateTime, string first)
        {
            if (!string.IsNullOrEmpty(strDateTime))
            {
                strDateTime = strDateTime.Trim();

                string[] DateTimeArray = strDateTime.Split(' ');
                string date = string.Empty, time = string.Empty, hour = string.Empty, min = string.Empty, sec = string.Empty, format = string.Empty;
                string month = string.Empty, year = string.Empty, day = string.Empty;
                date = DateTimeArray[0].ToString();
                time = DateTimeArray[1].ToString();

                string[] TimeArray = time.Split(':');
                hour = TimeArray[0].ToString();
                min = TimeArray[1].ToString();
                sec = TimeArray[2].ToString();

                if (DateTimeArray.Length == 3)
                {
                    format = DateTimeArray[2].ToString();

                    int ihour = Convert.ToInt32(hour);
                    if (format == "am")
                    {
                        if (ihour == 12)
                            ihour = 0;
                    }
                    else if (format == "pm")
                    {
                        ihour = ihour + 12;
                        if (ihour == 24)
                            ihour = 12;
                    }
                    if (ihour > 24)
                    {
                        ihour = ihour - 12;
                    }
                    hour = Convert.ToString(ihour);
                    time = addZero(hour) + ":" + addZero(min) + ":" + addZero(sec);
                }
                else if (DateTimeArray.Length == 2)
                {
                    time = addZero(hour) + ":" + addZero(min) + ":" + addZero(sec);
                }

                //else if (DateTimeArray.Length == 2)
                //{ 
                //    int ihour = Convert.ToInt32(hour);
                //    if (ihour == 0)
                //    {
                //        time = "12:" + addZero(min) + ":" + addZero(sec) + " am";
                //    }
                //    else if (ihour < 12)
                //    {
                //        time = addZero(hour) + ":" + addZero(min) + ":" + addZero(sec) + " am";
                //    }
                //    else if (ihour >= 12)
                //    {
                //        hour = Convert.ToString(ihour - 12);
                //        if (Convert.ToInt32(hour) == 0)
                //            time = "12:" + min + ":" + sec + " pm";
                //        else if (Convert.ToInt32(hour) > 0)
                //            time = addZero(hour) + ":" + min + ":" + sec + " pm";
                //    }
                //}

                string[] DateArray = date.Split('-');
                if (DateArray.Length != 3)
                    DateArray = date.Split('/');

                if (DateArray.Length == 3)
                {
                    int _date1 = Convert.ToInt32(DateArray[0]);
                    int _date2 = Convert.ToInt32(DateArray[1]);
                    int _date3 = Convert.ToInt32(DateArray[2]);

                    if (_date1 > 31)
                    {
                        year = _date1.ToString();
                        if (!string.IsNullOrEmpty(year))
                        {
                            month = _date2.ToString();
                            day = _date3.ToString();
                        }
                    }
                    else if (_date1 > 12)
                    {
                        day = _date1.ToString();
                        if (!string.IsNullOrEmpty(day))
                        {
                            month = _date2.ToString();
                            year = _date3.ToString();
                        }
                    }
                    else if (_date2 > 12)
                    {
                        day = _date2.ToString();
                        {
                            month = _date1.ToString();
                            year = _date3.ToString();
                        }
                    }
                    else
                    {
                        if (first.ToLower() == "day")
                        {
                            day = _date1.ToString();
                            month = _date2.ToString();
                            year = _date3.ToString();
                        }
                        else if (first.ToLower() == "month")
                        {
                            month = _date1.ToString();
                            day = _date2.ToString();
                            year = _date3.ToString();
                        }
                        else                                        // All condition falses then default consider dd/MM/yyyy 
                        {
                            day = _date1.ToString();
                            month = _date2.ToString();
                            year = _date3.ToString();
                        }
                    }
                    date = year + "-" + addZero(month) + "-" + addZero(day);
                }
                strDateTime = date + " " + time;
                DateTime dateTime = DateTime.MinValue;
                try
                {
                    dateTime = Convert.ToDateTime(strDateTime);
                }
                catch (Exception ex)
                {
                    try
                    {
                        dateTime = DateTime.ParseExact(strDateTime, "yyyy-MM-dd HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture);
                    }
                    catch (Exception e)
                    {
                        try
                        {
                            dateTime = DateTime.ParseExact(strDateTime, "yyyy-MM-dd hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture);

                        }
                        catch
                        {
                            return dateTime;
                        }
                    }
                }
                return dateTime;
            }
            return DateTime.MinValue;
        }

        public string addZero(string givenVal)
        {
            if (Convert.ToInt32(givenVal) < 10)
            {
                givenVal = givenVal.Replace('0', ' ').Trim();
                givenVal = "0" + givenVal;
            }
            return givenVal;
        }

