        public string GetVehicleByDriverLincenceNo(string licence, string login)
        {
            string query = "SELECT c.AssignedVehicleId FROM driverinfo c  WHERE c.LicenceNo=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("LicenceNo", licence.Replace(" ", string.Empty));
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            string AssignedVehicleId = string.Empty;
            if (dt.Rows.Count == 1)
            {
                AssignedVehicleId = dt.Rows[0]["AssignedVehicleId"].ToString();
                return AssignedVehicleId;
            }
            else if (dt.Rows.Count == 0)
            {
                string lstDigitsinLicence = licence.Substring(licence.Length - 6);
                lstDigitsinLicence = "%" + lstDigitsinLicence;
                query = "SELECT c.AssignedVehicleId FROM driverinfo c  WHERE c.LicenceNo LIKE ?;";
                lParameter.Clear();
                dt = dbx.executeQuery(query, lParameter).Tables[0];
                if (dt.Rows.Count == 1)
                    return dt.Rows[0]["AssignedVehicleId"].ToString();
            }

            if (dt.Rows.Count > 1)
            {
                query = "SELECT t2.Value FROM (SELECT i.ActionId,i.EditId FROM tbl_trans_form_action_info i JOIN tbl_trans_form_action a ON i.ActionId=a.Id AND i.EditId=a.EditId WHERE i.FieldId=6 AND i.VALUE=? AND a.ActionBy=?) t1 JOIN tbl_trans_form_action_info t2 ON t1.ActionId=t2.ActionId AND t1.EditId=t2.EditId WHERE FieldId=1;";
                lParameter.Clear();
                lParameter.Add("VALUE", licence);
                lParameter.Add("addedBy", login);
                string driverName = dbx.executeScalar(query, lParameter).ToString();
                if (!string.IsNullOrEmpty(driverName))
                {
                    query = "SELECT c.AssignedVehicleId FROM driverinfo c  WHERE c.NAME=?";
                    lParameter.Clear();
                    lParameter.Add("NAME", driverName);
                    return dbx.executeScalar(query, lParameter).ToString();
                }
                else
                {
                    return "";
                }
            }
            return "";
        }

        public string GetLincenceByVehicleNo(string vehicleno, string login)
        {
            try
            {
                string query = "SELECT c.LicenceNo FROM driverinfo c WHERE c.AssignedVehicleId=?;";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AssignedVehicleId", vehicleno);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                string licenceNo = string.Empty;
                if (dt.Rows.Count == 1)
                {
                    return dt.Rows[0]["LicenceNo"].ToString();
                }
                else if (dt.Rows.Count == 0)
                {
                    string last4digit = vehicleno.Substring(vehicleno.Length - 4);
                    string likeVehicleNo = vehicleno.Substring(0, 4) + "%" + last4digit;

                    query = "SELECT c.NAME,c.LicenceNo FROM driverinfo c WHERE c.AssignedVehicleId like =?;";
                    lParameter.Clear();
                    lParameter.Add("likeVehicleNo", likeVehicleNo);
                    dt = dbx.executeQuery(query, lParameter).Tables[0];

                    if (dt.Rows.Count == 1)
                    {
                        return dt.Rows[0]["LicenceNo"].ToString();
                    }
                }

                if (dt.Rows.Count == 2)
                {
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        if (!string.IsNullOrEmpty(dt.Rows[i]["LicenceNo"].ToString()))
                        {
                            if (licenceNo == string.Empty)
                                licenceNo += dt.Rows[i]["LicenceNo"].ToString();
                            else
                                licenceNo += "," + dt.Rows[i]["LicenceNo"].ToString();
                        }

                    }
                    return licenceNo;
                }
                else
                {
                    return "";
                }
            }
            catch (Exception e) { return ""; }//Added by suvarna on 11/3/2021 to handle null values
        }

        public string insertICTRequest(string reqFor, string ReqType, string username, string fieldId, string oldvalue, string newValue, string remark, int level, int accountid)
        {
            DateTime Dtime = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());

            string query = "INSERT INTO `tbl_trans_form_request` (RequestFor, `RequestType`, `RequestedBy`, `RequestedOn`, AccountId) VALUES (?, ?, ?, ?, ?);";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("RequestFor", reqFor);
            lParameter.Add("RequestType", ReqType);
            lParameter.Add("RequestedBy", username);
            lParameter.Add("RequestedOn", formatDBDate(Dtime));
            lParameter.Add("AccountId", accountid);
            string res = dbx.executeNonQuery(query, lParameter).ToString();
            if (res == "1")
            {
                query = "SELECT MAX(Id) FROM tbl_trans_form_request where RequestedBy=?;";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("RequestedBy", username);
                string id = dbx.executeScalar(query, lParameter).ToString();
                query = "INSERT INTO `tbl_trans_form_request_info` (`RequestId`, `FieldId`, `OldValue`, `NewValue`, `Comment`, Level) VALUES (?, ?, ?, ?, ?, ?);";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("RequestId", id);
                lParameter.Add("FieldId", fieldId);
                lParameter.Add("OldValue", oldvalue);
                lParameter.Add("NewValue", newValue);
                lParameter.Add("Comment", remark);
                lParameter.Add("Level", level);
                res = dbx.executeNonQuery(query, lParameter).ToString();
            }
            return res;
        }

