            lParameter.Add("soc", Soc);
            lParameter.Add("batv", BattVolt);
            lParameter.Add("batc", BattCurrent);
            lParameter.Add("cellminv", cellMinVolt);
            lParameter.Add("cellmaxv", cellMaxVolt);
            lParameter.Add("cellminind", minVoltIndex);
            lParameter.Add("cellmaxind", maxVoltIndex);
            lParameter.Add("pdutemp", pduTemp);
            lParameter.Add("celltempmin", mincellTemp);
            lParameter.Add("celltempmax", maxcellTemp);
            lParameter.Add("tempminind", TempMinIndex);
            lParameter.Add("tempmaxind", TempMaxIndex);
            lParameter.Add("ambtemp", AmbientTemp);
            lParameter.Add("pe", prsentEnergy);
            lParameter.Add("pc", presentCapacity);
            lParameter.Add("soh", SOH);
            lParameter.Add("prevmode", prevModeEnergy);

            try
            {
                dbx.executeNonQuery(query, lParameter);
            }
            catch (Exception ex)
            {
                Console.WriteLine(ex.Message);
            }
        }

