        public DataTable GetVetChecklist(string sessionid, string appId, string imei)
        {
            //Added By Madhuri for Vehicle vetting App-Language setting-26-12-2020
            string query = "";
            int groupid = getGroupId(sessionid);
            string query1 = "select LanguageSetting from accountgroups "
             + " where GroupId = " + groupid + " ";
            var lParameter1 = new Dictionary<string, object>();
            var lParameter = new Dictionary<string, object>();
            DataTable dt = dbx.executeQuery(query1, lParameter1).Tables[0];
            if (string.IsNullOrEmpty(imei))
            {
                if (dt.Rows.Count > 0 && !string.IsNullOrEmpty(dt.Rows[0]["LanguageSetting"].ToString()) && dt.Rows[0]["LanguageSetting"].ToString() == "English-English")
                {
                    query = "select c.Id,h.HeaderName,c.RuleName,c.Coefficient,group_Concat(concat('&@&',o.`Option`,'@&@',o.Score)) Options from vet_checklist c join "
                   + "vet_checklist_options o on c.Id=o.ChecklistId join vet_header h on h.Id=c.HeaderId where c.AppId=? and c.AccountId=?  group by c.Id";
                }
                else if (dt.Rows.Count == 0 || string.IsNullOrEmpty(dt.Rows[0]["LanguageSetting"].ToString()))
                {
                    query = "select c.Id,h.HeaderName,c.RuleName,c.Coefficient,group_Concat(concat('&@&',o.`Option`,'@&@',o.Score)) Options from vet_checklist c join "
                   + "vet_checklist_options o on c.Id=o.ChecklistId join vet_header h on h.Id=c.HeaderId where c.AppId=? and c.AccountId=?  group by c.Id";
                }
                else
                {
                    query = "select c.Id,h.HeaderName,ifnull(l.RuleName, c.RuleName) RuleName,c.Coefficient,group_Concat(concat('&@&', o.`Option`, '@&@', o.Score)) Options from "
                + "vet_checklist c join vet_checklist_options o on c.Id = o.ChecklistId join vet_header h on h.Id = c.HeaderId "
                + "left join vet_checklist_language l on l.RuleId = c.Id "
                + "left JOIN accountgroups a ON a.LanguageSetting = l.`Language`  where "
                + "a.GroupId = " + groupid + " and c.AppId = ? group by c.Id";
                }
            }
            //Ended By Madhuri for Vehicle vetting App-Language setting-26-12-2020
            else
            {
                query = "select c.Id,h.HeaderName,ifnull(l.RuleName,c.RuleName) RuleName,c.Coefficient,group_Concat(concat('&@&',o.`Option`,'@&@',o.Score)) Options from "
                    + "vet_checklist c join vet_checklist_options o on c.Id=o.ChecklistId join vet_header h on h.Id=c.HeaderId left join driverinfo d on "
                    + "d.AccountId=c.AccountId and d.IMEI=? left join vet_checklist_language l on l.RuleId=c.Id and l.`Language`=d.DriverLanguagePreference where "
                    + " c.AppId=? and c.AccountId=? group by c.Id";
                lParameter.Add("IMEI", imei);
            }
            lParameter.Add("AppId", appId);
            lParameter.Add("AccountId", GetAccountId(sessionid));
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

