        public string insertDailyDriverChecklistStatus(string driverId, string vehicleId, string submissionId, DateTime submissionDateTime)//developed by zoya on 16/05/2025
        {
            try
            {
                string checkQuery = "SELECT COUNT(*) FROM DailyDriverChecklistStatus WHERE DriverID = ?";
                var checkParams = new Dictionary<string, object>
                {
                    { "DriverID", driverId }
                };

                int recordCount = Convert.ToInt32(dbx.executeScalar(checkQuery, checkParams));

                string result = "";
                if (recordCount > 0)
                {
                    string updateQuery = " UPDATE DailyDriverChecklistStatus SET LatestSubmissionID = ?, LastSubmissionDateTime = ? WHERE DriverID = ?";

                    var updateParams = new Dictionary<string, object>
                    {
                        { "LatestSubmissionID", submissionId },
                        { "LastSubmissionDateTime", submissionDateTime },
                        { "DriverID", driverId }
                    };

                    result = dbx.executeNonQuery(updateQuery, updateParams).ToString();
                }
                else
                {
                    // Insert new record
                    string insertQuery = "INSERT INTO DailyDriverChecklistStatus (DriverID, VehicleID, LatestSubmissionID, LastSubmissionDateTime) VALUES (?, ?, ?, ?)";

                    var insertParams = new Dictionary<string, object>
                    {
                        { "DriverID", driverId },
                        { "VehicleID", vehicleId },
                        { "LatestSubmissionID", submissionId },
                        { "LastSubmissionDateTime", submissionDateTime }
                    };

                    result = dbx.executeNonQuery(insertQuery, insertParams).ToString();
                }

                return result;
            }
            catch (Exception ex)
            {
                return $"Error: {ex.Message}";
            }
        }


