        public void PushChangeDataToAPI(string id, string apiName, string accountid)
        {
            try
            {
                string query = "select * from tbl_push_chng_data t where t.Active=1 and t.API=? and t.AccountId=?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("API", apiName);
                lParameter.Add("AccountId", accountid);
                DataTable dtpush = dbx.executeQuery(query, lParameter).Tables[0];
                for (int i = 0; i < dtpush.Rows.Count; i++)
                {
                    string EndPoint = dtpush.Rows[i]["URL"].ToString();
                    string log = dtpush.Rows[i]["log"].ToString();
                    string PostData = dtpush.Rows[i]["Template"].ToString();
                    string ContentType = dtpush.Rows[i]["ContentType"].ToString();
                    string HTTPMethod = dtpush.Rows[i]["HTTPMethod"].ToString();
                    string Headers = dtpush.Rows[i]["Headers"].ToString();
                    string pushId = dtpush.Rows[i]["id"].ToString();
                    try
                    {
                        if (apiName == "UpdateDriverInfo")
                        {
                            DataTable dt = GetDriverDetailsById(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                PostData = PostData.Replace("<Id>", id);
                                PostData = PostData.Replace("<Name>", Convert.ToString(dt.Rows[0]["Name"]));
                                PostData = PostData.Replace("<Status>", Convert.ToString(dt.Rows[0]["Active"]) == "True" ? "1" : "0");
                                PostData = PostData.Replace("<LicenseNo>", Convert.ToString(dt.Rows[0]["LicenceNo"]));
                            }
                        }
                        else if (apiName == "UpdateDriverInfoNew")
                        {
                            DataTable dt = GetDriverDetailsById(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                PostData = PostData.Replace("<Id>", id);
                                PostData = PostData.Replace("<Name>", Convert.ToString(dt.Rows[0]["Name"]));
                                PostData = PostData.Replace("<Status>", Convert.ToString(dt.Rows[0]["Active"]) == "True" ? "1" : "0");
                                PostData = PostData.Replace("<LicenseNo>", Convert.ToString(dt.Rows[0]["LicenceNo"]));
                                PostData = PostData.Replace("<Aadhar>", Convert.ToString(dt.Rows[0]["AadharNo"]));
                                if (!String.IsNullOrEmpty(Convert.ToString(dt.Rows[0]["MobileNo"])))
                                {
                                    PostData = PostData.Replace("<MobileNo>", Convert.ToString(dt.Rows[0]["MobileNo"]));
                                }
                                else
                                {
                                    PostData = PostData.Replace("<MobileNo>", Convert.ToString(dt.Rows[0]["ContactNo"]));
                                }
                                PostData = PostData.Replace("<LanguagePreference>", Convert.ToString(dt.Rows[0]["DriverLanguagePreference"]));
                                PostData = PostData.Replace("<DOB>", Convert.ToDateTime(dt.Rows[0]["DOB"]).ToString("yyyy-MM-dd"));
                                PostData = PostData.Replace("<DriverImage>", "");
                            }
                        }
                        else if (apiName == "UpdateDriverVehicle")
                        {
                            //DataTable dt = GetDriverVehicleLogByDriverId(id);
                            DataTable dt = GetDriverDetailsById(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                PostData = PostData.Replace("<VehicleId>", Convert.ToString(dt.Rows[0]["AssignedVehicleId"]));
                                PostData = PostData.Replace("<DriverId>", id);
                            }
                        }
                        else if (apiName == "UpdateCustomerInfo")
                        {
                            DataTable dt = GetCustomerDetailsById(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                string pcd_custtype = "";
                                string CustomerType = dt.Rows[0]["CustomerType"].ToString();
                                if (CustomerType == "ALDS")
                                    pcd_custtype = "1";
                                else if (CustomerType == "COMMODITY")
                                    pcd_custtype = "2";
                                else if (CustomerType == "PACKED")
                                    pcd_custtype = "3";
                                else if (CustomerType == "BOOM/BOOT")
                                    pcd_custtype = "4";
                                else if (CustomerType == "STK")
                                    pcd_custtype = "5";
                                else if (CustomerType == "Others")
                                    pcd_custtype = "6";

                                PostData = PostData.Replace("<customercode>", Convert.ToString(dt.Rows[0]["CustomerCode"]));
                                PostData = PostData.Replace("<PlantId>", Convert.ToString(dt.Rows[0]["password"]));
                                PostData = PostData.Replace("<Type>", pcd_custtype);
                                PostData = PostData.Replace("<Name>", Convert.ToString(dt.Rows[0]["Name"]));
                                PostData = PostData.Replace("<Lat>", Convert.ToString(dt.Rows[0]["Lat"]));
                                PostData = PostData.Replace("<Lng>", Convert.ToString(dt.Rows[0]["Lng"]));
                                PostData = PostData.Replace("<Storage>", Convert.ToString(dt.Rows[0]["Storage"]));
                                PostData = PostData.Replace("<RKTM>", Convert.ToString(dt.Rows[0]["Lng"]));
                                PostData = PostData.Replace("<Status>", Convert.ToString(dt.Rows[0]["Active"]) == "True" ? "1" : "0");
                            }
                        }
                        else if (apiName == "UpdateCustomerOrderRequest")
                        {
                            DataTable dt = GetStockRequestByCustId(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                string scheduleDate = dt.Rows[0]["RequiredDate"].ToString();
                                if (!string.IsNullOrEmpty(dt.Rows[0]["rktm"].ToString()))
                                {
                                    long travel_time = Convert.ToInt64((Convert.ToInt64(dt.Rows[0]["rktm"].ToString()) * 3600) / 33);
                                    scheduleDate = formatDBDate(Convert.ToDateTime(dt.Rows[0]["RequiredDate"].ToString()).AddSeconds(-travel_time));
                                }
                                PostData = PostData.Replace("<OrderId>", Convert.ToString(dt.Rows[0]["Id"]));
                                PostData = PostData.Replace("<CustomerCode>", Convert.ToString(dt.Rows[0]["CustomerCode"]));
                                PostData = PostData.Replace("<Quantity>", Convert.ToString(dt.Rows[0]["StockRequest"]));
                                PostData = PostData.Replace("<DeliveryDate>", Convert.ToString(dt.Rows[0]["RequiredDate"]) != "" ?
                                    formatDBDate(Convert.ToDateTime(Convert.ToString(dt.Rows[0]["RequiredDate"]))) : "");
                                PostData = PostData.Replace("<RequestDate>", Convert.ToString(dt.Rows[0]["RequestedOn"]) != "" ?
                                    formatDBDate(Convert.ToDateTime(Convert.ToString(dt.Rows[0]["RequestedOn"]))) : "");
                                PostData = PostData.Replace("<ScheduleDate>", scheduleDate);
                            }
                        }
                        else if (apiName == "UpdateVehicleInfo")
                        {
                            DataTable dt = GetVehicleInfoByVehId(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                PostData = PostData.Replace("<VehicleId>", id);
                                PostData = PostData.Replace("<PlantId>", Convert.ToString(dt.Rows[0]["password"]));
                                PostData = PostData.Replace("<Capacity>", Convert.ToString(dt.Rows[0]["Capacity"]));
                                PostData = PostData.Replace("<VehRegData>", Convert.ToString(dt.Rows[0]["VehRegDate"]));
                            }
                        }
                        else if (apiName == "UpdateTripInfo")
                        {
                            DataTable dt = GetTripInfoById(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                PostData = PostData.Replace("<TripId>", id);
                                PostData = PostData.Replace("<VehicleId>", Convert.ToString(dt.Rows[0]["VehicleID"]));
                                PostData = PostData.Replace("<TripTime>", Convert.ToString(dt.Rows[0]["DateTime"]) != "" ?
                                    formatDBDate(Convert.ToDateTime(Convert.ToString(dt.Rows[0]["DateTime"]))) : "");
                                PostData = PostData.Replace("<NoOfDC>", Convert.ToString(dt.Rows[0]["NoofDcs"]));
                                PostData = PostData.Replace("<LoadCustId>", Convert.ToString(dt.Rows[0]["LoadingCustomerCode"]));

                                string fullPostData = "";
                                string[] splitStr = PostData.Split(new string[] { "<orders>" }, StringSplitOptions.None);
                                string beforeLoopStr = splitStr[0];
                                splitStr = splitStr[1].Split(new string[] { "</orders>" }, StringSplitOptions.None);
                                PostData = splitStr[0];
                                string afterLoopStr = splitStr[1];
                                for (int a = 0; a < dt.Rows.Count; a++)
                                {
                                    string dupPostData = PostData;
                                    dupPostData = dupPostData.Replace("<orderId>", Convert.ToString(dt.Rows[a]["orderid"]));
                                    dupPostData = dupPostData.Replace("<DCNo>", Convert.ToString(dt.Rows[a]["DCNo"]));
                                    dupPostData = dupPostData.Replace("<Quantity>", Convert.ToString(dt.Rows[a]["Quantity"]));
                                    dupPostData = dupPostData.Replace("<CustomerId>", Convert.ToString(dt.Rows[a]["CustomerCode"]));
                                    if (fullPostData != "")
                                        fullPostData += ",";
                                    fullPostData += dupPostData;
                                }
                                PostData = beforeLoopStr + fullPostData + afterLoopStr;
                            }
                        }
                        else if (apiName == "UpdateTripDetails")
                        {
                            DataTable dt = GetTripDetailsById(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                PostData = PostData.Replace("<TripId>", id);
                                PostData = PostData.Replace("<TripEndsOn>", Convert.ToString(dt.Rows[0]["TripEndsOn"]) != "" ?
                                    formatDBDate(Convert.ToDateTime(Convert.ToString(dt.Rows[0]["TripEndsOn"]))) : "");
                            }
                        }
                        else if (apiName == "UpdateDeliveryDetails")
                        {
                            DataTable dt = GetDeliveryDetailsById(id);
                            if (dt != null && dt.Rows.Count > 0)
                            {
                                PostData = PostData.Replace("<OrderId>", id);
                                PostData = PostData.Replace("<DeliveredOn>", Convert.ToString(dt.Rows[0]["DeliveredOn"]) != "" ?
                                    formatDBDate(Convert.ToDateTime(Convert.ToString(dt.Rows[0]["DeliveredOn"]))) : "");
                            }
                        }
                        else if (apiName == "MetroOrderStatusUpdate")
                        {
                            //DataTable dt = GetDriverDetailsById(id);
                            //if (dt != null && dt.Rows.Count > 0)
                            //{
                            PostData = PostData.Replace("<CONSIGNMENTID>", "cons04493005_0");
                            PostData = PostData.Replace("<STATUS>", "OUT_FOR_DELIVERY");
                            PostData = PostData.Replace("<DATE>", "03-01-2023 12:37:10 PM");
                            PostData = PostData.Replace("<TAXINVOICENUM>", "");
                            PostData = PostData.Replace("<REASON>", "");
                            PostData = PostData.Replace("<DRIVERINFO>", "");

                            Headers = Headers.Replace("<TOKEN>", id);
                            //}
                        }
                        string res = MakeHttpRequest(EndPoint, HTTPMethod, ContentType, PostData, Headers);
                        if (log == "1")
                        {
                            query = "insert into tbl_push_chng_data_log(PushId,response,ServerTS,data) values(?,?,?,?)";
                            lParameter = new Dictionary<string, object>();
                            lParameter.Add("PushId", pushId);
                            lParameter.Add("response", res);
                            lParameter.Add("ServerTS", formatDBDate(DateTime.Now));
                            lParameter.Add("data", PostData);
                            dbx.executeNonQuery(query.ToString(), lParameter);
                        }
                    }
                    catch (Exception ex)
                    {
                        //query = "insert into tbl_push_data_log(PushId,response,ServerTS,data) values(?,?,?,?)";

                        query = "insert into tbl_push_chng_data_log(PushId,response,ServerTS,data) values(?,?,?,?)";
                        lParameter = new Dictionary<string, object>();
                        lParameter.Add("PushId", pushId);
                        lParameter.Add("response", ex.ToString());
                        lParameter.Add("ServerTS", formatDBDate(DateTime.Now));
                        lParameter.Add("data", PostData);
                        dbx.executeNonQuery(query.ToString(), lParameter);
                    }
                }
            }
            catch (Exception ex)
            {
                try
                {
                    //string query = "insert into tbl_push_data_log(PushId,response,ServerTS,data) values(?,?,?,?)";
