        public DataTable NokiaViolationReportNotReachableVehicles(string groupId, string date)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query.Append("SELECT DISTINCT  v.VehicleId,c.UID,DATE_FORMAT(l.timestamp,'%Y-%m-%d %T') as timestamp,p.positiontxt,");
            query.Append("l.latitude,l.longitude,d.CT,d.Circle,d.Cluster,d.VehicleUsedFor,d.Vehicle,d.VehicleSupplier,d.VehicleNo,");
            query.Append("d.Engineer,d.EngineerMobileNo,d.EngineerEmpId,d.Remarks,d.VehicleLocationTown,d.EngineerLocationTown,");
            query.Append("d.PresentVehicleType,d.ProposedVehicleType,d.VehicleMake,d.VehicleRegistrationYear,d.TravelonHighway,");
            query.Append("d.HighwayNumber,d.DDTCertificateNo,d.DDTCertificateDate,d.DriverCommercialLicenseNo,d.DriverCommercialLicenseValidaty,d.DDTCompliance,");
            query.Append("d.DriverCommercialLicense,d.CommercialRegistration,d.SixyearsAgeing as 6yearsAgeing,d.DriverMedicalFitness,d.IVMSFunctional,d.FirstAidKitFireExtinguisher,");
            query.Append("d.ThreePointRetractableSeatBelt as 3PointRetractableSeatBelt,d.DriverShoes,d.ReflectiveJackets,d.DeviceID,d.DriverName,d.DriverContactNo,d.CircleInchargeName,");
            query.Append("d.CircleInchargeContactNO,d.ClusterInchargeName,d.ClusterInchargeContactNo,d.ClusterInchargeEmpID,d.WeeklyOFF FROM  vehiclesgroupsmap v  JOIN ");
            query.Append("(SELECT distinct d.vehicleid from daywisevehviosummary d where(d.groupid = ? or d.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid = ?))");
            query.Append(" and d.DATE=? and d.trip_starttime<>'0000-00-00 00:00:00' AND d.vehicleid NOT IN (SELECT DISTINCT e.vehicleid from daywisevehviosummary e ");
            query.Append("WHERE (e.groupid=? OR e.vehicleid in (select vehicleid from vehiclesgroupsmap where groupid=?) ) AND  e.DATE=? AND e.trip_starttime<>'0000-00-00 00:00:00'");
