            query.Append(" left join configdata c on c.TruckID=n.vehicleid and c.ReturnDate is NULL left join lastupdtdata l on l.truckid=n.vehicleid  left join vehiclepositiontxt p on p.truckid=l.truckid");
            query.Append(" left join vehdriver_staticdata d on d.Vehicle=REPLACE(v.VehicleId,' ','') order by d.CT ASC,v.VehicleId ASC,l.timestamp DESC;");
