        public DateTime getMontlyReportLastUpdateTime(string year, string month, string login)
        {
            DateTime Now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff(getSessionIdFromLogin(login))).AddDays(-1);
            string query = "SELECT lastlogdatetime FROM monthlyreportlastlog WHERE `year`=? AND `month`=? AND `login`=?;";
            var lParemeter = new Dictionary<string, object>();
            lParemeter.Add("YEAR", year);
            lParemeter.Add("MONTH", month);
            lParemeter.Add("LOGIN", login);
            DataTable DT = dbx.executeQuery(query, lParemeter).Tables[0];
            if (DT.Rows.Count > 0)
            {
                try { Now = Convert.ToDateTime(DT.Rows[0]["lastlogdatetime"]); }
                catch { }
            }
            else
            {
                query = "INSERT INTO monthlyreportlastlog (`year`, `month`, `login`, `lastlogdatetime`) VALUES (?,?,?,?);";
                lParemeter.Add("lastlogdatetime", formatDBDate(Now));
                dbx.executeNonQuery(query, lParemeter);
            }
            return Now;
        }

