        public string getRegionDestinations(string AccId, string GlAccId, string region, string destinationType = "", string userName = "")
        {
            region = QueryInStrFormat(region);
            string query = "SELECT GROUP_CONCAT(c.LoginUser) FROM customerinfo c WHERE c.CustomerType";
            var lParameter = new Dictionary<string, object>();
            string destTypes = "";
            if (string.IsNullOrEmpty(destinationType))
            {
                destTypes = "'unloading','loading',";
                DataTable allDestType = showCustTypeOnReport(Convert.ToInt32(AccId), userName);
                foreach (DataRow dr in allDestType.Rows)
                {
                    destTypes += "'" + Convert.ToString(dr["customertype"]) + "',";
                }
                destTypes = destTypes.Substring(0, destTypes.Length - 1);
                query += " in (" + destTypes + ") ";
            }
            else if (GlAccId == "2477" && destinationType.ToLower() == "hub")
            {
                destTypes = "'unloading','hub'";
                query += " in (" + destTypes + ") ";
            }
            else
            {
                destTypes = destinationType;
                query += "=? ";
                lParameter.Add("DestinationType", destinationType);
            }
            query += " AND c.Region in (" + region + ")";
            lParameter.Add("Region", region);
            string destination = Convert.ToString(dbx.executeScalar(query, lParameter));
            if (string.IsNullOrEmpty(destination) && !string.IsNullOrEmpty(userName))
            {
                query = "SELECT GROUP_CONCAT(c.LoginUser) FROM customerinfo c JOIN dc_source_destination_mapping m ON c.customerId=m.CustomerId WHERE m.UserLogin=? AND m.`Type`='1' AND c.CustomerType=?;";
                lParameter.Clear();
                lParameter.Add("UserLogin", userName);
                lParameter.Add("CustomerType", destTypes.Replace("'", ""));
                destination = Convert.ToString(dbx.executeScalar(query, lParameter));
            }
            return destination;
        }

