        public DataTable getGatePassEntryForAlerts(string session, string Region, string dclogin, string fromdate, string todate, string destinationType, string destination)
        {
            if (!string.IsNullOrEmpty(Region) && !string.IsNullOrEmpty(dclogin))
            {
                string AccId = Convert.ToString(GetAccountId(session));
                string GlAccId = GetGlobalAccountId(AccId);

                //string DestType = GetReportTypeByStoreType(Convert.ToInt32(AccId),destinationType);

                if (string.IsNullOrEmpty(destination))
                    destination = getRegionDestinations(AccId, GlAccId, Region, destinationType, dclogin);

                destination = QueryInStrFormat(destination);

                dclogin = QueryInStrFormat(dclogin);
                if (!string.IsNullOrEmpty(destination) && !string.IsNullOrEmpty(dclogin))
                {
                    StringBuilder query = new StringBuilder();
                    query.Append("SELECT v.id,v.VehicleID,a.LoadingPoint AS 'Source',s.geofencename AS 'Source_Geofence',v.DATETIME AS 'GatePassGeneratedTime',a.DCNo,v.EWayBillNo,");
                    query.Append("c.NAME AS 'Destination',g.geofencename AS 'Destination_Geofence',c.LoginUser,q.AcknowledgementTime,Sum(a.Quantity) as 'Quantity',");
                    query.Append("Sum(q.ReceivedQuantity) AS 'RevQty',v.IsTripEnds,v.TripEndsOn,v.AddedBy,v.IsCancel,v.VehicleType FROM vehicledctrip v JOIN customerdcassign a ON v.id=a.DCTripId");
                    query.Append(" JOIN dc_quntityinfo q ON a.id=q.CustomerDCAssignId JOIN customerinfo c ON c.customerId=a.CustomerId LEFT JOIN geofencenew g ON g.geofencename=c.GeofenceName ");
                    query.Append(" LEFT JOIN ( SELECT c2.NAME,c2.customerId,g2.geofencename,c2.LoginUser FROM  geofencenew g2 JOIN customerinfo c2 ON c2.GeofenceName=g2.geofencename ");
                    query.Append(" WHERE c2.LoginUser IN (" + dclogin + ")) s ON s.NAME=a.LoadingPoint WHERE v.AddedBy IN (" + dclogin + ") AND c.LoginUser IN (" + destination + ") and v.IsCancel=0 ");
                    query.Append(" AND v.DATETIME BETWEEN ? AND ? GROUP BY v.id;");
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("FromTime", fromdate);
                    lParameter.Add("ToTime", todate);
                    return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                }
                else
                {
                    return null;
                }
            }
            else
            {
                return null;
            }
        }

