        public string QueryInStrFormat(string value)
        {
            string retString = "";
            if (!string.IsNullOrEmpty(value))
            {
                value = value.Replace("'", "");
                string[] valList = value.Split(',');
                int n = 0;
                foreach (string val in valList)
                {
                    if (!string.IsNullOrEmpty(val))
                    {
                        if (n == 0)
                            retString = "'" + val + "'";
                        else
                            retString += ",'" + val + "'";
                        n++;
                    }
                }
                string lstChar = retString.Substring(retString.Length - 1, 1);
                if (lstChar == ",")
                    retString = retString.Substring(0, retString.Length - 1);
            }
            return retString;
        }

