        public DataTable GetNearestRouteList(string sessionid, double lat1, double long1)
        {
            int accid = GetAccountId(sessionid);
            //lat1=12.622876; long1=78.085327;
            string query = "SELECT r.accountid,r.routename,(r.minlat+r.maxlat)/2 latitude,(r.minlong+r.maxlong)/2 longitude, 6376.5 * 2 * ASIN(SQRT( POWER(SIN((" + lat1 + "-" +
            " abs((r.minlat + r.maxlat) / 2)) *pi() / 180 / 2),2) +COS(" + lat1 + " * pi() / 180) * COS(" +
            " abs((r.minlat + r.maxlat) / 2) * pi() / 180) * POWER(SIN((" + long1 + " - (r.minlong + r.maxlong) / 2) * pi() / 180 / 2), 2) )) as distance " +
            " from referenceroutedetail r " +
            " where r.accountid = " + accid + " group by r.routename " +
            " ORDER BY distance limit 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("accid", accid);
            lParameter.Add("lat1", lat1);
            lParameter.Add("long1", long1);
            return dbx.executeQuery(query, lParameter).Tables[0];

        }
