        public string AddEBSDetails(string driverId, string Odometer, string NoOfBrake, string BrakeFrequency, string ABSCount, string RSS1Count, string RSS2Count, string username)
        {
            string Query = string.Empty;
            var lParameter = new Dictionary<string, object>();
            //Query = "insert into idc_ebs_data(DriverId,OdometerValue,NoOfBraking,BrakingFrequency,ABSCount,RSS1Count,RSS2Count,AddedOn,AddedBy) values(?,?,?,?,?,?,?,?,?)";
            Query = "insert into idc_ebs_data(DriverId,OdometerValue,NoOfBraking,BrakingFrequency,ABSCount,RSS1Count,RSS2Count,AddedOn,AddedBy) values (?,?,?,?,?,?,?,?,?)" +
                   " ON DUPLICATE KEY UPDATE DriverId ='" + driverId + "',OdometerValue = '" + Odometer + "',NoOfBraking = '" + NoOfBrake + "',BrakingFrequency = '" + BrakeFrequency + "',ABSCount = '" + ABSCount + "',RSS1Count = '" + RSS1Count + "',RSS2Count = '" + RSS2Count + "',AddedOn = '" + formatDBDate(DateTime.Now) + "',AddedBy = '" + username + "'";
            lParameter.Add("DriverId", driverId);
            lParameter.Add("OdometerValue", Odometer);
            lParameter.Add("NoOfBraking", NoOfBrake);
            lParameter.Add("BrakingFrequency", BrakeFrequency);
            lParameter.Add("ABSCount", ABSCount);
