        public string InsertVehicleRequest(string VehicleType, string task, string remark, string scheduletime, int accountid, string username, string Status)
        {
            string query = "";
            var lParameter = new Dictionary<string, object>();

            string dt = string.Empty;
            if (!String.IsNullOrEmpty(scheduletime))
            {
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(scheduletime, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt = formatDBDate(Convert.ToDateTime(scheduletime));
                }
            }


            string dt1 = "";

            try
            {
                dt1 = formatDBDate(DateTime.ParseExact(DateTime.Now.ToString(), "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

            }
            catch (Exception e)
            {
                dt1 = formatDBDate(Convert.ToDateTime(DateTime.Now.ToString()));
            }



            query = "INSERT INTO `bial_vehiclerequest` (`VehicleType`, `Task`, `Remark`,`ScheduleTime`,`AccountId`,`UserName`,Status,RequestedOn) VALUES (?,?,?,?,?,?,?,?)";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleType", VehicleType);
            lParameter.Add("Task", task);
            lParameter.Add("Remark", remark);
            lParameter.Add("ScheduleTime", dt);
            lParameter.Add("AccountId", accountid);
            lParameter.Add("UserName", username);
            lParameter.Add("Status", Status);
            lParameter.Add("RequestedOn", dt1);
            return dbx.executeNonQuery(query, lParameter).ToString();
        }

        public DataSet GetRequestReportData(string fromdate, string todate, string vehicleType, string Status, int accountid, string username)
        {

            string dt = string.Empty;
            string dt1 = string.Empty;
            if (!String.IsNullOrEmpty(fromdate))
            {
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(fromdate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt = formatDBDate(Convert.ToDateTime(fromdate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    dt1 = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt1 = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            var lParameter = new Dictionary<string, object>();
            string query = "select ID,VehicleType, Task, Remark,ScheduleTime,RequestedOn,Status,AdminRemarks from bial_vehiclerequest where (RequestedOn between? and ?) and AccountId=? and UserName=? ";
            lParameter.Add("fromdate", dt);
            lParameter.Add("todate", dt1);
            lParameter.Add("AccountId", accountid);
            lParameter.Add("username", username);
            if (Status != "All")
            {
                query += " and Status=?";
                lParameter.Add("Status", Status);
            }
            if (vehicleType != "All")
            {
                query += " and VehicleType=?";
                lParameter.Add("VehicleType", vehicleType);
            }
            query += " order by requestedon desc";
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;

        }
