        public DataTable GetVehicleId(string VehicleType, string username, int accountid)
        {
            //string query = "select distinct a.VehicleId from vehicleinfo a inner join vehicletype d on d.id = a.trucktype inner join vehiclesgroupsmap b on a.VehicleId = b.VehicleId inner join usersgroupsmap c on b.GroupId = c.GroupId left join bial_tripdetails bi on bi.VehicleId=a.VehicleId where c.Login = ? and d.vehicletype = ? and bi.TripStart is null";
            string query = "select res.VehicleId from (select v.VehicleId,(select count(*) from bial_vehiclerequest bvr join bial_tripdetails btd on btd.TripId=bvr.ID "
                + "where bvr.VehicleID=v.VehicleId and bvr.`Status`='Accepted' and btd.TripClosedBy is null) tripCount from usersgroupsmap u join vehiclesgroupsmap v on"
                + " u.GroupId=v.GroupId join vehicles ve on ve.VehicleID=v.VehicleId join vehicleinfo vi on vi.VehicleId=ve.VehicleID join vehicletype vt on "
                + "vt.ID=vi.TruckType where u.Login=? and ve.AccountID=? and vt.VehicleType=?) res where res.tripCount=0";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Login", username);
            lParameter.Add("AccountID", accountid);
            lParameter.Add("vehicletype", VehicleType);
            DataSet vehicles = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = vehicles.Tables[0];
            return table;
        }
