        public string InsertVehicleRequestForm1(string rdbtnval, string Vehicle, string Driver, string AdminRemarks, string ID, int accountid)
        {
            string query1 = "select tripstart from bial_tripdetails where tripid=? ";
            var lParameter1 = new Dictionary<string, object>();
            lParameter1.Add("tripid", ID);
            string query = "";
            var lParameter = new Dictionary<string, object>();
            DataTable dt = dbx.executeQuery(query1, lParameter1).Tables[0];
            if (dt.Rows.Count == 0 || string.IsNullOrEmpty(dt.Rows[0]["tripstart"].ToString()))
            {
                query = "UPDATE bial_vehiclerequest SET Status = ?,AdminRemarks=?  ";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Status", rdbtnval);
                lParameter.Add("AdminRemarks", AdminRemarks);
                if (Vehicle != "Select Vehicle Id" && Vehicle != "")
                {
                    if (rdbtnval != "Rejected")
                    {
                        query += ",VehicleID=?";
                        lParameter.Add("VehicleID", Vehicle);
                    }
                    else
                    {
                        query += ",VehicleID=?";
                        lParameter.Add("VehicleID", null);
                    }

                }
                if (Driver != "Select Driver" && Driver != "")
                {
                    if (rdbtnval != "Rejected")
                    {
                        query += ",DriverId=?";
                        lParameter.Add("DriverId", Driver);
                    }
                    else
                    {
                        query += ",DriverId=?";
                        lParameter.Add("DriverId", null);
                    }
                    query += " WHERE ID = ? and accountid=? ";
                    lParameter.Add("ID", ID);
                    lParameter.Add("AccountId", accountid);
                    return dbx.executeNonQuery(query, lParameter).ToString();
                }
            }
            else
            {
                if (rdbtnval == "Rejected")
                {
                    return "Cannot reject this trip as it is already Started";
                }
                else
                {
                    return "Vehicle is already assigned";

                }
            }
            return "";

        }
