            string dt1 = string.Empty;
            if (!String.IsNullOrEmpty(fromdate))
            {
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(fromdate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt = formatDBDate(Convert.ToDateTime(fromdate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    dt1 = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt1 = formatDBDate(Convert.ToDateTime(todate));
                }
            }

            string query = "select distinct ID,VehicleType, Task, Remark,ScheduleTime,RequestedOn,Status,a.Name,AdminRemarks from bial_vehiclerequest bv inner join accountgroups a on bv.AccountId=a.AccountID inner join usersgroupsmap u on a.groupid = u.groupid  and bv.UserName=u.Login where (RequestedOn between? and ?)  and bv.AccountId=?  ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromdate", dt);
            lParameter.Add("todate", dt1);
            lParameter.Add("AccountId", accountid);
            if (Dept != "All")
            {
                query += " and a.Name =?";
                lParameter.Add("Name", Dept);
            }
            if (Status != "All")
            {
                query += " and Status=?";
                lParameter.Add("Status", Status);
            }
            if (vehicleType != "All")
            {
                query += " and VehicleType=?";
                lParameter.Add("VehicleType", vehicleType);
            }
            query += " order by requestedon desc";
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;

        }
