        public DataTable MetroGetUsageReportDetails(string storeNo, DateTime tripsStartAt, DateTime tripsEndAt)
        {


            string query = "SELECT m.StoreNo,mtd.TripNum as TripSheetNo,mtd.TripDate,mtd.VehicleId as VehicleNo,m.DriverName,m.Mobile as MobileNo,IF( IFNULL(mtd.DriverId,'0') = '0' ,'No','Yes') AS DriverAppUsage  FROM metro_trip_details mtd " +
                "INNER JOIN metro_market_vehicles m ON m.VehicleId = mtd.VehicleId and mtd.StoreNo=m.StoreNo " +
                "WHERE  m.Active = 1 and m.TransporterId=48 ";
            var lParameter = new Dictionary<string, object>();

            //if (!string.IsNullOrEmpty(storeNo.Trim()))
            if (storeNo != "")
            {
                query += " and mtd.StoreNo=?";

                lParameter.Add("StoreNo", storeNo);
            }
            query += "  and mtd.TripDate BETWEEN ? AND ? ";
            lParameter.Add("tripsStartAt", formatDBDate(tripsStartAt));
            lParameter.Add("tripsEndAt", formatDBDate(tripsEndAt));
            query += " ORDER BY m.StoreNo";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
