        public string InsertIntoDriverNotifications(string DriverId, string Subject, string Info, int Priority = 0)
        {
            try
            {
                string currenttime = formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff()));
                string query = "Insert into drivernotification(Driverid,Subject,Info,Date,Priority) values(?,?,?,?,?)";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("DriverId", DriverId);
                lParameter.Add("Subject", Subject);
                lParameter.Add("Info", Info);
                lParameter.Add("currenttime", currenttime);
                lParameter.Add("Priority", Priority);
                int res = dbx.executeNonQuery(query, lParameter);
                DataTable tokens = new DataTable();
                query = "select distinct f.Token from drivernotification d join otp_sessions o on d.driverid=o.userid join firebase_tokens f on f.Login=o.sessionid where "
                    + "  d.driverid in (" + DriverId + ")";
                tokens = dbx.executeQuery(query).Tables[0];
                SendNotificationFromFirebaseCloud(tokens, Info, Subject);
                return res.ToString();
            }
            catch { return "-1"; }
        }
