        public DataTable getIgnitiondata(String vehicleId, String fromDateStr, String toDateStr)
        {
            string query = "select min(p.TimeStamp) as ignitionOn,max(p.TimeStamp) as ignitionOff,p.TruckID from positiondata p ";
            query += " where ((p.Stop = 0 and p.CI != 0) or (p.Speed > 3 and p.CI = 0 and p.Stop = 0)) and p.TruckID= ? and ";
            query += " p.TimeStamp between ? and ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("TruckID", vehicleId);
            lParameter.Add("FromDate", fromDateStr);
            lParameter.Add("Todate", toDateStr);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public int NoOfFingerFails(string Message, string ReqType, string RequestedNumber, string StationNo, string VehicleNo, DateTime ReqTime)
        {
            int fails = 0;
            string query = "SELECT * FROM tbl_req_sms_log l WHERE ReqNumber =? AND l.VehicleNo =? AND l.StationNo =? AND l.ReqTime BETWEEN? AND ? " +
                "AND RepliedTime !='0000-00-00 00:00:00' AND l.ReqType=? ORDER BY ReqTime DESC LIMIT 1;";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("ReqNumber", RequestedNumber);
            lParameter.Add("VehicleNo", VehicleNo);
            lParameter.Add("StationNo", StationNo);
            lParameter.Add("FromTime", formatDBDate(ReqTime.AddHours(-1)));
            lParameter.Add("ToTime", formatDBDate(ReqTime));
            lParameter.Add("ReqType", ReqType);
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            if (dt.Rows.Count > 0) { fails = (int)dt.Rows[0]["FailCount"]; }
            else { fails = 0; }
            return fails;
        }

