        public DataTable MultiFormActionDetails(string keyword, string username, int loginReviewLevel, int fieldId, int AccId)
        {
            string query = "SELECT  DISTINCT  p.ShortName,a.Id,a.KeyWord,a.ActionBy,DATE_FORMAT(a.ActionTime, '%d-%m-%Y %H:%i:%s') as 'ActionTime',i.Value FROM tbl_trans_form_action a " +
                "INNER JOIN tbl_trans_form_action_info i ON i.ActionId = a.Id " +
                "INNER JOIN (SELECT n.ActionId,MAX(n.EditId) AS 'EditId' FROM tbl_trans_form_action_info n WHERE n.FieldId =? GROUP BY n.ActionId) s ON s.ActionId = i.ActionId AND s.EditId = i.EditId " +
                "INNER JOIN transporterinfo p ON p.login = a.ActionBy WHERE a.AccountId = ? AND a.Active = 1 AND i.FieldId = ? ";
            //"AND i.EditId IN (SELECT MAX(t.EditId) FROM tbl_trans_form_action_info t WHERE t.FieldId = ? GROUP BY t.ActionId) ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("FieldId1", fieldId);
            lParameter.Add("AccountId", AccId);
            lParameter.Add("FieldId2", fieldId);
            if (keyword == "All")
            {
                query += "AND a.KeyWord = 'TotalDriverInfo' OR a.KeyWord = 'TotalVehicleInfo' ";
            }
            else
            {
                query += "AND a.KeyWord = ? ";
                lParameter.Add("KeyWord", keyword);
            }
            if (username != "All")
            {
                query += "AND a.ActionBy = ? ";
                lParameter.Add("ActionBy", username);
            }

            query += "AND a.Id NOT IN (SELECT m.ActionId FROM tbl_trans_form_max_level_review m WHERE m.MaxLevelReviewed < ? OR m.MaxLevelReviewed >= ? OR m.MaxLevelReviewed = -1) ORDER BY a.ActionTime DESC";

            lParameter.Add("MaxLevelReviewed1", loginReviewLevel - 1);
            lParameter.Add("MaxLevelReviewed2", loginReviewLevel);
            DataTable dtActionDetails = dbx.executeQuery(query, lParameter).Tables[0];
            return dtActionDetails;
        }
