        public string InsertIctValuesInMainTable(DataTable fieldWithValues, string uniqueVal, string univalTblname, string univalColname, string key)
        {
            univalTblname = univalTblname.Trim();
            DataView dv = fieldWithValues.DefaultView;
            int res = 0;
            DataTable distinctTablename = dv.ToTable(true, "TableName");
            string connectionString = System.Web.Configuration.WebConfigurationManager.AppSettings["dbConnectionString"];
            var conString = connectionString.Split(';').Select(s => s.Split('='));
            conString = conString.Take(conString.Count() - 1).ToArray();
            var DicConString = conString.Take(conString.Count() - 1).ToArray().ToDictionary(k => k[0].Trim(), v => v[1].Trim());
            //string[] dummi = connectionString.Split(';').Select(s => s.Split('='));        
            string dataBase = DicConString["DATABASE"];
            string Query = "SHOW TABLES FROM " + dataBase;
            DataTable tblList = dbx.executeQuery(Query).Tables[0];
            tblList.CaseSensitive = false;
            foreach (DataRow dr in distinctTablename.Rows)
            {
                string tblname = dr["TableName"].ToString();
                if (tblname == univalTblname)
                {
                    string filtertable = "Tables_in_" + dataBase + " ='" + tblname + "'";
                    DataRow[] correctTblname = tblList.Select(filtertable);
                    if (correctTblname.Length == 1)
                        tblname = correctTblname[0].ItemArray[0].ToString();
                    Query = "SHOW COLUMNS from " + tblname;
                    DataTable colList = dbx.executeQuery(Query).Tables[0];
                    colList.CaseSensitive = false;

                    StringBuilder query = new StringBuilder();
                    DataRow[] tblRows = fieldWithValues.Select("TableName='" + tblname + "'");

                    DataRow[] rightColname = colList.Select("Field= '" + univalColname + "'");
                    if (rightColname.Length > 0)
                        univalColname = rightColname[0].ItemArray[0].ToString();
                    Query = "SELECT * FROM " + tblname + " WHERE REPLACE(" + univalColname + ", ' ', '') = REPLACE(?,' ','')";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("Value", uniqueVal);
                    DataTable dt = dbx.executeQuery(Query, lParameter).Tables[0];
                    int c = 1;
                    if (dt.Rows.Count > 0)                              // Value Present in system
                    {
                        lParameter.Clear();
                        string filterval = Convert.ToString(dt.Rows[0][univalColname]);
                        query.Append("update " + tblname + " Set ");
                        foreach (DataRow tbldr in tblRows)
                        {
                            string DataType = string.Empty;
                            string whereCondition = string.Empty;
                            if (!string.IsNullOrEmpty(Convert.ToString(tbldr["Value"])) && !string.IsNullOrEmpty(Convert.ToString(tbldr["ColumnName"])))
                            {
                                string value = Convert.ToString(tbldr["Value"]);
                                string columnName = Convert.ToString(tbldr["ColumnName"]);
                                rightColname = colList.Select("Field='" + columnName + "'");
                                if (rightColname.Length > 0)
                                {
                                    DataRow row = rightColname[0];
                                    value = ConvertICTTableinsertTypeVal(row["Type"].ToString(), value, tblname);
                                    if (!string.IsNullOrEmpty(value))
                                    {
                                        columnName = row["Field"].ToString();
                                        query.Append(columnName + "=?,");
                                        if (value == "b'1")
                                            lParameter.Add("Value" + c, true);
                                        else if (value == "b'0")
                                            lParameter.Add("Value" + c, true);
                                        else
                                            lParameter.Add("Value" + c, value);
                                        c++;
                                    }
                                }
                            }
                        }
                        query.Remove(query.Length - 1, 1);
                        query.Append(" Where " + univalColname + " =?;");
                        lParameter.Add("ColVal", filterval);
                        res = dbx.executeNonQuery(query.ToString(), lParameter);
                    }
                    else
                    {
                        lParameter.Clear();
                        query.Append("INSERT INTO " + tblname + " (");
                        string DataType = string.Empty;
                        string boolQuery = string.Empty; bool[] boolValue = new bool[tblRows.Length - 1]; int boolno = 0;
                        foreach (DataRow tbldr in tblRows)
                        {
                            if (!string.IsNullOrEmpty(Convert.ToString(tbldr["Value"])) && !string.IsNullOrEmpty(Convert.ToString(tbldr["ColumnName"])))
                            {
                                string value = Convert.ToString(tbldr["Value"]);
                                string columnName = Convert.ToString(tbldr["ColumnName"]);
                                rightColname = colList.Select("Field='" + columnName + "'");
                                if (rightColname.Length > 0)
                                {
                                    DataRow row = rightColname[0];
                                    value = ConvertICTTableinsertTypeVal(row["Type"].ToString(), value, tblname);
                                    if (!string.IsNullOrEmpty(value))
                                    {
                                        columnName = row["Field"].ToString();
                                        query.Append(columnName + ",");
                                        if (value == "b'1")
                                        {
                                            //boolQuery += columnName + ",";
                                            //boolValue[boolno] = true;
                                            //boolno++;
                                            lParameter.Add("Value" + c, true);
                                        }
                                        else if (value == "b'0")
                                        {
                                            //boolQuery += columnName + ",";
                                            //boolValue[boolno] = false;
                                            //boolno++;
                                            lParameter.Add("Value" + c, false);
                                        }
                                        else
                                        {
                                            lParameter.Add("Value" + c, value);
                                        }
                                        c++;
                                    }
                                }
                            }
                        }
                        query.Append(boolQuery);
                        query.Remove(query.Length - 1, 1);
                        query.Append(") values (");
                        foreach (var item in lParameter)
                        {
                            query.Append("?,");
                        }
                        query.Remove(query.Length - 1, 1);
                        query.Append(");");
                        res = dbx.executeNonQuery(query.ToString(), lParameter);
                    }
                }
            }
            return Convert.ToString(res);
        }
        public string ConvertICTTableinsertTypeVal(string DataType, string Value, string Table)
        {
            try
            {
                if (DataType.ToLower() == "date" || DataType.ToLower() == "datetime")
                {
                    DateTime Date = ConvertStringToDateTime(Value, "day");
                    if (DataType.ToLower() == "date")
                        Value = Date.ToString("yyyy-MM-dd");
                    else
                        Value = formatDBDate(Date);
                }
                else if (DataType.Contains("bit("))
                {
                    string dValue = "b'1";
                    if (Table.ToLower() == "driverinfo")
                    {
                        if (Value.ToLower().Contains("inactive"))
                            dValue = "b'0";
                    }
                    Value = dValue;
                }
            }
            catch { Value = string.Empty; }
            return Value;
        }
        public DataTable GetFieldsById(string actionId, string fieldsStr)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query.Append("SELECT t2.FieldName,t2.TableName,t2.ColumnName,t1.Value FROM tbl_trans_form_action t JOIN ");
            query.Append(" tbl_trans_form_action_info t1 ON t.Id=t1.ActionId AND t.EditId=t1.EditId JOIN tbl_trans_form_fields ");
            query.Append(" t2 ON t2.Id=t1.FieldId WHERE t.Id=?");
            lParameter.Add("Id", actionId);
            if (!string.IsNullOrEmpty(fieldsStr))
            {
                query.Append(" AND t1.FieldId IN (?);");
                lParameter.Add("FieldIds", fieldsStr);
            }
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }
        public DataTable getUniqueValByKeyId(string keyword, string actionId)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Id", actionId);
            if (string.IsNullOrEmpty(keyword))
            {
                query.Append("SELECT KeyWord FROM tbl_trans_form_action a WHERE a.Id=?;");
                keyword = Convert.ToString(dbx.executeScalar(query.ToString(), lParameter));
                query.Clear();
            }
            query.Append("SELECT t1.VALUE,t2.TableName,t2.ColumnName FROM tbl_trans_form_action t ");
            query.Append("JOIN tbl_trans_form_action_info t1 ON t.Id=t1.ActionId AND t.EditId=t1.EditId JOIN tbl_trans_form_fields t2 ON t2.Id = t1.FieldId ");
            query.Append(" WHERE t.Id=? AND t1.FieldId=(SELECT t3.UniqueFieldId FROM tbl_trans_form_key_config t3 WHERE t3.KeyWord=?)");
            lParameter.Add("KeyWord", keyword);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }

        public int InsertICTMutiformDataIntoMaster(string keyword, int accountid, string username, int actionId)
        {
            string LicenceValidity = "", DOB = "";

            string query = "SELECT ai.Value as 'Requested Value' , ai.ActionId,ff.MasterFieldName,fa.ActionBy,fa.AccountId,ai.ActionId FROM tbl_trans_form_action_info ai " +
                "INNER JOIN(SELECT n.FieldId, MAX(n.EditId) AS 'EditId' FROM tbl_trans_form_action_info n WHERE n.ActionId = ? GROUP BY n.FieldId) s ON s.FieldId = ai.FieldId AND s.EditId = ai.EditId " +
                "INNER JOIN tbl_trans_form_action fa ON fa.Id = ai.ActionId " +
                "INNER JOIN tbl_trans_form_fields ff ON ff.KeyWord = fa.KeyWord AND ff.Id = ai.FieldId " +
                "WHERE ai.ActionId = ? GROUP BY ai.FieldId ORDER BY ai.FieldId; ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("ActionId1", actionId);
            lParameter.Add("ActionId2", actionId);
            DataTable table = dbx.executeQuery(query, lParameter).Tables[0];

            string ActionBy = table.Rows[0][3].ToString().Trim();
            string transid = getTransporterIdByLogin(ActionBy);
            string Accountid = table.Rows[0][4].ToString().Trim();
            string GroupId = getGroupIdByLogin(ActionBy).ToString();

            DataTable dt = new DataTable();
            DataRow dr = dt.NewRow();
            //string query1 = "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'driverinfo'; ";  Modified by zoya due to migration
            string query1 = "call GetTableColumnNames('driverinfo'); ";
            if (keyword == "TotalVehicleInfo")
                //string query1 = "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'vehicleinfo'; "; Modified by zoya due to migration
                query1 = "call GetTableColumnNames('vehicleinfo'); ";
            DataSet DriverColumnName = dbx.executeQuery(query1, lParameter);
            DataTable table1 = DriverColumnName.Tables[0];

            for (int i = 0; i < table1.Rows.Count; i++)
            {
                for (int j = 0; j < table.Rows.Count; j++)
                {

                    if (table.Rows[j][2].ToString().Trim() == table1.Rows[i][0].ToString().Trim())
                    {

                        dt.Columns.Add(table.Rows[j][2].ToString().Trim());
                        dr[table.Rows[j][2].ToString().Trim()] = table.Rows[j][0].ToString().Trim();
                        break;

                    }

                }

            }
            dt.Rows.Add(dr.ItemArray);
            if (keyword == "TotalDriverInfo")
            {
                string query3 = "select count(1) from driverinfo where LicenceNo='" + dt.Rows[0]["LicenceNo"].ToString().Trim() + "'";
                dbx.executeNonQuery(query3.ToString());
                DataSet licencechk = dbx.executeQuery(query3.ToString());
                DataTable table3 = licencechk.Tables[0];
                int Active = 0;
                if (dt.Rows[0]["Active"].ToString().Trim() == "Active")
                {
                    Active = 1;
                }
                else
                {
                    Active = 0;
                }

                if (!String.IsNullOrEmpty(dt.Rows[0]["LicenceValid"].ToString().Trim()))
                {
                    try
                    {
                        LicenceValidity = formatDBDate(DateTime.ParseExact(dt.Rows[0]["LicenceValid"].ToString().Trim(), "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));
                        DOB = formatDBDate(DateTime.ParseExact(dt.Rows[0]["DOB"].ToString().Trim(), "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));

                    }
                    catch (Exception e)
                    {
                        LicenceValidity = formatDBDate(Convert.ToDateTime(dt.Rows[0]["LicenceValid"].ToString().Trim()));
                        DOB = formatDBDate(Convert.ToDateTime(dt.Rows[0]["DOB"].ToString().Trim()));
                    }
                }
