        public DataTable GetRequestValue(int accountid)
        {
            string query = "select distinct Keyword from tbl_trans_form_request_config where Account=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Account", accountid);
            DataSet requesttype = dbx.executeQuery(query, lParameter);
            if (requesttype.Tables.Count > 0)
                return requesttype.Tables[0];
            else
                return null;
        }
