        public Object[] getDriverNameByLicenseNo(string LicenseNo, string VehicleTypeOfChange)
        {
            ArrayList ldrivervehicleList = new ArrayList();
            if (VehicleTypeOfChange == "Select")
            {
                //string query = "select d.Name,d.AssignedVehicleId,d.Transporter from driverinfo d where d.LicenceNo=? ";
                string query = "select d.Name,d.AssignedVehicleId,ti.Name,d.LicenceNo from driverinfo d left join transporterinfo ti on d.Transporter = ti.TransporterId where d.LicenceNo=? ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("LicenseNo", LicenseNo);
                DataTable drivernamevehiclename = dbx.executeQuery(query, lParameter).Tables[0];
                foreach (DataRow lRow in drivernamevehiclename.Rows)
                {
                    ldrivervehicleList.Add(lRow.ItemArray);
                }
            }
            else if (VehicleTypeOfChange == "Driver Change")
            {
                string query = "select d.Name,d.LicenceNo,d.Transporter  from driverinfo d where d.AssignedVehicleId=? and d.DriverId in (select max(d.DriverId) from driverinfo d where d.AssignedVehicleId = ?) group by d.Name,d.LicenceNo,d.Transporter";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AssignedVehicleId", LicenseNo);
                lParameter.Add("AssignedVehicleId1", LicenseNo);
                DataTable drivernamevehiclename = dbx.executeQuery(query, lParameter).Tables[0];

                foreach (DataRow lRow in drivernamevehiclename.Rows)
                {
                    ldrivervehicleList.Add(lRow.ItemArray);
                }
            }
            else if (VehicleTypeOfChange == "Transporter Change")
            {
                string query = "select ti.Name  from vehicleinfo v left join transporterinfo ti on v.Transporter = ti.TransporterId where vehicleid =?  ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", LicenseNo);
                DataTable drivernamevehiclename = dbx.executeQuery(query, lParameter).Tables[0];

                foreach (DataRow lRow in drivernamevehiclename.Rows)
                {
                    ldrivervehicleList.Add(lRow.ItemArray);
                }
            }

            return ldrivervehicleList.ToArray();

        }
