            }
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }


        public void InsertDataIntoDriverInfoTable(int accountid, string username)
        {
            string keyword = "TotalDriverInfo";
            string query = "select CONCAT_WS(' ', AF.Value) as 'Requested Value' , AF.ActionId,f.MasterFieldName,A.ActionBy,A.AccountId,AF.ActionId";
            query += " from tbl_trans_form_fields f inner join tbl_trans_form_action A on A.KeyWord = f.KeyWord";
            query += " inner join tbl_trans_form_action_info AF on AF.FieldId = f.Id and AF.EditId = A.EditId and AF.ActionId = A.Id";
            query += " where f.KeyWord = 'TotalDriverInfo' and A.AccountId = ? and A.ActionBy = ? and AF.ActionId=2177";
            query += " group by AF.Value,AF.ActionId order by A.EditedOn desc";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountid);
            lParameter.Add("ActionBy", username);
            DataSet DriverInfo = dbx.executeQuery(query, lParameter);
            DataTable table = DriverInfo.Tables[0];
            string ActionBy = table.Rows[0][3].ToString().Trim();
            string transid = getTransporterIdByLogin(ActionBy);
            string Accountid = table.Rows[0][4].ToString().Trim();
            string GroupId = getGroupIdByLogin(ActionBy).ToString();
            string UserDefinedDriverId = table.Rows[0][5].ToString().Trim();

            DataTable table1 = new DataTable();

            if (keyword == "TotalDriverInfo")
            {
                //string query1 = "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'driverinfo'; ";  Modified by zoya due to migration
                string query1 = "call GetTableColumnNames('driverinfo'); ";
                DataSet DriverColumnName = dbx.executeQuery(query1, lParameter);
                table1 = DriverColumnName.Tables[0];
            }
            else
            {
                //string query1 = "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'vehicleinfo'; ";  Modified by zoya due to migration
                string query1 = "call GetTableColumnNames('vehicleinfo'); ";
                DataSet DriverColumnName = dbx.executeQuery(query1, lParameter);
                table1 = DriverColumnName.Tables[0];
            }



            DataTable dt = new DataTable();
            DataRow dr = dt.NewRow();


            for (int i = 0; i < table1.Rows.Count; i++)
            {
                for (int j = 0; j < table.Rows.Count; j++)
                {

                    if (table.Rows[j][2].ToString().Trim() == table1.Rows[i][0].ToString().Trim())
                    {

                        dt.Columns.Add(table.Rows[j][2].ToString().Trim());
                        dr[table.Rows[j][2].ToString().Trim()] = table.Rows[j][0].ToString().Trim();
                        break;

                    }

                }

            }
            dt.Rows.Add(dr.ItemArray);
            if (keyword == "TotalDriverInfo")
            {
                string query3 = "select count(1) from driverinfo where LicenceNo='" + dt.Rows[0]["LicenceNo"].ToString().Trim() + "'";
                dbx.executeNonQuery(query3.ToString());
                DataSet licencechk = dbx.executeQuery(query3.ToString());
                DataTable table3 = licencechk.Tables[0];
                int Active = 0;
                if (dt.Rows[0]["Active"].ToString().Trim() == "Active")
                {
                    Active = 1;
                }
                else
                {
                    Active = 0;
                }

                if (table3.Rows[0][0].ToString() == "0")
                {


                    string query4 = "insert into driverinfo(Name,LicenceNo,father,LicenceValid,DOB,ContactNo,GroupId,AccountId,Transporter,UserDefinedDriverId,Active) values(?,?,?,?,?,?,?,?,?,?,?)";
                    var lParameter4 = new Dictionary<string, object>();
                    lParameter4.Add("Name", dt.Rows[0]["Name"].ToString().Trim());
                    lParameter4.Add("LicenceNo", dt.Rows[0]["LicenceNo"].ToString().Trim());
                    lParameter4.Add("father", dt.Rows[0]["father"].ToString().Trim());
                    lParameter4.Add("LicenceValid", formatDBDate(Convert.ToDateTime(dt.Rows[0]["LicenceValid"].ToString().Trim())));
                    lParameter4.Add("DOB", formatDBDate(Convert.ToDateTime(dt.Rows[0]["DOB"].ToString().Trim())));
                    lParameter4.Add("ContactNo", dt.Rows[0]["ContactNo"].ToString().Trim());
                    lParameter4.Add("GroupId", GroupId);
                    lParameter4.Add("AccountId1", Accountid);
                    lParameter4.Add("Transporter", transid);
                    lParameter4.Add("UserDefinedDriverId", UserDefinedDriverId);
                    lParameter4.Add("Active", Active);
                    dbx.executeNonQuery(query4.ToString(), lParameter4);
                }
                else
                {


                    string query5 = "update driverinfo set Name=?, LicenceNo= ?,father=?,LicenceValid=?,DOB=?,ContactNo=?,Active=? where LicenceNo=?";
                    var lParameter5 = new Dictionary<string, object>();
                    lParameter5.Add("Name", dt.Rows[0]["Name"].ToString().Trim());
                    lParameter5.Add("LicenceNo", dt.Rows[0]["LicenceNo"].ToString().Trim());
                    lParameter5.Add("father", dt.Rows[0]["father"].ToString().Trim());
                    lParameter5.Add("LicenceValid", formatDBDate(Convert.ToDateTime(dt.Rows[0]["LicenceValid"].ToString().Trim())));
                    lParameter5.Add("DOB", formatDBDate(Convert.ToDateTime(dt.Rows[0]["DOB"].ToString().Trim())));
                    lParameter5.Add("ContactNo", dt.Rows[0]["ContactNo"].ToString().Trim());
                    lParameter5.Add("Active", Active);
                    lParameter5.Add("LicenceNo1", dt.Rows[0]["LicenceNo"].ToString().Trim());

                    dbx.executeNonQuery(query5.ToString(), lParameter5);

                }
            }
            else
            {
                string query3 = "select count(1) from vehicleinfo where REPLACE(VehicleId,' ','')='" + dt.Rows[0]["VehicleId"].ToString().Trim().Replace(" ", "") + "'";
                dbx.executeNonQuery(query3.ToString());
                DataSet licencechk = dbx.executeQuery(query3.ToString());
                DataTable table3 = licencechk.Tables[0];
                if (table3.Rows[0][0].ToString() == "0")
                {
                    string query4 = "insert into vehicleinfo(VehicleId,EngineNo,YearOfManufacturer,SeatBelt,Model,TankManfDate,UnladenWeight,Capacity,TruckType) values(?,?,?,?,?,?,?,?,?)";
                    var lParameter4 = new Dictionary<string, object>();
                    lParameter4.Add("VehicleId", dt.Rows[0]["VehicleId"].ToString().Trim());
                    lParameter4.Add("EngineNo", dt.Rows[0]["EngineNo"].ToString().Trim());
                    lParameter4.Add("YearOfManufacturer", dt.Rows[0]["YearOfManufacturer"].ToString().Trim());
                    lParameter4.Add("SeatBelt", dt.Rows[0]["SeatBelt"].ToString().Trim());
                    lParameter4.Add("Model", dt.Rows[0]["Model"].ToString().Trim());
                    lParameter4.Add("TankManfDate", dt.Rows[0]["TankManfDate"].ToString().Trim());
                    lParameter4.Add("UnladenWeight", dt.Rows[0]["UnladenWeight"].ToString().Trim());
                    lParameter4.Add("Capacity", dt.Rows[0]["Capacity"].ToString().Trim());
                    lParameter4.Add("TruckType", dt.Rows[0]["TruckType"].ToString().Trim());
                    dbx.executeNonQuery(query4.ToString(), lParameter4);
                }
                else
                {
                    //string query5 = "update vehicleinfo set VehicleId=?, EngineNo= ?,YearOfManufacturer=?,SeatBelt=?,Model=?,TankManfDate=?,UnladenWeight=?,Capacity=?,TruckType=? where VehicleId=?";
                    string query5 = "update vehicleinfo set EngineNo= ?,YearOfManufacturer=?,SeatBelt=?,Model=?,TankManfDate=?,UnladenWeight=?,Capacity=?,TruckType=? where VehicleId=?"; var lParameter5 = new Dictionary<string, object>();
                    ///lParameter5.Add("VehicleId", dt.Rows[0]["VehicleId"].ToString().Trim());
                    lParameter5.Add("EngineNo", dt.Rows[0]["EngineNo"].ToString().Trim());
                    lParameter5.Add("YearOfManufacturer", dt.Rows[0]["YearOfManufacturer"].ToString().Trim());
                    lParameter5.Add("SeatBelt", dt.Rows[0]["SeatBelt"].ToString().Trim());
                    lParameter5.Add("Model", dt.Rows[0]["Model"].ToString().Trim());
                    lParameter5.Add("TankManfDate", dt.Rows[0]["TankManfDate"].ToString().Trim());
                    lParameter5.Add("UnladenWeight", dt.Rows[0]["UnladenWeight"].ToString().Trim());
                    lParameter5.Add("Capacity", dt.Rows[0]["Capacity"].ToString().Trim());
                    lParameter5.Add("TruckType", dt.Rows[0]["TruckType"].ToString().Trim());
                    lParameter5.Add("VehicleId1", dt.Rows[0]["VehicleId"].ToString().Trim().Replace(" ", ""));

                    dbx.executeNonQuery(query5.ToString(), lParameter5);

                }

            }

        }
