        public DataTable GetDriverVehicleEditDetails(int accountid, string username, string RequestType, string fromdate, string todate, string EditType)
        {
            string requestedOnDate = DateTime.Now.AddDays(-60).ToString("yyyy-MM-dd"); // Added by zoya to fetch data of only last 60 days It was showing time out for all days data
            string dt = string.Empty;
            string dt1 = string.Empty;
            if (!String.IsNullOrEmpty(fromdate))
            {
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(fromdate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt = formatDBDate(Convert.ToDateTime(fromdate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    dt1 = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt1 = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            string Query = " select distinct (select Value from tbl_trans_form_action_info where ActionId=ta.ActionId  " +
                "and FieldId= case when t.KeyWord='TotalDriverInfo' then 1 when t.KeyWord='TotalvehicleInfo' then 25 end AND EditId = (SELECT MAX(CAST(o.EditId AS SIGNED)) FROM tbl_trans_form_action_info o WHERE o.ActionId = ta.ActionId )) Type ,tt.RequestId,tt.Status as 'Status1',t.FieldName,t.FieldType,tt.OldValue,tt.NewValue,DATE_FORMAT(ta.Requestedon, '%d-%m-%Y %H:%i:%s') as 'RequestedOn'," +
                //"CASE WHEN (trr.MaxLevelReviewed) = ReviewLevel THEN 'Done' " +
                //"ELSE concat('Pending for Review Level ', (trr.MaxLevelReviewed) + 1) END as Status   " +
                "CASE WHEN (tt.`Level`) = ReviewLevel THEN 'Done' " +
                "ELSE concat('Pending for Review Level ', (tt.`Level`) + 1) END as Status   " +
                "from tbl_trans_form_request ta inner join tbl_trans_form_fields t on t.KeyWord=ta.RequestFor " +
                "inner join tbl_trans_form_request_info tt on t.Id=tt.FieldId and tt.RequestId=ta.Id " +
                //"inner join tbl_trans_form_max_level_review trr on trr.ActionId=ta.ActionId and trr.MaxLevelReviewed=tt.Level " +
                //"inner join tbl_trans_form_max_level_review trr on trr.MaxLevelReviewed=tt.Level " +
                "left join tbl_trans_form_request_config ttr on ttr.KeyWord=t.KeyWord and ttr.RequestType=ta.RequestType " +
                "where ta.RequestType='Edit Entry' and tt.Status IN('Pending','Approved','Rejected') and t.KeyWord=? and ta.AccountId = ? and ta.RequestedBy= ? AND ta.Requestedon > ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("keyword", RequestType);
            lParameter.Add("AccountId", accountid);
            lParameter.Add("ActionBy", username);
            lParameter.Add("Requestedon", requestedOnDate);
            if (dt != "" && dt1 != "")
            {
                Query += " and ta.RequestedOn between ?";
                lParameter.Add("RequestedOn", dt);

                Query += " and ?";
                lParameter.Add("RequestedOn1", dt1);
            }
            //if (username != "All")
            //{
            //    Query += "AND tt.ReviewLogin = ? ";
            //    lParameter.Add("ReviewLogin", username);
            //}
            Query += " group by t.FieldName,tt.OldValue,tt.NewValue,ta.RequestedOn order by ta.RequestedOn desc";
            DataSet ds = dbx.executeQuery(Query, lParameter);
            if (ds.Tables.Count > 0)
                return ds.Tables[0];
            else
                return null;

        }
