        public DataTable GetDriverVehicleEditForApprovalDetails(int accountid, string username, string RequestType, string fromdate, string todate, string EditType, string requestedby, int myReviewLevel)
        {

            string dt = string.Empty;
            string dt1 = string.Empty;
            if (!String.IsNullOrEmpty(fromdate))
            {
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(fromdate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt = formatDBDate(Convert.ToDateTime(fromdate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    dt1 = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt1 = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            string Query = " select distinct (select Value from tbl_trans_form_action_info where ActionId=ta.ActionId  " +
                "and FieldId= case when t.KeyWord='TotalDriverInfo' then 1 when t.KeyWord='TotalvehicleInfo' then 25 end AND EditId = (SELECT MAX(CAST(o.EditId AS SIGNED)) FROM tbl_trans_form_action_info o WHERE o.ActionId = ta.ActionId )) Type ,ta.RequestedBy,tt.RequestId,tt.Status as 'Status1',t.FieldName,t.FieldType,tt.OldValue,tt.NewValue,DATE_FORMAT(ta.RequestedOn, '%d-%m-%Y %H:%i:%s') as 'RequestedOn'," +
                //"CASE WHEN (trr.MaxLevelReviewed) = ReviewLevel THEN 'Done' " +
                //"ELSE concat('Pending for Review Level ', (trr.MaxLevelReviewed) + 1) END as Status   " +
                "CASE WHEN (tt.`Level`) = ReviewLevel THEN 'Done' " +
                "ELSE concat('Pending for Review Level ', (tt.`Level`) + 1) END as Status,p.ShortName   " +
                "from tbl_trans_form_request ta inner join tbl_trans_form_fields t on t.KeyWord=ta.RequestFor " +
                "inner join tbl_trans_form_request_info tt on t.Id=tt.FieldId and tt.RequestId=ta.Id " +
                //"inner join tbl_trans_form_max_level_review trr on trr.ActionId=ta.ActionId and trr.MaxLevelReviewed=tt.Level " +
                //"inner join tbl_trans_form_max_level_review trr on trr.MaxLevelReviewed=tt.Level " +
                "left join tbl_trans_form_request_config ttr on ttr.KeyWord=t.KeyWord and ttr.RequestType=ta.RequestType " +
                "INNER JOIN transporterinfo p ON p.login = ta.RequestedBy where ta.RequestType='Edit Entry' and tt.Status='Pending' and t.KeyWord=? and ta.AccountId = ?   ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("keyword", RequestType);
            lParameter.Add("AccountId", accountid);
            //lParameter.Add("ActionBy", username);
            if (dt != "" && dt1 != "")
            {
                Query += " and ta.RequestedOn between ?";
                lParameter.Add("RequestedOn", dt);

                Query += " and ?";
                lParameter.Add("RequestedOn1", dt1);
            }
            if (requestedby != "All")
            {
                Query += "AND ta.RequestedBy = ? ";
                lParameter.Add("RequestedBy", requestedby);
            }
            Query += " AND ta.Id NOT IN(SELECT m.ActionId FROM tbl_trans_form_max_level_review m WHERE m.MaxLevelReviewed < ? OR m.MaxLevelReviewed >= ? OR m.MaxLevelReviewed = -1)  group by t.FieldName,tt.OldValue,tt.NewValue,ta.RequestedOn order by ta.RequestedOn desc;";
            lParameter.Add("MaxLevelReviewed1", myReviewLevel - 1);
            lParameter.Add("MaxLevelReviewed2", myReviewLevel);
            //Query += " group by t.FieldName,tt.OldValue,tt.NewValue,ta.RequestedOn order by ta.RequestedOn desc";
            DataSet ds = dbx.executeQuery(Query, lParameter);
            if (ds.Tables.Count > 0)
                return ds.Tables[0];
            else
                return null;

        }
        public DataTable GetDriverVehicleInfo(int accountid, string username, string RequestType, string fromdate, string todate)
        {

            string dt = string.Empty;
            string dt1 = string.Empty;
            if (!String.IsNullOrEmpty(fromdate))
            {
                try
                {
                    dt = formatDBDate(DateTime.ParseExact(fromdate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt = formatDBDate(Convert.ToDateTime(fromdate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    dt1 = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    dt1 = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            string Query = " SELECT CASE WHEN t.RequestType = 'New Entry' && t.KeyWord = 'TotaldriverInfo' THEN 'New Driver' " +
                "WHEN t.RequestType = 'New Entry' && t.KeyWord = 'TotalVehicleInfo' THEN 'New Vehicle' " +
                "WHEN t.RequestType = 'Driver Change' && t.KeyWord = 'Driver Change' THEN 'Driver Change' " +
                "WHEN t.RequestType = 'Vehicle Change' && t.KeyWord = 'Vehicle Change' THEN 'Vehicle Chang' " +
                //"ELSE 'Transporter Change' END as Type,  CONCAT_WS(' ', AF.Value) as 'Requested Value',  A.ActionTime as 'Created Date',A.EditedOn as 'Last Modified Date',  CASE WHEN max(trr.MaxLevelReviewed) = t.ReviewLevel THEN 'Done'  ELSE concat('Pending for Review Level ',  max(trr.MaxLevelReviewed) + 1) END as Status" +
                "ELSE 'Transporter Change' END as Type,  CONCAT_WS(' ', AF.Value) as 'Requested Value',  DATE_FORMAT(A.ActionTime, '%d-%m-%Y %H:%i:%s') as 'Created Date',A.EditedOn as 'Last Modified Date',  CASE WHEN max(trr.MaxLevelReviewed) = t.ReviewLevel THEN 'Done' WHEN max(trr.MaxLevelReviewed) = -1 THEN 'Rejected'  ELSE concat('Pending for Review Level ',  max(trr.MaxLevelReviewed) + 1) END as Status" +
                ",AF.ActionId from tbl_trans_form_fields f inner join tbl_trans_form_action A on A.KeyWord = f.KeyWord " +
                "inner join tbl_trans_form_action_info AF on AF.FieldId = f.Id and AF.EditId = A.EditId and AF.ActionId = A.Id" +
                " left join tbl_trans_form_request_config t  on t.keyword = f.KeyWord" +
                " left join tbl_trans_form_request tr on t.requesttype = tr.RequestType and t.keyword = tr.Requestfor  and tr.actionid = A.id and tr.actionid = AF.actionid" +
                " left join  tbl_trans_form_max_level_review trr on tr.ActionId = trr.ActionId" +
                " where f.keyword = ? and f.Id in (1, 25) and A.AccountId = ? and t.Account=? and A.ActionBy = ? and A.Active = 1 and t.requesttype = 'New Entry' ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("keyword", RequestType);
            lParameter.Add("AccountId", accountid);
            lParameter.Add("AccountId1", accountid);
            lParameter.Add("ActionBy", username);
            if (dt != "" && dt1 != "")
            {
                Query += " and ActionTime between ?";
                lParameter.Add("ActionTime", dt);

                Query += " and ?";
                lParameter.Add("ActionTime1", dt1);
            }
            //Query += " group by AF.value,A.ActionTime,A.EditedOn,trr.MaxLevelReviewed,t.reviewlevel order by A.EditedOn DESC";
            Query += " group by AF.value,A.ActionTime,A.EditedOn order by A.EditedOn DESC";
            lParameter.Add("fromdate", dt);
            lParameter.Add("todate", dt1);
            DataSet ds = dbx.executeQuery(Query, lParameter);
            if (ds.Tables.Count > 0)
                return ds.Tables[0];
            else
                return null;

        }
