            //{
            //    Query += " AND t.Id NOT IN(SELECT m.ActionId FROM tbl_trans_form_max_level_review m join tbl_trans_form_request tr on tr.RequestedOn=m.TimeStamp AND m.ActionId=tr.ActionId and tr.RequestFor = ? WHERE m.MaxLevelReviewed < ? OR m.MaxLevelReviewed >= ? OR m.MaxLevelReviewed = -1) ";
            //    lParameter.Add("ChangeType1", RequestType);
            //    lParameter.Add("MaxLevelReviewed1", MaxLevelReviewed );
            //    lParameter.Add("MaxLevelReviewed2", MaxLevelReviewed + 1);
            //}

