        public void SendMailForICTNewInduction(string RequestedType, string RequestedEntryType, string VehicleNo, string DriverName, string LicenseNo, string username, int accountid, string RequestedDate, string Status, string Remarks)
        {
            //string key = "ChangeRequest";
            string[] filepaths = new string[] { };
            bool emailsByLogin = true;
            string requestFor = "";
            if (RequestedType == "TotalDriverInfo")
            {
                requestFor = "Driver";
            }
            else if (RequestedType == "TotalVehicleInfo")
            {
                requestFor = "Vehicle";
            }
            string subject = "ICT: New Induction Request for " + requestFor + " from " + username;
            string additionalMailIds = "";
            String emailServer = System.Web.Configuration.WebConfigurationManager.AppSettings["emailServer"];
            string FromMail = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailId"];
            string Password = System.Web.Configuration.WebConfigurationManager.AppSettings["ReportingEmailPassword"];
            if (String.IsNullOrEmpty(emailServer))
                emailServer = "localhost";
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
            string emailBodyHeader = "Dear Sir/Madam,<br/>";
            string emailBodyFooter = "\n<br/><br/>Best Regards,<br/>Sensel Telematics Pvt. Ltd.<br/><br/>Note: Please do not reply to this mail as this is an auto-generated email.";
            string login = "";
            //if (emailsByLogin)
            //login = getUserId(sessionId);
            string emailBody = "<html><body style='font-family: Calibri;'>";
            if (RequestedType == "TotalDriverInfo")
            {
                emailBody += "Please find below details of " + requestFor + "<br/><br/>";
                if (!string.IsNullOrEmpty(DriverName))
                    emailBody += "Driver Name: " + DriverName + "<br/>";
                if (!string.IsNullOrEmpty(LicenseNo))
                    emailBody += "License No: " + LicenseNo + "<br/>";
                if (!string.IsNullOrEmpty(Status))
                    emailBody += "Status: " + Status + "<br/>";
                if (!string.IsNullOrEmpty(username))
                    emailBody += "Requested By: " + username + "<br/>";
                if (!string.IsNullOrEmpty(RequestedDate))
                    emailBody += "Requested On: " + RequestedDate + "<br/>";
            }
            else if (RequestedType == "TotalVehicleInfo")
            {
                emailBody += "Please find below details of " + requestFor + "<br/><br/>";
                if (!string.IsNullOrEmpty(VehicleNo))
                    emailBody += "Vehicle No: " + VehicleNo + "<br/>";
                if (!string.IsNullOrEmpty(Status))
                    emailBody += "Status: " + Status + "<br/>";
                if (!string.IsNullOrEmpty(username))
                    emailBody += "Requested By: " + username + "<br/>";
                if (!string.IsNullOrEmpty(RequestedDate))
                    emailBody += "Requested On: " + RequestedDate + "<br/>";
            }

            //Get the Configuration Level
            var lParameter = new Dictionary<string, object>();
            var lParameter1 = new Dictionary<string, object>();
            string query = "SELECT t.ReviewLevel FROM tbl_trans_form_request_config t WHERE t.KeyWord=? AND t.RequestType=? AND t.Account=? ";
            lParameter.Add("KeyWord", RequestedType);
            lParameter.Add("RequestType", RequestedEntryType);
            lParameter.Add("Account", accountid);
            DataTable ReviewLevelData = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            string Level = ReviewLevelData.Rows[0][0].ToString();

            //Get Email Id's For ICT
            string query1 = "SELECT * FROM tbl_trans_form_level_config t WHERE t.`Level` <=? AND t.AccountId =? ";
            lParameter1.Add("Level", Level);
            lParameter1.Add("AccountId", accountid);
            DataTable dtEmailConfig = dbx.executeQuery(query1.ToString(), lParameter1).Tables[0];


            //Added By Tusar on 23/08/2021
            try
            {
                string mailids = dtEmailConfig.Rows[0]["EmailIds"].ToString();
                string cc = dtEmailConfig.Rows[0]["EmailIds_cc"].ToString();

                DataTable dtTransporterDetails = IsTransporter(username);
                string TransporterID = "";
                if (dtTransporterDetails.Rows.Count > 0)
                {
                    TransporterID = dtTransporterDetails.Rows[0]["TransporterId"].ToString();
                }

                string transmailid = GetTransporterMailId(TransporterID);
                if (mailids == "")
                    mailids = transmailid;
                else
                    mailids += "," + transmailid;
                if (mailids != "")

                    try
                    {
                        EmailSender es = new EmailSender(emailServer);
                        es.setupEmail(FromMail, mailids, subject, emailBodyHeader + emailBody + emailBodyFooter, cc);
                        for (int j = 0; j < filepaths.Length; j++)
                        {
                            es.addAttachment(filepaths[j]);
                        }
                        es.setBodyHtml(true);
                        try
                        {
                            es.send(FromMail, Password);
                        }
                        catch (Exception ex)
                        {
                        }
                    }
                    catch (Exception ex)
                    {
                    }
            }
            catch (Exception ex)
            {
            }
        }
