        public void UpdateAssignedVehicleInDriverInfo(string existingVehicleId, string newVehicleId, string existingLicenseNo, string newLicenseNo)
        {
            string correctVehicleNo = GetCorrectVehicleNumber(newVehicleId);
            //Remove Vehicle From Existing Driver
            string query = "UPDATE driverinfo d SET d.AssignedVehicleId='' WHERE Replace(d.AssignedVehicleId,' ','') = ? OR Replace(d.AssignedVehicleId,' ','') = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AssignedVehicleId1", existingVehicleId.Replace(" ", ""));
            lParameter.Add("AssignedVehicleId2", newVehicleId.Replace(" ", ""));
            dbx.executeNonQuery(query, lParameter);

            //Update Vehicle in Driver
            query = "UPDATE driverinfo d SET d.AssignedVehicleId=? WHERE REPLACE(d.LicenceNo, ' ', '') = ? AND d.Active = 1";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("AssignedVehicleId", correctVehicleNo);
            lParameter.Add("LicenceNo", newLicenseNo.Replace(" ", ""));
            int res = dbx.executeNonQuery(query, lParameter);

            if (res != 0)
            {
                string queryNewDriverDetails = "SELECT d.DriverId,d.Name,d.LicenceNo,d.Active,d.AccountId,d.AssignedVehicleId FROM driverinfo d WHERE REPLACE(d.LicenceNo, ' ', '') = ?";
                var lParameter15 = new Dictionary<string, object>();
                lParameter15.Add("LicenceNo", newLicenseNo.Replace(" ", ""));
                DataTable dtNewDriverDetails = dbx.executeQuery(queryNewDriverDetails.ToString(), lParameter15).Tables[0];

                if (dtNewDriverDetails != null)
                {
                    if (dtNewDriverDetails.Rows.Count > 0)
                    {
                        UpdateVehicletoDriverlog(dtNewDriverDetails.Rows[0]["AssignedVehicleId"].ToString());
                        //PushChangeDataToAPI(dtNewDriverDetails.Rows[0]["DriverId"].ToString(), "UpdateDriverVehicle", dtNewDriverDetails.Rows[0]["DriverId"].ToString());
                    }
                }

            }

        }
        public void UpdateAssignedTransporterInVehicleDriverInfo(string ChangeType, string newTransporterId, string LicenseNo, string VehicleNo, string newTransporterName,string accid)
        {
            string query = "";
            var lParameter = new Dictionary<string, object>();

            //Added by Madhuri 15092025
            string RequestedDate = "";
            try
            {
                RequestedDate = formatDBDate(DateTime.ParseExact(DateTime.Now.ToString(), "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

            }
            catch (Exception e)
            {
                RequestedDate = formatDBDate(Convert.ToDateTime(DateTime.Now.ToString()));
            }

            if (ChangeType == "Driver Change")
            {
                //Assign new Transpoter to Driver
                query = "UPDATE driverinfo d SET d.Transporter = ? WHERE Replace(d.LicenceNo,' ','') = ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Transporter", newTransporterId);
                lParameter.Add("LicenceNo", LicenseNo.Replace(" ", ""));
                dbx.executeNonQuery(query, lParameter);

                //string query7 = "SELECT MAX(CAST(o.ActionId AS SIGNED)) FROM tbl_trans_form_action_info o WHERE REPLACE(o.VALUE, ' ', '') = REPLACE(?, ' ', '') AND o.FieldId = 6;";
                string query7 = "SELECT MAX(CAST(o.ActionId AS SIGNED)) FROM tbl_trans_form_action_info o WHERE o.FieldId = 6 AND REPLACE(o.VALUE, ' ', '') = REPLACE(?, ' ', '') AND o.EditId = (SELECT MAX(CAST(i.EditId AS SIGNED)) FROM tbl_trans_form_action_info i WHERE i.ActionId = o.ActionId);";
                var lParameter8 = new Dictionary<string, object>();
                lParameter8.Add("Value", LicenseNo.Replace(" ", ""));
                DataTable ActId = dbx.executeQuery(query7.ToString(), lParameter8).Tables[0];
                string ActionId1 = ActId.Rows[0][0].ToString();

                string Query6 = "update tbl_trans_form_action set ActionBy=? ,EditedOn=? where Id=? and AccountId=? ";
                var lParameter7 = new Dictionary<string, object>();
                lParameter7.Add("ActionBy", newTransporterName);
                lParameter7.Add("EditedOn", RequestedDate);
                lParameter7.Add("Id", ActionId1);
                lParameter7.Add("AccountId", accid);
                dbx.executeNonQuery(Query6.ToString(), lParameter7).ToString();
            }
            else
            {
                //Assign new Transpoter to Vehicle
                query = "UPDATE vehicleinfo v SET v.Transporter = ? WHERE Replace(v.VehicleId,' ','') = ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Transporter", newTransporterId);
                lParameter.Add("VehicleId", VehicleNo.Replace(" ", ""));
                dbx.executeNonQuery(query, lParameter);

                string query7 = "SELECT MAX(CAST(o.ActionId AS SIGNED)) FROM tbl_trans_form_action_info o WHERE REPLACE(o.VALUE, ' ', '') = REPLACE(?, ' ', '') AND o.FieldId = 25;";
                var lParameter8 = new Dictionary<string, object>();
                lParameter8.Add("Value", VehicleNo.Replace(" ", ""));
                DataTable ActId = dbx.executeQuery(query7.ToString(), lParameter8).Tables[0];
                string ActionId1 = ActId.Rows[0][0].ToString();

                string Query6 = "update tbl_trans_form_action set ActionBy=? ,EditedOn=? where Id=? and AccountId=? ";
                var lParameter7 = new Dictionary<string, object>();
                lParameter7.Add("ActionBy", newTransporterName);
                lParameter7.Add("EditedOn", RequestedDate);
                lParameter7.Add("Id", ActionId1);
                lParameter7.Add("AccountId", accid);
                dbx.executeNonQuery(Query6.ToString(), lParameter7).ToString();

            }
        }
        public void UpdateInactiveToActiveDriverInDriverInfo(string ChangeType, string newTransporterId, string LicenseNo, string Requestedby)
        {
            string query = "";
            var lParameter = new Dictionary<string, object>();
            var lParameter1 = new Dictionary<string, object>();
            var lParameter2 = new Dictionary<string, object>();
            var lParameter3 = new Dictionary<string, object>();
            if (ChangeType == "Inactive To Active")
            {
                //Assign new Transpoter to Driver
                query = "UPDATE driverinfo d SET d.Transporter = ? ,d.Active=1 WHERE Replace(d.LicenceNo,' ','') = ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("Transporter", newTransporterId);
                lParameter.Add("LicenceNo", LicenseNo.Replace(" ", ""));
                //dbx.executeNonQuery(query, lParameter);
                int res = dbx.executeNonQuery(query, lParameter);

                if (res != 0)
                {
                    string queryNewDriverDetails = "SELECT d.DriverId,d.Name,d.LicenceNo,d.Active,d.AccountId,d.AssignedVehicleId FROM driverinfo d WHERE REPLACE(d.LicenceNo, ' ', '') = ?";
                    var lParameter15 = new Dictionary<string, object>();
                    lParameter15.Add("LicenceNo", LicenseNo.Replace(" ", ""));
                    DataTable dtNewDriverDetails = dbx.executeQuery(queryNewDriverDetails.ToString(), lParameter15).Tables[0];

                    if (dtNewDriverDetails != null)
                    {
                        if (dtNewDriverDetails.Rows.Count > 0)
                        {
                            PushChangeDataToAPI(dtNewDriverDetails.Rows[0]["DriverId"].ToString(), "UpdateDriverInfo", (dtNewDriverDetails.Rows[0]["AccountId"].ToString()).ToString());
                        }
                    }

                }
            }
            //string query1 = " SELECT MAX(a.ActionId) FROM tbl_trans_form_action_info a WHERE a.Value=? ";
            string query1 = " SELECT MAX(a.ActionId) FROM tbl_trans_form_action_info a where REPLACE(a.Value,' ','')=? ";
            lParameter1.Add("Value", LicenseNo.Replace(" ", ""));
            DataTable MaxActionIdData = dbx.executeQuery(query1.ToString(), lParameter1).Tables[0];
            string MaxActionId = MaxActionIdData.Rows[0][0].ToString();

            if (MaxActionIdData.Rows.Count > 0)
            {
                int EditId = GetMAxEditId(MaxActionId);

                string query2 = "UPDATE tbl_trans_form_action_info d SET d.Value = ?  WHERE d.EditId = ? and d.FieldId=159 and d.ActionId=?";
                lParameter2 = new Dictionary<string, object>();
                lParameter2.Add("Value", "Active");
                lParameter2.Add("EditId", EditId);
                lParameter2.Add("ActionId", MaxActionId);
                dbx.executeNonQuery(query2, lParameter2);

                string query3 = "UPDATE tbl_trans_form_action a SET a.Active=1,a.ActionBy=? WHERE a.Id = ?";
                lParameter3 = new Dictionary<string, object>();
                lParameter3.Add("ActionBy", Requestedby);
                lParameter3.Add("Id", MaxActionId);
                dbx.executeNonQuery(query3, lParameter3);
            }
        }

