        public string MultiformRequestEditDetailsSaveData(string ActionId, string level, string fieldid, string oldvalue, string newvalue, string comment, int accountid, string RequestType, string username, int GetMAxEditId)
        {
            string RequestTypeValue = "Edit Entry";
            string RequestedDate = "";
            try
            {
                RequestedDate = formatDBDate(DateTime.ParseExact(DateTime.Now.ToString(), "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

            }
            catch (Exception e)
            {
                RequestedDate = formatDBDate(Convert.ToDateTime(DateTime.Now.ToString()));
            }
            string Query = "insert into tbl_trans_form_request(ActionId,RequestFor,RequestType,RequestedBy,RequestedOn,AccountId) values(?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("ActionId", ActionId);
