            lParameter.Add("RequestType", RequestTypeValue);
            lParameter.Add("RequestedBy", username);
            lParameter.Add("RequestedOn", RequestedDate);
            lParameter.Add("AccountId", accountid);
            dbx.executeNonQuery(Query.ToString(), lParameter).ToString();

            string query3 = "select max(Id) from tbl_trans_form_request  where ActionId=? ";
            var lParameter3 = new Dictionary<string, object>();
            lParameter3.Add("ActionId", ActionId);
            DataTable RequestData = dbx.executeQuery(query3.ToString(), lParameter3).Tables[0];
            string RequestId = RequestData.Rows[0][0].ToString();

            string Query5 = "update tbl_trans_form_action_info set Value=? where EditId=? and ActionId=? and FieldId=? ";
            var lParameter5 = new Dictionary<string, object>();
            lParameter5.Add("Value", newvalue);
            lParameter5.Add("EditId", GetMAxEditId);
            lParameter5.Add("ActionId", ActionId);
            lParameter5.Add("FieldId", fieldid);
            int res = dbx.executeNonQuery(Query5.ToString(), lParameter5);

            string Query4 = "select * from tbl_trans_form_action_info where Value=? and EditId=? and ActionId=? and FieldId=? ";
            var lParameter4 = new Dictionary<string, object>();
            lParameter4.Add("Value", newvalue);
            lParameter4.Add("EditId", GetMAxEditId);
            lParameter4.Add("ActionId", ActionId);
            lParameter4.Add("FieldId", fieldid);
            DataTable chkexistingdetails = dbx.executeQuery(Query4.ToString(), lParameter4).Tables[0];

            if (chkexistingdetails.Rows.Count == 0)
            {
                string Query17 = "insert into tbl_trans_form_action_info(ActionId,EditId,FieldId,Value) values(?,?,?,?)";
                var lParameter17 = new Dictionary<string, object>();
                lParameter17.Add("ActionId", ActionId);
                lParameter17.Add("EditId", GetMAxEditId);
                lParameter17.Add("FieldId", fieldid);
                lParameter17.Add("Value", newvalue);
                dbx.executeNonQuery(Query17.ToString(), lParameter17).ToString();
            }
            string Query1 = "insert into tbl_trans_form_request_info(RequestId,Level,FieldId,OldValue,NewValue,Comment,Status) values(?,?,?,?,?,?,?)";
            var lParameter1 = new Dictionary<string, object>();
            lParameter1.Add("RequestId", RequestId);
            lParameter1.Add("Level", level);
            lParameter1.Add("FieldId", fieldid);
            lParameter1.Add("OldValue", oldvalue);
            lParameter1.Add("NewValue", newvalue);
            lParameter1.Add("Comment", comment);
            lParameter1.Add("Status", "Pending");
            dbx.executeNonQuery(Query1.ToString(), lParameter1).ToString();

            string Query7 = "insert into tbl_trans_form_action_info_history(ActionId,EditId,FieldId,OldValue,NewValue) values(?,?,?,?,?)";
            var lParameter7 = new Dictionary<string, object>();
            lParameter7.Add("ActionId", ActionId);
            lParameter7.Add("EditId", GetMAxEditId);
            lParameter7.Add("FieldId", fieldid);
            lParameter7.Add("OldValue", oldvalue);
            lParameter7.Add("NewValue", newvalue);
            return dbx.executeNonQuery(Query7.ToString(), lParameter7).ToString();



        }
        public string UpdateICTMultipleFieldsEditDataIntoMaster(string keyword, int accountid, string username, string actionId, string fieldid, string newvalue)
        {
            string LicenceValidity = "", DOB = "";

            string query = "SELECT ai.Value as 'Requested Value' , ai.ActionId,ff.MasterFieldName,fa.ActionBy,fa.AccountId,ai.ActionId FROM tbl_trans_form_action_info ai " +
                "INNER JOIN(SELECT n.FieldId, MAX(n.EditId) AS 'EditId' FROM tbl_trans_form_action_info n WHERE n.ActionId = ? GROUP BY n.FieldId) s ON s.FieldId = ai.FieldId AND s.EditId = ai.EditId " +
                "INNER JOIN tbl_trans_form_action fa ON fa.Id = ai.ActionId " +
                "INNER JOIN tbl_trans_form_fields ff ON ff.KeyWord = fa.KeyWord AND ff.Id = ai.FieldId " +
                "WHERE ai.ActionId = ? GROUP BY ai.FieldId ORDER BY ai.FieldId; ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("ActionId1", actionId);
            lParameter.Add("ActionId2", actionId);
            DataTable table = dbx.executeQuery(query, lParameter).Tables[0];

            string ActionBy = table.Rows[0][3].ToString().Trim();
            string transid = getTransporterIdByLogin(ActionBy);
            string Accountid = table.Rows[0][4].ToString().Trim();
            string GroupId = getGroupIdByLogin(ActionBy).ToString();

            DataTable dt = new DataTable();
            DataRow dr = dt.NewRow();
            //string query1 = "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'driverinfo'; ";  Modified by zoya due to migration
            string query1 = "call GetTableColumnNames('driverinfo'); ";
            if (keyword == "TotalVehicleInfo")
                //string query1 = "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'vehicleinfo'; ";  Modified by zoya due to migration
                query1 = "call GetTableColumnNames('vehicleinfo'); ";
            DataSet DriverColumnName = dbx.executeQuery(query1, lParameter);
            DataTable table1 = DriverColumnName.Tables[0];

            for (int i = 0; i < table1.Rows.Count; i++)
            {
                for (int j = 0; j < table.Rows.Count; j++)
                {

                    if (table.Rows[j][2].ToString().Trim() == table1.Rows[i][0].ToString().Trim())
                    {

                        dt.Columns.Add(table.Rows[j][2].ToString().Trim());
                        dr[table.Rows[j][2].ToString().Trim()] = table.Rows[j][0].ToString().Trim();
                        break;

                    }

                }

            }
            dt.Rows.Add(dr.ItemArray);
            if (keyword == "TotalDriverInfo")
            {
                string query3 = "select count(1) from driverinfo where LicenceNo='" + dt.Rows[0]["LicenceNo"].ToString().Trim() + "'";
                dbx.executeNonQuery(query3.ToString());
                DataSet licencechk = dbx.executeQuery(query3.ToString());
                DataTable table3 = licencechk.Tables[0];
                int Active = 0;
                if (dt.Rows[0]["Active"].ToString().Trim() == "Active")
                {
                    Active = 1;
                }
                else
                {
                    Active = 0;
                }

                if (!String.IsNullOrEmpty(dt.Rows[0]["LicenceValid"].ToString().Trim()))
                {
                    try
                    {
