                        DOB = formatDBDate(DateTime.ParseExact(dt.Rows[0]["DOB"].ToString().Trim(), "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));

                    }
                    catch (Exception e)
                    {
                        LicenceValidity = formatDBDate(Convert.ToDateTime(dt.Rows[0]["LicenceValid"].ToString().Trim()));
                        DOB = formatDBDate(Convert.ToDateTime(dt.Rows[0]["DOB"].ToString().Trim()));
                    }
                }
                if (table3.Rows[0][0].ToString() == "0")
                {
                    //string query4 = "insert into driverinfo(Name,LicenceNo,father,LicenceValid,DOB,ContactNo,GroupId,AccountId,Transporter) values('" + dt.Rows[0]["Name"].ToString().Trim() + "','" + dt.Rows[0]["LicenceNo"].ToString().Trim() + "','" + dt.Rows[0]["father"].ToString().Trim() + "','" + formatDBDate(Convert.ToDateTime(dt.Rows[0]["LicenceValid"].ToString().Trim())) + "','" + formatDBDate(Convert.ToDateTime(dt.Rows[0]["DOB"].ToString().Trim())) + "','" + dt.Rows[0]["ContactNo"].ToString().Trim() + "',?,?,? )";
