        public int GetDubliateEntryInIct(string FieldId, string Value, string key, string sessionId)
        {
            int AccId = GetAccountId(sessionId);
            Value = Regex.Replace(Value, @"\s+", "");
            string query = "SELECT COUNT(*) FROM tbl_trans_form_action_info i JOIN tbl_trans_form_action a ON a.Id=i.ActionId " +
                           " and a.EditId=(SELECT MAX(CAST(o.EditId AS SIGNED)) FROM tbl_trans_form_action_info o WHERE REPLACE(o.VALUE,' ','')=REPLACE(?,' ','')) " +
                           //"SELECT COUNT(*) FROM tbl_trans_form_action_info i JOIN tbl_trans_form_action a ON a.Id=i.ActionId and a.EditId=i.EditId " +
                           //" WHERE i.FieldId=? AND a.KeyWord=? AND a.Active=1 AND REPLACE(i.VALUE,' ','') =? AND a.AccountId=?;";
                           " WHERE i.FieldId=? AND a.KeyWord=? AND REPLACE(i.VALUE,' ','')=REPLACE(?,' ','') AND a.AccountId=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("FieldValue", Value);
            lParameter.Add("FieldId", FieldId);
            lParameter.Add("KeyWord", key);
            lParameter.Add("FieldValue1", Value);
            lParameter.Add("AccountId", AccId);
            return Convert.ToInt32(dbx.executeScalar(query, lParameter));
        }

