        public DataTable GetRecentlyClosedTrip(string SessionId)
        {
            string AccountId = GetAccountId(SessionId).ToString();
            string query = " select cd.id,cd.DCNo,cd.CustomerId,cd.IsDelivered,cd.DeliveredOn,vd.IsTripEnds,vd.TripEndsOn, "
                        + " cd.Quantity,cd.DCTripId,vd.VehicleID,vd.DateTime from customerdcassign cd "
                        + " join vehicledctrip vd on vd.id = cd.DCTripId "
                        + " where vd.AccountId = " + AccountId + " "
                        + " and ((cd.IsDelivered=0 and vd.IsTripEnds=0) "
                        + " or if (cd.IsDelivered=1,cd.DeliveredOn>=date_sub(curdate(), interval 2 day),if(vd.IsTripEnds=1,vd.TripEndsOn>=date_sub(curdate(), interval 2 day),cd.DeliveredOn))) ";
            //+ " order by vd.DateTime Desc ";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", AccountId);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];


        }
