        //Added by Madhuri for ICT Review page
        public DataTable MultiFormActionApprovedDetails(string keyword, int fieldId, int AccId, string username)
        {
            var lParameter = new Dictionary<string, object>();
            string query = " SELECT distinct l.`Level`, r.RequestId,r.ReviewLogin,r.ReviewedBy,DATE_FORMAT(r.ReviewedOn, '%d-%m-%Y %H:%i:%s') AS 'ReviewedOn',i.Value,a.RequestFor,r.`Comment` " +
                            " FROM tbl_trans_form_request_review r " +
                            " INNER JOIN tbl_trans_form_request a ON a.Id = r.RequestId " +
                            " LEFT JOIN tbl_trans_form_level_config l ON l.`Level`= r.`Level` " +
                            " INNER JOIN tbl_trans_form_action_info i ON i.ActionId = a.ActionId " +
                            " INNER JOIN(SELECT n.ActionId, MAX(n.EditId) AS 'EditId' FROM tbl_trans_form_action_info n " +
                            " WHERE n.FieldId =? GROUP BY n.ActionId) s ON s.ActionId = i.ActionId AND s.EditId = i.EditId " +
                            " AND a.AccountId = ? AND i.FieldId = ? ";
            lParameter.Add("FieldId1", fieldId);
            lParameter.Add("AccountId", AccId);
            lParameter.Add("FieldId", fieldId);
            if (keyword == "All")
            {
                query += "AND a.RequestFor = 'TotalDriverInfo' OR a.RequestFor = 'TotalVehicleInfo' ";
            }
            else
            {
                query += "AND a.RequestFor = ? ";
                lParameter.Add("RequestFor", keyword);
            }
            if (username != "All")
            {
                query += "AND r.ReviewLogin = ? ";
                lParameter.Add("ReviewLogin", username);
            }
            query += "ORDER BY r.ReviewedOn DESC ";
            DataTable dtActionDetails = dbx.executeQuery(query, lParameter).Tables[0];
            return dtActionDetails;
        }
