        {
            var lParameter = new Dictionary<string, object>();
            string query = "SELECT distinct a.RequestFor,r.Level, r.ReviewedOn,r.ReviewLogin,r.ReviewedBy,r.Comment,t.Id,t.ChangeType,t.RequestType,t.ExistingVehicleId,t.NewVehicleId,ti.Name as 'ExistingTransporterId',ta.Name as 'NewTransporterId',t.ExistingDriverName,t.NewDriverName,t.ExistingDriverLicenseNo,t.NewDriverLicenseNo,DATE_FORMAT(t.RequestDate, '%d-%m-%Y %H:%i:%s') as 'RequestDate',t.`Status`,DATE_FORMAT(t.MaintenanceStartDate, '%d-%m-%Y %H:%i:%s') as 'MaintenanceStartDate',DATE_FORMAT(t.MaintenanceEndDate, '%d-%m-%Y %H:%i:%s') as 'MaintenanceEndDate' " +
                           " FROM tbl_trans_form_request_review r " +
                           " INNER JOIN tbl_trans_form_request a ON a.Id = r.RequestId " +
                           " INNER JOIN tbl_trans_form_driverchangelog t ON t.Id = a.ActionId " +
                           " left join transporterinfo ti on t.ExistingTransporterId = ti.TransporterId " +
                           " left join transporterinfo ta on t.NewTransporterId = ta.TransporterId " +
                           " WHERE a.AccountId = ? AND a.RequestFor = ? ";
            lParameter.Add("AccountId", AccId);
            lParameter.Add("RequestFor", keyword);
            if (username != "All")
            {
                query += "AND t.RequestedBy = ? ";
                lParameter.Add("RequestedBy", username);
            }
            query += "ORDER BY r.ReviewedOn DESC ";
            DataTable dtActionDetails = dbx.executeQuery(query, lParameter).Tables[0];
            return dtActionDetails;
        }
