        public DataTable GetTripReportDetails(string formDate, string todate, int accountid, string username)
        {
            string frdate = "";
            string tdate = "";
            if (!String.IsNullOrEmpty(formDate))
            {
                try
                {
                    frdate = formatDBDate(DateTime.ParseExact(formDate, "dd/MM/yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    frdate = formatDBDate(Convert.ToDateTime(formDate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    tdate = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    tdate = formatDBDate(Convert.ToDateTime(todate));
                }
            }

            //Modified by Tusar for request type based on admin login
            string admin = "BIAL";
            if (username == "bialhr")
            {
                admin = "HR";
            }
            else if (username == "bialproj")
            {
                admin = "PROJECTS";
            }
            else
            {
                admin = "BIAL";
            }

            string query = "select distinct bv.ContactPerson,bv.MobileNo,bv.RequestType,bv.VehicleSubType,bv.Purpose,bv.LocationName,bv.VehicleId,d.Name,bv.Task,a.Name as 'Requested_by',bv.ScheduleTimeFrom,bt.TripStart,bt.TripEnd,CONCAT(FLOOR(TIMESTAMPDIFF(MINUTE,bt.TripStart,bt.TripEnd)/60),'h ',MOD(TIMESTAMPDIFF(MINUTE,bt.TripStart,bt.TripEnd),60),'m') AS `TotalHrs`,bt.`Status` ";
            query += " from bial_vehiclerequestdetails bv ";
            query += " inner join bial_alltripdetails bt on bv.ID = bt.TripId inner join accountgroups a on bv.AccountId=a.AccountID inner join usersgroupsmap u on a.groupid = u.groupid and bv.UserName=u.Login ";
            query += " inner join driverinfo d on bt.DriverId = d.DriverId where bv.AccountId =? ";
            query += "  and bv.ScheduleTimeFrom BETWEEN ? AND ? and bv.Head = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountid);
            lParameter.Add("formDate", frdate);
            lParameter.Add("todate", tdate);
            lParameter.Add("Admin", admin);
            if (username != "biairportltd" && username != "bialhr" && username != "bialproj")
            {
                query += " and bv.UserName=? ";
                lParameter.Add("UserName", username);
            }
            query += " order by bv.ScheduleTimeFrom desc";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
