        public DataTable getDailyDistanceByAccId(string AccNO, string fromDate, string toDate)

        {
            if (!string.IsNullOrEmpty(AccNO) && Convert.ToInt32(AccNO) > 0)
            {
                try
                {
                    string query = "SELECT d.Date,d.vehicleId,Distance,runTime from dailydistance d JOIN vehicles v ON d.vehicleId=v.VehicleID " +
                        " WHERE v.AccountID=? AND d.DATE>=? and d.DATE<=? order by d.date ASC,d.vehicleId asc;";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("AccountID", AccNO);
                    lParameter.Add("FromDate", fromDate);
                    lParameter.Add("ToDate", toDate);
                    return dbx.executeQuery(query, lParameter).Tables[0];
                }
                catch { return null; }
            }
            else
                return null;
        }

        public DataTable accVehiclesByAccId(string AccId)
        {
            if (!string.IsNullOrEmpty(AccId) && Convert.ToInt32(AccId) > 0)
            {
                StringBuilder accVehiclesQry = new StringBuilder();
                accVehiclesQry.Append("SELECT DISTINCT v.VehicleID FROM vehicles v JOIN vehiclesgroupsmap m ON v.VehicleID=m.VehicleId ");
                accVehiclesQry.Append(" JOIN accounts a ON v.AccountID=a.ID JOIN accountgroups ag ON a.ID=ag.AccountID JOIN usersgroupsmap u ON u.GroupId=ag.GroupId ");
                accVehiclesQry.Append(" WHERE a.ID=? AND u.Login not like '%old%' AND ag.NAME not like '%old%';");
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("AccNo", AccId);
                return dbx.executeQuery(accVehiclesQry.ToString(), lParameter).Tables[0];
            }
            else
            {
                return null;
            }
        }
