        public DataTable LoginVehiclesDailyDistCapacityInfo(string Login, DateTime Date)
        {
            StringBuilder query = new StringBuilder();
            DateTime monStartDate = new DateTime(Date.Year, Date.Month, 1);
            int AccID = GetAccountId(getSessionIdFromLogin(Login));
            var lParameter = new Dictionary<string, object>();
            query.Append("SELECT v.VehicleID,vi.Capacity,d.DISTANCE,s.MthDISTANCE AS 'MonthlyDist',vp.intimestamp,vp.locationstr,d.lastupdated FROM vehicles v LEFT JOIN vehicleinfo vi ON ");
            query.Append(" vi.VehicleId=v.VehicleID LEFT JOIN dailydistancelastupdate d ON (d.vehicleId=v.VehicleID AND d.DATE=?) left JOIN (SELECT d.vehicleId,SUM(d.DISTANCE) AS 'MthDistance'");
            query.Append(" FROM dailydistance d WHERE d.DATE BETWEEN ? AND ? GROUP BY d.vehicleId) s ON s.vehicleId=v.VehicleID  left JOIN (SELECT v1.* FROM vehicleinplant v1 ");
            query.Append(" JOIN (SELECT v.vehicleid, MAX(v.intimestamp) intimestamp FROM vehicleinplant v WHERE (v.outtimestamp IS NULL OR v.outtimedone=0) GROUP BY v.vehicleid) v2");
            query.Append(" ON v1.vehicleid = v2.vehicleid AND v1.intimestamp = v2.intimestamp) vp ON vp.vehicleid=v.VehicleID ");
            query.Append(" WHERE v.VehicleID IN(SELECT m.VehicleId from vehiclesgroupsmap m JOIN usersgroupsmap u ON u.GroupId= m.GroupId WHERE u.Login= ?) AND v.AccountID=? GROUP BY v.VehicleID ORDER BY MthDISTANCE ASC, DISTANCE asc");
            lParameter.Add("DailyDistDate", Date.ToString("yyyy-MM-dd"));
            lParameter.Add("MonthStartDate", monStartDate.ToString("yyyy-MM-dd"));
            lParameter.Add("MonthEndDate", Date.AddDays(-1).ToString("yyyy-MM-dd"));
            lParameter.Add("Login", Login);
            lParameter.Add("AccountID", AccID);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
        }
        public string GetBaseURL()
        {
            String strPathAndQuery = HttpContext.Current.Request.Url.PathAndQuery;
            String sHost = HttpContext.Current.Request.Url.AbsoluteUri.Replace(strPathAndQuery, "/");
            if (String.Equals(HttpContext.Current.Request.ServerVariables["HTTP_X_FORWARDED_PROTO"], "https", StringComparison.OrdinalIgnoreCase))
                sHost = sHost.Replace("http://", "https://");
            return sHost;
        }
