                string query = "SELECT u.PageUrl,u.`Action`,u.ActionTime,'" + login + "' AS Login, u.UserIP,u.Browser FROM useractivity u WHERE u.login=? AND u.ActionTime BETWEEN ? AND ? ORDER BY u.ActionTime;";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("login", login);
                lParameter.Add("fromdate", formatDBDate(fromdate));
                lParameter.Add("todate", formatDBDate(todate));
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                return dt;
            }
            else
                return new DataTable();
        }

        public int GetCanSpeed(string VehicleNo, DateTime dateTime)
        {
            StringBuilder query = new StringBuilder();
            query.Append("SELECT Can_Speed(?,?)");
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleNo", VehicleNo);
            lParameter.Add("dateTime", dateTime);
            try
            {
                DataTable SpeedTbl = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                if (SpeedTbl.Rows.Count > 0)
                    return Convert.ToInt32(SpeedTbl.Rows[0][0]);
                else
                    return 0;
            }
            catch (Exception e) { string mes = e.Message; return 0; }
        }

        public bool VehicleInMaintenance(string vehicleId, string requestTime)
        {
            string query = "SELECT if(COUNT(*)>0,RequestType,'NoRequest') AS 'RequestType' from (SELECT * FROM driverchangelog d WHERE d.VehicleId=? AND d.RequestDate<=? ORDER BY d.RequestDate DESC LIMIT 1) c";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleNo", vehicleId);
            lParameter.Add("dateTime", requestTime);
            string requestName = Convert.ToString(dbx.executeScalar(query.ToString(), lParameter));
            if (!string.IsNullOrEmpty(requestName))
            {
                if (requestName.ToLower().Replace(" ", string.Empty) == "maintenance")
                    return true;
                else
                    return false;
            }
            else
                return false;
        }
