        public DataTable GetDetailedVehicleDriverDetailsInfo(string AccountId, string sessionid, string SelectedVehicleId)
        {
            int groupid = getGroupId(sessionid);
            string query = " SELECT a.`VehicleId`,a.TransName,a.TransNumber,a.TransporterId,a.ABS,a.ChasisNo,a.EngineNo,a.MarkersName,a.Capacity, " +
                          "  a.Articulated,a.TypeOfBody,a.YearOfManufacturer,a.OEMCabin,a.TankManfDate,a.TankMakeModel,a.Logo,a.GPS,a.SeatBelt, " +
                          "  a.Driver,a.DOB,a.MobileNo,a.LicenceNo,a.LicenceValid,a.HazardousLicExpDate,a.DDTDate,a.DDTGrade,a.DDTExpiryDate, " +
                         "   a.MedicalTestDate,a.MediExpDate,a.DriverId,a.Accident,a.UnladenWeight,a.rate,a.ContactNo,a.BrakeValue,a.DriverContactNo,a.DriverLanguagePreference,a.DriverPhoto,a.HazardousLicNo,a.TransEmailId,a.IMEI,a.CrashGuard, " +
                         "   a.DriverAccidentHistory,a.DrivingExp,a.DOJ,a.Plant,a.Dedicated,a.IsContract,a.ContractFrom,a.NoofAxle,a.VehRegDate,a.ContractType,a.ContractValid,a.AuditedDate,a.UnladenWeight,a.TypeOfVehicle,a.TruckType, " +
                         "  max(case when a.rank=1 then a.Driver end) as Driver1, " +
                         "  max(case when a.rank=1 then a.DriverId end) as DriverId1, " +
                         "  if(a.Driver!='',max(case when a.rank=2 then a.Driver END),'') as Driver2, " +
                         " max(case when a.rank=2 then a.DriverId end) as DriverId2 " +
                         " from(select *,CASE n.VehicleId " +
                         "   WHEN @VehicleId  " +
                         "   THEN @VehicleId := @curRow + 1 " +
                         "  ELSE @curRow := 1 " +
                         "  END AS 'rank', @VehicleId := n.VehicleId AS VehicleIds  " +
                         " from(SELECT i.`VehicleId`,t.Name as TransName,t.TransNumber,t.TransporterId,i.ABS,i.ChasisNo,i.EngineNo,i.MarkersName,i.Capacity, " +
                         "    i.Articulated,i.TypeOfBody,i.YearOfManufacturer,i.OEMCabin,i.TankManfDate,i.TankMakeModel,i.Logo,i.GPS,i.SeatBelt, " +
                         "   d.Name as Driver,d.DOB,d.MobileNo,d.LicenceNo,d.LicenceValid,d.HazardousLicExpDate,d.DDTDate,d.DDTGrade,d.DDTExpiryDate, " +
                          "  d.MedicalTestDate,d.MediExpDate,d.DriverId,i.Accident,i.UnladenWeight,i.rate,i.ContactNo,i.BrakeValue,d.ContactNo as DriverContactNo,d.DriverLanguagePreference,d.DriverPhoto,d.HazardousLicNo,t.EmailId as TransEmailId,d.IMEI,i.CrashGuard, " +
                         "   d.DriverAccidentHistory,d.DrivingExp,d.DOJ,i.Plant,i.Dedicated,i.IsContract,i.ContractFrom,i.NoofAxle,i.VehRegDate,t.ContractType,t.ContractValid,t.AuditedDate,i.TypeOfVehicle,i.TruckType " +
                         "   FROM vehicles v  " +
                         "   left join `vehicleinfo` i on v.VehicleID=i.VehicleId  " +
                         "   left join driverinfo d on d.AssignedVehicleId=v.VehicleID " +
                         "   left join transporterinfo t on t.TransporterId=i.Transporter " +
                         "   inner join vehiclesgroupsmap g on g.VehicleId=v.VehicleID and g.GroupId=? " +
                          " where v.AccountID=? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("AccountID", AccountId);
            if (SelectedVehicleId != "--Select Vehicle Id--" && SelectedVehicleId != "")
            {
                query += " and i.VehicleId=? )as n ";
                lParameter.Add("VehicleId", SelectedVehicleId);
            }
            else
            {
                query += " )as n ";
            }
            query += "  JOIN (SELECT @curRow := 0, @VehicleId := '') r " +
                    "  ) as a " +
                "  GROUP BY a.VehicleId ";
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];

        }
        public Object[] GetDriverInfoDetails(string SessionId, string DriverId)
        {
            string AccountId = GetAccountId(SessionId).ToString();
            string groupid = getGroupId(SessionId).ToString();
            StringBuilder query = new StringBuilder();
            query.Append("SELECT `DriverId`,`Name`,`Father`,DATE_FORMAT(DOB, '%Y-%m-%d') DOB,`AddressLine1`,`AddressLine2`,`AddressLine3`,");
            query.Append("`City`,`State`,`ContactNo`,`MobileNo`,`LicenceNo`,`IssuedBy`,DATE_FORMAT(LicenceValid, '%Y-%m-%d') LicenceValid,`LicenceRemainder`,");
            query.Append("`LRStartBefore`,`LRRepeat`,`LRSMS`,`LRSMS_MobileNo`,`LREmail`,`LREmail_MailId`,`InsuranceCompany`");
            query.Append(",`PolicyNo`,DATE_FORMAT(PolicyDate, '%Y-%m-%d') PolicyDate,`InsuranceRemainder`,`IRStartBefore`,`IRRepeat`,`IRSMS`,`IRSMS_MobileNo`,");
            query.Append("`IREmail`,`IREmail_MailId`,`AssignedVehicleId`,`CleanerName`,`CleanerMobile`,`DriverLanguagePreference`,");
            query.Append("`DriverPhoto`,`AccountId`,`Active`,`UserDefinedDriverId`,HelperId,IMEI,RFIDTag,HazardousLicNo,DATE_FORMAT(HazardousLicExpDate, '%Y-%m-%d') HazardousLicExpDate,");
            query.Append("DATE_FORMAT(DDTDate, '%Y-%m-%d') DDTDate,DATE_FORMAT(DDTExpiryDate, '%Y-%m-%d') DDTExpiryDate,DATE_FORMAT(MedicalTestDate, '%Y-%m-%d') MedicalTestDate,DATE_FORMAT(MediExpDate, '%Y-%m-%d') MediExpDate,DrivingExp,DOJ,DriverAccidentHistory,DDTGrade,Approve FROM `driverinfo` ");
            query.Append("where `AccountId`=" + AccountId + " and `DriverId`=" + DriverId + " and (GroupId='" + groupid + "' or (GroupId=2801 and GroupId is NULL) or `AssignedVehicleId` in (select vehicleid from vehiclesgroupsmap where GroupId='" + groupid + "')) Order by Name");
            DataSet vehicles = dbx.executeQuery(query.ToString());
            DataTable table = vehicles.Tables[0];
            ArrayList driverList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                driverList.Add(row.ItemArray);
            }
            return driverList.ToArray();
        }
