        public DataTable GetTransporterScoreDetails(int accountid, string username, string month, string year)
        {
            string query = "  SELECT a.Value, " +
                   "  max(case when a.rank = 1 then a.Score end) as Behavior, " +
                  "  max(case when a.rank = 2 then a.Score end) as DriverProfile, " +
                   " max(case when a.rank = 3 then a.Score end) as EnrouteSpotCheck, " +
                  "  max(case when a.rank = 4 then a.Score end) as STLandSTDChecklist, " +
                   " max(case when a.rank = 5 then a.Score end) AS MaintenanceofVehicles, " +
                   " max(case when a.rank = 6 then a.Score end) AS ICTAuditScore, " +
                  "  max(case when a.rank = 7 then a.Score end) as HSEQ, " +
                   "  truncate(SUM((a.Score)/7),0) AS FinalScore ,a.FileName" +
                  "  from " +
                   " (select *, " +
                  "  case when HeaderName = 'Behaviour' then 1 " +
                   " when HeaderName = 'Driver Profile' then 2 " +
                  "  when HeaderName = 'Enroute Spot Check' then 3 " +
                   " when HeaderName = 'STL and STD Checklist' then 4 " +
                   " when HeaderName = 'Maintenance of Vehicles' then 5 " +
                   " when HeaderName = 'ICT Audit Score' then 6 " +
                   " when HeaderName = 'HSEQ' then 7 end  AS 'rank', @DriverId:= n.VettingId AS DriverIds " +
                   " from(SELECT VALUE, MAX(vettingid) as VettingId, Score, HeaderName,FileName " +
                  "  FROM " +
                   " ( " +
                   " select distinct z.Value, (c.Coefficient * v.Score) as Score, s.Id, h.HeaderName, s.DateTime, v.VettingId, h.Id AS headerid,s.FileName " +
                   " from vet_static_details s join vet_header h on s.AppId = h.AppId join vet_checklist c on c.HeaderId = h.Id " +
                  "  join vet_checklist_values v on c.Id = v.RuleId and v.VettingId = s.Id AND (SELECT MAX(fv.Datetime) FROM vet_static_details fv ) " +
                   " join vet_checklist_options o on o.ChecklistId = c.Id and o.Score = v.Score " +
                   " join vet_field_values z ON z.VetId = s.Id AND z.VetId = v.VettingId AND h.AppId = 3 AND z.FieldId IN(3) inner JOIN transporterinfo t ON z.Value=t.Name AND t.Active=1 where s.AddedBy = ? and s.AccountId = ? and year(s.DateTime)=? and month(s.DateTime)=?) temp " +
                  "  GROUP BY VALUE, HeaderName ORDER BY VALUE, headerid " +
                   " ) as n " +
                   " JOIN(SELECT @curRow:= 0, @DriverId:= '') r " +
                   " ) as a " +
                   " GROUP BY a.VettingId order by a.rank ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AddedBy", username);
            lParameter.Add("AccountId", accountid);
            lParameter.Add("DateTime1", year);
            lParameter.Add("DateTime", month);
            DataSet ds = dbx.executeQuery(query, lParameter);
            if (ds.Tables.Count > 0)
                return ds.Tables[0];
            else
                return null;
        }

