        public object[] getAGradeDDTCount(string login)
        {
            string query = "select ifnull((sum(case when d.DDTGrade='A' then 1 else 0 end)/count(*))*100,0) as DDTScore from driverinfo d "
                            + "join vehicleinfo v "
                            + "on d.AssignedVehicleId = v.VehicleId "
                            + "join transporterinfo t on t.TransporterId = v.Transporter "
                            + "and t.login = ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("login", login);
            int AGradeDDTCount = Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString());
            object[] result = new object[2];
            result[1] = "A Grade DDT Count : " + AGradeDDTCount;
            result[0] = AGradeDDTCount > 75 ? 2 : AGradeDDTCount > 50 ? 1 : 0;
            return result;
        }
        /// <summary>
        /// Modified by suvarna on 20020-10-03 As per the HR driver requirements
        /// </summary>
        public object[] getHighRiskDrivers(int groupid, DateTime dt)
        {
            int month = dt.Month;
            int year = dt.Year;
            string query = "select count(*) from vehiclesgroupsmap v join storevehicleviolations s on v.VehicleId=s.vehicleId where v.GroupId=" + groupid
                              + " and month(s.timestamp)=" + month + " and year(s.timestamp)=" + year + " and s.`type` in ('OVERSPEEDING','NIGHT DRIVING','HARSH BRAKING','HIGH ACCELERATION','HARSH CORNERING') ";
            int HRDriver = Convert.ToInt16(dbx.executeScalar(query.ToString()));
            object[] result = new object[2];
            result[1] = "HR Driver Count : " + HRDriver;
            result[0] = HRDriver > 0 ? 0 : 2;
            if (HRDriver == 0)
            {
                query = "select count(*) from vehiclesgroupsmap v join vehicle_events s on v.VehicleId=s.vehicleId where v.GroupId=" + groupid
                              + " and month(s.timestamp)=" + month + " and year(s.timestamp)=" + year + " and s.`EventName`='MobileUsage'";
                HRDriver = Convert.ToInt16(dbx.executeScalar(query.ToString()));
                //if (HRDriver == 0)
                //{
                //    query = "select count(*) from vehiclesgroupsmap v join vehicle_events s on v.VehicleId=s.vehicleId where v.GroupId=" + groupid
                //              + " and month(s.timestamp)=" + month + " and year(s.timestamp)=" + year + " and s.`EventName`='Smoking')";
                //    HRDriver = Convert.ToInt16(dbx.executeScalar(query.ToString()));
                //}
                if (HRDriver == 0)
                {
                    query = "select count(*) from vehiclesgroupsmap v join vehicle_events s on v.VehicleId=s.vehicleId where v.GroupId=" + groupid
                              + " and month(s.timestamp)=" + month + " and year(s.timestamp)=" + year + " and s.`EventName`='SeatBeltViolation'";
                    HRDriver = Convert.ToInt16(dbx.executeScalar(query.ToString()));
                }
                if (HRDriver == 0)
                {
                    query = "select count(*) from vehiclesgroupsmap v join vehicle_events s on v.VehicleId=s.vehicleId where v.GroupId=" + groupid
                              + " and month(s.timestamp)=" + month + " and year(s.timestamp)=" + year + " and s.`EventName`='DriverFatigue'";
                    HRDriver = Convert.ToInt16(dbx.executeScalar(query.ToString()));
                }
                if (HRDriver == 0)
                {
                    query = "select count(*) from vehiclesgroupsmap v join vehicle_events s on v.VehicleId=s.vehicleId where v.GroupId=" + groupid
                              + " and month(s.timestamp)=" + month + " and year(s.timestamp)=" + year + " and s.`EventName`='Yawning'";

                    HRDriver = Convert.ToInt16(dbx.executeScalar(query.ToString()));
                    result[1] = "HR Driver Count : " + HRDriver;
                    result[0] = HRDriver > 3 ? 0 : 2;
                }
                else
                {
                    result[1] = "HR Driver Count : " + HRDriver;
                    result[0] = HRDriver > 1 ? 0 : 2;
                }
            }
            return result;
        }
        public object[] getAvgVettingScore(int groupid)
        {
            string query = "select ifnull(avg(r.Amount),0) from vehiclesgroupsmap v join remainder r on v.VehicleId=r.vehicleId "
                              + "and v.GroupId=? and Doctype='Vetting Date' order by r.id desc";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            int avgvetscore = Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString());
            object[] result = new object[2];
            result[1] = "Vetting Count : " + avgvetscore;
            result[0] = avgvetscore > 90 ? 2 : avgvetscore > 79 ? 1 : 0;
            return result;
        }
