        public string Updatestausforvehiclerequest(string Action, string VehicleId, string Driver, string AdminRemarks, string Id, string VehicleType, string DriverType, string VehicleSubType)
        {
            string Addedon = string.Empty;
            try
            {
                Addedon = formatDBDate(DateTime.ParseExact(DateTime.Now.ToString(), "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

            }
            catch (Exception e)
            {
                Addedon = formatDBDate(Convert.ToDateTime(DateTime.Now.ToString()));
            }
            string status = "";
            if (Action == "Accept")
            { status = "Accepted"; }
            else if (Action == "Reject")
            { status = "Rejected"; }

            string query = "update bial_vehiclerequestdetails set Status=?,RequestedOn=?  ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Status", status);
            lParameter.Add("RequestedOn", Addedon);
            if (AdminRemarks != "")
            {
                query += ",AdminRemarks= ?";
                lParameter.Add("AdminRemarks", AdminRemarks);
            }
            if (status == "Accepted")
            {
                query += ",VehicleID=? ,DriverId=? ,VehicleType=?,DriverType=?,VehicleSubType=? ";
                lParameter.Add("VehicleID", VehicleId);
                lParameter.Add("DriverId", Driver);
                lParameter.Add("VehicleType", VehicleType);
                lParameter.Add("DriverType", DriverType);
                lParameter.Add("VehicleSubType", VehicleSubType);

                //Update Checlist Status as "Allotted"
                UpdateCheckListStausForVehicleRequest(Id, "Allotted", "", "", "", "");
            }
            if (status == "Rejected")
            {
                query += ",VehicleID=? ,DriverId=?,VehicleType=?,DriverType=?,VehicleSubType=? ";
                lParameter.Add("VehicleID", null);
                lParameter.Add("DriverId", null);
                lParameter.Add("VehicleType", null);
                lParameter.Add("DriverType", null);
                lParameter.Add("VehicleSubType", null);
            }
            query += "where Id =?";
            lParameter.Add("Id", Id);
            int result = dbx.executeNonQuery(query.ToString(), lParameter);
            return result.ToString();

        }
        public string UpdateVehicleRequestTripDetails(string Action, string VehicleId, string Driver, string Id)
        {
            string status = "";
            if (Action == "Accept")
            { status = "Accepted"; }
            else if (Action == "Reject")
            { status = "Rejected"; }
            string query1 = "select TripId from bial_alltripdetails where TripId=? ";
            var lParameter1 = new Dictionary<string, object>();
            lParameter1.Add("TripId", Id);
            DataTable dt = dbx.executeQuery(query1, lParameter1).Tables[0];
            if (dt.Rows.Count == 0 || string.IsNullOrEmpty(dt.Rows[0]["TripId"].ToString()))
            {
                string query = "update bial_alltripdetails set  ";
                var lParameter = new Dictionary<string, object>();
                if (status == "Accepted")
                {
                    query += " VehicleID=? ,DriverId=?";
                    lParameter.Add("VehicleID", VehicleId);
                    lParameter.Add("DriverId", Driver);
                }
                if (status == "Rejected")
                {
                    query += " VehicleID=? ,DriverId=? ";
                    lParameter.Add("VehicleID", null);
                    lParameter.Add("DriverId", null);
                }
                query += "where TripId =?";
                lParameter.Add("TripId", Id);
                int result = dbx.executeNonQuery(query.ToString(), lParameter);
                return result.ToString();
            }
            else
            {
                string query = "update bial_alltripdetails set  ";
                var lParameter = new Dictionary<string, object>();
                if (status == "Accepted")
                {
                    query += " VehicleID=? ,DriverId=?";
                    lParameter.Add("VehicleID", VehicleId);
                    lParameter.Add("DriverId", Driver);
                }
                if (status == "Rejected")
                {
                    query += " VehicleID=? ,DriverId=? ";
                    lParameter.Add("VehicleID", null);
                    lParameter.Add("DriverId", null);
                }
                query += "where TripId =?";
                lParameter.Add("TripId", Id);
                int result = dbx.executeNonQuery(query.ToString(), lParameter);
                return result.ToString();
            }           
        }
