        public DataSet GetCheckListDetailsforAdmin(int requestid)
        {
            string query = "SELECT @rownum := @rownum + 1 AS SlNo,s.tripid,c.Rule,v.RuleValue,v.Remarks " +
                "from(SELECT @rownum:= 0) r ,bial_checklist c " +
                "join bial_checklist_value v ON v.RuleId = c.ChecklistId " +
                "JOIN bial_static_details s ON s.Id = v.bialId " +
                "WHERE s.Id = (select MIN(k.Id) from bial_static_details k WHERE k.tripid = ?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("tripid", requestid);

            DataSet dsCheckListDetails = dbx.executeQuery(query, lParameter);
            return dsCheckListDetails;

        }
