        public DataSet GetNewRequestDetailsforexport(string formDate, string todate, string vehicleType, string Status, int accountid, string username)
        {
            string fromdate1 = string.Empty;
            string todate1 = string.Empty;
            if (!String.IsNullOrEmpty(formDate))
            {
                try
                {
                    //fromdate1 = formatDBDate(DateTime.ParseExact(formDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                    //DateTime dt = DateTime.Parse(formDate);
                    //fromdate1 = dt.ToString("yyyy-dd-MM hh:mm tt");
                    fromdate1 = formatDBDate(DateTime.ParseExact(formDate, "dd/MM/yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    //fromdate1 = formatDBDate(Convert.ToDateTime(formDate));
                    //DateTime dt = DateTime.Parse(formDate);
                    //fromdate1 = dt.ToString("yyyy-dd-MM hh:mm tt");
                    fromdate1 = formatDBDate(Convert.ToDateTime(formDate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    //todate1 = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                    //DateTime dt = DateTime.Parse(todate);
                    //todate1 = dt.ToString("yyyy-dd-MM hh:mm tt");
                    todate1 = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    //todate1 = formatDBDate(Convert.ToDateTime(todate));
                    //DateTime dt = DateTime.Parse(todate);
                    //todate1 = dt.ToString("yyyy-dd-MM hh:mm tt");
                    todate1 = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            //string query = "select RequestType, Task, LocationName, WorkType,  ScheduleTimeFrom, ScheduleTimeTo, Status, AdminRemarks from bial_vehiclerequestdetails "
            //+ " where  AccountId=? and ScheduleTimeFrom between ? and ? and UserName=?  ";
            string query = "select DISTINCT RequestType, Task, LocationName,ScheduleTimeFrom, ScheduleTimeTo, b.`Status`, AdminRemarks,b.VehicleId,d.Name,d.MobileNo from bial_vehiclerequestdetails b LEFT JOIN bial_alltripdetails a ON b.DriverId=a.DriverId AND b.VehicleId=a.VehicleId LEFT JOIN driverinfo d ON d.DriverId=a.DriverId "
               + " where  b.AccountId=? and ScheduleTimeFrom between ? and ? and UserName=?  ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountid);
            lParameter.Add("fromdate", fromdate1);
            lParameter.Add("todate", todate1);
            lParameter.Add("UserName", username);
            if (Status != "All")
            {
                query += " and b.Status=?";
                lParameter.Add("Status", Status);
            }
            if (vehicleType != "All")
            {
                query += " and RequestType=?";
                lParameter.Add("RequestType", vehicleType);
            }
            //if (subtype != "All")
            //{
            //    query += " and SubRequestType=?";
            //    lParameter.Add("SubRequestType", subtype);
            //}
            query += " order by RequestedOn desc";

            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;
        }
        public DataSet GetAdminNewRequestDetailsforexport(string formDate, string todate, string vehicleType, string Status, int accountid, string username)
        {
            string fromdate1 = string.Empty;
            string todate1 = string.Empty;
            if (!String.IsNullOrEmpty(formDate))
            {
                try
                {
                    //fromdate1 = formatDBDate(DateTime.ParseExact(formDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                    //DateTime dt = DateTime.Parse(formDate);
