                admin = "BIAL";
            }

            //string query = "select RequestType, Task, LocationName, WorkType,  ScheduleTimeFrom, ScheduleTimeTo, Status, AdminRemarks from bial_vehiclerequestdetails "
            //+ " where  AccountId=? and ScheduleTimeFrom between ? and ? and UserName=?  ";
            string query = "select RequestType,concat(b.SubRequestType ,'-' , b.TypeOfBusCar)  AS 'vehicle type',b.Equipmentcategory,VehicleSubType as 'Type of Vehicle', Task, LocationName,ScheduleTimeFrom, ScheduleTimeTo,a.Name as 'Department Name',b.ContactPerson,b.MobileNo,b.VehicleId, Status,b.AdminRemarks,b.CheckListStatus from bial_vehiclerequestdetails b  "
            + " inner join accountgroups a on b.AccountId=a.AccountID inner join usersgroupsmap u on a.groupid = u.groupid and b.UserName=u.Login   where  b.AccountId=? and b.Head = ? and ScheduleTimeFrom between ? and ? and b.UserName=?  ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountid);
            lParameter.Add("Admin", admin);
            lParameter.Add("fromdate", fromdate1);
            lParameter.Add("todate", todate1);
            lParameter.Add("UserName", username);
            if (Status != "All")
            {
                query += " and Status=?";
