        public DataTable GetoverlappingVehicleList(string VehicleType, string username, int accountid, string Id)
        {
            DataTable vehdt = new DataTable();
            Object[] VehicleRequestDetails = GetDriverInfoDetails(Id);
            DateTime strdate = Convert.ToDateTime((((((Object[])VehicleRequestDetails[0])[2]).ToString()).Trim())).AddMinutes(-30);
            DateTime enddate = Convert.ToDateTime((((((Object[])VehicleRequestDetails[0])[3]).ToString()).Trim())).AddMinutes(30);
            //DateTime starttime = Convert.ToDateTime((((((Object[])VehicleRequestDetails[0])[2]).ToString()).Trim())).AddMinutes(-30);
            //DateTime endtime = Convert.ToDateTime((((((Object[])VehicleRequestDetails[0])[3]).ToString()).Trim())).AddMinutes(30);
            string starttime = formatDBDate(strdate);
            string endtime = formatDBDate(enddate);

            int GroupId = getGroupIdByLogin(username);
            string query = " SELECT DISTINCT v.VehicleId  FROM vehiclesgroupsmap v join vehicleinfo vi on vi.VehicleId=v.VehicleID " +
                            "join vehicletype vt on vt.ID=vi.TruckType WHERE v.GroupId = ? AND vt.VehicleType=? AND  v.VehicleId not IN( " +
                            "SELECT DISTINCT bvr.VehicleId FROM bial_vehiclerequestdetails bvr WHERE  (bvr.ScheduleTimeFrom between ? AND ? " +
                            "OR bvr.ScheduleTimeTo BETWEEN ? AND ?) AND bvr.`Status`='Accepted') ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", GroupId);
            lParameter.Add("VehicleType", VehicleType);
            lParameter.Add("starttime", starttime);
            lParameter.Add("endtime", endtime);
