        public string InsertVehicleRequestTripDetails(string Action, string Vehicle, string Driver, string Id)
        {
            string status = "";
            if (Action == "Accept")
            { status = "Accepted"; }
            else if (Action == "Reject")
            { status = "Rejected"; }
            string query1 = "select TripId from bial_alltripdetails where TripId=? ";
            var lParameter1 = new Dictionary<string, object>();
            lParameter1.Add("TripId", Id);
            DataTable dt = dbx.executeQuery(query1, lParameter1).Tables[0];
            if (dt.Rows.Count == 0 || string.IsNullOrEmpty(dt.Rows[0]["TripId"].ToString()))
            {
                string query = "";
                var lParameter = new Dictionary<string, object>();
                query = "INSERT INTO `bial_alltripdetails` (`VehicleId`, `DriverId`, `TripId`) VALUES (?,?,?)";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", Vehicle);
                lParameter.Add("DriverId", Driver);
                lParameter.Add("TripId", Id);
                return dbx.executeNonQuery(query, lParameter).ToString();
            }
            else
            {
                string query = "update bial_alltripdetails set  ";
                var lParameter = new Dictionary<string, object>();
                if (status == "Accepted")
                {
                    query += " VehicleID=? ,DriverId=?";
                    lParameter.Add("VehicleID", Vehicle);
                    lParameter.Add("DriverId", Driver);
                }
                if (status == "Rejected")
                {
                    query += " VehicleID=? ,DriverId=? ";
                    lParameter.Add("VehicleID", null);
                    lParameter.Add("DriverId", null);
                }
                query += "where TripId =?";
                lParameter.Add("TripId", Id);
                int result = dbx.executeNonQuery(query.ToString(), lParameter);
                return result.ToString();
            }
        }
