                + "where bvr.VehicleID=v.VehicleId and bvr.`Status`='Accepted' and btd.TripClosedBy is null) tripCount from usersgroupsmap u join vehiclesgroupsmap v on"
                + " u.GroupId=v.GroupId join vehicles ve on ve.VehicleID=v.VehicleId join vehicleinfo vi on vi.VehicleId=ve.VehicleID join vehicletype vt on "
                + "vt.ID=vi.TruckType where u.Login=? and ve.AccountID=? and vt.VehicleType=?) res where res.tripCount=0 "
                + "union select b.VehicleId from  bial_vehiclerequestdetails b where b.ID=?";

            var lParameter = new Dictionary<string, object>();
