        public object[] getStdRejectPercent(int groupid, DateTime dt, string wftype)
        {
            string query = "select ifnull((sum(case when w.`Action`='Allow' then 0 else 1 end)/count(*))*100,0) from customerdcassign c "
                + " join vehicledctrip v on v.id=c.DCTripId join stl_workflow w on w.vehicleid=v.VehicleID ";

            if (wftype == "0") //STL
                query += " and w.DateTime<v.DateTime and w.workflowtype=0";

            else if (wftype == "1") //STD
                query += " and w.DateTime<DATE_ADD(v.DateTime,INTERVAL 3 HOUR) and w.workflowtype=1";

            else if (wftype == "2") //SPOT
            {
                query += " and w.DateTime>v.DateTime and w.workflowtype=2" +
                         " and (w.DateTime < v.TripEndsOn or v.TripEndsOn IS NULL)";
            }
            query += " where w.vehicleId in(select vehicleid from vehiclesgroupsmap where groupid=?) and month(w.DateTime)=? and year(w.DateTime)=? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("month", dt.Month);
            lParameter.Add("year", dt.Year);
            int percent = Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString());
            object[] result = new object[2];
            result[1] = "Deviation(%) : " + percent;
            if (wftype == "0")
                result[0] = percent > 1 ? 0 : 2;
            else
                result[0] = percent == 0 ? 2 : 0;
            return result;
        }
