            {
                AccId = GetVehAccontId(VehicleNo);
            }
            string query = "select r.RegionName from vehicles v left join vehicleinfo vi on v.VehicleID=vi.VehicleId left join regioninfo r on vi.RegionId=r.RegionId and r.AccountId=? where Replace (v.VehicleId,' ','')=Replace(?,' ','') and r.RegionName is not null;";
