                " d.endlatlng, concat(DATE_FORMAT(d.trip_endtime, '%Y-%m-%d')) as TripEndDate, concat(DATE_FORMAT(d.trip_endtime, '%H:%i')) as TripEndTime, " +
                " d.maxsp_count,d.harshaccln_Count,d.harshbraking_count,d.cd,d.IsNightDrivingViol,d.md from daywisevehviosummary d " +
