        public int AddDriverRecruitmentDataFromReviewForApproval(int actionid, string FormId, string JoiningDate, string ReasonForChange, string DriverAppTrainie, string SafeDriver, string Review_Remarks, string ReviewedPersonName, string ReviewedBy, string Review_Action, string BindSpotTraining, string FatigueTraining, string remarks, string AddedPersonName, string AccountId)
        {
            DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
            //insertauditdata("Edit", "tbl_trans_driver_recruitment", "Id", FormId);
            string query1 = "select Name from users where login='" + ReviewedBy + "'";
            string reviewername = dbx.executeScalar(query1).ToString();
            string query = "insert into tbl_trans_driver_recruitment (Joining_Date,Reason_For_Change,Driver_App_Trainie,Safe_Driver,Bindspot_Training,Fatigue_Training,ActionId,AddedBy,Remarks, AddedPersonName,ReviewedOn,AddedOn,Status,AccountId) values (?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            try
            {
                lParameter.Add("Joining_Date", formatDBDate(DateTime.ParseExact(JoiningDate, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture)));
                //lParameter.Add("Joining_Date", formatDBDate(DateTime.ParseExact(JoiningDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture)));
            }
            catch
            {
                lParameter.Add("Joining_Date", formatDBDate(DateTime.ParseExact(JoiningDate, "dd-MM-yyyy", System.Globalization.CultureInfo.InvariantCulture)));
                //lParameter.Add("Joining_Date", formatDBDate(Convert.ToDateTime(JoiningDate)));
            }
            lParameter.Add("Reason_For_Change", ReasonForChange);
            lParameter.Add("Driver_App_Trainie", DriverAppTrainie);
            lParameter.Add("Safe_Driver", SafeDriver);
            lParameter.Add("BindSpot", BindSpotTraining);
            lParameter.Add("Fatigue_Train", FatigueTraining);
            lParameter.Add("ActionId", actionid);
            lParameter.Add("AddedBy", ReviewedBy);
            lParameter.Add("Remarks", remarks);
            lParameter.Add("AddedPersonName", AddedPersonName);
            lParameter.Add("ReviewedOn", formatDBDate(now));
            lParameter.Add("AddedOn", formatDBDate(now));
