        /// </summary>
        public string GetAllLoginVehicleStrBySession(string session, string retunFormat)
        {
            StringBuilder query = new StringBuilder();
            var lParemeter = new Dictionary<string, object>();
            query.Append("select Group_Concat");
            if (retunFormat.ToLower() == "querystring")
                query.Append("(CONCAT(\"'\",v.VehicleID,\"'\")) ");
            else
                query.Append("(v.VehicleID) ");
            query.Append(" from sessions s join usersgroupsmap u on s.login=u.Login join vehiclesgroupsmap m on u.GroupId = m.GroupId ");
            query.Append(" join vehicles v on v.VehicleID=m.VehicleId where s.SessionID=?");
            lParemeter.Add("SessionID", session);
            return Convert.ToString(dbx.executeScalar(query.ToString(), lParemeter));
        }

        /// <summary>
        /// Get specified variable maximum value (Speed/RPM)
        /// Added By : Harish on 22/09/2020
        /// Reason : Show the Max Speed or Rpm value on report
        /// </summary>
        public string GetMaxSpeedOrRpm(string vehileId, DateTime fromDateStr, DateTime toDateStr, string max = "speed")
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDateStr), Convert.ToDateTime(toDateStr), partions);
            String GloAcId = GetGlobalAccountId(Convert.ToString(getAccountIdByVehicleId(vehileId)));
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query.Append("select Round(max");
            if (max.ToLower() == "rpm" || max.ToLower() == "ci")
            {
                if (GloAcId == "3717")
                    query.Append("(RpmRatio(p.TruckID)*p.CI)");
                else
                    query.Append("(p.CI)");
            }
            else
            {
                if (GloAcId == "3717")
                    query.Append("(Can_Speed(p.TruckID,p.TimeStamp))");
                else
                    query.Append("(p.Speed)");
            }

            query.Append(",0) from positiondata PARTITION(" + part + ") p where p.TruckID =? and p.TimeStamp between ? and ?");
            lParameter.Add("TruckID", vehileId);
            lParameter.Add("FromDateStr", formatDBDate(fromDateStr));
            lParameter.Add("ToDateStr", formatDBDate(toDateStr));
            return Convert.ToString(dbx.executeScalar(query.ToString(), lParameter));
        }

