        /// <summary>
        /// Get the Violation Limit of a Shell Vehicles 
        /// Added By : Harish on 25/09/2020
        /// Reason : Base violation report not captring Limit of a violation so need to limit value to comapare with the violation speed
        /// </summary>
        public string GetViolationLimitOfShell(string vehicleId, DateTime time, string groupId, string violation = "")
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query.Append("select if (s.`type`= 'OVERSPEEDING',ifnull(p.maxSpeed, pv.maxSpeed), if (s.`type`= 'JRM OVERSPEEDING',SUBSTRING_INDEX(s.Location, '-', -1),");
            query.Append("if (s.`type`= 'HARSH BRAKING',u.ACLHBTH3, if (s.`type`= 'HIGH ACCELERATION',u.ACLHATH3,if (s.`type`= 'HARSH CORNERING','',");
            query.Append("if (s.`type`= 'FREEWHEELING', ifnull(p.FreewheelingTime, pv.FreewheelingTime),if (s.`type`= 'EXCESSIVE RPM',ifnull(p.ExcessiveRPM, pv.ExcessiveRPM), ");
            query.Append("if (s.`type`= 'EXCESSIVE IDLE',ifnull(p.ExcessiveIdle, pv.ExcessiveIdle),if (s.TYPE = 'NIGHT DRIVING',IFNULL(pv.NightDrivingTime, p.NightDrivingTime),");
            query.Append("if (s.`type`= 'ROUTE DEVIATION',IFNULL(p.routedeviation, pv.routedeviation),if (s.`type`= 'SHORT RUNTIME',round(IFNULL(p.shortRunDuration, pv.shortRunDuration) / 60, 0),");
            query.Append("if (s.`type`= 'TOTAL RUNTIME',round(IFNULL(p.longRunDuration, pv.longRunDuration) / 60, 0),'')))))))))))) as Limits from storevehicleviolations s left join ");
            query.Append("vehicletripparams_vehwise p on s.VehicleId = p.VehicleId left join vehicletripparams pv on pv.groupId =? left join unitconfigparams u on u.VehicleId = s.vehicleId ");
            query.Append("where s.VehicleId =? and s.timestamp =? and ");
            lParameter.Add("groupId", groupId);
            lParameter.Add("VehicleId", vehicleId);
            lParameter.Add("timestamp", formatDBDate(time));
            if (!string.IsNullOrEmpty(violation))
            {
                query.Append(" s.`type`=?");
                lParameter.Add("violation", violation);
            }
            else
            {
                query.Append(" s.`type`='NORMAL'");
            }
            return Convert.ToString(dbx.executeScalar(query.ToString(), lParameter));
        }
        /// <summary>
        /// Added by Suvarna on 2020-09-24
        /// To calculate SigSenz violations count and give score value for Transporter Incentive Schema
        /// </summary>
        public object[] getSigSenzViolationCount(int groupid, DateTime dt, string EventName)
        {
            string query = "select count(*) from vehiclesgroupsmap v join vehicle_events s on v.VehicleId=s.vehicleId where v.GroupId=? and "
                              + "month(s.timestamp)=? and year(s.timestamp)=? and s.`EventName`=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("month", dt.Month);
            lParameter.Add("year", dt.Year);
            lParameter.Add("EventName", EventName);
            int violCount = Convert.ToInt16(dbx.executeScalar(query, lParameter).ToString());
            object[] result = new object[2];
            result[1] = "Violation Count : " + violCount;
            result[0] = violCount > 0 ? 0 : 2;
            return result;
        }

