            {
                Addedon = formatDBDate(DateTime.ParseExact(DateTime.Now.ToString(), "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

            }
            catch (Exception e)
            {
                Addedon = formatDBDate(Convert.ToDateTime(DateTime.Now.ToString()));
            }
            string query = "INSERT INTO `Outboundcall_log` (`Sid`,VehicleId,Haulier,MobileNo,VioType,DateCreated,CallText,StartTime,EndTime,Duration,Price,BranchId,Status,VoiceCallStatus) "
                         + "VALUES (?,?,?, ?, ?, ?, ?, ?, ?, ?, ?, ?,?,?)";
