            { lParameter.Add("DateCreated", Addedon); }
            else
            { lParameter.Add("DateCreated", CallDetails.datecreated); }
            lParameter.Add("CallText", CallDetails.calltext);
            if (string.IsNullOrEmpty(CallDetails.datecreated))
            { lParameter.Add("StartTime", Addedon); }
            else { lParameter.Add("StartTime", CallDetails.starttime); }
            lParameter.Add("EndTime", CallDetails.endtime);
            lParameter.Add("Duration", CallDetails.duration);
            lParameter.Add("Price", CallDetails.price);
            lParameter.Add("BranchId", CallDetails.branchid);
            if (string.IsNullOrEmpty(CallDetails.status))
            {
                lParameter.Add("Status", "DND");
                lParameter.Add("VoiceCallStatus", "Closed");
            }
            else
            {
                lParameter.Add("Status", CallDetails.status);
                lParameter.Add("VoiceCallStatus", null);
            }
            string res = dbx.executeNonQuery(query, lParameter).ToString();
            return res;
        }
