        public Object[] getactiveVehiclesbyCustomers(string customername)
        {

            DataSet activeSet = new DataSet();
            ArrayList activeList = new ArrayList();

            try
            {
                string query = "select distinct v.vehicleid from accountgroups ag, accounts a,vehiclesgroupsmap v, usersgroupsmap u"
                                    + " where a.name = " + "'" + customername + "'"
                                    + " and ag.groupid = v.groupid"
                                    + " and a.id = ag.accountid"
                                    + " and u.groupid = v.groupid"
                                    + " and  u.login not like '%old%'"
                                    + " and ag.name not like '%old%'"
                                    + " order by a.id";
