        /// <summary>
        /// Update location in daywisevehviosummary table
        /// Added by Harish on 30/12/2020 for get report based on Tata customer
        /// </summary>
        public bool updateLocationInViosummaryTbl(int gpId, DateTime fromDate, DateTime toDate, string vehicles = "")
        {
            var lParameter = new Dictionary<string, object>();
            string queryStr = "select d.groupid,d.vehicleid,d.date,d.startlatlng,d.endlatlng,d.nd_startlatlng,d.nd_endlatlng,d.startlocation,d.endlocation,d.ndstartlocation,d.ndendlocation from daywisevehviosummary d where d.groupid=? and d.date between ? and  ?";
            //if (!string.IsNullOrEmpty(vehicles) && vehicles.ToLower() != "all")
            //{
            //    queryStr += "and d.vehicleid in (" + vehicles + ")";
            //}
            lParameter.Add("groupId", gpId);
            lParameter.Add("fromDate", formatDBDate(fromDate));
            lParameter.Add("toDate", formatDBDate(toDate));
            DataTable dt = dbx.executeQuery(queryStr, lParameter).Tables[0];

            StringBuilder query = new StringBuilder();
            string where = " where d.groupid=? and d.vehicleid=? and d.date=? and d.startlatlng=? and d.endlatlng=? and d.nd_startlatlng=? and d.nd_endlatlng=?;";
            foreach (DataRow row in dt.Rows)
            {
                bool exicute = false;
                lParameter.Clear();
                query.Clear();
                query.Append("update daywisevehviosummary d set ");
                if (!string.IsNullOrEmpty(Convert.ToString(row["startlatlng"])) && string.IsNullOrEmpty(Convert.ToString(row["startlocation"])))
                {
                    string[] startlatlng = row["startlatlng"].ToString().Split(',');
                    if (startlatlng.Length > 1)
                    {
                        string startloc = "";
                        try { startloc = getPositionTxt(startlatlng[0], startlatlng[1], 0); } catch { }
                        ;
                        query.Append("startlocation=?");
                        lParameter.Add("startlocation", startloc);
                        exicute = true;
                    }
                }
                if (!string.IsNullOrEmpty(Convert.ToString(row["endlatlng"])) && string.IsNullOrEmpty(Convert.ToString(row["endlocation"])))
                {
                    string[] endlatlng = row["endlatlng"].ToString().Split(',');
                    if (endlatlng.Length > 1)
                    {
                        string endloc = "";
                        try { endloc = getPositionTxt(endlatlng[0], endlatlng[1], 0); } catch { }
                        ;
                        if (exicute)
                            query.Append(",");
                        else { exicute = true; }
                        query.Append(" endlocation=?");
                        lParameter.Add("endlocation", endloc);
                    }
                }
                if (!string.IsNullOrEmpty(Convert.ToString(row["nd_startlatlng"])) && string.IsNullOrEmpty(Convert.ToString(row["ndstartlocation"])))
                {
                    string[] ndstartlatlng = row["nd_startlatlng"].ToString().Split(',');
                    if (ndstartlatlng.Length > 1)
                    {
                        string ndstartloc = "";
                        try { ndstartloc = getPositionTxt(ndstartlatlng[0], ndstartlatlng[1], 0); } catch { }
                        ;
                        if (exicute)
                            query.Append(",");
                        else { exicute = true; }
                        query.Append("ndstartlocation=?");
                        lParameter.Add("ndstartlocation", ndstartloc);
                    }
                }
                if (!string.IsNullOrEmpty(Convert.ToString(row["nd_endlatlng"])) && string.IsNullOrEmpty(Convert.ToString(row["ndendlocation"])))
                {
                    string[] ndendlatlng = row["nd_endlatlng"].ToString().Split(',');
                    if (ndendlatlng.Length > 1)
                    {
                        string ndendloc = "";
                        try { ndendloc = getPositionTxt(ndendlatlng[0], ndendlatlng[1], 0); } catch { }
                        ;
                        if (exicute)
                            query.Append(",");
                        else { exicute = true; }
                        query.Append("ndendlocation=?");
                        lParameter.Add("ndendlocation", ndendloc);
                    }
                }
                if (exicute)
                {
                    query.Append(where);
                    lParameter.Add("groupid", gpId);
                    lParameter.Add("vehicleid", row["vehicleid"]);
                    lParameter.Add("date", row["date"]);
                    lParameter.Add("startlatlng", row["startlatlng"]);
                    lParameter.Add("endlatlng", row["endlatlng"]);
                    lParameter.Add("nd_startlatlng", row["nd_startlatlng"]);
                    lParameter.Add("nd_endlatlng", row["nd_endlatlng"]);
                    dbx.executeNonQuery(query.ToString(), lParameter);
                }
            }
            return true;
        }

