        public string getunloadingtruckid(string unloadingstation)
        {
            string unloadinglocation = string.Empty;
            string query = "select locstr from stationcodes where stationcode =? ";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("stationnumber", unloadingstation);
            try
            {
                unloadinglocation = Convert.ToString(dbx.executeScalar(query, lParameter));
            }
            catch { return string.Empty; }
            if (!unloadinglocation.Equals(string.Empty))
            {
                string truckid = string.Empty;
                DateTime totimestamp = DateTime.UtcNow.AddHours(5).AddMinutes(30);
                DateTime fromtimestamp = totimestamp.AddHours(-2);
                string fromtimestampstr = formatDBDate(fromtimestamp);
                string totimestampstr = formatDBDate(totimestamp);
                string query1 = "select distinct vehicleid from vehicleinplant where locationstr =? and intimestamp between? and ? and outtimestamp is null and vehicleid not like 'INST%'";
                var lParameter1 = new Dictionary<string, object>();
                lParameter1.Add("loc", unloadinglocation);
                lParameter1.Add("from", fromtimestampstr);
                lParameter1.Add("to", totimestampstr);
                try
                {
                    DataSet dsVehicles = dbx.executeQuery(query1, lParameter1);
                    DataTable vehiclesdt = dsVehicles.Tables[0];

                    if (vehiclesdt.Rows.Count == 1)
                    {
                        truckid = Convert.ToString(vehiclesdt.Rows[0][0]);
                        return truckid;
                    }
                    else
                        return string.Empty;
                }
                catch (Exception ex) { return string.Empty; }
            }
            return string.Empty;
        }

