        public string insertSglCheckList(string imei, string ChecklistName, List<sgl_ChecklistValues> checklistValues)
        {
            string AccountId = GetDriverAccountByIMEI(imei);
            var lParameter2 = new Dictionary<string, object>();
            var lParameter = new Dictionary<string, object>();
            string query3 = "SELECT d.DriverId,d.Name,d.AssignedVehicleId,d.AccountId,d.Transporter FROM driverinfo d WHERE d.IMEI=? ";
            lParameter2.Add("IMEI1", imei);
            dbx.executeNonQuery(query3, lParameter2).ToString();
            DataSet driversdetails = dbx.executeQuery(query3.ToString(), lParameter2);
            DataTable driverdt = driversdetails.Tables[0];

            string query = "INSERT INTO `sgl_static_details` (`ChkDate`, `DriverId`, `DriverName`, `TransportedId`, `VehicleId`, `AccountId`,"
                         + " `IMEI`) "
                         + "VALUES (?, ?, ?, ?, ?, ?, ?)";
            lParameter.Add("ChkDate", formatDBDate(DateTime.Now));
            lParameter.Add("DriverId", driverdt.Rows[0]["DriverId"].ToString().Trim());
            lParameter.Add("DriverName", driverdt.Rows[0]["Name"].ToString().Trim());
            lParameter.Add("TransportedId", driverdt.Rows[0]["Transporter"].ToString().Trim());
            lParameter.Add("VehicleId", driverdt.Rows[0]["AssignedVehicleId"].ToString().Trim());
            lParameter.Add("AccountId", driverdt.Rows[0]["AccountId"].ToString().Trim());
            lParameter.Add("IMEI", imei);
            string res = dbx.executeNonQuery(query, lParameter).ToString();
            if (res == "1")
            {
                var lParameter3 = new Dictionary<string, object>();
                query = "SELECT Id FROM sgl_app_config WHERE AppName=? AND AccountId= ?";
                lParameter3.Add("AppName", ChecklistName);
                lParameter3.Add("AccountId1", AccountId);
                //string checklistid = dbx.executeQuery(query.ToString(), lParameter3);
                dbx.executeNonQuery(query, lParameter3).ToString();
                DataSet chkid = dbx.executeQuery(query.ToString(), lParameter3);
                DataTable chklistid = chkid.Tables[0];

                int checklistrulenocount = 0;
                string RuleId = "";

                query = "select Max(v.Id) from sgl_static_details v";
                lParameter = new Dictionary<string, object>();
                string id = dbx.executeScalar(query, lParameter).ToString();
                query = "INSERT INTO `sgl_checklist_value` (`SglId`,`ChecklistId`, `RuleId`, `RuleValue`) VALUES ";
                for (int i = 0; i < checklistValues.Count; i++)
                {
                    if (checklistValues[i].RuleValue == "No")
                    {
                        checklistrulenocount = 1;
                        RuleId = checklistValues[i].RuleId;
                    }
                    query += "(?, ?, ?,?),";
                    lParameter.Add("SglId" + i, id);
                    lParameter.Add("ChecklistId" + i, chklistid.Rows[0]["Id"].ToString().Trim());
                    lParameter.Add("RuleId" + i, checklistValues[i].RuleId);
                    lParameter.Add("RuleValue" + i, checklistValues[i].RuleValue);
                }
                query = query.Substring(0, query.Length - 1);
                res = dbx.executeNonQuery(query, lParameter).ToString();
                if (res != "0" && checklistrulenocount == 1)
                {
                    var lParameter4 = new Dictionary<string, object>();
                    query = "SELECT RuleName FROM sgl_checklist WHERE Id=? ";
                    lParameter4.Add("Id", RuleId);
                    DataSet RuleName = dbx.executeQuery(query.ToString(), lParameter4);
                    DataTable dtRuleName = RuleName.Tables[0];

                    query = "Update sgl_static_details set ChecklistStatus= \"The Value of " + dtRuleName.Rows[0]["RuleName"].ToString().Trim() + " is No\" where Id = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("SglId", id);
                    dbx.executeNonQuery(query, lParameter);
                }
                if (res != "0" && checklistrulenocount == 0)
                {
                    var lParameter4 = new Dictionary<string, object>();
                    query = "SELECT RuleName FROM sgl_checklist WHERE Id=? ";
