        //public DataTable getUpdatedAssetStatus(string type, string id)
        public DataTable getUpdatedAssetStatus(string id)
        {
            try
            {
                //string query = String.Empty;
                //query = "SELECT t.fasttracktime AS 'Motion Rate',CASE WHEN t.ACCL = 0 THEN 'Enable' ELSE 'Disable' END as 'Theft state',(t.slowtracktime * t.SLOWUPDTCOUNT) AS 'Halt Update Rate', "
                //        + " t.theftslowtracktime AS 'Theft Halt update rate' FROM unitconfigparams t WHERE t.VehicleId = ? ";
                //var lParameter = new Dictionary<string, object>();
                //lParameter.Add("Asset", id);
                //DataTable dt = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                //if (dt.Rows.Count == 0)
                //{
                //    DataRow row = dt.NewRow();
                //    dt.Rows.Add(row);
                //}
                string query = String.Empty;
                //query = "select u.Asset,u.RequestType,u.CurrentValue,u.RequestedValue,u.RequestedTime,u.RequestedBy,u.`Status`,u.Source from unitupdtrateconfiglog u "
                //      + " where u.Asset = ? and u.RequestType = ? and u.`Status`='queued' order by Id desc limit 1";
                query = "select u.Asset,u.RequestType,u.CurrentValue,u.RequestedValue,u.RequestedTime,u.RequestedBy,u.`Status`,u.Source from unitupdtrateconfiglog u "
                      + " where u.Asset = ?  and u.`Status`='queued' order by Id desc limit 1";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("Asset", id);
                // lParameter.Add("RequestType", type);
                DataTable dt = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                if (dt.Rows.Count == 0)
                {
                    DataRow row = dt.NewRow();
                    dt.Rows.Add(row);
                }
                else
                {
                    string type = dt.Rows[0]["RequestType"].ToString();
                    switch (type)
                    {
                        case "Moving Update Rate":
                            query = "select u.VehicleId,u.ServerTS,u.slowtracktime,u.fasttracktime,u.theftslowtracktime,u.theftclear from unitconfigparams" +
                                " u where u.VehicleId=? and u.ServerTS>=? and u.fasttracktime=? ";
                            break;
                        case "Theft Enable":
                            query = "select u.VehicleId,u.ServerTS,u.slowtracktime,u.fasttracktime,u.theftslowtracktime,u.theftclear from unitconfigparams" +
                               " u where u.VehicleId=? and u.ServerTS>=? and u.ACCL=? ";
                            break;
                        case "Halt Update Rate":
                            query = "select u.VehicleId,u.ServerTS,u.slowtracktime,u.fasttracktime,u.theftslowtracktime,u.theftclear from unitconfigparams" +
                               " u where u.VehicleId=? and u.ServerTS>=? and (u.slowtracktime * u.SLOWUPDTCOUNT)=? ";
                            break;
                        case "Theft Disable":
                            query = "select u.VehicleId,u.ServerTS,u.slowtracktime,u.fasttracktime,u.theftslowtracktime,u.theftclear from unitconfigparams" +
                               " u where u.VehicleId=? and u.ServerTS>=? and u.ACCL=? ";
                            break;
                        case "Theft Halt Update Rate":
                            query = "select u.VehicleId,u.ServerTS,u.slowtracktime,u.fasttracktime,u.theftslowtracktime,u.theftclear from unitconfigparams" +
                               " u where u.VehicleId=? and u.ServerTS>=? and u.theftslowtracktime=? ";
                            break;
                    }
                    //Modified by suvarna on 30/1/2021 due to bug while updating to success
                    DateTime timestamp = DateTime.MinValue;
                    timestamp = (DateTime)(dt.Rows[0]["RequestedTime"]);
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Asset", id);
                    lParameter.Add("RequestedTime", formatDBDate(timestamp));
                    if (type == "Theft Enable") { lParameter.Add("RequestedValue", "0"); }
                    else if (type == "Theft Disable") { lParameter.Add("RequestedValue", "1"); }
                    else
                    {
                        lParameter.Add("RequestedValue", dt.Rows[0]["RequestedValue"].ToString());
                    }
                    DataTable dt1 = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                    if (dt1.Rows.Count > 0)
                    {
                        query = "update unitupdtrateconfiglog u set u.`Status`= 'Success', u.StatusTime=?, u.CurrentValue=? where u.Asset=? and u.RequestType=? and u.RequestedValue=" + dt.Rows[0]["RequestedValue"].ToString();
                        lParameter = new Dictionary<string, object>();
                        DateTime timestamp1 = DateTime.MinValue;
                        timestamp1 = (DateTime)(dt1.Rows[0]["ServerTS"]);
                        lParameter.Add("StatusTime", formatDBDate(timestamp1));
                        if (type == "Theft Enable") { lParameter.Add("RequestedValue", "0"); }
                        else if (type == "Theft Disable") { lParameter.Add("RequestedValue", "1"); }
                        else
                        {
                            lParameter.Add("RequestedValue", dt.Rows[0]["RequestedValue"].ToString());
                        }
                        //lParameter.Add("RequestedValue", dt.Rows[0]["RequestedValue"].ToString());
                        lParameter.Add("Asset", id);
                        lParameter.Add("RequestType", dt.Rows[0]["RequestType"].ToString());
                        dbx.executeNonQuery(query.ToString(), lParameter);
                    }
                }
                return dt;
            }
            catch (Exception ex) { return null; }
        }
