        //
        // This method returns the data from lastupdtdataGL table of the passed asset. Please note only one asset shall be passed to this method.
        //
        public Object[] getLastUpdateFromGeolocationTbl(string asset)
        {
            // query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            // Compare the timestamp in lastupdtdata as well as lastupdtdataGL and if GL(ts) > ts then return it else return null
            if (!String.IsNullOrEmpty(asset))
            {
                String query1 = "select l.timestamp from lastupdtdata l where l.truckid = " + asset;
                //lParameter.Add("truckid", asset);
                // Object ts = dbx.executeScalar(query1,lParameter);
                Object ts = dbx.executeScalar(query1);
                DateTime tsGPS = DateTime.MinValue;
                DateTime tsGPRS = DateTime.MinValue;
                try
                {
                    tsGPRS = DateTime.Parse(ts.ToString());
                }
                catch { }
                //query.Clear();
                query1 = "select l.timestamp from lastupdtdataGL l where l.truckid = " + asset;
                //lParameter.Add("truckid", asset);
                //ts = dbx.executeScalar(query1, lParameter);
                ts = dbx.executeScalar(query1);
                try
                {
                    tsGPS = DateTime.Parse(ts.ToString());
                }
                catch { }
                //query.Clear();
                // return the lastupdtdataGL in case it is more current
                if (tsGPRS > tsGPS)
                {
                    //StringBuilder query = new StringBuilder();
                    query1 = "Select distinct p.truckId,CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,p.Stop,p.direction,v.IconType,v.OnOffType,v.TempSense,r.direction as trip_direction,p.hvinp,p.gvinp1,p.BV,p.haltfrom,p.fuellevel,p.panic "
                    + " from lastupdtdataGL p" +
                    " join vehicles v on v.VehicleId = p.truckId" +
                    " left join vehicleroutesummary r on p.truckid=r.vehicleid" +
                    " where p.TruckId = " + asset;
                    //lParameter.Add("TruckId", asset);

                    //lParameter = new Dictionary<string, object>();
                    DataTable lastPostable = dbx.executeQuery(query1).Tables[0];
                    ArrayList arglst = new ArrayList();
                    foreach (DataRow row in lastPostable.Rows)
                    {
                        arglst.Add(row.ItemArray);
                    }
                    return arglst.ToArray();
                }
                else
                    return null;
            }
            else return null;
        }
        //
        // This method returns the latest positiontxt from vehiclepositiontxtGL table if this table has an update later than vehiclepositiontxt for the same asset
        //
        public object[] getLatestPositiontxtGL(string asset)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            // Compare the timestamp in lastupdtdata as well as lastupdtdataGL and if GL(ts) > ts then return it else return null
            if (!String.IsNullOrEmpty(asset))
            {
                query.Append("select timestamp from vehiclepositiontxt  where truckid = '" + asset + "'");
                //lParameter.Add("", asset);
                Object ts = dbx.executeScalar(query.ToString());
                DateTime tsGPS = DateTime.MinValue;
                DateTime tsGPRS = DateTime.MinValue;
                try
                {
                    tsGPRS = DateTime.Parse(ts.ToString());
                }
                catch { }
                query.Clear();
                query.Append("select timestamp from vehiclepositiontxtGL  where truckid = '" + asset + "'");
                //lParameter.Add("truck", asset);
                ts = dbx.executeScalar(query.ToString());
                try
                {
                    tsGPS = DateTime.Parse(ts.ToString());
                }
                catch { }
                query.Clear();
                if (tsGPRS > tsGPS)
                {   // vehiclepositiontxtGL has the last known GPS position. 
                    query.Append("select vp.truckId,vp.positiontxt,vp.timestamp,vp.Latitude,vp.Longitude ");
                    query.Append("from vehiclepositiontxtGL vp ");
                    query.Append("where vp.truckId = '" + asset + "'");
                    //lParameter.Add("@truckId", asset);
                    DataTable dt = dbx.executeQuery(query.ToString()).Tables[0];
                    ArrayList list = new ArrayList();
                    foreach (DataRow row in dt.Rows)
                    {
                        list.Add(row.ItemArray);
                    }
                    return list.ToArray();
                }
                else
                    return null;
            }
            else return null;
        }

