        public void MergeDriverDocumentDetailsForEdit(string LicenceNo, int actionId, string FieldId)
        {
            string DriverId = "";
            string queryNewDriverDetails = "SELECT d.DriverId,d.Name,d.LicenceNo,d.Active FROM driverinfo d WHERE REPLACE(d.LicenceNo, ' ', '') = ?";
            var lParameter15 = new Dictionary<string, object>();
            lParameter15.Add("LicenceNo", LicenceNo);
            DataTable dtNewDriverDetails = dbx.executeQuery(queryNewDriverDetails.ToString(), lParameter15).Tables[0];

            int EditId = GetMAxEditId(actionId.ToString());
            DriverId = dtNewDriverDetails.Rows[0]["DriverId"].ToString();
            string NewDriverFileDetails = "SELECT a.Value,t.FieldName FROM tbl_trans_form_action_info a join tbl_trans_form_fields t ON a.FieldId=t.Id WHERE t.KeyWord='TotalDriverInfo' AND t.Id=? AND a.ActionId=? AND a.EditId=? AND a.Value !='' ";
            var lParameter16 = new Dictionary<string, object>();
            lParameter16.Add("Id", FieldId);
            lParameter16.Add("ActionId", actionId);
            lParameter16.Add("EditId", EditId);

            DataTable dtNewDriverFileDetails = dbx.executeQuery(NewDriverFileDetails.ToString(), lParameter16).Tables[0];

            if (dtNewDriverFileDetails.Rows.Count > 0)
            {
                string driverfieldname = dtNewDriverFileDetails.Rows[0]["FieldName"].ToString().Trim();
                string FileName = string.Join(",", dtNewDriverFileDetails.AsEnumerable().Select(r => r.Field<String>("Value")));
                string FieldName = string.Join(",", dtNewDriverFileDetails.AsEnumerable().Select(r => r.Field<String>("FieldName")));

                string[] doc = FieldName.Split(',');
                string[] files = FileName.Split(',');
                String query = "";
                int count = 0;
                if (files.Length > 0)
                {
                    for (int i = 0; i < files.Length; i++)
                    {
                        query = "SELECT d.Id,d.FileNo from driverdocument d JOIN tbl_trans_form_fields t ON d.DocumentName=t.FieldName WHERE d.DriverId = '" + DriverId + "' and d.DocumentName= '" + driverfieldname + "'  ";
                        DataTable dt = dbx.executeQuery(query).Tables[0];
                        if (dt.Rows.Count > 0)
                        {
                            int fileno = Convert.ToInt32(dt.Rows[0]["FileNo"]);
                            count = Convert.ToInt32(fileno + 1);

                            files[i] = "DD_" + count + DriverId + "_" + files[i];
                            files[i] = "Uploads/driverinfo/" + files[i];

                            query = "update driverdocument set DocumentName='" + doc[i] + "',FilePath='" + files[i] + "' where Id = '" + dt.Rows[0]["Id"].ToString() + "'";
                            dbx.executeNonQuery(query);

                        }
                        else
                        {

                            count = i + 1;

                            files[i] = "DD_" + count + DriverId + "_" + files[i];
                            files[i] = "Uploads/driverinfo/" + files[i];

                            query = "Insert into driverdocument(DocumentName,FilePath,DriverId,FileNo) values('" + doc[i] + "','" + files[i] + "'," + DriverId + "," + i + ")";
                            dbx.executeNonQuery(query);

                        }

                    }
                }
            }
        }
