        public void MergeVehicleDocumentsForEdit(string VehicleId, int actionId, string FieldId)
        {
            string vehId = VehicleId;
            int EditId = GetMAxEditId(actionId.ToString());
            string NewDriverFileDetails = "SELECT a.Value,t.FieldName FROM tbl_trans_form_action_info a join tbl_trans_form_fields t ON a.FieldId=t.Id WHERE t.KeyWord='TotalVehicleInfo' AND t.Id=? AND a.ActionId=? AND a.EditId=? AND a.Value !='' ";
            var lParameter16 = new Dictionary<string, object>();
            lParameter16.Add("Id", FieldId);
            lParameter16.Add("ActionId", actionId);
            lParameter16.Add("EditId", EditId);
            DataTable dtNewDriverFileDetails = dbx.executeQuery(NewDriverFileDetails.ToString(), lParameter16).Tables[0];

            if (dtNewDriverFileDetails.Rows.Count > 0)
            {
                string vehiclefieldname = dtNewDriverFileDetails.Rows[0]["FieldName"].ToString().Trim();
                string FileName = string.Join(",", dtNewDriverFileDetails.AsEnumerable().Select(r => r.Field<String>("Value")));
                string FieldName = string.Join(",", dtNewDriverFileDetails.AsEnumerable().Select(r => r.Field<String>("FieldName")));

                string[] doc = FieldName.Split(',');
                string[] files = FileName.Split(',');
                int count = 0;
                String query = "";
                if (files.Length > 0)
                {
                    for (int i = 0; i < files.Length; i++)
                    {
                        query = "SELECT d.Id,d.FileNo from vehicledocument d JOIN tbl_trans_form_fields t ON d.DocumentName=t.FieldName WHERE REPLACE(d.VehicleId,' ','') = '" + vehId.Trim().Replace(" ", "") + "' and d.DocumentName= '" + vehiclefieldname + "' ";
                        DataTable dt = dbx.executeQuery(query).Tables[0];
                        if (dt.Rows.Count > 0)
                        {
                            int fileno = Convert.ToInt32(dt.Rows[0]["FileNo"]);
                            count = fileno + 1;

                            files[i] = "VI_" + count + vehId.Replace(" ", "") + "_" + files[i];
                            files[i] = "Uploads/vehicleinfo/" + files[i];

                            query = "update vehicledocument set DocumentName='" + doc[i] + "',FilePath='" + files[i] + "' where Id = '" + dt.Rows[0]["Id"].ToString() + "'";
                            dbx.executeNonQuery(query);

                        }
                        else
                        {
                            count = i + 1;
                            files[i] = "VI_" + count + vehId.Replace(" ", "") + "_" + files[i];
                            files[i] = "Uploads/vehicleinfo/" + files[i];
                            query = "Insert into vehicledocument(DocumentName,FilePath,VehicleId,FileNo) values('" + doc[i] + "','" + files[i] + "'," + vehId + "," + i + ")";
                            dbx.executeNonQuery(query);

                        }

                    }
                }
            }
        }
        public void MergeVehicleDocuments(string VehicleId, int actionId)
        {
            string vehId = VehicleId;
            int EditId = GetMAxEditId(actionId.ToString());
            string NewDriverFileDetails = "SELECT a.Value,t.FieldName FROM tbl_trans_form_action_info a join tbl_trans_form_fields t ON a.FieldId=t.Id WHERE t.KeyWord='TotalVehicleInfo' AND t.Id IN(220,225,87,88,219,222,229,287) AND a.ActionId=? AND a.EditId=? AND a.Value !='' ";
            var lParameter16 = new Dictionary<string, object>();
            lParameter16.Add("ActionId", actionId);
            lParameter16.Add("EditId", EditId);
            DataTable dtNewDriverFileDetails = dbx.executeQuery(NewDriverFileDetails.ToString(), lParameter16).Tables[0];

            if (dtNewDriverFileDetails.Rows.Count > 0)
            {
                string FileName = string.Join(",", dtNewDriverFileDetails.AsEnumerable().Select(r => r.Field<String>("Value")));
                string FieldName = string.Join(",", dtNewDriverFileDetails.AsEnumerable().Select(r => r.Field<String>("FieldName")));

                string[] doc = FieldName.Split(',');
                string[] files = FileName.Split(',');
                int count = 0;
                if (files.Length > 0)
                {
                    for (int i = 0; i < files.Length; i++)
                    {
                        count = i + 1;
                        //doc[i] = doc[i];                                    
                        files[i] = "VI_" + count + vehId.Replace(" ", "") + "_" + files[i];
                        files[i] = "Uploads/vehicleinfo/" + files[i];

                    }
                }
                AddandUpdatevehicleDocs(vehId, doc, files);
            }
        }
