        public string InsertMobileGPSDetailsIntoPositionDetails(string sessionid, string source, string senttime, string rowscount, List<MobileGPSDetails> gpslistValues)
        {
            int resCount = 0;
            int timeZone = 5 * 60 * 60 + 30 * 60;
            //string q = "SELECT LAST_INSERT_ID()"; //Changed by Tusar 17/03/2021 -- Instead of doing max(id) from trackerdata,replace with LAST_INSERT_ID
            //string q = "SELECT MAX(id) FROM positiondata";
            //Int64 id = Convert.ToInt64(dbx.executeScalar(q));

            var lParameter = new Dictionary<string, object>();
            string query = "Insert ignore into positiondata (TruckID, TimeStamp, Start, Stop, Latitude, Longitude, Speed, FuelLevel, LAC, CI) values ";
            for (int i = 0; i < gpslistValues.Count; i++)
            {
                string dt = string.Empty;
                if (!String.IsNullOrEmpty(gpslistValues[i].gpstime))
                {
                    try
                    {
                        dt = formatDBDate(DateTime.ParseExact(gpslistValues[i].gpstime, "dd/MM/yyyy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                    }
                    catch (Exception e)
                    {
                        dt = formatDBDate(Convert.ToDateTime(gpslistValues[i].gpstime));
                    }
                }

                query += "(?,?,?,?,?,?,?,?,?,?),";
                //lParameter.Add("ID" + i, id);
                lParameter.Add("TruckID" + i, source);
                lParameter.Add("TimeStamp" + i, dt);
                lParameter.Add("Start" + i, 0);
                lParameter.Add("Stop" + i, 0);
                lParameter.Add("Latitude" + i, gpslistValues[i].lat);
                lParameter.Add("Longitude" + i, gpslistValues[i].lan);
                lParameter.Add("Speed" + i, gpslistValues[i].speed);
                lParameter.Add("FuelLevel" + i, 0);
                lParameter.Add("LAC" + i, 0);
                lParameter.Add("CI" + i, 0);

                if (i == 0)
                {
                    //Update vehiclepositiontxt
                    writePositionTextFromParser(Convert.ToDouble(gpslistValues[i].lat), Convert.ToDouble(gpslistValues[i].lan), Convert.ToDateTime(dt), source);

                    //Update lastupdtdata
                    updateLastPositionData(source, Convert.ToDateTime(dt), 0, 0, Convert.ToDouble(gpslistValues[i].lat), Convert.ToDouble(gpslistValues[i].lan), 0, 0, 0, 0, DateTime.UtcNow.AddSeconds(timeZone), 0, "0");
                }
            }
            query = query.Substring(0, query.Length - 1);
            resCount = dbx.executeNonQuery(query, lParameter);
            return resCount.ToString();
        }

        public string InsertMobileAppTrackerDetails(string sessionid, string source, string senttime, string rowscount, List<MobileAppDetails> applistValues)
        {
            int resCount = 0;
            var lParameter = new Dictionary<string, object>();
            string query = "Insert into mobileapptrackerdata (TruckID, TimeStamp, DataCount, BatteryLevel, GPSActive, MoblieData, AppStatus) values ";
            for (int i = 0; i < applistValues.Count; i++)
            {
                string dt = string.Empty;
