                {
                    try
                    {
                        dt = formatDBDate(DateTime.ParseExact(senttime, "dd/MM/yyyy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                    }
                    catch (Exception e)
                    {
                        dt = formatDBDate(Convert.ToDateTime(senttime));
                    }
