            return resCount.ToString();
        }

        public int InsertMobileAppTrackerConfigDetails(MobileAppTrackerConfig apptrackerconfigdetails)
        {
            string query = "UPDATE mobileapptracking_config_for_vehicle m SET m.Active = 0, m.IsActiveTrip = 0 WHERE m.VehicleNo = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleNo", apptrackerconfigdetails.VehicleId);
            dbx.executeScalar(query, lParameter);

            string licenseExpiryDate = string.Empty;
            string tripStartDate = null;
            string tripEndDate = null;
            if (!String.IsNullOrEmpty(apptrackerconfigdetails.LicenseExpiryDate))
            {
                try
                {
                    licenseExpiryDate = formatDBDate(DateTime.ParseExact(apptrackerconfigdetails.LicenseExpiryDate, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    licenseExpiryDate = formatDBDate(Convert.ToDateTime(apptrackerconfigdetails.LicenseExpiryDate));
                }
            }
            if (!String.IsNullOrEmpty(apptrackerconfigdetails.TripStartTime))
            {
                try
                {
                    tripStartDate = formatDBDate(DateTime.ParseExact(apptrackerconfigdetails.TripStartTime, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    tripStartDate = formatDBDate(Convert.ToDateTime(apptrackerconfigdetails.TripStartTime));
                }
            }
            if (!String.IsNullOrEmpty(apptrackerconfigdetails.TripEndTime))
            {
                try
                {
                    tripEndDate = formatDBDate(DateTime.ParseExact(apptrackerconfigdetails.TripEndTime, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    tripEndDate = formatDBDate(Convert.ToDateTime(apptrackerconfigdetails.TripEndTime));
                }
            }
            query = "Insert into mobileapptracking_config_for_vehicle (VehicleNo, DriverName, MobileNo, LicenseNo, LicenseExpiryDate, GPSAcqFrequency, DataUpdateFrequency, Is24HrTracking,NoOfHoursToTrack, TripStartTime, TripEndTime, IsActiveTrip, Domain1, Domain2, TransporterId, GroupID, AccountID, GlobalAccID, Active)" +
                            " values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
            lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleNo", apptrackerconfigdetails.VehicleId);
            lParameter.Add("DriverName", apptrackerconfigdetails.DriverName);
            lParameter.Add("MobileNo", apptrackerconfigdetails.MobileNo);
            lParameter.Add("LicenseNo", apptrackerconfigdetails.LicenseNo);
            lParameter.Add("LicenseExpiryDate", licenseExpiryDate);
            lParameter.Add("GPSAcqFrequency", apptrackerconfigdetails.GPSAcqFrequency);
            lParameter.Add("DataUpdateFrequency", apptrackerconfigdetails.DataUpdateFrequency);
            lParameter.Add("Is24HrTracking", apptrackerconfigdetails.Is24HrTracking);
            lParameter.Add("NoOfHoursToTrack", apptrackerconfigdetails.NoOfHoursToTrack);
            lParameter.Add("TripStartTime", tripStartDate);
            lParameter.Add("TripEndTime", tripEndDate);
            lParameter.Add("IsActiveTrip", 1);
            lParameter.Add("Domain1", apptrackerconfigdetails.Domain1);
            lParameter.Add("Domain2", apptrackerconfigdetails.Domain2);
            lParameter.Add("TransporterId", apptrackerconfigdetails.TransporterId);
            lParameter.Add("GroupID", apptrackerconfigdetails.GroupID);
            lParameter.Add("AccountID", apptrackerconfigdetails.AccountID);
            lParameter.Add("GlobalAccID", apptrackerconfigdetails.GlobalAccID);
            lParameter.Add("Active", 1);
            return Convert.ToInt32(dbx.executeScalar(query, lParameter));
        }

        public DataTable GetMobileAppTrackerVehiclesList(string sessionid)
        {
            int accountId = GetAccountId(sessionid);
            int groupid = getGroupId(sessionid);
            string query = "SELECT DISTINCT d.AssignedVehicleID FROM mobileappdriverchangelog d WHERE d.GroupID = ? AND d.AccountID = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupID", groupid);
            lParameter.Add("AccountID", accountId);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];

        }
        public DataTable GetMobileAppTrackerVehiclesDetails(string vehicleid)
        {
            string query = "SELECT * FROM mobileappdriverchangelog d WHERE d.AssignedVehicleID = ? ORDER BY d.ID DESC LIMIT 1;";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AssignedVehicleID", vehicleid);
            return dbx.executeQuery(query.ToString(), lParameter).Tables[0];

        }
