                dbx.executeScalar(query, lParameter);


                //Insert into driverinfo 
                query = "insert into driverinfo(Name, MobileNo, LicenceNo, LicenceValid, AssignedVehicleId, Transporter, AccountId, GroupId, Active) values(?,?,?,?,?,?,?,?,?)";
                lParameter = new Dictionary<string, object>();
