                lParameter.Add("AccountId", accountId);
                lParameter.Add("GroupId", groupid);
                lParameter.Add("Active", 1);
                dbx.executeScalar(query, lParameter);
            }
            else
            {
                //Remove Assigned vehicle from Driver Info
                query = "Update driverinfo set AssignedVehicleId= '' where AssignedVehicleId = ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("AssignedVehicleId", vehicle);
                dbx.executeNonQuery(query);

                //Update driverinfo if license no exist otherwise 
