            lParameter.Add("GroupID", groupid);
            lParameter.Add("AccountID", accountId);
            lParameter.Add("AddedBy", username);
            dbx.executeScalar(query, lParameter);


            // Insert into mysensel.com
            string baseurl = GetBaseURL();
            string tripStart = null;
            string tripend = null;
            string globalid = GetGlobalAccountIdBySession(sessionid.ToString());
            string postData = "{\"apptrackerconfigdetails\": {\"VehicleId\": \"" + vehicle + "\",\"DriverName\": \"" + drivername + "\",\"MobileNo\": \"" + mobileno + "\",\"LicenseNo\": \"" + licenseno + "\",\"LicenseExpiryDate\": \"" + licensevalidity + "\"," +
