        public int InsertMobileAppTripDetails(string sessionid, string username, string tripStartLocation, string tripEndLocation, string invoicenum, string remarks, MobileAppTrackerConfig apptrackerconfigdetails)
        {
            string baseurl = GetBaseURL();
            string globalid = GetGlobalAccountIdBySession(sessionid.ToString());

            string licenseExpiryDate = string.Empty;
            string tripStartDate = null;
            string tripEndDate = null;
            if (!String.IsNullOrEmpty(apptrackerconfigdetails.LicenseExpiryDate))
            {
                try
                {
                    licenseExpiryDate = formatDBDate(DateTime.ParseExact(apptrackerconfigdetails.LicenseExpiryDate, "dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    licenseExpiryDate = formatDBDate(Convert.ToDateTime(apptrackerconfigdetails.LicenseExpiryDate));
                }
            }
            if (!String.IsNullOrEmpty(apptrackerconfigdetails.TripStartTime))
            {
                try
                {
                    tripStartDate = formatDBDate(DateTime.ParseExact(apptrackerconfigdetails.TripStartTime, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    tripStartDate = formatDBDate(Convert.ToDateTime(apptrackerconfigdetails.TripStartTime));
                }
            }
            if (!String.IsNullOrEmpty(apptrackerconfigdetails.TripEndTime))
            {
                try
                {
                    tripEndDate = formatDBDate(DateTime.ParseExact(apptrackerconfigdetails.TripEndTime, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    tripEndDate = formatDBDate(Convert.ToDateTime(apptrackerconfigdetails.TripEndTime));
                }
            }

            TimeSpan difference = Convert.ToDateTime(tripEndDate).Subtract(Convert.ToDateTime(tripStartDate));
            int noOfHoursToTrack = Convert.ToInt32(difference.TotalMinutes);

            try
            {
                string postData = "{\"apptrackerconfigdetails\": {\"VehicleId\": \"" + apptrackerconfigdetails.VehicleId + "\",\"DriverName\": \"" + apptrackerconfigdetails.DriverName + "\",\"MobileNo\": \"" + apptrackerconfigdetails.MobileNo + "\",\"LicenseNo\": \"" + apptrackerconfigdetails.LicenseNo + "\",\"LicenseExpiryDate\": \"" + apptrackerconfigdetails.LicenseExpiryDate + "\"," +
                "\"GPSAcqFrequency\": \"" + apptrackerconfigdetails.GPSAcqFrequency + "\",\"DataUpdateFrequency\": \"" + apptrackerconfigdetails.DataUpdateFrequency + "\",\"Is24HrTracking\": \"" + apptrackerconfigdetails.Is24HrTracking + "\",\"NoOfHoursToTrack\": \"" + noOfHoursToTrack + "\",\"TripStartTime\": \"" + apptrackerconfigdetails.TripStartTime + "\",\"TripEndTime\": \"" + apptrackerconfigdetails.TripEndTime + "\"," +
                "\"Domain1\": \"" + baseurl + "\",\"Domain2\": \"\",\"TransporterId\": \"" + apptrackerconfigdetails.TransporterId + "\",\"GroupID\": \"" + apptrackerconfigdetails.GroupID + "\",\"AccountID\": \"" + apptrackerconfigdetails.AccountID + "\",\"GlobalAccID\": \"" + globalid + "\"}}";
                string sds = MakeHttpRequest("https://ui.mysensel.com/SenselRestService.svc/rest/v3/PostMobileTrackerConfigData", "POST", "application/json", postData);
            }
            catch (Exception ex)
            {

            }

            string query = "Insert into mobileapptracker_trip_details (VehicleNo, TripStartTime, TripStartLocation, TripEndTime, TripEndLocation, InvoiceNum, Remarks, IsActiveTrip, TripCreatedBy, GroupId, AccountId)" +
                            " values(?,?,?,?,?,?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleNo", apptrackerconfigdetails.VehicleId);
            lParameter.Add("TripStartTime", tripStartDate);
            lParameter.Add("TripStartLocation", tripStartLocation);
            lParameter.Add("TripEndTime", tripEndDate);
            lParameter.Add("TripEndLocation", tripEndLocation);
            lParameter.Add("InvoiceNum", invoicenum);
            lParameter.Add("Remarks", remarks);
            lParameter.Add("IsActiveTrip", 1);
            lParameter.Add("TripCreatedBy", username);
            lParameter.Add("GroupID", apptrackerconfigdetails.GroupID);
            lParameter.Add("AccountID", apptrackerconfigdetails.AccountID);

            return Convert.ToInt32(dbx.executeScalar(query, lParameter));
        }

        public Object[] getLastUpdtData(String vehicleId)
        {
            StringBuilder query = new StringBuilder();
            query.Append("select timestamp,stop,latitude,longitude,direction,start,speed,ServerTS,haltlat,haltlong,haltfrom from lastupdtdata where truckid='" + vehicleId + "'");
            DataTable dt = dbx.executeQuery(query.ToString()).Tables[0];
            ArrayList lastUpdtData = new ArrayList();
            foreach (DataRow row in dt.Rows)
            {
                lastUpdtData.Add(row.ItemArray);
            }
            return lastUpdtData.ToArray();
        }
