        public string CheckDutyTime(string vehicleId)
        {
            try
            {
                String query = "select v.DutyTime from vehiclessnapshot v where v.vehicleId='" + vehicleId + "' order by lastUpdateTime  desc limit 1";
                object Obj = dbx.executeScalar(query).ToString();
                double time = Convert.ToDouble(Obj);
                TimeSpan ts = TimeSpan.FromMinutes(time);
                return string.Format("{0}hr {1}min",
                 String.Format("{0:00}", ((int)ts.TotalHours)),
                 ts.Minutes,
                 ts.Seconds);
            }
            catch
            { }
            return string.Empty;
        }

