        public string AssetSmartApp_OTPRequest(string mobileno)
        {
            try
            {
                string query = "select p.*,a.globalaccountid from empl_info p join accounts a on a.Id=p.AccountId where p.MobileNo= ? and p.Active =1";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("Mobile", mobileno);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                if (dt.Rows.Count > 0)
                {
                    Random rand = new Random();
                    string otp = rand.Next(100000, 999999).ToString();
                    string str = "One Time Password for ASSET-SMART is " + otp;
                    //this mobileno for demo login
                    if (mobileno == "1020304050")
                        otp = "9080";
                    else
                        SendSMSByAdminService(dt.Rows[0]["globalaccountid"].ToString(), "", mobileno, str, "Asset-SMART App OTP", "");
                    query = "Insert into otp_sessions(`Type`,empid,MobileNo,OTP,OTP_GeneratedOn,login,sessionid,AccountId)" +
                            " values(?,?,?,?,?,?,?,?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("Type", "Employee");
                    lParameter.Add("empid", dt.Rows[0]["empid"].ToString());
                    lParameter.Add("MobileNo", mobileno);
                    lParameter.Add("OTP", otp);
                    lParameter.Add("OTP_GeneratedOn", formatDBDate(DateTime.Now));    /// Server time datetime setting
                    lParameter.Add("login", dt.Rows[0]["login"].ToString());
                    lParameter.Add("sessionid", dt.Rows[0]["sessionid"].ToString());
                    lParameter.Add("AccountId", dt.Rows[0]["AccountId"].ToString());
                    dbx.executeNonQuery(query, lParameter);
                    return "OTP Send Successfully";
                }
                else
                {
                    return "Mobile Number is Not Registered.";
                }
            }
            catch (Exception ex) { return ex.Message; }
        }

        public DataTable AssetSmartApp_OTPValidate(string mobileno, string OTP)
        {
            String ts = formatDBDate(DateTime.Now.AddSeconds(-30 * 60));   //server time datetime setting. OTP should be not OLDER than 30 mins
            try
            {
                string query = "select o.*,e.EmpName from otp_sessions o join empl_info e on e.mobileno = o.mobileno where o.MobileNo=? and e.Active =1 and "
                    + "o.OTP=? and o.`Type`='Employee' and o.OTP_GeneratedON > '" + ts + "'";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("mobileno", mobileno);
                lParameter.Add("OTP", OTP.Trim());
                return (dbx.executeQuery(query, lParameter).Tables[0]);
            }
            catch (Exception ex) { return null; }
        }

