        public string InsertBranchMobileGpsDetails(string sessionid, string source, string senttime, string rowscount, List<BranchMobileGPSDetails> gpslistValues)
        {
            int resCount = 0;
            int timeZone = 5 * 60 * 60 + 30 * 60;
            //string q = "SELECT LAST_INSERT_ID()"; //Changed by Tusar 17/03/2021 -- Instead of doing max(id) from trackerdata,replace with LAST_INSERT_ID
            //string q = "SELECT MAX(id) FROM positiondata";
            //Int64 id = Convert.ToInt64(dbx.executeScalar(q));

            var lParameter = new Dictionary<string, object>();
            string query = "Insert ignore into branchpositiondata (alias, TimeStamp, Latitude, Longitude, accuracy, provider) values ";
            for (int i = 0; i < gpslistValues.Count; i++)
            {
                string dt = string.Empty;
                if (!String.IsNullOrEmpty(gpslistValues[i].timestamp))
                {
                    try
                    {
                        dt = formatDBDate(DateTime.ParseExact(gpslistValues[i].timestamp, "dd/MM/yyyy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                    }
                    catch (Exception e)
                    {
                        dt = formatDBDate(Convert.ToDateTime(gpslistValues[i].timestamp));
                    }
                }

                query += "(?,?,?,?,?,?),";
                //lParameter.Add("ID" + i, id);
                lParameter.Add("alias" + i, source);
                lParameter.Add("timestamp" + i, dt);
                lParameter.Add("Latitude" + i, gpslistValues[i].lat);
                lParameter.Add("Longitude" + i, gpslistValues[i].lon);
                lParameter.Add("accuracy" + i, gpslistValues[i].accuracy);
                lParameter.Add("provider" + i, gpslistValues[i].provider);
            }
            query = query.Substring(0, query.Length - 1);
            resCount = dbx.executeNonQuery(query, lParameter);
            return resCount.ToString();
        }

