        //Added by suvarna on 11/8/2021 to change Asset/Vehicle dynamically in all the reports
        public string getUIDType(string sessionId)
        {
            DataTable dt = GetAccountGroupConfig(sessionId);
            string barfeature = string.Empty;
            String type = string.Empty;
            if (dt.Rows.Count > 0)
            {
                barfeature = Convert.ToString(dt.Rows[0]["barfeatures"]);
                if (barfeature.ToLower().ToString() == "at")
                    type = "Asset";//Modifie by suvarna on 23/10/2021 for changes in landing page
                else if (barfeature.ToLower().ToString() == "rail")
                    type = "Rail";
                else
                    type = "vehicle";
            }
            return type;
        }
