        public Dictionary<string, string> GetBranchIdsForAssets(List<string> assets)
        {
            StringBuilder query = new StringBuilder();
            Dictionary<string, string> branchIdMap = new Dictionary<string, string>();

            query.Append("SELECT d.UID,b.BranchID FROM branchdata b,devicebranchallocation d WHERE b.BranchID=d.BranchID AND d.UID in (");

            // Append each asset to the query
            query.Append(string.Join(",", assets.Select(asset => "'" + asset + "'")));

            query.Append(")");

            DataSet resultDataSet = dbx.executeQuery(query.ToString());

            // Assuming only one DataTable is returned
            if (resultDataSet != null && resultDataSet.Tables.Count > 0)
            {
                DataTable resultTable = resultDataSet.Tables[0];

                foreach (DataRow row in resultTable.Rows)
                {
                    string asset = row["UID"].ToString();
                    string branchId = row["BranchID"].ToString();
                    branchIdMap[asset] = branchId;
                }
            }

            return branchIdMap;
        }
