        public Int64 writeLowFreqBMSData(XmlNode pdu, String truckId)
        {
            XmlNodeList positions = pdu.SelectNodes("./bmshf");
            //XmlNodeList CANnodes = pdu.SelectNodes("./CAN");
            StringBuilder query = new StringBuilder();
            //if (!ReplaceData)
            query.Append("insert into lowfreqbmsdata ");
            //else
            //  query.Append("replace into trackerdata ");
            query.Append("(TruckID, FromTimeStamp, ToTimeStamp, bmsts1, bmsts2, bmsts3, bmsts4, bmsts5, bmsxa, bmsxb, bmsya, bmsza, bmsxap, bmsxbp, bmsyp, bmszp, bmstilt, ServerTS) values(\"");
            query.Append(truckId);
            query.Append("\",");
            XmlNode fromDate = positions.Item(0).Attributes.GetNamedItem("date");
            DateTime fromTS = DateTime.Parse(fromDate.Value);
            String fromTSStr = fromTS.ToString("u");
            String frmttdFromTSStr = fromTSStr.Substring(0, fromTSStr.Length - 1);
            query.Append("\"" + frmttdFromTSStr + "\"");
            query.Append(",");
            XmlNode toDate = positions.Item(positions.Count - 1).Attributes.GetNamedItem("date");
            DateTime toTS = DateTime.Parse(toDate.Value);
            String toTSStr = toTS.ToString("u");
            String frmttdToTSStr = toTSStr.Substring(0, toTSStr.Length - 1);
            query.Append("\"" + frmttdToTSStr + "\"");
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsts1").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsts2").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsts3").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsts4").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsts5").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsxa").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsxb").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsya").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsza").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsxap").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsxbp").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmsyp").Value);
            query.Append(",");
            query.Append(pdu.Attributes.GetNamedItem("bmszp").Value);
            query.Append(",");
            //Alarm Data
            query.Append(pdu.Attributes.GetNamedItem("bmstilt").Value);
            query.Append(",");
            /*
            //Caller Phone
            XmlNode caller = pdu.Attributes.GetNamedItem("CallerPhone");
            if (caller != null)
            {
                query.Append("'" + caller.Value + "'");
            }
            else
            {
                query.Append("NULL");
            }
            query.Append(",");
            if (pdu.Attributes.GetNamedItem("altitude") != null)
                query.Append(pdu.Attributes.GetNamedItem("altitude").Value);
            else
                query.Append(altitude);
            query.Append(",");*/
            query.Append("\"" + formatDBDate(DateTime.UtcNow.AddSeconds(GetTimeZoneDiff())) + "\"");
            query.Append(");");
            //Console.WriteLine(query.ToString());
            //Console.ReadKey(true);
            try
            {
                dbx.executeNonQuery(query.ToString());
            }
            catch (System.Data.Odbc.OdbcException e)
            {
                bool duplicate = false;
                for (int j = 0; j < e.Errors.Count; j++)
                {
                    // Check for duplicate entries error and suppress it
                    if (e.Errors[j].NativeError == 1062)
                    {
                        duplicate = true;
                    }
                }
                if (duplicate == false)
                {
                    throw e;
                }
                return -1;
            }
            string q = "SELECT LAST_INSERT_ID()"; //Changed by Gopal 18/12/2017 -- Instead of doing max(id) from trackerdata,replace with LAST_INSERT_ID
            Int64 id = Convert.ToInt64(dbx.executeScalar(q));
            for (int i = 0; i < positions.Count; i++)
            {
                try
                {
                    XmlNode position = positions.Item(i);
                    writeBMSHFData(position, id, truckId);
                }
                catch (System.Data.Odbc.OdbcException e)
                {
                    bool duplicate = false;
                    for (int j = 0; j < e.Errors.Count; j++)
                    {
                        // Check for duplicate entries error and suppress it						
                        if (e.Errors[j].NativeError == 1062)
                        {
                            duplicate = true;
                        }
                    }
                    if (duplicate == false)
                    {
                        throw e;
                    }
                }
            }

            return (id);
        }

        public void writeBMSHFData(XmlNode position, Int64 id, String truckId)
        {
            StringBuilder query = new StringBuilder();
            //#if PANIC
            //#else

            //if (!ReplaceData)
            query.Append("insert into highfreqbmsdata ");
            //else
            //    query.Append("replace into positiondata ");

            query.Append("(ID, TruckID, TimeStamp,bmtsv1,bmtsi,bmtsv2,bmtsv3,bmtsv4) values(");
            //#endif
            query.Append(id);
            query.Append(",\"");
            query.Append(truckId);
            query.Append("\",");
            XmlNode date = position.Attributes.GetNamedItem("date");
            DateTime timestamp = DateTime.Parse(date.Value);
            String timestampStr = timestamp.ToString("u");
            String formattedTsStr = timestampStr.Substring(0, timestampStr.Length - 1);
            query.Append("\"" + formattedTsStr + "\"");
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("bmtsV1").Value);
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("bmtsI").Value);
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("bmtsV2").Value);
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("bmtsV3").Value);
            query.Append(",");
            query.Append(position.Attributes.GetNamedItem("bmtsV4").Value);
            query.Append(");");

            //Console.WriteLine(query.ToString());
            //Console.ReadKey(true);
            dbx.executeNonQuery(query.ToString());
        }
