        public DateTime getTripStartTSForVehicle(String vehicleId, String viotime)
        {
            String query = "select outtimestamp from vehicleinplant where vehicleid = ? and outtimestamp < ? and planttype in (0) and reportstatus = 0 order by outtimestamp desc LIMIT 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleid", vehicleId);
            lParameter.Add("outtimestamp", formatDBDate(Convert.ToDateTime(viotime)));
            object tsObj = dbx.executeScalar(query.ToString(), lParameter);
            DateTime dt = DateTime.MinValue;
            try
            {
                dt = Convert.ToDateTime(tsObj);
            }
            catch
            {


            }
            if (dt == DateTime.MinValue)
            {
                query = "select outtimestamp from vehicleinplant where vehicleid =? and outtimestamp < ? and planttype in (0) and reportstatus = 0 order by outtimestamp desc LIMIT 1";
                lParameter.Clear();
                lParameter.Add("vehicleid", vehicleId);
                lParameter.Add("outtimestamp", formatDBDate(Convert.ToDateTime(viotime)));
                tsObj = dbx.executeScalar(query.ToString(), lParameter);
                dt = Convert.ToDateTime(tsObj);
            }
            return dt;
        }
