		public void GetViolationData(string vehicleid, string data)
        {
            //Modified by suvarna on 23 / 11 / 2021 as blank JSONs data were being send to ADANI endpoint'
            // updated - if accountid based entry is not there check for groupid based entry as adani wants only one login to send data
            int accid = getAccountIdByVehicleId(vehicleid);
            DataTable dtpush = getPushAPIConfig(accid);
            if (dtpush.Rows.Count == 0)
            {
                int groupid = getGroupIdByVehicleid(vehicleid);
                dtpush = getPushAPIConfig(groupid);
            }
            string id = string.Empty;
            for (int i = 0; i < dtpush.Rows.Count; i++)
            {
                try
                {
                    //if (dtpush.Rows[i]["Active"].ToString() == "True")
                    //{
                    string EndPoint = dtpush.Rows[i]["URL"].ToString();
                    string log = dtpush.Rows[i]["Log"].ToString();
                    string ContentType = dtpush.Rows[i]["ContentType"].ToString();
                    string HTTPMethod = dtpush.Rows[i]["HTTPMethod"].ToString();
                    string res = MakeHttpRequest(EndPoint, HTTPMethod, ContentType, data);
                    if (log == "1")
                    {
                        id = dtpush.Rows[i]["id"].ToString();
