        public DataTable getPushAPIConfigForAdaniSOUL(int accountid)
        {
            string query = "select * from tbl_push_chng_data a where a.Active=1 and a.AccountId=? and a.API = 'SendViolationDetailsForAdani'";
            var lParameter = new Dictionary<string, object>();
