        }
        public void GetViolationDataForAdaniSOUL(string vehicleid, string data)
        {
            int accid = getAccountIdByVehicleId(vehicleid);
            DataTable dtpush = getPushAPIConfigForAdaniSOUL(accid);
            if (dtpush.Rows.Count == 0)
            {
                int groupid = getGroupIdByVehicleid(vehicleid);
                dtpush = getPushAPIConfigForAdaniSOUL(groupid);
            }
            string id = string.Empty;
            for (int i = 0; i < dtpush.Rows.Count; i++)
            {
                try
                {
                    string EndPoint = dtpush.Rows[i]["URL"].ToString();
                    string log = dtpush.Rows[i]["Log"].ToString();
                    string ContentType = dtpush.Rows[i]["ContentType"].ToString();
                    string HTTPMethod = dtpush.Rows[i]["HTTPMethod"].ToString();
                    string Headers = dtpush.Rows[i]["Headers"].ToString();

                    if (!data.Contains("requestAlert"))
                    {
                        string res = MakeHttpRequestForAdaniSOUL(EndPoint, HTTPMethod, ContentType, data, Headers);
                        if (log == "1")
                        {
                            id = dtpush.Rows[i]["id"].ToString();
                            string query = "insert into tbl_push_chng_data_log(PushId,response,ServerTS,data) values(?,?,?,?)";
                            var lParameter = new Dictionary<string, object>();
                            lParameter.Add("PushId", id);
                            lParameter.Add("response", res);
                            lParameter.Add("ServerTS", formatDBDate(DateTime.Now));
                            lParameter.Add("data", data);
                            dbx.executeNonQuery(query.ToString(), lParameter);

                        }
                    }
                }
                catch (Exception ex)
                {
                    string query = "insert into tbl_push_chng_data_log(PushId,response,ServerTS,data) values(?,?,?,?)";
                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("PushId", id);
                    lParameter.Add("response", ex.ToString());
                    lParameter.Add("ServerTS", formatDBDate(DateTime.Now));
                    lParameter.Add("data", data);
                    dbx.executeNonQuery(query.ToString(), lParameter);
                }

            }
        }


