        public DataTable Get_DIPReportForTotal(int accountid, string TransporterId, string formDate, string toDate, string licenceNo)
        {
            string frdate = string.Empty;
            string tdate = string.Empty;
            if (!String.IsNullOrEmpty(formDate))
            {
                try
                {
                    frdate = formatDBDate(DateTime.ParseExact(formDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    frdate = formatDBDate(Convert.ToDateTime(formDate));
                }
            }
            if (!String.IsNullOrEmpty(toDate))
            {
                try
                {
                    tdate = formatDBDate(DateTime.ParseExact(toDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    tdate = formatDBDate(Convert.ToDateTime(toDate));
                }
            }
            string query = "";
            var lParameter = new Dictionary<string, object>();

            if (accountid == 14)
            {
                string FieldId = "4";

                query = "SELECT t.ShortName,d.Name,d.LicenceNo,f.Value,DATE_FORMAT(v.DateTime, '%d/%m/%Y %H:%i:%s %p') as 'DateTime',v.AddedBy,u.Name as TransporterName,v.FileName,v.Id FROM vet_static_details v " +
                    "INNER JOIN vet_field_values f ON f.VetId = v.Id " +
                    "INNER JOIN driverinfo d ON replace(d.LicenceNo,' ','') = replace(f.Value,' ','') " +
                    "INNER JOIN transporterinfo t ON t.TransporterId = d.Transporter " +
                    "INNER JOIN users u ON u.login = v.AddedBy " +
                    "WHERE v.DateTime BETWEEN ? AND ? AND f.FieldId = ? AND v.AccountId =? AND d.Active = 1 ";
                lParameter.Add("formDate", frdate);
                lParameter.Add("toDate", tdate);
                lParameter.Add("FieldId", FieldId);
                lParameter.Add("AccountId", accountid);
                if (licenceNo != "--Select License--" && licenceNo != "")
                {
                    query += "AND replace(f.Value,' ','') = ?  ";
                    lParameter.Add("LicenceNo", licenceNo.Replace(" ", ""));
                }
                if (TransporterId != "0")
                {
                    query += " AND t.TransporterId=?  ";
                    lParameter.Add("TransporterId", TransporterId);
                }
                query += " ORDER BY v.DateTime DESC";
            }
            else
            {
                string FieldId = "1";
                query = "SELECT t.ShortName,d.Name,d.LicenceNo,f.Value,DATE_FORMAT(v.DateTime, '%d/%m/%Y %H:%i:%s') as 'DateTime',v.AddedBy,u.Name as TransporterName,v.FileName,v.Id FROM vet_static_details v " +
                    "INNER JOIN vet_field_values f ON f.VetId = v.Id " +
                    "INNER JOIN driverinfo d ON replace(d.LicenceNo,' ','') = replace(f.Value,' ','') " +
                    "INNER JOIN transporterinfo t ON t.TransporterId = d.Transporter " +
                    "INNER JOIN users u ON u.login = v.AddedBy " +
                    "WHERE v.DateTime BETWEEN ? AND ? AND f.FieldId = ? AND v.AccountId =? AND d.Active = 1 ";
                lParameter.Add("formDate", frdate);
                lParameter.Add("toDate", tdate);
                lParameter.Add("FieldId", FieldId);
                lParameter.Add("AccountId", accountid);
                if (licenceNo != "--Select License--" && licenceNo != "")
                {
                    query += "AND replace(f.Value,' ','') = ?  ";
                    lParameter.Add("LicenceNo", licenceNo.Replace(" ", ""));
                }
                if (TransporterId != "0")
                {
                    query += " AND t.TransporterId=?  ";
                    lParameter.Add("TransporterId", TransporterId);
                }
                query += " ORDER BY v.DateTime DESC";

            }
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable Get_TechnicalInvariantTotal(int accountid, string TransporterName, string formDate, string toDate, string VehicleNo, string loginName)
        {
            string frdate = string.Empty;
            string tdate = string.Empty;
            if (!String.IsNullOrEmpty(formDate))
            {
                try
                {
                    frdate = formatDBDate(DateTime.ParseExact(formDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    frdate = formatDBDate(Convert.ToDateTime(formDate));
                }
            }
            if (!String.IsNullOrEmpty(toDate))
            {
                try
                {
                    tdate = formatDBDate(DateTime.ParseExact(toDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    tdate = formatDBDate(Convert.ToDateTime(toDate));
                }
            }
            string query = "select a.truckRegNo as VehicleNo,a.inspectName,u.Name as AddedBy,DATE_FORMAT(a.DateTime, '%d/%m/%Y %H:%i:%s %p') as 'AddedOn',a.Filename from " +
                "veh_inv_details a left join users u on a.AddedBy=u.login where a.AccountID=? and a.DateTime between ? and ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountid);
            lParameter.Add("formDate", frdate);
            lParameter.Add("toDate", tdate);
            //if (string.IsNullOrEmpty(VehicleNo))

            if (TransporterName != "--Select Transporter--" && VehicleNo != "--Select Vehicle--")
            {
                query += " and REPLACE(a.truckRegNo,' ','')=? ";
                lParameter.Add("truckRegNo", VehicleNo.Replace(" ", ""));
            }
            else if (TransporterName != "--Select Transporter--")
            {
                int groupid = getGroupIdByLogin(loginName);
                query += " AND REPLACE(a.truckRegNo,' ','') IN (SELECT REPLACE(v.VehicleId,' ','') FROM vehiclesgroupsmap v WHERE v.GroupId = ?)";
                lParameter.Add("GroupId", groupid);
            }
            query += " order by a.DateTime desc";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
