        public DataTable GetBatteryPerformanceReport(string formDate, string todate, int accountid, string username, string DeviceId, string groupid)
        {
            string frdate = string.Empty;
            string tdate = string.Empty;
            if (!String.IsNullOrEmpty(formDate))
            {
                try
                {
                    frdate = formatDBDate(DateTime.ParseExact(formDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    frdate = formatDBDate(Convert.ToDateTime(formDate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    tdate = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    tdate = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            var lParameter = new Dictionary<string, object>();
            string query = "select h.truckid,h.timestamp, h.bmtsv1, h.bmtsv2, h.bmtsv3, h.bmtsv4, h.bmtsi, l.bmsts1 as motortemp,l.bmsts2 as bat1temp,l.bmsts3  as bat2temp," +
                "l.bmsts4 as bat3temp, l.bmsts5 as bat4temp, l.bmsxa as xapeak, l.bmsxb as xbpeak, l.bmsya as yapeak, l.bmsza as zapeak, " +
                "l.bmsxa as xavg,l.bmsxb xbavg, l.bmsyp as ypavg, l.bmsza as zavg, l.bmstilt as tilt from lowfreqbmsdata l, " +
                "highfreqbmsdata h where l.ID = h.ID and h.timestamp between ? and ? ";
            lParameter.Add("formDate", frdate);
            lParameter.Add("todate", tdate);
            if (DeviceId != "--Select DeviceId--")
            {
                query += " and h.truckid=? ";
                lParameter.Add("truckid", DeviceId);
            }
            else
            {
                query += " and h.truckid in (select VehicleId from vehiclesgroupsmap where GroupId= ?)";
                lParameter.Add("GroupId", groupid);
            }
            //lParameter.Add("AccountId", accountid);
            query += " ORDER BY h.timestamp desc";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        //Added By Tusar on 25022022
        public DataTable GetAllDCTripDetailsByGroupId(int groupid)
        {
            try
            {
                string query = "SELECT DISTINCT v.id,v.VehicleID,d.Name AS 'DriverName',DATE_FORMAT(v.DateTime, '%d-%m-%Y %h:%i:%s %p') as `DateTime`,v.IsTripEnds,v.TripEndsOn,v.AddedBy,g.locstr,i.Name AS 'CustomerName',c.customerid,i.CustomerCode,r.routeid,v.LoadingPlaceName FROM vehicledctrip v " +
                    "JOIN customerdcassign c ON c.DCTripId = v.id " +
                    "JOIN driverinfo d ON d.AssignedVehicleId = v.VehicleID " +
                    "JOIN customerinfo i ON i.customerId = c.CustomerId " +
                    "JOIN plantlogin p ON p.login = v.AddedBy " +
                    "JOIN plantgeolocations g ON g.customerid = p.customerid " +
                    "JOIN customerroute r ON r.customerid = i.CustomerCode " +
                    "WHERE v.VehicleID IN(SELECT m.VehicleId FROM vehiclesgroupsmap m WHERE m.GroupId = ?) " +
                    "AND v.IsTripEnds = 0 AND i.customerId IN " +
                    "(SELECT MIN(c1.CustomerId) FROM vehicledctrip v1 " +
                    "INNER JOIN customerdcassign c1 ON c1.DCTripId = v1.id " +
                    "WHERE v1.VehicleID = v.VehicleID GROUP BY v1.id " +
                    "ORDER BY v1.DateTime DESC) GROUP BY v.id ORDER BY v.DateTime DESC";

                var lParameter = new Dictionary<string, object>();
                lParameter.Add("GroupId", groupid);
                return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            catch (Exception ex) { return null; }
        }

