            if (!String.IsNullOrEmpty(ToDate))
            {
                try
                {
                    todate = formatDBDate(DateTime.ParseExact(ToDate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    todate = formatDBDate(Convert.ToDateTime(ToDate));
                }
            }
            string query = "insert into titan_vehicle_tripdetails (VehicleId,fromdate,todate,Addedon,Addedby,"
                           + "Active,AccountId) values(?,?,?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("VehicleId", VehicleId);
            lParameter.Add("fromdate", frdate);
            lParameter.Add("todate", todate);
            lParameter.Add("Addedon", Addedon);
            lParameter.Add("Addedby", username);
            lParameter.Add("Active", 1);
            lParameter.Add("AccountId", accountid);
            int result = dbx.executeNonQuery(query.ToString(), lParameter);
            return result.ToString();

        }
        public DataSet GetTripDetails(int accountid, string username, string VehicleId, string fromdate, string todate)
        {
            string frdate = string.Empty;
            string tdate = string.Empty;
            if (!String.IsNullOrEmpty(fromdate))
            {
                try
                {
                    frdate = formatDBDate(DateTime.ParseExact(fromdate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    frdate = formatDBDate(Convert.ToDateTime(fromdate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    tdate = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    tdate = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            string query = "select t.TripId, t.VehicleId, DATE_FORMAT(t.fromdate, '%d-%m-%Y %h:%i:%s %p') as fromdate, DATE_FORMAT(t.todate, '%d-%m-%Y %h:%i:%s %p') as todate, DATE_FORMAT(t.Addedon, '%d-%m-%Y %h:%i:%s %p') as Addedon,a.Name AS 'Addedby' from titan_vehicle_tripdetails t inner join accountgroups a on t.AccountId=a.AccountID inner join usersgroupsmap u on a.groupid = u.groupid AND t.Addedby=u.Login where  t.AccountId=?  and t.Addedby=? and t.fromdate between ? and ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountid);
            lParameter.Add("Addedby", username);
            lParameter.Add("fromdate", frdate);
            lParameter.Add("todate", tdate);
            if (VehicleId != "--Select VehicleId--")
            {
                query += " and VehicleId=?";
                lParameter.Add("VehicleId", VehicleId);
            }
            query += " ORDER BY t.Addedon DESC";
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;

        }
        public string InsertJMPParkingLocationDetails(string tripid, string triptype, string tripstarttime, List<JMPParkingLocationDetails> addparkingspots)
        {
            //Convert DateTime Format
            string sTripStartTime = string.Empty;

            if (!String.IsNullOrEmpty(tripstarttime))
            {
                try
                {
                    sTripStartTime = formatDBDate(DateTime.ParseExact(tripstarttime, "dd-MM-yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));
                }
                catch (Exception e)
                {
                    sTripStartTime = formatDBDate(Convert.ToDateTime(tripstarttime));
                }
            }


            string query = "INSERT INTO `vehicledctrip_plan` (DCTripId,TripType,IsActive,TripStartTime) "
                         + "VALUES (?, ?, ?, ?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("DCTripId", tripid);
            lParameter.Add("TripType", triptype.ToUpper());
            lParameter.Add("IsActive", 1);
            lParameter.Add("TripStartTime", sTripStartTime);
            string res = dbx.executeNonQuery(query, lParameter).ToString();
            if (res == "1")
            {
                query = "select Max(PlanId) from vehicledctrip_plan v where v.DCTripId = ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("DCTripId", tripid);
                string planid = dbx.executeScalar(query, lParameter).ToString();
                lParameter = new Dictionary<string, object>();
                query = "INSERT INTO `vehicledctrip_plan_parking` (`PlanId`, `Location`, `Latitude`, `Longitude`, `EntryETA`, `ExitETA` , `EntryATA`, `ExitATA`, `EstRestDuration`, `ActRestDuration`, `IsCompleted`) VALUES ";
                for (int i = 0; i < addparkingspots.Count; i++)
                {

                    string sEntryETA = string.Empty;
                    string sEntryATA = string.Empty;
                    string sExitETA = string.Empty;
                    string sExitATA = string.Empty;
                    if (!String.IsNullOrEmpty(addparkingspots[i].EntryETA))
                    {
                        try
                        {
                            sEntryETA = formatDBDate(DateTime.ParseExact(addparkingspots[i].EntryETA, "dd-MM-yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));
                        }
                        catch (Exception e)
                        {
                            sEntryETA = formatDBDate(Convert.ToDateTime(addparkingspots[i].EntryETA));
                        }
                    }
                    if (!String.IsNullOrEmpty(addparkingspots[i].EntryATA))
                    {
                        try
                        {
                            sEntryATA = formatDBDate(DateTime.ParseExact(addparkingspots[i].EntryATA, "dd-MM-yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));
                        }
                        catch (Exception e)
                        {
                            sEntryATA = formatDBDate(Convert.ToDateTime(addparkingspots[i].EntryATA));
                        }
                    }
                    if (!String.IsNullOrEmpty(addparkingspots[i].ExitETA))
                    {
                        try
                        {
                            sExitETA = formatDBDate(DateTime.ParseExact(addparkingspots[i].ExitETA, "dd-MM-yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));
                        }
                        catch (Exception e)
                        {
                            sExitETA = formatDBDate(Convert.ToDateTime(addparkingspots[i].ExitETA));
                        }
                    }
                    if (!String.IsNullOrEmpty(addparkingspots[i].ExitATA))
                    {
                        try
                        {
                            sExitATA = formatDBDate(DateTime.ParseExact(addparkingspots[i].ExitATA, "dd-MM-yyyy hh:mm tt", System.Globalization.CultureInfo.InvariantCulture));
                        }
                        catch (Exception e)
                        {
                            sExitATA = formatDBDate(Convert.ToDateTime(addparkingspots[i].ExitATA));
                        }
                    }

                    query += "(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?),";
                    lParameter.Add("PlanId" + i, planid);
                    lParameter.Add("Location" + i, addparkingspots[i].Location);
                    lParameter.Add("Latitude" + i, addparkingspots[i].Latitude);
                    lParameter.Add("Longitude" + i, addparkingspots[i].Longitude);
                    lParameter.Add("EntryETA" + i, sEntryETA);
                    lParameter.Add("ExitETA" + i, sExitETA);
                    lParameter.Add("EntryATA" + i, sEntryATA);
                    lParameter.Add("ExitATA" + i, sExitATA);
                    lParameter.Add("EstRestDuration" + i, addparkingspots[i].EstRestDuration);
                    lParameter.Add("ActRestDuration" + i, addparkingspots[i].ActRestDuration);
                    lParameter.Add("IsCompleted" + i, addparkingspots[i].IsCompleted);
                }
                query = query.Substring(0, query.Length - 1);
                res = dbx.executeNonQuery(query, lParameter).ToString();

                res = planid;
            }
            return res;
        }

        public int CheckNoOfJMPPlansForTrip(string TripId, string TripType)
        {
            String query = "select count(*) from vehicledctrip_plan where DCTripId = ? and TripType = ?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("DCTripId", TripId);
            lParameter.Add("TripType", TripType);
            Object countObj = dbx.executeScalar(query, lParameter);
            int numEnt = Convert.ToInt32(countObj);
            if (numEnt != 0)
                return (numEnt);
            else
                return (0);
        }

