        public DataTable GetVehicleHaltDetailsFromStoreVehicleViolations(string Vehicle, string fromdate)
        {
            try
            {
                string query = "select vehicleid AS 'Vehicle',type,location AS 'Location',sum(duration) AS 'Duration',timestamp AS 'OutTimeStamp'" +
                    ",DATE_SUB(timestamp, Interval sum(duration) MINUTE) AS 'InTimeStamp' from storevehicleviolations where vehicleid = ? and timestamp BETWEEN ? AND ? " +
                    "and type in ('SCHEDULED STOP', 'UNSCHEDULED STOP') group by location";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", Vehicle);
                lParameter.Add("fromdate", fromdate);
                lParameter.Add("todate", formatDBDate(DateTime.Now));
                return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            catch (Exception ex) { return null; }
        }
        public DataTable GetVehicleHaltDetailsFromVehicleInPlant(string Vehicle, string fromdate)
        {
            try
            {
                string query = "SELECT v.vehicleid AS 'Vehicle',v.locationstr AS 'Location',min(v.intimestamp) AS 'InTimeStamp',max(v.outtimestamp) AS 'OutTimeStamp',TIMESTAMPDIFF(MINUTE, min(v.intimestamp),max(v.outtimestamp)) AS 'Duration'  " +
                    "FROM vehicleinplant v " +
                    "WHERE v.vehicleid = ? AND v.intimestamp BETWEEN ? AND ? and v.locationstr like '%ARH%' and v.locationstr not like '%JRM%' " +
                    "AND v.locationstr NOT IN (select location from storevehicleviolations where vehicleid = 'KA01 AL 6922' and timestamp BETWEEN ? AND ? and type in ('SCHEDULED STOP','UNSCHEDULED STOP') group by location)" +
                    " GROUP BY v.locationstr ORDER BY v.intimestamp";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("vehicleid", Vehicle);
                lParameter.Add("fromdate", fromdate);
                lParameter.Add("todate", formatDBDate(DateTime.Now));
                lParameter.Add("fromdate1", fromdate);
                lParameter.Add("todate1", formatDBDate(DateTime.Now));
                return dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            }
            catch (Exception ex) { return null; }
        }

