        public DataTable dbDriverPendingrequestsForNewEntry(string sessionId, string fromDate, string toDate)
        {
            int accountId = GetAccountId(sessionId);
            string query = "SELECT * FROM (SELECT CASE WHEN t.RequestType = 'New Entry' && t.KeyWord = 'TotaldriverInfo' THEN 'New Driver' " +
                            "ELSE '' END as 'RequestedType',  CONCAT_WS(' ', AF.Value) as 'RequestedValue', " +
                            "DATE_FORMAT(A.ActionTime, '%d-%m-%Y %H:%i:%s') as 'RequestGenerationDate',  " +
                            "CASE WHEN max(trr.MaxLevelReviewed) = t.ReviewLevel THEN 'Done' WHEN max(trr.MaxLevelReviewed) = -1 THEN 'Rejected' " +
                            "ELSE concat('Pending for Review Level ',  max(trr.MaxLevelReviewed) + 1) END as Status " +
                            "from tbl_trans_form_fields f inner join tbl_trans_form_action A on A.KeyWord = f.KeyWord inner join tbl_trans_form_action_info AF on AF.FieldId = f.Id and AF.EditId = A.EditId and AF.ActionId = A.Id " +
                            "left join tbl_trans_form_request_config t  on t.keyword = f.KeyWord " +
                            "left join tbl_trans_form_request tr on t.requesttype = tr.RequestType and t.keyword = tr.Requestfor  and tr.actionid = A.id " +
                            "and tr.actionid = AF.actionid left join  tbl_trans_form_max_level_review trr on tr.ActionId = trr.ActionId " +
                            "where f.keyword IN('TotalDriverInfo') and f.Id in (1) and A.AccountId = ? and t.Account = ? and A.Active = 1 and t.requesttype = 'New Entry' " +
                            "AND A.ActionTime > '2021-05-01 00:00:00' group by AF.value,A.ActionTime order by A.ActionTime desc) a " +
                            "WHERE a.Status NOT IN('Done', 'Rejected') GROUP BY a.RequestedValue,a.RequestGenerationDate ORDER BY a.RequestGenerationDate DESC ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountId);
            lParameter.Add("AccountId1", accountId);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable dbVehiclePendingrequestsForNewEntry(string sessionId, string fromDate, string toDate)
        {
            int accountId = GetAccountId(sessionId);
            string query = "SELECT * FROM (SELECT CASE WHEN t.RequestType = 'New Entry' && t.KeyWord = 'TotalVehicleInfo' THEN 'New Vehicle'  " +
                            "ELSE '' END as RequestedType,  CONCAT_WS(' ', AF.Value) as 'RequestedValue', " +
                            "DATE_FORMAT(A.ActionTime, '%d-%m-%Y %H:%i:%s') as 'RequestGenerationDate',  " +
                            "CASE WHEN max(trr.MaxLevelReviewed) = t.ReviewLevel THEN 'Done' WHEN max(trr.MaxLevelReviewed) = -1 THEN 'Rejected' " +
                            "ELSE concat('Pending for Review Level ',  max(trr.MaxLevelReviewed) + 1) END as Status " +
                            "from tbl_trans_form_fields f inner join tbl_trans_form_action A on A.KeyWord = f.KeyWord inner join tbl_trans_form_action_info AF on AF.FieldId = f.Id and AF.EditId = A.EditId and AF.ActionId = A.Id " +
                            "left join tbl_trans_form_request_config t  on t.keyword = f.KeyWord " +
                            "left join tbl_trans_form_request tr on t.requesttype = tr.RequestType and t.keyword = tr.Requestfor  and tr.actionid = A.id " +
                            "and tr.actionid = AF.actionid left join  tbl_trans_form_max_level_review trr on tr.ActionId = trr.ActionId " +
                            "where f.keyword IN('TotalVehicleInfo') and f.Id in (25) and A.AccountId = ? and t.Account = ? and A.Active = 1 and t.requesttype = 'New Entry' " +
                            "AND A.ActionTime > '2021-05-01 00:00:00' group by AF.value,A.ActionTime order by A.ActionTime desc) a  " +
                            "WHERE a.Status NOT IN('Done', 'Rejected') GROUP BY a.RequestedValue,a.RequestGenerationDate, a.status ORDER BY a.RequestGenerationDate desc ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountId);
            lParameter.Add("AccountId1", accountId);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
        public DataTable dbDriverPendingrequestsForEditEntry(string sessionId, string fromDate, string toDate)
        {
            int accountId = GetAccountId(sessionId);
            string query = "select distinct (select max(Value) from tbl_trans_form_action_info where ActionId=ta.ActionId  " +
                            "and FieldId= case when t.KeyWord='TotalDriverInfo' then 1 when t.KeyWord='TotalvehicleInfo' then 25 END) AS 'Driver Name' , " +
                            "t.FieldName AS 'Edited Field Name',tt.OldValue AS 'Existing Value',tt.NewValue AS 'New Value', " +
                            "DATE_FORMAT(ta.RequestedOn, '%d-%m-%Y %H:%i:%s') as 'Requested Date',   " +
                            "CASE WHEN (tt.`Level`) = ReviewLevel THEN 'Done'  " +
                            "ELSE concat('Pending for Review Level ', (tt.`Level`) + 1) END as STATUS ,ta.RequestedBy " +
                            "from tbl_trans_form_request ta inner join tbl_trans_form_fields t on t.KeyWord=ta.RequestFor  " +
                            "inner join tbl_trans_form_request_info tt on t.Id=tt.FieldId and tt.RequestId=ta.Id  " +
                            "left join tbl_trans_form_request_config ttr on ttr.KeyWord=t.KeyWord and ttr.RequestType=ta.RequestType " +
                            "INNER JOIN transporterinfo p ON p.login = ta.RequestedBy where ta.RequestType='Edit Entry' and tt.Status='Pending'  " +
                            "and t.KeyWord IN('TotalDriverInfo') and ta.AccountId = ? " +
                            "and ta.RequestedOn > '2021-05-01 00:00:00' group BY t.FieldName,tt.OldValue,tt.NewValue,ta.RequestedOn order by ta.RequestedOn DESC";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountId);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
