                            "DATE_FORMAT(t.RequestDate, '%d-%m-%Y %H:%i:%s') as 'Request Generation Date',t.`Status`,t.Remarks,t.RequestedBy " +
                            "from tbl_trans_form_driverchangelog t inner join tbl_trans_form_max_level_review m ON m.ActionId = t.Id AND m.TimeStamp = t.RequestDate  " +
                            "inner join transporterinfo h ON h.login = t.RequestedBy  " +
                            "left join transporterinfo ti on t.ExistingTransporterId=ti.TransporterId  " +
                             "left join transporterinfo ta on t.NewTransporterId = ta.TransporterId  " +
                            "where  t.RequestType='Vehicle Change' AND  t.ChangeType='Transporter Change' AND t.RequestDate >= '2021-05-01 00:00:00' and  t.AccountId = ? " +
                            "AND t.status NOT IN('Done','Rejected') order by t.RequestDate desc";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("AccountId", accountId);
            return dbx.executeQuery(query, lParameter).Tables[0];
        }
