        public Boolean AuthencateUID(string mobileno, string uid)
        {
            // verify that the device passed belongs to the BRANCH or not
            Boolean found = false;
            string query = "select uid from devicebranchallocation d where d.BranchID in " +
                " (select b.BranchID from branchdata b where b.BM_ContactNo = ?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Mobile", mobileno);
            DataSet ds = dbx.executeQuery(query, lParameter);
            foreach (DataTable table in ds.Tables)
            {
                foreach (DataRow row in table.Rows)
                {
                    foreach (DataColumn column in table.Columns)
                    {
                        if (uid == (string)row[column])
                        {
                            found = true;
                            break;
                        }
                    }
                }
            }
            return found;
        }

