        public int IsInHoliday(string vehicleid)
        {
            DateTime ts = DateTime.Now;
            string query = "select * from HolidayConfig where vehicleid = ? order by Hstarttime desc LIMIT 1;";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleid", vehicleid);
            DataTable tbl = dbx.executeQuery(query, lParameter).Tables[0];
            if (tbl.Rows.Count == 0) return 1;

            foreach (DataRow row in tbl.Rows)
            {
                if (tbl.Rows[0]["Hendtime"].Equals(System.DBNull.Value))
                {
                    if (tbl.Rows[0]["isHolidayOver"].ToString() == "1")
                    {
                        // Holiday Over Return 1
                        return (1);
                    }
                }
                else
                {
                    if (Convert.ToDateTime(tbl.Rows[0]["Hendtime"].ToString()) <= ts)
                        return (1);    // The Holiday is over
                }
            }
            return (0);
        }

