        //Muthoot Trip Details- API Insert
        //By Tusar on 06/06/2022
        public int Insert_MPG_TripDetails(MPG_TripDetails objMPGTrip, string groupid, string accountid)
        {
            int result = 0;
            string starttime = null, endtime = null, latstdist = "0";
            double distance = 0.0;

            //Close the previous active trip for the same device, if any.
            string query = "SELECT * FROM muthoot_trip_details m WHERE m.DeviceId = ? AND m.IsActive = 1 and m.StartLocationLatitude=? AND m.EndLocationLatitude=? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("DeviceId", objMPGTrip.deviceId);
            lParameter.Add("StartLocationLatitude", objMPGTrip.startLocationLatitude);
            lParameter.Add("EndLocationLatitude", objMPGTrip.endLocationLatitude);
            DataTable dtTrips = dbx.executeQuery(query, lParameter).Tables[0];
            if (dtTrips != null && dtTrips.Rows.Count > 0)
            {
                query = "UPDATE muthoot_trip_details m SET m.IsActive = 0, m.TripClosedOn = ?, m.TripClosedReason = ? WHERE m.DeviceId = ? AND m.IsActive = 1 and m.StartLocationLatitude=? AND m.EndLocationLatitude=?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("TripClosedOn", formatDBDate(DateTime.Now));
                lParameter.Add("TripClosedReason", "New Trip");
                lParameter.Add("DeviceId", objMPGTrip.deviceId);
                lParameter.Add("StartLocationLatitude", objMPGTrip.startLocationLatitude);
                lParameter.Add("EndLocationLatitude", objMPGTrip.endLocationLatitude);
                dbx.executeNonQuery(query, lParameter);

            }

            //Change the date and time format
            if (!String.IsNullOrEmpty(objMPGTrip.estTripStartDateTime) && objMPGTrip.estTripStartDateTime != "null")
            {
                starttime = formatDBDate(DateTime.ParseExact(objMPGTrip.estTripStartDateTime, "dd-MMM-yy HH:mm:ss", CultureInfo.InvariantCulture));
            }
            if (!String.IsNullOrEmpty(objMPGTrip.estTripEndDateTime) && objMPGTrip.estTripEndDateTime != "null")
            {
                endtime = formatDBDate(DateTime.ParseExact(objMPGTrip.estTripEndDateTime, "dd-MMM-yy HH:mm:ss", CultureInfo.InvariantCulture));
            }

            //Calculate Distance
            try
            {
                latstdist = getDistanceByMMIDistanceMatrix(objMPGTrip.startLocationLatitude, objMPGTrip.startLocationLongitude, objMPGTrip.endLocationLatitude, objMPGTrip.endLocationLongitude);

                if (latstdist != "NoData" || !string.IsNullOrEmpty(latstdist))
                {
                    distance = Convert.ToDouble((Convert.ToDecimal(latstdist) / 1000));
                }

            }
            catch (Exception ex)
            {
                distance = 0.0;
            }


            query = "INSERT IGNORE INTO `muthoot_trip_details` (`DeviceId`, `TripName`, `TripDate`, `TripStartDateTimeEstimated`, `TripEndDateTimeEstimated`, `StartLocationName`, `StartLocationLatitude`, `StartLocationLongitude`, `EndLocationName`, `EndLocationLatitude`, `EndLocationLongitude`, `TripDistance`,`IsActive`,`GroupId`,`AccountId`)";
            query += " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
            lParameter = new Dictionary<string, object>();
            lParameter = new Dictionary<string, object>();
            lParameter.Add("DeviceId", objMPGTrip.deviceId);
            lParameter.Add("TripName", objMPGTrip.tripName);
            lParameter.Add("TripDate", formatDBDate(DateTime.ParseExact(objMPGTrip.tripDate, "dd-MMM-yy HH:mm:ss", CultureInfo.InvariantCulture)));
            lParameter.Add("TripStartDateTimeEstimated", starttime);
            lParameter.Add("TripEndDateTimeEstimated", endtime);
            lParameter.Add("StartLocationName", objMPGTrip.startLocationName);
            lParameter.Add("StartLocationLatitude", objMPGTrip.startLocationLatitude);
            lParameter.Add("StartLocationLongitude", objMPGTrip.startLocationLongitude);
            lParameter.Add("EndLocationName", objMPGTrip.endLocationName);
            lParameter.Add("EndLocationLatitude", objMPGTrip.endLocationLatitude);
            lParameter.Add("EndLocationLongitude", objMPGTrip.endLocationLongitude);
            lParameter.Add("TripDistance", distance);
            lParameter.Add("IsActive", "1");
            lParameter.Add("GroupId", groupid);
            lParameter.Add("AccountId", accountid);
            result = dbx.executeNonQuery(query, lParameter);
            return result;
        }
