        public DataSet GetAssetTripReport(int accountid, string username, string VehicleId, string fromdate, string todate)
        {
            string frdate = string.Empty;
            string tdate = string.Empty;
            if (!String.IsNullOrEmpty(fromdate))
            {
                try
                {
                    frdate = formatDBDate(DateTime.ParseExact(fromdate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    frdate = formatDBDate(Convert.ToDateTime(fromdate));
                }
            }
            if (!String.IsNullOrEmpty(todate))
            {
                try
                {
                    tdate = formatDBDate(DateTime.ParseExact(todate, "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

                }
                catch (Exception e)
                {
                    tdate = formatDBDate(Convert.ToDateTime(todate));
                }
            }
            string GroupId = getGroupIdByLogin(username).ToString();
            string query = "select t.Id, t.DeviceId,t.TripId,t.TripType, DATE_FORMAT(t.TripStartDateTimeEstimated, '%d/%m/%Y %H:%i:%s') as TripStartDateTimeEstimated, DATE_FORMAT(t.TripEndDateTimeEstimated, '%d/%m/%Y %H:%i:%s') as TripEndDateTimeEstimated,t.TripStatus,t.EmployeeId,t.TripDistance,t.ShowPositionURL,t.ShowRouteURL from asset_trip_details t where t.IsActive=1 AND  t.ServerTS between ? and ? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromdate", frdate);
            lParameter.Add("todate", tdate);
            if (VehicleId != "--Select Device--")
            {
                query += " and DeviceId=? ";
                lParameter.Add("DeviceId", VehicleId);
            }
            else
            {
                query += " and DeviceId IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?)";
                lParameter.Add("GroupId", GroupId);
            }
            query += " ORDER BY t.ServerTS DESC";
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;

        }
        public DataTable GetAssetTripData(string fromDate, string toDate, string groupid, string accountid, string DeviceId)
        {
            try
            {
                string query;

                if (DeviceId != null)
                {
                    query = "SELECT * FROM asset_trip_details m WHERE m.ServerTS > ? " +
                            "AND m.ServerTS < ? AND m.DeviceId = ? AND m.GroupId=? AND m.AccountId=? ";

                    var lParameter = new Dictionary<string, object>();
                    lParameter.Add("FromDate", fromDate);
                    lParameter.Add("ToDate", toDate);
                    lParameter.Add("DeviceId", DeviceId);
                    lParameter.Add("GroupId", groupid);
                    lParameter.Add("AccountId", accountid);

                    DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                    return dt;
                }
                else
                {
                    query = "SELECT DISTINCT v.VehicleId from vehiclesgroupsmap v left JOIN asset_trip_details m ON m.DeviceId=v.VehicleId " +
                            "WHERE v.GroupId = ? ";

                    var deviceIdParameter = new Dictionary<string, object>();
                    deviceIdParameter.Add("GroupId", groupid);
                    DataTable deviceIdTable = dbx.executeQuery(query, deviceIdParameter).Tables[0];

                    var deviceIds = string.Join(",", deviceIdTable.AsEnumerable().Select(r => $"'{r.Field<string>("VehicleId")}'"));
                    deviceIds = string.IsNullOrEmpty(deviceIds) ? "''" : deviceIds;

                    query = "SELECT * FROM asset_trip_details m WHERE m.ServerTS > '" + fromDate + "' " +
                            "AND m.ServerTS < '" + toDate + "' AND m.DeviceId IN (" + deviceIds + ") " +
                            "AND m.GroupId='" + groupid + "' AND m.AccountId='" + accountid + "' ";

                    var lParameter1 = new Dictionary<string, object>();
                    lParameter1.Add("FromDate", fromDate);
                    lParameter1.Add("ToDate", toDate);
                    lParameter1.Add("DeviceId", deviceIds);
                    lParameter1.Add("GroupId", groupid);
                    lParameter1.Add("AccountId", accountid);

                    DataTable dt1 = dbx.executeQuery(query, lParameter1).Tables[0];
                    return dt1;
                }
            }
            catch (Exception ex)
            {
                return null;
            }
        }
