        public DataSet GetPositionsbytimestamp(string vehicleid, string fromdate, string todate)
        {
            string part = GetDateTablePartitions(Convert.ToDateTime(fromdate), Convert.ToDateTime(todate), partions);
            string query = "select id,TruckID,TimeStamp,Start,Stop,Latitude,Longitude,Speed from positiondata PARTITION(" +
                            part + ") where truckid = '" + vehicleid + "' and timestamp between '" + fromdate + "' and '" + todate + "'" +
                            " order by timestamp desc limit 1" + "; ";
            DataSet data = dbx.executeQuery(query);
            return data;
