        public string getencryptedPasswordStr(string newpassword)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query = new StringBuilder();
            query.Append("select SHA1(?)");
            lParameter = new Dictionary<string, object>();
            lParameter.Add("password", newpassword);
            Object encryptedPassword = dbx.executeScalar(query.ToString(), lParameter);
            String encryptedPasswordStr;
            if (encryptedPassword.GetType().ToString() == "System.Byte[]")
            {
                encryptedPasswordStr = System.Text.Encoding.ASCII.GetString((System.Byte[])encryptedPassword);
            }
            else
            {
                encryptedPasswordStr = encryptedPassword.ToString();
            }
            return encryptedPasswordStr;
        }
