        public DataSet GetOBCUptimeDetailsDefault(int accountid, string username, DateTime fromdate)
        {
            string GroupId = getGroupIdByLogin(username).ToString();
            var lParameter = new Dictionary<string, object>();

            string query = "SELECT d.vehicleId as 'VehicleNo',t.Name as 'Transporter',c.uid as 'UnitNo',CAST((SUM(CASE WHEN d.runTime > 300 THEN 1 ELSE 0 END) * 100.0) / 30 AS DECIMAL(5, 2)) AS 'PercentageUpTime' FROM dailydistance d JOIN vehicleinfo v ON d.vehicleId = v.VehicleId JOIN configdata c ON c.TruckID = v.VehicleId AND c.TruckID = d.vehicleId LEFT JOIN transporterinfo t ON v.Transporter = t.TransporterId WHERE d.Date > ? AND d.vehicleId IN (SELECT VehicleId FROM vehiclesgroupsmap  ";
            query += " WHERE GroupId = ? ) GROUP BY d.vehicleId, t.Name, c.uid ";
            lParameter.Add("fromdate", fromdate.ToString("yyyy-MM-dd"));
            lParameter.Add("GroupId", GroupId);
            DataSet OBCUptimeDetails = dbx.executeQuery(query, lParameter);
            return OBCUptimeDetails;
        }
