        public string updateBranchdetails(string BanchName, string BranchManagerName, string BranchEMailId, string BranchMobileNo, string BanchId, int accountid, string username, string EmailsForNr, string EmailsForBatery, string SmsForTheft, string PhoneCallsForTheft)
        {
            int result = 0;
            string Addedon = string.Empty;
            try
            {
                Addedon = formatDBDate(DateTime.ParseExact(DateTime.Now.ToString(), "dd/MM/yyyy hh:mm:ss tt", System.Globalization.CultureInfo.InvariantCulture));

            }
            catch (Exception e)
            {
                Addedon = formatDBDate(Convert.ToDateTime(DateTime.Now.ToString()));
            }

            string query = string.Empty;
            query = "SELECT b.BranchName,b.BM_Name,b.BM_ContactNo,b.BM_Email,b.AccountID,e.EmpName,b.emailsForNR,b.SMSForTheft,emailsForNR,SMSForTheft,PhoneCallsForTheft,emailsForCharging FROM branchdata b JOIN empl_info e ON b.BranchID=e.BranchID WHERE b.BranchID=? AND  b.AccountID=?;";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("BranchID", BanchId);
            lParameter.Add("AccountID", accountid);
            DataTable ExistingBranchDetails = dbx.executeQuery(query, lParameter).Tables[0];

            if (ExistingBranchDetails.Rows.Count > 0)
            {

                string query1 = "update branchdata set BM_ContactNo=?,BM_Email=?,BM_Name=?,emailsForNR=?,SMSForTheft=?,PhoneCallsForTheft=?,emailsForCharging=? where BranchID=? ";
                var lParameter1 = new Dictionary<string, object>();
                lParameter1.Add("BM_ContactNo", BranchMobileNo);
                lParameter1.Add("BM_Email", BranchEMailId);
                lParameter1.Add("BM_Name", BranchManagerName);
                lParameter1.Add("emailsForNR", EmailsForNr);
                lParameter1.Add("SMSForTheft", SmsForTheft);
                lParameter1.Add("PhoneCallsForTheft", PhoneCallsForTheft);
                lParameter1.Add("emailsForCharging", EmailsForBatery);
                lParameter1.Add("BranchID", BanchId);
                result = dbx.executeNonQuery(query1.ToString(), lParameter1);

                if (result > 0)
                {
                    string query2 = "update empl_info set MobileNo=? where BranchID=? ";
                    var lParameter2 = new Dictionary<string, object>();
                    lParameter2.Add("BM_ContactNo", BranchMobileNo);
                    lParameter2.Add("BranchID", BanchId);
                    result = dbx.executeNonQuery(query2.ToString(), lParameter2);


                    string query3 = "INSERT IGNORE INTO `branchEmployeeMobileNoHistory` (`BranchId`, `BranchName`, `NewBranchManagerName`, `ExistingEmailId`, `NewEmailId`, `ExistingMobileNo`, `NewMobileNo`, `UpdatedOn`, `UpdatedBy`,`AccountId`,ExistingBranchManagerName,ExistingemailsForNR,NewemailsForNR,ExistingSMSForTheft,NewSMSForTheft,ExistingPhoneCallsForTheft,NewPhoneCallsForTheft,ExistingemailsForCharging,NewemailsForCharging)";
                    query3 += " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
                    var lParameter3 = new Dictionary<string, object>();
                    lParameter3.Add("BranchId", BanchId);
                    lParameter3.Add("BranchName", BanchName);
                    lParameter3.Add("NewBranchManagerName", BranchManagerName);
                    lParameter3.Add("ExistingEmailId", ExistingBranchDetails.Rows[0]["BM_Email"].ToString());
                    lParameter3.Add("NewEmailId", BranchEMailId);
                    lParameter3.Add("ExistingMobileNo", ExistingBranchDetails.Rows[0]["BM_ContactNo"].ToString());
                    lParameter3.Add("NewMobileNo", BranchMobileNo);
                    lParameter3.Add("UpdatedOn", Addedon);
                    lParameter3.Add("UpdatedBy", username);
                    lParameter3.Add("AccountId", accountid);
                    lParameter3.Add("ExistingBranchManagerName", ExistingBranchDetails.Rows[0]["BM_Name"].ToString());
                    lParameter3.Add("ExistingemailsForNR", ExistingBranchDetails.Rows[0]["emailsForNR"].ToString());
                    lParameter3.Add("NewemailsForNR", EmailsForNr);
                    lParameter3.Add("ExistingSMSForTheft", ExistingBranchDetails.Rows[0]["SMSForTheft"].ToString());
                    lParameter3.Add("NewSMSForTheft", SmsForTheft);
                    lParameter3.Add("ExistingPhoneCallsForTheft", ExistingBranchDetails.Rows[0]["PhoneCallsForTheft"].ToString());
                    lParameter3.Add("NewPhoneCallsForTheft", PhoneCallsForTheft);
                    lParameter3.Add("ExistingemailsForCharging", ExistingBranchDetails.Rows[0]["emailsForCharging"].ToString());
                    lParameter3.Add("NewemailsForCharging", EmailsForBatery);
                    result = dbx.executeNonQuery(query3, lParameter3);
                    return result.ToString();

                }
            }
            return result.ToString();

        }
