        public string GetWorkStartTime(string IMEI)
        {
            DateTime now = DateTime.Now;
            string DriverId = GetDriverIdByIMEI(IMEI);
            String Date = DateTime.Now.ToString("yyyy-MM-dd");
            string query = "SELECT w.startTime FROM workdonedata w" +
              " where w.driverId=? and w.startTime >= '" + now.AddHours(-12).ToString("yyyy-MM-dd HH:mm:ss") + "' ";
            var lParameter = new Dictionary<string, Object>();
            lParameter.Add("DriverId", DriverId);
            //lParameter.Add("startTime", Date);
            DataTable table = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            if (table.Rows.Count > 0)
            {
                if (table.Rows[0][0].ToString() == string.Empty)
                {
                    return "Work Not started";
                }
                return "Work Started";
            }
            else
                return "Work Not started";
        }
        public DataTable Getworknotendeddata(string login)
        {
            DateTime now = DateTime.Now;
            string Transpoterid = getTransporterIdByLogin(login);
            string query = "SELECT w.driverName,d.LicenceNo,w.vehicleId,timediff('" + now.ToString("yyyy-MM-dd HH:mm:ss") + "', w.startTime) AS dif, w.startTime,w.endTime,d.Transporter,d.AccountId FROM workdonedata w JOIN driverinfo d ON w.driverId = d.DriverId" +
                            " WHERE timediff('" + now.ToString("yyyy-MM-dd HH:mm:ss") + "', w.startTime) > '12:00:00' AND w.startTime > '" + now.AddHours(-48).ToString("yyyy-MM-dd HH:mm:ss") + "' " +
                            " AND  d.Transporter = '" + Transpoterid + "'  AND w.endTime IS NULL ";
            DataTable dtworkdonedata = dbx.executeQuery(query).Tables[0];
