        public string getdaypartition(string actiontime) //partitions p001 to p031
        {
            try
            {
                int day_of_the_month = 0;
                string current_partition = string.Empty;
                day_of_the_month = Convert.ToDateTime(actiontime).Day;
                if (day_of_the_month < 10)
                    current_partition = string.Concat("P00", day_of_the_month);
                else
                    current_partition = string.Concat("P0", day_of_the_month);
                return current_partition;
            }
            catch
            {
                return string.Empty;
            }
        }

        // This method is specific for checking when ALERTs were sent in the case of ASG devices specifically for GEOFENCE based customers i.e customers who want aLERTs to be 
        // sent when there is a breach of geofence
        public Boolean checkLastTheftAlertNotification(string asset, int threshold, int breached, int custType = 0) //, DateTime alertTime, string alertType)
        {
            string current_partition = string.Empty;
            string lastAlertThreshold = formatDBDate(DateTime.Now.AddMinutes(-threshold));  // check to see if there are any alerts within the threshold time (in secs)
            current_partition = getdaypartition(lastAlertThreshold.ToString());
            string query = "SELECT info FROM transporternotification t WHERE t.Subject LIKE '%" + asset + "%'  ORDER BY DATETIME DESC LIMIT 1;";
            Object infoObj = dbx.executeScalar(query);
            if (infoObj == null || infoObj.Equals(System.DBNull.Value))  // no entry so 
                return true;
            else if (infoObj.ToString().Contains("dummy"))
            {
                // if the customer is a geofence enabled customer then it is breached then send true. i.e When initially the device entered THEFT state it
                // was inside the geofence but then the geofence was breached hence alert has to be sent immediately and not wait for threshold time
                if ((custType == 1 || custType == 2) && breached == 1)
                    return true;
                else
                { // most likely it is inside the geofence so wait for the first alert interval for sending the alert
                    query = "SELECT datetime FROM transporternotification t WHERE t.Subject LIKE '%" + asset + "%'  ORDER BY DATETIME DESC LIMIT 1;";
                    infoObj = dbx.executeScalar(query);
                    if (infoObj == null || infoObj.Equals(System.DBNull.Value))  // no entry so true means send alert
                        return false;
                    else if (DateTime.Now >= DateTime.Parse(infoObj.ToString()).AddMinutes(threshold))
                        return true;
                    else return false;
                }
            }
            else // in this case alert was sent b4 so see if it was sent b4 alerttime if yes then true else false
            {
                query = "SELECT datetime FROM transporternotification t WHERE t.Subject LIKE '%" + asset + "%' and datetime > '" + lastAlertThreshold + "' order by DATETIME desc" +
                    " limit 1";
                infoObj = dbx.executeScalar(query);
                if (infoObj == null || infoObj.Equals(System.DBNull.Value))  // no entry so true means send alert
                    return true;
                else
                    return false;
            }

        }
        // This method checks to see if the last entry in the notification is a DUMMY entry specifically when the customer is a geofence customer 
        public Boolean checkIfLatestNOtificationIsDummy(string asset)
        {
            string current_partition = string.Empty;
            DateTime lastAlertThreshold = DateTime.Now;  // check to see if there are any alerts within the threshold time (in secs)
            current_partition = getdaypartition(lastAlertThreshold.ToString());
            string query = "SELECT info FROM transporternotification t WHERE t.Subject LIKE '%" + asset + "%'  ORDER BY DATETIME DESC LIMIT 1;";
            Object infoObj = dbx.executeScalar(query);
            if (infoObj == null || infoObj.Equals(System.DBNull.Value))  // no entry so 
                return false;
            else if (infoObj.ToString().Contains("dummy"))
            {
                return true;
            }
            else
                return false;
        }

