            {
                objVehicleTrip.VEHICLENUMBER = dtVehicleDetails.Rows[0]["VehicleId"].ToString();
            }

            //Close the previous active trip for the same FO_ID, if any.
            string query = "SELECT * FROM shv_trip_details m WHERE m.FO_ID = ? AND m.IsActive = 1";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("FO_ID", objVehicleTrip.FO_ID);
            DataTable dtTrips = dbx.executeQuery(query, lParameter).Tables[0];
            if (dtTrips != null && dtTrips.Rows.Count > 0)
            {
                query = "UPDATE shv_trip_details m SET m.IsActive = 0, m.TripClosedOn = ?, m.TripClosedReason = ? WHERE m.FO_ID = ? AND m.IsActive = 1";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("TripClosedOn", formatDBDate(DateTime.Now));
                lParameter.Add("TripClosedReason", "New Trip");
                lParameter.Add("FO_ID", objVehicleTrip.FO_ID);
