        public string AddDCAssignDataForSHV(VehicleTripDetailsForAPI objVehicleTrip, string sessionId)
        {
            try
            {
                string createdDate;
                string AccountId = GetAccountId(sessionId).ToString();
                string userId = getUserId(sessionId).ToString();
                int timeZone = GetTimeZoneDiff(sessionId);
                DateTime now = DateTime.UtcNow.AddSeconds(timeZone);

                string query = "select * from vehicledctrip v where v.VehicleID=? and v.IsTripEnds=0";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", objVehicleTrip.VEHICLENUMBER);
                DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
                if (dt != null && dt.Rows.Count > 0)
                {
                    query = "Update vehicledctrip set IsTripEnds=b'1',TripEndsOn=? where `VehicleID`=? and IsTripEnds=0 ";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("TripEndsOn", formatDBDate(now));
                    lParameter.Add("VehicleId", objVehicleTrip.VEHICLENUMBER);
                    dbx.executeNonQuery(query, lParameter);
                }

                string ld_place = "";
                string ld_code = "";

                List<STAGE> stages = objVehicleTrip.STAGES;
                ld_code = stages[0].SRCLOC.LOCID;
                DataTable dtCustomerDetails = GetCheckCustomerDetailsByCustomerCode(ld_code, AccountId);

                if (dtCustomerDetails != null && dtCustomerDetails.Rows.Count > 0)
                    ld_place = dtCustomerDetails.Rows[0]["Name"].ToString();
                try
                {
                    //Added by zoya to insert created date on 20/02/2025
                    if (!string.IsNullOrWhiteSpace(objVehicleTrip.CREATED_ON_DATE) && !string.IsNullOrWhiteSpace(objVehicleTrip.CREATED_AT_TIME))
                    {
                        string combinedDateTime = $"{objVehicleTrip.CREATED_ON_DATE} {objVehicleTrip.CREATED_AT_TIME}";

                        //parsing the combined date and time
                        if (DateTime.TryParseExact(combinedDateTime, "dd-MM-yyyy HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out DateTime parsedDateTime))
                        {
                            createdDate = parsedDateTime.ToString("yyyy-MM-dd HH:mm:ss");
                        }
                        else
                        {
                            createdDate = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                        }
                    }
                    else
                    {
                        createdDate = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                    }
                }
                catch (Exception)
                {
                    createdDate = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                }


                query = "Insert Into vehicledctrip(`VehicleID`,`DateTime`,`NoofDcs`,`AddedBy`,`AccountID`,DriverMobileNo,LoadingPlaceName,LoadingCustomerCode)" +
                " values(?,?,?,?,?,?,?,?)";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", objVehicleTrip.VEHICLENUMBER);
                lParameter.Add("Created_Date", createdDate);
