        public void PushSHVTripDetailsToZoho(string dcTripId, string type)
        {
            DataTable dtSHVTripDetails = GetSHVTripDetails(dcTripId);

            List<SHVSTAGE> stages = new List<SHVSTAGE>();
            SHVTrip SHVTrip = new SHVTrip();
            foreach (DataRow row in dtSHVTripDetails.Rows)
            {
                SHVSTAGE stage = new SHVSTAGE();
                stage.FO_ID = row["FO_ID"].ToString();
                stage.VEHICLE_NUMBER = row["VehicleNo"].ToString().Replace(" ", ""); ;
                stage.SRC_LOC_ID = row["SrcLocID"].ToString();
                stage.DEST_LOC_ID = row["DestLocId"].ToString();
                stage.MESSAGE1 = row["MESSAGE1"].ToString().Replace("\\n", "");
                stage.MESSAGE2 = row["MESSAGE2"].ToString().Replace("\\n", "");
                stage.STATUS = row["DeliveryStatus"].ToString();
                stage.DATE_TIME = row["DeliveryDateTime"].ToString().Replace("-", "").Replace(":", "").Replace(" ", "");
                stages.Add(stage);
            }
            SHVTrip.IM_ZOHO_VTS_DETAILS = stages;

            //Call API to Push the Data
            string endPoint = "";
            string header = "";
            if (type == "QTM")
            {
                endPoint = "https://zoho-q.supergas.com/HttpAdapter/HttpMessageServlet?qos=BE&interfaceNamespace=http%3A%2F%2Fsupergas.com%2Fvts_details&senderService=YVM_BS_ZOHO&interface=SI_YVM_DUM_VTS_OUT&senderParty";
                header = "Authorization, Basic  dGl0b2ludGVncmF0aW9uOldlbGNvbWVAMzIx";
            }
            else if (type == "DTM")
            {
                endPoint = "https://zoho-d.supergas.com/HttpAdapter/HttpMessageServlet?qos=BE&interfaceNamespace=http%3A%2F%2Fsupergas.com%2Fvts_details&senderService=YVM_BS_ZOHO&interface=SI_YVM_DUM_VTS_OUT&senderParty";
                header = "Authorization, Basic  dGl0b2ludGVncmF0aW9uOnNodiMxMjM0";
            }
            else if (type == "PTM")
            {
                endPoint = "https://zoho-p.supergas.com/HttpAdapter/HttpMessageServlet?qos=BE&interfaceNamespace=http%3A%2F%2Fsupergas.com%2Fvts_details&senderService=YVM_BS_ZOHO&interface=SI_YVM_DUM_VTS_OUT&senderParty";
                header = "Authorization, Basic  dGl0b2ludGVncmF0aW9uOldlbGNvbWVAMTIz";
            }

            var postData = JsonConvert.SerializeObject(SHVTrip);
            string cleaned = postData.Replace("\n", "").Replace("\r", " ");
            String unescapedString = Regex.Unescape(cleaned);

            string result = MakeHttpRequest(endPoint, "POST", "application/json", unescapedString, header);

        }
        public bool SendWhatsAppMessageForSHV(string message, string mobilenumbers)
        {
            string token = string.Empty;

            string tokenmessage = getcurrenttoken("shv_whastapp_access_token", ref token);
            if (tokenmessage == "token expired" | tokenmessage == "insert new token")
                token = getValueFirstWhatsAppAccessToken();

            if (token != "error" && !String.IsNullOrEmpty(token))
            {
                //Call WhatsApp API to Send Message
                string header = "Authorization, Bearer " + token;
                //var postdata = new StringContent("{\r\n    \"@VER\": \"1.2\",\r\n    \"USER\": {\r\n        \"@CH_TYPE\": \"4\",\r\n        \"@UNIXTIMESTAMP\": \"\"\r\n    },\r\n    \"SMS\": [\r\n        {\r\n            \"@UDH\": \"0\",\r\n            \"@CODING\": \"1\",\r\n            \"@TEXT\": \"Dear Customer, There is a slight change in the Estimated Time of Arrival (ETA) for Truck no. 1234. To know the updated status, please click on dklr.pw/5MxDh Regards, SUPERGAS.\",\r\n            \"@PROPERTY\": \"0\",\r\n            \"@MSGTYPE\": \"1\",\r\n            \"@ID\": \"1\",\r\n            \"ADDRESS\": [\r\n                {\r\n                    \"@FROM\": \"917386661334\",\r\n                    \"@TO\": \"918431495923\",\r\n                    \"@SEQ\": \"1\",\r\n                    \"@TAG\": \"some client side random data\"\r\n                }\r\n            ]\r\n        }\r\n    ]\r\n}", null, "application/json");
                //string postdata = "{\"@VER\":\"1.2\",\"USER\":{\"@CH_TYPE\":\"4\",\"@UNIXTIMESTAMP\":\"\"},\"SMS\":[{\"@UDH\":\"0\",\"@CODING\":\"1\",\"@TEXT\":\"Dear Customer, There is a slight change in the Estimated Time of Arrival (ETA) for Truck no. 1234. To know the updated status, please click on dklr.pw/5MxDh Regards, SUPERGAS.\",\"@PROPERTY\":\"0\",\"@MSGTYPE\":\"1\",\"@ID\":\"1\",\"ADDRESS\":[{\"@FROM\":\"917386661334\",\"@TO\":\"" + mobilenumbers + "\",\"@SEQ\":\"1\",\"@TAG\":\"some client side random data\"}]}]}";
                string postdata = "{\"@VER\":\"1.2\",\"USER\":{\"@CH_TYPE\":\"4\",\"@UNIXTIMESTAMP\":\"\"},\"SMS\":[{\"@UDH\":\"0\",\"@CODING\":\"1\",\"@TEXT\":\"" + message + "\",\"@PROPERTY\":\"0\",\"@MSGTYPE\":\"1\",\"@ID\":\"1\",\"ADDRESS\":[{\"@FROM\":\"917386661334\",\"@TO\":\"" + mobilenumbers + "\",\"@SEQ\":\"1\",\"@TAG\":\"some client side random data\"}]}]}";
                //var postdata = @"{""@VER"":""1.2"",""USER"":{""@CH_TYPE"":""4"",""@UNIXTIMESTAMP"":""""},""SMS"":[{""@UDH"":""0"",""@CODING"":""1"",""@TEXT"":""Dear Customer, There is a slight change in the Estimated Time of Arrival (ETA) for Truck no. 1234. To know the updated status, please click on dklr.pw/5MxDh Regards, SUPERGAS."",""@PROPERTY"":""0"",""@MSGTYPE"":""1"",""@ID"":""1"",""ADDRESS"":[{""@FROM"":""917386661334"",""@TO"":""+mobilenumbers+"",""@SEQ"":""1"",""@TAG"":""some client side random data""}]}]}";

                string result = MakeHttpRequest("https://api.myvfirst.com/psms/servlet/psms.JsonEservice", "POST", "application/json", postdata.ToString(), header);
                //Insert Into SHV API Log 
                try
                {
                    InsertShvAPILog("WhatsApp", "PrimaryETA", mobilenumbers, postdata, result);
                }
                catch (Exception ex)
                {
                }

                if (result.ToString().Contains("ERROR") || result.ToString().Contains("error"))
                {
                    return false;
                }
            }
            return true;
        }
        public void InsertShvAPILog(string purpose, string type, string mobile, string request, string response)
        {
            string query = "INSERT INTO shv_api_log(`Purpose`, `Type`, `MobileNo`, `Request`, `Response`) VALUES (?,?,?,?,?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Purpose", purpose);
            lParameter.Add("Type", type);
            lParameter.Add("MobileNo", mobile);
            lParameter.Add("Request", request);
            lParameter.Add("Response", response);
            dbx.executeNonQuery(query, lParameter);
        }
        public string getValueFirstWhatsAppAccessToken()
        {
            string endpoint = "https://api.myvfirst.com/psms/api/messages/token?action=generate";

            string repStr = MakeHttpRequest(endpoint, "POST", "application/x-www-form-urlencoded ", "", "Authorization, Basic c2h2ZW5lcmd5d2E6MTEtRXMzUXFbVFlj");
            var data = JsonConvert.DeserializeObject<dynamic>(repStr);
            string access_token = data["token"];
            string expiryDate = data["expiryDate"];
            string tokenname = "shv_whastapp_access_token";
            //string timestamp = dbx.formatDBDate(expiryDate);
            try
            {
                updatesimtoken(tokenname, access_token, expiryDate);
            }
            catch (Exception ex)
            {
                return "error";
            }
            return access_token;
        }

