        public DataTable GetShvNonETAOnTripsinCustomerDC(string AccountIds)
        {
            string query = "select cd.id,v.VehicleID,v.AddedBy,v.LoadingOutTime,cd.DCTripId,v.LoadingCustomerCode,v.LoadingPlaceName from customerdcassign cd " +
                           " join vehicledctrip v on v.id=cd.DCTripId " +
                           " where v.AccountID in (" + AccountIds + ") and v.IsTripEnds=0 and cd.IsCancel=0 and cd.IsDelivered=0 and cd.ReportedTime IS NULL" +
                           " and v.DateTime>'" + formatDBDate(DateTime.Now.AddDays(-2)) + "' and v.DateTime<'" + formatDBDate(DateTime.Now.AddMinutes(-30)) + "'";
