        public int UpdateSHVTripStages(string Message1, string Message2, string DeliveryStatus, string DeliveryDateTime, string FO_ID, string DescLocID)
        {
            int res = 0;
            try
            {
                string query = "";
                var lParameter = new Dictionary<string, object>();

                if (!String.IsNullOrEmpty(Message1)) //If message1 is notempty or not null
                {
                    query = "UPDATE shv_trip_stages SET Message1 = ? WHERE FO_ID=? AND DestLocId=?";
                    lParameter.Add("Message1", Message1);
                }
                else if (!String.IsNullOrEmpty(Message2)) //If message2 is notempty or not null
                {
                    query = "UPDATE shv_trip_stages SET Message2 = ? WHERE FO_ID=? AND DestLocId=?";
                    lParameter.Add("Message2", Message2);
                }
                else if (!String.IsNullOrEmpty(DeliveryStatus)) //If DeliveryStatus is notempty or not null
                {
                    query = "UPDATE shv_trip_stages SET DeliveryStatus = ?, DeliveryDateTime = ? WHERE FO_ID= ? AND DestLocId= ?";
                    lParameter.Add("DeliveryStatus", DeliveryStatus);
                    lParameter.Add("DeliveryDateTime", DeliveryDateTime);//.ToString("yyyy-MM-dd HH:mm:ss")););
                }

                lParameter.Add("FO_ID", FO_ID);
                lParameter.Add("DescLocID", DescLocID);
                res = dbx.executeNonQuery(query, lParameter);
                return res;
            }
            catch (Exception ex)
            {
                return res;
            }
        }
        public DataTable GetSHVTripDetails(string DCTripId)
        {
            try
            {
                string query = " SELECT s.FO_ID, t.StageId, s.VehicleNo, t.SrcLocID, t.DestLocId, t.DestEmail, t.DestMobileNo1, t.DestMobileNo2, DATE_FORMAT(t.DestPlannedArrival, '%Y-%m-%d') AS DestPlannedArrival, t.Message1, t.Message2, DATE_FORMAT(t.DeliveryDateTime, '%Y-%m-%d %H:%i:%s') AS DeliveryDateTime, t.DeliveryStatus FROM shv_trip_details s" +
                                " JOIN shv_trip_stages t ON t.FO_ID = s.FO_ID WHERE s.DCTripId = ? AND t.StageId NOT LIKE '%RTN%' ";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("DCTripId", DCTripId);
                DataTable dt = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
                return dt;
            }
            catch (Exception ex)
            {
                return null;
            }
        }
