        protected string GenerateShortenURL(string sessionId, string tripId, string customerId)
        {
            String strPathAndQuery = HttpContext.Current.Request.Url.PathAndQuery;
            String sHost = HttpContext.Current.Request.Url.AbsoluteUri.Replace(strPathAndQuery, "/");
            sHost = sHost.Replace(":334", "");
            sHost = sHost.Replace("http://", "https://");
            string link = sHost + "TrackETA.aspx?sessionId=" + sessionId + "&tripid=" + tripId + "&customerid=" + customerId;
            DataTable table = GetCallActivationDetails("shvepl", "txtly");
            string url = "";
            if (table.Rows.Count > 0)
            {
                url = table.Rows[0]["CallUrl"].ToString();
                string result = MakeHttpRequest(url + System.Web.HttpUtility.UrlEncode(link), "POST", "application/json");
                if (result != null)
                {
                    var response = JsonConvert.DeserializeObject<dynamic>(result);// Converting JSON response
                    link = response["txtly"].ToString();//Read JSON value of txtly key
                                                        //btnurl.Text = "http://" + link.Replace("/{advc}", "");
                    return link;
                }
            }
            return "";
        }

