        public Object[] GetFilteredViolationsBasedOntheWorkDone(string fromDateStr, string toDateStr, string sessionId)
        {
            string username = getUserId(sessionId);
            int groupid = getGroupIdByLogin(username);
            string query = "SELECT distinct b.vehicleId,b.`type`,b.remarks,b.duration,b.timestamp,b.Location,b.latitude,b.longitude,b.maxsamplesval,b.samples ";
            query += " FROM  workdonedata a,storevehicleviolations b WHERE a.vehicleid IN(SELECT vehicleid FROM vehiclesgroupsmap WHERE groupid=?)";
            query += " AND (a.endTime between ? AND ? OR a.endTime IS NULL) and a.vehicleid=b.vehicleid AND";
            query += " b.timestamp BETWEEN a.startTime AND a.endTime AND b.type in('OVERSPEEDING','HARSH BRAKING','HIGH ACCELERATION') and";
            query += " b.type != 'Normal' ORDER BY a.vehicleid,b.timestamp;";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("groupid", groupid);
            lParameter.Add("fromDateStr", fromDateStr);
            lParameter.Add("toDateStr", toDateStr);
            DataTable GetFilteredViolationsBasedOntheWorkDone = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            ArrayList GetFilteredViolationsBasedOntheWorkDoneList = new ArrayList();
            foreach (DataRow row in GetFilteredViolationsBasedOntheWorkDone.Rows)
            {
                GetFilteredViolationsBasedOntheWorkDoneList.Add(row.ItemArray);
            }
            return GetFilteredViolationsBasedOntheWorkDoneList.ToArray();
        }
