            string part = GetDateTablePartitions(Convert.ToDateTime(fromDate), Convert.ToDateTime(toDate), partions);
            var lParameter = new Dictionary<string, object>();

            query = "select distinct vehicleid,type,timestamp,duration,location,remarks,drivername from storevehicleviolations PARTITION(" + part + ") AS s1 where timestamp between '"
