        public Object[] getDailyViolationList(String vehicleId, String fromDate, String toDate, String sessionId)
        {
            string query = String.Empty;
            string part = GetDateTablePartitions(Convert.ToDateTime(fromDate), Convert.ToDateTime(toDate), partions);
            var lParameter = new Dictionary<string, object>();
            if (String.Compare(vehicleId, "ALL") == 0)
            {
                DataTable dt = GetVehiclesBySessionId(sessionId).Tables[0];
                string vehls = string.Empty;
                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    vehls += "'" + dt.Rows[i]["VehicleId"].ToString() + "',";
                }
                vehls += "''";
                query = "select distinct s1.vehicleid as vehicleid,s1.type,s1.timestamp,s1.duration,s1.location,remarks,s1.drivername from storevehicleviolations PARTITION(" + part + ") AS s1 " +
                    " where s1.timestamp between '" + fromDate + "' and '" + toDate + "' and s1.vehicleid in (" + vehls + ") and s1.`type` not IN('NORMAL','JRM OVERSPEEDING','ROUTE DEVIATION','UNSCHEDULED STOP','SCHEDULED STOP') ";
            }
            else
            {
                query = "select  distinct vehicleid,type,timestamp,duration,location,remarks,drivername from storevehicleviolations PARTITION(" + part + ") AS s1 where timestamp between '"
                + fromDate + "' and '" + toDate + "' and vehicleid =? and type not IN('NORMAL','JRM OVERSPEEDING','ROUTE DEVIATION','UNSCHEDULED STOP','SCHEDULED STOP')";
                lParameter.Add("vehicleid", vehicleId);
            }
            DataSet violations = dbx.executeQuery(query, lParameter);

            violations.Tables[0].DefaultView.Sort = "vehicleid asc";
            DataTable table = violations.Tables[0].DefaultView.ToTable();
            DataRow dtrow = table.NewRow();
            table.Rows.Add(dtrow);
            ArrayList violationsList = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                violationsList.Add(row.ItemArray);
            }
            return violationsList.ToArray();
        }
