            query = "SELECT t.Name, v.vehicleId,`type` ,remarks,duration,DATE_FORMAT(TIMESTAMP, '%d/%m/%Y') TIMESTAMP, DATE_FORMAT(TIMESTAMP, '%H:%i:%s') time,Location,latitude,longitude,maxsamplesval,samples,drivername " +
                        " FROM violationsbetweenswipesNokia v left join vehicleinfo ve ON v.vehicleId=ve.VehicleId LEFT JOIN transporterinfo t ON t.TransporterId=ve.Transporter " +
                        " WHERE  " +
                        "  v.timestamp BETWEEN ? AND ? and v.vehicleId IN (" + inparam + ")";
            //lParameter.Add("p_groupid", groupid);
            //lParameter.Add("p_date", fromdate);
            //lParameter.Add("p_type", todate);
            //lParameter.Add("p_vehicles", vehicles);
            lParameter.Add("fromtimestamp", fromdate);
            lParameter.Add("totimestamp", todate);
            for (int i = 0; i < vals.Length; i++)
            {
                lParameter.Add("vehl" + i, vals[i]);
            }
            DataSet ds = dbx.executeQuery(query.ToString(), lParameter);
            DataTable table = ds.Tables[0];
            return table;
        }

