        public void MetroReturnRequestUpdate(string taxInvoiceNumber, MetroReturnRequest metroReturnRequest)
        {

            if (metroReturnRequest.returnStatus == "RETURN_CANCELLED")
            {
                // Need to update InvoiceType as Delivery
                // Update in metro invoice details - Return Id      
                string query = "UPDATE metro_invoice_details m SET m.InvoiceType = 'Delivery',m.ReturnId = ? WHERE m.ConsignmentId = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("ReturnId", "");
                lParameter.Add("ConsignmentId", metroReturnRequest.consignmentId);
                dbx.executeNonQuery(query, lParameter);

                // update metro_invoice_products
                query = "UPDATE metro_invoice_products m SET m.RequestedReturnQty = ?, m.IsReturnable = b'0' WHERE m.InvoiceId = ?";
                lParameter = new Dictionary<string, object>();
                lParameter.Add("RequestedReturnQty", "");
                lParameter.Add("InvoiceId", taxInvoiceNumber);
                dbx.executeNonQuery(query, lParameter);
            }
            else
            {
                // Need to update InvoiceType as Return
                // Update in metro invoice details - Return Id      
                string query = "UPDATE metro_invoice_details m SET m.InvoiceType = 'Return',m.ReturnId = ? WHERE m.ConsignmentId = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("ReturnId", metroReturnRequest.returnId);
                lParameter.Add("ConsignmentId", metroReturnRequest.consignmentId);
                dbx.executeNonQuery(query, lParameter);


                List<ReturnableItemsList> lp = metroReturnRequest.returnableItemsList;
                for (int i = 0; i < lp.Count; i++)
                {
                    // Insert into metro_invoice_product_return_log
                    query = "INSERT INTO metro_invoice_product_return_log(`TaxInvoiceNum`, `ProductId`, `ReturnId`, `ReturnType`,`RequestedReturnQty`,`ReasonCode`,`Description`,`FreebieMsg`,`RefundAmount`,`RequestedTimeStamp`)";
                    query += " VALUES (?,?,?,?,?,?,?,?,?,?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("TaxInvoiceNum", taxInvoiceNumber);
                    lParameter.Add("ProductId", lp[i].itemId);
                    lParameter.Add("ReturnId", metroReturnRequest.returnId);
                    lParameter.Add("ReturnType", "Post Delivery");
                    lParameter.Add("RequestedReturnQty", lp[i].qty);
                    lParameter.Add("ReasonCode", lp[i].reasonCode);
                    lParameter.Add("Description", lp[i].description);
                    lParameter.Add("FreebieMsg", lp[i].freebieMsg);
                    lParameter.Add("RefundAmount", lp[i].refundAmount);
                    lParameter.Add("RequestedTimeStamp", formatDBDate(DateTime.Now));
                    dbx.executeNonQuery(query, lParameter);

                    //update metro_invoice_products
                    query = "UPDATE metro_invoice_products m SET m.RequestedReturnQty = ?, m.IsReturnable = b'1' WHERE m.ProductId = ? and m.InvoiceId = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("RequestedReturnQty", lp[i].qty);
                    lParameter.Add("ProductId", lp[i].itemId);
                    lParameter.Add("InvoiceId", taxInvoiceNumber);
                    dbx.executeNonQuery(query, lParameter);
                }

            }


        }

