        public void updatesimtoken(string tokenname, string simtoken, string timestamp)
        {

            string query = "select count(*) from simtrackingtoken where name=" + "'" + tokenname + "'";
            int cnt = Convert.ToInt16(dbx.executeScalar(query));
            if (cnt == 0)
            {
                query = "insert into simtrackingtoken(name,token,updatetime) values(" +
                        "'" + tokenname + "'," + "'" + simtoken + "'," +
                        "'" + timestamp + "')";
                try
                {
                    dbx.executeNonQuery(query);
                }
                catch (Exception ex) { return; }

            }
            else
            {
                query = "update simtrackingtoken set token=" + "'" + simtoken + "'," +
                                " updatetime=" + "'" + timestamp + "'" + " where name = " +
                                 "'" + tokenname + "';";
                try
                {

                    dbx.executeNonQuery(query);

                }
                catch (Exception ex) { return; }
            }

        }


        public void updatesimconsenttoken(string tokenname, string consenttoken, string timestamp)
        {

            string query = "select count(*) from simtrackingtoken where name=" + "'" + tokenname + "'";
            int cnt = Convert.ToInt16(dbx.executeScalar(query));
            if (cnt == 0)
            {
                query = "insert into simtrackingtoken(name,token,updatetime) values(" +
                        "'" + tokenname + "'," + "'" + consenttoken + "'," +
                        "'" + timestamp + "')";
                try
                {
                    dbx.executeNonQuery(query);
                }
                catch (Exception ex) { return; }

            }
            else
            {
                query = "update simtrackingtoken set token=" + "'" + consenttoken + "'," +
                                " updatetime=" + "'" + timestamp + "'" + " where name = " +
                                 "'" + tokenname + "';";
