                {

                    dbx.executeNonQuery(query);

                }
                catch (Exception ex) { return; }
            }

        }

        public string getcurrenttoken(string tokenname, ref string token)
        {
            string query = "select updatetime from simtrackingtoken where name=" + "'" + tokenname + "'";
            DateTime tokenupdatetime = Convert.ToDateTime(dbx.executeScalar(query));
            if (!(tokenupdatetime.Equals(System.DBNull.Value)))
            {
                if (tokenupdatetime < DateTime.UtcNow.AddSeconds(19800).AddHours(-6))
                    return "token expired";

                else
                {

                    string query1 = "select token from simtrackingtoken where name=" + "'" + tokenname + "'";
                    token = Convert.ToString(dbx.executeScalar(query1));

                    return "token valid";
                }

            }
            else
                return "insert new token";
        }

