        public DataTable MetroGetDriverAppUsageReportDetailsForTransporters(string storeNo, int transporterId, DateTime tripsStartAt, DateTime tripsEndAt)
        {
            string query = "SELECT m.StoreNo ,m.TripNum,m.TripDate AS TripDateandTime,m.PaymentType,m.Trip_Status AS Delivery_status," +
                "m.VehicleId,v.VehicleType,t.ShortName AS Transporter,v.Capacity,m.DISTANCE,m.NoOfCustomers,m.NoOfInvoices,v.DriverName," +
                "v.Mobile,IF(IFNULL(m.DriverId, '0') = '0', 'No', 'Yes') AS AppUsage FROM metro_trip_details m JOIN metro_market_vehicles v " +
                "ON v.VehicleId = m.VehicleId AND v.Active = 1 LEFT JOIN transporterinfo t ON t.TransporterId = m.TransporterId WHERE" +
                " m.TripDate BETWEEN ? AND ? AND m.TransporterId = ?";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("tripsStartAt", formatDBDate(tripsStartAt));
            lParameter.Add("tripsEndAt", formatDBDate(tripsEndAt));
            lParameter.Add("TransporterId", transporterId);
            //if (!string.IsNullOrEmpty(storeNo.Trim()))
            if (storeNo != "")
            {
                query += " AND m.StoreNo=?";
                lParameter.Add("StoreNo", storeNo);
            }
            query += " ORDER BY m.StoreNo";
            return dbx.executeQuery(query, lParameter).Tables[0];
        }

