        public DataTable checkmobilenum(object myObject, string AccountId)
        {
            Type myType = myObject.GetType();
            System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
            string ContactNo = HttpUtility.HtmlEncode(props[10].GetValue(myObject, null).ToString());
            string MobileNo = HttpUtility.HtmlEncode(props[11].GetValue(myObject, null).ToString());
            string query = "SELECT d.MobileNo FROM driverinfo d WHERE d.MobileNo= " + "'" + MobileNo + "' and d.AccountId= " + "'" + AccountId + "'";
            DataTable dm = dbx.executeQuery(query).Tables[0];
            return dm;
        }
        public DataTable checkduplicateLicenseNO(object myObject, string AccountId)
        {
            Type myType = myObject.GetType();
            System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
            string LicenseNo = HttpUtility.HtmlEncode(props[12].GetValue(myObject, null).ToString());
            string query = "SELECT d.LicenceNo FROM driverinfo d WHERE REPLACE(d.LicenceNo, ' ', '')= ? and d.AccountId=?";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("LicenceNo", LicenseNo.Replace(" ", ""));
            lParameter.Add("AccountId", AccountId);
            DataTable dm = dbx.executeQuery(query, lParameter).Tables[0];
            return dm;
        }

