        public Object[] dtGatewiseInspectionCheck()
        {
            StringBuilder query = new StringBuilder();
            DateTime now = DateTime.Now;
            query.Append("SELECT * FROM stl_workflow s join stl_users u on s.username=u.username WHERE s.datetime > '" + now.AddMinutes(-30).ToString("yyyy-MM-dd HH:mm:ss") + "' AND s.workflowtype in (0,3) and u.Gate !=0 order by u.Gate asc ");

            DataSet WorkNotEndeddetails = dbx.executeQuery(query.ToString());
            DataTable dtWorkNotEndeddetails = WorkNotEndeddetails.Tables[0];
            ArrayList WorkNotEndeddetailsList = new ArrayList();
            foreach (DataRow row in dtWorkNotEndeddetails.Rows)
            {
                WorkNotEndeddetailsList.Add(row.ItemArray);
            }
            return WorkNotEndeddetailsList.ToArray();
        }

