        public DataSet GetUltraTechTripSummary(int GroupId, int accountid, string Yard, string Shift, DateTime fromdate, DateTime todate)
        {
            STL_RecordErrorMessage("ultratech-" + "Yard-" + Yard + "-Shift-" + Shift + "-fromdate-" + fromdate + "-todate-" + todate);
            string frdate = string.Empty;
            string tdate = string.Empty;
            string query = "";
            string shiftFilter = "";
            if (String.IsNullOrEmpty(Yard) || Yard == "--Select Yard--")
            {
                Yard = "ALL";
            }
            if (String.IsNullOrEmpty(Shift) || Shift == "--SELECT SHIFT--")
            {
                Shift = "ALL";
            }

            /*if (!String.IsNullOrEmpty(fromdate))
                {
                    try
                    {
                        frdate = formatDBDate(DateTime.ParseExact(fromdate, "dd/mm/yyyy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                    }
                    catch (Exception e)
                    {
                        frdate = formatDBDate(Convert.ToDateTime(fromdate));
                    }
                }
                if (!String.IsNullOrEmpty(todate))
                {
                    try
                    {
                        tdate = formatDBDate(DateTime.ParseExact(todate, "dd/mm/yyyy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture));

                    }
                    catch (Exception e)
                    {
                        tdate = formatDBDate(Convert.ToDateTime(todate));
                    }
                }*/
            string formattedFromDate = formatDBDate(fromdate);
            string formattedToDate = formatDBDate(todate);

            if (Shift.ToUpper() == "ALL")
            {
                // If Shift is "ALL", include all shifts
                shiftFilter = "'A', 'B', 'C'";
            }
            else
            {
                // If Shift is not "ALL", include only the specified shift
                shiftFilter = "'" + Shift.ToUpper() + "'";
            }
            if ((Shift.ToUpper() == "ALL" && Yard == "ALL") || (Yard == "ALL"))
            {
                try
                {
                    query = "SELECT d.Tipper_No AS vehicleNo, DATE_FORMAT(CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN d.Tipper_InTime " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN d.Tipper_InTime " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN DATE_SUB(DATE(d.Tipper_InTime), INTERVAL 1 DAY) " +
                            "ELSE DATE(d.Tipper_InTime) END, '%d/%m/%Y') AS 'Date', CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' " +
                                    "END AS Shift, CASE WHEN d.Loading_Geo_Fence_Name LIKE '%Naokari Yard%' THEN 'Naokari Yard' " +
                        "WHEN d.Loading_Geo_Fence_Name LIKE '%Tower Yard%' THEN 'Tower Yard' WHEN d.Loading_Geo_Fence_Name LIKE '%Details Not entered%' THEN 'Details Not entered' ELSE 'Railway Line 11' END AS Yard, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('US Coal Naokari Yard') THEN 1 ELSE 0 END) AS Actual_US, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Ghonsa Coal Naokari Yard') THEN 1 ELSE 0 END) AS Actual_Ghonsa, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Linkage Coal Naokari Yard') THEN 1 ELSE 0 END) AS Actual_Linkage, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Petcock Coal Naokari Yard') THEN 1 ELSE 0 END) AS Actual_Petcock, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Details Not entered') THEN 1 ELSE 0 END) AS Other, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('US Coal Naokari Yard') AND Shift = CASE " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_US, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Ghonsa Coal Naokari Yard') AND Shift = CASE " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Ghonsa, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Linkage Coal Naokari Yard') " +
                        "AND Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Linkage, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Petcock Coal Naokari Yard') " +
                        "AND Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Petcock,SEC_TO_TIME(SUM(TIME_TO_SEC(TIMEDIFF(d.Tipper_OutTime, d.Tipper_InTime)))) AS IdlingHours, " +
                    "SEC_TO_TIME(8 * 3600 - SUM(TIME_TO_SEC(TIMEDIFF(d.Tipper_OutTime, d.Tipper_InTime)))) AS RunningHours FROM ultratech_trip_details d " +
                "WHERE d.Tipper_InTime > '" + formattedFromDate + "' AND d.Tipper_InTime < '" + formattedToDate + "' AND d.Loading_Geo_Fence_Name LIKE '%Naokari Yard%' " +
                    "AND (CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' " +
                            "ELSE 'C' END IN (" + shiftFilter + ")) GROUP BY d.Tipper_No, DATE_FORMAT(CASE " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN d.Tipper_InTime " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN d.Tipper_InTime " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN DATE_SUB(DATE(d.Tipper_InTime), INTERVAL 1 DAY) " +
                            "ELSE DATE(d.Tipper_InTime)END,'%d/%m/%Y'), CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' " +
                        "ELSE 'C' END, CASE WHEN d.Loading_Geo_Fence_Name LIKE '%Naokari Yard%' THEN 'Naokari Yard' WHEN d.Loading_Geo_Fence_Name LIKE '%Tower Yard%' THEN 'Tower Yard'  " +
                        "WHEN d.Loading_Geo_Fence_Name LIKE '%Details Not entered%' THEN 'Details Not Entered' ELSE 'Railway Line 11' END " +
                        "union " +
                        "SELECT d.Tipper_No AS vehicleNo, DATE_FORMAT(CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN d.Tipper_InTime " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN d.Tipper_InTime " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN DATE_SUB(DATE(d.Tipper_InTime), INTERVAL 1 DAY) " +
                            "ELSE DATE(d.Tipper_InTime) END, '%d/%m/%Y') AS 'Date', CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' " +
                                    "END AS Shift, CASE WHEN d.Loading_Geo_Fence_Name LIKE '%Naokari Yard%' THEN 'Naokari Yard' " +
                        "WHEN d.Loading_Geo_Fence_Name LIKE '%Tower Yard%' THEN 'Tower Yard' WHEN d.Loading_Geo_Fence_Name LIKE '%Details Not entered%' THEN 'Details Not entered' ELSE 'Railway Line 11' END AS Yard, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('US Coal Tower Yard') THEN 1 ELSE 0 END) AS Actual_US, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Ghonsa Coal Tower Yard') THEN 1 ELSE 0 END) AS Actual_Ghonsa, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Linkage Coal Tower Yard') THEN 1 ELSE 0 END) AS Actual_Linkage, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Petcock Coal Tower Yard') THEN 1 ELSE 0 END) AS Actual_Petcock, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Details Not entered') THEN 1 ELSE 0 END) AS Other, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('US Coal Tower Yard') AND Shift = CASE " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_US, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Ghonsa Coal Tower Yard') AND Shift = CASE " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Ghonsa, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Linkage Coal Tower Yard') " +
                        "AND Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Linkage, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Petcock Coal Tower Yard') " +
                        "AND Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Petcock, SEC_TO_TIME(SUM(TIME_TO_SEC(TIMEDIFF(d.Tipper_OutTime, d.Tipper_InTime)))) AS IdlingHours, " +
                    "SEC_TO_TIME(8 * 3600 - SUM(TIME_TO_SEC(TIMEDIFF(d.Tipper_OutTime, d.Tipper_InTime)))) AS RunningHours FROM ultratech_trip_details d " +
                "WHERE d.Tipper_InTime > '" + formattedFromDate + "' AND d.Tipper_InTime < '" + formattedToDate + "' AND d.Loading_Geo_Fence_Name LIKE '%Tower Yard%' " +
                    "AND (CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' " +
                            "ELSE 'C' END IN (" + shiftFilter + ")) GROUP BY d.Tipper_No, DATE_FORMAT(CASE " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN d.Tipper_InTime " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN d.Tipper_InTime " +
                            "WHEN TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN DATE_SUB(DATE(d.Tipper_InTime), INTERVAL 1 DAY) " +
                            "ELSE DATE(d.Tipper_InTime)END,'%d/%m/%Y'), CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' " +
