                    "AND (CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' " +
