                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('US Coal ', ?) THEN 1 ELSE 0 END) AS Actual_US, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Ghonsa Coal ', ?) THEN 1 ELSE 0 END) AS Actual_Ghonsa, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Linkage Coal ', ?) THEN 1 ELSE 0 END) AS Actual_Linkage, " +
                    "SUM(CASE WHEN d.Loading_Geo_Fence_Name = CONCAT('Petcock Coal ', ?) THEN 1 ELSE 0 END) AS Actual_Petcock, " +
