                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_US, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Ghonsa Coal ', ?) AND Shift = CASE " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Ghonsa, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Linkage Coal ', ?) " +
                        "AND Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Linkage, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Petcock Coal ', ?) " +
                        "AND Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_Petcock, " +
                    "COALESCE((SELECT SUM(No_Of_Trips) FROM ultratech_target_trips WHERE Coal_Type = CONCAT('Railway yard Coal') " +
                        "AND Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                                        "WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END " +
                        "AND Date = DATE(d.Tipper_InTime)), 0) AS Target_US,SEC_TO_TIME(SUM(TIME_TO_SEC(TIMEDIFF(d.Tipper_OutTime, d.Tipper_InTime)))) AS IdlingHours, " +
                    "SEC_TO_TIME(8 * 3600 - SUM(TIME_TO_SEC(TIMEDIFF(d.Tipper_OutTime, d.Tipper_InTime)))) AS RunningHours FROM ultratech_trip_details d " +
                "WHERE d.Tipper_InTime BETWEEN ? AND ? and d.Tipper_OutTime BETWEEN ? AND ? AND d.Loading_Geo_Fence_Name LIKE '%" + Yard + "%' " +
                    "AND (CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' " +
                            "ELSE 'C' END IN (" + shiftFilter + ")) GROUP BY d.Tipper_No, DATE_FORMAT(CASE " +
