            lParameter.Add("fromdate", formatDBDate(fromdate));
            lParameter.Add("todate", formatDBDate(todate));
            lParameter.Add("fromdate1", formatDBDate(fromdate));
            lParameter.Add("todate1", formatDBDate(todate));

            STL_RecordErrorMessage("ultratech-" + "-fromdate-" + frdate + "-todate-" + tdate);
            //lParameter.Add("Yard", Yard);
            //lParameter.Add("Shift", Shift);
            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
