        public DataSet CheckTargetTripsCount(string vehicleNo, string yard, string shift, DateTime Date, string targetLinkage, string targetUS, string targetGhonsa, string targetPetcock)
        {
            string query = "";
            if (shift == "A" || shift == "B")
            {
                query = " SELECT u.Tipper_No, t.Coal_Type, t.Date,t.Shift,vc.Total_Vehicle_Count AS Vehicle_Count,FLOOR(t.No_Of_Trips / vc.Total_Vehicle_Count) AS TripsPerVehicle," +
                   "ROUND(t.No_Of_Trips % vc.Total_Vehicle_Count, 0) AS TripsPerVehicle1 FROM (SELECT Tipper_No,CASE WHEN TIME(Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                   "WHEN TIME(Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' WHEN TIME(Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59' OR TIME(Tipper_InTime) " +
                   "BETWEEN '00:00:00' AND '05:59:59' THEN 'C' END AS Shift FROM ultratech_trip_details WHERE DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN ? AND ?  ) u " +
                   "JOIN ultratech_target_trips t ON t.Date = ? AND t.Shift = u.Shift JOIN (SELECT COUNT(DISTINCT Tipper_No) AS Total_Vehicle_Count FROM ultratech_trip_details " +
                   "WHERE DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN ? AND ? ) vc ON 1=1 WHERE t.Coal_Type LIKE '%" + yard + "%' AND t.Shift = ? GROUP BY u.Tipper_No, " +
                   "t.Coal_Type, t.Shift, vc.Total_Vehicle_Count, t.No_Of_Trips; ";
                var lParameter = new Dictionary<string, object>();
                //lParameter.Add("vehicleNo", vehicleNo);
                //lParameter.Add("yard", yard);
                //lParameter.Add("shift", shift);
                lParameter.Add("Date", Date.ToString("yyyy-MM-dd"));
                if (shift == "A")
                {
                    lParameter["StartTime"] = "06:00:00";
                    lParameter["EndTime"] = "13:59:59";
                }
                else if (shift == "B")
                {
                    lParameter["StartTime"] = "14:00:00";
                    lParameter["EndTime"] = "21:59:59";
                }
                lParameter.Add("Date1", Date.ToString("yyyy-MM-dd"));
                lParameter.Add("Date2", Date.ToString("yyyy-MM-dd"));
                if (shift == "A")
                {
                    lParameter["StartTime1"] = "06:00:00";
                    lParameter["EndTime1"] = "13:59:59";
                }
                else if (shift == "B")
                {
                    lParameter["StartTime1"] = "14:00:00";
                    lParameter["EndTime1"] = "21:59:59";
                }

                lParameter.Add("shift1", shift);
                DataSet dstripDetails = dbx.executeQuery(query, lParameter);
                return dstripDetails;
            }
            else if (shift == "C")
            {
                query = " SELECT u.Tipper_No, t.Coal_Type, t.Date,t.Shift,vc.Total_Vehicle_Count AS Vehicle_Count,FLOOR(t.No_Of_Trips / vc.Total_Vehicle_Count) AS TripsPerVehicle," +
                   "ROUND(t.No_Of_Trips % vc.Total_Vehicle_Count, 0) AS TripsPerVehicle1 FROM (SELECT Tipper_No,CASE WHEN TIME(Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' " +
                   "WHEN TIME(Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' WHEN TIME(Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59' OR TIME(Tipper_InTime) " +
                   "BETWEEN '00:00:00' AND '05:59:59' THEN 'C' END AS Shift FROM ultratech_trip_details WHERE (DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59') " +
                   "OR (DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59')) u JOIN ultratech_target_trips t ON t.Date = ? AND t.Shift = u.Shift " +
                   "JOIN(SELECT COUNT(DISTINCT Tipper_No) AS Total_Vehicle_Count FROM ultratech_trip_details WHERE(DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59') OR " +
                    "(DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59')) vc ON 1 = 1 WHERE t.Coal_Type LIKE '%" + yard + "%' AND t.Shift = ? GROUP BY u.Tipper_No,t.Coal_Type, t.Shift, vc.Total_Vehicle_Count, t.No_Of_Trips; ";
            }
            var lParameter1 = new Dictionary<string, object>();

            lParameter1.Add("Date", Date.ToString("yyyy-MM-dd"));
            lParameter1.Add("Date1", Date.AddDays(1).ToString("yyyy-MM-dd"));
            lParameter1.Add("Date2", Date.ToString("yyyy-MM-dd"));
            lParameter1.Add("Date3", Date.ToString("yyyy-MM-dd"));
            lParameter1.Add("Date4", Date.AddDays(1).ToString("yyyy-MM-dd"));
            lParameter1.Add("shift1", shift);
            DataSet dstripDetails1 = dbx.executeQuery(query, lParameter1);
            return dstripDetails1;

        }

        public string InsertUltraTech(string Loader_No, string coalType, int noOfTrips, DateTime fromDate, DateTime toDate, string username, int GroupId, int accountid)
        {

            string insertquery1 = "INSERT INTO `ultratech_plannedtrip_Log` (`Loader_No`, `Coal_Type`, `No_Of_Trips`, `From_Date`, `To_Date`, `IsActive`, `Added_By`, `Added_On`, `GroupId`, `AccountId`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?);";

            var insertparameters1 = new Dictionary<string, object>();
            insertparameters1.Add("Loader_No", Loader_No);
            insertparameters1.Add("Coal_Type", coalType);
            insertparameters1.Add("No_Of_Trips", noOfTrips);
            insertparameters1.Add("From_Date", fromDate.ToString("yyyy-MM-dd HH:mm:ss"));
            insertparameters1.Add("To_Date", toDate.ToString("yyyy-MM-dd HH:mm:ss"));
            insertparameters1.Add("IsActive", 1);
            insertparameters1.Add("Added_By", username);
            insertparameters1.Add("Added_On", formatDBDate(DateTime.Now));
            insertparameters1.Add("GroupId", GroupId);
            insertparameters1.Add("AccountId", accountid);

            int res1 = dbx.executeNonQuery(insertquery1, insertparameters1);
            try
            {
                string query = "SELECT * FROM `ultratech_plannedtrip` WHERE `Loader_No` = ? AND  `Coal_Type` = ? AND  `From_Date` = ? AND `To_Date`= ?  AND `AccountId` = ?;";

                var parameters = new Dictionary<string, object>();
                parameters.Add("Loader_No", Loader_No);
                parameters.Add("coalType", coalType);
                parameters.Add("From_Date", fromDate.ToString("yyyy-MM-dd HH:mm:ss"));
                parameters.Add("To_Date", toDate.ToString("yyyy-MM-dd HH:mm:ss"));
                //parameters.Add("GroupId", GroupId);
                parameters.Add("AccountId", accountid);
                parameters.Add("Added_By", username);

                DataTable dt = dbx.executeQuery(query, parameters).Tables[0];

                if (dt.Rows.Count > 0)
                {
                    //return "Details already entered. Please edit the No. of Trips column if required.";
                    int id = Convert.ToInt32(dt.Rows[0]["ID"]);
                    int currentNoOfTrips = Convert.ToInt32(dt.Rows[0]["No_Of_Trips"]);
                    int updatedNoOfTrips = currentNoOfTrips + noOfTrips;
                    string updateQuery = "UPDATE `ultratech_plannedtrip` SET `No_Of_Trips` = ? WHERE `ID` = ? AND `Coal_Type` = ? AND `Loader_No` = ?  AND `From_Date` = ? AND `To_Date` = ?  AND `AccountId` = ? AND `IsActive` = 1;";
                    var updateParameters = new Dictionary<string, object>();
                    updateParameters.Add("No_Of_Trips", updatedNoOfTrips);
                    updateParameters.Add("ID", id);
                    updateParameters.Add("coalType", coalType);
                    updateParameters.Add("Loader_No", Loader_No);
                    updateParameters.Add("From_Date", fromDate.ToString("yyyy-MM-dd HH:mm:ss"));
                    updateParameters.Add("To_Date", toDate.ToString("yyyy-MM-dd HH:mm:ss"));
                    //updateParameters.Add("GroupId", GroupId);
                    updateParameters.Add("AccountId", accountid);
                    //updateParameters.Add("Added_By", username);

                    int result = dbx.executeNonQuery(updateQuery, updateParameters);

                    if (result > 0)
                        return "Details already exist. No.of trips has been updated.";
                    else
                        return "Failed to update.";
                }
                else
                {
                    string insertquery = "INSERT INTO `ultratech_plannedtrip` (`Loader_No`, `Coal_Type`, `No_Of_Trips`, `From_Date`, `To_Date`, `IsActive`, `Added_By`, `Added_On`, `GroupId`, `AccountId`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?);";

                    var insertparameters = new Dictionary<string, object>();
                    insertparameters.Add("Loader_No", Loader_No);
                    insertparameters.Add("Coal_Type", coalType);
                    insertparameters.Add("No_Of_Trips", noOfTrips);
                    insertparameters.Add("From_Date", fromDate.ToString("yyyy-MM-dd HH:mm:ss"));
                    insertparameters.Add("To_Date", toDate.ToString("yyyy-MM-dd HH:mm:ss"));
                    insertparameters.Add("IsActive", 1);
                    insertparameters.Add("Added_By", username);
                    insertparameters.Add("Added_On", formatDBDate(DateTime.Now));
                    insertparameters.Add("GroupId", GroupId);
                    insertparameters.Add("AccountId", accountid);

                    int res = dbx.executeNonQuery(insertquery, insertparameters);

                    if (res > 0)
                        return "Success";
                    else
                        return "Failed";
                }
            }
            catch (Exception e)
            {
                return "Failed";
            }
        }
