        public DataSet GetMaterialSummaryReport(int GroupId, int accountid, string Material, string Shift, DateTime fromdate, DateTime todate)
        {
            string frdate = string.Empty;
            string tdate = string.Empty;
            string query = "";
            string shiftFilter = "";
            string YardFilter = "";
            if (String.IsNullOrEmpty(Material) || Material == "'--Select Material--'")
            {
                Material = "'ALL'";
            }
            if (String.IsNullOrEmpty(Shift) || Shift == "'--SELECT SHIFT--'")
            {
                Shift = "'ALL'";
            }

            if (Shift.ToUpper() == "'ALL'")
            {
                Shift = "'A', 'B', 'C'";
            }
            if (Material.ToUpper() == "'ALL'")
            {
                query = "SELECT u.Vehicle_No as vehicleNo,DATE_FORMAT(u.Date, '%d/%m/%Y') AS Date,u.Shift,u.Target_Redmud,u.Actual_Redmud,u.Target_Flyash,u.Actual_Flyash,u.Target_Limestone,u.Actual_Limestone,u.Target_Bauxite,u.Actual_Bauxite,u.Target_Laterite,u.Actual_Laterite,u.Other as Actual_Others,u.Idling_Hrs as IdlingHours, u.Running_Hrs as RunningHours FROM ultratech_summary_report u WHERE u.Date BETWEEN ? AND ? AND u.Shift IN (" + Shift + ") AND u.Yard='Material';";
            }
            else if (Material == "'Redmud'")
            {
                query = "SELECT u.Vehicle_No as vehicleNo,DATE_FORMAT(u.Date, '%d/%m/%Y') AS Date,u.Shift,CASE WHEN u.Target_Redmud IS NOT NULL OR u.Actual_Redmud IS NOT NULL THEN u.Target_Redmud ELSE 0 END AS Target_Redmud,CASE WHEN u.Target_Redmud IS NOT NULL OR u.Actual_Redmud IS NOT NULL THEN " +
                    "u.Actual_Redmud ELSE 0 END AS Actual_Redmud,0 AS Target_Limestone, 0 AS Actual_Limestone, 0 AS Target_Flyash, 0 AS Actual_Flyash, 0 AS Target_Bauxite, 0 AS Actual_Bauxite, 0 AS Target_Laterite, 0 AS Actual_Laterite, 0 AS Actual_Others, u.Idling_Hrs as IdlingHours, u.Running_Hrs as RunningHours FROM ultratech_summary_report u WHERE u.Date BETWEEN ? AND ? AND u.Shift IN (" + Shift + ") AND (u.Target_Redmud IS NOT NULL OR u.Actual_Redmud IS NOT NULL) AND NOT (u.Target_Redmud = 0 AND u.Actual_Redmud = 0) ORDER BY u.Date DESC;";

            }
            else if (Material == "'Limestone'")
            {
                query = "SELECT u.Vehicle_No as vehicleNo,DATE_FORMAT(u.Date, '%d/%m/%Y') AS Date,u.Shift,CASE WHEN u.Target_Limestone IS NOT NULL OR u.Actual_Limestone IS NOT NULL THEN u.Target_Limestone ELSE 0 END AS Target_Limestone, CASE WHEN u.Target_Limestone IS NOT NULL OR u.Actual_Limestone IS NOT NULL THEN " +
                    "u.Actual_Limestone ELSE 0 END AS Actual_Limestone,0 AS Target_Redmud, 0 AS Actual_Redmud, 0 AS Actual_Limestone, 0 AS Target_Flyash, 0 AS Actual_Flyash, 0 AS Target_Bauxite, 0 AS Actual_Bauxite, 0 AS Target_Laterite, 0 AS Actual_Laterite, 0 as Actual_Others,u.Idling_Hrs as IdlingHours,u.Running_Hrs as RunningHours FROM ultratech_summary_report u WHERE u.Date BETWEEN ? AND ? AND u.Shift IN (" + Shift + ") AND (u.Target_Limestone IS NOT NULL OR u.Actual_Limestone IS NOT NULL) AND NOT (u.Target_Limestone = 0 AND u.Actual_Limestone = 0) ORDER BY u.Date DESC;";
            }
            else if (Material == "'Flyash'")
            {
                query = "SELECT u.Vehicle_No as vehicleNo,DATE_FORMAT(u.Date, '%d/%m/%Y') AS Date,u.Shift, 0 AS Target_Redmud, 0 AS Actual_Redmud,  0 AS Target_Limestone,  0 AS Actual_Limestone,CASE WHEN u.Target_Flyash IS NOT NULL OR u.Actual_Flyash IS NOT NULL THEN u.Target_Flyash ELSE 0 END AS Target_Flyash,CASE WHEN u.Target_Flyash IS NOT NULL OR u.Actual_Flyash IS " +
                    "NOT NULL THEN u.Actual_Flyash ELSE 0 END AS Actual_Flyash,0 AS Actual_Limestone, 0 AS Target_Flyash, 0 AS Actual_Flyash, 0 AS Target_Bauxite, 0 AS Actual_Bauxite, 0 AS Target_Laterite, 0 AS Actual_Laterite,0 AS Actual_Others, u.Idling_Hrs as IdlingHours, u.Running_Hrs as RunningHours FROM ultratech_summary_report u WHERE u.Date BETWEEN ? AND ? AND u.Shift IN (" + Shift + ") AND (u.Target_Flyash IS NOT NULL OR u.Actual_Flyash IS NOT NULL) AND NOT (u.Target_Flyash = 0 AND u.Actual_Flyash = 0) ORDER BY u.Date DESC;";
            }
            else if (Material == "'Bauxite'")
            {
                query = "SELECT u.Vehicle_No as vehicleNo,DATE_FORMAT(u.Date, '%d/%m/%Y') AS Date,u.Shift, 0 AS Target_Redmud, 0 AS Actual_Redmud,  0 AS Target_Limestone,  0 AS Actual_Limestone, 0 AS Target_Flyash,  0 AS Actual_Flyash, CASE WHEN u.Target_Bauxite IS NOT NULL OR u.Actual_Bauxite IS NOT NULL THEN u.Target_Flyash ELSE 0 END AS Target_Flyash,CASE WHEN u.Target_Flyash IS NOT NULL OR u.Actual_Flyash IS " +
                    "NOT NULL THEN u.Actual_Bauxite ELSE 0 END AS Actual_Bauxite,0 AS Actual_Limestone, 0 AS Target_Flyash, 0 AS Actual_Flyash, 0 AS Target_Bauxite, 0 AS Actual_Bauxite, 0 AS Target_Laterite, 0 AS Actual_Laterite,0 AS Actual_Others, u.Idling_Hrs as IdlingHours, u.Running_Hrs as RunningHours FROM ultratech_summary_report u WHERE u.Date BETWEEN ? AND ? AND u.Shift IN (" + Shift + ") AND (u.Target_Bauxite IS NOT NULL OR u.Actual_Bauxite IS NOT NULL) AND NOT (u.Target_Flyash = 0 AND u.Actual_Flyash = 0) ORDER BY u.Date DESC;";
            }
            else if (Material == "'Laterite'")
            {
                query = "SELECT u.Vehicle_No as vehicleNo,DATE_FORMAT(u.Date, '%d/%m/%Y') AS Date,u.Shift, 0 AS Target_Redmud, 0 AS Actual_Redmud,  0 AS Target_Limestone,  0 AS Actual_Limestone, 0 AS Target_Flyash,  0 AS Actual_Flyash, 0 AS Target_Bauxite,  0 AS Actual_Bauxite,  CASE WHEN u.Target_Laterite IS NOT NULL OR u.Actual_Laterite IS NOT NULL THEN u.Target_Laterite ELSE 0 END AS Target_Laterite,CASE WHEN u.Target_Laterite IS NOT NULL OR u.Actual_Laterite IS " +
                     "NOT NULL THEN u.Actual_Laterite ELSE 0 END AS Actual_Laterite,0 AS Actual_Limestone, 0 AS Target_Laterite, 0 AS Actual_Laterite, 0 AS Target_Bauxite, 0 AS Actual_Bauxite, 0 AS Target_Laterite, 0 AS Actual_Laterite,0 AS Actual_Others, u.Idling_Hrs as IdlingHours, u.Running_Hrs as RunningHours FROM ultratech_summary_report u WHERE u.Date BETWEEN ? AND ? AND u.Shift IN (" + Shift + ") AND (u.Target_Laterite IS NOT NULL OR u.Actual_Laterite IS NOT NULL) AND NOT (u.Target_Laterite = 0 AND u.Actual_Laterite = 0) ORDER BY u.Date DESC;";
            }
            else if (Material == "'Details Not Entered'")
            {
                query = "SELECT u.Vehicle_No as vehicleNo,DATE_FORMAT(u.Date, '%d/%m/%Y') AS Date,u.Shift, 0 AS Target_Redmud, 0 AS Actual_Redmud,  0 AS Target_Limestone,  0 AS Actual_Limestone,CASE WHEN u.Target_Flyash IS NOT NULL OR u.Actual_Flyash IS NOT NULL THEN u.Target_Flyash ELSE 0 END AS Target_Flyash,CASE WHEN u.Target_Flyash IS NOT NULL OR u.Actual_Flyash IS " +
                     "NOT NULL THEN u.Actual_Flyash ELSE 0 END AS Actual_Flyash,0 AS Actual_Limestone, 0 AS Target_Flyash, 0 AS Actual_Flyash, 0 AS Target_Bauxite, 0 AS Actual_Bauxite, 0 AS Target_Laterite, 0 AS Actual_Laterite,0 AS Actual_Others, u.Idling_Hrs as IdlingHours, u.Running_Hrs as RunningHours FROM ultratech_summary_report u WHERE u.Date BETWEEN ? AND ? AND u.Shift IN (" + Shift + ") AND (u.Target_Flyash IS NOT NULL OR u.Actual_Flyash IS NOT NULL) AND NOT (u.Target_Flyash = 0 AND u.Actual_Flyash = 0) ORDER BY u.Date DESC;";
            }
            var lParameter = new Dictionary<string, object>();

            //lParameter.Add("Shift", shiftFilter);
            //lParameter.Add("Yard1", YardFilter);
            //lParameter.Add("accountid", accountid);Date.ToString("yyyy-MM-dd"));
            lParameter.Add("fromdate", fromdate.ToString("yyyy-MM-dd"));
            lParameter.Add("todate", todate.ToString("yyyy-MM-dd"));

            DataSet dstripDetails = dbx.executeQuery(query, lParameter);
            return dstripDetails;
        }
