        public DataSet GetUltraTechMaterialSummaryReport(int GroupId, int accountid, string Material, string Shift, DateTime fromdate, DateTime todate)
        {
            string frdate = string.Empty;
            string tdate = string.Empty;
            string query = "";
            string formattedFromDate = formatDBDate(fromdate);
            string formattedToDate = formatDBDate(todate);
            if (Material == "'Redmud','Flyash','Limestone','Bauxite','Laterite'")
            {
                query = "SELECT d.Tipper_No AS vehicleNo,DATE_FORMAT(CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN d.Tipper_InTime WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN d.Tipper_InTime WHEN TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN DATE_SUB(DATE(d.Tipper_InTime), INTERVAL 1 DAY) ELSE DATE(d.Tipper_InTime) END, '%d/%m/%Y') AS Date," +
                    "CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END AS Shift,SUM(CASE WHEN d.Material = 'Redmud' THEN 1 ELSE 0 END) AS Actual_Redmud,SUM(CASE WHEN d.Material = 'Flyash' THEN 1 ELSE 0 END) AS Actual_Flyash,SUM(CASE WHEN d.Material = 'Limestone' THEN 1 ELSE 0 END) AS Actual_Limestone," +
                    "SUM(CASE WHEN d.Material = 'Bauxite' THEN 1 ELSE 0 END) AS Actual_Bauxite,SUM(CASE WHEN d.Material = 'Laterite' THEN 1 ELSE 0 END) AS Actual_Laterite,SUM(CASE WHEN d.Material NOT IN ('Redmud', 'Flyash', 'Limestone','Bauxite', 'Laterite', 'Coal') THEN 1 ELSE 0 END) AS Actual_Others,COALESCE(MAX(t.Target_Redmud), 0) AS Target_Redmud," +
                    "COALESCE(MAX(t.Target_Flyash), 0) AS Target_Flyash,COALESCE(MAX(t.Target_Limestone), 0) AS Target_Limestone,COALESCE(MAX(t.Target_Bauxite), 0) AS Target_Bauxite,COALESCE(MAX(t.Target_Laterite), 0) AS Target_Laterite,TIMEDIFF(MAX(d.Tipper_OutTime), MIN(d.Tipper_InTime)) AS IdlingHours,TIMEDIFF(MAX(d.Tipper_OutTime), MIN(d.Tipper_InTime)) AS RunningHours FROM ultratech_trip_details d " +
                    "LEFT JOIN (SELECT Date,Shift,SUM(CASE WHEN Coal_Type = 'Redmud' THEN No_Of_Trips ELSE 0 END) AS Target_Redmud,SUM(CASE WHEN Coal_Type = 'Flyash' THEN No_Of_Trips ELSE 0 END) AS Target_Flyash,SUM(CASE WHEN Coal_Type = 'Limestone' THEN No_Of_Trips ELSE 0 END) AS Target_Limestone,SUM(CASE WHEN Coal_Type = 'Bauxite' THEN No_Of_Trips ELSE 0 END) AS Target_Bauxite," +
                    "SUM(CASE WHEN Coal_Type = 'Laterite' THEN No_Of_Trips ELSE 0 END) AS Target_Laterite FROM ultratech_target_trips t WHERE EXISTS (SELECT 1 FROM ultratech_trip_details d WHERE DATE(d.Tipper_InTime) = t.Date AND ((t.Shift = 'A' AND TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59') OR (t.Shift = 'B' AND TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59') OR (t.Shift = 'C' AND (TIME(d.Tipper_InTime) " +
                    "BETWEEN '00:00:00' AND '05:59:59' OR TIME(d.Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59'))))GROUP BY Date, Shift) t ON DATE(t.Date) = DATE(d.Tipper_InTime) AND t.Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END WHERE (d.Material IN (" + Material + ") OR " +
                    "d.Material NOT IN ('Redmud', 'Flyash', 'Limestone','Bauxite','Laterite')) AND (CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END IN (" + Shift + ")) AND d.Tipper_InTime > ? AND d.Tipper_InTime < ? GROUP BY d.Tipper_No, Shift, DATE_FORMAT(CASE WHEN TIME(d.Tipper_InTime) " +
                    "BETWEEN '06:00:00' AND '13:59:59' THEN d.Tipper_InTime WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN d.Tipper_InTime WHEN TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN DATE_SUB(DATE(d.Tipper_InTime), INTERVAL 1 DAY) ELSE DATE(d.Tipper_InTime) END, '%d/%m/%Y') HAVING Actual_Redmud > 0 OR Actual_Flyash > 0 OR Actual_Limestone > 0 OR Actual_Bauxite > 0 OR Actual_Laterite > 0 OR Actual_Others > 0;";

                var lParameter = new Dictionary<string, object>();

                //lParameter.Add("Material", Material);
                //lParameter.Add("Shift", Shift);
                lParameter.Add("fromdate", formatDBDate(fromdate));
                lParameter.Add("todate", formatDBDate(todate));
                DataSet dstripDetails = dbx.executeQuery(query, lParameter);
                return dstripDetails;
            }
            else
            {
                query = "SELECT d.Tipper_No AS vehicleNo,DATE_FORMAT(CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN d.Tipper_InTime WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN d.Tipper_InTime  WHEN TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN DATE_SUB(DATE(d.Tipper_InTime), INTERVAL 1 DAY)  ELSE DATE(d.Tipper_InTime) END, '%d/%m/%Y') AS Date, CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END AS Shift,";
                if (Material == "'Redmud'")
                {
                    query += "SUM(CASE WHEN d.Material = 'Redmud' THEN 1 ELSE 0 END) AS Actual_Redmud, 0 AS Actual_Flyash, 0 AS Actual_Limestone, 0 AS Actual_Bauxite, 0 AS Actual_Laterite, 0 AS Actual_Others, ";
                }
                else if (Material == "'Flyash'")
                {
                    query += "0 AS Actual_Redmud, SUM(CASE WHEN d.Material = 'Flyash' THEN 1 ELSE 0 END) AS Actual_Flyash, 0 AS Actual_Limestone, 0 AS Actual_Bauxite, 0 AS Actual_Laterite, 0 AS Actual_Others, ";
                }
                else if (Material == "'Limestone'")
                {
                    query += "0 AS Actual_Redmud, 0 AS Actual_Flyash, SUM(CASE WHEN d.Material = 'Limestone' THEN 1 ELSE 0 END) AS Actual_Limestone, 0 AS Actual_Bauxite, 0 AS Actual_Laterite, 0 AS Actual_Others, ";
                }
                else if (Material == "'Bauxite'")
                {
                    query += "0 AS Actual_Redmud, 0 AS Actual_Flyash, 0 AS Actual_Limestone, SUM(CASE WHEN d.Material = 'Bauxite' THEN 1 ELSE 0 END) AS Actual_Bauxite, 0 AS Actual_Laterite,0 AS Actual_Others, ";
                }
                else if (Material == "'Laterite'")
                {
                    query += "0 AS Actual_Redmud, 0 AS Actual_Flyash, 0 AS Actual_Limestone, 0 AS Actual_Bauxite, SUM(CASE WHEN d.Material = 'Laterite' THEN 1 ELSE 0 END) AS Actual_Laterite,0 AS Actual_Others, ";
                }
                else
                {
                    query += "0 AS Actual_Redmud, 0 AS Actual_Flyash, 0 AS Actual_Limestone, 0 AS Actual_Bauxite, 0 AS Actual_Laterite,SUM(CASE WHEN d.Material not in ('Redmud', 'Flyash', 'Limestone', 'Bauxite', 'Laterite','Coal') THEN 1 ELSE 0 END) AS Actual_Others,";
                }
                query += " COALESCE(MAX(CASE WHEN " + Material + " = 'Redmud' THEN t.Target_Redmud ELSE 0 END), 0) AS Target_Redmud, COALESCE(MAX(CASE WHEN " + Material + "  = 'Flyash' THEN t.Target_Flyash ELSE 0 END), 0) AS Target_Flyash," +
                "COALESCE(MAX(CASE WHEN " + Material + " = 'Limestone' THEN t.Target_Limestone ELSE 0 END), 0) AS Target_Limestone, COALESCE(MAX(CASE WHEN " + Material + " = 'Bauxite' THEN t.Target_Bauxite ELSE 0 END), 0) AS Target_Bauxite," +
                "COALESCE(MAX(CASE WHEN " + Material + " = 'Laterite' THEN t.Target_Laterite ELSE 0 END), 0) AS Target_Laterite,				TIMEDIFF(MAX(d.Tipper_OutTime), MIN(d.Tipper_InTime)) AS IdlingHours, TIMEDIFF(MAX(d.Tipper_OutTime), " +
                "MIN(d.Tipper_InTime)) AS RunningHours FROM ultratech_trip_details d LEFT JOIN(SELECT Date, Shift, SUM(CASE WHEN Coal_Type = 'Redmud' THEN No_Of_Trips ELSE 0 END) AS Target_Redmud, SUM(CASE WHEN Coal_Type = 'Flyash' THEN No_Of_Trips ELSE 0 END) AS Target_Flyash, " +
                "SUM(CASE WHEN Coal_Type = 'Limestone' THEN No_Of_Trips ELSE 0 END) AS Target_Limestone, SUM(CASE WHEN Coal_Type = 'Bauxite' THEN No_Of_Trips ELSE 0 END) AS Target_Bauxite, " +
                "SUM(CASE WHEN Coal_Type = 'Laterite' THEN No_Of_Trips ELSE 0 END) AS Target_Laterite FROM ultratech_target_trips t WHERE EXISTS(SELECT 1 FROM ultratech_trip_details d WHERE DATE(d.Tipper_InTime) = t.Date AND((t.Shift = 'A' AND TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59') " +
                "OR(t.Shift = 'B' AND TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59') OR(t.Shift = 'C' AND(TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' OR TIME(d.Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59'))))GROUP BY Date, Shift) t ON " +
                "DATE(t.Date) = DATE(d.Tipper_InTime) AND t.Shift = CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END WHERE ";
                if (Material == "'Details Not Entered'")
                {
                    query += "d.Material NOT IN ('Redmud', 'Flyash', 'Limestone', 'Bauxite', 'Laterite', 'Coal') AND(CASE WHEN TIME(d.Tipper_InTime) ";
                }
                else
                {
                    query += "d.Material = " + Material + " AND(CASE WHEN TIME(d.Tipper_InTime) ";
                }
                query += "BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' ELSE 'C' END IN(" + Shift + "))AND d.Tipper_InTime > ? AND d.Tipper_InTime < ? GROUP BY  d.Tipper_No, Shift, " +
                "DATE_FORMAT(CASE WHEN TIME(d.Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN d.Tipper_InTime WHEN TIME(d.Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN d.Tipper_InTime WHEN TIME(d.Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN DATE_SUB(DATE(d.Tipper_InTime), INTERVAL 1 DAY) ELSE DATE(d.Tipper_InTime) END, '%d/%m/%Y');";

                var lParameter1 = new Dictionary<string, object>();

                //lParameter.Add("Material", Material);
                //lParameter.Add("Shift", Shift);
                lParameter1.Add("fromdate", formatDBDate(fromdate));
                lParameter1.Add("todate", formatDBDate(todate));
                DataSet dstripDetails1 = dbx.executeQuery(query, lParameter1);
                return dstripDetails1;
            }

        }

        public DataSet CheckMaterialTargetTripsCount(string vehicleNo, string yard, string shift, DateTime date, string targetRedmud, string targetFlyash, string targetLimestone, string targetBauxite, string targetLaterite)
        {
            // List to hold results for each material if multiple targets are provided
            DataSet finalResults = new DataSet();

            // Create a list of materials to check
            var materials = new List<string>();

            // Determine the materials based on provided targets
            if (!string.IsNullOrEmpty(targetRedmud) && int.TryParse(targetRedmud, out int redmudTarget) && redmudTarget != 0)
            {
                materials.Add("Redmud");
            }
            if (!string.IsNullOrEmpty(targetFlyash) && int.TryParse(targetFlyash, out int flyashTarget) && flyashTarget != 0)
            {
                materials.Add("Flyash");
            }
            if (!string.IsNullOrEmpty(targetLimestone) && int.TryParse(targetLimestone, out int limestoneTarget) && limestoneTarget != 0)
            {
                materials.Add("Limestone");
            }
            if (!string.IsNullOrEmpty(targetBauxite) && int.TryParse(targetBauxite, out int bauxiteTarget) && bauxiteTarget != 0)
            {
                materials.Add("Bauxite");
            }
            if (!string.IsNullOrEmpty(targetLaterite) && int.TryParse(targetLaterite, out int lateriteTarget) && lateriteTarget != 0)
            {
                materials.Add("Laterite");
            }

            // Check if there are any materials to process
            if (materials.Count > 0)
            {
                foreach (var material in materials)
                {
                    string query = "";
                    Dictionary<string, object> lParameter = new Dictionary<string, object>();

                    // Construct the query based on the shift
                    if (shift == "A" || shift == "B")
                    {
                        query = "SELECT u.Tipper_No, t.Coal_Type, t.Date, t.Shift, vc.Total_Vehicle_Count AS Vehicle_Count, COUNT(DISTINCT u.Tipper_No) AS DistinctVehicleCount, FLOOR(t.No_Of_Trips / vc.Total_Vehicle_Count) AS TripsPerVehicle, " +
                            "ROUND(t.No_Of_Trips % vc.Total_Vehicle_Count, 0) AS TripsPerVehicle1 FROM (SELECT Tipper_No, CASE WHEN TIME(Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(Tipper_InTime) BETWEEN '14:00:00' AND '21:59:59' THEN 'B' " +
                            "WHEN TIME(Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59' OR TIME(Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN 'C' END AS Shift FROM ultratech_trip_details WHERE DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN ? AND ?) u " +
                            "JOIN ultratech_target_trips t ON t.Date = ? AND t.Shift = u.Shift JOIN (SELECT COUNT(DISTINCT Tipper_No) AS Total_Vehicle_Count FROM ultratech_trip_details WHERE DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN ? AND ? AND Material IN " +
                            "('Redmud', 'Flyash', 'Limestone', 'Bauxite', 'Laterite')) vc ON 1=1 WHERE t.Coal_Type LIKE '%" + material + "%' AND t.Shift = ? GROUP BY u.Tipper_No, t.Coal_Type, t.Shift, vc.Total_Vehicle_Count, t.No_Of_Trips;";

                        lParameter.Add("Date", date.ToString("yyyy-MM-dd"));
                        if (shift == "A")
                        {
                            lParameter["StartTime"] = "06:00:00";
                            lParameter["EndTime"] = "13:59:59";
                        }
                        else if (shift == "B")
                        {
                            lParameter["StartTime"] = "14:00:00";
                            lParameter["EndTime"] = "21:59:59";
                        }
                        lParameter.Add("Date1", date.ToString("yyyy-MM-dd"));
                        lParameter.Add("Date2", date.ToString("yyyy-MM-dd"));
                        if (shift == "A")
                        {
                            lParameter["StartTime1"] = "06:00:00";
                            lParameter["EndTime1"] = "13:59:59";
                        }
                        else if (shift == "B")
                        {
                            lParameter["StartTime1"] = "14:00:00";
                            lParameter["EndTime1"] = "21:59:59";
                        }
                        lParameter.Add("shift1", shift);
                    }
                    else if (shift == "C")
                    {
                        query = "SELECT u.Tipper_No, t.Coal_Type, t.Date, t.Shift, vc.Total_Vehicle_Count AS Vehicle_Count, COUNT(DISTINCT u.Tipper_No) AS DistinctVehicleCount, FLOOR(t.No_Of_Trips / vc.Total_Vehicle_Count) AS TripsPerVehicle, " +
                            "ROUND(t.No_Of_Trips % vc.Total_Vehicle_Count, 0) AS TripsPerVehicle1 FROM (SELECT Tipper_No, CASE WHEN TIME(Tipper_InTime) BETWEEN '06:00:00' AND '13:59:59' THEN 'A' WHEN TIME(Tipper_InTime) BETWEEN '14:00:00' AND " +
                            "'21:59:59' THEN 'B' WHEN TIME(Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59' OR TIME(Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59' THEN 'C' END AS Shift FROM ultratech_trip_details WHERE (DATE(Tipper_InTime) = " +
                            "? AND TIME(Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59') OR (DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59')) u JOIN ultratech_target_trips t ON t.Date = " +
                            "? AND t.Shift = u.Shift JOIN (SELECT COUNT(DISTINCT Tipper_No) AS Total_Vehicle_Count FROM ultratech_trip_details WHERE (DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN '22:00:00' AND '23:59:59') OR " +
                            "(DATE(Tipper_InTime) = ? AND TIME(Tipper_InTime) BETWEEN '00:00:00' AND '05:59:59')AND Material IN ('Redmud', 'Flyash', 'Limestone', 'Bauxite', 'Laterite')) vc ON 1 = 1 WHERE t.Coal_Type LIKE '%" + material + "%' AND t.Shift = ? GROUP BY u.Tipper_No, t.Coal_Type, t.Shift, vc.Total_Vehicle_Count, t.No_Of_Trips;";

                        lParameter.Add("Date", date.ToString("yyyy-MM-dd"));
                        lParameter.Add("Date1", date.AddDays(1).ToString("yyyy-MM-dd"));
                        lParameter.Add("Date2", date.ToString("yyyy-MM-dd"));
                        lParameter.Add("Date3", date.ToString("yyyy-MM-dd"));
                        lParameter.Add("Date4", date.AddDays(1).ToString("yyyy-MM-dd"));
                        lParameter.Add("shift1", shift);
                    }

                    // Execute the query for each material and merge the results
                    DataSet dstripDetails = dbx.executeQuery(query, lParameter);
                    finalResults.Merge(dstripDetails);
                }
            }

            return finalResults;
        }
        public DataSet GetTargetTrips(string Shift, DateTime date, string targetRedmud, string targetFlyash, string targetLimestone, string targetBauxite, string targetLaterite)
        {
            string materials = "'Redmud', 'Flyash', 'Limestone', 'Bauxite', 'Laterite'";

            string query = "SELECT u.Coal_Type, u.Shift, u.Date, u.No_Of_Trips " +
                           "FROM ultratech_target_trips u " +
                           "WHERE u.Shift = ? AND u.Date = ? AND u.Coal_Type IN (" + materials + ");";

            var lParameter1 = new Dictionary<string, object>();

            lParameter1.Add("Shift", Shift);
            lParameter1.Add("Date1", date.ToString("yyyy-MM-dd"));
            DataSet dstripDetails1 = dbx.executeQuery(query, lParameter1);
            return dstripDetails1;

        }

