        {
            try
            {
                // Modified by Zoya on 11/06/2024  Check if the same details already exist in the database
                string query = "SELECT * FROM ultratech_target_trips t WHERE t.Loader_No = ? AND t.Coal_Type = ? AND t.Shift = ? AND t.Date = ? AND t.AccountId = ?;";

                var parameters = new Dictionary<string, object>();
                parameters.Add("Loader_No", Loader_No);
                parameters.Add("Yard", Yard);
                parameters.Add("Shift", Shift);
                parameters.Add("Date", Date.ToString("yyyy-MM-dd"));
                //parameters.Add("GroupId", GroupId);
                parameters.Add("AccountId", accountid);
                parameters.Add("Added_By", username);

                DataTable dt = dbx.executeQuery(query, parameters).Tables[0];

                if (dt.Rows.Count > 0)
                {
                    //Modified by Zoya on 11/06/2024 if details are entered for same trip return "Details already entered. Please edit the No. of Trips column if required.";
                    int id = Convert.ToInt32(dt.Rows[0]["ID"]);
                    int currentNoOfTrips = Convert.ToInt32(dt.Rows[0]["No_Of_Trips"]);
                    int updatedNoOfTrips = currentNoOfTrips + noOfTrips;
                    string updateQuery = "UPDATE `ultratech_target_trips` SET `No_Of_Trips` = ? WHERE `ID` = ? AND `Coal_Type` = ? AND `Loader_No` = ? AND `Shift` = ? AND `Date` = ? AND `AccountId` = ? AND `IsActive` = 1;";
