                    updateParameters.Add("Yard", Yard);
                    updateParameters.Add("Loader_No", Loader_No);
                    updateParameters.Add("Shift", Shift);
                    updateParameters.Add("Date", Date.ToString("yyyy-MM-dd"));
                    //updateParameters.Add("GroupId", GroupId);
                    updateParameters.Add("AccountId", accountid);
                    //updateParameters.Add("Added_By", username);

                    int result = dbx.executeNonQuery(updateQuery, updateParameters);

                    if (result > 0)
                        return "Details already exist. No.of trips has been updated.";
                    else
                        return "Failed to update.";
                }
                else
                {
                    // Insert the new details
                    string insertQuery = "INSERT INTO `ultratech_target_trips` (`Loader_No`,`Coal_Type`, `Shift`, `No_Of_Trips`, `Date`, `IsActive`, `Added_By`, `Added_On`, `GroupId`, `AccountId`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?);";

                    var insertParameters = new Dictionary<string, object>();
                    insertParameters.Add("Loader_No", Loader_No);
                    insertParameters.Add("Yard", Yard);
                    insertParameters.Add("Shift", Shift);
                    insertParameters.Add("No_Of_Trips", noOfTrips);
                    insertParameters.Add("Date", Date.ToString("yyyy-MM-dd"));
                    insertParameters.Add("IsActive", 1);
                    insertParameters.Add("Added_By", username);
                    insertParameters.Add("Added_On", formatDBDate(DateTime.Now));
                    insertParameters.Add("GroupId", GroupId);
                    insertParameters.Add("AccountId", accountid);

                    int res = dbx.executeNonQuery(insertQuery, insertParameters);

                    if (res > 0)
                        return "Success";
                    else
                        return "Failed";
                }
            }
            catch (Exception e)
            {
                return "Failed";
            }
        }

