                        insertParameters.Add("Actual_Linkage", Actual_Linkage);
                        insertParameters.Add("Target_US", Target_US);
                        insertParameters.Add("Actual_US", Actual_US);
                        insertParameters.Add("Target_Petcock", Target_Petcock);
                        insertParameters.Add("Actual_Petcock", Actual_Petcock);
                        insertParameters.Add("Target_Ghonsa", Target_Ghonsa);
                        insertParameters.Add("Actual_Ghonsa", Actual_Ghonsa);
                        insertParameters.Add("Other", Other);
                        insertParameters.Add("IdlingHours", IdlingHours);
                        insertParameters.Add("RunningHours", RunningHours);

                        int res = dbx.executeNonQuery(insertQuery, insertParameters);

                        /*if (res <= 0)
                            return "Failed to insert.";*/
                    }
                }

                //return "Success";
            }
            catch (Exception e)
            {
                return $"Failed: {e.Message}";
            }
            return "Success";
        }
