        public DataTable GetViolatedVehiclesCount(int month, int year, int groupid)
        {
            string query = "select count(distinct if(d.md>0,d.vehicleid,NULL)) as MD, " +
                        "count( distinct if(d.maxsp>0,d.vehicleid,NULL)) as OS, " +
                        "count(distinct if(d.cd>0,d.vehicleid,NULL)) as cd, " +
                        "count(distinct if(d.harshbraking_count >0,d.vehicleid,NULL)) as HB, " +
                        "count(distinct if(d.harshaccln_value>0,d.vehicleid,NULL)) as HA, " +
                        "count(distinct if(d.nd>0 && d.IsNightDrivingViol=1,d.vehicleid,NULL)) as nd " +
                        "from daywisevehviosummary d " +
                        "where month(date)=? and year(date)=?  and d.IsTrip=1 and d.VehicleId in (select vehicleid from vehiclesgroupsmap m where m.GroupId=?)";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("Month2", month);
            lParameter.Add("Year2", year);
            lParameter.Add("Groupid", groupid);
            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];
            return dt;
        }
        public DataTable GetVehMaintanceData(string user)
