            {
                query = "select * from `vehiclecategory` v order by v.UpdatedDate desc limit 10;";
                dt = dbx.executeQuery(query);
            }
            else
            {
                query = "select h.vehicleId,h.Hstarttime AS fromdate, h.Hendtime AS todate FROM holidayconfig h WHERE h.isHoliDayOver=0 order by h.Hstarttime desc limit 10;";
