        public DataTable DeleteStoreVehicleViolation(string vehicleId, string type, DateTime timestamp)
        {
            string query = string.Empty;
            query = "insert into storevehicleviolations_validation(vehicleid,TYPE,TIMESTAMP,duration,remarks,location,drivername,latitude,longitude,samples,maxsamplesval) SELECT vehicleid, type, timestamp, duration, remarks, location, drivername, latitude, longitude, samples, maxsamplesval FROM storevehicleviolations s WHERE s.vehicleId= ? AND s.type= ? AND s.timestamp=? ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("vehicleId", vehicleId);
            lParameter.Add("type", type);
            lParameter.Add("timestamp", formatDBDate(timestamp));
            dbx.executeNonQuery(query, lParameter);

            query = "DELETE FROM storevehicleviolations WHERE vehicleId = ? AND type = ? AND timestamp = ? ";
            var lParameter1 = new Dictionary<string, object>();
            lParameter1.Add("vehicleId", vehicleId);
            lParameter1.Add("type", type);
            lParameter1.Add("timestamp", formatDBDate(timestamp));
            dbx.executeNonQuery(query, lParameter1);
            // if no data is found in the first table, select data from the backup table 
            query = "SELECT * FROM storevehicleviolations_bak WHERE vehicleId = ? AND type = ? AND timestamp = ? ";
            var lParameter2 = new Dictionary<string, object>();
            lParameter2.Add("vehicleId", vehicleId);
            lParameter2.Add("type", type);
            lParameter2.Add("timestamp", formatDBDate(timestamp));
            DataTable Getstorevehicleviolations_bak = dbx.executeQuery(query.ToString(), lParameter2).Tables[0];

            if (Getstorevehicleviolations_bak.Rows.Count > 0)
            {
                query = "DELETE FROM storevehicleviolations_bak WHERE vehicleId = ? AND type = ? AND timestamp = ? ";
                var lParameter3 = new Dictionary<string, object>();
                lParameter3.Add("vehicleId", vehicleId);
                lParameter3.Add("type", type);
                lParameter3.Add("timestamp", formatDBDate(timestamp));
                dbx.executeNonQuery(query, lParameter3);
            }
            return Getstorevehicleviolations_bak;
        }
        public DataTable GetAsgVehiclesInfo(string SessionId)
        {

            DataTable dtNrInterval = getNRconfigurationByAccount(SessionId);//For the Not reporting threshold
            int NRInterval = 72;
            int BatteryUnknownConfig = 15;
            if (dtNrInterval != null && dtNrInterval.Rows.Count > 0)
            {
                if (!string.IsNullOrEmpty(dtNrInterval.Rows[0]["NRInterval"].ToString()))
                {
                    NRInterval = Convert.ToInt32(dtNrInterval.Rows[0]["NRInterval"]);
                    BatteryUnknownConfig = Convert.ToInt32(dtNrInterval.Rows[0]["DistanceCorrection"]);

                }
            }
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query.Append("Select distinct p.truckId,t.positiontxt,b.BranchID, DATE_FORMAT(p.timestamp, '%d/%m/%Y') AS UpdateDate, DATE_FORMAT(p.timestamp, '%r') AS UpdateTime,p.speed,v.VehicleInfo, ");
            //query.Append("p.Stop,p.direction,'' as trip_direction,CASE WHEN p.timestamp < NOW() - INTERVAL ? DAY THEN 0  ELSE p.BV END AS BV,p.fuellevel,p.gvinp1,p.panic,p.latitude,p.longitude,p.direction,v.IconType,DATE_FORMAT(p.timestamp, '%d %b %y') AS UpdateDate1, ");//if device updated was more than 15 days from cuurent datetime then battery will shown as UNKNOWN
            query.Append("p.Stop,p.direction,'' as trip_direction,CASE WHEN p.timestamp < (NOW() - INTERVAL ? DAY) + INTERVAL 5 HOUR + INTERVAL 30 MINUTE THEN 0  ELSE p.BV END AS BV,p.fuellevel,p.gvinp1,p.panic,p.latitude,p.longitude,p.direction,v.IconType,DATE_FORMAT(p.timestamp, '%d %b %y') AS UpdateDate1, ");//if device updated was more than 15 days from cuurent datetime then battery will shown as UNKNOWN
            query.Append("CASE WHEN p.panic = 1 THEN 'Priority Theft Alert' WHEN p.panic = 2 THEN 'Theft Alert' ");
            query.Append("WHEN p.timestamp <= (NOW() - INTERVAL ? HOUR) + INTERVAL 5 HOUR + INTERVAL 30 MINUTE THEN 'Not Reporting' ELSE 'Reporting' END AS Remarks ");//calculating remarks
            query.Append("from lastupdtdata p ");
            query.Append("left JOIN vehiclepositiontxt t on p.truckid=t.truckid ");//to fetch location
            query.Append("join vehicles v on v.vehicleId = p.truckid ");
            query.Append("join accounts a on v.AccountID = a.ID ");
            query.Append("join vehiclesgroupsmap g on v.VehicleId = g.VehicleId ");//this join is for to fetch all the active assets in the login
            query.Append("join users u on a.ID = u.AccountID ");
            query.Append("join sessions s on u.login = s.login ");
            //query.Append("LEFT join devicebranchallocation d ON d.UID = p.truckid ");
            //query.Append("LEFT join branchdata b ON b.BranchID = d.BranchID ");
            query.Append("LEFT JOIN (SELECT d.UID, MIN(d.BranchID) AS BranchID FROM devicebranchallocation d  ");//For fetching branchId 
            query.Append("GROUP BY d.UID ) d ON d.UID = p.truckid LEFT JOIN branchdata b ON b.BranchID = d.BranchID ");//This is for is there is two and more entries present in devicebranchallocation table then by this line it will  take only one row
            query.Append("where s.SessionID =? AND g.GroupId=? ");
            query.Append("ORDER BY FIELD( CASE WHEN p.panic = 1 THEN 'Priority Theft Alert' WHEN p.panic = 2 THEN 'Theft Alert' ");
            query.Append("WHEN p.timestamp <= (NOW() - INTERVAL ? HOUR) + INTERVAL 5 HOUR + INTERVAL 30 MINUTE THEN 'Not Reporting' ELSE 'Reporting' END,'Priority Theft Alert',  ");//this is for ordering of the data based on the remarks column
            query.Append("'Theft Alert', 'Not Reporting', 'Reporting') ");
            lParameter.Add("BatteryUnknownConfig", BatteryUnknownConfig);
            lParameter.Add("NRInterval", NRInterval);
            lParameter.Add("SessionId", SessionId);
            lParameter.Add("GroupId", getGroupId(SessionId));
            lParameter.Add("NRInterval1", NRInterval);
            DataTable lastPostable = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            return lastPostable;
        }
        public DataTable GetRailDevicesInfo(string SessionId)
        {
            DataTable dtNrInterval = getNRconfigurationByAccount(SessionId);//For the Not reporting threshold
            int NRInterval = 12;
            int BatteryUnknownConfig = 15;
            if (dtNrInterval != null && dtNrInterval.Rows.Count > 0)
            {
                if (!string.IsNullOrEmpty(dtNrInterval.Rows[0]["NRInterval"].ToString()))
                {
                    NRInterval = Convert.ToInt32(dtNrInterval.Rows[0]["NRInterval"]);
                    BatteryUnknownConfig = Convert.ToInt32(dtNrInterval.Rows[0]["DistanceCorrection"]);
                }
            }
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            query.Append("SELECT DISTINCT p.truckId,t.positiontxt, DATE_FORMAT(p.timestamp, '%d/%m/%Y') AS UpdateDate,DATE_FORMAT(p.timestamp, '%r') AS UpdateTime, ");
            query.Append("CASE WHEN p.speed < 8 AND (p.Stop = 0 OR p.Stop = 1) THEN 0 ELSE p.speed END AS speed, ");
            query.Append("CASE WHEN x.Category IS NOT NULL THEN CONCAT('(', x.Category, ') ', v.VehicleInfo) ELSE v.VehicleInfo END AS VehicleInfo,p.Stop,p.direction,'' AS trip_direction,CASE WHEN p.timestamp < (NOW() - INTERVAL ? DAY) + INTERVAL 5 HOUR + INTERVAL 30 MINUTE THEN 0  ");
            query.Append("ELSE p.BV END AS BV,p.fuellevel,p.gvinp1,p.panic, p.latitude,p.longitude,p.direction,v.IconType,DATE_FORMAT(p.timestamp, '%d %b %y') AS UpdateDate1, ");
            query.Append("CASE WHEN p.timestamp <= (NOW() - INTERVAL ? HOUR) + INTERVAL 5 HOUR + INTERVAL 30 MINUTE THEN 'NR,' WHEN p.speed > 8 THEN 'VM,' ");
            query.Append("WHEN p.speed < 8 AND (p.Stop = 0 OR p.Stop = 1) THEN 'VH,' ELSE 'VM,' END AS Remarks FROM lastupdtdata p ");
            query.Append("LEFT JOIN vehiclepositiontxt t ON p.truckid = t.truckid JOIN vehicles v ON v.vehicleId = p.truckid left JOIN vehiclecategory x ON v.VehicleID=x.VehicleId ");
            query.Append("JOIN accounts a ON v.AccountID = a.ID JOIN vehiclesgroupsmap g ON v.VehicleId = g.VehicleId ");
            query.Append("JOIN users u ON a.ID = u.AccountID JOIN sessions s ON u.login = s.login ");
            query.Append("WHERE s.SessionID = ? AND g.GroupId = ? ORDER BY p.truckId; ");
            lParameter.Add("BatteryUnknownConfig", BatteryUnknownConfig);
            lParameter.Add("NRInterval", NRInterval);
            lParameter.Add("SessionId", SessionId);
            lParameter.Add("GroupId", getGroupId(SessionId));
            DataTable lastPostable = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            return lastPostable;
        }
        public DataTable GetShowPositinsByAsset(string SessionId,string Vehicles)
        {
            StringBuilder query = new StringBuilder();
            var lParameter = new Dictionary<string, object>();
            if (!string.IsNullOrEmpty(Vehicles))
            {
                string[] vehls = Vehicles.Replace("'", "").Replace("\"", "").Split(',');
                string inparam = string.Empty;
                for (int i = 0; i < vehls.Length; i++)
                {
                    if (i == 0)
                        inparam += ("?");
                    else
                        inparam += (", ?");
                }
                DataTable dtNrInterval = getNRconfigurationByAccount(SessionId);//For the Not reporting threshold
                int NRInterval = 72;
                int BatteryUnknownConfig = 15;
                if (dtNrInterval != null && dtNrInterval.Rows.Count > 0)
                {
                    if (!string.IsNullOrEmpty(dtNrInterval.Rows[0]["NRInterval"].ToString()))
                    {
                        NRInterval = Convert.ToInt32(dtNrInterval.Rows[0]["NRInterval"]);
                        BatteryUnknownConfig = Convert.ToInt32(dtNrInterval.Rows[0]["DistanceCorrection"]);

                    }
                }                
                query.Append("Select distinct p.truckId,CAST(DATE_FORMAT(p.timestamp, '%d %b %y, %r') as CHAR) as times,p.latitude,p.longitude,p.speed,UNIX_TIMESTAMP(p.timestamp) as unix,v.VehicleInfo,t.positiontxt,b.BranchID, DATE_FORMAT(p.timestamp, '%d/%m/%Y') AS UpdateDate, DATE_FORMAT(p.timestamp, '%r') AS UpdateTime, ");
                //query.Append("p.Stop,p.direction,'' as trip_direction,CASE WHEN p.timestamp < NOW() - INTERVAL ? DAY THEN 0  ELSE p.BV END AS BV,p.fuellevel,p.gvinp1,p.panic,p.latitude,p.longitude,p.direction,v.IconType,DATE_FORMAT(p.timestamp, '%d %b %y') AS UpdateDate1, ");//if device updated was more than 15 days from cuurent datetime then battery will shown as UNKNOWN
                query.Append("p.Stop,p.direction,'' as trip_direction,CASE WHEN p.timestamp < (NOW() - INTERVAL ? DAY) + INTERVAL 5 HOUR + INTERVAL 30 MINUTE THEN 0  ELSE p.BV END AS BV,p.fuellevel,p.gvinp1,p.panic,p.direction,v.IconType,DATE_FORMAT(p.timestamp, '%d %b %y') AS UpdateDate1, ");//if device updated was more than 15 days from cuurent datetime then battery will shown as UNKNOWN
                query.Append("CASE WHEN p.panic = 1 THEN 'Priority Theft Alert' WHEN p.panic = 2 THEN 'Theft Alert' ");
                query.Append("WHEN p.timestamp <= (NOW() - INTERVAL ? HOUR) + INTERVAL 5 HOUR + INTERVAL 30 MINUTE THEN 'Not Reporting' ELSE 'Reporting' END AS Remarks ");//calculating remarks
                query.Append("from lastupdtdata p ");
                query.Append("left JOIN vehiclepositiontxt t on p.truckid=t.truckid ");//to fetch location
                query.Append("join vehicles v on v.vehicleId = p.truckid ");
                query.Append("join accounts a on v.AccountID = a.ID ");
                query.Append("join vehiclesgroupsmap g on v.VehicleId = g.VehicleId ");//this join is for to fetch all the active assets in the login
                query.Append("join users u on a.ID = u.AccountID ");
                query.Append("join sessions s on u.login = s.login ");
                //query.Append("LEFT join devicebranchallocation d ON d.UID = p.truckid ");
                //query.Append("LEFT join branchdata b ON b.BranchID = d.BranchID ");
                query.Append("LEFT JOIN (SELECT d.UID, MIN(d.BranchID) AS BranchID FROM devicebranchallocation d  ");//For fetching branchId 
                query.Append("GROUP BY d.UID ) d ON d.UID = p.truckid LEFT JOIN branchdata b ON b.BranchID = d.BranchID ");//This is for is there is two and more entries present in devicebranchallocation table then by this line it will  take only one row
                //query.Append("where s.SessionID =? AND g.GroupId=? ");
                query.Append("where p.TruckId in (" + inparam + ") AND s.SessionID =? and g.GroupId=? ");
                query.Append("ORDER BY p.TruckId ");
                lParameter.Add("BatteryUnknownConfig", BatteryUnknownConfig);
                lParameter.Add("NRInterval", NRInterval);
                //lParameter.Add("SessionId", SessionId);
                for (int i = 0; i < vehls.Length; i++)
                {
                    lParameter.Add("vehicle1_" + i, vehls[i]);
                }
                lParameter.Add("SessionId", SessionId);
                lParameter.Add("GroupId", getGroupId(SessionId));
            }
                DataTable lastPostable = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            
            return lastPostable;
        }
