		public DataTable GetDailyChecklistReport(string fromDateStr, string toDateStr, int groupid)
		{
			string query = "WITH DriverDailyMaxSubmissionTime AS(SELECT DriverId,DATE(SubmissionDateTime) AS SubmissionDate,MAX(SubmissionDateTime) AS LatestSubmissionDateTime FROM DailyChecklistHeader	WHERE SubmissionDateTime BETWEEN ? AND ? " +
			"GROUP BY DriverId, DATE(SubmissionDateTime)),LatestChecklist AS( SELECT h.SubmissionID 	FROM DailyChecklistHeader h INNER JOIN DriverDailyMaxSubmissionTime dmax ON h.DriverId = dmax.DriverId AND " +
			"h.SubmissionDateTime = dmax.LatestSubmissionDateTime ),ChecklistData AS( SELECT d.SubmissionID, d.ItemCode,	d.ItemValue	FROM DailyChecklistDetail d WHERE d.SubmissionID IN (SELECT SubmissionID FROM LatestChecklist) )," +
			"PivotedChecklist AS(SELECT	SubmissionID," +
	   "MAX(CASE WHEN ItemCode = '1a' THEN ItemValue END) AS `1a`, MAX(CASE WHEN ItemCode = '1b' THEN ItemValue END) AS `1b`, MAX(CASE WHEN ItemCode = '1c' THEN ItemValue END) AS `1c`, MAX(CASE WHEN ItemCode = '1d' THEN ItemValue END) AS `1d`," +
	   "MAX(CASE WHEN ItemCode = '1e' THEN ItemValue END) AS `1e`, MAX(CASE WHEN ItemCode = '2e' THEN ItemValue END) AS `2e`, MAX(CASE WHEN ItemCode = '3e' THEN ItemValue END) AS `3e`, MAX(CASE WHEN ItemCode = '4e' THEN ItemValue END) AS `4e`," +
	   "MAX(CASE WHEN ItemCode = '5e' THEN ItemValue END) AS `5e`, MAX(CASE WHEN ItemCode = '1f' THEN ItemValue END) AS `1f`, MAX(CASE WHEN ItemCode = '2f' THEN ItemValue END) AS `2f`, MAX(CASE WHEN ItemCode = '3f' THEN ItemValue END) AS `3f`," +
	   "MAX(CASE WHEN ItemCode = '4f' THEN ItemValue END) AS `4f`, MAX(CASE WHEN ItemCode = '1g' THEN ItemValue END) AS `1g`, MAX(CASE WHEN ItemCode = '1h' THEN ItemValue END) AS `1h`, MAX(CASE WHEN ItemCode = '2h' THEN ItemValue END) AS `2h`," +
	   "MAX(CASE WHEN ItemCode = '3h' THEN ItemValue END) AS `3h`, MAX(CASE WHEN ItemCode = '4h' THEN ItemValue END) AS `4h`, MAX(CASE WHEN ItemCode = '5h' THEN ItemValue END) AS `5h`, MAX(CASE WHEN ItemCode = '1i' THEN ItemValue END) AS `1i`," +
	   "MAX(CASE WHEN ItemCode = '2i' THEN ItemValue END) AS `2i`, MAX(CASE WHEN ItemCode = '1j' THEN ItemValue END) AS `1j`, MAX(CASE WHEN ItemCode = '2j' THEN ItemValue END) AS `2j`, MAX(CASE WHEN ItemCode = '3j' THEN ItemValue END) AS `3j`," +
	   "MAX(CASE WHEN ItemCode = '1k' THEN ItemValue END) AS `1k`, MAX(CASE WHEN ItemCode = '2k' THEN ItemValue END) AS `2k`, MAX(CASE WHEN ItemCode = '3k' THEN ItemValue END) AS `3k`, MAX(CASE WHEN ItemCode = '1l' THEN ItemValue END) AS `1l`" +
	   "FROM ChecklistData	GROUP BY SubmissionID )SELECT h.SubmissionID, h.VehicleID, h.DriverName, DATE_FORMAT(h.SubmissionDateTime, '%d/%m/%Y %H:%i:%s') AS SubmissionDateTime,t.Name AS Transporter, pc.*, MAX(w.startTime) AS 'Start Time' ,MAX(w.endTime) AS 'End Time'," +
	   "CASE WHEN MAX(w.startTime) IS NULL AND MAX(w.endTime) IS NULL THEN '' WHEN MAX(w.endTime) IS NULL THEN 'Driver Not Ended endTime' WHEN TIMEDIFF(MAX(w.endTime), MAX(w.startTime)) > '12:00:00' THEN 'Exceeded more than 12 hours' ELSE CONCAT(HOUR(TIMEDIFF(MAX(w.endTime)," +
	   " MAX(w.startTime))), ' hours ', MINUTE(TIMEDIFF(MAX(w.endTime), MAX(w.startTime) )), ' minutes ',SECOND(TIMEDIFF(MAX(w.endTime), MAX(w.startTime))), ' seconds')  END AS 'Total WorkTime' FROM	DailyChecklistHeader h INNER JOIN LatestChecklist lc ON h.SubmissionID = lc.SubmissionID " +
	   "LEFT JOIN PivotedChecklist pc ON pc.SubmissionID = h.SubmissionID LEFT JOIN driverinfo di ON h.DriverId = di.DriverId LEFT JOIN transporterinfo t ON t.TransporterId = di.Transporter LEFT JOIN workdonedata w ON w.DriverId = di.DriverId AND DATE(w.startTime) = DATE(h.SubmissionDateTime) " +
	   "AND w.startTime BETWEEN ? AND ? INNER JOIN vehiclesgroupsmap vi ON vi.VehicleId = h.VehicleID WHERE vi.GroupId =? GROUP BY h.SubmissionID, h.VehicleID, h.DriverName, h.SubmissionDateTime, t.Name ORDER BY h.SubmissionDateTime DESC; ";

			var lParameter = new Dictionary<string, object>();
			lParameter.Add("fromDate", formatDBDate(Convert.ToDateTime(fromDateStr)));
			lParameter.Add("toDate", formatDBDate(Convert.ToDateTime(toDateStr)));
			lParameter.Add("fromDate1", formatDBDate(Convert.ToDateTime(fromDateStr)));
			lParameter.Add("toDate1", formatDBDate(Convert.ToDateTime(toDateStr)));
			lParameter.Add("groupId", groupid);

			DataTable GetDailyChecklistReport = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
			return GetDailyChecklistReport;
		}
