		// --- below insert code added to store the daywise Violation summary count data for nokia customer ----- added by sahana on 19-08-2025
		public int InsertNokiaDayWiseSummaryData(int totalVehicles, int vehiclesOnRoad, int totalTrips, string totalTagInTagOut, string haltedVehicles, string notReachableVehicles, int mdViolation, int cdViolation, int osViolation, int hbViolation, int haViolation, int ndViolation, string circleName, string ctName, int istrip = 0)
		{
			try
			{
				// Get current UTC time adjusted for local timezone
				DateTime now = DateTime.UtcNow.AddSeconds(GetTimeZoneDiff());
				string formatDate = now.AddDays(-1).ToString("yyyy-MM-dd"); ; // e.g., "yyyy-MM-dd HH:mm:ss"				 

				// Prepare SQL insert query
				string query = @"INSERT INTO `nokiadaywisesummary`   (`Istrip`, `CircleName`, `CTName`, `Total_Number_of_Vehicles`, `Vehicles_on_road`, `Total_Number_of_Trips`, `Total_Number_of_Tagin_Tagout`,`Halted_Vehicles`, `NotReachable_Vehicles`, `MD_violation`, `CD_violation`,
                              `OS_violation`,  `HB_violation`, `HA_violation`, `ND_violation`, `Date`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

				// Create parameter dictionary
				var lParameter = new Dictionary<string, object>
				{
					{ "Istrip", istrip },
					{ "CircleName", string.IsNullOrEmpty(circleName) ? null : circleName },
					{ "CTName", string.IsNullOrEmpty(ctName) ? null : ctName },
					{ "Total_Number_of_Vehicles", totalVehicles },
					{ "Vehicles_on_road", vehiclesOnRoad },
					{ "Total_Number_of_Trips", totalTrips },
					{ "Total_Number_of_Tagin_Tagout", string.IsNullOrEmpty(totalTagInTagOut) ? null : totalTagInTagOut },
					{ "Halted_Vehicles", string.IsNullOrEmpty(haltedVehicles) ? null : haltedVehicles },
					{ "NotReachable_Vehicles", string.IsNullOrEmpty(notReachableVehicles) ? null : notReachableVehicles },
					{ "MD_violation", mdViolation },
					{ "CD_violation", cdViolation },
					{ "OS_violation", osViolation },
					{ "HB_violation", hbViolation },
					{ "HA_violation", haViolation },
					{ "ND_violation", ndViolation },
					{ "Date", formatDate }
				};

				// Execute insert query
				int res = dbx.executeNonQuery(query, lParameter);

				return res;
			}
			catch (Exception ex)
			{
				// Optional: log error (ex.Message) for debugging
				return 0;
			}
		}
