        public void LogVettingNotificationSent(string VehicleID, string VettingDate)
        {
            try
            {
                string query = "SELECT * FROM VettingNotificationsSent WHERE VehicleId = ?";
                var lParameter = new Dictionary<string, object>();
                lParameter.Add("VehicleId", VehicleID);
                DataTable dtGetVehicle = dbx.executeQuery(query, lParameter).Tables[0];
                int exists = CheckVettingEmailNotification(VehicleID, VettingDate.ToString());
                if (dtGetVehicle != null && dtGetVehicle.Rows.Count > 0 && exists ==0)
                {
                    query = "UPDATE VettingNotificationsSent SET VettingDate = ?,SentOn=? WHERE VehicleId = ?";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("VettingDate", VettingDate);
                    lParameter.Add("SentOn", formatDBDate(DateTime.Now));
                    lParameter.Add("VehicleId1", VehicleID);                    

                    dbx.executeNonQuery(query, lParameter);
                }
                else if(exists == 0)
                {
                    query = "INSERT INTO `VettingNotificationsSent` (`VehicleId`, `VettingDate`,SentOn) VALUES (?, ?,?)";
                    lParameter = new Dictionary<string, object>();
                    lParameter.Add("VehicleId2", VehicleID);
                    lParameter.Add("VettingDate1", VettingDate);
                    lParameter.Add("SentOn1", formatDBDate(DateTime.Now));
                    dbx.executeNonQuery(query, lParameter).ToString();
                }
            }
            catch (Exception e)
            {
            }
        }
        public int Insert_atgl_cab_trip_details(CabTripDetailsRequest objcabTrip, string sessionId)
        {
            int res = 0;
            try
            {
                // Get actual vehicle number if exists in Sensel system
                //DataTable dtVehicleDetails = GetActualVehicleNo(objcabTrip.vehicle_number);
                //if (dtVehicleDetails != null && dtVehicleDetails.Rows.Count > 0)
                //{
                //    objcabTrip.vehicle_number = dtVehicleDetails.Rows[0]["VehicleId"].ToString();
                //}

                // Handle START_TRIP: Insert
                if (objcabTrip.trigger_point.Equals("START_TRIP", StringComparison.OrdinalIgnoreCase))
                {					 
					string insertQuery = "INSERT IGNORE INTO atgl_cab_trip_details (trip_id, vehicle_number, trip_start_latitude, trip_start_longitude, trip_start_timestamp, trigger_point,gps_tracking_url, created_at)" +
						"             VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)";
					Dictionary<string, object> lParameter = new Dictionary<string, object>();
					lParameter.Add("trip_id", objcabTrip.trip_id);
					lParameter.Add("vehicle_number", objcabTrip.vehicle_number);
					lParameter.Add("trip_start_latitude", objcabTrip.trip_start_Latitude);
					lParameter.Add("trip_start_longitude", objcabTrip.trip_start_Longitude);
					lParameter.Add("trip_start_timestamp", objcabTrip.trip_start_timestamp);
					lParameter.Add("trigger_point", objcabTrip.trigger_point);
					lParameter.Add("gps_tracking_url", objcabTrip.gps_tracking_url); 
					res= dbx.executeNonQuery(insertQuery, lParameter); 
                }
                // Handle END_TRIP: Update
                else if (objcabTrip.trigger_point.Equals("END_TRIP", StringComparison.OrdinalIgnoreCase))
                {
                    string updateQuery = @"UPDATE atgl_cab_trip_details SET 
                    trip_end_latitude = ?, 
                    trip_end_longitude = ?, 
                    trip_end_timestamp = ?, 
                    trip_distance_km = ?, 
                    trigger_point = ?,
                    updated_at = CURRENT_TIMESTAMP
                WHERE trip_id = ?";

                 Dictionary<string, object> updateParams = new Dictionary<string, object>
                    {
                        { "trip_end_latitude", objcabTrip.trip_end_Latitude },
                        { "trip_end_longitude", objcabTrip.trip_end_Longitude },
                        { "trip_end_timestamp", objcabTrip.trip_end_timestamp },
                        { "trip_distance_km", objcabTrip.trip_distance_km },
						{ "trigger_point", objcabTrip.trigger_point },
						{ "trip_id", objcabTrip.trip_id }
                    };

                    res = dbx.executeNonQuery(updateQuery, updateParams);
                }
            }
            catch (Exception ex)
            {
                STL_RecordErrorMessage("Insert_atgl_cab_trip_details: " + ex.ToString());
            }

            return res;
        }
