        public int GetRefreshRate(string sessionId)
        {
            int defaultRefreshRate = 60000;
            DataSet account = null;

            try
            {
                StringBuilder query = new StringBuilder();
                query.Append(@" SELECT accountgroups.refreshrate
            FROM sessions
            INNER JOIN usersgroupsmap 
                ON sessions.login = usersgroupsmap.login
            INNER JOIN accountgroups 
                ON usersgroupsmap.groupId = accountgroups.groupId
            WHERE sessions.SessionID = @sessionId
        ");

                var parameters = new Dictionary<string, object>
        {
            { "@sessionId", sessionId }
        };

                account = dbx.executeQuery(query.ToString(), parameters);

                if (account != null &&
                    account.Tables.Count > 0 &&
                    account.Tables[0].Rows.Count > 0 &&
                    account.Tables[0].Rows[0]["refreshrate"] != DBNull.Value)
                {
                    return Convert.ToInt32(account.Tables[0].Rows[0]["refreshrate"]);
                }

                return defaultRefreshRate;
            }
            catch
            {
                return defaultRefreshRate;
            }
            finally
            {
                //close();
            }
        }

