        public DataTable Getdedicatedlist(DateTime fromDate, DateTime toDate)
        {
            String query = "SELECT u.plant,COUNT(IFNULL(e.Action, w.Action)) AS Dedicated_Done,SUM(CASE WHEN IFNULL(e.Action, w.Action) = 'Block' " +
                "THEN 1 ELSE 0 END) AS Dedicated_Rejected FROM stl_workflow w JOIN stl_users u ON u.username = w.username " +
                "LEFT JOIN stl_editedworkflow e ON e.EditId = (SELECT MAX(a.EditId) FROM stl_editedworkflow a WHERE a.workflowid = w.workflowId) " +
                "WHERE w.AccountId = 14 AND w.workflowtype = '0' AND w.vehicletype = 'CONTRACT' AND w.datetime BETWEEN ? AND " +
                "? GROUP BY u.plant ORDER BY u.plant asc ";
            var lParameter = new Dictionary<string, object>();
            lParameter.Add("fromDate", fromDate);
            lParameter.Add("toDate", toDate);
            //lParameter.Add("EventDateTime", formatDBDate(Convert.ToDateTime(fromDateTime)));
            DataTable details = dbx.executeQuery(query, lParameter).Tables[0];
            return details;
        }

