        public DataTable GetTicketReport(string GlobalAccId)
        {
            string query = "SELECT b.bug_id as 'Ticket No',b.short_desc as 'Details of the Issue',TRIM(TRAILING ', ' FROM b.VehicleId) as 'Vehicle No',DATE_FORMAT(b.creation_ts, '%Y-%m-%d %H:%i:%s') as 'Raised On',b.CustomerName as 'Raised By Name',b.bug_status as 'Ticket Status',DATE_FORMAT(b.lastdiffed, '%Y-%m-%d %H:%i:%s') as 'Closed On',p.realname as 'Closed By Name'" +
            ",t.comments as 'Closer Comment',b.VehicleAvailablilityPlace as 'Service Location' FROM bugs b JOIN bugs_fulltext t ON b.bug_id=t.bug_id " +
            "JOIN profiles p on p.userid=b.assigned_to " +
            "WHERE b.GlobalAccId=? AND b.creation_ts > ? ";

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GlobalAccId", GlobalAccId);
            lParameter.Add("toDate", DateTime.Today.AddMonths(-1).ToString("yyyy-MM-dd"));

            DataTable GetTicketReport = dbx.executeQuery(query.ToString(), lParameter).Tables[0];
            return GetTicketReport;
        }
		public int InsertGeofenceTripDetails(string trip_no,string vehicle_no,	string vehicle_category,string trip_start_location,	double trip_start_latitude,	double trip_start_longitude,string trip_start_in_time,string trip_start_out_time,string trip_end_location,	double trip_end_latitude,double trip_end_longitude,	string trip_end_in_time,string trip_end_out_time,double distance_km,string time_duration,string running_time,
		string dest_detention_time,	string halt_hours,	string route_traveled,	double google_distance_km,	string event_timestamp)
		{
		 string query = @"INSERT IGNORE INTO `geofence_trip_details`
		 (`trip_no`, `vehicle_no`, `vehicle_category`, `trip_start_location`,
		 `trip_start_latitude`, `trip_start_longitude`, `trip_start_in_time`, `trip_start_out_time`,
		 `trip_end_location`, `trip_end_latitude`, `trip_end_longitude`, `trip_end_in_time`, 
		 `trip_end_out_time`, `distance_km`, `time_duration`, `running_time`, `dest_detention_time`,
		 `halt_hours`, `route_traveled`, `google_distance_km`, `event_timestamp`)
		 VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?);";

