		public int ATGLdeleteVehicleInPlantData(string vehiclesStr, string geofencesStr, string date)
		{
			string vehicles = "";
			string geofences = "";
			var lParameter = new Dictionary<string, object>();
			string[] str = vehiclesStr.Split(new string[] { "@&@" }, StringSplitOptions.None);
			for (int i = 0; i < str.Length; i++)
			{
				lParameter.Add("vehicle_" + i, str[i]);
				if (vehicles == "")
					vehicles = "?";
				else
					vehicles += ",?";
			}
			str = geofencesStr.Split(new string[] { "@&@" }, StringSplitOptions.None);
			for (int i = 0; i < str.Length; i++)
			{
				lParameter.Add("geofence_" + i, str[i]);
				if (geofences == "")
					geofences = "?";
				else
					geofences += ",?";
			}
			string query = "delete from vehicleinplant_new where vehicleid in (" + vehicles + ") and locationstr in (" + geofences + ") and date(intimestamp)=?";
			lParameter.Add("intimestamp", Convert.ToDateTime(date).ToString("yyyy-MM-dd"));
			return dbx.executeNonQuery(query, lParameter);
		}
		public int InsertNotReachableData(int groupid, String Date)
		{
			int res = 0;
			var lParameter = new Dictionary<string, object>();
			var InsertParameters = new Dictionary<string, object>();
			string Query = "SELECT DISTINCT vg.vehicleid,s.DeviceID,s.CT,DATE_FORMAT(CURDATE()-INTERVAL 1 DAY,'%Y-%m-%d %H:%i:%s') AS DATE,DATE_FORMAT(l.timestamp,'%Y-%m-%d %H:%i:%s') AS Lastupdate FROM vehiclesgroupsmap vg JOIN vehdriver_staticdata s" +
						  " ON REPLACE(vg.VehicleId,' ','')=s.Vehicle JOIN lastupdtdata l ON l.truckid=vg.VehicleId WHERE vg.groupid = ? AND vg.vehicleid NOT IN " +
						  "(SELECT DISTINCT d.vehicleid FROM daywisevehviosummary d  WHERE (d.groupid = ? OR d.vehicleid IN ( SELECT vehicleid  FROM vehiclesgroupsmap WHERE groupid = ?))" +
						  " AND d.date =? AND d.trip_starttime <> '0000-00-00 00:00:00' AND(d.startlatlng <> ''  OR d.endlatlng <> ''  OR d.nd_startlatlng <> '' OR d.nd_endlatlng <> ''" +
						  "  OR d.totalruntime > 0 OR d.Kms_driven > 0));";

			lParameter.Add("groupid", groupid);
			lParameter.Add("groupid1", groupid);
			lParameter.Add("groupid2", groupid);
			lParameter.Add("date", Date);
			DataTable dt = dbx.executeQuery(Query.ToString(), lParameter).Tables[0];
			foreach (DataRow row in dt.Rows)
			{
				string query = $@"
						INSERT IGNORE INTO `notreachablevehicles`
						(`UID`, `Vehicleid`, `Lastaccess`, `VerifiedBy`, `VerifiedDateTime`) VALUES (
						 '{row["DeviceID"]}', '{row["vehicleid"]}', '{row["Lastupdate"]}', '{row["CT"]}', '{row["DATE"]}'
						);";
				res = dbx.executeNonQuery(query);
			}
			return res;
		}
		public void ATGLwriteVehicleInPlantData(String vehicleId, String plantLoc, DateTime inTimeStamp, DateTime outTimeStamp, Boolean outTimeDone, string planttype = "0")
		{
			String query = String.Empty;
			var lParameter = new Dictionary<string, object>();
			String inTimeStampStr = formatDBDate(inTimeStamp);

			// Conditon to skip vehicles if already inside OR overlapping IN
			string checkQuery = "select outtimestamp from vehicleinplant_new where vehicleid=? AND locationstr = ? order by intimestamp desc LIMIT 1";
			var checkQueryParameter = new Dictionary<string, object>();
			checkQueryParameter.Add("vehicleid_check", vehicleId);
			checkQueryParameter.Add("locationstr_check", plantLoc);

			DataTable dt = dbx.executeQuery(checkQuery, checkQueryParameter).Tables[0];

			// 🔹 Apply skip logic ONLY for IN records
			if (outTimeDone == false && dt.Rows.Count > 0)
			{
				object lastOut = dt.Rows[0]["outtimestamp"];

				// Already inside → do NOT insert another IN
				if (lastOut == DBNull.Value)
				{
					return;
				}

				DateTime lastOutTime = Convert.ToDateTime(lastOut);

				// Overlapping or old data → ignore
				if (lastOutTime >= inTimeStamp)
				{
					return;
				}
			}

			byte bf = Convert.ToByte(outTimeDone);

			if (outTimeDone == false)
			{
				query = "insert into vehicleinplant_new(vehicleid,locationstr,intimestamp,planttype) values(?,?,?,?)";
				lParameter.Add("vehicleid", vehicleId);
				lParameter.Add("locationstr", plantLoc);
				lParameter.Add("intimestamp", inTimeStampStr);
				lParameter.Add("type", planttype);
			}
			else
			{
				String outTimeStampStr = formatDBDate(outTimeStamp);
				query = "insert into vehicleinplant_new(vehicleid,locationstr,intimestamp,outtimestamp,outtimedone,planttype) values(?,?,?,?,?,?)";
				lParameter.Clear();
				lParameter.Add("vehicleid", vehicleId);
				lParameter.Add("locationstr", plantLoc);
				lParameter.Add("intimestamp", inTimeStampStr);
				lParameter.Add("outtimestamp", outTimeStampStr);
				lParameter.Add("outtimedone", bf);
				lParameter.Add("type", planttype);
			}

			dbx.executeNonQuery(query, lParameter);
		}
