		public DataSet GetDriverAppNotifications(string MobileNo)
		{
			DateTime date = System.DateTime.Now;

			StringBuilder Query = new StringBuilder();
			Query.Append("select dn.DriverId,dn.Subject,dn.Info,dn.Date,0 as count,dn.Isnotified,dn.Priority from drivernotification dn inner join driverinfo di " +
						   "on dn.Driverid=di.DriverId " +
						   "where dn.Isnotified<>1 and di.MobileNo= ? order by dn.Date desc limit 500");
			var lParameter = new Dictionary<string, object>();
			lParameter.Add("MobileNo", MobileNo);
			DataSet result = dbx.executeQuery(Query.ToString(), lParameter);
			int newrows = result.Tables[0].Rows.Count;
			if (newrows < 10)
			{
				Query.Clear();
				Query.Append("select dn.DriverId,dn.Subject,dn.Info,dn.Date,0 as count,dn.Isnotified,dn.Priority from drivernotification dn inner join driverinfo di " +
						  "on dn.Driverid=di.DriverId " +
						  "where di.MobileNo= ? order by dn.Date desc limit 10");
				lParameter = new Dictionary<string, object>();
				lParameter.Add("MobileNo", MobileNo);
				result = dbx.executeQuery(Query.ToString(), lParameter);
			}
			if (result.Tables[0].Rows.Count > 0)
			{
				result.Tables[0].Rows[0][4] = newrows;
			}
			return result;
		}
