        public int EditAmazonPassengerInfo(string PsngrIds, string cirOrVeh,
                                  string SessionId, string AssgnedVehice,
                                  string Location, string RFID, int PanicFlag)
        {
            insertauditdata("Edit", "psngr_info", "PsngrId", PsngrIds);

            string query = "UPDATE psngr_info SET ";
            var lParameter = new Dictionary<string, object>();
            List<string> updates = new List<string>();


            if (!string.IsNullOrEmpty(cirOrVeh))
            {
                updates.Add("RegionId = ?");
                lParameter.Add("cirOrVeh", cirOrVeh);
            }

            if (!string.IsNullOrEmpty(AssgnedVehice))
            {
                updates.Add("AssignedVehicleId = ?");
                lParameter.Add("AssgnedVehice", AssgnedVehice);
            }

            if (!string.IsNullOrEmpty(Location))
            {
                updates.Add("HomeLatitude = ?");
                lParameter.Add("Location", Location);
            }

            if (!string.IsNullOrEmpty(RFID))
            {
                updates.Add("RFID = ?");
                lParameter.Add("RFID", RFID);
            }

            if (PanicFlag >= 0)
            {
                updates.Add("PanicFlag = ?");
                lParameter.Add("PanicFlag", PanicFlag);
            }

            if (updates.Count == 0)
                return 0;

            query += string.Join(",", updates);
            query += " WHERE PsngrId IN (" + PsngrIds + ")";

            int res = dbx.executeNonQuery(query, lParameter);
            return res;
        }
        public string InsertAmazonPassengerInfo(object myObject, string sessionId)
        {
            Type myType = myObject.GetType();
            System.Collections.Generic.IList<System.Reflection.PropertyInfo> props = new System.Collections.Generic.List<System.Reflection.PropertyInfo>(myType.GetProperties());
            string Name = Convert.ToString(myType.GetProperty("Name")?.GetValue(myObject, null));
            string MobileNo = Convert.ToString(myType.GetProperty("MobileNo")?.GetValue(myObject, null));
