        public DataTable GetPassengerDetails(string vehicleId, DateTime tripStart, DateTime tripEnd, int groupId)
        {           
            if (tripEnd == DateTime.MinValue)
            {
                tripEnd = DateTime.Now;
            }
            string Query = "SELECT p.PsngrName,t.VehicleId,r.RouteName,t.TagInTime,t.TagOutTime FROM psngr_info p JOIN psngr_tag t ON p.PsngrId = t.PsngrId" +
                " LEFT JOIN vehicleroute_mapping v ON t.VehicleId = v.VehicleId LEFT JOIN route r ON v.RouteId = r.RouteId WHERE t.TagInTime BETWEEN ? AND ?  AND t.VehicleId = ? ORDER BY t.TagInTime DESC";
            var lParameter = new Dictionary<string, object>();
            //lParameter.Add("groupid", groupid);
            lParameter.Add("tripStart", formatDBDate(tripStart));
            lParameter.Add("tripEnd", formatDBDate(tripEnd));
