            DataTable details = dbx.executeQuery(Query, lParameter).Tables[0];
            return details;
        }

        public DataTable GetJourneyPlannerdata(DateTime fromdate, DateTime todate, int groupid)
        {
            string Query = "SELECT DISTINCT v.id,v.VehicleID,d.Name AS 'DriverName', t.`Name` AS Transporter,v.LoadingPlaceName AS Loading_Location," +
                "i.Name AS 'Unloading_Location' ,DATE_FORMAT(v.DateTime, '%d-%m-%Y %h:%i:%s %p') as `DC_Creation`,DATE_FORMAT(vp.PlanCreatedAt + INTERVAL 5 HOUR + INTERVAL 30 MINUTE,'%d-%m-%Y %h:%i:%s %p') AS Journey_Planner_DateTime, " +
                "DATE_FORMAT(vp.ApprovedOn, '%d-%m-%Y %h:%i:%s %p') AS Transporter_Approval_DateTime FROM vehicledctrip v  JOIN customerdcassign c ON c.DCTripId = v.id JOIN driverinfo d ON d.AssignedVehicleId = v.VehicleID " +
                "JOIN customerinfo i ON i.customerId = c.CustomerId JOIN plantlogin p ON p.login = v.AddedBy JOIN plantgeolocations g ON g.customerid = p.customerid JOIN customerroute r ON r.customerid = i.CustomerCode " +
                "INNER JOIN transporterinfo t ON t.TransporterId = d.Transporter inner JOIN vehicledctrip_plan vp ON vp.DCTripId = v.id WHERE v.VehicleID IN(SELECT m.VehicleId FROM vehiclesgroupsmap m WHERE m.GroupId = ?) AND  " +
                "v.`DateTime` BETWEEN ? AND ? AND i.customerId IN (SELECT MIN(c1.CustomerId) FROM vehicledctrip v1 INNER JOIN customerdcassign c1 ON c1.DCTripId = v1.id WHERE v1.VehicleID = v.VehicleID " +
                "GROUP BY v1.id ORDER BY v1.DateTime DESC) GROUP BY vp.PlanId ORDER BY v.DateTime DESC;";
            var lParameter = new Dictionary<string, object>();
            //lParameter.Add("groupid", groupid);
            lParameter.Add("groupid", groupid);
            lParameter.Add("fromdate", formatDBDate(fromdate));
            lParameter.Add("todate", formatDBDate(todate));
            DataTable details = dbx.executeQuery(Query, lParameter).Tables[0];
            return details;
        }
