        public DataTable Get_DashboardviolationSDB(string fromdate, string todate, int groupid, string group, string viotype, string time)
        {
            string where = "";
            if (time == "Day")
            {
                where = " and hour(s.timestamp) < 20 and hour(s.timestamp) >= 8 ";
            }
            else if (time == "Night")
            {
                where = " and (hour(s.timestamp) >= 20 or hour(s.timestamp) < 8) ";
            }

            string query = "SELECT concat(" + group + ") AS date, COUNT(*) AS vcount, (COUNT(DISTINCT s.vehicleId)) / COUNT(DISTINCT s.driverName) AS percentage" +
                           " FROM storevehicleviolations s JOIN vehiclesgroupsmap m ON s.vehicleId = m.vehicleid " +
                           " WHERE m.GroupId = ? AND s.timestamp BETWEEN ? AND ? AND s.type = ?" + where +
                           " GROUP BY " + group;

            var lParameter = new Dictionary<string, object>();
            lParameter.Add("GroupId", groupid);
            lParameter.Add("from", fromdate);
            lParameter.Add("to", todate);
            lParameter.Add("viotype", viotype);

            return dbx.executeQuery(query, lParameter).Tables[0];
        }

        public DataTable Get_Allviolation_SelecteddataSDB(string date, string violationtype, int groupid, string group, string fromdate, string todate, string time)
        {
            DateTime parsedDate;
            string[] formats = { "dd/MM/yyyy", "yyyy-MM-dd", "yyyy-MM-dd HH:mm:ss", "yyyy-MM-ddTHH:mm:ss", "yyyy-MM-ddTHH:mm:ss.fffZ" };
            if (DateTime.TryParseExact(date, formats, CultureInfo.InvariantCulture, DateTimeStyles.None, out parsedDate))
            {
                date = parsedDate.ToString("yyyy-MM-dd");
            }
            string where = " WHERE d.vehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap m WHERE m.GroupId=" + groupid + ") " +
                           " AND d.timestamp >= '" + fromdate + "' AND d.timestamp <= '" + todate + "' ";

            // Date grouping
            if (group == "week")
            {
                //where += " AND WEEKOFYEAR(d.timestamp)=WEEKOFYEAR('" + date + "')";
                where += "AND DATE_FORMAT(STR_TO_DATE(CONCAT(YEARWEEK(d.timestamp,1), ' Monday'),'%X%V %W'),'%Y-%m-%d') ='" + date + "'";
            }
            //else if (group == "month")
            //{
            //    where += " AND MONTH(d.timestamp)=MONTH('" + date + "')";
            //}
            //else if (group == "year")
            //{
            //    where += " AND YEAR(d.timestamp)='" + date + "'";
            //}
            else if (group == "month")
            {
                DateTime monthDate;
                if (DateTime.TryParse(date, out monthDate))
                {
                    DateTime firstDay = new DateTime(monthDate.Year, monthDate.Month, 1);
                    DateTime nextMonth = firstDay.AddMonths(1);

                    where += " AND d.timestamp >= '" + firstDay.ToString("yyyy-MM-dd") + " 00:00:00'" +
                             " AND d.timestamp < '" + nextMonth.ToString("yyyy-MM-dd") + " 00:00:00'";
                }
            }
            else if (group == "year")
            {
                DateTime yearDate;
                if (DateTime.TryParse(date, out yearDate))
                {
                    where += " AND YEAR(d.timestamp) = " + yearDate.Year;
                }
            }
            else
            {
                where += " AND DATE(d.timestamp)='" + date + "'";
            }
            if (violationtype == "maxspeed" || violationtype == "OverSpeed")
                where += " AND d.type='OVERSPEEDING'";
            else if (violationtype == "HarshBrake")
                where += " AND d.type='HARSH BRAKING'";
            else if (violationtype == "Harsh Acceleration")
                where += " AND d.type='HIGH ACCELERATION'";
            else if (violationtype == "nd")
                where += " AND d.type='NIGHT DRIVING'";
            else if (violationtype == "Continuous Driving" | violationtype == "Continue Driving")
                where += " AND d.type='SHORT RUNTIME'";
            else if (violationtype == "md")
                where += " AND d.type='TOTAL RUNTIME'";

            // Day / Night filter (based on timestamp)
            if (time == "Day")
            {
                where += " AND HOUR(d.timestamp) >= 8 AND HOUR(d.timestamp) < 20 ";
            }
            else if (time == "Night")
            {
                where += " AND (HOUR(d.timestamp) >= 20 OR HOUR(d.timestamp) < 8) ";
            }

            string query = "SELECT  d.vehicleId AS VehicleId, d.drivername AS 'Driver Name',d.type AS 'Violation Type', DATE_FORMAT(d.timestamp, '%Y-%m-%d %H:%i:%s') AS 'Violation Time',d.Location,d.latitude,d.Longitude" +
                           " FROM storevehicleviolations d " + where + " ORDER BY d.timestamp DESC";

            return dbx.executeQuery(query).Tables[0];
        }
