        public DataTable Get_AllviolationdataSDB(string fromdate, string todate, string groupby, int groupid)
        {
            int accountid = GetAccountIdByGroupId(groupid);
            string originalGroupby = groupby;
            var lParameter = new Dictionary<string, object>();

            if (groupby == "date")
            {
                groupby = "DATE_FORMAT(s.timestamp, '%Y-%m-%d')";
            }
            else if (groupby == "YEARWEEK(s.timestamp,1)")
            {
                groupby = "DATE_FORMAT(STR_TO_DATE(CONCAT(YEARWEEK(s.timestamp,1), ' Monday'), '%X%V %W'),'%Y-%m-%d')";
            }
            else if (groupby == "DATE(s.timestamp)")
            {
                groupby = "DATE_FORMAT(DATE(s.timestamp), '%Y-%m-%d')";
            }

            // Using parameterized query for better performance and security
            string query = " SELECT (" + groupby + ") AS date, " +
                           " COUNT(CASE WHEN s.type = 'OVERSPEEDING' THEN 1 END) AS overspeed_count, " +
                           " COUNT(CASE WHEN s.type = 'SHORT RUNTIME' THEN 1 END) AS cd_count, " +
                           " COUNT(CASE WHEN s.type LIKE '%TotalRun%' THEN 1 END) AS md_count, " +
                           " COUNT(CASE WHEN s.type = 'NIGHT DRIVING' THEN 1 END) AS nd_count, " +
                           " COUNT(CASE WHEN s.type = 'HARSH BRAKING' THEN 1 END) AS hb_count, " +
                           " COUNT(CASE WHEN s.type = 'HIGH ACCELERATION' THEN 1 END) AS ha_count, " +
                           " COUNT(CASE WHEN s.type LIKE '%TotalRun%' THEN 1 END) AS tr_count " +
                           " FROM storevehicleviolations s " +
                           " JOIN vehiclesgroupsmap vg ON s.vehicleId = vg.vehicleid " +
                           " WHERE vg.GroupId = ? AND s.timestamp BETWEEN ? AND ? " +
                           " GROUP BY " + groupby + " ORDER BY date;";

            lParameter.Add("GroupId", groupid);
            lParameter.Add("fromdate", fromdate);
            lParameter.Add("todate", todate);

            DataTable dt = dbx.executeQuery(query, lParameter).Tables[0];

            // Optimized additional counts for 'daynight' grouping
            if (originalGroupby == "case when hour(s.timestamp) <  20 and hour(s.timestamp)>= 8 then 'DAY' else 'NIGHT' end" ||
                originalGroupby == "CASE WHEN HOUR(s.timestamp) BETWEEN 8 AND 19 THEN 'DAY' ELSE 'NIGHT' END")
            {
                // Ensure we have both DAY and NIGHT rows
                if (dt.Rows.Count < 2)
                {
                    bool hasDay = dt.AsEnumerable().Any(r => r.Field<string>("date") == "DAY");
                    bool hasNight = dt.AsEnumerable().Any(r => r.Field<string>("date") == "NIGHT");

                    if (!hasDay) { var dr = dt.NewRow(); dr[0] = "DAY"; for (int i = 1; i < dt.Columns.Count; i++) dr[i] = 0; dt.Rows.InsertAt(dr, 0); }
                    if (!hasNight) { var dr = dt.NewRow(); dr[0] = "NIGHT"; for (int i = 1; i < dt.Columns.Count; i++) dr[i] = 0; dt.Rows.Add(dr); }
                }

                dt.Columns.Add("crash_count", typeof(Int32));
                dt.Columns.Add("vehicles_count", typeof(Int32));
                dt.Columns.Add("install_count", typeof(Int32));
                dt.Columns.Add("psngr_install_count", typeof(Int32));

                // Consolidate crash counts into one query
                string crashQuery = "SELECT CASE WHEN HOUR(timestamp) < 20 THEN 'DAY' ELSE 'NIGHT' END as dn, COUNT(vehicleid) as count " +
                                    "FROM crash_events WHERE vehicleid IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?) " +
                                    "AND timestamp BETWEEN ? AND ? GROUP BY dn";
                var crashParams = new Dictionary<string, object> { { "GroupId", groupid }, { "from", fromdate }, { "to", todate } };
                DataTable crashDt = dbx.executeQuery(crashQuery, crashParams).Tables[0];

                // Consolidate vehicle and install counts
                string countQuery = @"
                    SELECT 'DAY' as dn, 
                        (SELECT COUNT(DISTINCT VehicleId) FROM vehiclesgroupsmap WHERE GroupId=?) as vcount,
                        (SELECT COUNT(DISTINCT IMEI) FROM taging t JOIN vehicleinfo v ON v.VehicleId=t.VehicleId WHERE v.VehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?)) as icount,
                        (SELECT COUNT(DISTINCT p.PsngrId) FROM psngr_info p JOIN psngr_tag pt ON pt.PsngrId=p.PsngrId WHERE p.Active=1 AND p.AccountId=? " + (groupid != 2801 ? "AND pt.VehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?)" : "") + @") as pcount
                    UNION ALL
                    SELECT 'NIGHT' as dn,
                        (SELECT COUNT(DISTINCT d.DriverId) FROM taging t JOIN vehicleinfo v ON v.VehicleId=t.VehicleId JOIN driverinfo d ON d.DriverId=t.DriverId WHERE t.TimeStamp BETWEEN ? AND ? AND v.VehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?)) as vcount,
                        (SELECT COUNT(DISTINCT d.DriverId) FROM taging t JOIN vehicleinfo v ON v.VehicleId=t.VehicleId JOIN driverinfo d ON d.DriverId=t.DriverId WHERE t.TimeStamp BETWEEN ? AND ? AND v.VehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?)) as icount,
                        (SELECT COUNT(DISTINCT p.PsngrId) FROM psngr_info p JOIN psngr_tag pt ON pt.PsngrId=p.PsngrId WHERE p.Active=1 AND p.AccountId=? AND pt.TagInTime BETWEEN ? AND ? " + (groupid != 2801 ? "AND pt.VehicleId IN (SELECT vehicleid FROM vehiclesgroupsmap WHERE GroupId=?)" : "") + @") as pcount";

                var countParams = new Dictionary<string, object>();
                countParams.Add("g1", groupid); countParams.Add("g2", groupid); countParams.Add("a1", accountid); if (groupid != 2801) countParams.Add("g3", groupid);
                countParams.Add("f1", fromdate); countParams.Add("t1", todate); countParams.Add("g4", groupid);
                countParams.Add("f2", fromdate); countParams.Add("t2", todate); countParams.Add("g5", groupid);
                countParams.Add("a2", accountid); countParams.Add("f3", fromdate); countParams.Add("t3", todate); if (groupid != 2801) countParams.Add("g6", groupid);

                DataTable countDt = dbx.executeQuery(countQuery, countParams).Tables[0];

                foreach (DataRow row in dt.Rows)
                {
                    string dn = row["date"].ToString();
                    var crashRow = crashDt.AsEnumerable().FirstOrDefault(r => r.Field<string>("dn") == dn);
                    row["crash_count"] = crashRow != null ? crashRow["count"] : 0;

                    var cntRow = countDt.AsEnumerable().FirstOrDefault(r => r.Field<string>("dn") == dn);
                    if (cntRow != null)
                    {
                        row["vehicles_count"] = cntRow["vcount"];
                        row["install_count"] = cntRow["icount"];
                        row["psngr_install_count"] = cntRow["pcount"];
                    }
                }
            }
            return dt;
        }
        public int InsertRakeWagonChangeLog(string rakeNo, string wagon, string username)
        {
            int result = 0;
            int AccID = GetAccountId(getSessionIdFromLogin(username));
            int GroupId = getGroupIdByLogin(username);
            //string username = getUserId(sessionid);
            // Step 1: Get existing record Id
            string getIdQuery = "SELECT Id, Wagon FROM rakewagon_change_log WHERE Wagon=? and AccountId=? ORDER BY Id DESC LIMIT 1";

            var param1 = new Dictionary<string, object>();
            param1.Add("Wagon", wagon);
            param1.Add("AccID", AccID);
            DataSet ds = dbx.executeQuery(getIdQuery, param1);
            DataTable dt = ds.Tables[0];

            if (dt != null && dt.Rows.Count > 0)
            {
                int id = Convert.ToInt32(dt.Rows[0]["Id"]);
                string Wagon = dt.Rows[0]["Wagon"].ToString();

                // Step 2: Update existing record ToDate
                string updateLogQuery = "UPDATE rakewagon_change_log SET ToDate=? WHERE Id=? AND Wagon=? and AccountId=?";

                var param2 = new Dictionary<string, object>();
                param2.Add("ToDate", formatDBDate(DateTime.Now));
                param2.Add("Id", id);
                param2.Add("Wagon", Wagon);
                param2.Add("AccID", AccID);

                dbx.executeNonQuery(updateLogQuery, param2);
            }

            // Step 3: Insert new log record
            string insertLogQuery = "INSERT INTO rakewagon_change_log (RakeNo, Wagon, FromDate, RequestedBy, AccountId, GroupId) VALUES (?, ?, ?, ?, ?, ?)";

            var param3 = new Dictionary<string, object>();
            param3.Add("RakeNo", rakeNo);
            param3.Add("Wagon", wagon);
            param3.Add("FromDate", formatDBDate(DateTime.Now));
            param3.Add("username", username);
            param3.Add("AccID", AccID);
            param3.Add("GroupId", GroupId);
            dbx.executeNonQuery(insertLogQuery, param3);

            // Step 4: Update rakewagonmapping table
            string deleteWagonQuery = "DELETE FROM rakewagonmapping r WHERE r.Wagon = ? and AccountId = ?";
            var param4 = new Dictionary<string, object>();
            param4.Add("Wagon", wagon);
            param4.Add("AccID", AccID);
            dbx.executeNonQuery(deleteWagonQuery, param4);

            if (rakeNo.Equals("Idle", StringComparison.OrdinalIgnoreCase) || string.IsNullOrEmpty(rakeNo))
            {
                return 1;
            }

            string updateMappingQuery = "INSERT INTO rakewagonmapping (RakeNo, Wagon, AccountId, GroupId) VALUES (?, ?, ?, ?) ";

            var param5 = new Dictionary<string, object>();
            param5.Add("RakeNo", rakeNo);
            param5.Add("Wagon", wagon);
            param5.Add("AccID", AccID);
            param5.Add("GroupId", GroupId);
            result = dbx.executeNonQuery(updateMappingQuery, param5);

            return result;
        }


        public DataTable GetRakeWagonMappingList(int accountid)
