        public int UpdateVehicleInfoCategory(string category, string vehicleid, string accountid)
        {
            try
            {
                // Get existing VehicleInfo
                string getQuery = "SELECT IFNULL(VehicleInfo,'') AS VehicleInfo FROM vehicles WHERE VehicleId=? AND AccountID=?";

                Dictionary<string, object> getParam = new Dictionary<string, object>();
                getParam.Add("p1", vehicleid);
                getParam.Add("p2", accountid);

                DataSet ds = dbx.executeQuery(getQuery, getParam);

                string existingVehicleInfo = "";

                if (ds != null &&
                    ds.Tables.Count > 0 &&
                    ds.Tables[0].Rows.Count > 0)
                {
                    existingVehicleInfo = ds.Tables[0].Rows[0]["VehicleInfo"].ToString();
                }

                // Remove old category if present at end
                if (existingVehicleInfo.Contains("(") && existingVehicleInfo.EndsWith(")"))
                {
                    int index = existingVehicleInfo.LastIndexOf("(");

                    if (index > 0)
                    {
                        existingVehicleInfo = existingVehicleInfo.Substring(0, index).Trim();
                    }
                }

                // Append new category
                // Append category only if available
                string updatedVehicleInfo = existingVehicleInfo;

                if (!string.IsNullOrWhiteSpace(category))
                {
                    updatedVehicleInfo = existingVehicleInfo + " (" + category.Trim() + ")";
                }

                // Update query
                string updateQuery = "UPDATE vehicles SET VehicleInfo=? WHERE VehicleId=? AND AccountID=?";

                Dictionary<string, object> updateParam = new Dictionary<string, object>();

                updateParam.Add("p1", updatedVehicleInfo);
                updateParam.Add("p2", vehicleid);
                updateParam.Add("p3", accountid);

                int res = dbx.executeNonQuery(updateQuery, updateParam);
                if (res > 0)
                {
                    string deleteQuery = "DELETE FROM vehiclecategory WHERE VehicleId=?";

                    Dictionary<string, object> deleteParam = new Dictionary<string, object>();

                    deleteParam.Add("p1", vehicleid);

                    dbx.executeNonQuery(deleteQuery, deleteParam);
                }
                return res;
            }
            catch (Exception ex)
            {
                Console.WriteLine("UpdateVehicleInfo Error : " + ex.Message);
                return 0;
            }
        }
