        public int AddAssetSitedetails(string assetId, string siteId, string username)
        {
            int result = 0;

            int AccID = GetAccountId(getSessionIdFromLogin(username));
            int GroupId = getGroupIdByLogin(username);


            // STEP 1: Check if record exists
            string checkQuery = "SELECT COUNT(*) FROM assetSiteIdMapping WHERE Asset=? AND AccountId=? AND GroupId=?";

            var checkParams = new Dictionary<string, object>();
            checkParams.Add("Asset", assetId);
            checkParams.Add("AccountId", AccID);
            checkParams.Add("GroupId", GroupId);

            DataSet ds = dbx.executeQuery(checkQuery, checkParams);

            int count = Convert.ToInt32(ds.Tables[0].Rows[0][0]);

            if (count > 0)
            {
                string updateQuery = "UPDATE assetSiteIdMapping SET SiteId=?, AddedBy=?, AddedOn=? WHERE Asset=? AND AccountId=? AND GroupId=?";

                var updateParams = new Dictionary<string, object>();
                updateParams.Add("SiteId", siteId);
                updateParams.Add("AddedBy", username);
                updateParams.Add("AddedOn", DateTime.Now);
                updateParams.Add("Asset", assetId);
                updateParams.Add("AccountId", AccID);
                updateParams.Add("GroupId", GroupId);

                result = dbx.executeNonQuery(updateQuery, updateParams);
            }
            else
            {
                // STEP 4: CASE 3 → INSERT NEW
                string insertQuery = "INSERT INTO assetSiteIdMapping (Asset, SiteId, AddedBy, AddedOn, GroupId, AccountId) VALUES (?, ?, ?, ?, ?, ?)";

                var insertParams = new Dictionary<string, object>();
                insertParams.Add("Asset", assetId);
                insertParams.Add("SiteId", siteId);
                insertParams.Add("AddedBy", username);
                insertParams.Add("AddedOn", DateTime.Now);
                insertParams.Add("GroupId", GroupId);
                insertParams.Add("AccountId", AccID);

                result = dbx.executeNonQuery(insertQuery, insertParams);
            }

            // STEP 5: ALWAYS INSERT INTO LOG TABLE
            string logQuery = "INSERT INTO assetSiteIdMapping_Log (Asset, SiteId, AddedBy, AddedOn, GroupId, AccountId) VALUES (?, ?, ?, ?, ?, ?)";

            var logParams = new Dictionary<string, object>();
            logParams.Add("Asset", assetId);
            logParams.Add("SiteId", siteId);
            logParams.Add("AddedBy", username);
            logParams.Add("AddedOn", DateTime.Now);
            logParams.Add("GroupId", GroupId);
            logParams.Add("AccountId", AccID);

            dbx.executeNonQuery(logQuery, logParams);

            return result;
        }

