        public Object[] GetMultiGeofencebylogin(String LoginUser, String tableName)
        {
            StringBuilder query = new StringBuilder();
            if (tableName == "geofencenew")
            {
                var lParameter = new Dictionary<string, object>();
                int AccID = GetAccountId(getSessionIdFromLogin(LoginUser));
                query.Append("SELECT MIN(GroupId) FROM accountgroups WHERE AccountID=?");
                lParameter.Add("AccountId", AccID);
                string MinGroupID = dbx.executeScalar(query.ToString(), lParameter).ToString();
                string UserGroupID = getGroupIdByLogin(LoginUser).ToString();
                query.Clear();
                query.Append("select id,geofencename,minlatitude,minlongitude,maxlatitude,maxlongitude,lastviolation,LoginUser,smsphone,smsmessage,email_id,inorout,noofpoints,AllOrSingleVehicle,Road,Place,City,District,State,Latitude,Longitude,Accountid,geofencetype,lat1, lng1, lat2, lng2, lat3, lng3, lat4, lng4, lat5, lng5, lat6, lng6, lat7, lng7, lat8, lng8, lat9, lng9,lat10 ,lng10 ,lat11 ,lng11 ,lat12 ,lng12 ,lat13 ,lng13 ,AlertNotification from geofencenew ");
                if (MinGroupID == UserGroupID)
                {
                    query.Append("where Accountid = " + AccID);
                }
                else
                {
                    query.Append("where LoginUser = '" + LoginUser + "'");
                }
            }
            else if (tableName == "plantgeolocations")
            {
                query.Append("select accountid from vehicles where vehicleid = '" + LoginUser + "'");
                Object accIdObj = dbx.executeScalar(query.ToString());
                if (accIdObj == null)
                    return null;
                int accId = Convert.ToInt32(accIdObj);
                query.Clear();
                query.Append("select accountid,locstr,emailid,minlatitude,minlongitude,maxlatitude,maxlongitude from plantgeolocations where accountid = " + accId + " and minlatitude <>0.0");
                //query.Append("where truckId = '" + vehicleId);
                //query.Append("'");
            }
            DataSet geofencenew = dbx.executeQuery(query.ToString());
            DataTable table = geofencenew.Tables[0];
            ArrayList geofencelist = new ArrayList();
            foreach (DataRow row in table.Rows)
            {
                geofencelist.Add(row.ItemArray);
            }
            return geofencelist.ToArray();
        }

    }

